INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Yaşlıyım O Kadar Yaşlıyım ki **', 'yasliyim-o-kadar-yasliyim-ki-sakine-aydin-8yi12', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşlıyım o kadar yaşlıyım ki….

Sevdayım, umudum, hayalim..

Acıyım, hasretim, kederim..

Ecelim, hayatım, nurum..

Sevdalarım umutları doğurdu, 

Umutlar da hayalleri yoğurdu..

Şiir oldu, türkü oldu, masal oldu…

Acılarım dilden dile dolaştı..

Derdim dağlar deldirdi,

Hasret çöller gezdirdi..

Ecel geldi sonlar hayata kavuştu..

Nur oldu yürekten yüreğe ulaştı..

Ateşim, suyum, taşım..

Canım, cananım, başım..

Savaşım, barışım, silahım.. 

İbrahim in ateşine sular taşıdım..

Yusuf un kuyusunun taşıyım..

Karun un en can arkadaşıyım..

Musa yım Firavun la savaştım..

Yollarda kızıl denizi açtım..

Dua ile çıkıp arş a ulaştım..

Gülüm, bülbülüm, toprağım..

Batağım, nehirim, dalda yaprağım..

Zehirim, balım, katığım..

Zindanım, işkenceyim, davayım..

Günahım, tövbeyim, sevabım..

Cennetim, cehennemim, azabım..

Göz yaşıyım, baş tacıyım, Züleyhayım..

Tebessümüm, ilacım, devayım..

Kurtum, kuzuyum, dostum, düşmanım..

Denizim, deryayım, ummanım..

Hasretim, özlemim, sılayım..

Derdim, dermanım, yarayım..

Zebur da, Tevrat da, İncil de, Kur ‘an dayım..

Gerçeğim, yalanım, meleğim, şeytanım..

Adem im..

Havva yım.. 

Habil..

Kabil im..

Yaşlıyım o kadar yaşlıyım ki….

16.01.06', 'Yaşlıyım o kadar yaşlıyım ki…. Sevdayım, umudum, hayalim.. Acıyım, hasretim, kederim.. Ecelim, hayatım, nurum.. Sevdalarım umutları doğurdu,...', ARRAY['Türk Edebiyatı','Şiir','Sakine Aydın']::text[], 8.5, '{"poet":"Sakine Aydın","poet_slug":"sakine-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yasliyim-o-kadar-yasliyim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun Menekşe', 'suskun-menekse-mehmet-sahin-z6o91', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Menekşenin suya düşmüş hali

Ele uzak, söze sığmayan

Savurur rüzgar seni susuzluğuma

Uzun geceler geçti uzak şehrin birinde

Terk eder gibi bir ayrılık başladı uzak şehir bitince

Artık yan yana değildi hiçbir sokak

Paslanmış takvim yapraklarında kaldı geçmiş zaman

Lekesiz bir kalp çocuğusun sen

Adın adıma benzer, sözün sesime

Yan yana değil artık bu rüya iç içe.', 'Menekşenin suya düşmüş hali Ele uzak, söze sığmayan Savurur rüzgar seni susuzluğuma Uzun geceler geçti uzak şehrin birinde Terk eder gibi bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şahin']::text[], 8.5, '{"poet":"Mehmet Şahin","poet_slug":"mehmet-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/suskun-menekse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş', 'serzenis-huseyin-ozcan-5sux2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir han idi aşk yolunda şu gönlüm,			

kimi geldi durdu biraz eylendi,			

kimi yorgun idi, kaldı biraz dinlendi,			

kimi yaralıydı, geldi derman istedi,			

kimi geldi viran etti, talan etti, mahvetti…..', 'bir han idi aşk yolunda şu gönlüm,			 kimi geldi durdu biraz eylendi,			 kimi yorgun idi, kaldı biraz dinlendi,			 kimi yaralıydı, geldi der...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Özcan']::text[], 8.5, '{"poet":"Hüseyin Özcan","poet_slug":"huseyin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/serzenis-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarım', 'aglarim-i-brahim-yavuz-bildik-uw83z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne üç, ne beşe ağlarım,

Döndüm,güneşe ağlarım.

Yaşım,derelere sığmaz.

Ağlarsam; döşe ağlarım...

Kendi nefsime kıyarak,

Sözüm söylerim duyarak.

Terkeder,gider diyerek...

Düştüm telâşa ağlarım.

Görünmez içimdekiler,

Yaşımı,yağmurlar siler.

Eller,parayınan güler...

Bense,beleşe ağlarım.

Yavuz''um,çağladım aktım,

Gönlümdeki bendi yıktım.

Gürledim,göklere çıktım...

Korkarım,boşa ağlarım.

i.Yavuz Bildik       2002 Ankara', 'Ne üç, ne beşe ağlarım, Döndüm,güneşe ağlarım. Yaşım,derelere sığmaz. Ağlarsam; döşe ağlarım... Kendi nefsime kıyarak, Sözüm söylerim duyara...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz Bildik']::text[], 8.5, '{"poet":"İbrahim Yavuz Bildik","poet_slug":"i-brahim-yavuz-bildik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aglarim-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Kalmayalım Geri', 'biz-kalmayalim-geri-seyfet-bozcali-okbii', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tarihteki mirasa biraz sahip çıkalım,

Geleceye düşünüp,rehaveti atalım,

Devlet,millet malına yeni şeyler katalım,

Alem aya çıkarken biz kalmayalım geri...

Cinsiyet ayırmadan,eğitelim herkesi,

Teknoloji yolunda,terlemeli ensesi,

Vatan,millet aşkıyla coşturmalı herkesi,

İller icat yaparken biz kalmayalım geri...

Çoğalsın Fabrikalar,işsizimiz iş bulsun,

İşçi iyi kazansın eve gururla dönsün,

Yetim,öksüz korunsun,yuvada şenlık olsun,

Hayırda,hasanette biz kalmayalım geri...

Öğretmen Seyfet der ki Alem duysun adını,

Halkın mutlu yaşasın,sende al muradını,

Uzaya,Aya yazdır Türk''ün şanlı adını,

El alem yükselirken,biz kalmayalım geri...

16.01.2006', 'Tarihteki mirasa biraz sahip çıkalım, Geleceye düşünüp,rehaveti atalım, Devlet,millet malına yeni şeyler katalım, Alem aya çıkarken biz kalm...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biz-kalmayalim-geri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapkaççı Ne Kaptın Sen? ‘Hasret Coşkun’ Anısına', 'kapkacci-ne-kaptin-sen-hasret-coskun-anisina-caglar-asik-hwuue', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanıdım onu, dün akşam bir haberle.

Ağladım ona, dün akşam bin kederle.

Yandı yüreğim, kanadı bu haberle.

Olmasın vahşi, insanlar bizlerle.

&

Niçin bir insan, böyle vahşet yapar? 

Kime bu öfke, buna herkes şaşar? 

Aciz haklıdır, mahşerde Hak sorar.

Tek güçlü Hak’tır, acizi sarmalar.

&

Sanma ey kaçan, kurtulabildin sen! 

Üç kuruş için, kaç cana kıydın sen? 

Hak var her yerde, her anı hep gören.

İster temizlen, istersen hep kirlen.

&

İstanbul – 17.01.2006

Çağlar Aşık – Kapkaççı Ne Kaptın Sen? ‘Hasret Coşkun’ Anısına

Haber: Kapkaççılar dehşet saçtı! 

Adres: http://www.gap.web.tr/haber_detay.asp? id=3817 

Hatay''ın İskenderun İlçesi''nde motosikletli 2 kapkaççı, çantalarını çalmak istedikleri teyze ile yeğeni yerde sürükleyerek hastanelik etti. Yaklaşık 20 metre sürüklenen 30 yaşındaki Hasret Coşkun, başını kaldırıma çarparak yaralanırken teyzesi olayı hafif sıyrıklarla atlattı.

Dün akşam TV’deki bir haber Hasret Coşkun’un vefat ettiğini bildirdi. 

Kendisine Allah’tan rahmet kederli ailesi ve yakınlarına başsağlığı diliyorum.', 'Tanıdım onu, dün akşam bir haberle. Ağladım ona, dün akşam bin kederle. Yandı yüreğim, kanadı bu haberle. Olmasın vahşi, insanlar bizlerle. ...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kapkacci-ne-kaptin-sen-hasret-coskun-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kederli Adamım Ben', 'kederli-adamim-ben-hasan-can-k41r8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kederli adamım ben,

Aklıma düşerse sevgili,

Utanmam ağlarım açıkça.

Hele geceyse ki,

Odur en kederli anım

Şarkılar dilimdeyken

Düşer gözyaşlarım.

Kederli adamım ben,

Kime ne kederimden,

Gözyaşımdan kime ne.

Dokunmayın bana,

Düşünce sevgili aklıma,

Ağlıyorum işte.', 'Kederli adamım ben, Aklıma düşerse sevgili, Utanmam ağlarım açıkça. Hele geceyse ki, Odur en kederli anım Şarkılar dilimdeyken Düşer gözyaşl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kederli-adamim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-46 (M.S.) 15/01/2006', 'mektuplar-46-m-s-15-01-2006-mahzun-doga-s24a5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Resmimiz buz çölü.

Çizildikçe eriyoruz.

Donuyoruz yandıkça.

Ve büyüyor aramızdaki karalar.

Cehennem ortasında buz çölüyüz.

Göstermiyor aslımızı hiçbir mevsim.

Gök mavi buz.

Karmakarışık yağmur doluyuz.

Nereye aksak önümüzde kara sular.

Ne zaman kurur sular.

Suçlarımız ne zaman donar.

Ne zaman erişiriz.

Dünya ne zaman barışır.', 'Resmimiz buz çölü. Çizildikçe eriyoruz. Donuyoruz yandıkça. Ve büyüyor aramızdaki karalar. Cehennem ortasında buz çölüyüz. Göstermiyor aslım...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mektuplar-46-m-s-15-01-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-47 (M.S.) 16/01/2006', 'mektuplar-47-m-s-16-01-2006-mahzun-doga-ud2ia', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkmosferimizde göç bulutların.

Kendimize gelemedik daha.

Gözlerim aynı yerde hâlâ.

Bakışlarında aynı yer.

Hiçkimse geçmedi daha bastığın yerden.

Durduğum yerden ayrılmadım.

Ve gitmekten durmuyorsun daha.

Kendimize dönemedik daha.

Kaldığımız gibiyiz.

Üstümüzde aynı elbuğseler.

Tenimde parmak izlerin.

Adımlarımız aynı basamaklarda.

Kendimize inemiyoruz.

Dönemiyorsun.

Hiçbir ''neden? ''imize cevap veremiyor hiçkimse.

Nedeni nedensiz bir neden yüklüyüz.

Kayıkta yaşayan balık da olsak.

İki büklüm olmuş kayıktalığımız bile.

Islansak bir nokta, okyanuslar dolusu soru doluyoruz.

Gelişinle yaşamaya yalnız başlamadım.

Şimdi bir tek ben varım gittiğinde ölen.', 'Aşkmosferimizde göç bulutların. Kendimize gelemedik daha. Gözlerim aynı yerde hâlâ. Bakışlarında aynı yer. Hiçkimse geçmedi daha bastığın ye...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mektuplar-47-m-s-16-01-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüce Yaratanım Var', 'yuce-yaratanim-var-seyfet-bozcali-j6tvi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zalimin zulmü varsa,mazlumun Allah''ı var,

Hainin malı çoksa,Müminin sevabı var,

Zorbada kuvvet varsa,yoksulun duası var,

Her şeye kadir olan,Ulu Yaratanım var...

Zenginin parası varsa,züyürdün çenesi var,

Şerefsiz yaşantıda,bolca yüz karası var,

Gayri meşru yollardan, çok yüklü kazancı var,

Mahkemeyi kübrada Yüce yaratanım var...

Dünya''yı dost görenin dünyalık dostları var,

Hakkı seven insanın,kocaman imanı var,

Seyfet der ki yaşamanın zararı var karı var,

Mahşerde hesap gören Ulu Yaratanım var...

                17.01.2006', 'Zalimin zulmü varsa,mazlumun Allah''ı var, Hainin malı çoksa,Müminin sevabı var, Zorbada kuvvet varsa,yoksulun duası var, Her şeye kadir olan...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yuce-yaratanim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğini avuçlarken', 'sensizligini-avuclarken-esref-uzulmez-4qcop', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimde ki tüm gayr-ı resmi duygularımı ayıklarken

Sen hep isyanıma düşerdin

İllegallik hoşuna giderdi

Sıkışmış alt benlerime inat

Seni düşünürken

Saçların sabahın ellerine değerdi

Işık kusardı sanki bu şehir

Yakamoz her gece uzayıp giden yokluğundu

Karanlığıma düşen gölgeler üşürdü

Sen gece olunca

Sensizliğimi avuçlardım

Yıllar devrilirdi üstüme 

Günler yağmur olurdu

Ellerim boşalırdı caddelere

Yağan her günde 

Seni arardım

Ve hep mağlup uyanırdım sensizliğimden 

Oysa bir karanfil bozdu

Yakamozun gizemini…', 'İçimde ki tüm gayr-ı resmi duygularımı ayıklarken Sen hep isyanıma düşerdin İllegallik hoşuna giderdi Sıkışmış alt benlerime inat Seni düşün...', ARRAY['Türk Edebiyatı','Şiir','Eşref Üzülmez']::text[], 8.5, '{"poet":"Eşref Üzülmez","poet_slug":"esref-uzulmez","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sensizligini-avuclarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum, Sevmiyorum', 'seviyorum-sevmiyorum-mustafa-aslan-2-yohyu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hergün ayni laflar,

Uymazmi birbirine bu kafalar,

Yarim dedim bagrima bastim,

Namusunu namusum bildim,

Seni güldürmek için kendimi yedim,

Her seferinde ayni soru,

Beni seviyormusun? 

Birgün evet,

Diger günler hayir,

Biktim bilmem sözlerinden,

Artik yoksun,

Bazen seviyorsun,

Bazen sevmiyorsun,

Artik yoksun,

Ister sev,

Ister sevme,

Umrumda degilki yasamak.

Artik hersey bitti nede olsa.

Tarih Ve Saati: 17-01-2006	17:19', 'Hergün ayni laflar, Uymazmi birbirine bu kafalar, Yarim dedim bagrima bastim, Namusunu namusum bildim, Seni güldürmek için kendimi yedim, He...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seviyorum-sevmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Şairlik Olmaz', 'boyle-sairlik-olmaz-seyfet-bozcali-m963q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şairlik duygudur,şiir kafiye,

Üç beş sözcük yazan girmiş siteye,

Yerli,yersiz birkaç mısra var diye,

Övünme hiç böyle şairlik olmaz...

Şair odur şiirleri yol olsun,

Okuyana huzur versin,dil olsun,

Çıkmazına ışık olsun el olsun,

İşkal etmek için şairlik olmaz...

Seyfet der şiirde emek olmalı,

Okuyanın gönlünde taht kurmalı,

Olaylarla bağlantılar kurmalı,

Emeksiz yürekten şairlik olmaz...

17.01.2006', 'Şairlik duygudur,şiir kafiye, Üç beş sözcük yazan girmiş siteye, Yerli,yersiz birkaç mısra var diye, Övünme hiç böyle şairlik olmaz... Şair ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/boyle-sairlik-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitti Mi?', 'bitti-mi-mustafa-aslan-2-ylkom', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sözden söze geçtin,

Beni dertlerle erittin,

Yedirdin,

Beni kendi kendime,

Bitirdin,

Öldürdün hayellerimi.

Söyle söyleyecegini,

Bitti mi? 

Bitmedi mi? 

Kafaya bile takmam artik,

Varliginla,

Yoklugun ayni geliyor bana,

Ikiside aci dolu.

Söyle ha,

Simdi bu sevda,

Bitti mi? 

Tarih Ve Saati: 17-01-2006	17:25', 'Sözden söze geçtin, Beni dertlerle erittin, Yedirdin, Beni kendi kendime, Bitirdin, Öldürdün hayellerimi. Söyle söyleyecegini, Bitti mi?  Bi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bitti-mi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onu Hatirlatmayin', 'onu-hatirlatmayin-mustafa-aslan-2-85wya', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yasadigim hersey,

Ama hersey mazide kaldi.

Tamam hala agliyorum,

Belki seni kaybettigin için,

Belki beni taniyamadigin için,

Belkide zamanimi bosa harcadigim için.

Biliyordum bitecekti,

Bu sevdada bitecekti,

Herseyin bittigi gibi.

Bitmez demeyin bana,

Ömür bitiyorda,

Sevdalar niye bitmesin.

Sizden tek bir istegim var,

Bana onu hatirlatmayin.

Tarih Ve Saati: 17-01-2006	17:30', 'Yasadigim hersey, Ama hersey mazide kaldi. Tamam hala agliyorum, Belki seni kaybettigin için, Belki beni taniyamadigin için, Belkide zamanim...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/onu-hatirlatmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artik Sen Yoksun', 'artik-sen-yoksun-mustafa-aslan-2-fr73u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sevdam vardi,

Simdi yokoluyor.

Zaman geçtikçe herseyden bikiyor,

Herseyden,

Herkezden usaniyorum,

Soguyorum.

Bir sen vardim,

Yasam sevincim sen,

Umutlarim,

Ümitlerim ve Hayellerim,

Hepsi sendin.

Seni simdi biraktim,

Sen degil,

Ben ayrildim,

Ve simdi hayatimda sen yoksun,

Hayalin olsada,

Artik sen yoksun.

Tarih Ve Saati: 17-01-2006	18:16', 'Bir sevdam vardi, Simdi yokoluyor. Zaman geçtikçe herseyden bikiyor, Herseyden, Herkezden usaniyorum, Soguyorum. Bir sen vardim, Yasam sevin...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/artik-sen-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Batırdım Gülüm', 'batirdim-gulum-i-brahim-yavuz-bildik-0wn3r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdâ pazarında alıp satmadan,

Elde sermayemi yitirdim gülüm.

Limitsiz kredi açılmış iken,

Hesabım bilmedim,batırdım gülüm.

Yaşamın tadını tadamıyorum,

Üç keçi verdiler güdemiyorum.

Kadehleri sarhoş edemiyorum.

Gene bir büyüğü bitirdim gülüm.

Dalga oldum,bir kıyıya çarpmadım,

Aç dolaştım amma çalıp çırpmadım,

Gece geçti kirpiğimi kırpmadım,

Denizi uykuya yatırdım gülüm.

İ.Yavuz Bildik	2002 tisan', 'Sevdâ pazarında alıp satmadan, Elde sermayemi yitirdim gülüm. Limitsiz kredi açılmış iken, Hesabım bilmedim,batırdım gülüm. Yaşamın tadını t...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz Bildik']::text[], 8.5, '{"poet":"İbrahim Yavuz Bildik","poet_slug":"i-brahim-yavuz-bildik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/batirdim-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Oğluma', 'canim-ogluma-mevlut-bicik-tf5dp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günlerden Bayram ocak ayının onbiri

“o kızı seviyorum”sözü geldi bana iri

O anda mezara koydun beni  diri  diri

Ben üzüldüm, sen üzülme emi oğlum.

Halinin perişanlığı beni kahr’etti

Akan gözyaşlarım etrafımı  bahr’etti

Sana düşkünlüğüm dünyan değil ahiretti

Ben ağladım, sen ağlama emi oğlum.

Bir arkadaş gibi sana nasihatler verdim

Sen ise aksilik yaparak beni hep gerdin

Beni hüngür,hüngür ağlatıp muradamı erdin

Nasihatlerimi hep yanlış anladın demi oğlum.

Bir baba evladının yanışına nasıl dayanır

Bir evlad gayr-ı ahlâkî boya ile nasıl boyanır

Huyunu,tüyünü bilmediğin kız sana sulanır

Bir anlık hevesle, olma bunların yemi oğlum.

Yavrum sen benim canımsın kanımsın 

Gözümsün, kulağımsın her yanımsın

Arkamda bırakacağım en güzel anımsın

Bu âileye lâyık, bir evlad ol emi oğlum.

Mevlüt Bicik

17.01.06  saat 16.26

Esslingen', 'Günlerden Bayram ocak ayının onbiri “o kızı seviyorum”sözü geldi bana iri O anda mezara koydun beni  diri  diri Ben üzüldüm, sen üzülme emi ...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Bicik']::text[], 8.5, '{"poet":"Mevlüt Bicik","poet_slug":"mevlut-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/canim-ogluma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-i-brahim-yavuz-bildik-dxrpz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çelişkili bahçıvanız

diken de biz

söken de

gerekli mi

gereksiz mi demeden

silâhını çeken de

sahi...

biz ne''yiz ki

kendimize 

uzak da biz 

yakın da..

İ.Yavuz Bildik                    1995 adana', 'çelişkili bahçıvanız diken de biz söken de gerekli mi gereksiz mi demeden silâhını çeken de sahi... biz ne''yiz ki kendimize  uzak da biz  ya...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz Bildik']::text[], 8.5, '{"poet":"İbrahim Yavuz Bildik","poet_slug":"i-brahim-yavuz-bildik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biz-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dertli Yasemen', 'dertli-yasemen-munevver-senol-apgq1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana temizliğe gelir yasemen.

                                Amaa dertlimi dertli, kocasından.

                                Tembel adam ben çalışayım o yesin.

                                Birde kıymetimi bilse ya, ne gezer.

                                Bir yandan halıları siliyor, bir yandan da söyleniyor.

                                Evlen, evlen dediler başımın etini yediler.

                               Sanki evde kalmışım gibi.

                                Evlendim de ne oldu? 

                               Ev ocak bebe doldu.

                               Keşke doğurmaz komaz olaydım.

                              Evlenmeseydim de kız kurusu kalsaydım.

                              Anama, babama bakardım da.

                              Hiçmi değil hayır duasını alırdım.

                              Şimdi hayırsız herifin, künde koruna küfür etmez.

                              Hiç yok yere günaha da girmezdim.

EVET şanssız olan kadın hangi konumda olursa olsun farketmiyor,

Yasemen beni de yaz kız abla demişti bende söz verdim ve işte tüm dostlarımla onun derdini paylaşıyorum, kolay gelsin Yasemen Allah sana kuvvet versin. Münevver Şenol  17.1.2006', 'Bana temizliğe gelir yasemen.                                 Amaa dertlimi dertli, kocasından.                                 Tembel adam ...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dertli-yasemen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ödeme', 'odeme-i-brahim-yavuz-bildik-4s4zt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sonbaharın hüzünlü çığlıkları boğuşur

yalnızlıkla

kül rengi bulutlardan arta kalan duygular

yeşerir  bakışlarında.

sildim alacakları

sevdân boyun borcum

çek senet de bilmem

bırak peşin ödeyeyim

	İ.Yavuz Bildik	2001 Ankara', 'sonbaharın hüzünlü çığlıkları boğuşur yalnızlıkla kül rengi bulutlardan arta kalan duygular yeşerir  bakışlarında. sildim alacakları sevdân ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz Bildik']::text[], 8.5, '{"poet":"İbrahim Yavuz Bildik","poet_slug":"i-brahim-yavuz-bildik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/odeme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarla', 'tarla-i-brahim-yavuz-bildik-augxs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her bülbülün âhı var,daldaki dikenlerden,

Haklı iken susarak,gözyaşı dökenlerden,

Allah bizi korusun,rüzgâra göre esip,

Her bulutun altına tarlayı çekenlerden.                              

                       

 İ.Yavuz Bildik

                                                  5.Nisan 1997', 'Her bülbülün âhı var,daldaki dikenlerden, Haklı iken susarak,gözyaşı dökenlerden, Allah bizi korusun,rüzgâra göre esip, Her bulutun altına t...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz Bildik']::text[], 8.5, '{"poet":"İbrahim Yavuz Bildik","poet_slug":"i-brahim-yavuz-bildik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tarla-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Avuçlarımdan', 'yorgun-avuclarimdan-i-brahim-yavuz-bildik-rhmja', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Müebbet hüküm giydim,ben gönül suçlarımdan 

Nice güneşler battı, benim de burçlarımdan. 

Kaç yılım kaldı bilmem,yarım asırdan sonra, 

Bir yıl daha uçuyor yorgun avuçlarımdan. 

İ.Yavuz Bildik

  			26.12.2005', 'Müebbet hüküm giydim,ben gönül suçlarımdan  Nice güneşler battı, benim de burçlarımdan.  Kaç yılım kaldı bilmem,yarım asırdan sonra,  Bir yı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz Bildik']::text[], 8.5, '{"poet":"İbrahim Yavuz Bildik","poet_slug":"i-brahim-yavuz-bildik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yorgun-avuclarimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytanlara Daha Taşım Bitmedi', 'seytanlara-daha-tasim-bitmedi-umut-gungor-1r74h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şeytanlara daha başım bitmedi,

Yıllar boyu ona öfkem gitmedi,

O kadar taş attım yine yetmedi,

Atacağım taşım cepte çok daha.', 'Şeytanlara daha başım bitmedi, Yıllar boyu ona öfkem gitmedi, O kadar taş attım yine yetmedi, Atacağım taşım cepte çok daha....', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seytanlara-daha-tasim-bitmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylece...', 'oylece-yasemin-sezer-tulgar-iiv38', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaz gülüm

İç sesinle yaz

Ayaza esas duran nefesin nemiyle

Dudak aralarından sızamayanlarla 

Bir içimlik olsun önce

Sonra dökül ve öldür 

Öylece...

Basiret dediğin nedir

Bilir misin yarında 

Nice gömüler gizlidir

Tuttuğum sözün tiryakisi olmuşum

Çektiğim tenine hasret imidir

Önce bildir

Sonra öldür

Öylece...

Sirenler çalsın

Yırtsın kıtaları

Okyanuslar

Yeterince derin midir

Yolları geçtim

Bana varışlarını getir

Önce öp

Sonra öp

Öldüresiye...

17.01.06', 'Yaz gülüm İç sesinle yaz Ayaza esas duran nefesin nemiyle Dudak aralarından sızamayanlarla  Bir içimlik olsun önce Sonra dökül ve öldür  Öyl...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/oylece-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayranım', 'hayranim-huseyin-kir-c1f13', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yolların ayrımındayım,

Sessizliğin otağındayım,

Ve hakikat haykıran

Bir dere kenarındayım

Pırıl pırıl akan suya hayranım,

Sessiz sessiz esen yele hayranım,

İnce ince açan güle hayranım,

Doğan kuşa hayranım ben

                                      tabiatın bağrında

Gökte uçan bir baykuşa hayranım,

Hayranım ben ormandaki aslana,

Hayranım ben çölde gezen tilkiye,

Özgürlüğü tadanlara hayranım

Tarlasında bir çiftçiye,

İşyerinde bir işçiye,

Mutfağında bir aşçıya,

Alın teri silenlere hayranım.', 'Yolların ayrımındayım, Sessizliğin otağındayım, Ve hakikat haykıran Bir dere kenarındayım Pırıl pırıl akan suya hayranım, Sessiz sessiz esen...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kır']::text[], 8.5, '{"poet":"Hüseyin Kır","poet_slug":"huseyin-kir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayranim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Şehri Ramazan', 'ya-sehri-ramazan-seyfet-bozcali-y60jr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin gelişinle şenlendi yuvalarımız,

Kuruldu çadırlar,kaynadı kazanlar,

Pişirildi yemekler.

Belkide etli yemekleri sende tattı,

Garip,guraba....

Sende açtı kesenin ağzını,

on bir aydır sevaptan mahrumlar...

Müjdeledin; başı rahmet ortası,bereket,

Sonunun kurtuluş olduğunu...

Sende rağbet gördü,doldu camiler,mescitler,medreseler.

Şenlendi sokaklar yandı mahyalar.

İşıklandı minareler,

Okundu Kur''anlar,Bağışlandı hatimler.

Getirildi selavatlar,tekbirler,bağlandı şeytanlar.

Teskin oldu nefisler.

Hız kesti azgınlıklar,azaldı günahlar...

Akmaya başlandı yardımlar toplandı sevaplar.

Verildi zekatlar,fitreler,sadakalar.

Kalbimiz seninle doldu,

Resulüllah sevgisiyle coştu.

Bin aydan hayırlı Kadir gecesi sende saklıydı.

Sen gidersen yine üzüleceğiz,

Çünki melun şeytanlar zincirlerinden kurtulup,

tekrar nefislere musallat olacaklar,

Tekrar günahlar çoğalacak.

Çabuk gel ya Şehri Ramazan,

Fazla günah işlemeden,

Hak yolundan sapmadan,

Dünya malına tapmadan,

Boynumuzu büküp senin gelmeni bekleğeceğiz..

02.11.2005', 'Senin gelişinle şenlendi yuvalarımız, Kuruldu çadırlar,kaynadı kazanlar, Pişirildi yemekler. Belkide etli yemekleri sende tattı, Garip,gurab...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ya-sehri-ramazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul da olmak! ! ! !', 'i-stanbul-da-olmak-nazan-i-zmirli-es4we', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'istanbul da 

olmak

geçti

içimden

yedi tepeler

sultanlar şehrinden

ne yere batan sarayı

ne  dolmabahçe

seninle olmak

vardı 

kuzguncukta,

boğazda

ya da; olanı biteni

izlemeliydik

köprülerin altında

akşamdan 

kalmışlığımızı

vermeliydik

poyrazlara

sessizliğimizi

katmalıydık

martıların

çığlıklarına

güvercinleri

yemlemeliydik

sevdamızı bağlamalıydık

kanatlarına

bir falcının avcunda

okunmalıydı 

geleceğimiz

geçmişimiz

bugünümüz

iç çekmeliydim 

ela gözlerinle

buluştuğumda

dudakların titremeliydi

göğsündeki yalnızlığıma

gözlerimiz dalmalıydı 

dalgalar kırıldıkça

koca  gövdeli

takaların altında

ve hemen 

irkilmeliydik

bağıran vapurların

sayılı anları hatırlatışıyla

istanbulun 

unutulmaz aşklarına 

anıt olan kız kulesine

bakıp........bakıp.......

gün geceye teslim

olmaya başladığında

bizde bir kule mi

kurmalıydık  aşkımıza

neden mi! 

cevabı; sende saklı

keşki anıtsız olsak

bugünü

yaşayabilsek doyasıya

belki kız kulesi bile

birgün  kaybolacak

moraran  dalgalarda....

yinede; 

İstanbul da olmak geçti içimden......

acı  tatlı   ne varsa.................

01.01.2006-antalya''dan sevgiler', 'istanbul da  olmak geçti içimden yedi tepeler sultanlar şehrinden ne yere batan sarayı ne  dolmabahçe seninle olmak vardı  kuzguncukta, boğa...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/istanbul-da-olmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör talih...', 'kor-talih-ercan-akbay-3t5ze', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çift gözü çok özlemiştim,oysa

    Ya ben körmüşüm,

    Ya onlar beni görmedi....

                                            17.1.2006 B.EVLER.', 'Bir çift gözü çok özlemiştim,oysa     Ya ben körmüşüm,     Ya onlar beni görmedi....                                             17.1.2006 B...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kor-talih-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimi verdim kolumu alamıyorum', 'elimi-verdim-kolumu-alamiyorum-abdullah-oral-oi1io', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nereden geldiyse geldiler bana

Finans bank kimdir tanımıyorum

Cart Finansa beni üye ettiler

El verdim kolumu alamıyorum

Kartsızımya veba dedi teşhisin

Acı çektirmek mi bana bahşişin

Kartını almadım diye keşişin

Onlar güler ya ben gülemiyorum

Beni garip gördü kesildi aslan

Üstüme geliyor aldıkça alttan

Amele sümüğü gibi yapışkan

Bir türlü yakamdan silemiyorum

Vurğuni olmadan kaptalist cani

Evveli aşk için yakardın teni

Koydular ki öyle bir hale beni

Gayrı gönül sazı çalamıyorum', 'Nereden geldiyse geldiler bana Finans bank kimdir tanımıyorum Cart Finansa beni üye ettiler El verdim kolumu alamıyorum Kartsızımya veba ded...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/elimi-verdim-kolumu-alamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Mevsim Hep Sonbahar', 'bende-mevsim-hep-sonbahar-celal-topo-35iiu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutmuşum yalnızlığımın ellerinden

Yaşıyorum kapalı kapılar arkasında

Acılar enkazının altında yüreğim

Dönüşsüz bir gidişin arkasından

Çaresizce boşluğa düşmüş ellerim...

Hala düşüncelerimi kemirir o anılar

Islanmış bir mendil gibi avuçlarımda

Gözyaşlarımı kurutmaya yetmiyor yıllar...

Her gece yorgun,güçsüz şu bedenimi

Karanlığın insafsız koynuna bırakıyorum

Bakışlarım bir kayıp gibi aranıyor

İlanlar asılarak kimsesizler duvarlarına

Ben kaderine terkedilmiş bir yalnız adam

Çıkmaz sokakların dar kaldırımlarında

Yorgun düşüncelerimi dokurken tezgahımda

Hayallerimse

Düşmeyi bekleyen solgun birer yaprak

Çok uzak bana başka mevsimler çok uzak

Sizin bir türlü göremediğiniz

Hiç gitmeyen bir sonbahar var içimde...



16 / 01 / 2006 Antalya', 'Tutmuşum yalnızlığımın ellerinden Yaşıyorum kapalı kapılar arkasında Acılar enkazının altında yüreğim Dönüşsüz bir gidişin arkasından Çaresi...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bende-mevsim-hep-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yükseklerin Süsü', 'yukseklerin-susu-altay-taskin-fqhc7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'rüyalarımızın renkli süsü

gönüllerde taht kuran

bayrağım

senin ayında

gecelerin sessizliği 

ışıldar

yıldızında patlayan

mermilerin

çakışları var

Hanife bacımın feryadı

Emine anamın ağıtı

kundaktaki Ali''min ıngası

göklerde yankılanan

gözlerimizi alır rengin

sürükler düşünceye

al rengin

toprağımda şehit olan

Mehmed''imin kanıdır

iyi tanı unutma

o yükseklerde dalgalanan

senin adındır', 'rüyalarımızın renkli süsü gönüllerde taht kuran bayrağım senin ayında gecelerin sessizliği  ışıldar yıldızında patlayan mermilerin çakışları...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yukseklerin-susu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterdim..', 'i-sterdim-selma-sengoren-829uy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çağla gözlerinden süzülen

İnci tanelerini

Dudaklarındaki acı tebessümü 

Yüzündeki sararmış yaprakların izlerini

Mevsimlerin en güzelinde,

Silmek isterdim.

Kar beyazı saçlarını

Sözcüklerindeki ‘keşke’ leri

Yaptığın hataları

Ömründe yaşadığın pişmanlıkları

Dualarımla,

Silmek isterdim.

Dağ misali güçlülüğü

Yaşama sevincinin,

Henüz açmayan tomurcuklarıyla

Gönül bahçesindeki 

Tüm gizli çiçekleri

Sana hediye etmek isterdim.', 'Çağla gözlerinden süzülen İnci tanelerini Dudaklarındaki acı tebessümü  Yüzündeki sararmış yaprakların izlerini Mevsimlerin en güzelinde, Si...', ARRAY['Türk Edebiyatı','Şiir','Selma Şengören']::text[], 8.5, '{"poet":"Selma Şengören","poet_slug":"selma-sengoren","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/isterdim-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Tüneli', 'zaman-tuneli-altay-taskin-0572v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dönüşü olmayan tünel

tutmuş elimizden

pamuk şekerlerle

kandırmış bizi

dikenli güller

ısırgan otları

değmemiş tenimize

yumuşak yataklar

leylak kokuları

bembeyaz kar

ebemkuşağı

yolumuza serilmiş

ikinci kez

dönememişiz geçmişe

film şeridi kayan

altımızdan

doğumdan ölüme doğru

yavaş ya da hızlı

zaman

bize yanıp sönen

koca ışıktı...', 'dönüşü olmayan tünel tutmuş elimizden pamuk şekerlerle kandırmış bizi dikenli güller ısırgan otları değmemiş tenimize yumuşak yataklar leyla...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zaman-tuneli-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istırap Meleğim', 'istirap-melegim-huseyin-ozan-ozturk-c3pw6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin bakışların kadar hızlı,

Ne bir yıldırım çakar,

Senin gözlerin kadar engin,

Ne bir deniz,ne okyanus var...

Benim senden çektiğim kadar,

İşkence...

Ne bir esir çekmiş efendisinden,

Benim,senden gördüğüm azabı,

Hiç bir ası kul görmemiş Tanrısından! 

Benim,senin için gözyaşı döktüğüm kadar,

Her gece...

Hiç bir abit dökmemiş Tanrısı için,

Benim sana yalvardığım kadar,

Hiç bir günahkar yalvarmamış,

Affı için.....

İnsan birkez ölür ömründe,

Bense binkez ölüyorum günde.

Gamzeli bakışından,sıçrayan kıvılcımla,

Kalbim parçalanıyor,deliniyor yüreğim,

Ama o gururun öylesine kapsamış ki seni,

Ne beni görüyorsun,ne de olan biteni..', 'Senin bakışların kadar hızlı, Ne bir yıldırım çakar, Senin gözlerin kadar engin, Ne bir deniz,ne okyanus var... Benim senden çektiğim kadar,...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ozan Öztürk']::text[], 8.5, '{"poet":"Hüseyin Ozan Öztürk","poet_slug":"huseyin-ozan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/istirap-melegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyümeye Özlem', 'buyumeye-ozlem-nurhan-gokturk-mdvrx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Boş ver çocuğum bunları,

Herşeyi anlamaya kalkma.

Yarın çok şey anlamak zorunda kalacaksın.

''Ayşe neden ikide birde,

Evcilik oynar mısın? ''

Doğru senin daha önemli işlerin var.! ! 

Hayır yavrum, sen daha oyun çocuğusun,

Nasıl olsa roller değişecek,

Sorunlar seni çepeçevre sarınca,

Kaçıp kurtulmak  için asılacaksın  zamanlara

Zamanlarsa seni çoktan terk etmiş olacak,

O zaman sana oynamaya vakit kalmayacak,

Büyüdüğünü anlıyorsun.

Çiçeklerin hep beyazını alıyorsun,

Her şeyi baştan sona çözmek istiyorsun.

Gözlerin hep ağabeyinin sigarasında,

Ablanın mini eteğinde,

Kulakların; ananla, babanın feryatlarında,

Sanma  ki onlar mutluluktan uçuyorlar

Ağabeyin sorunlar yüzünden,

Sigara dumanlarıyla

Düşüncelerini,

Duygularını karartıyor,

Ablan mini eteğiyle gerçekleri,

Çıplak ve apaçık göstermeye çalışıyor,

Baban amirinin, memurunun hıncını anandan,

Anansa hep düşünü kurup ta  elde edemediği,

Kürkünün acısını birbirlerinden alıyorlar,

Sana söz veriyorum küçüğüm,

Bir daha böyle ağzın dolarak gülemeyeceksin,

Bugün olduğu gibi yarında rahat olamayacaksın,

Sana öyle bir yarın bırakıyoruz ki! ! ! ! 

Kördüğüm...

Sen İskender değilsin elbette ki çözemeyeceksin,

O zaman kuşlar gibi ötseydim,

Kuzu gibi metleseydim.

Yo! !  yoo en iyisi hep çocuk kalsaydım diyeceksin....

Nurhan Göktürk

(Niğde)', 'Boş ver çocuğum bunları, Herşeyi anlamaya kalkma. Yarın çok şey anlamak zorunda kalacaksın. ''Ayşe neden ikide birde, Evcilik oynar mısın? '' ...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/buyumeye-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Limit dolmadan gel', 'limit-dolmadan-gel-abdullah-oral-bmrzu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlayamadık sona varmadan

Ömür limitinin bittiğini

Sindi uzağındasın düşlerimin 

Kac zamandır yollarına asılı kaldı gözlerim.

LİMİT DOLMADAN GEL

Gönül bahçemde yar alkızıl gül ol

Bahçıvanın olup dereyim seni

Çiğ düşmüş yaprağın kurusun diye

Gel sinem üstüne sereyim seni

Gel bahar yaşasın son kez ömrümüz

Aşkın secdesine varsın anlımız

Kredi kartına benzer ömrümüz

Limit dolmadan gel sarayım seni

Vurguni ekin’e katmışım teri

Döğülmüş başağı döş harman yeri

Kaç bons kaldı bilmem limitten geri

Sona varmadan gel göreyim seni', 'Anlayamadık sona varmadan Ömür limitinin bittiğini Sindi uzağındasın düşlerimin  Kac zamandır yollarına asılı kaldı gözlerim. LİMİT DOLMADAN...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/limit-dolmadan-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanatır', 'kanatir-abdullah-oral-ymo1q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KANATIR

Düştüm sevda sularına

Sel kanatır yaraları

Kurşun gelir geçer ama

Dil kanatır yaraları

Içimde bir yara sızlar

Hüzün kuşanmış ay yüzler

Çiğ düşmüş ıslanmış gözler

Gül kanatır yaraları

Dağlarına haber salmış

Sırların içinde kalmış

Yen içinde kırık kalmış

Kol kanatır yaraları

Vurguninin sevgi dini

Sevdan ile yaktı günü

Bir çıkmaza düştü sonu

Yol kanatır yaraları', 'KANATIR Düştüm sevda sularına Sel kanatır yaraları Kurşun gelir geçer ama Dil kanatır yaraları Içimde bir yara sızlar Hüzün kuşanmış ay yüzl...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kanatir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Omuzlar', 'omuzlar-fikret-dundar-cuxgv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Omuzlar vardır, apoletli.

Dimdik,heybetli.

Omuzlar var, oynak,

Öpülesi.

Omuzlar var

Can yakar,

Kıvrak mı kıvrak! 

Omuzlar var

Yuvarlak başlı.

Kıpır kıpır,

Kahreder insanı.

Omuzlar vardır,

Eğrilmiş çökmüş

Yükü altında hayatın.

Üzerine basıla basıla.

Nasır tutmuş.

Başkalarına hayat boyu 

Basamak olmuş,

Çileli,çarpılmış.

Yere doğru yaklaşmış

Ağrı çeken,

Yorgun olduğunu haykıran omuzlar var.

Yaradana saygılı yaşayan,

Artık hayat yükünü kaldıramaz olmuş

Yıllarca evine aş getiren,

Her şeye omuz veren 

Emektar omuzlar var!', 'Omuzlar vardır, apoletli. Dimdik,heybetli. Omuzlar var, oynak, Öpülesi. Omuzlar var Can yakar, Kıvrak mı kıvrak!  Omuzlar var Yuvarlak başlı...', ARRAY['Türk Edebiyatı','Şiir','Fikret Dündar']::text[], 8.5, '{"poet":"Fikret Dündar","poet_slug":"fikret-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/omuzlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-abdullah-oral-i0bup', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'HÜZÜN

Kaşlarına çiğ’mi yağdı

Hüzün çiçekleri açmış

Yar sinene ok’mu deydi

Gözlerinin feri kaçmış

Saçların tel tel elimde

Adın bir türkü dilimde

Oynayıp durur tenimde

Sanki bıçak kından geçmiş

Yar yanlış karara varma

Zaten ezik içim kırma

Öyle dalgın bakıp durma

Bakışların senden geçmiş

Vurguni bin ömür verir 

Duygularım sana yürür

Seniniçin yanar durur

Sanki beden benden geçmiş', 'HÜZÜN Kaşlarına çiğ’mi yağdı Hüzün çiçekleri açmış Yar sinene ok’mu deydi Gözlerinin feri kaçmış Saçların tel tel elimde Adın bir türkü dili...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/huzun-142-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuçlarım Terliyor Gözlerinde', 'avuclarim-terliyor-gozlerinde-selahattin-yetgin-rqxq7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdanın ovalarına düştüm yar, avuçlarım terliyor gözlerinde

Beklemem artık mevsimsiz yağmurları, beklemem cemreleri,

Sensin bütün rengim, sensin zifiri karanlığımı bölen kutsal ışık

Bir şiir, destan oldum, büyüyorum ‘sevdam’ diyen sözlerinle…

Dillerinin doğurgan ovalarına düştüm düşeli, yüreğime ‘can’ sözlerini sürdün süreli, acılarla örülü bu yüreği sevdin seveli ustura ayazlarım bitti, köklerime yeniden can yürüdü, düşlerimdeki kabuslarım sonlandı yar. İçimdeki incinmiş ve incelmiş sabırlarla, sazlıklarımda boy veren hasretlerle, gecemin denizindeki kahırlarla, avuçlarımda biriktirdiğim göz yaşlarımla, bomboş bir yitiklikle, dizginsiz bekleyişlerdeydim.

Ülkeme düşünce sesinin tınısı bütün ırmaklarımı kardelenler kuşattı. Rengarenk bir gök kuşağı aylar sonra yeniden kraterlerimi boşalttı. Unuttuğum, belki de acılarımın kuyularına attığım bütün sevda sızılarım çocukların çığlıklarıyla bana geri döndü. Titreyen ellerim, nemlenen gözlerim ve kilitlenen sözlerim başka yüzyıla indirdi beni. Yar, karlarımı eriten, sevdamı yeniden dirilten yar, seninle bu yürek aşkın otağına yeniden bağdaşını kurdu bu bahar.

Bizi birbirine yansıtan hangi yıldızdır ki, en kıyım acılarda düştü bağrımıza. Ağlamanın mendillerini kurutamadan daha, yüreğimizdeki sancıların tufanında yapıştı yakamıza. Denizlerimin yunusunun sözcükleri silinmeden ruhumdan, ormanlarımın keklikleri uçmadan kafesinden sevdanla sarsıldım ben. Yarim, gönlü sürmeli dolunayım. Her şafakta kapımı toynaklarıyla aşan ruhumun deli tayı. Seninle ben dolaşıyorum yeniden şu acılarla örülmüş yalan ve garip dünyayı.

Sevdama sağanaklar gibi çıkagelen, beni uzak diyarlara gülücükleriyle götüren yar. Senden önce hiçbir kırmızı ağlamadı içimde, hiçbir tükenmişlik mutluluk vermedi can evime. Ateşlerin hiç sönmediği bu aşk madeninde kimi orman gözlerine, kimi de düşlerine dalıyorum ben. Ellerin gelince usuma, ellerime bakıyor, gözlerin düşünce içime, gözlerinin zeytin krallıklarında ağına gözyaşı düşmüş balıkçılarla ağlıyorum.

Senin için şiirlerden inşa ettiğim aşk yelkenlimi saldım sulara bak. Delikanlı gezip gecelerde, yorulduğumuz yerlerde dingin uykulara aldım seni. Kök saldığım bütün yerlerde seninle yürek yüreğe, yaşanmamış tüm günleri doldurup heybemize sana sarhoş kelimeler biriktiriyorum. Gönlüme düşen zamansız gölgenle, sevdikçe olgunlaşan meyvelerimle dilim rüzgarda lal, gönlüm yüreğinde gezinen bir sal gibi, bu rüzgarların hiç kesilmediği denizlerden okyanuslarına gidiyorum.

Yatır yüreğine ve pışpışla korkularını şimdi. Senin gözlerinin şavkıdığı kentlerde ara beni. Kolumdaki paslanmış saatleri atmıştım nicedir bilinmezliklere. Nicedir, susmuş yüreğimdeki şarkılarla demli yıldızlar dolduruyordum kadehime. Usumdaki anıların çarpışmasından yüreğim kısa devre yapmış, kirpik seğremelerindeydi gözlerim. Yüreğindeki denizleri bırak ben boyayayım, bırak kelebek kanatlarına rengarenk ışıkların izdüşümlerini indireyim göklerden.

Umutsuzluğu ağlatırsa kırmızı, dilden dile düşer yaşadıklarımızın sızısı. Hayallerin tarlasına yıldız ekip, bildik bir felsefenin içinde çıldırtan bir yalnızlığı oynarsın sevdayla. Bazen kabına dar gelen mantığınla, kimi de metcezir sorgularında dağınık yataklarını toplarsın aşkın. Ürkek mavilikleri sağan, konuşunca tenine değecek bakışların izdüşümünde yeni bir devir açarsın yaşadıklarınla. Düşlerini parçalayan çakallar karanlığın uyandığı yerlerde gölgeni kovalar durmadan.

Avuçlarımda terlemelere duran zamanla, yüreğimde bekleyen harmanla düşlerin hiç eksik olmadığı bir yer var gönül tarlamda. Bir geceden diğer bir geceye geçerken bu sevda, incinmiş bütün sevilmişliklerimizde ‘sen olmasan’ olmuyor işte. Büyük balıkların süzgeçlerinin yosun bağladığı bu aşk denizinde, küçük balıklar ışığa hasret yaşarlar her zaman. Aldırmadan yürüdüğümüz bataklıklar kurutulmadan, gözlerimizdeki yaşlar kurumadan, yüreğimizdeki kutsal sevda pullanmadan, bu denizlerden çıkış yok bize.

Her ağlayışımızda tükendikçe, her sevdalanışımızda yeniden türedikçe, bizi birbirimize bağlayan zaman döndükçe bu sevda da değişime uğramayacak inan. Ellerinle yüreğimi okşadıkça, efsane gözlerinde beni ağırladıkça, ekinlerim yağmurunla büyüdükçe, yüreğimdeki kıyametlere de aldırmayacağım işte.', 'Sevdanın ovalarına düştüm yar, avuçlarım terliyor gözlerinde Beklemem artık mevsimsiz yağmurları, beklemem cemreleri, Sensin bütün rengim, s...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/avuclarim-terliyor-gozlerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmezem', 'gitmezem-abdullah-oral-2ovl9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'GİTMEZEM 

Hırlı hırsız puşt elini

Uzatırya ben tutmazam

Namlulara kurşun sürüp

Gelirlerya ben gitmezem

İkibin ihanet yılı

Çaldılar işçiden çulu

İmamlar haramı dolu

Sunarlarya ben tatmazam

Proleter benim özüm

Güneşe dönüktür yüzüm 

Sürüye salınır gözüm

Sürelerya ben gitmezem

Geçti ömrün güzel çağı

Ağız salya tamdiz bağı

Duydum kuşatmışlar dağı 

Vururlarya ben bitmezem

Vurguni der sar yaşamı

 binyıllık uğraş boşamı

Yoksulumya öz neşemi

Milyar verseler satmazam', 'GİTMEZEM  Hırlı hırsız puşt elini Uzatırya ben tutmazam Namlulara kurşun sürüp Gelirlerya ben gitmezem İkibin ihanet yılı Çaldılar işçiden ç...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gitmezem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerdanlık', 'gerdanlik-altay-taskin-w4pvg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ucun Asya''da bir ucun Avrupa''da

O masmavi boğazın şıklığı sensin,

Kıtaları birleştirmek hayal ise de

Üstünden geçenler biliyor, gerçeksin.

Hüzünlü yatıp kalktılar şimdiye kadar

Rüyalarında bile görmemişlerdi,

Islık çalıyorlar sevincinden yalılar,

Neşe ile yatıp kalkıyorlar şimdi.

Tüm yüzüklere taş, yapılara taç oldun,

Mutlusun, doğaya ellerini açtın,

Gözlere yaşlar, kalplere neşe doldurdun,

Yanında gülen mi, ağlayan mı kalsın.

Gündüz, güneş ile asaletin denizde,

Her gece ay-yıldız ile parlıyorsun,

Serinliyorlar balıklar senin gölgende,

Rüzgarlar ninni söylüyorlar habersiz,

Kokularını sunuyor çiçekler birbir,

Kuşlar ve bulutlar yapamıyor sensiz,

Daha çok anılacaksın geçtikçe devir,

Sayfaları doldurur güzelliklerin,

Kıtalara aranan barışı getirsin

Ömür tüketip toka yapan ellerin...', 'Bir ucun Asya''da bir ucun Avrupa''da O masmavi boğazın şıklığı sensin, Kıtaları birleştirmek hayal ise de Üstünden geçenler biliyor, gerçeksi...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gerdanlik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-hasan-ekrem-63yyw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben böyleyim işte tanıdın beni artık,

Bittiyse gidebilirsin,haydi git artık..

Git artık bakmadan ardına,

Tereddüt etmeden bir an,

Ve hiç duraksamadan,

Git ne olur,geldiğin gibi bana..

Haydi, çabuk git ki dolmasın kıpkızıl yaşlarla gözlerim,

Sen olmasan da ben, seninle dolu anlarda yaşar giderim.

Açmadan bir yara daha gönül ufkumda,

İlkin yavaş sonra çok hızlı git gözlerimden,

Git ki seni sevdiğime pişman olmayayım..', 'Ben böyleyim işte tanıdın beni artık, Bittiyse gidebilirsin,haydi git artık.. Git artık bakmadan ardına, Tereddüt etmeden bir an, Ve hiç dur...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/git-158-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşümesin', 'usumesin-abdullah-oral-imlw3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ÜŞÜMESSİN

Olurda  kuşatırsa zulüm

Çiekli dalını

Avluda gülünü

Sevdaya durmuş dilini

Vur yüreğine öfkeni

Dağlar dökülsün yanaklarından

 Kankızılı çiçeklensin

Ovaların sessizliği

Yaşanmamış aşklariçin 

Bükülmemiş başlariçin

Yık duvarını kör bakışların

Aydınlık düşsün 

Geceyi kuşatan yarınlara

Ve sen hürriyeti ol

            Tutsaklığımın 

Ey aydınlık 

            Dökül ellerime

                Serpil yüreğimde ki

Üşümesin

          Yoksul çocukların

               Masum gülüşlerinde 

                                 UMUT', 'ÜŞÜMESSİN Olurda  kuşatırsa zulüm Çiekli dalını Avluda gülünü Sevdaya durmuş dilini Vur yüreğine öfkeni Dağlar dökülsün yanaklarından  Kankı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/usumesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Olan Sevgimi Gözlerime Gizledim', 'sana-olan-sevgimi-gozlerime-gizledim-umut-gungor-nkvbt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana olan sevgimi gözlerime gizledim,

Ömür boyu onları senin ile sözledim,

Görmediğim her dakika saniye özledim,

Ceylan gözlüm inan''ki sana aşkım çığ gibi.

Yüreğimde ateşi hiç bir doktor ölçmedi,

Ne kadar derece konduysa yine yetmedi,

Tartıya koydum da yüreği kantar çekmedi,

Ceylan gözlüm inan''ki sana aşkım çığ gibi.', 'Sana olan sevgimi gözlerime gizledim, Ömür boyu onları senin ile sözledim, Görmediğim her dakika saniye özledim, Ceylan gözlüm inan''ki sana ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sana-olan-sevgimi-gozlerime-gizledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konma Vurulan Karanfil Yapraklarına', 'konma-vurulan-karanfil-yapraklarina-eyup-selahattin-dalkiran-o8e13', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir bir düştü

O uzun ince yolda

Vuruldular karanfil yapraklarında 

Karanfillerimiz.

Bir düzen ki

Her bir oyun birbirini öldürür

Karanfil yapraklarında ölümüne

Yeşil çehreli arılar bile korkar oldu

Türkiyeden,ortadoğuya Türkiyeden,Amerikaya

Uç uç uğur böceğim

Yalnızca kanatlarına güven

Konma vurulan karanfil yapraklarına,vurularak

Öyle bir oyun öyle bir düzen ki

her bir oyun birbirini öldürür

Karanfil yapraklarında.

Sonra çaresiz yine uzanır

umutsuz,acımazsız yarınların 

vurulan yaprakları arasına.

Altan geçen karıncalar bakarlar sessiz

Ürkek bakışlarla

neler oluyor diyerek kıtalar arası karanfil şavaşta

Bu ölüm bu şavaş niye diye bağırırlar

Kuşlara,uçaklara bakınırken

Ağlar bir uçtaki Papatyalar

Ağlar bir uçtaki kardelenler

ki hiç bir şeyden korkmayan

Uçurum çiçeği bile korkar oldu

yarlarının duvarlarına tutunarak 

uç uç böceklerinin,helikopter böceklerinin

Ateşinden korunmak için

Ateş etmekte bakın helikopter böcekleri

Suda ki Kurbağalara sıkı sıkıya,acımazsızca

kaldıramazlar başlarını soktukları kumdan

Deve kuşları nedensiz korkularıyla

Sanki haraç mezet gitmekte karanfil pazarı

Kara çingenenin kollarına.

Uç uç uğur böceğim

Yalnızca kanatlarına güverek

Konma vurulan vurulan karanfil yapraklarına

Uzanıyor bak doğalgaz,petrol boruları

Rusyadan,Türkiyeye Türkiyeden,İrana

Öyle bir oyunki

Her bir oyun kendini öldürür

Karanfil yapraklarında

Uç uç uğur böceğim

Cumaya yetişmeyen canlılar,cesetler arasında

Uyar Uyar deki

Yılbaşı çamları,

Minereler süslenmiş

Lambaları yakılmak üzere

Her yer pazar oldu çam ağaçlarına

süslenmiş minereler ile

Tut tutabilirsen durdura bilirsen

Uzanan bir sonraki nükleer başlıklı yarınlara.', 'Bir bir düştü O uzun ince yolda Vuruldular karanfil yapraklarında  Karanfillerimiz. Bir düzen ki Her bir oyun birbirini öldürür Karanfil yap...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/konma-vurulan-karanfil-yapraklarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerinle uyu', 'duslerinle-uyu-nazan-i-zmirli-wyj15', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bırak

düşlerini

uykuya dalsın...

göğsümdeki

başın

kalbimi çalsın...

17.01.2006-antalya', 'bırak düşlerini uykuya dalsın... göğsümdeki başın kalbimi çalsın... 17.01.2006-antalya...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/duslerinle-uyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaredemezsin', 'yaredemezsin-abdullah-oral-ukx0y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YAREDEMEZSİN

Sıkma boğazını yaşlı dünyanın 

Hayat hayli cimri kar edemezsin 

Boşyere saklama kara gözlerin

Sen kendini yoktan var edemezsin

Düşürdünya gülüm aşkı dillere

Savurdun umudu uzak yerlere

Seni benden alan yaban ellere

Sen kendini gayrı yar edemezsim

Ne kaldı yar söyle günden yarına 

Çektin yüreğimi gönül darına 

Ölürüm gülüşüm kalır yarına

Güneşi dünyana dar edenessin

Vurguniyim dinle güzel sesimi

Senden uzakların bırak peşini 

Yelleme boşuna aşk ateşini

Küllenmiş yüreği kor edemessin', 'YAREDEMEZSİN Sıkma boğazını yaşlı dünyanın  Hayat hayli cimri kar edemezsin  Boşyere saklama kara gözlerin Sen kendini yoktan var edemezsin ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yaredemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Hicaptan Mahrem, Nihan Olayım', 'her-hicaptan-mahrem-nihan-olayim-ali-riza-unal-59fhp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne mümkün derdi gam, nigâr-ı dilzâra, 

Velevki gönül tahtına, mihman olayım 

Bi çare ferman-ı hüküm, nalân-ı gülzâra, 

Sen iste her nefes, pinhan olayım

Yek çaredir leylevi aşk, gel pirzadeye, 

Her hicaptan mahrem, nihan olayım..!', 'Ne mümkün derdi gam, nigâr-ı dilzâra,  Velevki gönül tahtına, mihman olayım  Bi çare ferman-ı hüküm, nalân-ı gülzâra,  Sen iste her nefes, p...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/her-hicaptan-mahrem-nihan-olayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılmaz Komutan', 'yilmaz-komutan-altay-taskin-i3bbq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Ben, askerliğin her şeyden ziyade sanatkarlığını severim.'' K.Atatürk-1938

Kararları isabetli omzunda rütbesi

Çarpışırken cephe cephe yılmaz komutan

Ümit doludur alev alev yanan gözleri

Karanlıklarda bir meşaledir ışıtan

Doğu''da dadaş Batı''da zeybek

Coşkuyla onu karşılayan

Bir güneş doğuyor ufuktan

Sıcak sımsıcak Anadolu''ma

Göklerde dalga dalga bayrağım

İşte Mustafa Kemal bu duran

İsabetli bir karar uzatmış elini

Bölünemez bu topraklar bu şanlı vatan

Emrediyor düşünceyle yine vatanından

''Ordular; ilk hedefiniz Akdeniz''dir, ileri! ''', '''Ben, askerliğin her şeyden ziyade sanatkarlığını severim.'' K.Atatürk-1938 Kararları isabetli omzunda rütbesi Çarpışırken cephe cephe yılmaz...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yilmaz-komutan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik 11 (bir çığlık ol ömrüme)', 'lirik-11-bir-ciglik-ol-omrume-fevzi-cebe-cpnpz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'başlamadan biten baharlar

bilinmeyen yaşamlar

unutulan

sessizlik

tarihin sessiz tanıkları

yaşamın gri renkleri onlar

kurumuş yapraklar

hayat veriyorlar yeniden toprağa

bizden önce ve

belki bizden sonra

olması umuduyla

yalnızlık ömür boyu

ıssız bir denizfeneri

gemileri olsa da olmasa da

yanmak zorunda onlar

kendilerini tüketene kadar

bedenleri yerçekiminde

ruhları

ruhları 

ah bu hayatı anlamak

yeni bir tutsaklık

tatlı bir tutsaklık

bir çığlık ol ömrüme

sil baştan olmasa da herşey

bir çığlık ol ömrüme

her gün yeni bir tutsaklığa mahkum kalsam da

bir çığlık ol ömrüme

yeret belleğimde yeniden

18.03.2004.20.46', 'başlamadan biten baharlar bilinmeyen yaşamlar unutulan sessizlik tarihin sessiz tanıkları yaşamın gri renkleri onlar kurumuş yapraklar hayat...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Cebe']::text[], 8.5, '{"poet":"Fevzi Cebe","poet_slug":"fevzi-cebe","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/lirik-11-bir-ciglik-ol-omrume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüyorsun', 'guluyorsun-mustafa-alpaydin-gygng', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevda nedir bilmiyorsun

Kalp kırmayı seviyorsun

Sonra gülüp geçiyorsun

Aklınca eğleniyorsun.

Gururuna esir oldun

Çok koşturdun tez yoruldun

Kırkından sonra duruldun

Aklınca eğleniyorsun.

Sen hiç mesut olamazsın

Mutluluğu bulamazsın

Sevgiden de anlamazsın

Aklınca eğleniyorsun.

Ruh önce sever bedenden

Sevdan miras kaldı senden

Arlanman gerek halinden

Kahkahayla gülüyorsun.

**Sana yazıyorum sanma / Nar çiçeğim sen alınma / Hüzünlenip kaygılanma / Birtanemsin biliyorsun.**', 'Sevda nedir bilmiyorsun Kalp kırmayı seviyorsun Sonra gülüp geçiyorsun Aklınca eğleniyorsun. Gururuna esir oldun Çok koşturdun tez yoruldun ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alpaydın']::text[], 8.5, '{"poet":"Mustafa Alpaydın","poet_slug":"mustafa-alpaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/guluyorsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlarına Hilal Çizdim Üç Ayla', 'daglarina-hilal-cizdim-uc-ayla-umut-gungor-vhqhe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağlarına hilal çizdim üç ayla,

Kayseri yücesi Erciyes yayla,

Dolaşsam sende bir güzel al tayla,

Dağları karlı hep güzel Erciyes.

Her yıl Ağustos''ta coşan Erciyes,

Milyonlarla koşup taşan Erciyes,

Dünyaya al bayrak açan Erciyes,

Dağları karlı hep güzel Erciyes.', 'Dağlarına hilal çizdim üç ayla, Kayseri yücesi Erciyes yayla, Dolaşsam sende bir güzel al tayla, Dağları karlı hep güzel Erciyes. Her yıl Ağ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/daglarina-hilal-cizdim-uc-ayla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-mehmet-yucel-karaciga-ykmqd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımla ve hüznümle baş başa

Gözyaşımın kekremsi tadını

Hissediyorum dudaklarımda

Her bir damla gözyaşı

Dokunduğunda dudağıma

Saçımdan bir telde sanki

İnadına ağarıyor 

Yıllarımı çalıp gidiyor

Bu yazdıklarımı isyan sanma

HAŞA asla yakışmaz bana

Sadece yaşadıklarım,

Umutlarım,

Duygularım,

YALNIZLIĞIM SENİ

Anlatmama gerek yok 

Sen beni tek anlayan anlayansın', 'Yalnızlığımla ve hüznümle baş başa Gözyaşımın kekremsi tadını Hissediyorum dudaklarımda Her bir damla gözyaşı Dokunduğunda dudağıma Saçımdan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yücel Karaciğa']::text[], 8.5, '{"poet":"Mehmet Yücel Karaciğa","poet_slug":"mehmet-yucel-karaciga","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalnizligim-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalden Öteye', 'hayalden-oteye-mehmet-yucel-karaciga-8kxld', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aslında şöyle uzun uzun

Karşılıklı sohbet etmeye 

Ne kadar ihtiyacım var bi bilsen. 

Biliyorsun beni nedense

Pek anlayan insan yok

Beni anlamıyorlar mı

Yoksa ben mi anlaşılmazım 

Bende anlamadım

Hayat işte naparsın. 

Hep anlatmak istediklerini içine atarsın. 

İçine attıkça çoğalır

Hani bir şeyi biriktirirsin, biriktirirsinde 

Sonunda kabına sığmaz taşar ya 

İşte benim içimde aynen öyle

Hatta patlama derecesinde

Sohbet nedir, nasıl yapılır

Onu bile unuttum sonunda 

Oysa ne hayallerim var benimde

Öylesine güzel hayaller ki

İçine daldıkça güzelleşen

Güzelleştikçe mutlu eden

ahhhh ahhhh 

Hayalden öteye gitmiyor işte', 'Aslında şöyle uzun uzun Karşılıklı sohbet etmeye  Ne kadar ihtiyacım var bi bilsen.  Biliyorsun beni nedense Pek anlayan insan yok Beni anla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yücel Karaciğa']::text[], 8.5, '{"poet":"Mehmet Yücel Karaciğa","poet_slug":"mehmet-yucel-karaciga","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hayalden-oteye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayma Ana Genç Osman''ı Büyütmüş', 'hayma-ana-genc-osman-i-buyutmus-umut-gungor-h66m4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayma ana genç Osman''ı büyütmüş,

Nasihatla Kayı Boyu yürütmüş,

Dedikleri tüm obaya övütmüş,

Nasip oldu gördük kutlu türbesi.

Gidip gördük şifa dolu pınarı,

Tam yanında üçyüz yıllık çınarı,

Domaniç''te bir cennetin kenarı,

Nasip oldu gördük kutlu türbesi.

Not: Buradaki Genç Osman Osman Gazidir.

Ayrıca özellikle ve hasseten bu geziye önderlik eden bu geziyi düzenlememizi sağlayan Sadi YILMAZ kardeşime çok teşekkürlerimi iletirim.Yine bizleri Domaniç''in dışında karşılama lütfu gösterip bizi gezilecek yerlere götüren Domaniç''in tarihini ayrıntılı bir şekilde anlatan, belediye personeli ile birlikte bize eşlik eden seferber olan Domaniç Belediye Başkanına çok teşekkürlerimi iletirim Allah onlardan razı olsun.Sanırım bir Domaniç gezisi daha yapılmalı daha geniş çapta yada Domaniç Hayma Ana Şenliklerinde.

Yine bu gezinin düzenlenmesinde en büyük katkısı olan başkanımız Hünkar DAĞLI yine Fahrettin KÖSEOĞLU ve Fatih TAŞKIN ve Nuray ALPER ve eşi Emre ALPER kardeşlerime, Ali GÜNDÜZ beye Ahmet KURT abimede ve gezimize katılan değerli şair kardeşlerimizede ayrıca teşekkür ederim.', 'Hayma ana genç Osman''ı büyütmüş, Nasihatla Kayı Boyu yürütmüş, Dedikleri tüm obaya övütmüş, Nasip oldu gördük kutlu türbesi. Gidip gördük şi...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hayma-ana-genc-osman-i-buyutmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eceme', 'eceme-sedat-akguden-z8i45', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ece akgüdene itafen

Bir gün gel

O ne zamansa

sarıl boynuma

hiç bırakmamışcasına

usulca

seni seviyorum de amca

sana hiçbir şey söylemesemde 

yetmez mi yüreğimden

seni çok seviyorum desemde', 'ece akgüdene itafen Bir gün gel O ne zamansa sarıl boynuma hiç bırakmamışcasına usulca seni seviyorum de amca sana hiçbir şey söylemesemde  ...', ARRAY['Türk Edebiyatı','Şiir','Sedat Akgüden']::text[], 8.5, '{"poet":"Sedat Akgüden","poet_slug":"sedat-akguden","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/eceme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Gözün Gördüğünü Sever', 'gonul-gozun-gordugunu-sever-mehmet-yucel-karaciga-41hgz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Baktım gözlerine

Gözlerinde kaldım

Aldım ellerini ellerime

Ellerimde kaldın 

Gözlerin gözlerimde

Ellerin ellerimde

Yandı işte gönlüm

Sen neyle işte öyle eyle

Göz Görür gönüle söyler

Gönül gözün gördüğünü sever

Sonra her derdi beden çeker

Ben çektim sen çekme', 'Baktım gözlerine Gözlerinde kaldım Aldım ellerini ellerime Ellerimde kaldın  Gözlerin gözlerimde Ellerin ellerimde Yandı işte gönlüm Sen ney...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yücel Karaciğa']::text[], 8.5, '{"poet":"Mehmet Yücel Karaciğa","poet_slug":"mehmet-yucel-karaciga","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-gozun-gordugunu-sever-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Durakta', 'son-durakta-salim-erben-asi40', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unutulmayan vedalar bıraktım 

Otobüs pencerelerinde 

El salladım 

Buseler kondurdum buğulu camlara 

Acı tebessümler biriktirerek 

Yanaklarımda 

Kimi hasret adını aldı gitti 

Kaçar gibi 

Kimi ayrılık tadını aldı 

Dönecekmiş gibi 

Bunlar billur dudaklarından 

Su içtiğim 

Soluk kesen gecelerin 

Masum öpüşleriydi 

Yok artık ne sen ne de 

Deli sevdanın çılgın gençliği 

Karanlık yolun son ışığı 

Ve o ışığın altında toplanan 

Sevgililerin son durağı 

Yok artık 

Arama zalim boşu boşuna', 'Unutulmayan vedalar bıraktım  Otobüs pencerelerinde  El salladım  Buseler kondurdum buğulu camlara  Acı tebessümler biriktirerek  Yanaklarım...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/son-durakta-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pirzola', 'pirzola-sedat-akguden-qzfz6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nasılda kenetlenmişiz birbirimize

satırın eliyle ezerler ikimizide

sen bensiz

ben sensiz edemeyiz

sana en yakın ben kemik

sen et

lütfen kendine dikkat et', 'Nasılda kenetlenmişiz birbirimize satırın eliyle ezerler ikimizide sen bensiz ben sensiz edemeyiz sana en yakın ben kemik sen et lütfen kend...', ARRAY['Türk Edebiyatı','Şiir','Sedat Akgüden']::text[], 8.5, '{"poet":"Sedat Akgüden","poet_slug":"sedat-akguden","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/pirzola-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslını İnkar..', 'aslini-i-nkar-ali-orhan-gunaydin-46ect', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah! bir bilseydin dostum,

Söylediklerinin yanlışlığını.

Doğru ile yanlışın arasındaki o müthiş farklılığı...

Yazık ki ne yazık,

Bu dünya senide değiştirmekte,

Senin söylediklerine aslında,

Aslını İnkar denmekte...', 'Ah! bir bilseydin dostum, Söylediklerinin yanlışlığını. Doğru ile yanlışın arasındaki o müthiş farklılığı... Yazık ki ne yazık, Bu dünya sen...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/aslini-inkar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-i-lyas-genc-tfias', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni tanımadan öncede yalnızdım

Ama yalnızlığın bu kadar, 

Acı olduğunu anlamazdım..

Gecelerle paylaşırdım yalnızlığımı, 

Duvarlara anlatırdım 

Çiçeklerle konuşur, rahatlardım.. 

Bu kadar incitmezdi beni yalnızlık 

Kaç çeşit yalnızlık var bilmezdim

Hep güneşi yalnız, yıldızları dost sanırdım

Oysa seni tanıdıktan sonra

Yıldızlarında yalnız olduğunu anladım.. 

Gökyüzündeki yıldızların 

Kaçının birbirinden haberi var 

Bunları hiç düşünmezdim 

yalnızlık bu kadar koymazdı bana

Hem yalnız olduğumu umursamazdım

Ama şimdi seni özlemek var ya 

Yalnızlığın, ne kadar ağır 

Bir işkence olduğunu anlatıyor bana..

Hiçbir şey paylaşamıyorum seninle

Kelimeler bozguna uğruyor

Dilimin ucuna kadar geliyor 

Bakışlarında eriyip kayboluyor

Sen yanımdayken yalnızlık uzaklaşıyor 

Zaman akıp gidiyor

Sen yokken yalnızlık koyuyor bana

Her şey yerli yerinde duruyor 

Anlatamıyorum…anlatamıyorum sana

Su koskoca şehir sensiz 

Hiçbir değer taşımıyor..bu kalabalıkta

Yalnızım…Yalnız ve sensizim

Bazen hayal kuruyorum 

Kendi kendime yanındaymışım gibi

Oysa hayalden öteye gecmıyor. hem geçse 

Yalnızlığımın bir anlamı olmaz

Elimi uzatsam dokunacağım yalnızlığa

Ne ölüm.. ne yaşam.. nede sen..! 

Hiçbir şey yalnızlık kadar yakın değil bana…

yasak_tutku', 'Seni tanımadan öncede yalnızdım Ama yalnızlığın bu kadar,  Acı olduğunu anlamazdım.. Gecelerle paylaşırdım yalnızlığımı,  Duvarlara anlatırd...', ARRAY['Türk Edebiyatı','Şiir','İlyas Genç']::text[], 8.5, '{"poet":"İlyas Genç","poet_slug":"i-lyas-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yalnizim-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhabalar Güneyin Kızı', 'merhabalar-guneyin-kizi-munevver-duver-04gmo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Merhabalar Güneyin Kızı

Getiren şahsın ismi İsmail Altınışık, 

Dört kitap getirdi birbirinden şık. 

Bunlarla sağlarız şiir hazzımızı, 

Neler de yazmış bu Güneyin Kızı... 

Hepsini de okuyacağız tek tek, 

Öncelikle elimde ''Sırça Yürek'' 

''Yalgın'' ismi de, ikinci olacak, 

Güzeldir, çünkü kapağına bir bak... 

''Güzeller Kervanı Gönülden Geçer'', 

Şiirden anlayan bu kapağı seçer... 

Bakalım bir dördüncü daha vardı, 

Sıradağ resimleri ve ''Dağ Ardı...'' 

Ayrıca gazeteler takvimler de var, 

Hele takvimdeki güzel sanki bahar. 

Tüm Türkiye tanıyacak bu Şaire''yi, 

Bu kitaplar genişletir mevcut daireyi. 

Derler ya ''kitap gibi, çevir çevir oku'' 

Ne iş düşünürsün bunlarla ne uyku. 

Şiirler yazarının sanki kartviziti, 

Güneyin Kızı demişler ya o bile yetti... 

İsmin yayılsın dalga dalga her yere, 

Candan sevgiler Münevver Düver''e... 

17.01.2006 

Ekrem Şama', 'Merhabalar Güneyin Kızı Getiren şahsın ismi İsmail Altınışık,  Dört kitap getirdi birbirinden şık.  Bunlarla sağlarız şiir hazzımızı,  Neler...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/merhabalar-guneyin-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağrı Dağı', 'agri-dagi-i-rfan-kayagil-rzx0p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüce dağsın bulutların nicedir

Kor,  kül  olmuş  yüreğimde gecedir.

Söyle Ağrı  geçenleri gördün mü? 

Sen doruğa tırmanıp da döndün mü? 

Ağrı dağı ağıt yakar dururum

Geçitleri bende  arar bulurum

Söyle Ağrı  geçenleri gördün mü? 

Sen doruğa tırmanıp da döndün mü? 

Hasret akan pınarından içerim

Her tependen uçar gibi geçerim

Söyle Ağrı geçenleri gördün mü? 

Sen doruğa tırmanıp da döndün mü? 

Her bir tepen sanki senden uludur

Bir can vermez hangi Allah kuludur? 

Söyle Ağrı geçenleri gördün mü? 

Sen doruğa tırmanıp da döndün mü? 

Çektiğin acıdan  saçın  ağarmış

Yoksa, yaz günleri kar mı yağarmış? 

Söyle Ağrı geçenleri gördün mü? 

Sen doruğa tırmanıp da döndün mü? 

Bizi geçit vermez dağ mı  ayırmış

Sevda gülü biten bağ mı bayırmış

Söyle Ağrı geçenleri gördün mü? 

Sen doruğa tırmanıp da döndün mü?', 'Yüce dağsın bulutların nicedir Kor,  kül  olmuş  yüreğimde gecedir. Söyle Ağrı  geçenleri gördün mü?  Sen doruğa tırmanıp da döndün mü?  Ağr...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/agri-dagi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dharma', 'dharma-kerem-kayar-ebgxs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pencerenin önünde, yaşama açılan sırrı

çözmeye başlarken beş ve yedi yaş arası

bize öğretilmeyenlerin kuşkusuyla

yön vermeye çalışırken

bu an

Bir kız çocuğunun, çüküm yok karmaşası

Bir oğlanın, neden bu garip çıkıntı telaşı

amaçlarımıza yön vermeye başlarken 

hedeflerimiz olmaya başladı, vakitsiz

büyüyorduk ve saate bakmadan

hatta; akrebi ve yelkovanı tanımadan 

saat kaç Anne?   diye sormaları

En önemli ayrıntı ise, içimizde

başlayan '''' süperego '''' yoğunluğu

bize öğretilmeyeni, biz öğrendik

gibi duruyor şimdi yaşam

İlkokulun teneffüs zilleri heyecanı ile

amaçlamayı ve bilgeliği

içimizde büyüyerek

En gerçeği; 

 Yaşamı amaçlamayı ve yasalarını

yaşamın,

her adımda bir adım daha büyümek

her hata bir öğreniş, her kırılma bir geçiş

yavaşça içimize işlerken

süperegonun sesini

belki de ilk defa anlamak

O an,

dünya bir öğretiye dönüşür...', 'Pencerenin önünde, yaşama açılan sırrı çözmeye başlarken beş ve yedi yaş arası bize öğretilmeyenlerin kuşkusuyla yön vermeye çalışırken bu a...', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dharma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkta Bekleyen', 'karanlikta-bekleyen-mukerrem-suna-gumus-fb7x3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1.

Orada, karanlıkta oturuyordu, bir başına. Tam olarak ona baktığım anda O da bana bakıyordu. Ne zamandır oradaydı, hiç bilmiyordum; ama hislerim sürekli kulaklarıma yeminler ediyordu, onun yıllardır orada oturup durmakta olduğuna dair. Ya da bunu O yapıyordu, öyle hissetmemi istiyordu. 

-Kalk gidelim, dedim. 

Hiç kıpırdamadı. Ellerini tuttum, buz gibiydiler. 

-Kalk gidelim, dedim, tekrar.

Hiç ses çıkartmadı. Aynayı yüzüne yaklaştırdım; buğulanıyordu. 

-Kalk gidelim...

Gözlerini gözlerimden hiç ayırmadı:

-Nereye? 

-Çay içelim.

2.

Deniz cayır cayır yanmaktaydı. Sanki ''her şeyin bir parçası'' gibi yanıyordu deniz. Yeryüzünde sadece Onun bakışları hala buz gibiydiler. Ve bir de elleri... İlla ki elleri... Ne yapsam ısıtamayacaktım ellerini. Ya onlar çok çaresizdiler ya da ben. Ya da... ''Her şeyin bir parçası'' gibi biz hepimiz çok çaresizdik. 

-Sıcak bir çay iyi gelir sana.

-...

-Başka bir şey ister misin canım? 

-...

Buz kesmiş bir fincan çayı ellerime tutuşturup arabadan indi.

-Beni bırakıp nereye gidiyorsun, dedim ardından. 

Omuzlarından bir şeyler döküldü yere. 

-Git, dedi, beni yalnız bırak.

-Lütfen senle olmama izin ver, buna ihtiyacım var, lütfen. 

-...

Deniz, içinde buz parçacıkları gezinmekte olan bir fincan çaya rağmen hala yanmaktaydı.

3.

Benden önce dönmüştü. 

Hiç kıpırdamadı. Hiç ses çıkartmadı. Aynayı yüzüne yaklaştırdım, buğulanıyordu. Gözleri soğuktu hala, elleri... Onlara dokunmaya cesaret edemedim. Öylece kaldı orada. Hiç kıpırdamadı. Hiç ses çıkartmadı.

4.

-Affet beni, diyordu, lütfen affet...

Yatağımın baş ucunda duruyordu. Gözleri ıslanmıştı ya da belki bundan çok daha fazlasıydı. Elinde ancak sokak lambasının öngördüğünce parıldayan bir şey tutuyordu. 

-Bunu al, dedi.

Bir aynaydı.

5.

Uyandım.

Elbette uyanacaktım. Onun aynı yerde, aynı şekilde, aynı karanlıkta, aynı ifade ile oturmakta olduğuna yemin edebilirdim.

Ayna... Ah evet, bu oydu.

6.

İşte yine Onu bana bakmadığı bir anda yakalayamamıştım. Ben içeri girdiğimde gözleri çoktan gözlerime kilitlenmişti. Beni, hiç bilmediğim bir şey ile tehdit eder gibiydi bakışları. Ne yana dönsem kurtuluşum olmayacaktı bu bakışlardan, biliyordum artık. 

İlk kez önce O konuştu:

-Affet beni, dedi, lütfen affet...

-Bunu daha önce söylemiştin, dedim, ve bunu daha önce de söylediğini ikimiz de biliyoruz. 

-Babasını banyoda iken izleyen bir çocuk vardı, dedi. Ve bir anahtar deliğinden bakmanın yanlış bir şey olduğunu bilirsin.

-Hayır, bu tür bir şey hiç olmadı.

İtiraz etmedi bana. Böyle bir şey olmadığını ben çoktandır biliyordum. Belki bin yıldır biliyordum gerçeği. Ama gerçek, bin yıldır sürekli değişip gelişmekteydi. 

-Kalk gidelim, dedim.

Gelmedi benimle.

7.

Yerdeki ölü bir çekirgeyi izliyordu! Bana bakmak yerine, yerdeki ölü bir çekirgeyi izliyordu! Tehdit yoktu; fakat bu daha da korkunçtu. Ürktüm. 

Birden,

-Sanki iki tane kafası var, dedi. 

-Saçmalıyorsun, dedim kısaca.

Titriyordu. 

-Hastasın sen, kalk gidelim, dedim. 

-Hayır, dedi, bu soğuğu ben yarattım ve şimdi böylece üşümekteyim.

Çekirge sıçradı ve karanlıkta kayboldu. Çekirgenin, iki tane kafası vardı, ve kayboldu.

8.

Sayın Meslektaşım,

Hastanızın Temporal Kemik Spiral BT incelemesinde; 

Sağ dış kulak yolu kemik kanalı hipoplazik ve dardır. Orta kulak kemik yapıları izlenmekle birlikte epitimpaniuma kadar yumuşak doku dansitesi mevcuttur. Kulak zarı normal anatomik pozisyonda izlenmemektedir. 

Sol dış kulak yolu aplaziktir. Petröz kemikte düzensizlik ve aerasyon kaybı dikkati çekmektedir. Orta kulak kemik yapıları hipoplazik olup malleoloinkal kompleks normal anatomik bütünlüğünü yitirmiştir. Orta kulak içerisinde epitimpaniuma kadar uzanan yumuşak doku dansitesi görülmektedir. Kulak zarı normal anatomik pozisyonda izlenmemektedir. 

Vestibüler ve koklear yapılar ile internal akustik kanallar bilateral tabiidir. 

Ve birkaç şişe kırmızı şarap, birkaç sigara…

Sonuç:

I.	Sağ dış kulak yolu hipoplazisi.

II.	Sol dış kulak yolu aplazisi.

III.	Bilateral orta kulak hipoplazisi.

IV.	Geçirilmiş mastoidit.

V.	Şarap kötü, sigara kötü, ben kötüyüm, O da çok kötü…

9.

Ah işte ne zaman aklıma O gelse, böyle uyumak istiyorum. 

Günlerdir hiç bakmadı bana. Artık bunu yaptığında korkuyorum. Ve galiba korkmam için böyledir, diye düşünüyorum; yeni bir tehdit şekli… 

Hiç ses çıkartmadı. Hiç kıpırdamadı. 

Ayna, buğulandı.

10.

Deprem oluyor.

-Kalk gidelim! Suna! Suna, kalk gidelim.

Hiç itiraz etmeden yürüdü benle. 

-Biliyor musun, rüyamda bir Anka Kuşu idim ben. Gökyüzünün beni yaktığını gördüm. Ellerimi tutsana Suna, ellerimi tut, bak hala sıcaklar! 

Ellerini tuttum, gerçekten öyleydiler. 

-Nereye gidiyoruz, dedi.

-Bilmiyorum.

11.

Aynayı kırdım.

Artık tek kişiydik.

Gecenin o vaktinde, sokakta, tek kişiydik.

Deprem nerede idi, bunu hala bilmiyorum. Bunu, kimse bilmiyordu.

12.

Senin sorduğun sıralar O henüz ölmemişti. Ve ben Onu öldürecek olanı henüz tanımıyordum. Onu öldürecek olanın adını ben koydum. Ortada bir suç varsa, içerisinde benim de yer almam gerekiyordu. Bu nedenle katilin adını hiç olmasa ben koymalıydım. Zaten hiç kimse kendi başına suçlu değildir dostum.

Katilini onunla ben tanıştırdım. O yine karanlıkta bekliyordu ve hiç kimsenin buna inanmasını da istemiyordu. Aslına bakarsan hiç kimsenin buna inanmasına ihtiyacı da yoktu. Bir insanın inanılmaya ihtiyacı yoksa mutludur. Fakat bazen insan inanmak da isteyebilir.

Onu sadece bu kez değil, aslında hiç anlamamış olduğumu itiraf etmeliyim.

Bir insanın adı nasıl da kutsaldır! Onun adını katiline söyledim. Onun o güzel adını bir başkasına, hem de katiline söyledim! O korkmasın diye katiline güzellikli bir ad vererek de, Ona en büyük ihanetimi yerine getirdim. Aydınlanmak ister mi diye düşünmeksizin karanlığını elinden aldım. Nasıl koparttım Onu öyle! 

Onu ben öldürmedim dostum. Ben, aynayı kırdım…', '1. Orada, karanlıkta oturuyordu, bir başına. Tam olarak ona baktığım anda O da bana bakıyordu. Ne zamandır oradaydı, hiç bilmiyordum; ama hi...', ARRAY['Türk Edebiyatı','Şiir','Mükerrem Suna Gümüş']::text[], 8.5, '{"poet":"Mükerrem Suna Gümüş","poet_slug":"mukerrem-suna-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/karanlikta-bekleyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabrim Kalmadı', 'sabrim-kalmadi-esat-erbil-ip1tq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok dedin bekle bekledim işte,

Sabir istedin sabrim kalmadı,

Dedim gelisen gerçek yok düşte,

Sabir istedin sabrim kalmadı.

Aşkın kalbimde girdi gizledi,

Yer yer yaralar açtı sizladi,

Seninle oldum zaman hızladı,

Sabir istedin sabrim kalmadı.

Gönlüm bulandı hiçte durulmaz,

Aşkın kapattı neden sorulmaz,

Her güzele de gönül verilmez,

Sabir istedin sabrim kalmadı.

Ardınca koştum diyar dolaştım,

İnan ki sensiz her zaman şaştım,

Çile çekincem sana ulaştım,

Sabir istedin sabrim kalmadı.', 'Çok dedin bekle bekledim işte, Sabir istedin sabrim kalmadı, Dedim gelisen gerçek yok düşte, Sabir istedin sabrim kalmadı. Aşkın kalbimde gi...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sabrim-kalmadi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamam', 'aglamam-esat-erbil-8kdax', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vefa görset beni salsan ağlaram,

Seven gönlünm yalan söze bağlamam.

Seni sevdim ömür boyu kalağın,

Eglenceyle hoş hayata dalağın.

Bir gün benden uzak olsan özlerem,

Heyacanla yol başında gözlerem.

Her gün gelip seni görmek isterim,

Al gönlünmü sana vermek isterim.

Kavuşmağın umuduyla yaşıram,

Korkum çoktur hasretim çok  taşıram.

Aşkimize engel olma kavuşak,

Gitme uzak küsülmüşsen barışak', 'Vefa görset beni salsan ağlaram, Seven gönlünm yalan söze bağlamam. Seni sevdim ömür boyu kalağın, Eglenceyle hoş hayata dalağın. Bir gün be...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aglamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerimde', 'ellerimde-esat-erbil-93um0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerimde renkli demet güller var,

Sana doğru gelip vermek isterim,

Doğru aşka titreyen bir yürek var,

Kokun canda kana sürmek isterim.

Can veririm canan iste can iste,

Alem gibi bende gülmek isterim, 

Sevgimize düzdük Türkü hem beste,

Yaşıyamam sensiz ölmek isterim.

Az çok çektim bu dünyanın çilesin,

Hoş bir hayat sürüp kalmak isterim,

Yola verdim gülüp zaman belasin,

Gözlerine her an dalmak isterim.', 'Ellerimde renkli demet güller var, Sana doğru gelip vermek isterim, Doğru aşka titreyen bir yürek var, Kokun canda kana sürmek isterim. Can ...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ellerimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgâr Havası', 'ruzg-r-havasi-yusuf-ter-xzc3a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin  karanlığında

Soyun boş caddeler

Kaldırımlar yosması güneş

Ay yüzümüzde dolunay

Şu denizin rüzgâr havası

Türkü gibi akan

Nedir gözlerimden 

Dudağıma damlayan? 

Yusuf Ter 15.01.06

saat 22:00 İsviçre', 'Gecenin  karanlığında Soyun boş caddeler Kaldırımlar yosması güneş Ay yüzümüzde dolunay Şu denizin rüzgâr havası Türkü gibi akan Nedir gözle...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ruzgar-havasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Saniye Ayrıldın Ya!', 'bir-saniye-ayrildin-ya-ramazan-ates-dfgz3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sende neyi özledim? 

Bana bakan gözleri,

Beni yakan gözleri,

O cilveli sözleri.

Ben senden ne istedim? 

Beni tutan elleri,

Beni saran kolları,

O sıcacık tenleri.

Ben sende ne aradım? 

Beni ısıtan tatlı dili,

Yüzündeki o gülüşü,

İçten gelen o öpüşü.

Öyleyse ben ne özledim? 

O güzelim gözlerini,

Hele tatlı sözlerini,

Beni saran kollarını,

Ben, seni özledim, seni.

Ramazan Ateş/Enschede-17.1.2006', 'Ben sende neyi özledim?  Bana bakan gözleri, Beni yakan gözleri, O cilveli sözleri. Ben senden ne istedim?  Beni tutan elleri, Beni saran ko...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-saniye-ayrildin-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel-Git Zamanlar – III', 'gel-git-zamanlar-iii-ugur-deniz-ulkegul-gdoab', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sabahçı kahvesinde uykulu mahmur

Saçı başı dağınık bir kadın endamında

Bir yosma kıvamında geçerdi zaman….

Dudağımda tütün kokusu biraz

Biraz hüzün tortusu senden kalan..

Azalan uzaklaşan seslerin ortasında

İsmini saklarcasına sustuğum şehir

Ve aşk..Her soluk alışımda

Sessizce yutkunduğum tek kelimedir…

Saçının teli gelir aklıma

Hafif meşrep gülüşüne saplanır düşüm

Kıvrak ve sokulgan, can yakan bakışına

Bir sigara daha yakar efkarım..Üşürüm..

Pazarlıksız sevişime gülesim gelir

Oysa ücreti mukabil satılıktır aşk

Sevişmeye en asgari ücretten başlamak

Vasıfsız olmakla ilgili bir neticedir….

Gülesim gelir asilzade suçlar tayfasına

Afi’li duruşuna, en aptal soytarının

Buyur abla! Delikanlı adamlarız biz

Gel otur sende bu meşveret sofrasına! ...

Ücreti mukabil satılıktır aşk

Soyunur kendinden duyguları

Çırılçıplak bırakır bütün korkuları

Bedavaya gelir teni ısıtmak! .....

Ben küfürbaz özlemler saklarken içimde

Gelmişini geçmişini yazarım sevmenin

En asil, en soylu, an ahmak biçimde…

Aklımda tenin….', 'Bir sabahçı kahvesinde uykulu mahmur Saçı başı dağınık bir kadın endamında Bir yosma kıvamında geçerdi zaman…. Dudağımda tütün kokusu biraz ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gel-git-zamanlar-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-esat-erbil-kxbaa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat benzer aynaya,

Her gelen bahıp giçer,

İnsan konak dünyaya,

Ne yapsa onu biçer.

Hayat benzer çirağa,

Sönse gider toprağa,

Ölüm salar irağa,

Her kes suyundan içer.

Hayatta tut düz yolu,

Üstüne gelmez kolu,

Dünya kalı biz ölü,

Yigitler hoşluk biçer.

Kötü yoldan yan durak,

Kardeşçe safa sürek,

Parlak yarınlar kurak,

Dostluk ne güzel giçer.', 'Hayat benzer aynaya, Her gelen bahıp giçer, İnsan konak dünyaya, Ne yapsa onu biçer. Hayat benzer çirağa, Sönse gider toprağa, Ölüm salar ir...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayat-287-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sevda Bitmedi, Ama Bitmeli', 'bu-sevda-bitmedi-ama-bitmeli-mustafa-aslan-2-s5160', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Koca bir sene sana verdim,

Hergün sevdim,

Hergün özledim,

Hergün sana belli ettim,

Yaranamadim.

Simdi ayrildik hosuna gitti mi? 

Bitti dedim ya gerçekten bitti mi? 

Yüregin dalgalarla gitti mi? 

Bu sevda bitmedi, ama bitmeli.

Artik yasanmaz bu sehirde günüm zehir,

Ayni okul,

Ayni semt,

Ayni sehir,

Ayni ülke dar gelir bize.

Artik gitmek istiyorum buralardan,

Sence gitmem gerek mi? 

Tarih Ve Saati: 17-01-2006	20:53', 'Koca bir sene sana verdim, Hergün sevdim, Hergün özledim, Hergün sana belli ettim, Yaranamadim. Simdi ayrildik hosuna gitti mi?  Bitti dedim...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-sevda-bitmedi-ama-bitmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarinim Artik Yarinsiz', 'yarinim-artik-yarinsiz-mustafa-aslan-2-ymw0j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün varim, belkide yarim yokum,

Ben sira daglar arasindaki bir okum,

Ben sevdaya aç bir kurdum,

Biktim artik herseyden nerede benim yurdum,

Yarinim artik yarinsiz.

Sen gittin, ben bittim,

Kendi kendimi bitirdim,

Beni sen uçuruma ittin,

Sende benimle bittin,

Yarinim artik yarinsiz.

Tarih Ve Saati: 17-01-2006	21:03', 'Bugün varim, belkide yarim yokum, Ben sira daglar arasindaki bir okum, Ben sevdaya aç bir kurdum, Biktim artik herseyden nerede benim yurdum...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yarinim-artik-yarinsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden 2', 'neden-2-mustafa-aslan-2-7zf1q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmiyorum dedin, neden,

Hergün beni kirdin, neden,

Hayellerimi yiktin, neden,

Umutlarimi sarstin, neden,

Simdi uzaklardasin, Neden.

Biktirdin beni yasantimdan,

Biktirdin beni sevdalardan,

Hergün ah çekip yanmalardan,

Biktim, biktim neden.

Agliyorum simdi gözüm yasli,

Hani nerede kara kasli,

Ardimda var bir anam yasli,

Gözümü yumuyorum dünyaya neden.

Usandim artik aglamaktan,

Her siirimi agliyarak yazmaktan,

Bitmediki bu çilem,

Bitmedi neden.

Tarih Ve Saati: 17-01-2006	20:37', 'Sevmiyorum dedin, neden, Hergün beni kirdin, neden, Hayellerimi yiktin, neden, Umutlarimi sarstin, neden, Simdi uzaklardasin, Neden. Biktird...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/neden-2-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgalar Bile Doymus Dertlere', 'dalgalar-bile-doymus-dertlere-mustafa-aslan-2-osky7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canim sikintilar içinde,

Derdimi anlatmamki, saklarim içimde,

Belli olsada yüzümde,

Basim hergün dertlerde.

Giderim deniz kenarina,

Anlatirim derdimi dalgalara,

Deniz gittikçe yükselir,

Diyemezki bana dertlerle doluyum.

Sevilen hep vefasiz,

Seven hep vijdansiz,

Dertlerim dermansiz,

Yasiyorum yarinsiz.

Hasret doldu yüregime,

Aci, keder var sözlerimde,

Dinlemez oldu dalgalar hersey içimde,

Dalgalar bile doymus dertlere.

Tarih Ve Saati: 17-01-2006	20:41', 'Canim sikintilar içinde, Derdimi anlatmamki, saklarim içimde, Belli olsada yüzümde, Basim hergün dertlerde. Giderim deniz kenarina, Anlatiri...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dalgalar-bile-doymus-dertlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki Varsın', 'i-yi-ki-varsin-ramazan-ates-d53rp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen olmasan,

Ne renklerin adı var,

Ne çiçekler güzeldir.

Sen olmasan,

Ne aldığım nefestir,

Ne de birşey zevk verir.

Sen olmasan,

Gözlerim görmez olur,

Ve dillerim susar.

Sen olmasan,

Ne yagmur zevkli yağar,

Nede güneş güzel doğar.

Sen olmasan,

Ben nefes alamazdım,

Sensiz yaşayamazdım.

Ramazan Ateş/Enschede-17.1.2006', 'Sen olmasan, Ne renklerin adı var, Ne çiçekler güzeldir. Sen olmasan, Ne aldığım nefestir, Ne de birşey zevk verir. Sen olmasan, Gözlerim gö...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iyi-ki-varsin-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biter Mi, Biter Mi Söyle?', 'biter-mi-biter-mi-soyle-mustafa-aslan-2-ky9fm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Simdi yine gözü yasliyim,

Dogdugumdam bahti karaliyim,

Kötü kaderimin kurbaniyim,

Biter mi simdi bu sevda, biter mi söyle? 

Hergün yorgun, birazda solgun,

Bu sevdami sen yüregine soktun,

Yalan sevginle beni uyuttun,

Biter mi simdi bu sevda, biter mi söyle? 

Sen bir ana kuzusu,

Ben ise ölüm sorgusu,

Aci çeker yüregim, gider mi ayrilik kokusu,

Biter mi simdi bu sevda, biter mi söyle? 

Hergün damla yas döktüm,

Ben yagmur dolusu göktüm,

Desem ki seni kalbimden söktüm,

Biter mi simdi bu sevda, biter mi söyle? 

Tarih Ve Saati: 17-01-2006	20:48', 'Simdi yine gözü yasliyim, Dogdugumdam bahti karaliyim, Kötü kaderimin kurbaniyim, Biter mi simdi bu sevda, biter mi söyle?  Hergün yorgun, b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biter-mi-biter-mi-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük.12 [Hayyam ]', 'dortluk-12-hayyam-ercan-akbay-g5tuf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şarabı içerken,Hayyam ı düşün,

    Kadehi öperken,Hayyam ı düşün,

    Çılgınca yaşamış,hayatı üstat,

     Her nefes alışta,Hayyam ı düşün...

                               14.11.2001 İst.', 'Şarabı içerken,Hayyam ı düşün,     Kadehi öperken,Hayyam ı düşün,     Çılgınca yaşamış,hayatı üstat,      Her nefes alışta,Hayyam ı düşün......', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dortluk-12-hayyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Diyecegim', 'seviyorum-diyecegim-mustafa-aslan-2-lvj89', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana siirler yazarak,

Sana gönlümü vererek,

Senin için ölüme hazir bekleyerek,

Gülüsünü görmek için,

Sana seviyorum diyecegim.

Son bir cümlem olacak,

O cümle ben varken yasayacak,

Ben yokken yokolacak,

Hep benimle varolacak,

O gün sana seviyorum diyecegim.

Yalnizda kalsamda,

Ateslerde yansamda,

Korkularla yasasamda,

En son söz olarak sana,

Seviyorum diyecegim.

Tarih Ve Saati: 10-01-2006	03:34', 'Sana siirler yazarak, Sana gönlümü vererek, Senin için ölüme hazir bekleyerek, Gülüsünü görmek için, Sana seviyorum diyecegim. Son bir cümle...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seviyorum-diyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Büyük Bir Yanlis', 'yine-buyuk-bir-yanlis-mustafa-aslan-2-d81bk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Affet beni,

Biliyorum yine büyük bir yanlis yaptim,

Mutlu bir gün düsünürken,

Dünyani kararttim,

Hem seni yaktim,

Hem kendim yandim.

Aglattim,

Aglattiktan sonra dayanamadim,

Agladim,

Gözlerimden yas,

Yüregime kan akittim,

Ben yalniz seni degil,

Ben kendi dünyamida kararttim.

Yalnizliga verdim kendimi seni sevdim,

Sevgimden bir umut bekledim,

Beklerken hep sen vardin,

Gülerken veya aglarken,

Mutluyken veya mutsuzken,

Hep sen vardin,

Yani basimda,

Ve kötülüklere kanat germis gibisin.

Ben seni sevdim,

Sevdimde seni degistirmek istedim,

Degistirmek isterken seni kaybettigimi anladim,

Vazgeçtim,

Geçmedi gönlüm.

Yine büyük bir yanlis yaptim,

Affetmeni isterim,

Bilki sevgilim,

Seni sevdim,

Yalniz seni severim,

Ben senden yalniz sevgi dilenirim.

Tarih Ve Saati: 10-01-2006	03:24', 'Affet beni, Biliyorum yine büyük bir yanlis yaptim, Mutlu bir gün düsünürken, Dünyani kararttim, Hem seni yaktim, Hem kendim yandim. Aglatti...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yine-buyuk-bir-yanlis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak! ! !', 'tutsak-perihan-dosgul-jgam3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nedir bu yaşadıklarım

Çözmek istesem, çözülür mü? ki

Anlamaya çalışsam imkân var mı? 

Neyim ben, kimim ya da? 

Sahibi miyim kendimin? 

Yoksa emanet mi aldım bedenimi? 

Teslim edebilecek miyim? Aldığım gibi

Kim söyleyecek bana.

Soru sorabilir miyim? 

Kırkımda kendim olabilir miyim? 

Tutsaklık mı? yaşadıklarım..

Kendi hayatım mı? Tutsak.

Neden ağlıyor gözlerim.

Durdurmalıyım...

Susmalı. Susmalı mı? 

Söz geçirmeliyim durmaları için

Ama susmuyor yüreğim

Durmuyor gözyaşlarım.

Yaşamaksa eğer nedir bu? 

Ağlamalar nedensizlik mi? 

Nedenler anlamsızlık mı? 

Nedir? 

Özgürlük uzak mı? 

Uzaklarda özürlük var mı? 

Gitmeli miyim? 

Gitmek o kadar kolay mı? ki..

Bu olsa olsa firar…

Özgürlüğe, yaşamaya, kurtuluşa.

Kırkından sonra kendini bulmaya

Bedeninin, ruhunun, beyninin sahibi olmaya

Yüreğini anlamına göre yaşamaya…', 'Nedir bu yaşadıklarım Çözmek istesem, çözülür mü? ki Anlamaya çalışsam imkân var mı?  Neyim ben, kimim ya da?  Sahibi miyim kendimin?  Yoksa...', ARRAY['Türk Edebiyatı','Şiir','Perihan Dosgül']::text[], 8.5, '{"poet":"Perihan Dosgül","poet_slug":"perihan-dosgul","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/tutsak-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda hala çalışmadı dersini.! ! ! ! !', 'sevda-hala-calismadi-dersini-guler-atas-achfl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'eyyyyyyy TÜRKİYE’li kadınlar

Bir otobüs durağında

Başınıza çuval geçirdiler

Siz orada değildiniz.

..................şimdilik

Ama

Bir gün evinizde 

Bir gün yatak odanızda

Bir gün sevdalınızın kollarında

Önce bir çuvala 

Sonra hoyratça intikamlara.......

O çuval bu gün  bir otobüs durağında

SEVDA AYDIN a

GÜLBAHAR a / DERYA ya / 

TUĞBA ye /HAFİFE ye

Yani memleket sevdalısı 

Bütün kadınlara giydirildi

Ey başımdaki keskin kılıç

Nasıl büyüksün ki

Tanrı gibi secde istersin

Öyle eminsin ki doğrundan

Akan kanı görmezsin

Kestiğin parmaktan

Ders vermekse niyetin

SEVDA hala çalışmadı dersini

GÜLBAHAR kötü öğrenci

DERYA TUĞBA HAFİFE 

Başka sınıflarda bu günlerde

Ve hala otobüs durağından

Ve de korkmadan biniyorlar otobüslere

Yine sanat yapıyorlar

Yine yazı yazıyorlar

Ve yine inadına sokaklardalar

Eyy TÜRKİYE ‘li kadınlar

Başınıza çuval geçirdiler

Yusufpaşa da

Siz orda değildiniz şimdilik

Ama bir gün? ? ? ? ? 

-25/12/2005

12 aralık 2005 tarihinde ekin sanat merkezi çalışanı Sevda Aydın, Yusufpaşa otobüs durağından, başına çuval geçirilerek kaçırılmış ve arka sokaklarda güpe gündüz tecavüz edilip baygın bir şekilde bırakılmıştır.Olay faili meçhul de kalmıştır..Benzer şekilde Gülbahar, Derya, Tuğba ve Hafife arkadaşlarda 2005 yılında yaşanmış diğer olayların mağdurlarıdır..', 'eyyyyyyy TÜRKİYE’li kadınlar Bir otobüs durağında Başınıza çuval geçirdiler Siz orada değildiniz. ..................şimdilik Ama Bir gün evi...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sevda-hala-calismadi-dersini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyyar satıcılar', 'seyyar-saticilar-nevzat-ozkan-5m3fl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'karanlık sinsice çökmüş

akşam ayazı çıktı çıkacak

köşede tabela

tabelanın altında

kafa kafaya vermiş

sarhoş iki seyyar araba

arabalar sarhoş ama

satıcılar ayakta

boş sandıklar yakılmış

yorgun kollar uzanmış

kirli eller

danseden alevlerin üstünde

meyvaların bir kısmı çürük

çekilen iki nefes sigaranın ardından

soluk kesen kesik kesik öksürük

sohbet derin

konu ekmek parası

birinin yüzü solgun

sinirleri çok gergin

diğerinin yanağında kimbilir ne yarası

vakit gece yarısı,ateş küllendi 

gölgeler çekildi çoktan

iki sarhoş araba

yalpalayarak daldılar karanlığa', 'karanlık sinsice çökmüş akşam ayazı çıktı çıkacak köşede tabela tabelanın altında kafa kafaya vermiş sarhoş iki seyyar araba arabalar sarhoş...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seyyar-saticilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Noktayım', 'noktayim-ramazan-ates-hdje6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kağıt, birde kalem,

Kendimi yazacaktım.

Düşündüm istemeden,

Nasıl başlıyacaktım? 

Kalem değdi kağıda,

Çizildi bir tek nokta,

Ne kalemi kaldıra bildim,

Ne de nokta çoğalmakta.

Demekki bu Dünya’da,

Nokta kadar bir şeyim,

Ben beni tanımazsam,

Kimden bir şey isteyim? 

Ne kadar düşündüğümü,

Unuttum bilmiyorum.

Halen nokta kaldım,

Bir çizgi çizmiyorum.

Dedim kendi kendime,

Bu nokta sensin işte; 

Varlığın değerin,

Ancak o nokta işte.

Karamsar olma diye,

Nasihat ediyorlar.

Koskoca bedenimle,

Noktayım bilmiyorlar.

Noktanın yarısı,

İçimdeki imandır; 

İmanım olmasaydı,

Nokta bile yarımdı.

Noktayı küçümseme,

Mühimdir hayatında.

Anlamı çok büyüktür; 

Tam yerine konursa.

Noktasız kalmıyalım,

Virgüle dönmeyelim.

Nokta bir ışık olsun,

Sakın ha sönmeyelim.

Hadi bir nokta koyup,

Bitireyim sözümü,

Küçük bir nokta diye,

Anlamazlar sözümü,

Oyarlar bak gözümü.

Ramazan Ateş/Enschede-17.1.2006', 'Bir kağıt, birde kalem, Kendimi yazacaktım. Düşündüm istemeden, Nasıl başlıyacaktım?  Kalem değdi kağıda, Çizildi bir tek nokta, Ne kalemi k...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/noktayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Osmanlı Kadısı', 'osmanli-kadisi-kamil-at-g936v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Böyle masum anlattılar osmanlıyı

Öğrenmeden bilemedim kanlıyı

Tek düşünceli olacak yutar canlıyı

Tarihte geçmişte belası vardı.

Birbirlerini ilk fırsatta yedi ısırdı

Sonuna dek oğlu babayı vurdu

Baba da oğlunu vurdu kafayı kırdı

Ecel ile ölmedi meselesi vardı.

İnsan kemiğinden yaptı piramit

İlki Osman''mış amcayı astı hamit

Başka dinde isen, deri yüzdü yahut

Geçmişi kanlı bir sülalesi vardı.

Her paşanın yüzlerce idi çocuğu

Kadısı vardı, ebussuud idi kıcığı

Uyur gezer takipçisi kaybetti çağı

Şimdi tarihte bitti kalesi vardı.

İki mısra söyledi, şair figani''ydi 

Haberi yoktu gammazladı canıydı

Sırtından vuruldu lekelenen adıydı

Tarihte silindiler nicesi vardı.

Kamil At Alevilik var diye çıldırdı

Osmanı tarihe pisliği ile bildirdi

Anadoluyu kana boyadı da saldırdı

Hükmü boşa gitti çaresi vardı.', 'Böyle masum anlattılar osmanlıyı Öğrenmeden bilemedim kanlıyı Tek düşünceli olacak yutar canlıyı Tarihte geçmişte belası vardı. Birbirlerini...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/osmanli-kadisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapılar Kapanıyor', 'kapilar-kapaniyor-ramazan-ates-gi16t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tiren kaçıyor tiren,

Gel artık biz binelim.

Bırak inenler insin,

Son durakta inelim.

Arada istasyonlar,

Tirenler durur kalkar,

Kimizi el sallarda,

Kimi gözlerde yaşlar.

Hayat bu acı tatlı,

Bazende meşakkatli.

Ben benle uğraşırken,

Çok tiren geldi geçti.

Binelim biz tirene,

Artık zaman kalmadı,

Bu tiren son tirendi,

Bizi burdan almalı.

Hedefine varmalı.

Ramazan Ateş/Enschede-17.1.2006', 'Tiren kaçıyor tiren, Gel artık biz binelim. Bırak inenler insin, Son durakta inelim. Arada istasyonlar, Tirenler durur kalkar, Kimizi el sal...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kapilar-kapaniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kekeme Günler', 'kekeme-gunler-tunahan-ermihan-8jnsd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gündür geçer gider derdim

Senden ayrı kalınca anladım

Zamanın kıymetini

Ve belki de ellerini tutamamanın acısını

Ve ben seni...

Gözlerimde hayalin gün batımına bakınca

Bir kez daha andım adını

Gün battı gözlerin batmadı bebeğim ufukta

Ve ben seni…

Her satırda seviyorum demenin

Binlerce yolunu bilmeme rağmen sana

Dilimde adını bilmediğim bir sızı

Gözümde gözlerinin hayali

Yüreğimin orta yerinde filizlenen sen

Ve ben seni

Anla işte ben seni…', 'Gündür geçer gider derdim Senden ayrı kalınca anladım Zamanın kıymetini Ve belki de ellerini tutamamanın acısını Ve ben seni... Gözlerimde h...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kekeme-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hasbihâl', 'bir-hasbih-l-mustafa-benkli-sbps1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir hasbihâl niyeti düştü içime gönül dostlarım! ...

Niyetim vaktinizi almak değil hemen noktalarım..

Bir bayram rehaveti girdi araya, gönüle revâ; 

Bayram; oldu tatil, araya giren günlerle bedâva! ...

Sıcak yuvalarında eş dost sohbeti bayramın tadı; 

Lâkin, sıcak yuvaların bir de vardır arka standı! ... 

Mûtâdım üzre, yine bir hüzün, beni saldı sokağa; 

O mu beni buluyor; ben mi âşinayım bu merâğa? 

Alt geçitler tılsımlı sürprizler atar bazen karşıma; 

Bu gün de, şu üst geçitten geçsem diye, uyup aklıma:

Tenha merdivenlerini adımlayıp üste çıkınca:

Artık sürpriz değil dedim, bunlar; alışkanlık olunca! ...

Soğuk, nemli bir hava, bir tartı makinesi ortada; 

Soğuğa omuz silken yine bir vakar vardı orda da:

Hep deriz ya, her zaman: Rızkı veren Allahtır; öyle de:

Açın hakkı yok mu tokun doyduğu rızktaki hissede? 

Gerçi, lisânen değil; hâl''en cevap vardı anladımsa,

Hep de, bu küçük çocuklar bu hâle dûçar; her nasılsa? 

Biz titrerken, O; titremeyi yenmiş, belki, vakariyle

Azmetmiş; nafakasını temine, pâk alın teriyle! ..

Bir harçlık vereyim diye geçer insanın içinden ya! ...

Mümkün mü kabul ettirmek? Önüne serilse tüm dünya! ..

Eline alınca, verdiğini; tartı parası diye,

Karşılıksız bırakmaz, tartarak, verir sana hediye...

Bu sayede, ben de, yeniden kilomu anlamış oldum; 

Rehavetle, kilo kazanıldığını kavramış oldum..', 'Bir hasbihâl niyeti düştü içime gönül dostlarım! ... Niyetim vaktinizi almak değil hemen noktalarım.. Bir bayram rehaveti girdi araya, gönül...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Benkli']::text[], 8.5, '{"poet":"Mustafa Benkli","poet_slug":"mustafa-benkli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-hasbihal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun Yanımda', 'yoksun-yanimda-sevilay-celik-dboli', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'söylemek istedim ya sana içimde saklı kalanları,

bulutların üstüne yazdım umutlarımı

aşkımızı adını,birde anlamını,

birde anlatamadığım saf duygularımı

söylemek istedim ya ama yoksun yanımda

ellerim,sıcaklığını bile hissetmedi,

gözlerim, gözlerini bile görmedi,

her hüzünlendiğimde kırılan kalbimin tamiri,

senin sevgindi ama o bile yokki yanımda.

bir görebilseydim yüzünü söyle doyasıya,

birde anlatabilseydim sana sevgimi kanasıya,

ben yaklaştıkça sen hep uzaklaştın

bir söyleyemedimki sevgimi YOKSUN YANIMDA:(((', 'söylemek istedim ya sana içimde saklı kalanları, bulutların üstüne yazdım umutlarımı aşkımızı adını,birde anlamını, birde anlatamadığım saf ...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Çelik']::text[], 8.5, '{"poet":"Sevilay Çelik","poet_slug":"sevilay-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yoksun-yanimda-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma O Bir Toprak', 'sanma-o-bir-toprak-ramazan-ates-hzjaa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adın duysam duygularım kabarır,

Ben vatanın, ta kendini özledim.

Bal yesem de onsuz zevki mi olur? 

Ekmeğinin, kokusunu özledim.

Tepelerde kır çiçeği açarken,

Kuzu koyun sağa sola kaçarken,

Çekirgeler zıp zıp edip uçarken,

Ben vatanın, çimenini özledim.

Pınar suyu soğuk olur içmeye,

Piknik yapıp keyfe keyif katmaya,

Lale, sümbül, nergiz çiçek açmaya,

Vatanımın, baharını özledim.

Güzel gözlü kızlarına doyulmaz,

Düğününde oynamadan durulmaz,

Deli taya kolay koşum vurulmaz,

Hem atını, eşeğini özledim.

Hal hatırın sorar kimi görürsen,

Bir ekmeği böler kime söylesen.

Aç yatırmaz, açık koymaz kimseyi,

Ben yurdumun, insanını özledim.

Al bayrağı rüzgar vurur, sallanır,

Ezan sesi, yürekleri inletir.

Her bir köşe, şehit yurdu, bir yatır,

Ben vatanın, toprağını özledim.

Özledim ben, vatanımı özledim.

Ramazan Ateş/Enschede-17.1.2006', 'Adın duysam duygularım kabarır, Ben vatanın, ta kendini özledim. Bal yesem de onsuz zevki mi olur?  Ekmeğinin, kokusunu özledim. Tepelerde k...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sanma-o-bir-toprak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum', 'seni-dusunuyorum-sevilay-celik-k5v2y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu gece,

herşeye ve herkeze inat yine seni düşünüyorum.

yaşadığımız onca yılı,

anıları,hayalleri bir bir aklımdan geçiriyorum

hatırlıyomusun seninle ilk tanıştığımız yeri,

bana tomurcuk gül aldığın o köşe başındaki çiçekçiyi,

elini tuttuğumda nasıl titrediğimi,

nerden bilirdimki herşeyin böyle olacağını

sensiz,sadece hayalinle yaşayacağımı.

sonunu bile bile direniyorum sanki,

aşkın bütün dertlerine,bütün üzüntülerine

razıyım,razıyım diyorum.

meğer razı olduğum aşkımın derdi değil,kaderimmiş

yağmurda bir köşeye sıkışıp direnen kedi misali

bitkince bekliyorum burda ben seni,,

sadece ama sadece tek bir gerceğe bakıyor,

tek bir gerceği yaşıyorum

oda birgün ölürsem senin kollarında ölmekti işte...', 'bu gece, herşeye ve herkeze inat yine seni düşünüyorum. yaşadığımız onca yılı, anıları,hayalleri bir bir aklımdan geçiriyorum hatırlıyomusun...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Çelik']::text[], 8.5, '{"poet":"Sevilay Çelik","poet_slug":"sevilay-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seni-dusunuyorum-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Kollarında Ölmek', 'senin-kollarinda-olmek-sevilay-celik-crlax', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bu gece,

herşeye ve herkeze inat yine seni düşünüyorum.

yaşadığımız onca yılı,

anıları,hayalleri bir bir aklımdan geçiriyorum

hatırlıyomusun seninle ilk tanıştığımız yeri,

bana tomurcuk gül aldığın o köşe başındaki çiçekçiyi,

elini tuttuğumda nasıl titrediğimi,

nerden bilirdimki herşeyin böyle olacağını

sensiz,sadece hayalinle yaşayacağımı.

sonunu bile bile direniyorum sanki,

aşkın bütün dertlerine,bütün üzüntülerine

razıyım,razıyım diyorum.

meğer razı olduğum aşkımın derdi değil,kaderimmiş

yağmurda bir köşeye sıkışıp direnen kedi misali

bitkince bekliyorum burda ben seni,,

sadece ama sadece tek bir gerceğe bakıyor,

tek bir gerceği yaşıyorum

oda birgün ölürsem senin kollarında ölmekti işte...', 'bu gece, herşeye ve herkeze inat yine seni düşünüyorum. yaşadığımız onca yılı, anıları,hayalleri bir bir aklımdan geçiriyorum hatırlıyomusun...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Çelik']::text[], 8.5, '{"poet":"Sevilay Çelik","poet_slug":"sevilay-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/senin-kollarinda-olmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anka', 'anka-mukerrem-suna-gumus-zw45r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I.

bende doğar, bende büyür, bende ölür ancak

ulu bir Tek Tanrı''nın katından

melek kanatlarına çarpan öfkeli yağmur

hangi taşı kaldırsan ben görünürüm

hangi yurtluğa konsan yine ben

ve ey yağmur yağdıkça üşüyen toprak

al içine beni, göklerim deprem

II.

.......................................... duymuşlar ki dünyanın bir yerinde

.......................................... bir Anka yangına bırakmış tüylerini

.......................................... oradaymış bütün insanlar

.......................................... görmek için son kere görkemini

işte bunu herkes görmek isterdi ruhum

kendimi yangınlara attığımı nasıl

pırıltılı bir günün batımında

düştüğümü göklerimden, ve neden

/başka bir yerinde evrenin

yeni güneşler doğmaktadır 

görkemli kanatlarıyla kardeşlerim

senin yurdun gibi yurtlara 

zümrütler taşır/

göğün bir yanı ben, bir yanı alev

bilirler ki sığmaz bedenim ne ağaç kovuğuna

ne de ben gözlerimi koynuna sığdırabildim

işte bu yeryüzü ancak

kaynamaktan usanmış kemiklerimle beni

bütün içtenliğiyle kucaklayacak

/yine de göklerime savurun küllerimi/

III.

.......................................... bir martı olsaydım demem bundan şimdi

.......................................... binlercesinin arasında sadece biri

.......................................... uçtu sanılan, kondu sanılan, öldü sanılan

.......................................... kendini de öyle sanan belki

belki de bir mezarım, göklerim toprak

iğrenerek geçsinler diye yanı başımdan

batak köyün hamfendileri, kibar beyleri

öldürmem kendimi belki de bundan

belki de bu ben''im, bu da yaşamak

IV.

usulca yum beton gözlerini, bu zehir

ikimize yeniden hayat verecektir', 'I. bende doğar, bende büyür, bende ölür ancak ulu bir Tek Tanrı''nın katından melek kanatlarına çarpan öfkeli yağmur hangi taşı kaldırsan ben...', ARRAY['Türk Edebiyatı','Şiir','Mükerrem Suna Gümüş']::text[], 8.5, '{"poet":"Mükerrem Suna Gümüş","poet_slug":"mukerrem-suna-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/anka-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ki', 'sen-ki-ferdi-aydin-1l052', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen icimde bir sorusun anlamsız

Cevabı yıllar kadar uzun.

Bir şarkısın yağmurun dilinden düşmeyen

Yüzüme vurduğunda suskun.

Bir Nehirsin uçsuz bucaksız bulanık bir o kadarda çoşkun.

Bir ağrısın göğsümde bir yerlerde 

Ağrıdığında tam yerini bulamadığım.

Korkutan bişeysin korkusuz gözlerimi

Olmasa nasıl olur diye düşündüren 

Su nefes gibi onsuz olamadığım.

Ve yokluğunun hesabını kimseye soramadığım.

Bir yaşam biçimisin hiç ölmeyen..

Vede Bana Gözlerindeki Gerçekleri Söylemeyen.

Ben senin neyinim diye soran neyim olduğunu göremeyen.

Dudakları kıvılcım avuçları ateş ki

İçimdesin dumansız sabahlara kadar sönmeyen....', 'Sen icimde bir sorusun anlamsız Cevabı yıllar kadar uzun. Bir şarkısın yağmurun dilinden düşmeyen Yüzüme vurduğunda suskun. Bir Nehirsin uçs...', ARRAY['Türk Edebiyatı','Şiir','Ferdi Aydın']::text[], 8.5, '{"poet":"Ferdi Aydın","poet_slug":"ferdi-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-ki-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Gelip', 'bahar-gelip-sahin-kars-qlzjz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahar gelip lâle sümbül açınca,

Yeniler hasretin yarası bende.

Kelebekler çiçeklere uçunca,

Tutuşur sevdanın çırası bende.

Umutlardan hayâllerden haz kaldı,

Yüreğimde katmer katmer iz kaldı.

Nasıl denir şad olmaya az kaldı,

Tümlenmez cümlenin burası bende.

Zaman zaman sıkar dünya dar gelir,

Söyleyemem, belki sözüm hor gelir.

Gönül ister gücüm yetmez zor gelir,

Sızılar göğsümün şurası bende.

Gazel gibi yel önünde savruldum,

Derd-i hicran ile yandım kavruldum.

Sevenimden sevdiğimden ayrıldım,

Ey olmaz bu aşkın yarası bende.

Ömür bağlarına temaşa düşer,

Gönül feryad edip telaşa düşer.

Kimseden fayda yok iş başa düşer,

Ha gayret demenin sırası bende.

Kapısında esir eden hileler,

Hilelerden aşılmıyor kaleler.

Şahin''den gülmeyi almış çileler,

Çekilmez bu yükün darası bende.', 'Bahar gelip lâle sümbül açınca, Yeniler hasretin yarası bende. Kelebekler çiçeklere uçunca, Tutuşur sevdanın çırası bende. Umutlardan hayâll...', ARRAY['Türk Edebiyatı','Şiir','Şahin Kars']::text[], 8.5, '{"poet":"Şahin Kars","poet_slug":"sahin-kars","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gogsumun-surasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-sevilay-celik-05vkj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yaşadığımız onca yılın hatrına

bir kere söyle be sevgilim,birkere söyle

çok şey istemiyorumki sadece iki kelime

yalanda olsa,sahtede olsa bir kere söyle

çok sey istemiyorumki sadece iki kelime

bu sevginin bu hayalin sonuda olsa

yeterki sen söyle be sevgilim yeterki sen söyle,

hiç olmazsa benimle birlikte

bak ben söylüyorum

SENİ SEVİYORUM....', 'yaşadığımız onca yılın hatrına bir kere söyle be sevgilim,birkere söyle çok şey istemiyorumki sadece iki kelime yalanda olsa,sahtede olsa bi...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Çelik']::text[], 8.5, '{"poet":"Sevilay Çelik","poet_slug":"sevilay-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-seviyorum-326-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller', 'guller-orcun-basol-39rvh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Odan bomboştu

Kapın aralık kalmış

Masanın üzerinde son verdiğim güller

Güllerinde senin gibi tek seveni kalmış

Fani hayatta unutulmuş güller gibisin

Solarsında yağmur vurmaz diplerine 

Bir damla yağmuru fazla görür o ılık, bahar rüzgarı

Kapıları çarparda yalnız bırakır insanı

Bu şehrin boş sokakları

Nerdesin', 'Odan bomboştu Kapın aralık kalmış Masanın üzerinde son verdiğim güller Güllerinde senin gibi tek seveni kalmış Fani hayatta unutulmuş güller...', ARRAY['Türk Edebiyatı','Şiir','Orçun Başol']::text[], 8.5, '{"poet":"Orçun Başol","poet_slug":"orcun-basol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/guller-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-orcun-basol-m98sw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uyanın düşlerim, uyanın rüyalarım

Gerçeklerle karşı karşıyayım

Arkada koca bir dağ; 

Çeker beni kendine,

Düşmekten korkuyorum,

Gölgemden irkiliyorum,

Galiba ben ölüyorum …', 'Uyanın düşlerim, uyanın rüyalarım Gerçeklerle karşı karşıyayım Arkada koca bir dağ;  Çeker beni kendine, Düşmekten korkuyorum, Gölgemden irk...', ARRAY['Türk Edebiyatı','Şiir','Orçun Başol']::text[], 8.5, '{"poet":"Orçun Başol","poet_slug":"orcun-basol","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/son-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim', 'gozlerim-mehmet-can-xvfm6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerim  ıslak bulutların ardında..

Yağmur yağdı,yağacak gibi gözlerimden..

Hayat bir fırtına gibi geçiyor.

Dost bildiklerimin, ihanet zincirlerinden..

Hem kazanan,hem yenilen taraf olmak..

İntikam alacakken.. durmak..

Titrek parmaklarımın arasında duran sigara..

Her duman..

Her üfleyişte,ayrı bir hülya bulmak..

Dosdoğru olmanın cezasıdır çektiğim..

Dimdik ayakta durmanın cezası, kırılmak..

Bir tek ben miyim tutan sözlerini…

Öyle ya..

Yenilen tarafım yine..

Dosdoğru oldum..

Suçum insan olmak..', 'Gözlerim  ıslak bulutların ardında.. Yağmur yağdı,yağacak gibi gözlerimden.. Hayat bir fırtına gibi geçiyor. Dost bildiklerimin, ihanet zinc...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerim-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçum İnsan Olmak', 'sucum-i-nsan-olmak-mehmet-can-rf5tp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim  ıslak bulutların ardında..

Yağmur yağdı,yağacak gibi gözlerimden..

Hayat bir fırtına gibi geçiyor.

Dost bildiklerimin, ihanet zincirlerinden..

Hem kazanan,hem yenilen taraf olmak..

İntikam alacakken.. durmak..

Titrek parmaklarımın arasında duran sigara..

Her duman..

Her üfleyişte,ayrı bir hülya bulmak..

Dosdoğru olmanın cezasıdır çektiğim..

