INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Çıkıyor Bütün Sokaklar', 'sana-cikiyor-butun-sokaklar-nurten-koroglu-ltr2q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Girmişim bir çıkmaz sokağa

Adım ne sanım ne bilmiyorum

Yollar yabancı insanlar yabancı

Bu ben değilim biliyorum

Sana çıkıyor bütün sokaklar yürüyorum

Özlediğim mutlu yarınlar yok artık

Bu yanan son alevimdi 

Kadere küsüyorum

Dönmek kolay

Bir o kadarda zor biliyorum

Yapamıyorum

Sana çıkıyor bütün sokaklar yürüyorum

Gözlerin kaldırımlarda

Gözlerin soğuk duvarlarda

Gözlerin bir yaz yağmuru

Islanıyorum ıslanıyorum

Ben iflah olmam biliyorum

Sana çıkıyor bütün sokaklar yürüyorum', 'Girmişim bir çıkmaz sokağa Adım ne sanım ne bilmiyorum Yollar yabancı insanlar yabancı Bu ben değilim biliyorum Sana çıkıyor bütün sokaklar ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sana-cikiyor-butun-sokaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Sen Yarım Kalan Aşkının Tırnaklarını Yemektesin', 'simdi-sen-yarim-kalan-askinin-tirnaklarini-yemektesin-eyup-selahattin-dalkiran-i77md', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitti''mi

Yarım kalan aşk? 

hiç Şaşırman

şimdi sen

Yarım kalan 

Aşkının tırnaklarını yemektesin

Kurulmuş şiş göbekli sofralarda

Yarım kalan devrimler gibi.

Şimdi seni düşünürken bile

Varoşlar içindeki

Çaresizler geçmekte gözlerimin önünden.

Bitti''mi

Yarım kalan aşk? 

Hiç şaşırmam

şimdi sen

Yarım kalan 

aşkının tırnaklarını yemektesin

Kurulmuş şiş göbekli sofralarda

Şimdi seni düşünürken bile

Kelebek kanadından

Daha ince bir yaşam içinde

Afrikada,etopyada,güneydoğuda

Babey karnım aç diyen

ve bir damla suya hasret giden

Küçük Bebekler,çoçuklar geçmekte

Gözümden damlayan gözyaşlarımda.

Niye yalan söyleyeyim

Sen yarım kalan aşk tırnakalarını

Yerken şiş göbekli sofralarda

Benim gözümden

F tipi ceza evlerinde bedavaya yatan

Meydanlarda hakkı için seslenipte

Bedavaya coplanan,saçlarından sürüklenip

Çamurlada sürünen botlar altında çiğnenen

Kuş gribini nasıl yayarız politakaları,

Yapılan planlar ile

Amerkadan kanlarımız alınıp DNA''ları çözülen

İnsanların nasıl değiştirecekleri hesabını yapan

Düşünceler aynadan yansıyan ışıklar gibi geçmekte

Sen orda durma ye yiyebildiğin kadar

Yarım kalan arta kalan aşk tırnaklarını

Şiş göbekli sofralarda

Ye bakalım ye

Yesene Ulaannnn', 'Bitti''mi Yarım kalan aşk?  hiç Şaşırman şimdi sen Yarım kalan  Aşkının tırnaklarını yemektesin Kurulmuş şiş göbekli sofralarda Yarım kalan d...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/simdi-sen-yarim-kalan-askinin-tirnaklarini-yemektesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Küçüğüm-', 'kucugum-elif-gulay-5arv3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'büyüdün artık! 

işte bir bardak çay.

sakın su katma,

katma ki ağzın yansın,

büyüdüğünü anlayasın...', 'büyüdün artık!  işte bir bardak çay. sakın su katma, katma ki ağzın yansın, büyüdüğünü anlayasın......', ARRAY['Türk Edebiyatı','Şiir','Elif Gülay']::text[], 8.5, '{"poet":"Elif Gülay","poet_slug":"elif-gulay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kucugum-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Almanya', 'almanya-sahin-kars-q46xx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeterli reklamın yapılır bizde,

Merak edip sana geldim Almanya.

Cennet misâliydin gönülde gözde,

Seni çok değişik buldum Almanya.

Sokağın süpürdüm, çöplerin attım,

Kolay zor demedim, her işin yaptım.

Böyle miydin? seni ben ihya ettim.

Şimdi de yabancı oldum Almanya.

Köprü oldum ırmağına, çayına.

Yıllar yılı boyun eğdim dayına.

Uşakların el uzatır payıma.

Köle yaşamaktan yıldım Almanya.

Şahin, bayrağına saygı duyarım.

Ver hakkımı kanununa uyarım.

Kucak açmış beni bekler diyarım

Sanma ki arada kaldım Almanya.

Beklediğimiz Bahar', 'Yeterli reklamın yapılır bizde, Merak edip sana geldim Almanya. Cennet misâliydin gönülde gözde, Seni çok değişik buldum Almanya. Sokağın sü...', ARRAY['Türk Edebiyatı','Şiir','Şahin Kars']::text[], 8.5, '{"poet":"Şahin Kars","poet_slug":"sahin-kars","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/almanya-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
