INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmura İnat', 'yagmura-i-nat-baran-demir-59ppd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir düş gördüm beyazlar içinde

Süzülerek gelmekte parlak bir ışık gibi

Omzundan aşağıya  doğru salınmakta saçları

Yağmur yağıyor bardaktan boşalırcasına

Beyazlar içinde ıslak bedenini sararak

Bütün güzelliğini ortaya sunmakta

Saçlarından süzülen damlalar

Dudağından aşağı  doğru akmakta

O ise kendinden geçmiş öylesine 

Salınarak ışığa doğru yürüyerek gitmede

Yağmura inat', 'Bir düş gördüm beyazlar içinde Süzülerek gelmekte parlak bir ışık gibi Omzundan aşağıya  doğru salınmakta saçları Yağmur yağıyor bardaktan b...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yagmura-inat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ucuza Kaçar', 'ask-ucuza-kacar-baran-demir-btkk9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yanlızlığım takılmış peşime 

ardım sıra gelmekte

oysa ben sana gelmek isterim

ama ne çare

senin için atar yüreğim

yanlızlıgını hiçe sayarak

gel de geleyim

kurtar yüreğimi yanlızlıktan

aşk değil elbet bu 

ucuza kaçar

sana yürüyen yanlızlığım

sevdadır asil olan

gel he de be sevdam

yanlız atmasın yüreğim

seni ne çok özledim', 'yanlızlığım takılmış peşime  ardım sıra gelmekte oysa ben sana gelmek isterim ama ne çare senin için atar yüreğim yanlızlıgını hiçe sayarak ...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-ucuza-kacar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mai Sevda', 'mai-sevda-yunus-kara-4o1z4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğimde mecnûn esen  rüzgârı,

Saçımda üşüyen karı sevdim ben.

Yusuf”tan haberci kanlı gömleği,

Mansur”un gittiği darı sevdim ben.

Eyüple ıstırap çeken toprağı,

İbrahim”e âşık narı sevdim ben.

O gözlerin üftadesi çok olur,

Gözünde hareli arı sevdim ben.

Gülün içindeki gülü göreli,

Yaprağa sığınan harı sevdim ben.

                             Yunus KARA', 'Yüreğimde mecnûn esen  rüzgârı, Saçımda üşüyen karı sevdim ben. Yusuf”tan haberci kanlı gömleği, Mansur”un gittiği darı sevdim ben. Eyüple ı...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mai-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mephistopheles Şehri', 'mephistopheles-sehri-utku-demir-houop', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayaletler dolar Mephistopheles şehrine

Bilirim zaptedilmiştir burada yürekler

Sevemezler göz boyayan zümrütün hipnozunda

Saklı hayallerin devasa umutları

Teslim olur asanın bir tek eylemine

Sen de köleydin Mephistopheles emrinde

Bir melek gibi beyazda olsa pelerinin

Büyücünün sihirli küresiydi gözlerin

Mümkün değildi sürüklenmemek çağrıya

Dolamıştın bakışlarınla yaşamın iplerini

Başardı nihayetinde Mephistopheles

Hem seni çaldı hem de hayatımı 

Gittikçe yayılmakta efsanevi ateş

Sevgi ışınlarının soluk kırılışında

Prizmalarda hapsolur aşık renkler 

Gururla atar kandırıkçı şeytan

Kılıksız şehrinde muamma kahkahasını', 'Hayaletler dolar Mephistopheles şehrine Bilirim zaptedilmiştir burada yürekler Sevemezler göz boyayan zümrütün hipnozunda Saklı hayallerin d...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mephistopheles-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiysen Eğer', 'gittiysen-eger-mavi-su-rqapk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gittin ya yine...

Şimdi İstanbul''un kuşlar gibi pırpır göğüne

Yarın o salkım saçak denizine vah vah

O ikimizlik güzelliklerin tümüne öbürgün

Bir şapşal gurbet çöreklenir elbet! 

_Gittiysen Eğer_

İliştirdim kendimi senin yanına

Ellerim ezberlemiş ellerini

Yüzümde parmaklarının sıcaklığı

Göğsüm adanmış ne zamandır

Gözlerimde yüzünün gümüş aydınlığı

Hiç bozmadan belki,

Öylece,

Şu kalabalık ezmeden bende kalan seni.', 'Sen gittin ya yine... Şimdi İstanbul''un kuşlar gibi pırpır göğüne Yarın o salkım saçak denizine vah vah O ikimizlik güzelliklerin tümüne öbü...', ARRAY['Türk Edebiyatı','Şiir','Mavi Su']::text[], 8.5, '{"poet":"Mavi Su","poet_slug":"mavi-su","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gittiysen-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Bahar', 'gel-bahar-yunus-kara-b190g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün gece nevrûz idi, bu kışın mevtasını

Dualarla beraber kaldırmaya gel bahar.

Gül dalında bekleyen  “Hızır-İlyas tasını”

Nefes nefes umutla doldurmaya gel bahar.

Yağmurlarla işleyip güneşten elbiseni,

Zamana konduruver toprak kokan buseni,

Cemrelerle bin defa billurlaşan kâseni,

Çiçeklerle yeniden doldurmaya gel bahar.

Gel bahar; ya sevda ol Leylâ’nın adıyla gel,

Gel bahar; ya ecel ol Azrail kanadıyla gel.

Ya tipi ol ya boran, ya da gözyaşından sel,

Ayrılık ateşini söndürmeye gel bahar.

Seninle anlatırmış bülbül güle yasını,

Işığınla parlatmış İskender Aynasını,

Yusuf’tan miras kalan güzellik deryasını,

Şebnem şebnem her yere kondurmaya gel bahar.

Kuşata dursun  hasret düşlerinde her yeri,

Dirilme vakti şimdi, çıkart artık kefeni.

Adına yaz denilen o sarışın dilberi,

Türkülerle bir daha kandırmaya gel bahar.

				Yunus KARA', 'Dün gece nevrûz idi, bu kışın mevtasını Dualarla beraber kaldırmaya gel bahar. Gül dalında bekleyen  “Hızır-İlyas tasını” Nefes nefes umutla...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gel-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Okumak', 'seni-okumak-dilek-kadioglu-eox2p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni okumak:hayatı tanımak 

seni okumak:askı sevgiyi hasreti tanımak 

seni okumak:yıldızlara bakmak 

seni okumak:yürekte bir heyecan fırtınası yaratmak 

seni okumak:tarifsiz bir duygu bazen 

seni okumak:seni tanımak 

seni okumak:zamandan ve mekandan sıyrılmak 

seni okumak:hayalinde yaşamak 

seni okumak:bir tutku 

seni okumak:gözyaşlarına boğulmak 

seni okumak:her zerresinde kendimi bulmak 

seni okumak:hiç susmamak, konuşmak seninle

seni okumak:sana yazmak, seni taşımak yüreğimde 

seni okumak:her satırında ayrı bir heyecan, askı da, sevgisi de, hasreti de 

seni okumak:bir kelebeğin kanatlarından bakmak dünyaya özgürce 

seni okumak:hasret yağmurlarının altında şemsiyesiz kalmak 

seni okumak:seni okumak yüreğimin şairi demek sana, yüreğinin ışığına vurulmak, ama çarpılan bu yürek nasıl dile gelir, nasıl toplar da yüreğindeki sözleri bocalayarak sana dile getirir, işte seni okumak böyle bir şey, 

Seni okumak: ağlamak bazen, belki de sen o satırları yazarken ağladığın için belki, seni hissetmek şiirlerinde, her satırında seni kazımak yüreğe, öyle bir şey seni okumak...

Seni okumak: Suyu dinlemek, tüm zamanlarından sıyrılıp yeryüzünün manevi dünyanda seyir etmek seni okumak...', 'seni okumak:hayatı tanımak  seni okumak:askı sevgiyi hasreti tanımak  seni okumak:yıldızlara bakmak  seni okumak:yürekte bir heyecan fırtına...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kadıoğlu']::text[], 8.5, '{"poet":"Dilek Kadıoğlu","poet_slug":"dilek-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-okumak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veraset', 'veraset-yunus-kara-dgcg2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her şafak boynumda urganın izi,

Her gece sorguya çekilen benim.

Dar gelir ufkuma tarihin yüzü,

Zamana sığmayıp bükülen benim.

İçimde bozkırın mavi gözleri,

Bir at toynağında gezer her yeri.

Tenimden fışkırır Aras’ın teri,

Gizlice Hazar’a dökülen benim.

Bazen Oğuz oldum bazen Türkmenim,

Bir elim Tuna’da, Çin’de bir elim.

Türküye saz oldum nakışa kilim,

Türklüğün dilinden dökülen benim.

Ruhumda karılan Türklük harcına,

Canımı adadım vatan borcuna,

Her gazadan sonra düşman burcuna,

Zafer muştusuyla çekilen benim.

		Yunus KARA', 'Her şafak boynumda urganın izi, Her gece sorguya çekilen benim. Dar gelir ufkuma tarihin yüzü, Zamana sığmayıp bükülen benim. İçimde bozkırı...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/veraset-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıma', 'kizima-yunus-kara-bbl89', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sancısını ciğerimde duyduğum,

Yüreğimde belediğim umutsun.

Kederimi sevgisiyle yunduğum,

Ömrüme bereket,gözde nurumsun.

Sevgide sadakat denen yarışta,

Senin adın yavrum bil ki en başta.

Allah’a el açıp her yalvarışta,

Dilerim elinden melekler tutsun.

Gülümse gözlerin mutluluk saçsın,

Gönlüme teselli,derde ilaçsın.

Semada güneşim başımda taçsın; 

Kızımsın,canımsın; canım yavrumsun.

			Yunus KARA', 'Sancısını ciğerimde duyduğum, Yüreğimde belediğim umutsun. Kederimi sevgisiyle yunduğum, Ömrüme bereket,gözde nurumsun. Sevgide sadakat dene...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kizima-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Lüks Hayat', 'luks-hayat-mustafa-alpaydin-ok7st', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sil baştan yaşama şansım olsaydı 

Babamdan yüklüce miras kalsaydı 

Gelir çoğalsaydı cüzdan dolsaydı 

Biz de mutluluğa ererdik sevdam. 

Bir elimiz yağda diğeri balda 

Altınlar kasada para çuvalda 

Tatlı bir lüks hayat denilen yolda 

Elele tutuşur gezerdik sevdam. 

Senin bir dediğin iki olmazdı 

Efkarın dağılır hüznün kalmazdı 

Yüreğin yanmazdı tenin solmazdı 

Gül gibi geçinir giderdik sevdam. 

Gönül bahçemizde güller derince 

Maziyi anardık inceden ince 

Yokluk çeken iki aşık görünce 

Onlara da düğün yapardık sevdam.', 'Sil baştan yaşama şansım olsaydı  Babamdan yüklüce miras kalsaydı  Gelir çoğalsaydı cüzdan dolsaydı  Biz de mutluluğa ererdik sevdam.  Bir e...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alpaydın']::text[], 8.5, '{"poet":"Mustafa Alpaydın","poet_slug":"mustafa-alpaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/luks-hayat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayan Ş / Karalama defterine mırıldandıklarım...', 'yasayan-s-karalama-defterine-mirildandiklarim-bir-mim-kemal-ertugrul-153no', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '19

''Şiirim benim''

dediydim

''Şiirim senin''...

Gene benim

Gene senin şiirim

Lakin; 

Şiirim diyemediğim...

18

Kavlim sevmekti

Sevmek dediysek

Öyle laf olsun diye değil 

Yürek yarılıncaya dek...

Başka söze ne gerek

Çatladı yürek..! 

17

Düştükçe düşüyorum

Bir düşte üşüyorum

Hadi 

uzat artık

Kirpiklerini......

16

İçinden çekip aldım

L_iri olmayacak artık Ş_i_irin...

15

Kulağındadır eli

O kadar sıkıldı ki

Pencereden atacak kendini yalnızlığım...

14

Enteresan adamdı

Gökyüzüne evler kurardı

Aylak zamanlarında...

O şimdi müteahhit..! 

13

Yarına gelmedin madem

Bugüne gel..........

Yine I_IH diyorsan

Çık gel dünüme lutfen...

12

Ses ayarı yapmak kadar

Isı ayarı da yapmaktır sözcüklere

Şairin işi....

(ki yapanı var... :)           

11

Zamansız uyanışıdır 

Kırağıya karşı en zayıf yanı çiçeğin... 

10

Yeşil değildin belli

Yeşillerden biriydin

HER doğum gününde

HEP hatırlanan...

9

Denizlerden boş olta

Şiir çekerim özlemlerden

Aylak zamanlarımda....

8

Boşaltma uğraşında

Şair içini

Ama; 

İçmeden...

7

Birini arıyorum...

Bir numara büyük olmalı ama

Ruhu bedeninden...

6

Ne güzel yakışır

Siyahla beyaz? 

Sen beyazlar

Ben karalar içinde...

5

Az buzum değil

Vaz geçilmezliğimdin sen...

V a z   g e ç t i m..! 

4

Usuma şiir düşmüş

Dizleri yaralı

Dizeler harap...

3

Şiire düşen adam

Şiir dökmeli tortularından...

2

Asılacak

Adammışım ben...

Suçum

Ne miymiş? 

Düşlerine girmiş

Düşlerini silmişim...

1

Gönlümü sana verdim vereli

Ne çok özlemişim kendimi

Değil mi?', '19 ''Şiirim benim'' dediydim ''Şiirim senin''... Gene benim Gene senin şiirim Lakin;  Şiirim diyemediğim... 18 Kavlim sevmekti Sevmek dediysek Ö...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/yasayan-s-karalama-defterine-mirildandiklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereden Bileceksin?', 'nereden-bileceksin-yunus-kara-y2io3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sonuncusuyum Mecnûnların; 

Bu yüzyıla yabancı.

Yüreğim sende kaldı,

Yüreğimin yüreğinde çöller kadar bir acı.

Bu yaranın sensin,sendedir,senden olur ilacı.

Fakat sen nereden bileceksin.

Yastığıma rüyalarla işledim en alıcı resmini,

Kapanmayan gözlerim kazıdıkça kazıdı,

Duvarlara,tavanlara ismini.

Cümle âlem anladı tek seni sevdiğimi.

Fakat sen nereden bileceksin? 

Üsküdar da farkında,

Bir peri masalında seni aradığımın.

Uykulardan uyanıp,

Titreyen yüreğimle kapını çaldığımın.

Şahidi göz yaşlarım,

Tek sana ağladığımın.

Fakat sen nereden bileceksin? 

Madem ki yazmadım,yazamadım

Yüreğimin üstüne bu sevdanın adını,

Bırak örtsün hasretin

Bir ankanın tekliğiyle tükenin muradımı.

Gözlerinin elifine yazdım bak,

Alev saran gönlümün,

Gündüzleri buz tutup,her gece yandığını.

Fakat sen nereden bileceksin? 

Yine geçtin düşlerimin ufkundan,

Saçlarının kokusuna uyandım.

Uyandım da bölünmedi bak düşüm,

Tenin ruhumu sardı,dudağımda gülüşün.

Bu benim ki; kuruların içinde yanışına denk yaşın.

Fakat sen nereden bileceksin? 

                       Yunus KARA', 'Sonuncusuyum Mecnûnların;  Bu yüzyıla yabancı. Yüreğim sende kaldı, Yüreğimin yüreğinde çöller kadar bir acı. Bu yaranın sensin,sendedir,sen...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/nereden-bileceksin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-yunus-kara-zzpjz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dikensiz gül gibi görse de gönül,

Ümidi acıyla bilemektir aşk.

Kapanınca bir gün bütün kapılar,

Vuslatı ahrette dilemektir aşk.

Kıvrımlı, upuzun öyle bir yol ki,

Asırlar,içinde noktadır sanki.

Belki Züleyha’dır,Yusuf’tur belki; 

Belki de beyhûde bir emektir aşk.

Aça dursun bir gül hasret çölünde,

Bülbülün nabzıdır atar gülünde.

Göçmen kuş misali yarin gönlünde,

Birkaç günlüğüne tünemektir aşk.

Kurşun geçmez,kılıç kesmez hasreti,

Yaşamayan anlatamaz gurbeti.

Bazen bir ömürdür aşkın diyeti; 

Eceli yürükte belemektir aşk.

Âşığın her zaman böyledir hâli,

Mecnûn’u var eden Leylâ hayali.

Bîsütün önünde Ferhat misali,

Dağları kalburla elemektir aşk.

         Yunus KARA', 'Dikensiz gül gibi görse de gönül, Ümidi acıyla bilemektir aşk. Kapanınca bir gün bütün kapılar, Vuslatı ahrette dilemektir aşk. Kıvrımlı, up...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-519-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor menekşe', 'mor-menekse-yunus-kara-7l135', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Boynunu dayayıp yaprak beline

Aşkın uykusuna dalmış gibisin.

Rüyanda mutlaka dağları görüp,

Dağlardan yadigâr kalmış gibisin.

İşve ile nazdan bir tek sen kaldın,

Rengini ışıktan,nurdan mı  aldın? 

Bilmem kaç gönüle kaç sevda saldın? 

Dersini Leylâ''dan almış gibisin.

Belli ki Ferhat''ın alın terisin,

Şirin''in yüzünde aşkın ferisin,

Sen aşk yolcusunun son seferisin,

Hızını sevdadan almış gibisin.

Saksıda,bahçede,bağda güzelsin,

Ovada,tepede,dağda güzelsin,

Çiçeğe erdiğin çağda güzelsin

Rengini Tuğbâ''dan almış gibisin

               Yunus KARA', 'Boynunu dayayıp yaprak beline Aşkın uykusuna dalmış gibisin. Rüyanda mutlaka dağları görüp, Dağlardan yadigâr kalmış gibisin. İşve ile nazda...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mor-menekse-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamlar', 'aksamlar-ayse-kok-fbo7q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensiz sarhoş şimdi

Derbeder duygularım

Yine kabuslara mahkum

Parçalanmış uykularım

Kaybetmiş rotasını

Meçhullerde umutlarım

Akşamlarda depreşir

Tarifsiz acılarım

Sitemlerim tutuklu

Buğulu gözlerimde

Feryadım sessiz kalmış

Kahrolan yüreğimde

Sünger çekmişim artık 

Yaşanmış kederlere

Akşamlar ağlıyor

Şimdi benim yerime

Aydınlığım sadece

Titreyen mum ışığında

Dileklerim gökyüzünde

Düşmez yağmur damlasında

Hep yolculuk etmişim

Bitmez dertler kervanında

Akşamlar ateş olmuş

İçimdeki yangınımda', 'Sensiz sarhoş şimdi Derbeder duygularım Yine kabuslara mahkum Parçalanmış uykularım Kaybetmiş rotasını Meçhullerde umutlarım Akşamlarda depr...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Kök']::text[], 8.5, '{"poet":"Ayşe Kök","poet_slug":"ayse-kok","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aksamlar-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimiz Çiçek Çiçek Açar', 'yuregimiz-cicek-cicek-acar-zeki-ergin-ysj2z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'susar sanmasınlar 

bu yürek

aynı şiirleri okuyup

aynı türküleri dinledikçe

ve kır çiçeklerini sevdikçe

dağbaşlarında açan

ardından

yüreğimiz çiçeklenir 

deniz kuşlarınca uçar  özgürlüğe

_gülpınar 18oca''06

_şarkılar savrulur ege''den', 'susar sanmasınlar  bu yürek aynı şiirleri okuyup aynı türküleri dinledikçe ve kır çiçeklerini sevdikçe dağbaşlarında açan ardından yüreğimiz...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yuregimiz-cicek-cicek-acar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyordum', 'agliyordum-sair-hejaryan-kwcl5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'AĞLIYORDUM                                           

                         Ben seni şiirlerime yazdım

	Her gün ağlıyordum gözlerin için	

	Ama sen ağlamıyordun  gözlerim için 

	Ben sana şiirler yazıyordun 

	Ben senin kirpiklerin için ağlıyordum                        

	Sen ise ağlamıyordun

	Ama ben sana şiirler yazıyordum

	Gözyaşlarıma dayanarak

	Hangi ayet bahsediyordu 

	         Gözlerinden

	Ama sen bana şiirler yazıyordun

	Sensizliğin gölgesinde

	Ama ben sana hala şiirler yazıyordum

	Sen ise inanmıyordun gözlerinin güzelliğine

	Ama onlarca saat durmuştu gözlerinde

	 Sen ise başkalarının gözleriyle izliyordun 

	GÖZYAŞLARIMI

	Ve her gün gözlerim ağlıyordu

	Gözlerinin karşısında

	SAYGIDAN', 'AĞLIYORDUM                                                                     Ben seni şiirlerime yazdım 	Her gün ağlıyordum gözlerin için	...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/agliyordum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlan', 'i-lan-mikdat-bal-w6fb0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaş ellibir Tuncay Akdeniz adı

Gören duyan varsa selam söylesin

Aramadı bir ay oldu, Mikdat’ı

Gören duyan varsa selam söylesin

Çok iyi bir dosttur yakındır cana

Tuncayım bir yana dünya bir yana

Bunu kim okuyup rastlarsa ona

İnsanlık adına selam söylesin

Herkesin sevdiği saydığı kişi

Yurtta az bulunur Tuncayın eşi

Bağrında yanıyor dostluk ateşi

Bu dostu görenler selam söylesin

Dostun hasretine yanar bu ciğer

Geçmiş olsun deyin hastaysa eğer

Onu bir ziyaret dünyaya değer

Tuncayı görenler selam söylesin

Geçmiş olsun derim hasta olmuşsa

Hastanede bunca zaman kalmışsa

Bana haber versin her kim bulmuşsa

Bir de o dostuma selam söylesin

Mikdat Bal ilanı saldı buradan

Kavuştursun tezden bizi yaratan

Onun kıymetini bildim sonradan

Bilen haber versin, selam söylesin', 'Yaş ellibir Tuncay Akdeniz adı Gören duyan varsa selam söylesin Aramadı bir ay oldu, Mikdat’ı Gören duyan varsa selam söylesin Çok iyi bir d...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ilan-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramızda dağlar var', 'aramizda-daglar-var-sair-hejaryan-0qmwm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ARAMIZDA DAĞLAR VAR

Aramızda dağlar var

Dağlarda karlar

Erir diye beklediğimiz

Aramızda yıllar var

Yıllarda hüzün

Geçer diye beklediğimiz 

Aramızda geceler var

Gecelerde gözlerin 

Bakar diye beklediğimiz 

Aramızda duvarlar var 

Duvarlarda anılar 

Canlanır diye beklediğimiz

Aramızda sen varsın

Sende ben 

SEVER DİYE BEKLEDİĞİMİZ

                           

	Galiba umuttan bahsettim

	M.S.', 'ARAMIZDA DAĞLAR VAR Aramızda dağlar var Dağlarda karlar Erir diye beklediğimiz Aramızda yıllar var Yıllarda hüzün Geçer diye beklediğimiz  A...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aramizda-daglar-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amalar ve Özellikleri', 'amalar-ve-ozellikleri-sair-hejaryan-yzmv9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'AMALAR ve ÖZELLİKLERİ

  Ben ateşi seçtim       

  Derkende yanıyordum

  Seni seviyorum kelimesini 

  Sadece şiirlerde görüyordum

  Çünkü sen hep vardın

  Ancak ben kalmamıştım

  Amayla başlayan bütün seni taşıyordum içimde

  Ancak taşıyamadım beni gözyaşlarıma inat

  Sen oldukça ben olamayacaktım

  Çünkü sen beni kaybettirdim

  O özel problemlerinde 

  Ama ben senin hiç özelin olamadım 

  Çünkü sen sensizliğimi sevdin

  Ben ise hala amalarda 

  Saklınıyordum 

  Biraz sitem biraz gözyaşım

  Kalmıştı sana verecek

  Ancak senden alacacağım çoktu senli bölgelerde

  Ve bu bölgelerin iklimleri hiç yeşermiyordu

   Ve de hiç güneş açmadı gözlerime

  Ve ÖZELlikle taşıyorum AMAlarını 

	m.s.', 'AMALAR ve ÖZELLİKLERİ   Ben ateşi seçtim          Derkende yanıyordum   Seni seviyorum kelimesini    Sadece şiirlerde görüyordum   Çünkü sen...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/amalar-ve-ozellikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Azat', 'azat-sanem-deniz-pw9gd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dolamışken

sarmaşıklar dört bir yanımı

nefes alamam...

Hissedersem  ellerini

tenimde

ateşinde yanamam...

Bırak yağmurları

çare olurlar belki

ayrılıklara...', 'Dolamışken sarmaşıklar dört bir yanımı nefes alamam... Hissedersem  ellerini tenimde ateşinde yanamam... Bırak yağmurları çare olurlar belki...', ARRAY['Türk Edebiyatı','Şiir','Sanem Deniz']::text[], 8.5, '{"poet":"Sanem Deniz","poet_slug":"sanem-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/azat-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beynelminel', 'beynelminel-sair-hejaryan-e99w3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BEYNELMİNEL

ÖZGÜRLÜK Şarkı dinlemenin özelleştirilmesi

KARDEŞLİK Ekmeğin küçük parçası	

EŞİTLİK  Sözde kalan sözcüğün yarısı

DEMOKRASİ Düşüncenin küçük küçük doğranması	

DİN Başı olmayan gövde

GELENEK Mayası bozuk insanlar

	Ve sen tek umudum

	ŞARKILAR İçimde yaşayan son tanrı

M.S.', 'BEYNELMİNEL ÖZGÜRLÜK Şarkı dinlemenin özelleştirilmesi KARDEŞLİK Ekmeğin küçük parçası	 EŞİTLİK  Sözde kalan sözcüğün yarısı DEMOKRASİ Düşün...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beynelminel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Cinnet', 'cinnet-ahmet-turan-altunsu-899sb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'nişanı bir kez ve son kez alacaksın...

hedef rahat…

önce bir “tık” sesi, sonra “pat! ..”...

alnının çatından vurulacaksın! 

zulme tarafsız olmak bakarkörlere mahsus:

inleme ney, sus kudüm, semazen sus, semah sus! 

an vardır andan içre, doğar o anda karar:

sözcük cinnete tutsak; bombada kundak arar...

ve şiir kan gölünde kaybederken sesini,

şair, darağacına uzatır ensesini...

o kadar

yakınım

işte sana

ey sonsuz hayat! 

____________18.01.2006 / Güdül / Ankara

_______________Ahmet Turan Altunsu', 'nişanı bir kez ve son kez alacaksın... hedef rahat… önce bir “tık” sesi, sonra “pat! ..”... alnının çatından vurulacaksın!  zulme tarafsız o...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cinnet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yol Vardı', 'bir-yol-vardi-sair-hejaryan-i53df', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BİR YOL VARDI                                  

	Bir yol vardı gözlerinde 

	Yol üstü çıkmazlarda

	Seni sevmenin sevmek kere 

	Aşığıydım

	Gözyaşlarıyla yazılan şiirlerim vardı 

	Yollarda 

	Yollarda anlatılmayan gözyaşlarım vardı 

	 Gözlerimin nefesinde

	Seni seviyorum diyemiyordum

	Gözlerinin içine

	Ne içten konuşuyordum 

	İçtikçe 

	Gözlerini görünce   mola veren 

	Yolculuklarım vardı 

	Sen kraliyet ailesinden gelmiştin 

	Ben ise zavallı 

	Seni seviyorum ama 

	Sadece şiirlerde

	Yollar anlamıyordu beni 

	Anlayan duvarlar vardı 

	GÖZYAŞLARIMIN İÇİNDE

	M.S.', 'BİR YOL VARDI                                   	Bir yol vardı gözlerinde  	Yol üstü çıkmazlarda 	Seni sevmenin sevmek kere  	Aşığıydım 	Göz...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-yol-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martılar Olur Kadıköy''de', 'martilar-olur-kadikoy-de-nizamettin-ozel-o4ku1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Martılar olur Kadıköy''de; 

Havada süzülür, süzülür...

Fakir bir boyacı çocuk,

Ansızın yanımdan geçer,

Bakan ağlar, gören üzülür...

Martılar olur Kadıköy''de; 

Bir de fakir boyacı çocuklar...

Ekmek parasıdır, gurbettir; 

Daha oyun çağındayken,

İliklerine işler soğuklar...', 'Martılar olur Kadıköy''de;  Havada süzülür, süzülür... Fakir bir boyacı çocuk, Ansızın yanımdan geçer, Bakan ağlar, gören üzülür... Martılar ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/martilar-olur-kadikoy-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırlangıç Günlüğü', 'kirlangic-gunlugu-berrak-su-ynesy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırlangıç oldum bugün,

En tepesinde hüznümün,

Ardına süzüldüm.

Üç beş konak yeri kadar,

Yoruldum.

Geçebildiğim çığlıklar kadar,

Ağladım.

Ki kaflar ardında,

Masallarım var,

Beni bekleyen.

Çok değil,

Bir avaz kadar nefesim.

Sıcak, ürkek,

Yanılgan da olsam,

Tekrar uçacak kadar,

Derin özgürlüğüm.

Berrak Su', 'Kırlangıç oldum bugün, En tepesinde hüznümün, Ardına süzüldüm. Üç beş konak yeri kadar, Yoruldum. Geçebildiğim çığlıklar kadar, Ağladım. Ki ...', ARRAY['Türk Edebiyatı','Şiir','Berrak Su']::text[], 8.5, '{"poet":"Berrak Su","poet_slug":"berrak-su","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kirlangic-gunlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennetten Manzaralar', 'cennetten-manzaralar-sair-hejaryan-7uger', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'CENNETTEN MANZARALAR                         

Cennet, diye bir şey yok

İnanmayın masallara

Tabii lafımız anlamayana değil

Anlatamayana

Cennet,içimizde  bir düş

Bakmayın şeytansı yalanlara

Şeytan bir oyuncak

Ateşsiz zamanlara

Cehennemin  ateşi  yok

Alırız ateşi buralardan

Tabii lafımız  yanana değil 

YAKMAYA ÇALIŞANA

İsteriz cenneti dipsiz  kuyularda

Ararız ibadeti  rekatsal  sayılarda

Ve de  hep ağlarız  ölümlere

Lafımız  ölene değil

ÖLMESİNİ  BİLMEYENE

Birde bakarsın  tanrı  şeytan  elele

Ahirette cennet ararsın

Hep  giden sevgiliye yanarsın

Lafımız sevmeyene değil 

SEVGİSİNİ GÖSTEREMEYENE

Cennet  cehennem iki eski arkadaş 

Birisi sağdan GARDAŞ,diğeri soldan YOLDAŞ

Onlarda ayrılırlar buluşmak niyetiyle

Lafımız kardeşlere değil, 

KARDEŞLERİ AYIRANLARA

Cennette bekler  birkaç huri

İstersin onlarla cennetle buluşmak

Ancak çare önündeki gözden caymak

Lafımız huriye değil

HURİYİ CENNETTE ARAYANA

Adem bir elmayı yedi

Yani sen elmayı  yiyorsun diye

Benimde elmayı yemem gerekmez ki

Lafımız  elmayı yiyene  değil,

CENNETİ ELMADA GÖRENLERE

İnanırsın tanrıya bir cennet  uğruna

Ya cennet  olmasaydı kim  yanardı şeytana

Yakarsın cennetin  ateşini  şeytanla

Lafımız tanrıya değil 

YALNIZ CENNETİNE KANANLARA

Gidersin  şeytan  taşlamaya

Yani şeytanlık  taslamaya

İnanırsın şeytanın yalanlarına

Lafımız inanana değil

İNANDIĞINI SANANA

	m.s.', 'CENNETTEN MANZARALAR                          Cennet, diye bir şey yok İnanmayın masallara Tabii lafımız anlamayana değil Anlatamayana Cenne...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/cennetten-manzaralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Güzel bir Derdim Var', 'cok-guzel-bir-derdim-var-sair-hejaryan-j2gn2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok güzel bir derdim var

Seni seviyorum diye başlayan 

Bütün hüzünlerim

Sen ile gözlerin arasına sıkışmıştı

Gözlerini gördükçe

Sensizliğim geliyordu aklıma 

Aklım ise kaybolmuştu yollarda

Seni tanımak istiyordum ama

Beni kim tanıyacaktı

Sen beni yaşatıyordun

Belkide istemeden

Umut diyordun bir taraftan

Ama neyin umudu

Yinede teşekkürler 

Ağlamak için güzel bir derdim var artık





m.         s.', 'Çok güzel bir derdim var Seni seviyorum diye başlayan  Bütün hüzünlerim Sen ile gözlerin arasına sıkışmıştı Gözlerini gördükçe Sensizliğim g...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cok-guzel-bir-derdim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinin İçi', 'gozlerinin-i-ci-sair-hejaryan-k67vd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'GÖZLERİNİN İÇİ

Aşk kabristanında yerimi almalıyım

Şeytandan ateş    çalmalıyım

Belkide mecnun kadar cesur olmalıyım

Herşey herşeyden üstün olmalı

Belkide bir çocuk kadar

Masum olmalıyım

Hiç kimse kadar herşey olmalı

Her şey kadar hiç olmalıyım

Ne olursa olsun

Gözlerinin içinde olmalıyım

M.S.', 'GÖZLERİNİN İÇİ Aşk kabristanında yerimi almalıyım Şeytandan ateş    çalmalıyım Belkide mecnun kadar cesur olmalıyım Herşey herşeyden üstün o...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerinin-ici-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilbaz Sevişmeler', 'dilbaz-sevismeler-atilla-guler-y6pfj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yangınlara vurulmuş bedenlerin kızıl yalnızlığına ortak yıldızlar

duraksız nefes alışların duvarlara sinen kokusunda saklı

isterik bir sıradanlığın savrulan kahkahası

doygunluğuna bir kala bitmeyen doyumsuzluklar kapıda

buselik makamında inleyen sözlerden süzülen arzu

al yazmalara basılmış boncuklarda şehvet

zalim bir gece yarısı yarasına sıkılan bir kurşun daha

sakinliğin dilbaz duruluğu soyunmuş urbasını

şeffaf iç çekişlerin durdurulamaz baskısına vurulmuş duvarlar

veryansın eden yatakların dağınık dilleri

kıvırdıkça dökülür damlalar intihar eder ışıklar

raksına tutulan sevişmelerin ıssız sadeliği

sözcükler sessiz/sesler sözcüksüz

fırtınalar ateşten...daha gece bitmedi', 'yangınlara vurulmuş bedenlerin kızıl yalnızlığına ortak yıldızlar duraksız nefes alışların duvarlara sinen kokusunda saklı isterik bir sırad...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dilbaz-sevismeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Kelimesi Karşılamıyor Gözyaşlarımın Masraflarını', 'guzel-kelimesi-karsilamiyor-gozyaslarimin-masraflarini-sair-hejaryan-w37ap', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GÜZEL  KELİMESİ KARŞILAMIYOR GÖZYAŞLARIMIN

MASRAFLARINI

Gözlerinde yaşayan yaşantıma devam ediyordum

Devamsızlık yalanlarına dayanarak

Kalemle değilde gözyaşlarıyla dökülen acılarım karşısında

Karşılık beklemeden karşılacaktım

Gözlerinin tüm masraflarını

Rüzgarlarla paylaşacaktım belkide

Belkide beklentim olmayacaktı

Yaprak dökümlerinde

Seni unutmak için sunulan tüm geceler

YENEMİYORDU BENİ

Hep top çeviriyordum hayatta

Çünkü seviyordum  çevrilen   duyguları

Ancak o gözyaşlarım çizgiyi geçmiyordu bir kere

		Seviyordum kısa pasları

	 Ancak adamın birisi geliyordu bir uzun  topla        

	Geçiriyordu çizgiyi

Sonuçsa  hiç  değişmiyordu

Yani iyi oynamak yetmiyordu

Ve aşk iki kişilik bir masada yaşamıyordu

Sen ise hala dinliyordun

Ben ise hala kulübede bekliyordun

Ama seviyordum beklemeyi

Çünkü beklentilerim hala vardı

Hala bir  çocuk   kokusu   taşıyordum  üzerinde

Üzerime yıkılsada

O kocaman yalanlarımı seviyordum



M.s.', 'GÜZEL  KELİMESİ KARŞILAMIYOR GÖZYAŞLARIMIN MASRAFLARINI Gözlerinde yaşayan yaşantıma devam ediyordum Devamsızlık yalanlarına dayanarak Kalem...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/guzel-kelimesi-karsilamiyor-gozyaslarimin-masraflarini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayyama Hitaben', 'hayyama-hitaben-sair-hejaryan-x0z1y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'HAYYAMA HİTABEN

Birgün diyordu tarihteki o koca adam nizamülmülk

Hayyama

Sana sahih-i haberi verelim 

Yani milli istihbaratı

Hayyamın cevabı hazırdı

Ben insanların güzel taraflarını görüyorum

Ve bunun için seviyorum

Ve içiyorum

Nasıl insanların kusurlarını ortaya çıkarabilirim

Benimki de o mesele

Hep güzel taraflarını görüyorum güzelliklerinin

Sen ise görmüyorsun benim güzel TARAFLARIMI

	m.s.', 'HAYYAMA HİTABEN Birgün diyordu tarihteki o koca adam nizamülmülk Hayyama Sana sahih-i haberi verelim  Yani milli istihbaratı Hayyamın cevabı...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayyama-hitaben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hejar', 'hejar-sair-hejaryan-504pq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'HEJAR

Gözleri bu kadar güzel olmamalıydı

Düşüncelerimin eksensizliğinde

Kendimce yaratılmış yargılarda

Ne kadar masumdu masumiyet ezgisinde

Gözlerin

Ben sadece gözlerinin renksizliğini sevdim

Renklere inat

Hejarım benim

Sen beni sevmesen ne olur

Ben seni sevdim bir kere

Bir kere de sevdim seni

Sende seviyordun benim acılarımı

Toplandığında toplama bir aşk etmiyordu

toplumlarımız

seni seviyorum

hejarım

m.s.', 'HEJAR Gözleri bu kadar güzel olmamalıydı Düşüncelerimin eksensizliğinde Kendimce yaratılmış yargılarda Ne kadar masumdu masumiyet ezgisinde ...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hejar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her şeyde bir HAYIR var', 'her-seyde-bir-hayir-var-sair-hejaryan-ndn6j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'HER ŞEYDE BİR   HAYIR  VAR                            

Senin için duygulu rakılar içiyordum

İçin için şiirler yazıyordum

Sen ise kendi gölgenin karanlığında

Aramıyordum beni 

Belkide aramayı bilmiyordun 

Ne yazabiliyordun aşkın için

Ne gülebiliyordun masumiyet  sevgisinde 

Ne seviyordun rakının ana sonsuz halini

Sokaklar sinsice bakıyordu gözlerine

Duvarlar yaklaşıyordu kirpiklerinin arasına

Ancak sen göremiyordun bunları

Çünkü senin görmeye engel gözlerin vardı

Benim ise hala saklanmış gizlerim vardı

Nerede anlatsam yersiz kalan kalıntılar saklıyordum gözlerinde 

Ölümde arıyordum gözlerinin rengini 

Sıcak beyaz filmlere inat

Kelimeler birleştiğinde ayrılık türküleri söylüyordu 

Ve bu türküler  rakının son demi kadar tatlı değildi 

Ne yapalım önümüzdeki kızlara bakacağız

Belki de bir hayır vardı teklifimim içinde

Gözlerimin dışında



	M.S.', 'HER ŞEYDE BİR   HAYIR  VAR                             Senin için duygulu rakılar içiyordum İçin için şiirler yazıyordum Sen ise kendi gölge...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/her-seyde-bir-hayir-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzüne Veda', 'huzune-veda-sair-hejaryan-ww4vr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'HÜZÜNE VEDA

Artık gülmek için bir sebeb yoktu

Aranmayacaktı sözlerde anlam 	

Gözlerin mistik kokusu yalanlarda kayıp

Kendi kendine yaratılmış iklimlerin yaprak dökümü

Ve o bakışlar sadece bir renk

 İçi boşaltılmış 

 Artık sen yoksun gözlerinde 

 Artık bakacak bir yönüm yok ölmek içinde sebebim

 Yalnız sen değilsin hatalarımın küçük harfi

Ancak sen yalnız benden kaçmadım 

 Gözlerindende kaçtım

Unutulmuş acıların yeniden keşfiydi gözlerin

Gecenin unuttuğu çocuk ki kirasını ödemişti belki de

Karanlıklarının gülmeye inat ağlamaklarının gölgesinde

Sen ise eski şarkılarının yeni bunalımıydın 

ÖZGÜRLÜK şarkılarımda

Ve şarkılar ağır  gelmişti gözlerine

	Ne olursa olsun ben ve şarkılarım yalnız kalmıştı



	M.s.', 'HÜZÜNE VEDA Artık gülmek için bir sebeb yoktu Aranmayacaktı sözlerde anlam 	 Gözlerin mistik kokusu yalanlarda kayıp Kendi kendine yaratılmı...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/huzune-veda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü Gelişmeler', 'huzunlu-gelismeler-sair-hejaryan-wfy9k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'HÜZÜNLÜ GÜLÜŞMELER

Gözlerinin örttüğü beyaz düşlerim vardı

Karla kaplanmış ankara sokaklarında

Anlamsız bakışlarım vardı hecelerimde

            İçimde kahramanlarım olduğu duvar resimlerinde

            Resimlerde gülen kahramanların olduğu duvar resimlerinde	

Resimlerde gülen yüzler kanıyordu buz gibi suratlarda 

Gözlerim yaşıyordu umutsuz morglarda

Ama sen vardın prenses 

Belkide bir kere öpsen kalkacağım 

            RÜYALARDAN

Ancak sen beni öpme prenses

Bu masal devam etsin

	HÜZÜNLÜ GÜLÜŞLERDE

M.S.', 'HÜZÜNLÜ GÜLÜŞMELER Gözlerinin örttüğü beyaz düşlerim vardı Karla kaplanmış ankara sokaklarında Anlamsız bakışlarım vardı hecelerimde        ...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/huzunlu-gelismeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşılık Bekleyen Bir Şiir', 'karsilik-bekleyen-bir-siir-sair-hejaryan-mt9q0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KARŞILIK BEKLEYEN BİR ŞİİR

	Ne yazacağımı bilmiyordum

	Gözlerimin karşısında

	Çünkü hiç karşı değildim gözlerine

	Karşıdan karşıya geçerken önce sağa sonra sola

	En sonra ise gözlerine bakıyordum

	Hiçbir kural ağlatmıyordu beni 

	Gözlerin kadar

	Umutlar anlatıyordu hiç kimsenin anlatmadığı

	Gözlerinin karalığını

	Ve hiç düşünmemiştim

	Düşündürücü gözlerini

	Gözlerin yani yine gözlerin

	Yaşanmıyordu hiçbir şiirde

	Çünkü bunu ben keşfetmiştim

	Bütün keşifleri reddererek

	Belkide korkuyordum korkularımdan

	Ve korktukça güvenecek bir dal arıyordum

	Ve de soruyordum

	Tanrıya 

	Niye bütün enerjini harcadın bir güzel göze diye



	m.S.', 'KARŞILIK BEKLEYEN BİR ŞİİR 	Ne yazacağımı bilmiyordum 	Gözlerimin karşısında 	Çünkü hiç karşı değildim gözlerine 	Karşıdan karşıya geçerken ...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/karsilik-bekleyen-bir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Sever Tanrıyı', 'kim-sever-tanriyi-sair-hejaryan-5vom3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'KİM SEVER  TANRIYI

	

	Kim duyar rüzgarın sesini

	Fırtına olmadıkça 

	Kim ağlar ölümler için 

	Hayatlar solmadıkça

	Kim yaşar şarkıları 

	Anlamı kalmadıkça

	Kim söyler  gerçekleri

	Yalanlar bulmadıkça

	Kim sever tanrıyı

	CENNETTE KALMADIKÇA



	M.S.', 'KİM SEVER  TANRIYI 	 	Kim duyar rüzgarın sesini 	Fırtına olmadıkça  	Kim ağlar ölümler için  	Hayatlar solmadıkça 	Kim yaşar şarkıları  	Anl...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kim-sever-tanriyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milli Aşk', 'milli-ask-sair-hejaryan-tmlp7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'MİLLİ AŞK

Platonik aşklar yaşamıyordum

Platonu okumuyordum sokratı yargılamadan

Neyse o felsefe inanmıyordum

Senden sonra isadan önce

Değer miydi o kadar kan

O kadar gözyaşı

İnsanların bağrışmaları en büyük asker

Bizim asker diye kaplanan birkaç manifesto

Sonuçta annelerin gözyaşları

Neydi bu gurur nerede bu düşmanlar

O tanrının kıldan geçirilmiş

Kılıçtan bağımsız köprüsünde

Korkmuyorum artık ekmeğin bayatlamasından

Nerede o dağlar, taşlar

Nerede dik başlı, kısa boylu savaşlar

Milli tarih kitapları nerelerde

Milli coğrafyanın milli başkentleri bir mil etmiyordu

Milli hareket miydi bu harakiri

Neydi hareketin bereketi

Seviyorum kelimesini artık senle taşımasamda

Milli sevgilerim yaşanıyordu  vakanüvis arşivlerinde

Sen benden kalan bir zavallı

Ne o kadar güzel ne de anlamlı

Gözleri esrar kadar dumanlı

Hangi kitapta kaldıysan

O kadar zamanlı

Bir beklentisizlik bir çaresizlik  belirtisi

Milli podyumların gösterişsiz, bakışı yerden kalkmayan

Bir yerinde kalmıştın

Ne verdiysen o kadar almıştın

Alacakların duyacaklarının teminatıdır

Toplasam dediklerim ÇIKARTTIĞIM KİTAPLARIMDIR

	M.S.', 'MİLLİ AŞK Platonik aşklar yaşamıyordum Platonu okumuyordum sokratı yargılamadan Neyse o felsefe inanmıyordum Senden sonra isadan önce Değer ...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/milli-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedense', 'nedense-sair-hejaryan-f6mwy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'NEDENSE

Hep kaçıyordun benden 

Nedense

Ne yapmıştım ki ben

Birkaç şiir birkaç gözyaşı

Birkaç umut taşımak istedim gözlerine

Hep kaçıyordun benden

Nedense 

Kendimi hissediyordum

Kötü zamanlarda

Kırılacak yerim kalmamıştı

Beni özlemeni isterdim belkide

Hep kaçıyordun benden 

Nedense

Kaçacak yerlerin vardı belkide

Benimse kaçacak yerim kalmamıştı

Ne yapsam nereye baksam nereye kaçsam

Sen çıkıyordum karşıma

Önünden geçiyordun sadece

İlerliyordun uzaklara

Hep bekledim dönersin diye

Hep kaçıyordun benden 

Nedense

Yalnızlık tek başına yaşanmıyordu

Belki gülüyordum

Sen belkide gördüğüne inanıyordun

BEN İSE GÖREMEDİKLERİME

Ve göremedikçe özlüyordum seni

	NE YAPIYIM

	M.           S.', 'NEDENSE Hep kaçıyordun benden  Nedense Ne yapmıştım ki ben Birkaç şiir birkaç gözyaşı Birkaç umut taşımak istedim gözlerine Hep kaçıyordun b...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/nedense-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmalı', 'olmali-sair-hejaryan-unt7c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'OLMALI            

                 Kıblesi olmayan bir aşkın

                 En güzel yönüydün sen

	Gecelerin kavuşulmaz güzelliğinde

	Açılmayan düşüncelerin açmazında

	Belki de bir kelebek kadar 

	Kısa olmalıdır aşk

	Ancak onun kadar da renkli

	Ancak gözleri kara olmalı

	İçinde bir ışık olmalı

	Yalnızca güzellikleri gösteren

M.S.', 'OLMALI                              Kıblesi olmayan bir aşkın                  En güzel yönüydün sen 	Gecelerin kavuşulmaz güzelliğinde 	Açı...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olmali-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen benim tek dilegimsin', 'sen-benim-tek-dilegimsin-husamettin-guven-5nc2c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'canim ve cigerimsin

goren iki gozumsun

yuruyen dizlerimsin

sen benim tek dilegimsin

asik oldum ben sana

ariyorum yana yana

hasretim inan  sana

sen benim tek dilegimsin

o simsiyah gozler ile

tatli sicak sozler ile

manken gibi fiziginle 

sen benim tek dilegimsin', 'canim ve cigerimsin goren iki gozumsun yuruyen dizlerimsin sen benim tek dilegimsin asik oldum ben sana ariyorum yana yana hasretim inan  sa...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-benim-tek-dilegimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-sair-hejaryan-vufy0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ÖYLESİNE

Tanrının anlamı büyüktür

Gözlerinde

Anlamı küçüktür sevdanın

Aşkımın gölgesinde

Kalkıyordum rüyalardan

Uykuların GİZLERİNDE

Ve kalkıyorum gözlerinden

Utanıyorum kendimden

Derken de özlüyorum

GÖZLERİNİ

Ancak

GÖZ GÖZÜ

GÖRMÜYOR

M.S.', 'ÖYLESİNE Tanrının anlamı büyüktür Gözlerinde Anlamı küçüktür sevdanın Aşkımın gölgesinde Kalkıyordum rüyalardan Uykuların GİZLERİNDE Ve kalk...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oylesine-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka İnanmazdım', 'aska-i-nanmazdim-orhan-tuncay-9vdvs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sürüdüm ayaklarımı koridor karanlıklarında

Sağ yanımda sensizliğin sessizliğini duyarken

Son bir hamle uzandı üzerimdeki anahtara

Açmak için  odamın kilidini elimi yalnızlığa astım.

Bomboş odalarda dolaştım gölgeler peşinde

Yutkundum hıçkırıklarımı boğazımdan yükselen

Dönüp durdum girdaplarında sensizliğimin

Boş çerçevedeki resmini bağrıma bastım.

Sel olup kanadılar içimdeki göz yaşlarım

Ben böyle miydim, bu muydu benim  aslım? 

Aşk denilen sevda ölçüye gelmez derlerdi de

Güler geçerdim ben aşka hiç inanamazdım.', 'Sürüdüm ayaklarımı koridor karanlıklarında Sağ yanımda sensizliğin sessizliğini duyarken Son bir hamle uzandı üzerimdeki anahtara Açmak için...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aska-inanmazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine 2', 'oylesine-2-sair-hejaryan-4o0ka', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ÖYLESİNE 2                 

Yaşamak anlamsızdı

Ağlamak yetmiyordu artık 

Ben şiirler yazıyordum

Sen sadece okuyordun

Ve bakmıyordun gözlerime

Seni anlamak kendimi kaybetmekti

Gözlerin üzerine yazılmış tüm şiirler

GÖZLERİME ULAŞMIYORDU

Hala gözlerinde hapistim 

Cezası özel sebeblerde gizli

Hala bir çocuktum gözlerinde

Büyümeyi önemsemiyordum

Derdimi dökecek yerim kalmamıştı

Artık  şiirlerde anlamıyordu beni



	M.             S.', 'ÖYLESİNE 2                  Yaşamak anlamsızdı Ağlamak yetmiyordu artık  Ben şiirler yazıyordum Sen sadece okuyordun Ve bakmıyordun gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oylesine-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine 3', 'oylesine-3-sair-hejaryan-ez7le', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ÖYLESİNE 3

Sevmek nedir ki

       Eski bir kelime  

Şarkılar görünüyor yalnızlık çizgisinde

Bu kez ağlamak yasak

Anayasa maddelerinde

Gülmek yasak gözyaşı bilgisinde

Ne yapsak beraberce tek başına yasak

Seni sevmek yasak

Tanrının sevgisinde

Seni yazmak yasak

Duvarların gölgesinde

İsmin neyse bilmiyorum seni

Seni büyütmek yasak

       Küçücük yüreğimde

Sana yaklaşmak yasak

Türkiye cumhuriyetininde

Ölmek yasak tanrının ilacıyla

       Neyse ki bu esaret eski bir film adı

Filmler birkaç cümlede asılı kaldı

Artık şiirlerim özgür kaldı

Ancak bu biraz zaman aldı

Neyse ki bu esaret bir film adı

O günler mazide asılı kaldı

Tanrı ne sana inandı ne de bana 

Şiirlerim tanrıya verilen son ibadet 

Neyse ki bu esaret eski bir film adı

	

	m.s.', 'ÖYLESİNE 3 Sevmek nedir ki        Eski bir kelime   Şarkılar görünüyor yalnızlık çizgisinde Bu kez ağlamak yasak Anayasa maddelerinde Gülmek...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/oylesine-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine 4', 'oylesine-4-sair-hejaryan-wkmbd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÖYLESİNE 4

Sen ile sensizliğim arasına sıkışmış

Tüm senli cümleler senden bana armağandı

Bu kadar  senli  cümle ben den bağımsızlık taşıyordu

Hedefim ayrılmak değildi bu cümlelerden

En azından usulca yanaşmak gözlerinin tanrısal gizemine

Ateşe düşüyordum sen bakıyordun sadece

Sadece izliyordun şeytansal iklimlerde olan biten ne varsa

Ne varsa benden kalma umudu olan

Dönecektin çocukluğuna bir ölümsel bir zaman boşluğunda

Ve tek başına kalacaktın gözlerinin yalnızlığında

Belki de anlayacaktın bir çocuğun gözyaşlarının yalnızlığını

m.s.', 'ÖYLESİNE 4 Sen ile sensizliğim arasına sıkışmış Tüm senli cümleler senden bana armağandı Bu kadar  senli  cümle ben den bağımsızlık taşıyord...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/oylesine-4-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine 5', 'oylesine-5-sair-hejaryan-u97zf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ÖYLESİNE 5

Çocuksu bir bakış,korkarak, üzülerek  ve de  anlatamayarak

Ne seni taşıyordum, ne de kendimi

Bir harita görüyordum düşlerimde, düştükçe boğuluyordum kimsenin hissettiğimi karasal iklimlerde                          

Gülüyordum, ve de geçiyordum sabahlara

Kimsenin dinlemedi sabah ezanlarımı bende dinlemiyordum

Çünkü anlamıyordum artık seslerin gizemini

Bir tarafa bırakıyordum,kendimi, tarafsız kalıyordum senin karşısında

Sen aranıyordu, sensiz sabahlarda

Ilık ılık üşüyordum, nedenini bilmiyordun

Artık vazgeçmiştim kendi yalanlarımdan

Artık sevecek yerim kalmamıştı, senin ise görecek gözlerin taşınmıştı

Kişiselleştirmiyordum seni,çünkü sen kişi değildin zaten

Bir kişi kadar anlamın yoktu

Çünkü bir kişiye dökülen gözyaşı kadar yoktun sen

Şiirlerde geçiyordun sen

Usulca gözlerimden

Eski anı olmuştunsa 

Ah bir bilsen,ama neyi

Ah bir anlatsam, sevmiştim bir aralar

Ancak neyi,kimi

Ah bir  bilsen



	m.s', 'ÖYLESİNE 5 Çocuksu bir bakış,korkarak, üzülerek  ve de  anlatamayarak Ne seni taşıyordum, ne de kendimi Bir harita görüyordum düşlerimde, dü...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/oylesine-5-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Kalan', 'senden-kalan-sair-hejaryan-bycnc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SENDEN KALA N

Anadoluda bir çocuk yaşardı

Ne o ne de zaman onu anlardı

Hayat denen esprinin hüzünlü tarafıydım

Gecenin güneşi gören son hecesiydim

Kimsesizliğim kimliğiydi belkide

Gözlerde aranan anlam

Aptalca yaşanan masumiyet

Ne sen ne de sensizlik

Motifti yolculukların molasında

Düşlerden düşüyordum

Canım yanıyordu tenime inat

Bu hayat böyle mi olur

Düşen gözlerimin nemiydi

Ancak şiirlerimgözlerimin kiniydi       m.s.', 'SENDEN KALA N Anadoluda bir çocuk yaşardı Ne o ne de zaman onu anlardı Hayat denen esprinin hüzünlü tarafıydım Gecenin güneşi gören son hece...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/senden-kalan-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşif', 'kesif-mustafa-caliskan-manisa-hh7wy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Keşif etsende tüm evreni, fezayı

Kaldıramazsın ahirete ait cezayı', 'Keşif etsende tüm evreni, fezayı Kaldıramazsın ahirete ait cezayı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan Manisa']::text[], 8.5, '{"poet":"Mustafa Çalışkan Manisa","poet_slug":"mustafa-caliskan-manisa","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kesif-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum Şimdi', 'gidiyorum-simdi-ayse-kok-llf4b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidiyorum yarıda bırakarak

Bu pembe romanı

Biliyorsun romanlarda hiç

Mutlu sonlar olmadı

Hep şarkılara yüklesek de

Biz bu sevdayı

Aslında şarkıların

Bizi anlattığı falan yoktu

Bütün yaşananlar

Sanki suda yazıydı

Bir tabloydu yaptığımız

Yere düştü kırıldı

Bir resimdi çizdiğimiz

Boyaları silindi

Gidiyorum şimdi

Bu yolculuk bitti

Herşey yalandı belki

Gerçekler rahatsızlık verdi

Yarınlar bize ihanet etti

Sevmek bile yetmedi

Artık ayrılık vakti

Bak gözlerimde yağmurlar birikti

İstemem veda busesi

Git yabancı gibi', 'Gidiyorum yarıda bırakarak Bu pembe romanı Biliyorsun romanlarda hiç Mutlu sonlar olmadı Hep şarkılara yüklesek de Biz bu sevdayı Aslında şa...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Kök']::text[], 8.5, '{"poet":"Ayşe Kök","poet_slug":"ayse-kok","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gidiyorum-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Kalan Sensizlik', 'senden-kalan-sensizlik-sair-hejaryan-s8hn9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SENDEN KALAN SENSİZLİK

Sen benden kalan son güzellik

Sakarya caddesinin son şarkısı

İsyan ölümden kalan son an

Gözlerini düşündükçe

Acılarım geliyor aklıma

Peşin peşin yaşanmış duyguların

Taksit taksit intikamları

Geceler bitmeyen intikamın karanlık yönü

Acılarım üstünde

Din tanrının son cezası

İman sende kaybettiğim bensizlik

Neler yaşanmadıysada yaşattım seni

Şeytanınım gölgesinde

Yinede kendimi buldum senle

Karanlığın ensesinde

Düşlerimin oyuncağı olmuştun

Oyunsuz çocukluğumda

M.S.', 'SENDEN KALAN SENSİZLİK Sen benden kalan son güzellik Sakarya caddesinin son şarkısı İsyan ölümden kalan son an Gözlerini düşündükçe Acılarım...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/senden-kalan-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sana Yazmak', 'seni-sana-yazmak-sair-hejaryan-8ch8p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SENİ SANA YAZMAK

Ayrılık türküleri demleniyordu sensiz çay bardaklarında

Geceler kaçıyordu karanlıktan

Gözlerin taşınıyordu şiirlerimden usulca

Seni sana yazmak yasaklanıyordu 

Gözlerinin mühürsel açmazlarında

Sana ne kadar yaklaşsam uzaklaşıyordum Çocukluğumdan

Seni uzaktan seviyordum yakınlaştıkça korkuyordum

Şeytancıl gözlerinden

Seni sana yazmak yasaklanıyordu

Aranıyordu bir aşkın sanığı

Tanıklar bekleniyordu hala

Hala kapılar açılmıyordu

Gelmiyordun hala şiirsel acılarıma

Seni sana yazmak yasaklanıyordu

Yüreğimim arasına sıkışmış bir çift göz kalmıştı

Onlarda görünmüyordu gözlerinin tek başına kalmış 

GÜZELLİĞİNDE

	M.S.', 'SENİ SANA YAZMAK Ayrılık türküleri demleniyordu sensiz çay bardaklarında Geceler kaçıyordu karanlıktan Gözlerin taşınıyordu şiirlerimden usu...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-sana-yazmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şark', 'sark-sair-hejaryan-nq188', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ŞARK 

Gözlerin sadece bir kelimeydi

                Anlamsız sözlerinde

	Rüzgarlar anlatılmaz gecelerin havaya	

	Kattığı fısıltı

	Düşüncelerim gözyaşlarımdan dökülen 

	Anlamsız şiirler

              Ve aşklar benden sana yetişen son otobüs

                 Kimselerin olmadığı kimselerde  		

	        Olmak da var

	Kimsesizliğin kimliğinde 

                       Kalmak da var	

	  Sonuçta 

	Ne sen ne de ben ne de rüzgar sesleniyorduk

	        hayata

	sadece sözleri olmayan bir şarkının

	ŞARK tarafıydık ikimiz

	Aşkımız küllenmiyordu şarkılardaki

	Gibi

	Gecemiz ışıktan mahrumdu belki

	Belki de şeytandık biz ateşimizi   almaya

                                            Gelmiştik tanrıdan

	Bizde tanrı gibi   toplandığında 

                                                              Bir etmeliyiz

                            Ancak her şeye rağmen affetmeliyiz şeytanımızı

	M.S.', 'ŞARK  Gözlerin sadece bir kelimeydi                 Anlamsız sözlerinde 	Rüzgarlar anlatılmaz gecelerin havaya	 	Kattığı fısıltı 	Düşünceler...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sark-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrının Gözleri', 'tanrinin-gozleri-sair-hejaryan-wxi7d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanrının gözleri

Gözlerin ötesini düşündüm

kararsızca

aşkımın ötesine güldüm

Yararsızca

Ölümle yaşadım sensiz

yaşarcasına

Gözlerine inandım tanrıdan

kaçarcasına

M.S.', 'Tanrının gözleri Gözlerin ötesini düşündüm kararsızca aşkımın ötesine güldüm Yararsızca Ölümle yaşadım sensiz yaşarcasına Gözlerine inandım ...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tanrinin-gozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Üzerine', 'umut-uzerine-sair-hejaryan-0l9h4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'UMUT ÜZERİNE

Gözlerin umuttan bir iklim taşıyordu

Kar kadar beyazdı umutlarım

Hayallerim ise kar gibi eriyordu

Senle düşlenen gecelerim su gibi akıyordu

Ve de tutamıyordum gözyaşlarımı

Seni bekliyordum ders çıkışlarında

Sen ise benim gitmemi

Gideceğim ama nereye

Gözlerimin kanayan bölgeleri defoluyor

Gözlerinin karşısında

Ve de merak ediyordum seni

 Senin için gülüyordum

 Ve de kazanmak istiyordum bu kez

  Kırgın kalbini

 Senin en çok neyini seviyorum biliyor musun 

                          SAFLIĞINI

	M.             S.', 'UMUT ÜZERİNE Gözlerin umuttan bir iklim taşıyordu Kar kadar beyazdı umutlarım Hayallerim ise kar gibi eriyordu Senle düşlenen gecelerim su g...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/umut-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzerimde hüzün var fazla yaklaşMAYIN', 'uzerimde-huzun-var-fazla-yaklasmayin-sair-hejaryan-vk4c3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üzerimde hüzün var fazla yaklaşMAYIN

Senle başlayan bütün sensizliklerim

Gözlerinde başlayan

Yani sonuçta

Gözlerinde biten

Hüzünlerim vardı

Yokluk zamanlarımda

Hiçbir şey benzemiyordu sana

Ve üzerinde bir anlam vardı

	    Ben bile utanıyordum gözlerinden

Ahlaksız zamanlarımda

Seni seviyordum

Tanrıdan utanarak

Belki yüzüm kızarmıyordu ama

Yüzsüzlükte taşımıyordu

Taşınmaz duygularımda

Seni sevmek belkide biçare kalmaktı

En azından seviyordum

Gözlerinde mola vermeyi

Ve hiç istemiyordum

Bu molanın bitmesine

Sen üç harf

Ben üç harf

Şiirler ise harften bağımsız

Ben ise bağımlılık taşıyan

Bir aç GÖZLÜLÜK

M.S.', 'Üzerimde hüzün var fazla yaklaşMAYIN Senle başlayan bütün sensizliklerim Gözlerinde başlayan Yani sonuçta Gözlerinde biten Hüzünlerim vardı ...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/uzerimde-huzun-var-fazla-yaklasmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-mehmet-ali-kepez-v74dq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlem beter bir derd''imiş

		Canı  tüketir  yerimiş

		Bütün yolcular yürümüş

		Ben burada bekliyorum

		Bağımıza hàzan düştü

		Geldi  başa bu ne işti

		Nice mevsimler  deyişti

		Yagmur,karda bekliyorum

		Hasret ictim yudum yudum

		Buhara döndüm suyudum

		Gelirsin diye umudum

		Hàlen varda  bekliyorum

		Bunca  acılar görmüşüm

		Sen oldun hayàlim,düşüm

		Kara  toprağa girmişim

		Gel mezarda bekliyorum', 'Özlem beter bir derd''imiş 		Canı  tüketir  yerimiş 		Bütün yolcular yürümüş 		Ben burada bekliyorum 		Bağımıza hàzan düştü 		Geldi  başa bu ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekliyorum-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeş', 'kardes-nurullah-yildiz-14jki', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir deli sevdaya düştüm ki sorma

O yar beni derbeder etti kardaş

Yüreğümde açtı büyük bir yara

Halimi perişan eyledi kardaş

Kardaş bana yardım eyle

Dertliyim ben derman eyle

Seviyorum bir şey söyle

Beni yalnız bırakma kardaş

Yarin hasretinden yollara düştüm

Gurbet ellerde gülüm sensiz kaldım

Tek suçum sevmekmiş ama ben sevdim

Şimdi ben neylerim söyle be kardaş

Kardaş bana yardım eyle

Dertliyim ben derman eyle

Seviyorum bir şey söyle

Beni yalnız bırakma kardaş', 'Bir deli sevdaya düştüm ki sorma O yar beni derbeder etti kardaş Yüreğümde açtı büyük bir yara Halimi perişan eyledi kardaş Kardaş bana yard...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Yıldız']::text[], 8.5, '{"poet":"Nurullah Yıldız","poet_slug":"nurullah-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kardes-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun Diye', 'sen-yoksun-diye-nurullah-yildiz-2gz70', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yatağım buz gibi üşüyorum yine

Çaresiz ağlıyorum sen yoksun diye

Kimlere diyeyim derdimi kime

Yokluğun ecelim olmuş 

Sen yoksun diye

Uykularım kaçıyor uyuyamıyorum

Rüyaların tadı yok sen yoksun diye

Kimlere diyeyim derdimi kime

Yokluğun ecelim olmuş 

Sen yoksun diye

Aldım sazımı duvara astım

Rüyaların tadı yok sen yoksun diye

Kimlere diyeyim derdimi kime

Yokluğun ecelim olmuş 

Sen yoksun diye', 'Yatağım buz gibi üşüyorum yine Çaresiz ağlıyorum sen yoksun diye Kimlere diyeyim derdimi kime Yokluğun ecelim olmuş  Sen yoksun diye Uykular...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Yıldız']::text[], 8.5, '{"poet":"Nurullah Yıldız","poet_slug":"nurullah-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-yoksun-diye-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim Sana', 'hasretim-sana-nurullah-yildiz-8f433', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlüyorun seni 

Seni bekliyorum yar

Dayanacak takatim yok 

Geleceksen gel

Ela gözlerine bakıp 

Ağlayacağım

Nazlı yarim dön gel artık HASRETİM SANA

Uykularım harap oldu 

Gözlerimde kan

Sabret gönlüm bitti 

Dayan yüreğim dayan

Sevdamıza dağler bile 

Dayanmıyordu

Nazar değdi aşkımıza 

Bebeğim inan

İnan bebeğim inan

Dayan yüreğim dayan

Dost ile sohbeti kestim 

Küstüm sazıma

Sensiz geçen her dakika 

Gider ağrıma

Dayanacak gücüm sabrım 

Kalmadı artık

Karalar bağlayıp 

Taş basayım bağrıma

Uykularım harap oldu 

Gözlerimde kan

Sabret gönlüm bitti 

Dayan yüreğim dayan

Sevdamıza dağler bile 

Dayanmıyordu

Nazar değdi aşkımıza 

Bebeğim inan

İnan bebeğim inan

Dayan yüreğim dayan', 'Özlüyorun seni  Seni bekliyorum yar Dayanacak takatim yok  Geleceksen gel Ela gözlerine bakıp  Ağlayacağım Nazlı yarim dön gel artık HASRETİ...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Yıldız']::text[], 8.5, '{"poet":"Nurullah Yıldız","poet_slug":"nurullah-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hasretim-sana-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm Yar', 'gulum-yar-nurullah-yildiz-riod2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlama sana kıyamam

Göz yaşına dayanamam yar

Sen gizli aşkım gözbebeğimsin

Sende olmasan ne yaparım yar

Gülüm yar canım yar

Bütün sevdam sana yar

Aşkımsın sen benim

Kalbimdeki yaram yar', 'Ağlama sana kıyamam Göz yaşına dayanamam yar Sen gizli aşkım gözbebeğimsin Sende olmasan ne yaparım yar Gülüm yar canım yar Bütün sevdam san...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Yıldız']::text[], 8.5, '{"poet":"Nurullah Yıldız","poet_slug":"nurullah-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gulum-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Bir Yarısın', 'gecenin-bir-yarisin-nurullah-yildiz-284sq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine gecenin bir yarısında

Yatağıma uzanıp düşündüm seni

Yarım kalan cigaramın dumanında

Hayal meyal seyrettim seni

Yine daldım albümlerin arasına

Seninle çekildiğimiz o resmi aradım

Geçtim kırık dökük aynanı karşısına

Dağılmış kıvırcık saçlarımı taradım

İlk tanıştığımız sevda parkına gittim

Oturduğumuz masada düşündüm seni

Kemancıya bizim şarkımızı çaldırdım

Hayallere dalıpta seyrettim seni

Yine daldım albümlerin arasına

Seninle çekildiğimiz o resmi aradım

Geçtim kırık dökük aynanın karşısına

Dağılmış kıvırcık saçlarımı taradım', 'Yine gecenin bir yarısında Yatağıma uzanıp düşündüm seni Yarım kalan cigaramın dumanında Hayal meyal seyrettim seni Yine daldım albümlerin a...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Yıldız']::text[], 8.5, '{"poet":"Nurullah Yıldız","poet_slug":"nurullah-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecenin-bir-yarisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-nurullah-yildiz-hj2ne', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yollar uzun yollara çıkamıyorum

Çok özledim seni ama gelemiyorum

Kaderimdir ne yapayım geçer diyorum

Bu iş böyle gitmez böyle yürümez dostum

Bir gün gelir buda geçer acılar biter

Umudunu yitirme herşey yoluna girer

Çektiğin acılar dertler yel olur gider

Sabrın sonu selamettir sen sabret dostum

Yaralı yüreğin birini sever

Sevda denizinde yüzersin dostum

Çektiğin acılar dertler yel olur gider

Sabrın sonu selamettir sen sabret dostum', 'Yollar uzun yollara çıkamıyorum Çok özledim seni ama gelemiyorum Kaderimdir ne yapayım geçer diyorum Bu iş böyle gitmez böyle yürümez dostum...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Yıldız']::text[], 8.5, '{"poet":"Nurullah Yıldız","poet_slug":"nurullah-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dostum-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eminem', 'eminem-nurullah-yildiz-ik1ea', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağlar başı duman olur EMİNEM

Kara sevda yaman olur EMİNEM

Ayrılık ateşi kavurur derler

Adamı küle çevirir EMİNEM

Oy EMİNEM yar EMİNEM

Dağlar başı duman olur EMİNEM

Kara sevda yaman olur EMİNEM

Ayrılık ateşi kavurur derler

Adamı küle çevirir EMİNEM

Oy EMİNEM yar EMİNEM

Dağlar başı duman duman oy

Zülüfleri tel tel olmuş

Boynundan aşağı inen oy

Seni sevdim gönül verdim EMİNEM

Yollarına güller derdim EMİNEM

Yar sen bana birkez olsun gülmedin

Ölürmüydün bana gülsen EMİNEM 

Oy EMİNEM yar EMİNEM

Dağlar başı duman duman oy

Zülüfleri tel tel olmuş

Boynundan aşağı inen oy', 'Dağlar başı duman olur EMİNEM Kara sevda yaman olur EMİNEM Ayrılık ateşi kavurur derler Adamı küle çevirir EMİNEM Oy EMİNEM yar EMİNEM Dağla...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Yıldız']::text[], 8.5, '{"poet":"Nurullah Yıldız","poet_slug":"nurullah-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/eminem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zafer çığlığı', 'zafer-cigligi-nevzat-ozkan-exf9o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sabahın sessiz alacakaranlığı,

sahil ve deniz

gece yosunları ile dolu

dalgaların ansızın getirdiği.

sabahçı kargalar

telaşla gagalıyor sağı solu.

moral bozuyor

martı çığlıklarına karışan

sabah salası.

Çakırlarda

erken bir yaz sabahı,

burunlarda özlenen yosun kokusu.

saldırgan kargaların

kimseden yok korkusu.

yosunlar arasında

uzanmış yatıyor,

karadenize doyamamış

garip bir istavrit kılçığı.

ve tüm sahili kaplıyor

zalim karganın

ürkütücü zafer çığlığı..', 'sabahın sessiz alacakaranlığı, sahil ve deniz gece yosunları ile dolu dalgaların ansızın getirdiği. sabahçı kargalar telaşla gagalıyor sağı ...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zafer-cigligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PeyğamBerim', 'peygamberim-hasan-tosun-2-x3y43', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ararım   miskin   kokusunu

hissederim  dokusunu

benim  serim  yokuşunu

peygamberimi  özlerim

allah  çıkardı  onu  karşımıza

hayırlı   etti  hakkımıza

sensizlik   bize  ceza

peygamberimi  özlerim

yaşla  dolar  gözlerim

mendil  ile   silerim

anımsadıkça  gülerim

peygamberimi   özlerim

muhammet  aşkına

onsuzluk  çevirir  şaşkına

kur; anı  oku  kana  kana

peygamberimi  özlerim', 'ararım   miskin   kokusunu hissederim  dokusunu benim  serim  yokuşunu peygamberimi  özlerim allah  çıkardı  onu  karşımıza hayırlı   etti  ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Tosun 2']::text[], 8.5, '{"poet":"Hasan Tosun 2","poet_slug":"hasan-tosun-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/peygamberim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '& - Turkuvaz Düşlerdeki Bebek - &', 'turkuvaz-duslerdeki-bebek-gulsen-senderin-z2cwx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Annenin gözleri turkuvaz, tutkuları turkuvaz 

Babanın yeşillere inat,  bakışları turkuvaz

Şansız doğan  tek evlat,  mağrur hayalleri turkuvaz.

Üç çift göz turkuvaz, düşlerdeki BEBEK  turkuvaz..

Acılar örmüş ağını, tek yavruları maluldü.

Üzülür diye kardeş de yapmadılar, tek oğuldu.

Hayatın anlamı yavruları, umutları  güldü.

Üç çift göz turkuvaz, düşlerdeki BEBEK turkuvaz..

Umutların katmer katmer, açtırdığı bahçelerden

Yüreklerindeki simsiyah karanlık gecelerden

Şafaklar atıp yaşanacaktı mutluluk hecelerden

Üç çift göz turkuvaz, düşlerdeki BEBEK turkuvaz..

Yaşam mücadelesi, hayata kazandırma gücü

Gönülde  umudun  harı, anne babanın bilinci

Şansı sonunda kucakladı, şair olan bu genci

Üç çift göz turkuvaz, düşlerdeki BEBEK turkuvaz.

Kıbrıs’ın güneyinde, Dağaşan’dan bir yaban gülü

Aşık edecekti kendine, Bakırköylü bülbülü

Ve vuslat kuşatacaktı, beyaz gelinliği tülü 

Üç çift göz turkuvaz, düşlerdeki BEBEK turkuvaz.

Sevgi yağmurları bembeyaz bulutlar gibi  yağdı

Umut bağında  zambaklar  açtı,  Musa Korkut doğdu

Turkuvaz düşleri ve utkuları  sevince boğdu

Üç çift göz turkuvaz, düşlerdeki BEBEK turkuvaz.

Turkuvaz Bebek''ten müjde; torunumuz “ Arif Cumhur “

Aman nazar değmesin! Buhurdanlıkta tütsün buhur

Efsaneler gibi bir aşk masalı, aşkı saran nur.

Üç çift göz turkuvaz, düşlerdeki BEBEK turkuvaz..

Gülşen der ki mutluluk acıların zamkından akar

Ve bu  reçineyle birleşen güzelliklerde  yatar

Bir masmavi ummandan bilinen o sona kadar.

Üç çift göz turkuvaz, düşlerdeki BEBEK turkuvaz.', 'Annenin gözleri turkuvaz, tutkuları turkuvaz  Babanın yeşillere inat,  bakışları turkuvaz Şansız doğan  tek evlat,  mağrur hayalleri turkuva...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/turkuvaz-duslerdeki-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hor görme Hasanı', 'hor-gorme-hasani-hasan-tosun-2-w0i7f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahtındaki güller bir gün solar 

Şu yalan dünyaya kimler geldi de 

Kalmadı Leylalar mecnunlar 

Hor görme bu garip hasanı 

Güzellik bir çiçektir açar solar 

Öyle bir zaman gelir ki kurur dallar 

Sana hazmedemez yıllar 

Hor görme bu garip hasanı 

İnsanı yer bitirir gurur ile kibir 

Yaş ilerledikçe yüzüne çizgiler gelir 

İnsan toprak misali erir 

Hor görme bu garip hasanı 

Hasan dediğin bir garip aşık 

Dünyaya küs hayata barışık 

Şu yalan dünyada çile çekmeye alışık 

Güzeli seven şiirine aşık', 'Bahtındaki güller bir gün solar  Şu yalan dünyaya kimler geldi de  Kalmadı Leylalar mecnunlar  Hor görme bu garip hasanı  Güzellik bir çiçek...', ARRAY['Türk Edebiyatı','Şiir','Hasan Tosun 2']::text[], 8.5, '{"poet":"Hasan Tosun 2","poet_slug":"hasan-tosun-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hor-gorme-hasani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz: Rüzgar Müzik: Yağmur', 'soz-ruzgar-muzik-yagmur-hasan-can-lvjoh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yitirilmiş bir sevdanın ardında,

Kederli bir yüz ifadesi,

Ve acılı bir yürek kalır...

Artık hayatını yenilemeye çalışır kişi,

Eskileri tamamen silmek ister beyninden,

Evdeki eşyaları değiştirir,

Resimler mektuplar birer birer yakılır.

Sonra gece olur, rüzgar bir yandan,

Yağmur bir yandan kurcalar aklını,

Şarkılar gelir aklına birden,

Yağmur müzik olur,

Rüzgar söz eder,

İster istemez tutuşur diline sözler,

Birlikte söyletir yaktığını sandığın hatıralar.

Bitti dediysen ki acısı yerindeyse,

Sakın üsteleme, bırak kendi kendini alıştırsın yürek,

Sırası gelince bittiğini o söyleyecektir sana...', 'Yitirilmiş bir sevdanın ardında, Kederli bir yüz ifadesi, Ve acılı bir yürek kalır... Artık hayatını yenilemeye çalışır kişi, Eskileri tamam...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/soz-ruzgar-muzik-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesap Verilecek Hakka', 'hesap-verilecek-hakka-mehmet-dogan-8-dqkij', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elinde bakır helkesi

Ak topuğa vurmuş gıcırtısı

Maraş ilinde gezinir

Antepte duyduk biz bu sesi

Bu ne güzellik zalım kızı

Seyrana çıkmış Gavur dağının çukur ovanın berisi

Kim ona yan bakar

Neydi ondaki fiyaka

Yılanı ortadan biçer

Fadima ananın görüntüsü

Hemi valla hemi billa

Hesap verilecekse hakka

Yağmur yağdı yayla yazı ıslattı

Yazmasın al beyazı ıslattı

Mendilimin ne suçu var anam

Sen ağlarsın göz ıslattı...', 'Elinde bakır helkesi Ak topuğa vurmuş gıcırtısı Maraş ilinde gezinir Antepte duyduk biz bu sesi Bu ne güzellik zalım kızı Seyrana çıkmış Gav...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 8']::text[], 8.5, '{"poet":"Mehmet Doğan 8","poet_slug":"mehmet-dogan-8","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hesap-verilecek-hakka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru', 'soru-caglar-asik-u1dcp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dolmayan kaptan, su taşar mı? 

Akmayan çaydan, göl dolar mı? 

Gezmeyen arın, bal yapar mı? 

Olmayan meyvan, tat tutar mı? 

&

Sormayan dostun, ahh çeker mi? 

Çağlayan gözün, yaş siler mi? 

Çekmeyen derdin, hiç bilir mi? 

Dinmeyen kalbin, ohh eder mi? 

&

Bilmezsen dersin, off yeter mi? 

Yalnızsan ey can, dost biter mi? 

Arasan her an, Hak yetmez mi? 

Kavuşsan o an, dert yitmez mi? 

&

Talipsen eğer, Hak bilmez mi? 

Teslimsen eğer, kul demez mi? 

Dertliysen bilip, hep sarmaz mı? 

Garipsen görüp, hiç bakmaz mı? 

&

Selamın alıp, nur yaymaz mı? 

Sonsuzun bilip, dert savmaz mı? 

Işıktan gözün, kör olmaz mı? 

Aşıksan yüzün, pak olmaz mı? 

&

Güzelse sevgin, saf olmaz mı? 

Doluysa kalbin, kor yanmaz mı? 

Kavuşsa gönlün, ar etmez mi? 

İsterse ruhun, hiç gitmez mi? 

&

İstanbul – 18.01.2006

Çağlar Aşık – Soru', 'Dolmayan kaptan, su taşar mı?  Akmayan çaydan, göl dolar mı?  Gezmeyen arın, bal yapar mı?  Olmayan meyvan, tat tutar mı?  & Sormayan dostun...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/soru-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tufan', 'tufan-omer-faruk-demircan-seqmg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıkıldı En Büyük Mabedim Yüce Sesinden.

 Yazık Devrildi Gökler Yeryüzü Yerle Bir.

 Ağladı Yıldızlar, Hıçkırıklara Boğuldu Ay.

Yazık Karanlığa Boyandı En Aydınlık Ovan.

 Kara Bir Tufandın, Denizlerde Ayaklanan

 Yazık Alabora Oldu Tekneler, Bütün Adalar Tarumar,

Alevlendi Kıyısı Sahillerin

 Yazık Kül Oldu Anılar.

 Yitirdim Artık Hazzını Erişilmez çağlayanım,

 Ama Sanmaki Bitirdim Beynimdeki Krallığını

 Hala Karanlık Denizdeki O Aydınlık Kuraklığım.

Sanmaki Yaktım En Lüks Urbasını Aşkın

 Demirledim Dünyayı Da, Hala Hala Başdöngüçlerindeyim,

Yazık! Kurtuluşu Yok Artık, Anlamlı Arzunun,

 Kanadı Yarası Devleşen Ayrılık Karşısında Sevmenin Yazık! 

 Hep Kıyısında Büyüyeceğim Artık,

 Acılı Kenarların''da Mutluluğun', 'Yıkıldı En Büyük Mabedim Yüce Sesinden.  Yazık Devrildi Gökler Yeryüzü Yerle Bir.  Ağladı Yıldızlar, Hıçkırıklara Boğuldu Ay. Yazık Karanlığ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Demircan']::text[], 8.5, '{"poet":"Ömer Faruk Demircan","poet_slug":"omer-faruk-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tufan-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşama Dair Portreler I', 'yasama-dair-portreler-i-nihat-albayrak-ptya2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir şafak vakti, bir gün batımı,

Zaman ayarlı mevsimler,

Su gibi derin ve sessiz! ..

Ihlamur çiçeği kokulu bir kadınla,

Kumru sesleri arasında,

Kayan yıldızlarda dilekler tutmak! ..

Bir kadın teni yumuşaklığı,

Masalımsı akşamlarda uykusuz geceler,

Bir bebek gülümseyişi! ..

Suyun derinliği,

Ormanın sessizliği,

Gecenin karanlığı,

Kırk yaş sendromları,

Erdemsiz düşler! ..

Karabulutlar altında,

Çok uzaklara koşmak,

	Kendi yalnızlığını bulmak! ...

Yaşamak,

Dudaklarımda o bildik şarkılarla

Gecenin kızlarıyla dans etmek,

                        değil sadece,

Güneşin sıcaklığına,

Suyun buğusuna aldırmaksızın,

Bir gökkuşağını resmeder gibi,

Kendini gerçekleştirmek! ...

	

Sonra,

Sessiz bir vadide,

Sevda türkülerinin,

Sevinç çığlıklarının yankısını dinlemek! ...

Kocaali 18/01/2006', 'Bir şafak vakti, bir gün batımı, Zaman ayarlı mevsimler, Su gibi derin ve sessiz! .. Ihlamur çiçeği kokulu bir kadınla, Kumru sesleri arasın...', ARRAY['Türk Edebiyatı','Şiir','Nihat Albayrak']::text[], 8.5, '{"poet":"Nihat Albayrak","poet_slug":"nihat-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yasama-dair-portreler-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmeliyim', 'gitmeliyim-gulden-isik-9hbjd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni düşüncelerime hapsedip

Örtmeliyim üstünü

Anıların yorganıyla.

Ardından hiç el sallayanı olmayan

Sessiz bir gemi gibi

Yüreğimdekilerle beraber

Gitmeliyim bu limandan.

Bilmelisin ki

Korkularla sıvanıp

Boşluklara doldurulmak

Bana göre değil.

Bana göre değil

Özgürlüğe hasret

Uçurtmaları

Tam gökyüzündeyken vurmak.

Seni istediğin hayatın

İçine salıp

Kendini buluncaya dek

Kaybetmeliyim.

Beni anlayacağın güne kadar da

Ayaklarımı bu şehirden

Kesmeliyim.

1998', 'Seni düşüncelerime hapsedip Örtmeliyim üstünü Anıların yorganıyla. Ardından hiç el sallayanı olmayan Sessiz bir gemi gibi Yüreğimdekilerle b...', ARRAY['Türk Edebiyatı','Şiir','Gülden Işık']::text[], 8.5, '{"poet":"Gülden Işık","poet_slug":"gulden-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gitmeliyim-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük.13 [Bilmem ki....]', 'dortluk-13-bilmem-ki-ercan-akbay-1dvyi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilmem ki ne olur,bu aşkın sonu.

   Gider mi,döner mi,bu aşkın yolu.

   Sevenler bir kere,güler mi acep,

   Gider mi,döner mi,bu aşkın yolu...

                            18.1.2006 B.EVLER...İSTANBUL.', 'Bilmem ki ne olur,bu aşkın sonu.    Gider mi,döner mi,bu aşkın yolu.    Sevenler bir kere,güler mi acep,    Gider mi,döner mi,bu aşkın yolu....', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dortluk-13-bilmem-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şüphe', 'suphe-mustafa-caliskan-manisa-6t8v6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçin, için kemirir de kemirir

Kemirdikçe akıl yere serilir

Yerde akıl damarların gerilir

Sükun yok olur, çünkü sükun erir', 'İçin, için kemirir de kemirir Kemirdikçe akıl yere serilir Yerde akıl damarların gerilir Sükun yok olur, çünkü sükun erir...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan Manisa']::text[], 8.5, '{"poet":"Mustafa Çalışkan Manisa","poet_slug":"mustafa-caliskan-manisa","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/suphe-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-sair-utopia-8jxlb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ama hatirla biraz 

Ne kadar mutu idik 

Cocuklugun o el degmemis okyanusundaki 

Azgin dalgalarin arasinda bogusurken..

Simdi ise,içine gömüldügüm rahibin tahtinda

Gururun, kibirin ve riyakarligin istila ettigi gerçeklerden..

Geriye kalan harab olmus o Kralligin

Melankolisini yudumluyorum.

Beni,kömürden bir ekmek ve kandan bir sarap ile besliyen..

Annem, yanlizligim..

Mavi vitraylarin ardindaki dogayla bulusturuyor beni 

Ve ben,tipki bir yagmur damlasinin karistigi gibi okyanusa..

Birakiyorum kendimi çocukluguma..

Hüzünlü kalbimden akan bu serin, soguk suyu kirletme anne.

Gösterme bana gerçekleri..

Birak aksin boylu boyunca ,temiz olsun ki..

Bende karisabileyim sonsuzluga kollarinin arasinda..', 'Ama hatirla biraz  Ne kadar mutu idik  Cocuklugun o el degmemis okyanusundaki  Azgin dalgalarin arasinda bogusurken.. Simdi ise,içine gömüld...', ARRAY['Türk Edebiyatı','Şiir','Şair Utopia']::text[], 8.5, '{"poet":"Şair Utopia","poet_slug":"sair-utopia","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zaman-284-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
