INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Anam', 'garip-anam-hifzi-ozbekmez-21o7t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'GARİP ANAM

Bir gün bende bu ellerden gidersem

Ağlama göz yaşın sil garip anam

Derdim ile her gün figan edersem

Gönül firardadır bil garip anam

Derdim dağa döndü yıkılsın gayrı

Yeter nazlı yardan kaldığım ayrı

Sinem beter oldu kalmadı hayrı

Ateşim söndürmez sel garip anam

Kader şu yazgımı döndürsün artık

Yari küheylana bindirsin artık

Yanan ateşimi söndürsün artık

Seher vakti esen yel garip anam

Ağlaya ağlaya  gözlerim şişti

Dertler gönül bağım amansız biçti

Sanarlar latifin zehiri içti

Ciğerim dağladı el garip anam', 'GARİP ANAM Bir gün bende bu ellerden gidersem Ağlama göz yaşın sil garip anam Derdim ile her gün figan edersem Gönül firardadır bil garip an...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/garip-anam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyor', 'diyor-hifzi-ozbekmez-pgtj1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'DİYOR

Ne kadar çağırsam duyulmaz feryat

Demek aşka kıymet verilmez heyhat

Sendeki resmimi artık kaldır at

Yeter hayatından sil beni diyor

Vuslata kalmadı ne yazık umut

Mazide geçeni dilerim unut

Gönlünü kendince oyala unut

Artık bir yabancı bil beni diyor

Boşa hayal etme artık yüzümü

Talan olmuş gönül bağı üzümü

Sana bağlayamam artık özümü

İster dilim dilim dil beni diyor

Yeter ağladığım yeter çektiğim

Sevdanın yoluna hasret ektiğim

Ozanım dediğim latif  bildiğim 

Artık serinletmez nil beni diyor

09  EKİM  2005  SAAT: 03:00', 'DİYOR Ne kadar çağırsam duyulmaz feryat Demek aşka kıymet verilmez heyhat Sendeki resmimi artık kaldır at Yeter hayatından sil beni diyor Vu...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/diyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedim', 'dedim-hifzi-ozbekmez-bfdbw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'DEDİM

Yine sevdiğime bir haber saldım

Hasret ateşlerde kor beni dedim

Özlemin yüzünden ateşte yandım

Rüyanda hayıra yor beni dedim

Akıl başta değil gözüm selinden

Ölümü isterim aşkın elimden

Eğer sual ediyorsan halimden

Uçan kuşlara da sor beni dedim

Yeniden doğsam da severdim seni

Başımda taç diye överdim seni

Kimseye bırakmam namerdim seni

Senden ayırması zor beni dedim

Ey latifi son ver gözün yaşına

Akıl sır ermiyor gönül kuşuna

Yeter ağladığım burda boşuna

Bekletme gel artık sar beni dedim

09  EKİM  2005  SAAT: 02:00', 'DEDİM Yine sevdiğime bir haber saldım Hasret ateşlerde kor beni dedim Özlemin yüzünden ateşte yandım Rüyanda hayıra yor beni dedim Akıl başt...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dedim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Kalbinde Taşı-3', 'beni-kalbinde-tasi-3-sahin-erturk-os9cp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerinde sil yaşı

Kirletme,koru aşkı

Dilden düşmez bu şarkı

Beni kalbinde taşı

Kibir sokma araya

Sapla,saman ayıkla

Rüyalarda sayıkla

Beni kalbinde taşı

Kavuşmamız mahşerde

Kalbe şeytan girerse

Bozma sakın yemini

Beni kalbinde taşı

(20.01.2006)', 'Gözlerinde sil yaşı Kirletme,koru aşkı Dilden düşmez bu şarkı Beni kalbinde taşı Kibir sokma araya Sapla,saman ayıkla Rüyalarda sayıkla Beni...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beni-kalbinde-tasi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum', 'seni-dusunuyorum-mehmet-sait-akkus-pvyej', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığında yürüyorum

Her adım atışımda seni düşünüyorum

Hava çok soğuk öylesine üşüyorum ki

Dalıp gitmişim öylecesine

Seni düşünüyorum

Seni

Beraber ne sevdalar ekmiştik

Avuçlarımızla sulamıştık

Ele ele tutuşup sözleşmiştik

Ve unutma şunu söylemiştik

Ölünceye kadar

Ölünceye kadar

Bak yeşerdi ektiğimiz sevdalar

Yar senin için ne çok canlar

Ateşlere yandı akşamlar

Gelmez olunca sabahlar

Yanarım o zaman

Yanarım

Yanarım sana,seni görmesem

Seni seviyorum hergün demesem

Ellerini avuçlarıma alıp öpmesem

Ve senin için bu canı vermesem

Ne eyliyeyim bu bedeni

Ne eyliyeyim bu canı.', 'Gecenin karanlığında yürüyorum Her adım atışımda seni düşünüyorum Hava çok soğuk öylesine üşüyorum ki Dalıp gitmişim öylecesine Seni düşünüy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-dusunuyorum-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Gizli Ağlıyorsun', 'gizli-gizli-agliyorsun-yusuf-onder-bahceci-rn3hp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gizli gizli ağlıyorsun,

Neden, neden diyorsun,

Çok sevmişsin demiyorsun,

Ne vardı söyleseydin,

Seni sevdim deseydin,

Sana yandım deseydin,

Ne vardı söyleseydin,

Hep içine atıyorsun,

Günden güne soluyorsun,

Derdin çoktur biliyorsun,

Ne vardı söyleseydin,

Seni sevdim deseydin,

Sende sevdin deseydin,

Ne vardı söyleseydin....', 'Gizli gizli ağlıyorsun, Neden, neden diyorsun, Çok sevmişsin demiyorsun, Ne vardı söyleseydin, Seni sevdim deseydin, Sana yandım deseydin, N...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gizli-gizli-agliyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-salih-erdem-11ddb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'şiir nedir ki

bir duygu ve düşünce

………………sözdür ötesi

kararmışsam 

yağmur toplayan bulutlar gibi

…………………….önce dolmalıyım

taşkınlığım 

………..nasılsa sana ulaşacaktır

sende var olan güzelliklerin

bendeki ifadesi

			31.12.2004 Aydın', 'şiir nedir ki bir duygu ve düşünce ………………sözdür ötesi kararmışsam  yağmur toplayan bulutlar gibi …………………….önce dolmalıyım taşkınlığım  ……….....', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/siir-145-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sevmedim Diye', 'guzel-sevmedim-diye-yusuf-onder-bahceci-5c437', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum sözleri,

Acep sözlükte yokmudur,

Seni seven şu kalbime,

Bu cümleler çokmudur.

Eller ne derse desin,

Sen benim kalbimdesin,

Kimse bana demesin,

Güzel sevmedim diye.

Güzellerde olmaz karar,

Ayrılıkmış akla zarar,

İnsanlar kendine kızar,

Güzel sevmedim diye.

Şimdi nasıl ederim,

Söyle nere giderim,

Kendime t''an ederim,

Güzel sevmedim diye....', 'Seni seviyorum sözleri, Acep sözlükte yokmudur, Seni seven şu kalbime, Bu cümleler çokmudur. Eller ne derse desin, Sen benim kalbimdesin, Ki...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guzel-sevmedim-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni bugün dövme anne', 'beni-bugun-dovme-anne-tevfik-karinca-hrk1b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu şiir annesi tarafından şiddete maruz kalan bebeklere ithaf edilmiştir.

Annelerin kendi parçaları olan çocuklarına şiddet uygulamamaları dileklerimle.

O bebeklerin gün olup eşlerine şiddet uygulayacaklarını unutmayalım.

Bugün beni dövme anne

Ben sevgiye muhtacım

Yaşım ne

Etim ne butum ne

Bugün beni dövme anne

Madem zor gelecekti bakmak

Neden doğurdun beni anne

Doğduğumda döktüğün gözyaşları sahtemiydi anne

Yine de geç kalmış değilsin

İstemiyorsan beni devlete ver anne

Onlar baksınlar bana

Dayak yesem de orada

Annem değil derim nasıl olsa

Bugün beni dövme anne

Bana vuran o ellerini

Gün olup öpmemi bekleme anne

Sen de böyle aciz

Sen de böyle muhtaç

Sevgi dilendiğin günlerin olacak anne

O zaman ben vurursam sana

Gücüne gitmez mi söyle

Ah be anne ah

Babama mı kızdın

Kardeşime mi komşuya mı

Seni de dövermiydi annen anne

Ondan mı öğrendin yoksa dövmeyi

Bugün beni dövme anne

Yaşım küçük

etim ne butum ne anne

Ya karnıma vurduğunda ölseydim

Pişman olmayacakmıydın

Beni, ileride

Karım, çocuklarımı,annemi döven

Adam olarak mı yetİştirmek mi istiyorsun

Benden ne bekliyorsun

Buna hakkın yok be anne

Eğer bakamayacaksan beni neden doğurdun 

Bana vurursan bir daha sana anne demem anne

BENİ BUGÜN DÖVMEDİĞİN İÇİN TEŞEKKÜRLER', 'Bu şiir annesi tarafından şiddete maruz kalan bebeklere ithaf edilmiştir. Annelerin kendi parçaları olan çocuklarına şiddet uygulamamaları d...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/beni-bugun-dovme-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Nazlı Sevdiğim', 'benim-nazli-sevdigim-yusuf-onder-bahceci-hnr2b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözleri hep gülerdi,

Edâ, nazlar ederdi,

Sonra küsüp giderdi,

Benim nazlı sevdiğim.

Neden böyle ederdi,

Kendini heder ederdi,

Gözler yaşlı silerdi,

Benim nazlı sevdiğim.

Seni sevdim demezdi,

Sende sevdin demezdi,

Çok sevmiştim bilmezdi,

Benim nazlı sevdiğim.

Gizli gizli ağlıyordur,

Neden, neden diyordur,

Hâlim yaman bilmiyordur,

Benim nazlı sevdiğim....', 'Gözleri hep gülerdi, Edâ, nazlar ederdi, Sonra küsüp giderdi, Benim nazlı sevdiğim. Neden böyle ederdi, Kendini heder ederdi, Gözler yaşlı s...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-nazli-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresi Yok Dertlerimin', 'caresi-yok-dertlerimin-yusuf-onder-bahceci-y5s3e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözler kara, kalbim yara,

Gezdim diyardan diyara,

Sen derdine çare ara,

Çaresi yok dertlerinin.

Onu sevdim oldum heder,

Seven kalbim acı, keder,

Bu yollar uzayıpta gider,

Çaresi yok dertlerimin.

Onu sevdim gözüm kara,

Hep açtı kalbimde yara,

Sıra dağlar var arada,

Çaresi yok dertlerimin.

Onu sevdim oldum harap,

Çekip gitti, oldu serap,

Gönül bağım oldu turap,

Çaresi yok dertlerimin....', 'Gözler kara, kalbim yara, Gezdim diyardan diyara, Sen derdine çare ara, Çaresi yok dertlerinin. Onu sevdim oldum heder, Seven kalbim acı, ke...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/caresi-yok-dertlerimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasan Basri Bey', 'hasan-basri-bey-mehmet-akif-tiryaki-mm9vv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir enstrüman çalarmısın abi,

Bir tek kapı zili çalarım dedi Hasan Basri,

Çocukları için çalıştı, Mahmut Paşa, Karaköy''de,

Kızı şimdi Amerika''da öğretmen üniversitede.

Hasan Basri bey Voyvoda Han''da ofisinde.

Bir piyano almıştı kazandığı parayla ilk ihalesinde.

O piyanoyu çalmasını kızı öğrendi,

Hasan Basri bey bir tek kapı zili çalmasını bildi.

Daha sonraki şiirlerimde bu abiden,

Bahsedeceğim eminim ki...

Kendisinde suda kurutulmuş laflar çoktu,

Samimi insandı, kalbinde kötülük yoktu.

Sigarayı bıraktı, sigara tabakasına paralarını koydu,

İnsanları sevdi, hayata doydu.

Şimdi hanımıyla baş başa yaşıyor,

Senede bir kaç gün de kızıyla ve damadıyla buluşuyor.

Sen çok yaşa Hasan Basri Bey damadın, kızın ve eşinle,

Mutlu olurum seninle her görüştüğümde.', 'Bir enstrüman çalarmısın abi, Bir tek kapı zili çalarım dedi Hasan Basri, Çocukları için çalıştı, Mahmut Paşa, Karaköy''de, Kızı şimdi Amerik...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hasan-basri-bey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman/Senin Şiirin', 'zaman-senin-siirin-ali-gencay-b713j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saati; Sana kurdum

Her saat başı öp beni

Sabahın er vakti

Karanfil/Kadife tenli

Gecenin kör vakti

Günahkâr/Cüretkâr, hevesli

Dayanılmaz ateşli

Fırlattım yorganı

Aylardan zemheri

Kısaltıyorum süreni

Saati: sana kurdum

Her yarım saatte bir öp beni

Gölgelerde

Kıvrak, saklı gülüşmeler

Sessizlik/Suskun istemeler

Kapanan göz kapaklarında sevişmeler

Katlanılmaz seni beklemeler

İki de bir,

Elim/Saat/Kurma pimi

Parmak uçlarımda tırtıllı izi

Kısaltıyorum süreni

Saati; sana kurdum

Her on beş…

Bu böyle olmayacak

Kaldırıyorum süreni

Ayırma dudaklarını benden

Karanfilde çiğ gibi

Kurulmamış, durmuş saatte

Yelkovan/Akrep üst üste durur gibi

Sonsuza dek ölüm gibi', 'Saati; Sana kurdum Her saat başı öp beni Sabahın er vakti Karanfil/Kadife tenli Gecenin kör vakti Günahkâr/Cüretkâr, hevesli Dayanılmaz ateş...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/zaman-senin-siirin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçi Boş Olunca Paket Güzel Olmalı (Hiç''lik)', 'i-ci-bos-olunca-paket-guzel-olmali-hic-lik-turan-tuncer-ck7gj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İÇİ BOŞ OLUNCA PAKET GÜZEL  OLMALI (HİÇ''LİK) 

İnsan!  ''Hiç'' olunca, 

İçinde ''Hiç''in anlamını büyütür,

Kıyamet kopar o gün H/içliğinde. 

Olurda, 

Göremezse kendi yüzünü 

Baktığı aynalarda.

Vahaları, 

Kızıl kıyamet yangın olur.

Yangınları, 

Yüreğinde, düşlerinde.

Düşleri, kabuslara tutsak.

Yaşayan bedendir artık,

İçindeki kendi ''Hiç''dir.

Mütarekeleri kayıp üstünedir,

Koşulsuz.

Dün''e ait ne varsa  bulduğu,

''Hiç''liğinde ''Hiç'' kalırda ''Hiç'' olarak

Umudu ayrık otlarıdır,

İnsanın sırtını döndüğü

Küfür ve lanet, 

Katığı olur da yaşamının

Aynaya her baktığında,

Dengini yıkan, 

Yoz! 

Fincancı inadlarını görür

Tımarsız.

Ahengi de kalmamıştır 

Düzeni de

İçindeki sevgi bir ateştir artık

Dem vurduğu hanlardan önce

Kendisini yakan.

Bıraksa içindeki kusmuk kinlerini

Rüzgarlar da alıp götürmez

Ağırdır yükü.

Dağın taşın taşıyamadığı 

Lanetler vardır içinde,

Artık! 

Konakladığı dam altına 

İki aynası vardır 

''Hiç'' liğini yansıtan 

Ne yana dönse 

Bütün ''Hiç'' likleri hasatta

Hasadı berekete kesmiş

Gıpta eder de Şeytan 

''Hiç'' in kabus yüzüne

''Hiç'' 

''Hiç'' liğini bilmez

Açar kollarını boş bi mağrurlukla

Kesime hazır 

Yılbaşı hindisi

18-01-2006/İst

Alkadraz_Kuşcusu', 'İÇİ BOŞ OLUNCA PAKET GÜZEL  OLMALI (HİÇ''LİK)  İnsan!  ''Hiç'' olunca,  İçinde ''Hiç''in anlamını büyütür, Kıyamet kopar o gün H/içliğinde.  Olur...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/ici-bos-olunca-paket-guzel-olmali-hic-lik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecikmesin Baharlar', 'gecikmesin-baharlar-turan-tuncer-e3wfa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'GECİKMESİN  BAHARLAR

Bırakıp gitme

Ne olursun? 

Bırak,

Sensiz gitsin göçmen kuşlar

Uzak iklimlere.

Seviyorsan! 

Yanımda kalırsın.

İçini,

Sendeki; 

Beni yakıp ısıtırsın.

Bırak gemiler

Sensiz çıksın

Uzak yollara.

Dönüşülerinde,

Senin olma ihtimalin olmasın.

Bırakıp gitme

Ne olursun? 

Gecikmesin baharlar

25-12-2005

Alkadraz_Kuşcusu', 'GECİKMESİN  BAHARLAR Bırakıp gitme Ne olursun?  Bırak, Sensiz gitsin göçmen kuşlar Uzak iklimlere. Seviyorsan!  Yanımda kalırsın. İçini, Sen...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gecikmesin-baharlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kayıp Hayat', 'bir-kayip-hayat-turan-tuncer-0f4zz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BİR  KAYIP  HAYAT

( Yüzün hiç olmadı

    Gözlerin

    Gülüşün olmadı) 

BİR  KAYIP  HAYAT

Göçükler altında kalmışım

Üstümde hayallerim

Umutlarım

Yarısı kayıp 

Bir yaşam elimdeki

Bütün bakışlar

Siyah beyaz

Renkler kayıp

Ayarımla oynamayın boşuna

Bu benim yazgım

Bütün manşetlerim

Ve

Bütün ikinci sayfalarım

Hüzün haberleri ile dolu

Ben ofsaytlara düşerken

Kalemde 

Yalnızlığın golleri

Bir sıfır yenik başlar

Her günüm

Kısa yaşam yolculuklarında

Umutlarım

Tozlu raflardaki

Unutulanlar arasında

Yerini almış

Resimlerim

İzafi mutluluklar üstüne

Yüzün hiç olmadı

Gözlerin

Gülüşün olmadı

Güvertelerinden

Hiç 

Mutluluk kırıntıları atamadım

Arsızca düşmüşüm peşine

                                         Gemilerinin

Sol yanımda

Acımasız bir lodos

İçimde

Yine

       Yarım mutluluklar

Bir kayıp ilanında

17-11-2005/İst

Alkadraz_Kuşcusu', 'BİR  KAYIP  HAYAT ( Yüzün hiç olmadı     Gözlerin     Gülüşün olmadı)  BİR  KAYIP  HAYAT Göçükler altında kalmışım Üstümde hayallerim Umutla...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bir-kayip-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Umudun Mavisi', 'i-cimde-umudun-mavisi-turan-tuncer-bl222', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İÇİNDE UMUDUN MAVİSİ

Ayrılık ağırdır 

Otururda 

Yüreğine taş gibi

Zordur taşıyamazsın

Hamalı olursun da

Gece sancılarının 

Hasılatı göz yaşlarındır 

Sayamazsın

Mora düşmüş geceler

Göz ötesi yanlızlık

                             Diz boyu

Her şeyden kaçarsın da

Ya kendini ne yapacaksın

Dost olur da alaca kuşlar

Bütün açmış çiçeklerine

Gemilerin son çizgide kaybolurken

İçinde umudun mavisi

Kızıl bir gurup olur

Evrenin bütün renkleri ayrılık

Rüzgarları hüzün olur da 

Sarar, seni dört yanından

Beyazların kirletilmiştir artık

Bakışların 

Sarı, hüzündür

Mevsimlerin 

Beyaz, umutsuzluk

Karakışa, kara talihe

Ne de yakışır 

Karın beyazı

                    Üşümenin ayazı

Çaresizlik,

İçinde yeşerir de 

Bütün yeşillere inat

Sol yanın kavgalarda

Umudunun mevsimleri 

Çöle döner

Yokluğu 

Yazılmamış şiir olur 

Ayrılıklar kırık plak

Zaman 

Anlamını yitir 

Ayrılık

Sol yanında

Saplı kalır 

Gülüşü bakışı

İçinde

Kirliletilmiş savaşlar



29-11-2005/İst

Alkadraz_Kuşcusu', 'İÇİNDE UMUDUN MAVİSİ Ayrılık ağırdır  Otururda  Yüreğine taş gibi Zordur taşıyamazsın Hamalı olursun da Gece sancılarının  Hasılatı göz yaşl...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/icimde-umudun-mavisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniş (2)', 'seslenis-2-caglar-asik-sk425', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rabb’imiz Allah’tır bizim.

Dinimiz İslam’dır bizim.

Uyarız Resul’dür bizim.

Yaşarız Kur-an’dır bizim.

Severiz Gönül’dür bizim.

Veririz can Dost’tur bizim.

Ölmeyen Baki’dir bizim.

Sonsuza Hakim’dir bizim.

Var olan tek Hak’tır bizim.

Yağmakta Rahmet’tir bizim.

Bilmekte Alim’dir bizim.

Görmekte Gören’dir bizim.

Duymakta Duyan’dır bizim.

Yazmakta Yazan’dır bizim.

Sormakta Soran’dır bizim.

Cezayı Veren’dir bizim.

Mükafat Eden’dir bizim.

Mahşerde var Hak’tır bizim.

Dönecek tek Yer’dir bizim.

Yitmeyen Güzel’dir bizim.

Bitmeyen tek Aşk’tır bizim.

Temizlik İman’dır bizim.

Sunarız ruh Pak’tır bizim.

Coştukça coşmaktır bizim.

Baktıkça kanmaktır bizim.

Rızasın ummaktır bizim.

Güvende olmaktır bizim.

Huzurda kalmaktır bizim.

&

İstanbul – 20.01.2006

Çağlar Aşık – Sesleniş (2)', 'Rabb’imiz Allah’tır bizim. Dinimiz İslam’dır bizim. Uyarız Resul’dür bizim. Yaşarız Kur-an’dır bizim. Severiz Gönül’dür bizim. Veririz can D...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/seslenis-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniş (3)', 'seslenis-3-caglar-asik-r03tm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rabb’im bizi aff eyle.

Sonumuzu hayr eyle.

Aşkından lütuf eyle.

Hasretten yanmış eyle.

Ölmeden ölmüş eyle.

El Aman medet eyle.

Ağlarız gülmek eyle.

Sapmadan gelen eyle.

Doğruyu bulan eyle.

Aşkını duyan eyle.

Her daim coşan eyle.

Gül canım kurban eyle.

Son sözde imdat eyle.

&

İstanbul – 20.01.2006

Çağlar Aşık – Sesleniş (3)', 'Rabb’im bizi aff eyle. Sonumuzu hayr eyle. Aşkından lütuf eyle. Hasretten yanmış eyle. Ölmeden ölmüş eyle. El Aman medet eyle. Ağlarız gülme...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seslenis-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha seri', 'daha-seri-mikdat-bal-9et33', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sönen ışık değil gözün feridir

Ferasetle bakan gönül eridir

Işık hızı saniyede şu kadar

Kalpten kalbe seyran daha seridir', 'Sönen ışık değil gözün feridir Ferasetle bakan gönül eridir Işık hızı saniyede şu kadar Kalpten kalbe seyran daha seridir...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/daha-seri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-038 Çıkardan başka büyük yok! ..', 'ub-038-cikardan-baska-buyuk-yok-mehmet-coban-iqdmr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnançlar birleştirmek isterken

Çıkarlar savurdu bizi

Kalmadı ortalıkta doğru dürüst

Ne tanrıdan gelen, 

Ne de kuldan üretilen din

Çıkarlar oldu koskoca bir din

Ümmetleri farklı yerlerden

Dinleri, dilleri, ırkları ayrı

Farklı toplumlardan

Farklı ideolojilerden geldiler

Hepsi birlik olup çıkarda birleştiler 

Çıkar üzerine bir yaşam kurdular

Koskoca bir din oluşturdular

Desek ki Allah’tan başka büyük yok

Yalan oldu, çıkardan başka büyük yok

İnandıkları tanrılar

Girmedi dillerinden

Ne kalplerine 

Ne inançlarına

Ne de yaşamlarına

İnandıkları dinler

Özünü kaybetti

Töre oldu çıkarlarına

Tanrının büyüklüğü lafta kaldı

Gerçek tanrıları yaşamlarında saklı

Yaşamları ise sadece çıkara bağlı

O zaman, 

Onlar demeseler de

Diyelim biz onlar adına

Haydi, hep beraber

Tadına vara vara! ..

En büyük çıkar,

Çıkardan başka büyük yok! ..

20.01.2006-İzmir', 'İnançlar birleştirmek isterken Çıkarlar savurdu bizi Kalmadı ortalıkta doğru dürüst Ne tanrıdan gelen,  Ne de kuldan üretilen din Çıkarlar o...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ub-038-cikardan-baska-buyuk-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-056 Ey insanlık! ..', 'ub-056-ey-insanlik-mehmet-coban-16ohq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuş gibi uçup gittin

Yer yarıldı içine girdin

Yok, oldun hayatta yoksun

Kitaplarda ideallerde bolsun

Haykırıyorum….

Seni kaybedenler

Seni yok edenler

Seni kaçıranlar

Hepten kahrolsun! ..

Döner misin? 

Gelir misin? 

Bir kere daha dünyaya

Sunar mısın? 

Bir kere daha 

Kendini insanlığa! .. 

Sen yoksun diye! ..

Zulüm aldı başını gidiyor….

Sen yoksun diye! ...

Zalimler can alarak

Kan akıtmaya özgürlük diyor! ...…….

20.01.2006-İzmir', 'Kuş gibi uçup gittin Yer yarıldı içine girdin Yok, oldun hayatta yoksun Kitaplarda ideallerde bolsun Haykırıyorum…. Seni kaybedenler Seni yo...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ub-056-ey-insanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiş', 'gidis-nihal-yasar-6i9r6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Canım sevgilim bugün gidiyor.

daha ona doyamadan,

öpüp koklayamadan.

uzaklaşıyor benden.

nice yollar,nice dağlar giriyor araya.

oysa daha dün gibiydi ona sarılışım.

hala sıcaklığı var bende o tatlı vedanın.

inanmak istemiyor bu gidişe

ne tenim ne kalbim.

ama biliyorum çoktan gitti benim sevgilim.

gidişini görmemek tek tesellim.

çünkü dayanamazdı yüreğim.', 'Canım sevgilim bugün gidiyor. daha ona doyamadan, öpüp koklayamadan. uzaklaşıyor benden. nice yollar,nice dağlar giriyor araya. oysa daha dü...', ARRAY['Türk Edebiyatı','Şiir','Nihal Yaşar']::text[], 8.5, '{"poet":"Nihal Yaşar","poet_slug":"nihal-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gidis-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemler Üzerine Düşünceler', 'ozlemler-uzerine-dusunceler-h-hikmet-esen-8q6s9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göz süzerken Ayvalık,

Egenin kıyısından,

Cunda akşamlarına; 

Karanlığa boyansa da,

Duygular,

İki gözüm yıldızlarda,

Yüreğimde 

Ay..

Yakamoz mu,

Balıklar mı,

Denizle oynaşanlar.? ! 

Bir yanda sıkıntılar,

Umutlar öte yanda; 

Patlayan tomurcuklar..

Direnen özlemlerdir; 

Hoyrat akşamların,

Anılarına.

Bir inip, 

Bir çıkarken; 

Yaşanmamış günlere,

Ömrü bağlarlar..

20/01/2005', 'Göz süzerken Ayvalık, Egenin kıyısından, Cunda akşamlarına;  Karanlığa boyansa da, Duygular, İki gözüm yıldızlarda, Yüreğimde  Ay.. Yakamoz ...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ozlemler-uzerine-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-nihal-yasar-fu6nj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kah yürüdüm yollarda

kah koştum dağlarda,taşlarda

yetişmek için zamana

yetişip tutup durdurmak.

kah beyazlamış saçlarım savruldu rüzgarda

kah oturup ağladım bu geçen zamana

içti kurumuş toprak tüm gözyaşlarımı

benimde bir vakit içtiğim gibi zamanı.', 'Kah yürüdüm yollarda kah koştum dağlarda,taşlarda yetişmek için zamana yetişip tutup durdurmak. kah beyazlamış saçlarım savruldu rüzgarda ka...', ARRAY['Türk Edebiyatı','Şiir','Nihal Yaşar']::text[], 8.5, '{"poet":"Nihal Yaşar","poet_slug":"nihal-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zaman-285-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnkİlap III', 'i-nki-lap-iii-mehme-arslan-76x0y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bi bankayla eski sevgili arasında

ortak nokta ne olabilir sizce

durun ben söyleyeyim

borcumu ödemediğimde

bankam da hemen arıyor

eski sevgilim de

peki farklarını da belirtelim o halde

bankam tüm özel günlerde

en azından bi mesaj atıyor

eski sevgilimin aksine

19/01/2006', 'bi bankayla eski sevgili arasında ortak nokta ne olabilir sizce durun ben söyleyeyim borcumu ödemediğimde bankam da hemen arıyor eski sevgil...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/inkilap-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genç Adam', 'genc-adam-cengiz-kapusuz-rpbr4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir genç adam varmış,

Yüreği dağlar kadarmış.

Ulaşmak için sevdasına,

Onca şeyi göze almış.

O genç adam ki! 

Gözleri kap kara,

Ulaşamasa da sevdalıya,

Umut ile sarılmış sevdalısına.

O genç adam sevdasına hasret! 

Düşmüş sevda yollarına,

Bir gün alacak elbet,

Sevdasını kollarına....', 'Bir genç adam varmış, Yüreği dağlar kadarmış. Ulaşmak için sevdasına, Onca şeyi göze almış. O genç adam ki!  Gözleri kap kara, Ulaşamasa da ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/genc-adam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlardaki Kârlar Eriyince', 'daglardaki-k-rlar-eriyince-yusuf-onder-bahceci-q5lwu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana gönül verdim, seni severim,

Sen istersen sevme bana ne derim,

Hiç kusura bakma birgün dönerim,

Dağlardaki kârlar eriyince ben.

Seni sevdim rüyalarda görürüm seni,

Her gece istihare yapıp bilirim seni,

Sen yorulma gel deme gelirim emi,

Dağlardaki kârlar eriyince ben.

Seni sevdim ölene dek beklerimde,

Gün değil, ay değil, yılı yıla eklerimde,

Gözlerimde fer kalmasa geleceğimde,

Dağlardaki kârlar eriyince ben...', 'Sana gönül verdim, seni severim, Sen istersen sevme bana ne derim, Hiç kusura bakma birgün dönerim, Dağlardaki kârlar eriyince ben. Seni sev...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/daglardaki-karlar-eriyince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-074 İster miydin?', 'ub-074-i-ster-miydin-mehmet-coban-fmf1b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Roma’da bir köle

Gemilerde ayağı zincirde

Piramitlerin alın terinde

Saraylarda cariye

Devasa tapınaklarda işçi

Kaderi baştan sona kederli

 ……………………...Olmak! ...

İster miydin? 

Babası öldürülen

Anası köle edilen

Kendi dindaşlarına

Kendi insanlarına 

Karşı asker yetiştirilen! ..

…………………Olmak! ..

                                

İster miydin? 

Ailenden uzak

Evinden uzak

Köyünden uzak

Arkadaşlarından uzak

Yokluk, sefillik içinde

Gündüz ve gecenin içinde

Bu gün orada 

Yarın burada

Her gün öldürmelerde

Her gün, her an ölümlerde 

……………………..Olmak! ..  

Düşün bunları! ..

Okuduğun her tarihte

Gezdiğin her yerde

Seyre daldığın mabetlerde

Gördüğün tarihi eserlerde

Olmak,

İster miydin? 

Sen en diplerde 

Her yapıtın temellerinde…

Alın terinle, emeğinle, yüreğinle

Geçmişi kara, geleceği kara günlerinle! ..

Düşün bunları! ..

Seyrederken bunları

Okurken olanları

Hissetmemişsen

Utanmamışsan

Kalbini yokla! 

Düşünceleri yokla! 

Oralarda insanlık ara! ..

Kulaklarını aç dinle..

İnsanlık ararken oralarda

İnce bir şarkı duyacaksın kulaklarınla

Acı çeken insanların, yakıcı ağıtlarında! ..

Zalimlerin, zorbaların, kahramanların

Sultanların, kralların, imparatorların

Kahkahaları arasında……………………………….. 

20.01.2006-İzmir', 'Roma’da bir köle Gemilerde ayağı zincirde Piramitlerin alın terinde Saraylarda cariye Devasa tapınaklarda işçi Kaderi baştan sona kederli  …...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/ub-074-ister-miydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zıtlıklar', 'zitliklar-timur-i-likan-f9o2m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herşey zıttıyla birlikte

Güzeldir ve de anlamlıdır da

İyi ve kötü

Güzel ve çirkin

Akıllı ve ahmak

Ahlaklı ve ahlaksız gibi

Bir düşünsenize kötüler

Olmasaydı iyilerin

Olur muydu ki bir kıymeti? 

Çirkinler olmasıydı eğer

Güzellerin peşinden 

Hiç koşulur muydu ki? 

Ahmaklar olmasaydı

Akıllı olmak neye yarardı ki? 

Ahlaksızlar olmasaydı

Ahlaklının ne değeri olurdu ki? 

Bütün bunlar olmasaydı

Hayâtın ne anlamı kalırdı ki? 

(20 Ocak 2006/ İstanbul)', 'Herşey zıttıyla birlikte Güzeldir ve de anlamlıdır da İyi ve kötü Güzel ve çirkin Akıllı ve ahmak Ahlaklı ve ahlaksız gibi Bir düşünsenize k...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/zitliklar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Yöre', 'bizim-yore-mustafa-benkli-6p1us', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu yörenin toprağından yoğruldum; 

Varacağım sonunda bu toprağa

Hiç bakmadan ne sola ne de sağa

Kaynaştığım havasıyla soğruldum! ...

Bir aklıma esti mi, doğrulurdum,

Kargapazar''dan tâ Palandöken''e; 

Tepelerden aşıp terim dökene

Yetişirdi imdâdıma yoğurdum...

Doğusuna doğru kurulu Tortum; 

Orasının havası pek sevâil,

Manzarası nefis olurdum mâil; 

Kavlimde ben O''na Nihah diyordum...

Çocukken bir ağıt işitiyordum:

''Hapseyledi beni, yıkıla Nihah! 

Penceresi yok ki, çıkah da bakah! ''

Sebebini bilmeden ağlıyordum...

Geçtiğim her yeri Cennet bulurdum; 

Unutamaz baharını bilenler:

Çevrilirdi güle bütün dikenler; 

Çiçek kokan havasını solurdum...

Lezzetinden; yemesem de doyduğum

Güzün güzlük ekilirdi yörede; 

Bostanında bulunurdu tere de,

Yar Göze''nin suyu ile yûduğum...

Ocağını sönmüş gibi gördüğüm; 

O bostanlar şimdi merâya dönmüş,

Bilmem ki kaç kişi sılâya dönmüş? 

Gurbetini tâ içimde duyduğum...

Gidenlere burdan kopma diyordum; 

Değer mi ki gurbet; sılaya, sanki? 

Emânettir sana bu toprak, bil ki! ...

Diye bunu gizlice soruyordum...

Sanki ''eyvâh'' çektiğini duyduğum,

Ervâhına derim ki: Çekme eyvâh! ...

Sonra nasıl kurulur viran Nihah! ...

Kurtuluşa dûa olur; umduğum...

Tâ, Keşmir''den Zigetvâr''a koştuğum

Bu ülkenin bizde büyük hakkı var! ...

Türk''ün İki Cihânda da tahtı var! ...

Şâyet ruhsât alır ise Baş Tuğum! ...

Bu dûaya amin derken korktuğum:

Cihânlara hakim iken kavrulduk

Ve  acı bir rüzgâr esti savrulduk! ...

Dilerim ki, toparlar bir Başbuğ''um! ...', 'Bu yörenin toprağından yoğruldum;  Varacağım sonunda bu toprağa Hiç bakmadan ne sola ne de sağa Kaynaştığım havasıyla soğruldum! ... Bir akl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Benkli']::text[], 8.5, '{"poet":"Mustafa Benkli","poet_slug":"mustafa-benkli","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bizim-yore-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiye''m', 'turkiye-m-i-brahim-pataz-nfpsg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yamyamlar, vampirler, birlikte gene,

Şo dostların, derdi oldun Türkiye’m.

Böyle geçti, böyle sürer kaç sene? 

Özlerinin, kurdu oldun Türkiye’m.

   Anlaşmalar dolu, sinsice oyun,

   Bizi karalıyor, her türlü yayın,

   Türk’e suçsuz diyen, suçluymuş duyun! 

    Soysuz soyu kırdı oldun Türkiye’m.

Irkım temiz, kirli işim yok dedin,

Arşivini ele açtın, bak! Dedin.

Tarihimde, benim alnım ak dedin.

Devletlerin, merdi oldun Türkiye’m.

   Hakkımızda, çeşit çeşit yalan var,

   Aramıza, kin tohumu salan var,

   ELEMİ der: bin bir çeşit bölen var,

   Azınlıklar yurdu oldun Türkiye’m.

        İbrahim PATAZ

        20/01/2006 ADANA', 'Yamyamlar, vampirler, birlikte gene, Şo dostların, derdi oldun Türkiye’m. Böyle geçti, böyle sürer kaç sene?  Özlerinin, kurdu oldun Türkiye...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Pataz']::text[], 8.5, '{"poet":"İbrahim Pataz","poet_slug":"i-brahim-pataz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/turkiye-m-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-032 Bir yıldız kaydı! ..', 'ub-032-bir-yildiz-kaydi-mehmet-coban-qvkjd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda şarkıları dinlerken

Sevgiliden söz ederken

Kalbim sevda açısı çekerken

Gözlerim ufukları seyrederken

Etrafa gülücükler atarken

Kazandığım paraları sayarken

Yalandan insanlık için ağlarken

Önümdeki sofrada tıkınırken

Bir yıldız kaydı……

Bir insan vuruldu…

Bir insan öldü…

Bebekti,

Çocuktu, 

Delikanlıydı

Babaydı

Büyük babaydı

Anneydi

Büyük anneydi

Açlığın acımasız açlığında

Bombaların altında

Namluluların ucunda

Bir yıldız kaydı…………

20.01.2006-İzmir', 'Sevda şarkıları dinlerken Sevgiliden söz ederken Kalbim sevda açısı çekerken Gözlerim ufukları seyrederken Etrafa gülücükler atarken Kazandı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ub-032-bir-yildiz-kaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-nihal-yasar-2d2dc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özlemine yasladım başımı

Örtün üzerime yalnızlığı

gözlerimi kapadım

hayalinin gözlerinde

seni soludum buram buram

hasret çektim cigerlerime..', 'Özlemine yasladım başımı Örtün üzerime yalnızlığı gözlerimi kapadım hayalinin gözlerinde seni soludum buram buram hasret çektim cigerlerime....', ARRAY['Türk Edebiyatı','Şiir','Nihal Yaşar']::text[], 8.5, '{"poet":"Nihal Yaşar","poet_slug":"nihal-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalnizlik-330-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüğünü Sanan Körler', 'gordugunu-sanan-korler-hikmet-yaman-b653l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gördüğünü sanan körlere,

Gülümü anlatsam

Renkleri seçemeyen körler

Benim al''ımdan ne anlasın.

Yürümüyor,uçuyorum desem,

Aşkımı anlatsam

Koşmayı bilmemiş körler

Benim halimden ne anlasın.

Gözleri yakıyor desem,

Güneşimi anlatsam

Mehtabı yaşamamış körler

Ruhumun fenerinden ne anlasın.

Zamanı durdurun desem,

Geçen günleri anlatsam

Zamandan bihaber körler

Akan ömrümden ne anlasın.

19.01.2006 MUŞ', 'Gördüğünü sanan körlere, Gülümü anlatsam Renkleri seçemeyen körler Benim al''ımdan ne anlasın. Yürümüyor,uçuyorum desem, Aşkımı anlatsam Koşm...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yaman']::text[], 8.5, '{"poet":"Hikmet Yaman","poet_slug":"hikmet-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gordugunu-sanan-korler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseri Gönlüm', 'serseri-gonlum-cengiz-kapusuz-n37um', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gönülde serseri oldu ya! 

Başka birşey diyemiyorum.

Sevmek ademden bu yana,

Aşkı bile tarif edemiyorum.

Dedim ya  ne bulduğunu aradı,

Nede aradığını buldu.

Aşkın ne kitabını yazdı,

Nede resmini karaladı.

O adına aşk denilen şey,

Nice aşıklar yaraladı,

Nicelerini bu yolda paraladı,

Lokman hekim bile bu yarayı saramadı.

Dedim ya dostlar,

Bu gönül serseri oldu,

Ne aradığını buldu,

Nede bulduğu bu derde çare oldu...', 'Bu gönülde serseri oldu ya!  Başka birşey diyemiyorum. Sevmek ademden bu yana, Aşkı bile tarif edemiyorum. Dedim ya  ne bulduğunu aradı, Ned...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/serseri-gonlum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tdk', 'tdk-bilal-i-lhami-koksal-rh9p9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen gittikten sonra karşıyım bütün ayrılıklara

Hatta soru eki olan -mi''yi bile birleşik yazıyorum

Acaba ayıp oluyormudur Türk Dil Kurumu çalışanlarına?', 'Sen gittikten sonra karşıyım bütün ayrılıklara Hatta soru eki olan -mi''yi bile birleşik yazıyorum Acaba ayıp oluyormudur Türk Dil Kurumu çal...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/tdk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savrulduk', 'savrulduk-umut-engin-deniz-l4vjd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SAVRULDUK

— ablama

Derin bir sessizlik var.

Çöktü üzerimize kara bulutlar.

Oysa, parlayarak süzülüyordu

altın renkli ışığı.

Güneşimizi kapattılar.

Birden gökyüzü nefretini kustu.

Karabulutlar yağmur bulutlarıyla kardeş oldu.

Koptu fırtına,

savrulduk ordan oraya.

Karanlıkta kaldı güneşimiz,

direnemedi.

Bizleri tek edip gitti.

Ah... terk edip gitti.

08 Ocak 2006

UNLBBCN — Umut Engin Deniz', 'SAVRULDUK — ablama Derin bir sessizlik var. Çöktü üzerimize kara bulutlar. Oysa, parlayarak süzülüyordu altın renkli ışığı. Güneşimizi kapat...', ARRAY['Türk Edebiyatı','Şiir','Umut Engin Deniz']::text[], 8.5, '{"poet":"Umut Engin Deniz","poet_slug":"umut-engin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/savrulduk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahdımız Olsun', 'ahdimiz-olsun-mehmet-karli-ekcpa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kanımızı mukaddesat için vermeliyiz ki

Bir kıymeti olsun kanımızın değeri olsun…

Düşmanın üzerine cesaretle gitmeliyiz ki

Yiğitler yanında bizim de yerimiz olsun…

Dertlilerin tüm derdini dert etmeliyiz

Haini çakalı kahpeyi şıp tutmalıyız 

Yardımda merhamette fark atmalıyız

Mecliste yer verilsin sözümüz olsun...

Değiştirdik kendimizi hanım bey yaptık

Sosyeteye uyduk giyinmedik tül taktık

Sebep yokken kıvırtarak yoldan da saptık

Mayası bozulmayan özlü yapımız olsun…

Kaçmalı saklanmalı cani olanlar bizden

Elbisemiz görünmesin çamurdan tozdan

Çekinip korkmayasın bozulmuş yozdan

Ödleklerden pısırıklardan farkımız olsun…

Gözlerimiz baktığında iyiyi güzeli görsün

Sözünden dönenlere lanet kahrolsun ölsün

İhanet eden alçaklar var ya hepsi sürünsün

Bizim de bu kadarcık bari ahdımız  olsun....', 'Kanımızı mukaddesat için vermeliyiz ki Bir kıymeti olsun kanımızın değeri olsun… Düşmanın üzerine cesaretle gitmeliyiz ki Yiğitler yanında b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karlı']::text[], 8.5, '{"poet":"Mehmet Karlı","poet_slug":"mehmet-karli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ahdimiz-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyor Beni', 'seviyor-beni-yusuf-onder-bahceci-j954v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu nasıl iştir, nasıl sevdadır,

Bir teselli verin, seviyor deyin,

Şimdi mutlu değil, ağlıyor deyin,

O mutlu değilse seviyor beni.

Seven gözlerinde yaşlar var deyin,

Bakışları hep mahsun ağlıyor deyin,

Yollara hep çıkıyor, bakıyor deyin,

O mutlu değilse seviyor beni.

Seni çok sevmiş seviyor deyin,

Adını hep soruyor, özlüyor deyin,

Senden bir haber bekliyor deyin,

O mutlu değilse seviyor beni.

Albümlere hergün bakıyor deyin,

Sevdiğini kalbinde saklıyor deyin,

O seni ölene dek bekliyor deyin,

O mutlu değilse seviyor beni....', 'Bu nasıl iştir, nasıl sevdadır, Bir teselli verin, seviyor deyin, Şimdi mutlu değil, ağlıyor deyin, O mutlu değilse seviyor beni. Seven gözl...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seviyor-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızları Sardım Yaralarıma', 'yildizlari-sardim-yaralarima-derya-aslan-fnbhb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Demdir bu derya dibinde yangınlar” demiş büyük usta. Kim bilebilirdiki yüreğinde kopan fırtınaları.

Kimsenin bendeki yangınları bilemediği,Göremediği,duyamadığı gibi…

İnan bilmiyorum kaç zamandır yüreğim böyle sürgün gurbet ellerde.Bilmiyorum kaç zamandır kanar yüreğim.Dinmez acılar, azar yaralar, durmaz yaşlar.İşte böyle; izlerim yeryüzünü, gökyüzünü.Yaralarım kanar ve ben yıldızlarla sararım yaralarımı kimse bilemez. 

Bir rüzgar esintisi ile sürüklenirim umman deryalara, turna sürüleri ile uçarım ırak diyarlara. Geçer zaman. Aman demeden alır benden en toy çağlarımı fark ettirmeden. Sonra yaralar biri yüreğimi derinden, öyle bir sevda yeli eser başımda bülbüle döner dizelerim. Hani tüm ırmaklar birleşir ya Kızılırmağa kavuşmak için. Ve haykırır o yüzyıllardır dinmeyen türküyü ılgıt ılgıt. Sevdamda öyle bir ırmak olur.Önce yürekte başlar ve sonra her hücreye karışır. Can verirken yare ben denize yol alırım. Canım bilmem artık tanımam beni ben tepeden tırnağa aşk olurum. Hiç hesapta yok iken yüreğimi söker yerinden yare sunarım. Ellerim kan gözlerim yaş dolu. Öyle yakar ki bu sevda ben külümde kaydolur ve tepeden tırnağa destansı bir aşk olurum sonra. Ve yanarım dağ yamaçlarında bir zaman. Baharın habercisi eder insanoğlu beni. Ve seni severim yar. Seni ne çok severim ben her bahar yanarım alev alev. 

Sevdikçe ben ayrılık girer araya. Kavuşmaları bilemem bu yüzden. Küskünüm. Küskünlüğüm yare değil kara bahtıma. Zemheri gecelerde kanar yüreğim. Sevdamı dökerim ırmaklara güzde. Irmak olur taşarım. Dökülür sevda sayfalara sığmaz ve birde zaman halden anlamaz. Yar gider de dönüp ardına bakmaz. Gözüm görmez dilim anmaz başkasını. 

Ve nasılki yağmur yağar benden bilirim.Nasılki solar bir çiçek kendim bilirim ve nasılki uzar yollar yardan bilirim. Azar yaralım Gece olunca.

Ben yıldızları sararım yaralarıma kimse bilmez.', 'Demdir bu derya dibinde yangınlar” demiş büyük usta. Kim bilebilirdiki yüreğinde kopan fırtınaları. Kimsenin bendeki yangınları bilemediği,G...', ARRAY['Türk Edebiyatı','Şiir','Derya Aslan']::text[], 8.5, '{"poet":"Derya Aslan","poet_slug":"derya-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yildizlari-sardim-yaralarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer', 'eger-bilal-i-lhami-koksal-9hp3s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğer benimle gelirsen 

Bildiğim şarkıları ezberden okurum sana bir çırpıda

Hatta şiirler yazarım her kafiyesi sana

Hepsi senin adına

Bütün yıldızlarda bir anımız olur

Bütün çıkmaz sokaklarda

Eğer beni seversen

Daha bir güzel bakarım hayata

Bir çift gülen kahverengin olur senin de

Dahası büyümüş bir çocuğun

Şairsem iki yanağımdan

Değilsem dudağımdan öp beni', 'Eğer benimle gelirsen  Bildiğim şarkıları ezberden okurum sana bir çırpıda Hatta şiirler yazarım her kafiyesi sana Hepsi senin adına Bütün y...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eger-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolan Var Dolan', 'dolan-var-dolan-huseyin-sigirtmac-l92to', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mertliği bölmüşler etmişler kalleş.

Menfaat uğruna yalan var yalan! 

Bulmadım dünyada doğruya bir eş.

Yanlışın içine dolan var dolan! 

Aşk atına bindim gitmez dört nala.

Yollarda kim öle bilmem kim kala.

Leyla’nın aşkından düşsem de çöle.

Pay oldu sevgiler talan var talan! 

Güven kalesine kondu namertler.

Baykuşlar tünedi virandır yurtlar.

Tilki gölgesine sığındı kurtlar.

Bülbül yuvasında yılan var yılan! 

Sığırtmaç doğrulup bakma boşuna.

Kargalar sürmeyi çekmiş kaşına.

Şekle aldananın eyvah başına.

Aklını başından alan var alan!', 'Mertliği bölmüşler etmişler kalleş. Menfaat uğruna yalan var yalan!  Bulmadım dünyada doğruya bir eş. Yanlışın içine dolan var dolan!  Aşk a...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dolan-var-dolan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Lambası', 'sokak-lambasi-umut-engin-deniz-v8nvy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasret bir sokak lambası,

köşe başında —

kopkoyu bir gecenin karanlığında.

Aydınlatıyor etrafını,

kendisi hep karanlıkta.

Yapayalnız,

          tek başına…

Bazen yağmur yağar, ıslanır —

bazen soğuk bir rüzgâr savurur saçlarını.

Bazen kavrulur

cehennem sıcağında.

Yine de —

aydınlatıyor etrafını,

kendisi hep karanlıkta.

Hasret bir sokak lambası,

köşe başında —

kopkoyu bir gecenin içinde.

Yapayalnız,

          tek başına,

                  bir başına…

                        Aydınlatıyor.

09.03.2000

UNLBBCN

Umut Engin Deniz', 'Hasret bir sokak lambası, köşe başında — kopkoyu bir gecenin karanlığında. Aydınlatıyor etrafını, kendisi hep karanlıkta. Yapayalnız,       ...', ARRAY['Türk Edebiyatı','Şiir','Umut Engin Deniz']::text[], 8.5, '{"poet":"Umut Engin Deniz","poet_slug":"umut-engin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sokak-lambasi-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabrın sonu selamettir', 'sabrin-sonu-selamettir-mikdat-bal-z4l80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dert edinme bunca derdi

Onu sana Allah verdi

Dertler seni fena gerdi

Sabrın sonu selamettir

Vesvesedir seni yoran

Sabır diyor sana Kur’an

İblistir yolunda duran

Mel’un şeytan ne lanettir

At gitsinler rahata er

Bil ki dünya muvakkat yer

Allah’tandır hayır ve şer

Şer istemek melanettir

Supriz var her dakikata

Koyul artık tahkikata

Erince bu hakikata

Mutluluğa alamettir', 'Dert edinme bunca derdi Onu sana Allah verdi Dertler seni fena gerdi Sabrın sonu selamettir Vesvesedir seni yoran Sabır diyor sana Kur’an İb...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sabrin-sonu-selamettir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evimiz', 'evimiz-cemil-aygen-mskqd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir evimiz olmalı 

Şöyle kutu gibi birşey

Dört duvarı

Penceresi

ve Penceresinde perdesi

Bizi gözlerden saklayan

Sonra iki sandalyemiz

Bir masamız olmalı 

Bir yatağımız

Enine boyuna yatacağımız

Dostlarımız olmalı candan

Tabiat..Ağaçlar çiçekler kuşlar

Sonra başbaşa yalnızlığımız

Bir evimiz olmalı

Bizi herkezden gizleyen 

Bizi birbirimize bağlayan

İçinde korkmadan seviştiğimiz

Kutu gibi bir evimiz

Bir penceresi bir kapısı

Bizi gözlerden gizleyen

Penceresinde perdesi

Bir evimiz olmalı 4 duvar

Kutu gibi birşey

Hani ikimize de

Bir ömür boyu yeter', 'Bir evimiz olmalı  Şöyle kutu gibi birşey Dört duvarı Penceresi ve Penceresinde perdesi Bizi gözlerden saklayan Sonra iki sandalyemiz Bir ma...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/evimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Defterim Dürülmüş! ! !', 'defterim-durulmus-saim-bastik-bw20b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüzüme gülmeyen yalan dünyanın

Düzeni düzensiz,  kurulmuşmu ne? 

Her gece gördüğüm tatlı rüyanın

Sebebi kötüye,yorulmuşmu ne? 

Ruhum,ondan ayrı,huzur bulmuyor

Hergün azaptayım,kimse bilmiyor

Şu garip gönlüme,sabah olmuyor

Geceler sabaha,darılmışmı ne? 

Ne kadar sürecek, böyle dargınlık

Vuslat çok uzakta,umudum kırık

Ayrılığın ardı,yine ayrılık

Yüreğim gurbete,sürülmüşmü ne? 

Dertler bırakmıyor,bir gün peşimi

Yüreğime akıttım gözyaşımı

Felek bu sevdaya,ister başımı

Katlime fermanlar,verilmişmi ne? 

Baharda kurumuş, çalı gibiyim

Yitirdim aklımı, deli gibiyim

Yaşıyorum amma, ölü gibiyim

Defterim ezelden, dürülmüşmü ne? 

20/01/2006', 'Yüzüme gülmeyen yalan dünyanın Düzeni düzensiz,  kurulmuşmu ne?  Her gece gördüğüm tatlı rüyanın Sebebi kötüye,yorulmuşmu ne?  Ruhum,ondan a...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/defterim-durulmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum', 'erzurum-zernisan-aydogan-a5el9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani bir sehir varya uzaklarda

Yazin unutulup kisin hatirlanan 

Hali ahvali hiç bir zaman sorulmayan

Lapa lapa kar yagdi o sehrin üzerine

Örttü tüm çirkinliklerin üzerini yine beyaz örtüsüyle

Hani bir sehir varya uzakta

Yazlari serin kislari soguk geçen

Dadaslarinin yüregini üsütmeye gücü yetmeyen

Lapa lapa kar yagdi o sehirin üzerine

Örttü tüm yalanlarin üzerini yine beyaz örtüsüyle

Hani bir sehir varya uzakta

Oy zamani hatirlanan sonrada unutulan

Kariyla buzuyla bas basa byrakilan

Lapa lapa kar yagdi o sehrin üzerine

Örttü unutulmuslugunun  üzerini yine beyaz örtüsüyle

Hani bir sehir varya uzaklarda

Dogu anadoluda dadaslar diyarinda 

Lapa lapa kar yagdi o sehrin üzerine

Örttü sahte vaadlerin üzerini yine beyaz örtüsüyle

                                             Erzurum / zernişan Aydoğan', 'Hani bir sehir varya uzaklarda Yazin unutulup kisin hatirlanan  Hali ahvali hiç bir zaman sorulmayan Lapa lapa kar yagdi o sehrin üzerine Ör...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/erzurum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğimin Gözleri Güzel Sözleri', 'sevdigimin-gozleri-guzel-sozleri-yusuf-onder-bahceci-i4hpv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Derdimin dermanı, gönül fermanı,

Aşk bağının gülü, hasat zamanı,

Kalbimde saklarım özlem, emanı,

Sevdiğimin gözleri, güzel sözleri.

Gözlerinde yaşlar, mahsun bakışlar,

Benim sevdam yüce kalbimde kışlar,

Şimdi kaldım Gülüm yuvasız kuşlar,

Sevdiğimin gözleri, güzel sözleri.

Sevgisiyle yanan kalbi bilmiyor,

Ona yandım senede bir gelmiyor,

Gönül verdim, heder oldum görmüyor,

Sevdiğimin gözleri, güzel sözleri....', 'Derdimin dermanı, gönül fermanı, Aşk bağının gülü, hasat zamanı, Kalbimde saklarım özlem, emanı, Sevdiğimin gözleri, güzel sözleri. Gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdigimin-gozleri-guzel-sozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit Öyle Akşam ki', 'vakit-oyle-aksam-ki-engin-akbaba-lyfwv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'vakit öyle akşam

öyle akşam ki

bağırsan duyacağım...

ellerin küçücük

dudağın uzak

bir tebessüm kıvrılsa öpeceğim

başını eğmesen

yüzüme değsen

''seviyor'' diyeceğim

beni gecenin bağrına çarpma

dikenli tellere vurma kendini

b

ı

r

a

k.....................

gölgelerin boyu uzasın...

aslı, yağmurlar biriktir

içmeye geleceğim.

ocak yirmisi ikibinaltı..

antalya', 'vakit öyle akşam öyle akşam ki bağırsan duyacağım... ellerin küçücük dudağın uzak bir tebessüm kıvrılsa öpeceğim başını eğmesen yüzüme değse...', ARRAY['Türk Edebiyatı','Şiir','Engin Akbaba']::text[], 8.5, '{"poet":"Engin Akbaba","poet_slug":"engin-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vakit-oyle-aksam-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatması Güç!', 'anlatmasi-guc-arzu-gulucudur-kpzq5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünüm; tutamadığım sözlerde kaldı

Gölgelere meyilli yarınım

Tutsaklığına esir sözlerim

Vurgun düşler kelimelere

Prangalı sevdam 

Sevdam....

UMUDUM

Sevdam...

HASRETİM

Sevdam...

ÖZGÜRLÜĞÜM

Sevdam...

TANECİĞİM

Anlamlandıramadığım anlamlarda saklı

Anlatamasam da anladığın

Dile gelmeyen 

Gözden düşmeyen...

Tek dokunuş...

Sevdam...

GEÇMİŞİM

Sevdam...

BUGÜNÜM

Sevdam...

YARINIM

Ve sevdam....

DOYAMADIĞIMSIN...', 'Dünüm; tutamadığım sözlerde kaldı Gölgelere meyilli yarınım Tutsaklığına esir sözlerim Vurgun düşler kelimelere Prangalı sevdam  Sevdam.... ...', ARRAY['Türk Edebiyatı','Şiir','Arzu Gülücüdür']::text[], 8.5, '{"poet":"Arzu Gülücüdür","poet_slug":"arzu-gulucudur","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/anlatmasi-guc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yak Yık', 'yak-yik-murat-demir-n3emf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kattın karştırdın ne varsa bizde

Şu sevdadan yana şu elimizde

Bak bir şey kalmışsa yüreğimizde

Affetme onu da affetme yak yık

Köşeden, bucaktan kolaçan edip

Dıştan hançerleyip içten kahredip

O da yetmiyorsa ateşe verip

Affetme sakın ha affetme yak yık

Olanlar bu kadar oldu mademki

Ne yapsan da bana üzülmem bil ki

Aşkından ölenin olsamda ilki

Affetme düşünüp affetme yak yık

Ben bilerek giydim abdal gömleği

Kırıldı sevdamın çanak çömleği

Sana ben yetmezsem, cemi cümleği

Affetme bakıpta affetme yak yık

Ben bunu hak ettim seni sevince

Beden neye yarar can devrilince

Ne zaman aklına Murat gelince

Affeme seni de affetme yak yık', 'Kattın karştırdın ne varsa bizde Şu sevdadan yana şu elimizde Bak bir şey kalmışsa yüreğimizde Affetme onu da affetme yak yık Köşeden, bucak...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yak-yik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi git', 'hadi-git-zernisan-aydogan-gv75l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşte geldi ayrılık saati

Bu gün yaşlarla ağlamak yok

Çektiğim acıya gülüyorum işte

Durma hadi git

Yalanmış ettiğin yeminler verdiğin sözler

Tükenirmiş bir gün en büyük sevgiler

Rüyaymış yaşanılan en güzel günler 

Durma hadi git

Bukadar basitmiydi gönüle girmek

Maziyi bir anda tarumar etmek

Nekadar kolaymış hoşcakal demek

Durma hadi git', 'İşte geldi ayrılık saati Bu gün yaşlarla ağlamak yok Çektiğim acıya gülüyorum işte Durma hadi git Yalanmış ettiğin yeminler verdiğin sözler ...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hadi-git-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine yaparsın', 'kendine-yaparsin-yasar-ali-kamsiz-hroy6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendine yaparsın askım

Aşkım deme bana

Kendin ile yaşarsın aşkım

Aşkını soyleme bana

Ben bır yalancı dervisim

Ne tanrıyla ne seytanla benim işim

Aşkı benle degil

Aşkı benden öğreneceksin

Sakın dileme aşkım

Ne tanrıdan ne şeytandan 

Çünkü gelmeyecegim Aşkım

Ne ezelden ne ebedden

Beni sevme Aşkım

Sevgim kadar sevemezsin

Benle yanma aşkım

Aşkmla kor degil kör olursun', 'Kendine yaparsın askım Aşkım deme bana Kendin ile yaşarsın aşkım Aşkını soyleme bana Ben bır yalancı dervisim Ne tanrıyla ne seytanla benim ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Ali Kamsız']::text[], 8.5, '{"poet":"Yaşar Ali Kamsız","poet_slug":"yasar-ali-kamsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kendine-yaparsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Sevdalar', 'buyuk-sevdalar-melih-baki-ef7cf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son zamanların 

En büyük sevdalarını,

Yaşıyorum ben.

Sokaklara indim

Kapı kapı.. dolaştım

Acıların sevdaların 

Girmediği ev aradım

Bulamadım.! 

Kendimi Dağlara vurdum

Ferhatı gördüm.

Koştum çöllere

Dolaşırken Mecnundan

Keremi sordum..

Son zamanların

En büyük sevdalarını

Yaşıyorum ben.

Ay''a..Yıldızlara gittim

Şirin''i,Aslı''yı,Leyla''yı sordum

Kor Ateşler içinde

Yanan yürekleri

Güneşte gördüm..

Son zamanların

En büyük sevdalarını

Yaşıyorum ben..

En çok bahar kokulu

Kadınları sevdim.! 

Buğulu gözlü kadınları

Bir başka sevdim..

Beni yakan her güzeli

Aslı,Şirin,Leyla  sandım.! 

Son zamanların 

En büyük Sevdalarını

Yaşıyorum ben..

Ozanlara,şairlere

Eli kalem tutan  kimi.

Gördüysem..

Acının ilacını sordum.! 

Ateş yağmurundan

Kavrulmuş gözlerinde

Kendi yansımamı gördüm..

Son zamanların

En büyük sevdalarını

Yaşıyorum ben..

Dağa,taşa,karıncaya

Yaşayan her varlığa

Aşık oldum..! 

Çılgınlar gibi sevdim

Büyük aşklar,ihanetler yaşadım.! 

Son zamanların

En büyük sevdalarını

Yaşıyorum ben..

2005/Adana', 'Son zamanların  En büyük sevdalarını, Yaşıyorum ben. Sokaklara indim Kapı kapı.. dolaştım Acıların sevdaların  Girmediği ev aradım Bulamadım...', ARRAY['Türk Edebiyatı','Şiir','Melih Baki']::text[], 8.5, '{"poet":"Melih Baki","poet_slug":"melih-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/buyuk-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Kaçayım...', 'nasil-kacayim-nurdane-diken-ingfl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendimden hep kaçarım yâri nasıl tutayım? 

Ahdımı hep tutarım seni nasıl satayım? 

Yürekte mıh olmuşsun pası nasıl atayım? 

Bin doktor gelse de, deva bulmaz dertlerim.

Her köşede sen varsın gölgeler oynaşıyor

Gecelere sinmişsin duygular oynaşıyor

Ahû-zarım olmuşsun kalp dertle kaynaşıyor

Doktor ilâç olsa da, derman tutmaz dertlerim.. 

Tepede kardelensin ulaşmam çok zor sana

Avuturum kendimi ağlarım yana yana

Hasretin yaktı beni kül oldum yana yana

Bin defa söz söylense, anlamaz ki dertlerim..

Mutluluk düşlerimde hergün seni yaşayım 

Sıra dağlar önümde dağı nasıl aşayım 

Derman bulmaz dizlerim sana nasıl koşayım 

Bir kerre gelsem sana inan uçar dertlerim.', 'Kendimden hep kaçarım yâri nasıl tutayım?  Ahdımı hep tutarım seni nasıl satayım?  Yürekte mıh olmuşsun pası nasıl atayım?  Bin doktor gelse...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasil-kacayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüksün küçüğüm', 'kucuksun-kucugum-zernisan-aydogan-hlxnr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nekadar zor şeydir şu ayrılık

Küçüksün küçüğüm bilemezsin sen

Anandan babandan uzakta olmak

Zor iştir küçüğüm bilemezsin sen

Dost olarak yaklaşır yüzüne gülerler

Sırrını söylesen un eder elerler

Zevk vermiyor zaten sahte sevgiler

Anlamazsın küçüğüm bilemezsin sen

Akrabadan yana şansım olmadı

Kimi yalanladı kimi horladı

İşleri düşünce beni hatırladı

Zor iştir küçüğüm bilemezsin sen

Beni hayata sım sıkı bağlayan

Benimle gülüp benimle ağlayan

Dargünümde her zaman yanımda olan

Babandı küçüğüm bilemezsin sen', 'Nekadar zor şeydir şu ayrılık Küçüksün küçüğüm bilemezsin sen Anandan babandan uzakta olmak Zor iştir küçüğüm bilemezsin sen Dost olarak yak...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kucuksun-kucugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol - Şeytan hacca mı geldi?', 'yol-seytan-hacca-mi-geldi-mehmet-coban-nmoij', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zehir oldu bayramım 

Çok acıydı duyduklarım

Bu gün Mina’da 

Şeytan taşlarken

345 kişi öldü

Geçen yılda 

850 kişi ölmüştü

Maalesef bizim 

Hacılarımızdan da

………....… kişi öldü! ..

Bayram ziyaretine gelenler

Şöyle bir oh çektiler

Şükür bizden yok dediler

Bizim akrabalarda aynen

İyi ki,  bizden de yok dediler

Onlar için bir haberdi

2006 yılı 345 kişi ölmüş

2005 yılı 850 kişi ölmüş

Ne çıkar? 

Bizim ülkemizden 

Bizim şehrimizden

Bizim ailemizden 

Değilse ölenler

Ne çıkar? 

Ölenler Müslüman’salar

Ölenler kadınsalar

Ölenler yaşlıysalar

Ölenler Çocuksalar

Yeter ki,

Ülkemizden olmasın

Şehrimizden olmasın

Ailemizden olmasın

Akrabalarımızdan olmasın

Allah aşkına! ..

Bu ne biçim mantık? ! ……………

Öldürmenin yasak

Amacın Allah’a tapmak

Olan yerde, 

Kutsal vadide

Allah’ın evinde

İnsanlar öldü

Ölenler insandı

Ölenler yaşlıydı

Ölenler çocuktu

Ölenler kadındı

Ölenler din kardeşimizdi! ..

Ya ölümlerine sebep olanlar? ....

Güya, Müslüman’dılar

Güya, insandılar

Güya, itaatkârdılar

Güya, güvenilen insandılar

Güya, ibadetkardılar

Güya, günahtan arındılar

Ama? ! ...

Sevap çıkarı adına

Kıydılar dindaşlarına

Taşlıyorlar Mina’daki şeytanı

Taşlayamıyorlar kalplerindeki şeytanı

Sığınmışlar sembollerin ardına

Düşmüşler şuursuzca sevap uğruna

Allah’ın emretmediği bir ibadeti

Gönülden kopan bir nafile töreyi

Yaparlarken işliyorlar cinayeti

Yok, ediyorlar kalplerinde olmayan dini

Dur diyen yok

Tedbir alan yok! ...

Din adına boy gösterenler

Din adına susmayan diller

Din adına kitapları süsleyenler

Hangi emir? 

Hangi ibadet? 

İşlenirken döner cinayete? 

İnsan hayatı tehlikeye girince,

Ruhsat olup kalkar farzlar niye? 

Din adına gelen törelerle 

Her yıl insanları öldürmek niye? 

Duymuyor musunuz Allah’ı? 

Okumuyor musunuz kitabı? 

Demiyor mu Allah kitabında

Hükmettiğime uymayanlar

Kâfirdir, zalimdir, fasıktır diye? 

Arar durursun,

Kafiri, zalimi, fasıkı başka yerde! ..

Din adına ibadet ederken,

Allah’ın indirdiğiyle hükmetmezsin niye? 

Duy şeytan ne diyor? 

''Ben o inananların

Arkalarından önlerinden geleceğim

Kan damarlarından gireceğim

Düşüncelerinde hayallerinde gezeceğim

Her kötülüğü allayıp pullayacağım

Amellerindeki imanı söndüreceğim

Kötü amellerini süslü göstereceğim

Bir, bir hepsini azdıracağım

Allah’ın yolundan saptıracağım

Kendime dost ve arkadaş yapacağım''

Ey şeytan taşlayanlar,

Taşlarken ölümlere sebep olanlar! ..

Şeytan içinizde sizinle beraber

Hacca gelmiş ne haber? ! ..........................................

Şeytanla haccınız mübarek ola,

Unutmayın çıkacaksınız hesaba! ...

20.01.2006-İzmir', 'Zehir oldu bayramım  Çok acıydı duyduklarım Bu gün Mina’da  Şeytan taşlarken 345 kişi öldü Geçen yılda  850 kişi ölmüştü Maalesef bizim  Hac...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":103,"source_url":"https://www.antoloji.com/yol-seytan-hacca-mi-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydi O Günler!', 'neydi-o-gunler-sahin-kars-2skfl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Evimizdi, köyümüzde yaşardık,

Koyunu kuzuyu yaydık biz yaydık.

Beygirleri arabaya koşardık,

Neyidi o günler, neydik biz neydik! 

Bahar vardı, yazlar vardı orada,

Bizler vardık, sizler vardı orada.

Dinlenecek sözler vardı  orada,

Burada tersini duyduk biz duyduk.

Özlem gidermeye yılda bir geldik,

Değer değmezine tarla, ev aldık.

Her türlü gülüşü samimi bulduk,

Sağlam basamadık kaydık biz kaydık.

Ömür verip döderirken çarkları,

Göremedik aradaki farkları.

Alın teri yeşil yeşil markları 

Getirip getirip saydık biz saydık.

Burda zengin olmak idi meylimiz,

Bekâr yola geldi, saptı evlimiz,

Çabuk geri dönmekti ya kavlimiz,

Şimdi sözümüzden caydık biz caydık.

Şahin''leri, defterlerden siliniz,

Bunca zaman sorulmadı halimiz.

Kalmayınca tutunacak dalımız,

Gayrı Avrupa''ya uyduk biz uyduk.', 'Evimizdi, köyümüzde yaşardık, Koyunu kuzuyu yaydık biz yaydık. Beygirleri arabaya koşardık, Neyidi o günler, neydik biz neydik!  Bahar vardı...', ARRAY['Türk Edebiyatı','Şiir','Şahin Kars']::text[], 8.5, '{"poet":"Şahin Kars","poet_slug":"sahin-kars","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/neydi-o-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ha Bittin Ha Bitiyorsun İçimde', 'ha-bittin-ha-bitiyorsun-i-cimde-meram-yalinizoglu-xwohm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman azaldı, tükendi yarınlar.

Geçip gidiyorsun ömrümün bir kenarından

Sürte sürte dikenlerini

Parçalayarak kalbimi

Tik takları azalıyor, yavaşlıyor

Duvarda senin hediye ettiğin saatin

Ben deki sende duruyor ama

Parçalarını düşürüyor tiktaklar

Bendeki seni tüketiyorsun

Kalbimdeki seni törpülüyorsun

Dökülüyor tozların yavaş yavaş

Bitiyorsun artık bende

Siliniyor suya düşmüş resim gibi

Aşkın kalbimden

Yanıklarımı artık hissetmiyorum sana.

Uyuşturuyor beni

Kalbimde açtığın yara

Beynim duruyor

Az kaldın

Ha bittin ha bitiyorsun

Damlaların dökülmesi hızlandı

Hatta büyük parçalarını

Hızla döküyorsun artık

Son parçalarında gitti gidiyor

Bittin artık sen

BİTTİN! ! ! !', 'Zaman azaldı, tükendi yarınlar. Geçip gidiyorsun ömrümün bir kenarından Sürte sürte dikenlerini Parçalayarak kalbimi Tik takları azalıyor, y...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ha-bittin-ha-bitiyorsun-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek nefesim', 'tek-nefesim-meram-yalinizoglu-afbxd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen şimdi yatağında

Mışıl mışıl uyuyorsun

Bense her zaman ki gibi

Seni düşünüyorum

Kimbilir? 

Ne ruyalar görüyorsun

Varmıyımdır acaba bilmiyorum

Gördüğünü farzettiğim ruyada

Oysa ben her an

Hep seninle dolu ruyalar görüyorum

Ayıkken de uyurken de

Sarılıyorsun şimdi belki

Yanındaki nefese

Ben se her zamanki gibi

Tek nefesim...', 'Sen şimdi yatağında Mışıl mışıl uyuyorsun Bense her zaman ki gibi Seni düşünüyorum Kimbilir?  Ne ruyalar görüyorsun Varmıyımdır acaba bilmiy...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/tek-nefesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırla', 'hatirla-yavuz-dogan-udj74', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey tövbeye tenezzül etmeyen büyük kâfir 

Ey gönül sarayımdan kovulmuş tek misafir. 

Ey sabahın düşmanı, gecenin en zifiri 

Ey ömrün yıkandıkça simsiyah olan kiri. 

Sana son mektubum bu ister oku ister yak 

İster gönlüne dert bil ister mazide bırak.. 

Hatırla, ne çok şeydin kırılmış yüreğimde 

Sevdaya tövbe etmiş, darılmış yüreğimde. 

Hatırla, ne çok sevdim gözlerinin rengini 

Teninin kokusunu, sesinin ahengini. 

Hasrete isyan etmiş sevdalı sesimdin sen 

Aşımdın, ekmeğimdin, en son nefesimdin sen. 

Sen en olmaz duama “âmin” dediğim andın 

Sen göğüs kafesimde taşıdığım tek candın. 

Karanlıkta göz kırpan küçük bir yıldızdın sen 

Bir gülüşle gönlümü çalmış bir hırsızdın sen. 

Buz tutmuş düşlerimin kor olmuş ateşiydin 

Sen soğuk bir sabahın sımsıcak güneşiydin. 

Mutlu düşler getirmiş bir kuş kanadıydın sen 

Her anı hasret kokan ömrün inadıydın sen. 

Sen gönlümün gözünü kör eylemiş güzeldin 

Sen yitik bir ormanda rastladığım gazeldin. 

Kararmış bir kandile yüklenmiş anlamdın sen 

Sırrı kendine mazhar kırılmış aynamdın sen. 

Yorulmuş bir bedenin gördüğü son rüyaydın 

Sislerin arkasından doğmuş bir dolunaydın. 

Hatırla, gittin sonra sol yanımı alarak 

Göğsümü öksüz koyup cananımı çalarak. 

Gittin, mutlu bir günün sabahsız gecesiyken 

Gönlümü saray bilmiş sevdanın ecesiyken. 

Sevabı günah diye yazan oldun gönlüme 

Güllerimi kurutup hazan oldun gönlüme. 

Bin yerinden kırarak bükülmez bileğimi 

Mahşere erteledin düşümü, dileğimi. 

Hatırla, and içmiştim caymadım, tuttum bu kez 

Kokunu, gözlerini; seni unuttum bu kez. 

Artık başka gözlerde başka düş görür oldum 

Artık başka bir yürek peşinde yürür oldum. 

Sevda önüne geçti gözün çağlamasının 

Mızrabı tele küstü hasret bağlamasının. 

Su yandı, ateş söndü; yemyeşil artık çöller 

Aşk bitti mazi oldu dikensiz kaldı güller. 

Korkuların korktuğu karanlık düşsün artık 

Gözyaşıyla süslenmiş mahzun gülüşsün artık. 

Müebbet bir sevdayı kurşuna dizensin sen 

Boy vermiş filizleri hesapsız ezensin sen. 

Sen artık yüreğimin nefretle atışısın 

Sen erken doğmuş günün zamansız batışısın. 

Sen ömrün iflah olmaz en devasız derdisin 

Sen koca kâinatın en büyük namerdisin! 

Sana son mektubum bu ister oku ister yak 

İster gönlüne dert bil ister mazide bırak… 

youtube: www.youtube.com/watch? v=LbmCXSt6HGs', 'Ey tövbeye tenezzül etmeyen büyük kâfir  Ey gönül sarayımdan kovulmuş tek misafir.  Ey sabahın düşmanı, gecenin en zifiri  Ey ömrün yıkandık...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Doğan']::text[], 8.5, '{"poet":"Yavuz Doğan","poet_slug":"yavuz-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/hatirla-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Şiirleri', 'cocuk-siirleri-mehmet-ayhan-gunaydin-8qayd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'DÜNYA HALİ İŞTE

Dün gece ben yatarken,

Üzerimi açmışım bilmeden.

Nasıl da üşümüştü her yanım,

Yağmura tutuldum sandım.

Annemdi gelip, hafifçe örten.

M. Ayhan Günaydın.

    21 Aralık 2005 

          Ankara', 'DÜNYA HALİ İŞTE Dün gece ben yatarken, Üzerimi açmışım bilmeden. Nasıl da üşümüştü her yanım, Yağmura tutuldum sandım. Annemdi gelip, hafifç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cocuk-siirleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-mikdat-bal-usrp6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yükseklere çıkıp eyledin seyran 

Her şeyi içine sığdırdın gönül

Vefasız bir yâre olunca hayran 

Bana elemleri yığdırdın gönül

Sen bana keder mi çile mi oldun

Dikene mi aşık güle mi oldun

Bırak şu yakamı köle mi oldun

Boynumu toprağa eğdirdin gönül

Paramparça ettin kalp pare pare

Bu öyle bir dert ki bulunmaz çare

Kaptırdın kendini gurbetli yâre

Hasret oklarını yağdırdın gönül

Ne rengine baktın ne de tipine

Sarıldın bir yarin sevgi ipine

Beni alçatarak yerin dibine

Başını göklere değdirdin gönül', 'Yükseklere çıkıp eyledin seyran  Her şeyi içine sığdırdın gönül Vefasız bir yâre olunca hayran  Bana elemleri yığdırdın gönül Sen bana keder...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-135-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Bilinmeyenli Sevda Çukuru', 'i-ki-bilinmeyenli-sevda-cukuru-caglar-demir-elb7y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bulamıyorum seni

veya

Hayatımın nersine koydum hatırlamıyorum

Bazen tam sevilesi yerindesin yüreğimin

Bazen baktılça sızlayan bir bıçak yarası...

İki bilinmeyenli bir sevda çukurundayım

Hem elim varmaz dokunmaya eline

Hem nefes olmaz sensiz soluduğum

Kimseye açılmaz acayip bir hüzündür bu 

Hem zehir zukkum 

Hem tadından yenmez....', 'Bulamıyorum seni veya Hayatımın nersine koydum hatırlamıyorum Bazen tam sevilesi yerindesin yüreğimin Bazen baktılça sızlayan bir bıçak yara...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Demir']::text[], 8.5, '{"poet":"Çağlar Demir","poet_slug":"caglar-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iki-bilinmeyenli-sevda-cukuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulmaca', 'bulmaca-asli-evrensel-5bgv7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bulmacanın harflerinde

rastladım sana

adının harflerinde anılar

soldan sağa', 'bulmacanın harflerinde rastladım sana adının harflerinde anılar soldan sağa...', ARRAY['Türk Edebiyatı','Şiir','Aslı Evrensel']::text[], 8.5, '{"poet":"Aslı Evrensel","poet_slug":"asli-evrensel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bulmaca-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orta Yaşım', 'orta-yasim-cemil-aygen-v08y6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gençliğimin Son günlerindeyim 

Orta yaş başlangıcı

43 yaşındayım

Gülmeyin

Cahit Sıtkı Tarancıya mahsus o

Yaş OTUZBEŞ yolun yarısı eder

43 Yaşın nesi var 

Ne günlerdi o günler

Deniz kenarında

Fırtına gibi koşup nefes açtığımız

Dalgalara bakıp bakıp

Dalga geçtiğimiz

Hani sabaha kadar uyumadan

Uykuyu hatırlamadan

Kafa çektiğimiz

Hızlı yaşadığımız

Deli dolu günler

Birbir geçtiler

Şimdi orta yaşı bulduk

Hani 43 ün biraz üstünde

Ama nefes açamadığımız

Fırtına gibi koşamadığımız

Zamanlarda bile

Düşünüp düşünüp hamle yapmaktayız ya

Yaşamaktayız be

Dolu dolu yaşamı özleyerek yaşamaktayız 

Hayali bile Cihana değer 

Dediğimiz günlerimiz var ya

O da Yeter', 'Gençliğimin Son günlerindeyim  Orta yaş başlangıcı 43 yaşındayım Gülmeyin Cahit Sıtkı Tarancıya mahsus o Yaş OTUZBEŞ yolun yarısı eder 43 Ya...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/orta-yasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Deyip Ağlıyordun Sen', 'seviyorum-deyip-agliyordun-sen-yusuf-onder-bahceci-zsmg8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel gözlerinde hasreti gördüm,

Hergece rüyamda, rüyamda gördüm,

Saçlarını çözüpte, yeniden ördüm,

Seviyorum deyip ağlıyordun sen.

Hayaller kurup gülüyordum ben,

Elinde güllerle geliyordun sen,

Beni çok sevip ölüyordun hem,

Seviyorum deyip ağlıyordun sen.

Hasret çeken gönül hergün iniler,

O seni hiç sevmedi ki dediler,

Gelmiyor dediler, yemin ettiler,

Seviyorum deyip ağlıyordun sen.

Gördüğüm rüyalar rüya değilmiş,

O beni sevmiş ama ellere gitmiş,

O kardeşim değil sevdiğim demiş,

Seviyorum deyip ağlıyormuşsun....', 'Güzel gözlerinde hasreti gördüm, Hergece rüyamda, rüyamda gördüm, Saçlarını çözüpte, yeniden ördüm, Seviyorum deyip ağlıyordun sen. Hayaller...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seviyorum-deyip-agliyordun-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-necmiye-sarpkaya-dpjy3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni Seviyorum 

 	

Seviyorum düşünmeyi 

Düşündükçe sana yaklaştığımı 

Zümrüt tepeler aştığımı 

İçimdeki bulutların kümelendiğini 

Düşsel yağmurlara dönüştüğünü 

Görüyorum 

Seviyorum yürümeyi 

Sana ulaştırıyor her adım 

Seni hatırlatıyor her nefes 

Işıl ışıl gözlerim 

İsmini fısıldarken dudaklarım 

Seviyorum gülmeyi 

Seviyorum yağmurları 

Her damla sen oluyor içimde 

Dalgaları sütliman denizleri 

Nilüferleri yakamozları 

Seviyorum 

Seviyorum gölleri 

Sakin ve asude 

Pırlanta suları seviyorum 

İçini yakarken mecnunun 

Dışını da yakan kavuran çölleri 

Leyla vurgunu mecnuni çölleri 

Seviyorum 

Seviyorum kır çiçeklerini 

Hercai menekşeleri 

Utangaç gelincikleri 

Masum papatyaları 

Asil orkideleri seviyorum 

Yaprakları toprakları 

Işıltılı nazlı nazlı yıldızları

Gök kubbeyi yerküreyi 

Arz’ı okyanusları 

Kutupları seviyorum 

Gökyüzünü seviyorum 

Kainatı donatan seni hatırlatan 

Sana yaklaştıran semayı seviyorum 

Seviyorum hayaller kurmayı

Seninle dolu hayalleri seviyorum 

Mevsimlerin incisi baharı 

Haşin kışları 

Uysal yazları seviyorum 

Seviyorum heybetli mağrur dağları 

Dümdüz mütevazı ovaları seviyorum 

Seni anlatan seni hatırlatan 

Senden gelen sana varan 

Bütün yolları bütün gizleri 

Seviyorum seni seviyorum

Necmiye Sarpkaya', 'Seni Seviyorum   	 Seviyorum düşünmeyi  Düşündükçe sana yaklaştığımı  Zümrüt tepeler aştığımı  İçimdeki bulutların kümelendiğini  Düşsel yağ...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/seni-seviyorum-328-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Nasıl Yıktılar', 'beni-nasil-yiktilar-yusuf-onder-bahceci-mbyjy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni nasıl sevmiştim,

Ne hayaller kurmuştum,

Nasıl mutlu olmuştum,

Beni nasıl yıktılar.

Türlü yalan söylediler,

Seni sevmez dediler,

Sana gelmez dediler,

Beni nasıl yıktılar.

Nasıl inandım onlara,

Ucu türlü yalanlara,

Ben kanmazdım onlara,

Beni nasıl yıktılar.

Şimdi hergün ağlıyorum,

Neden, neden diyorum,

Seni sevdim seviyorum,

Beni nasıl yıktılar...', 'Seni nasıl sevmiştim, Ne hayaller kurmuştum, Nasıl mutlu olmuştum, Beni nasıl yıktılar. Türlü yalan söylediler, Seni sevmez dediler, Sana ge...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-nasil-yiktilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-049 Duvarların arkası', 'ub-049-duvarlarin-arkasi-mehmet-coban-w84gt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duvarlarım var benim

Özü iki tanedir bilirim

Biri tabularım

Diğeri dogmalarım

Doğarken seçmediğim

Doğum yerim, memleketim

Annem, babam, toplumum

Çevrem, akrabalarım

Irkım, kabilem insanlarım

Ailemden öğrendiklerim

Okullardan öğrendiklerim

Çevremden öğrendiklerim

Öğretilen, inançlarım, yaşantım, 

Ve, 

Aklım, mantığım, hayallerim

Duygularım, hislerim, ideallerim

Beklentilerim, beklentilerim, beklentilerim! ..

Hepsi,

Malzemesidir duvarlarımın.

Sarılırlar bana,

Sarılırlar hayatıma,

Sarılırlar geçmişime,

Sarılırlar geleceğime! ...

Yumak olurlar

Tabulaşır ve dogmalaşırlar

Ve beni, 

Ve seni, 

Ve bizi,

Hapsederler arkasına! ..

Çıkarmazlar bizi dışarıya,

Karıştırtmazlar insanlara! ..

Bir mantık kurarlar, 

Atlarsa başkaları bu tarafa,

Dönüşürler arkadaşa dosta.

Kalırlarsa öbür tarafta,

Uzaktırlar arkadaşlığa dostluğa.

Şartı budur duvarlarımın,

Ya bu tarafta, ya öbür taraftasın! ..

Kapıları yoktur açamazsın,

Sapıtmadan asla yıkamazsın! ..

Bir an için düşünmem

Zenginliktir varlığım demem

Paylaşmayı hiç düşünmem

Almadan asla veremem

Karşılığı vardır yaptığımın

Karşılığı vardır her adımımın

Böyle olunca, 

İçim başka 

Dışım başkadır

Sözüm insanca

Davranışlarım …………dır! ...

Niyet etsem ki insanlaşmaya

Hep çıkar duvarlar karşıma! ..

Önce benim duvarlarım salmaz dışarıya

Sonra çarpar dururum karşıdaki duvarlara! ..

Sormayın,

Bir zordur ki insanlık yolu

İnsanlık kendi duvarlarıyla dolu

Seslensem, 

Aşalım duvarları

Paylaşalım arkada olanları

Katalım birbirimize içimizdekileri

Açalım bütün açıklığıyla kalbimizi

Yüksek binalar dikelim

Duvarlarımızın malzemeleriyle

İnsanlık değerlerini yükseltelim

Bizde var olan benliğimizdekilerle! ..

Bütün duvar malzemelerimizi

Saygı malzemesine dönüştürelim

Paylaşalım hayallerimizi

İçimizdeki bencilliği söndürelim! ..

20.01.2006-İzmir', 'Duvarlarım var benim Özü iki tanedir bilirim Biri tabularım Diğeri dogmalarım Doğarken seçmediğim Doğum yerim, memleketim Annem, babam, topl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/ub-049-duvarlarin-arkasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlarım Hep Hayret Eder', 'dostlarim-hep-hayret-eder-yusuf-onder-bahceci-k2ojc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel kendini çekme naza,

Belki çıkmam bahar, yaza,

Ettiğim dualarla niyaza,

Dostlarım hep hayret eder.

Sen kendini etme heder,

Yollar hep uzayıpta gider,

Benim kalbim seni sever,

Dostlarım hep hayret eder.

Neden böyle sevdin derler,

Neden böyle yandın derler,

Türlü sitemler, söz ederler,

Dostlarım hep hayret eder.

Kim ne derse desin bana,

Benim kalbim yanmış sana,

Senden gelen güzel bana,

Dostlarım hep hayret eder....', 'Gel kendini çekme naza, Belki çıkmam bahar, yaza, Ettiğim dualarla niyaza, Dostlarım hep hayret eder. Sen kendini etme heder, Yollar hep uza...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dostlarim-hep-hayret-eder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Kadin', 'en-guzel-kadin-huseyin-avdic-2d6yt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En Güzel Kadin

Kadinlar icinde en güzel kadin, ibadet eden kadindir.

Onlarin da en güzeli, iyi huylu ve gecimli olandir.

Berlin, Ocak 2006.', 'En Güzel Kadin Kadinlar icinde en güzel kadin, ibadet eden kadindir. Onlarin da en güzeli, iyi huylu ve gecimli olandir. Berlin, Ocak 2006....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/en-guzel-kadin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nevroz', 'nevroz-adullah-korkmaz-b6bo1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göç mevsimiydi; 

kuşlar kendi içlerine göçüyorlardı.

Onlara bu dünyada gidecek daha 

iyi bir yer olmadığını düşündüren

neydi. Yoksa yazıGöç mevsimiydi  ve hiçbir şey o kadar 

sağlam değildi. Tutunmak aptallık olurdu.

Ya tuttuğun elinde kalırdı ya da 

elin tuttuğunda. İnsanların en büyük 

arzusuydu bütün kalmak. Artık 

intihar hükmündeydi kıpırdamak.

Felçli bedenlere imreniliyordu.

Dilimin altında başlayan yangın 

dilim hariç tüm bedenimi yakmıştı. 

Artık bozuk bir 

dondurma bile hayalim. 

8220; Doğa kadar kusursuz  olamadık biz 

yaratıcılarımız aynıyken de8221; . Yankılanabileceğim 

bir boşluk bulamadan boşalacağım diye 

ölesiye korkuyorum. 8220; Onu da bozduk8221; .

Hazreti ve evet artık hazretim; zaman 

o dalı kemiren siyah-beyaz 

iki fareden farksızdı. Bense o dala 

hiç tutunamadan düşmüş gibi 

hissedecektim kendimi. Ejderha bir 

görünüp bir kayboluyordu. Fareler hiç 

doymaz mı ki. Dehşetim kuyuyu doldurdu. 

Işıkları yakan ele 

sonsuza kadar minnettarım.

Ve artık kullanmaktan vaz 

geçtiğim bir kelime oldu aşk.

İçimdeki boşluğu uzaya kustum 

esir oldum süpernovalara. 

YAZDIKÇA ÇOĞALIYOR KENDİ İÇİMİ DOLDURUYORDUM.

Herkesin bildiği ama 

herhangi bir kelimenin herhangi bir 

başına ya da sonuna ekleyemediği 

ekler var mıdır. Varsa neyi çağrıştırır. 

Atmaya kıyamadığın tohumların elinde mi 

çürüyecek.hurafedir inığın. Büyü-

Yecekler. Ama taşıyamayacaksın bu 

sefer.



Yağmur yardımcı olur gitme eylemine 

karar vermeye. Dindiği zamır zaten 

gitmek vakti benim için. Lazım olmayan 

olmayacak olan onca şeyi tıkarım 

çantama ağırlık yapsın diye. Beni

ilgilendiren çamurdur zira. Ne kadar 

derine bırakırsam izlerimi o kadar

geç dolar içleri. Yağmur-çamur ikilemini 

sevmişimdir hep. Gitmek-kalmak ise 

bitirmiştir beni. İzlere güvenirim başlamak

için. Çıplak ayakla yürünür8230; 

Evet bir hataydı sıfırdan 

türetilmiş. Dünyanın sonu değil 

ama ya aynı hatayı kıyamet günü de yaparsam.

İzleri yok olmaz ki. Çürümüş patatesleri baskı 

altına almak ilk öğretilmişti bize.

Sezar8217; ın sırtındaki bıçakla çizerdik desenlerimizi. 

Boyamasak da sayfalar dolardı.

 Boşalırdı. Öteki 

BENSE YAZDIKÇA ÇOĞALIYORDU

 ne kadar çoğalsa da kendi içini 

dolduramıyordu. Bir hummayla çizilmişti buğuların

arkasına manzaralar. Elimi kaldırıp 

camı silmeye mecalim yok. Vardı. 

Nefes almaya kullım.

Her kapalı şeklin içine 

kim bırakmıştı hiç üşenmeden

açıları. Elimin altında bir uzay 

olma fikri küçümsemeye itiyordu 

bizi. Sanki bu dünyadan başka 

bir dışarıya çıkabilmiş gibi.

Belki geri dönmezdik o zaman.

Belki.

Annemle beraber içinde ayları 

doldururken tek sevgilim olan göbek bağımdı. 

Oksijen ciğerlerimi yakarken 

o veya tokat yüzünden ağlamadım ben 

bağım yerinde yoktu. Hesabını sordum hemşireden 

çöpü gösterdi. Gittim ama diğerlerinden ayıramadım.

 İnsanların nereye kadar saçmalayacağını o zaman anladım.

Şimdiki sevgililer ne? Sonra 

çöpte birikecek olan8230;



Tohum kadar fedakar 

olamaz insan. Kendini feda edebilemez.

Etse bilebilir belki. Onun özü de

 tohumdur çünkü. Ancak manaya ermeden

 biraz önceki mesele ve aslolan ne için kendini feda etmektir.

Niçin.

İçinden dalları, yaprakları,meyveleri ile

birlikte bir cennet ağacı çıkara

Bileceksen hiç durma. Aksi halde 

hasat kısır geçecektir. Ama zaman yok çok. 

Toprağın üstünde çürümeye başlı. İçeri 

girecek kadar cesur olmak ondan da önce yol bulmak

gerekir.

-tiği için.

İçin.

Gregor Samsa

bir -sabah uyığında-hamam böceğine

dönüşmüştü. 

Peki ya hamam böceği olarak 

uyuyanların üstlerini kim örtüp ışıklarını söndürecek.

Kafka8217; ya sorardım ben olsam.

Olsam sorardım.

İki şeyin arasında bir 

çizgi arayagelmiştir insan hep. Çizginin

 olmayabilme  ihtimalini düşünmez hiç. 

Çünkü sınırlanmıştır yine 

avucundaki ve alnındaki çizgilerle. Ona göre. Kader 

mahkum etmiş çaresizdir. 

Sonra özgürlük der.mahkum olmak 

kadere güzeldir onu çizebildiğin yere kadar. Sonra.

Sonrası çizgiler boşlukta

kesişir.

Ve masal biter. Bitti 

ısındığından genişleyen zamanın

hikayelemesi.Gökten düşen 

elmaları geri fırlatmaya uğraşıyorum şimdi8230; 

                                              ? ?  ak ? ? 

.', 'Göç mevsimiydi;  kuşlar kendi içlerine göçüyorlardı. Onlara bu dünyada gidecek daha  iyi bir yer olmadığını düşündüren neydi. Yoksa yazıGöç ...', ARRAY['Türk Edebiyatı','Şiir','Adullah Korkmaz']::text[], 8.5, '{"poet":"Adullah Korkmaz","poet_slug":"adullah-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":121,"source_url":"https://www.antoloji.com/nevroz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delirmenin Mantığı', 'delirmenin-mantigi-adullah-korkmaz-fcoub', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'iç organlarımı eritip fal bakan

gri gözlü bir cadı tanımıştım

; şair değilim diye haykırmak için

bir şiir daha yazacaksın; demişti

bildi.

uyuşmuş bacaklarımın üstünde durmaya

çalışırken bir türlü emin olamıyordum

ellerimi ceplerimin içine mi

dışına mı soktuğuma

zira burası geldiğim yerden daha soğuk.

gece yapışır gibi gelir ve kalırdı

sonra ay tarafından dikkatim çekildi

medden gelip cezire

gidemiyordum

sabitlenmiyordu boyum.

düşüncemin çölündeki kaktüsler

sempatik görünmek için çiçek açardı

kumlar kulaklarımdan

ve burun deliklerimden

sonsuza akardı.

çocukken zamanın

biz hareket ettikçe geçtiğini sanır

fazla kımıldamazdım

ama etrafımdakilerin niye küçüldüğünü

hala da anlamadım.

gereksiz kıldım artık konuşmayı

inadıma susuyorum zira

bu gökkubbe altında söylenmemiş

söz kalmadı; 

biz sadece yerlerini değiştiriyoruz.

aynanın arka yüzünü merak etmiyor kimse

camı ayna yapan şeyi

kararsızlığı simgeleyen

eğer bir yolun da başındaysan kararsız

o ikidir.

Borges in sığı gibi gül

sonsuz değilse de bitmez hiç rengi

çağrıştırdığı şekilde niye hiç aşık olmadım

dostlarım siz aşkları yaşadınız

ben yazdım.

öyleyse kendi kalbine niye

 kazık çakar insan

vampir mi oldum diye telaşından

grubu fark etmese de bulunamayacak

aranan kan      ak171205', 'iç organlarımı eritip fal bakan gri gözlü bir cadı tanımıştım ; şair değilim diye haykırmak için bir şiir daha yazacaksın; demişti bildi. uy...', ARRAY['Türk Edebiyatı','Şiir','Adullah Korkmaz']::text[], 8.5, '{"poet":"Adullah Korkmaz","poet_slug":"adullah-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/delirmenin-mantigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Perişan Haldeyim', 'cok-perisan-haldeyim-yusuf-onder-bahceci-4v4ek', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben hergece ağlıyorum,

Neden neden diyorum,

Ne haldedir bilmiyorum,

Çok perişan haldeyim.

O kendini feda etti,

Beni sevdi ele gitti,

Bana sitem söz etmedi,

Çok perişan haldeyim.

Sevgi vardı gözlerinde,

Yalan yoktu sözlerinde,

Kalbim kırık içerimde,

Çok perişan haldeyim.

Benim için doğmuştu,

Rüya gerçek olmuştu,

Tamda benim olmuştu,

Çok perişan haldeyim...', 'Ben hergece ağlıyorum, Neden neden diyorum, Ne haldedir bilmiyorum, Çok perişan haldeyim. O kendini feda etti, Beni sevdi ele gitti, Bana si...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cok-perisan-haldeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Olmamalıydı Ayrılık', 'boyle-olmamaliydi-ayrilik-yusuf-onder-bahceci-k8j12', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Böyle olmamalıydı ayrılık,

Neden diye soramadan,

Böyle olmamalıydı ayrılık,

Gül dalında bülbül iken,

Böyle olmamalıydı ayrılık,

Seni sevdim diyemeden,

Böyle olmamalıydı ayrılık,

Yollarında gül ve diken,

Böyle olmamalıydı ayrılık,

Bana hasret çektirirken,

Böyle olmamalıydı ayrılık,

Böyle olmamalıydı.....', 'Böyle olmamalıydı ayrılık, Neden diye soramadan, Böyle olmamalıydı ayrılık, Gül dalında bülbül iken, Böyle olmamalıydı ayrılık, Seni sevdim ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/boyle-olmamaliydi-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Yalıhüyük', 'bizim-yalihuyuk-aziz-cinar-hmhum', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KiMi TÜRKÜ, KiMiDE ŞARKI YAZAR 

MEHMET ALi ÇAVUŞ MANiLER DiZER 

SENi ANLATMAMAK BENi DE ÜZER 

HEDiYEM ŞiiRiM YAZIM YALIHÜYÜK 

SIRTINI DAYAMIS TOROS DAĞINA 

Bi ZAMANLAR HAYRANLARMIS BAĞINA 

BALIKLAR DOLARMIŞ IĞRIB AĞINA 

MEMLEKETiM iKi GÖZÜM YALIHÜYÜK 

DÖRT YOLUN BAŞINDA DUA EDiLiR 

BiZLERDE ASKERE BÖYLE GiDiLiR 

MEZARDA GEÇMiŞE YEMiN EDiLiR 

GURUR DA DUYSUN GAZiM YALIHÜYÜK 

SANMAYIN ÖLEN SAHiPSiZ KiŞiDiR 

CENAZE KÖYLÜNÜN ORTAK iŞiDiR 

ONUN AMCASIYSA BUNUN EŞiDiR 

HEP BiR SALKIMDA ÜZÜM YALIHÜYÜK 

UNUTULMUŞ KÜL-ABDAL AKLA KAZINA 

KURANLAR OKUNUR GELiN KIZINA 

ÇUVAL NiŞAN VEDE KINA 

iŞTE DÜĞÜNÜM SÖZÜM YALIHÜYÜK 

BAHÇEKAYA VE MUTLUDAKi KUYU 

KARPUZU ÇATLATIR ŞiRŞiRiN SUYU 

SANDI VE SARAY''DIR TEK iKi KÖYÜ 

YOKTAN iYiDiR AZIM YALIHÜYÜK 

CAMÖĞÜNDE DEDELER SOHBET EDERLER 

MUHALLEZDE ÇOBANLAR DAVAR GÜDERLER 

YiRCEDE AVCILAR AVA GiDERLER 

NE GÜZELDiR TAVŞANIM KAZIM YALIHÜYÜK 

SUĞLADA BUĞDAY SARAY ÖNÜNDE ELMA 

KIRDA YEŞiL NOHUT iSTERSEN ALMA 

YANTiRDE ARPA TA GÜZDEN KALMA 

NE VERiMLiDiR YAZIM YALIHÜYÜK 

ESKiDEN VAR iDi EŞEKLER ATLAR 

HER SÜRÜ BAŞINDA HAVLAYAN iTLER 

DELi-KAVAKLARDA iNEKLER OTLAR 

MUTLUDA KOYUNUM KUZUM YALIHÜYÜK 

HAMARATTIR YALIHÜYÜK KADINI 

KEŞLi,KÖMBE BEN SAYAYIM ADINI 

DUYUNCA PELTE ARAP-AŞINI 

CANLANIR ELiM DiZiM YALIHÜYÜK 

NERDE VAR BU GÜZEL YERLER BE ABi 

YANTiR ADAYANNI VE ENiŞDiBi 

ŞEHiRDEN BAKINCA NAZLANIR GiBi 

SANKi GELiNLiK KIZIM YALIHÜYÜK 

ESKiDEN DAMDAKi YUVAK SESiNi 

GÖLCÜKTE BAĞRILAN SESiN AKSiNi 

YÜKSEK OLUKTAKi ÇAMIN SESiNi 

ÇALMIYOR BENiM SAZIM YALIHÜYÜK 

NEFiSTiR AYRANI TUFRAN YAYIĞI 

YALISI SUĞLADAN TEPEDEN HÜYÜĞÜ 

SEViLiR KÜÇÜK SAYILIR BÜYÜĞÜ 

BUNU EMREDER ÖZÜM YALIHÜYÜK 

BiR BARAJ YAPMIŞLAR SUĞLA GÖLÜNE 

GiDENiMiZ ÇOKTUR GURBET ELiNE 

iSTERSE YOLLARIM, ONA BÖLÜNE 

BENiM YiNEDE iZiM YALIHÜYÜK 

iSTERSE SILADA iSTER GURBETTE 

BAŞIMIZ BiRGÜN OLURSA DERTTE 

YÜZÜNÜ ÇEViR ŞÖYLE SEYRETTE 

DiYECEKSiN TEK ÇÖZÜM YALIHÜYÜK 

iSTANBUL ANKARA VEDE BURSA''DA 

BELÇiKA,ALMANYA YADA HOLLANDA 

YALIHÜYÜKLÜSÜN ORDA OLSANDA 

BENiM SENiN DEĞiL BiZiM YALIHÜYÜK 

ÖRFE VE ADETE BAĞLIYIZ BiZLER 

EY ŞANLI ECDADIM ŞAHiDiM SiZLER 

BiRGÜN DAHADA GÜLECEK BU YÜZLER 

BENiMDE SANA SÖZÜM YALIHÜYÜK', 'KiMi TÜRKÜ, KiMiDE ŞARKI YAZAR  MEHMET ALi ÇAVUŞ MANiLER DiZER  SENi ANLATMAMAK BENi DE ÜZER  HEDiYEM ŞiiRiM YAZIM YALIHÜYÜK  SIRTINI DAYAMI...', ARRAY['Türk Edebiyatı','Şiir','Aziz Çınar']::text[], 8.5, '{"poet":"Aziz Çınar","poet_slug":"aziz-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/bizim-yalihuyuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelirsin Aklıma', 'sen-gelirsin-aklima-yusuf-onder-bahceci-v8sxz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nerde mutlu bir çift görsem,

Sen gelirsin aklıma,

Nerde güzel bir söz duysam,

Sen gelirsin aklıma,

Nerde bir garip görsem,

Yaşlar dolar gözüme,

Nerde bir nehir görsem,

Dalar dalar giderimde,

Nerde bir türbe görsem,

Dua niyaz ederimde,

Sen gelirsin aklıma.....', 'Nerde mutlu bir çift görsem, Sen gelirsin aklıma, Nerde güzel bir söz duysam, Sen gelirsin aklıma, Nerde bir garip görsem, Yaşlar dolar gözü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-gelirsin-aklima-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Kervan...', 'yitik-kervan-ulvi-ziya-lm6b4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu kervan bir menzile kolay varamaz; çünkü

Yoluna sık arayla harâmî pusu kurmuş...

Eski yolkesicinin soyundandır bugünkü

Sis çökmüş ruhlarında itler ulur,kudurmuş...

Ellerde kanlı teber yol üstünde otururlar...

Lisan ferman dinlemez hemen karşı dururlar...

Derin sözden anlamaz,katı darbe vururlar...

Bunlar; güyâ,düz yolu yolculardan korurmuş...

Kendileri; bu yolun cesur,yiğit erleri (!) .

Kirletseler de helâl geçtikleri yerleri  (!) ...

İsteğe tam uygundur onların eserleri (!) ...

Ayrı biri nûr saçsa,onlara nâr olurmuş...

Bu kervan menziline kolay varamaz,çünkü

Yoluna sık arayla nâmertler pusu kurmuş...

Mayası bozukların soyundandır bugünkü

Karanlık rûhlarında itler ulur; kudurmuş...', 'Bu kervan bir menzile kolay varamaz; çünkü Yoluna sık arayla harâmî pusu kurmuş... Eski yolkesicinin soyundandır bugünkü Sis çökmüş ruhların...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yitik-kervan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YB-31 Domates festivali', 'yb-31-domates-festivali-mehmet-coban-vkebf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayaklarımın altı vıcık, vıcık

Birden kayıyorum yerlerde 

Ayağa kalkmak istediğimde

Her tarafım kıpkırmızıydı

Üzerimdeki domates kızılıydı

İnsanlar bağırıyor gülüyorlar

Birbirlerine domates fırlatıyorlar

İlerilerde bir büyük araba

Arkasına domates doldurmuşlar

Adamlar sürekli domates atıyorlar

Etraftan müzik sesleri geliyor

Gürültü ve şamatadan inliyor

Düşe kalka uzaklaştım oradan

Temizlenmeye çalıştım akan sudan

Dinlenirken bir kenarda

Biri geldi oturdu yanıma

Sen yabancı mısın dedi bana

Evet ben yabancıyım dedim ona

Sordum, şehirde domatesleri atıyorlar

Yiyeceklerine, çocuklar gibi oynuyorlar

Dedi, bu festival yılda bir kez olur 

Tonlarca domates yok olur

Sordum, nice insan aç, bulamıyor

Onlara göndermek niçin olmuyor? 

Dedi, bu bizim âdetimiz

Her yıl düşünmeden eğleniriz

Uzaklaştım oradan geldim ülkeme

Merak edip daldım internete

Birde ne göreyim aynı şey ülkemde

Daha farklı, daha değişik bir şekilde

Döndüm aklıma sordum soruları

Karıştırdım bilgileri, kitapları

Kutsamakmış meğer doğayı

Unutmakmış meğer kutsarken insanları

Dünyanın her bir yerinde 

Çoğunluk açlık sefalet içinde

İnsanlar şuursuzca israf peşinde

Derim ki, 

Doğa kutsanacaksa kutsansın

İsterim ki, insanlık bundan faydalansın

Kutsanırdı, sözle, yazıyla, ibadetle

Kutsanırdı, boğuşarak açlıkla sefaletle

Ama bunu anlayacak insanlık nerede? 

Ey insanlık kulak ver şu sözlere! ..

“Tanrı der, size çeşit çeşit nimetler verdim”

“İnsan der, bak gör ben kıymet bilmez nasıl telef ederim”

“Tanrı der, nimetlerimi, yeyin, yedirin”

“İnsan der, hem yer, hem telef ederim”

……………………..

Daha tanrının ne demesini bekliyoruz ki? 

 20.01.2006-İzmir', 'Ayaklarımın altı vıcık, vıcık Birden kayıyorum yerlerde  Ayağa kalkmak istediğimde Her tarafım kıpkırmızıydı Üzerimdeki domates kızılıydı İn...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/yb-31-domates-festivali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı uçurtma', 'kirmizi-ucurtma-nevzat-ozkan-jntjf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kendi çöplüğünde 

birden horozlandı.

kuyruğunu kabarttı.

rüzgar arkasında

boşaldıkça makara,

başıyla selam verdi

kibar bir reveransla..

selamını alırken 

açıldı gözüm  birden.

kırmızı uçurtmamı 

kaçırdım ellerimden.', 'kendi çöplüğünde  birden horozlandı. kuyruğunu kabarttı. rüzgar arkasında boşaldıkça makara, başıyla selam verdi kibar bir reveransla.. sela...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kirmizi-ucurtma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Acâyip Yaşamak...', 'bir-ac-yip-yasamak-ulvi-ziya-r55du', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çürür sevgi çiçekleri

nefret bataklığında

günler,geceler boyu...

Yaşamın ölüme değdiği

her yerde

yok edici

can alır...

Mâsumu cennetinden eder

bir yılan soyu

Ferah rûh kasvetlenir

bunaldıkça bunalır...

Kalleş,sinsi bir çatışma

sürüp gider aralıksız

zehirlenir tatlı hayat

ömrün posası kalır...

Ve can çekişir inleyerek

umut,gayret,sabır...

Karışır günler geceye

gül yüzler solar,sararır...

Silinir tablodan

sırasıyla her varlık

yerinde bir boşluk kalır...', 'Çürür sevgi çiçekleri nefret bataklığında günler,geceler boyu... Yaşamın ölüme değdiği her yerde yok edici can alır... Mâsumu cennetinden ed...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-acayip-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle', 'soyle-ayhan-matafaci-mruld', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bekliyorum ne? 

Bekliyorum kim? 

Bekliyorum......

Kimbilir kimsin? 

Kimbilir nesin? 

Kimbilir.....

Bir kelebeğin kozası mı? 

Bir gülün goncası mı? 

Bir aşkın meyvası mı? 

Söyleee........', 'Bekliyorum ne?  Bekliyorum kim?  Bekliyorum...... Kimbilir kimsin?  Kimbilir nesin?  Kimbilir..... Bir kelebeğin kozası mı?  Bir gülün gonca...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Matafacı']::text[], 8.5, '{"poet":"Ayhan Matafacı","poet_slug":"ayhan-matafaci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/soyle-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulmaca', 'bulmaca-tulay-sustam-9uldc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yukarıdan aşağıya

soyundu ay...

döktü

eteğindeki yıldızları

ortaya çıktı giz''em 

soldan sağa

ince bir sızı gider

bırak! ...

ortası boş kalsın 

kara kutunun

*07.01.2007 tarihinde www.elelebizbize.com  sitesinde günün şiiri seçilmiştir. Emeği geçen herkese teşekkür ediyorum.', 'yukarıdan aşağıya soyundu ay... döktü eteğindeki yıldızları ortaya çıktı giz''em  soldan sağa ince bir sızı gider bırak! ... ortası boş kalsı...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bulmaca-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rabbim Boş Çevirme', 'rabbim-bos-cevirme-mehmet-postalli-pvkg6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Affını  umarak  geldim  kapına

Rabbim, boş çevirme kutlu kapından

Halimi arz  ettim, yüce  katına

Rabbim, boş çevirme kutlu kapından

Haccı nasip ettin şükürler olsun 

Rahmet kaynağından testimiz dolsun

Yarın mahşer günü, yüzümüz gülsün

Rabbim, boş çevirme kutlu kapından

Sana malum, benim günahım pek çok

Bu  asi  kulunun yüzüne bir bak

Burdan boş dönersem, başka kapım yok

Rabbim, boş çevirme kutlu kapından

Çağrına uyarak çıktım bu yola

Yaptığım ibadet yerini bula

Kevser ırmağından doyası sula

Rabbim, boş çevirme kutlu kapından

Selam kapısından girdim ilk defa

Selam olsun ya Muhammed  Mustafa

Cennet bahçesinde buldum çok vefa

Rabbim, boş çevirme kutlu kapından

Peygamberin kabri - saadetine

Şükür, nail oldum ziyaretine

Beni mazhar eyle şefaatine

Rabbim, boş çevirme kutlu kapından

Mekke’nin Emini, Medine Gülü

Âlemlere Rahmet, Allah Resulü

Yüreğim titriyor, gözlerim dolu

Rabbim, boş çevirme kutlu kapından

Sükûnetle geçip attım üç adım

Ebu Bekir ve Ömer’ e uğradım

Salih kullarınla okunsun adım

Rabbim, boş çevirme kutlu kapından

Üzerimden gaflet gömleğin açın

Hak yoldan sapmayım, vurun bir perçin

Habibin  Muhammed  hatırı  için 

Rabbim, boş çevirme kutlu kapından

Biliyorum yoktur iyi amelim

Rızana ermektir asıl emelim

El - aman Allah’ım ortada halim

Rabbim, boş çevirme kutlu kapından

Evin ziyarete geldim bu gece

İhsanın büyüktür, affın çok yüce

Rahmetine sığınırım sadece

Rabbim, boş çevirme kutlu kapından

Dilek eşiğine koydum yüzümü

Baştan sona sıraladım sözümü

Mübarek beytine diktim gözümü

Rabbim, boş çevirme kutlu kapından

Ruhum ve bedenim, rahmetine aç

Kalbimi nurlandır, gözlerimi aç

Senden gayrısına eyleme muhtaç

Rabbim, boş çevirme kutlu kapından

Yüce Peygamberin  gittiği  izden

Beytin tavaf ettim lütfeyle bizden

Asla geri dönmem verdiğim sözden

Rabbim, boş çevirme kutlu kapından

Reçetem kurandır, Resulün rehber

Derim, Bismillâhi – Allahüekber

Cenneti âla da Cemalin göster

Rabbim, boş çevirme kutlu kapından

Kâbe’ye yakışmış asil örtüsü

Belli değil amelimin tartısı

Aldı beni, reddedilme korkusu

Rabbim, boş çevirme kutlu kapından

Vardım Arafat’a durdum divana

Cürüm defterimi serdim meydana

Bağışla suçumu, kerem et bana 

Rabbim, boş çevirme kutlu kapından

Mahşerin, bir tatbikatı Arafat

Ömrümde görmedim böylesi bir tat

Yüce makamından isterim berat

Rabbim, boş çevirme kutlu kapından

Müzdelife  vakfesinde sözleştim

Mina’ da nefsimle mertçe yüzleştim 

Bütün kötü huylarımdan vazgeçtim

Rabbim, boş çevirme kutlu kapından

Kisvemi çıkardım, büründüm ihram

Şeytanı taşladım birinci bayram

Senin rızan için, kestim bir kurban

Rabbim, boş çevirme kutlu kapından

Gezdiğim yerlerden çok hisse kaptım

Beytine ziyaret tavafı yaptım

Haceri – Esvede yüz sürdüm, öptüm

Rabbim, boş çevirme kutlu kapından

Sefa ile Merve arası koştum

Her tavaf sonrası zemzemi içtim

Nur dağına çıktım, kendimden geçtim

Rabbim, boş çevirme kutlu kapından

Rahmetinle yaraları saransın

Kullarının hacetini görensin

Diledin mi, hem hesapsız verensin

Rabbim, boş çevirme kutlu kapından

Cümle günahıma gözyaşı döktüm

Geriye dönüş yok, gemiyi yaktım

Açtım ellerimi, boynumu büktüm

Rabbim, boş çevirme kutlu kapından

Âhireti andım, giydim ihramı

Bir merhem sür, tedavi et yaramı

Elbet olur, Ev Sahibi ikramı

Rabbim, boş çevirme kutlu kapından

Mehmet POSTALLI / 2006 

Yahyalı  - Kayseri

Toprağa Bir Can Düştü isimli kitabımdan alınmıştır ve bu kitap Gündüz Yayınevi tarafından çıkartılmıştır.

www.gunduzkitabevi.com.tr', 'Affını  umarak  geldim  kapına Rabbim, boş çevirme kutlu kapından Halimi arz  ettim, yüce  katına Rabbim, boş çevirme kutlu kapından Haccı n...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":104,"source_url":"https://www.antoloji.com/rabbim-bos-cevirme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esra', 'esra-bilal-konal-72et8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgiliye bir gece vakti yürü

Sessiz ol seni kimse duymasın

Gizlen seni kimse görmesin

Heycanla çarpsın kalbin

Ona ulaşmak olsun amacın

Sal düşüncelerini,herşeyden arın

Ondan başka ne varsa

Bırak geride kalsın

Yavaşça yürü adım adım

Ağır ağır çık merdivenleri

Kapılar açılana kadar

Çal durmadan çal

Firar edin Vedud''e

Her türlü kötülükten

Kaçın özgür aleme

Özgürlüğün sahibine

Amacım sensin ey yüce Rabbim

Sadece senin rızanı isterim', 'Sevgiliye bir gece vakti yürü Sessiz ol seni kimse duymasın Gizlen seni kimse görmesin Heycanla çarpsın kalbin Ona ulaşmak olsun amacın Sal ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Konal']::text[], 8.5, '{"poet":"Bilal Konal","poet_slug":"bilal-konal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/esra-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurum...', 'ucurum-ulvi-ziya-b42ry', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlık ortasında her köşeden bir enîn

Yükselir kimse duymaz; sesler kısık,sözler boş...

Kim sorumlu bilinmez,suç birlikte gidenin

Civanmert yol gösteren bulursan,onunla koş...

Kime güvensek acep,kılavuzlar zedeli

Her kılavuz bir karga,para hırsı güdeli...

Yürüttüler,yürüdük,bir de baktık uçurum

Kuşatır çevremizi; dibi çamurlu,selli...

Mâzî sızıp dökülmüş,avcumuzdan,su gibi...

Güvenilmez bir âtî ölüm korkusu gibi...

Ümidimiz çırpınır çilelerin ağında; 

Ömürden nasîbimiz,yaşam tortusu gibi...', 'Karanlık ortasında her köşeden bir enîn Yükselir kimse duymaz; sesler kısık,sözler boş... Kim sorumlu bilinmez,suç birlikte gidenin Civanmer...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ucurum-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstikamet', 'i-stikamet-bilal-konal-f722n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Niçin seninle konuşamam

Neden gözlerine bakamam

Derdimi bir kere anlatsam

Meramı bir türlü anlatamam

Bıraktım sana layık olmayı

Ertelenen ameller unuttu saymayı

Bu kaçıncı yanılgı,bu kaçıncı gaflet

Demeye utanır oldum,ne olur affet

Bazen yürek ferahlar görünce seni

Kurtuldum zanneder arar görünmeyeni

Gözlerini açtığında kırılmıştır dümeni

Dalgalar istediği yere sürüklemek isterken

Rüzgar başka yöne doğru üflerken 

Ben ayrı diyarlara kürek çekerim', 'Niçin seninle konuşamam Neden gözlerine bakamam Derdimi bir kere anlatsam Meramı bir türlü anlatamam Bıraktım sana layık olmayı Ertelenen am...', ARRAY['Türk Edebiyatı','Şiir','Bilal Konal']::text[], 8.5, '{"poet":"Bilal Konal","poet_slug":"bilal-konal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/istikamet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Labirent', 'labirent-bilal-konal-ov1vm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Labirentin içinde dolaşmayı hayat mı sandın? 

İsteklerine köle olmayı özgürlük mü saydın? 

Bir zamanlar yoktun yine yok olacaksın,

Var oluşun varlığına niye inanmayacaksın?', 'Labirentin içinde dolaşmayı hayat mı sandın?  İsteklerine köle olmayı özgürlük mü saydın?  Bir zamanlar yoktun yine yok olacaksın, Var oluşu...', ARRAY['Türk Edebiyatı','Şiir','Bilal Konal']::text[], 8.5, '{"poet":"Bilal Konal","poet_slug":"bilal-konal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/labirent-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Sessizce', 'bir-gun-sessizce-fevzi-gunenc-7raxn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne kadar ömür biçilmişse o kadar yaşarsın

Ne uzatabilirsin, ne kısaltabilir

Bilemezsin ne zaman öleceğini

Bir gün sessizce gidersin.

Oysa umutların vardır hala

yaşamayı umduğun mutlulukların

günlerin geçer gözlerinin önünden

Ne zaman büyüdüm

ne zaman yaşlandım diyemeden

gidersin

Sessizce...

Ağlarlar ardından

timsah gözyaşları dökerler

“Unutmayacağız seni” derler

“Yüreğimizde yaşayacaksın”

Yalan! 

arada bir adını anarlar yalnızca

doğru değil mi söylediklerim sizce

gerçek tek:

gidersin 

sessizce.', 'Ne kadar ömür biçilmişse o kadar yaşarsın Ne uzatabilirsin, ne kısaltabilir Bilemezsin ne zaman öleceğini Bir gün sessizce gidersin. Oysa um...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-gun-sessizce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafiye', 'kafiye-bilal-konal-v9mf0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karınca    kararınca

Sevince   sevilince

Arıyı          arayınca

Doğuda   doğunca 

Batıya      batınca

Yarayı      yarınca

Kurtlar     kurtulunca

Yanlış       yayılınca

Duruyu    durdurunca

Gerçek     gerilince

Soruyu     sorunca

Yorumu    yorunca

Kurguyu  kurcalayınca

Manayı     mayalayınca

Anlamı      anlatmaya

Kafiyeler  kafi gelmez', 'Karınca    kararınca Sevince   sevilince Arıyı          arayınca Doğuda   doğunca  Batıya      batınca Yarayı      yarınca Kurtlar     kurtu...', ARRAY['Türk Edebiyatı','Şiir','Bilal Konal']::text[], 8.5, '{"poet":"Bilal Konal","poet_slug":"bilal-konal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kafiye-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuva', 'yuva-bilal-konal-v0n29', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Salkım saçak dökülüyor damlarımız,

Gıcık bir sesle kırılıyor camlarımız,

Ocakta ateş sönüyor esen yelden,

Köşelerde örümcek ağı dikenli telden.

Kara bulutlar üzerimize geliyor,

Bir çığlık çıldırıyor gökyüzünde.

Yıldırımlar ta yüreğimize iniyor.

Yuvamız dağılıyor garip bir hüzünle.', 'Salkım saçak dökülüyor damlarımız, Gıcık bir sesle kırılıyor camlarımız, Ocakta ateş sönüyor esen yelden, Köşelerde örümcek ağı dikenli teld...', ARRAY['Türk Edebiyatı','Şiir','Bilal Konal']::text[], 8.5, '{"poet":"Bilal Konal","poet_slug":"bilal-konal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yuva-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gör Bakalım Neler Olur', 'gor-bakalim-neler-olur-yusuf-onder-bahceci-a9ez8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni sevdim derdin ile,

Dağlar, taşlar gelir dile,

Sen Allah''tan sabır dile,

Gör bakalım neler olur.

Seni sevdim halim yaman,

Hain dostlar hain aman,

Hep ederim feryat, figan,

Gör bakalım neler olur.

Seni sevdim elin oldun,

Verdiğin söz hani noldun,

Sen gözümde serap oldun,

Gör bakalım neler olur.

Hep bekleyip göreceğiz,

Kimler dostmuş bileceğiz,

Birgün murada ereceğiz,

Gör bakalım neler olur....', 'Seni sevdim derdin ile, Dağlar, taşlar gelir dile, Sen Allah''tan sabır dile, Gör bakalım neler olur. Seni sevdim halim yaman, Hain dostlar h...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gor-bakalim-neler-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toplum', 'toplum-bilal-konal-4tvba', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum nerdeyim,      kafam ise karışık

Ben kendime perdeyim,   ruhum kime barışık? 

Doğmayan seherdeyim,   ilerde var mı ışık? 

Çırpındığım yerdeyim,    elim ayağıma dolaşık

Söylediğim her deyim,    kendi kendine bulaşık', 'Bilmiyorum nerdeyim,      kafam ise karışık Ben kendime perdeyim,   ruhum kime barışık?  Doğmayan seherdeyim,   ilerde var mı ışık?  Çırpınd...', ARRAY['Türk Edebiyatı','Şiir','Bilal Konal']::text[], 8.5, '{"poet":"Bilal Konal","poet_slug":"bilal-konal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/toplum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair', 'sair-mualla-yasdiman-rcw3r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bizde,ne kimsesizlik biter

Ne aşk, ne isyan diner

Sevgi; hasrettir,dizelerimizde

Değil mi ki,kendimizi şair sanırız

Mutluluk bol gelir bedenimize', 'Bizde,ne kimsesizlik biter Ne aşk, ne isyan diner Sevgi; hasrettir,dizelerimizde Değil mi ki,kendimizi şair sanırız Mutluluk bol gelir beden...', ARRAY['Türk Edebiyatı','Şiir','Mualla Yasdıman']::text[], 8.5, '{"poet":"Mualla Yasdıman","poet_slug":"mualla-yasdiman","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sair-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muktedir Olmak...', 'muktedir-olmak-ulvi-ziya-svtod', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hükmetme hırsı

ne tılsımlı tutkudur ki ey felek! ...

uğrunda ne baba dinlenir,

ne kardeş göze görünür,

ne kız evlât,ne erkek...

Hâkan olur bir şehzâde

Ramazanda olsa bile

cellata teslim eder birâderlerini

boğdurur

sonra da mâtem tutar

siyah kavuk giyerek...

Sanki budur tek çıkar yol

can kardeşe kıymaktır tek gerçek

sabî olsalar ya da ergen

hiç farketmez

haram eder kardeşlerine yaşamayı,hükümdar

''Devletin selâmeti için '' diyerek...

Lânet vardır,kargış vardır

devletlerin derûnunda...

Nice îmânlı hükümdar

alikıran başkesendir

sınır yoktur gururunda...

Çok iyilik,çok kötülük

yapıp dünyâyı terkeder

Bir hırslıya tâbi millet

azıcık iyiliğe minnet

zulümlere lânet eder...

Nâhoş sesler çıkararak

gıcırdar hep çark-ı felek...

Günler geçer,zaman dolar

böyle gelmiş,benzeriyle giderek...', 'Hükmetme hırsı ne tılsımlı tutkudur ki ey felek! ... uğrunda ne baba dinlenir, ne kardeş göze görünür, ne kız evlât,ne erkek... Hâkan olur b...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/muktedir-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçlik', 'hiclik-mehtap-tolu-n22qv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düzme değerlerin,uydurma sözlerin sihrine kapılmadan evvel gördüm ki, 

kurtarıcı dediklerini zincire vurmuşlar zaten. 

Zincire vurulmadan önce de uyuyordu. 

Zaten uyur, o hep uyur. 

Onu uyandırdığımda, bana; 

“Diz üstünde çık merdivenleri” dedi. 

En yüce dorukta kaynıyorken sevgi pınarım, 

Susuz kalmış sırıtkan ağızlar gözlerini pınara dikmişler, 

Suyu ağılamışlar, pınarın içinden bakarlar bana. 

Hayatın gözlerinin içine baktım geçenlerde. 

Beni altın oltayla dipten çıkardı, 

Hayata dipsizsin dediğimde, 

Bütün balıklar böyle söyler dedi. 

Haklı bile olsan hayat, şimdi gelgeç diye mi adlandırmalıyım seni. 

Ay yükselirken, güneş doğurmak ister gibi. 

Öylesine gebe kalmış ufukta. 

Bu yalancı gebeliğe inanmıyorum artık. 

Gerçek şu ki oyuncağınızı elinizden aldım. 

Bana kızıyorsunuzdur, çocuklar gibi kızıyorsunuzdur hem de. 

Sadece zarar vermek için hayatı öven zehirli örümceği gördüm diye bana kızmayın. 

Kızmayın, ölmeden önce ölmeyi deneyin. 

Bana olanlarda, önce çok korktum. 

Böylesine alaca bulaca görmemiştim kendimi. 

Bugün yüküm ağır. 

Üstüme böcekler, solucanlar konsa ne olur. 

Yüküm hafiler sadece, aynı kızım gibi. 

Bataklıkta sazlar arasında oturup, bizi kimseyi ısırmayız diyenler; 

Sadece yolunuzdan çekildim artık. 

Çünkü yüküm ağır. 

Amin’ini çaldığım kızgın davulcu, ne güzel geldin üstüme. 

Güzelliğine bürünmüşsün ama dilsiz konuştun benimle. 

Hani bilgeliğin de apaçık ortada. 

Dengede duran terazime; 

Üç ağır soru attım, diğer kefeye de üç ağır cevap. 

Artık sadece doyasıya hiçliğimi yaşıyorum.', 'Düzme değerlerin,uydurma sözlerin sihrine kapılmadan evvel gördüm ki,  kurtarıcı dediklerini zincire vurmuşlar zaten.  Zincire vurulmadan ön...', ARRAY['Türk Edebiyatı','Şiir','Mehtap Tolu']::text[], 8.5, '{"poet":"Mehtap Tolu","poet_slug":"mehtap-tolu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hiclik-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Böyle Olduki', 'neden-boyle-olduki-yusuf-onder-bahceci-mp1ln', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne vardı sanki böyle,

Beni bırakıpta gidecek,

Bu kalbim seni nasıl,

Seni nasıl silecek.

Gözlerimde yaşlar olur,

Çok sevdiğim elin olur,

Bize gayrı hasret kalır,

Neden böyle olduki.

Ben sararıp solmuşum,

Çoktan toprak olmuşum,

Çok sevmişim ölmüşüm,

Neden böyle olduki.

Sanma senden ayrıyım,

Senden ayrı, gayrıyım,

Sana nasıl bağlıyım,

Neden böyle olduki....', 'Ne vardı sanki böyle, Beni bırakıpta gidecek, Bu kalbim seni nasıl, Seni nasıl silecek. Gözlerimde yaşlar olur, Çok sevdiğim elin olur, Bize...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neden-boyle-olduki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafası Kurşun Gibi Ağır', 'kafasi-kursun-gibi-agir-mehtap-tolu-qn8n3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmediğini biliyorum, böyle diyor gözler. 

Öldürdüğün sevgiyle barışman yetmez, üzüntün sevgin olsun. 

Haklı çıkarsan sağ kalırsın. 

Yargıcın acıysa, tez gelen ölümde kurtuluş yoktur. 

Kurşun gibi ağır kafanı bir sallayabilsen yükü düşecek üzerinden. 

Kim bu kafayı sallayacak. 

Zavallı gövdenin çektikleri kafan yüzünden. 

Gel gör ki düşünce ve eylem başka başka. 

Zavallı gövdesindeki can kendisine göre yorumladı ölümü; 

Bıçak mutluluğuna duyulan hırs. 

Evet delilik de gerçek. 

Ya bağlılık, ya doğruluk denseydi keşke. 

Ben nehir kıyısına bir korkuluğum. 

Tutunan tutunsun. 

Ama asla koltuk değneği değilim...', 'Sevmediğini biliyorum, böyle diyor gözler.  Öldürdüğün sevgiyle barışman yetmez, üzüntün sevgin olsun.  Haklı çıkarsan sağ kalırsın.  Yargıc...', ARRAY['Türk Edebiyatı','Şiir','Mehtap Tolu']::text[], 8.5, '{"poet":"Mehtap Tolu","poet_slug":"mehtap-tolu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kafasi-kursun-gibi-agir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırıldı Ruhun Kanatları Bugün', 'kirildi-ruhun-kanatlari-bugun-mehtap-tolu-za7jo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çirkinliğin yüceliğinde büyüyen gönüller, 

Sözlerin kirine göre temiz kalan gerçekler. 

İçtenliklikteki utangaçlığımla arınmış sözlerim; 

önce yüreğim kocadı, sonra ruhum. 

Gök donanmış fişeklerini, attı atacak, 

İçimin sırları açığa çıktı çıkacak, 

Yeryüzünde biraz oyalandım; 

ölmeyi öğrenmek, yeniden doğmak için. 

Gözyaşları içinde uzandım altın topa. 

Kurban ya da armağan olmanın yorgunluğu, 

Yine toprak olmak istiyorum dinlenmek için. 

Bir canı harcamak değil ereğim, 

Işığı sonsuza kadar yanacak, sönen bir yıldız olmak. 

Kopmuş alt üst yatarken, 

Güzelliğin gülüşü usul usul titredi. 

Kırıldı ruhun kanatları bugün.', 'Çirkinliğin yüceliğinde büyüyen gönüller,  Sözlerin kirine göre temiz kalan gerçekler.  İçtenliklikteki utangaçlığımla arınmış sözlerim;  ön...', ARRAY['Türk Edebiyatı','Şiir','Mehtap Tolu']::text[], 8.5, '{"poet":"Mehtap Tolu","poet_slug":"mehtap-tolu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirildi-ruhun-kanatlari-bugun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniş', 'seslenis-mehtap-tolu-29y4n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Son kazında buldun kendi gömünü, göremedin. 

Üzerine ağırlığın ruhu çöktü, çözemedin. 

Senin olanı alamadın,senden sakladılar, bulamadın. 

Kendini sevmeyi beşikte yasakladılar, sevemedin. 

Yasak dolu çeyizine ''iyi ve kötü'' dediler, inandın. 

Seni,deve gibi çökertip yük yüklediler,yüklendin. 

Yüke, kendine katlanamadın, kızgındın, söylendin. 

Soylu, süslü bir kabuk armağan ettiler, kabul ettin. 

Sadece kendi kulaklarıma söylesemde, 

Sana bir türkü yakacağım, 

Yüreğin uyansın, gözlerin dillensin. 

Utanma sev, ama önce kendini sev.', 'Son kazında buldun kendi gömünü, göremedin.  Üzerine ağırlığın ruhu çöktü, çözemedin.  Senin olanı alamadın,senden sakladılar, bulamadın.  K...', ARRAY['Türk Edebiyatı','Şiir','Mehtap Tolu']::text[], 8.5, '{"poet":"Mehtap Tolu","poet_slug":"mehtap-tolu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seslenis-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden önce senden sonra-2', 'senden-once-senden-sonra-2-erdener-kirim-s2p8t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şair idim,sazan oldum

Şiir,roman yazan,oldum

Kırk yaşımda azan oldum

Senden önce,senden sonra

Duyan idim,sağır oldum

Hafifledim,ağır oldum

Ama oldum,kahır oldum

Senden önce,senden sonra

Dik idim,eğik oldum

Boynuz taktım,geyik oldum

Ağlayana emzik oldum

Senden önce,senden sonra

Sevgilindim,delin oldum

Ayak,kafan,elin oldum

Kurda tuzak yemin oldum

Senden önce,senden sonra

Göz yaşındım,selin oldum

Sen yanarken,yelin oldum

Kaçıp gittin gelin oldun

Senden önce,senden sonra

Direk idim,bayrak oldum

Dalında bir yaprak oldum

İnsan iken,toprak oldum

Senden önce,senden sonra

Deri idim,nasır oldum

Kopya idim,asıl oldum

Hakkı arar,vasıl oldum

Senden önce,senden sonra

Senden önce,senden sonra

Ruh kalır bedenden sonra

Ne tutar dünyada bizi

Vademiz dolduktan sonra

(İstanbul............20/01/2006)', 'Şair idim,sazan oldum Şiir,roman yazan,oldum Kırk yaşımda azan oldum Senden önce,senden sonra Duyan idim,sağır oldum Hafifledim,ağır oldum A...', ARRAY['Türk Edebiyatı','Şiir','Erdener Kırım']::text[], 8.5, '{"poet":"Erdener Kırım","poet_slug":"erdener-kirim","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/senden-once-senden-sonra-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece Düşümde', 'dun-gece-dusumde-mehtap-tolu-1ohve', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dumanı tüten bir dağın eteğine, 

Uzanmış düşünürken düşümde, 

İlle de gerçeklik diye tutturmuş yüreğim; 

Bıktırdı beni dırdırından tıngırtılarından. 

Dünden bugünden, yarından öbür günden, 

Duyuyorum seslerini ensemde, 

Bulutlar ülkesinden hayalet aksırmalarını. 

Vaktidir tam vaktidir dedim, 

Ağımı attım derin denizlere. 

İnancımın eşlik ettiği öğreti gürleyerek sordu, 

Neyin tam vaktidir. 

Üstüme ateşler yağdı, kül oldum tozadım. 

Zehir oldu şarabım kurudum. 

Yer yarıldı, deniz çekildi yarığa. 

Sığ bataklıkta üzüntüye boğuldum. 

Gördüğüm bir düş. 

Issız dağın kalesine bekçi olmuşum. 

Her yeri sessizlik kaplamış. 

Uyanmışım kendi çığlığıma. 

Düşümde anahtarımı soktuğum kapı, 

Bir parmak bile aralanmadı. 

Gördüğüm sadece bir düş.', 'Dumanı tüten bir dağın eteğine,  Uzanmış düşünürken düşümde,  İlle de gerçeklik diye tutturmuş yüreğim;  Bıktırdı beni dırdırından tıngırtıl...', ARRAY['Türk Edebiyatı','Şiir','Mehtap Tolu']::text[], 8.5, '{"poet":"Mehtap Tolu","poet_slug":"mehtap-tolu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dun-gece-dusumde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Bahtım', 'kara-bahtim-levent-goktas-zhm8d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karadır bu bahtım kara

Gülmez oldu felek bana

Yaşamak haramdır bana

Çekilmez bu dünya kahrı

Yaşamak haramdır bana

Çekilmez dünyanın kahrı

Yeşil gözlerine yandım

Adıda münevver hanım

Sana verdim tüm kalbimi

Sensin canım canyoldaşım

Sana verdim tüm sevgimi

Sensin aşım arkadaşım', 'Karadır bu bahtım kara Gülmez oldu felek bana Yaşamak haramdır bana Çekilmez bu dünya kahrı Yaşamak haramdır bana Çekilmez dünyanın kahrı Ye...', ARRAY['Türk Edebiyatı','Şiir','Levent Göktaş']::text[], 8.5, '{"poet":"Levent Göktaş","poet_slug":"levent-goktas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kara-bahtim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göç', 'goc-muslum-cagli-atca2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimler geldi geçti kimler bu handan

Kimler konakladı bu köhne handa

Hesap soruyorum senden ey zaman

Oyolcular şimdi hangi mekanda

Beklerim gidenler dönmedi geri

Vardır her birinin makul sebebi

Ya sevmediler bu garip yeri

Ya da saklı duruyorlar zamanda

Ruh uçar geride kalır bir beden

Azıksız giderler bilmemki neden

Bir seher vaktinde kimse görmeden

Göçsem bende bir mübarek ezanda', 'Kimler geldi geçti kimler bu handan Kimler konakladı bu köhne handa Hesap soruyorum senden ey zaman Oyolcular şimdi hangi mekanda Beklerim g...', ARRAY['Türk Edebiyatı','Şiir','Müslüm Çağlı']::text[], 8.5, '{"poet":"Müslüm Çağlı","poet_slug":"muslum-cagli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/goc-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Suçu Bende Bilirim', 'o-sucu-bende-bilirim-yusuf-onder-bahceci-5zidx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnan seni görünce titriyorum ben,

Yanındayken bile hasretim neden,

Beni bırakıpta gitsen bile sen,

O suçu bende bende bilirim.

Ben erkeğim yumruğu vurmalıydım,

Kırılacak biri varsa onu kırmalıydım,

Seni ellerinden çoktan almalıydım,

O suçu bende bende bilirim.

Gözlerine bakıpta sevdim demeli,

Şimdi ne hallerdesin gittin gideli,

Sanma yüzüm güler Dünya güzeli,

O suçu bende bende bilirim....', 'İnan seni görünce titriyorum ben, Yanındayken bile hasretim neden, Beni bırakıpta gitsen bile sen, O suçu bende bende bilirim. Ben erkeğim y...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-sucu-bende-bilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YB-25 Neyin ispatı?', 'yb-25-neyin-ispati-mehmet-coban-1i50f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzaktan seyrediyorum

Birini boğa kovalıyor

Elinde pelerin sallıyor

Oyun bir müddet sürüyor

Sonra genelde boğa ölüyor

Seyreden insanlar zevk içinde

Düzenleyenler para peşinde

Boğayı öldürenler ün peşinde

Bir başka gün,

İnsanlar sokaklara doluşmuş

Ellerinde kırmızı kâğıtlar

Boğalara doğru sallıyorlar

Onları takip ediyor boğalar

Bir koşturmaca başlıyor

Önde koşanlar

Arkada kızgın boğalar

Yakaladığını yere seriyor

Yerdekileri boynuzluyor

Etrafta çılgın insanlar

Olanlardan zevk alıyorlar

Yılda bir kez, bir hafta

Çılgınlar ile boğalar sokakta

Hayretler içinde seyrediyorum

Hiçbir anlam veremiyorum

Dalıyorum düşüncelere,

Ki bu insanların dinleri

Sevgiden söz ediyorken

Tanrının yarattıklarına 

Zulüm ediyorlar neden? 

Bir anlık zevkleri için

Duygularını tatmin için

Cesaretlerini ölçmek için

Tanrının yarattıklarını 

Öldürüyorlar neden? 

Merak ettim, 

Dinlerini anlatan siteye girdim

İnandıkları tanrının oğlu İsa Mesih

Kendine inananların bütün günahlarını

Üstlenerek bu dünyadan gitmişti. 

Düşündüm, 

Tanrı veya tanrının oğlu 

Üstlenmişse günahlarını

Niçin saygı duysunlar ki

Tanrının yarattıklarına? 

Ki, Tanrının yarattıkları

İnsan olabilir fark etmez

Hayvan olabilir fark etmez

Öldür öldürebildiğin kadar

Kullan kullanabildiğin kadar

Sömür sömürebildiğin kadar

Fark etmez! ...

Nasıl olsa, günah işlemiyorsun

Nasıl olsa, ceza çekmiyorsun

Dinin, inancın sana hürriyet vermiş

Öldür, çal, çırp, süründür, kullan, at

Fark etmez! .........

Düşündüm, 

O zaman sevgi sözleri niye? 

Tanrıya döndüm

Tanrılara döndüm,

Sapkınların tanrısı hariç

Bütün tanrılar doğaya kutsallık vermiş

Hele benim tanrım, Allah! ...

Yaratılana eziyeti suç saymış

Yaratılana haksızlığı suç saymış

Yarattıklarına karşı yapılan

Her türlü saygısızlığı, zulmü

Kendine karşı yapılmış saymış

Ve 

Hiçbir kimseye,

Peşinen, 

Suçunu bağışladım,

Suçunu ben üstlendim, 

Buyur istediğin kadar suç işle dememiş! ..

Ve benim bildiğim

Tanrı aşığı, tanrı dostu! ..

“Yaratılanı severim

Yaratandan ötürü”

Diyor.

Ve benim tanrım 

İnsanı seviyor

Doğayı seviyor

Doğadaki varlıkları seviyor

Onlara yapılan en küçük haksızlığı

En büyük suç ilan ediyor! ....

Ve benim tanrımın 

Sevgisinde yalan yok! ..

Ve benim tanrıma 

Gerçekten inananların sevgisinde

Yalan ve riya yok! ...

Ve benim tanrımın gözünde

Yalan ve riya en büyük suç! ..

Kim işlerse işlesin, 

Kim yaparsa yapsın! ..

20.01.2006-İzmir', 'Uzaktan seyrediyorum Birini boğa kovalıyor Elinde pelerin sallıyor Oyun bir müddet sürüyor Sonra genelde boğa ölüyor Seyreden insanlar zevk ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/yb-25-neyin-ispati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçinde', 'i-cinde-akin-dursun-lt77p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne doğrular gördüm yanlışların içinde

Ne yanlışlarda vardı doğruların içinde 

Hayat sürüyor geçiyor zaman içinde 

Gözleri görmüyor sevenin

Sevdalar içinde 

Geçmiş geçmiyor beyinler içinde 

Adı gibi olmuyor yüreğim pençesinde

Kara bir sevda peşimde 

Oyuncak olmuşum onun bunun elinde

Sevmek mi zor sevilmek mi? 

Kara bir sevdada ölüme yürümek mi? 

Sevmek kolay, kolay da

Onca sevdalar içinde

Yüreğini eline

Sevgiyi benliğine nakşedecek 

Seven bulmak,

Sevda bulmak, zor kendine



                                          

                                                                                                                                                                                                                                                                                  20.08.2001 / 01:00 İzmir', 'Ne doğrular gördüm yanlışların içinde Ne yanlışlarda vardı doğruların içinde  Hayat sürüyor geçiyor zaman içinde  Gözleri görmüyor sevenin S...', ARRAY['Türk Edebiyatı','Şiir','Akın Dursun']::text[], 8.5, '{"poet":"Akın Dursun","poet_slug":"akin-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/icinde-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir kalem Bir masa', 'bir-kalem-bir-masa-ozan-turk-zz0b1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karnımdaki ağrı

ve başımda yanıp sönen bu ateş,

Bir kaç notaya aldanıp da eğildiğinde bir kalem

Bir masaya...

İşte o an çıkageliyor tüm devrimler tarihten,

Yayılalım çoğalalım diyor,

Kitaplar,

Manifestolar,

Alfabeler

Hep sen ve ben.', 'Karnımdaki ağrı ve başımda yanıp sönen bu ateş, Bir kaç notaya aldanıp da eğildiğinde bir kalem Bir masaya... İşte o an çıkageliyor tüm devr...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-kalem-bir-masa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-akin-dursun-8ebos', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'güzel günler yakın dediler 

bende kandım

sevmek kolaymış sevilmek zor 

anladım 

nerde şimdi o söyleyenler hepsi tek tek öldüler 

inandım...

16.02.2002 / 01:55 İzmir', 'güzel günler yakın dediler  bende kandım sevmek kolaymış sevilmek zor  anladım  nerde şimdi o söyleyenler hepsi tek tek öldüler  inandım... ...', ARRAY['Türk Edebiyatı','Şiir','Akın Dursun']::text[], 8.5, '{"poet":"Akın Dursun","poet_slug":"akin-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gercek-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzünün Aynadaki Resmi', 'yuzunun-aynadaki-resmi-akin-dursun-hrk30', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün boyu düşünüyorum seni 

Düşümde duyuyorum ayak seslerini 

Birden uyanıp kapıya koşuyorum 

Bir türlü unutamıyorum, unutamıyorum

Yüzünün aynadaki resmini 

Kim bilir kaç bahar oldu 

Yokluğunda, baktığım her yer koskoca bir buz dağı 

Tüylerim ürperiyor 

Ve birden maske takıyor gözlerim

Yüzünün aynadaki resmine akıyor oluk oluk 

Seviyorum diyen sözlerim 

Gülüşünle açan güller, suskunluğa boğuluyor

Şu saksıdaki fesleğenler

Durmadan bir şeyler kırılıyor içimde 

Gecelerce, adını koyamadığım yıldızlar yağmalanıyor adınla 

Unutamıyorum o büyüdükçe büyüyen sevgini

Unutamıyorum hâlâ, saklı yüzünün aynadaki resmi 



24.01.2002 / 01:00 izmir', 'Gün boyu düşünüyorum seni  Düşümde duyuyorum ayak seslerini  Birden uyanıp kapıya koşuyorum  Bir türlü unutamıyorum, unutamıyorum Yüzünün ay...', ARRAY['Türk Edebiyatı','Şiir','Akın Dursun']::text[], 8.5, '{"poet":"Akın Dursun","poet_slug":"akin-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yuzunun-aynadaki-resmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıksın', 'asiksin-galip-uyar-zrze8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yarin göz yaşındadır

Aşk...

Görünce anlarsın

Eger ki sen de ağlarsın

Geçmiş olsun

Gözün aydın

Bil ki

Aşıksın', 'Yarin göz yaşındadır Aşk... Görünce anlarsın Eger ki sen de ağlarsın Geçmiş olsun Gözün aydın Bil ki Aşıksın...', ARRAY['Türk Edebiyatı','Şiir','Galip Uyar']::text[], 8.5, '{"poet":"Galip Uyar","poet_slug":"galip-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/asiksin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkma', 'korkma-galip-uyar-zb2pv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmekten korkma

Dolaşmaktan uçurum kenarlarında 

Korkma...

Sonuna kadar git yolun

Dönme sonunu görmeden

Bin kere çarpsa da kapılar

Suratına

Bin kere dönsen de

Ellerin boş

Ümidini soldurma

Her başlayan günle

Yeşert yeniden ümitlerini

Yeniden git kapısına

Otur bekle

Ama

Ne olursa olsun

Sevmekten korkma', 'Sevmekten korkma Dolaşmaktan uçurum kenarlarında  Korkma... Sonuna kadar git yolun Dönme sonunu görmeden Bin kere çarpsa da kapılar Suratına...', ARRAY['Türk Edebiyatı','Şiir','Galip Uyar']::text[], 8.5, '{"poet":"Galip Uyar","poet_slug":"galip-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/korkma-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözüyle İşitmesini Bilmeyene Göre Ağız Değilim', 'gozuyle-i-sitmesini-bilmeyene-gore-agiz-degilim-mehtap-tolu-ac2l4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözüyle işitmesini bilmeyene göre ağız değilim ben.

Gözünle işitmeyi öğrenmek için kulağını mı patlatmalısın.

Ben; 

Yüreği batmaya zorlasa da onu severim, çok severim hem de.

Çünkü; ötesini aramazlar.

 Ben:

Gönlünü har vurup, harman savuranı severim, 

çok severim hem de.

Çünkü; zorlu düğümdür onlar, ruh olarak yürürler.

Zengin ya da züğürt olunmaz bu sularda.

Öte dünya kuruntulu “Biz mutluğu bulduk diyenler”

Gündüz küçük hazları vardır, 

Gece küçük hazları vardır.

Gözlerine uyku vurduğunda ağızları açık uyuyakalırlar.

Hanım hanımcık dişiler, efendiden beyler.

Dürüstlük denen erdemden çıldırasıya nefret ederler.

Erdemsizlikleriyle baş edemezler,

Utanmayacak kadar,  büyük de  değildirler.

En yüksek umutlarla sevgi beslemesini bilmezler.

Sevgim ve umudum hakkı için; 

Sevgimden ve umudumdan asla ödün vermedim.

Hoş geldiniz bu sulara! ! ! 

Sizi candan yürekten severim.

Gönüllü buyurun bu sulara.

Ama bilin ki; gözüyle işitmesini bilmeyene göre ağız değilim.', 'Gözüyle işitmesini bilmeyene göre ağız değilim ben. Gözünle işitmeyi öğrenmek için kulağını mı patlatmalısın. Ben;  Yüreği batmaya zorlasa d...', ARRAY['Türk Edebiyatı','Şiir','Mehtap Tolu']::text[], 8.5, '{"poet":"Mehtap Tolu","poet_slug":"mehtap-tolu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gozuyle-isitmesini-bilmeyene-gore-agiz-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybettim İçimdeki Dostumu...', 'kaybettim-i-cimdeki-dostumu-ali-orhan-gunaydin-o0c7n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllar sonra tekrar uğramıştı bana..

Günlerce hasbihal ettik,dertleştik kahvehane masalarında,

Yudumladığım çayın tadı,

Tenefüs ettiğim havanın kokusu bile bambaşka olmuştu onun yanında...

Habersiz geldi...

Geldiği gibi haber vermeden de çekip gitti.

Kaybettim içimdeki dostumu...

Dalından zorla koparılmış bir yaprak gibi,

Yapayalnız bıraktı beni...

Haber saldım tanıdıklara,dört bir yana gören bulan var mı? 

Çaresiz kaldım,peşini bıraktım.

Şimdi aradığım başka...

Benim gibi aradığını bulamayan, başka dostlarda var mı?', 'Yıllar sonra tekrar uğramıştı bana.. Günlerce hasbihal ettik,dertleştik kahvehane masalarında, Yudumladığım çayın tadı, Tenefüs ettiğim hava...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kaybettim-icimdeki-dostumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '....::Veda::....', 'veda-emrah-kaan-7lc8b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beklı  huzun  lu  bir sonbahar  aksam i 

Yada  sisli  bir  kıs  gecesi 

Cesedimi  bulacaklar camurlar ortasında 

Gelip sana  haber  verecekler sasıracaksın 

Bir  Elinde  Resmin

Bir  Elinde  Silah ı var  Diyecekler  inanmayacaksın 

Sonra  Kalkıp  Geleceksin  yanıma 

Cesedimi  Görunce  tas  kesileceksin 

İste o  an Anlayacaksin   seni  ne  kadar  sevdigimi

Eller  imi  Tutup  Affet Affet  Beni  Diyeceksin 

Seni  coktan  Affet  tigimi  Bilmeyeceksin

Sonra  egilip  Sarılacaksın  Soguk  Bedenıme 

iste  o an   Bir  Fısıltı  Duyacaksın... 

                                                             ELVEDA...', 'Beklı  huzun  lu  bir sonbahar  aksam i  Yada  sisli  bir  kıs  gecesi  Cesedimi  bulacaklar camurlar ortasında  Gelip sana  haber  verecekl...', ARRAY['Türk Edebiyatı','Şiir','Emrah Kaan']::text[], 8.5, '{"poet":"Emrah Kaan","poet_slug":"emrah-kaan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/veda-194-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esir ve Eser', 'esir-ve-eser-galip-uyar-ewlcj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elimde resmin vardı

Dilimde ismin

Aklımda gözlerin..

Heryerde sen

Sevdiğim...

Şimdi yalnızlığın kederi 

Sevememişim sensizliği

Sessiz bir çığlık:

Hasretin

Sen sevdiğim:

Hasretim

Aşkının esiriyim 

Aşkının eseriyim', 'Elimde resmin vardı Dilimde ismin Aklımda gözlerin.. Heryerde sen Sevdiğim... Şimdi yalnızlığın kederi  Sevememişim sensizliği Sessiz bir çı...', ARRAY['Türk Edebiyatı','Şiir','Galip Uyar']::text[], 8.5, '{"poet":"Galip Uyar","poet_slug":"galip-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/esir-ve-eser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fazlalıklar...', 'fazlaliklar-pinar-koc-k06do', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sana hep fazla geldim..

Daha ağır bastı yüreğimin sancıları…

Kalkamadım altından hiç

Tutamadığım çenemin,

Ve sarf ettiğim onca sözlerin…

Fazlamı deliydim,

Yoksa fazlamı akıllı…

Neydi benim bu kadar içimi döktüren…

Çok mu doğal davrandım,

Yoksa yapmacık mı sandın…

Ben sana hep bir kalıp fazla geldim…

                                                                                        20.01.06', 'Ben sana hep fazla geldim.. Daha ağır bastı yüreğimin sancıları… Kalkamadım altından hiç Tutamadığım çenemin, Ve sarf ettiğim onca sözlerin…...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fazlaliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben,Ben Değilim...', 'ben-ben-degilim-pinar-koc-11vtr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben,

Ben değilim aslında,

Senin bildiğin gibi…

Ne kızıl saçlarım var artık,

Nede mavi gözlerim…

Yumruklarımı sıkıyorum 

Sebepli sebepsiz….

Ve kan çanağı gözlerim dolmuyor artık

Ağlamıyorum…

Bir berrak pınar değil artık,

Çağlayan sularım…

Veya bir mavi deniz olamadı hiç

Yüreğim

Şaşkın balıkları barındıran….

Ben,

Ben değilim aslında,

Senin bildiğin gibi…

Ne sarı saçlarım var artık,

Nede yeşil gözlerim…

                                                                              20.01.06', 'Ben, Ben değilim aslında, Senin bildiğin gibi… Ne kızıl saçlarım var artık, Nede mavi gözlerim… Yumruklarımı sıkıyorum  Sebepli sebepsiz…. V...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-ben-degilim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmesin', 'gelmesin-seyfet-bozcali-gbymm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dost olupta dostluklara karıştık,

Dünya için yarıştık ha yarıştık,

Boş şey için kavga ettik barıştık,

İnsanlarca sevilmeyen gelmesin...

Aşkınla boyandım,badeler içtim,

Candan seven insanlarla tanıştım,

Tatlı muhabbetle kendimden geçtim,

Muhabbeti hiçe sayan gelmesin...

Seyfet derki canlar dünya fanidir,

Gerçek mekan Ahiret mekanıdır,

Gönlümüzde ol Muhammed aşkıdır,

Gönlünde karası olan gelmesin...', 'Dost olupta dostluklara karıştık, Dünya için yarıştık ha yarıştık, Boş şey için kavga ettik barıştık, İnsanlarca sevilmeyen gelmesin... Aşkı...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelmesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz Aşk', 'umutsuz-ask-ferit-gursoy-my41p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deliyim ben deli

Sevdim ya seni

Koştum ya yıllarca peşinden

Habersiz 

Yağmur çamur demeden

Asfaltı olmayan sokaklarınız da

Bekledim ya ayaz gecelerde

Işık bekledim pencerende

Sonra perde arkasında gölgeni 

Kaç gece bekledim bilirmisin? 

Nöbet tutar gibi

Düşmanını Uykunun

Deliyim ben deli

Yıllar sonra başkasının koynundayken bile

Üşüme hissettim içimde

Ve hala nöbetteyim

Asfaltlanmış ama ışıksız pencerende', 'Deliyim ben deli Sevdim ya seni Koştum ya yıllarca peşinden Habersiz  Yağmur çamur demeden Asfaltı olmayan sokaklarınız da Bekledim ya ayaz ...', ARRAY['Türk Edebiyatı','Şiir','Ferit Gürsoy']::text[], 8.5, '{"poet":"Ferit Gürsoy","poet_slug":"ferit-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/umutsuz-ask-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yirmi Üç Nisan', 'yirmi-uc-nisan-altay-taskin-75a3i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vatanın her karışı

Özlemişti barışı

Gelip çatmıştı

Kurtuluş yarışı

Akan ırmakları

Esen rüzgarları

El ele coşkuluydu

Türkiye toprakları

Çocuklara armağan

Bugün yirmi üç nisan

Kırmızı bayrak ellerde

Kalpler dolu heyecan

Kutlayalım bugünü

Duyuralım ününü

Tüm dünyada alalım

Çocukların gönlünü', 'Vatanın her karışı Özlemişti barışı Gelip çatmıştı Kurtuluş yarışı Akan ırmakları Esen rüzgarları El ele coşkuluydu Türkiye toprakları Çocuk...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yirmi-uc-nisan-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Delisin..', 'sen-delisin-pinar-koc-9j2pr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen delisin…

En olmadık zamanlarda sevdin hep beni….

Uçurumların kenarlarından aldın,

Dipsiz kuyulara attın sevgimi….

Şimşekler çaktı kimi zaman,

Derin düşüncelerinde.

Kimi zaman sustun,

Kızıl derin sularda duruldun….

Sen delisin aslında…	

En olmadık anlarda gömdün sevgini…

Bir katil zanlısı gibi kaçarken kendinden,

Ben buradayım diye bağıran

Yüreğini susturamadın hiç….

Ütopyalar kurdun kendi içinde,

Ve kendi kentinde kayboldun…….

Sen delisin aslında…

En olmadık anlarda hep sus pus oldun…..

Konuşsan bitecekti acıların,

Bir konuşsan,

Dünyan yıkılacaktı kapkara olan……..

Sarı bir güneş doğacaktı ansızın,

Ve sen kendinle,

Henüz tanışmadığın,

Sadece kendinle varolacaktın….

Sen delisin aslında…..

En olmadık anlarda,

En olmadık zamanlarda,

Ve en olmadık diyarlarda

Sadece kendini sevdin…….

                                                                            20.01.06', 'Sen delisin… En olmadık zamanlarda sevdin hep beni…. Uçurumların kenarlarından aldın, Dipsiz kuyulara attın sevgimi…. Şimşekler çaktı kimi z...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-delisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azabı Burhan Dabbe', 'azabi-burhan-dabbe-ahmet-ferit-cosan-hbh75', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Semavi bombaların

Kullarının kahır ayetleri-

Baktık sana,

Tanrının yarısı boş dedik,

Kulların yarını dolu gördüler.

Israrla geldin sular aşıp,

Kondun baharatlı, ipekli

Doğunun kubbelerine.

Dişlerin katran karası,

Gözlerinde kızılı kanın.

Komşumun ırzına çökmüş,

Duyduk seni,

Tanrının yarısı İblis dedik,

Kulların yarını Mesih gördüler.

Çevirmeye kafi kudretin

Yer altı cevahirini

Yer üstü azrailine.

Dağım, taşım, aşım 

Hep kurşun, 

	Kurşun, 

		Kurşun

Taslarım boş,

Silme kemik tüm bedenler...

Yaş içinde sana koşan,

Sana tapan kulların,

Sundular sana kurbanlar

Derileri ışık yutan.

Azabını tattık, 

Siyaha boğup alemi

''Işık taşırım cihana'' diye

Sırtlanlara duyuran,

Yalancı Promethe! 

Olmadığını söyledik,

Kulların Ol’durdular.', '-Semavi bombaların Kullarının kahır ayetleri- Baktık sana, Tanrının yarısı boş dedik, Kulların yarını dolu gördüler. Israrla geldin sular aş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/azabi-burhan-dabbe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgalan', 'dalgalan-altay-taskin-hilmf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey göklerin barış güvercini

Kanatlarını açmış uçuyorsun bembeyaz

Ey toprağın kırmızı gülü

Kokuyorsun solmayacaksın kış yaz

Ey denizlerin yılmaz gemisi

Yüzüyorsun batmayacaksın dalgalardan

Ey kalplerin unutulmaz sevgilisi

Yaşıyorsun sen selam sana yaşayanlardan', 'Ey göklerin barış güvercini Kanatlarını açmış uçuyorsun bembeyaz Ey toprağın kırmızı gülü Kokuyorsun solmayacaksın kış yaz Ey denizlerin yıl...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dalgalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıraktığın Yerde Bulursun Beni', 'biraktigin-yerde-bulursun-beni-yusuf-onder-bahceci-sal6n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben seni sevdiğimi niye demedim,

Kalbimden söylemek, niyet eyledim,

Senden ayrı kaldım hiç gülemedim,

Bıraktığın yerde bulursun beni.

Küçük bir pastane, birkaç sandalye,

Senle konuşurken kalbim ne halde,

Kelimeler boğazımda düğümlendide,

Bıraktığın yerde bulursun beni.

Sen bu kadar zalim biri değildin,

Neden yalan, dolan söze eğildin,

Sen beni bilirdin neden yanıldın,

Bıraktığın yerde bulursun beni....', 'Ben seni sevdiğimi niye demedim, Kalbimden söylemek, niyet eyledim, Senden ayrı kaldım hiç gülemedim, Bıraktığın yerde bulursun beni. Küçük ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biraktigin-yerde-bulursun-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Girdaba Giriyorum', 'girdaba-giriyorum-suheyl-turkoglu-uzoki', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşanmışın üstünde,

Bir sevgi istiyorum,

Gökyüzünden aşk yağsın,

Mutluluk diliyorum.

Toprakla su birleşin,

Dünyaya hayat versin,

Barış rüzgarı essin,

Aşığım biliyorum.

Bülbüller incinmesin,

Güller yaprak dökmesin,

Gönül küsüp gitmesin,

Sevdamı gizliyorum.

Kalbime inen sıcak,

Ruhumu anlayacak,

Dönüşü olmayacak,

Girdaba giriyorum.

Bestelenebilir.', 'Yaşanmışın üstünde, Bir sevgi istiyorum, Gökyüzünden aşk yağsın, Mutluluk diliyorum. Toprakla su birleşin, Dünyaya hayat versin, Barış rüzga...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/girdaba-giriyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznüm kadar', 'huznum-kadar-ekrem-anac-lcnl2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sevdiğim

derin anlamlı gözlerin 

aşk tenbihleyen

can sıkıntılarım kadar yakın olsun

hüznüm kadar 

can sıkıntılarım kadar sadık olsun 

hüznüm kadar 

sevdiğim', 'sevdiğim derin anlamlı gözlerin  aşk tenbihleyen can sıkıntılarım kadar yakın olsun hüznüm kadar  can sıkıntılarım kadar sadık olsun  hüznüm...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Anaç']::text[], 8.5, '{"poet":"Ekrem Anaç","poet_slug":"ekrem-anac","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siirin-adi-yok-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Deliyim...', 'ben-deliyim-pinar-koc-ygeav', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben deliyim.

En olmadık zamanlarda beklerim seni

Veya

Uçsuz bucaksız özlemlerde ararım….

Kurumuş ağaç yapraklarını

Bir ömür gibi koklarım….

Kimsesiz bir çocuk gördüğümde

Onu güldürür,ben ağlarım…

Ben deliyim….

En olmadık zamanlarda severim seni….

Benim olduğunda uzaklaştırır,

Kaybettiğimde,bir köşede içten içe ağlarım…

Sebep aramam sessiz gidişlerinde,

Gelince sen hesap sorarım…

Seversin,

Bir başkası vardır bilirim…

İnadına sever seni,

İnadına nefret ederim…

Ben deliyim….

En olmadık zamanlarda yudumlarım sevgini…

Kusana kadar içerim,

Sonra neden diye sorarım….

Mide bulantılarımı senden bilirim,

Başım dönünce sevgine düşerim….

Ben deliyim…

En olmadık zamanlarda,

En olmadık yarınlarda,

Ve

En olmadık savaşlarda

Seni 

Her zaman sevmeyi bilirim….

                                                                               20.01.06', 'Ben deliyim. En olmadık zamanlarda beklerim seni Veya Uçsuz bucaksız özlemlerde ararım…. Kurumuş ağaç yapraklarını Bir ömür gibi koklarım…. ...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ben-deliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Dileğim Buydu', 'tek-dilegim-buydu-yusuf-onder-bahceci-2ylwx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerimden akan yaşı silseydi,

Seni sevdim ama kader deseydi,

Onun için ölürüm bunu bilseydi,

Tek dileğim buydu sevdim deseydi.

Hergün rüyalarda gördüm deseydi,

Sen beni çok sevdin bildim deseydi,

Bütün suçlu annem annem deseydi,

Tek dileğim buydu sevdim deseydi.

Şimdi mutlu değil biliyorum ben,

Ona sabır sabır diliyorum ben,

Beni bırakıpta böyle giderken,

Tek dileğim buydu sevdim deseydi....', 'Gözlerimden akan yaşı silseydi, Seni sevdim ama kader deseydi, Onun için ölürüm bunu bilseydi, Tek dileğim buydu sevdim deseydi. Hergün rüya...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tek-dilegim-buydu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış Meşalesi', 'baris-mesalesi-altay-taskin-kp14x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hep rüyamda görüyorum

evrenin her bahçesinde

sıcak renkleri

açan çiçekleri

beyaz-kırmızı-pembeleri

seslerini duyuyorum

kanat çırpan kuşların

kanarya-bülbül-martıların

adım adım geziyorum

büyük kıtaları

çocuklar bahçelerde

sevinç muştuları yüzlerde

silahları tanımıyorum uykuda

görünmüyor onlar gözüme

uçuyorum mutluluktan

serinliyorum bir an

yaşam rüyalar gibi

pembe olsun

barış meşalesi

dünyanın tepesinde

hep yansın dursun

geceler kısa da olsa

uykular derin olsun

Yazı Dergisi Mart/Nisan 1993', 'hep rüyamda görüyorum evrenin her bahçesinde sıcak renkleri açan çiçekleri beyaz-kırmızı-pembeleri seslerini duyuyorum kanat çırpan kuşların...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/baris-mesalesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YB-32 İncecik/İricik', 'yb-32-i-ncecik-i-ricik-mehmet-coban-al5w4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün, 

Şişmanlarla ilgili 

Şişmanlıkla ilgili

Bir program seyrediyorum

Bütün zengin ülkelerde

Baş hastalık olmuş obezite 

Özellikle süper güçlerde

Yenilenlerden içilenlerden

Yenilmeyeceklerden içilmeyeceklerden

Söz ediyorlardı durmadan

Bunlarla sürüyordu program

Değişik adamlar konuştu

Konuşanlar coştukça coştu

Bir başka gün, 

Açlıktan söz ediyordu 

Başka bir program

Bir deri bir kemik insanlar

Hastalık ve sefalet içinde

Fakir ve yoksul ülkelerde

Bir dilim ekmeğe muhtaçlar

Yoksulluk ne kelime, aç, açlar

Bir başka gün, 

Bir haber izliyorum

Afrika’nın bir ülkesinde

Süper güçler çıkar peşinde

Uğraşıyorlar altınıyla madeniyle

Götürmeseler altınları madenleri

En zengin ülke olacak yoksul ülke

Hâlbuki şimdi sefaletin ötesinde

Hem aç, hem köle süper zengine

Sözde insanlık, hürriyet sözcülerine! ..

Düşünüyorum, 

Zenginler fakirleri sömürmüş

Şişmanlıktan ölüyor……..

Fakirleri zenginler sömürmüş

Fakirlikten ölüyor………

Kurtulan yok,

Görünen insanlar ölüyor! .

Niçin? 

Üç beş çılgın yüzünden mi? 

20.01.2006-İzmir

.', 'Bir gün,  Şişmanlarla ilgili  Şişmanlıkla ilgili Bir program seyrediyorum Bütün zengin ülkelerde Baş hastalık olmuş obezite  Özellikle süper...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yb-32-incecik-iricik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık-2', 'karanlik-2-i-smail-arslan-1dl41', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Büyük,kocaman bir dünya

Renk cümbüşü her yer

Kalabalık insanlar

Cıvıl cıvıl çocukların oynadığı

Yaşamanın güzel olduğu dünya 

Bana karanlık.

Hayat yaşanıyor boş dolu

Herkes bir alem kendi içinde

Gündüzleri aydınlık

Geceleri bile aydınlatılmış şehir

Benim,içim karanlık

Umut ışığı aydınlatmıyor gönlümü

Sadece bir kıvılcım var

Oda kör ve isli

Işık saçmıyor gönlüme

Gözümde aydınlık var

Lakin gönlüm hala karanlık', 'Büyük,kocaman bir dünya Renk cümbüşü her yer Kalabalık insanlar Cıvıl cıvıl çocukların oynadığı Yaşamanın güzel olduğu dünya  Bana karanlık....', ARRAY['Türk Edebiyatı','Şiir','İsmail Arslan']::text[], 8.5, '{"poet":"İsmail Arslan","poet_slug":"i-smail-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karanlik-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toz ve Kızıl', 'toz-ve-kizil-arif-onbasioglu-1ci25', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neden kızıla boyadın denizleri anne

Ben daha ölmedim

Ne günahı var, Tanrı mavisinin

Ben daha ölmedim 

neden tozlu kefenim', 'Neden kızıla boyadın denizleri anne Ben daha ölmedim Ne günahı var, Tanrı mavisinin Ben daha ölmedim  neden tozlu kefenim...', ARRAY['Türk Edebiyatı','Şiir','Arif Onbaşıoğlu']::text[], 8.5, '{"poet":"Arif Onbaşıoğlu","poet_slug":"arif-onbasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/toz-ve-kizil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağol', 'sagol-murat-polat-2-2rzgr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yandan ağlarken düşündüm

Benim yazdıklarımdan,

Benim söylediklerimden

Daha fazla, daha sevecen,

Daha umut vaat eden

Sözler yoktu! 

Konuk Ferdi babaydı

Devletin sahnesinde.

Benim tarzımdı...

Yada ben onların! 

İnsanlar coşkuyla alkışlarken düşündüm

Benim söylediklerim niye deli saçması? 

İnsan hepmi güler, gülmeli? 

Olamazmı hiç hüzün ve hasret

Olamazmı bazılarında hep acı,

Keder ve bekleyiş...

Bu insanlar derttende anlarlar

Hasret ve beklemenin ne olduğunuda

Tamam hayat bir eğlence kimine

Bizlerde hayatın hüzünlü yüzü

O kadar...

Sağol Ferdi baba

Bana moral verdiğin için! ! ! 

Bilsen uzaklarda kimler ağlıyor...

                                Kasım 2006', 'Bir yandan ağlarken düşündüm Benim yazdıklarımdan, Benim söylediklerimden Daha fazla, daha sevecen, Daha umut vaat eden Sözler yoktu!  Konuk...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sagol-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günüm', 'dogum-gunum-murat-polat-2-wo6wv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün benim doğum günüm

Tam bir yıl önce sanki yoktum! 

Çok sancılıydım önce, acılı

Sonra biraz biraz duruldum.

Bugün benim doğum günüm

Bir yıl önce dibi buldum

Çok yandım, kavruldum

Yavaş yavaş soğudum.

“bugün o doğdu ben cansız”

demiştim bir zamanlar

şimdi o yok artık...öldü

ben doğdum bugün yeniden! 

                     07 Mart 2005', 'Bugün benim doğum günüm Tam bir yıl önce sanki yoktum!  Çok sancılıydım önce, acılı Sonra biraz biraz duruldum. Bugün benim doğum günüm Bir ...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dogum-gunum-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senle dolu yüreğim. ..(Şarkı Biçimi)', 'senle-dolu-yuregim-sarki-bicimi-ahmet-unal-cam-rn4e8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaralanmış çırpınır       

Senle dolu yüreğim.      

Her an, bin kez kırılır      

Senle dolu yüreğim.      

Umut istedim senden   

Dert verdin dert üstüne

Can ayrılmadı tenden  

Ama ne kaldı bende?  

Yine kaldı güneşsiz       

Yine kaldı çaresiz,        

Yine kaldı bak sensiz,   

Senle dolu yüreğim.      

Umutlarımı aldın,         

Hüzün zaten bende çok. 

''Unut''diyenler olur,      

Acımı anlayan yok.      

Karlı dağlarda kaldım,   

Viran yollarda kaldım,   

Kırdın, içine baktım,       

Senle dolu yüreğim.      

Işıktın gözlerime,         

Şimdi karanlıktayım.    

Yarındın yüreğime,      

Yarınsız hayattayım.    

Toprak olup çiğnensem,

Bulut olupta gitsem.

Ne kadar inkar etsem,

Senle dolu yüreğim.

Ötelerden ses verir,

Çektiğim şu ''Ah..'' larım.

Gülü yok, diken verir,

Yalnızlığım...ağlarım.

Yarın sensiz olacak,

Mümkün değil unutmak.

Gel de istersen bir bak

Senle dolu yüreğim.

Sarıldım acılara,

Sarıldım sensizliğe,

Düştüm karanlıklara,

Hasret kaldım gülmeye.

Acılardan bir gemi,

Yalnızlığın kalesi,

Susuz bir toprak gibi

Senle dolu yüreğim.

Tebessümün aklımda,

Düşünüpte özlerim.

Yaş kalmamış baktım da

Yaşsız ağlar gözlerim.', 'Yaralanmış çırpınır        Senle dolu yüreğim.       Her an, bin kez kırılır       Senle dolu yüreğim.       Umut istedim senden    Dert ver...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/senle-dolu-yuregim-sarki-bicimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '! Sadece Senin İçin!', 'sadece-senin-i-cin-multe-ci-han-8aott', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine aynı yerdeydim

Güneşin doğuşunu izliyordum

Her zaman yaptığım gibi...

Düşünüyordum hayatımı,

Dost diye yaklaştıklarımın yalanlarını

Tutunacak dalım yoktu.

Sıcak eller soğumuş; 

Umutlarım yok olmuştu

Hafif hafif yağmur başlamıştı

Islanıyordu vücudum

Olmayacak hayallere dalıyordum

Birden toprakta bir kıpırtı meydana geldi

Bir çiçek filizleniyordu...

Taptaze kokusu etrafı sardı

O kadar güzeldi ki

-büyülendim-

Konuşamadım, sadece baktım.

Bana inat giderek büyüyor

Beni ısıtıyordu

Bu bir mucizeydi! ! ! 

-biliyordum-

Hayata tekrar bağlanıyordum...', 'Yine aynı yerdeydim Güneşin doğuşunu izliyordum Her zaman yaptığım gibi... Düşünüyordum hayatımı, Dost diye yaklaştıklarımın yalanlarını Tut...', ARRAY['Türk Edebiyatı','Şiir','Mülte Ci Han']::text[], 8.5, '{"poet":"Mülte Ci Han","poet_slug":"multe-ci-han","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sadece-senin-icin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Adanmış Bir Kurban! ! !', 'aska-adanmis-bir-kurban-kubra-gulbahar-vcjiu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ortaköy''de köşe başında ki bir binanın en üst katında bir adam yaşarmış... Siyahın en güzelini gözleri için çalmış, buğdayın en sarısını teninde saklarmış... Öylesine yaşıyormuş her şeyden habersiz... Bir dolu kelime biriktirmiş yüreğinde ama söyleyecek kimsesi yokmuş yanında, kolunda, içinde, dilinde... Geceler boyu sürmüş yalnızlığı... Şikâyet etmekten usanmış... 

Bir gün umutlarını bıraktığı o masada, ona candan yakın ve uzun zamandır tanıdığı, dünyasını unutmuş o kız; 

- sen çıldırdın mı? 

diye bağırdı ona... Adam şöyle bir dönüp baktı kızın yüzüne..! Kız daha önce o kadar sıcak ve samimi bir bakışı hiç bir gözde yakalayamamıştı. Adam; 

-Yapmamam gereken bir şey mi bu

dedi.

Kız; 

-Bu bence korkaklık... Geriye çekiliş... Anlamsızca sinmek... Bu kadar mısın? Fazlasını görmek istiyorum! 

dedi.

Adam; 

-Gelme korkuyorum... Bu başlangıç benim sonumdur... diye karşılık verdi.

Kız ayağa kalktı, içtiği bira bardağını eline alarak adamın yanına yaklaştı ve..

- Şu bardağın içindekini görüyor musun? Koyu sarı ve çok masum duruyor... Bunu hiç tatmasam, sadece dıştan bakarak, bana bunun ne kadar alkol barındırdığını anlatabilir misin? Bunu denesen bile ben anlayabilir miyim? İşte sen bana böylesin... Umutlarının bittiğini söylüyorsun ama ben senin yüreğini göremiyorum... Buna nasıl inanabilirim... 

dedi... ve adam ona bakarak

-Ben tüm umutlarımı sende unuttum... Onları bana geri ver... diye haykırdı! 

Kız şaşkın bir o kadarda heyecanlı bir ses tonuyla...

-Ya bu üzerinde yürüyemeyeceğin bir yolsa...! dedi.

Adam; 

-Ben bu yol üzerinde yorulmaya hatta kendimi tüketmeye razıyım diye karşılık verdi...! 

Bu konuşmanın ardından günler, aylar geçmişti... İkiside öyle mutluydu ki... Kız daha önce kendisini bu kadar özel hissettiğini hatırlamıyordu ve karşı tarafa özel olduğunu bu denli inandıracağını kendisi bile tahmin edemiyordu... Hayatı yeniden öğreniyor ve öğrenmenin verdiği keyifle bildiklerini korkmadan paylaşıyordu... Birbirlerinin yanında buldukları huzurun tadını daha önce kimselerde bulamamışlardı...

ve... ilk defa birbirlerini anlamak istemedikleri o gün geldi! ! 

Adam eğitimini tamamlamak için İngiltere''ye gitmek istediğini ve 4 yıl boyunca orda kalacağını, yılda iki kez onar günlük tatil hakkında kızı görmek için İstanbul''a geleceğini en uygun bir dille kıza anlatmaya çalışıyordu... Kız onu anlamak istemiyordu... aralarında anlamsız bir tartışma başladı...

K: Seni anlamıyorum.. İyi bir bölümden mezunsun. Sorun yabancı dil olsa seni anlayacağım ama onuda gayet iyi bir şekilde konuşabiliyorsun. İyi bir işin var ve olmak istediğin yerdesin.. Daha ne istiyorsun.

A: Orada alacağım eğitimle, hayal bile edemeyeceğim bir yerde olacağım çünkü! 

K: Çıldırmışsın sen... Elindekileri de kaybedeceksin. Bahsettiğin zaman dilimi üç beş ay değil, dört yıldan bahsediyorsun... Kim bekler o kadar seni söyle bana... Hadi beni bırak..! Geldiğinde çalıştığın şirket, ailen,  arkadaşların... aklına gelebilecek her şey değişmiş olacak..! Hiç bir şeyi bıraktığın gibi bulamayacaksın... Buna katlanabilecek misin? 

A: İşimle bağlantım kesilmeyecek... İngiltere''de şirkete bağlı bir firma var oradan yapacağım iş takiplerini.. Ailem ve arkadaşlarımsa benim uzun zaman dışarıda kalmama zaten alışıklar... ve biliyorum ki sen asla değişmeyeceksin... Geriside benim için o kadar önemli değil zaten..! 

K: Kusura bakma ben buna anlayış gösteremem... Senin bu hırslarının sonu gelmeyecek... Seni bulduğum zaman umutların sonuna kadar tükenmişti. Hiç bir şey gözünde değildi ve ben elimden gelen gayreti göstererek seni hayata bağladım... Ben sana bitirdiğin umutlarını geri veren kişi oldum... Ve şimdi senin hırsın yaşamak istediklerinin bile önüne geçiyor... Ben sana bu umudu, anlamsız bir hırs uğruna tüketmen için vermedim! Tekrar başa dönemem... Yoruldum... Beni yeteri kadar yordun... Sana son kez söylüyorum... Dilediğin kadar düşün ve bana cevabını ver ''gitme''...

A: Evet her şeyimin adı oldun ve bir daha kimsenin sana veremeyeceği bir sevgi yaşattım sana... Tüm yaşattıklarının teşekkürü olarak... ama beni şimdi neden anlamıyorsun bunu aklım almıyor... Amacım sana her şeyin en iyisini verebilmek... ve gitmem gerektiğine inanıyorum... Bana şimdi kızacaksın ama çok uzun bir zaman geçmeden beni anlayacak ve hak vereceksin...

K: Hiç ama hiç tanımamışsın beni... Ben senden bundan fazlasını zaten beklemiyordum... Git.. Seni yolundan asla men etmek istemem... Umarım her şey dilediğin gibi olur... ama ben artık yokum bunu bil... Bu saatten sonra vazgeçmen bende bir değişiklik uyandırmayacak... Yolun açık olsun.! ! 

dedi ve bulunduğu yerden ayrıldı... Haftalar geçti ve kızın telefonu hiç susmak bilmedi... En sonunda kız, adama bir mesaj çekti ''Ben aşkı Ortaköy''de köşe başında ki bir binanın en üst katında unuttum ve bir daha hatırlamak istemiyorum. Geri dönüşlerim asla olmamıştır... Olmayacakta..! ''

Adamın nasıl bir hal aldığı, cevap olarak çektiği mesajdan anlaşılabiliyordu... ''Canım biliyorum bana kızgınsın... ama vazgeçtim gitmeyeceğim... Seninle konuşmam lazım... Boğuluyorum... Beni bu şekilde yalnızlığıma uğurlayamazsın... Seni seviyorum hemde kimselerin anlam veremeyeceği kadar çok..! Lütfen telefonu aç''

Kız kararını çoktan vermişti. Onunla gittiği hiç bir mekâna bir daha asla uğramadı... Ortak arkadaş grubundan kimsenin kendisine ulaşmasına izin vermedi. Aradan iki ay geçmişti... Artık telefonu çalmıyordu... Ondan gelen bir mesaj dahi yoktu... ve içinden yine aynı cümleyi geçirdi... 

K: Ne kadar doğru bir sözmüş... Diyen ne güzel söylemiş... ''Hiç bir insan unutulmayacak kadar değerli değildir'' diye... dedi ve o dünyasını unuttuğu hayatına tekrardan geri döndü... 

Bir gün İstiklal caddesinde yürürken adamın çok yakın bir erkek arkadaşı koşar adımlarla kızın yanına geldi... Kız onu dinlemek dahi istemiyordu... 

K: Ben kendimi ondan da onun çevresinden de çoktan soyutladım... Konuşulacak bir şey yok

-: Oda kendini senden ve hepimizden soyutladı artık

K: Anlamadım? 

-: Annesine gitmişti. Yemek yiyip bir zaman sonra annesinin odasında yatmak istediğini, başının fena halde ağrıdığını ve kimsenin onu rahatsız etmemesini söyleyerek, odaya girmiş... Zaman sonra annesi yanına geldiğinde, kullandığı tüm tansiyon haplarını yuttuğunu görmüş... Öyle ceset gibi yatıyormuş yatakta... Hastaneye bile yetiştirememişler... O artık yok! ! ! 

K: Hayır... Şaka yapıyorsun... Bu kadarı fazla! ! Bunu ben kaldıramam! ! Bu vicdan azabıyla yaşayamam! ! ! 

diye ağlayarak ayrıldı oradan... Kimseye anlatmadı bu sıkıntısını... Yapacak hiç bir şey onu geri getirmeyecekti... Uzandığı yatakta Tanrı''ya ettiği şu duayla kendini cezalandırdı...

K: Tanrım beni yalnızlığa soy... Bu yürek içinde kimseyi yaşatmasın bundan sonra ve hiç bir beden bu yüreği kabul etmesin aşk adına... Gözlerimi ebediyen kapattığımda, beni o soğuk toprakla nişanla! ! !', 'Ortaköy''de köşe başında ki bir binanın en üst katında bir adam yaşarmış... Siyahın en güzelini gözleri için çalmış, buğdayın en sarısını ten...', ARRAY['Türk Edebiyatı','Şiir','Kübra Gülbahar']::text[], 8.5, '{"poet":"Kübra Gülbahar","poet_slug":"kubra-gulbahar","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/aska-adanmis-bir-kurban-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Vatan Benimdir Korurum Onu', 'bu-vatan-benimdir-korurum-onu-yusuf-onder-bahceci-g148p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vatanıma kast eden kardeşim olsa,

İnan ki affetmem Dünya bir olsa,

Bahçemdeki güllerin tamamı solsa,

Bu Vatan benimdir korurum onu.

Mert olsun düşmanım göreyim hele,

Bu Vatan''a kim kasteder bileyim hele,

Meydan okuyorum sözüm bilene,

Bu Vatan benimdir korurum onu.

Çanakkale Savaşını tüm Dünya bilir,

Atasını bilmeyen soysuz neleri bilir,

Yiğit olan Yiğit namusu için ölür,

Bu Vatan benimdir korurum onu.

Adımız Mehmetçiktir, andımız ölüm,

Dünya''da mazlumlara kim yapar zulüm,

Şöyle beri gelsin hele göreyim boyun,

Bu Vatan benimdir korurum onu....', 'Vatanıma kast eden kardeşim olsa, İnan ki affetmem Dünya bir olsa, Bahçemdeki güllerin tamamı solsa, Bu Vatan benimdir korurum onu. Mert ols...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-vatan-benimdir-korurum-onu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Sevgimle Kal Bebeğim *', 'sevgimle-kal-bebegim-i-brahim-dikmen-2-4pux7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhaba canım

bu kadar seviyorken

ayrılmak ta niye? 

sormayacağım

nasılsın,iyimisin diye.

yüreğinin nasıl acıdığını

kor içinde yandığını

bilmezmiyim.

lakin! 

öyle naçar kaldım ki

elimden birşey gelmiyor gülüm.

seni,söküp almak

mutsuzluğuna

mutluluk katmak

hapsolduğun prangaları

kırmak istemezmiyim.

son bakışlarınmıydı gözlerime

yada

bir veda buluşmasımıydı

gelişin.

bilseydim sonkez göreceğimi

ısıtmazmıydım yüreğimdeki ateşle

öpmezmiydim yakamoz gözlerini

al dudaklarına veda busesini

kondurmazmıydım gülüm.

ne haldeyim biliyormusun? 

al ateşler sardı yüreğimi

gözlerimde kızıl bakışlar türedi

ellerim cansız

damarlarımdan kanlar çekildi

apansız.

gitme desem neyi değiştirecek

bu gün olduğu gibi

sessizce,ait olduğun yere

geldiğin gibi gideceksin yine.

bir kez olsun benim olsaydın

kadınım diyebilseydim sana

yansaydık aşk ateşiyle

inan ki! 

bu kadar ağlamazdım

ardından.

oysa! 

şimdi gözlerim yaşlı 

yüreğim yaslı benim.

giderken

hoşçakal bile diyemediğim

yakamoz gözlüm

yağmurun kızı

şimdi ben

sensiz hayatı neyleyim.

bilki herzaman

her mevsim

yüreğimdesin.

***** Sevgimle Kal Bebeğim *****', 'Merhaba canım bu kadar seviyorken ayrılmak ta niye?  sormayacağım nasılsın,iyimisin diye. yüreğinin nasıl acıdığını kor içinde yandığını bil...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/sevgimle-kal-bebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylesene Kim Bunlar', 'soylesene-kim-bunlar-yusuf-onder-bahceci-g0l08', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalan haber yazarlar,

Satılmış bu yazarlar,

Mazlum görse kızarlar,

Söylesene kim bunlar.

Sanma Vatan sahipsiz,

Bu Vatanının sahibiyiz,

Milyon dolar bilmeyiz,

Söylesene kim bunlar.

Beyaza kara derler,

Mazlum görse bilirler,

Yalan, talan ederler,

Söylesene kim bunlar.

Gözüm yoktur Dünya''da,

Gözüm yoktur Ukba''da,

Sözüm çoktur onlara,

Söylesene kim bunlar....', 'Yalan haber yazarlar, Satılmış bu yazarlar, Mazlum görse kızarlar, Söylesene kim bunlar. Sanma Vatan sahipsiz, Bu Vatanının sahibiyiz, Milyo...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soylesene-kim-bunlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-erol-duran-1vgua', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çözüldü yüreğim bağı çözüldü

Benim yazım gurbet ele yazıldı

Şöyle gırtlağıma bir şey dizildi

Sıla mı, hasret mi bilemiyorum 

Dünya da özlenen sılaysa eğer

Gidip de şöyle bir gezmeye değer

İçimden geçene uymuşum meğer

Sıla mı, hasret mi bilemiyorum

Hiç kimse doğduğum yeri beğenmez

Üste para versem görmek istemez

Ne duysam bu kadar zoruma gitmez

Sıla mı, hasret mi bilemiyorum', 'Çözüldü yüreğim bağı çözüldü Benim yazım gurbet ele yazıldı Şöyle gırtlağıma bir şey dizildi Sıla mı, hasret mi bilemiyorum  Dünya da özlene...', ARRAY['Türk Edebiyatı','Şiir','Erol Duran']::text[], 8.5, '{"poet":"Erol Duran","poet_slug":"erol-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilmiyorum-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Sana Soruyorum', 'simdi-sana-soruyorum-yusuf-onder-bahceci-knriy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi sana soruyorum,

Mutlumusun söyle bana,

Senin için şiir yazan,

Yazan varmı söyle bana.

Her an şiir yazıyorum,

Sanma sana kızıyorum,

Yazıp yazıp ağlıyorum,

Yazan varmı söyle bana.

Şiirlerde sitemim var,

Burdan tâ kalbine uzar,

Bu sözlerim azar azar,

Yazan varmı söyle bana.

Gece, gündüz ağlıyorum,

Neden neden diyorum,

Hemen şiir yazıyorum,

Yazan varmı söyle bana....', 'Şimdi sana soruyorum, Mutlumusun söyle bana, Senin için şiir yazan, Yazan varmı söyle bana. Her an şiir yazıyorum, Sanma sana kızıyorum, Yaz...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/simdi-sana-soruyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denize-1', 'denize-1-hasan-huseyin-ozak-jutva', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızlık girdabından artık kurtuldum

Göz yaşımı kalbinin ateşinde kuruttum

Kurumuş yaprakları yollarına savurdum

Bir an önce gel diye, her gün dilekler tuttum

Bu rengin adı sensin sevdiğim

Kalbimin tek sahibi sensin sevdiğim

Bu mavi bizim mavimiz

Bu denizin rengi sensin sevdiğim

(Kalbi sevgiyle dolu Hilal arkadaşımın duygularına vesile oldum)', 'Yalnızlık girdabından artık kurtuldum Göz yaşımı kalbinin ateşinde kuruttum Kurumuş yaprakları yollarına savurdum Bir an önce gel diye, her ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/denize-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığın Ölümü', 'asigin-olumu-serdar-ahmet-guzel-5ks5b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşığın Ölümü

Bir gün âşık olursun

Zaman durur senin için

Midende kramplar,

Yüreğinde yangınlar vardır.

Uykusuz geçer gecelerin…

Bıraktığın sigaraya 

Yeniden başlamışsındır.

Ne varsa yaşam adına

Hepsi onun isminde gizlidir.

Gerçek manayı onda bulmuşsundur.

Bir sözü güldürmüş,

Bir bakışı ağlatmıştır,

Biçare gönlünü…

Umursamazsın dünyayı,

Ne anan vardır ne de baban…

Ne varsa odur,

Gözünde.

Karamıştır,

Ruh dünyan,

Onu görmediğin anda…

İçtiğin suda,

Yediğin yemekte,

Sigaranın dumanında,

Vardır,

Hayali…

Asla yetmez sana,

Birlikte olduğun zaman…

Her varışında güler,

Her gidişinde,

Ölürsün…

Acabalar kemirirken beynini,

Ben,

Evet, ben! 

Ama acaba,

Oda seviyor mu diye…

Her sözünü doğru kabul edersin,

Mantığın kabul etmese bile…

Gururun kırılsa da,

Her görüşünde,

Unutursun,

Beyninde çakan şimşekleri,

Ölüm senin için bir hiçtir,

Yoktur ondan ötesi…

Ve bir gün anlarsın,

Seni hiç sevmediğini…

Korumak istersin, 

İncinmesin diye.

Feda etmişsindir,

Onun uğruna,

Otuz üç seneni…

Anlatırsın onu çok sevdiğini,

Zarar göreceğini…

Ama

İşte bir,

Cevap uyandırır,

Seni,

O senin dünyan,

Ahretin olmuştur.

Sense onun boş vakti.

Değeri yoktur,

Yaşananların,

Değeri yoktur,

Duyguların, 

Ciğerin acır,

Sigara üstüne, 

Sigara, 

Sigara,

Üstüne sigara…

Demiştir ya,

Sana,

Özel hayatım var,

Israr edersen aramam diye,

İşte anlarsın,

Özel olmadığını…

Ciğerin dökülür,

Kalbin durur,

Beynin zaten yoktur,

Aşkın körlüğünde…

Sen bitmişsindir,

Artık arkadaş,

Ne hallere düştüm diye…

Ölmek bir an aklına gelir,

Manası yoktur,

Hiçbir şeyin,

Sen ölmüşsündür.

Yaşar diye bilirlerken seni…

20.01.2006 saat: 18.05', 'Aşığın Ölümü Bir gün âşık olursun Zaman durur senin için Midende kramplar, Yüreğinde yangınlar vardır. Uykusuz geçer gecelerin… Bıraktığın s...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ahmet Güzel']::text[], 8.5, '{"poet":"Serdar Ahmet Güzel","poet_slug":"serdar-ahmet-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/asigin-olumu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurur Murur Kalmadı', 'gurur-murur-kalmadi-yusuf-onder-bahceci-lwme6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O sevgili dönmeyecek,

Bu sevdamız bitmeyecek,

Gözyaşlarım dinmeyecek,

Gurur murur kalmadı.

Onu sevdim bilmeyecek,

Belki yüzüm gülmeyecek,

Bahar, yazı görmeyecek,

Gurur murur kalmadı.

Gözlerinle vurdun beni,

Sözlerinle kırdın beni,

Hiçbirşey anlamadım,

Gurur murur kalmadı.

Ayaklara düştüm ben,

Seni sevdim bilmeden,

Beni terkedip giden,

Gurur murur kalmadı....', 'O sevgili dönmeyecek, Bu sevdamız bitmeyecek, Gözyaşlarım dinmeyecek, Gurur murur kalmadı. Onu sevdim bilmeyecek, Belki yüzüm gülmeyecek, Ba...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gurur-murur-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol yorgunu', 'yol-yorgunu-zati-erbas-6lzrz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'avuçlarım

sen

kokuyor.

bir 

telin 

iki ucuna

mahkumuz

şimdi.

yol

yorgunu kuşlar

tünüyor

yüreğime,

gittiğin 

günden beri.

ben

her 

gece 

bin yürekle özlüyorum seni', 'avuçlarım sen kokuyor. bir  telin  iki ucuna mahkumuz şimdi. yol yorgunu kuşlar tünüyor yüreğime, gittiğin  günden beri. ben her  gece  bin ...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yol-yorgunu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendin', 'sendin-nehri-berdan-5nrkz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Önce mavisini sundun gözlerinin

uçsuz bucaksız...

bakınca anlardı fırtınayı

bakınca ağlardım...

Maviydin

geceydin

sendin

Ellerim avuçlarında uyudum

ilk annesiz gecemi

apak bir yağmur yağıyordu

ıslanıyordum

anneydin

sıcaktın

Sendin

Sesin, söylenmemiş ilk türküydü

sesin çok uzaklardaki ailem

sesin hüzün

sesin hasretti

türküydün

şiirdin

sendin

tan yeri kızıllığıydı dudakların

alt dudağın üstekini hapsetrtiği yerde

öldüm öldüm dirildim

Sabahtın

Güldün

SENDİN...', 'Önce mavisini sundun gözlerinin uçsuz bucaksız... bakınca anlardı fırtınayı bakınca ağlardım... Maviydin geceydin sendin Ellerim avuçlarında...', ARRAY['Türk Edebiyatı','Şiir','Nehri Berdan']::text[], 8.5, '{"poet":"Nehri Berdan","poet_slug":"nehri-berdan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sendin-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lastik Tekerlek', 'lastik-tekerlek-altay-taskin-mztdr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dünya döner ben dönerim

çamurların içinden

karların izinden

yine de başım dönmez

gevşerim sıcaktan

gerilirim soğuktan

acılara yetişmek

sevinçleri paylaşmak

kaderimdir benim

döner döner dönerim', 'dünya döner ben dönerim çamurların içinden karların izinden yine de başım dönmez gevşerim sıcaktan gerilirim soğuktan acılara yetişmek sevin...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/lastik-tekerlek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçlik', 'hiclik-orhan-mahir-kizilboga-ov58a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dolaştığım sokaklar artık yabancı bana

sararmış yapraklarını özledim geçmişin

yalnızlığında son bulsun istedim 

yalnızlığımda aşk olsun, sonbaharın.

ıslak sokaklarım savaş veriyor rüzgarlarda

yüzüme bakmaktan yoruldum

birikmiş sularımda...

güneş yavaş yavaş kayboluyor günlerimden 

güneş...

biliyorum düşlerimde artık.

yazmaya ihityacım var 

ama kelimeler inatla gelmiyorlar biraraya.

yorulmaktan yoruldum,

özlemekten....

susamamaktan....', 'dolaştığım sokaklar artık yabancı bana sararmış yapraklarını özledim geçmişin yalnızlığında son bulsun istedim  yalnızlığımda aşk olsun, son...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hiclik-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapma, Küsme', 'yapma-kusme-tunahan-ermihan-32n9j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dur yapma, küsüp dönme bana yüzünü

Kanarım açıkta kalmış yara misali sensiz

Işığım gözlerinden yansır karanlıkta korkarım

Gülüşün olmazsa solarım hazan vurmuş misali

Dur yapma bebeğim küsme bana

Mah cemalin olmadan atmaz yüreğim

Bir köprü altında korkularımla

Sessiz sedasız ölürüm', 'Dur yapma, küsüp dönme bana yüzünü Kanarım açıkta kalmış yara misali sensiz Işığım gözlerinden yansır karanlıkta korkarım Gülüşün olmazsa so...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yapma-kusme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnat', 'i-nat-yasar-pullu-dx27d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnadına seveceğim seni

ister kasırga çalsın şehri

ister çıyanlar yesin etimi

inadına

ellerim aydınlık sabahlar besleyecek

Sırf ınat olsun diye

ezeceğim geceyi

tenim ter yorgun tenim

zifiri karanlıklara ve sana inat

türküler söyleyeceğim

hiç eksik olmayacak adın sazımdan

asi şiirler yazacağım

evcil duygularıma inat

kıskanacak şiirlerimi uçurum çiçekleri

kan akacak gözlerimden

kime ne kan benim değilmi

mayıslar getireceğim ülkeme

mezarın tastamam şah damarımda

kaçman boşuna sevgili', 'İnadına seveceğim seni ister kasırga çalsın şehri ister çıyanlar yesin etimi inadına ellerim aydınlık sabahlar besleyecek Sırf ınat olsun di...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/inat-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterdim olmak', 'i-sterdim-olmak-altay-taskin-5zycq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bilginin kördüğümü

sevincin kaynayan kazanı

hüznün serabı

zamanın kara kaplumbağası

ölümün de şarabı

Karabük Ekspres 17-23 Ocak 1994', 'bilginin kördüğümü sevincin kaynayan kazanı hüznün serabı zamanın kara kaplumbağası ölümün de şarabı Karabük Ekspres 17-23 Ocak 1994...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/isterdim-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmazsan', 'sen-olmazsan-yasar-akbas-dgzox', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kim tanırdı aşk''ı meşk''i

Sen olmazsan,sen olmazsan

Kim  çeker ki o çileyi

Sen olmazsan, sen olmazsan

Sevinç, neşe dururmuy du

Gül bülbül''ü bulurmuy du

Vuslat hasıl olurmuy du

Sen olmazsan,sen olmazsan

Susardı tüm bahce, bağlar

Çorak olurdu topraklar

Hüzün dolardı sevdalar

Sen olmazsan,sen olmazsan

Aşklar sensiz leziz olmaz

Değer,kiymet,paha bulmaz

Masallara konu olmaz

Sen olmazsan, sen olmazsan

Akbaş sana aşık oldu

O gönlüne melhem buldu

Sensiz ömür boş olurdu

Sen olmazsan, sen olmazsan', 'Kim tanırdı aşk''ı meşk''i Sen olmazsan,sen olmazsan Kim  çeker ki o çileyi Sen olmazsan, sen olmazsan Sevinç, neşe dururmuy du Gül bülbül''ü b...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Akbaş']::text[], 8.5, '{"poet":"Yaşar Akbaş","poet_slug":"yasar-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-olmazsan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Gelince', 'bahar-gelince-altay-taskin-iugob', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tatlıdır bahar gelince

Menekşelerin selâmı

Fırıldak olur papatyalar

Döner döner sessizce

Çiğdemler borazan çalar

Uzaklara duyulsun diye

Yağmur duasında mantarlar

Hemen cümbüşe katılmak üzere

Kıpırdar toprak uykusunu almış

Gözler artık hep güneşte', 'Tatlıdır bahar gelince Menekşelerin selâmı Fırıldak olur papatyalar Döner döner sessizce Çiğdemler borazan çalar Uzaklara duyulsun diye Yağm...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bahar-gelince-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik Ve Sensizlik', 'sessizlik-ve-sensizlik-seda-baba-wmslg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sessizliğin içinde

bir yüreğimin haykırışlarını duyuyorum

bir de saatin tıklayışlarını

yüreğimin haykırışları sensizliğe 

saatin tıklayışları ise 

zamanın beklemeden geçişine

ben sensizliği adımlarken 

tüm mecburiyetimle

saat dakikaları adımlıyor

sensizliğim geçsin diye...', 'sessizliğin içinde bir yüreğimin haykırışlarını duyuyorum bir de saatin tıklayışlarını yüreğimin haykırışları sensizliğe  saatin tıklayışlar...', ARRAY['Türk Edebiyatı','Şiir','Seda Baba']::text[], 8.5, '{"poet":"Seda Baba","poet_slug":"seda-baba","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sessizlik-ve-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümde Açan Çiçek', 'gonlumde-acan-cicek-timur-i-likan-1hh6n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen ki gönlümde açan bir çiçeksin

Sen ki tuttuğum en güzel dileksin

Sen ki dağlarda yetişen çileksin

Sen ki aşk otağımdaki direksin

Haydi gel de ikimiz buluşalım

Senle hep sevdâmızı konuşalım

Haydi bir tek yüreğe doluşalım

Senle doyumsuz aşka kavuşalım

Hayat geçmiyor sen orda ben burda

Yoksun yanımda aklımda olsan da

Geleceğim yanına sen kovsan da

Seveceğim seni sararıp solsam da

(20 Ocak 2006/ İstanbul)', 'Sen ki gönlümde açan bir çiçeksin Sen ki tuttuğum en güzel dileksin Sen ki dağlarda yetişen çileksin Sen ki aşk otağımdaki direksin Haydi ge...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gonlumde-acan-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-054 Eğer! ..', 'ub-054-eger-mehmet-coban-q8x0a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşık olup 

Aşk şiiri yazsaydım eğer

Kendimden hiç söz etmezdim

Çünkü aşık olunca ben sana

Kendimden bir şey kalmaz sen olurdum

Tanrıya verdiğim sözü tutup

Aklımı, kalbimi özgür kılmak için

Sana aşık olmaktan vazgeçtim

Sadece Tanrı yoluna aşkı seçtim

Şimdi aklımla, kalbimle

Mantığımla, hayallerimle

Tanrı yolunu gözlüyor ve izliyorum

İnsanları ve doğayı seyrediyorum

Bir seni görmemi istersen eğer

Sen varlıklar içinde sadece bir varsın

Bir seni duymamı istersen eğer

Varlıkların sesinde kaybolmuşsun

Bir seni düşünmemi istersen eğer

Düşünecek senden daha önemli şeyler var

Bir seni sevmemi istersen eğer

Ben, her türlü bencillikten uzağım

O nedenle kızma bana

Sadece tanrı yolundan

Ve O''nun yarattıklarından 

Söz edişim ondandır

Çünkü ben tanrı yolunda kayboldum

Kendimden hiç bir şey kalmadı! ..

Bireysel duygularımdan söz edecek

Özür dilerim! ....

20.01.2006-İzmir', 'Aşık olup  Aşk şiiri yazsaydım eğer Kendimden hiç söz etmezdim Çünkü aşık olunca ben sana Kendimden bir şey kalmaz sen olurdum Tanrıya verdi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ub-054-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-fikret-dundar-ya8jk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözler var,

Efsunlu, puslu! 

Gözler var mahmur,

Uykulu! 

Sizi baktığınızda

Birlikte uykuya  davet eden

Gözler var! 

Baktığınızda size 

Ha yağdı  ha yağacak  dedirten

Yağmur bulutlu gözler var! 

Gözler var, 

Ümidini yitirmiş, üzgün.

Hayatta pek birşey görememiş,

Kaderine küskün,

Bakışları süzgün! 

Gözler var, 

Merhamet dileyen, aşk dileyen.

Yelken açmış bahtına enginliklerde.

Gönülden gönüle

Berrak su gibi akan.

İnsana huzur kaynağı olan gözler var.

Gözler var,

Neler görmüş neler geçirmiş.

Zamanın çarkında

Erimiş, büzülmüş,

Gördükleriyle 

Avunup giden gözler var! 

Bir bakıldığında,

İnsanı sarhoş eden,

Baktığına da 

Bin pişman eden gözler var! 

Bazılarının ,

Etrafa fel fecir okuyan 

Cin gibi gözleri var.

Her şeye hazırım 

Ne duruyorsun 

Gelsene dercesine.

Arayışlar içerisinde! 

Gözler var, davetkar.

Aşk arayan,

Meşk arayan 

Eş arayan! 

Gözler var yere bakan, 

Yürekleri alev alev yakan! 

Gözler var,

Deniz mavisi.

Enginliklerinde  yüzesin gelir! 

Gözler var, 

Sanki zeytin danesi.

Yanında yudumlayacağın 

Demli bir çayı aklına getirir! 

Gözler var,

Baharı müjdeler.

Yeşil, yeşil bakan,

İnsanları hülyalara salan gözler var! 

Kahverengi, ela gözler,

Söyleyin unutulur mu hiç 

Onların günahı ne? .

Gözler var  bakanları 

Alemden aleme gezdiren,

Etrafa tatlı tebessümler  eden,

İnsanı deli eden,

Gözler var! 

Alev alev bakar bazı gözler,

Sanki yangın yerinin 

Sıcaklığını hissedersiniz

Ta yüreğinizde! 

Gözler var, 

İnsafsız, merhametsiz,

Yerden yere çarpar sizi! 

Gözler var,

Üfül üfül eser, 

Bahar meltemi gibi  gönlünüze! 

Velhasıl dostlarım.

Nasıl söylesem size,

İnanın günahım yok amma,

Bu yorgun kalbimi 

Durduracak gözler var! 

Fikret Dündar

Erenköy-İstanbul

20.1.2006', 'Gözler var, Efsunlu, puslu!  Gözler var mahmur, Uykulu!  Sizi baktığınızda Birlikte uykuya  davet eden Gözler var!  Baktığınızda size  Ha ya...', ARRAY['Türk Edebiyatı','Şiir','Fikret Dündar']::text[], 8.5, '{"poet":"Fikret Dündar","poet_slug":"fikret-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/gozler-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi-Güzel', 'sevgi-guzel-altay-taskin-psobv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgi güzeli düşünde görmüş

Kaçarken pembe örtülü ormanda

Sevgi güzelin peşine düşmüş

Arı çiçek ararken ilkbaharda

Sevgi güzelin yanına ermiş

Soluk soluğa ve gerçek anlamda

Sevgi güzelin elini öpmüş

Şaşırmış dağlar taşlar uzaklarda

Sevgi güzelin yanında ölmüş

Çatlamış hırsından yüz aynalarda', 'Sevgi güzeli düşünde görmüş Kaçarken pembe örtülü ormanda Sevgi güzelin peşine düşmüş Arı çiçek ararken ilkbaharda Sevgi güzelin yanına ermi...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevgi-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karınca', 'karinca-altay-taskin-w34wf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karınca

Kararınca

Çalışır

Toprakta

Taşır

Yiyeceğini

Saz

Çalmaz

Boşuna

Yeter

Kendi

Kendine

Asalak

Değildir

Tabiatta

Zarar

Vermez

Hiçbir

Canlıya

Örnek

Alınacak

Çalışkanlıkta

Küçük 

Üretici

Küçük

Ziraatçidir

Büyük

Toprakta', 'Karınca Kararınca Çalışır Toprakta Taşır Yiyeceğini Saz Çalmaz Boşuna Yeter Kendi Kendine Asalak Değildir Tabiatta Zarar Vermez Hiçbir Canlı...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/karinca-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufukta', 'ufukta-altay-taskin-wp189', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Açık denizlerin derin dostluğu

Ufuktan görünür uzar ışığı

O uzaklardan ısıtır soluğu

İnsan hep güzelliklerin aşığı', 'Açık denizlerin derin dostluğu Ufuktan görünür uzar ışığı O uzaklardan ısıtır soluğu İnsan hep güzelliklerin aşığı...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ufukta-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığın İçimdeki Son Sızım', 'ayriligin-i-cimdeki-son-sizim-elif-sevim-57cqw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlemimdin sen benim içimde büyüttüğün sevdamdın benim seninleyken özlüyorum seni.

      Seninle buluşacağımız saati beklemek ölüm gibi gelirdi bana.Sensiz saatler bir türlü geçmek bilmezdi seninleyken zaman çabuk geçecek diye korkardım.Seninle geçirdiğim saatleri sanki bir günmüş gibi yaşardım.

      Anlatamazdım kimselere seni nasıl sevdiğimi.Kelimeler boğazımda düğümlenip kalırdı.Harketmezdim gözlerimin dolduğunu.Yanaklarımdan süzülen yaşlar senin yokluğunun acısıyla yakardı tenimi.

      Her gece hayalin rüyalarımı süslerdi.Her yeni güne yeni bir hüzün katarak başlardı. Yokluğunun verdiği dayanılmaz acı günlerimi zehir ederdi.

      Yokluğun bir bıçak gibi saplandı yüreğime.Artık yüreğim durdu zamanın durduğundan beri.

       Ama sen anlayamadın yaralı bir kuşun avuçlarında can verdiğini.Acıyan yüreğimin senin avuçlarında durduğunu ve bir daha asla geri dönmeyeceğini.', 'Özlemimdin sen benim içimde büyüttüğün sevdamdın benim seninleyken özlüyorum seni.       Seninle buluşacağımız saati beklemek ölüm gibi geli...', ARRAY['Türk Edebiyatı','Şiir','Elif Sevim']::text[], 8.5, '{"poet":"Elif Sevim","poet_slug":"elif-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ayriligin-icimdeki-son-sizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-altay-taskin-5bhzi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tohumdun,

Sevgiyle sulandın,

Yemyeşil fidan oldun.

Fidandın,

Güneşle oynadın,

Ağaç oldun, dallandın,

Çiçek açtın, koktun.

Ağaçtın,

Usunla uzadın,

Gün oldun, parladın.

_Tohumdum, ''hamdım'',

''Piştim'' fidanken,

 Ağaçken ''yandım''.', 'Tohumdun, Sevgiyle sulandın, Yemyeşil fidan oldun. Fidandın, Güneşle oynadın, Ağaç oldun, dallandın, Çiçek açtın, koktun. Ağaçtın, Usunla uz...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bebegim-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmiş Ola', 'gecmis-ola-munevver-senol-44zd7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Doksan derece sarsılan yıkılmamak için direnen.

Bu bedenin mimarı sensin, övün övünebildiğince.

Şimdi üzülmen pişmanlık duyman boşuna, nafile artık.

O yarayı derinden aldı artık onaramazsın.

Sen onu hiç anlayamadınki zaten.

Boşver bu saatten sonra hiç anlayamassın

Bırak onu yıkıldığı yere kadar gitsin elleme.

Sonra kırılırda tuttuğun her dalı elinde kalır.

Dedim ya o yarayı derinden aldı onaramazsın.

Boşver gitsin bu saatten sonra sen onu anlayamazsın.

Bu bedenin mimarı sensin, övün övünebildiğince.

Ama şunu unutmaki bende yaşamayı öğrendim sayende.

Sağ elim ihanet etti senin gibi,sol elimi kullanmayı öğrendim

Yataktan kalkamadığım için.

Yattığım yerden, yemeyi içmeyi öğrendim sayende.

Ayağa kalkmayı yürümeyi özledim, inatla kalktı

AMAA yere çakılınca ağlamadım gülmeyi öğrendim sayende

Şimdi koşmasamda yürüyorum, 

Oturarak yemeğimi yiyiyorum.

Ben güçlü bir kadınım bak neleri başardım kendi sayemde.

           

 25.10.2002', 'Doksan derece sarsılan yıkılmamak için direnen. Bu bedenin mimarı sensin, övün övünebildiğince. Şimdi üzülmen pişmanlık duyman boşuna, nafil...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gecmis-ola-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim neyana koyayım seni', 'yuregim-neyana-koyayim-seni-abdullah-oral-r7o80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YÜREĞİM NE YANA  KOYAYIM SENİ 

Sığmadın içime depreşip durdun 

Ne yana çevirsem eğemem seni 

Bazen süt limansın bazen çıldırdın 

Yüreğim ne yana koyayım seni 

 Irak’ta oturmuş Kapitalist paya 

Kan ile örüldü zulüm Dünya’ya 

 Koskoca bir tarih düşmüş yağmaya

 Yüreğim ne yana koyayım seni 

 Kötü bir it ulur ta uzaklardan 

Katlime çalmakta kiliseler çan 

Geriye ne kaldı koca bir halktan 

Yüreğim ne yana koyayım seni 

 İki bin üç yılı kuşattı zulüm 

Körpe bebelere düşüyor ölüm 

Çiçeğe durmadan kırılır dalım 

Yüreğim ne yana koyayım seni 

 Doymaz kan içmeye Emperyalistler 

İşbirlikçi müslüm, sofu, faşistler 

Ne kadar dirense azdır milisler 

Yüreğim ne yana koyayım seni 

 Gördükçe biçare aç çocukları 

Göğüs kafesimde yırtmışsın zarı 

Vurguni çözüldü dağların karı 

Yüreğim ne yana koyayım seni.', 'YÜREĞİM NE YANA  KOYAYIM SENİ  Sığmadın içime depreşip durdun  Ne yana çevirsem eğemem seni  Bazen süt limansın bazen çıldırdın  Yüreğim ne ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yuregim-neyana-koyayim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben-Sizlik', 'ben-sizlik-alper-yildiz-wdna3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ruhun ruhuma okunu atmış,

Görünmez zincirlerle bağlanmışım.

Ölüm,hüznüme huzuru katmış,

Sensiz aynada boşa ağlanmışım.

Su gördüm seni belirgince rüyaymış,

Uyandım bir damla sende saklanmışım.

Yıldız gibi uykuma düşlerin kaymış,

Uyanık gördüm,karanlıktan aklanmışım.

Gün geçmez ki göremezsem seni,

Zaman ters akar ben katlanmışım.

Görsem bir an anlarım görünmeyeni,

Senin yokluğuna bile katlanmışım.

Sükut eder gece,gündüzler arsız,

Sessizce kalabalıktan arlanmışım.

Her renk tutar elimden umarsız,

Bende bensizlikten toparlanmışım.', 'Ruhun ruhuma okunu atmış, Görünmez zincirlerle bağlanmışım. Ölüm,hüznüme huzuru katmış, Sensiz aynada boşa ağlanmışım. Su gördüm seni belirg...', ARRAY['Türk Edebiyatı','Şiir','Alper Yıldız']::text[], 8.5, '{"poet":"Alper Yıldız","poet_slug":"alper-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-sizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüşü yoktur dağların', 'donusu-yoktur-daglarin-abdullah-oral-vanv9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'DÖNÜŞÜ YOKTUR DAĞLARIN

Bu coşkuyla sanma bu hasret biter 

Sularda özlemi çoktur dağların

 Toprağın üstünden yollanır gider

 Bir daha dönüşü yoktur dağların 

 Düşe kalka gider dağları aşar 

Bazen öfkelenir bendinden taşar 

Deryaya varınca durgunluk başlar

 Bir daha dönüşü yoktur dağların

Bulut olamazsa yoktur çaresi 

Dalga olur düşer kanar yarası 

Yanar durur iç de çoban çırası

 Bir daha dönüşü yoktur dağların 

 Vurguni hasretim yürek çalkalar

 Kıyıları yıkıp durur dalgalar

 Boş yere dövünüp durmasın sular

 Bir daha dönüşü yoktur dağların', 'DÖNÜŞÜ YOKTUR DAĞLARIN Bu coşkuyla sanma bu hasret biter  Sularda özlemi çoktur dağların  Toprağın üstünden yollanır gider  Bir daha dönüşü ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/donusu-yoktur-daglarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapalı Çıplak', 'kapali-ciplak-sadettin-deren-i5rir', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Daha bir yaklaşmak her gün

Daha bir duyar gibi olmak seni

Ve yücelerden bir kara bulut

Toprağa inerken,

Sana gelmek Tanrı’ca bir güçle,

Senden gitmek gibi.', 'Daha bir yaklaşmak her gün Daha bir duyar gibi olmak seni Ve yücelerden bir kara bulut Toprağa inerken, Sana gelmek Tanrı’ca bir güçle, Send...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kapali-ciplak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ücretli köle', 'ucretli-kole-abdullah-oral-ar63c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÜCRETLİ KÖLE 

 Ayın kaçı diye sormayın bana

 Yetmiş ikinci gün yine maaş yok

 Geceler uyutmaz dön yana yana 

Sabaha tadımlık bir tas aşım yok 

Yoksulu görür mü patronun gözü 

Tükürsen kızarmaz keçedir yüzü

 Yıllardır suskunluk kul etti bizi 

Şimdi ağarmadık tek bir dişim yok 

İşçiyim pul dahi etmiyor sözüm 

Bilirim yakarmak değildir çözüm 

Kanaya kanaya kurudu gözüm

 Vursalar boynumu damla yaşım yok 

Ne yapayım ki ben bana edenim 

 Olmadı dünyada nasıl nedenim 

Toprağa düşecek çıplak bedenim 

Bir kefen biçimlik kirli bezim yok 

Hani özgürlüğüm, umudum hani 

Yüreğim ne yana koyayım seni 

 Gün yorar da gece uyutmaz beni 

Hayıra yoracak bir tek düşüm yok

 Vurma dedim soysuz ağrıma vurma

 Henüz tomurcukta dalımı kırma

 Vurguni boş yere dövünüp durma 

Sınıf savaşından başka çözüm yok…', 'ÜCRETLİ KÖLE   Ayın kaçı diye sormayın bana  Yetmiş ikinci gün yine maaş yok  Geceler uyutmaz dön yana yana  Sabaha tadımlık bir tas aşım yo...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ucretli-kole-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Divane', 'divane-abdullah-oral-ujgiq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zaman özgürlüğü düşünsem

    Kocaman bir yalnızlık çiziyorum 

                    Mazgalların ardında 

                      kızıl bir yağmur yağar 

                             Türkü yangını dudaklarımdan...       

                    DİVANE

Haklılıktan yana coşunca seller

 Virane eyledi bu şehir beni 

Vakitli vakitsiz solunca güller                                             Divane eyledi bu şehir beni

Temmuz sarı sıcak güneş yakıcı

 Öfkeyle indirdik örse çekici 

Emek katlolmakta zulüm yakıcı 

Divane eyledi bu şehir beni

Sevda güllerini ektik bağlara

 Umudun adını yazdık dağlara 

Kırdılar kanadım düştüm ağlara

 Divane eyledi bu şehir beni

 Neden kaçar durur yobaz fikirden

 Eline ne geçti sofu, zikirden 

Ne ister tanrılar yoksul fakirden

 Divane eyledi bu şehir beni 

 Düşmez iken tanrı ismin dilimden

 Çiçekteyken soldum düştüm dalımdan

 Medet umulur mu hain zalimden

  Divane eyledi bu şehir beni 

 Kaldırımlar sessiz sokaklar yaslı 

Dostluk kapıları açılmaz paslı 

Her şey fotokopi bulunmaz aslı 

Divane eyledi bu şehir beni 

 Kula kul olmadık kimse kalmamış 

Solgun yanaklar var henüz gülmemiş

 Vurguni’yim dağlar düze inmemiş

 Divane eyledi bu şehir beni', 'Ne zaman özgürlüğü düşünsem     Kocaman bir yalnızlık çiziyorum                      Mazgalların ardında                        kızıl bir ya...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/divane-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alacaklıyım Hayattan', 'alacakliyim-hayattan-muzaffer-cura-ibbu6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yarım kalmışlıklarım

yaşanmamışlıklarım var benim.

alacaklı hissediyorum

kendimi hayattan.

tamamlayamadığım düşlerim

çıkmak isteyip çıkamadığım

yolculuklarım var benim.

suyunu

çam kokularını

dokunulmamış, uçurum çiçeklerini 

merak ettiğim,

beni çağıran dağlarım var.

daha kardelenleri

kendi topraklarında göremedim.

''gül, niye kıskanır mor menekşeyi''

diye soramadım.

utangaç bir çoban kızına..

balıklarını tutmadığım,

göller, denizler

olta atacağım akarsular var.

güzel sulara, susuzluklarım var.

dahalarım var benim.

sususuzluktan kuru dudaklarım.

ulaşmak istediğim, vahalarım var benim.

taşçıyım ama

taş evleriyle ünlü Mardin''i görmedim.

güneşin doğuşunu

seyretmedim Nemrut''ta.

Karadeniz

kafamda bir güzellik hala.

mavi suları, azgın dalgaları

dere ve yaylalarıyla..

toroslardan kalkan

yörük aşiretinin kervanı.

süslü develeri,

çan-çun öten çanları

binlerce

ak-kara kıl keçisiyle

gençliğimin anılarında hala.

o güzelim

o rengarenk

telaşlı masum yol kesmelerini

bir daha yaşamak istiyorum

bir daha..

ve hatta onlarla yaylalara çıkmak.

bu yaşta,

yeşil gözlü bir yörük kızına sevdalanmak

bile geçiyor içimden.

usumdan utanarak.

canına can katmak istediğim

bir sevda özlemim.

sıcacık kavramak istediğim

bir el hala düşüm.

Hayat ne kadar karşılık verecek buna? 

bir cana

ihtiyacım var.

alacaklıyım hayattan.

yarım kalmışlıklarım,

yaşanmamışlıklarım var..

object width=''576'' height=''432'' param name=''allowfullscreen'' value=''true'' /param name=''allowscriptaccess'' value=''always'' /param name=''movie'' value=''http://www.facebook.com/v/47928069394'' /embed src=''http://www.facebook.com/v/47928069394'' type=''application/x-shockwave-flash'' allowscriptaccess=''always'' allowfullscreen=''true'' width=''576'' height=''432''/embed/object', 'yarım kalmışlıklarım yaşanmamışlıklarım var benim. alacaklı hissediyorum kendimi hayattan. tamamlayamadığım düşlerim çıkmak isteyip çıkamadı...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Cura']::text[], 8.5, '{"poet":"Muzaffer Cura","poet_slug":"muzaffer-cura","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/alacakliyim-hayattan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba 15', 'merhaba-15-tulay-i-cen-zuvin', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Merhaba.....

Can merhaba  tarihi attığımda Nisanın 25 idi ama defterin yapraklarını karıştırırken  zaman öyle aktı ki 26 Nisana girmiştik bile saat  yeni günün  ilk saatlerini gösteriyor.Yeni  bir gün,acımasız  bir gün daha aslında  günün suçu yok suçlu olan  bizleriz günü yaşamayı bilmiyoruz, içimde kopan fırtına dinmiyor sanki yüreğim parça parça oluyor.

Ben hep karanlığa mahkum mu kalacağmı hiç hayatımda  aydınlık olmayacakmı, benimde hayellerim ve isteklerim var  ama ne yazık ki hepsi hayal ve istek olarak kalıyor kalacak hiç bir zaman gülmeyeceğim.Hep dertli ve  hayata küskün olarak.... Sana kavuşana kadar yaşayacağım buna yaşamak denirse..

Benimde  hayellerim  var dedim, şuan senin kollarında olmayı  başımı omzuna koyup  teninin kokusunu koklayarak senin varlığını  hissetmeyi  okadar  cok isterdimki...

Sen benim hayellerimin gercekleşmeyen gerceğisin.Hayelde olsa güzel ama ne yazıkki  hayellerimde  ve kalbimdesin, seni kalbimden  atamam  sen onun sahibisin...

SENİ COK ÖZLEDİM CAN.

Ellerimde bir kardelen gibiydin.

Göğsüme sokmak istedim 

Seni,,,

Üşümüsün diye.

Ey hak.,, ne yazık.

Varmıydın  yoksa,

benmi öyle  hissetim.

Bileklerimde  kelepçeydin,

Anahtarı olamayan.

Karanlığın  benim mahpusluğum.

Aydınlığında benim  özgürlüğüm.

Kardelen gibiydin  yüzüme  gülen.

Ne yazık....

Varmıydın yoksa, benim hayalim mi.

Kalbin matemi  hayat boyu sürer,

ama hayat  yinede devam eder...

25/04/2004', 'Merhaba..... Can merhaba  tarihi attığımda Nisanın 25 idi ama defterin yapraklarını karıştırırken  zaman öyle aktı ki 26 Nisana girmiştik bi...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/merhaba-15-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Cellat Tutsağı Bir Geceydi...', 'cellat-tutsagi-bir-geceydi-i-mdat-ozcan-b770s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'adımladığın sokakların kanamasıydı 

ellerimde depreşen 

ayağının dokunuşu sızlatıyordu 

oysa sen bilmiyordun 

ne çok merakına düşer yüreğim 

ne çok adın takılır 

ayazına gençliğimin 

cellat tutsağı bir geceydi 

o sessiz sedasız konuşmanın artığı 

bir yanda yanık bir yüz suretinde istanbul 

bir yanda gidişinin buz kesmişliği 

yorgun bir haykırış ağzımı dolduran 

yenilgi kisvesinde kahır 

bir uzak diyardı 

yıllar geçirdiğim tenha 

hep yabancı yüzler 

ardımda yabancı izler 

kuytularda susuşum 

aynalarda küsüşüm 

yokluğundan... 

talan olan her şehir benim 

şehir şehir talan olan benim 

savaş mağlubu 

düşlerde can çekişir gece 

gecenin kuytusunda can verir düşler 

boğulmuş bir şafak uzaktan el eder 

gün doğumu sancısında uykusuzluğum... 

zemheride yanışım 

ağulardan kanışım 

yokluğundan... 

25/11/2005 - Merter', 'adımladığın sokakların kanamasıydı  ellerimde depreşen  ayağının dokunuşu sızlatıyordu  oysa sen bilmiyordun  ne çok merakına düşer yüreğim ...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/cellat-tutsagi-bir-geceydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günün 25. Saatinde (136)', 'gunun-25-saatinde-136-i-brahim-arslan-d83tq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kafam ellerimin içinde 

Günün 25. saatinde,

Bütün insanlardan uzak ve çok çok uzaklarda...

Ben değilim kendimde

Neyi düşünüyorum...

Yalanlardan uzak,yılanlardan uzak,güneşten uzak

Yaşam eriyor nefesimde

Ben niye yürüyorum,

Uykumda,geceleyin,gündüzün,durmadan...

Neden titriyor sesim,

Neden kendimden ürküyorum...

Kendimden mi? yoksa birgün ansızın ölmekten mi? 

Olmasın kimse izimde

Ben kendime örnek olamıyorum

Karınca kadar bile,örümcek kadar bile...

Hatta en acizi kadar bile

Doğruyu göremiyorum...

Ne doğru,ne yalan,ben kimim.ben neyim? 

Cahillerin cahiliyim

Bilgililerin bilgesi...

Düşünüyorum varım,ya düşünemiyorsam? 

Her kapı kilitliyse

Ve her insan deliyse...

iİaçlar çeşit çeşit,hekim bir

Beni yaratan bilir

Beni yaşatan bilir

Öyleyse neden değilim O''nun izinde

Ve neden yapma dediğini yapıp

Yap dediğini yapmıyorum...

Ölümsüzmüyüm? değilim.katiyyen

Hiçbir insan yaşlı değil

Bende her zaman için gençmiyim? 

Müslümanım gururla söylüyorum,

Öyleyse

Neden müslüman gibi yaşamıyorum...

Neden,neden,neden ve neden,neden

Kafam ellerimin içinde

Günün 25. saatinde

24.7.1999', 'Kafam ellerimin içinde  Günün 25. saatinde, Bütün insanlardan uzak ve çok çok uzaklarda... Ben değilim kendimde Neyi düşünüyorum... Yalanlar...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gunun-25-saatinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader anlıma gurbet yazalı', 'kader-anlima-gurbet-yazali-halil-colak-7k9pm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaç mevsim  kaç yıl geçti

Ben sıladan hasret kalalı

Özledim bile sert olan ayazı

Kader anlımada gurbet yazalı

Yollar uzak her zaman gidilmiyor

Dağlar yüksek kar tipiden geçilmiyor

Buranın adı  anam gurbet çekilmiyor 

Kader anlımada dostum gurbet yazalı

Kader yazmışta bacım ayrılık yazısını

Gurbet bu verir yavrum hasretlik sızısını

Kimseler bilmez  gurbettekinin çilesini

Kader anlımada  kardaş gurbet yazalı

Halil Çolak 20.1.2006 Ankara', 'Kaç mevsim  kaç yıl geçti Ben sıladan hasret kalalı Özledim bile sert olan ayazı Kader anlımada gurbet yazalı Yollar uzak her zaman gidilmiy...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kader-anlima-gurbet-yazali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğul', 'ogul-orhan-kutlu-gp00i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boşver oğul üzülme her şey gelir geçer,

Gönül kuşu konar bir gün seni de seçer,

Eğer ihanetten yana kalırsan naçar,

Başını dik tut sakın eğilme ha oğul.

Değer verdiklerin değer bilmez olur da,

El verdiğin düşersen el vermez olur da,

Dostlar, arkadaşlar hatır sormaz olur da,

Başını dik tut sakın eğilme ha oğul.

Sen hep sev sevilmesende mecnun desinler,

Doğruyu söyle Hak''kı bil bırak gülsünler,

Sen sen ol, seni hep  böyle adam bilsinler

Başını dik tut sakın eğilme ha oğul.

İnsan, aile, bayrak vatan ve de millet,

Şehitliğe uzan tehdit ederse zulmet,

Ölmek yeğdir inan yaşamaktansa namert,

Başını dik tut sakın eğilme ha oğul', 'Boşver oğul üzülme her şey gelir geçer, Gönül kuşu konar bir gün seni de seçer, Eğer ihanetten yana kalırsan naçar, Başını dik tut sakın eği...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ogul-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Akşamları', 'gurbet-aksamlari-muzaffer-cura-ca2xt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'nedense hep sevdim ben

gurbet akşamlarını

ulaşılmayanı özlemek mi ne? 

yoksa hüzün mü benim güzel çocuğum..

yine gece,

yine otel odası

yine gurbet burası..

yine hüzün buldum ayrılıklarda

yine gurbette

bir akşam molası.', 'nedense hep sevdim ben gurbet akşamlarını ulaşılmayanı özlemek mi ne?  yoksa hüzün mü benim güzel çocuğum.. yine gece, yine otel odası yine ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Cura']::text[], 8.5, '{"poet":"Muzaffer Cura","poet_slug":"muzaffer-cura","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gurbet-aksamlari-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Arta Kalan Şehirde', 'senden-arta-kalan-sehirde-tunahan-ermihan-fnjr0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensiz kalınca akşam çöküyor kentime

Sokak lambaları yanıyor

Puslu bir düşünce çöküyor beynime 

Çöpçüler ortaya düşüyor

Hasretin kalıyor bir fikrimde

Yayalar evlerinde trafik azalıyor

Bir ben yabancı bu şehirde

Ay inadına bulutların ardına saklanıyor

Gelirmisin diye baktığım sokak çamur içinde

Yağmur niyetine gözlerimden bir damla yaş iniyor

Sokaktaki çamur ayaklarının derdinde

Sensiz kalınca akşam çöküyor kentime

Evlerde sobalar yanıyor, çocuk sesleri ayyukta

Bir ben üşüyorum bir ben bekliyorum

Ve ben seni çok özlüyorum', 'Sensiz kalınca akşam çöküyor kentime Sokak lambaları yanıyor Puslu bir düşünce çöküyor beynime  Çöpçüler ortaya düşüyor Hasretin kalıyor bir...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/senden-arta-kalan-sehirde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatya', 'papatya-nurten-koroglu-u7gwy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uçurum kenarlarında kök salan

Bir papatya''yım  ben boynu bükük

Bitek topraklar uzaktır bana

Yanıyor sandığım ışıklar ufkumda sönük

Ümidim,ümitsizliğin pençesinde tutsak

Bir yudum suya hasretim,tutunduğum topraklar kıraç

Nereye dayansam,sanki alnıma dayanmış gibi namlular

İçimdeki öksüz çocuk sevgiye muhtaç

Bir karayel savurur durur yapraklarımı

Baharları beklerim,yine de ümidim hiç bitmez

Sevdalanırım yanı başımdaki dağ göllerine

Hasretin yarası bende,günbegün kanar dinmez

Artık yağmur duaları da çare değildir bana

Yaralarımı saramaz bahar meltemleri

İçimde çok şeyler varken çoğalıp büyüyen

Sayamıyorum artık,benden kopup gidenleri', 'Uçurum kenarlarında kök salan Bir papatya''yım  ben boynu bükük Bitek topraklar uzaktır bana Yanıyor sandığım ışıklar ufkumda sönük Ümidim,üm...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/papatya-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-seyfet-bozcali-qx2lb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geceler karanlık,uykular ölüm,

Gündüz kuzu olan,geceler zalim,

Kötülükler saklı,sonumuz vahim,

Çok yuvalar yıktın zalim geceler...

Hainler,soysuzlar karanlığında,

Hırsızlar,zalimler yaşar bağrında,

Sonun olur tanlar ağardığında,

Foyan anlaşılır hain geceler...

Tüm mahlukar yere iner seninle,

Korkular saçarsın,siyah teninle,

Çok oyun oynarsın pis emelinle,

Sonun sabah olur garip geceler...

Seyfet der çocukken korkuttun bizi,

Zifri karanlıkta hep yuttun bizi,

Köşe bucak süründürdün öksüzü,

Sonun hep karanlık olur geceler....

19.01.2006', 'Geceler karanlık,uykular ölüm, Gündüz kuzu olan,geceler zalim, Kötülükler saklı,sonumuz vahim, Çok yuvalar yıktın zalim geceler... Hainler,s...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/geceler-132-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-nurten-koroglu-58ovh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çekince sevdanı göğsümden

Yaralı bir kuş  olurum

Gitme! 

Ne acılara dayandı bu yürek

Nice yandı,nice kavruldu

Eğer; bu da bir vurgunsa,olsun yinede

Geçme! 

Kalsın geride ne kalacaksa

Sinemi dağlayacak

Bir avuç kor olsa da  aşk dedikleri

Yansın yangınlar yanacaksa

Sönme! 

Çekince sevdanı göğsümden

Yaralı bir kuş  olurum

Gitme!', 'Çekince sevdanı göğsümden Yaralı bir kuş  olurum Gitme!  Ne acılara dayandı bu yürek Nice yandı,nice kavruldu Eğer; bu da bir vurgunsa,olsun...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gitme-148-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-muzaffer-cura-chgwc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dünya bir tane değil! 

herkesin bir dünyası var.

kimi küsmüş dünyaya

kiminin dünyası dört duvar.

kiminin dünyası mavi

kiminin dünyası toz pembedir.

benim dünyam

kafam ile yüreğimin birleştiği yerdedir!', 'dünya bir tane değil!  herkesin bir dünyası var. kimi küsmüş dünyaya kiminin dünyası dört duvar. kiminin dünyası mavi kiminin dünyası toz pe...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Cura']::text[], 8.5, '{"poet":"Muzaffer Cura","poet_slug":"muzaffer-cura","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dunya-106-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmıştım ilkbahar geldi benim ömrüme', 'sanmistim-ilkbahar-geldi-benim-omrume-ramazan-kayak-aivxo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zamanı geldi öte zamanlardan 

Karlar yağmurlarla dost oldu 

Gönlümün çorak toprakları

Sanmıştım ilkbahar geldi benim ömrüme 

Beni yeni ateşlere itmişlerdi oysa 

Kervanlara katılmışım asırları ötesinde gelen 

Malabadi den dert yüklemiş yemenden geçen

Tenha yollarda solgun yapraklar arasında 

Sonbahardan arta kalan

Yalnızlığa giden kervanlara katılmışım 

Kaderimi arıyorum kendimi soruyorum 

Gecelerin ötesinde öte mevsimlerden 

Kendi gecemden kendi ömrümden 

Geçmişimden kaçarcasına 

Kaçarcasına kendi ömrümden', 'Zamanı geldi öte zamanlardan  Karlar yağmurlarla dost oldu  Gönlümün çorak toprakları Sanmıştım ilkbahar geldi benim ömrüme  Beni yeni ateşl...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sanmistim-ilkbahar-geldi-benim-omrume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-beytullah-tanhan-ih77f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bir insan

dört duvar arasında 

hapis....

ben bir insan

ellerimde kelepçe

ayaklarım da zincir

boynumda yafta ile

dört duvar arasında

hapis...

ben birinsan

ama kalbim kanat çırpar

özgürce burada

ben bir insan 

korkularını 

gün be gün yaşayan

tepemde parlayan güneş

masmavi gök kubbe ile

ayaklarım seyyah

dolaşır durur dünyayı

ben bir insan

sanki her yer 

kafes bana

sanki her yer 

zından....

ben bir insan 

dört duvar arasında 

hür.........', 'Ben bir insan dört duvar arasında  hapis.... ben bir insan ellerimde kelepçe ayaklarım da zincir boynumda yafta ile dört duvar arasında hapi...', ARRAY['Türk Edebiyatı','Şiir','Beytullah Tanhan']::text[], 8.5, '{"poet":"Beytullah Tanhan","poet_slug":"beytullah-tanhan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/insan-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahitleşmiştik', 'ahitlesmistik-beytullah-tanhan-07zb1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ahitleşmiştik,sözvermiştik

bir bedenin azaları gibi

bütünleşmiştik...

nikah kıymıştık toprağa

yeis tohumlarını

işte O zaman,söküp atmıştık

önce kendimizi,sonra düşmanı

tanımaya başladık

biz kimdik

niçin vardık,

ve neden savaşıyorduk

tanıdık ta....

bu yolda ilerlerken

dokülen yapraklar gibi savrulduk

kimimiz sendeledik

kimimiz ise malum

ve düşmanı tüm vahşetiyle

bir meydan muharebesinde tanıdık

işte ozaman 

ilk defa 

coşkulu bir düğün de

bir şehidin mürvetinde ağladık

sıra bende demek istiyorduk hepimiz

ama diyemedik diyemedik...', 'ahitleşmiştik,sözvermiştik bir bedenin azaları gibi bütünleşmiştik... nikah kıymıştık toprağa yeis tohumlarını işte O zaman,söküp atmıştık ö...', ARRAY['Türk Edebiyatı','Şiir','Beytullah Tanhan']::text[], 8.5, '{"poet":"Beytullah Tanhan","poet_slug":"beytullah-tanhan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ahitlesmistik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Bir İstasyon Mahkumu', 'guzel-bir-i-stasyon-mahkumu-muzaffer-cura-khrxf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yanaklarımda iki damla göz yaşı.

yitik bir sevda adına

yıkamaya kıyamadığım.

ve yüreğimde bayramlıkları,

alınmamış bir yoksul çocuğun hüznü..

kafam bir tren.

yükünü boşaltamamış,

uzun yollar yorgunu

güzel bir istasyon mahkumu! 

gözlerim çakılı felaket haberlerine Tsunaminin.

dul kadınları,

yetim çocukları dünyamın.

ve onların acıları,

benim gözyaşım.

sulu mektubu yüreğimin

insan yanım, güzel sırdaşım!', 'yanaklarımda iki damla göz yaşı. yitik bir sevda adına yıkamaya kıyamadığım. ve yüreğimde bayramlıkları, alınmamış bir yoksul çocuğun hüznü....', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Cura']::text[], 8.5, '{"poet":"Muzaffer Cura","poet_slug":"muzaffer-cura","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guzel-bir-istasyon-mahkumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türban…', 'turban-esat-korkmaz-njbzm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne mübarek şeysin öyle

orta çağın karasından kara

bir tabudan gelir neslin

tesettür yada Burkadır soy adın

kuşandın mı  bedene 

an geçmez yaşatırsın dişiliği

sardın mı Kadını

gün boyu arzulara köle

şehvet yangını alev edersin

bedeni

şeytan aklına gelmez arzulara

fitil olursun bende

mülk olur taşınır haremime

benim olur sayende özgür beden

güç katar gücüme

baş''ından başlayan 

haneme kapatmanın adısın

türban

sevmeliyim aslında seni

ben ki

erkek egemen', 'ne mübarek şeysin öyle orta çağın karasından kara bir tabudan gelir neslin tesettür yada Burkadır soy adın kuşandın mı  bedene  an geçmez ya...', ARRAY['Türk Edebiyatı','Şiir','Esat Korkmaz']::text[], 8.5, '{"poet":"Esat Korkmaz","poet_slug":"esat-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/turban-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönlümde', 'deli-gonlumde-necati-keceli-l4aq9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerime bir bak içim cız etsin

   Aşkınla sulanan, çiçekler bitsin

   Bütün hüzünlerim, bırakıp gitsin

   Mutluluk arayan, deli gönlümde

   Bir şiir yaz bana sımsıcak olsun

   Gözlerim mısrada, sevgiyi bulsun 

   Kalbe aşk, gönül’e mutluluk dolsun

   Aşk sevgiyle yanan deli gönlümde

   Gel de gir rüyama bütün her gece

   İster sultanım ol, istersen ece

   Sevginle kalbime, dol hece hece

   Gözlere aşk soran deli gönlümde

   Bir güneş gibi doğ, benim içime

   Bu aşkımı getir, sen bir biçime

   Bahçemde gülüm ol, düşme hiçime

   Gözden kalbe akan deli gönlümde

   Bir kere tut okşa saçın telini

   Yavaş yavaş gezdir başta elini

   Gönlüme çevir, şu aşkın yelini

   Mutluluğu soran, deli gönlümde

   Necati KEÇELİ

  ADANA', 'Gözlerime bir bak içim cız etsin    Aşkınla sulanan, çiçekler bitsin    Bütün hüzünlerim, bırakıp gitsin    Mutluluk arayan, deli gönlümde  ...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/deli-gonlumde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüzlük Şarkımız', 'olumsuzluk-sarkimiz-rifki-kaymaz-jpikg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceleyin gökyüzünde bir yıldız

Işık saçar, bir mutluluk gönderir.

Yıllar yılı ölümsüzlük şarkımız

Söylenir de yıllar yılı söylenir.

Söylenir de yıllar yılı söylenir

İçimizde yankılanır bestesi

Zincirler kırılır, kırılır bir bir

Duyulur içerden bir muştu sesi.

Duyulur içerden bur muştu sesi

Yayılır dört yana yayılır birden

Karanlığın ezilirkean gölgesi

Aydınlığa kavuşulur yeniden.', 'Geceleyin gökyüzünde bir yıldız Işık saçar, bir mutluluk gönderir. Yıllar yılı ölümsüzlük şarkımız Söylenir de yıllar yılı söylenir. Söyleni...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olumsuzluk-sarkimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müptela Şehir İstanbul', 'muptela-sehir-i-stanbul-eyup-gok-sacvi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Genç bir adam geldi bu şehre

Hayalleri büyük sığmıyor kente

Kendi küçük ama şehir Yeditepe

Genç adam bakıyor Çamlıca''dan

Burası Avrupa, kendisi Anadolu''dan

İnsanlar var, kendi gibi her yaştan

Masal gibiydi anlatılanlar, eski şehrinde

Sokaklar, caddeler, görünen her yerde

Altınlar vardı hani, her yeni gelene

Şimdi düşlerde kaldı beklentiler 

Onlarda bu yoldan, eğer geçmişseler

Zamanla anlıyor insanı, şehirdekiler

Her ne yaşandıysa, eski bu kentte

Duygu müptelası oluyor bu gençte

Zaman farklı işliyor, inan bu şehirde

Yaşanan her his ve bekleyiş insanı

Olgunlaştırıp, deli deli akıtıyor kanını

Şairleri okudukça, çoğaltıyor aşkını

''Sevmez ise gönül, aşkı ne anlar''

Aşk şarabı içmiş, bunu anlatanlar

Hasretim diyor, uzaktan bakanlar

Aşkı aramakla geçti, koca ON YIL

Zamana bırak artık, Kendini bul

Müptela olduğun bu şehrin adı:''İSTANBUL''', 'Genç bir adam geldi bu şehre Hayalleri büyük sığmıyor kente Kendi küçük ama şehir Yeditepe Genç adam bakıyor Çamlıca''dan Burası Avrupa, kend...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Gök']::text[], 8.5, '{"poet":"Eyüp Gök","poet_slug":"eyup-gok","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/muptela-sehir-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakalın Hayallerim', 'hoscakalin-hayallerim-lee-vincant-gusdi-69av0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi gitmek var aklımda

Bu şehri terketmek...

Sahip olduğumu sandığım

Ama hiçbir zaman benim olmayanları 

Arkamda bırakmak...

Tüm anılarımı denize atmak...

Belki yeniden başlamak...

Yalan sevgilerden yoruldum artık.

Zaten daha fazla kandıramıyorum kendimi sevildiğime,

Yalnızlıktan kaçamıyorum daha fazla

Ne de hayal kırıklıklarından...

Şimdi kalmak anlamsız.

Biraz daha beklersem

Umutsuzluğun karanlığı hapsedicek beni.

Şimdi,

Şimdi gitmem gerek...

Güneşin doğduğu bir yere.

En azından bakışlarımı kaçırmam gerekmeyen bir yere.

Hoşçakalın hayallerim

Ve ne olur beni unutmayın', 'Şimdi gitmek var aklımda Bu şehri terketmek... Sahip olduğumu sandığım Ama hiçbir zaman benim olmayanları  Arkamda bırakmak... Tüm anılarımı...', ARRAY['Türk Edebiyatı','Şiir','Lee Vincant Gusdi']::text[], 8.5, '{"poet":"Lee Vincant Gusdi","poet_slug":"lee-vincant-gusdi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hoscakalin-hayallerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefsim', 'nefsim-seyfet-bozcali-wft20', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben aldıkça dahasını istedi,

Yeni şeyler için hayel süsledi,

İçerimde şeytanları besledi,

El aleme rezil eyledi nefsim...

Dünyalık metanın peşinden koştu,

Tükenmeyen mal,servete kavuştu,

Rezillikler aştı,sonra sıvıştı,

Dostlukları zehir eyledi nefsim...

Ölünce anladı Hakkın özünü,

Bir avuç toprak doyurdu gözünü,

Orada anladı tadın özünü,

Tattırmadı gerçek lezzeti nefsim...

       19.01.2006', 'Ben aldıkça dahasını istedi, Yeni şeyler için hayel süsledi, İçerimde şeytanları besledi, El aleme rezil eyledi nefsim... Dünyalık metanın p...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nefsim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar Zemheriye Bilet Kesince', 'ruzgar-zemheriye-bilet-kesince-umut-gungor-0t2jn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rüzgar zemheriye bilet kesince,

Şu bağrıma sancı olup esince,

Bir ıslık duyarım senin sesince,

Ayazdan rüzgardan haberim olmaz.

Dağlara koşup kardelen dererken,

Gururu benliği yere sererken,

Hele birde aklımdan sen geçerken,

Ayazdan rüzgardan haberim olmaz.', 'Rüzgar zemheriye bilet kesince, Şu bağrıma sancı olup esince, Bir ıslık duyarım senin sesince, Ayazdan rüzgardan haberim olmaz. Dağlara koşu...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruzgar-zemheriye-bilet-kesince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprak Olmak', 'yaprak-olmak-lee-vincant-gusdi-i83yb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamana karşı savaşamayacağım artık.

Düşlerim yenik düştü çaresizliğe.

Geçen her saniye ile 

Bir parça daha kopuyor kalbimden.

Her akşam biraz daha erken yatıyorum,

Gelen güne dayanabilmek için.

Hergün ellerimi uzatıyorum boşluğa,

Belki bir tutan olur diye,

Ama güneş batarken,

Ben yine yalnız oluyorum.

Özlemle bakıyorum düşen her yaprağa,

Sonbaharı izlerken kirli camımdan,

Bende yaprak olmak istiyorum.

Dolu yaşayıp,

Bir yılda sararmak,

Yavaşça düşmek dallardan...

Düşen her yaprak için

Bir damla akıyor gözlerimden.

Düşen her yaprakla daha özgür oluyorum.

Yaprak oluyorum yani.

Gözyaşlarım donuyor yanaklarımda.

Soğuğu da hissetmiyorum ki artık...', 'Zamana karşı savaşamayacağım artık. Düşlerim yenik düştü çaresizliğe. Geçen her saniye ile  Bir parça daha kopuyor kalbimden. Her akşam bira...', ARRAY['Türk Edebiyatı','Şiir','Lee Vincant Gusdi']::text[], 8.5, '{"poet":"Lee Vincant Gusdi","poet_slug":"lee-vincant-gusdi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yaprak-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Narinsin Gelincik Yaprağı Kadar', 'narinsin-gelincik-yapragi-kadar-umut-gungor-x6fgt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Narinsin gelincik yaprağı kadar,

Dokunmam zamansız solarsın diye,

İncesin çiçeğin toprağı kadar,

Dokunmam zamansız solarsın diye.

Güneş''ten yağmur''dan yelden saklarım,

Erime  savrulma ıslanma diye,

Soğuk''tan sıcak''tan sel''den saklarım,

Üşüme kavrulma kapılma diye.', 'Narinsin gelincik yaprağı kadar, Dokunmam zamansız solarsın diye, İncesin çiçeğin toprağı kadar, Dokunmam zamansız solarsın diye. Güneş''ten ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/narinsin-gelincik-yapragi-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kız Çocuğu Büyüyor', 'bir-kiz-cocugu-buyuyor-nurten-koroglu-shofz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kız çocuğu büyüyor

Azerbaycan,n barut kokan sabahında

Isınmak  için minicik elleri ateşe uzanıyor

Parmaklarından ince dal parçaları

Tutuşmak için yağmurla savaşıyor

Ak yüzünde kara lekeler

Küçücük kalbinde koskoca bir dünya sabrı

Attıkça dalları ateşe,alevler boyunu aşıyor

Kim bilir rüyalarında,

Savaşın olmadığı hangi dünyada yaşıyor

Sorsam oyuncak nedir bilir mi ki? 

Anlam veremediği toplarla tüfeklerle

Kardeş olmuş birlikte yaşıyor

Etrafına bakan sorgulu gözlerle

Yarınsız bir dünyaya koşuyor

Kara gözlerinden belli

Yine de bir umut arıyor yarınlarda

Bir kız çocuğu üşüyor

Azerbaycan,n güneşi doğmayan

Barut kokan sabahında

Sevgi desen yok,

Baba şehit olmuş savaşta.

Şefkat desen o da yok,

Anası kara yasta.

Bir kız çocuğu büyüyor,

Azerbaycan,n barut kokan sabahında,

Yarı hasta.', 'Bir kız çocuğu büyüyor Azerbaycan,n barut kokan sabahında Isınmak  için minicik elleri ateşe uzanıyor Parmaklarından ince dal parçaları Tutu...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-kiz-cocugu-buyuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İste', 'i-ste-seyfet-bozcali-fkvyb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Var onun varlık onun,verir hep istedikçe,

Her şey ona ayandır,dile de diledikçe,

İsteğini iyi yaz ulaşır o dilekçe,

Verenin şanı yüce,iste sen istedikçe.....

Yaşam O''nun can O''nun,yaşatır  gerektikçe,

Rızıklarını kesmez,kullar şımarmadıkça,

Şükürler etmelyiz tende iman oldukça,

Kul istediğini alır,hakkıyla istedikçe...

20.01.2006', 'Var onun varlık onun,verir hep istedikçe, Her şey ona ayandır,dile de diledikçe, İsteğini iyi yaz ulaşır o dilekçe, Verenin şanı yüce,iste s...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/iste-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antet', 'antet-mehmet-rizaoglu-m3obp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İster misin; 

Gözlerini kapatıp,

Kaplumbağa gibi tıpa tıp,

Bir geziye çıkmak! ..

Hiç''ten başlayıp,Var''a ulaşmak,

Var''ın Varları''nda dolaşmak

Ruhumun,bârid odalarında,

Ayrı ayrı Ben''le tanışmak! ..

Ben! ..

Hepsi farklı Ben.

Bu kadar bolluğa rağmen,

Bir tek Ten.

Özel bir oda

Kapı kilitli.

Önünde birbirini yiyen Ben''ler

Sanki lanetli.

Anahtarı,Ben''de görüyorum,

Ama O çelikten,Ben eriyorum.

Ey! ..Bütün Ben''leri

Biz yapan Güç! ..

Ben''leri,Hiç yaptın

Hiç''leri,Ben.

Parlasın,artık şu Kalb-i Ahen.

Biz ki,Vücûd-u toprak,

Sen ki,Kadîr-i Mutlak! ..', 'İster misin;  Gözlerini kapatıp, Kaplumbağa gibi tıpa tıp, Bir geziye çıkmak! .. Hiç''ten başlayıp,Var''a ulaşmak, Var''ın Varları''nda dolaşmak...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Rızaoğlu']::text[], 8.5, '{"poet":"Mehmet Rızaoğlu","poet_slug":"mehmet-rizaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/antet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sis', 'sis-arzu-akin-actti', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sis sardı etrafımı önce,

Kalbim duracak gibi oldu bunu görünce.

Unuttuğumu sanmışım meğerse,

Sen yalanmışsın, ben de yalan...

Meğer her şey yalanmış,

Gerçek olansa hiçbir şeymiş

Aşk yalan, umut yalan

Asıl gerçek hiçbir şeymiş

Unut beni,

Zaten hatırlamak bile istemezsin

Ben her ne kadar birşey yapmamış olsamda,

Sen bilirsin!', 'Bir sis sardı etrafımı önce, Kalbim duracak gibi oldu bunu görünce. Unuttuğumu sanmışım meğerse, Sen yalanmışsın, ben de yalan... Meğer her ...', ARRAY['Türk Edebiyatı','Şiir','Arzu Akın']::text[], 8.5, '{"poet":"Arzu Akın","poet_slug":"arzu-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sis-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyümüze Gidelim', 'koyumuze-gidelim-huseyin-sonmez-oklur', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zehra ninenin gözlemesini yiyelim,

Hacı Ahmet''in balını ekmeğimize sürelim,

Zeynep ebenin ayranını içelim,

Gel bizim köye gidelim sevgilim.

Bizim köyde başka öter horozlar,

Başka başka meler yavru kuzular,

Başka başka koşar ceylan gibi tazılar,

Gel bizim köye gidelim sevgilim.

Kara Oğlan''da dağa çıkalım,

Çavuşlar Köyü''nü seyredelim bakalım,

Bir çamın dibinde sarılalım yatalım,

Gel bizim köye gidelim sevgilim.

Yataklıklarda davar güdelim,

Şelâlede suya girip çimelim,

El ele Yazı Pınarı''nda gezelim,

Gel bizim köye gidelim sevgilim.

Kamışlı Çayır''da ata binelim,

Harman Arkası''nda düven sürelim,

Odanın önünde dibek dövelim,

Gel bizim köye gidelim sevgilim.

Hacı İbrahim''in bağına girelim,

İri iri üzümlerini yiyelim,

Kara dutun dutlarını dövelim,

Gel bizim köye gidelim sevgilim.', 'Zehra ninenin gözlemesini yiyelim, Hacı Ahmet''in balını ekmeğimize sürelim, Zeynep ebenin ayranını içelim, Gel bizim köye gidelim sevgilim. ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/koyumuze-gidelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Gelsin', 'senden-gelsin-seyfet-bozcali-h5i6y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kazabında,sevginde gelirse senden gelsin,

Yarap rahmetinlede,kahrınlada güzelsin.

Bizler hep bir faniyiz,dönüşümüz sanadır,

Yüzümüzü güldüren,mağfiret senden gelsin...

Bu naciz zayıf kulun,yoluna feda olsun,

Birazcık lutuf eyle,gönlü aşkınla dolsun,

Duamızı kabül et,biraz yüzümüz gülsün,

Cennet''ine kabul et rahmetin senden gelsin...', 'Kazabında,sevginde gelirse senden gelsin, Yarap rahmetinlede,kahrınlada güzelsin. Bizler hep bir faniyiz,dönüşümüz sanadır, Yüzümüzü güldüre...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senden-gelsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Mutlu Sabahlar', 'beklenen-mutlu-sabahlar-eyup-gok-5vyc7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kelam olup da gelsem dillere

Şiir olup da girsem kalplere

San''atı haykırsam, şair olup da ilime

Dinmez gözyaşlarım, döner sellere

Tefekkürü bulamazsam nicedir halim

Maddeye takılıp ya olursam zalim

Halvete girsem lakin sadece benle

Bulurmuyum Beni kendi kendimde

Eskiler söyler, bugünden sonra

Lakin yaş geldi kemale, sorma

Haniydi beklenen mutlu sabahlar

Gelmedi dünden sonraki yarınlar', 'Kelam olup da gelsem dillere Şiir olup da girsem kalplere San''atı haykırsam, şair olup da ilime Dinmez gözyaşlarım, döner sellere Tefekkürü ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Gök']::text[], 8.5, '{"poet":"Eyüp Gök","poet_slug":"eyup-gok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beklenen-mutlu-sabahlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ot', 'ot-sefer-i-nce-nigth', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen suyuna toprağına bak,

Sanane maganda dolmuş şoföründen.

Boydan boya ıslanan kızdan...

Eşitlik var memlekette,

Ne olmuş alınmamışsa 

O güzel okula fatey''in kızı.

Ne yani, istemedi mi dersin,

Patronun  altına yatarken Hanzey.

Demedim mi sana kardeşim? 

Bu Iraz döl tutmaya meraklı

Bu onbeşinci oldu, bunlar var ya.. bunlar...

.... Ha bire  doğururlar.

Sen suyuna toprağına bak,

Adam mı bunlar? 

Akşama kadar kahvelerde,

Sonra da tükürürler sokaklara.

Otlar... Dere kenarında, sazlıklarda

Salınır dururkan 

Çığlıklarla havalanır elekçi  kuşları.

Otlar... Kendirik tadında,

Otlar... kadın dokunuşunda,

Otlar... Muş ovasında dalga.

Sen suyuna toprağına bak,

Otlayan henüz kimse yok buralarda...', 'Sen suyuna toprağına bak, Sanane maganda dolmuş şoföründen. Boydan boya ıslanan kızdan... Eşitlik var memlekette, Ne olmuş alınmamışsa  O gü...', ARRAY['Türk Edebiyatı','Şiir','Sefer İnce']::text[], 8.5, '{"poet":"Sefer İnce","poet_slug":"sefer-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ot-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-seyfet-bozcali-l5ekd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman geçiyor çabuk,vakit doluyor hey hat,

Yaşam ömrümüzde yük,çalış günlere gün kat,

Yalan dolan bir düzen,al birini ona sat,

Birde baksan geriye,var birçelmelik hayat...', 'Zaman geçiyor çabuk,vakit doluyor hey hat, Yaşam ömrümüzde yük,çalış günlere gün kat, Yalan dolan bir düzen,al birini ona sat, Birde baksan ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayat-290-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımın Duvarlarına Çarpan', 'aklimin-duvarlarina-carpan-sevinc-kavuk-vnu93', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aklama,

yaşamda zaman zaman

şöhret ile zevk arasında seçim yapma gerekliği iken

teknolojiyle virüs bilimi birleştirmek de oldu

kalan akla yakınlık, söylenen en ince yalan.

Aklı çalıklar da yaşamın akımında kürek çekerler zaten.

Aklından geçeni gömleği gibi değiştirmeli

bir temizlik konumudur diyor Jules Renard...

Bu yüzden söylenirmiş 

''insan artık bir şey düşünemiyor ki,

başka bir budalanın da aklından aynısı geçmemiş olsun! 

Akıldan geçen denilen anlayış avantürüne

akıldan geçme şemsiyesi de beraber götürülmeli''...diye

Aklımın duvarlarına çarpan bu her tutanağa

hoş geldiniz demeyi üstelik becerdim de

sığmak istemediler kabuklarına

hazırladım bohçalarını

giderken almayı

dönerken doldurmayı 

unutmadan hem gitsin hem gelsinler diye 

yolluk olarak

güle güle uğurlanırlarken hatırlanan olmayı

bilerek...

20 Ocak 2006', 'Aklama, yaşamda zaman zaman şöhret ile zevk arasında seçim yapma gerekliği iken teknolojiyle virüs bilimi birleştirmek de oldu kalan akla ya...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aklimin-duvarlarina-carpan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçilmez', 'gecilmez-seyfet-bozcali-rngyg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O ra hakkın kapısı,yorulmadan geçilmez,

Sorularına cevap verilmeden geçilmez,

Yüzünü eşiğine sürülmeden geçilmez,

Mevla''nın ipliğine sarılmadan geçilmez...

Rızası olmaz ise o güzellik görülmez,

Emekler zayi ise o kul hiç zaman gülmez,

Salih ameli yoksa ahirette sevinmez,

Rabbi''min rahmetine güvenmeden geçilmez...', 'O ra hakkın kapısı,yorulmadan geçilmez, Sorularına cevap verilmeden geçilmez, Yüzünü eşiğine sürülmeden geçilmez, Mevla''nın ipliğine sarılma...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gecilmez-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kartal Kanadında Sana Ulaşsam', 'kartal-kanadinda-sana-ulassam-umut-gungor-hnq6j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kartal kanadında sana ulaşsam,

Senin için yedi diyar dolaşsam,

Farketmez toprağa toza bulaşsam,

Bulutları yarsam yine farketmez.

Dünya çiçeği toplayıpta dersem,

Binlerce karanfil yerlere sersem,

Bağrımı esen rüzgara gersem,

Bulutları yarsam yine farketmez.

Sana ulaşayım gün gece olsun,

Söğlenmeyen o iki hece olsun,

Sana ulaşayım gün gece olsun,

Bulutları yarsam yine farketmez.

Gökkuşağı renkler saçmasın varsın,

Karanfil dağlarda açmasın kalsın,

Kuşlar göklerde uçmasın varsın,

Bulutları yarsam yine farketmez.

Farketmez sabaha kadar ağlasam,

Şu yüreği gönlü ruhu dağlasam,

Sinirden konuşan dili bağlasam,

Bulutları yarsam yine farketmez.', 'Kartal kanadında sana ulaşsam, Senin için yedi diyar dolaşsam, Farketmez toprağa toza bulaşsam, Bulutları yarsam yine farketmez. Dünya çiçeğ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kartal-kanadinda-sana-ulassam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahibini Arayan Mektup', 'sahibini-arayan-mektup-yusuf-safi-mylc2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Söz verdiği gibi zamanın usulca çekip gitmişti tıpkı hatıraların gibi ne geriye dönüş kaldı nede ileriye dönük herhangi bir umut. Kalan yalnızca sessizce bir çöküştü senin gözlerinde. Ayrılığın var olduğuna dair getirdiğin somut deliller bana seni tanıtmıştı, varolan bir gerçek ve yok olan bir yaşam. Gittiğin gün neden aklına getirmedin sen kaç hayat söndürmüştün kendinle beraber kaç gül soldurmuştun kendi gözlerinde.

Umut da seninle beraber sessizce terk etmişti tüm yaşamlarımızı, zaten yok olan bir hayatın umudu olmazdı. Aynen öyle bırakıp gitmiştin her şeyi.

Senin ardından şiirler döküldü nice şairin kaleminden, nice dengbej senin adına türkü yaktı,

Sana ulaşamayan ama yüreğimi dağlayan en acıklı sözler döküldü senin ardından. Bütün canlılar düşman kesildiler birbirine ve bir serçe yavrusunu terk etti tek bir damla gözyaşı dökülmeden gözlerinden tıpkı senin gibi. Rüzgarlar fırtınaya dönüştü yağmurlar kasırgaya ve dağıttılar tüm yaratılanların yuvalarını düşleriyle umutlarıyla sonra arkalarına bile bakmadan terk edip gittiler bu şehri senin gittiğin gibi.

Bilmem kaç mektup yazıldı sana ama hiç birisi sana gönderilemedi çünkü sen bilinen bir şehri tüm bilinmezliklere sürüklemiştin. Acaba diyorum mecnun benim yerimde olsaydı ne yapardı yada Ferhat, dağları deldikten sonra hoşça kal bile demeden hoşça kal bile demeden gitseydi Şirin.

 Sen gidince bu şehirden  Boş belgeler giriyordu hayatıma Yağmurlar da sessizce senin ardından terk ediyordu beni. Senin yokluğunda tüm melankoli anlarım anlamsızlaşıyordu 

Boş sayfalara yazılar yazıyordum  hiçbir anlamı olmayan,  kimseyi duygulandırmayan

Şiirler döküyordum beyaz ama saflığını yitirmiş kağıtlara. Ta sabahın ilk ışığına kadar  Düşlere terk ediyordum tüm gerçeklerimi, güneş doğuyor ve ben uyanıyordum senle geçirdiğim tüm rüyalarımdan', 'Söz verdiği gibi zamanın usulca çekip gitmişti tıpkı hatıraların gibi ne geriye dönüş kaldı nede ileriye dönük herhangi bir umut. Kalan yaln...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Safi']::text[], 8.5, '{"poet":"Yusuf Safi","poet_slug":"yusuf-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sahibini-arayan-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydınlık Gece', 'aydinlik-gece-eyup-gok-xapx1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin bütün güzelliği, kalplerde gizli

Aydınlıktan farkı, tevazudan ibaret

Sabahları cesur olur insan neyazık ki

Karanlıktan farkı, ihlastan ibadet

Geceyle aydınlanır, sevginin yüzü

Bir ömür boyu görünür sonra

Yıldızlar ve yakamozlar, O''nun süsü

Tüm kötülükler O''nda birer forsa

Lakin dinlemek istemiyorsan geceyi

Yalvarırım genede karanlık deme 

Bil ki insana öğreten O''dur secdeyi

Karanlıktır tüm kötülüklere gebe

O''nun kollarında tanırsın kendini

Aynaya ne hacet, hava kararırken

Bilir kendi payına duracağı yeri

Yine de dinle O''nu zamanı yaşarken

Sen genede karanlık deme O''na

Nasıl görürdük endem-ı hilali

Dinle, huzuru bulursun kollarında

Bilmezdik yıldızı, nuru ve de güneşi

Aydınlatan ışık, ondan bir ürün

Sevgiden sıkılmış, bir kadeh şarap

Tefekkürü bize, O verdi büsbütün

Olmasaydı gece, tüm şiirler harap

Sen, genede karanlık deme O''na

Aslında O, aydınlığın ta kendisi

Yaklaştığını hissediyorsan Son''a

Bil ki sensin gecelerin Efendisi.', 'Gecenin bütün güzelliği, kalplerde gizli Aydınlıktan farkı, tevazudan ibaret Sabahları cesur olur insan neyazık ki Karanlıktan farkı, ihlast...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Gök']::text[], 8.5, '{"poet":"Eyüp Gök","poet_slug":"eyup-gok","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aydinlik-gece-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahibini Arayan Mektup-2', 'sahibini-arayan-mektup-2-yusuf-safi-htyw0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sonbahara dönen mevsimin başlangıcında yitivermişti yine zaman. Senin çekip gitmenle talihsiz bir yağmur yağıyordu kendisine bile faydası olmayan bereketsiz bir yağmur dökülmüştü senin ardından.

Gittiğin gün hani bu kentte yıkılmamıştı. Sadece biraz sıkılganlık bir kabına sığmama ruh hali vardı o gün. Ama kuşlar ayrılmıştı şehirden senin gibi, her sonbaharın başlangıcında. Ve sen gitmiştin eylül ortası sonbahar başlangıcı, arkana bile bakmadan

Son defa ellerimi sıkıp “Allahaısmarladık, belki yine görüşürüz.” 

İki cümle iki kısa ama yaşamı kara bir deliğe dönüştüren söyleyip yitmiştin.

“Hoşça kal ve kendine iyi bak” umutsuzca dökülmüştü ağzımdan, sen ellerini kurtarmaya çalışırken avuçlarımdan.

İşte gittin

Ve yağmur tekrar yağacak bu şehre, fırtınalar belki kopmayacak ama gittiğin günün sıkılganlığı hep bende kalacak. Arkandan belki yas tutmayacağım fakat seni her düşündüğümde sana söz bir sigara yakacağım, geceleri arabesk şarkılar çalacak radyolarda ve ben sabahlara kadar onları dinleyeceğim. Bu sefer jilet atmayacağım yalnızca önceki yaralarıma bakıp biraz hüzünleneceğim. 

Sen gittin işte 

Bir eylül günü öğlenin tam ortası hani hiç olmayacak bir saate, ayrılığa hiç yakışmayacak bir saate.

Saat, 12:30 

Bekleyebilirdin oysa akşamı yada ikindi vaktinin geç saatlerini o zaman belki biraz daha romantik olurdu ayrılığımız. O saate gider efkarlı efkarlı şarkılar söylerdim şehrin kendine bile faydası olmayan yağmurlarında, yada sarılacak bir dost bulurdum. Oysa sen ayrılığa hiç yakışmayan bir saati seçmiştin. 

Gittin ve gitmeliydin 

Ardında bir türkü bırakabilirdin en azından “bu şehri seninle sevdim.” Şimdiyse bu şehri sensiz seviyorum, ateşin ortasında kalan bir sevgimde yok artık.

Hoşça kal ve kendine iyi bak

Gittin işte

Belki bir daha rüyalarıma dahi gelmeyeceksin, gülüşünün izi kalacak boş koridorlarda, bir de dökülen saçlarının telleri. Teker teker  her bir telini alıp okşardım. 

Belki yine okşarım alıp ta götüremediğin senden bana kalan tek şey. Dağılmasınlar diye tüm bir sonbahar hiçbir pencereyi açmayacağım. 

Gitmen gerekiyordu 

Seni bekleyen yeni hayatlar yeni umutlar ve yepyeni bir gelecek. 

Çünkü sen bu şehre sığmıyordun ben seni yüreğime sığdırmaya çalışırken. 

Söyleyivermiştin 

Bir gün buralardan gideceğini belki bir daha hiç geriye dönmeyeceğini. Ama o kadar erken beklemiyordum bu ayrılığı, hani ne zaman gitsen yine erken olur ama o kadar da erken gitmemeliydin.

Biraz daha kalabilirdin, belki bir gün daha, en azından akşamı bekleyebilirdin.

Hoşça kal ve kendine iyi bak

Arkandan ağlamadım, bir damla gözyaşı dahi dökmedim hep öptüğün gözlerimden.

Efkarlandım bağırmak istedim, fakat sen en uygunsuz saatte Allahaısmarladık dedin ve ben sustum. 

Ardından uzun uzun bakarken ilk kez tanıdım seni ve beni, yolları kesişmemesi gereken iki yabancı iki farklı atomun yörüngesinde dönen zıt elektronlar.

Ama ilk kez ardından bakarken anladım ne kadar bağlandığımı sana. Ve sessizce dökülüverdi ağzımdan

  Kendine iyi bak ne olur.', 'Sonbahara dönen mevsimin başlangıcında yitivermişti yine zaman. Senin çekip gitmenle talihsiz bir yağmur yağıyordu kendisine bile faydası ol...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Safi']::text[], 8.5, '{"poet":"Yusuf Safi","poet_slug":"yusuf-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sahibini-arayan-mektup-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahibini Arayan Mektup-3', 'sahibini-arayan-mektup-3-yusuf-safi-ynpih', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gün yokluğunun bilmem kaçıncı günü

Havada puslu bir duman 

Ekim ayının tam ortaları

Artık bu şehir mevsim gibi kendini kışa hazırlıyor.

Sonbaharın son yağmurları da artık veda ediyor bu lanetli şehre 

Çünkü bu gün yokluğunun bilmem kaçıncı günü

Ben  yine her sabah erken kalkıyorum, şehrin bomboş caddelerinde hesapsız voltalar sayıyorum.

Hangi sokakta hangi kavşakta yitirmiştim seni, onlara soruyorum ama sözbirliği etmişçesine hiçbir kavşak, hiçbir sokak cevap vermiyor sorularıma. Sonrasından ben küfürler sayıyorum her geçtiğim kaldırıma sokağa kavşağa. 

Hala geceleri en son ben yatıyorum bu şehirde tüm ışıkların bir bir sönmesini bekliyorum ve ardından içtiğim en ucuz sigaranın son izmaritine kadar seni bekliyorum.

Belki de seni değil senden gelecek bir haberi.

Acaba şimdi neredeydin? 

Hayata mıydın en azından? 

Hayattaysan mutlu muydun? 

Mutluysan bensiz nasıl başardın? 

Bu gün yokluğunun bilmem kaçıncı günü

Sabahlara kadar radyo istasyonlarının cızırtıları dolanıyor yalnızca odam da değil beynimde 

Her şarkıda ismini duymak özlemiyle sesini kısmıyorum 

Bu şehir sakladı seni benim içimde

Ve şehirler arası bir otobüs alıp götürdü seni benden.

14 numaralı koltuk pencere kenarı,

uğurlamaya seni kimse gelemediği halde ağlamadığını biliyorum,

belki başını yaslamışsındır camın soğukluğuna.

Acaba giderken diyorum hatırlamış mıydın beni 

Sessizce köşeme çekilip başımı avuçlarımın arasına aldığımı hiç düşünmüş müydün.

Üzülmüş müydün hiç halime,

Üzülür müydün halime eğer görseydin kupkuru yaşları gözümde.

Bu gün yokluğunun bilmem kaçıncı günü

Taptaze doğmadı güneş bu sabah, 

Bulanıktı bütün gün 

Hatta sabahleyin bile doğmak istememişti

Saklamıştı kendini birkaç kara bulutun arkasına

Ve kuşlar bu sabah hiç ötmedi, yeni bir günü müjdelemediler

Oysa bütün gece onları beklemiştim yapayalnız, 

Soğuk bir rüzgar esti bütün gün fakat ağaçlar yerlerinden kımıldamak istemeyen bir çocuk gibi zorlukla sallandılar bir o yana bir bu yana. 

Çünkü bu gün tarihin en karanlık günü bu şehirde 

Doğa bir daha kaldıramaz böyle bir acıyı

Bu gün yokluğunun bilmem kaçıncı günü

Ve hala ne sen varsın ne de senden bir haber', 'Bu gün yokluğunun bilmem kaçıncı günü Havada puslu bir duman  Ekim ayının tam ortaları Artık bu şehir mevsim gibi kendini kışa hazırlıyor. S...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Safi']::text[], 8.5, '{"poet":"Yusuf Safi","poet_slug":"yusuf-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sahibini-arayan-mektup-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dövünme', 'dovunme-seyfet-bozcali-n63q9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben ölünce hiç boşuna dövünme,

Arkamdan azmı beddua ettin,

Mal servetim senin diğe sevinme,

İşte o hesapla öteğe gittim...

Hayırlı dua et,hep hayırla an,

Bir fatiha oku,şenlensin mekan,

Hiç bir fayda yoktur bu dünyalıktan,

İşte bunun için sizi eğittim....

Var ise arkada hayırlı evlat,

Yazılır sevaplar amelde kat,kat,

Harırda yarışa daim gayret et,

Yoksa faydasız şey için dövünme...', 'Ben ölünce hiç boşuna dövünme, Arkamdan azmı beddua ettin, Mal servetim senin diğe sevinme, İşte o hesapla öteğe gittim... Hayırlı dua et,he...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dovunme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimizde bir rüzgar', 'i-cimizde-bir-ruzgar-halime-vatansever-jwvm1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her anımdaydın önceleri 

Sonra bir anı oldun 

Rüzgarla kapandı kapıları gönlümün 

Savruldu hoyratça saçların 

Yavaşça bana dokundu 

Ellerinin elimi bırakmak istememesi gibi 

Oysa biliyorduk ikimiz de 

Yaşamamak gerek birşeyi 

Eğer unutmak istemiyorsak 

Yaşamıştım oysa ben saçlarını 

Her teline dek 

Ve saçların 

Unuttum 

Onların elime verdiği 

Kalbine dokunuyormuşum hissini 

Öyle bir unutuş ki 

Yüzünü bir türlü aklıma getirememem gibi. 

Oysa biliyordun sen de 

İkimiz de düşünmedik 

Bu rüzgarda savrulup gideceğimizi 

Pişmanım seni bu kadar çok sevdiğime 

Çünkü ateşi güçlü olan mumlar çabuk erir 

Ya da bir rüzgar geçer 

Söndürüverir onları 

Yarım kalırlar 

İçilmiş sulardan geriye 

Buruk bardaklar gibi', 'Her anımdaydın önceleri  Sonra bir anı oldun  Rüzgarla kapandı kapıları gönlümün  Savruldu hoyratça saçların  Yavaşça bana dokundu  Ellerini...', ARRAY['Türk Edebiyatı','Şiir','Halime Vatansever']::text[], 8.5, '{"poet":"Halime Vatansever","poet_slug":"halime-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/icimizde-bir-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahibini Arayan Mektup-4', 'sahibini-arayan-mektup-4-yusuf-safi-ilp11', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gittiğinin henüz ertesi günü

Şimdiden duvarlara çizik atmaya başladım. Acaba diyorum kendime kaçıncı çizikte tüm çiziklere bir çizgi çizeceğim.

Belki tüm duvar beyazlığını siyahlara terk edince bitecek bu lanet ibadet 

Ama o gün senin döneceğin gün de olmayabilir, tıpkı beyaz duvar gibi karanlıklara gömüleceğim gün olur.

Acı tazeyken neden farkına varamıyor insan, tıpkı bir bıçak yarası gibi bir sıcaklık var şimdi bedenimin bilmediğim, dokunmaya korktuğum yada kendime kabullenmeye korktuğum tarafımda sıcak bir acı var.

Yarın yaram soğuyacak ve ben yeni farkına varacağım senin gittiğini ve bir daha da geriye dönmeyeceğini, o zaman farkına varacağım kurduğum saçma sapan hayallerin asla gerçekleşmeyeceğini.

Bir soğuk ürperti saracak beni tıpkı her hava her soğuduğunda beni saran ürperti gibi.

Annesini kaybetmiş bir çocuk gözüyle etrafı süzeceğim.

Ellerini saran ellerim boşlukta sallanıyor şimdi. 

İnan bana hiçbir dost eli uzanmayacak bana senin yokluğunda.

Yalnız başıma kalacağım ve saçma sapan düşlerim eşlik edecek bundan sonra bana.

Hayalini bekleyeceğim odama geceden sabaha, sabahtan geceye kadar,

Sen gelmesen de hayalin belki geri döner odama,

Soğuk bıraktığın yatağa girmese bile odamı aydınlatacak 

O sımsıcak gülüşünle.

Bu gün gittiğinin ertesi günü 

Henüz kaybolmadı umutlarım, hala koltukta sıcaklığın var

Son demlediğin çay hala demlikte sıcak duruyor,

Dudaklarının izi var fincanında 

Bana en son söylediğin türkünün nakaratı hala kulaklarımda.

Tam bitirmemiştin belki de ama artık hiç tamamlanmayacak bu türkü.

Defalarca tekrar ediyorum oysa dünden beri ama son nakarat bir türlü dökülemiyor dudaklarımdan.

Çünkü en son senin sesine yakışıyordu bu türkü 

Ve o son nakarat.

“feleka me xayine 

ji mere na xamline.”

Bu gün ayrılığının henüz ertesi günü 

Oturup bir köşede sessizce sana bunları yazıyorum.

Ve yağmurlar için dua ediyorumartık yağsınlar bu kente

Temizlesinler senin ayak izlerini tüm kaldırımlardan, 

Birlikte yürüdüğümüz tüm sokaklar arındırsınlar artık kendilerini tüm bu masum günahlardan.', 'Gittiğinin henüz ertesi günü Şimdiden duvarlara çizik atmaya başladım. Acaba diyorum kendime kaçıncı çizikte tüm çiziklere bir çizgi çizeceğ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Safi']::text[], 8.5, '{"poet":"Yusuf Safi","poet_slug":"yusuf-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sahibini-arayan-mektup-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman(sızlık) larım', 'zaman-sizlik-larim-halime-vatansever-xyqfa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşüncelerim çürüdü 

Sabahların bitimi 

Akşama vurdu 

Akşam devrildi

Gecem akşamımı inkar etti 

Ben yine zamansızlığıma çıktım 

Zamansızlığımın tam bu zamanlarına 

Denk geldin sen ki 

Yoksa güzel olurdun 

Olamadın 

Lalelerimle karanfillerimi 

Bir vazoya koydum 

Hiçbiri birbirinin güzelliğine 

Gölge düşürmedi 

Tersine yücelttiler birbirlerini 

Morumun kırmızısına yenik düştüğü vakitlerde 

Karşıma çıkma 

Çıkmadın ya zaten 

Yoksa çirkin olurdun 

Olamadın 

Şimdi neredeyim peki 

Güzelde mi çirkinde mi 

Morum hangi mor 

Çiçeğim lale mi karanfil mi 

Yoksa hepsini bırakıp 

Bir menevşeye mi gönül vermeli 

Peki bu hangi zamanıma denk gelir 

Belki gecelerim gündüzüme sarıldı 

Güneş ayı yaktı kavurdu 

Belki aşk da beni sardı 

Yaktı 

Ben 

Yine zamansızlığımdayım', 'Düşüncelerim çürüdü  Sabahların bitimi  Akşama vurdu  Akşam devrildi Gecem akşamımı inkar etti  Ben yine zamansızlığıma çıktım  Zamansızlığı...', ARRAY['Türk Edebiyatı','Şiir','Halime Vatansever']::text[], 8.5, '{"poet":"Halime Vatansever","poet_slug":"halime-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/zaman-sizlik-larim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ablam''a', 'ablam-a-halime-vatansever-zb393', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneşle beraber açılınca perdeler 

İçerdeki ışıkla gönlünü aydınlatırdı 

Ah be abla 

Şimdi nerde odadaki ışık 

Nerde sen, nerde ben 

Oyuncaklarını bozup 

Küçülen elbiselerini giymemiş miydim 

Ki senin olan herşeyi kabullendim ben 

Anneleri çalışan çocuklar daha çok severmiş birbirini 

Şimdi anladım. 

Kanayan dizime de sen üflemiştin ya 

Onu da hatırlarım 

Bakma sen etrafına 

Çekinme insancıklardan 

Sev sevdiğini, kız kızdığına 

Melek gibisin be abla 

Oysa insanların duyguları fikirlerine esir 

Hak etmiyorlar ya 

Yine de sen aç bana kalbini 

Ve ben yine senin nefesinde 

Arayayım dermanını 

Kanayan yüreğimin.', 'Güneşle beraber açılınca perdeler  İçerdeki ışıkla gönlünü aydınlatırdı  Ah be abla  Şimdi nerde odadaki ışık  Nerde sen, nerde ben  Oyuncak...', ARRAY['Türk Edebiyatı','Şiir','Halime Vatansever']::text[], 8.5, '{"poet":"Halime Vatansever","poet_slug":"halime-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ablam-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çirkin kadınlarım', 'cirkin-kadinlarim-halime-vatansever-4pz9p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Küçükken aynı kadınları çizerdim hep 

Resim derslerinde 

Bir ellerinde çiçekleri diğerinde çantaları olurdu 

Elbiseleri V yakalı 

Ayakkabıları topuklu olurdu 

Ya ayakları tutmazdı birbirini 

Biri kısa biri uzun olurdu 

Ya da parmaklarından biri 

Unutkanlığıma gelirdi 

Ya gözleri 

Hiç bahsetmemeli 

Kadınlarım hep çirkin olurdu benim 

Mutlu değillermiş 

Şimdi farkettim 

Ne ellerini beğenmişler 

Ne elbiselerini 

Hem kollarini kucak açmış gibi 

İki yana açık çizerdim hep 

Hem de yalnız çizerdim onları 

Oysa yalnız bırakmamalı 

Hiçbir resimde 

Hiçbir kadını', 'Küçükken aynı kadınları çizerdim hep  Resim derslerinde  Bir ellerinde çiçekleri diğerinde çantaları olurdu  Elbiseleri V yakalı  Ayakkabıla...', ARRAY['Türk Edebiyatı','Şiir','Halime Vatansever']::text[], 8.5, '{"poet":"Halime Vatansever","poet_slug":"halime-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cirkin-kadinlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tartı', 'tarti-halime-vatansever-t28tc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hangimizin yüzü duvara dönüktü 

Hangimizin önüne duvarlar dikildi 

Hangimiz insana at muamelesi etti peki? 

Tartı hileli 

Tartı dengesiz 

Tartı bozuk', 'Hangimizin yüzü duvara dönüktü  Hangimizin önüne duvarlar dikildi  Hangimiz insana at muamelesi etti peki?  Tartı hileli  Tartı dengesiz  Ta...', ARRAY['Türk Edebiyatı','Şiir','Halime Vatansever']::text[], 8.5, '{"poet":"Halime Vatansever","poet_slug":"halime-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tarti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim', 'yuregim-yusuf-ter-bc5vk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yürek acı ve tatlı, gözlerdedir kalıcı.

