INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tren', 'tren-ahmet-beltekin-9a5sq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her tren sesinde, yeni bir ayrılık var.

Yalnız kalmaktan korkan çocuklar,

Taş atmayın trenlere; 

Sevdiğine kavuşacaklar da var...', 'Her tren sesinde, yeni bir ayrılık var. Yalnız kalmaktan korkan çocuklar, Taş atmayın trenlere;  Sevdiğine kavuşacaklar da var......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Beltekin']::text[], 8.5, '{"poet":"Ahmet Beltekin","poet_slug":"ahmet-beltekin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tren-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Akşamı', 'hayatin-aksami-ahmet-beltekin-74csz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herkes bir şeyler veriyor,hayata,kendinden,

Ve sıkılıyor, üzülüyor, ağlıyor...

Ben de kendimi verdim sana; 

Beni hayata bağlıyor...', 'Herkes bir şeyler veriyor,hayata,kendinden, Ve sıkılıyor, üzülüyor, ağlıyor... Ben de kendimi verdim sana;  Beni hayata bağlıyor......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Beltekin']::text[], 8.5, '{"poet":"Ahmet Beltekin","poet_slug":"ahmet-beltekin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayatin-aksami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Rengi', 'askin-rengi-ahmet-beltekin-uani6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerini açınca,

Ne gökyüzünün maviliğini,

Ne gökyüzündeki kuşları,

