INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reddetme?', 'reddetme-seyfet-bozcali-z69lr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanoğlu Hak yolu adım,adım bilirsin,

Bir denesen no olur, neden inat edersin? 

Bir yanda kurtuluş var,öte yanda bataklık,

Bataklığı seçmede neden israr edersin...

Bu verimli çağında,insana hizmet varken,

Helalı çiğneğipte,haramlara  dalarken,

Şeytanın pisliğini çekip kafa bulurken,

Yaşadığın çirkefte,neden israr edersin..

Yaratan sunmuş nimet her gün bolca yiyersin,

Bunca nimetlerine bir gün şükür etmezsin,

Beş vakit ezan ile çağırırda gitmezsin,

Hayvanca yaşamada neden israr edersin...

              24.01.2006', 'İnsanoğlu Hak yolu adım,adım bilirsin, Bir denesen no olur, neden inat edersin?  Bir yanda kurtuluş var,öte yanda bataklık, Bataklığı seçmed...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/reddetme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader Torbası', 'kader-torbasi-bahri-yildirim-n2yyk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birde baktım ki

Seninle  yüz yüzeyiz

Gözgözeyiz farkına bile varmadan

El  eleyiz.

Ama söylenmiş  tüm sözler

Susuyoruz....

İkimizde zamana uyup

Ya doyumsuzluğundayız aşkın

Ya da fırtına öncesinde kavganın

Sözün tükendiği yerde

Yanyanayız sevmesekte

Aynı torbasındayız kaderin,istemesekte

Amortileriyle avunuyoruz o büyük aşkın

Birileri dönüyor köşeleri

Omuzumuza     basa basa

Biz birbirimizi yerken', 'Birde baktım ki Seninle  yüz yüzeyiz Gözgözeyiz farkına bile varmadan El  eleyiz. Ama söylenmiş  tüm sözler Susuyoruz.... İkimizde zamana uy...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kader-torbasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kapı', 'i-ki-kapi-fatma-guven-sgcc5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğum ve ölüm; iki kapı.

Sonsuzluktan gelen,sonsuzluğa giden.

Filizlenen bir tohum gibi,

Yaşamaya başlayıp,

Oluruz her birimiz,

Birer yağmur ormanı.

Bir ağaca tutunan sarmaşık gibi,

Birşeylere tutunup,

Uzanmaya çalışırız sonsuzluğa.

Bir tırtıl gibi,

Doğumla örmeye başlarız kozamızı.

Yaşamımızdaki emekle.

Edindiğimiz bilgi,tecrübe ve

Ölümle kozamızdan çıkarız.

Muhteşem görünüşümüzle.

Son gibi görünen yeni bir başlangıca.', 'Doğum ve ölüm; iki kapı. Sonsuzluktan gelen,sonsuzluğa giden. Filizlenen bir tohum gibi, Yaşamaya başlayıp, Oluruz her birimiz, Birer yağmur...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iki-kapi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnadına sevmek', 'i-nadina-sevmek-durdane-demirkoparan-hib06', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgi tohumları  atıyorum yüreğime

Yükselttiğim duvarları yıkıyorum 

Tek tek

Sevmeye çalışıyorum yeniden

Sevgiye küstüren yüreğe inat

Seviyorum 

Bu dünyada sevgi var

Aşk var

Kalplerde merhamet var

Gönüller  birleşmeye

Sevdalar yaşanmaya devam ediyor

Senin

Gönül  gözün kapanmış

İçin  kararmış

Sevgiye inancımı kaybettirmiş

Ve küstürmüşsün  diye beni hayata

Vazgeçmeyeceğim

Göreceksin  yeniden sevecek

Yeniden mutlu olacak

Yeniden mutlu edeceğim

Sevgimi hak edenleri seveceğim

Sen

Bir yerlerde

Kaybolmuşsun karanlığında

Ve riyakar yüzünün ardında

Mutluluklar sana

Ben mutluyum

Sensiz aydınlanan  dünyamda…', 'Sevgi tohumları  atıyorum yüreğime Yükselttiğim duvarları yıkıyorum  Tek tek Sevmeye çalışıyorum yeniden Sevgiye küstüren yüreğe inat Seviyo...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/inadina-sevmek-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılmalıyız', 'ayrilmaliyiz-durdane-demirkoparan-hpr4s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk

İçinde her şeyi saklarmış

Sevdayı, acıyı, ayrılığı

Kimileri severmiş

Yaşarmış sevdasını  sonuna dek

Kimileri acıtırmış 

Sevdiğinin yüreğini

Kimilerine

Sadece ayrılık

Bizde onlardanız sevdiğim

Ayrılık yakışmış bize

Yada

Yakıştırılmış tarafından

Ayrılmalıymış yüreklerimiz

Ayrılmalıymış ellerimiz

Dillerimize  yakışmamış  sevda

Gözlerimiz başkasını görmeliymiş

Unutmak zorundaymışız

Öyle emretmişsin

Sen bir su damlası

Ben bir  sel gibi severken

Ayrılmalıyız

Tek taraflı gitmez aşk

Uğraşsam da

Savaşsam da boşunaymış

Sevdiğim  diye diye 

Çırpınan yüreğimi 

Duymadıktan sonra

Hoşça kal sevdiğim

Hoşça kal...

Ben kıyamadım

Konduramadım

Sen 

Ayrılığı yakıştırdın

Yolun açık 

Bahtın aydınlık olsun

Bazen sevmek

Bırakıp

Ardına bile bakmadan

Gitmektir

Seven üzmez sevdiğim

Kıyarmıyım sana

Git dedikten sonra

Gitmezmiyim

Hoşça kal sevdiğim…', 'Aşk İçinde her şeyi saklarmış Sevdayı, acıyı, ayrılığı Kimileri severmiş Yaşarmış sevdasını  sonuna dek Kimileri acıtırmış  Sevdiğinin yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ayrilmaliyiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canlarıma', 'canlarima-durdane-demirkoparan-cj1wl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sevda masalı yaşanıyor 

Bir yerlerde

Belki çok yakınımda

Birleştiriyorlar kalplerini

Uzaklık koparmıyor

Gönüllerini

Elleri birleşmese de

Gözleri görmese de

Yaşatıyorlar aşklarını

Onlar benim canlarım

Canım birdi

İki oldu

Gördüm yüreklerinin büyüklüğünü

İnsanlar dip dibe bir sevdayı bile

Yürütemezken

Onlar yolları uzaklık saymıyor

Asıl sevda bu değilmidir

Sevgine, sevdiğine

Sahip çıkabiliyorsan

Kendinden çok

Onu düşünüyorsan

Sesini duymadan yatamıyorsan

Aradaki dağlar denizler nedir

Yalan bakan gözleri görünce

İnanması güç olur

Uzaklık aşkı yaşatırmı derdim

İnanmazdım önceleri

Ama gördüm ki

Uzaktan bile olsa

Bir yudum mutluluk 

Yaşatmak için birbirlerine

Canlarını verecekler

Tamam dedim

Gerçek bir sevda yaşanıyor

Aradaki dağlara denizlere karşı

Ve yalan bakan gözlerin inadına

Daha çok

Daha çok seviyorlar

Mutluluğunuz sonsuza ulaşsın canlarım

Gönülleriniz ayrılmasın

Canlarıma ithafen', 'Bir sevda masalı yaşanıyor  Bir yerlerde Belki çok yakınımda Birleştiriyorlar kalplerini Uzaklık koparmıyor Gönüllerini Elleri birleşmese de...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/canlarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Olmalı', 'boyle-olmali-ramazan-ates-vf17u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben, elini ellerimde isterim,

Gözlerini, gözlerimde isterim.

Uzaktan uzaga olmuyor öyle,

Ben ki seni, canlı sevmek isterim.

Çıra gibi hasretinle yanarken,

Geldin diye hayaline dalarken,

Gözleriyin ta dibine girerken,

Ben ki seni, canlı sevmek isterim.

Tenim senin tenin ile buluşsun,

Yönüm senin yönün ile buluşsun.

Ben susayım, arzularım konuşsun,

Ben ki seni, canlı sevmek isterim.

Ellerimde sıcak elin olursa,

Gözlerimse ta hedefi bulursa,

Nefes almaz, kalbim bile durursa,

Ben ki seni, işte öyle severim,

Ben ki seni, canlı sevmek isterim.

Ramazan Ateş/Enschede-24.1.2006', 'Ben, elini ellerimde isterim, Gözlerini, gözlerimde isterim. Uzaktan uzaga olmuyor öyle, Ben ki seni, canlı sevmek isterim. Çıra gibi hasret...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/boyle-olmali-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Gurbet', 'bana-gurbet-necati-keceli-8tazc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Diyar diyar gurbet elde

      Gezdim durdum her bir yerde

      Nasip olur bilmem ner de

      Bana gurbet yazmış TANRIM

      Felek bana kurmuş tuzak

      Eşim dostum herkes uzak

      Yaşlar akar gözler ıslak

      Bana gurbet yazmış TANRIM

      Gurbet çöker sol yanıma 

      Dertler verdi her anıma

      Dügün bayram dert canıma

      Bana gurbet yazmış TANRIM

      Acı, acı eser poyraz

      İçinde aşk sevgi olmaz

      Gönül bu hasrete doymaz

      Bana gurbet yazmış TANRIM

      Yaban eller şu kaderim

      Yollar uzun ben giderim

      Gurbet bitse ne ederim

      Bana gurbet yazmış TANRIM

      Gurbet deyim otuz yıldır

      Çözemedim bu ne haldir

      Gideceğim yeri bildir

      Bana gurbet yazmış TANRIM

      Necati KEÇELİ

      ADANA 24.01.2006', 'Diyar diyar gurbet elde       Gezdim durdum her bir yerde       Nasip olur bilmem ner de       Bana gurbet yazmış TANRIM       Felek bana ku...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bana-gurbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tik Tak', 'tik-tak-reyhan-tataroglu-gc9ie', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçük bir hile ile bozuldu  büyük bir akid 

                      İşte o an kıyamete biçildi vakit

                      Takıldı her kalbe birer birer saat

                      Tik taklarla geçti bol bol verilen vaad

                      Kimi ayarını bozdu kimi dakika şaşmadı

                      Biri zamanı aştı diğeri formülü aşmadı

                      Her saatte bir pil, hepsinin ömrü bellidir

                      Biri tik der durur diğeri yüzellidir

                      Zamanın hiçbir zaman olmaz asla şarjı

                      Sakın çürütme pilini boşa olmasın deşarjı', 'Küçük bir hile ile bozuldu  büyük bir akid                        İşte o an kıyamete biçildi vakit                       Takıldı her kalbe b...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tik-tak-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ninni.', 'ninni-gulnare-leman-exxo5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin yarısı duydum o sesi

Bir bebek durmadan hep ağlıyordu

Merakla bekledim,duvardan sesi

Anne yavrusunu duymuyor muydu? 

Bebek birden bire sesini kesti..

Sevindim! annesini buldu yavrucak

Duvar arkasından sesler gelirdi...

Şimdi anne kucağına sığınan bebek

Ninni  dinliyerek uyuyacaktı...

Ninni yüreğime hakim kesildi

İşitmek isterdim o güzel sesi...

Hayret  yine hayret dinlediğim ses

Kadın sesi değil, erkek sesiydi

Baba yavrusuna  ninni söylüyordu:

“ Ah bebeğim ah...

Hayat neden acımasız..,

Hiç geçmiyor sorularsız..

Ağlama sen ağlama..

Eğer bilsem yardım etsem,

Güzel kızım, bahtsız kuzum..

Ah bebeğim ah....

Göz yaşının sebebini bir bilebilsem

Daha hayatın sorularını çözmeden

Neler gördün sen neler...

Hayallerim derbeder..

Annen seni göremeden..

Bir sesini duyamadan..

Terk eyledi bizleri...

Öldü yazık, perişan.

Ah bebeğim ah... 

Ağlayıpta yüreğimi dağlama.

Kara kışlar geçecek..

Güzel günler gelecek

Ağlama sen bebeğim ağlama...

Bir tek sensin herşeyim.”

O... ninnisini söylüyordu..

Duvarın arkasından 

Ben onu dinliyordum.

Ilk defa dinlediğim,

Içimde inlediğim..

Uyuya bilmediğim

Ilk ninniydi bu ninni.', 'Gecenin yarısı duydum o sesi Bir bebek durmadan hep ağlıyordu Merakla bekledim,duvardan sesi Anne yavrusunu duymuyor muydu?  Bebek birden bi...', ARRAY['Türk Edebiyatı','Şiir','Gulnare Leman']::text[], 8.5, '{"poet":"Gulnare Leman","poet_slug":"gulnare-leman","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/ninni-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yad Eller', 'yad-eller-seyfet-bozcali-2kxb1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kızı  anasından kopardı aldı,

Yuvalara hüzün,gözyaşı saldı,

Bir taraf sevindi öbürü güldü,

Destanlara konu oldu yad eller...

Aylar,yıllar,yollar  koydu araya,

Boynu bükük bakar oldum silaya,

Hasret koydun beni ana,babaya,

Yaşantımız zindan oldu yadeller...', 'Kızı  anasından kopardı aldı, Yuvalara hüzün,gözyaşı saldı, Bir taraf sevindi öbürü güldü, Destanlara konu oldu yad eller... Aylar,yıllar,yo...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yad-eller-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli deli küpeli...', 'deli-deli-kupeli-reyhan-tataroglu-ean9a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yürürken

                             adımlarım

                             yürüdüğüm 

                             yere kadar

                            düşünürüm

                            adım..

                            adım...

                            çıkar...', 'yürürken                              adımlarım                              yürüdüğüm                               yere kadar             ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/deli-deli-kupeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim Hacı Bektaşa', 'giderim-haci-bektasa-yusuf-ter-ul0ai', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kamil olan şal büründü

Yürekleri kalktı şaha

Erenlerde güle döndü

Giderim Hacı Bektaşa

Kırklar kapısına vardık

Gönülleri güle bandık

Burada  eşikte kaldık

Giderim Hacı Bektaşa

Göz çağlasın gönül gülüp

On iki deryaya dalıp

Her birinden bir el alıp

Giderim Hacı Bektaşa

Der Yusuf yurdun beşiği

Kültür şehri Hacı Bektaş

Yedi karanfil dervişi 

Giderim Hacı Bektaşa

Yusuf Ter 08.01.2006

Saat 21:41 İsviçre', 'Kamil olan şal büründü Yürekleri kalktı şaha Erenlerde güle döndü Giderim Hacı Bektaşa Kırklar kapısına vardık Gönülleri güle bandık Burada ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/giderim-haci-bektasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kişiliksiz...', 'kisiliksiz-reyhan-tataroglu-uxwha', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kendimi değildi

                        başkasımı değildi

                        bilemedi? ! ...

                        bir onun

                        bir bunun önünde

                        eğildi', 'kendimi değildi                         başkasımı değildi                         bilemedi? ! ...                         bir onun          ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kisiliksiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kullanma Klavuzu', 'kullanma-klavuzu-emre-ozoran-ne07i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kullanma klavuzu paketten çıkmadı hayatın

ya da elinize geçen klavuz başka bir modelin

size kimse sormamış fişinizi prize takarken

kalbinizi kıranlar izin istememiş

tamirci?', 'kullanma klavuzu paketten çıkmadı hayatın ya da elinize geçen klavuz başka bir modelin size kimse sormamış fişinizi prize takarken kalbinizi...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kullanma-klavuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırıldım', 'kirildim-reyhan-tataroglu-1fcfq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'umutlarım ışık

                       umutsuzluklarım mercek

                       hangi ayna zahir

                       hangi ayna gerçek', 'umutlarım ışık                        umutsuzluklarım mercek                        hangi ayna zahir                        hangi ayna gerçe...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kirildim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirim', 'bilirim-osman-nuri-ozpekel-gbv5o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göremem bir daha asla o güzel çehre gibi

Olamaz böyle güzel gözleri hiç bir kadının

Doyamam bakmaya baksam ecelimdir bilirim

Severim sevmeyi bilmez ne yamandır güzelim

(Feilâtün (Fâilâtün)  Feilâtün Feilâtün Feilün (Fâ’lün)) 

(02.01.1977- İzmir)', 'Göremem bir daha asla o güzel çehre gibi Olamaz böyle güzel gözleri hiç bir kadının Doyamam bakmaya baksam ecelimdir bilirim Severim sevmeyi...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bilirim-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elçi', 'elci-reyhan-tataroglu-lqecf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ruhuma düştü can

                              tenime oldu ayan

