INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Gibi', 'siir-gibi-birsen-ates-bta0u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'razıyım

düşlerde olsan da

şimdi sarılsam sana

sıcacık

uyutsan beni göğsünde

şiir gibi 

kurumuş dudaklarım

dudaklarında hayat bulsa

aşka dair ne varsa

yaşansa yüreğimizde

ruhum ruhunla can bulsa

ister miydin 

sana yürekten bağlı

düşlerindeki beni

25.01.06', 'razıyım düşlerde olsan da şimdi sarılsam sana sıcacık uyutsan beni göğsünde şiir gibi  kurumuş dudaklarım dudaklarında hayat bulsa aşka dair...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/siir-gibi-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüp ardını gitmek', 'donup-ardini-gitmek-hayrettin-turk-uvqkb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dönüp ardını gitmek

En güzel anında nağmenin,

Hele beyninin içinde hapsetmişsen

Gözlerin kapalıyken devam etmekteyse

Tüm büyüsüyle o serenat

Kuytuların saltanatına koşup

Dönüp ardını gitmek…

Belli olmasın diye perişanlığım

Bohem bir rüzgar misali

Esmekteysem eğer

Her nabızda şerbetsem

Ve her tad beni andırıyorsa

Tadımdır bilki sakladığım

Belli olmasın diye perişanlığım…

Sessiz sakin sular misali

Yansımasız karanlıklarda kaybolmuşsam

Bende ummuşumdur herkesler gibi

Ay yansıması olmayı gözlerde

Yaşanmamışları yok sayıp

Alıp akıntıma gitmek birilerini

Sessiz sakin sular misali…

25.01.2005', 'Dönüp ardını gitmek En güzel anında nağmenin, Hele beyninin içinde hapsetmişsen Gözlerin kapalıyken devam etmekteyse Tüm büyüsüyle o serenat...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/donup-ardini-gitmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Aşk', 'ask-turk-oger-koc-5sqig', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'korkulara 

yenik düşmek 

koymadı bu sefer 

bir ürperti gibi çöktü 

sadece üzerime 

sevdalarla büyüdüm 

bizim zamanımızda 

aşk 

uykudaydı 

pamuk ellerden 

uzak 

metalin 

soğukluğunu 

avuçlardı ellerimiz 

severdik 

pir severdik 

ser koyup meydana 

ser verirdik 

sevdalarımıza 

korkulardan uzak 

sessizliğe 

büründüğünde 

kötürümleştiğinde yaşam 

bir gün sen çıktın karşıma 

gözlerinde 

gök gürlemesi 

saçların bozkırlarda 

dolu dizgin giden 

bir tay yelesi 

ve 

yüreğimde 

korkunun 

düşen 

ilk tanesi 

korkmak 

ölümden değil 

dokunamamaktan 

korkmak 

konuşamamaktan 

korkmak 

sesini duyamamaktan 

gül yanağa 

bir buse 

konduramamaktan 

korkmak 

korkuyu tanımaktır 

bence aşk 

yirmi bir yıl 

sonra 

korkulara 

alışamamak 

yanında yatanın 

yüzüne sevgiyle 

baka bilmektir aşk… 

kısacası aşık olup 

aşık kalmaktır aşk 

2006-01-25', 'korkulara  yenik düşmek  koymadı bu sefer  bir ürperti gibi çöktü  sadece üzerime  sevdalarla büyüdüm  bizim zamanımızda  aşk  uykudaydı  pa...', ARRAY['Türk Edebiyatı','Şiir','Türk Öğer Koç']::text[], 8.5, '{"poet":"Türk Öğer Koç","poet_slug":"turk-oger-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/ask-525-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir şey sor ilinç / kan küsmeler...', 'bir-sey-sor-ilinc-kan-kusmeler-zafer-zengin-etnika-vpsq0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.

“ bir şey sor

bilmediğim

çözemediğim

düşündüğüm

düşündüğüm

üstüne düştüğüm

bir şey sor…

bilemeyip de

seni beklettiğim

çocuk marşları

duvar söksün gayriden

kendime geleyim “

“ ilinç bir renk olsan

bakır tadı

sessiz

şu aşkı konuşan

adam yaşasa

ölüm gibi aşkta

kalsa bir başına

ben olmazsam kim anlatır

aşkın ayıplarını çocuklara

bir beni sev

geçmez kıskançlığım sonra “

“ bir şey sor ilinç

yalnızlığın karanlığına

seni özlemek ölüm olsa

ölsem

ilinç kan küsüyorum “

“ mor yapraklar erteliyor geceyi

hüzün büyüyor gecenin içinde

mavi müptela

şimdi kaç içime

kabulsün can 

ölümsün her an

etim kağıt şiirlere

yaz güzün düştüğü yüzüme

sesinin en ince harfleriyle

sustur gözlerimi

kapatayım…”

10 25 2005

.', '. “ bir şey sor bilmediğim çözemediğim düşündüğüm düşündüğüm üstüne düştüğüm bir şey sor… bilemeyip de seni beklettiğim çocuk marşları duvar...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bir-sey-sor-ilinc-kan-kusmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kubilaylar Ölmesin', 'kubilaylar-olmesin-suheyl-turkoglu-979zc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Katledildi Kubilay

Bir manga askerle

Onları ölüme gönderen

Alay komutanı nerde? 

On asker ve Kubilay,

Silahlarında mermi yok.

Onları katlettiren,

Alay komutanı nerede? 

On askerle Kubilay,

Feda edildi gerekçelere,

Onlara acımayan,

Alay komutanı nerede?', 'Katledildi Kubilay Bir manga askerle Onları ölüme gönderen Alay komutanı nerde?  On asker ve Kubilay, Silahlarında mermi yok. Onları katlett...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kubilaylar-olmesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zonê To Şirino', 'zon-to-sirino-ercan-cengiz-bd8od', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dayê, Dayıka mı 

zone to şirino

noxdê to gêrmi 

tore savaci

sebıqêri qı Dayê 

heqa to bıdi,

Dayê, Dayıka mı 

destê tora 

xona

boya tezego ena

zone to dı ro esto

zone dı insani 

xontı şirin beno

Dayê, Dayıqa mı 

no senê zono 

boya tezego

çarneno cicego...

K-34

Xebera Qılmeqı

Cım cımo qı zengınosa, wırniya xo nêwêno

Zon qı be wayir mono, gosono xo werdeno.

Xebera qı nesona, hürindiya xo nêwena

Bena darê dı usk, adıre şüridı qız bena.

.............

Xöyno koti Camêrdo 

Rai ra ne qeno.

Xebêra koti

Camêrdo ser nena

K-32

Rocê Ena

Rocê ena 

senê hala bu

ezi qi mıronı

tıxêqê mı

ezi qi mıronı

xona

mordemini estasa

zedı nê

ji bostê

yaxut

angorê lesa mı

hêrdi qi wênê sa

icara tepa benê

qenê bınê herdê şayi,

to nê mırenay

tıxêqê mı

to nê mırenay

qedırê xo bı zanı,

ez qı ezo

merdenêra qi

nê tersonı

bı zanı qı 

qudretê to rau

xo wira me qı...

tıxêqê mı.

K-25

Dayê Dayê

Dayê Dayê

zonê to tenıqo

qês mavaco

windi benno

wacı Dayê

zonê to çıma

hontı gırano

gıraniya zonira

hêrd jibeno.

Bê bıwênı Dayê

qêlemı damis nıdane

xetı damis nıdane

qıtab xo ser negêno

zono xam bınıdı mono

çikko, adıro

cıko Dayê...

Dayê Dayê

zone to tenıqo 

rocora qi gırano 

zonodı weso 

çıma hontı şirino 

roştina cımona

noğda dı to 

aşirorê bêsa

aşirê ênê pêser

hemgêno 

serbeto, cıko

mordem qı 

mordemo

qupe genno 

mesımo qi

tam qenno.

K-05

Adır

Erxati amê

arara ravêr

adır vazenê

tersê mı 

hêga nıçine

wesnenê.

k.01

Zöyiti

Ni zöyitê ê kami 

qutê ma dımıra,

şimı qoti sa

pêsayu peruc

pıroşinê lıngonê mara,

tainonê binora qi eşiyo pê

ji ez niyo,

nai rınd bızanê.

K-35

Bêqes

-Bêqes

amo zon

qêşi qêno-

Gose sıma

mı sero

ez qı ezo

ezo bêqeso

beqêşina mı 

alem zano

hometi 

sıma qi

bızanê

tometı niya.

Ez qı ezo 

ezo beqêso

reina qı 

ennı sa

na dina

zengelo

belona 

qotidı

benê sa

bıbê

qotidı 

estê sa

tedini 

ama

tedini

ji bı ji 

top qonı

mezelora

düri dı

wêsnonı.

K-03', 'Dayê, Dayıka mı  zone to şirino noxdê to gêrmi  tore savaci sebıqêri qı Dayê  heqa to bıdi, Dayê, Dayıka mı  destê tora  xona boya tezego en...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":143,"source_url":"https://www.antoloji.com/zone-to-sirino-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kararlı mısın?', 'kararli-misin-nesrin-gocmen-djolj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tükenen yaşlara feryat ederim 

Sevdanı yıkmaya kararlı mısın? 

Bağışlar, yakarır, ''hayat bu! '' derim 

Sözünden caymaya kararlı mısın? 

. 

Buza yazılana inanır oldun 

Mavi hasretiyle karlarla doldun 

El dediklerinde şimdi ne buldun 

Beni yok saymaya kararlı mısın? 

. 

Savrulan yalanla kalbim tekliyor 

Kasırga rüzgâra hüzün ekliyor 

Umudum, uğurum dönüş bekliyor 

Şeytana uymaya kararlı mısın? 

. 

Çürük bir tekneyle aştık da nehri 

Bir damla su yıktı sevdadan şehri 

Çok mu vazgeçilmez inadın zehri 

İçerek doymaya kararlı mısın? 

. 

En zorlu yollarda gamsızca koştuk 

Huzura varınca tasaya düştük 

Yaşam şarabını içen sarhoştuk 

İnatla aymaya kararlı mısın? 

. 

Bu dünya kaldırmaz gururu, kini 

Gölgelere sinme, tanı kendini 

Sırtındaki sevda giysilerini 

Çıkarıp koymaya kararlı mısın? 

25 Ocak 2006', 'Tükenen yaşlara feryat ederim  Sevdanı yıkmaya kararlı mısın?  Bağışlar, yakarır, ''hayat bu! '' derim  Sözünden caymaya kararlı mısın?  .  Bu...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kararli-misin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dermansın', 'dermansin-bayram-cerit-0udwn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben seni karanlık satırlara sakladım

Öznelere yükledim seni 

Gözpınarlarına sakladım yüreğimi.

Yeşermeyen çamlar içinde gözlerin

Kuramadığım hayaller içindesin şimdi.

Meyler neylesin sarhoş bedenimi.

Yokluğuna var mı derman

Ferman olmuş her sözün	

Kadir Mevlam seni vermiş

Derdi niye sorarsın ki..

BAYRAM CERİT

25.01.2006

YOZGAT', 'Ben seni karanlık satırlara sakladım Öznelere yükledim seni  Gözpınarlarına sakladım yüreğimi. Yeşermeyen çamlar içinde gözlerin Kuramadığım...', ARRAY['Türk Edebiyatı','Şiir','Bayram Cerit']::text[], 8.5, '{"poet":"Bayram Cerit","poet_slug":"bayram-cerit","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dermansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir fincan kahve', 'bir-fincan-kahve-ulya-erkman-u19u9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakiyordum penceremden

Yokuslu bir sokaga

Geciyordu onumden insanlar aceleci

Adimlarla

Bakiyordum erkek kadin coluk cocuk

Isten donen insanlara

Kimisi carsi pazardan ellerinde

Torbalarla

Ihtiyar bir dedeydi yokusta 

Beliren

Tutuyordu torununu siki siki 

Ellerinden

Yuruyordu yasli adimlarla hic

Dinlenmeden

Durdu nihayet onumde yorulmustu

Yurumekten

Oturdu karsida alcak bir 

Bahce duvarina

Cikardi bir paket sigara iyi gelir diye 

Yorgunluguna

Yildirim gibi indim asagiya hemen 

Mutbaga

Koydum birlik cezveyi alelacele

hemen ocaga

Kosturdum fincanla cezveyi  hemen 

Dedeye

''Yorgunluk kahvesi dede'' dedim ''icersin

Sigaranla diye

Bakti yasli gozlerle dikkatlice 

Yuzume

''Senin gibiler kalmis demek'' dedi

Biraz da huzunle

''Acele etme''dedim ''

''Rahatca ic kahveni

Bitince birakirsin duvara

Fincanla cezveyi

Biraktim sonra dedeyle torunu

Girdim iceri

Icimde derin bir huzur

Verebildim diye dedeye

O BIR FINCAN KAHVEYI', 'Bakiyordum penceremden Yokuslu bir sokaga Geciyordu onumden insanlar aceleci Adimlarla Bakiyordum erkek kadin coluk cocuk Isten donen insanl...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bir-fincan-kahve-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyayı taradım dost bulamadım', 'dunyayi-taradim-dost-bulamadim-mikdat-bal-ffkgu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünyayı taradım dost bulamadım

Ne işe yaradım zevk alamadım

Gönlümde aradım ben olamadım

Kusur bende imiş, elde değilmiş

Dostluk gönüldeymiş dilde değilmiş

Kusurum küsürüm dağlardan engin

İnsan iki türlü fakir ya zengin

Kim demiş ki dostun olmalı dengin

Değer insanlıkta malda değilmiş

Dostluk gönüldeymiş dilde değilmiş

Dostu arıyorsan kendinde ara

Herkesle tanıştır bulduktan sonra

Menfaat dostluğu etmez beş para

Dostluk malda, para pulda değilmiş

Dosluk gönüldeymiş dilde değilmiş

Önce sevgi gerek sonra hoşgörü

Sabreden başarır, müşkülü zoru

Dostlukta aranan şartlar bir sürü

Merhabanın sırrı elde değilmiş

Dosluk gönüldeymiş dilde değilmiş', 'Dünyayı taradım dost bulamadım Ne işe yaradım zevk alamadım Gönlümde aradım ben olamadım Kusur bende imiş, elde değilmiş Dostluk gönüldeymiş...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dunyayi-taradim-dost-bulamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rengarenk..', 'rengarenk-pinar-koc-gsadv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kırmızı olabilir miyiz sence biz? 

İhtiras gibi al al,

Alev rengi yanıp kavrulan…

Sevdalı kalpleri tutuşturabilir miyiz

Kavurabilir miyiz kül misali…

Mavi olabilir miyiz sence biz? 

Özlem mavisi,hasret mavisi,gök mavisi….

Engin maviler olabilir miyiz dipsiz sularda..

Martılar uçar mı göğsümüzün gönlünde,

Güneşi doğurup batırabilir miyiz kalbimizde,

Nefes aldırabilir miyiz insanlara derin derin……

Beyaz olabilir miyiz sence? 

Bembeyaz…

Yıldızlar kadar parlak,

Bulutlar kadar temiz….

Kar taneleri kadar saf olabilir miyiz,,

Veya damlalar kadar sessiz….

Aşk kadar beyaz olabilir miyiz,

Ekmek kadar semiz….

Beyaz nine olabilir miyiz

Bir uzun beyaz bulut Gelibolu dan

Hırçın,sabırlı ve sessiz…….

Pembe olabilir miyiz sence? 

Biraz mutluluk,biraz huzur…

Bazen güzel bir gül,

Bazen kokulu bir bebek teni….

Sarı olabilir miyiz sence? 

Hep ayrılıklar,hep huzursuz…….

Bazen soluk,bazen durgun…

Bazen ağlayan,bazen suskun…

Hayır

Sarı olmamalıyız bence biz…….

                                                                    28.03.2002', 'Kırmızı olabilir miyiz sence biz?  İhtiras gibi al al, Alev rengi yanıp kavrulan… Sevdalı kalpleri tutuşturabilir miyiz Kavurabilir miyiz kü...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/rengarenk-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Dostum', 'gonul-dostum-halide-selcan-karagul-omhx5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül Dostum



Karşıma ilk çıkışında

Yüzüme ilk bakışında

Gönlüme ilk akışında

Sevdim seni gönül dostum..



Gülümsersin hiç durmadan

Gönül perini bulmadan

Sana gönül verdim çoktan

Sevdim seni gönül dostum..



Ben sana sen bana

Bilmeden bağlandık aşka

Sana sevgim bambaşka

Sevdim seni gönül dostum..



16.12.1983', 'Gönül Dostum Karşıma ilk çıkışında Yüzüme ilk bakışında Gönlüme ilk akışında Sevdim seni gönül dostum.. Gülümsersin hiç durmadan Gönül perin...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gonul-dostum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Sen! ...', 'i-cimdeki-sen-halide-selcan-karagul-iuf7q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimdeki Sen! ...



İçimdeki senle

Çarpar  yüreğim,

Öyle muhteşem ki

Gönlümde açar

Sevdamın çiçekleri.

Kelebekler misali

Kanatlanır Ruhum

Mutluluğa koşarım

Seni gördüğüm zaman..

O güzel bakışlarınla

Sıcacık tatlı gülüşünle

Yüreğim öyle dolu ki seninle,

Yüreğimde ki  seni

Unutamıyorum

Öylesine işlemişsin ki

Benliğime

Söküp atamıyorum,

Yeniden canlanıyor

Geçmişteki anılar,

Seni gördüğüm zaman..



14.05.2002', 'İçimdeki Sen! ... İçimdeki senle Çarpar  yüreğim, Öyle muhteşem ki Gönlümde açar Sevdamın çiçekleri. Kelebekler misali Kanatlanır Ruhum Mutl...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/icimdeki-sen-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne olursa', 'ne-olursa-burhan-kucuk-fshng', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne olursa

İklimler geçer birer birer

Arasından ağaran saçların

Solar tek tek yaprakları

Ömür ağacının

Bitmez denen takvimler

Koparılır yaprak yaprak

Ard arda serilir seneler

Boş gözlerle bakılarak

Ölüm gibi çöker gece

Şaklabanlık yaparak

Dönüşür gün hasrete

Öylesine,sarsak sarsak

Ki uykuda olur

Tüm ziyanlıklar

Burhan KÜÇÜK

Kdz.Ereğli

25.01.2006', 'Ne olursa İklimler geçer birer birer Arasından ağaran saçların Solar tek tek yaprakları Ömür ağacının Bitmez denen takvimler Koparılır yapra...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ne-olursa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zemheri…', 'zemheri-zulfikar-yapar-kaleli-p00v8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Karakışta Zemheri’yi

Aramaya çıktım bugün.

İrdeleme sen geriyi

Harşit boyu aktım bugün.

Sana gelmekti muradım

Gönlün yolu iki adım

Belki bir işe yaradım

Diye yere baktım bugün.

Derdim vardı dizi dizi

Yıprattım yüzlerde yüzü

Gözüm aramaz mı sizi

Yüreğimi yaktım bugün.

Sitemlerin başım üste

Yaş indirdin yaşım üste

Yola düştüm işim üste

Aklı yola soktum bugün.

Arka çıktım, arkam bildim

Seninle ağladım, güldüm

Artık sitem etme öldüm

Ki, kafayı taktım bugün.

Karlı dağlar aşıyorum! 

İnan, bana şaşıyorum…

Yaşamaya yaşıyorum

Ama, benden bıktım bugün.', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Karakışta Zemheri’yi Aramaya çıktım bugün. İrdeleme sen geriyi Harşit boyu aktım bugün. S...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zemheri-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhbar Ediyorum..! ! -1-', 'i-hbar-ediyorum-1-h-hikmet-esen-u3bvj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sabaha karşı,

Kurşuna dizdiler, 

Karanlıkları..! 

Şafağa gömdüler sonra,

Kimse farkına varmadan...

Güneş''in ilk ışıklarıyla,

Bulutlardan,

Damla damla, 

Sızan kan; 

İz bıraksa da ardında,

İnsanlar; 

Ne İnfazın farkında,

Ne de, yaşam,

Kurşunlanırken,

Karanlıklar..

Kendi halinde

Dönüp duruyorken 

Dünya; 

Kimin umurunda..! .

24/01/2006', 'Sabaha karşı, Kurşuna dizdiler,  Karanlıkları..!  Şafağa gömdüler sonra, Kimse farkına varmadan... Güneş''in ilk ışıklarıyla, Bulutlardan, Da...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ihbar-ediyorum-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birlik ve Beraberlik', 'birlik-ve-beraberlik-mehmet-serdar-ates-28z41', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel artık sesini, duyalım kardeşim,

Bir nefes bir soluk,ver artık kardeşim,

Uzat elini gel, kalbini bana ver,

Birlikte zor yolu aşalım kardeşim.

Kederlenme sakın, sırtını bana ver,

Derde düşme sakın, tasayı bırak gel,

Dost elime gel, canıma can ver,

Mutlu olalım dost, kederi bırak gel.

Bir ekmeği sen ben, bölüşelim dostum,

Aynı yolda senle, koşalım beraber,

Vatana bayrağa, hizmette coşalım,

Tek yumruk tek yürek, olalım can dostum.

23.01.2006', 'Gel artık sesini, duyalım kardeşim, Bir nefes bir soluk,ver artık kardeşim, Uzat elini gel, kalbini bana ver, Birlikte zor yolu aşalım karde...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Serdar Ateş']::text[], 8.5, '{"poet":"Mehmet Serdar Ateş","poet_slug":"mehmet-serdar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/birlik-ve-beraberlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Bizim', 'bayram-bizim-mehmet-serdar-ates-ulm1v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bayram geldi hoş geldi,

Her eve neşe geldi,

Tatil yerleri doldu taştı,

Bayram ruhu nerede kaldı.

Hep yorgunuz yorgunuz,

Felekle sorunluyuz,

Eğlenceye susamışız,

Bayramda felekten gün çalmışız

Ay kızım vay kızım,

Raks eder can kızım,

Eğlenmeli tabiî ki,

Bayramda da yoksulla dargınız.

Para benim pul benim,

Can benim canan benim,

İster yerim, ister içerim,

Bayram değil tatildeyim.

Bayram nedir bilemem,

Kulağımı veremem,

Hayat kısa, zora gelemem,

Bayram sizin, çengi benim.

Vur davula davula,

Giderim Avrupa da tatile,

Beğendiğini koy bavula,

Bayram seyranımdır benim.

Arada sırada Allah demeli,

Ben de müslimanım demeli,

Hayır hasenat denince,

Allah versin demeli. 

Bu zamanda bu da olur mu demeli,

Bana göre diyerek, yeni din icat etmeli,

Bir iki hayır yapıp çaka satmalı,

Kim kimi aldattı, kendine bir sormalı.

Bayram bizim, seyran sizin

Allah verdi serveti, iyi yiyin,

Görmeyin, duymayın, Avrupa’dan giyin 

Hesabı Münker ve Nekir’e verin.

09.01.2006 22.40', 'Bayram geldi hoş geldi, Her eve neşe geldi, Tatil yerleri doldu taştı, Bayram ruhu nerede kaldı. Hep yorgunuz yorgunuz, Felekle sorunluyuz, ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Serdar Ateş']::text[], 8.5, '{"poet":"Mehmet Serdar Ateş","poet_slug":"mehmet-serdar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bayram-bizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Geldi Çocuklar', 'bayram-geldi-cocuklar-mehmet-serdar-ates-qxyjp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neşe ile dolun, coşun çocuklar,

Büyüklerin eli, öpün çocuklar,

Hatır gönül alın, güzel çocuklar, 

Haydi bayram geldi, koşun çocuklar.

Ne güzeldir bayram, namaza durun,

Namazın sonunda tekbir getirin,

Harçlıkları alın sevinci tadın,

Haydi bayram geldi, koşun çocuklar.

Yaşlıları sevin, bol dua alın,

Hakkın rızasıyla, huzura varın, 

Bayramda şen olun, bahtiyar kalın,

Haydi bayram geldi, koşun çocuklar.

Gözünüzü açın, sevabı kapın,

Bayramı yaşayın, mükafatı alın,

Allah’ı zikredin, rahmete varın,

Haydi bayram geldi, koşun çocuklar.

08.01.2006 23.40', 'Neşe ile dolun, coşun çocuklar, Büyüklerin eli, öpün çocuklar, Hatır gönül alın, güzel çocuklar,  Haydi bayram geldi, koşun çocuklar. Ne güz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Serdar Ateş']::text[], 8.5, '{"poet":"Mehmet Serdar Ateş","poet_slug":"mehmet-serdar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bayram-geldi-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kokonalar-"siz hiç ay aşığında ağladınız mı" Kitabından', 'kokonalar-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-i4rgc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uğultusu kıpkızıl 

Sibirya soğukları 

Çırılçıplak 

Ve kefene sararlar 

Pervazsız maskaralar 

Buz bedeni yüzü kar 

Çek elini sahtekâr

Kaba vahşi binalar 

Cirit atar finolar 

Oynaşır sarhoş devler

Büyük ruhsuz odalar 

Haşmetli kokonalar 

Mobilya ve modalar', 'Uğultusu kıpkızıl  Sibirya soğukları  Çırılçıplak  Ve kefene sararlar  Pervazsız maskaralar  Buz bedeni yüzü kar  Çek elini sahtekâr Kaba va...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-balikta-sen-kurtar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram', 'bayram-mehmet-serdar-ates-zcegg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senede iki defa gelir bayram,

Yoksula, fakire yakınlıktır makam,

Bayramda muhtaca el uzat paşam,

Bayram, çalgılı düğün değil ağam.

Otuz gün oruç tuttun aldın sevabı,

Yine gördün Ramazan Bayramı,

Fitreyi, zekatı ver, al mükafatı,

Bayram, tatil için değil ağam.

Sevap defterin dolar, taşar,

Fakiri, fukarayı sevindirir yaşar,

Öksüzü,yetimi sever okşar,

Bayram, merhametsizlik değil ağam.

Kurbanı aldın, akıttın kanı,

Rabbim sever yardım yapanı,

Malını mülkünü hayırda harcayanı,

Bayram, cimrilik değil ağam.

Büyüklerin ellinden öper,

Gönül alır, çocukları sever,

Akraba ile sılayı rahim yapar,

Bayram, ayrılık değil ağam.

Bayram yakınlaşma fırsatı,

Küslerin barışma zamanı,

İçten ve samimi dostluk mekanı,

Bayram, dargınlık değil ağam.

Bayramda melekler dünyaya iner,

Rabbini anan kulu sever,

Kanadını fakire, fukaraya serer,

Bayram, anlamsız değil ağam.

Bayramda güzel giyinir insan,

Bayram namazına duran, 

Deftere sevabı, içine huzuru alır o an,

Bayram, miskinlik değil ağam.

Allah verdi bunca malı, mülkü,

Alacak elbet gelince günü,

Hakkını ver, rahat ol hesap günü, 

Bayram, gaflet değil ağam.

07.01.2006 Saat 07.50', 'Senede iki defa gelir bayram, Yoksula, fakire yakınlıktır makam, Bayramda muhtaca el uzat paşam, Bayram, çalgılı düğün değil ağam. Otuz gün ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Serdar Ateş']::text[], 8.5, '{"poet":"Mehmet Serdar Ateş","poet_slug":"mehmet-serdar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bayram-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba 17', 'merhaba-17-tulay-i-cen-viwl8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Merhaba Can.

Canım  merhaba..Seni özledim sana  olan özlemimi ne kadar  anlatmaya çalışsamda anlatamıyorum.

Bu özlemi  yaşamak  lazım..Seni seviyorum, seni  özledim, demek bana yapmacık  gelsede  seni   sevdiğimi  söylemenin  hiç  bir  yolu  yok.Aşkım  acın  içimde  sönmeyen  bir ateş,ateş her gün  biraz daha büyüyor..

Can ne olur  beni  anlamaya  çalışsan  yoruldum artık  yaşamaktan beni yormanın  ötesinde  bıktırdı  beni..İnanki  yaşamak  istemiyorum.

Şuan  istediğim  tek  şey  var ellerini  tutmak sana   sarılmak  terini  teninde  koklamak  seni  hissetmek istiyorum.Seni seviyorum.Seni seviyorum..

Can  sana  ben  merhaba  demeye  devam ediceğim,içim yanmaya devam etsede..Sen bana elveda  demeden çekip gittin bu gönlü acılar içinde  bırakıp  gittin...

Beni yıktın...

Beni enkaz  hale  getirdin.

Olsun....

ben enkaz olsamda

yıkılsamda,,

Seni  seviyorum,

Seni istiyorum...

Kalbimi ve ruhumu,

acılar içinde  bıraktın.

Ağıt yakıyorum,

Karalar  bağlıyorum,

inatla unut deselerde.

Unuturamayacaklar seni...

Sen bile unutturmaya calışsan 

Seni...

İnatla seni bekliyeceğim,

taki toprakla nikah kıyıp sana  kavuşana kadar..

29/11/2000', 'Merhaba Can. Canım  merhaba..Seni özledim sana  olan özlemimi ne kadar  anlatmaya çalışsamda anlatamıyorum. Bu özlemi  yaşamak  lazım..Seni ...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/merhaba-17-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanış ve Yakarış', 'aldanis-ve-yakaris-mehmet-serdar-ates-dqdfc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hazine arayan insan,

Hazineyi bulamazsan,

Doğru yola varamazsan,

Ağla gözlerim sen ağla.

Hazine dediğin ne ki,

İçi dolu ambar mı ki,

Kabirde de geçer mi ki,

Ağla gözlerim sen ağla.

Kırk haramiler misali,

Yetim malı da yemeli,

Hesap da var mı demeli

Ağla gözlerim sen ağla.

Söyle kim gerçek aldanan,

Kendini uyanık sanan,

Aldanıp dünyaya kanan,

Ağla gözlerim sen ağla.

Kalü belada “belâ” de! 

Güzel gözü gör “elâ” de! 

Cehennemi gör “ana” de! 

Ağla gözlerim sen ağla.

Şeytan örmüştür ağını,

Ne çabuk sattın andını,

Cehennem verir hakkını,

Ağla gözlerim sen ağla.

09.01.2006 00.20', 'Hazine arayan insan, Hazineyi bulamazsan, Doğru yola varamazsan, Ağla gözlerim sen ağla. Hazine dediğin ne ki, İçi dolu ambar mı ki, Kabirde...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Serdar Ateş']::text[], 8.5, '{"poet":"Mehmet Serdar Ateş","poet_slug":"mehmet-serdar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aldanis-ve-yakaris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban', 'kurban-mehmet-serdar-ates-8yx86', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haramdır kendi nefsin,

Ey Müslüman kurban kes.

İbrahim peygamber kesmek istedi,

Kurban olarak oğlu İsmail peygamberi,

Tam teslim oldu oğlu İsmail,

“emir olunduğunu yap” buyurdu,

Taşı kesen bıçak kesmedi,

Allah izin vermeyince,

Kesemedi insan etini, 

Kestirmeyene bak.

Bir koç ve tekbir ile indi Cebrail,

“Allâhu ekber, Allâhu ekber”

İbrahim peygamber karşılık verdi; 

“Lâ ilâhe illellâhu vallâhu ekber”,

Oğlu İsmail peygamber de; 

“Allahu ekber ve lillahilhamd” dedi,

Böylece vacip oldu bu tekbir.

Nice sırlar vardır kurban da bilesin,

İsmi azam gizlidir, elde edesin,

Nefsine kefarettir kurban, kesesin,

Sıratı kestiğin kurban ile geçesin,

Allah’a kurban gibi boyun eğesin. 

Görmez mi gözün mucizeyi,

Sen kestikçe çoğalır hayvan, 

Allahın lütfü keremi dolar, taşar,

Bu ibadette hikmeti ilahi var,

Kurban gibi sende Rabbine var.

Rabbim yarattı bu hayvanı,

Rızai ilahi için kes, et için kesme,

Rabbine ancak ibadette takvan ulaşır,

üçe taksim et kubanı, 

birini sen, 

birini eş, dost ve komşun,

diğerini de muhtaçlara dağıt.

Ey Âdemoğlu anla bunu,

Takva ile Rabbine teslim ol.

.......sen onun vücudunda gerçek kurban ol.', 'Haramdır kendi nefsin, Ey Müslüman kurban kes. İbrahim peygamber kesmek istedi, Kurban olarak oğlu İsmail peygamberi, Tam teslim oldu oğlu İ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Serdar Ateş']::text[], 8.5, '{"poet":"Mehmet Serdar Ateş","poet_slug":"mehmet-serdar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kurban-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicret', 'hicret-abdullah-yasar-erdogan-g4xv7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'HİCRET

O, Hz. İbrahim ki, hicretle mücerret,

Faslıların zulmünden korumuş hicret.

Doğru olur plan sistemi demek,

Islah edicilerin yoludur hicret.

Musâ’nın Nil’e gönderilmesi davet,

Musâ’nın Firavundan kaçışı hicret,

İsâ’yı Beyt-i Lahm’dan Kudüs’e davet,

İsâ’nın göğe yükseltilmesi hicret.

Mekke’den Medine’ye etmiş sirayet,

Medine’de devlet sistemidir hicret.

Hak ile batılı ayırmış o davet,

İman edicilerin yoludur hicret.

Hz. Ömer’in uyguladığı adalet,

İslâm Tarihi başı dediği hicret.

İdeal uğrunda fedakârlık, sebat,

Daim musibete karşı sabır hicret.

Kaçış değil, Allah’tan yardım istemek,

Allah’a sığınma ifadesi hicret.

Engellenirse Mü’mine muaşeret,

Kur’ân nazarında bir zaferdir hicret.

Hakça yaşamdır insanoğluna gerçek,

Allah bizimle beraber demek hicret.

Sarmışsa eğer devranı bir zulmet,

Allah’a kaçıp O’na iltica hicret.

Dünyada mal ve mülk kazanmaksa niyet,

Bu sevdaya hiçbir zaman denmez hicret.

Allah ve Resûlü’ne itaat etmek,

Ecelle Allah’a dönüşte bir hicret.

İman üzerindeki tesiri müspet,

Mü’minlerde olmalı Allah’a hicret.

Uyanmışsa nefsani arzu ve istek,

Kurtuluş tevbe ile Allah’a hicret.



Muaşeret: Birlikte hoşça yaşama.

Şair: Abdullah Yaşar Erdoğan', 'HİCRET O, Hz. İbrahim ki, hicretle mücerret, Faslıların zulmünden korumuş hicret. Doğru olur plan sistemi demek, Islah edicilerin yoludur hi...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hicret-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nokta', 'nokta-mehmet-serdar-ates-63znu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her işin bir sonu var; 

Her cümlenin sonuna konur nokta.

Giriş ile başlar anlatım,

Gelişme ile açılır, aydınlanır,

Sonuç ile noktalanır.

Hayatta böyledir,

Bebeklik ile başlar,

Gençlik ile doruğa ulaşır,

Yaşlılık ile olgunlaşır,

Ölüm ile noktalanır.

Ömür ise farklıdır; 

Kalü bela ile yaratılış,

Dünya ile imtihan,

Ölüm ile sonsuza yolculuk,

Mizan ile tespit,

Cennet veya cehennem ile,

Sonsuz bir yaşam başlar.

Nerede nokta? 

Sonsuzluğun olduğu yerde,

Olur mu hiç nokta? 

Rabbim hayatına koymadıysa nokta,

Sonsuza sen koy hayırlı bir nokta.

***Hz. Peygamber (sav)  buyurdular ki: ''Kimin (hayatta söylediği)  en son sözü La ilahe illallah olursa cennete gider''*** (Hadisi Şerif Kütübü Sitte No:6) , Kaynak:http://hadis.ihya.org/ksitte.php? ara=s yüzde F6zt2=hadis', 'Her işin bir sonu var;  Her cümlenin sonuna konur nokta. Giriş ile başlar anlatım, Gelişme ile açılır, aydınlanır, Sonuç ile noktalanır. Hay...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Serdar Ateş']::text[], 8.5, '{"poet":"Mehmet Serdar Ateş","poet_slug":"mehmet-serdar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/nokta-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar', 'kuslar-mehmet-serdar-ates-hsm18', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kar yağınca kapanır yollar,

Heryeri beyaz bir örtü kaplar,

İnsanlar için çalışır dev araçlar,

Yolda kalmasın, kurtarılmalı insanlar.

Ya kuşlar! 

Üşümüş bir kuş,

Çatıma konmuş,

Tüyleri kaparmış, 

Kafasını mantosuyla örtmüş,

Ürkek ürkek bakınıyor,

Susmuş dili şakıyamıyor,

Acıkmış belli söyleyemiyor,

O şimdi mağdur, ifade edemiyor,

Yine lisanı kalp ile Allah`ı zikrediyor.

Zikir ehline yardım en büyük sevap; 

Allah`ı zikredene yardım et, al sevap,

Allah sana veriyor fırsat,

Kadrini kıymetini bil, 

Fırsatı ganimet bil!', 'Kar yağınca kapanır yollar, Heryeri beyaz bir örtü kaplar, İnsanlar için çalışır dev araçlar, Yolda kalmasın, kurtarılmalı insanlar. Ya kuşl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Serdar Ateş']::text[], 8.5, '{"poet":"Mehmet Serdar Ateş","poet_slug":"mehmet-serdar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kuslar-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesaj', 'mesaj-mehmet-serdar-ates-3s1n4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yazın sonu sonbahar; 

Yapraklar dökülür,

Tabiatın yeşil elbisesi sökülür.

Kışa hazırlan mesajı veren,

Yine o sonbahar.

Sebzeler, meyveler kurutulur,

Çeşit çeşit turşular kurulur,

Hâlâ bir inatla çimenler,

Gazellerin altından yeşerir durur.

Yazı uğurlar güller,

Son kez öter bülbüller,

Hazan vakti geldi,

Ağlar gönüller.

Hep yazı uğurlarken,

İçime buruk bir hüzün çöker.

Gülen yüzüm solar,

Ağlamakla içim dolar.

Her yıl süre gelen bu tekrar,

Geçen günlere ve geleceğe bakar,

Hikmeti görmemek akla zarar.

Dile gelir gönlüm,

Fanidir bu dünya diye,

İçimde belirir hüzünlü bir ikrar.

Burada alınacak dersler var,

Ahirete hazırlan mesajı var,

Kışa hazırlandığı gibi insan,

Baki âleme de hazırlanırsa,

Gelir Rabbinden o yüce ihsan.

Anlarsa bunu insan,

Secdeye kapanır o an,

Kalbini Hakka bağladığı zaman,

Bahara ermiştir artık o insan.', 'Yazın sonu sonbahar;  Yapraklar dökülür, Tabiatın yeşil elbisesi sökülür. Kışa hazırlan mesajı veren, Yine o sonbahar. Sebzeler, meyveler ku...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Serdar Ateş']::text[], 8.5, '{"poet":"Mehmet Serdar Ateş","poet_slug":"mehmet-serdar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/mesaj-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-mehmet-serdar-ates-9leeb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün yine duygulandım,

Seni andım; 

Gözlerim nemlendi, bir taşa yaslandım,

Oynuyordu çocuklar, baka kaldım.

Mutlulukları gözlerinden belli,

Kahkahaları yeri göğü deldi,

Ne dert var ne tasa,

Oyna yavrum oyna,

Kimisi sarı saçlı,

Kimisi kara kaşlı,

Sen de oynardın böyle,

Haydi bir daha şarkı söyle,

Dertli dertli bakma bana öyle,

Ahhh! Daldım gittim,

Seni gürdüm sandım, 

Yanılmışım yine aldandım.

Yavrum ne çabuk gittin,

Özlemlerin vardı, nasıl da bittin,

Kara toprak gülümü alıp, bitirdin,

Soldu rengim, kalmadı neşe,

Elim mendilime uzandı,

Mendilim yine ıslandı,

Ağlamaklı gözlerim sel oldu çağladı.

Allah’ım yavrumu sana saldım.

Sen verdin, sen aldın,

Bana sabrı sen saldın,

Habibini örnek aldım. 

İsyan yok, sabretmek var,

Sabrın sonunda selamet var,

Bekle bizi yavrum,

Zamanımız dolunca geleceğiz elbet,

Siparişini aldım, oyuncağını paket yaptım.

31.12.2005', 'Dün yine duygulandım, Seni andım;  Gözlerim nemlendi, bir taşa yaslandım, Oynuyordu çocuklar, baka kaldım. Mutlulukları gözlerinden belli, K...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Serdar Ateş']::text[], 8.5, '{"poet":"Mehmet Serdar Ateş","poet_slug":"mehmet-serdar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ozlem-304-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşver', 'bosver-mehmet-serdar-ates-fim8l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aylardan Şubat. Saat gecenin yarısı,

Kışın en çetin günü, soğuk alabildiğince şiddetli,

Kütahya’da en işlek cadde; Cumhuriyet Caddesi,

İnsanlar bir bir çekilmiş evlerine, sokaklar ıssız, 

Ortalıkta gezinir bir iki sokak köpeği ve bir insan sureti,

O insan, sendeleyerek yürüyor belli ki ayaklarından problemli,

Sokak lambalarının loş ışıkları yansıyor kirli kar ve buzda,

O ise duvarlara tutunarak yürüyor, onu gören kenara çekilip yol veriyor,

Saygıdan değil elbet, virane halinden, saçak bağlamış saçlarından ürperiyorlar, 

O ise kendi dünyasında yol arıyor, yol buluyor, yürüyor, yürüyor,

Yıkık eski bir binaya doğru yöneliyor, telaşlı telaşlı,

Merdiven pislik dolu, bir gayret. çöpler aşağı o yukarı,

Karanlık bir oda, arıyor kuytu bir köşe, yaslanıyor pis bir poşete,

İniltiler ile uzatıyor vücudunu, sızlanıyor belli belirsiz “ahhh! ” diye,

Soğuk bir rüzgar esiyor, bazen küçük horumlar vücudunu yalıyor, geçiyor,

Eli ile bir şeyler arıyor, uzanıyor boş bir şişeye,

İçmek için yelteniyor yok bir damla şarap, kalmamış bitmiş, fırlatıyor duvara,

Biraz sonra soğuk ile beraber bir titreme alıyor vücudunu, 

Derken sıkıştığını anlıyor, kalkacak derman yok bırakıyor altına,

Sıcak bir sıvı akıyor, koku ise hak getire, o zaten alışık bunlara,

Vücuttan çıkan sıcak sıvı, alıp götürüyor son ısıyı, başlıyor titremeye,

Biraz sonra dona çalıyor ortalık, anlıyor, bekliyor, artık beklenen son yakın,

Bir düşünce girdabına kapılıyor, geçmişi geliyor aklına,

Her şeyi varken, ev, araba, dükkân, iyi bir eş ve evlat,

Dost sanıp kandığı insanlar, 

Önce biraz felekten gün çalmalar, şişenin dibine vurmalar,

Hep dostluk üzerine kurulan sofralar, bir kadehten bir şey olmaz derken,

Adım adım ilerleyen zaman, gelsin biralar, gitsin şaraplar,

Onu takip eden birasına oynanan kumar! ! ! 

Sonra parasına, evine, arabasına daha, daha,…

Yok oluyor onca emekler, çabalar, borçlar borçlar,…

İcra memurları kapıda, hani nerde o dostlar? , 

Aldılar parayı nasıl da sıvıştılar,

Terk ediliyor bir bir, kalıyor çaresiz,…

O ise elinde içki şişesi hep BOŞVER diyor kaygısız,…

Saygın bir esnaf, iyi bir aile reisi, toplumda itibarlı bir bey,…

Bırak artık dedikçe aile dostları “BOŞVER” diyor o, yine umudunu kesik bir halde,…

“Battı balık, yan gider” diyor kaygısız. Battı balık yan gitmiyor, battıkça batıyor dibe,...

Mücadele ruhunu kaybetmiş, zoru gördükçe içiyor şarabı uyuşturuyor kendini,...

Her şeyini kaybetmiş, sokaklarda dilenir, çöp bidonlarını karıştırır olmuş bir anda,..

Sefil bir hayat, sonra işte şimdi burada, yıkık bir binada,

Zaman dolmuş Azrail kapıda, Son kez bir hak tanınıyor İman niyetine,…

O yine bildik bir cevap veriyor; “BOŞVER”,

Yalnız boş vermiyor birisi, hiç boş vermemişti ki. Yine boş vermiyor,

Veriyor vesveseyi; O son kez söylüyor “BOŞVER”. Ezeli düşman alıyor imanı, 

Ecel saati oldu tamam. Ve Alıyor Azrail canı, Kasılmalar, kasılmalar,…

Sevinç çığlıkları atıyor, ezeli düşman, melun şeytan,…

“Avenelerim hazırladı ortamı, ben ise aldım imanı, Oh ne güzel! ne güzel! ”…

26.12.2005

''Her gördüğüne dost diye dayanırsan, gerçek dostu bulamadan dostsuz kalırsın.''

Mehmet Serdar ATEŞ 27.12.2005 saat:09.02', 'Aylardan Şubat. Saat gecenin yarısı, Kışın en çetin günü, soğuk alabildiğince şiddetli, Kütahya’da en işlek cadde; Cumhuriyet Caddesi, İnsan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Serdar Ateş']::text[], 8.5, '{"poet":"Mehmet Serdar Ateş","poet_slug":"mehmet-serdar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/bosver-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-005 Aç perdeleri! ..', 'ub-005-ac-perdeleri-mehmet-coban-httpf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duvarların içinde

Kapıların gerisinde

Örtülü perdelerde

İçlerimizde aydınlık

Dışımızda karanlık

İçimizdeki aydınlığın

Dışarıya faydası yok

Dışımızdaki karanlığın

Bizlere zararı çok

Açsak perdelerimizi 

Karanlıklar görse bizi

Aydınlığımıza kavuştursak

Karanlıkları savuştursak

Ama hep kapalı perdelerimiz

Birbirimizden yok haberimiz

Dönüştürsek kendimizi

Bireysel yaşamdan

Toplumsal yaşama

Elveda deriz 

Dışımızdaki karanlığa

Haydi, açalım perdeleri

Paylaşalım içimizdekileri

Aydınlıklarımızdan güç alalım

Karanlığı bir kaşık suda boğalım

25.01.2006-İzmir', 'Duvarların içinde Kapıların gerisinde Örtülü perdelerde İçlerimizde aydınlık Dışımızda karanlık İçimizdeki aydınlığın Dışarıya faydası yok D...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ub-005-ac-perdeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
