INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Sözlere Karnım Tok', 'bos-sozlere-karnim-tok-mehmet-tas-mz2gb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sustu yüreğimdeki kanat çırpan tüm kuşlar

Eylüllerden bir eylül yaşamaktayım şimdi.

Manasını yitirdi baygın baygın bakışlar

Anıları albümde saklamaktayım şimdi. 

Gelişinde geç kaldın ben de artık zaman yok

Avutmaya çalışma boş sözlere karnım tok

Yüreğimde kavrulan ateşe su döküldü

Senelerce bekledim gelme istemem şimdi

Alışmışken hasrete hayalin de silindi

Seni ta yüreğimde saklamaktayım şimdi

Gelişinde geç kaldın ben de artık takat yok

Avutmaya çalışma boş sözlere karnım tok', 'Sustu yüreğimdeki kanat çırpan tüm kuşlar Eylüllerden bir eylül yaşamaktayım şimdi. Manasını yitirdi baygın baygın bakışlar Anıları albümde ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bos-sozlere-karnim-tok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kervanda Düştük Yola', 'bir-kervanda-dustuk-yola-sabahattin-hizmetli-16rgi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ana babanın sevgisi,           

Dünyaya getirdi bizi,            

Dertler buldu dizi dizi,        

Bir kervanda düştük yola.    

İstemeden doğduk geldik,    

Hem ağladık hem de güldük,

Bu hayatı gerçek bildik,       

Bir kervanda düştük yola.     

Kar fırtına esti durdu,            

Bazen yağmur dolu vurdu,    

Diken battı yürek yandı,        

Bir kervanda düştük yola.      

Günlerimiz bitmez sandık,

Hem inandık hem aldandık,

Aşkın ateşine yandık,

Geldi ömrün sonbaharı.

Yalan Dünyaya doymadan,

Henüz muradın almadan,

Sevdiklere kavuşmadan, 

Geldi ömrün sonbaharı.

Bazen sevindik üzüldük,

Bazen hayallerle güldük,

Ömür bitti yere düştük, 

Kervan devam etti yola.



Sabahattin HİZMETLİ tarafından THM formunda bestelenmiştir.

TRT Müzik Dairesi THM Denetleme Kurulrunca yayınlanır kararı verilmiştir.', 'Ana babanın sevgisi,            Dünyaya getirdi bizi,             Dertler buldu dizi dizi,         Bir kervanda düştük yola.     İstemeden d...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Hizmetli']::text[], 8.5, '{"poet":"Sabahattin Hizmetli","poet_slug":"sabahattin-hizmetli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-kervanda-dustuk-yola-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadık', 'anlatamadik-serhan-maral-9dfyf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlatamadık

Bir kar tanesine yakışan 

En güzel gözlerin baktığı boğaz 

Ya karşımdan çekil ya da sarıl rüzgarınla

Ya da bırak burcularını dağılsın etrafa 

Dağılsın ki çekelim içimize bir nefeste

ve o anı anlamadık zannetmesin.

Anladık anlamasına ama 

anlatamadık herhalde…

25.01.2006

Vaniköy', 'Anlatamadık Bir kar tanesine yakışan  En güzel gözlerin baktığı boğaz  Ya karşımdan çekil ya da sarıl rüzgarınla Ya da bırak burcularını dağ...', ARRAY['Türk Edebiyatı','Şiir','Serhan Maral']::text[], 8.5, '{"poet":"Serhan Maral","poet_slug":"serhan-maral","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/anlatamadik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orhan Velİ''ye nazire', 'orhan-veli-ye-nazire-osman-nuri-ozpekel-pcdz2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstanbul’u dinliyorum, yollar kapalı

Önce hafiften köprü tıkanıyor

Sonra yavaş yavaş araçlar çoğalıyor

Uzaklarda çok uzaklarda

Polislerin hiç durmayan düdükleri

İstanbul’u dinliyorum yollar kapalı

İstanbul’u dinliyorum yollar kapalı

Kırmızı ışıkta geçen geçene

Araçlar çekiliyor otoparklara

Bir kadının otomobile takılıyor pardösüsü

İstanbul’u dinliyorum yollar kapalı

İstanbul’u dinliyorum yollar kapalı 

Soğuk soğuk su satanlar

Cıvıl cıvıl kos helvacılar

Dilenci dolu yollar

Küfür sesleri geliyor arabalardan

Güzelim bahar rüzgârında egzoz kokuları

İstanbul’u dinliyorum yollar kapalı

İstanbul’u dinliyorum yollar kapalı

Başımda boş yolların sarhoşluğu

Kırk dokuz model Dodge’ların hoşluğu

Kibar şoförlerin uğultusu içinde

İstanbul’u dinliyorum yollar kapalı

İstanbul’u dinliyorum yollar kapalı

Bir yaya geçiyor kaldırımdan

Küfürler küfürler küfürler

Bir şey düşüyor elinden yere

Bırakmaya mecbur edildiği insanlığı olmalı

İstanbul’u dinliyorum yollar kapalı

İstanbul’u dinliyorum yollar kapalı

İnsanlar çırpınıyor sokaklarında 

Herkes insan mı değil mi bilmiyorum

Sürücülerin sürüşünden anlıyorum

İstanbul’u dinliyorum.

(00.00.0000-Beşiktaş)', 'İstanbul’u dinliyorum, yollar kapalı Önce hafiften köprü tıkanıyor Sonra yavaş yavaş araçlar çoğalıyor Uzaklarda çok uzaklarda Polislerin hi...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/orhan-veli-ye-nazire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
