INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Dediğin Nedir Ki?', 'hayat-dedigin-nedir-ki-alper-yilmaz-z88j0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat dediğin nedir ki? 

Dün,bugün,ve yarın…

Olmak istediğim yerse

İşte o,senin yanın.

Öyle saf,öyle temiz,

Öyle masum,öyle yalın.

İzin ver canım,

Canım olsun canın.', 'Hayat dediğin nedir ki?  Dün,bugün,ve yarın… Olmak istediğim yerse İşte o,senin yanın. Öyle saf,öyle temiz, Öyle masum,öyle yalın. İzin ver ...', ARRAY['Türk Edebiyatı','Şiir','Alper Yılmaz']::text[], 8.5, '{"poet":"Alper Yılmaz","poet_slug":"alper-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayat-dedigin-nedir-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aka Gündüz Kutbay''a', 'aka-gunduz-kutbay-a-osman-nuri-ozpekel-o0tvr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aka Gündüz iki hançer kaşın altında deryâ,

Aka Gündüz iki sâhir elin altında dünya

Görebildim seni ancak iki kere dünyâda, 

Meğer ölmek ne kolaymış  bizi boğdun feryada.

Cebininden damlayan ter düşerdi rind-abaya 

Öyle kim vermezdin kıymet beş paralık dünyaya

Aka Gündüz çok işittim ve de gördüm vuruldum.

Aka Gündüz ilahi bir nağme idin tutuldum

Bu cihandan seni teşrifat ile defn ederken

Dedi gönlüm seyret O’nu  Cemil’le ıyş ederken

Seni ancak görecek ilk eminim ki Mevlâna 

Çökeceksin önüne diz Aka Hiç durma ağla

Güneşi O Tebriz’in  sen bilirsin makalatı

De ki geldim sana ben  ey gönüllerin sultanı

Sana çok yandı yakıldı hem-saz olan üftade.

Mezarında çıktı segâhtan feryâdlar eflake

Seni Zâti ile kıyas ediverdim hele gör.

O şairdi sense neyzen menşeiniz kefş-ger

Bize koydun gittin sanma senindir o kemençe

Yüce Rabbim sana kıymaz aleminde düşmanca

(8+7=15’li Hece) 

(1979 Bursa)', 'Aka Gündüz iki hançer kaşın altında deryâ, Aka Gündüz iki sâhir elin altında dünya Görebildim seni ancak iki kere dünyâda,  Meğer ölmek ne k...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aka-gunduz-kutbay-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soldurdular Güllerimi', 'soldurdular-gullerimi-sabahattin-hizmetli-piano', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soldurdular güllerimi dostlukların bahçesinde,

Ne türkü var ne de şarkı,hasretim bülbül sesine, 

Hasretim bir dost sesine,hasretim canlar sesine.

Çiçek açmaz oldu bağlar,meyve vermiyor ağaçlar,

Gönlüm gizli gizli ağlar,hasretim irfan sesine,

Hasretim bir dost sesine,hasretim canlar sesine.

Bencilliğin ırmakları taştı yok etti bağları,

Ne kök kaldı ne de bir dal,hasretim mertlik sesine,

Hasretim bir dost sesine,hasretim canlar sesine.

İnsanlığın hükmü bitti hatır gönül uçtu gitti,

Sevdalara perde indi,hasretim sevgi sesine,

Hasretim bir dost sesine,hasretim canlar sesine.

Dost akraba arkadaşlık,niçin bu yollardan şaştık,

Menfaatle dolup taştık,hasretim komşu sesine,

Hasretim bir dost sesine,hasretim canlar sesine.

                            





(Sabahattin HİZMETLİ tarafından THM formunda bestelenmiş olup,TRT Müzik Dairesi THM Denetleme Kurulunca yayınlanır kararı verilmiştir.)', 'Soldurdular güllerimi dostlukların bahçesinde, Ne türkü var ne de şarkı,hasretim bülbül sesine,  Hasretim bir dost sesine,hasretim canlar se...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Hizmetli']::text[], 8.5, '{"poet":"Sabahattin Hizmetli","poet_slug":"sabahattin-hizmetli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soldurdular-gullerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hizmetçi', 'hizmetci-reyhan-tataroglu-uyzyz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hizmet

