INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittin ya!', 'sen-gittin-ya-nevin-aydin-hh2ex', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen Gittin ya! 

Gözlerin,ellerin,dudakların

Gitti ya! 

Söyleyerek sevda türkülerini

Yüreğin gitti ya! 

Üşüyorum şimdi,tir tir titriyorum

Bıraktığın hüzünle

Buz kesti gözlerim,ellerim

Seni götüren otobüsün ardından

Yüreğim koptu,karlara karıştı gördüm

Sen gittin ya! 

Sanki ben öldüm.', 'Sen Gittin ya!  Gözlerin,ellerin,dudakların Gitti ya!  Söyleyerek sevda türkülerini Yüreğin gitti ya!  Üşüyorum şimdi,tir tir titriyorum Bır...', ARRAY['Türk Edebiyatı','Şiir','Nevin Aydın']::text[], 8.5, '{"poet":"Nevin Aydın","poet_slug":"nevin-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-gittin-ya-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşkın', 'saskin-fusun-sayan-wc4av', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kemanlar çalıyor mevsim yaz  gibi   

Yüreğim yanıyor suyum naz gibi        

Gözlerim ağlıyor deniz az gibi            

Ciğerim kanıyor yorgunuyum aşkın 

Ben yokluk denizinde dümensiz şaşkın    

Kader silahıyla vurdun kalbimi              

Hasret rüzgarıyla yıktın hanemi            

 Kimseler gelipte  sormaz halimi             

Nefretim çağlıyor, vurgunuyum aşkın     

Ben felek sillesinde,çaresiz şaşkın      

Sabırla büyüyen bir çocuktum ben     

Bir ağaçtım ben de yaşken eğilen              

Yıldızındım gece,sönmek bilmeyen           

Sözlerim çağlıyor,suskunuyum aşkın         

Ben gönül kafesinde sehersiz şaşkın         

Aşkın şarabından içtim bir kere           

Günah çukuruna düştüm bir kere          

Seni  kendime yar seçtim bir kere           

Kaderim bağlıyor,durgunuyum aşkın     

Ben ömür sahnesinde başrolüm şaşkın  

Börtüler böcekler ağlasın bana         

Toprak ana yeşil bağlasın bana             

Aşka aşık gönül çağlasın bana              

Servetim dağlıyor,sorgunuyum aşkın       

Ben ahret kapısında sualsiz şaşkın.', 'Kemanlar çalıyor mevsim yaz  gibi    Yüreğim yanıyor suyum naz gibi         Gözlerim ağlıyor deniz az gibi             Ciğerim kanıyor yorgu...', ARRAY['Türk Edebiyatı','Şiir','Füsun Sayan']::text[], 8.5, '{"poet":"Füsun Sayan","poet_slug":"fusun-sayan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/saskin-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalimdesin Her Zaman', 'hayalimdesin-her-zaman-alper-yilmaz-3on0s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayalimdesin her zaman,

Her zaman zihnimde,

Hep,daima fikrimde...

Görmek için zahirde,

Verirdim ne var ne yok elimde.

Hele ki o yüce sevgin için,

Al her şeyimi,ellerinde.', 'Hayalimdesin her zaman, Her zaman zihnimde, Hep,daima fikrimde... Görmek için zahirde, Verirdim ne var ne yok elimde. Hele ki o yüce sevgin ...', ARRAY['Türk Edebiyatı','Şiir','Alper Yılmaz']::text[], 8.5, '{"poet":"Alper Yılmaz","poet_slug":"alper-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hayalimdesin-her-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yâr kalsın!', 'y-r-kalsin-veysel-alkan-exau3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tüm malımı mülkümü,alın elimden.

Bir canımı bırakın, bir de  yâr kalsın! 

Veririm ben herşeyi,canı gönülden.

Bir canımı bırakın,bir de  yâr kalsın! 

Ne var ne yok toplayıp,silip süpürün.

Zenginlikte gözüm yok,fakir düşürün.

Kuruşu hesaplayıp,alıp götürün.

Bir canımı bırakın,bir de yâr kalsın! 

O benim sebebimdir,o benim ömrüm.

Ben o varsa yaşarım,onsuz ölürüm.

Mutluluğu huzuru, onla görürüm.

Bir canımı bırakın,bir de yâr kalsın! 

Benim için yokluğu, dayanılmazdır.

Onsuz hayat bin çile,katlanılmazdır.

Sebebini sormayın,anlatılmazdır.

Bir canımı bırakın,bir de yâr kalsın!', 'Tüm malımı mülkümü,alın elimden. Bir canımı bırakın, bir de  yâr kalsın!  Veririm ben herşeyi,canı gönülden. Bir canımı bırakın,bir de  yâr ...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yar-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyitler', 'beyitler-alper-yilmaz-9b7d0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Endamı zarif-i servidir yanakları gül-i ruhsar

Ömrü eksiltir o mahv u mest eden hüsn-i nazar

*

Eğer nazar kılmışsa biri timsal-i zarafetine

Rabb''im versin biderman dert nezaretine

Bulunmaz ne arz ne semada emsali şahsiyetine

Rabb''im versin sonsuz nur tabiat u asaletine

*

Güzel olursun işler isen amel-i salih 

Olur sana alem-i cihan sadık-ı valih

*

Ol mah durur karşımda arz-ı endam ederek

Nuru vurur pür suya aks u raks ederek

Misba oldu ab-ı arz senin ışığından 

Ab bile ah ü zar aşkından el aman ederek

*

FİKRİ olmuş perişan aşkın ile virane

Raks-ı aşk eder maşuk ile divane', 'Endamı zarif-i servidir yanakları gül-i ruhsar Ömrü eksiltir o mahv u mest eden hüsn-i nazar * Eğer nazar kılmışsa biri timsal-i zarafetine ...', ARRAY['Türk Edebiyatı','Şiir','Alper Yılmaz']::text[], 8.5, '{"poet":"Alper Yılmaz","poet_slug":"alper-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beyitler-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çatal Değnek Yere Batmaz', 'catal-degnek-yere-batmaz-ramazan-ates-rfr67', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gönülde iki karpuz olur mu? 

Ya benden geç, ya hırsından sen gayri.

Bir koltukda iki karpuz taşınmaz,

Ya benden geç, ya hırsından sen gayri.

Hırs yaparak sevda elde tutulmaz,

Çok gururun sana faydası olmaz.

Çatal değnekse asla yere batmaz,

Ya benden geç, ya hırsından sen gayri.

Böyle sevda, sevda değil işkence,

Acı vermek, hoş mu oluyor sence? 

İnanmıyom sence sevgi bu ise,

Ya benden geç, ya hırsından sen gayri.

Bu son sözüm, sen seçimin yaparsın,

Düşün taşın bir karara varırsın,

Böyle gitmez, bak arada kalırsın,

Ya benden geç, ya hırsından sen gayri.

Ramazan Ateş/Enschede-20.1.2006', 'Bir gönülde iki karpuz olur mu?  Ya benden geç, ya hırsından sen gayri. Bir koltukda iki karpuz taşınmaz, Ya benden geç, ya hırsından sen ga...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/catal-degnek-yere-batmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazîre-i tedvîr', 'naz-re-i-tedv-r-osman-nuri-ozpekel-fql5s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bende dil-baz nükte çoktur kimseler hiç bilmeyübdür

Nükte çoktur bende dilbaz bilmeyübdür kimseler hiç 

Kimseler hiç bilmeyübdür nükte çoktur bende dilbaz

Bilmeyübdür kimseler hiç bende dil-baz nükte çoktur

(Fâilâtün Fâilâtün Fâilâtün Fâilün) 

(1979- Zeynep Kâmil Konağı)', 'Bende dil-baz nükte çoktur kimseler hiç bilmeyübdür Nükte çoktur bende dilbaz bilmeyübdür kimseler hiç  Kimseler hiç bilmeyübdür nükte çoktu...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nazire-i-tedvir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatır mı / anlatılmadan anlamak...', 'anlatir-mi-anlatilmadan-anlamak-zafer-zengin-etnika-oumzc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.

bıçakla soymadan

ısırıp yemek

elmayı

anlatır mı  kırmızıyı

dişteki sızıyı

kırılıp dağlanmayı

dağlarda ağlamayı

güleç kalıp

lokma diye

paylaşmak hayatı

çeliğe yazdığımız adımızı

anlamayı

anlamak

ağlatır mı insanı

anlamak

anlatır mı insanı

18 03 2005

.', '. bıçakla soymadan ısırıp yemek elmayı anlatır mı  kırmızıyı dişteki sızıyı kırılıp dağlanmayı dağlarda ağlamayı güleç kalıp lokma diye payl...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anlatir-mi-anlatilmadan-anlamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fi tarihinden kalma', 'fi-tarihinden-kalma-reyhan-tataroglu-jvk7f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sallanmadan

                                     taşınmaz

