INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bey! gir', 'bey-gir-reyhan-tataroglu-pytjk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'her

                               zaman ki

                               gibi

                               kapıyı

                               çaldı

                               ''''kim o'''' 

                                yorgundu...

                                ''''beyin''''

                                 açtı

                                 kapıyı

                                 ''''bey! gir''''

                                 bey

                                 girdi

                                 gerçekten

                                 kadının 

                                 halini 

                                 görünce

                                 anladım

                                 sonradan

                                 ben', 'her                                zaman ki                                gibi                                kapıyı                       ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bey-gir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlâhî Aşk(Tefekkür)', 'i-l-h-ask-tefekkur-esat-anik-334yh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Israrla methedilen; Secdedeki başlardır.

Mutlak teslim esastır, imân alfâbesinde.

İlahî Af`fa mazhâr, dökülecek yaşlardır; 

Adına gönül denen iklimin kâbesinde.

Acıya taviz olmaz, dîl yâresi değilse.

Öyle ufak rüzgârlar, sarsamaz yüceleri.

Asîl ruhlar rükûya, tefekkürle eğilse; 

Aşıkların bir (Ah!)  ı, titretir geceleri.

Bir suskunluk hap`solur kalplerin köşesine.

Başlar ritme tutulur, dizler yere vurulur.

Mânâ ufuklarında varılır neş`esine; 

Gönüller otağına, ''Ulu Divan'' kurulur.

Sesler uzaklaştıkça, nefesler yükselirler.

Gözler aynı odakta, kulaklarda (Hû!)  sesi.

Hurîler, meleklerin ardı sıra gelirler; 

Yüreklerde sevdânın, o en mâsum bûsesi.

Geceler gündüzlere, gündüzler gecelere

Karışmış bir zamandır, zamanlar ötesinde.

Cümleler parçalanıp, dönüşür hecelere; 

Ayaklar yere değer, bir kudümün sesinde.

Nefis, mahkûmdur şimdi; Mânâ hüküm bulmuştur.

Sırlar bir bir açılıp; Ayıp, günah örtülür.

Tedbir yoktur arada, artık olan olmuştur; 

Aşk âteşi vurunca, ar perdesi yırtılır.

''En Sevgili'' şân ile, kalbe girdiği anda

''Ölmeden evvel ölmek'', âşıklar ilkesidir.

Duru pınar gibidir, zihinler bu zamanda; 

Varılan her mertebe, huzûrun ülkesidir.

Başlar mutmain kalkar, eller arş`a yükselir.

Yüzlerde nûr şavkları, çöker kalplere huşû.

Uzak, çok uzaklardan ılık rüzgârlar gelir; 

Âlemleri mest eden, Aşk-ı İlâhî`dir bu!', 'Israrla methedilen; Secdedeki başlardır. Mutlak teslim esastır, imân alfâbesinde. İlahî Af`fa mazhâr, dökülecek yaşlardır;  Adına gönül dene...', ARRAY['Türk Edebiyatı','Şiir','Esat Anık']::text[], 8.5, '{"poet":"Esat Anık","poet_slug":"esat-anik","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ilahi-ask-tefekkur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sevdalı Bir Bulutum', 'ben-sevdali-bir-bulutum-bahri-yildirim-miyc7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneşe nokta koydu ay ışığı sessizce

Dolunay dokundu geceme gelince akşam

Yıldızlar sinsice doğdular üstüme

Düş yağmurlu gecemde

 Senin yüzünden zerresi kalmadı gözyaşımın

Mahcup oldum el aleme,utandım

Seni sanıp göz ettim,içlerinden birine

Bir tutam sevgi koydu, yanmış avuçlarıma

Sonra geldiği gibi gitti

Rüyalarımı da götürdü giderken

Savurdu dağdan dağa umudumu

Alıp götürdü beni

Ben sana sevdalı

Bir küçücük buluttum oysa

Anlamazdı kimseler 

İçimdeki isyanı

Bir tek umudum sendin

Sen bile anlamadın, sen bile

Birazcıkta bunadır sitemim

Biliyorum korkuyorsun Güneşten

Bir yanın sevdaya tutkun

Bir yanın çekingen

Bir yanın ömürlük olsun diyor sevdam

Hadi  saklan yüreğime

Ömürlük bir sevda arıyorsan', 'Güneşe nokta koydu ay ışığı sessizce Dolunay dokundu geceme gelince akşam Yıldızlar sinsice doğdular üstüme Düş yağmurlu gecemde  Senin yüzü...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-sevdali-bir-bulutum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter ki Sevdan Olsun', 'yeter-ki-sevdan-olsun-volkan-yoruc-911zj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herkesin gitmediği yoldan giderim

İster uçurum ister bataklık olsun

Düşünülmeyen düşlerde gezerim

Yeter ki sevdan yüreğime dolsun

Herkesin sevmediği gibi severim

İster deli bir çağlayan ister hoyrat deniz olsun

Yüzülemeyen denizlerde yüzerim

Yeter ki yüreğim senin sevdanda boğulsun

Herkesin anlatamayağı kelimelerimi severim

İster arzın merkezi ister arşın tepesi olsun

Ben ki bu dünyayı sen diye bilirim

Yeter ki senden aldığım sevdam olsun', 'Herkesin gitmediği yoldan giderim İster uçurum ister bataklık olsun Düşünülmeyen düşlerde gezerim Yeter ki sevdan yüreğime dolsun Herkesin s...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeter-ki-sevdan-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstasyon', 'i-stasyon-seyfet-bozcali-li1wc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelende çok gidende,dolar taşar istasyon,

Kimi bir daha dönmez,kimi için bir oyun.

Çok olaylara gebe sık,sık yapılır yayın,

Bazen yoksul mekanı,bazen boştur istasyon...

Yalan dünya''ya benzer içinde yolcu tutmaz,

Bir dolar bir boşalır,insanlar rahat etmez,

Ne kadar ağırlasa,kimseyi mutlu etmez,

İhtişama güvenme,sonun boştur istasyon...

12.12.2005', 'Gelende çok gidende,dolar taşar istasyon, Kimi bir daha dönmez,kimi için bir oyun. Çok olaylara gebe sık,sık yapılır yayın, Bazen yoksul mek...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/istasyon-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Yağmurları yağıyor,', 'huzun-yagmurlari-yagiyor-ali-osman-yilmaz-haho8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aylardan eylül ayı,

Yaşımı hatırlatırcasına,

Hazan mevsimi geldi yine,

Göz yaşlarım gibi,

Hüzün Yağmurları yağıyor,

Bu gece gökten yine,

Halbuki dün gece,

Mutluluk duaları yollamıştım,

Gökteki yıldızlara,

Söylesin bulutlara,

Sevinç dolu yağmurlarla,

Mutluluk yağdırsın diye,

Neden bilmem neden,

Ulaşmaz dualarım bile,

Tanrıya ve meleklerine,

Umut dolu gönlümle,

Mutluluk diledim göklerden,

Hazan mevsimine geldim,

Onun için mi,

Hüzün yağmurları yağıyor,

Bu gece yine.', 'Aylardan eylül ayı, Yaşımı hatırlatırcasına, Hazan mevsimi geldi yine, Göz yaşlarım gibi, Hüzün Yağmurları yağıyor, Bu gece gökten yine, Hal...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/huzun-yagmurlari-yagiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyor musun?', 'biliyor-musun-hazret-seyda-n3yrd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyor musun? sana nasıl ısındığımı,

Gönlüme hangi tohumlar ektiğini? 

Sensizken ne ile avunduğumu? 

Biliyor musun? baharlara hasret kaldığımı? 

Hani mehtaplı geceler olur ya,

O an sevdalar şikayet edilir aya.

Deryalar dalga vururken dünyaya,

O zaman ağıtlar yakarım sevdaya.

Biliyor musun özlediğimde çıkarım kıra,

Kılıfına uydururum kendimi, kendimce asra.

Bazen bir name yazar veririm tele ahvalimi,

Bazen rüzgardan alır tekrar veririm şimalini.

Bilemezsin önümdeki rakımı dudağımda izmariti,

Bazen bulama cığaramı yakmak için kibriti,

Bazen de namerde muhtacım almak için simidi,

Ama Rabbime imanım var veriyor takatı himmeti.

Bilme olanların hiç birini yorma kafanı,

Sinemden inen damla deşmesin yaranı,

Ben garibin biriyim gah zavallı olurum,

Gah güle su gah ekabire deccal olurum', 'Biliyor musun? sana nasıl ısındığımı, Gönlüme hangi tohumlar ektiğini?  Sensizken ne ile avunduğumu?  Biliyor musun? baharlara hasret kaldığ...', ARRAY['Türk Edebiyatı','Şiir','Hazret Seyda']::text[], 8.5, '{"poet":"Hazret Seyda","poet_slug":"hazret-seyda","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biliyor-musun-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülderen Çocuk', 'gulderen-cocuk-hazret-seyda-mr7zd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sokakta karşılaştım.

Satarken güllerini,

Alırken alın terini.

Yırtıktı elbisesi,

Ayağında terliği.

Bir kör topal babası,

Ve mezarda anası.

Daha on bir de yaşı, 

Ağarmış saçı başı.

Bir amaç için yaşar,

Aklı fikrinde hep var

Babacığının aşı.

Köhne bir kulübede,

Kapıda iskemlesi.

Giderken oturuyor,

İskemleye babası.

Sabahları tez kalkar,

Erkenden işe çıkar.

Cadde cadde sokak sokak,

Al yanağından almış,

Kırmızı güller satar.

Serseriler alır bazen,

Kazandığını hepten.

Bazen gülle oynaya,

Gelir eve erkenden.

Güneş batmadan evvel,

Mutfaksız eve koşar.

Babacığına aşı,

Yırtıklarını döşer.', 'Sokakta karşılaştım. Satarken güllerini, Alırken alın terini. Yırtıktı elbisesi, Ayağında terliği. Bir kör topal babası, Ve mezarda anası. D...', ARRAY['Türk Edebiyatı','Şiir','Hazret Seyda']::text[], 8.5, '{"poet":"Hazret Seyda","poet_slug":"hazret-seyda","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gulderen-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Sen', 'gittin-sen-hazret-seyda-d1fsn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ela gözlüm gurbet yolun gözüktü,

Göz yaşıma baka baka gittin sen.

Naçar gönlüm hüzünlere büründü,

Kaderimi allak bulak etti sen.

Senden sonra sokaklara düştüm ben,

Hatıranla avunmaya kaldım ben,

Yollarına gözüm yaşlı baktım ben,

Sensizliği halka yapıp taktın sen.

Bir tavsiye bir akıl ver gönlüme,

Bulutların yağmur döksün hüznüme

Şu viranda yalnız kaldım başıma,

Feleğime tokat atıp gittin sen.

Gönül bahçem sensizlikten kurudu,

Siyah saçım ak ak oldu döküldü,

Prangalar yaktı beni kavurdu,

Gençliğime acımadan gittin sen.

Şu adresin ver de bana geleyim,

Hangi köye gelin oldun bileyim,

Kocan ile mutluluğun göreyim,

Yaşadığın kutsal yeri öpeyim.

Sakın bakma kalemime çizgime,

Sen mutlu ol kapılma hislerime,

Şiirlerim sebattır dertlerime,

Eş olmuşlar aş olmuşlar içime.', 'Ela gözlüm gurbet yolun gözüktü, Göz yaşıma baka baka gittin sen. Naçar gönlüm hüzünlere büründü, Kaderimi allak bulak etti sen. Senden sonr...', ARRAY['Türk Edebiyatı','Şiir','Hazret Seyda']::text[], 8.5, '{"poet":"Hazret Seyda","poet_slug":"hazret-seyda","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gittin-sen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-yasar-yiltan-t7mg0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sendikayı düşünüyordum,

                     Sabahın bu erken vaktinde; 

                     Hak aramak için verilen mücadeleleri,

                     Bu uğurda dökülen kanları...

                     Sonra sen geldin aklıma.

                     Birini sevmek, birine aşık olmak geldi.

                     Çok güzel bir duygu bu; 

                     Hep birini düşünmek,

                     Hep onu sevdiğini düşünmek. 

                     Sonra neden bilmiyorum:

                     Tanrı geldi aklıma.

                     O nasıl bir şeydi ki? 

                     İnsan gibi değildi büyük bir olasılıkla.

                     Bir ışık mıydı yoksa? 

                     Mavi bir ışık! 

                     Birden hafiflediğimi hissettim; 

                     Ölüyor muyum yoksa? 

                     İrkildim! 

                     Oğlumun sesini duydum sonra.

                     Kulak verdim ağlıyordu.

                     Ne kadar da küçük,

                     Ne kadar da aciz,

                     Tek başına yapamayacak kadar.

                     Sonra saat tıkırtısı duydum.

                     Derken, yoldan geçen arabaları 

                     Ve işçi seslerini duydum.', 'Sendikayı düşünüyordum,                      Sabahın bu erken vaktinde;                       Hak aramak için verilen mücadeleleri,         ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yıltan']::text[], 8.5, '{"poet":"Yaşar Yıltan","poet_slug":"yasar-yiltan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yasamak-198-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Şikayetname 26 / Kördüğüm...', 'sikayetname-26-kordugum-naime-erlacin-qff0c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'içimdeki yumağı çözmeye ayırdım 

gece masallarını

yüreğimde çeteleşen 

kelimelere ayarlı saatlerin karanlık yüzüne

asmışız hayata paltomuzu bir kez

sabaha sağ çıkmaz zihin kurtları

uçsuz kördüğümler vehmeder

selamsız atların sabırsız kişneyişinde

esir alındığını bilmez bir yumak 

''parça tesirli''* vuruşların menzilini

içtiğimiz acı su aynı

döktüğümüz kan ve cerahat

nabız atışlarımız birbirine ayarlı

ihtilâlim var bu gece! 

kalkışacak körelmiş tüm dizeler 

bir dağ yankısı olacak bu masal

keskin bir törpülenme 

dışa bakan 

iç yüzümüze

feshedecek aksi halde kördüğüm hepimizi

kapsama alanı içindeyiz zalim bir şebekenin

(*)     Altay Öktem

(25 Ocak 2006)

(''ŞİKÂYETNAME'' - Hayal Yayınları,  Temmuz 2010, Sayfa 90)', 'içimdeki yumağı çözmeye ayırdım  gece masallarını yüreğimde çeteleşen  kelimelere ayarlı saatlerin karanlık yüzüne asmışız hayata paltomuzu ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sikayetname-26-kordugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyor musun Bir Tanem?', 'biliyor-musun-bir-tanem-hazret-seyda-70iu6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biliyor musun bir tanem..? 

Sana karşı dağların yamaçlarında,

Köyünden görünen yıldızları seyrederken,

O an..! 

Mazimde kalan hatıralarımla,

Kalırım baş başa tabii halimle.

Biliyor musun bir tanem..? 

Teselliler hayatı zorluyor bazen,

Seherleri hiç uyumam ayrıldığımdan beri.

Belki köyünden gelen rüzgar,

Seherde geçer diye.

Biliyor musun bir tanem..? 

Nöbet tutarım her güneşin batışında,

Belek Burcu ile Diclenin halini hayal ederek.

Sana olan özlemliğimle yazarım.

Bunlar temennilerim,

Bunlar tesellilerim,

Sana olan hasretimin dayanağı,

Sana ulaşmanın birkaç yıllık günlüğü,

Seni ifade etmenin tutanağı,

Belki de; 

Elde etmenin en kolay yolu.

Anladığını anla,

Anlamadığını aynana sor.

Biliyor musun bir tanem..? 

Vatanım dar gelir bazen,

Başka diyarlar katmak ister,

Gönül kafesimin sınırlarına.

Engin ufuklara yelkenlenirken,

Ufacık beynim koca bedenimi zorluyor,

Tıpkı şimdi; 

Bazılarınca,

Heba ettiğim beyaz kağıdım gibi.

Ve biliyor musun bir tanem..? 

Unutmanı istemediğim bir şey! 

Mutlaka emr olunan olacak,

Asılı levham indirilecek,

Hak zahir olacak,

Her beden gibi bende göçüp gideceğim,

Ebedi istrahatgahıma.

Gitmeden isterim ki; 

İşlensin defterim açılana dek,

Ve bir tanem,

Temenniler öteye gitmez,

Teselliler de tastan çıkmaz.

Unutma..!', 'Biliyor musun bir tanem..?  Sana karşı dağların yamaçlarında, Köyünden görünen yıldızları seyrederken, O an..!  Mazimde kalan hatıralarımla,...', ARRAY['Türk Edebiyatı','Şiir','Hazret Seyda']::text[], 8.5, '{"poet":"Hazret Seyda","poet_slug":"hazret-seyda","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/biliyor-musun-bir-tanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orda Bir Köyüm Var Uzakta Benim', 'orda-bir-koyum-var-uzakta-benim-ramazan-ates-qby02', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nevşehir ilim de, Gülşehir ilçem,

Köyümü sorarsan, Yeşilli benim.

Anamı gelin Elif bilirler de,

Gambur Ali derler, babamdır benim.

Ateşoğlu diye namımız varmış,

Bekir koca, Ateş soyadın almış,

Küçükken yetimlik nedir bilirde,

Çolak Osman derler, dedemdir benim.

İnadı üstüne yok derler köyde,

İnşaat ustası, hacıdır birde,

Adını bilen yok, Cağlak derlerde,

Hacı Ahmet adı dedemin benim.

Biz altı gardaşız, üç oğlan üç kız,

Ben büyük oğlanım, benden büyük kız,

Herkes başka yerde, ayrı ayrıyız,

Babamla anam var köyümde benim.

Köyümüz küçüktür, atmış haneli,

Kızılırmak vardır eğlence yeri,

Adı yeşil olsada, köyü görmeli,

Susuz köyüm, çorak, kuraktır benim.

Okuyan kaçıyor, iş güç kuruyor,

Evini yurdunu şehre yapıyor,

Düğünde bayramda köye geliyor,

Hep yaşlı yaşıyor, köyümde benim.

Bağ bahçe haraptır, eken olmuyor,

Yaşlılar yorulmuş gençler bakmıyor,

Kışı soğuk, yazı kurak geçiyor,

Eskiyi özlüyor, şu gönlüm benim.

Kuzu koyun güder, ferik üterdik,*

Gider nergiz toplar, tülü kazardık,

Tarlalardan bazen karpuz çalardık,

O günler burnumda tütüyor benim.

Bekçiler kızarda sopa atardı,

Hele biri vardı, fena çatardı,

Öyle bir vururdu canlar yakardı,

Bak şimdi yanıyor, yüzlerim benim.

Kimler gelmiş, kimler göçmüş köyümden,

Kırkbeş yılım şimdi geçti gözümden,

İçimden ah dedim,  hasret çöktüde,

O günler canlandı, gözümde benim.

Gurbetten köyüme selamlar olsun,

Dilerim köylümün biri okusun,

Bir gün olur bende gelirim elbet,

Var ise bir lokma kısmetim benim.

Bir damla suyumsa kısmetim benim.

Ramazan Ateş/Enschede(Hollanda)  8.1.2006

*ferik ütmek: Tazeyken sararmaya basliyan bugday basaklarini ates uzerinde biraz kavurup yemeye denir.', 'Nevşehir ilim de, Gülşehir ilçem, Köyümü sorarsan, Yeşilli benim. Anamı gelin Elif bilirler de, Gambur Ali derler, babamdır benim. Ateşoğlu ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/orda-bir-koyum-var-uzakta-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilyorum Gideceksin', 'bilyorum-gideceksin-hazret-seyda-r0xim', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyorum gideceksin! 

O meçhul tepeyi sende aşacaksın,

Güneş ile birlikte sende kaybolacaksın,

Amma sen; 

Bir daha doğmayacaksın.

Biliyorum! 

Giderken ardına bakmayacaksın,

Beni yalnız bırakacaksın,

Kayan bir yıldız gibi, 

Ansızın kaybolup gideceksin.

Senden sonra; 

Anlamını yitirecek gözlerim,

Cilası çıkmış,

Bir mobilya gibi eskiyeceğim,

Saçlarım alnıma düşecek,

Düşen yıldızlardan başkasını,

Söz veriyorum sevmeyeceğim.

Bir bahar rüzgarı alır götürür belki,

Belki de dillerde şarkı eşe dosta ağıt,

Belik de; 

Tıpkı çıra gibi tarihe karışacağım.

Bunlar tesellilerimdir bakma,

Kendimi avutmanın tek yolu,

Pervane gibi çark etmenin anlamsızlığıdır.

Sen yoluna bak boylu boyunca,

Dert etme garibi.', 'Biliyorum gideceksin!  O meçhul tepeyi sende aşacaksın, Güneş ile birlikte sende kaybolacaksın, Amma sen;  Bir daha doğmayacaksın. Biliyorum...', ARRAY['Türk Edebiyatı','Şiir','Hazret Seyda']::text[], 8.5, '{"poet":"Hazret Seyda","poet_slug":"hazret-seyda","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bilyorum-gideceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla Yar Ağla !', 'agla-yar-agla-hazret-seyda-5necz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağla yar ağla..! 

Kes o uzattığın siyah zülüflerinin.

Kötüler ölmedi,kötülük ölmez,

Devran bin parmağa konmuş,

Kalemle kağıtla olmaz.

Sevdana ağlasan da,

Halim yaman desen de,

Yine de yaranamaz.

Ağla yar ağla..! 

Çek gözlerine sürmeyi,

Onlar matem rengidir bilirsin.

Yar sana küsmüş,yar sana dargın,

Devran sana yaman,

Örtü sana yakışmaz,

Ayıplar örtünmez,

Çek ellerini yanaklarına,

Aksın gözlerinden yaş,

Ağıt yaksın dönsün dilin.

Ağla yar ağla..!', 'Ağla yar ağla..!  Kes o uzattığın siyah zülüflerinin. Kötüler ölmedi,kötülük ölmez, Devran bin parmağa konmuş, Kalemle kağıtla olmaz. Sevdan...', ARRAY['Türk Edebiyatı','Şiir','Hazret Seyda']::text[], 8.5, '{"poet":"Hazret Seyda","poet_slug":"hazret-seyda","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/agla-yar-agla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Albüm', 'album-hazret-seyda-s1pdr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu akşam konuştu gerçekler,

İndirildi tozlu albüm,

Bakıldı bakıldı aktı göz yaşlar.

Anıldı yaşanan maziler,

Vah gençliğim vah gerçekler.

Açarken albümü dalarken maziye,

İndi göz yaşlarım yandı gençliğe,

Torpil yaptım aynaya çare yok diye,

Nafile bir ömür verdik geriye.

Sitemin her damlası gider boşuna,

İster ağla ister gül hoşuna nahoşuna,

Kanma güzelliğine dünyanın sarhoşuna,

Albümdeki resme bak kaşına başına.

Ağarmış saçlar ağlatmış kader,

Albümdeki delikanlı bu gün titriyor eller,

Var olan şerefi almadan kimseler,

Selam sana ey ecel hemen durma gel.

Albümle bu asır hiç kaynaşmıyor,

Cıbıldakla pantolon aynı yerde olmuyor.', 'Bu akşam konuştu gerçekler, İndirildi tozlu albüm, Bakıldı bakıldı aktı göz yaşlar. Anıldı yaşanan maziler, Vah gençliğim vah gerçekler. Aça...', ARRAY['Türk Edebiyatı','Şiir','Hazret Seyda']::text[], 8.5, '{"poet":"Hazret Seyda","poet_slug":"hazret-seyda","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/album-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta', 'usta-nedim-akgun-x8aeu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşarken yokuşları aşmak istersin

Bir kötüye düşer zulüm çekersin,

Sevgi şevkat mutlulugu sende beklersin,

Onun için sevme,sevme be usta

Gördüm aşk şerbeti içen avareleri,

Sevgi,sevgi diye feryat edenleri,

Kötülük eksilmez zulüm çekenleri,

Onun için sevm,sevme be usta.

Yarına kavuşmaya dermanı yoktur,

Ağzından eksilmeyen lafları çoktur,

Yaşadığı bir anlık koskoca zevktir,

Onun için sevme,sevme be usta.

Haksızın yanında haklı olmadan,

Bir bardak suda fırtına kopmadan,

Açan çiçeklerin yaprakları solmadan,

Onun için sevme,sevme be usta.

Umutsuz yarınlarda dostları sordum,

Ne sevda gördüm,ne de vefa buldum,

Yalan aşklarda sitemler gördüm,

Onun için sevme,sevme be usta.

Biz hayyam olmadı bu güne geldik,

Kendimizi mavi bildik herkez''i sevdik,

Düşler sokağında ne güzeller gördük,

Onun için sevme,sevme be usta', 'Yaşarken yokuşları aşmak istersin Bir kötüye düşer zulüm çekersin, Sevgi şevkat mutlulugu sende beklersin, Onun için sevme,sevme be usta Gör...', ARRAY['Türk Edebiyatı','Şiir','Nedim Akgün']::text[], 8.5, '{"poet":"Nedim Akgün","poet_slug":"nedim-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/usta-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Susmaya Giden...', 'susmaya-giden-naime-erlacin-q73nv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sessizce gelen

susmaya gitti

sorgusuz 

sualsiz

yanıtsız 

gürüldeyerek akardı yeraltında

gece yarısı 

sonsuza doğru

acılar ırmağında

ak kâğıda düşürdü rengini

içedönük bir yolculuk methiyesi

gökten soruldu 

kökenden ey yâr

özentiyi uslandıran bilgelikten

dil’in sevdalı sorumlusu 

özdeki karmaşadan soruldu

susmaya gitti! 

geleceğe pullanmış mühürlü bir mektuptu

(25 Ocak 2006)', 'sessizce gelen susmaya gitti sorgusuz  sualsiz yanıtsız  gürüldeyerek akardı yeraltında gece yarısı  sonsuza doğru acılar ırmağında ak kâğıd...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/susmaya-giden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cizrelim', 'cizrelim-hazret-seyda-dpfo4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah mem-u zin’li  kentim CİZRELİM! 

O güzelim şehir vazgeçilmez sevdam,

Bir yar verdin bin can aldın benden,

Neyleyim vatanımsın hoşnuttum senden.

Bin asırlık kabarık bir tarihsin.

Aşk dedikodu saltanatlı geçmişsin,

Getirin mendilimi sileyim göz yaşımı,

Yanayım sevdiğime ağlayayım CİZRELİME.

..............

Kulak ver güzelim aldanma etrafına,

Ziyanım yok gönlüm vurulmuş sana,

Taş koydun göğsüme od koydun gönlüme,

Dinlensin yazıktır sen ağla CİZRELİMİN yerine.

Ah deşmiş gönüllü CİZRELİM hasretliğim,

 Sürmeye gerekmez çık şenlendir şenimi,

Bir hoş olsun içim kan akıtmasın gözlerim,

Bir görünüp kaybolma yazıktır CİZRELİME.', 'Ah mem-u zin’li  kentim CİZRELİM!  O güzelim şehir vazgeçilmez sevdam, Bir yar verdin bin can aldın benden, Neyleyim vatanımsın hoşnuttum se...', ARRAY['Türk Edebiyatı','Şiir','Hazret Seyda']::text[], 8.5, '{"poet":"Hazret Seyda","poet_slug":"hazret-seyda","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cizrelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anacigim', 'anacigim-nurullah-saadettin-budak-hmeg9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her olum cok erkendir anacigim

Seninde oldugu gibi

Nasil bir duygudur bilemem ama

Seni gomerken gordum

sevilir gibi degil topragin dibi

Hepimiz birer suclu gibi durduk karsinda

Sanki dunyayi biz kirletmisiz gibi

Fukaraydi anam,Turkceyi ogrenememisti

Iki kocasi olmustu garibin

Ilkini 16 sinda kaybetmis

Sonra babamla evlenmis..

Ne zaman dertlesmek istese babamla

Horlanmisti hep

Ona ragmen mutluda olurdu bazen

Aklisira dunyaya tam 11 evlat vermisti

Hic boyasi olmamisti anamin

Yesil sabunla yikardi simsiyah saclarini

Tararken gecerdi belinin yarisini

Bize gore dunya guzeli idi anamiz

Cok darbe yemisti ama,gostermezdi yarasini

Gun geldi yaslandi anam

cizgiler belirdi nurdan yuzunde

Saclari tel tel agardi

Sancisi eksilmezdi garibin

Basi catlamasin diye sancidan

Ikinci bir yazma ile siki sikiya baglardi

Basimizi koyardi dizlerinin ustune

Saclarimizi oksarken bile aglardi

Cok gecmemisti arada,agbim aradi

''Basimiz sagolsun,Anamizi kaybettik''

Cok yikilmistim o an

Veda bile edememistik

Ben bacim ve kardesim toplanip gittik

Optuk anamin sararmis yanaklarindan

Ellerinden tutup topraga gomduk.', 'Her olum cok erkendir anacigim Seninde oldugu gibi Nasil bir duygudur bilemem ama Seni gomerken gordum sevilir gibi degil topragin dibi Hepi...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Saadettin Budak']::text[], 8.5, '{"poet":"Nurullah Saadettin Budak","poet_slug":"nurullah-saadettin-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/anacigim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olasım geliyor sana..!', 'olasim-geliyor-sana-ahmet-kose-7xumv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İç içe geçmek gerekir seninle.

Duru bir denizdeyiz

akan

için   için...yüzen

yakamozlar

geçiyorken

içimizden,

sana köpük olasım geliyor

lacivert yanımız kabardığında

derinimsin sen.

Her bakışımda sana

iç içe olasım geliyor benim

kıçındayken teknemin..! 

sen bir kaç dalga ötemde

geliyorken

bana

çarpa çarpa yüreğime

kenet olmak sana,

geçiyor içimden.

Yelkendeki ipler

düğüm düğüm

dolaşırken 

bakışırken

aramızda yüreği kabarık bir deniz

düğüm olasım geliyor sana.

Kayboluyorsun bir ara

beyaz ışığında güneşin

kırpmadan yüreğimi

mavimizde

öte yanıma dönüyorum

koparılmaz

dalında

uçtaki nar gibi duruyorsun

dal olasım geliyor nar çiçeğim

koparılmayan sana.

Dönüyorum mavime

beyaz gömlekli 

filinta gemilerim geliyor sana

salıvermişim 

davullarını yüreğimin

sana düğün olasım geliyor içimden

lacivert köpüklerinde yüreğimizin.

Düşüyorum sana

kafesteyken ben

bilmez iken

bunca gürültülerini hapisliğimin

boşunalığını

bir halay gibi yüzerken yollarda kıyılarda

sessiz

isyansız

sandallarımız gibi yüreğimiz

yan duruyorken

ağların karmaşalığında

fora olmuşum ben sana

sabah gibi deniz

küheylan gibi rüzgar

çözüldü hayat

sana kuş olasım geliyor kafesinde.

Pırıl duruyor önümde hayat

geçmiş yosun taşlı duvarlarda sırtım

gelinlik kızlar gibi gemilerim

mağrur

sakin

ağır

bir yürek edası

kımıltısız herkes

açık ve aç yürekler

dimdik gözler

yerinde değil

haşarı çocuk

kopacak palamarlar

çağırıyor düğüne

maviye mavimize

olasım geliyor işte bu an da

hep iç içe

deniz olasım geliyor seninle.

Bir durun diye çırpınıyorum

kuğular gibisiniz biliyorum

kuğularım,

sudaki kuzularım

gemilerim benim

üstümdesiniz

o güzelim zarifliğinizle...

durmaz ki

duramaz ki

bu

yelkenler açık

bu fırtınanda senin

demirlide olsam diplerime.

Kopasım geliyor palamarlarımdan işte o an da..! ! 

sana kırdığım bu mavi yolda  dümenimden

olasım geliyor sana bir dümen..

olasım geldi sana bir kuzu

sessiz

yelkensiz

durasım geldi

suyunda.

21/ekm/bitez/05', 'İç içe geçmek gerekir seninle. Duru bir denizdeyiz akan için   için...yüzen yakamozlar geçiyorken içimizden, sana köpük olasım geliyor laciv...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":98,"source_url":"https://www.antoloji.com/olasim-geliyor-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pir Sultan', 'pir-sultan-nurullah-saadettin-budak-yvz4n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seyda bulbul olduk Sivas ilinde

Derdimizi gule doktuk Pir Sultan

Sairlerin ozanlarin dilinde

Turkuleri tele doktuk Pir Sultan

Hepimiz bir candik et ile tirnak

Ayrilmadik kenetlendik Pir Sultan

Cehennem atesiyle yanar madimak

Sondurmedik korukledik Pir Sultan

Bir bedende semah cekti kizlarin

Karanliga isik olduk Pir Sultan

Apdestsiz secdeye durdu dizlerim

Niyaz ettik egilmedik Pir Sultan

Yere indirmadik emanetini

Alnimiza kader yazdik Pir Sultan

Dudaktan dudaga ask serbetini

Serefine  ikram ettik Pir Sultan', 'Seyda bulbul olduk Sivas ilinde Derdimizi gule doktuk Pir Sultan Sairlerin ozanlarin dilinde Turkuleri tele doktuk Pir Sultan Hepimiz bir ca...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Saadettin Budak']::text[], 8.5, '{"poet":"Nurullah Saadettin Budak","poet_slug":"nurullah-saadettin-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pir-sultan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidelim', 'gidelim-ali-kalafat-3u1lj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüzümüz dönmüş sulu cesede

Ne kaldı ki bakacagımız geride

Hazırlan...

Ver elini 

GİDELİM...

Dışarısı soğuk

Üzerine bir manto

Bavuluna sonbahar yapraklarını al 

Ceplerine biraz ümit 

Yüzünede bir parca tebessüm sal 

Ve hazırsan 

Ver elini 

GİDELİM...

O gecmeyen günlerin şafaklarını 

Teskereye gün sayanlara 

Akşam batan güneşlerini 

Kader mahkumlarına bırak

Dakikası gecmeyen zamanları oruçlulara

Bitmesini istemediginn anlarıda

Kaderin bilmedigi zulalara sakla

Hadi fazla ugraşma 

Ver elini 

GİDELİM...

Acılarını kederlerine sar

Gözü kapalıyken vur bıcaga

Öldügüne emin isen

Ver bana gömelim topraga

Selasını sen ver 

Ben kazdım mezarınıda

Sakın gec kalma 

Belki yetişemeyiz cenaze namazına

Kimseye hissettirme yaptıgını

Yakalanırsan ben cekerim cezasını

Ve üzülme hala 

Aglama

Kaç benimle umut dolu yarınlara

İnanmak istiyorsan bana

VER ELİNİ 

GİDELİM....', 'Yüzümüz dönmüş sulu cesede Ne kaldı ki bakacagımız geride Hazırlan... Ver elini  GİDELİM... Dışarısı soğuk Üzerine bir manto Bavuluna sonbah...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalafat']::text[], 8.5, '{"poet":"Ali Kalafat","poet_slug":"ali-kalafat","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gidelim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizdenmiş!', 'bizdenmis-mikdat-bal-66sdm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Millet döndü şaşkına 

Kimse bakmaz düşküne 

Yandık Allah aşkına 

Yakanlar da bizdenmiş! 

İnsafı yok ettiler 

Bu yıl az tükettiler 

Malları stok ettiler 

Dükkanlar da bizdenmiş! 

Gelirler çok dar idi 

Satın almak kâr idi 

Her hafta zam var idi 

Bıkanlar da bizdenmiş! 

Düşmüşler bir zillete 

Kâr yapacak ille de 

Kazık marka millete 

Kakanlar da bizdenmiş! 

Elleyip her yanını 

Hortumlayıp kanını 

Bu milletin canını 

Sıkanlar da bizdenmiş! 

Onlarda hile çokmuş 

Sattıkları hep kokmuş 

Derler ki kusur yokmuş 

Kokanlar da bizdenmiş! 

Yabancı malla tazyik, 

Serbest piyasa, yazık! 

Millete bu tür kazık 

Sokanlar da bizdenmiş! 

Çok yedik silesini 

Halk çekti çilesini 

Bu işin hilesini 

Çakanlar da bizdenmiş! 

Halka bilgi vermeyen 

Halk içine girmeyen 

İstikbali görmeyen 

Dekanlar da bizdenmiş! 

Onlar geçmez okuldan 

Satıp hileli maldan 

Şaşırıp doğru yoldan 

Çıkanlar da bizdenmiş! 

Mikdat gece yatmamış 

Evi de uyutmamış 

Sözlerini tutmamış 

Bakanlar da bizdenmiş!', 'Millet döndü şaşkına  Kimse bakmaz düşküne  Yandık Allah aşkına  Yakanlar da bizdenmiş!  İnsafı yok ettiler  Bu yıl az tükettiler  Malları s...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bizdenmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalıydım', 'sevdaliydim-muhiddin-ates-4bcjw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok severdim seni bilirsin

Senin için hiçbir şeyden sakınmaz

Canımı bile hiçe sayardım

Çünkü ben sana sevdalıydım

Kimse adını anamazdı yanımda

Bana tescilliydi adın

Yakardım bu dünyayı senin için

Çünkü ben uğruna belalıydım

Ama sen birden yok oldun

Kimse içki içiremezken bana

Meyhaneden çıkmaz oldum

Çünkü kadehlerde seni bulmalıydım', 'Çok severdim seni bilirsin Senin için hiçbir şeyden sakınmaz Canımı bile hiçe sayardım Çünkü ben sana sevdalıydım Kimse adını anamazdı yanım...', ARRAY['Türk Edebiyatı','Şiir','Muhiddin Ateş']::text[], 8.5, '{"poet":"Muhiddin Ateş","poet_slug":"muhiddin-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdaliydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mânevî eksiklik', 'm-nev-eksiklik-sair-ahrazi-tavmx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kulak ver rûhuna artık,nefs''e verdiğin kadar 

Sefil olmazdın; övseydin dîni,yerdiğin kadar! 

(mefâîlün/mefâîlün/fâilâtü/fâilün)   

* * *', 'Kulak ver rûhuna artık,nefs''e verdiğin kadar  Sefil olmazdın; övseydin dîni,yerdiğin kadar!  (mefâîlün/mefâîlün/fâilâtü/fâilün)    * * *...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/manevi-eksiklik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Masalsı...', 'masalsi-naime-erlacin-p2beu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bin geceden 

bir kuş masalı anlat bana

ışığın dansı 

rüzgârın ateşi ol yüreğime

es! tutuşsun tanıdık bu haz 

sen söyle anlat 

yazarım ben

daha çok severim sesine geldiğimde

gitmişsem bir gün 

sakın sorma “neden” 

tek adım uzaktaysan 

on gerideyim

incilerim dağılır zemheriye

buz bir ayaz üşütür köklerim

sinsi kurtların insafına teslim 

kuru bir çınara benzer 

giderim

kanadı ol sıra dışı hayallerimin

dimdik kışkırtıcı 

ve asi

kıtlama şeker gibi emeriz aşkı böyle

esaret zapt edemez kuşları bilirsin 

zincirlere kör bakar onlar

bu yüzden daha güzeldir aşk

iri bir kuşun masalsı teleğinde 

(1 Ocak 2006)', 'bin geceden  bir kuş masalı anlat bana ışığın dansı  rüzgârın ateşi ol yüreğime es! tutuşsun tanıdık bu haz  sen söyle anlat  yazarım ben da...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/masalsi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemin Ardından 2', 'annemin-ardindan-2-zeliha-bicer-jaw7x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüzünü unuttum, sesin hatrımda değil

En cok sevgini biliyorum

Sarılmanı,sıcacık

Kederimi bilemezsin annem

Sen koca bir çınardın fideleri bizdik 

Yıkıldın ansızın

Çocuktum  korkmuştum

Savunmazdım,sensizlik neydi 

Neydi diye düşündüm

Koca bir boşlukmuş,kimsesizlikmiş meğer

Kar yağıyor lapa lapa,içim buz gibi

Gözlerimde biriken yaşlarıma don vurdu

Yanan mum gibiyim,erimekteyim yavaş yavaş

Yılların birikimi var üstümde bedenimde

Taşımakta zorlandığım,

Yokuşu çıkmakta kaderim,hep yokuşu

Nefes almak isterken ben hancer saplanır gögüsüme

İsyan değil bu Yaradanıma 

Biraz özlem,biraz yetimliğim vardı satırlarımda...', 'Yüzünü unuttum, sesin hatrımda değil En cok sevgini biliyorum Sarılmanı,sıcacık Kederimi bilemezsin annem Sen koca bir çınardın fideleri biz...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/annemin-ardindan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş ve sevgi;', 'gunes-ve-sevgi-levent-i-skenderoglu-ud5ag', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneş ve sevgi; 

Bir yaprağın ayrıntıları gibi

Bir atom taneciğinin ayrıntıları gibi

Isınmak üşümek gibi, bir damla 

Resimde boğulmak gibi bir şeydir', 'Güneş ve sevgi;  Bir yaprağın ayrıntıları gibi Bir atom taneciğinin ayrıntıları gibi Isınmak üşümek gibi, bir damla  Resimde boğulmak gibi b...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gunes-ve-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz sarkar yalnızlık', 'buz-sarkar-yalnizlik-elazigli-mustafa-kaya-htcyp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kar beyaz örtü

sis kadar

tipi olup hırçınca

yağdıkça yağdı

yollar kapandı

yine kar başladı 

dün den öncede

kar,

hep kar vardı..

şehir içine çekildi

içine çekilen sendin

söyle..? nasıl gideceksin..? 

bin uykusuz gecelerine..

içimde üşüyen sen

buz sarkar

yalnızlığın ağlatır beni

tutuşturup dudaklarımı

kar ötesi

bir kar nasıl inerse

girdin içme

ve nasıl inlerse bir çığ

bir taş yağmuru gibi

ürperiyorum düşünceden

kar akıyor

kan yerine yüreğimden..

ahh..içinde sen olan 

kış

seninle  olmak vardı

kaçıp bir kar tanesine.

doya doya yağmak

seninle

içinde sen olan 

o yerde …

Mustafa kaya

26.01.2006 / tepebaşı

www.mustafa kaya.net', 'kar beyaz örtü sis kadar tipi olup hırçınca yağdıkça yağdı yollar kapandı yine kar başladı  dün den öncede kar, hep kar vardı.. şehir içine ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/buz-sarkar-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ayyaşın İçkisini Yudumlaması Gibi..', 'bir-ayyasin-i-ckisini-yudumlamasi-gibi-zeliha-bicer-wnvi2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karın dondurucu soğuğu vuruyor pencereme

Üşüyorum sıcacık evimde

Ellerim titriyor nöbete tutulmuş gibiyim

Bir ayyaşın,bir damla içkisini yudumlaması gibi

Sana ihtiyacım var.

Kimsesizliklerim öyle dövüyor ki bu gece benliğimi

Paramparça umutlarım

Bu gece sabahı beklemek istedim

Günün aydınlığını görmek

Yüreğime çöreklenen bu karabasanı atmak

Doğan güne MERHABA derken

Ben gibi olmak

Sevgi dolu,umut dolu

Sensizliğin vermiş olduğu özlemi içimde taşıyarak..', 'Karın dondurucu soğuğu vuruyor pencereme Üşüyorum sıcacık evimde Ellerim titriyor nöbete tutulmuş gibiyim Bir ayyaşın,bir damla içkisini yud...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-ayyasin-ickisini-yudumlamasi-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızların Üstüne-', 'yildizlarin-ustune-nuri-gokhan-sonsel-r0a4v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün gece mehtap vardı, hava sakin ve sessiz, 

Deniz durgun dalgasız, rüzgar susmuş nefessiz.

         Diyordu ki.. Eğer beni gerçekten çok fazla seviyorsan...

Bir elinde kalemin, bir elinde yüreğin.

Sevda mektupları yaz, yıldızlarda göreyim.

Binbir zorlukla çıktım, ayın en tepesine, 

Yıldızlar gülümsedi, bayıldım neşesine.

Neler yazdım ah neler, aşk dolu kelimeler,

Ben bu aşkın yüzünden, şair olmuşum meğer.

Sabah oldu gün doğdu, yağmur başladı birden,

Sakin rüzgar kudurdu, esiyor karayelden.

Bugün size küskünüm, yıldızları örttünüz,

Neden sert esen rüzgar, mektubumu yırttınız? 

Okusaydı dün gece, sevda mektuplarımı, 

İnanırdı sevgime, sarardı kollarını.

Bir kere bir inansa, bu gönül taşmaz mıydı.

Kış ortası çiçekler, yeniden açmaz mıydı? 

	Acaba kimdi... O mektubu yıldızlarda isteyen? ..

Rüyaları süsleyen, bir melek kadar güzel,

Benim duygu dünyamda, yeri özel mi özel.

Tarif edemem onu, kelimeler yetersiz,

Bu aşkın boyutunu, sizler bilemezsiniz.', 'Dün gece mehtap vardı, hava sakin ve sessiz,  Deniz durgun dalgasız, rüzgar susmuş nefessiz.          Diyordu ki.. Eğer beni gerçekten çok f...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yildizlarin-ustune-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metal soğuğu', 'metal-sogugu-elazigli-mustafa-kaya-zyjg8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Metal soğuğu 



 

büklümlü boğaz 

kış soğuğu

şehir 

gri mi gri

utancından sessiz

martılar

metal renginde istanbul

oysa deniz 

mavi gülümseyecekti.. 

Mustafa kaya 

25.01.2006 / kanlıca 

Mustafa kaya

25.01.2006 / kanlıca', 'Metal soğuğu    büklümlü boğaz  kış soğuğu şehir  gri mi gri utancından sessiz martılar metal renginde istanbul oysa deniz  mavi gülümseyece...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/metal-sogugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin kokun', 'senin-kokun-elazigli-mustafa-kaya-tu083', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sesimi bir rüzgar

kaçırıyor.

ve bir koku

senden,

tüm ruhumu dolaşıyor.

gök açık

tek şikayetim

yüzünü saklayan

beyaz saçlı bulutlar.

merakım bu ya..! 

sürüklendim rüzgarla

nerede bulurum seni

birbirinden uzak 

şimdi şehirlerde

duru bir şafakla.

içime attığın ses

sen olabilirsin ancak

su üzerinde

gözyaşlarına bakarak..

Mustafa kaya

12.07.2005 / Üsküdar', 'sesimi bir rüzgar kaçırıyor. ve bir koku senden, tüm ruhumu dolaşıyor. gök açık tek şikayetim yüzünü saklayan beyaz saçlı bulutlar. merakım ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/senin-kokun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçleme', 'ucleme-zulfikar-yapar-kaleli-uywqh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Leylâ ile Gül Muhammet üçleme

Gönülleri bire salması gerek

Leyla yoksa boşa kovan çeçleme

Ona arı girmez, solması gerek

Leylâ’dır dünyanın arşta temeli

Sırat köprüsünde Leylâ demeli

Mecnunun ne ise gerçek emeli

Ehlî kâmilde de olması gerek

Gül dalında Leylâ yazar şüphesiz

İsyân eden de siz, boyun eğen siz 

Uzaklardan biri gelir küpesiz

O  Leylâ’dır gönle dolması gerek

Hasan, Hüseyin’in dilinde Leylâ

Ali Murtaza’nın elinde Leylâ

Resulü Ekrem’in gülünde Leylâ

Her nefis Leylâ’yı bulması gerek

Âlemi meleküt Leylâ’dan geçer

Kuşlar Leylâ diye suyunu içer

Her can bu dünyadan Leylâ’ya göçer

Leylâ’nın gönülde kalması gerek

Muhabbet aslında hâkikat şudur

Leylâ damarda kan, dudakta sudur

Evrenin hayali, niyazı budur

İnsanın da ibret alması gerek', 'Leylâ ile Gül Muhammet üçleme Gönülleri bire salması gerek Leyla yoksa boşa kovan çeçleme Ona arı girmez, solması gerek Leylâ’dır dünyanın a...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ucleme-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kekliğime Ağıt', 'kekligime-agit-bahaettin-karakoc-htx60', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karşı duran karlı dağlar akça gönlümdür 

Bir çoban ateşi ince ince tütende 

Gök ırgalanır gözlerimin sarı nehrinde 

Eşim keklik bir kafeste ötende.

İster çöpten olsun 

İster sarı altından 

Kafes aynı kafes oy 

Kara bir zindan! 

Gece bir atmacadır, döner üstüne üstüne 

Ekşi bir elmayı koklar yüreğin 

Çiçekleri çirkin bir perde iner üstüne 

Çoğalır karası şeker gözlerinin.

İster gül çubuğundan olsun 

İster söğüt dalından 

Kafes aynı kafes oy 

Karanlık bir zindan! 

Kesik kanatlarda derman ne gezer 

Çalmışlar rüzgârını meşeli dağlardan 

Hicret düşlerini kelepçelemişler 

Parmaklarındaki kına değil, kan.

İster çelik telden olsun 

İster saç kıllarından 

Kafes aynı kafes oy 

Kapkara bir zindan! 

Çalmışlar nice yıllarını, meyvesi acı 

Perçemler taranır eski aynalarda 

Çeyizi çürümüş sabır sularında 

Bir yıldız çarpmış yüreğine, sonra bir daha.

İster giysilerden olsun

İster paradan puldan

Kafes aynı kafes oy

Küflü bir zindan! 

Şu buzlu camlardan buzlar daha güzeldi 

Nerde kaldı karda sekmek, doruklarda uçmak? 

Kim demiş kekliğim evcilleşti, 

Kime kalmış gönül yarasını sarmak? 

İster mukavvadan olsun

İster kerpiç tuğladan

Kafes aynı kafes oy

Acımasız bir zindan! 

Kekliğim tutsak ta ben hür müyüm? 

Kıyılara vura vura akıyoruz ya 

Sevgiyi, şiiri, düşü öldürenler vurmuş bizi 

Selâm verdiğimiz gün bu dünyaya.

İster buyruklardan olsun

İster kurallardan 

Kafes aynı kafes oy 

İlkel bir zindan! ...

Bahaeddin KARAKOÇ (Kar Sesi – Ocak Yay. Ankara – 1983)', 'Karşı duran karlı dağlar akça gönlümdür  Bir çoban ateşi ince ince tütende  Gök ırgalanır gözlerimin sarı nehrinde  Eşim keklik bir kafeste ...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/kekligime-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felsefe', 'felsefe-mehmet-akif-gulhan-tiym1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her yanlışa bir haklılık buluyorsun

çoğunluğun fikrine mantık diyorsun

sevmedim seni,fikrini de sevmedim

hele her şeyden kâr''lı çıkmak istemen 

çıldırtıyor beni

koştuğun şey mutluluk değil

kaybeden mutsuz olur

yerini koruyanı mutlu oldu say

Mehmet Akif Gülhan 26.01.2006 Saat 00.49', 'her yanlışa bir haklılık buluyorsun çoğunluğun fikrine mantık diyorsun sevmedim seni,fikrini de sevmedim hele her şeyden kâr''lı çıkmak istem...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/felsefe-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuba cevap', 'mektuba-cevap-mikdat-bal-o0kik', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mektubunu aldım cevap yazmadım

Yazacaktım vaktim dar diye geçtim

İsmini çok andım istif bozmadım

Bu da benim eski yâr diye geçtim

Gurbet ele düştüm halim bilinmez

Gurbeti bırakıp hemen gelinmez

Hatıralar öyle kolay silinmez

Kendi özel dünyam var diye geçtim

Hasret bende de var ne gelir elden

Artık çalmayalım hep aynı telden

Bülbül ayrı kaldı goncadan gülden

Burada mevsim kış kar diye geçtim

İsmini kazıdım belleklerime

Havale eyledim meleklerime

Ben dönerim kendi feleklerime

Sana umut vermek ar diye geçtim

Ömür gelir geçer sevgi ebedi

Kader nasip etmiş bana gurbeti

Sunulmadan bize ecel şerbeti

Ne kadar yaşarsak kâr diye geçtim

Mikdat der bu sevda mahşere kalsın

Bırak da şu gönlüm muradın alsın

Eski sevdam bana bir mektup salsın

Ateşi gönlümde har diye geçtim', 'Mektubunu aldım cevap yazmadım Yazacaktım vaktim dar diye geçtim İsmini çok andım istif bozmadım Bu da benim eski yâr diye geçtim Gurbet ele...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mektuba-cevap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın Anahtarı', 'yasamin-anahtari-ethem-turan-ecwne', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Korkularla dolu  bir ömür yaşamak 

En değer verdiğin anlarda dahi korkmak 

Güven hissini tadarak  huzur bulmak 

Yaşam savaşında mecburen gözünü kapamak

 En güvendiğinden şüphe duymak

Nasıl bir dünya ki en yakınınca 

İhanete uğramak 

Ve bu hayatta kalabilmek için savaşmak 

İşte insanoğlu işte üstün yaratık

Ölüm korkusu değil belki  yaşananlar

Var olan değerlerin yara  alması 

İnsanı insan eden değerlerin 

Bir bir çiğnenip yok olması 

Ruhunda yaşattığın  asaletin 

İnsanlığının kayboluşu 

Korku dolu bir dünya 

Ve çok sevdiğimiz hayatımız 

Değer verdiğimiz insanlar 

Eşyalarımız 

Bizi biz eden aşklarımız 

Yaşamımız 

Çaresiz kaldığımızda dahi 

Sığınacağımız limanı olan 

Ummadığımız bir anda yıkılabilen 

Bir anda da  sevinç deryasına düşen

Yaşamımız 

Ömrümüz 

Acı ve tatlı anılarla 

Yaşanmışların tecrübeleriyle yoğrulmuş 

Deneme yanılma tahtamız

Gülün açıp solması gibi

Çabucak geçi veren ömrümüz

Gökyüzündeki parlak ışıklar gibi 

Zihnimizde parlayan ömrümüzün ve yaşamımızın

Bizi bizden eden   değerimizi çalan 

Aşklarımız 

Korkularımızı hiç eden 

Yaşama değer veren 

Ölümü ölümsüz kılan 

Yaşanası aşklarımız

Leyla ile Mecnun gibi Ferhat ile Şirin gibi 

Fani dünyada korkunun soğuk zincirini kırıp 

Ölümü ölümsüz kılan aşklarımız', 'Korkularla dolu  bir ömür yaşamak  En değer verdiğin anlarda dahi korkmak  Güven hissini tadarak  huzur bulmak  Yaşam savaşında mecburen göz...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/yasamin-anahtari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Ayrılık', 'beyaz-ayrilik-ethem-turan-6vys9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fırtınalı bir akşam 

Savuruyor sokak küllerini

Her taraf bembeyaz 

Sanki yaprak döküyor 

Beyaz bahar gülleri

Beyaz ayrılık derlerse inanırım 

Ayırıyor bu atmosfer 

Dostları, sevenleri 

Kavuşmak istese de

Ulaşamıyor insan

Engel oluyor beyaz yaprak taneleri

Sokak kedileri terk etmiş mekanlarını

Çöpçülerde uğramaz olmuş 

Issız olmuş mahalleler

Her yer istilada 

Hakim olmuş beyaz   yaprak taneleri 

Soğuk hapsetmiş sevenleri 

Gönüllerdeki ateş hiç kayıpsız yanmakta

Düşünceler ortak 

Arzular,isteyişler.özlemler  sarmış olsa da 

Engel oluyor buluşmaya  beyaz yaprak taneleri 

Ne kumruların ötüşleri 

Ne çocukların sevinç çığlıkları 

Nede el ele tutuşmuş aşıkların tebessümleri 

Hiç biri yok  sarmış etrafı 

Beyaz  yaprak taneleri 

Bütün endamını gösterircesine

Sokak ışıklarında  raks edercesine 

Aşk melodileri söylercesine 

Kendine aşık etmek istercesine

Dökülüyor beyaz yaprak taneleri', 'Fırtınalı bir akşam  Savuruyor sokak küllerini Her taraf bembeyaz  Sanki yaprak döküyor  Beyaz bahar gülleri Beyaz ayrılık derlerse inanırım...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/beyaz-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yüreklim', 'gul-yureklim-can-abdullah-yildirim-mr7v2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Buluştuk omuz omuza

Her birimiz bir yerlerde 

Salavat ve tekbirlerle

Diller dönünceye nefesler yetinceye

Biraz hüzün biraz sevinçle

Nidalarımız sanadır ya Resul

Gül yüreklimin doğum günü bugün 

Müjdeler olsun 

Yeryüzünde yaşayana göklere havalanana

Sevene sevilene

Yaralı yüreklere yaşlı gözlere

Kollarını açana yoluna baş koyana 

Sen ki bir umut 

İnsanlığa verilen armağan 

Sen karanlıkların sonu 

Aydınlık yarınların sonsuz sabahı 

Ve sen ruhlara meltem saran

Dillerden düşmeden anılan 

Doyumsuz bir şiirsin Muhammedim', 'Buluştuk omuz omuza Her birimiz bir yerlerde  Salavat ve tekbirlerle Diller dönünceye nefesler yetinceye Biraz hüzün biraz sevinçle Nidaları...', ARRAY['Türk Edebiyatı','Şiir','Can Abdullah Yıldırım']::text[], 8.5, '{"poet":"Can Abdullah Yıldırım","poet_slug":"can-abdullah-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gul-yureklim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkına Varabildimse', 'farkina-varabildimse-erhan-azbent-km6a9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aslında gözlerinin aslını bildiğim yalan

Hiç değmedi ellerim saçlarına

Sadece bakışını hatırlar gibiyim...

Seni düşlerimde izledim bir kaç kez

Sakinliğini haşlar gibiydi yüreğim

Farkına varabildimse,farkına varamadığım yalan...

Uykularına sızmışım,

Rüyaların gerçekse gerçekler yalan

Sonra bir tebessümle bakmışım yanaklarına

Gamzelerinin içinden dudaklarına eser gibiyim...

Sabahlarıma doğdun bir çok kez

Sensizliği taşlar gibiydi,

Haykıran sessizliğim.

Farkına varabildimse,farkına varamadığım yalan...

                                       04/aralık/''97  Emirdağ', 'Aslında gözlerinin aslını bildiğim yalan Hiç değmedi ellerim saçlarına Sadece bakışını hatırlar gibiyim... Seni düşlerimde izledim bir kaç k...', ARRAY['Türk Edebiyatı','Şiir','Erhan Azbent']::text[], 8.5, '{"poet":"Erhan Azbent","poet_slug":"erhan-azbent","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/farkina-varabildimse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-black-tears-obtpq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç gitmeyecek sandığım bir gün doğdu

Asla ihanet etmez dediğim bir ışık 

Aydınlattı gece sevgililerin gezdiği 

O günahkar,sessiz sokakları

Bir teneke kutudaki fesleğen saflığında

Üzerinde çıplak ayaklı,yalnız

Varoş çocukları koştu,ağladı,güldü

Kaldırımlarında bin bir renk

Yağan yağmurun damlalarında

Işık oyunları yaparken usulca güneş

Hiç terketmeyecek sandım beni

Bir sis gibi tünedi çukur şehrin üzerine

Pencerede ağlayan yalnız kızlar

Kapkara yüreklerini aydınlatsın diye

Gözyaşlarını kurutsun diye

Asılıp beklerdi

Onlar da derdi:

''Terketmeyecek ışık bizi''

Geçti zaman izinsiz

Ve bir ilk yaz tazeliği sindi şehre

Okyanusun derinliklerindeki 

Taze sular gibi sardı etrafı

Yumuşacık,aşık olunacak bir hava

İçlerine çektikleri bir yudumuyla herkes sarhoştu

Ve olan oldu

Battı gün,açtı peçesini utanmaksızın

O beyaz tenli güzel kadın edasıyla ay

Ve herkes hep bir ağızdan 

Ellerinde meşalelerle 

Bir şarkı mırıldanıyorlardı

Uzaklarda, o şehrin mor sokaklarında

''Güneş battı, o herkesin güvenip inandığı

Işığın bize ihanet ettiğini hissediyoruz..

Bir gün her şey, böyle bırakıp gidecek bizi..

Tıpkı bize umut verip, sonra kaçan gün gibi.''', 'Hiç gitmeyecek sandığım bir gün doğdu Asla ihanet etmez dediğim bir ışık  Aydınlattı gece sevgililerin gezdiği  O günahkar,sessiz sokakları ...', ARRAY['Türk Edebiyatı','Şiir','Black Tears']::text[], 8.5, '{"poet":"Black Tears","poet_slug":"black-tears","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ihanet-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur Biraz Daha Zaman', 'ne-olur-biraz-daha-zaman-haldun-uras-dmfmr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyorum suçluyum sevgilim.

Sana sevgimi daha sık söyleyemedim.

Saçlarını okşayıp,

Kokunu içime sindiremedim.

Ne olur biraz daha zaman.

Sürgit bir yaşam kavgası mı,

Yoksa; 

Zorlu bir ekmek kavgası mı desem? 

Neden bilmem.

Sanki çok varmış gibi,

Zamanımızı başkalarına satarız.

Ve kendimiz için yaşayamayız.

Günler günleri kovalar,

Ümitler ertelenir.

Yapacaklarımız hep yarınlardadır.

Gün gelir 

Yüreğini pişmanlıklar sararsa.

Gözlerin 

Tatmakta geciktiğin güzellikleri arar da,

Birşeylerin özlemi içini sararsa

İşte o zaman,

Sevdiklerine sarıl.

Onlara uzun uzun bak.

Sanki yarınlar yokmuş gibi.

Akşamın karanlığında,

Yıldızlar hani bazen kayar ya,

İşte o zaman

Başını gökyüzüne kaldır ve fısılda.

Ne olur biraz daha zaman.', 'Biliyorum suçluyum sevgilim. Sana sevgimi daha sık söyleyemedim. Saçlarını okşayıp, Kokunu içime sindiremedim. Ne olur biraz daha zaman. Sür...', ARRAY['Türk Edebiyatı','Şiir','Haldun Uras']::text[], 8.5, '{"poet":"Haldun Uras","poet_slug":"haldun-uras","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ne-olur-biraz-daha-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar', 'cocuklar-akin-kelesoglu-fk5od', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dileyin çocuklar

Ne dilerseniz

Sizler için

Kocaman bir güneş topu

Gündüz oynayacağınız

Bir ay dede

Beraber yatacak kucağınızda

Yıldızlar 

Milyonlarca ceplerinizde

Badem ağaçları

Çiçekler açacak

Her sabah

Karyolalarınızda

Yunuslarla yarışacaksınız

Okyanuslarda

İsteyin çocuklar

İsteyin...', 'Dileyin çocuklar Ne dilerseniz Sizler için Kocaman bir güneş topu Gündüz oynayacağınız Bir ay dede Beraber yatacak kucağınızda Yıldızlar  Mi...', ARRAY['Türk Edebiyatı','Şiir','Akın Keleşoğlu']::text[], 8.5, '{"poet":"Akın Keleşoğlu","poet_slug":"akin-kelesoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cocuklar-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımın Ruhsatı', 'askimin-ruhsati-selcuk-sahin-qzlpk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bırakın kalsın yakamda 

o eski akşamların yakamozu..

Büyük kadırgalar şişirir yüreğimi

Sevkulceyşim varmaktır yakamoza..

Uzakta doluydu serzenişleri

gırlağıma,muzaffer..

Arşa açılan baplara kaçar yüreğim.

Mihnetim**dinmez,

acılar mezun olmaz bende..

Aşkımın ruhsatı o eski

                            akşamların yakasında...

*sevkulceyş:strateji

**mihnet:sıkıntı,üzüntü

06.06.2001 Erenköy/İstanbul', 'Bırakın kalsın yakamda  o eski akşamların yakamozu.. Büyük kadırgalar şişirir yüreğimi Sevkulceyşim varmaktır yakamoza.. Uzakta doluydu serz...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Şahin']::text[], 8.5, '{"poet":"Selçuk Şahin","poet_slug":"selcuk-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/askimin-ruhsati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gök Gürültüsü Tanrısı Amoko', 'gok-gurultusu-tanrisi-amoko-black-tears-4kowq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bükme dudaklarını öyle

Acı mı vereceğini sanıyorsun bana 

O bal damlayan dudaklarınla? 

Kestiğim umutlarımın kanlarıyla

Kıpkırmızı oldu ellerim

Hayallerim bir kuş gibi tünedi baş ucuna

Bak sağ omzuna,işte ben oradayım

Ey Amoko! 

Estirdiğin rüzgarların,

Yağdırdığın yağmurların,

Düşürdüğün yıldırımların adına

Hangi aşk verebilir senden daha fazlasını bana? 

Gökyüzüm oldun

Bir aydınlanıp, bir sönüyorsun

Güneşinle,ayınla

Göz kırpıyorsun bana 

Uzaktaki yıldızlarınla...', 'Bükme dudaklarını öyle Acı mı vereceğini sanıyorsun bana  O bal damlayan dudaklarınla?  Kestiğim umutlarımın kanlarıyla Kıpkırmızı oldu elle...', ARRAY['Türk Edebiyatı','Şiir','Black Tears']::text[], 8.5, '{"poet":"Black Tears","poet_slug":"black-tears","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gok-gurultusu-tanrisi-amoko-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Yüzünden', 'senin-yuzunden-akin-kelesoglu-01odk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duygularımın doruğundasın bu akşam

Bu akşam sanki üzerimde yorgan

Bir plâğın iki yüzü

Birkaç bira

Üç beş küfürde de olsa isyanım

Bu kez sen

Kötü akşamımdasın

Sigaramın dumanı namuslu tüter

Gelmiyorsam

Uzuyorsa geceler bazen

Kahroluyorsam

Çiçekleri koparmamışsam dallarından

Acıdığımdan değil

Her şey

İnanki

Senin yüzünden.', 'Duygularımın doruğundasın bu akşam Bu akşam sanki üzerimde yorgan Bir plâğın iki yüzü Birkaç bira Üç beş küfürde de olsa isyanım Bu kez sen ...', ARRAY['Türk Edebiyatı','Şiir','Akın Keleşoğlu']::text[], 8.5, '{"poet":"Akın Keleşoğlu","poet_slug":"akin-kelesoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-yuzunden-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülnihâl', 'gulnih-l-necdet-bayindir-4pnyl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kim koydu aramıza seti? Nedir ki bu hal? 

Set üstü set ördükçe yıkamadık Gülnihâl! 

Ortak neyimiz varsa yaktık, sildik, süpürdük

Bir an olsun göz göze bakamadık Gülnihâl! 

Köktenci kondu yaftam sana dediler solcu 

Aynı incitti bizi ayrı iki ok ucu

Şeytan vesvesesinden bıkamadık Gülnihâl! 

Ayrılık sende sola bende sağa sinmişti 

Yürek sancısı ancak el tutunca dinmişti

Kibirimizle başa çıkamadık Gülnihâl

Sormadık hiç kim haklı? Ayrıldıkça ayrıldık 

Ufaldıkça ufaldık, savruldukça savrulduk

Ayrılığı zindana tıkamadık Gülnihâl

Çatışırken beyinler yüreğimiz uyudu 

Ne kinimiz azaldı ne sevdamız soğudu

Tek bir çatı, aynı gök: tek dileğim buyudu

Giderken yedi göğü tepeme yık Gülnihâl

Yetmedi bize yıllar onca dersi almadık 

Yedikçe acıktık biz, bize; hırsı almadık

Birbirin çeken iki kutbun tersi olmadık 

Kaim olan firaksa nar ol da yak Gülnihâl

Ne sen söyledin, ne ben diyebildim hasreti

Özledik, özledikte bağladık basireti

Anlatamadığım bu aşkın tek alameti

Gözümdeki resmine iyice bak Gülnihâl 

Geçti mevsimi düştü gönüldeki yapraklar

Saramadın ya sarsın sarmalasın topraklar

Kâr eylemez ölürsem çekilen ahlar vahlar

Badem gözlü aşkına ağıtlar yak Gülnihâl', 'Kim koydu aramıza seti? Nedir ki bu hal?  Set üstü set ördükçe yıkamadık Gülnihâl!  Ortak neyimiz varsa yaktık, sildik, süpürdük Bir an olsu...', ARRAY['Türk Edebiyatı','Şiir','Necdet Bayındır']::text[], 8.5, '{"poet":"Necdet Bayındır","poet_slug":"necdet-bayindir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gulnihal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Senden İbaret', 'her-sey-senden-i-baret-necdet-bayindir-ag53a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kim anlatmış ki aşkı ben tercüme edeyim

Yılda bir gece olsun yumsam gözüm, düşte gel

Senle gördüm cihanı, sensiz canı n’edeyim

Yıkacağın bend olsam okyanusu aşta gel

Yok, tutunacak dalım, türbedarım bu aşka

Destan Ferhat’ı bilir, benden kopan bambaşka

İçimde ölen başka, dilde yaşayan başka

Düşman ol, yık ufkumu, şimşek gibi çakta gel

Her şey senden ibaret, ayrıntıyım hayatta

Gayrı dolsun vadem hatır defterine bakta

Zebun olan ömrümün kalanını sil at da

Azrail ol ansızın hiddetini saçta gel', 'Kim anlatmış ki aşkı ben tercüme edeyim Yılda bir gece olsun yumsam gözüm, düşte gel Senle gördüm cihanı, sensiz canı n’edeyim Yıkacağın ben...', ARRAY['Türk Edebiyatı','Şiir','Necdet Bayındır']::text[], 8.5, '{"poet":"Necdet Bayındır","poet_slug":"necdet-bayindir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-sey-senden-ibaret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-aysun-erat-ur10b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzak olmak ne kötü düşlerden.

Düşerken hele...

Kimseler karşılamazken,

Sen karşıla beni.

Açık tut kapılarını.

Hep ama..

Üşümesin yüreğim bu soğukta.

Korkuyorum deli gibi.

Çıldırmış bir hızla atıyor kalbim.

Bu nasıl bir dünya? 

Aklım ermedi,

Ermeyecek..

Anlat bana, neler oluyor? 

Korkacak bir şey yok de.

Geçecek, geçecek...

01/2006', 'Uzak olmak ne kötü düşlerden. Düşerken hele... Kimseler karşılamazken, Sen karşıla beni. Açık tut kapılarını. Hep ama.. Üşümesin yüreğim bu ...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/korku-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Kanatlı Melekler', 'tek-kanatli-melekler-black-tears-zpwvx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bulunması zor bir aşkın

Tek kanatlı melekleri

Yalnızca sarılarak uçabilirken

Ya ölüm

Ya da ölümsüz bir ayrılık

Yakalayıp onları kanatlarından

Uzaklara fırlatmalı

Esen her rüzgarda

Kuru bir yaprak misali

Oradan oraya savurmalı 

Savurmalı ki

Birbirlerinin adını sayıklasınlar

Birbirlerinin kokusunu arasınlar

Ve en önemlisi

İki kanatlı olmadan

Uçamayacaklarını

Kavrasınlar...

Ey insanoğlu! 

Bir şeyin değerini anlaman için

Hep onu kaybetmen mi gerekir?', 'Bulunması zor bir aşkın Tek kanatlı melekleri Yalnızca sarılarak uçabilirken Ya ölüm Ya da ölümsüz bir ayrılık Yakalayıp onları kanatlarında...', ARRAY['Türk Edebiyatı','Şiir','Black Tears']::text[], 8.5, '{"poet":"Black Tears","poet_slug":"black-tears","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tek-kanatli-melekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Aşk Benim', 'adim-ask-benim-necdet-bayindir-lwn0b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaradılışta varım varlığım kanıt Var’a

Gönülde han yıkmayan eremez asla kâra

Edhem gibi gâh düşte gâh çatıda iz sürsen

Saklıyım ben İbrahim! düş de gel hemen nara

Bilemem ateşten mi yoğurulmuş hamurum 

Nice canlar tav oldu bendeki çılgın hara 

Yazsan ciltler dolusu söylesen beste beste 

Yine anlatılamam sığmam yüz bin satıra

Ürkek, nazlı bir ceylan gibi görünsem bile

Aşık katlederim ki adı şaire vara

Mantık mantıksızlıktır gönülde ben olunca

Akıl esirimdir ki hazır dünden firara

Toyluk rüzgârın aşıp varsan ömrü ahire

Kadim olacak benim gelirim hep hatıra

Çeken kim ki kahrımı? Sen talipli olasın

Zaman varken kaç kurtul gönül düşmeden dara

AŞK VE YÂR 

Yâr ki yar ise yârdır, aşk ecel ise vardır

Nice hana, sultana diz çöktürdü bu yara', 'Yaradılışta varım varlığım kanıt Var’a Gönülde han yıkmayan eremez asla kâra Edhem gibi gâh düşte gâh çatıda iz sürsen Saklıyım ben İbrahim!...', ARRAY['Türk Edebiyatı','Şiir','Necdet Bayındır']::text[], 8.5, '{"poet":"Necdet Bayındır","poet_slug":"necdet-bayindir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/adim-ask-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-akin-kelesoglu-zyl5u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen

Bir gece karanlığında

Çelik bir bilya gibi 

Yatağında

Bir ses çığlığında

Uzak

Çok uzaklarda

Bir of çeksem

Karşıki dağlar yıkılır...', 'Sen Bir gece karanlığında Çelik bir bilya gibi  Yatağında Bir ses çığlığında Uzak Çok uzaklarda Bir of çeksem Karşıki dağlar yıkılır......', ARRAY['Türk Edebiyatı','Şiir','Akın Keleşoğlu']::text[], 8.5, '{"poet":"Akın Keleşoğlu","poet_slug":"akin-kelesoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-744-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş', 'serzenis-aysun-erat-04bse', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Baharda gitseydin mesela

Dallar dolarken çiçek çiçek

Yeşil bir sevda hücum ederken dağa taşa

Bu kadar koymazdı adama

Avunurdum papatyaların arsızlığıyla

Deliliğe vururdum sensizliği

Bahar çarptı derdim de kandırırdım kendimi.

Bu kadar soğuk olmasaydı en azından

Üşümeseydim bu kadar

Olmadı böyle.

Hiç olmadı ki! ...

01/2006', 'Baharda gitseydin mesela Dallar dolarken çiçek çiçek Yeşil bir sevda hücum ederken dağa taşa Bu kadar koymazdı adama Avunurdum papatyaların ...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/serzenis-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Fayton', 'beyaz-fayton-akin-kelesoglu-flmeu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Pas tutmuş barakaların

Kapılarından fırlar

Gecekondu ihtilâlcisi

Tozkoparan çocuklar

Pas tutmuş gecelerin

Gece yarılarında

Binmişler beyaz faytona

Islık çalar

Dudakları

Kırbacı

Yüreği

Uçarcasına koşarken atlar

En zeytinyağlı caddelerinde

İstanbulun

Ellerinde gece fenerleri

Binmişler beyaz bir faytona

Uzayıp giden yollarda

Adım adım

Çalarlar özgürlüğü

Biter o gecenin kırbacında

İstanbul

İstanbul

O gecenin kırbacında.', 'Pas tutmuş barakaların Kapılarından fırlar Gecekondu ihtilâlcisi Tozkoparan çocuklar Pas tutmuş gecelerin Gece yarılarında Binmişler beyaz f...', ARRAY['Türk Edebiyatı','Şiir','Akın Keleşoğlu']::text[], 8.5, '{"poet":"Akın Keleşoğlu","poet_slug":"akin-kelesoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/beyaz-fayton-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşama Sevinci', 'yasama-sevinci-ali-taskiran-avu26', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yaşamak seninle olunca güzel

acılar tatlanır gülüşünde,

sanırım dünya cennettir bana

ekmek kavgasını unutur giderim

masallar ülkesinde oynaşırım seninle

imkansıza inat,koşarım bilinmeze

neden niçin diye sormayın bana

namerde  inat savaşırım gerçek yalanla

yürür giderim gizemin koynuna

bakarım görüp de tadamadıklarıma

eksik kalan olsa da hayatımda

kalkıp giderim yine de seninle son defa ölüme', 'yaşamak seninle olunca güzel acılar tatlanır gülüşünde, sanırım dünya cennettir bana ekmek kavgasını unutur giderim masallar ülkesinde oynaş...', ARRAY['Türk Edebiyatı','Şiir','Ali Taşkıran']::text[], 8.5, '{"poet":"Ali Taşkıran","poet_slug":"ali-taskiran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasama-sevinci-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Senfoni', 'bitmeyen-senfoni-ali-taskiran-9zl2p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'korkaklığın ya da cesaretin bedelini yaşarsın

seçimi sen yaparsın bir başkası değil

bir başka sonbaharda başlarsın yaşayamadıklarına

ama çok geç olmuştur artık

sen o eski sen değilsin

ne yazlar ne kışlar geçti üzerinden

nice tatlar nice acılar karıştı birbirine

o eski dostlar gitti şimdi birer birer

ne kaldı geriye yaşanan anlardan başka

bir varmış bir yokmuş bitiverdi o güzelim yıllar

herşeyin sonu olduğu gibi bunun da sonu geldi

giden gelmez artık geri hoşçakal sevgilim

ölene kadar yine de sevmeye devam', 'korkaklığın ya da cesaretin bedelini yaşarsın seçimi sen yaparsın bir başkası değil bir başka sonbaharda başlarsın yaşayamadıklarına ama çok...', ARRAY['Türk Edebiyatı','Şiir','Ali Taşkıran']::text[], 8.5, '{"poet":"Ali Taşkıran","poet_slug":"ali-taskiran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bitmeyen-senfoni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avucumuzdan Uçan Bir Kuştu Gençlik', 'avucumuzdan-ucan-bir-kustu-genclik-ali-taskiran-rv6ax', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sevmeleri  geciktirdik

hep başka baharlara bıraktık

ne umduk ne bulduk

neyi bekledik durduk 

düşümüzü gerçek kılmak

bu kadar zor muydu 

gençtik güzeldik enerji doluyduk

nelere gücümüz yetmezdi ki

dağları devirir okyanusları geçer

bütün engelleri aşar

isteseydik 

cennet yapardık bu güzel dünyayı', 'sevmeleri  geciktirdik hep başka baharlara bıraktık ne umduk ne bulduk neyi bekledik durduk  düşümüzü gerçek kılmak bu kadar zor muydu  genç...', ARRAY['Türk Edebiyatı','Şiir','Ali Taşkıran']::text[], 8.5, '{"poet":"Ali Taşkıran","poet_slug":"ali-taskiran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/avucumuzdan-ucan-bir-kustu-genclik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalemim sana gebe', 'kalemim-sana-gebe-mikdat-bal-xylrs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalemim sana gebe bir gün seni yazacak

Mürekkep damla damla sessizliği bozacak

Aleme haykırarak seni takdim ederek

Sevinecek tek benim, diğerleri kızacak', 'Kalemim sana gebe bir gün seni yazacak Mürekkep damla damla sessizliği bozacak Aleme haykırarak seni takdim ederek Sevinecek tek benim, diğe...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kalemim-sana-gebe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evet!', 'evet-sevinc-kavuk-88x3m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Evet! 

Kadınım

Hem istisnasız Atatürk hayranı

ve toplumun da kimliği kayıtsız, şartsız, istisnasız.

Tanrım tek, yurdum yeryüzü, ulusum renk renk,

ibadetim zevk dolu ve binlerce türden...

evet

tanışıyoruz,

ortaklığımız var seninle

havaya, suya, toprağa,

hortlaklığımız var seninle,

sen onun enstrümani ben bununki ile,

oyun oynar gibi.

dilimiz kuruyor şu yok,

nefesimiz kesiliyor hava yok,

bedenimizi örtmeye toprak az, beton çok,

suskun bir gariplikte....

Ortaklığımız yine şekillendi,

ben ama hiç buna ortak olmadan,

kadere ortağız şimdi seninle, sızıya, sırra...

Nefesimiz kesiliyor,

kesecek kelle arıyoruz,

dilimiz kuruyor,

küfürler arıyoruz,

umarsızlığı bile kıyafetlendik,

yine de bak...

şimdi...

biz birer yğın olduk...

insanlığın tüm cevherleriyle üstelik! 

Haziran 2004', 'Evet!  Kadınım Hem istisnasız Atatürk hayranı ve toplumun da kimliği kayıtsız, şartsız, istisnasız. Tanrım tek, yurdum yeryüzü, ulusum renk ...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/evet-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düet 1', 'duet-1-fatma-guven-xbvkb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu sevda hep sürse

ben hep gelsem 

gözlerim aramasa başka diyar

ellerin hep orda kalsa

sıcaklığın bende kalsa

bir masal

bir rüya gibi

bilirim düşler asılı kalır

sevda nakışlarında

bilirim feryadım yaşama

ve yaşanmamışlarıma

umutlar yüreğime dolar seninle

yağar yağmur damlaları gibi

imkansızlar elimde dönüşür

bir sihirli değneğe

yaşamım,can katarım ömrüne

umut verir bana sendeki sevgide

can 

yanar tutuşur bu yürek 

dur dedin

susturdun beni de

son sözü söylemedim daha

 neden aşmazsın sevgide

çevrelersin kendini

bir mahkum gibi

esir olma, zevklere

can bir nefeslik canı hissette

ellerine vereyim ruhumu

ruhunu istedim hep

 ruhsuz bir sevdaya yelken açmadım 

hazlar kervanına gütmedim bedenimi

 sen ne zaman açarsan ruhunu

o zaman aldım sendeki sana ait ne varsa

B.Ünver''e saygılarımla', 'bu sevda hep sürse ben hep gelsem  gözlerim aramasa başka diyar ellerin hep orda kalsa sıcaklığın bende kalsa bir masal bir rüya gibi biliri...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/duet-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düet 2', 'duet-2-fatma-guven-5bm9o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kimsin sen

nereden geldin mekanıma

zaman seni getirdi bana

bir hesabı mı vardı benle,yoksa senle

geri döner tekrar başa

yeniden geliriz bulunduğumuz yere

zehir olsa içerim sevgi pınarından

 akıl ermez oldu bu sırra

bir çeşme olmak isterdim

 erciyes’ in koynunda

sadece sevda içsin suyumdan

 üstünde bilinmez iki ad kazılı

biri can biri canan

yaşanmış mıydı bu masal

yoksa dillerde mi dolaştı ruhları

tapmak adına mı sunuldu

sunaklık adına can çeşmesi

can tapınak oldu bu sevdaya

sevdayı bilmeyen kem gözlere

görünmez sultanın izniyle

on emir bilirdim eskiden

 şimdi bin emir bilirim

sevda dilinden

 yandım, yandı bu beden

sevda diliylen

 hangi yöndür diye sorsalar her gün

gün batımlarımda

uzandığın; 

tanımsız derim uzandığım yön

B.Ünver''e saygılarımla', 'kimsin sen nereden geldin mekanıma zaman seni getirdi bana bir hesabı mı vardı benle,yoksa senle geri döner tekrar başa yeniden geliriz bulu...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/duet-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düet 3', 'duet-3-fatma-guven-z1odv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'susar an gelir konuşmaz bu beden

alır başımı giderim sonsuz ufuklara

ben eririm yok olurum cananda

o ha orda, ha burada

özengisinde mıhlanmış yüregim

ruh aynası oldu can canda

dün seyistim yolun da

şimdi yollar oldu ellerinde sevdam

bana sorma ruh mu önde

beden mi 

bilse yürek çıkmazları

gecenin karanlığında olur mu seninle

ne bir adım önde ne bir adım beride

her çıkmazın bir açarı vardır

yürek aynana bak seslen de

yol gösterir sana git, gidebilirsen

uzanmış buselerin önünde

uzanmaksa bedene

gönül asla gitmez yollara

karlar yağar yollar uzar gider

 uzanmamak adına bedene

bir garip duygulardayım

hepsi sarmalandı bedenimde

hem gel der yüreğim hem gelme

korkar oldum ben kendimden

ne ister nereye götürür

bir anlaşılamaz düştüm derde

Düet 1-2-3 ''e emeği geçen  değerli arkadaşıma sonsuz sevgi ve saygılarımı sunarım.

B.Ünver''e saygılarımla', 'susar an gelir konuşmaz bu beden alır başımı giderim sonsuz ufuklara ben eririm yok olurum cananda o ha orda, ha burada özengisinde mıhlanmı...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/duet-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hissetmek', 'hissetmek-canan-motorcu-xxsvk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine seni düşündüm,

Tüm şirinliğinle

Düşüverdin yüreğime...

Beni sarıp sarmalayışın

Hayatımsın artık deyişin

Canı gönülden sevişin

Filim şeridi gibi akıverdi.

Dans edişimizi hatırlamam

Burdu en çok beni,

Birbirimize hiç değmeden

Hayaller arasında raksetmiştik.

Sonra...

Sonra iç çekmeler içinde

Sarsılarak uyandım,

Biz seninle

Hiç beraber olmamıştık ki

Hiç dokunmamıştık birbirimize

Parmaklarımız bile değmemişti.

Ama öylesine hissetmiş

Öylesine duyumsamıştık ki,

Belkide yıllarını birlikte geçirenlere bile

Nasip olmamıştı böyle bir bütünleşme.

05:35  22/01/2006', 'Yine seni düşündüm, Tüm şirinliğinle Düşüverdin yüreğime... Beni sarıp sarmalayışın Hayatımsın artık deyişin Canı gönülden sevişin Filim şer...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hissetmek-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk=Özlem', 'ask-ozlem-canan-motorcu-xaz2r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen hissetmek de yeter kişiye

Aşk ille de dokunmak değildir.

O tatlı, o acı özlem duygusu bile

Aşkla baştan sona bütünleşmektir

21:59  25.01.2006', 'Bazen hissetmek de yeter kişiye Aşk ille de dokunmak değildir. O tatlı, o acı özlem duygusu bile Aşkla baştan sona bütünleşmektir 21:59  25....', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Ahh Çektiren Kadın...!', 'bana-ahh-cektiren-kadin-ertan-akbayrak-9bqq8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine vuruldum bu gece...

Yine vurdun beni,kahrolası 

Kan aksın gözlerimden

Bana ah çektiren kadın...

Yine yordun bu gece...

Yine yoruldum

Uyuşsun bedenim

Bana ah çektiren kadın...

Yine sevdim bu gece...

Yine en derin...

Kahrolsun bu kederim...

Bana ah çektiren kadın...

Yine sabah oldu bu gece...

Yine hep sen doldu yüreğim

Olmaz olsun böyle kaderim

Bana ahhh  çektiren kadın...!', 'Yine vuruldum bu gece... Yine vurdun beni,kahrolası  Kan aksın gözlerimden Bana ah çektiren kadın... Yine yordun bu gece... Yine yoruldum Uy...', ARRAY['Türk Edebiyatı','Şiir','Ertan Akbayrak']::text[], 8.5, '{"poet":"Ertan Akbayrak","poet_slug":"ertan-akbayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bana-ahh-cektiren-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-mehmet-sait-akkus-jaxf0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne şiirler ne şarkılar

Okuyacam senin için

Ne zevkler ne acılar

Tadacağım senin için

Ne dizeler ne notalar

Dökecem senin için

Ne kalemler ne mısralar

Yazacağım senin için

Ne canları ne bedenler

Asacağım senin için

Nice gözler nice diller

Yakacağım senin için

Ne köşkleri ne saraylar

Yapacağım senin için

Ne kilimler ne halılar

Dokuyacam senin için

Ne hazanları ne kışlar

Yaşıyacam senin için

Nice ayları ne yıllar

Bekliyecem senin için

Ne zambaklar ne çiçekler

Ekeceğim senin için

Ne leylaklar ne sümbüller

Dereceğim senin için

Ne saatler ne dakkalar

Soracağım senin için

Ne zamanlar ne asırlar

Bekleyecem senin için', 'Ne şiirler ne şarkılar Okuyacam senin için Ne zevkler ne acılar Tadacağım senin için Ne dizeler ne notalar Dökecem senin için Ne kalemler ne...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/senin-icin-147-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua XL', 'dua-xl-erol-dal-pz30q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gerçek zenginlikler

Gerçek mekanlardadır.

Sahte mutluluklar

Zahiri topraktan ibarettir.

Rabb beni; 

Yarattıklarının aslıyla buluştur

Aslımın aslıyla da; 

Kavuştur.

                                     Amin.

              2006/Mekan', 'Gerçek zenginlikler Gerçek mekanlardadır. Sahte mutluluklar Zahiri topraktan ibarettir. Rabb beni;  Yarattıklarının aslıyla buluştur Aslımın...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dua-xl-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haziranda son bahar', 'haziranda-son-bahar-umran-aldic-ktb80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmurlar yağıyor gecelerime

Pencereleri zangırdatıyor rüzgarlar

Cehennemden çıkmış zebaniler misali

Ağaçlar uzatmış kollarını.

Neden yaparlar pencereleri? 

Ne görecek benim gibiler? dışar da

Yağmurdan,,,,,dökülen yapraklardan,

Puslu, yaslı bir sonbahardan başka.

Neden uyandım gece yarısı? 

Neden kalktım sıcacık yatağımdan? 

Uyku ölüm sanki.....

Belki koparır acılardan....

Saat kaç? hangi gün? hangi ay? yıl? 

Tanrım ne zaman kaybettim zamanı

Kayıp gitti ellerimden yıllar? 

Unuttum aynaları...

Sebep neydi bütün bunlara? 

Ağaran saçlarıma, simsiyah bahtıma

Külü bile kalmamış bir ateşin başın da....

Takılmışım.....haziranda sonbahara.', 'Yağmurlar yağıyor gecelerime Pencereleri zangırdatıyor rüzgarlar Cehennemden çıkmış zebaniler misali Ağaçlar uzatmış kollarını. Neden yaparl...', ARRAY['Türk Edebiyatı','Şiir','Ümran Aldıç']::text[], 8.5, '{"poet":"Ümran Aldıç","poet_slug":"umran-aldic","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/haziranda-son-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Şair İşte Şiir', 'i-ste-sair-i-ste-siir-huseyin-erdogan-51pa0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'işte şair işte şiir

dizelerimde her şey var aşka dair

sevmesini ve sevilmesini bilenlere

hele ben sevda yaşıyorum diyenlere

mısralarım birer vitamindir

her bir dizem dopdoludur

farklı vitaminlerle mesela A B C

eğer okursanız şiirlerimi

vallahi billahi böylece

ne grip olursunuz ne de nezle

zaten şiirimi de

hem besleyeceğim sevgimle

hem de sağlıklı yaşayatacağım ömrünce

sevgi en temel gıdadır bence

ya sizce? aksini söyleyen var mı içinizde? 

yazdığım her bir dizem şiirim için

onu doruklarda tutacağım ölünceye değin

bana her sevdiğini söyleyişinde

kendimi daha genç dinamik enerjik hissediyorum

biliyor musunuz sevgili şiirseverler? 

ben şiirimi sevgimle sıhhatli besliyorum

onun bütün ihtiyaçlarına aşkımla cevap veriyorum

davranışlarımla hareketlerimle de bunu ifade ediyorum

bilsin herkes duysun tüm dünya ben şiirimi çok seviyorum

hepiniz şimdi anladınız değil mi aşkın sevginin değerini? 

sevenlere sevilenlere sevda adına ben de teşekkür ediyorum

                                                        26.01.2006

                                                    Hüseyin Erdoğan', 'işte şair işte şiir dizelerimde her şey var aşka dair sevmesini ve sevilmesini bilenlere hele ben sevda yaşıyorum diyenlere mısralarım birer...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/iste-sair-iste-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satılık.', 'satilik-tulay-i-cen-lpr0c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayallerim artık satılık,

Seyyar  satıcının tezgahında,

Ve ya

Bir  mağazanın vitrininde..

Satılık  hayallerim  var,,,

Gercekleşmeyen, hayaller.

Satılık..

Umudumdu  hayallerim,

Yaşamak için tutunduğum daldı.

Bana  yar olmadı hayaller.

Satıyorum..

Sat..sat... sattım gitti...', 'Hayallerim artık satılık, Seyyar  satıcının tezgahında, Ve ya Bir  mağazanın vitrininde.. Satılık  hayallerim  var,,, Gercekleşmeyen, hayall...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/satilik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülsün benim için gül', 'gulsun-benim-icin-gul-halil-colak-dloic', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülsün benim için gül

Hep gül olarak kal

Hayatın boyunca hep gül

Yaşamdan tat al

Gönlünde hep sevinç olsun

Kederden dertten uzak kal

Halil Çolak 25.1.2006 Ankara', 'Gülsün benim için gül Hep gül olarak kal Hayatın boyunca hep gül Yaşamdan tat al Gönlünde hep sevinç olsun Kederden dertten uzak kal Halil Ç...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gulsun-benim-icin-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kansız Bir Pençenin Tokluğu Kadar', 'kansiz-bir-pencenin-toklugu-kadar-seckin-turk-e84yx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kansız bir pençenin tokluğu kadar

sevgisiz kalır acımasız sevdaların herbir tarafı! ! 

öyle ya

hayat kanatabildiğin kadar güzeldir,

dişlerini geçirebildiğin,

suyunu sıkabildiğin! ! 

öyle kıyısında bekleyip de elini sokmazsan, 

denizinde yüzmezsen,

başka bir avcının hançeri 

saplanıverir gövdene! ! 

acısını hissedene kadar, yemeye başlamıştır seni hayat! ! 

Oysa sevmesini bilsek geçer mi hiç o duvardan

aciz bostan korkuluğunun

kendinden aciz hançeri?', 'kansız bir pençenin tokluğu kadar sevgisiz kalır acımasız sevdaların herbir tarafı! !  öyle ya hayat kanatabildiğin kadar güzeldir, dişlerin...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Türk']::text[], 8.5, '{"poet":"Seçkin Türk","poet_slug":"seckin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kansiz-bir-pencenin-toklugu-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ş i m d i', 's-i-m-d-i-ahmet-unal-cam-4zn5m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sonbaharda gelseydin,

Beni öyle görseydin; 

Hayalleri yıkılmış,

Ümitleri kırılmış.

Her şey,

Bir özür dileyince

Unutulurmuş gibi,

Tüm dertler bitmiş gibi

Yine içten gülseydin.

Unutupta geçmişi

İnan kanardım sana.

Yine terketmen için,

Fırsat tanırdım sana.

Şimdi,

Çok şey değişti

Gözüm açıldı benim.

Hiç boş yere sevinme

Ben eski ben değilim.

Şimdi,

Sen, eski kurşun yaram,

Sen, sönmüş bir sigaram,

Fotoğrafı yakılmış,

Unutulmuş hatıram.

Şimdi,

Orta halli gelirim,

İki odalı evim,

Bir de dünya güzeli,

Şipşirin sevdiğim var.

Ne gözü yükseklerde,

Ne kibirli-havalı,

Bir kahkaha yetiyor,

Yarım ekmek arası.

Uzandığım kapılar,

Ümitlere açılır.

Sevdiğim beni sever,

Gör, sensiz de yaşanır.', 'Sonbaharda gelseydin, Beni öyle görseydin;  Hayalleri yıkılmış, Ümitleri kırılmış. Her şey, Bir özür dileyince Unutulurmuş gibi, Tüm dertler...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/s-i-m-d-i-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Yeter', 'o-yeter-ali-kaybal-bxyaa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fincan içinde acı bir kahve sundular,

Kolayına iç, yorgunluğu alır deyu,

Fincanın içine telve, içimle dolar,

Bahtıma, çileli çıkar ayrılık yolu.

Durduramaz, önüme geçse bütün engeller,

Gözüme girse zalimin attığı oku,

Seni görmeye giden, ela bir göz yeter,

Getirir seni, teninden yayılan koku.

Dermani’yim, haykıramasam adını,

Dağlansa gövdem, ayırsalar kolumu,

Seni bulmaya giden, tatlı bir söz yeter,

Getirir seni, telinden salınan koku.', 'Fincan içinde acı bir kahve sundular, Kolayına iç, yorgunluğu alır deyu, Fincanın içine telve, içimle dolar, Bahtıma, çileli çıkar ayrılık y...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-mustafa-benkli-kn947', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Korku; acz eseri gelir bana,

Hep, buna dûçâr olmaktan korktum.

Korkuyla; ders verilir insana,

Utanç verilmemesinden korktum.

Zinâ, riyâ ve her kötü yana; 

Bu yolla varılmasından korktum.

Ne yapsan; bulunur kılıf ona,

Âr, hayâ tükenmesinden korktum.

Hakk''tan korkmamak ta var; bak sana! ...

Hep bu münâfıklıktan korktum.

Allah''tan korkmak mı; korkum? Hâşâ! ...

Rabbimden utanmamaktan korktm...', 'Korku; acz eseri gelir bana, Hep, buna dûçâr olmaktan korktum. Korkuyla; ders verilir insana, Utanç verilmemesinden korktum. Zinâ, riyâ ve h...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Benkli']::text[], 8.5, '{"poet":"Mustafa Benkli","poet_slug":"mustafa-benkli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/korku-118-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize öğrettin vatanı candan çok sevme sevdasını', 'bize-ogrettin-vatani-candan-cok-sevme-sevdasini-halil-colak-1lv5q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bize öğrettin vatanı candan çok sevme sevdasını 

Erzurum’um insanın gibi ak ve beyazsın 

Kahramanlığınla,cömertliğinle destanlaştın 

Dürüstlüğünle temizliğinle tarihte yer aldın

Sen mazısı karlar gibi beyaz temiz vatansın 

Aziziye tabyalarında dadaşın kahramanca direnişi 

Her ferdinin kalbinde vatan aşkı yanar yanardağ gibi 

Bize öğrettin vatanı candan çok sevme sevdasını 

Dünyaları verseler ferdin vermez bir çakıl taşı 

Halil Çolak 25.1.2006 Ankara', 'Bize öğrettin vatanı candan çok sevme sevdasını  Erzurum’um insanın gibi ak ve beyazsın  Kahramanlığınla,cömertliğinle destanlaştın  Dürüstl...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bize-ogrettin-vatani-candan-cok-sevme-sevdasini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ektiğimi Biçtim de', 'ektigimi-bictim-de-zeliha-ural-smqzx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni de arayan soran olmasın

Özle, hep kapılarda kalsın gözün

Pişmanlık olsun da son sözün

Ektiğimi biçtim de.

Umut et hep doğan güne

Hasret et sende hayaline

Kapılarından geçip te

Ektiğimi biçtim de

Her şeyi kitabına uydurdun

Sonunda aradığını buldun

Devran senindi, salla bayrağın

Ektiğini biçersin birgün.

Nedir ki aleme olsan da paşa 

Allahtan büyükmüsünki haşa

Arayıp sormadın geçen gün boşa

Ektiğimi biçtim de

Ne hatır bildin nede kıymet

Geçmişinden demi almadın ibret

Hesabını vereceksin bir gün elbet

Ektiğimi biçtim de

Ulu olur çınar ağacı 

Kibrini bırakta kendine acı

Pişmanlığın olsun son demdeki sancı

Kibrimi biçtim de

   Antoloji 1 şiir kitabından', 'Seni de arayan soran olmasın Özle, hep kapılarda kalsın gözün Pişmanlık olsun da son sözün Ektiğimi biçtim de. Umut et hep doğan güne Hasret...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Ural']::text[], 8.5, '{"poet":"Zeliha Ural","poet_slug":"zeliha-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ektigimi-bictim-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayır mı Şer mi?', 'hayir-mi-ser-mi-zafer-tugrul-sfdn3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu beşaret iyiye mi işaret,

Düçar olmuşum bir güzele

Yoksa kopmasın kıyamet

Kötü kelam etmeyem ezele

Asumanda rengarenk bir alaimisema,

Bulutlar dahi azimkârane

Hasbelkader kendim buldum,güç bela

Meğer deli gönlüm tutuşmuş gafilane', 'Bu beşaret iyiye mi işaret, Düçar olmuşum bir güzele Yoksa kopmasın kıyamet Kötü kelam etmeyem ezele Asumanda rengarenk bir alaimisema, Bulu...', ARRAY['Türk Edebiyatı','Şiir','Zafer Tuğrul']::text[], 8.5, '{"poet":"Zafer Tuğrul","poet_slug":"zafer-tugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayir-mi-ser-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haziranda son bahar 2', 'haziranda-son-bahar-2-umran-aldic-5neb5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidişin var ya o gidişin

Yağmur yağıyordu bardaktan boşanırcasına

Mecburum vatan borcu demiştin

Ayakların isteksiz geri geri giderken.

Ben katılmıştım sanki acıdan

Ne ağlıyor ne güle güle diyebiliyordum

Taş olmuştum kök salmıştım toprağa

Öyle duygusuz öyle çaresiz...

Fırtınalar koparken yüreğimde

Çığlık çığlığa bağırırken sesim içimde

Bakakalmıştım gidişine.

Olamaz olamaz dercesine.

Kabul edemedim gidişini o sonbahar gününde

Hiç kış gelmedi yağmadı karlar

Gecikti baharlar yazlar.

Ben hala o sokağın başında....

Kabullenseydim gidişini ağlasaydım doyasıya

Yaşasaydım yokluğunu..kış gelseydi sonra bahar

Geri gelirdin belki gittiğin yerden

Ben aynı olmasam da güle güle diyemediğim gibi

Hoş geldin diyemesemde gelirdin.

Gelirdin...artık  yasak... artık  yabancı olsan da...gelirdin.

Takılmasaydım O uğursuz sonbahar akşamına

Oturmasaydım  şimdi  külleri bile kalmamış.....

Bir zamanlar orman yangınlarına benzeyen

 O ateşin başında....', 'Gidişin var ya o gidişin Yağmur yağıyordu bardaktan boşanırcasına Mecburum vatan borcu demiştin Ayakların isteksiz geri geri giderken. Ben k...', ARRAY['Türk Edebiyatı','Şiir','Ümran Aldıç']::text[], 8.5, '{"poet":"Ümran Aldıç","poet_slug":"umran-aldic","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/haziranda-son-bahar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Nasıl Seviyorum', 'seni-nasil-seviyorum-yusuf-onder-bahceci-yueyt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni nasıl seviyorum,

Sende sevdin biliyorum,

Sabır sabır diyorum,

Mevla görelim neyler,

Neylerse güzel eyler.

Senden evvel ölürsem,

Seni Arasat''ta beklerim,

Benden evvel ölürsen,

Hergün mezarına gelirim,

Seni çok sevdim seni,

Seni sevdim be derim,

Sana dualar ederim,

Vallahi konuşurum seninle....', 'Seni nasıl seviyorum, Sende sevdin biliyorum, Sabır sabır diyorum, Mevla görelim neyler, Neylerse güzel eyler. Senden evvel ölürsem, Seni Ar...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-nasil-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelen Ağam Giden Paşam', 'gelen-agam-giden-pasam-zafer-tugrul-ldz75', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hâletiruhiyemiz bozulmuş,

Filhakika parlak değil ati,

Aman beyzadem,

Kötü kelama yoktur müsadem

Gelen ağam,giden paşam

Gözler mahmur,

Bir uykuya dalmışız ki gaflet uykusu

Bu ne perhiz bu ne lahana turşusu

Aman beyzadem,

Kötü kelama yoktur müsadem

Gelen ağam,giden paşam

Hayalperest bir siyaset,

Hasılıkelam reca ederim biraz hassasiyet,

Aman beyzadem,

Kötü kelama yoktur müsadem

Gelen ağam,giden paşam

Serencamımız hayır ola,

Başkoymuşuz Garb yola

Akl-ı selim olan kendin bula,

Aman beyzadem,

Kötü kelama yoktur müsadem

Gelen ağam,giden paşam....', 'Hâletiruhiyemiz bozulmuş, Filhakika parlak değil ati, Aman beyzadem, Kötü kelama yoktur müsadem Gelen ağam,giden paşam Gözler mahmur, Bir uy...', ARRAY['Türk Edebiyatı','Şiir','Zafer Tuğrul']::text[], 8.5, '{"poet":"Zafer Tuğrul","poet_slug":"zafer-tugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gelen-agam-giden-pasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek', 'cicek-sadik-kilicarslan-4yd9s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çiçek özlemi bendeki,

Korkarım incinmenden 

Budayamam yapraklarını.

Susuzluğunda,

Yağmur olmak isterim sana

Üşüdüğünde güneş 

Yanlızlığına dost

Bana sarıl isterim 

Toprağa sarıldığın gibi

Bende sal köklerini

Özluyorum işte,seviyorum....', 'Bir çiçek özlemi bendeki, Korkarım incinmenden  Budayamam yapraklarını. Susuzluğunda, Yağmur olmak isterim sana Üşüdüğünde güneş  Yanlızlığı...', ARRAY['Türk Edebiyatı','Şiir','Sadık Kılıçarslan']::text[], 8.5, '{"poet":"Sadık Kılıçarslan","poet_slug":"sadik-kilicarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cicek-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın Eğer', 'sen-varsin-eger-aynur-avci-bbgcr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen varsan eğer

İlkbahar yaz oluyor

Çiçekler buram buram

Özlem kokuyor

Yüreğim aşkını hep taşıyor

Sen yoksan eğer

Dört mevsim kış oluyor

Dereler taşıyor,çağlayan coşuyor

Mevsimler sevgisiz yaşıyor.

Gülen yüzüne muhtaç gözlerim

Senin dönmeni,hasretle beklerim

Sen varsan eğer

Geceler sevgiye doymuyor

Bak yakamozlar

Seninle dans ediyor

Sen yoksan eğer

Ay doğmuyor

Bak gökyüzü ağlıyor

Mevsimler sevgisiz yaşıyor

Gülen yüzüne muhtaç gözlerim

Senin dönmeni hasretle beklerim..', 'Sen varsan eğer İlkbahar yaz oluyor Çiçekler buram buram Özlem kokuyor Yüreğim aşkını hep taşıyor Sen yoksan eğer Dört mevsim kış oluyor Der...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-varsin-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Sefil Gezerim', 'boyle-sefil-gezerim-yusuf-onder-bahceci-fra4e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevdim olmadı,

Kalbim huzur bulmadı,

Benim çilem dolmadı,

Böyle sefil gezerim.

Yollara hep çıkarım,

Yollara hep bakarım,

Bu hayattan bıkarım,

Böyle sefil gezerim.

Hep yollara çıksan sen,

Hep yollara baksan sen,

Hâlin nedir bana desen,

Böyle sefil gezerim.

Yollar uzun dağlar var,

Şu kalbimde neler var,

Dilim hep adın söyler,

Böyle sefil gezerim...', 'Seni sevdim olmadı, Kalbim huzur bulmadı, Benim çilem dolmadı, Böyle sefil gezerim. Yollara hep çıkarım, Yollara hep bakarım, Bu hayattan bı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/boyle-sefil-gezerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Sesi', 'gecenin-sesi-aynur-avci-op0g0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aslan sütü değil içtiğim

Horozun sabah ötüşünü

Şarabın yudumunda dinliyorum

Şerefe diyorum yalnızlığımda

Vazodaki çiçeğe 

Kadeh kaldırıyorum sessizce

Dayanamayıp bana 

Eşlik edercesine çekirge

Kendi sesiyle şerefe diyor

Sanki bir şeyler söylüyor

Gecenin sessiz karanlığında

Yal   nız   lı   ğı   ma..', 'Aslan sütü değil içtiğim Horozun sabah ötüşünü Şarabın yudumunda dinliyorum Şerefe diyorum yalnızlığımda Vazodaki çiçeğe  Kadeh kaldırıyorum...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gecenin-sesi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolmuşum ben', 'kaybolmusum-ben-umran-aldic-hrn9w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağarmadığına bakma saçımın 

Acıyı neşe ye gizliyorum ben.

Ağlamadığına bakma gözümün

Acıyı mahşere saklıyorum ben.

Yaşamak hakkımdı şöyle gönlümce

Terketti mutluluk seneler önce.

Şaşıyorum beni taşıyan dize

Gençliği ihtiyar yaşıyorum ben.

Mutluluktan sanma geç gülüyorsam

Dertleri içimde taşıyorum ben.

Kahrını zulümle çekerken bile

Kalbimi kimseye kul etmedim ben.

Yaşamak hakkımdı şöyle gönlümce

Terketti mutluluk seneler önce

Şaşıyorum beni taşıyan dize 

Gençliği ihtiyar yaşıyorum ben.', 'Ağarmadığına bakma saçımın  Acıyı neşe ye gizliyorum ben. Ağlamadığına bakma gözümün Acıyı mahşere saklıyorum ben. Yaşamak hakkımdı şöyle gö...', ARRAY['Türk Edebiyatı','Şiir','Ümran Aldıç']::text[], 8.5, '{"poet":"Ümran Aldıç","poet_slug":"umran-aldic","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaybolmusum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Derdin Çaresi Sendedir Sende', 'bu-derdin-caresi-sendedir-sende-yusuf-onder-bahceci-6p9tv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi sana onbinlerce şiir yazsam bile ben,

Bilki senin için binlerce kez cânımı versem,

Eğer sen bana gelmesen, gönül vermesen,

Onulmaz bu derdin çaresi sendedir sende.

Ölsem kabre koysalar, Cennetliksin deseler,

Sorgu sual etmeseler, hûri gılman verseler,

Bana yüzler köşk verip, bu senindir deseler,

Onulmaz bu derdin çaresi sendedir sende.

Allah''ım sorsa, Ey Kulum Niyetin nedir dese,

İstemem hiç bir şey bunların hepsi vesvese,

Dünya''da hesabını yaptım gerek yok yeise,

Onulmaz bu derdin çaresi sendedir sende.', 'Şimdi sana onbinlerce şiir yazsam bile ben, Bilki senin için binlerce kez cânımı versem, Eğer sen bana gelmesen, gönül vermesen, Onulmaz bu ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-derdin-caresi-sendedir-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakışır! ! !', 'yakisir-saim-bastik-8wtr1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu şiir 20/01/2006 tarihinde başları açık(belki de abdestsiz)  erkeklerle karışık namaz kılmaya kalkan ve bu güne kadar din ticareti yapan ama dinimize de enbüyük zararı veren utanmazlar için yazılmıştır.

YAKIŞIR! ! ! 

Sünneti bırakıp,attınız farzı

Bu namaz herhalde,ampulcü tarzı

Kitabı mı değiştirdin lan,dürzü

Bu işler sizlere,yakışır hani! ! 

Kimden başlayıpta,yazsam tahtaya

Herkes gördü,gerek yoktur yaftaya

Emine’yi unutmayın haftaya

Bu işler sizlere,yakışır hani! ! 

Riyakarlık tüter,daim bacanız

Böyle mi öğretti, size hocanız

Boynuz da çıkarsın,bari kocanız

Bu işler sizlere,yakışır hani! ! 

Boya çıktı,dökülüyor her yanı

Nesebi belirsiz,belirsiz kanı

Şeytanlıkta,geçtiniz siz şeytanı

Bu işler sizlere,yakışır hani! ! 

25/01/2006', 'Bu şiir 20/01/2006 tarihinde başları açık(belki de abdestsiz)  erkeklerle karışık namaz kılmaya kalkan ve bu güne kadar din ticareti yapan a...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yakisir-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dominoyu görmeden', 'dominoyu-gormeden-firat-acikgoz-nwlyb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sokağa bakan

ceviz kıran

içine sinse 

şurup niyetine 

takasa gireceksin

mordan el örmelerini

her derde deva

diyeceksin

karın altı da olsa

elin varmaz

dokunmaya

bileceksin

yarın cebindeki 

düğmeleri dikeceksin

sökeceksin

domino taşlarını

üçlüsünü

çiftlisini

çekeceksin

hep soracaksın

sardığın gibi 

1+1 sineceksin

kale duvarlarını 

ithal edeceksin

geleceksin

sonra da gideceksin

Fırat, 2006, Sabah karşısı', 'sokağa bakan ceviz kıran içine sinse  şurup niyetine  takasa gireceksin mordan el örmelerini her derde deva diyeceksin karın altı da olsa el...', ARRAY['Türk Edebiyatı','Şiir','Fırat Açıkgöz']::text[], 8.5, '{"poet":"Fırat Açıkgöz","poet_slug":"firat-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dominoyu-gormeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçine', 'i-cine-ahmetnecat-ucur-q2jwq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İç içe geçti,hepsi birbirinin içine

Gel girelim,sevgi ve aşkların en içine

Sarılmaz insan,sevgi ve aşk için içine

Aşktır bu, bilemezsin, girmeyince içine

Girdikçe gireceksin ki,bu aşkın içine 

Yaşayacaksın aşkı,sine sine içine

Girecek ki aşkımız,öylesine içine

Yaşayacaksın yaşamı sinerek içine

Sevdikçe insan,sevecek ki,girsin içine 

Kara sevdalar girecek ki aşkın içine

Güneş gibi aydınlıklar doğacak içine 

Gireceksen gir,sevgi ve aşklarım içine.', 'İç içe geçti,hepsi birbirinin içine Gel girelim,sevgi ve aşkların en içine Sarılmaz insan,sevgi ve aşk için içine Aşktır bu, bilemezsin, gir...', ARRAY['Türk Edebiyatı','Şiir','Ahmetnecat Ucur']::text[], 8.5, '{"poet":"Ahmetnecat Ucur","poet_slug":"ahmetnecat-ucur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/icine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Gelmez Biliyorum Ben', 'geri-gelmez-biliyorum-ben-yusuf-onder-bahceci-n9esl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dilek ağacına çaput bağlasam,

Dilek kayasını ortadan yarsam,

Her gece ağlayıpda  yakarsam,

Yine geri gelmez biliyorum ben.

Uğruna yüzlerce kurbanlar kessem,

Adını deyip deyip türbeler gezsem,

Allah''ım Allah''ım diyerek de ölsem,

Yine geri gelmez biliyorum ben.

Öyle sağlam bağlamışlar ki düğümü,

Sökemedim kalbimden kör düğümü,

Senden ayrı kaldım ederler düğünü,

Yine geri gelmez biliyorum ben.', 'Dilek ağacına çaput bağlasam, Dilek kayasını ortadan yarsam, Her gece ağlayıpda  yakarsam, Yine geri gelmez biliyorum ben. Uğruna yüzlerce k...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geri-gelmez-biliyorum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm ve Gülüm', 'olum-ve-gulum-seyfettin-bilal-ozluk-d5h3q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu kadar hoş gelmemişti gözüme ölüm

Sen yoksun ve sessizliğin içimi ürpertiyor

Ya sen gidipte bilmediğim uzaklardan dönmezsen

Yaşamak neye yarar ki gülüm...

Çıkardım içimden dışa vuramadıklarımı

Koydum önüme teker teker eledim

Herşeyi sildim geçmişten arta kalanları

Bir seni birde ölümü silemedim gülüm...

Gidişini geçici bildim git dedim

Dönmeyeceğini bilemedim dönemedin

Şansımı zorlasam gelirmisin bilemiyorum

Yokluğunda üşüdü buz tuttu bedenim gülüm...

Gidenler dönmez derler inanmazdım

Yolculuk başlıyor yeni seferde

Sıra bana geldi gitmeler

Ölüm karbeyaz şimdi gözümde gülüm..', 'Bu kadar hoş gelmemişti gözüme ölüm Sen yoksun ve sessizliğin içimi ürpertiyor Ya sen gidipte bilmediğim uzaklardan dönmezsen Yaşamak neye y...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olum-ve-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba Parası', 'baba-parasi-nizamettin-ozel-kvaza', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kolunda bilezik,

Yirmi dört ayar...

Parmağında yüzük,

Bilmem kaç milyar...

Giydiği elbise,

Hakiki ipek...

Bacaklarında ise,

Mini bir etek...

Boğazda villa,

Kapıda mersedes...

Yemek yese illa,

Havyar, karides...

Eğlendiği sahil; 

Etiler, Trabya...

Umurunda değil,

Yıkılsa dünya...

Yediği ne yazık ki; 

Baba parası...

O kadar uzak ki; 

Bizlerle arası...', 'Kolunda bilezik, Yirmi dört ayar... Parmağında yüzük, Bilmem kaç milyar... Giydiği elbise, Hakiki ipek... Bacaklarında ise, Mini bir etek......', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baba-parasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulluk', 'kulluk-nizamettin-ozel-pm2yq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bıraktım bir köşeye,

Aşkı ve sevdayı.

Cebimde topluyorum,

Yıldızları ve ayı.

Yüreğimdeki bu kor,

Günden güne yakıyor.

Anlamsız oluyor,

Yaşamak dünya’yı.

Gelip geçer bir bir,

Şu kısacık ömür.

Bana dost görünür,

Rakamlar ve sayı.

Evimde bir garibim,

Eşyalar sahibim.

Beni affet Rabbim,

Başaramadım kul olmayı…', 'Bıraktım bir köşeye, Aşkı ve sevdayı. Cebimde topluyorum, Yıldızları ve ayı. Yüreğimdeki bu kor, Günden güne yakıyor. Anlamsız oluyor, Yaşam...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kulluk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam Üstü', 'bu-aksam-ustu-hifzi-ozbekmez-adsta', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BU AKŞAM ÜSTÜ

Yıllarca ömrümü yedin yetmedi

Ukala budala dedin yetmedi

Çektiğim çileler demek bitmedi

Çok canımı sıktın bu akşam üstü

Dilerim Allah’tan çekersin cefa

Hayatın boyunca görmezsin vefa

Yüzüme gülecek sandım son defa

Alay edip baktın bu akşam üstü

Gönlümde hasretin beni yakarken

Gözümün yaşları durmaz akarken

Aşkına doymadan ne çabuk erken

Hayalimi yıktın bu akşam üstü

Hani yoktu aşkımızın emsali

Mecnunu da geçti latifin hali

Sanki çıngıraklı yılan misali

Ciğerime aktın bu akşam üstü

08  EKİM  2005  SAAT: 22:00', 'BU AKŞAM ÜSTÜ Yıllarca ömrümü yedin yetmedi Ukala budala dedin yetmedi Çektiğim çileler demek bitmedi Çok canımı sıktın bu akşam üstü Dileri...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bu-aksam-ustu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görüş', 'gorus-nizamettin-ozel-2b6pz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu benim görüşüm; 

Kadın ait olmalı birine.

Başka hiç kimseyi,

Koymamalı onun yerine.

Bu benim görüşüm; 

Erkek ait olmalı eşine.

Gördüğü her güzelin,

Düşmemeli peşine…', 'Bu benim görüşüm;  Kadın ait olmalı birine. Başka hiç kimseyi, Koymamalı onun yerine. Bu benim görüşüm;  Erkek ait olmalı eşine. Gördüğü her...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gorus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi göğe düştü', 'sevgi-goge-dustu-selcen-boyar-g5m3z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Coştu coştu uçtu gönül

Uçtu yere düştü gönül

Yükseklerde gözü yoktu

Yerden yere düştü gönül

Göz görmez oldu uzağı

Bilemedi gönül ırağı

Türlü türlü tuzakları

Geçti geçti düştü gönül

Nefis hakkı görmez oldu

Hakkı hakka vermez oldu

Nefs kendini sevmez oldu

Sevgi göğe düştü gönül

Yar yar dedi iniledi

Senelerce hep bekledi

Yar yürekten uçtu gönül

Yar ırağa düştü gönül', 'Coştu coştu uçtu gönül Uçtu yere düştü gönül Yükseklerde gözü yoktu Yerden yere düştü gönül Göz görmez oldu uzağı Bilemedi gönül ırağı Türlü...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgi-goge-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzursuz Mutluluk', 'huzursuz-mutluluk-orhan-turhan-mgzyq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saadet, cevaplar mı mutluluk arayışlarını,

Yoksa huzur mu son verir bu heyecana? 

Hayatın kısacık anlarıdır  mutlu yaşanan.

Hem mutlu hem huzurlu olamaz ki insan; 

Mutlu olmak için arananlar,

Huzuru ve saadeti  kovalar çoğu zaman. 

25.01.2006', 'Saadet, cevaplar mı mutluluk arayışlarını, Yoksa huzur mu son verir bu heyecana?  Hayatın kısacık anlarıdır  mutlu yaşanan. Hem mutlu hem hu...', ARRAY['Türk Edebiyatı','Şiir','Orhan Turhan']::text[], 8.5, '{"poet":"Orhan Turhan","poet_slug":"orhan-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/huzursuz-mutluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-zernisan-aydogan-p4xrg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle bakiyor ki gözlerin bana

Beni kollarina al diyor sanki

Bosver güne akip giden zamana

Ömrümce yanimda kal diyor sanki

Yansin gönlümüzde askin atesi

Dogsun ruhumuza sevda günesi

Seninle vereyim en son nefesi

Derdin nedir bu hal diyor sanki

Herzaman her yerde bakip gülüyor

Su seven yüregi yakip gidiyor

Benide ardina takip gidiyor

Eger vermezlerse çal diyor sanki

Gururu yaratmis sanki daglara 

Bir bayrama dönmüs gençlik çaglari

Unut bensiz geçen tatsiz yillari

Ömrümce yanimda kal diyor sanki', 'Öyle bakiyor ki gözlerin bana Beni kollarina al diyor sanki Bosver güne akip giden zamana Ömrümce yanimda kal diyor sanki Yansin gönlümüzde ...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerin-218-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Ele Yaşam', 'el-ele-yasam-orhan-turhan-kklwb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Haydi umudum,

Ver elini! 

Hayallerimizin titrek ateşiyle ısıtalım,

Yarısını zemheride unuttuğumuz  yüreklerimizi.

Ve öpüverelim şükranla

Bizi incecik bir iplikle yaşama teyelleyen terzinin

O incecik,  nasırlı ellerini.

25.01.2006', 'Haydi umudum, Ver elini!  Hayallerimizin titrek ateşiyle ısıtalım, Yarısını zemheride unuttuğumuz  yüreklerimizi. Ve öpüverelim şükranla Biz...', ARRAY['Türk Edebiyatı','Şiir','Orhan Turhan']::text[], 8.5, '{"poet":"Orhan Turhan","poet_slug":"orhan-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/el-ele-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum 2', 'yorgunum-2-i-lhan-koruyucu-hdpn3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yorgunum 2

Öyle yada böyle nice halim

Kendimden geçmişim dünya işleriyle

Dizlerim tutmaz olmuş yokuş çıkamam

Yorgunum dostlarım birazda yılgın

Neşem kaybolmamış yine de çehremden

Demli bir bardak çay içmek isterim

Kalbim dayanır mı bilmem 

Dünyadaki bir sürü kötülüklere

Kar yağıyor ve ardından soğuk

Soğukla birlikte güzelim güneş peşinde

Güzelliklerde oluyor velhasıl

Yorgunum ama dostlar

Yine de mutluyum

Yorgunlunluktan şikayetçi olsam da

Bilin ki yarından umutluyum.

İlhan KORUYUCU.', 'Yorgunum 2 Öyle yada böyle nice halim Kendimden geçmişim dünya işleriyle Dizlerim tutmaz olmuş yokuş çıkamam Yorgunum dostlarım birazda yılg...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yorgunum-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gül Bebek', 'sen-gul-bebek-orhan-turhan-24i1s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gül bebek! 

Yüreğinle, geleceğinle gül! 

Sen gül ki; ben de gülleri sulayayım.

Sen gül ki; mutluluğu saklandığı yerden bulup çıkarayım.

Sen gül ki; vuslat anı geldiğinde

Dudaklarımın arasına sıkıştırılmış

Çirkin bir yırtık gibi duran  gülüşle karşına çıkmayayım. 

Sen gül bebek! 

Gül ki; seni seninle parantezlerinin arasında yaşayayım.

25.01.2005', 'Gül bebek!  Yüreğinle, geleceğinle gül!  Sen gül ki; ben de gülleri sulayayım. Sen gül ki; mutluluğu saklandığı yerden bulup çıkarayım. Sen ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Turhan']::text[], 8.5, '{"poet":"Orhan Turhan","poet_slug":"orhan-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-gul-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil İpek', 'yesil-i-pek-latif-oz-f812w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeşil ipek perdedir

Püskülleri nerdedir

Sevdiğimin emsali

Ne gökte ne yerdedir

Yeşil ipek bürüyor

Bohçaları dürüyor

Senin o bakışların

Yüreğimi deliyor', 'Yeşil ipek perdedir Püskülleri nerdedir Sevdiğimin emsali Ne gökte ne yerdedir Yeşil ipek bürüyor Bohçaları dürüyor Senin o bakışların Yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Latif Öz']::text[], 8.5, '{"poet":"Latif Öz","poet_slug":"latif-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yesil-ipek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim -2', 'ogretmenim-2-mehmet-postalli-7x95u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bir çiçek isem, bahçıvanım sen

Güzel ellerinle der öğretmenim

Bin bir çiçek açar senin elinden

Renk renk, demet demet ser öğretmenim

Senin eserindir bildiğim her şey

Bilgi hazinenden aldığım bu pay

Şimdi ses veriyor üflediğin ney

Yüreklerde yankın var öğretmenim

Sınıfa girince ışır gözlerin

Şefkatle bakarsın, güler yüzlerin

Kulağıma küpe olur sözlerin

İster imtihan et, sor öğretmenim

İçimi  ısıtır  sıcacık  sesin

Kendi çocuğundan fazla seversin

Anneden, babadan öte bir şeysin

Sensin yolumdaki nur, öğretmenim

Her gün senin günün, her saat her an

Bir güne sığmazsın, sen bir cansın can

Şerefle taşınır taktığın nişan

Bu dünya durdukça dur öğretmenim.

2005', 'Ben bir çiçek isem, bahçıvanım sen Güzel ellerinle der öğretmenim Bin bir çiçek açar senin elinden Renk renk, demet demet ser öğretmenim Sen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ogretmenim-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gündüzler seninse', 'gunduzler-seninse-zernisan-aydogan-ub569', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aldigim her nefesin birisi senin

Hasret sarhosuyum dolasir dilim

Gittigim yollarin kenar kösenin

Attigim her adimin birisi senin

Paylasirim seni yanliz seninle

Gündüzler seninse geceler benim

Bilmedigim bir his var sana içimde

Yedigim lokmanin birisi senin

Gözlerim karardi sana hasretten 

Saklama artik kendini benden

Ne zarar gördün ki benim sevgimden

Al iki gözümün birisi senin', 'Aldigim her nefesin birisi senin Hasret sarhosuyum dolasir dilim Gittigim yollarin kenar kösenin Attigim her adimin birisi senin Paylasirim ...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gunduzler-seninse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur Gitarın Teline', 'vur-gitarin-teline-aynur-avci-fmp1l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vur gitarın teline

Alıp götürsün yüreğimi

Ta derinden derine

İnletsin aşıkları

Vur gitarın teline

Bir daha,bir daha

Alıp götürsün beni

Yıllar ötesine

Vur  gitarın teline

Dalga dalga dolsun

Nağmeler esintisi

Yürekler vursun..', 'Vur gitarın teline Alıp götürsün yüreğimi Ta derinden derine İnletsin aşıkları Vur gitarın teline Bir daha,bir daha Alıp götürsün beni Yılla...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vur-gitarin-teline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanımda yoksun!', 'yanimda-yoksun-i-lhan-koruyucu-y1akf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanımda yoksun! 

Ben yalnız ve sadece yalnızım

Bakıyorum ufkun derin semalarına

Kollarım sarıyor boşluğun yokluğunu

Seni arasam da yanımda yoksun 

.......

Amaç aynı gaye aynı bırak gururu

Sözle anlatamazsan gözlerin nerde? 

Okşa, sev, sar beni bırakma dertte

Günde seni ararım yanımda yoksun 

......

Sonbahar dökmüşse sarı yaprakları

Ayrılık rüzgarları kafamda fırtına

Şimşekler çakar zavallı yüreğimde

O gün, bugün ararım yanımda yoksun 

......

Gün ışığı tüm eğreltisiyle penceremde

Vur vur bir daha acıma hissin nerde

Naz etme cilve hadi neyse ama

Duygularımda arasam yanımda yoksun

......

Sığ körfezin mavi bulanıklığıyla mercanlarda

Geçit vermeyen vadilerin uçsuz karanlığında

Sıradan manasız sohbetlerde, sigaramda

Yerin altında seni arasam yoksun 

ilhan KORUYUCU.', 'Yanımda yoksun!  Ben yalnız ve sadece yalnızım Bakıyorum ufkun derin semalarına Kollarım sarıyor boşluğun yokluğunu Seni arasam da yanımda y...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yanimda-yoksun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğun Tarifini Yaparmısın Sen', 'mutlulugun-tarifini-yaparmisin-sen-yusuf-onder-bahceci-dwbgk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Parayla alacak bir şey olsaydı,

Onu satın alırdım param olsaydı,

Mutluluk sevdiğim benim olsaydı,

Mutluluğun tarifini yaparmısın sen.

Mutluluk yanında olmak değilmi,

Yanında olupta sarmak değilmi,

Yârinden ayrılan ahmak değilmi,

Mutluluğun tarifini yaparmısın sen.

Mutluluk öyle kolay ele geçmiyor,

Sevenler sevdiğinden geçmiyor,

Yaşım gidiyor gözümse seçmiyor,

Mutluluğun tarifini yaparmısın sen.

En sonunda mutlu olacakken ben,

Önümüze serdilerde çalı ve diken,

Ben seni severken, ele giderken,

Mutluluğun tarifini yaparmısın sen...', 'Parayla alacak bir şey olsaydı, Onu satın alırdım param olsaydı, Mutluluk sevdiğim benim olsaydı, Mutluluğun tarifini yaparmısın sen. Mutlul...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mutlulugun-tarifini-yaparmisin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı yaşadım mı?', 'aski-yasadim-mi-i-lhan-koruyucu-y9mrb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkı yaşadım mı? 

Girdaba girdi  öylece aradım durdum

Baktım ay’a yetmez dedim

Olmadı güneş’e döndüm içimi yaktı

Gökteki en parlak yıldıza ad taktım yine olmadı.

……

Nereye baksam bilmem ben aşkı

İçimde, gönlümde ve sende arasam

Umudum varoldukça yaşasam

Doyasıya çeksem içime temiz hava gibi

……

Bilmiyorum aşkı yaşadım mı? 

Ezele  kadar koştum aşkın peşinden

Hep ben kovaladım, yakaladım sandım

Birde baktım hep  benden bir adım  önde

……

Aşkı bazen umutlarımda, kalemimde

Olmadı sevgilinim bade gözlerinde aradım

Kitaplarımda, dipnotlarda taradım durdum

İç huzurumda, sevginde buldum aşkı şaştım kaldım.

11.12.2005 İlhan KORUYUCU.', 'Aşkı yaşadım mı?  Girdaba girdi  öylece aradım durdum Baktım ay’a yetmez dedim Olmadı güneş’e döndüm içimi yaktı Gökteki en parlak yıldıza a...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aski-yasadim-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelim', 'guzelim-i-lhan-koruyucu-atngc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzelim

Seni düşledim ben ömrümce

Buldumsandım hep gönlümce

Elini uzat tut ne olur bence

Gönlüme sokayım güzelim gömlümce

......

Oyun bozanlık yapmayalım

Dar gelmesin koca dünya

Sevgi, aşk güzellikler uğruna

Gel gel kırma yaşayalım güzelim

......

Renkler fıkır fıkır çember olmuş

Küçük büyük sevgi ah neş''eler

Hoplarız zıplarız hasretiz mutluluğa

Geceler gibi gündüzlerde bizim güzelim.

İlhan KORUYUCU.', 'Güzelim Seni düşledim ben ömrümce Buldumsandım hep gönlümce Elini uzat tut ne olur bence Gönlüme sokayım güzelim gömlümce ...... Oyun bozanl...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guzelim-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıklar olsun', 'yaziklar-olsun-zernisan-aydogan-fi5if', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllardır benimle uğraşıyorlar

Doymadılar gitti Allah doyursun

Haksız yere benimle uğraşanların

Kalpleri çürüsün dili lal olsun

Namaz kılıp dedi koduya başlarlar

Dilim değmediği halde beni haşlarlar

Fesatlık hepsinin mayasında var

Allah tan da korkmuyorlar yazıklar olsun

Hakkım helal deyil haramdır size

İki elim yakanızda olacak  ahirette

Ahımı aldınız şu yer yüzünde

Sizin gibi akrabaya yazıklar olsun

Sesim çıkmıyor diye ezip geçtiniz

Elinizden gelse çiğ çiğ yersiniz

Bilmem ki şu garipten ne istersiniz

Can dedikçe çor dediniz yazıklar olsun

Bin bir hayallerle geldim bu şehire

Gecemi gündüzümü zından ettiniz

Derdime derman olacağınız yerde

Ciğerimi parça parça ettiniz

Ne istedim sizden sevgiden başka

Bir tatlı dil bir güler yüz yeterdi bana

Onuda çokmu gördünüz şu garibana 

Akrabalığı öldürdünüz yazıklar olsun', 'Yıllardır benimle uğraşıyorlar Doymadılar gitti Allah doyursun Haksız yere benimle uğraşanların Kalpleri çürüsün dili lal olsun Namaz kılıp ...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yaziklar-olsun-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Bıraktığın Resim!', 'bende-biraktigin-resim-kubra-gulbahar-u928a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sende kabataslak çiziyorum aşkın resmini

Şurada iki ağaç olacak gölgesinde dinlendiğin

Bulutların bir kısmını koyuya boyayacağım

Yağmur havaların hiç eksik olmasın yüreğinde diye

Derme çatma bir kulüben olacak şu sol tarafta

İçimde yıktıklarını hatırlaman maksatlı

Bilirim serinlikleri seversin

Sana bir göl çizmeyi unutmayacağım

Uzaklara baktığında ne dağ göreceksin

Ne de bir köy manzarası…

Sendeki boşlukları koyacağım oralara

Biliyorum biraz canın acıyacak

Sonra alışacaksın! 

Birkaç göçmen kuş süzülecek bulutlardan

Çok uzaklardan gelecek o huzur sesleri

Sana uğramadıklarına üzüleceksin

“Belki bir gün” ile başlayan avuntular birikecek içine

Başın öne eğildiği vakit

Gelmeyeceklerini kavrayacaksın! 

Pencerelerin ışığa bakmayan taraflarda kalacak

Bir yol çizeceğim yürümekten korktuğun

Şekil almaz yalnızlık rengine boyayacağım etrafı

Mevsim ne olursa olsun üşüyeceksin

Yakarışların hep bana olacak

Ellerine bıraktığım sıcak geceleri arayacak yüreğin

Tüm pişmanlıkları giydiğin o vakit üstüne

Yan yana duran ayrılıkların farklı yüzleri olduğumuzu anlayacaksın!', 'Sende kabataslak çiziyorum aşkın resmini Şurada iki ağaç olacak gölgesinde dinlendiğin Bulutların bir kısmını koyuya boyayacağım Yağmur hava...', ARRAY['Türk Edebiyatı','Şiir','Kübra Gülbahar']::text[], 8.5, '{"poet":"Kübra Gülbahar","poet_slug":"kubra-gulbahar","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bende-biraktigin-resim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adam', 'bir-adam-mehmet-postalli-e8av0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elini alnına koymuş, oturuyor boynu bükük,

Taşın üstünde görünen, adam değil sanki kütük.

Matem pazarı kurulmuş, vücuduna bölük bölük,

Belini yaya çevirmiş, omuzlarına çöken yük.

Gözlerinin önü mosmor, avurtları çökük çökük

Kır bıyığını sarartmış, dert ortağı isli körük 

Başında gri bir kasket, kasketin tereği sökük

Gelecekten beklentisi tükenmiş, umudu sönük.

Belli, ömründe gülmemiş, derdi kâf dağından büyük

Dudağından üç-beş kelam dökülüyor kırık, dökük

Dedi: sükutum isyandır, yüzümden okuyun günlük

Muhannetin potasında, eritildim köpük köpük

Kanımı emip kuruttu, tenime yapışan sülük

Eşim öldü, evlat firar, bozuldu birlik bütünlük,

Elimi attığım dalın, hepsi, hepsi kökten çürük

Beynimde tortu bıraktı, ne varsa geriye dönük

Öfkeyle baktı boşluğa, suç mu acaba dürüstlük? 

Diyerek yumdu ağzını; biz derin derin düşündük.', 'Elini alnına koymuş, oturuyor boynu bükük, Taşın üstünde görünen, adam değil sanki kütük. Matem pazarı kurulmuş, vücuduna bölük bölük, Belin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-adam-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-nizamettin-ozel-6odch', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhaba; diyeceksin ki, bu da nerden çıktı! 

Vallahi kapını çalmazdım, fakat kapı açıktı.

Biliyorum, sen beni hiç ama hiç tanımadın ki; 

Olsun, ben hayalini sevdim senin sanki.

Senin gibi, şimdi ben de başka biriyle evliyim,

Öyleyse niye mektup yazıyorum, herhalde deliyim.

Gerçekten çok güzel bir karım var, adı Arife; 

Lakin senin sayende başladım, aşkı şiirle tarife.

O yüzden sana minnettarım, bir ömür boyu; 

Birkaç satır yazayım dedim, kelimeleri koyu.

Zaman aldı yürüdü her şeyi, iki bine bir kala; 

Senin hep mutlu olmanı isterim, eşin ve çocuğunla.

İnan hayalin bile kalmadı gözümde, iki gözüm; 

Yine de tatlı anıların hatırası, ben de şu tebessüm.

Ya işte böyle, ilk göz ağrım, Nalan Sevda Erol; 

Beni sen şair yaptın, minnettarım sana, sağol...', 'Merhaba; diyeceksin ki, bu da nerden çıktı!  Vallahi kapını çalmazdım, fakat kapı açıktı. Biliyorum, sen beni hiç ama hiç tanımadın ki;  Ols...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mektup-122-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abdal', 'abdal-serdar-ahmet-guzel-20l4c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Abdallara mağlum olur.

Geceden görürler,

Gündüzün ışıltısını…

Yalan söyleyene 

Sanma inanırlar,

Hakkın tecellisini

Bekler dururlar…

Rahmetsizlere dua ederler

Rab onlara acısın diye…

Bilirler,

Mührün Padişahını,

Yalnız o isterse

Kaldırır melanet hükmünü…

Yanılma sen ey! fani

Dua et Yaradana 

Yolda bırakmasın seni

Kötülerin dünyasında.

22.01.2006 saat:23.23', 'Abdallara mağlum olur. Geceden görürler, Gündüzün ışıltısını… Yalan söyleyene  Sanma inanırlar, Hakkın tecellisini Bekler dururlar… Rahmetsi...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ahmet Güzel']::text[], 8.5, '{"poet":"Serdar Ahmet Güzel","poet_slug":"serdar-ahmet-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/abdal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alkol Akşamları', 'alkol-aksamlari-serdar-ahmet-guzel-0b3v2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Önceleri içmezdim ben 

Senden sonra başladı,

Alkolle arkadaşlığım…

Unutmak istediğimde elimde,

Hatırlamak istediğimde yanımda,

Kısacası her ne olsa da,

Sen varsan konu başında, parantez açarak 

Ve yanında ünlemi,

Sebep oluyorsun erkenden başlayıp,

Erkenden biten,

Alkol akşamlarıma…

25.01.2006 saat: 21.36', 'Önceleri içmezdim ben  Senden sonra başladı, Alkolle arkadaşlığım… Unutmak istediğimde elimde, Hatırlamak istediğimde yanımda, Kısacası her ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ahmet Güzel']::text[], 8.5, '{"poet":"Serdar Ahmet Güzel","poet_slug":"serdar-ahmet-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/alkol-aksamlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''da Hep Sonbahar', 'i-stanbul-da-hep-sonbahar-adem-atacak-7uoru', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaldırımların yağmur üzerinde bıraktığı,

Derin ayak izlerinin dramını; 

Beş taş oynayan çocukların,

Dünyaya yüz çevirmiş

Çığlıkları kamufle ediyor.

Bense; sevdiğim İstanbul kalıntılarını süpüren,

Uzun pardösümün yerle temas eden,

Çamurlu yanlarını sevmekle meşgulüm.

Alakasız bir tufandan kurtulan,

Düğmeleri kopmuş sıcak,

Hera''nın eteklerinde,

Mayıs çiçekleriyle selamlaşıyor.

Tabi ki beni de seviyorlar.

Çok değişimin,

Tek değişmeyen mevsimi, 

13.ayın 5.mevsimiyle zaten aram iyi.

Güneşi tepeden koparıp

Kış çocuklarının mahalle maçı yaptığı,

Şarkı söyleyen ağaçların,

Gülhane üzerine,

Yapraklarını döktüğü mevsimi

Yani seni düşündüğümde 

Karagümrük''te sallanan dualarımın,

Baş ucuma koyduğu mevsimi seviyorum.

Velhasıl Anadolu''yu kamufle eden yokluğunu,

Üsküdar''da martılarla paylaşmayı seviyorum.', 'Kaldırımların yağmur üzerinde bıraktığı, Derin ayak izlerinin dramını;  Beş taş oynayan çocukların, Dünyaya yüz çevirmiş Çığlıkları kamufle ...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/istanbul-da-hep-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demokrasi', 'demokrasi-abdurrahim-karakoc-doned', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dedim ki, demokrasi geldi mi sizin eve? 

Dedi: Gelse ağırlar, beslerdim seve seve.. 

Açık koymuş kapıyı belki gelir diyerek 

Pencereden fil girmiş, bacadan girmiş deve! 

16.01.2006/Vakit', 'Dedim ki, demokrasi geldi mi sizin eve?  Dedi: Gelse ağırlar, beslerdim seve seve..  Açık koymuş kapıyı belki gelir diyerek  Pencereden fil ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/demokrasi-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Ateşin Gazeli Yaktığı Gibi*', 'atesin-gazeli-yaktigi-gibi-zernisan-aydogan-5ydf9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gurbet ve hasret içimde yeşerir

Tipki ağaçların yeşerdiği gibi

Hasretlik çöktü omuzlarıma

Taşımıyor bedenim eskisi gibi

Insanlar mı fani dünya mı yalan? 

Herkesin dilinde küfürle isyan

Sararip düsüyor topraga insan

Azrail elini attiğı gibi.

Faniymiş dünya çok geç anladım

Söyle fani Allah için bu gün ne yaptın

Verilen zamanı sende mi yaktın

Ateşin gazeli yaktiğı gibi

Uyan gönlüm uyan gaflete dalma

Zalimin yüzünden ağlayıp durma

Bir gün hesap verecekler bunu unutma

Ahirete intikal ettiği gibi

                                  Erzurum/  zernişan AYDOĞAN', 'Gurbet ve hasret içimde yeşerir Tipki ağaçların yeşerdiği gibi Hasretlik çöktü omuzlarıma Taşımıyor bedenim eskisi gibi Insanlar mı fani dün...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/atesin-gazeli-yaktigi-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Şiirler Yazacağım Ben', 'boyle-siirler-yazacagim-ben-yusuf-onder-bahceci-t16g9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bizim bu sevdamız ölene kadar,

Ölene kadar değil gülene kadar,

Çok sevdiğim benim olana kadar,

Böyle şiirler yazacağım ben.

Mecnun Leyla için çöllerde gezmiş,

Ferhat''sa Şirin için dağları delmiş,

İkisi de çok sevmiş cânını vermiş,

Böyle şiirler yazacağım ben.

Önder şiir yazıp da ağlıyor deyin,

Adam deli mi olmuş gülüyor deyin,

Siz ne derseniz deyin gönül eyleyin,

Böyle şiirler yazacağım ben...', 'Bizim bu sevdamız ölene kadar, Ölene kadar değil gülene kadar, Çok sevdiğim benim olana kadar, Böyle şiirler yazacağım ben. Mecnun Leyla içi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/boyle-siirler-yazacagim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pembelim', 'pembelim-nizamettin-ozel-clumr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Pembelim; 

Bak yaşlandım artık,

Doğrulmuyor işte belim.

Seni elimden alırlarken,

Baktım ardından.

Gördün ya ben; 

Ne kadar tembelim...

Pembelim; 

Güle uzanır gibi,

Uzanmıştı sana elim.

Dikenler battı,

Eşek arıları soktu; 

Senden uzaklaştırdılar,

Beni güzelim...

Pembelim; 

Ağlama sakın sen.

Benim çektiğim zulüm, 

Biter bir gün.

Ama şunu unutma; 

Ayıramaz beni senden

Ölüm...', 'Pembelim;  Bak yaşlandım artık, Doğrulmuyor işte belim. Seni elimden alırlarken, Baktım ardından. Gördün ya ben;  Ne kadar tembelim... Pembe...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/pembelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muallak', 'muallak-adem-atacak-4yhcm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Menfaatleri çakışan düşüncelerimin

Tartıştığı bir gecede

İlk şiirimi senin için yazdım

Zamanla azalan uykularım

Benzetirken beni birine

Tanıyamadım ayaklarına yatıyordu.

Muhakkak dediklerimde

Muallak engeller çıktı

Şimdi ise

Belki ve keşkelerle uğraşıyorum

Yarım kalan bir şeylerin

Üzerine ilave edeceğim

Sadece annemin merhameti kaldı

Yoğun bir geceye

Homojen dağılan cüssemi

Sabaha karşı kırık dökük toparlıyorum

Yani zor geçti

Birkaç sene

Yavaş yavaş alışıyor insan

Ya eksiğe ya da eksilmeğe', 'Menfaatleri çakışan düşüncelerimin Tartıştığı bir gecede İlk şiirimi senin için yazdım Zamanla azalan uykularım Benzetirken beni birine Tanı...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/muallak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sedef Çiçeği (Rengi Çok Hoş)', 'sedef-cicegi-rengi-cok-hos-bekir-gedikoglu-kh94g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sedef çiçeğinin azmi

Hiçbir çiçekte yok belli

İki yıl bakacaksın ki

Ortaya çıkacak rengi

Bir sapı var ince uzun

Gelin beline çok uygun

Onun için kışlar uzun

Bakımda dikkatli olun

İkinci yıl yaz ayında

Çiçek kuruduğu anda

Yapraklar soyulduğunda

Sedef  renkler artık fora

Elips şeklinde yapraklar

O dalları donatırlar

Bir küpeyi andırırlar

Sanki kulaktan sarkmışlar

İnce zar gibi yapraklar

Aşağı doğru sarkarlar

Sanki sedeften damlalar

Bir arada toplanmışlar

Bu çiçeğin yok kokusu

Pek uzundur onun boyu

Sedef renkler beğeni oldu

Tüm dalları onla doldu

Gelinlerin gözündeki

Parıltının ta kendisi

Sedef çiçeğinin rengi

Bellidir Allah vergisi

Ankara saat 06-00', 'Sedef çiçeğinin azmi Hiçbir çiçekte yok belli İki yıl bakacaksın ki Ortaya çıkacak rengi Bir sapı var ince uzun Gelin beline çok uygun Onun ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sedef-cicegi-rengi-cok-hos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Platonik', 'platonik-adem-atacak-ntpvz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gürültülü bir kantinin

Demlenmiş muhabbetlerinde

Anlatamadım seni arkadaşlarıma

Kayboldun ansızın

Platonik okulumda

İki kişilik sevgiyi

Tek başıma kullanmanın

Yan etkilerini,evlendiğin de bıraktım

Sevebilme ihtimaliyle ilgili şiirleri

Uzun zaman okumadım

Sınav öncesi heyecanlarım

Bekar evi sorunlarım

Ve sen kaldın anılarımda

Çok merak ediyorum

Söylesem beni de sever miydin', 'Gürültülü bir kantinin Demlenmiş muhabbetlerinde Anlatamadım seni arkadaşlarıma Kayboldun ansızın Platonik okulumda İki kişilik sevgiyi Tek ...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/platonik-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denize Attım Bu gece Şiirlerimi', 'denize-attim-bu-gece-siirlerimi-zeliha-bicer-09wxq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denize attım bu gece şiirlerimi

Dalgalarda o maviliklerde 

İçimin öfkesini hüznümü

Yelken yapıp açtım rüzgara

Gitsinler,terketsinler beni, 

Sevgisiz değilim ki,umarsız hiç olmadım

Yaşamın hep beyazındaydım

Yeşilini de sevdim

Bazen hüzünlüydü turuncum

Ama

Siyahım bu gece simsiyah

Yağan karın da faydası yok siyahıma

Kıyamet günü gibiyim

Kopmuş, yokolmuş

İçimdeki depremlerin 

Sayısını unuttum.

Bu karalıkta karanlıkta

Işıksın beklediğim

Uzat elini ya da

Martılarını gönder bana...', 'Denize attım bu gece şiirlerimi Dalgalarda o maviliklerde  İçimin öfkesini hüznümü Yelken yapıp açtım rüzgara Gitsinler,terketsinler beni,  ...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/denize-attim-bu-gece-siirlerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Var', 'var-hikmet-kucuk-jmoz0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalan dünyanın bin bir türlü hali var,

Hem güldüren hem ağlatan ahvali var.

Pek yaslanmaya gelmez, eğreti durur,

Hazırlanıp gidecek bir minvali var.

Delil istersen sözlerime karşılık,

Kabristanlarda yatan çok misali var.

Gönlüm, isyanlarda gezinmen reva mı? 

Her şeyin az haramı, çok helali var.

Mağrur olma iyi günlere aldanıp,

Güneş doğuyor amma, bak zevali var.

Yılgınlık niye ki başarısızlıkta? 

Elbette ki her işin bir kemali var.

Dokunmayın umutlara uçuşsunlar,

Herkesin nefes aldığı hayali var.

Ey dünya! Neden yüklenirsin garibe? 

Taş değil ki tâkati bir mecali var.

Dalgalan her daim yıldızlı bayrağım,

Ne talihli yıldız ki, bir hilali var.

Nakış nakış yerler, inci inci gökler,

Yerin dağı varsa göğün Zühali var.

Güzellikler içinde niçin kavgalar? 

Benim, senin, hepimizin ihmali var.

Şu kainatın ne de güzel şahı var,

Ol şahın, celalinden çok cemali var.

(Eskişehir 25/01/2006)', 'Yalan dünyanın bin bir türlü hali var, Hem güldüren hem ağlatan ahvali var. Pek yaslanmaya gelmez, eğreti durur, Hazırlanıp gidecek bir minv...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Küçük']::text[], 8.5, '{"poet":"Hikmet Küçük","poet_slug":"hikmet-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/var-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne dersin?', 'ne-dersin-zernisan-aydogan-l7igo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne sen çiçek ol 

Ne de ben arı

Ne sen gül ol

Ne de ben bülbül

Ne özünü alıp çiçek açmak

Nede gülden ayrı hüzünle yaşamak

Hayır! 

İkimiz bir vazoda çiçek olsak

Birlikte yaşasak birlikte solsak

Ama hep beraber olsak 

Ne dersin?', 'Ne sen çiçek ol  Ne de ben arı Ne sen gül ol Ne de ben bülbül Ne özünü alıp çiçek açmak Nede gülden ayrı hüzünle yaşamak Hayır!  İkimiz bir ...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ne-dersin-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık ve Karanlık', 'isik-ve-karanlik-gulsen-gonenc-vi1a9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok korktum

Bir an karanlık oldu

Sadece bir an

Zaman kavramını yitirten bir an

Alışığım sanıyordum karanlığa

Işık başka birşeymiş

Akışkanlığı benzemezmiş karanlığa

Işığım bir daha sakın sönme.', 'Çok korktum Bir an karanlık oldu Sadece bir an Zaman kavramını yitirten bir an Alışığım sanıyordum karanlığa Işık başka birşeymiş Akışkanlığ...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/isik-ve-karanlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesabı Hiç Sorulmazmı', 'hesabi-hic-sorulmazmi-yusuf-onder-bahceci-mhaoy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni böyle solduranın,

Kalbe elem dolduranın,

Köpek gibi saldıranın,

Hesabı hiç sorulmazmı.

Yarım kalan sevdalar,

Şimdi bizi kimler anlar,

Aramızda sıra dağlar,

Hesabı hiç sorulmazmı.

Hakkın varmı ayırmaya,

Bu sendeki nasıl maya,

Eller hep giderken aya,

Hesabı hiç sorulmazmı.

Sevdim desem ne olur,

Derdim nasıl son bulur,

Belki de birgün sorulur,

Hesabı hiç sorulmazmı....', 'Seni böyle solduranın, Kalbe elem dolduranın, Köpek gibi saldıranın, Hesabı hiç sorulmazmı. Yarım kalan sevdalar, Şimdi bizi kimler anlar, A...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hesabi-hic-sorulmazmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharı Bekliyorum', 'bahari-bekliyorum-mehmet-postalli-njh85', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mevsim kış, kar diz boyu, kapandım pencereye

Pembe hayaller kurup, baharı bekliyorum

Pınar susuz, seherle figan düştü dereye

Hasret ile oturup, baharı bekliyorum

Hava yine kapalı, dilek sessiz ve sakin

Başak damla istiyor, müjde bekliyor ekin

Çiğdem sarı yazmalı, çok naziktir velâkin

Gaye yağmuru sorup, baharı bekliyorum

Ülker, mehtap el ele ve yıldız göz kırpıyor

Tanyeli efil efil, gönüle su serpiyor

Meltem, selvi dalını yasemine çarpıyor

Duyguya söz duyurup, baharı bekliyorum

Birer sedef taç gibi güle takılmış şule

Hilal kaşını eğmiş, menekşe gözlü lale

Buse, gamzeye dargın, sevinci sarmış hale

Bir demet çiçek sarıp, baharı bekliyorum

Arzu, emel hülyada, bengisu derde derman

Sevgiyi seviyorum, canana canım kurban

Kader ne der, aslı ne, ne söyler yüce ferman? 

Yaratana yalvarıp, baharı bekliyorum.', 'Mevsim kış, kar diz boyu, kapandım pencereye Pembe hayaller kurup, baharı bekliyorum Pınar susuz, seherle figan düştü dereye Hasret ile otur...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bahari-bekliyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umurumda değil', 'umurumda-degil-adem-atacak-0i49j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ay ışığının 

Esmerleştirdiği gecelerde

Hitap edecek sadece hayalini bulabildim

Hiç sevmiyorum diye tekrarlayarak

Unutmak istediğim

Geçmişimizle gayet sıkı fıkıyım

Şu aralar

Ellerimi yıkarken

Senden arındığımı düşünsem de

Mektup yazar gibi

Şiir yazıyorum sana

Ne temiz hava

Ne de arkadaşlar umurumda

Mutluyum şimdilik sıkıntılarımla', 'Ay ışığının  Esmerleştirdiği gecelerde Hitap edecek sadece hayalini bulabildim Hiç sevmiyorum diye tekrarlayarak Unutmak istediğim Geçmişimi...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/umurumda-degil-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Kalmayın', 'gec-kalmayin-abdurrahim-karakoc-s7z7k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çukuru tiksindirir zirvedeki hâlleri 

Gün gelip ruhlarını boğacak veballeri 

Cehennemde villalar sudan ucuz diyorlar 

Geç kalan kaybedecek, yağlayın pedalları! 

14.01.2006/Vakit', 'Çukuru tiksindirir zirvedeki hâlleri  Gün gelip ruhlarını boğacak veballeri  Cehennemde villalar sudan ucuz diyorlar  Geç kalan kaybedecek, ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gec-kalmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzeldin Sen', 'ne-guzeldin-sen-nizamettin-ozel-wizbw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne güzeldin sen,

Kızıp sinirlendiğinde.

Hepimiz ağlamıştık,

Çekip gittiğinde.

Ne güzeldin sen,

Akşam serinliğinde.

Saçların dalgalanırdı,

Rüzgar değdiğinde.

Ne güzeldin sen,

Beyazlar giydiğinde.

Ben karalar bağlamıştım,

Sen evlendiğinde...', 'Ne güzeldin sen, Kızıp sinirlendiğinde. Hepimiz ağlamıştık, Çekip gittiğinde. Ne güzeldin sen, Akşam serinliğinde. Saçların dalgalanırdı, Rü...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-guzeldin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palyaço', 'palyaco-nizamettin-ozel-mdown', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dudağında ruj,

Gözünde rimel.

Bence onsuz,

Daha güzel.

Parmağı ojeli,

Saçı boyalı.

Palyaçoya çevirdiler,

Kadınları soyalı...', 'Dudağında ruj, Gözünde rimel. Bence onsuz, Daha güzel. Parmağı ojeli, Saçı boyalı. Palyaçoya çevirdiler, Kadınları soyalı......', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/palyaco-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Anı', 'olum-ani-fatih-erdogan-c751j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ölüyorum yakınımda kimse yok

feryadediyorum sesimi duyan yok

yok hemde hiç kimse 

daha iyi anlıyorum

allahım bir sen varsın

her yerde sen

artık azraille baş başayım

kimse gelmesin

son nefesimde kendimle hesaplaşayım

bırakın 

benim için ben ağlayayım', 'ölüyorum yakınımda kimse yok feryadediyorum sesimi duyan yok yok hemde hiç kimse  daha iyi anlıyorum allahım bir sen varsın her yerde sen ar...', ARRAY['Türk Edebiyatı','Şiir','Fatih Erdoğan']::text[], 8.5, '{"poet":"Fatih Erdoğan","poet_slug":"fatih-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olum-ani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben seni çok özledim', 'ben-seni-cok-ozledim-adem-atacak-dvqyf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tekerleği yalpalayan bisikletimi

Ve başaklar toprağı öperken

Karıncanın buğday taşırken yorulması gibi

Çok özledim seni

Kıraç topraklara boyunu anımsatan

Uzun serviler diktim

Parmak aralarımda üç beş saç telim

Ben seni çok özledim

Kayboluyor sesim çığlıklar içinde

Medet beklemem geceler benimle

Gelsen de gelmesen de

Ben seni çok özledim', 'Tekerleği yalpalayan bisikletimi Ve başaklar toprağı öperken Karıncanın buğday taşırken yorulması gibi Çok özledim seni Kıraç topraklara boy...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-seni-cok-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-nizamettin-ozel-c8j0l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Daha çiçek bile açmamıştı,

                          Tomurcuktu.

Gitti ellisindeki adama kaçtı,

                         Çocuktu.

Yıllar ardı ardına geçti,

                        Soğuktu.

Bir gün ansızın çıka geldi,

                       Hala çocuktu...', 'Daha çiçek bile açmamıştı,                           Tomurcuktu. Gitti ellisindeki adama kaçtı,                          Çocuktu. Yıllar ard...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cocuk-138-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanayım', 'yanayim-nizamettin-ozel-svbvm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşleyen demir ışıldasın; 

Ben emekten yanayım.

Hiç kimse aç kalmasın,

Ben ekmekten yanayım.

İnsanlar boşa ağlamasın; 

Ben gülmekten yanayım.

Kimse beğenmesin, varsın; 

Ben sevmekten yanayım.

Bunun adı vatansa; 

Ben bölmekten yanayım.

Gurursuz yaşamaktansa,

Ben ölmekten yanayım...', 'İşleyen demir ışıldasın;  Ben emekten yanayım. Hiç kimse aç kalmasın, Ben ekmekten yanayım. İnsanlar boşa ağlamasın;  Ben gülmekten yanayım....', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanayim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bucak Bucak', 'bucak-bucak-nizamettin-ozel-lx9gw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duvarda resmine baktım; 

Uzun uzun.

Gözlerin ırmak gibiydi,

Yurdumuzun.

Saçların dalga dalga,

Deniz deniz.

Yaşamaya çalıştım, bunca sene; 

Ruhsuz, bedensiz.

Ellerin ekmek saçardı,

Sıcak sıcak.

Çarem yok, kaçıyorum senden; 

Bucak bucak...', 'Duvarda resmine baktım;  Uzun uzun. Gözlerin ırmak gibiydi, Yurdumuzun. Saçların dalga dalga, Deniz deniz. Yaşamaya çalıştım, bunca sene;  R...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bucak-bucak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-adem-atacak-e8mdr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beyaz cennetlerden 

Sarı güller getirdim sana anne

Serin rüzgarlar eser

Ekin tarlasında bir teyze

Aynı sana benzer

Küçük ellerimle

Büyük dualar bırakıyorum anne

Bir gün kara menekşelere

Güneş çaprazdan vuracak

Biliyorum 

İhtimal değil,ben rüyamda gördüm

En geç bu sabah bir otobüs kalkacak

Sana doğru bir ben doğacağım

Yarın sana geleceğim anne

Sana hayat hikayemi

Biten aşklarımı 

Ve sevdiğim kızı getireceğim anne

Kırılan ümitlerim  cebimde

Sönük fenerimle koşarak geleceğim

Yılanlar girmiş çiçek tarlalarına

Çıkacak ağaç bulamadım anne

Günüme perde çekildi

Geceye muhtaç edildim

Otogara gittim

Oraya bilet vermiyorlar anne', 'Beyaz cennetlerden  Sarı güller getirdim sana anne Serin rüzgarlar eser Ekin tarlasında bir teyze Aynı sana benzer Küçük ellerimle Büyük dua...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anne-193-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorum', 'yorum-nizamettin-ozel-n5yeh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yorum, yorum! ; 

Bırak bunları.

Boşa uğraşma,

Seni anlamıyorum.

Yorum, yorum! 

Sus iki dakika.

Kadıköy’de,

Seni bekliyorum.

Yorum, yorum! 

Laf, laf, laf.

Anla artık,

Seni seviyorum...', 'Yorum, yorum! ;  Bırak bunları. Boşa uğraşma, Seni anlamıyorum. Yorum, yorum!  Sus iki dakika. Kadıköy’de, Seni bekliyorum. Yorum, yorum!  L...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yorum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-adem-atacak-lz9iv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hani derdin ya dere gibi çağlarım

Kardelen kadar soğuk,menekşe kadar nazlıyım

Sorma ki bir kurşun kadar hızlıyım 

Anlat ne oldu böyle gönül

Hani severdin de kendini koymazdın

Zor geldi deyip omuzlarını çatmazdın

Yoksa hasreti zor mu geldi

Bilirim ya sen hiç böyle yapmazdın gönül

Yanaklarından süzülen yaş mı yoksa

Acısını sakla,ararsın sonra

Bir gün severek koparsan 

Derdine derman değil dert ara gönül', 'Hani derdin ya dere gibi çağlarım Kardelen kadar soğuk,menekşe kadar nazlıyım Sorma ki bir kurşun kadar hızlıyım  Anlat ne oldu böyle gönül ...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-142-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya Tabiri', 'ruya-tabiri-nizamettin-ozel-mg3oc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbime özlemi bağlayıp; 

Uçurtma gibi uçuruyorum.

Ara sıra çocukları toplayıp,

Rüyalarını yorumluyorum.

Kiminin beyaz atlı prensi,

Kiminin pamuk prensesi,

Diyorum: “Bugün pazartesi”

İşten geldim, yoruluyorum.

Her şey masal olsa keşke; 

Rüyalarla süslü bir ülke.

Düşünsene, başkenti Mekke; 

Ben Medine’yi özlüyorum...', 'Kalbime özlemi bağlayıp;  Uçurtma gibi uçuruyorum. Ara sıra çocukları toplayıp, Rüyalarını yorumluyorum. Kiminin beyaz atlı prensi, Kiminin ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruya-tabiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temmuz', 'temmuz-nizamettin-ozel-843ke', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Temmuzdu gittiğinde,

Üstelik sıcaktı hava.

Gönül duvarını, işte o gün; 

Ne badana tuttu, ne sıva.

Temmuzdu gittiğinde,

Camı kırılmış pencere.

İlk önce ben düştüm,

Sonra resmin yerlere.

Temmuzdu gittiğinde,

Soğumamıştı hala terim.

Gelirsen gündüz gelme,

Geceme yıldız isterim...', 'Temmuzdu gittiğinde, Üstelik sıcaktı hava. Gönül duvarını, işte o gün;  Ne badana tuttu, ne sıva. Temmuzdu gittiğinde, Camı kırılmış pencere...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/temmuz-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün farklı bişey aolmalı', 'bugun-farkli-bisey-aolmali-adem-atacak-vcu0c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu gittiğim yol aynı eve çıkmasa

Üç şeker yine aynı çaya

İstemiyorum yine aynı kıza şiir yazmayı

Farklı bir şeyler yapmalı

Yani farklı bir şeyler olmalı bugün

Mesela dünden sonra bu gün gelmemeli

Bu günde ağızlık kullanmadan Bafra içmeli

Dökülmemeli yapraklar sonbaharlarda 

Mutluluk taşımalı hamallar çuvallarında

Beyaz eşya satılmalı manavlarda

Hatta güneş esmeden önce

Rüzgar doğmalı batıdan

Ateşi suya dökebilmeli

Bir tavşanı kovalayabilmeli

Bakıya inat akarsular

Bir anadan çiçek doğabilmeli

Yani bugün farklı bir şeyler olmalı', 'Şu gittiğim yol aynı eve çıkmasa Üç şeker yine aynı çaya İstemiyorum yine aynı kıza şiir yazmayı Farklı bir şeyler yapmalı Yani farklı bir ş...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bugun-farkli-bisey-aolmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oda', 'oda-nizamettin-ozel-37pwq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Odan bomboş şimdi; 

Masan sana küskün.

Kağıtlar etrafa saçılı

Gelecek diye bir gün.

Hani vardı ya çiçekler; 

Onlarda soldular.

Son nefeslerinde bile,

Bana seni sordular.

Gitti dedim, terk etti; 

Dönmeyecek bir daha.

Baktım ki can vermişler,

Çıkmadan daha sabaha.

Dün camını açtım,

Havalansın diye oda.

Boş koltuğuna bakındım,

Oda kırılmış sana, o da...', 'Odan bomboş şimdi;  Masan sana küskün. Kağıtlar etrafa saçılı Gelecek diye bir gün. Hani vardı ya çiçekler;  Onlarda soldular. Son nefesleri...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oda-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpücük', 'opucuk-nizamettin-ozel-lcfri', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şarkılarda aradım,

Şiirlerde adını.

Hiçbir yemekte bulamadım,

Senin dudak tadını.

Şekerdir, baldır,

Her kimi öpsen.

Beni bu uykudan kaldır! 

Öpmeden gideceksen...', 'Şarkılarda aradım, Şiirlerde adını. Hiçbir yemekte bulamadım, Senin dudak tadını. Şekerdir, baldır, Her kimi öpsen. Beni bu uykudan kaldır! ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/opucuk-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Badem Gözlüm', 'badem-gozlum-guler-ilgaz-b3yhe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen olmasaydın SEN! 

Badem ürer miydi? 

Çiçeğe yürür müydü? 

.....................................

Ben olmasaydım BEN! 

Badem badem olur mu? 

Çiçeğini görür müydü? 

.......................................

Sendeki göz olmasaydı

Ben senden içeri yol almasaydım

Badem gözlerimi

Gözlerine dikip te bakmasaydım

EĞER..........

Görebilirmiydik

Biz bademi

.........................................

Söyle badem gözlüm

Masallar gerçek olabilir miydi?', 'Sen olmasaydın SEN!  Badem ürer miydi?  Çiçeğe yürür müydü?  ..................................... Ben olmasaydım BEN!  Badem badem olur mu?...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/badem-gozlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yanımda Ol''da', 'sen-yanimda-ol-da-nizamettin-ozel-c2e3v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüzgar ol’da,

Götür beni uzaklara.

Yağmur ol’da,

Yağ kıraç topraklara.

Yıldız ol’da,

Aydınlat kara gecemi.

Fikir ol’da,

Umutlandır düşüncemi.

Bahar ol’da,

Çiçekler aç yolda.

Hiçbir şey istemem,

Sen yanımda ol’da...', 'Rüzgar ol’da, Götür beni uzaklara. Yağmur ol’da, Yağ kıraç topraklara. Yıldız ol’da, Aydınlat kara gecemi. Fikir ol’da, Umutlandır düşüncemi...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-yanimda-ol-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''ını Seversen Ne Var Bir Sorsan', 'allah-ini-seversen-ne-var-bir-sorsan-yusuf-onder-bahceci-zuz9n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öyle sitem sözlerle no''lur kalbimi kırma,

İnan ben seni çok severim üzülüp durma,

Derdim çoktur benim bir de sen vurma,

Allah''ını seversen ne var bir sorsan.

Gel Allah''ı seversen bana bir söz ver sen,

Bu Dünya''da yalnız seni sevdim bilirsen,

Sende bana yemin etsen söz sana desen,

Allah''ını seversen ne var bir sorsan....', 'Öyle sitem sözlerle no''lur kalbimi kırma, İnan ben seni çok severim üzülüp durma, Derdim çoktur benim bir de sen vurma, Allah''ını seversen n...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/allah-ini-seversen-ne-var-bir-sorsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız babam', 'yalniz-babam-adem-atacak-9k7zc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bu bakışları 

Yalnız babamın 

Bir kavgada tek kaldığında

Tepelerin yıldırım inen

Ağaçların kokularından aldım

Çarpık kentleşen 

Gözlerimin korkak bakışlarını

Yıkıyorum buldozerlerle

Sek  bir korkudan 

Acılar var boğazımı yakan 

Bir yudum su istiyorum

Korkularımı boğup 

Boğazımı söndürecek 

Ben

Yalnız babamın 

Çoğu kavgada kalabalık kaldığı

Tepelerin güneş açan ağaçların

Cesaretini istiyorum gözlerimde

Ben bu enkazın maliyetini

Babama yükledim', 'Ben bu bakışları  Yalnız babamın  Bir kavgada tek kaldığında Tepelerin yıldırım inen Ağaçların kokularından aldım Çarpık kentleşen  Gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalniz-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Kirli Bir Mendildir', 'ask-kirli-bir-mendildir-selahattin-yetgin-9v45h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bakışının karelerini düşledikçe ben

sensizliğin bütün eskimiş suretlerine

çizgiler çekiyorum

aralayıp aralayıp dudaklarını 

sevincin oluyorum

oysa, ben seni sevdikçe

mevsim hep kış kalmalı

bunu istemiyorum 

yağmur durmamacasına yağarken

ruhumda mevsimler hızla dönmeli

gözlerin şiir ellerin sevda olmalı

ben gözlerinde ağlamalı

ellerinde hiç yürünmemiş 

hiç bilinmemiş ülkeler aşmalıyım

bütün iyimserliğimin rüzgar direncinde

ışıltılı bir sırça köşktür düşünü gördüğüm

bu yalnızlık harmanında gülüşlerimle

yoksul bir sevdaya mendil açarım

üşür parmaklarım bölünür düşlerim

ben sevdayı ince gülüşünden tanırım

her sevdanın aşkla dönen değirmeninde 

ay parlak yıldızlar ak yüreğimiz çıplak

geceler gündüzlere inat yaşamaktır

umarsız sızılar büyüdükçe 

arar yüreğin efendisini sözcükler 

efsunlanır gizemin tütsü krallığı

köleler pazara çıkarılır ve umutların kelepçeleri kırılır

çünkü; aşk  /kirli bir mendildir/

sustukça kanla yıkanır/', 'bakışının karelerini düşledikçe ben sensizliğin bütün eskimiş suretlerine çizgiler çekiyorum aralayıp aralayıp dudaklarını  sevincin oluyoru...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ask-kirli-bir-mendildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben büyüyünce', 'ben-buyuyunce-adem-atacak-2452p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mutluluğu; çerçevelerdeki

Kahverengi ahşap verniklere

Kazıdım baş harflerinle

Ucuz hayatımı 

Pahalı sevdalara yüklemenin

Dramatik senaryolarından biriydi

Bu omuz izleri

Saçlarına ümitlerimi

Gözlerine geleceğimi düşürdüm

Her geçen zaman küçülüyorum

Ben büyüyünce 

Çocuk olmak istiyorum', 'Mutluluğu; çerçevelerdeki Kahverengi ahşap verniklere Kazıdım baş harflerinle Ucuz hayatımı  Pahalı sevdalara yüklemenin Dramatik senaryolar...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-buyuyunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitanem', 'bitanem-zernisan-aydogan-hs8ui', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bitanem

 

Dün yine seni andım bitanem 

inceden bir yağmur yağıyordu 

Anılar diye aradım birtanem 

Bende bir resmin vardı ağlıyordu 

Yüreğim sevgiden yana yoksul 

Gözlerimde kuraklık pul pul 

Düşünmemek imkansız ağlamak zordu 

Güneş son sefer el etti çamlara 

Severken dayanılmaz akşamlara 

Dayadım ellerimi buz gibi camlara 

Ellerimi görsen bir yığın kordu 

Sesini kahkahanı aradım köşe bucak 

Tozlu zarflar buldum dolu bir kucak 

Ümittir ne de olsa bitanem ümitler sıcak 

ışik durdu birden bire ses durdu zaman durdu 

Odam da yanlızlığım beni boğuyordu 

Dışarda inceden bir yağmur yağıyordu 

Erzurum

Zernişan Aydoğan', 'Bitanem   Dün yine seni andım bitanem  inceden bir yağmur yağıyordu  Anılar diye aradım birtanem  Bende bir resmin vardı ağlıyordu  Yüreğim ...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bitanem-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arar Olduk Dünümüzü', 'arar-olduk-dunumuzu-sahin-erturk-le68y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kör ettiler gözümüzü

Göremedik önümüzü

Bir vefasız kalbe düştük

Arar olduk dünümüzü

(26.01.2006-Yeni)', 'Kör ettiler gözümüzü Göremedik önümüzü Bir vefasız kalbe düştük Arar olduk dünümüzü (26.01.2006-Yeni)...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/arar-olduk-dunumuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümce sevince türkçe', 'olumce-sevince-turkce-adem-atacak-bp7a0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fiskiyeleri ıslatan düşüncelerimin üstünde

Sakalları uzamış 

Çıplak ayaklı şehrin 

Nefesini ölüm gibi hissediyorum ensemde

Boyun damarlarımdan gelen 

Yağlanmamış gürültülü adrenalin sesleri 

Şiir kadar sessiz 

Akıyor parmak aralarıma

Ben yalnız kalışımı sana bağlamam

Aklımı çelen 

Kirli camlardaki sinek seslerini

Galeye alacak kadar hassas 

Alnını gün ışığına değdirmemiş 

Tohumlar kadar umursamazım

Vakti geldiğinde

Yollar halka olup

Bindiğim uçan süpürgelerle savaşırken

Cadılar bayramında

Bilinçsizce yenen 

Bayram şekerleri gibi

Yine amaca ulaşamayacağım

Her geçen gün

Üst üste biniyor harfler

Her gün bir sonraki güne dair

Faturası ödenmemiş telefonlar kadar

Sessiz olacağıma yemin etsemde

En basitimin üstüne

Pahalı yorumlar yaptılar

Susmuyorum susamıyorum

Ben suda istemiyorum

Ben bir şeylerle boğuşurken

Tiz sesimden güvercinlerin

Uğur böceklerinin kaçmasını istemiyorum

Seni arkama alıp

Dalarken piramit tuzaklarına

Ayağım takıldığında

Düşerken görmemek değil de

Seni hiçbir yanımda görememek üzdü

Kaç harf biliyorsam

 O kadar dil biliyorum

Ölümce Sevince Gülümce Türkçe 

Seni okurken unuttum

Bütün öğrendiklerimi

Uykular benden mahmur uyanır

Unuturken öğrendim

Öğrenirken unuttum

Dizgini kopmuş kan kaybını', 'Fiskiyeleri ıslatan düşüncelerimin üstünde Sakalları uzamış  Çıplak ayaklı şehrin  Nefesini ölüm gibi hissediyorum ensemde Boyun damarlarımd...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/olumce-sevince-turkce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarıma Güller Gönder', 'mezarima-guller-gonder-sahin-erturk-9gqhk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pek yakında gideceğim

Ölümümü tez duyarsın

Hala beni seviyorsan

Mezarıma güller gönder

Üç Fatiha oku yeter

(26.01.2006)', 'Pek yakında gideceğim Ölümümü tez duyarsın Hala beni seviyorsan Mezarıma güller gönder Üç Fatiha oku yeter (26.01.2006)...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mezarima-guller-gonder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri bana anlatsın', 'biri-bana-anlatsin-dilek-kadioglu-z0d9h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'biri bana anlatsın 

anlatır mısın? dostum 

hayatı bana 

yaşıyor olmanın anlamı ne..? 

niçin doğarız..? 

hiç birşey cevap vermiyor 

isteklerime 

umut mu.? işe yaramıyor 

umutlar ben de 

aşkı tadmadım 

sevgiyi-sevilmeyi istedim 

tanımadım..bilemedim 

bir sevgi istiyorum 

bir cevap bekliyorum 

sonu yok sorularımın 

arayışlarımın da 

cevabı da.. 

herkes güldü bana 

ben hep ağladım 

ağlamayı yakıştırdılar 

oysa 

anlaşılmak istiyorum 

bilmediklerim çok daha 

içimi okusalar 

anlayacaklar 

şimdi 

insansız çöllerdeyim 

ben ağlıyorum.... 

ben ağlıyorum... 

26.01.2006 / beşiktaş', 'biri bana anlatsın  anlatır mısın? dostum  hayatı bana  yaşıyor olmanın anlamı ne..?  niçin doğarız..?  hiç birşey cevap vermiyor  istekleri...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kadıoğlu']::text[], 8.5, '{"poet":"Dilek Kadıoğlu","poet_slug":"dilek-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/biri-bana-anlatsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük.15 [Ne ilk ne de son]', 'dortluk-15-ne-ilk-ne-de-son-ercan-akbay-hsnv1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen benim dinlediğim,ne ilk ne  son şarkısın, 

Sen benim özlediğim,ne ilk ne son kadınsın, 

Alplerden bir çığ kopar,düşer gönül üstüne, 

Sen benim tutuştuğum,ne ilk ne  son yangınsın... 

ERCAN AKBAY 

[26.1.2006 Rüyada yazılmış bir şiir. ]', 'Sen benim dinlediğim,ne ilk ne  son şarkısın,  Sen benim özlediğim,ne ilk ne son kadınsın,  Alplerden bir çığ kopar,düşer gönül üstüne,  Sen...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dortluk-15-ne-ilk-ne-de-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkış dar geldi', 'cikis-dar-geldi-adem-atacak-0y0gt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Boşluğa düşmüş huzurumun

Derin mağara çıkışlarına astığı

Yapay gökyüzü hayali ile

Seni paylaşmak zorundayım

Ara ara seviyorum

Karanlıkların örttüğü çıkışları

Sevmediğim bir kurtuluşun

Serbest bıraktığı gün ışığından çıkarsam

Sana ağlayarak dönen

Vicdan azabımla

Gördüğüm pembe rüyaları vurmuş olurum

Haksızlığa uğrayan hayallerim

Zaten ne sana olur faydası

Ne de bana

Mevcut olanlarla avunduğum

Kanaatkar hayallerin

Üstü başı yırtık

Aşklarından başka bir şeyi kalmadı

Neyi özlersen

Tezadı gelen kavuşmalara

Alıştım gibi

İlk defa çıkışı buldum

Oda bana dar geldi', 'Boşluğa düşmüş huzurumun Derin mağara çıkışlarına astığı Yapay gökyüzü hayali ile Seni paylaşmak zorundayım Ara ara seviyorum Karanlıkların ...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/cikis-dar-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayyaş Şiirler', 'ayyas-siirler-ahmet-zekai-yildiz-ts61y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sağır gecelerde,

Yatağımı dar eden şiirlerdi.

Sözcükler yatağına sığmayan nehir,

Sözcükler boğazıma düğümlenen

Darağacı ilmeği.

Ve şiir beni arar dururdu; 

Uykusuz gecenin

Çıkmaz sokaklı labirentlerinde

Eküri koşarken.

Ve şiir beni sorardı,

Utanmaz sabahın ilk ışıklarına.

İlk günaydın diyen

Yine ayyaş şiirler olurdu,

Akşamdan kalma.

Elime alıp, okumazdım bile..

Kimin umurunda? 

Şiir gece boyu tüttürdüğüm

Sıgaranın külü kadar kırılgan.

Bursa''nın Deli Ayten''i gibi hoyrat.

Şiir her dilde

Yakılan özgürlük ateşlerinin

Yıldızlaşan hercai uçkunlarınca sayısız,

Ulaşılmaz ve sereserpe..

Ve benimle,

Dalına barışık zeytinler gibi dost.', 'Sağır gecelerde, Yatağımı dar eden şiirlerdi. Sözcükler yatağına sığmayan nehir, Sözcükler boğazıma düğümlenen Darağacı ilmeği. Ve şiir beni...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ayyas-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ela gözlüm', 'ela-gozlum-zernisan-aydogan-fgzgw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yagmur yagacak biliyorum

Yeryüzündeki bütün kötülükleri aritacak

Bir rüzgar esecek biliyorum 

Seni bana getirecek

Mutluluk kol gezecek sokaklarda

Bir gelsen ela gözlüm

Uykularim yarim kalmayacak 

Gecenin bilmem saat kaçinda

Böyle deliler gibi aglamayacagim

Sevdali siirler yazmayacak ellerim

Gözlerim yollara takili kalmayacak

Bir gelsen ela gözlüm

Umutlarim kalmayacak yarinlara

Sevdali türküler söylemiyecek dudaklarim

Resmine bakip bakip aglamayacagim

Mektubum geldi mi diye de sormayacagim

Ah bir gelsen ela gözlüm 

Sana dünyalari bagislayacagim', 'Bir yagmur yagacak biliyorum Yeryüzündeki bütün kötülükleri aritacak Bir rüzgar esecek biliyorum  Seni bana getirecek Mutluluk kol gezecek s...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ela-gozlum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜRSEM SENİ UNUTACAGIM(Gitme)', 'olursem-seni-unutacagim-gitme-seyhmus-sait-aydin-aliyh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gitme

Gözlerime bak.

Ellerimi tut,

Saçlarımı okşa

Mutluluğu buluyorum

O bakışta, o okşayışta.

Duygu seliyim şimdi,

Gözlerim çaglamakta.

Gitme,

Sen gittiğinde,

Yüreğim kan ağlamakta.



Sen Kal

Ben gitmeliyim.

Adını 

haykıra, haykıra,

Tüm ıssız sokakları gezmeliyim,

Elimde renkli tebeşirler,

Tüm duvarlara, resmini çizmeli,

Geçeceğin tüm yollara,

Adını yazmalıyım.

Gözlerimde güz yagmurları,

Yüreğimde ayrılığın acısı,

Bedenimde sensizliğin sancısı.

Sana mısra mısra, 

satır, satır,

Şiirlerle seslenmeliyim. 

Şimdi, 

şimdi ben gitmeliyim.



Sevmek

Acıya da, 

Cefaya da katlanmak demektir.

Eşsizim, emsalsizim.

Cefayı çekemeyen sefayı süremez,

Ve 

Hiç unutma sevdiğim

Her insan

Sevdiği uğruna ölmeyi bilemez.

Birtanem

Ağlamayı bilmeyen gülemez.



Sevenin gözündeki yaşı,

Kalbindeki aşkı görmeyen sevgili,

Ben de seni seviyorum diyemez..



Eğer gidersen, 

Çıkıp 

Adını sokaklar''da haykıracagım

Resmini duvarlara çizecegim

Elllerim cebimde saatlerce 

mecnun gezecegim

Köhne bir meyhanede oturup

Karşımda seni tahayyül edeceğim

Boş kadehleri yan yana dizip

Şarap yerine,

Ayrılıgı doldurup,

Bir kadeh senin yerine,

Bir kadeh de benim için,

Körkütük olana kadar,

Bu sevginin şerefine içeceğim.







Gidecegim diyorsun,

Sensizliğin,

Benim için ölüm olduğunu biliyorsun.

Anladım erişilmezim,

Anladım hal bilmezim.

Konuşma ne olursun.

Sus, 

gidiyorum deme artık,

Şimdi ben gidiyorum,

Bu aşkın çıkmaz sokağın''da

Silah gibi kullandıgın,

Gidiyorum sözlerini

Dayayıp şakağıma,

Kendimi vuracagım.

Yaşarken unutmak kolay olmayacak

Ancak Ölürsem

Ölürsem,

seni unutacagım.



Şeyhmus Sait Aydın.



18.01.2006.', 'Gitme Gözlerime bak. Ellerimi tut, Saçlarımı okşa Mutluluğu buluyorum O bakışta, o okşayışta. Duygu seliyim şimdi, Gözlerim çaglamakta. Gitm...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/olursem-seni-unutacagim-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayselim', 'ayselim-mahmut-simsek-7awf3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kelimelerle anlatamam özlemimi

Bilebilsen sana olan duygularımı

Ben hep içime gömdüm sevgimi aşkımı

Seni ölesiye özlemişim ayselim

Her an aklımdasın aklımdan çıkmıyorsun

Benim için başkasın özelsin özlemsin

Sevdasın sevda çiçeğisin sen ayselim

Seni ölümüne özlemişim ayselim

Bakışların bir ceylan ve mahsun bir sevda

Ben zamansız gelmişim dünyaya ne fayda

Gökteki yıldızlara bakıp avunsamda

Seni ölesiye özlemişim ayselim

Sana olan özlemim bitsin be güzelim

Sonsuzdur sana bu duygularım hislerim

Dinlemez gönlüm seni arzular ayselim

Seni her zaman candan gönülden severim

Unutamamki gönlüm arzular ayselim

İçim alev alev yanarım ben ayselim

Dinsin bu acılar bitmesin sana sevgim

Sen bir başkasın benim için nar çiçeğim', 'Kelimelerle anlatamam özlemimi Bilebilsen sana olan duygularımı Ben hep içime gömdüm sevgimi aşkımı Seni ölesiye özlemişim ayselim Her an ak...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayselim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüdüm', 'usudum-zati-erbas-tsdz2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bulutların 

yeryüzüne indiği

gün

öğrendim

ayrılığı.

üşüdüm', 'bulutların  yeryüzüne indiği gün öğrendim ayrılığı. üşüdüm...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/usudum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiklerim', 'sevdiklerim-mustafa-bilgili-uc5ro', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretlik bir alev oldu bağrımda,

Şu mahzun kalbimi yakar da gider,

Tüm sevdiklerim dizilmişler karşıma,

 Her biri el gibi,el gibi bakar da gider.

Genç yaşta ağardı simsiyah saçım,

Bir anda yıkıldı tahtım ve tacım,

Nerede anam babam,haniya bacım,

Burnuma gül gibi kokar da gider.

Gönül eğlenmiyor gurbet ellerde,

Şarkılarım yarım kaldı dillerde,

Size doğru gelen toprak yollarda,

Bu canım sel gibi akar da gider.

Siyah saçlarını öremediğim,

Gonca güllerini deremediğim,

Çok seneler oldu göremediğim,

Yarim kaşlarını yıkar da gider.

                                            05.05.1980

                                          K Ü T A H Y A', 'Hasretlik bir alev oldu bağrımda, Şu mahzun kalbimi yakar da gider, Tüm sevdiklerim dizilmişler karşıma,  Her biri el gibi,el gibi bakar da ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgili']::text[], 8.5, '{"poet":"Mustafa Bilgili","poet_slug":"mustafa-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevdiklerim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Ağararınca', 'gun-agararinca-dervis-hakan-eh430', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıldızımsın, ayımsın, gökyüzünde güneşimsin 

Sen ki günün sahibi, yerin göğün Mâlik''isin

Gün sen ile ağarır, şanın ne yücedir senin 

Yüzlerimiz aydınlık bizim, talip olmuşuz sana,

Saf tutmuşuz yoluna,  gün ağarınca

Bir busen erişti bize, olmaz mı sana canlar feda!', 'Yıldızımsın, ayımsın, gökyüzünde güneşimsin  Sen ki günün sahibi, yerin göğün Mâlik''isin Gün sen ile ağarır, şanın ne yücedir senin  Yüzleri...', ARRAY['Türk Edebiyatı','Şiir','Derviş Hakan']::text[], 8.5, '{"poet":"Derviş Hakan","poet_slug":"dervis-hakan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gun-agararinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum gülüm', 'erzurum-gulum-zernisan-aydogan-deeab', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşenin dostu olmaz diyorlar

Vallahi yalan inanma  gülüm

Bu şehirde yüzlerce insan düşüyor

Her düşen bedene el uzaniyor

Burasi nere mi!  Erzurum gülüm 

Dişarda yürürken çok üşüyorsun

Bir dosta rastlayinca ısınıyorsun

Yüreğindeki sevgiyi hissediyorsun

Burasi nere mi!  Erzurum gülüm

Yazi serin kışı ağır geçiyor

Baharin yüzünü çok az görüyor

Bu şehirde sicak insanlar yasiyor

Burasi nere mi! Erzurum gülüm

Dim dik ayakta durur asla yıkılmaz

Yalanla dolanla hiç işi olmaz

Yardimi Allah''tan ister kula yalvarmaz

Burasi nere mi!  Erzurum gülüm

Azla yetinir isyan etmez  şükreder

Semaya açılır nasırlı eller

Misafirperverdir bütün yürekler

Burasi nere mi! Erzurum gülüm.', 'Düşenin dostu olmaz diyorlar Vallahi yalan inanma  gülüm Bu şehirde yüzlerce insan düşüyor Her düşen bedene el uzaniyor Burasi nere mi!  Erz...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/erzurum-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Her Şeyimsin', 'sen-benim-her-seyimsin-alper-yilmaz-t2fgs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen benim derdim değil aşkım,

Hüznüm değil sevincimsin.

Dünüm,bugünüm,yarınım; 

Bütün ömrümsün benim.

Kalbin,kalbim ile her an,

En saklı ama en bildiğim yerdesin.

Ruhum,bedenim feda yoluna,

Sen benim her şeyimsin!', 'Sen benim derdim değil aşkım, Hüznüm değil sevincimsin. Dünüm,bugünüm,yarınım;  Bütün ömrümsün benim. Kalbin,kalbim ile her an, En saklı ama...', ARRAY['Türk Edebiyatı','Şiir','Alper Yılmaz']::text[], 8.5, '{"poet":"Alper Yılmaz","poet_slug":"alper-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-benim-her-seyimsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana gidiyorum', 'sana-gidiyorum-adem-atacak-hqmrw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beynimin kanlandırdıgı gözlerimle

Boş bakan Aşti peronları

Zaten tanışıyor birbiriyle

Yabancılaşması gereken duygularımın 

Pişmanlaşan karmaşası

Karanlıga itelesede

Ben yinede beyaz ışıkları tırmalıyorum

Nekadar anlam varsa 

Dilimin düğümlendigi yerde kaldı

Yoksa diyorum bazen acaba

Ben gitmek istemesemde 

Eziliyorum otobüsün karanlıgında

Üzgünleri oynayan

Büzgün cesaretimin

İntiharını gömdük artık

Korkuların rengi gözlerimde 

Ya lens takmalıyım 

Yada ölene kadar uyumalıyım

Herşeyin karışık oldugu

Cevapsız problemleri

Önüme koysanda 

Samimiyetin çiçek açtıgı

Secde eden bütün güzellikleri 

Sana diliyorum 

Akcigerlerimde hissettigim 

Nikotin bile beni anlamıyor

Birgün

Masalarda adı geçen daglarda 

Maneviyatın dogurdugu açlık kadar 

Geçici olsun üzüntülerin

Sana gelmeye gidiyorum 

Kavramları yıkıp

Sana ad bulmaya gidiyorum

Yok olurken

Anatomimi yeryüzünde bırakmaya gidiyorum 

Tüylerimin dikildigi 

Şaklaban paradokslara inat 

Başkenti sana

Seni Allaha emanet ediyorum', 'Beynimin kanlandırdıgı gözlerimle Boş bakan Aşti peronları Zaten tanışıyor birbiriyle Yabancılaşması gereken duygularımın  Pişmanlaşan karma...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sana-gidiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilseydim Ele Gidemezdin Sen', 'bilseydim-ele-gidemezdin-sen-yusuf-onder-bahceci-oqalc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yazdığım şiirler harap ediyor,

O kendini bana serap ediyor,

Beni sevmiş ama ele gidiyor,

Bilseydim ele gidemezdin sen.

Sevmiyor zannettim gülemedim,

Hâlbuki ne severmiş bilemedim,

Aramızda dağlar var gelemedim,

Bilseydim ele gidemezdin sen.

İçim kan ağlar nedendir neden,

Yıllardır  haber gelmedi senden, 

Derdim sensin ayrıyım senden,

Bilseydim ele gidemezdin sen....', 'Yazdığım şiirler harap ediyor, O kendini bana serap ediyor, Beni sevmiş ama ele gidiyor, Bilseydim ele gidemezdin sen. Sevmiyor zannettim gü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilseydim-ele-gidemezdin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halam Nebiş''in Üç Gülü', 'halam-nebis-in-uc-gulu-munevver-senol-3yo1r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dedim ya, biz çok bağlı bir aileyiz, halam Nebiye''nin üç kızı ve dünya güzeli üç de kız torunu var. Büyük torunu Burcu''nun, benim küçük oğlum Burak ile bir gün arası var. Hep anlatırımya, annem Merzifon''a bana gelirken, halam da Burcu''yu alır o da gelirdi. Çünkü Burcu''nun annesi Asuman, Zeynep Kamil hastanesinde jinekolog doktordu. Burcu''ya da halam bakıyordu. Aman Allah''ım sevimli mi sevimli... Ama kızdımı hemen tırnaklarını çıkaran bir panterdi. Herkeste mutlaka Burcu''nun tınak izi vardır. 

    Şimdi sıra, dünya güzeli, başarılı bir tekstil mühendisi,  Burcu''nun bir küçüğü olan Başak''ta. Sapsarı saçlar, derin derin bakan yaprak yeşili gözler. Anlatamam tıpkı tablo gibi. O da bende kalmayı ve Çiğli''deki hava lojmanlarını çok severdi. Gene bende kaldığı zaman, ben en tepede oturuyorum. Kantinde aşşağıda, nizamiyeye yakın. Güle oynaya bayır aşşağı indik. Ama çıkarken,  ''''ben yoruldum, arabasız gitmem, benim babamın arabası var.  Ben yürümeye alışkın değilim'''' dedi ve oturduğu yerden kalkmadı. Neyse ki eşim jiple geliyordu. O  jipten indi, yerine Başak bindi ve paketleride ona  verdik. Biz eşimle yürüyerek çıktık ki, Başak evin yanındaki parkta kaydıraktan kayıyor. Tabi poşette elinde, içindekileri merak ediyor musunuz? Yumurtalar omletlik olmuş, bir de üstelik ''''alın be poşetinizi bununla zor kaydım'''' demez mi? O da şimdi dünya güzeli, babası Bilgin Karaman gibi, başarılı bir hukukçu. 

   Geldik üç numaralı güle, o gül de halamın küçük kızı Ülkü''nün biricik kızı Aslı. Ben ona maviş derim. Gerçektende bu kadar güzel mavi göz az bulunur. Onu da Allah ona vermiş. Onlarda kaldığım birgün ben Aslı''nın odasındaki çekyatta yattım. Sabah onun sevgi çığlıklarına uyandım ki uyku tulumunun içinde, karyolasının muhafazalarına tutunmuş, yumuk gözlerinin içinde maviş maviş iki göz. Altta üstte iki tane sırıtan beyaz dişlerle,  bana gülücükler atan Aslıcık. Benim büyük oğluma büyük abi, küçüğüne de küçük abi derdi. Aslı, gene birgün Çiğli''de lojmandayız. O zaman Aslı da dört-beş yaşlarında. Her yere küçük abisiyle gitmek istiyor, küçük abiside ilkokul sonlarda falan. O da Aslı''yı çok seviyor ama arkadaşlarıylada oynamak istiyor. Aslı bunu sezdi bıdıcık boyuyla, küçük abisi gitmesin diye, odadan sandalye sürükleyerek getiriyor, kapının önüne oturup yolu kesiyordu. Ama küçük abi balkon kapısından çoktan kaçıp gitmişti bile. Aslıcığın, o maviş gözlerinden sicim gibi dökülen yaşlarla ''''küçük abi'''' diye ağlayışını hiç unutamam. Evet Aslıda şimdi üniversite son sınıf talebesi, annesi  Ülkü Aykuz  gibi hukukçu değil ama başarılı  bir iş adamı ve değerli bir insan olan  babası Aydın Aykuz gibi,  Aslı da  müthiş bir iş kadını olabilir.

   Halamın üç gülünü anlatabildiysem eğer, ne mutlu bana. Bu fikir Aslıdan çıktı. Aslıcığım sana çok teşekkür ediyorum. Çünki ölümsüz olan  bu anıları kaleme almama fırsat verdin. Bende bunu dostlarımla paylaştığım için  çok mutlu oldum. İyi ki varsınız, sizleri çok ama çok seviyorum. 

Münevver Şenol. 26.1.2006', 'Dedim ya, biz çok bağlı bir aileyiz, halam Nebiye''nin üç kızı ve dünya güzeli üç de kız torunu var. Büyük torunu Burcu''nun, benim küçük oğlu...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/halam-nebis-in-uc-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görünen adam', 'gorunen-adam-adem-atacak-bgadf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İki kaşımın bana

En yakın tarafsızlığından

Düello eşitliğinde uzaklaşırken

Yüzümü sana seriyorum

Varım yoğumun aynasıdır

Eşkali belirsiz

Saydam yalanlarımın

Arkasını görmeyen kalmadı

Ters ve düzün farkını

Baş harflerinden anlıyorum

Yani benim sürgülü

Kapılar arkasında

Kaçmayı bekleyen gözlerim

Sırtında kamçı izleri bulunan

Geçmişim olmadı hiç

Hayalperest adımlarımın

Reel duruşuyla

Paralel sapması

Ellerimi kırıyor ümitsizliğimin

Benim kararlı umutsuzluklarım

Bunalım sevinçlerim

Yani ben hiç olamadım benim

Boyun hizama geldi 

Yağmalanmış rüyalar

Aynı adımı tekrar atarken

Çatlan topraktan

Ben ve benim gibi

Yatanları görmekteyim

Hesabı kabarmış defterden

Veresiye yarınları çaldırırken

İlk defa nefret ettim kendimden', 'İki kaşımın bana En yakın tarafsızlığından Düello eşitliğinde uzaklaşırken Yüzümü sana seriyorum Varım yoğumun aynasıdır Eşkali belirsiz Say...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gorunen-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar beyaz', 'kar-beyaz-nazan-i-zmirli-hs0br', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kar  beyaz 

sevdamı

kara  kışlara 

salma.

dokunamasanda

titretir  yüreğini

sevdam

üşütür 

bilirim

seni

ama 

beni

sensizlikte

dondurma

26.01.2005-antalya', 'kar  beyaz  sevdamı kara  kışlara  salma. dokunamasanda titretir  yüreğini sevdam üşütür  bilirim seni ama  beni sensizlikte dondurma 26.01....', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kar-beyaz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben seni unutamadım', 'ben-seni-unutamadim-adem-atacak-zvngl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İmla kurallarına uygun

Sarışın cümlelerle

Ter kokan bir akşamın 

Kirası ödenmemiş bekar evlerinde

Ben seni otuz beş milyona unuttum

Simit satan çocuğun

Çığlıklarında boğulan bir pişmanlıkla

Uyandım otuz beş milyonluk somut düşüncelerle

Beynimi tırmalar çekirdek sesleri

Tırnakları uzun bir soru cümlesi

Ben seni otuz beş milyona unuttum

Bugün param yok

Ben seni unutamadım', 'İmla kurallarına uygun Sarışın cümlelerle Ter kokan bir akşamın  Kirası ödenmemiş bekar evlerinde Ben seni otuz beş milyona unuttum Simit sa...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-seni-unutamadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz Dünya', 'olumsuz-dunya-mahmut-simsek-ceds2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamak öyle zorki şu fani dünyada

Her şey,her şey,yapmacık geliyor,insana

Doğumla gelen bebek,gençlik ve yaşama

Şu kısacık görünen,yapmacık dünyada

Kimi ahenkle dans eder güler zevkinden

Kimide ah eder,ömründen,eziklikten

Talihsizlik bırakmaz etkiler derinden

Şu,up uzun görünen,yapmacık dünyadan

Çırpınışlar,haykırışlar gelir peşimden

Uğultular,gariplikler gelir derinden

Zevk alamıyorum artık ben,bu seyirden

Yapmacık dünyada yaşarız,ta ezelden

Gençlikten sonra,olgunluk vardı eskiden

Ve yaşlılık vardı zeminden,ezelden

Şimdi onlarda kalmadı kesildi birden

Şu,uzun görünen,yapmacık,dünyamızdan

Hastalık sardı bizi,çepe çepe birden

Kimi kanserden,kimi vebadan,veremden

Kimi kalpten,kimi tifodan,eyidisten

Trafik kazası ve töreden.terörden

Uğultular,haykırışlar gelir derinden

Çırpınışlar,gariplikler,gelir peşimden

Gençlik,ihtiyarlık,yoktur artık şimdiden

Şu,up uzun görünen,yapmacık dünyadan', 'Yaşamak öyle zorki şu fani dünyada Her şey,her şey,yapmacık geliyor,insana Doğumla gelen bebek,gençlik ve yaşama Şu kısacık görünen,yapmacık...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/olumsuz-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serenat-Caz', 'serenat-caz-asude-gediz-z66wa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmura susayan toprak

Hazanı bekleyen yaprak

Işığa tutsak gecedir sevdam

Filizlendi hüzün çare bulamam

El sürmezsen toprak yağmur alamaz

Sevgimiz büyüdü dünyaya sığmaz

Sevda bahçemizde bir kış, bir yaz

Filizlendi hüzün çare bulamaz

Gece gözler kurulmuş baş köşeye 

şiirimde arz-ı endam eder.

Bu yürek buna dayanamaaaz

Filizlendi hüzün çare bulamaz...

Sevdam yanında booya boya biraz

pembeye maviye istersen beyaz

kara olmaaaz. Kara sevda karagözlü yare yaraşır ya

hadi annnlat, anlat biraz......

Aşk meleği  nasıl ne zaman gelir bilinmez

Rüyanda serenat yaparsın dünyanda cazzz.....

Sevmişim seni yürek susdan anlamaz

Filizlendi hüzün çare bulamaz

Yürek coşar, yürek sızlar laf anlamaz

Yürek coşar, yürek sızlar..................Susmaz', 'Yağmura susayan toprak Hazanı bekleyen yaprak Işığa tutsak gecedir sevdam Filizlendi hüzün çare bulamam El sürmezsen toprak yağmur alamaz Se...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/serenat-caz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Dağlar Aşılmaz Aşılmaz Gülüm', 'bu-daglar-asilmaz-asilmaz-gulum-yusuf-onder-bahceci-zp1h9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağlar üzerine yazılan şiirler çok olur,

Benim kalbimde hüzün hep  hüzün olur,

Şimdi çok sevdiğim yârim gider el olur,

Bu dağlar aşılmaz, aşılmaz Gülüm.

Dağlarda gezeceğim, seni seveceğim,

Sen beni seversin, seversin diyeceğim,

Rüzgarlar haber getirir, ben bileceğim,

Bu dağlar aşılmaz, aşılmaz Gülüm.

Bu karlı dağlar aşılsa, hem arkası vardır,

Senin sevgin kalbimde bu Dünya dardır,

Deki Allah Aşkıyla yanan gönüller vardır,

Bu dağlar aşılmaz, aşılmaz Gülüm.', 'Dağlar üzerine yazılan şiirler çok olur, Benim kalbimde hüzün hep  hüzün olur, Şimdi çok sevdiğim yârim gider el olur, Bu dağlar aşılmaz, aş...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-daglar-asilmaz-asilmaz-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey iki olmalı', 'hersey-iki-olmali-adem-atacak-p7t3p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanaklarını okşayan iki damla yaş

Ve anlatan iki sözcük seni

Ben hep iki olmak isterdim

Neden mi? Biri sen diğeri ben

Kıskanırım ikiden fazla yaşı

Korkarım okşamasın yanaklarını

Dedim ya, her şey değil ki ben

Bilirsin severim seni

Gülersem hep iki defa

Biri senin diğeri de benimki

Ve dedim ya, ağlarsam da iki defa

İstediğin iki şey olmayı isterdim

Düşünmedim ama olursa bir gün

Arkamdan salladığın iki mendil olmayı

Ve isterdim ki unutmadığın dün

Ben arzuladığın iki şey olmayı isterdim

Dedim ya, biri sen diğeri de ben', 'Yanaklarını okşayan iki damla yaş Ve anlatan iki sözcük seni Ben hep iki olmak isterdim Neden mi? Biri sen diğeri ben Kıskanırım ikiden fazl...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hersey-iki-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miras', 'miras-nizamettin-ozel-g583f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zengin bir işadamıydı; 

Servetini düşündü.

Daha orta yaşlıydı,

Hep mutlu göründü.

Hiç ummadığı bir anda,

Bir hastalığa yakalandı.

İki-üç hafta sonra,

Ona bir mezar hazırlandı.

Cenazesinde toplandı,

Eşi dostu, yakını.

Onca servetten iyi kötü,

Hepside aldı payını…', 'Zengin bir işadamıydı;  Servetini düşündü. Daha orta yaşlıydı, Hep mutlu göründü. Hiç ummadığı bir anda, Bir hastalığa yakalandı. İki-üç haf...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/miras-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen bulanır sular', 'gidersen-bulanir-sular-adem-atacak-g2081', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adı konulmamış duygular 

Muhtaç kaybolan tariflere

Bir hayat akar 

Belli belirsiz  portrelere

Dağ kırlangıçlarının özgürlüğünde

Ezilir serin rüzgarlar

Boğulur medetler dar ağacında

Gidersen bulanır sular

Ne olur  burada kal', 'Adı konulmamış duygular  Muhtaç kaybolan tariflere Bir hayat akar  Belli belirsiz  portrelere Dağ kırlangıçlarının özgürlüğünde Ezilir serin...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gidersen-bulanir-sular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamıyorum', 'anlamiyorum-nizamettin-ozel-6qysd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlayamıyorum; 

Şu kadın milletini.

Daha mı güzel oluyorlar,

Ufacık kumaşlara,

Sıkıştırarak etini.

Anlayamıyorum; 

Şu kadın milletini.

Hemen herkese gösteriyorlar,

Orasını burasını,

Bütün iskeletini…', 'Anlayamıyorum;  Şu kadın milletini. Daha mı güzel oluyorlar, Ufacık kumaşlara, Sıkıştırarak etini. Anlayamıyorum;  Şu kadın milletini. Hemen...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anlamiyorum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tecavüz', 'tecavuz-nizamettin-ozel-so1ko', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dere kenarına atılmış,

Genç bir kadının ölüsü.

Cüzdanından kimliği çıktı,

Adana’nın bir köylüsü.

Yerde parçalanmış cesedi,

Lime lime organları.

Tecavüz edilmiş defalarca,

Toprakta iz bırakmış kanları.

Hemen otopsiler yapıldı,

Gece gündüz, bir dizi.

Yinede bulunamadı,

Ne ip ucu, ne parmak izi.

Bu ne bir, ne beş; 

Bunun gibi yüzlercesi.

Ölüp gitti tek tek,

Bir sonbahar gecesi.

Şimdi diyeceksiniz ki,

İstanbul nere, Adana nere.

Ne umutlarla gelmişti,

Halbuki bu şehre…', 'Dere kenarına atılmış, Genç bir kadının ölüsü. Cüzdanından kimliği çıktı, Adana’nın bir köylüsü. Yerde parçalanmış cesedi, Lime lime organla...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tecavuz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Saltanatı', 'askin-saltanati-kamer-taskin-23xay', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gösteriyor, baktırmıyor,

Özletiyor, kavuşturmuyor,

konuşturuyor, dinletmiyor,

Yakıyor, acıtıyor.

Oturmuş baş köşeye,

Zulmediyor bize,

Bitmiyor,

Bitmiyor bu,

Aşkın saltanatı.', 'Gösteriyor, baktırmıyor, Özletiyor, kavuşturmuyor, konuşturuyor, dinletmiyor, Yakıyor, acıtıyor. Oturmuş baş köşeye, Zulmediyor bize, Bitmiy...', ARRAY['Türk Edebiyatı','Şiir','Kamer Taşkın']::text[], 8.5, '{"poet":"Kamer Taşkın","poet_slug":"kamer-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/askin-saltanati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana Yurt', 'ana-yurt-sadik-altinkaynak-9167f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anayurt

Yaradan Adem’ i

Yoktan var etti

O’ na ilminden

Esmayı öğretti

O’ na secde etsinler diye

Meleklere emretti

Sonra eş olarak

Havva’ yı halk etti

İşte 

Bu noktadan başladı

İnsanlık tarihi

İşte

Bu noktada ters döndü

Beşerin talihi

Lain iblis

Kandırınca Havva''yı

Yedirdi O''na 

Nehy-edilmiş elmayı

Adem de 

Yalnız bırakmamak için O''nu

Isırdı yasak meyvayı

İşte

O anda kaybetti davayı

Veda ettiler

Anayurt Cennet'' e

Sürüldüler 

Dünya denen gurbete

Kaçarsak nehî-den

Uyarsak emir-e

Tekrar kavuşabiliriz

O kutlu ve mutlu yere

Sadık ALTINKAYNAK', 'Anayurt Yaradan Adem’ i Yoktan var etti O’ na ilminden Esmayı öğretti O’ na secde etsinler diye Meleklere emretti Sonra eş olarak Havva’ yı ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ana-yurt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara leke', 'kara-leke-adem-atacak-admty', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kokan etlere

Sıkışan,gökkuşağının

Sekizinci rengiydi bu kara leke

Sürünen bir ben değilim

Bak sümüklü böceğe

Bak kertenkeleye

Bu düdük can vermez

Elbet yalnız değilim

Takılı kalan musalla duvarına

Hep benim sesim

Bir zamanlar nefestim

Şimdi nerdeyim

Baş ucumda sapma taşı

Hep başıma vurur

Bir ölü

Mekanı günaha sıfır

Kürekle serptiler üstüme yorganı

Ciğerim yırtıldı.

Duyan olmadı', 'Kokan etlere Sıkışan,gökkuşağının Sekizinci rengiydi bu kara leke Sürünen bir ben değilim Bak sümüklü böceğe Bak kertenkeleye Bu düdük can v...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kara-leke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardan Adam', 'kardan-adam-nizamettin-ozel-d8u82', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim isyanımı taşır,

Bu sokaklar, bu caddeler.

İnsanıma sınır koyar,

Anayasa’daki maddeler.

Benim insanım duygusaldır,

Dokunsan kırılır camlar.

İçinde volkan taşır,

Bu kardan adamlar…', 'Benim isyanımı taşır, Bu sokaklar, bu caddeler. İnsanıma sınır koyar, Anayasa’daki maddeler. Benim insanım duygusaldır, Dokunsan kırılır cam...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kardan-adam-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Sevda', 'gizli-sevda-nizamettin-ozel-q12h9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çekip gitmekti,

Belki de tek hatası.

Bir gün çıka geldi,

Mayıs’ın ilk haftası.

Hepimiz şaşırdık, 

Oturunca yanımıza.

Döndüm dedi artık,

Döndüm işte aranıza..

Hiç değişmemişti,

Onca seneye rağmen.

Hala yakışıklı, gençti; 

Tam bir centilmen.

Söz düğümlenip gırtlağa,

Sordu “Elif nerde? ”

Cevap verdi, Ali Ağa,

Dedi: “bıraktığın yerde.”

Bir çırpıda gitti,

Görmek için Elif’i.

Onu eş yapmıştı,

Tanımadığı elin herifi.

Dayanamadı yüreği,

Duramadı daha fazla.

Sonra oda evlendi; 

Sevmediği bir kızla…', 'Çekip gitmekti, Belki de tek hatası. Bir gün çıka geldi, Mayıs’ın ilk haftası. Hepimiz şaşırdık,  Oturunca yanımıza. Döndüm dedi artık, Dönd...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gizli-sevda-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmtiyazlı aşk', 'i-mtiyazli-ask-adem-atacak-t7t5o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İmtiyazlı aşkların

Çelişkisini taşıyorsun gözlerinde

Mat boyanmış odamın

Gölgeli tavırlarında bozulan

Psikolojimi gönderiyorum

Her köşeyi tutan kafa ağrılarının

Çekik gözlü merhametinde eziliyorum

Birbirine değmeyen kuyrukların

Çürük ipli dizginleri ellerimde

Dört nala sana geliyorum

Çatık kaşlı gecelere 

Kaf dağından iner ümitlerim

Dik yokuşta

Aksayan atlara binerim', 'İmtiyazlı aşkların Çelişkisini taşıyorsun gözlerinde Mat boyanmış odamın Gölgeli tavırlarında bozulan Psikolojimi gönderiyorum Her köşeyi tu...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/imtiyazli-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Ülkesi', 'dusler-ulkesi-nizamettin-ozel-5cf5b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerin; 

Uzak denizlere benzerdi.

Kirpiklerin dalgalandıkça,

Sanki su üzerinde gezerdi.

Ellerin; 

Ekmek kadar tazeydi.

Keşke o narin parmakların,

Benim bedenimde gezeydi.

Saçların; 

Kömür gibi simsiyahtı.

Ayrılık vardı er yada geç,

Terk etmek tacı tahtı.

Belalım; 

Yalan yere yaşadık,

Yalan yere sevdik.

Ve bir yalan gibi ayrıldık…', 'Gözlerin;  Uzak denizlere benzerdi. Kirpiklerin dalgalandıkça, Sanki su üzerinde gezerdi. Ellerin;  Ekmek kadar tazeydi. Keşke o narin parma...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dusler-ulkesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk kayıplar', 'i-lk-kayiplar-adem-atacak-q35sg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çocuk bahçelerinde sallanan

Beyaz tenli geleceğimle

Ters düştüm uzun zaman 

Başı dönen hayallerimle

Düşerken kiraz ağaçlarından 

Pansuman edilen hayallerime 

Gölge düşüren aşklarım bindi

Çok şey değişti

Çamurdan yaptığım evlerin kokusu

Hala tırnak aralarımda

Derin çukurlar kazıyorum 

Yenik düşmeden gün batımına

Dolaptan aldığım  eski bir entariden

Lolipop harçlıkçısı

Baba annem öldü sonra dedem

Ben ne çocuk bahçelerinde

Düşen misketlerimin 

Ne de bakkal muhittin  in şekerlerinin peşindeyim.

Ben ilk kayıplarını veren

Bıyıkları terlememiş, çocukluğumu özledim', 'Çocuk bahçelerinde sallanan Beyaz tenli geleceğimle Ters düştüm uzun zaman  Başı dönen hayallerimle Düşerken kiraz ağaçlarından  Pansuman ed...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ilk-kayiplar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahliye', 'tahliye-nizamettin-ozel-z5uy0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Artık ikisi de özgürdüler; 

Havada kuşlar kadar.

Bir birine bakıp güldüler,

Sonra sevinçten ağladılar.

Tamı tamına on-üç sene,

Ve güneşsiz daracık bir hücre.

Umutlarını tüketmedi gene,

Geçen onca yıl ve de süre.

İlkin güneşi gördüler, 

Aydınlatırken yüzlerini.

Karanlık gecelerde geçirmiyorlar,

Onlar artık gündüzlerini…', 'Artık ikisi de özgürdüler;  Havada kuşlar kadar. Bir birine bakıp güldüler, Sonra sevinçten ağladılar. Tamı tamına on-üç sene, Ve güneşsiz d...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tahliye-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örümcek', 'orumcek-nizamettin-ozel-mwuyw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tavanda ağ kurmuş,

Saygı değer örümcek! ..

Kendi isteğinizle gitmeniz,

Beni mutlu edecek.

Yok eğer gitmezseniz,

İşte süpürgenin sapı.

Canınızı yakmak istemiyorum,

Haydi açık kapı.

Dost olarak ayrılalım,

Seni unutamadığımı bil.

Teşekküre gerek yok,

Hiç önemli değil…', 'Tavanda ağ kurmuş, Saygı değer örümcek! .. Kendi isteğinizle gitmeniz, Beni mutlu edecek. Yok eğer gitmezseniz, İşte süpürgenin sapı. Canını...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/orumcek-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmekten sıkıldım', 'gormekten-sikildim-adem-atacak-2nxzw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Islak kaldırımlara 

Günahlar ayak basarken

Sabahın bakışlarını

Küçük cüsseli adamlar karşılar

Tavana astığım boşluklar biner

Göğüs kafesime

Karanlık gürültülerin

Boşboğaz seslerini çeker tramvaylar

Dev adamlar bir mendilciyi ezer geçer

Nefes almakta zorlanan

Ben işe,yelkovanlar akşama gider

Boğulan devasa günahları

Aydınlatamaz şehrin sarı gözleri

Artık konuşamaz 

Otobüs duraklarının boş gürültüleri

Çaresizlik ümüğüme dolalı

Çıksam iki ekmek kırıntısıyla 

Kiralasam dağları

Görmekten sıkıldım 

Hep aynı zımbırtıları', 'Islak kaldırımlara  Günahlar ayak basarken Sabahın bakışlarını Küçük cüsseli adamlar karşılar Tavana astığım boşluklar biner Göğüs kafesime ...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gormekten-sikildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuktuk O Zamanlar', 'cocuktuk-o-zamanlar-nizamettin-ozel-4ecr0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çocuktuk o zamanlar,

Kırmıştık bütün camlarını.

O yine de bana yolladı 

En içten selamlarını. 

Çocuktuk o zamanlar,

Başımızda yoktu aklımız.

Hiçbir zamanda olmadı,

Ondan gizlimiz saklımız.

Çocuktuk o zamanlar,

Kaçıracaktık onu bir gece.

Korkudan ödümüz koptu,

Babasını pencerede görünce…', 'Çocuktuk o zamanlar, Kırmıştık bütün camlarını. O yine de bana yolladı  En içten selamlarını.  Çocuktuk o zamanlar, Başımızda yoktu aklımız....', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cocuktuk-o-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahalle Esnafı', 'mahalle-esnafi-nizamettin-ozel-q0ne9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Veresiye yazmıyor,

Mahallenin bakkalı.

Ne alırsan al,

Hepsi çok pahalı.

Parayı seviyor,

Mahallenin manavı.

Meyveleri çürük,

Karakteri sıvı.

Eşek eti satıyor,

Mahallenin kasabı.

Ne çek kullanıyor,

Ne banka hesabı…', 'Veresiye yazmıyor, Mahallenin bakkalı. Ne alırsan al, Hepsi çok pahalı. Parayı seviyor, Mahallenin manavı. Meyveleri çürük, Karakteri sıvı. ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mahalle-esnafi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçı', 'balikci-avni-aydin-q5j7a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'güneşin battığı bi yer düşün önce...

deniz kuşlarının süslediği bir koy...

ağlarını tamir etmekte olan yorgun balıkçılar bir de...

özlem ve kavuşma da ekle...

yanılsamalarını denizin... yalnız gözlere yaptığı...

ve sütlimanlığı her fırtına sonrasında...

martılar gibi uç o koyun üzerinden...

kanat çırp engin maviliğine karadenizin...

bir kaç yunus var sana eşlik eden...

ve bir kaç sanssız balıkçı... fırtınaya takılan...

yoldaş ol onlara.. esen rüzgara inatla...

aldırma yunusların geri dönmelerine..

onlar fırtınadan korkar...

süzül iyice rüzgara doğru...  ve daha fazla kanat çırp

özlediği mekanlarına balıkçıları.. kavuştur...

ve sonra geri dön...

geri dön yuvana

geri dön.. bana...', 'güneşin battığı bi yer düşün önce... deniz kuşlarının süslediği bir koy... ağlarını tamir etmekte olan yorgun balıkçılar bir de... özlem ve ...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/balikci-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ninni söyleyen sazlar', 'ninni-soyleyen-sazlar-adem-atacak-4wami', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Halı desenlerine gömülen 

Düşüncelerimi

Örümcek ağlarıyla örülen 

Vuslatlar ziyaret eder 

Gecenin koynundan 

Kafiyesiz dostlarım dökülürken 

Kağıt üzerine 

Bense serin rüzgarların 

Set koltuğunda

Acıların çocuğunu oynarım 

Ama sen yinede

Ninni söyleyen sazların 

Uyuyan tellerinde

Bestelenmemiş notalarına kucak açan 

Ozanı olarak bil beni', 'Halı desenlerine gömülen  Düşüncelerimi Örümcek ağlarıyla örülen  Vuslatlar ziyaret eder  Gecenin koynundan  Kafiyesiz dostlarım dökülürken ...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ninni-soyleyen-sazlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem Anlatabildimmi', 'bilmem-anlatabildimmi-yusuf-onder-bahceci-muc92', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiirler güzelse, yorum gelmezse,

Beklediğin güzel birgün gelmezse,

Çok sevmişsin ama gönül vermezse,

Birgün yazmaktan usanır bırakırsın sen.....

Bilmem anlatabildim mi....', 'Şiirler güzelse, yorum gelmezse, Beklediğin güzel birgün gelmezse, Çok sevmişsin ama gönül vermezse, Birgün yazmaktan usanır bırakırsın sen....', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bilmem-anlatabildimmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çember', 'cember-avni-aydin-b7yv1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevemdim ki kimseyi bir anlık...

inanmadım ki o sevgilere keza...

bir çemberdeyim sanki gittikçe daralan,

daraldıkça seni bulan...

ve bir ömür sende kesişen...', 'sevemdim ki kimseyi bir anlık... inanmadım ki o sevgilere keza... bir çemberdeyim sanki gittikçe daralan, daraldıkça seni bulan... ve bir öm...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cember-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım... Hoşgeldin...', 'kadinim-hosgeldin-avni-aydin-b5fjp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ateşi yaktım,

belki biraz ısınırsın diye...

hoşgeldin güzel,

soğuktur buralar bilirim.

üşürsün...

neden diye sormayacağım,hoşgeldin...

uzun oldu görmeyeli seni,

özledim...', 'ateşi yaktım, belki biraz ısınırsın diye... hoşgeldin güzel, soğuktur buralar bilirim. üşürsün... neden diye sormayacağım,hoşgeldin... uzun ...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kadinim-hosgeldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günebakan...', 'gunebakan-avni-aydin-ksbey', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günebakan çiçekleriyle bezeliydi geçtiğim tarla,

ve sen çok uzaklardaydın...

yürüyordun vakur, sade...

bir adım önümdeydin dokunmak için

ve bin adım önde benim olmak için...', 'Günebakan çiçekleriyle bezeliydi geçtiğim tarla, ve sen çok uzaklardaydın... yürüyordun vakur, sade... bir adım önümdeydin dokunmak için ve ...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gunebakan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyden Gelen Mektup', 'koyden-gelen-mektup-nizamettin-ozel-alw0j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aylar sonra mektubu geldi; 

Kargacık burgacık yazısı.

Devamlı acı çekiyormuş,

Devamlı bir kalb sızısı.

Havalar iyiymiş köy yerinde,

Bir ukde kalmış derinde.

Koca bekliyormuş evinde,

İstemeye bile gelmiş bazısı.

Benden de cevap bekliyor,

Bari gel iste diye ekliyor.

Sonrada mektubu bitiriyor,

Kelimeler kan kırmızısı…', 'Aylar sonra mektubu geldi;  Kargacık burgacık yazısı. Devamlı acı çekiyormuş, Devamlı bir kalb sızısı. Havalar iyiymiş köy yerinde, Bir ukde...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/koyden-gelen-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abim Hasta', 'abim-hasta-nizamettin-ozel-971ft', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Abi’m hasta; 

Çalışmıyor böbrekleri.

Daha genç yaşta; 

Daha bitmedi görecekleri.

Abi’m hasta; 

Kanını zehirliyor yedikleri.

Ama en başta,

Eriyip gitmekte sevdikleri.

Abi’m hasta; 

Başında rahmet melekleri.

Dostları yasta,

Hepsinin şifa dilekleri…', 'Abi’m hasta;  Çalışmıyor böbrekleri. Daha genç yaşta;  Daha bitmedi görecekleri. Abi’m hasta;  Kanını zehirliyor yedikleri. Ama en başta, Er...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/abim-hasta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fitne', 'fitne-taner-nisanci-4bt5r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'FİTNE..

              ‘’Fitne uykudadır onu uyandırmayınız.’’

Resul-i Ekremden miras bilinen

Günde beş vakit huşuyla kılınan

Tertemiz suyla abdesti alınan

Namaza fitne sokulmuş yarabbi

Erkek kadın aynı safta yan yana 

Rezillik yayıldı  uçup her yana

Gerildi sinirler, sığmaz can kına

Namaza fitne sokulmuş yarabbi

Ilımlı İslam modeli diyerek

Vacib,sünneti farzı yok sayarak

Gelenek yerine aklı koyarak

Namaza fitne sokulmuş yarabbi

Bir Garib der; ehli sünnet vel cemaat

Özümüz hakka teslim,hep itaat

Bir saçmalık var,dışardan ithalat

Namaza fitne sokulmuş yarabbi

              

                                                   26/01/2006', 'FİTNE..               ‘’Fitne uykudadır onu uyandırmayınız.’’ Resul-i Ekremden miras bilinen Günde beş vakit huşuyla kılınan Tertemiz suyla ...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/fitne-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Kız', 'yalniz-kiz-nizamettin-ozel-70cxk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güzel bir ağaç altı buldu,

Açtı piknik sepetini.

Bir sağına baktı, bir soluna,

Aradı bulamadı birini.

Halbuki biri olmalıydı,

Bu güzel yemekleri yiyen.

Ardından bir romantik müzik,

Zaman geçmeliydi derken.

Olmadı, tek yedi yemekleri,

Tek topladı sofra bezini.

Onca kalabalığın arasında,

Kaybettirdi gitti izini…', 'Güzel bir ağaç altı buldu, Açtı piknik sepetini. Bir sağına baktı, bir soluna, Aradı bulamadı birini. Halbuki biri olmalıydı, Bu güzel yemek...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalniz-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-okan-nar-pwmod', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün daha geçti senden ayrı,

Sevgilim aşkınla kavrulmadan gel.

Günlerin,ayların özlemi canıma yetti,

Benliğim kül olup,savrulmadan gel.



Ne mümkün sensiz olup,nefes almak,

Neye yarar senden ayrı varolmak.! 

Alın yazım mı.? özleminle kahrolmak,

Sevgilim hasretinle ölmedan gel.', 'Bir gün daha geçti senden ayrı, Sevgilim aşkınla kavrulmadan gel. Günlerin,ayların özlemi canıma yetti, Benliğim kül olup,savrulmadan gel. N...', ARRAY['Türk Edebiyatı','Şiir','Okan Nar']::text[], 8.5, '{"poet":"Okan Nar","poet_slug":"okan-nar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-261-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle', 'gule-gule-nizamettin-ozel-m5jyt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözler mika,

Yüz desen harika.

Öyle baka kaldım,

Birkaç dakika.

Saçlar lüle,

Benziyor güle.

Baktım ayrılıyor yollar,

Dedim: “Güle güle”…', 'Gözler mika, Yüz desen harika. Öyle baka kaldım, Birkaç dakika. Saçlar lüle, Benziyor güle. Baktım ayrılıyor yollar, Dedim: “Güle güle”…...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gule-gule-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Aşkı Sorma', 'bana-aski-sorma-nizamettin-ozel-trowp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana aşkı sorma! 

Politik bir konu...

Gerçekle başlasa da her şeyin,

Yalanla bitiyor sonu...

Bana aşkı sorma! 

Ne yenir, ne içilir...

Hayatım, canım diyenler,

Bir adımda geçilir...

Bana aşkı sorma! 

İzafi bir kavram...

En son birini sevdim ben; 

Hala sızlar, aha şuram...', 'Bana aşkı sorma!  Politik bir konu... Gerçekle başlasa da her şeyin, Yalanla bitiyor sonu... Bana aşkı sorma!  Ne yenir, ne içilir... Hayatı...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bana-aski-sorma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçükten Büyüğe Sıralanan BİZ', 'kucukten-buyuge-siralanan-bi-z-tulay-sustam-bjty9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gün ağardığında

siyah kopardı güneşin saçından

kızılında yıkanırdım / denizin

gözlerin / mavinin içinde ağlardı

göz yaşın düşerdi yüreğime

el açardım senin için

-.-

alın çizgine yazılırdım

çıkmazında sevişirdik aşkın

yağmurlar yağardı, nergisin üzerine 

kururdu dudakları hazanın

yelkovan, akrebi her vuruşunda

hedefi olurdum aşkın', 'gün ağardığında siyah kopardı güneşin saçından kızılında yıkanırdım / denizin gözlerin / mavinin içinde ağlardı göz yaşın düşerdi yüreğime e...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kucukten-buyuge-siralanan-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla', 'leyla-nizamettin-ozel-cs7qh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlerlemiş yaşına rağmen; 

Hala çok şıktı.

Ne kadar kız tanıdıysam,

Hepsi ona aşıktı.

Hoş biriydi üstelik,

Sevilirdi mahallede.

O ise hiç birini sevmiyordu,

“Leyla” diyordu ille de…

(Aşk böyle birşey işte..)', 'İlerlemiş yaşına rağmen;  Hala çok şıktı. Ne kadar kız tanıdıysam, Hepsi ona aşıktı. Hoş biriydi üstelik, Sevilirdi mahallede. O ise hiç bir...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/leyla-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yudum Türkü', 'bir-yudum-turku-derya-aslan-wxeew', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeşil dereler kıvrılırda akar gider, 

Pullu balıkları var, oynaşırda gider. 

Yarimin incedir beli, bükülürde gider.

Al yanaklarında güller, dökülür gider.

Erzincan’ın yolları uzarda uzar, 

Dereleri birleşirde, Fırat’a akar. 

Aşk şarabı içtim içeli, yüreğim yanar. 

Erenler oturmuşta, bana çare arar.

Yüksek olur ararda sıra dağlar, 

Buz tutar etekleri,erimez karlar. 

Uzun olur gurbete yolculuklar

Hasret kokar, yare yakılan ağıtlar. 

Güz gelirde, altın başaklar dalgalanır 

Al yanaklı kızların,eline kına yakılır 

Ak gerdanlara sıra inciler takılır 

İşlenir  gergeflerde, kervan yola dizilir.', 'Yeşil dereler kıvrılırda akar gider,  Pullu balıkları var, oynaşırda gider.  Yarimin incedir beli, bükülürde gider. Al yanaklarında güller, ...', ARRAY['Türk Edebiyatı','Şiir','Derya Aslan']::text[], 8.5, '{"poet":"Derya Aslan","poet_slug":"derya-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-yudum-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla Beni', 'anla-beni-nizamettin-ozel-hf012', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben; kocaman ormanda,

Ufacık bir ağaçtım.

Köklerimi söktüm önce; 

Sonra senden kaçtım...

Daha yeni doğmuştum,

Hemen birden solamazdım.

Ne olur anla beni,

Yanında olamazdım…', 'Ben; kocaman ormanda, Ufacık bir ağaçtım. Köklerimi söktüm önce;  Sonra senden kaçtım... Daha yeni doğmuştum, Hemen birden solamazdım. Ne ol...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anla-beni-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat', 'anlat-gul-yazganarikan-nl8h6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlayabilsem seni,

Anlatabilsen bana,

Senin için neyim,

Gizli bir sevgili miyim? 

Her dem özlenen miyim? 

Dokunuşlarında istek

Bakışlarında sıcaklık,

Ellerindeki telaş sahi mi? 

Yoksa  bir heves miyim? 

İçinde boşlukta, küçük bir noktada

Derinden bir giz miyim? 

Yüreğinden başlayıp,

Teninde gezer miyim? 

Ah anlayabilsem seni.

Anlatabilsen bana,

Islak öpüşleri düşündüğünde,

Tek bir gül gördüğünde,

O güzel dudaklarda,

Bitmeyen istek miyim? 

Suskun dudakların, öpmediği zaman,

Durgun ellerin, dokunmadığı zaman,

Ah yangınım, baş ağrım, uykusuzluğum,

Deli düşüncem, 

Bir cümle dökülsün ateş dudaklarından,

Bir kelimeyi dillendirsin sesin, içinden, uzaklardan.

Korkusuz, hesapsız, yalansız olsun...

Neyse o olsun...

Gel al avuçlarına beni, 

Sessizce olmasın gelişin,

Gürültümüz karışsın rüzgara,

Ateşlenen tenimiz kor olup, düşsün karlara,

Bu derin sessizlik bitsin,

Gözlerin konuşsa da,

Dudakların söylesin...', 'Anlayabilsem seni, Anlatabilsen bana, Senin için neyim, Gizli bir sevgili miyim?  Her dem özlenen miyim?  Dokunuşlarında istek Bakışlarında ...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/anlat-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanışma', 'tanisma-nizamettin-ozel-pjv2o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ruhum yaralı,

Bahtım karalı,

Geceleri uykusuzum; 

Sen karşıma,

Çıktın çıkalı...

Asfalt halı,

Önüm diken, çalı.

Sana gelmek istiyorum; 

Ama bütün yollar

Tıkalı…', 'Ruhum yaralı, Bahtım karalı, Geceleri uykusuzum;  Sen karşıma, Çıktın çıkalı... Asfalt halı, Önüm diken, çalı. Sana gelmek istiyorum;  Ama b...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tanisma-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güllerin Rengi', 'gullerin-rengi-i-zzettin-donmez-kqujl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gül deyince neler gelir aklıma

Onlar çeşit çeşit türlü biçimdir,

Rengine bakıpta yanılmayasın,

Kırmızı gül sevgililer içindir.

Beyaz gül temizlik saflık demektir,

Pembesi sevenden naz istemektir.

Her rengin anlamı ayrı dilektir,

Siyah gül kararlı seven içindir.

Demetle verenler çokluğu sever,

Karışık güllerse sevgiyi över.

Gülsüz başlayanlar, dizini döver,

Goncalar ilklere vermek içindir.

Karmaşık duygular salkım güllerde

İlk gün anısıdır tüm gönüllerde,

Sevilen beklenir gözler yollarda

Dalında gül gülü seven içindir.

Soluk gül götürme pişman olursun,

Kırık gül verirsen yolda kalırsın

İzzetin, elin boş hava alırsın

Gül, gülmek isteyen güller içindir.', 'Gül deyince neler gelir aklıma Onlar çeşit çeşit türlü biçimdir, Rengine bakıpta yanılmayasın, Kırmızı gül sevgililer içindir. Beyaz gül tem...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gullerin-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Bahsetti', 'senden-bahsetti-nizamettin-ozel-nv73t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önce yüreğimde başladı deprem,

Sonra bütün şehri sardı.

Başımdan ayrıldı gövdem; 

Kıp kızıl kanlar akardı...

Bilemedi hiç kimse; 

Sandılar taştan bir yatır.

Yine senden bahsetti,

Cebinden çıkan bir-iki satır...', 'Önce yüreğimde başladı deprem, Sonra bütün şehri sardı. Başımdan ayrıldı gövdem;  Kıp kızıl kanlar akardı... Bilemedi hiç kimse;  Sandılar t...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senden-bahsetti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelirim', 'gelirim-i-zzettin-donmez-7j7v9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu kadar özleme inanabilsem; 

Huzurun içinden çıkar gelirim! 

Yüce dağlar engel olsa yoluma; 

Dağları taşları, yıkar gelirim! 

Kokunu ararım esen yellerden, 

Daha da temizsin beyaz güllerden,

Özlemin duyarsam, susuz çöllerden; 

Çağlayanlar gibi akar gelirim! 

Sevgiyi anlamak, sevene kârdır,

Beşerin ateşi, cürmü kadardır. 

Zaten bir atımlık barutum vardır; 

Düşünmez onu da, sıkar gelirim! 

Nedendir bilinmez, ayrılık neden?

Huzursuz ortamda, ömürdür giden, 

İnandırsan beni, gel desen birden; 

Geceyi gündüze katar gelirim! 

Sebebi belirsiz, sevdası kayıp, 

Emeksiz sevgiyi kaderden sayıp,

Terkedip gidersen, gözün kapayıp; 

O zaman vicdanı yıkar gelirim! 

27-28 Mayıs 1999', 'Bu kadar özleme inanabilsem;  Huzurun içinden çıkar gelirim!  Yüce dağlar engel olsa yoluma;  Dağları taşları, yıkar gelirim!  Kokunu ararım...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gelirim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz İsyan', 'sessiz-i-syan-i-zzettin-donmez-r9el7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seninle hayatım zorlaşıyor da, 

İsyanı dışıma vuramıyorum! 

Niceler endamın, methetse lakin; 

Benzer hayalleri kuramıyorum! 

Fizikle kimyalar, içle dış gibi,

İsyana sükutlar yakarış gibi,

Yeşil zeytin dalı, hep barış gibi; 

Düşleri de hayra yoramıyorum! 

Hoyratlar gülleri yolmasın derim,

Umut çiçekleri solmasın derim, 

Gönüller derbeder olmasın derim; 

Her gülden bülbülü soramıyorum! 

İnsanlar severse, kuşu böceği, 

Sevgiler yeşertir gülü çiçeği,

Mutluluk hayatın, tatlı gerçeği; 

Onunla uzakta duramıyorum! 

İzzettin hayatın gidişi böyle, 

Tartarak süzerek lafını söyle, 

Şehirdeki hesap bağdaşmaz köyle; 

Menziller çok uzak varamıyorum! 

                         28.06.2001', 'Seninle hayatım zorlaşıyor da,  İsyanı dışıma vuramıyorum!  Niceler endamın, methetse lakin;  Benzer hayalleri kuramıyorum!  Fizikle kimyala...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sessiz-isyan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım Ermiyor', 'aklim-ermiyor-i-zzettin-donmez-9salw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu insanoğluna aklım ermiyor

Üçü gider beşi gelir durmadan

Kimi ekmek için savaşa dursun

Kimi göğe çıkar,kendin yormadan

Mutluluğu arar ömrü boyunca,

Yemekten vazgeçmez,karnı doyunca

Gözü doyar,baş toprağa koyunca

Şu insanoğluna aklım ermiyor

Kimi mevki ister,kimisi para,

Kimi varlıklıdır,kimi fukara,

Kimi hükmedemem der,yüce dağlara,

Şu insanoğluna aklım ermiyor

Yalanı sevenler,doğrudan fazla

İş yapan bulunmaz kırkiki nazla

Kafa üşüten var,hafif ayazla

Şu insanoğluna aklım ermiyor

Sıhhat isteyen az,mala düşkünler,

Çoğu ham meyvedir,azdır pişkinler

Çocuğu aratır,çok yetişkinler

Şu insanoğluna aklım ermiyor

İzzettin yaşamış otuzbeş sene

Sorsalar insanı tanımaz gene

Gözüm açık gider,girsem kefene,

Şu insanoğluna aklım ermiyor  

                                                       1987', 'Şu insanoğluna aklım ermiyor Üçü gider beşi gelir durmadan Kimi ekmek için savaşa dursun Kimi göğe çıkar,kendin yormadan Mutluluğu arar ömrü...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aklim-ermiyor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Gidi Gençliğim', 'hey-gidi-gencligim-nizamettin-ozel-f5nul', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hey gidi gençliğim; hey gidi! 

Saçıma ak düşüren  uzun yıllar.

Yanar hala yüreğim, yanar! 

Yanar da içim,  bir garip sızlar…

Bilmem şimdi nerde o çocukluğum,

Nerde o kız, hayalini kurduğum.

Geceleri gelmesinden koktuğum,

Gençliğimi çalan, nerde o hırsızlar…', 'Hey gidi gençliğim; hey gidi!  Saçıma ak düşüren  uzun yıllar. Yanar hala yüreğim, yanar!  Yanar da içim,  bir garip sızlar… Bilmem şimdi ne...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hey-gidi-gencligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saflığımı Yüze Vuran Olmadı!', 'safligimi-yuze-vuran-olmadi-i-zzettin-donmez-7afot', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umutsuz dünyada umut ararken; 

Saflığımı yüze vuran olmadı! 

Pembe düşler ile hayal kurarken; 

Saflığımı yüze vuran olmadı! 

Bilmedim dünyanın dar olduğunu,

Hayat yollarının zor olduğunu,

Unuttum sevginin var olduğunu; 

Saflığımı yüze vuran olmadı! 

Hedef nerde diye aradım durdum! 

Huzur bulmak için fazla yoruldum,

Umut diye yılana da sarıldım; 

Saflığımı yüze vuran olmadı! 

Yaptığım yanlışlar yol olur aya,

Gerek yoktur fazlasını sormaya,

Tükenirken hayat denen sermaye; 

Saflığımı yüze vuran olmadı! 

Faydasız diyorlar araban katın,

Geriye dönüşü yokmuş hayatın,

Boşa kürek çektim, bitti takatım; 

Saflığımı yüze vuran olmadı! 

                                      28-29 Kasım 1999', 'Umutsuz dünyada umut ararken;  Saflığımı yüze vuran olmadı!  Pembe düşler ile hayal kurarken;  Saflığımı yüze vuran olmadı!  Bilmedim dünyan...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/safligimi-yuze-vuran-olmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''a Kul Olan Kullar Kardeşim', 'allah-a-kul-olan-kullar-kardesim-yusuf-onder-bahceci-sl34c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Allah sevgisi ile kalbim yanıyor,

Sade Allah''mı Peygamber diyor,

Benim deli gönlüm söz dinlemiyor,

Allah''a kul olan kullar kardeşim.

Allah''a kul olan kullar kardeşim,

Peygamber Ümmeti olur kardeşim,

Sade Dünya değil, Ukba kardeşim,

Allah''a kul olan kullar kardeşim. 

Allah için birbirini sevenler nerde,

Artık gözün iyi görür gider de perde,

Sana hep sorarlar, sorar mahşerde,

Allah''a kul olan kullar kardeşim...', 'Allah sevgisi ile kalbim yanıyor, Sade Allah''mı Peygamber diyor, Benim deli gönlüm söz dinlemiyor, Allah''a kul olan kullar kardeşim. Allah''a...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/allah-a-kul-olan-kullar-kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-i-zzettin-donmez-16wri', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ömürgezsen de yalan Dünya’da,

Ne kazandın diye sorarlar birgün! 

Gönlünce yaşasan tüm anıları; 

Terletir ruhunu yorarlar bir gün! 

Gideceğin yerde başlar velvele,

Boşuna uğraşın savrulur yele,

Birikimin nedir görelim hele,

Heybeni, dosyanı ararlar bir gün! 

Alçak gönüllü ol, yükseklerden in,

Yumuşasın yürek, bulunmasın kin,

Bilirim mezarı sevmezdin lakin; 

Kürekle toprağa kararlar birgün

Bilinçli rehber bul, cahile sorma,

Dünya benim deyip yanlış yorulma,

Gayeni aşıpta tuzaklar kurma; 

Beş metre kefene sararlar birgün! 

İzzettin yanlızsın enzor gününde,

Dostun,oğlun,malın yoktur yanında,

Nizam terazide hakkın önünde:

Günahın sevabın tartarlar birgün! 

03-08. Haziran 2002', 'Bir ömürgezsen de yalan Dünya’da, Ne kazandın diye sorarlar birgün!  Gönlünce yaşasan tüm anıları;  Terletir ruhunu yorarlar bir gün!  Gidec...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-gun-147-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye Gülmüyor?', 'niye-gulmuyor-i-zzettin-donmez-x5iem', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülüp geçiyorum, Dünya haline,

Bilmemki gülmeyen, niye gülmüyor? 

Bir fırsat geçmişken, kulun eline; 

Bilmemki gülmeyen, niye gülmüyor? 

Ağla, gül, sonuçta zaman geçiyor! 

Toplumda yargı var, değer biçiyor,

Vadesi dolanlar, durmaz göçüyor? 

Bilmemki gülmeyen, niye gülmüyor? 

Merak ettim yıllar yılı dolandım,

Beş kez durulduysam, on kez bulandım,

Dünyada fırsatı ben mi kullandım; 

Bilmemki gülmeyen, niye gülmüyor? 

Sabretmek çaresiz, anlayan azdır,

İyi niyetli az, çoğu garazdır, 

Neşeli olmaksa, bahardır yazdır; 

Bilmemki gülmeyen, niye gülmüyor? 

                                                 01.Eki.00', 'Gülüp geçiyorum, Dünya haline, Bilmemki gülmeyen, niye gülmüyor?  Bir fırsat geçmişken, kulun eline;  Bilmemki gülmeyen, niye gülmüyor?  Ağl...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/niye-gulmuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzleşme', 'yuzlesme-nizamettin-ozel-4hlh7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gerçeklerle yüzleşmeliyiz; 

Gözden geçirilmeli ilişkimiz.

Temiz bir sayfa çevirmeliyiz; 

Sen ve  ben, yani ikimiz…

Gerçeklerle yüzleşmeliyiz; 

Lekelenmemeli ismimiz.

O zaman daha hoş durur,

Yan yana duvarda resmimiz…', 'Gerçeklerle yüzleşmeliyiz;  Gözden geçirilmeli ilişkimiz. Temiz bir sayfa çevirmeliyiz;  Sen ve  ben, yani ikimiz… Gerçeklerle yüzleşmeliyiz...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yuzlesme-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belli Bellidir', 'belli-bellidir-i-zzettin-donmez-ltq2e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kartal yuvasına karga konamaz; 

Yiğitlik orada belli bellidir! 

Aslanın avını tilki alamaz; 

Krallık orada belli bellidir! 

Herdem dövüşmekle koyun kurt olmaz! 

Zulme alışkına çile dert olmaz! 

Bey otağı çakallara yurt olmaz; 

Asalet orada belli bellidir! 

Gözün kestiğine çatar dayılar,

Dengeleri alt, üst eder sayılar,

Köpek sürüsünden korkmaz ayılar; 

Korkular orada belli bellidir! 

Öküze gül sunsan yiyecek sanır! 

Develer ot için dağa tırmanır,

İzzettin mahluku yakından tanır; 

Karakter orada belli bellidir! 

      19 Mart 1999', 'Kartal yuvasına karga konamaz;  Yiğitlik orada belli bellidir!  Aslanın avını tilki alamaz;  Krallık orada belli bellidir!  Herdem dövüşmekl...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/belli-bellidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-nizamettin-ozel-1iffo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu ömrümün sonbaharı; 

Ne bir arzu, ne istek.

Ağaçların sarı yaprakları,

Dökülmekte tek tek.

Yenilgiyi kabul ettim; 

Gücüm kalmadı işte, pes.

İstersen derimi yüz,

İstersen lime lime kes...', 'Bu ömrümün sonbaharı;  Ne bir arzu, ne istek. Ağaçların sarı yaprakları, Dökülmekte tek tek. Yenilgiyi kabul ettim;  Gücüm kalmadı işte, pes...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sonbahar-127-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz arkadaştık', 'biz-arkadastik-adem-atacak-a32ko', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yol kenarlarındaki dizili paragrafların

Kara tahtalarda,ertelenmiş öykülerini okuyan

Mavi gözlü sularıydık

Karanlık kuyularda

Ben Karadeniz’e dökülürdüm

Özgürse Marmara’ya

Karmaşık romanlara 

Devrik cümleler kurardık

Manasız muhalifleri oynadık 

Sahipsiz tiyatrolarda

Delik cüzdanlarımızda 

Dost hane yamalarımız vardı

Bedelsiz oynanan oyunlarıydık

Çamur kokan mahalle aralarının

Biz arkadaştık', 'Yol kenarlarındaki dizili paragrafların Kara tahtalarda,ertelenmiş öykülerini okuyan Mavi gözlü sularıydık Karanlık kuyularda Ben Karadeniz’...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biz-arkadastik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değil', 'degil-i-zzettin-donmez-ck348', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kuş bir ağaca gidip sığınsa; 

Ağaçta yaprağın dökmeli değil; 

Yoksulun başına bir iş gelende,

Varlıklı yüzünü yıkmalı değil! 

Umutsuz olmayın yaşıyorsanız,

Sorumluluk ruhu taşıyorsunuz,

Ahvali Alem’e şaşıyorsanız:

Kâmilce, çileden çıkmalı değil! 

Geleceği biraz sezmek gerekir,

Manevi denizde yüzmek gerekir,

Bazan hastaları gezmek gerekir; 

Boşuna hayattan bıkmalı değil! 

Bir eserin olsun, gözle görüne,

Haddini bil fazla dalma derine,

Bir iyilik yaptıyısan birine; 

    Gün olup başına kakmalı  değil! 

                          12.10.2001', 'Bir kuş bir ağaca gidip sığınsa;  Ağaçta yaprağın dökmeli değil;  Yoksulun başına bir iş gelende, Varlıklı yüzünü yıkmalı değil!  Umutsuz ol...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/degil-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Müslüman Dediğim', 'benim-musluman-dedigim-nizamettin-ozel-vio96', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Barda pavyonda ömrün geçti,

Hala baş eğmezsin.

Senin için akıttığım; 

Gözyaşına değmezsin.

Sevginin dile gelişi,

Kalemin ucundadır.

Benim müslüman dediğim; 

Namazında, orucundadır...', 'Barda pavyonda ömrün geçti, Hala baş eğmezsin. Senin için akıttığım;  Gözyaşına değmezsin. Sevginin dile gelişi, Kalemin ucundadır. Benim mü...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/benim-musluman-dedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Mahalle', 'bizim-mahalle-nizamettin-ozel-uc2v0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Burası Fikirtepe, yani benim yurdum; 

Bu yollarda geçti, benim çocukluğum.

Üç katlı evimizden kalan tek eser,

Çatısında duran kırmızı kiremitler.

Bu mahallede Ali Osman vardı, Şenol; 

Remzi, Mehmet, Yılmaz, Birol.

Çocukluk arkadaşım Yalçın, Hayrettin; 

Ayhan, Mustafa, Seyfettin, Şerafettin.

Hepsi duman olmuş gözümde tüter; 

Sadık, Sedat, Tarkan, Sefer.

Artık saklananlar çıksın birer birer; 

Önder, Fatih, Hasan, Tamer.

Neydi o günler, ah o günler; 

Kızardı gözlerim, ağlayacak gibiler.

Yapa yalnız kalmak güç geliyor; 

Onca derdi sırta yükleyip, taşıması zor.

Çeşmi teyzem nerde, ya anam; 

Muhsin amcam nerde, ya babam.

Olmuyor kara toprak, olmuyor; 

Yine acıkmış karnın, bir türlü doymuyor...', 'Burası Fikirtepe, yani benim yurdum;  Bu yollarda geçti, benim çocukluğum. Üç katlı evimizden kalan tek eser, Çatısında duran kırmızı kiremi...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bizim-mahalle-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-nizamettin-ozel-mm0t7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Allah''tır; her iyiliğin,

Her güzelliğin başı...

Doğruluğunun ifadesidir; 

Sendeki bu gözyaşı...

Çoktandır görmemiştim,

Böyle ağlayan güzel...

Allah koşarak geliyor; 

Sen bir adım gel...

Senin, için güzel olsun,

Kim bakar şekline...

Rahmettir ağlamak; 

Yine ağla kızım, yine...

Tanıdıklarına üzül,

Hiç tanımadıklarına...

Allah seni affeder; 

Tövbe et yaşadıklarına...

Söyle kimmiş kızım,

Allah varken başkası...

Ebedi bir hayat; 

Hemen ölümün arkası...', 'Allah''tır; her iyiliğin, Her güzelliğin başı... Doğruluğunun ifadesidir;  Sendeki bu gözyaşı... Çoktandır görmemiştim, Böyle ağlayan güzel.....', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nasihat-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özrü Kabahatinden Büyük', 'ozru-kabahatinden-buyuk-nizamettin-ozel-qh9ye', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benden özür diliyor,

Kondurup yanağıma öpücükleri.

İlle de kıskandırıyor,

Yolda oynayan küçükleri...

Hani gitmiyor değil hoşuma,

Yanağıma konan buse.

Dur be kızım yapma; 

Ya o çocuklarda isterse...

Benim gönlümü aldın,

Git onlarında gönlünü al.

Bak büyükleri de sıraladın; 

Bekleşiyor kasap, manav, bakkal...', 'Benden özür diliyor, Kondurup yanağıma öpücükleri. İlle de kıskandırıyor, Yolda oynayan küçükleri... Hani gitmiyor değil hoşuma, Yanağıma ko...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozru-kabahatinden-buyuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Gibi', 'su-gibi-nizamettin-ozel-qbg5b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin kapının önünden,

Karanlıkta geçiyorum.

Ezberlediğim bu yolları; 

Sanki su gibi içiyorum...

Belki seni görürüm diye,

Pencerenize bakıyorum.

O kadar heyecanlıyım ki; 

Sanki su gibi akıyorum…', 'Senin kapının önünden, Karanlıkta geçiyorum. Ezberlediğim bu yolları;  Sanki su gibi içiyorum... Belki seni görürüm diye, Pencerenize bakıyo...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/su-gibi-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haber Ver', 'haber-ver-i-zzettin-donmez-kyidl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin ile yaylaları gezelim,

Menekşeler morlaşınca haber ver! 

Hayallerin ummanında yüzelim,

Umutlar gürleşince haber ver! 

Gülşenim yok türlü güller yetirem,

Yetirem de demet demet getirem,

Alıp seni uzaklara götürem:

Deli gönlün darlaşınca haber ver! 

Mevlam bilir yoktur başka dileğim,

Gül desin ki bende içten güleyim,

Gerekirse koşaraktan geleyim:

Kolay işin zorlaşınca haber ver! 

Birazcık gülümse korkumu atam,

Gönlümden gönlüne sevgi yansıtam,

Üşüyünce ellerini ısıtam:

Dağlar başı karlaşınca haber ver! 

Resmimi ismimi gönlünde sakla,

Sevgi düşman değil,  vurulmaz okla,

Sıcak yüreğini devamlı yokla:

Alev alıp harlaşınca haber ver!', 'Senin ile yaylaları gezelim, Menekşeler morlaşınca haber ver!  Hayallerin ummanında yüzelim, Umutlar gürleşince haber ver!  Gülşenim yok tür...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/haber-ver-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Ola', 'haberin-ola-nizamettin-ozel-lrex2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dağları tepeleri,

Ardımca yere serip; 

Nefesimi tutup,

Vücudumu öne gerip; 

Kazanacağım bu savaşı,

Gerekirse; 

Her şeyimi feda edip; 

Haberin ola...

Güneşim ben,

Kar isen eritip; 

Kaçsan ne çıkar,

Yakalarım seğirtip; 

Aşk, ızdırap, gözyaşı,

Biraz kendimi eğitip; 

Çıkacağım karşına,

Haberin ola...

Bitmedim daha,

Yaşıyorum kan içip; 

Bir gün, ama bir gün,

Önüne geçip; 

Çatlatacağım seni,

Kızların,

En güzelini seçip; 

Haberin ola...', 'Dağları tepeleri, Ardımca yere serip;  Nefesimi tutup, Vücudumu öne gerip;  Kazanacağım bu savaşı, Gerekirse;  Her şeyimi feda edip;  Haberi...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/haberin-ola-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olduk!', 'olduk-i-zzettin-donmez-s73ty', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zamanı durdurup, zamandan öte; 

Hayalle yaşayan kişiler olduk! 

Beleşten sahiplik, kemiğe ete; 

Kayboldu insanlık, bir şeyler olduk! 

Hatır gönül, kayıplara karıştı,

Eşek attan daha üstün yarıştı,

Yeni gençlik bedavaya alıştı; 

Aslan gibi yatıp av tutar olduk! 

Mutlu yüz maskenin altında kaldı,

Hesap vermek Allah katında kaldı,

Çaremizde zakkum otunda kaldı; 

Yabancıya karşı kül yutar olduk! 

Huzuru ararız şiddetle şerde, 

Güleriz, coşarız, matemli yerde,

Karakterimiz değişir ikide birde; 

Bukalemun gibi birşeyler olduk! 

İzzettin ne dersin, bu nasıl iştir, 

Belkide bu gidiş, kötü gidiştir,

Yaşanan gerçekler sanmaki düştür; 

Gerçeği görüp de ders almaz olduk! 

                    21.07.1998', 'Zamanı durdurup, zamandan öte;  Hayalle yaşayan kişiler olduk!  Beleşten sahiplik, kemiğe ete;  Kayboldu insanlık, bir şeyler olduk!  Hatır ...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olduk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evcilik', 'evcilik-nizamettin-ozel-qku0f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çocukluğumuza dönelim hadi,

Fakirliğimize.

On kuruşa aldığımız, tap taze,

Ekmeğimize...

Hatırlar mısın, denize girerdik ya; 

Denize.

Yaklaştırmazdık kimseyi, kumdan

Kalemize...

Karı koca olurduk, evcilik oynardık,

Biz bize.

Gördün ya, ayrı evlilik yaramadı işte

İkimize...', 'Çocukluğumuza dönelim hadi, Fakirliğimize. On kuruşa aldığımız, tap taze, Ekmeğimize... Hatırlar mısın, denize girerdik ya;  Denize. Yaklaşt...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/evcilik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış Kurarsın', 'yanlis-kurarsin-i-zzettin-donmez-yl81o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Haldan bilmeyene derdin açarsan,

Boşuna yorulur, boşa yorarsın,

Sisli havalarda müşgül  uçarsan,

Hayat saatini yanlış kurarsın,

Her yanında olumsuzluk belirir, 

Görüntün bozulur, aklın delirir,

Gide gide son noktaya gelinir,

Sarhoş adamlardan adres sorarsın.

	

Düşlerin kararır, umudun yiter,

İstenmeyen kıllar burnun da biter,

Güvendiğin gençlik, bırakır gider,

Suçunu yıkmaya yerler ararsın.

	

Sürüden sayarlar takmazlar yular,

Ardına akbaba, çaylaklar dolar,

Umudun azalır, benzin de solar,

Olmayan saçı nasıl tararsın.

	

Dostların yanına gelmez inan ki; 

Kimseler yüzüne gülmez inan ki; 

Yakının halini bilmez inan ki; 

Tükenmiş halinle neye yararsın,', 'Haldan bilmeyene derdin açarsan, Boşuna yorulur, boşa yorarsın, Sisli havalarda müşgül  uçarsan, Hayat saatini yanlış kurarsın, Her yanında ...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yanlis-kurarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veysel’e Bak!', 'veysel-e-bak-i-zzettin-donmez-ai7rn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapalı göz görür desem; 

İnanmazsan Veysel’e bak! 

Kalbden kalbe yürür desem;

İnanmazsan, Veysel’e bak!

Hisseder dünden yarını, 

Bilir zararla kârını,

Yırtar toprağın bağrını; 

İnanmazsan, Veysel’e bak! 

Zindanı Dünya’ da yaşar, 

Dost bildiği dosta şaşar, 

Ölmez gönüllerde yaşar,

İnanmazsan, Veysel’e bak! 

Koyunu yoldaş kurduna, 

Leke getirmez yurduna,

Toprak ilaçtır derdine; 

İnanmazsan, Veysel’e bak! 

İzzettin yaşar nicedir,

Ozanlarla iç içedir,

Aşık gerçekten yücedir; 

İnanmazsan, Veysel’e bak! 

                           29.Oca.99', 'Kapalı göz görür desem;  İnanmazsan Veysel’e bak!  Kalbden kalbe yürür desem; İnanmazsan, Veysel’e bak! Hisseder dünden yarını,  Bilir zarar...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/veysel-e-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyümde Şimdi', 'koyumde-simdi-i-zzettin-donmez-7dhgk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Davulcu manide, sahur vaktidir,

Horozlar ötüyor köyümde şimdi.

Ezan sesleri de kovar geceyi,

Karanlık yitiyor köyümde şimdi.

Hazan düştü sararmıştır obalar,

Rüzgarlar uğuldar, dağları yalar,

Kışı erkencidir yanar sobalar,

Bacalar tütüyor köyümde şimdi.

Hasretlik çoğaldı ne gelir elde,

Kokuda beklenmez her çeşit gülde,

Çalışkandır ahalisi genelde,

Tembeller yatıyor, köyümde şimdi.

Sebzelerin sonu soğan ekilir,

Dostluğu daimi kahır çekilir.

Kalan üzümlerden şıra sıkılır,

Cevizler bitiyor, köyümde şimdi.

İzledimde fazla çıktı artılar,

Hak’tan yana iner kalkar tartılar,

Baraj kıyısında açtır martılar,

Ne bulsa yutuyor köyümde şimdi.

Vasıta hızlandı yollar kısaldı,

İzzettin düşündü derine daldı,

Yüksek okul öğrencisi çoğaldı,

Okuyan artıyor köyümde şimdi.', 'Davulcu manide, sahur vaktidir, Horozlar ötüyor köyümde şimdi. Ezan sesleri de kovar geceyi, Karanlık yitiyor köyümde şimdi. Hazan düştü sar...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/koyumde-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çınar Ağacı', 'cinar-agaci-nizamettin-ozel-89ub7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bir ağacım,

         Gövdemi toprağa sapladım.

Nice fırtınalar gördüm de; 

         Hala ayaktayım, yıkılmadım...

Dallarım, kollarım; 

         Dua eder gibi açıldı göklere.

Her gün yağmurla beslenir,

         Parmak parmak su gider köklere...', 'Ben bir ağacım,          Gövdemi toprağa sapladım. Nice fırtınalar gördüm de;           Hala ayaktayım, yıkılmadım... Dallarım, kollarım;   ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cinar-agaci-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneler Günü', 'anneler-gunu-i-zzettin-donmez-ftnhr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anneler gününü kabul etmem:

Yılda birgün ile anne sorulmaz! 

Üçyüz altmışta bir, razımısın sen; 

Yılda bir gün ile anne sorulmaz! 

Daim sormalısın anne halini,

Ne oldu, ne biti bil ahvalini,

Hiçte esirgeme tatlı dilini:

Yılda bir gün ile anne sorulmaz! 

Cennet vardır ayağının altında,

Analar melektir Allah katında,

Gece beşik sallar, gündüz sırtında; 

Yılda birgün ile anne sorulmaz! 

Sembol olsun bırak kalsın bugünü,

Anayı sevip, çözelim düğümü,

Bahtiyarım ben, görsen güldüğünü; 

Yılda birgün ile anne sorulmaz! 

                              25-27 Nisan 1998', 'Anneler gününü kabul etmem: Yılda birgün ile anne sorulmaz!  Üçyüz altmışta bir, razımısın sen;  Yılda bir gün ile anne sorulmaz!  Daim sorm...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anneler-gunu-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim', 'zalim-nizamettin-ozel-lvw6g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlk önce sen vardın,

Sonra sonra diğerleri.

Zalimdi bir adın; 

Ağlatırdın sevenleri...

Ne zaman ki seni bıraktım,

Unuttum acıyı kederi.

Beden diye taşıdığım,

Bir kemik, bir deri…', 'İlk önce sen vardın, Sonra sonra diğerleri. Zalimdi bir adın;  Ağlatırdın sevenleri... Ne zaman ki seni bıraktım, Unuttum acıyı kederi. Bede...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zalim-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim!', 'benim-i-zzettin-donmez-n4mgx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daha yeni geliyorum akından,

Sırtım da okumla yayım var benim! 

Yarışları izliyorum yakından; 

Küheylan olacak tayım var benim! 

		

Gece gündüz durmadan hep çalıştım,

Engel denen zorluklara alıştım,

Gücüm aştım aletlerle yarıştım; 

Başarı içinde payım var benim! 

		

Beni etkiliyor benim kederim,

Kendi borçlarımı kendim öderim,

Herkes yürü ben koşarak giderim,

Yüksekçe yerlerde dayım var benim! 

		

Kararmış kalplere ışık dolacak,

Zehirli mantarlar hepsi solacak,

Beklenenden büyük deprem olacak; 

Daha kırılmamış fayım var benim! 

	

Gün olur bir sevgi bin aybı saklar

Gün olur bir ağu, bin mikrobu paklar,

Çatlamasın susuzluktan dudaklar; 

Gürül gürül akan çayım var benim', 'Daha yeni geliyorum akından, Sırtım da okumla yayım var benim!  Yarışları izliyorum yakından;  Küheylan olacak tayım var benim!  		 Gece gün...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/benim-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Ver', 'can-ver-nizamettin-ozel-sishh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derdim taşkındır,

Hem dağ, hem tepe.

Beni yaralayan bakışındır; 

Yataklara düşüren, sere serpe...

Ölüm yakındır,

Yaş desen daha körpe.

Diyar diyar gezdiren aşkındır; 

Salar beni ipten ipe...

Kızmak hakkındır,

Atıver duygularımı çöpe.

Yürek kabına sığmaz, taşkındır; 

Can ver bana öpe öpe...', 'Derdim taşkındır, Hem dağ, hem tepe. Beni yaralayan bakışındır;  Yataklara düşüren, sere serpe... Ölüm yakındır, Yaş desen daha körpe. Diyar...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/can-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Kendime', 'kendi-kendime-mehmet-koc-2-di9is', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendi Kendime

Sanki bir harabe oldu bu dünyam

Yıkıldı umudum kayboldu sevdam

Ben bu hallerdeyken fazla yaşamam

Çıkıp gideyim ben kendi kendime.

Tıkamış yolumu zalim ayrılık

çekilmiş dünyamdan çekilmiş ışık

Şimdi halime bak zavallı aşık

Bitip gideyim ben kendi kendime.

Dostlarım mı kaldı dertler anlatsam

Sevdalım mı var ki sevgiler alsam

Ne yaparım artık dünyada kalsam

Yitip gideyim ben kendi kendime.

Ben yapmadım böyle acı seçimi

Dert kaplamış hem dışımı içimi

Başları ağrıtan kısık sesimi

Kesip gideyim ben kendi kendime.

		KOÇBEY KOÇ.', 'Kendi Kendime Sanki bir harabe oldu bu dünyam Yıkıldı umudum kayboldu sevdam Ben bu hallerdeyken fazla yaşamam Çıkıp gideyim ben kendi kendi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Koç 2']::text[], 8.5, '{"poet":"Mehmet Koç 2","poet_slug":"mehmet-koc-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kendi-kendime-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu İktidar', 'bu-i-ktidar-mehmet-ayhan-gunaydin-guk6l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BU İKTİDAR

Allah’ım bunlara Sen,

Gerçeği gör diye mi,

İktidar nasip ettin? 

İslam sözle yaşanmaz,

Gör de iç yüzlerini,

Gör de bil, bil mi dedin? 

Gördüm ve anladım ben.

Dinimle ilgili de,

Değerlerim de bir bir.

Bunların sayesinde,

Ayaklar altındadır.

Gördükçe içim erir.

Kocalar memleketin,

Bak içine ediyor.

Karılar da dinimin…

Din’e niyetleniyor.

Adamı hadi geçtim,

Kadın imam olacak.

Adam yıktı dünyamı,

Eş dinimi yıkacak.

Kadın imam olursa,

Ardına duracağım. 

O rükuya varınca,

Ben nasıl varacağım? 

Kadın eğilecekmiş,

Önümde olacakmış.

Üstünde kot baş açık

Nefsim uyanmıycakmış.

Nasıl olacaksa bu,

Ben de bilemiyorum.

Yeter artık be yahu,

İnan kuduruyorum.

Allah’ım yeter artık,

Bitsin bunca rezalet.

Millete, dine yazık,

Ya Rab artık himmet et! 

M. Ayhan Günaydın.

     26 Ocak 2006 

          Ankara', 'BU İKTİDAR Allah’ım bunlara Sen, Gerçeği gör diye mi, İktidar nasip ettin?  İslam sözle yaşanmaz, Gör de iç yüzlerini, Gör de bil, bil mi de...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bu-iktidar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık!', 'artik-i-zzettin-donmez-un1rb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneyi kapadık doğudan sonra,

Güneş pencereme doğmuyor artık! 

Köpek melezledik, değişim için; 

Kurtlar koyunları boğmuyor artık! 

Gel eyledik, kal eyledik ellere, 

Tırpan attık, çiçeklere güllere, 

Pisledik, hor baktık, kutsal yerlere; 

Hayırlı bir rahmet yağmıyor artık! 

Umut sözü, uyut oldu sonunda, 

Tahlil etsen, RH çıkmaz kanında,

Devler bile küçük kaldı yanında; 

İçlerde dışlara sığmıyor artık! 

Çok ezelden beri bizler böyleydik! 

En son sözümüzü önce söyledik! 

Sulara gem vurduk baraj eyledik; 

Nehirler alüvyon yığmıyor artık! 

İnsan unutulmaz varsa eseri! 

Hep kendine yontmuyorsa keseri,

Sağım makinası çıkandan beri; 

Besici ineği sağmıyor artık! 

                                     25.07.2000', 'Güneyi kapadık doğudan sonra, Güneş pencereme doğmuyor artık!  Köpek melezledik, değişim için;  Kurtlar koyunları boğmuyor artık!  Gel eyled...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/artik-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuruldum', 'vuruldum-nizamettin-ozel-nee4c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vuruldum; 

Senin gözlerine vuruldum.

Kurşun gibi, mermi gibi; 

Vuruldum...

Kovuldum; 

Gönül kapından kovuldum.

Köpekleri, itleri saldılar üzerime; 

Kovuldum...

Yoruldum; 

Bir umut verdin doğruldum.

Gölgen gibi peşinde gezmekten; 

Yoruldum...', 'Vuruldum;  Senin gözlerine vuruldum. Kurşun gibi, mermi gibi;  Vuruldum... Kovuldum;  Gönül kapından kovuldum. Köpekleri, itleri saldılar üz...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vuruldum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahmur Gözler', 'mahmur-gozler-i-zzettin-donmez-vsv1e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mahmur gözler uykusuna doymamış

Sarıp sevip uyandırmak gerekir

Umutluyum oda beni özlemiş

Sarıp sevip uyandırmak gerekir

Sarı saçlar belik bele dökülmüş

Yalnız kalmış mahzun boynu bükülmüş

Ağlamaktan gül yanağı küçülmüş

Sarıp sevip şenlendirmek gerekir

Mektup saldım terki diyar bildirdim

Anlaşılan yar yüzünü güldürdüm

Yıllar yılı gül benzini soldurdum

Sarıp sevip affettirmek gerekir

Ben gurbette yar sılada derbeder

Ayrılık seveni perişan eder

Seven sevdiğine koşarak gider

Sarıp sevip kucaklaşmak gerekir

26.09.1986', 'Mahmur gözler uykusuna doymamış Sarıp sevip uyandırmak gerekir Umutluyum oda beni özlemiş Sarıp sevip uyandırmak gerekir Sarı saçlar belik b...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mahmur-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamazsın', 'bulamazsin-i-zzettin-donmez-u4u21', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Viran bağlarında boşa gezinme

Güzelce koklanır gül bulamazsın

Baktıkça şaşırırsın aklın dolanır	

Geriye dönmeye yol bulamazsın

Lale gül menekşe hepsi hazanda

Sanki atıp kaynatmışlar kazanda 

Hayatta ayrılık vardır bazan da

İstediğin şeyi bol bulamazsın

Yapraklar dökülmüş üzgün ağaçlar 

Gittikçe aklaşır dökülür saçlar

Temiz hislerine kötü amaçlar

Kalenderce saran kol bulamazsın

Kış geldi ayılar ininde şimdi 

Yağcılar her zaman günün de şimdi

Menfaat her şeyin önünde şimdi

Kendine yontmayan kul bulamazsın

Yemekle doyar mı dev dinozorlar

Tuzlu yiyecekler bedeni zorlar

Rüzgar savurunca açılır korlar

Yarana basmaya kül bulamazsın

İzzettin kaçırma sıkı tut ipi

Hayat bir kuyudur görünmez dibi

Söyleyip geçerler bilirmiş gibi

Gönlüne göre de fal bulamazsın', 'Viran bağlarında boşa gezinme Güzelce koklanır gül bulamazsın Baktıkça şaşırırsın aklın dolanır	 Geriye dönmeye yol bulamazsın Lale gül mene...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bulamazsin-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '26 no'' lu Tren', '26-no-lu-tren-i-brahim-ethem-bingul-8mm4f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hangi tren sesi o, seni benden götüren

Hüzün şehrinde beni karanlıklara gömen

Tükendi, ellerine dokunamadan günler

Hayallerimi çaldı ah o zalim trenler...

Raylarına baş koysam onu durdurur muyum

Haykırsam gitme diye sana duyurur muyum

Nerede kaldı, hani kırılmayan gururum

O vagonda ben senle birlikte olur muyum...

Kimileri vurgunmuş giden tren sesine

Âşık seslenirmiş de çağlarmış sevdiğine

Yalan...Yalan...Aman ha, inanmasın hiç kimse

Bu tren yakmaktadır yüreği içten içe...

İstersen sen de bin git, git şimdi bu trene

Dönme ve asla bakma bundan böyle geriye

Yön verdim yüz seksen derece ben hislerime

İstemem dokunmayı o dolgun ellerine...

Bir gün sen de böylece baka kalıp trene

Bin bir çeşit insana, ağlayana gülene

Bir bilet aldım yirmi altı no'' lu trene

Yalnızca gidiş için dönüşü yok geriye...

İstemem sallama yâr, at mendili elinden

Çok dalgalandım durdum, durulma vakti gelen

Bundan sonra rüyamda iki şeyi istemem

Biri sensin, biri de yirmi altı no''lu tren...

www.iebingül.com', 'Hangi tren sesi o, seni benden götüren Hüzün şehrinde beni karanlıklara gömen Tükendi, ellerine dokunamadan günler Hayallerimi çaldı ah o za...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/26-no-lu-tren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Işıklar', 'olu-isiklar-nizamettin-ozel-paorn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerinden pınar gibi,

Düğüm düğüm yaş sızardı.

En son biri baktı yüzüne,

Kulaklarına kadar kızardı...

Karşı pencerede ölü ışıklar,

Hasta gölgeler, sesi kısıklar.

Yüreğinde bir hıçkırık,

Rüyasında ismini sayıklar...', 'Gözlerinden pınar gibi, Düğüm düğüm yaş sızardı. En son biri baktı yüzüne, Kulaklarına kadar kızardı... Karşı pencerede ölü ışıklar, Hasta g...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olu-isiklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barışa Çağrı', 'barisa-cagri-i-zzettin-donmez-af88m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana sevgi dolu bir buse yolla,

Ayrılık aklımda çıkıpta gitsin! 

Hatırla sevdiğim yabancı olma; 

Aşkımız bu yolda akıpta gitsin! 	

Sahip çık aşkıma yalnız kalmasın! 

Her gece baktığım yıldız kaymasın! 

Dışlama sevgimi, ruhum duymasın,

Yüz verme ayrılık kaçıpta gitsin! 

Bir haber, bir selam yetiyor bana, 

Seviyorum hala atma yabana,

Bundan sonrası da kalıyor sana; 

Evet de düğümler çözülüp bitsin! 

Bir evet e dayalıdır kaderim,

İnan sensiz sona ermez kederim, 

Aşkla geldim, aşk uğruna giderim; 

Uzat dost elini, bu sorun bitsin! 

                                         13.08.1987', 'Bana sevgi dolu bir buse yolla, Ayrılık aklımda çıkıpta gitsin!  Hatırla sevdiğim yabancı olma;  Aşkımız bu yolda akıpta gitsin! 	 Sahip çık...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/barisa-cagri-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Methedeyim Seni Eller İçinde', 'nasil-methedeyim-seni-eller-i-cinde-yusuf-onder-bahceci-7l2rq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acep güllermi güzel senmi güzelsin,

Sen kâlbimi yakan, yakan güzelsin,

Benim sevdam yüce sense güzelsin,

Nasıl methedeyim seni eller içinde.

Şu bağrıma salarsın sen ateşi, közü,

Bana versen yemin, sevdanın sözü,

Kalbim hep kan ağlar, sözümün özü,

Nasıl methedeyim seni eller içinde.

Damarlarımda gezen kanlar çekilse,

Gözlerim görmese, gücüm tükense,

Sadece seni övecek bir dilim kalsa,

Nasıl methedeyim seni eller içinde.

Ancak şiirler yazıp ağlayacağım ben,

Yıllar oldu anlamadım bu gidiş neden,

Beni böyle bırakıpta sen ellere giden,

Nasıl methedeyim seni eller içinde....

Bu şiiri bende beğendim....', 'Acep güllermi güzel senmi güzelsin, Sen kâlbimi yakan, yakan güzelsin, Benim sevdam yüce sense güzelsin, Nasıl methedeyim seni eller içinde....', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nasil-methedeyim-seni-eller-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karacaahmet', 'karacaahmet-nizamettin-ozel-7wycs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözümde her şey değersiz; 

Mal, mülk, para hepsi.

Artık Allah’a kulluk işimiz,

Gerisi elimin tersi...

Önümde sıra sıra engel,

Birinden kurtul, ötekine gel.

Yanıma diz çökmüş ecel; 

Nisan ayı, pazartesi...

Gökten yağıyor rahmet; 

Taşıdığım bir kuru ceset.

Ağla ağla karacahmet,

Göster, benim yerim neresi...', 'Gözümde her şey değersiz;  Mal, mülk, para hepsi. Artık Allah’a kulluk işimiz, Gerisi elimin tersi... Önümde sıra sıra engel, Birinden kurtu...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karacaahmet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '... Mi Sayarsın', 'mi-sayarsin-i-zzettin-donmez-fc7u2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yabancı sözcüğe merakın neden,

Türkçe konuşmayı ar mı sayarsın? 

Söyler anlamını bilmezsin amma:

Dilini kirletir, kâr mı sayarsın? 

Yapmacık sözcükler,sahte türevler,

Layıkıyla yapıldı mı görevler,

Bireyler çatışır,yad olmuş evler:

Ayvayı boyayıp, nar mı sayarsın? 

Yunus Emre’mizin diline bakın! 

Yedi asır önce,tavrını takın! 

Birazcık dikkat et,dilini sakın:

Tertemiz Türkçe’yi zor mu sayarsın? 

Benliğini atıp yadları tutma,

Susuz bırakıp ta dilin kurutma,

Anadilin Türkçe sakın unutma:

Bu bedeni cana dar mı sayarsın! 

Dili anlamıyor, mayın düşüyor! 

Uydurma sözcükle haddin aşıyor,

Eğitimciye de çok iş düşüyor:

Küllenmiş alevi kor mu sayarsın.

                                          20.04.2001', 'Yabancı sözcüğe merakın neden, Türkçe konuşmayı ar mı sayarsın?  Söyler anlamını bilmezsin amma: Dilini kirletir, kâr mı sayarsın?  Yapmacık...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mi-sayarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Beyinli', 'kus-beyinli-i-zzettin-donmez-mycho', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuş beyinli deyip, kuşları yerme; 

Sen kendi beynini ölçtün mü gardaş! 

Bırak olgunlaşsın, yeşilken derme; 

Sen kendi beynini ölçtün mü gardaş! 

Karga dersin beğenmezsin sesini,

İnsan kadar düşünür mü nefsini,

Soydaşına dokun, deler fesini; 

Sen kendi beynini ölçtün mü gardaş! 

Martı yüksek uçmaz, yelli havada,

Sürüden ayrılmaz ortak davada,

Yavrusunu yalnız koymaz yuvada; 

Sen kendi beynini ölçtün mü gardaş! 

Deve kuşu dersin, aptal eklersin! 

Yüz kilo et verir, neler beklersin! 

Ceylan gibi koşar, sense teklersin; 

Sen kendi beynini ölçtün mü gardaş! 

Leylek dersin, lak lak dersin geçersin! 

Aklın var gaganı kendin seçersin! 

İzliyorum, kuşlardan da naçarsın; 

Sen kendi beynini ölçtün mü gardaş! 

                                                  10.07.2000', 'Kuş beyinli deyip, kuşları yerme;  Sen kendi beynini ölçtün mü gardaş!  Bırak olgunlaşsın, yeşilken derme;  Sen kendi beynini ölçtün mü gard...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kus-beyinli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün', 'surgun-nizamettin-ozel-kdi62', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kan kaybediyorum,

Günden güne.

Daha bekletmeyin beni; 

Gönderin sürgüne.

Aşk acısı derler,

Perişan eder adamı.

Çiçeklerle bezeyin,

Toprak altında odamı...', 'Kan kaybediyorum, Günden güne. Daha bekletmeyin beni;  Gönderin sürgüne. Aşk acısı derler, Perişan eder adamı. Çiçeklerle bezeyin, Toprak al...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/surgun-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabul görmeyen adam', 'kabul-gormeyen-adam-adem-atacak-71x8r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sıska  bacaklı yazlara

Yaprak dökümünden kalan

Şişko acılarım bindi

Bocalamakta olan kalbimin

Ritmi bozulan dünyasının ayak seslerine

Kabul görmeyen 

Alık bakışlı bir ihtiyar gibi dışlanırım

Dünyanın düzeni dediklerinden

Suskun bir küfür kaçar ağzımdan

Ve terk ederim

Bu dünyanın anasını avradını

Buyurun vezir yapın 

Onun bunun evladını', 'Sıska  bacaklı yazlara Yaprak dökümünden kalan Şişko acılarım bindi Bocalamakta olan kalbimin Ritmi bozulan dünyasının ayak seslerine Kabul ...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kabul-gormeyen-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmediğini Biliyor Musun?', 'bilmedigini-biliyor-musun-i-zzettin-donmez-p2f7w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu dünya nasıldır, bu düzen nasıl,

Yaşar da bilmezsin bilyormusun? 

Kulağı çınlatır, yapılan fasıl; 

Duydukça kendine geliyormusun? 

Birgün konar, birgün göçer giderdin! 

Sevgiden anlamaz, severim derdin! 

Olmayacak şeyi, kat, kat isterdin; 

O günleri anıp gülüyor musun? 

Bilmezsin, küçükken çok yaramazdın! 

Kavgasız dövüşsüz hiç duramazsın; 

Biraz yüz verdik ya, iyice azdın; 

Şimdi nasihatten anlıyor musun? 

Umudum da bitti düzelmezsin sen! 

Çağırsam da yola gelemezsin sen,

İnsanlık ne desem, bilemezsin sen; 

Bu konuda dersler alıyormusun? 

İzzettin ne yapsın, çokta uğraştı! 

Kafa değil sende, belkide taştı, 

Sabrı da tükendi, isyanı taştı; 

Sabırda sınır var, biliyormusun? 

                                     04.05 Mayıs 2000', 'Bu dünya nasıldır, bu düzen nasıl, Yaşar da bilmezsin bilyormusun?  Kulağı çınlatır, yapılan fasıl;  Duydukça kendine geliyormusun?  Birgün ...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bilmedigini-biliyor-musun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maymun', 'maymun-nizamettin-ozel-hp9r4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanlığın atası maymun mu? 

Budur bütün merakları.

Fosil ararlar yer yer; 

Kazarak bütün toprakları...

Halbuki insanlığın atası,

Allah’ın yarattığı Adem.

Maymunum diyorsan, tercihine karışamam,

İnsan olmayı yediremiyorsun madem...', 'İnsanlığın atası maymun mu?  Budur bütün merakları. Fosil ararlar yer yer;  Kazarak bütün toprakları... Halbuki insanlığın atası, Allah’ın y...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/maymun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Verir', 'verir-i-zzettin-donmez-9svwj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her bitkide gülümseme görürsün,

Biri çiçek açar,biri gül verir! 

Çiçeksizler aynı çaba içinde; 

Biri renkli yaprak,biri dal verir! 

Toprak ana her canlının ilacı,

Pancar şeker gibi biber çok acı,

Börtü böcek yaradana duacı,

Sinek koku alır,arı bal verir! 

Kollar kırılsada çıkmazmış yende,

Sahtece dostların çok olur gen de,

Biraz incelersen,anlarsın sen de; 

Karıncalar düşünecek hal verir! 

Alçak gönül güzel çağlar akarsan

Hırsla bencilliği toplar yakarsan,

Onun gözü sende,sende bakarsan:

Ürününü artırırda bol verir! 

Ruh çıkmazsa canlı sürer hayatı,

Niyet acımasız,yürek çok katı,

Kendini taşıda bul hakikatı:

Mevlam sana yüreyecek yol verir! 

                                             04.04.2002', 'Her bitkide gülümseme görürsün, Biri çiçek açar,biri gül verir!  Çiçeksizler aynı çaba içinde;  Biri renkli yaprak,biri dal verir!  Toprak a...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/verir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülme', 'uzulme-nizamettin-ozel-ttbpa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman her şeyi çözer; 

Üzülme bir gün görüşürüz.

Deniz kenarında gezer,

Beraber bol bol gülüşürüz...

Birbirini seven dostlar gibi,

El ele tutuşur da yürürüz.

Tıpkı eski günlerdeki gibi; 

Ayrılırken hatta öpüşürüz…', 'Zaman her şeyi çözer;  Üzülme bir gün görüşürüz. Deniz kenarında gezer, Beraber bol bol gülüşürüz... Birbirini seven dostlar gibi, El ele tu...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzulme-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahve Gözlerin', 'kahve-gozlerin-i-zzettin-donmez-gxjdy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülmeyince neye yarar; 

Şu kahve gözlerin senin! 

Kısa ömre hepten zarar; 

O kahve gözlerin senin! 

Daim gülsün istiyorum,

Benim olsun diliyorum,

Neden üzgün bilmiyorum; 

Şu kahve gözlerin senin! 

Saçına gül takmasını,

Uğrun uğrun yakmasını,

Öğrenmedi bakmasını; 

Şu kahve gözlerin senin! 

Lalelere güle baksın,

Çiçekle bülbüle baksın,

Gelmem için yola baksın; 

O kahve gözlerin senin! 

Güzelliğin hürmetine,

Katlanırım zahmetine,

Yan bakmasın İzzetin’e; 

O kahve gözlerin senin! 

                      20-21 şubat 1998', 'Gülmeyince neye yarar;  Şu kahve gözlerin senin!  Kısa ömre hepten zarar;  O kahve gözlerin senin!  Daim gülsün istiyorum, Benim olsun diliy...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kahve-gozlerin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanç üzüntülerim', 'kiskanc-uzuntulerim-adem-atacak-glshz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gemilerin yağmalandığı okyanuslarda

Yunusların emzirdiği özgürlükler

Tırmanıyor kollarımdan ve bacaklarımdan

Yel değirmenlerine takılan

Donkişot kafalı kim varsa

Gerçekle yalan arası mesafelere

Köprü oldu

Ben de özgürüm sağ taraftan

Sarp kayalıkların 

Kaşımı açtığındaki duyduğum acıyı

Kapılar arkasından

Gülen gözlerle yaşadık

Cümbür cemaat

Ne zaman güllerin güldüğünü hissetseler

Deve dikeni ordularının

Mukafatlandırılmış kıskançlıkları

Gömer bizi derinlere

Ağlarken düşündüklerimin

Gülerken sevdiklerimin

Severken kaybettiklerimin

Toprağa karışan kokusu

Merhametin midesini bulandırmaktan 

Başka bir işe yaramıyor

Ben arınırken doldurdum 

Bütün pislikleri içime

Batarken çırpınmanın zararını ödüyorum', 'Gemilerin yağmalandığı okyanuslarda Yunusların emzirdiği özgürlükler Tırmanıyor kollarımdan ve bacaklarımdan Yel değirmenlerine takılan Donk...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kiskanc-uzuntulerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayılıyor!', 'sayiliyor-i-zzettin-donmez-zlo2f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'At, eşek, tosbağa aynı kulvarda,

Yürüyenle koşan, bir sayılıyor! 

Dergah kapısını görmese bile; 

Hırkayı kapanlar, pir sayılıyor! 

Dayısı olmayan çıkarsa yola, 

Her adım  başında verecek mola, 

Meyili de yoksa sağ ile sola; 

Siyasi anlamda kir sayılıyor! 

Zarar ile kâra bakma diyorlar,

Umuda kafanı takma diyorlar, 

Karanlıkta ışık yakma diyorlar, 

Işıkla yürüyen kör sayılıyor! 

Locaya yerleşmiş, senyörler, dükler, 

Eşeğin sırtında inmiyor yükler, 

Kırmızı ışığı takmaz büyükler; 

Vatandaşa hepsi dur sayılıyor! 

Düz yürüme sağa sola çark derler,

Olsun söyle aramızda fark derler, 

Gizlim saklım dolar ile mark derler; 

Lirada ne varsa, sır sayılıyor! 

                                         23.08.2001', 'At, eşek, tosbağa aynı kulvarda, Yürüyenle koşan, bir sayılıyor!  Dergah kapısını görmese bile;  Hırkayı kapanlar, pir sayılıyor!  Dayısı ol...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sayiliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tercih', 'tercih-nizamettin-ozel-7j428', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Terk etmek kolay değil; 

              Gönül girer araya.

Sen beni tercih ettin! 

              Üç kuruş paraya...

Ben gecekonduya,

               Sen gittin saraya.

Geçen göresim geldi,

               Herkes girmiş sıraya...', 'Terk etmek kolay değil;                Gönül girer araya. Sen beni tercih ettin!                Üç kuruş paraya... Ben gecekonduya,         ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tercih-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Düşen Ağlamaz', 'kendi-dusen-aglamaz-i-zzettin-donmez-phe12', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Terörü destekleyen,

Gün gelir,yenik düşer! 

El bağına çiş yapan; 

Bir gün üstüne işer! 

Kendini dev zanneden,

Dev değildir bilmeli,

Haklara saygı duyup:

Sevmeli sevilmeli! 

Köpeksiz köyde gezen,

Her yer köpeksiz sanır,

Kendi eliyle yapan.

Sonucuna katlanır! 

Yıllarca destekledi,

Çok kanlara girdiler.

Ateş düştüğü yeri:

Yakıyormuş gördüler! 

Sonuca bakılırsa,

Terör fayda sağlamaz! 

Atalarım demiş ki:

Kendi düşen ağlamaz! 

Bunca suçsuz insana,

Böyle ölüm hak değil,

Herkes ana kuzusu:

Kimse oyuncak değil! 

Misilleme yanlıştır,

Uyandırır yılanı! 

Bence huzursuz eder:

Daha geniş alanı! 

                         14.09.2001', 'Terörü destekleyen, Gün gelir,yenik düşer!  El bağına çiş yapan;  Bir gün üstüne işer!  Kendini dev zanneden, Dev değildir bilmeli, Haklara ...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kendi-dusen-aglamaz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Görüşlerim', 'benim-goruslerim-nizamettin-ozel-guyum', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derin uykularım var; 

Derin düşlerim.

Bazen ağlamaklı çıkar,

Gülüşlerim.

Sorunlar, sorunlar; 

Bilmediğim oyunlar.

Kimseyi bağlamaz, bunlar; 

Benim görüşlerim...', 'Derin uykularım var;  Derin düşlerim. Bazen ağlamaklı çıkar, Gülüşlerim. Sorunlar, sorunlar;  Bilmediğim oyunlar. Kimseyi bağlamaz, bunlar; ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/benim-goruslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halk Ozanı', 'halk-ozani-i-zzettin-donmez-9g246', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koyununan kuzuyunan; 

Söyler gider halk ozanı! 

Dert ortağı sazıyınan; 

Söyler gider halk ozanı! 

Özü temiz dili arı,

Kara toprak onun yarı,

Sözle bastırır efkarı:

Söyler durur halk ozanı! 

Haram katmaz ki aşına,

Köle olur yoldaşına,

Halkı taç eyler başına:

Söyler durur halk ozanı! 

Çoğu bilir, azı bilir,

Cilve ile nazı bilir,

Herşeyden çok sazı bilir:

Söyler durur halk ozanı

Kem gözle kimseye bakmaz1

Taşkın olup setler yıkmaz,

Çevrecidir orman yakmaz; 

Söyler durur halk ozanı! 

Dönmezi;  yıldırmaz  tipi,

Öncüdür, göğüsler ipi,

Yunus gibi, Veysel gibi; 

Söyler durur halk ozanı!      

                                 Eki.98', 'Koyununan kuzuyunan;  Söyler gider halk ozanı!  Dert ortağı sazıyınan;  Söyler gider halk ozanı!  Özü temiz dili arı, Kara toprak onun yarı,...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/halk-ozani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçime tükürmekteyim', 'i-cime-tukurmekteyim-adem-atacak-2w07u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sakat rehberlerle

Basit söylenenden 

Zor anlaşılana giden

Ömrümün yokuşuydun sadece

Keşkelerin sunduğu fırsatlardan biriydin

Hani kolay yaşanılıp zor unutulan

Güzel yarınların

Korkak düşünceleriyle adımlıyorum

Senle otobüs durağı arası mesafeyi

Yani kolay gibi

Zorların basit tadında

Kolaylara kazandığı  zaferlere şahidim

İlk defa kazanmanın üzüntüsü içinde

İçime tükürmekteyim', 'Sakat rehberlerle Basit söylenenden  Zor anlaşılana giden Ömrümün yokuşuydun sadece Keşkelerin sunduğu fırsatlardan biriydin Hani kolay yaşa...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/icime-tukurmekteyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naz', 'naz-nizamettin-ozel-lehj7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Genç kız işte; 

Davranışları nazdır.

Ne yaptığını bilmez,

Aklı biraz azdır...

Bacağında mini,

Açar her yerini.

Aldırış etmez hani,

Nasılsa mevsim yazdır…

Ölüsü dirisi,

Ardından bakar hepisi,

Evlenince gerisi

Sivrisinek, sazdır…', 'Genç kız işte;  Davranışları nazdır. Ne yaptığını bilmez, Aklı biraz azdır... Bacağında mini, Açar her yerini. Aldırış etmez hani, Nasılsa m...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/naz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gene Sigara Ağzında', 'gene-sigara-agzinda-i-zzettin-donmez-pgzwu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani bıraktım diyordun,

Gene sigara ağzında! 

İlk işindir sabahleyin; 

Lokma geçmez boğazında! 

Çocuk değil, ergen yaşın, 

Aynaya bak, karlı başın,

Duman olmuş için dışın; 

Gene sigara ağzında! 

Yemeği hiç aramazsın! 

Sigarasız duramazsın! 

Düşü hayra yoramazsın; 

Gene sigara ağzında! 

Ciğer muhtaç mı dumana,

Götürüyor acı sona,

Tütüyorsun yana yana; 

Gene sigara ağzında! 

İzzettin sevmez dumanı,

Zaten budur farklı yanı,

Temiz hava nedir tanı; 

Gene sigara ağzında! 

                             24.Kas.99', 'Hani bıraktım diyordun, Gene sigara ağzında!  İlk işindir sabahleyin;  Lokma geçmez boğazında!  Çocuk değil, ergen yaşın,  Aynaya bak, karlı...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gene-sigara-agzinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalaman', 'dalaman-nizamettin-ozel-qzcek', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yorucu bir çalışma,

Sonra senelik izin.

Götürmez Dalaman’a,

Bir depo benzin...

Halbuki orada,

Benim dayının villası.

Ormanın yeşilliği,

Denizin en alası…

Çare yok gideceğiz,

Paraya kıyıp biraz.

Yorgunluk atacağız,

Dinlenip bu yaz.

Birde diyorum ki; 

Şu çıplaklar olmazsa.

Orasını burasını açıp,

Kumsallara dolmasa...', 'Yorucu bir çalışma, Sonra senelik izin. Götürmez Dalaman’a, Bir depo benzin... Halbuki orada, Benim dayının villası. Ormanın yeşilliği, Deni...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dalaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürsün', 'ozgursun-sevilay-celik-jgvg6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'farkına varmadan kapladı içimi temiz bir sevgi,

ilk defa serviste gördüm seni esmer sevgilim,

unutturdun bana mazimi geçmişimi

inkar edemem inan sana sevgimi.

şarkılarla efkarlandık,şarkılarla coştuk,

hayaller kurduk çünkü çok mutluyduk.

duyguların yolunda,sevginin yolunda

elini tutarak geldim ben lise sıralarına.

her zil çalışında bir başka sevinirdim,

yüzünü görebilmeyi nede çok hayal ederdim.

hemen servise binsekte elini tutsam diye,

iple çekerdim ben hep son saatleri.

belki yolum çok kısaydı evime,

işte sana aşkımdan en son hediye.

bırakmasaydın beni bir öğle vaktinde

ne mutlu günler bekliyordu ikimizi halbukiyse..

aramadım senin sevgini bir başkasında,

temiz duygu yaşattım kalbimde hep sana,

onu bari yıkmasaydın özgürlüğün adına.

yemin ettim bundan sonra sevmemeye,

güvenmiyorum edilen tüm yeminlere.

biliyorumki sevgi anlayıştan ibaret,

anlayışla karşılıyorum esmerim

özgürsün git gidebildiğin yere...

Zehra Mustafa Dalgıç TML. 11/H sınıfı özellikle sevcan,melike,fatma,dicle,metin,alper,niyazi,ağar abi ve lisedeki gelmiş geçmiş tüm aşklarım sizleri ve yaşanan anıları hiç unutmucam:((sınıfın haylaz ve yaramaz kızlarından SEVİLAY :)))', 'farkına varmadan kapladı içimi temiz bir sevgi, ilk defa serviste gördüm seni esmer sevgilim, unutturdun bana mazimi geçmişimi inkar edemem ...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Çelik']::text[], 8.5, '{"poet":"Sevilay Çelik","poet_slug":"sevilay-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ozgursun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gene Ben Oldum!', 'gene-ben-oldum-i-zzettin-donmez-jpqxl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayata küstüm de ne oldu sanki; 

Zarar eden kişi, gene ben oldum! 

Dünyanın gidişi değişmedi ki; 

Saçları ağartan gene ben oldum! 

Kadere sırt döndüm, oralı değil, 

Herkeste baht böyle karalı değil, 

Kimse benim gibi yaralı değil; 

Kalpte yara alan, gene ben oldum! 

Rahatı görmedim ömrü yaşarken, 

Takılır kalırım engel aşarken, 

Hüzün darbe yapar, gülüp coşarken; 

Hayatta gülmeyen, gene ben oldum! 

İzzettin gülecek engel olmasa, 

Gözüne süzülen yaşlar dolmasa, 

Umut çiçekleri erken solmasa; 

Umutsuz yaşayan, gene ben oldum! 

                                                29.Ağu.87', 'Hayata küstüm de ne oldu sanki;  Zarar eden kişi, gene ben oldum!  Dünyanın gidişi değişmedi ki;  Saçları ağartan gene ben oldum!  Kadere sı...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gene-ben-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-nizamettin-ozel-dt4cx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koca dünyaya geldim geleli,

Üzüntüyle geçirdim günümü.

Meğer hiç tat almamışım ben,

Yalanla süslemişim ömrümü.

Mutluluk yalanmış, sevda yalan; 

Kalbimi yalanla işlemişim.

Cümle alem yalan diye,

Ben de yalana yalan eklemişim...', 'Koca dünyaya geldim geleli, Üzüntüyle geçirdim günümü. Meğer hiç tat almamışım ben, Yalanla süslemişim ömrümü. Mutluluk yalanmış, sevda yala...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalan-196-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugulanan camlar', 'bugulanan-camlar-murat-alemdar-70ajy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir  ekmek  parası, neler  yapılmaz ki.

Kimi, pencerelerin ardında,

Sıra  sıra dizilen umutlar ve hayeller kovalar  birbirlerini

Kimi  zaman  camlar  bugulanır, kimi zaman gözler yaşarır,

Arkasından  her  ne  kadar  hüzün gelsede,

Ve  bir  gölgeyle, umutlar  filizlenir.', 'Bir  ekmek  parası, neler  yapılmaz ki. Kimi, pencerelerin ardında, Sıra  sıra dizilen umutlar ve hayeller kovalar  birbirlerini Kimi  zaman...', ARRAY['Türk Edebiyatı','Şiir','Murat Alemdar']::text[], 8.5, '{"poet":"Murat Alemdar","poet_slug":"murat-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bugulanan-camlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıktı', 'cikti-i-zzettin-donmez-mj2qk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sertlik yapan birisini izledim; 

Kabuğu sert, içi yumuşak çıktı! 

Kafatasın açıp, bakınca gördüm; 

Asaletten geri, bir uşak çıktı! 

Tabanca taşırdı, pislik saçardı,

Delikler yapar yara açardı,

Güçlüyü görünce, yağlar kaçardı; 

Düşürdüğü plastik bir bıçak çıktı! 

Aklınca yıldırmak için milleti,

Abartarak anlatırdı illeti,

İt yemez beş para etmezdi eti; 

Evini aradık, kör nacak çıktı! 

Naralar savurur korku salardı,

Derede yüzemez, nehre dalardı,

Ayı ya dayı der, ayak yalardı; 

Gördüler hayatı, oyuncak çıktı! 

Yakalandı sorgulandı sonunda,

Tiksinmişler kimse yoktu yanında,

Tahkik ettik, boya aktı kanında,

Namussuz yalaka, bir kaçak çıktı! 

Herkes üzerinden atsa bitleri

Toplum büyütmez böyle itleri

Pislik diye attık parazitleri

Görseniz tonlarca yakacak çıktı', 'Sertlik yapan birisini izledim;  Kabuğu sert, içi yumuşak çıktı!  Kafatasın açıp, bakınca gördüm;  Asaletten geri, bir uşak çıktı!  Tabanca ...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cikti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerekmez', 'gerekmez-i-zzettin-donmez-aj3ip', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Küfrün gölgesine sığınan yiğit, 

Gerçekçi insana, gölge gerekmez! 

Sonsuz avazıyla, ürse de bir it; 

Cesur insanlara belge gerekmez! 

Cıvıklar bellidir hareketinden, 

Daim kuyruk sallar nezaketinden,

Kim yemek isterki murdar etinden; 

Anlamak içinde bilge gerekmez! 

İzzettin daima gerçekten yana, 

Bin ayıp örtermiş bir küçük yama, 

Her yerde yiğitlik sökmüyor amma; 

Dürüstlük içinde bölge gerekmez! 

                                              26.Mar.99', 'Küfrün gölgesine sığınan yiğit,  Gerçekçi insana, gölge gerekmez!  Sonsuz avazıyla, ürse de bir it;  Cesur insanlara belge gerekmez!  Cıvıkl...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gerekmez-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hassas Terazi', 'hassas-terazi-nizamettin-ozel-ntodc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her an uygulanış ve yorum farkı; 

Gözümde bütün gerçekler sisleniyor.

Bu çok hassas bir terazi sanki; 

Beynimde insanlar gizleniyor...

Ne kanun, ne yargıç, ne sanık! 

Bizler adaleti, çok geride bıraktık.

Bir zamanlar küfre çok uzaktık,

Şimdi küfür içimizde besleniyor...', 'Her an uygulanış ve yorum farkı;  Gözümde bütün gerçekler sisleniyor. Bu çok hassas bir terazi sanki;  Beynimde insanlar gizleniyor... Ne ka...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hassas-terazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Aşımı', 'zaman-asimi-ali-aydogdu-whycy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'öyle bir zamandı, o zaman 

ansızın uğrayanlardan 

dikildi 

dikildi 

önüne gelene değil 

bir türlü gelmeyene 

irkildi 

silkelendi 

ahh, çorap rengi kadar karışık aman 

ten misin, kahpe mi? 

bilendi 

keskindi 

dokunsa bir el kopardı yerinden 

kansız ve ihtişamlı olurdu ölümü

yendikçe yenildi 

gurur dalında güzeldi 

koparıldığında,bir defter sayfası kadar savruk 

kavruk nakışlar gibi başına buyruk

eğilişi etikti 

göstermeden kimselere gereksizleri 

O''na özeldi

bereketli bulutlar gibiydi göğüsleri

ve tam ucunda bir sevda kelebeği 

helâldi 

helâl ötesi

hasretin gırtlağa dayanmış elleri', 'öyle bir zamandı, o zaman  ansızın uğrayanlardan  dikildi  dikildi  önüne gelene değil  bir türlü gelmeyene  irkildi  silkelendi  ahh, çorap...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydoğdu']::text[], 8.5, '{"poet":"Ali Aydoğdu","poet_slug":"ali-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/zaman-asimi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın', 'yangin-nizamettin-ozel-j5rdz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde duman, neyin nesidir? 

Uzakta yangın var, yükselen alevler.

Acaba bu yanan yer neresidir,

Kimindir bu kül olmuş, yanan evler.

Bu bir matemdir, bir çöküşün ufkudur,

Yıllardır içimde sakladığım tutkudur.

Nedense küçükten beri beni korkutur,

Masallara saklanmış, kocaman devler...', 'Gökyüzünde duman, neyin nesidir?  Uzakta yangın var, yükselen alevler. Acaba bu yanan yer neresidir, Kimindir bu kül olmuş, yanan evler. Bu ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yangin-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefret', 'nefret-nizamettin-ozel-o8rp3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğer sitem varsa benim sesimde,

Bu; islam’a düşman fikirleredir.

Bir yer ki, kaynıyor içimde,

Bütün nefretim kafirleredir.

Hep böyle başladı, bende hüzün; 

Gece varken, değeri mi olur gündüzün.

Dilimden fışkıran her sözün,

Acısı bana, hatırası şiirleredir...', 'Eğer sitem varsa benim sesimde, Bu; islam’a düşman fikirleredir. Bir yer ki, kaynıyor içimde, Bütün nefretim kafirleredir. Hep böyle başladı...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nefret-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şüphesiz', 'suphesiz-i-zzettin-donmez-mac9j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstekleri bitmez insanoğlunun,

Biri bulsa iki ister şüphesiz! 

Mülkün tamamını koysan önüne; 

Bana yeter deyip kalkmaz şüphesiz! 

Medeni tarlaya girmek istemez, 

Açık gerçekleri görmek istemez, 

Kendini boşuna yormak istemez; 

Kolayını arar, kullar şüphesiz! 

Hem din, hem imandır çoğuna para, 

Şükür eden azdır, kapanmaz yara, 

Rızıklar gider içkiyle kumara; 

Çoğu doğru yolu bilmez şüphesiz! 

Artistir rol yapar yerine göre, 

Yok etti ananeyi kalmadı töre, 

Gitse ecdadının yattığı yere; 

Fatiha okumaz, geçer şüphesiz! 

Öyle hilesi var, akıllar almaz, 

Önden gitmek ister geride kalmaz,

On kez tövbe etse, sözünde durmaz; 

Yaptığına aklı ermez şüphesiz! 

                                             1993', 'İstekleri bitmez insanoğlunun, Biri bulsa iki ister şüphesiz!  Mülkün tamamını koysan önüne;  Bana yeter deyip kalkmaz şüphesiz!  Medeni tar...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/suphesiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanet', 'emanet-nizamettin-ozel-arpd0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimdeki beni, tanımaz ben bile,

Kaf dağlarına sürükler bir masal.

Söylenecek söz gelmezse dile,

Beni sonu gelmez acılara sal...

Aşkın gezdirirken diyar diyar; 

Senden başka, beni kim duyar.

Madem hayat denen bir pazar,

Gel, sinemde saklı emanetini al...', 'İçimdeki beni, tanımaz ben bile, Kaf dağlarına sürükler bir masal. Söylenecek söz gelmezse dile, Beni sonu gelmez acılara sal... Aşkın gezdi...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/emanet-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşılıksız Sevgi', 'karsiliksiz-sevgi-sevilay-celik-6s6yx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'öyle zor geliyorki,

seni bir başkasıyla düşünmek,

kalbinin sahibinin bir başkasının olduğunu bilmek,

beni hiç sevmediğini düşünmek..

hayat bu işte,

sen birini seversin,

o biride bir başkasını sever,

başkasıda başka birini.

okadar karmaşıkki,

okadar acımasızki bu aşk dedikleri

hiç düşünmüyor bir insanı öldürdüğünü,

acı çektirdiğini.

okadar acımasızki bu aşk dedikleri,

inadına saplıyor bıçakları

birer birer,tek tek insanın kalbine,

inadına acıtıyor yürekleri..

öyle zor geliyorki,

seni bir başkasıyla düşünmek,

kalbinin sahibinin bir başkasının olduğunu bilmek

sen beni arkadaşın olarak görüyorsun,

ben ise seni............

varsın olsun sen arkadaşım de bana

buda yeter inan benim aşkıma

uzaktanda sevmeye razıyım ben seni

ama bir gözünü açsan göreceksin beni

karşındayım tam karşındayım

inan ben hep senin baş ucundayım..', 'öyle zor geliyorki, seni bir başkasıyla düşünmek, kalbinin sahibinin bir başkasının olduğunu bilmek, beni hiç sevmediğini düşünmek.. hayat b...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Çelik']::text[], 8.5, '{"poet":"Sevilay Çelik","poet_slug":"sevilay-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/karsiliksiz-sevgi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçe', 'serce-i-zzettin-donmez-furjp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Serçeye baktımda çok şey öğrendim; 

Mala düşkün değil, bize benzemez! 

Ötüşür de durur çalı dalında; 

Fesatta değildir, giz’e benzemez! 

Bir parça ekmekle, günlerce yaşar, 

İnsanı tanısa, aklını şaşar, 

Nisanla, mayısta sevinci taşar; 

Bahara düşkündür, güz’e benzemez! 

İnadı hiç sevmez, hırsı da yoktur, 

Köşk villa istemez, yeri kovuktur,

İyilik düşünür, düşmanı çoktur; 

Yalancı ağzında söze benzemez! 

Kavgayı hiç sevmez, uçar da gider,

Ne ayak diretir, ne isyan eder, 

Ne ırkçılık bilir, ne nefret güder; 

Sahte bakışlarda, göze benzemez! 

İzzettin çok sever, serçe kuşunu,

Unutmak istiyor, sapan taşını,

Ağartmış saçını almış yaşını; 

Maskeyle gizlenmiş yüze benzemez! 

                                             12.01.2001', 'Serçeye baktımda çok şey öğrendim;  Mala düşkün değil, bize benzemez!  Ötüşür de durur çalı dalında;  Fesatta değildir, giz’e benzemez!  Bir...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/serce-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölebilirsin?', 'olebilirsin-nizamettin-ozel-uzd5h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çürük yapı,

Önü çalı çırpı.

İşte açık kapı,

Gidebilirsin.

Bahçe uzun avlu,

Alnımda ter dolu.

İşte havlu! 

Silebilirsin.

Yaralansın gönül,

Bu hastalık ölümcül.

Sen mutlu ol, gül; 

Gülebilirsin.

Sana pembe sayfa,

Bana başsız kafa.

Beni son defa,

Öpebilirsin.

Gözlerim dolmadan,

Çiçekler solmadan.

Hatta haberim olmadan; 

Ölebilirsin...', 'Bir çürük yapı, Önü çalı çırpı. İşte açık kapı, Gidebilirsin. Bahçe uzun avlu, Alnımda ter dolu. İşte havlu!  Silebilirsin. Yaralansın gönül...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olebilirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Postacı - I', 'postaci-i-i-zzettin-donmez-57ton', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilirsin gurbette haber beklerim; 

Mektubu çok görme, postacı bana! 

Boşuna gitmesin, tüm emeklerim; 

Habersiz günlerim, hep sancı bana! 

Selamı, sabahı beklerim her an, 

Hep onu düşünüp, hep hayal kuran, 

Yok deyip gönlümü, eyleme viran; 

Selamı çok görme postacı bana! 

Yardan haber yoksa, geçme buradan! 

Zaten ayrı koydu bizi yaradan, 

Söz vermiştin hafta geçti aradan; 

Mektubu çok görme postacı bana! 

Sahi mektup yokmu gerçeği söyle,

Neden üzüyorsun seveni böyle, 

Git bul sevdiğimi, sor, sual eyle; 

Haberi çok görme postacı bana!', 'Bilirsin gurbette haber beklerim;  Mektubu çok görme, postacı bana!  Boşuna gitmesin, tüm emeklerim;  Habersiz günlerim, hep sancı bana!  Se...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/postaci-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saya Saya', 'saya-saya-nizamettin-ozel-fbm88', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nereden başlamalı,

Seni anlatmaya.

Kaşından gözünden,

Kirpiğinden mi? 

Yoksa ipek gibi,

Siyah saçlarından mı? 

Nereden başlamalı,

Seni anlatmaya.

İncecik belinden,

Yumuşak teninden mi? 

Söyle nereden başlamalı,

Seni anlatmaya.

Aslında boşa çabalıyorum,

Bitmez sendeki güzellik,

Bitmez saya saya...', 'Nereden başlamalı, Seni anlatmaya. Kaşından gözünden, Kirpiğinden mi?  Yoksa ipek gibi, Siyah saçlarından mı?  Nereden başlamalı, Seni anlat...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/saya-saya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Postacı - II', 'postaci-ii-i-zzettin-donmez-gje4c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çantan mektup dolu, sen yok satarsın! 

Pencereme bakıp sitem atarsın,

Özleyen gönlüme hüzün katarsın; 

Selamı çok görme, postacı bana! 

Bir çayımı içte yorgunluk gider,

Bilmezsin özleyiş, perişan eder,

Ayrılıkla gitti bu nasıl kader; 

Mektubu çok görme, postacı bana! 

Yükün ağır, yolun ırak bellidir! 

Sonbahar yağmuru, taşkın sellidir,

Yar mektubu kudaleli, güllüdür; 

Özlemi çok görme, postacı bana! 

Yardan haber yoktur, korkarım küstü! 

Postacı sevene yapmalı jesti,

Dönmez, İzzettin’se zarfların üstü; 

Sürprizi çok görme, postacı bana!', 'Çantan mektup dolu, sen yok satarsın!  Pencereme bakıp sitem atarsın, Özleyen gönlüme hüzün katarsın;  Selamı çok görme, postacı bana!  Bir ...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/postaci-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fatiha', 'fatiha-nizamettin-ozel-nbrnn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben ölürsem,

Ve de senin haberin olursa; 

Gelmemezlik etme emi.

Mezarıma gelirken,

Senden istediğim,

Ne papatya, ne karanfil.

Bir fatiha yeter de artar,

Koparıp getirdiğin,

Çiçek değil...', 'Ben ölürsem, Ve de senin haberin olursa;  Gelmemezlik etme emi. Mezarıma gelirken, Senden istediğim, Ne papatya, ne karanfil. Bir fatiha yet...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/fatiha-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmez', 'bilinmez-i-zzettin-donmez-vvsj7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senden ayrı boynu bükük gezerim; 

Kadermidir, çilemidir bilinmez! 

Bülbül ötüşünden figan sezerim:

Dikenemi, güle midir bilinmez! 

Hazan bağı gibi gecem gündüzüm,

Kurudu teveğim, ekşidi üzüm,

Kopmuştur telleri, küsmüştür sazım; 

Dostlara mı, ele midir bilinmez! 

Al,mor çiçeklerle süslenmiş dağlar,

Yetişti meyveler, şenlendi bağlar,

Çağlayıp akıyor, gözlerim ağlar:

Nehiremi, gölemidir bilinmez! 

Sesini duyanda gönlüm doluyor,

Nabzım sıklaşıyor, rengim soluyor,

Hayatım uğrunda telef oluyor:

Esirmidir, kölemidir bilinmez! 

İzzettin nasıldır bilinmez yazgın,

Körelt hırslarını olmasın azgın,

Buseyi unutmuş birine kızgın:

Dudağamı, dilemidir, bilinmez! 

                            09-10. Haziran 2002', 'Senden ayrı boynu bükük gezerim;  Kadermidir, çilemidir bilinmez!  Bülbül ötüşünden figan sezerim: Dikenemi, güle midir bilinmez!  Hazan bağ...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bilinmez-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firkât zehri zebanın,nar-ı leylâsıdır,', 'firk-t-zehri-zebanin-nar-i-leyl-sidir-ali-riza-unal-lx53a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu fakru aciz, aşk-ı ilâhi,müptelâsıdır,

Bi çare düştü ar-ım,gönül  belâsıdır,

Firkât zehri zebanın,nar-ı leylâsıdır,

Na ehil lokman,bu hicranın ukâlasıdır,

Neyler bu bende can,dostun istilasıdır,

Rey-i mevt ettim varı,besteler selâsıdır

Talebim cismi canân,buseler devasıdır,

Bilmeye  dür-ü hicabı,na ehil ukâlasıdır.', 'Bu fakru aciz, aşk-ı ilâhi,müptelâsıdır, Bi çare düştü ar-ım,gönül  belâsıdır, Firkât zehri zebanın,nar-ı leylâsıdır, Na ehil lokman,bu hicr...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/firkat-zehri-zebanin-nar-i-leylasidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramız Açıldı', 'aramiz-acildi-i-zzettin-donmez-8mu0j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şubat sıcak dedim diye; 

Martla aramız açıldı.

Tavuğa piliç demedim; 

Kartla aramız açıldı! 

Yiyenlerden hak istedik

Taşı kabul etmez gedik,

Tilkiye benziyor dedik; 

Kurtla aramız açıldı! 

Azgın atı tutmaz eğer,

İzliyormuş gibi meğer,

Üçe biraz verdik değer; 

Dörtle aramız açıldı! 

Üç, beş çürük diş biledik,

Yenilmez haltları yedik,

Altsız üstsüz olmaz dedik; 

Şortla aramız açıldı! 

Uğraşırım bilmeceyle

Nakış dokurum heceyle,

Gittik, geldik B.M.C eyle,

Ford’la aramız açıldı! 

Ters düşünce fikirlere 

Attı beni yeden yere, 

Selam verdik fakirlere; 

Lord’la aramız açıldı!', 'Şubat sıcak dedim diye;  Martla aramız açıldı. Tavuğa piliç demedim;  Kartla aramız açıldı!  Yiyenlerden hak istedik Taşı kabul etmez gedik,...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aramiz-acildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstedim', 'i-stedim-i-zzettin-donmez-v6l3m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönlümün bağında görünce seni; 

Koparıp bir çiçek vermek istedim! 

Sunuşun güzeldi o nazik teni; 

Daha da yakından görmek istedim! 

Duruşun başkaydı, bakışın başka,

Kalbinle kalbimi yakışın başka

Toy misali canım düşmeden aşka; 

Sevginin sırrına ermek istedim! 

Tasayı, korkuyu aczi terkedip,

Sevdanın uğrunda önlerde gidip, 

Kaderim diyerek acele edip; 

Postumu kapına sermek istedim! 

Tertemiz, bembeyaz ak tüller gibi,

Sevgiye susamış gönüller gibi, 

Baharda çift gezen bülbüller gibi; 

Seninle bir yuva kurmak istedim! 

                                           26.05.2001', 'Gönlümün bağında görünce seni;  Koparıp bir çiçek vermek istedim!  Sunuşun güzeldi o nazik teni;  Daha da yakından görmek istedim!  Duruşun ...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istedim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolayına Kaçanlara', 'kolayina-kacanlara-i-zzettin-donmez-f1sx2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yorgunu yokuşa sürenlere bak:

Hayatta kendini yormayanlardır! 

Suskuna geveze diyenlere bak:

Ağzı beş dakika durmayanlardır! 

Dostu atıp düşmanına sarılan,

Yanık kavun gibi boydan yarılan,

Beni aramadın diye darılan; 

Yıllarca arayıp, sormayanlardır! 

Ne değişir sebepsizse nedenler,

Verimsiz ortamda gelip gidenler,

Geç kalmayı alışkanlık edenler:

Bir kez olsun saat kurmayanlardır.

Rağbette görmüyor fazla didinen.

Ağır değilim der, sırtıma binen,

Sobanın başını, mekan edinen:

Bir sobalık odun kırmayanlardır! 

İstersen hastalan, istersen inle,

Sorunlara ortak yoktur seninle,

Hayat nutku çekenleri bir dinle:

Yaşamın farkına varmayanlardır! 

                                           25.Haz.02', 'Yorgunu yokuşa sürenlere bak: Hayatta kendini yormayanlardır!  Suskuna geveze diyenlere bak: Ağzı beş dakika durmayanlardır!  Dostu atıp düş...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kolayina-kacanlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Yokum', 'artik-yokum-handan-ceylan-d2ope', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimi verdiğim gün, söz vermiştin.

Asla aldatmayacağına, yemin etmiştin.

Rüyalarında bile benimle olacaktın.

Doğan güneşi asla batırmayacaktın.

Söz verdin, and içtin...

Yüreğimin yarısı sensin dedin.

Oysa ben, yüreğimin tamamını sana vermiştim..

İhanetlerde iken sen yüreğimi bitirdin..

Sonsuz sevgimi tükettin....

Şimdi sorma ne haldeyim...

Lodoslarda, fırtınalarda savrulmuş,

Okyanusta bomboş bir tekneyim....

Limanım sendin sığındığım...

Dalgakıranların yokmuş meğer..

Her dalgaya kucak açmışsın...

Hani bendim bebişin, sevdiğin, yürek sesin..

Yoruldu yüreğim artık dayanmıyor...

Kanayan yüreğim hiç susmuyor..

Gözyaşlarım kurudu,

Damarlarımdaki kan damlıyor..

Çok çabuk tükettin sevgimi...

Helal etmiyeceğim asla..

Eğer biraz inancın kaldıysa...

Dön derken bile sen ihanetler içindesin hala,

Kaç kadın tanıdı hercai yüreğin..

Kaç yürek ağlattı..

Sevmedi hiçbiri benim sevdiğim gibi... 

Hala seni düşünüp hala sana yazıyorum...

Sahipsiz bıraktığın kalbimi derinlere gömüyorum...

Artık ben yokum yokum...

Kayboluyorummmm.....

Marmaris  Aksaz 26.01.2006', 'Yüreğimi verdiğim gün, söz vermiştin. Asla aldatmayacağına, yemin etmiştin. Rüyalarında bile benimle olacaktın. Doğan güneşi asla batırmayac...', ARRAY['Türk Edebiyatı','Şiir','Handan Ceylan']::text[], 8.5, '{"poet":"Handan Ceylan","poet_slug":"handan-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/artik-yokum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seç kökü', 'sec-koku-ali-veli-px635', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seçilmiş seçmek için

Seçebilme yetisi kesin

Seçme özgürlüğü değil

Seçilme özgürlüğü

Engellenmiş

Engince engelli

Sıçrıyor ve olabildiğince

Açıyor bacakları

Seçilmiş,engellenmiş,sıçrıyor,açıyor...

İnsanca seçilmemiş,seçememiş

Seçilmiş seçen

Seçen seçil olmuş

Bireyin öfkesi

Varoluş nedeni seç kökü', 'Seçilmiş seçmek için Seçebilme yetisi kesin Seçme özgürlüğü değil Seçilme özgürlüğü Engellenmiş Engince engelli Sıçrıyor ve olabildiğince Aç...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sec-koku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Malatya', 'malatya-i-zzettin-donmez-yjmxh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Malatya diyorlar Anadolu’nun,

Bağrında bir güldür görenler bilir

Yazıhan ovası yeşillendi ya

Bire kaç verirmiş derenler bilir

Beydağları kucaklamış şehri

Eski Malatya’sı evliya yeri

Gem vurmuşta akıtmazlar  nehiri

Fıratın ilk halin görenler bilir

Yan yana dörtler var plakasında

Ne tatlı su içilir bakır tasın da

Şakadan geçemezler laf ortasında

Malatyalıyla dost olanlar bilir

Miş miştir soyadı kaysıdır adı

Kolay kolay gitmez damakta tadı

İlaç gibi her dertlere yaradı

Düzenli üç beş tane yiyenler bilir

Şanına laik tıp merkezi Özal’ın

Hustına gerek yok buraya gelin

Türk ekibi özbenim,özmalım

Atanın sözünü bilenler bilir

İzzettin uzaktır özlemi bitmez

Sevgisin anlatmaya kudreti yetmez	

Gurbette bırakmaz gelende bırakmaz

Malatya’dan uzak kalanlar bilir', 'Malatya diyorlar Anadolu’nun, Bağrında bir güldür görenler bilir Yazıhan ovası yeşillendi ya Bire kaç verirmiş derenler bilir Beydağları kuc...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Dönmez']::text[], 8.5, '{"poet":"İzzettin Dönmez","poet_slug":"i-zzettin-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/malatya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Eserin', 'senin-eserin-nizamettin-ozel-vnopu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bedenimi savaştırdım,

Yüreğimde senin yerin.

Yaklaşmakta adım adım; 

Açık mavi gözlerin.

Çağırma beni yanına,

Bu sular çok derin.

Çektiklerim Allah adına,

Hepsi senin eserin...', 'Bedenimi savaştırdım, Yüreğimde senin yerin. Yaklaşmakta adım adım;  Açık mavi gözlerin. Çağırma beni yanına, Bu sular çok derin. Çektikleri...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senin-eserin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız Aşkım', 'i-mkansiz-askim-sevilay-celik-ht15w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sonumuz ne olacak bilmiyorum sevgilim

ya hüsranla bitecek,

yada mutlu olucaz.

koskoca yedi senemi vermişim ben bu sevgiye

üzüntüleriyle,sevinçleriyle,acılarıyla,tatlılarıyla.

herşeyinle sevmiştim ben seni.

okadar çok seviyorumki seni

fakat birtek ailem istemiyor bu sevgiyi

karşı çıkıyor.

öyle zor durumdayımki şimdi

bir yandan canımı bile vermeye hazır olduğum,

herşeyimi adadığım sen,

biryandan da beni gözbebekleri gibi büyüten,

herşeyden sakınan ailem.

okadar karıştıki aklım,

ne yapacağımı bilmez durumdayım.

acı çekiyorum,

adeta kor alevler gibi yanıp tutuşuyorum.

ne yapıcam ben şimdi inan bilemiyorum

neden istemiyolar seni,

neden bana acı çektiriyolar,

neden canımın canı seni benden ayırmaya çalışıyolar.

koskoca yedi senemi vermişim ben bu sevgiye

okadar kolaymı silmek seni,

hiç olmamışın gibi davranmak,

hayatımdan çıkartmak.

ne olursa olsun savaşıcam,

bütün herkezle,bütün dertlerle

Allahım''a herzaman dua edicem,

beni senden ayırmasın diye.

sensiz ben hiçim,

sensiz ben ben değilim.

sen benim canımsın,

hayatımı adadığımsın,

ilk aşkımsın,

canımın bir parçasısın.

sen benim, sen benim İmkansız Aşkımsın....', 'sonumuz ne olacak bilmiyorum sevgilim ya hüsranla bitecek, yada mutlu olucaz. koskoca yedi senemi vermişim ben bu sevgiye üzüntüleriyle,sevi...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Çelik']::text[], 8.5, '{"poet":"Sevilay Çelik","poet_slug":"sevilay-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/imkansiz-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sayfa', 'son-sayfa-nizamettin-ozel-t21iw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşte sonu geldi yolun; 

Sevgi kimin tekelinde.

Derdime derman bulun,

Hepiniz toplanın gelinde.

Söz geçmiyor gönlüme,

Biterken son sayfa.

İnan razıyım ölüme,

Hayatımda ilk defa...', 'İşte sonu geldi yolun;  Sevgi kimin tekelinde. Derdime derman bulun, Hepiniz toplanın gelinde. Söz geçmiyor gönlüme, Biterken son sayfa. İna...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/son-sayfa-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aitliğim', 'aitligim-ali-veli-w0d6b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşam gerçek yüzünü gösterdikçe

Hayalleri basitlik sayıyorum

Umut edemiyorum,tükendiğimi hissediyorum

Fakat yaşam abartılı

Geçiyor anlamsızca zaman

Sınırlar saydamlaşıyor

Aşılmayı bekliyor,umarsızca

Ve ben geleceğin planlarını hiçliyorum

Anlamsızlığı yaşamak,kendimle barışmak istiyorum

Kendimi soyutlamak

Yaşanılanı değil,bilinmeyeni görmek istiyorum

Var ile yok arasına aitim

Ait olduğum yere dönmek istiyorum

Umarsızca...

*Umarsızların serzenişi sessizliği bozmaya başladı...', 'Yaşam gerçek yüzünü gösterdikçe Hayalleri basitlik sayıyorum Umut edemiyorum,tükendiğimi hissediyorum Fakat yaşam abartılı Geçiyor anlamsızc...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aitligim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöpçülere verdim', 'copculere-verdim-adem-atacak-eanab', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece yarısı öfkelerimi 

Aya yapıştırdım

Mutluyken daha mutlu hissediyorum kendimi

İçimi okşayan karanlığın sessizliğinde

Tanımadığım üç sarhoş

Kolaçan ediyor 

Ayık kafalı gözlerimi

Umulmadık bir şefkatin

Kucağında sallanan

Derin bir uykuya dalar

Yorgun bir efsanenin bakışları

Oda sıcaklığında sokaklar

Serin bir huzur var

Son kullanma tarihi geçmiş

Takıntılı düşüncelerimi

Çöpçülere verdim

Silah dayamışlar

Karaltılara, götürürler beynimi', 'Gece yarısı öfkelerimi  Aya yapıştırdım Mutluyken daha mutlu hissediyorum kendimi İçimi okşayan karanlığın sessizliğinde Tanımadığım üç sarh...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/copculere-verdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamsızlığın ötesindeki anlam', 'anlamsizligin-otesindeki-anlam-ali-veli-twx2t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşüncelerin yıkılmazlığı

Tabiatın karşısında anlamsız kalıyor

Çaresizlik ve zayıflık gücün karşısında

Tekrar boyun eğiyor

Anlamsız saydığım şeylerin derinliğinde

Gizli olanı gerçek varlığı...

Acıyorum acizliğime korkuma neden bulamıyorum', 'Düşüncelerin yıkılmazlığı Tabiatın karşısında anlamsız kalıyor Çaresizlik ve zayıflık gücün karşısında Tekrar boyun eğiyor Anlamsız saydığım...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/anlamsizligin-otesindeki-anlam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal kırıklıkları', 'hayal-kirikliklari-adem-atacak-h2ow9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dibi görünen sorunların 

Yüzüme yansıyan parıltısıyla

Ayrılıyorum diğerlerinden

Aynı düşüncelerden 

Farklı duruşlar sergiliyorum

Cüssemden büyük bir hadisenin

Önünde dururken

Yaşamaktan öte yaşamadığım

Bilmekten öte bilmediğim 

Bir sualdi bu

Keşke güzel olan her şey

Cümleler kadar uzun

Paragraflar kadar yeni olabilse

Ne yağmur yağar bu halvete

Ne de gün gösterir bu kirli perde

Sıradan yaşamımda 

Sımsıkı sarılmıştım sizlere

Neden kanattınız ellerimi

Hayal kırıklıkları

Ben sizlere kızmadım

Ben sadece

Benden rahatsızım', 'Dibi görünen sorunların  Yüzüme yansıyan parıltısıyla Ayrılıyorum diğerlerinden Aynı düşüncelerden  Farklı duruşlar sergiliyorum Cüssemden b...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hayal-kirikliklari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seversen Varsın', 'seversen-varsin-i-brahim-yavuz-r0smg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç meylin olmasın nefretten yana

Aşk iksir gibidir can katar cana

Dünyayı toz pembe gösterir sana

Bırak bu güzellik ruhunu sarsın

Ne kadar seversen o kadar varsın

Dünyada hiçbir şey yerini tutmaz

İhaneti sevmez yalanı yutmaz

Gerçek sevenlerse asla unutmaz

Bırak bu güzellik ruhunu sarsın

Ne kadar seversen o kadar varsın

Baştan yaratıyor insanı baştan 

Yumuşatır kalbi olsa da taştan

Lezzeti üstündür en tatlı aştan

Bırak bu güzellik ruhunu sarsın

Ne kadar seversen o kadar varsın

İnsan bedeninde haz yaratıyor

Sönmüş bir ateşte köz yaratıyor

Hiç akla gelmedik söz yaratıyor

Bırak bu güzellik ruhunu sarsın

Ne kadar seversen o kadar varsın

Bir başka aleme durmaz uçarsın

Artık enginlere yelken açarsın

Etrafına neşe huzur saçarsın

Bırak bu güzellik ruhunu sarsın

Ne kadar seversen o kadar varsın

Ne gördü insanlık kalbi karadan

Bütün kötülükler kalksın aradan

Sevin demiyor mu yüce yaratan

Bırak bu güzellik ruhunu sarsın

Ne kadar seversen o kadar varsın', 'Hiç meylin olmasın nefretten yana Aşk iksir gibidir can katar cana Dünyayı toz pembe gösterir sana Bırak bu güzellik ruhunu sarsın Ne kadar ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/seversen-varsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni, Benden Çıkarsam: Sen Kalır Geriye', 'beni-benden-cikarsam-sen-kalir-geriye-aylin-ayla-selcukoglu-9ok9i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni benden çıkarsam

“Sen” kalır geriye

Ve bi’kaç asırdır asılı kaldığım

Bitmek bilmeyen bi’kaç uykusuz gece

E bi de senciliğinde  yağmuru koklarsam

“Ben” i taşır ileriye

Ve bi’kaç yasak ömür çaldığım

Adınca özgür, bi’kaç  yorumsuz hece

Seni, “sensiz ben” de  yoklarsam

Çığlığım varır öteye

Ve bi’kaç mısradır içerisine sarktığım

Sanki  tatmadığım Bi’kaç sabırsız “sen” ce

26.01.2006   14.45-14.54', 'Beni benden çıkarsam “Sen” kalır geriye Ve bi’kaç asırdır asılı kaldığım Bitmek bilmeyen bi’kaç uykusuz gece E bi de senciliğinde  yağmuru k...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beni-benden-cikarsam-sen-kalir-geriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-sevilay-celik-uuun8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'senin için nelere katlandım,

bütün acılara,bütün dertlere göğüs gerdim.

sen ise ne yaptın,

beni bir çöp gibi kenara fırlattın.

ben seni; 

bu değersiz canımı uğruna adayacak kadar çok sevdim,

ben senin için ailemi bir kalemde sildim,

herkeze karşı geldim,

dostlarımı kırdım,

hepsini birer birer kaybettim.

tek başımayım şimdi.

ne bir dostum var nede derdimi anlatacağım kimse,

ailem bile yok yanımda.

yanlızım,yanlızım ben buralarda,

üşüyorum,korkuyorum,ağlıyorum dört duvar arasında,

hiç birşey yok buralarda,

sadece bir bedenim,birde hayallerim var yanımda,

hayellerimde olmasa inan yaşayamam ben bu dünyad.

bilmiyorum nekadar dayanacak bu kalbim acılara

özlem çekiyorum,

ailemi,arkadaşlarımı,dostlarımı,

en önemliside seni özlüyorum.

ama özlenecek birimisin hiç bilmiyorum.

ben senin için nelere katlanıyorum

senin için acılar içinde balıklama yüzüyorum,

birgün boğulucam bu dertler arasında biliyorum.

fakat btün acılara,dertlere,yanlızlığa,özlemlere,bana yaptıklarına rağmen

seni bir an olsun unutamıyorum..', 'senin için nelere katlandım, bütün acılara,bütün dertlere göğüs gerdim. sen ise ne yaptın, beni bir çöp gibi kenara fırlattın. ben seni;  bu...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Çelik']::text[], 8.5, '{"poet":"Sevilay Çelik","poet_slug":"sevilay-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/senin-icin-148-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat bu', 'hayat-bu-adem-atacak-ms8vt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Delik bir şemsiye altında

Ekmeğini ıslatmadan yemenin telaşıdır bu

Kırık camlar arkasında

Bulutlara şekil vermenin sevincidir bu

Şehrin ışıklarında kaybolan

Yıldızların korkusudur bu

Nefesi kokan çocuğun 

Kuşları beslemesinin gururudur bu

Koca bir hayatı 

Üç tekerlekliğe yüklemenin yorgunluğudur bu

Velhasıl yokluğa ekilen sevincin

Varlıkla kavuşmasının hüznüdür bu', 'Delik bir şemsiye altında Ekmeğini ıslatmadan yemenin telaşıdır bu Kırık camlar arkasında Bulutlara şekil vermenin sevincidir bu Şehrin ışık...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-bu-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek İçimden Gelmiyor Anne', 'sevmek-i-cimden-gelmiyor-anne-i-brahim-halil-demir-fazc7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sağ gösterip sol vuranları, 

Dışarıda kibirlice yürüyenleri, 

Ahde vefalı olmayanları, 

Kendini çok beğenenleri, 

Aslını inkar edenleri, 

Dünya malına tapanları, 

Sevmek içimden gelmiyor anne. 

Günahsız çocuklarına haram lokma yedirenleri, 

Namuslu,şerefli eşlerini aldatanları, 

Konuşurken yalan konuşanları, 

Emanete hıyanet edenleri, 

Başkalarının namuslarına kötü gözle bakanları, 

Kendinden başkasını düşünmeyenleri, 

“Altta kalanların canı çıksın” diyenleri, 

Sevmek gelmiyor içimden anne 

Mahşer gününü düşünmeyenleri, 

Zalim olup mazlumlara zulüm edenleri, 

Günahsız insanların canına kast edenleri, 

Menfaati uğruna dostlarına küsenleri, 

Yaşadıkları toprakların kıymet ve değerini bilmeyenleri, 

“Devletin malı deniz yemeyen keriz” diyenleri, 

Sevmek gelmiyor içimden anne. 

Çöplükte açan papatyanın güzelliğini görmeyenleri, 

Kainattaki bu muhteşem düzeni.idrak etmeyenleri, 

Karıncanın, yuvasına şaşırmadan girip çıkmasından ibret almayanları, 

Acından uyuyamayanları düşünmeyenleri, 

“Üzümünü ye bağını sorma” diyenleri, 

Sahip olduğu nimetler için şükretmeyenleri, 

Sevmek gelmiyor içimden anne. 

26/01/2006', 'Sağ gösterip sol vuranları,  Dışarıda kibirlice yürüyenleri,  Ahde vefalı olmayanları,  Kendini çok beğenenleri,  Aslını inkar edenleri,  Dü...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sevmek-icimden-gelmiyor-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aptallar', 'aptallar-ali-veli-kqpf5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nereye yürüdüklerini bilmeden

Amaçlarımıza koşuyoruz diyorlar

Daha şimdiden körleşmişler

Sanki hiç görmüşler gibi

Tanımlamaya çalışıyorlar

Amaçlarını...

Suçsuz ve haklılar

Çünkü hakediyorlar

Bir tek bildikleri bu

Saygıyla eğiliyorum karşılarında

Aptal olmayı beceriyorlar

Saygıyla selamlıyorum onları

Kendilerinden çok eminler

Onlara acımıyorum

Çünkü yaptıklarını üstünlük sayıyorlar

*Aptallar var ve dengemizi bozuyorlar', 'Nereye yürüdüklerini bilmeden Amaçlarımıza koşuyoruz diyorlar Daha şimdiden körleşmişler Sanki hiç görmüşler gibi Tanımlamaya çalışıyorlar A...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aptallar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sapanca''lı Mevlüt', 'sapanca-li-mevlut-mehmet-akif-tiryaki-9i755', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tanışırsınız Mevlüt Bey''le Sapanca çarşısında,

Günün birinde Sapanca''da size balta sapı lazım olursa,

Aynı zamanda bisiklet parçalarıda satar, bulundurur,

Fırtına gibidir, derdinize çare bulur.

Severim kendini delikanlı çocuk harbi,

Sözünü saklamaz, yüzünüze söyler, arkanızdan konuşmaz,

Birkaç görüşmeyle insanlar hakkında karara varılmaz.

Örf ve adetlerine bağlıdır Sapanca insanı,

Mevlüt Bey''se bunlardan biri, Sapanca esnafı.

Çalışır, menfaatlerini korur,

Kimsenin malına da bakmaz, ne de gözü olur.

Tanışırsınız Mevlüt Bey''le Sapanca çarşısında,

Günün birinde Sapanca''da silahınıza yağ lazım olursa.

Bulur, buluşturur sizi memnun eder,

Giderken de arkanızdan uğurlar, tekrar görüşelim der.

Mevlüt temiz arkadaş, kravat takım elbise ona yakışır,

Eğer size bir balta sattıysa mutlaka tanışır.

Size çay söylediyse iş tamamdır,

Mevlüt artık sizin Sapanca''da bir dostunuz oldu,

Mevlüt Bey''de sizinle konuştu, neşeli ve huzurluydu.

Yarım saatlik zamanda böylece son buldu.

Tekrar bekleriz efendim.', 'Tanışırsınız Mevlüt Bey''le Sapanca çarşısında, Günün birinde Sapanca''da size balta sapı lazım olursa, Aynı zamanda bisiklet parçalarıda sata...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sapanca-li-mevlut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolmayacaktın', 'kaybolmayacaktin-mustafa-kemal-sen-uv2mw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sesim sesinden indikçe, 

Bin şirazeden çıktın...

Kahrın yağmuru dindikçe, 

Üstüme şimşekler çaktın...

Sözümü kesti sükutun, 

Ve ne de çok kayboldun, 

Almadım alacağım olsun, 

Sen hiç kaybolmayacaktın...', 'Sesim sesinden indikçe,  Bin şirazeden çıktın... Kahrın yağmuru dindikçe,  Üstüme şimşekler çaktın... Sözümü kesti sükutun,  Ve ne de çok ka...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kemal ŞEN']::text[], 8.5, '{"poet":"Mustafa Kemal ŞEN","poet_slug":"mustafa-kemal-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kaybolmayacaktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimden Geçeni Yazıyorum Ben', 'i-cimden-geceni-yaziyorum-ben-yusuf-onder-bahceci-mismt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben şair değilim diyorum, kâfiye bilmem,

Uyak, muyak anlamam sevdim diyemem,

Kusura bakma üzgünüm, seni dinlemem,

Ben içimden geldiği gibi şiir yazarım.', 'Ben şair değilim diyorum, kâfiye bilmem, Uyak, muyak anlamam sevdim diyemem, Kusura bakma üzgünüm, seni dinlemem, Ben içimden geldiği gibi ş...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/icimden-geceni-yaziyorum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki dilim doğum günü', 'i-ki-dilim-dogum-gunu-adem-atacak-nde2n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şafak üç

Perşembe doğum günüm

Bir santim daha batıyorum

Bu hayata

Yakın yirmi beş tane yakın mumları

Akşam  üstü keyfinin tadını kaçıran

Yakın çöp kokularını

Her şeye rağmen hızlı seviyorum

Monoton hayatımı

Her şeye rağmen

Yoklayarak buluyorum 

Hafif sis bulaşmış

Doğum günü hatıranı

Bilemem bu koşuda

İpi ne zaman göğüslerim

Ne zaman gözlerimi örterim

Ama ben her şeye rağmen

Seviyorum seni

İyi ki varsın olmasan bile

Üfledim mumları

İki dilim düştü hissene', 'Şafak üç Perşembe doğum günüm Bir santim daha batıyorum Bu hayata Yakın yirmi beş tane yakın mumları Akşam  üstü keyfinin tadını kaçıran Yak...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/iki-dilim-dogum-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-ali-veli-w8dex', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir dem ki sınırlarını sürdüğüm tarlalar

Geçmişten gelen bir nadas yansıması tepkilerim

Postmodern aşklar yarattım yüreğimde anlamsız

Nedenselliğini bilmediğim istekler kuşattı aciz bilincimi

Çıkışların umudunda bir kaybolmuş gibi

Aradım tüm umutlarımı açık kapılara doğru anlamsız

Bir bilinç ve altı karmaşası istençlerim

Doğru göreceliğinde çıkışsızlığım...', 'Bir dem ki sınırlarını sürdüğüm tarlalar Geçmişten gelen bir nadas yansıması tepkilerim Postmodern aşklar yarattım yüreğimde anlamsız Nedens...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/arayis-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Hiç Sevmiyorum', 'simdi-hic-sevmiyorum-sevilay-celik-g1613', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'okadar sevmiştimki seni,

senden başkası olmaz sanıyodum,

sensiz bir hayat düşünemiyordum,

unutamam zannediyodum,

bu heycan hiç bitmeyecek,

hep yeşerecek diyordum.

ama uzak olmak öldürüyormuş sevgiyi,

bitiriyomuş,unutturuyormuş.

suan, seninleyken o heycanı yaşayamıyorum,

canımı bile vermeye hazır olduğum kişiyi,

şimdi hiç sevmiyorum.

adını duyunca içim titrerdi,

yüreğim kıpır kıpır olurdu,

yanımdayken gözümü ayırmadan saatlerce gözlerine bakardım.

sarılmak isterdim,sıkıca sarılmak,

birdaha hiç bırakmamak...

şimdi bunları yaşayamıyorum,

nedenini bende bilmiyorum,

ona karşı hiç birşey hissetmiyorum.

canımı bile vermeye hazır olduğum kişiyi,

şimdi hiç sevmiyorum...', 'okadar sevmiştimki seni, senden başkası olmaz sanıyodum, sensiz bir hayat düşünemiyordum, unutamam zannediyodum, bu heycan hiç bitmeyecek, h...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Çelik']::text[], 8.5, '{"poet":"Sevilay Çelik","poet_slug":"sevilay-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/simdi-hic-sevmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde sen', 'i-cimde-sen-burhan-kucuk-rio8r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimde sen

Seni aradım

Dağlarda rüzgar esintisinde

İçimde sen

İz sürdüm

Gecelerin içinde

Hasretimde sen

Bende hasret

Hasretimde sen

Çay bardağında bırakılan

Dudak payı kadar

Ayrı Kalamam senden

Burhan KÜÇÜK

Kdz.Ereğli-26.01.2006', 'İçimde sen Seni aradım Dağlarda rüzgar esintisinde İçimde sen İz sürdüm Gecelerin içinde Hasretimde sen Bende hasret Hasretimde sen Çay bard...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/icimde-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuhname', 'yuhname-i-brahim-sagir-0j1lr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu vatanda gençliğime,gencime,

Türlü türlü tuzak kuranlara yuh! 

Bayrak, millet gibi bak direncime,

Set,  baraj, sur, duvar örenlere yuh

Zalimleri putlaştırıp tapana,

Doğrulardan eğrilere sapana,

Uşak gibi susta durup yabana

Halkı cahil, bağnaz görenlere yuh.

Özden kopup taklit işe uyana,

Hak dururken batılılara kayana,

Kendi cevherini hiçe sayana,

Düşmanlardan akıl sorana yuh.

        

Millete bakış garazca kince,

Davranıp içerde hin oğlu hince,

Yurt dışına her çıkışta haince,

Oralarda beni yerenlere yuh.

Madaması geldi tafr’etti sustuk,

Yunan bakanıma küfretti sustuk, 

Onlar şımardıkça biz sindik, pustuk,

Siyaset deyipte yoranlara yuh.

Toplanıp toplanıp taşlarlar bizi,

Teftiş eder eder haşlarlar bizi,

Her hâlü-kârda dışlarlar bizi,

Bu zillete boyun eğenlere yuh.

             

Partisi, medyası daha ne varsa,

Millete tepeden bakıp durursa,

Enkazımdan kapmak için bir parsa,

Hainlere destek verenlere yuh.

Bu vatanın nimetiyle yaşar da,

Devletimi gammazlarsa dışarıda,

Hileyle, bühtanla her hâlü-kârda,

Dürüstlere omuz vuranlara yuh.

Ayırmadan çoluk çocuk ve dedi,

Dağlarda, ovada, yolda caddede,

Suçsuza, masuma, asker Mehmet’e

Polisime tuzak kuranlara yuh.

                

Bunca yıldır bu vatan yaşarım,

Şöyle, böyle vardır elbet başarım,

Hâlâ anlamadım, hâlâ şaşarım, 

Batı batı diyip duranlara yuh.', 'Bu vatanda gençliğime,gencime, Türlü türlü tuzak kuranlara yuh!  Bayrak, millet gibi bak direncime, Set,  baraj, sur, duvar örenlere yuh Zal...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sağır']::text[], 8.5, '{"poet":"İbrahim Sağır","poet_slug":"i-brahim-sagir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yuhname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoğun bakımdayım', 'yogun-bakimdayim-adem-atacak-zasml', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tarihini attığım

Numaralandırılmış anılarımın

Sırayla üzüntüsünü yaşıyorum

Belime kadar gömülüyüm 

Bu kumpasın içerinde

Deniz kabuğunda asılı anahtarın

Sadece caddelerin kapısını açıyor

Ve yalnız yürüyorum

Arabaların çarptığı yokluğunla

İki ayaklı et yığınlarının 

Yoğun bakımındayım

Senden 0 RH(-)  kan istiyorum', 'Tarihini attığım Numaralandırılmış anılarımın Sırayla üzüntüsünü yaşıyorum Belime kadar gömülüyüm  Bu kumpasın içerinde Deniz kabuğunda asıl...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yogun-bakimdayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiler Artık Gerilerde', 'eskiler-artik-gerilerde-atilla-guler-w1ddj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ikilemlerin içine sığdırılmış bir yaşamdı önüme konan

kıpırda....yavaş...yavaş/bırak kendini...kıpırda

içini eritsin güneş/sonsuzluğa devam

lavantaları hazır et birikecek anılara

…unutma

minik düşlerini sırtlamış

…yol al bitmek bilmeyen boşluklara

oklar sıkılsın yüreğine

tik taklarında saatlerin 

sil izlerini dünlerden

…kaldır at ıraklara

zor

unutmak isterken hep hatırlamak 

sürüp gidiyor özlem

nihayetsiz öykülerde 

ortalama bir sevda yetmiyor yüreğe

tutsağı olmak

…yanmak

…kavrulmak

lirik bir şarkıda yittiğince yitmek

…ağlamak

ağla…ve son damlayı tut/ağlama

renklerin karmaşasını al içine…siyah bir düşün içinde kaybol 

çakırkeyif günlere taşı ölmeyen umutlarını

koynuna al akşamlarında

…beni

lacivert bir çizgi çekilmiş gözlerimde sensizliğin hırçın dalgaları

dumanların ardında yüzünü göremiyor olmaktan bitkin

ışıkları kapatan eller şimdi nerelerde

aşk

şarkılarımda

kara bir leke

rollerin dağıtımında kaçırdığım son uzun bir sessizliğin içinde çakılı çivi

hıçkırıklarımın engellediği sözlerim gözlerimde/gözlerim uykusuz gecelerimde kan kırmızı

maviye tutkunken siyaha bulanmış yüreğimde birikenler/usulca kabaran öfkem

ne kaldı bilinmeyen bitişlere

doğmamış bir çocuğun günahını yükledi tanrı omuzlarına

eskiler biliyorum şimdi çok gerilerde

ruhsuz bir isyanın son çığlıklarında gizli çaresizlik

içimde ölen her renkte senin zalimliğin/nasıl olduğunu asla bilemeyeceğim senli günlerin kayboluşunda yiten güneş

*“love is never to say you are sorry”/işte bu…asla ama asla

küllere dönüşse de yaşadıklarım alevleniyor tekrar Anka gibi

öyle çok ki lavanta kokusu anlar eskimesin diye

ertelediğim tüm sözlerim şimdi kabarmış göğsümde

rüyalar çalıyor kapılarımı…açan yok/sensiz hiçbir şey açılmıyor

ilmeklerini sımsıkı at kader/boynuma dolanıyor ördüğün ağ

noktasız bir aşka koyulan nokta/direnişlerde duygularım bitişlere

ertelemediğim iki söz çağlıyor hep yüreğimde

seni büyütüyor sensizlik gün be gün içimde…kızıl bir yaş süzülüyor gözlerimden…eskiler artık gerilerde

*Aşk asla pişmanlık duymamakır. (Love Story filminden bir söz.)', 'ikilemlerin içine sığdırılmış bir yaşamdı önüme konan kıpırda....yavaş...yavaş/bırak kendini...kıpırda içini eritsin güneş/sonsuzluğa devam ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/eskiler-artik-gerilerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basit görünen karmaşık', 'basit-gorunen-karmasik-ali-veli-9zxye', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ucu kavisli karamsarlık

Kendisi kaide üstündeki beyaz gizem

Görünende anlamsızlık,gerçek içindeki tanım

En üstte koca bir delik

Güzel kokulu,siyah,içi dolu

Bilgi değil,tütün bastırılmış

Koca sarığı,iri sakalıyla

Bir Osmanlı padişahı

Lületaşı,minyatür yüz,bakışları anlamlı

Güzel pipom Eskişehir hatırası

Onunla geçirdiğim anlarım

En güzel hatıralarım

Pipom bir cisim değil

Keşfettiğim dünyamın canlı varlığı

Kimileri anlatır bana edindiği tarzı

Yaşadığı tütün,nefes ve gizemli dumanları

Anlatır bana hep gördüğü dünyaları,mekanları

Seviyorum pipomu dürüst olduğu için

Varım,canlıyım diyen haykırışı! ..', 'Ucu kavisli karamsarlık Kendisi kaide üstündeki beyaz gizem Görünende anlamsızlık,gerçek içindeki tanım En üstte koca bir delik Güzel kokulu...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/basit-gorunen-karmasik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımaşık', 'askimasik-ahmetnecat-ucur-os4po', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Söyle, söyle ne olur, nasıl olduğunu,

Aşkımla, benliğinin nasıl dolduğunu

Gece gündüz kendini nasıl yolduğunu 

Ve hele günden güne nasıl solduğunu! 

Düşündün mü,yaşamın nasıl olduğunu

Görmedin mi, yaşamın nasıl dolduğunu

Yaşamını,yaşamın nasıl yolduğunu

Susuzluktan yaşamın nasıl solduğunu! 

O halde, bilmez misin aşık olduğunu,

Sevgi ve aşkımın,kalbine dolduğunu

Aşksız yaşamını boşuna yolduğunu 

Unutacaksın, yaşamın da solduğunu

Söyler misin, bana, sen aşık olduğunu

Bomboş duran kalbinin şimdi dolduğunu

Yaşamını sevgilim aşkla yolduğunu

Sevgisizlikten, hep soldukça solduğunu! 

Hissettikçe, aşkımın gerçek olduğunu

Aşkımla dolan kalbine aşk dolduğunu

Aşkla yolacaksın, yoldukça yolduğunu

Solmadıkça anımsamazsın solduğunu!', 'Söyle, söyle ne olur, nasıl olduğunu, Aşkımla, benliğinin nasıl dolduğunu Gece gündüz kendini nasıl yolduğunu  Ve hele günden güne nasıl sol...', ARRAY['Türk Edebiyatı','Şiir','Ahmetnecat Ucur']::text[], 8.5, '{"poet":"Ahmetnecat Ucur","poet_slug":"ahmetnecat-ucur","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askimasik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamamışım', 'unutamamisim-sevilay-celik-4hahj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'tam unutmuşken seni,bitti hersey demişken,

radyoda şarkımız çalındı,

yaşadığımız anılar,bir bir gözümün önünden geçti

ağladım,ağladım.

kalbim acıdı,

tam unutmuşken seni yine hatırladım.

bir sigara yaktım.

derler ya sigara dertleri bir an olsun unutturur diye.

hiç bir derdimi unutturmuyorki,

birini söndürüp diğerini yakıyorum,

içime çektikçe dumanını,

içim daha çok acıyor

sigara dertleri unutturmuyor,

yalan söylüyolar

inadına daha çok acıtıyor yüreğimi

tam unutmuşken seni,bitti herşey demişken,

tekrar hatırladım.

şarkıda elindeyim işte oyuncak gibi diyor ya,

evet elindeyim bir oyuncak gibi,

yine ben seninleim,

yine içimde aşkın,

aklımda hayalin,

elimde solmuş resmin

yine ben ağlıyorum.

anladımki ben seni hiç birzaman unutamamışım,

sadece ama sadece kendimi kandırmışım..', 'tam unutmuşken seni,bitti hersey demişken, radyoda şarkımız çalındı, yaşadığımız anılar,bir bir gözümün önünden geçti ağladım,ağladım. kalbi...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Çelik']::text[], 8.5, '{"poet":"Sevilay Çelik","poet_slug":"sevilay-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/unutamamisim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güllerin olsam.', 'gullerin-olsam-i-shak-ozlu-jf3hi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göz yaşlarımın toprağı olsan,

Tane tane süzülsem göğsüne.

Bağrında açan güllerin olsam,

Sarsan kucak kucak ak göğsüne.

Sızlayan tenime ilaç olsan,

Yudum yudum işlesen kalbime.

Yansam ateşinde tabip olsan,

Sarıp başım yaslasan kalbine.

Bekletme ey yar gel dermanım ol,

Sar sevdalın gibi bas göğsüne.

Sensiz deli gönül susuz bir çöl,

Yağmurum ol süzül gel göğsüme.', 'Göz yaşlarımın toprağı olsan, Tane tane süzülsem göğsüne. Bağrında açan güllerin olsam, Sarsan kucak kucak ak göğsüne. Sızlayan tenime ilaç ...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gullerin-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antikacı Aziz', 'antikaci-aziz-mehmet-akif-tiryaki-1crcz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sapanca''nın girişinde, karakolun karşısında, 

Antikacı Aziz Bey dükkanın tam ortasında 

Oturmuş müşteri bekler dururdu, 

Antikaların tozunu siler, onları iyi korurdu. 

İlk tanışmamız Aziz Bey''le şöyle oldu; 

Arabamı dükkanın önüne çektim, içeri girdim, 

Antikalara bakarak vakit geçirecektim, 

Dükkanın her köşesi eski eşyalarla doluydu, 

Enteresan eski eşyalar kafamı yordu. 

Kimse yok mu diyecektim ki birden bir sesle irkildim, 

Buyurun efendim dedi bir ses yakınlarımda, 

Baktım ki Aziz Efendi oturuyor karşımda koltukta. 

Elinde antika bir tespih, şapkası fötr, 

Elbiselerinin rengi eski eşyalarla aynı renk, 

Yüzü hafif soluk ve donuktu, 

Sanki o dükkanda antika bir konuktu. 

Hoş bulduk dedim, şaşırdım kaldım, 

Aziz Bey''i incelemeye daldım. 

Antikalardan çok beni aziz bey ilgilendirdi, 

Antikaları da toplayan ve değerlendiren kendisiydi. 

Tam bir tarihti, eşya eksperiydi, 

Tanıştık hoş sohbet çayını içtim, 

Kendime bir kaç tunç havanı seçtim. 

Aziz Abi onları paketledi, fiyat saptadı, 

Beni sevindirdi, puan topladı. 

Bir saatlik vaktimi güzel geçirdim, katladım, 

Koydum cebime, 

Devam ettim Sapanca eğlencesine. 

Göl kenarına gittim iki çay yudumladım, 

Aziz Abi''yi devamlı hatırladım.', 'Sapanca''nın girişinde, karakolun karşısında,  Antikacı Aziz Bey dükkanın tam ortasında  Oturmuş müşteri bekler dururdu,  Antikaların tozunu ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/antikaci-aziz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce olmak', 'dusunce-olmak-ali-veli-m4q2m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşam deneyimlerinin amacı

Öğrenmek bilgilenmek dostlarım

Bilmek ve düşünebilmek

Özgürlüğün,mutluluğun,yaşamın

Sınırsız olduğunu kavramak

Zekanın yüceliğini bilerek

Kendimizide yüceltebilmek

Düşünceyle kavramı kavramak

Algılamak,benimsemek,hissetmek

En önemlisi sevebilmek

Sevgi düşüncesini bilmek,karışmak

Varlığımızın sesiyle

Kavuşmayı beklemek,coşmak

Değişim rüzgarında

Değişebilir olmak,birleşmek

Geniş anlayışla,soyutlaşmak

Sevgi olmak,düşünce olmak

Karışmışlık gibi evrimleşmek

Gerçekliğimize dönmek

Düşünce olmak

İnsanlığı oluşturan sevgiyle

Yüceliğimizi idrak etmeliyiz', 'Yaşam deneyimlerinin amacı Öğrenmek bilgilenmek dostlarım Bilmek ve düşünebilmek Özgürlüğün,mutluluğun,yaşamın Sınırsız olduğunu kavramak Ze...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dusunce-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıtmam Lazım Kendimi Senden', 'aritmam-lazim-kendimi-senden-meram-yalinizoglu-v8wry', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kanatları kırıldı içimde

Özgürce çırpınan aşk kuşunun

Çıkarmam lazım seni hayatımdan

Unutmam lazım

Bitirmem lazım

Yok etmem lazım

Hiç tanımamış gibi

Hiç görmemiş gibi

Hiç sevmemiş bibi

Arıtmam lazım kendimi senden

Okunmamış mektup gibi,

Anlamsız kelimeler gibi,

Yazmayan kalemler gibi,

Açmayan güneş, dinmeyen yağmur gibi

Gözlerimden boşluğa akan damlaların gibi

Çıkarmam lazım seni hayatımdan,

Unutmam lazım

Bitirmem lazım

Yok etmem lazım

Arıtmam lazım kendimi senden...

23/01/2006', 'Kanatları kırıldı içimde Özgürce çırpınan aşk kuşunun Çıkarmam lazım seni hayatımdan Unutmam lazım Bitirmem lazım Yok etmem lazım Hiç tanıma...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aritmam-lazim-kendimi-senden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-ali-veli-0o869', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düş''tün gerçekliğinde

Ben düş''ünün peşinde

Düş-lendim düş-lerinde

Gerçekliğimde düş-tün

Düş-üm gerçek oldu

Gerçekliğim düş-ün

Düş-ürdün,düş-tüm

Düş-ünemedim düş-künlüğünü

Düş oldum

Düş-man oldum

Düş-tün...', 'Düş''tün gerçekliğinde Ben düş''ünün peşinde Düş-lendim düş-lerinde Gerçekliğimde düş-tün Düş-üm gerçek oldu Gerçekliğim düş-ün Düş-ürdün,düş-...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dus-156-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğu Arıyorum', 'mutlulugu-ariyorum-meram-yalinizoglu-80319', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kuşlar gibi gökleri feth etmek

Karşı koyabilmek rüzgara

Denizlerin en derinlerine inmek

Özgürce mutlu olmak istiyorum...', 'Kuşlar gibi gökleri feth etmek Karşı koyabilmek rüzgara Denizlerin en derinlerine inmek Özgürce mutlu olmak istiyorum......', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mutlulugu-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmişti', 'bitmisti-sevilay-celik-b60w5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün gördüm seni tanıştığımız yerde,

okadar çok değişmişsinki tanıyamadım.

saçlarına aklar düşmüş,

üstün perperişan,

bitkin,çağresiz bir durumda oturuyorsun.

dedilerde inanmamıştım.

benden ayrıldıktan sonra böyle olacağını hiç düşünmemiştim,

beni bukadar sevdiğini hiç bilmiyordum.

ama iş işten geçmiş derler ya,

gerçektende iş işten çoktan geçmişti.

ayrılmıştık,herşey bitmişti.

okadar isterdimki sana geri dönmeyi,

seni bir an olsun unutamadığımı,

herzaman sevginin kalbimde olduğunu,

senden sonra kimseyi sevmediğimi,

gözlerinin içine bakarak,

seni seviyorum seni hala çok seviyorum,

demeyi isterdim.

ama yapamadım

çünkü herşey bitmişti.

adı üstünde b-i-t-m-i-ş-t-i', 'Dün gördüm seni tanıştığımız yerde, okadar çok değişmişsinki tanıyamadım. saçlarına aklar düşmüş, üstün perperişan, bitkin,çağresiz bir duru...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Çelik']::text[], 8.5, '{"poet":"Sevilay Çelik","poet_slug":"sevilay-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bitmisti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Günlerde Gülüyorsam Eğer...', 'bu-gunlerde-guluyorsam-eger-ali-orhan-gunaydin-ibmt7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülüyorsam bu günlerde eğer...

Sağolsun...

Kaderim hep güldürüyor...

Hayır olur inşallah...

Bu günlerde nedense,

Bana bir başka iyi davranıyor...

26/01/2006', 'Gülüyorsam bu günlerde eğer... Sağolsun... Kaderim hep güldürüyor... Hayır olur inşallah... Bu günlerde nedense, Bana bir başka iyi davranıy...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-gunlerde-guluyorsam-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmişüç kiloydu', 'yetmisuc-kiloydu-adem-atacak-6zudi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yarım tava menemene kırılan

Yetmiş üç kiloluk ömrün özetiydi bu

Küflenmiş ekmek tadı var hayatın

Ne kadar da rahatmış 

Bu dört tarafı tahtanın

Beyaz yağar yağmurlar 

Semadan aşağı

Vurdular beni 

Ölümüm kan kaybındandı

Namahrem bilmez imam

Onca insan içinde beni yıkayan 

Yarım gelir bu çilenin fedakarlığı 

Keşke biraz daha vaktim olsaydı

İlk defa korkmadım ölmekten 

Artık sağlam basıyorum adımlarımı

Küflenmiş gururum aşındırır

Eşin dostun omuzlarını 

Siyasetten olmadı bu terk edişim

Teşhisim kolay oldu

Beni öldüren sol akciğerim

Adı konulmamış bu özet benim

Keşke herkesi daha çok sevseydim', 'Yarım tava menemene kırılan Yetmiş üç kiloluk ömrün özetiydi bu Küflenmiş ekmek tadı var hayatın Ne kadar da rahatmış  Bu dört tarafı tahtan...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yetmisuc-kiloydu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SeVmİş BiRkErE KaLbİm SeNi', 'sevmi-s-birkere-kalbi-m-seni-sevilay-celik-cvqkn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevmiş bir kere bu kalbim seni,

nasıl unutsun bunca şeyleri,

unutmak kolaysa sen unut beni,

unutursan unuturum belki bende seni.

sevmiş bir kere bu kalbim seni

kolay değil bir anda silmek herşeyi,

silmek kolaysa sen sil beni,

silersen silerim belki bende herşeyi.

sevmiş bir kere bu kalbim seni,

atmak kolaymı kalpten senin sevgini,

atmak kolaysa sen at kalbinden beni,

ama atamam ben bu kalpten senin sevgini...', 'sevmiş bir kere bu kalbim seni, nasıl unutsun bunca şeyleri, unutmak kolaysa sen unut beni, unutursan unuturum belki bende seni. sevmiş bir ...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Çelik']::text[], 8.5, '{"poet":"Sevilay Çelik","poet_slug":"sevilay-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmis-birkere-kalbim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyemedim', 'usuyemedim-adem-atacak-au8c1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben, sana 

Balta girmemiş üzüntülerimin

İçinde yankılanan

Hoyrat çığlıklarımı getirdim

Çöp kutusundan çıkmaya çalışan 

Yırtık mısralarımın üstüne yemin ederim ki 

Yağmur bulutlarında asılı kalan 

Hıçkırıklarım yağacak düşlerine

Perilerden arta kalan

Defolu masalların 

Bezgin bedenlere can oluşuna şahit olacaksın

Ve ben

Kırağı inen camlardan seyrederken

Şakırdayan dişlerimi

Seni düşündüm

Üşüyemedim', 'Ben, sana  Balta girmemiş üzüntülerimin İçinde yankılanan Hoyrat çığlıklarımı getirdim Çöp kutusundan çıkmaya çalışan  Yırtık mısralarımın ü...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/usuyemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adonis', 'adonis-okan-nar-ktbtt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceye katran karıştı,

Yüreğimde hasretin Bahar Gözlüm.

Biliyorum yine zor olacak sabah..! 

Her ne yana baksam,

Gözlerin...ahh şiir gözlerin.

Her ne yana salsam yüreğimi,

Boydan,boya aynalar..! 

Bir çift bakış...

İki damla gözyaşı...

Ve sen...ve Adonis.*

Kısa,kısa kareler..

Fakat,uzun metrajlı.

Biliyorum yine zor olacak sabah..! 

Dokunamadığım gölgelerde suletin,

Bitmeyen,tükenmeyen hasretin.

Gecelerde,gündüz..

Gündüzlerde,gece her dem.

Bir çift bakış...

İki damla gözyaşı...

Ve sen...ve Adonis.*

Çok cilveli o gün deniz,

Çarşaf olmuş,çakılları gözüküyor.

Biliyorum yine zor olacak sabah..! 

Gözlerindeki ışıltılar sarmalıyor  herbir yanı,

Yakomozları kıskandırıyor  gamzelerin.

İhtişamıyla karşıda tarihi kale,

Sevişmelerimize tanıklık ediyor.

Bir çift bakış...

İki damla gözyaşı...

Ve sen...ve Adonis.*

Yeni bir eski yıla saatler var..! 

Dışarıda deli yağmur,şimşekler.

Biliyorum yine zor olacak sabah..! 

Tempo tutuyor silecekler ve titanic.

Arabanın farları kesiyor geceyi.

Yüreğimizde hayallerimiz,sevdamız...

Herkese,herşeye inat sözümüz var..! 

Bir çift bakış...

İki damla gözyaşı...

Ve sen...ve Adonis.*

*** APHRODITE VE ADONIS



 

 Bütün bitkilerin anası olan Aphrodite''in Adonis adında bir oğlu daha vardı. Yunanlılar Aphrodite''in oğlunu bizi çarçabuk terk eden çiçekli ve neşeli ilk baharın sembolü olarak kalbul ederlerdi. Adonis saklandığı ağacın kabuklarını yarark çıktığı zaman güzel günler başlıyor, çiçekler açıyor, ilbahar başlıyordu. Onun hayatı tıpkı çiçekler gibi sınırlıydı, bir kaç gün sürüyordu. Çünkü Adonis açılıp güldüğü, gençliğin en güzel ve parlak çağına ulaştığı gün ölüyordu. Bu zaman yaz mevsiminin sonuna denk geliyordu. Yani sonbaharın çiçeklerin solduğu, yaprakların sarardığı dünyaya hüzünlü bir havanın hakim olduğu mevsimn. İşte bu mevsimde Adonis dünyamızı terk ediyor görünmez bir aleme giriyordu. 

Böyle bir mevsim de Adonis yaban domuzunu kovalarken hiç beklemediği bir anda yaban domzu birden bire geri dönmüş ve ona saldırmıştı. Aphrodite oğlunun geçirdiği kazayı haber alır almaz Olympos''tan aşağı inmişti, ancak yanına vardığında oğlu çoktan ölmüştü. Aphrodite ağlayarak oğluna sarıldı. Adonis''in ölümüyle Aphrodite''in yanı sıra periler ve bir çoktanrıça göz yaşı döktüler, yas tuttular. O günden sonra Adonis''in öldüğü gün''ün anısına Adonis''I sevenler yas tutmaya başladılar..taki doğduğu güne kadar. Bu yüzden, neşeli ve rengarenk geçen ilk bahar ve yaz mevsiminden sonra kasvetli ve hüzünlü sonbahar ve kış gelir. Bu mevsimler Aphrodite ve perilerin Adonis''in yasını tuttukları dönemdir.', 'Geceye katran karıştı, Yüreğimde hasretin Bahar Gözlüm. Biliyorum yine zor olacak sabah..!  Her ne yana baksam, Gözlerin...ahh şiir gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Okan Nar']::text[], 8.5, '{"poet":"Okan Nar","poet_slug":"okan-nar","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/adonis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum ve kalemim bir de şiir', 'dogum-ve-kalemim-bir-de-siir-ali-veli-a92bl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir başkalaşımdır yaşam belirginsizliğimizle

Farkedemediğimiz,kısırdöngülerin parçalanışı

Sarmaldır bilincin aktardığı bilinçaltına

Dehlizler gerekli hatırlayışlara suskun...

Biz ki susturulmuş ya da unutmuş

İdealar değil kaygılar dünyası takıldığımız

Doğumlar gerekli sancılara...

Kırık buz parçaları acılarımız

Sadece kırıkken rahatsız eden

Su halinde dingin ve emin...

Kalemim yazmak istemez bazen,

Bildiklerini tüketmek istememecesine

Paylaşmak ah paylaşmak

Unutturuverir tükenişleri tüketilmişlikleri

Akar gider sonsuza doğru

Bir yerde duracağını bilmeden

Dört saat sonra ben doğuyorum

Dokuz ayın sonrasında suskun...', 'Bir başkalaşımdır yaşam belirginsizliğimizle Farkedemediğimiz,kısırdöngülerin parçalanışı Sarmaldır bilincin aktardığı bilinçaltına Dehlizle...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dogum-ve-kalemim-bir-de-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalin', 'hayalin-sevilay-celik-n8rwt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şimşek gürültüsüyle uyandım dün gece,

birden sen aklıma geldin bilmem nedense,

karşımda aniden hayalin büründü,

''''gel'''' diyordun bana bilmiyorum nereye,

kollarımı açtım geliyorum diyorum,

gitsemmi,gitmesemmi karar veremiyorum.

kalbimede gönlümede söz geçiremiyorum

sadece hayaline koşu veriyorum.

bu gidişin sonu bilmiyorum nereye,

sana sarılmak ümidi ile gidiyorum bir yere

belki sonu ölüm bunu bile bile,

koşu veriyorum hayaline sadece..', 'şimşek gürültüsüyle uyandım dün gece, birden sen aklıma geldin bilmem nedense, karşımda aniden hayalin büründü, ''''gel'''' diyordun bana bilmiy...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Çelik']::text[], 8.5, '{"poet":"Sevilay Çelik","poet_slug":"sevilay-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayalin-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kenar mahalle', 'kenar-mahalle-adem-atacak-0oczs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çıplak ayaklarında 

Nasırlı ümitler besleyen 

Kenar mahalleye

Güneşi ıslatan yağmurlar yağdı

Ve fazla kilolu nefretimden 

Çakallar birer parça aldı

Mavi gökkuşağı vurdu gözlerinden

Kırmızı lambalara

Hırçın kavgalarda 

Senin içindi direnişim

Roman gibi yaşadık

Şiir gibiydi gidişin', 'Çıplak ayaklarında  Nasırlı ümitler besleyen  Kenar mahalleye Güneşi ıslatan yağmurlar yağdı Ve fazla kilolu nefretimden  Çakallar birer par...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kenar-mahalle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Dünya Neye Yarar', 'bu-dunya-neye-yarar-yusuf-onder-bahceci-3f5ay', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilki sen bütün Alem bir olsa,

Açan güllerimin hepsi solsa,

Eğer bu sevdamız olmasa,

Bu Dünya neye yarar.

Yer ile gök hep birleşse,

İnsanlar da herşeyi üleşse,

Satılan her şey beleşse,

Bu Dünya neye yarar.

Sevdim seni beklermiyim,

Yürüyemem emeklermiyim,

Kalbimde kırık teklermiyim,

Bu Dünya neye yarar.

Arif olanlar hep anlıyor beni,

Cân kulağı ile dinliyor beni,

Aşk acısı çeken inliyor hemi,

Bu Dünya neye yarar....', 'Bilki sen bütün Alem bir olsa, Açan güllerimin hepsi solsa, Eğer bu sevdamız olmasa, Bu Dünya neye yarar. Yer ile gök hep birleşse, İnsanlar...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-dunya-neye-yarar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilsiz mantığı', 'dilsiz-mantigi-ali-veli-oag5q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çekiyor at arabasını adsız

Çekiyor peşinde birkaç yaşamı

Bitiyor geçmiş ve gelecek

Bitiyor varoluş malzemesi ses

Bakıyor uzaklara umursamaz

Bakıyor ve yankılanıyor sessizliği

Çeviriveriyor gözlerini

Marjinalliğini lanetliyor

Sınıflayamıyor kendini

Mekan tutsağı sayıyor kendisini

Yanlızca ben...', 'Çekiyor at arabasını adsız Çekiyor peşinde birkaç yaşamı Bitiyor geçmiş ve gelecek Bitiyor varoluş malzemesi ses Bakıyor uzaklara umursamaz ...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dilsiz-mantigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşarak geliyorum', 'kosarak-geliyorum-adem-atacak-6u2pl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Islak çimenlerde

Şehit edilen bir gelecek açar

Çiçeği burnunda bulutlardan

Sağanak bir ışık yağar

Boğuşan kavgalar

Sular altında kalır

Güneş doğar

Esmer bir sükunet buharlaşır

Nur topu iğde ağaçlarını gönderiyorum

Bilmediğin adresine

Koşarak geliyorum 

Nerdesin hala bilmiyorum', 'Islak çimenlerde Şehit edilen bir gelecek açar Çiçeği burnunda bulutlardan Sağanak bir ışık yağar Boğuşan kavgalar Sular altında kalır Güneş...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kosarak-geliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erciyesle Sohbet', 'erciyesle-sohbet-mehmet-postalli-ffwp6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim başımda sevda, senin başında hep kar

Senin içinde yangın, benim içimde umut

Senin başında duman, benim başımda efkar

Çile dolu içimi dökeyim de  saklı  tut

O, serin kucağına dayasam da başımı

Vefalı bir dost gibi, dertlerimi dinlesen

Kül rengi toprağına akıtsam gözyaşımı

Kan kırmızı çiçekler yeşerse desen desen

Benim başım dönüyor, senin başın göklerde

Ben yerden göğe doğru, sen tepeden bakarsın

Üstünde ak bulutlar dolaşır perde perde

Damla damla alırda, oluk oluk dökersin

Sen kıyamda durukken, benim başım eğilir

İkimizde Allah’a inanırız yürekten

Her zaman zikirdesin, ancak bilenler bilir

Birçoğumuz hissizdir, habersizdir gerçekten

Bir gelin gibi nazlı, kral kadar mağrursun

Yıldızlarla konuşur, dağlara baş tutarsın

Alnı berrak, başı dik bir modelsin, uğursun

Kayseri’yi kucaklar gönlünü hoş tutarsın

Güneş ilk önce sana gösterir gül yüzünü

Sen kıyamete kadar yaşarsın be Erciyes

Mevlam öbür dünyada güldürsün öksüzünü

Benim ömrüm sadece, tek perdelik bir piyes', 'Benim başımda sevda, senin başında hep kar Senin içinde yangın, benim içimde umut Senin başında duman, benim başımda efkar Çile dolu içimi d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/erciyesle-sohbet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişine tekabül ediyor', 'gidisine-tekabul-ediyor-adem-atacak-irxre', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üzerimden atamadığım 

Yorgun bir uğursuzluğun

Tuz çöreği stresiyle aynı masadayım

Hoyratça bir paylaşımın

Aç gözlü parçalarına bölündüm

Dilim dilim 

Kimilerine sen düştün

Kimlerine ben

Zaruri yaşamımın 

Batan her köşesinde

Gözlerim seni arıyor

Ağızlarına kan bulaşmış

Acımasız gülümsemelerin 

Kimilerini sen seyrediyorsun

Kimilerini ben

Son birkaç gündür 

Efkarım ters taraftan iniyor

Hesap ettim

Gidişine tekamül ediyor', 'Üzerimden atamadığım  Yorgun bir uğursuzluğun Tuz çöreği stresiyle aynı masadayım Hoyratça bir paylaşımın Aç gözlü parçalarına bölündüm Dili...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gidisine-tekabul-ediyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 42', 'guncel-beyitler-42-huseyin-avdic-8w5kq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bizim A$kimiz

Ölümsüz Olan''adir bizim a$kimiz, sevdamiz.

Ölümlüleri de, O''nun icin sevip saymadayiz.

Berlin, Ocak 2006.', 'Bizim A$kimiz Ölümsüz Olan''adir bizim a$kimiz, sevdamiz. Ölümlüleri de, O''nun icin sevip saymadayiz. Berlin, Ocak 2006....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Skoru belirsiz savaş', 'skoru-belirsiz-savas-adem-atacak-fl38x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağzına yağmurluk geçirdiğim

Ütülü gömleğimin üstüne

Tenimle karışık sevdiğim 

Gökyüzü kusuyor

Kaçan iştahımı yutuyor 

Girdaplı ayaklarım

Ve ben ıslanan elbisemle 

Zayıfladığımı-kuruduğumu-düşünüyorum

Bu sırılsıklamda

Bir kavga kaçıyor ellerimden

Bu savaşta,skoru belirsiz

Bir sen kaldın birde ben', 'Ağzına yağmurluk geçirdiğim Ütülü gömleğimin üstüne Tenimle karışık sevdiğim  Gökyüzü kusuyor Kaçan iştahımı yutuyor  Girdaplı ayaklarım Ve ...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/skoru-belirsiz-savas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıymetlim', 'kiymetlim-meram-yalinizoglu-wvxfx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalemler tüketmek istiyorum senin için

Işıklar sönene kadar

Yanan ateşimi anlatmak kelimelerde.

Mesafeleri kaldırmak aramızdan

Engelleri aşmak, kucaklamak seni

Tenlerimizi birleştirmek,

Lapa lapa karı eritircesine.

içimdeki sevgiyle

Mesafeleri kaldırmak istiyorum aramızdan.', 'Kalemler tüketmek istiyorum senin için Işıklar sönene kadar Yanan ateşimi anlatmak kelimelerde. Mesafeleri kaldırmak aramızdan Engelleri aşm...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kiymetlim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizilen resim', 'cizilen-resim-ali-veli-mh5fk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Başlangış bir güneş patlamasıydı

Sonra kesik kesik dalgalar gibi

İki yanda dev kepçeler yükseliyordu

Sesleri yutmak için

Ya o solucan görünümlü karartı

İki büyük çukur vardı

Bir çukur daha ve yine bir çukur

Ortasındaki dallar

Büyük çukurda karamsarlık

Küçük çukurda evren

Sert çizgili iki kanca

Evet,elmacık kemikleriydi

Ve aşağıya indikçe

Büyük bir değişken

Dilediğini söyleyen

Sahibinin varlığını,kişiliğini betimleyen

Bir surat çizmişti

Hem de korkunç,hem de şaşkın

Hem de tüm ifadeleriyle bir surat

Çelişkiyi anlatmıştı suratında

Yaradılışın malzemesiydi çelişki

Yeni bir estetik yaratmak istemişti

Farkında olmadan gerçeği bulmuştu

İnkar etmiştik bu gerçeği

Vurdumduymaz davranmıştık

Küçümsemiştik çelişkiyi

Çelişki kendimdi,varlıktı,varolandı

Çelişkilere çelişiğim

Sanki çelişki değilmişim gibi...', 'Başlangış bir güneş patlamasıydı Sonra kesik kesik dalgalar gibi İki yanda dev kepçeler yükseliyordu Sesleri yutmak için Ya o solucan görünü...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cizilen-resim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne olur', 'ne-olur-adem-atacak-h3bun', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aksayan tren seslerinin

Dökülen kırıntılardan başka

Birkaç uyak biraz da redif

Yeşerdi belediye parkında

Yastık altı annelik duygularına

Emanet ediyorum.

Biçtirme ne olur başkalarına

Şiiristanda yaşayan 

Toprak kokulu çocuklarımın

Gurbet bestelerine kucak aç

Sen oku,sen yaz

Okutma ne olur başkalarına.

Sana

Bir de şiirlerimi  emanet ediyorum

Yastık altı annelik duygularına

Kulun kölen olayım

Ezdirme ip atlayan çocuklara

Eski bir kalemden 

Seni severken

Duyduğum yeni hazlar

Tutmadan yatmasın ellerini

Saat dokuzu geçmeden

Fırçalasınlar dişlerini

Sana yok oğlu yokları

Elde avuçta olmayan

Karnı aç kuruntularımı

Emanet ediyorum

Yastık altı annelik duygularına

Ne olur

Ben gelene kadar dokunma', 'Aksayan tren seslerinin Dökülen kırıntılardan başka Birkaç uyak biraz da redif Yeşerdi belediye parkında Yastık altı annelik duygularına Ema...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ne-olur-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zulüm Makinası', 'zulum-makinasi-ekrem-sama-jzfmp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mahalleli dehşet içindedir o an, 

Kudurmuş bir köpek, bağını koparsa...

Zulüm makinesi oluverir insan 

Allah’ı unutup, ilaha taparsa...

(İstanbul:24.01.2006)', 'Mahalleli dehşet içindedir o an,  Kudurmuş bir köpek, bağını koparsa... Zulüm makinesi oluverir insan  Allah’ı unutup, ilaha taparsa... (İst...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zulum-makinasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şizofren', 'sizofren-adem-atacak-6en4b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Avuçlarım terler 

Bir aralık gecesi

Gördüğüm sanrılar birbirine biner 

Ya bir hastalığın 

Yada şizofrenin habercisi

Yok oluşumu heceleyen 

Muhabbet kuşuyla 

Zaten aram bozuk

Kafam bozuk

Bozuk oğlu bozuk

Sende kimsin tanıyamadım

Okuldan mı, işten mi 

Yoksa diğerleri gibi evden mi

Ciğeri beş para etmez 

Sakatatlı bir yaşamın 

rektumu oturmuş  beynime

hey şey hep aynı renkte     -kahverengi- 

nerde sarı  nerde yeşil,nerde limoni

nerde seni en az sevdiğim 

gök yüzü mavisi

bu kurgunun 

tek gerçek sanılan 

çok yalanıyım

adem nerdesin

rolümü yanlış oynamaktayım', 'Avuçlarım terler  Bir aralık gecesi Gördüğüm sanrılar birbirine biner  Ya bir hastalığın  Yada şizofrenin habercisi Yok oluşumu heceleyen  M...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sizofren-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutmam Mümkün Değil', 'seni-unutmam-mumkun-degil-i-brahim-dikmen-2-xo2gz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Arama hiç boşuna

         Unut beni diyorsun

         Kalbimden söküp atmak

         O kadar

         Kolaymı sanıyorsun

                        Yaşanan onca değerleri

                        Paylaştığımız sevgileri

                        İçimde büyüyen hisleri

                       Seni unutmam mümkün değil

Kalbimi kaldırdım rafa

Sevemem biliyorsun

Başkasının olmayı

O kadar

Kolaymı sanıyorsun

               Yaşlar bürüse gözlerimi

               Yokluğun karartsa günleri

               Sensizlik boğsa geceleri

               Seni unutmam mümkün değil

26/01/2006

Aydınlı_İbrahim Dikmen', 'Arama hiç boşuna          Unut beni diyorsun          Kalbimden söküp atmak          O kadar          Kolaymı sanıyorsun                    ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-unutmam-mumkun-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizlik', 'caresizlik-ali-veli-ei1ce', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne yaptığını bilememek

Ne yapacağını da

Sonsuzca beklemek

Karanlığın karamsarlığın dibinde

Işık halinde çığlık

Kımıldayamadan haykıramadan beklemek

Tıkanmak nefes alamamak

Ve mücadeleyi yitirmek

Öylece beklemek

Sezilere ümitle sarılmak

Sonsuz karanlıkta

Umut ışığını aramak

Kısaca çaresiz yaşamak

Bilinmeyen bir dünyada

Bilinen olmak

Labirentte çıkış aramak gibi

Zaman ilerledikçe yıpranmak

Açlığa susuzluğa boyun eğmek

Düşünebilmeyi yitirmek

Varlığın son kımıltısı

Hiçlikte tanımsız olmak

Çaresizim...', 'Ne yaptığını bilememek Ne yapacağını da Sonsuzca beklemek Karanlığın karamsarlığın dibinde Işık halinde çığlık Kımıldayamadan haykıramadan b...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/caresizlik-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buralarda gördünüz mü?', 'buralarda-gordunuz-mu-adem-atacak-jbuaq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim bir sevdiğim vardı

Akşam üstü yirmi dört nolu peronda kaybettim

Eksi beş yaşında

Çocuğu olacak Boğaçhan adında

Şu selpağı vereceğim

Onu hiç buralarda gördünüz mü

Kalbini kırdım biraz kabayım

Beni kaybetti şimdi yalnızım

Özür dileyip evime gideceğim

Onu hiç buralarda gördünüz mü

Tiroidi yüksekti biraz zayıf

Vaktim az kısaydı hafif

Real’de tas kebabı

Ayrılırken halt yedik

Biz yan yana çok avareydik

Adı meçhul bir ben bilirim.

Onu hiç buralarda gördünüz mü

Dibimdeydi az önce

Eminim buralarda bir yerde

Size soruyorum

Taşlar, bardaklar, insanlar

Benim yarım kalan sözlerim var

Gelmeden şeytanlar

Söyleyin onu hiç buralarda gördünüz mü', 'Benim bir sevdiğim vardı Akşam üstü yirmi dört nolu peronda kaybettim Eksi beş yaşında Çocuğu olacak Boğaçhan adında Şu selpağı vereceğim On...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/buralarda-gordunuz-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Gripli Deli Dana Omleti', 'kus-gripli-deli-dana-omleti-yusuf-onder-bahceci-1pnch', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birgün cânım çok istedi yumurta yemek,

Ben günlerce aradım çok verdim emek,

Küçük bir bakkal gördüm içeri girerek,

Birkaç yumurta versen bakkal diyerek,

Yumurtaları getirdim Hanım al dedim,

Rafadan yumurta bana sanki bal dedim,

Sen kalbini serin tut işte bu hâl dedim,

Yumurtaları güzelce yedim birşey olmadı,

Bir zamanlar deli dana vardı, danalar vardı,

Memleketin her yanını deli danalar sardı,

Allah''ım çok dana eti yedim bir intizarmı,

Yine deli olamadım ben danalar nerde,

Belki de kuş gribi olurum belki ilerde....', 'Birgün cânım çok istedi yumurta yemek, Ben günlerce aradım çok verdim emek, Küçük bir bakkal gördüm içeri girerek, Birkaç yumurta versen bak...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kus-gripli-deli-dana-omleti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kul Hakkı Bahşişimiz Olsun', 'kul-hakki-bahsisimiz-olsun-mehmet-akif-tiryaki-om76t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu tarih sayfalarından hangi partiler geldi geçti,

Kimileri hedef kitle olarak yoksul aileleri seçti,

Sözünü tutmadı, vatandaşı ezdi geçti.

Bırakın bu işleri çökertmeyin bizleri,

Fakir fukara, garip guraba hepimizi,

Bakkal kapattı, esnaf kan ağlıyor,

Çalışanlar kartlarla savaşıyor,

Kart faizleri yıllık ikiyüzkırkı aşıyor,

Devlet banka kanunlarına sahip çıkıyor,

Sayın beyler titreyin ve kendinize gelin,

Hesap sorar gelecek bunu bilin.

Türban sorunu halledilmediki,

Enflasyon indi gene ezildik,

Plastik kartlarla ödedik bileklerimiz çizildi,

Hak mefhumu hiç sayıldı geçildi,

Vatan sağ olsun ama beyler,

Görün artık bunları dinsin akan kan,

Esnaf kan ağlıyor marketler şen,

Zaman gelir ters döner bu devran,

Bir günde güler elbet ağlayan,

Kul hakkı ahrette bahşişimiz olsun,

Bunu siz tercih ettiniz,

Aklınızı başınıza alın, sizi Allah korusun.', 'Bu tarih sayfalarından hangi partiler geldi geçti, Kimileri hedef kitle olarak yoksul aileleri seçti, Sözünü tutmadı, vatandaşı ezdi geçti. ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kul-hakki-bahsisimiz-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cam küreler', 'cam-kureler-ali-veli-08acg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saydam bildiğim katı

İçinde cam küreler

Bilinci toprak ve ısı

Bir başka serüvendir geçmişi

Değişim ile yoğurulmuş bir yaşam

Can bildiğim cam

İçteki dış küreler

Güzellik barındırıyorlar

Nesnel ve göreceli

Var sayılmak gibi varolan

Cam küreler 

Saydam bildiğim katı', 'Saydam bildiğim katı İçinde cam küreler Bilinci toprak ve ısı Bir başka serüvendir geçmişi Değişim ile yoğurulmuş bir yaşam Can bildiğim cam...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cam-kureler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık mısınız?', 'asik-misiniz-emel-hicyilmaz-z8d3m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen; 

   Kalemi elinize aldığınızda; 

   Bir sörfçü edasıyla kayıverir satır sonlarına! 

   Bazen ise; 

   Toprağı harmanlayan kazma misali,

   Saplanıverir sayfanın alnına! 

   Ya aşık olmuşsunuzdur böyle anlarda,

   Ya da yitik bir sevdanın mazlum karışığısınızdır! 

   Tan yeri ağarmakta,

   Göz kapaklarınız isyanlardadır! 

   Gömersiniz başınızı yastığın tam ortasına! 

   Yorganı başınıza kadar çekeresiniz; 

    Nafile! 

      Hafiften bir melodi dinlersiniz; 

        Nafile! 

           Kitap okumayı denersiniz; 

             Nafile! 

   Acımtırak bir açlık hissi saplanır midenize,

   Sebebi huzursuzluktur! 

   Ekmek arası mini bir umut iyi olurdu deyip,

   Geçersiniz hayat tezgahının başına! 

   Yanında; 

   İçine sadakat katılmış bir bardak çay olsa! 

   Bir yudum alırsınız; 

   Şekeri yoktur oysa! 

   Ilık Bir duş olsa,

   Belki de direnmezdiniz uykuya! 

   Geçersiniz akarsuların kesiştiği noktaya; 

   Sıcaklık aniden düşer sıfırın altına,

   Buz tutar her damla! 

   Elinizi attığınız her dal kurur ya!

   İşte o misal yaşıyorsunuz dünyada! 

   Ama hala yanıtı yok! 

   Aşık mısınız! ?                         Karışık mısınız! ?', 'Bazen;     Kalemi elinize aldığınızda;     Bir sörfçü edasıyla kayıverir satır sonlarına!     Bazen ise;     Toprağı harmanlayan kazma misal...', ARRAY['Türk Edebiyatı','Şiir','Emel Hiçyılmaz']::text[], 8.5, '{"poet":"Emel Hiçyılmaz","poet_slug":"emel-hicyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/asik-misiniz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elde var sıfır', 'elde-var-sifir-adem-atacak-2nyef', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Faciaların eşiğine sürüklenen

Çatlak seslerin

Elimi yakan cesaretini tutukladılar

Şekersiz, köpüklü ömrümün

Balkondan yükselen hırıltılarını

Yüksek çatılı evlerin göğsü karşılar

Kılık değiştirerek yankılanır

İfade edemediklerim

Pencereden başka bir dünya bakar

Yan gelen hayatıma

Kendi ekseninde dönen bir evin

Yaşanan iki mevsiminde

Günler karaltı  elde var sıfırlar açar', 'Faciaların eşiğine sürüklenen Çatlak seslerin Elimi yakan cesaretini tutukladılar Şekersiz, köpüklü ömrümün Balkondan yükselen hırıltılarını...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/elde-var-sifir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle kal', 'oyle-kal-adem-atacak-zor2d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karıncaların kemirdiği kaldırımlarda

Ağlayınca çirkinleşen yüzümle

Dibine yürüdüm, yerlerin dibine

Yetim çocukların, N harfiyle yazdığı

Bütün şiirleri getirin başucuma

İzole edilen kişiliğimin

Teneffüs ettiği kokunu

Öksürükle atamayacağımı anladım

Artık egzoz kokan minibüslerin

Asfaltla sevişirken çıkardığı gıcırtılarında

Duyulmuyordu ağlamalarım

Zaten bende onları duymadım

Büyük yediğim lokmaların

Altında ezilmekten başka çarem yok

Nereye gittiysen  öyle kal

Benden eser yok', 'Karıncaların kemirdiği kaldırımlarda Ağlayınca çirkinleşen yüzümle Dibine yürüdüm, yerlerin dibine Yetim çocukların, N harfiyle yazdığı Bütü...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oyle-kal-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Dursa Şimdi...', 'zaman-dursa-simdi-cagla-toygan-cuvhj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman dursa şimdi aniden

Özgür kalsak yeniden sen ve ben

Kaybolsak kopsak hayattan

Tutsan elimi güneşe yansısak tümden….

keyifsizim buaralar bakma bana

ruhumda sızı var anlasana

sensiz olamiyorum beni birakma..

arasira da olsa askini göster bana..

degistirsek kaderi olmaz mı

senle ben yeniden fena mı

geri dönüşü yok bu acı bize reva mı

gel aşkım gel bana duyma sen onları…

(26/01/2006)', 'Zaman dursa şimdi aniden Özgür kalsak yeniden sen ve ben Kaybolsak kopsak hayattan Tutsan elimi güneşe yansısak tümden…. keyifsizim buaralar...', ARRAY['Türk Edebiyatı','Şiir','Çağla Toygan']::text[], 8.5, '{"poet":"Çağla Toygan","poet_slug":"cagla-toygan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zaman-dursa-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLK ŞİİRİM Ağacım', 'i-lk-si-i-ri-m-agacim-levent-i-skenderoglu-eet1i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İLK ŞİİRİM

Ağacım 

Bahçemde ki ağacım

Çiçek açmış dün gece

Bu anı beklemiştim 

Günlerce senelerce

Arılara mekan oldu 

Kelebeklere de öyle

Bu vakte nasıl geldin 

Ağacım bana söyle

Hani dikmiştin beni

Elinde tohumcukken

Sulamıştın ya beni

Güneş baba üstümdeyken

Sonra filizlendim

Çıktım toprak anadan

Sen farkında değilken 

Büyüyordum her zaman

Sonunda seneler geçti

Geliştim olgunlaştım

Gördüğün gibi dostum

Dün gece çiçek açtım.

1986', 'İLK ŞİİRİM Ağacım  Bahçemde ki ağacım Çiçek açmış dün gece Bu anı beklemiştim  Günlerce senelerce Arılara mekan oldu  Kelebeklere de öyle Bu...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ilk-siirim-agacim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun Ya', 'sen-yoksun-ya-meram-yalinizoglu-gclc7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen yoksun ya,

Dünya kapkara

Sen yoksun ya,

Gündüzler bile gece.

Sen yoksun ya,

Kalbim buruk, ruhum sıkkın.

Sen yoksun ya,

Yatağımda bana kırgın,buz gibi.

Odam ruhsuz,

Ben ruhsuz,

Gönlüm tarumar

Sen yoksun ya

Ötesi de yok...', 'Sen yoksun ya, Dünya kapkara Sen yoksun ya, Gündüzler bile gece. Sen yoksun ya, Kalbim buruk, ruhum sıkkın. Sen yoksun ya, Yatağımda bana kı...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-yoksun-ya-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir öykü tasarladım', 'bir-oyku-tasarladim-ali-veli-kxd2p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir öykü tasarladım kafamda

Bir tanrıydım

İnsanlara karışmıştım

Hiçbir şeyin farkında değildim

Onlar gibi olmalıydım

Ve kendim gibi düşünmeye başladım

Özütledim insanları kafamda

Tasarladıkça yalnız kaldım aralarında

Anlamadılar beni

Fazlalık fazla geldi onlara

İlk önce kafalarına çelişkiyi sokayım dedim

Aydınlığa kavuşmaları dileğiyle

Anlamadılar beni

Deli dediler

Aldırmadım

Zaman gerekliydi

Gelişmeliydiler

Sınırları zorlamalıydılar

Başaramadılar

Çünkü olduklarıyla yetindiler

Hep istemeyi biliyorlardı

Vermeyi bilemediler

Mücadele ediyorum isteyeceklermiş gibi

Ben de tanrının oynadığı bir oyunun 

Başrol oyuncusuyum

Niteleyemiyorum kendimi

Kendimi anladığım gün

Anlayacağım onları ve

Son sözümü söyleyeceğim onlara

Siz insansınız...', 'Bir öykü tasarladım kafamda Bir tanrıydım İnsanlara karışmıştım Hiçbir şeyin farkında değildim Onlar gibi olmalıydım Ve kendim gibi düşünmey...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-oyku-tasarladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-adem-atacak-m58cm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neler sıkıştırdım 

Mısraların arasına

Noktalar,virgüller ünlemler

Hepsi ifadenin çaresizliğindeler

Aynı üniformalı duygu panzerlerinde

Kah sevda kah hasret için cebelleşirler

Şiirler başka

Su koymazlar yarı yolda

Römork gibi tren gibi çekerler kahrını

Satmazlar insanı

Son mısrasına kadar severler

Bu borçtur

Öderim diyetimi

Senden başka tanımam gerisini', 'Neler sıkıştırdım  Mısraların arasına Noktalar,virgüller ünlemler Hepsi ifadenin çaresizliğindeler Aynı üniformalı duygu panzerlerinde Kah s...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/siir-146-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paranoyak iklimler', 'paranoyak-iklimler-adem-atacak-hs5jf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'paranoyak iklimlerin bahçelerinde

yüzü façalı rüzgarlar

unutamamaktan korktuklarımı tutar ellerinde

hür irademden geriye 

karar veremediklerim kaldı

Birde somutları soyutlaştıran

Pusuya yatan avuntularım

Ne zaman toprağı kazsam

Kendime güvenemediklerimle kesişiriz

Ve bir kinin burnundan soluyan

Uğultusuyla dineriz

Konuştukça yiğitleşen

Cılız benliğimin

Kış ortası güneşlenmelerini ısıtıyorum

Gazete parçalarıyla

Kararın eşiğinden döneli çok oldu

Kararsızlık sırtımda

Yüküm ağır oldu', 'paranoyak iklimlerin bahçelerinde yüzü façalı rüzgarlar unutamamaktan korktuklarımı tutar ellerinde hür irademden geriye  karar veremedikler...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/paranoyak-iklimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Dediğin', 'omur-dedigin-mahmut-simsek-gin94', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doğarken bile hayattan almazsın heves

Ağlarsın durmadan bir zaman nefes nefes

Hayat bir merdivendir çıkmak zor bir heves

Ömür dediğin nedirki bir yudum nefes

Nefesle birlikte yaşatır bir yudum su

Yaşam dediğin nedirki ana kuzusu

Ölümsüz olmak ister yaşamak arzusu

Ömür dediğin nedirki bir tek yudum su

Gençlikte insanın kanı kıpır kıpırdır

yaşarken gençlik hevesi cıvıl cıvıldır

Olgun yaşa gelince insan bir düşünür

Nefes dediğin nedirki bir yudum ömür.

Hayat bir merdiven yavaş yavaş çıkarsın

Zirve çok yüksektir başın döner düşersin

Heves kırılır su gibi olmak istersin

Ömür dediğin nedirki bir yudum nefesin.

Yaş kemale erince insan bir durulur

Bilirki ebedi hayatı onu bulur

Dönüşü olmayan bir yolculuk durdurur

Dünya dediğin ne,ki bir yudum ömürdür', 'Doğarken bile hayattan almazsın heves Ağlarsın durmadan bir zaman nefes nefes Hayat bir merdivendir çıkmak zor bir heves Ömür dediğin nedirk...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/omur-dedigin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmek ve farketmek', 'bilmek-ve-farketmek-ali-veli-v7tz3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çıkışsızlığın döngüsüdür yaşamak

Sanrılar nefessizliğin göstergesi

Bir an sarmal görüngülerde varoluş

Gerçeklik postmodernleştirilmiş,umursamaz

Ve ben güneşe doğru suskun

Haykırışlarımız kanat sesi gibi

Bazen farkedilmiş kanıksanık

Bazen farkedilmemiş yalın...

Bilmediğimiz çemberin ne zaman neresinde olduğumuz

İç ve dış döngüsünde kaybolmuş

Yolumuz raylarla biçimlenmiş yollara uyumsuz

Bir Ömer Hayyam sarhoşluğu istiyorum

Hem farkında hem farkındasız

Bilmeliyiz...', 'Çıkışsızlığın döngüsüdür yaşamak Sanrılar nefessizliğin göstergesi Bir an sarmal görüngülerde varoluş Gerçeklik postmodernleştirilmiş,umursa...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bilmek-ve-farketmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne istediğimi unuttum', 'ne-istedigimi-unuttum-adem-atacak-jok25', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözümde büyüyen 

Yavşak boyunda engellerin

Atladığını gördüm üzerimden

İçim dışıma yapıştığında

Sorunlar içerisinde çözünen

Basit cevaplı 

Bir kişiliğim artık

Dilenme diyor hayat

Dile benden

Sil baştan doğ

Sil baştan insanların,koy isimlerini

Babamın ellerine

Alnımın değdiğindeki

Temiz bir yazgıyla

Dilenmeden diliyorum

Unuttum adı neydi', 'Gözümde büyüyen  Yavşak boyunda engellerin Atladığını gördüm üzerimden İçim dışıma yapıştığında Sorunlar içerisinde çözünen Basit cevaplı  B...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-istedigimi-unuttum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa kesiyorum hayatı', 'kisa-kesiyorum-hayati-adem-atacak-2qrem', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağrılı özlemlerim vardı

Islanmış dağ yamaçlarında.

İhtimaller üzerine kurulu

Uzun ömürlü hasretlerim vardı

Ve kısa gülüşlerim oldu

Uzun ağlamalardan sonra

Göz göze geliyorum dünyayla

Artık kısa kesiyorum hayatı', 'Ağrılı özlemlerim vardı Islanmış dağ yamaçlarında. İhtimaller üzerine kurulu Uzun ömürlü hasretlerim vardı Ve kısa gülüşlerim oldu Uzun ağla...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kisa-kesiyorum-hayati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem neden', 'bilmem-neden-adem-atacak-ksjc6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilmem neden

Bir gece oturdum ağladım

Göz yaşlarım sessizce yolunu bulmuş akarken

Yalnızlık odamın duvarlarında

Gel diye haykırırken

Oturdum bir daha ağladım

Bilmem neden', 'Bilmem neden Bir gece oturdum ağladım Göz yaşlarım sessizce yolunu bulmuş akarken Yalnızlık odamın duvarlarında Gel diye haykırırken Oturdum...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bilmem-neden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulaşıklar', 'bulasiklar-adem-atacak-bxbhb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tek kişilik ailenin

Çekirdek mensubu cesaretiyle

Ahkam kesiyorum kendime

Sözüm bir bulaşıklara geçiyor

Onlar da bitmek üzere

Yorgan altından 

Işık isteyen korkularıma

Çullanmış kabuslar

Yine yalnız kaldık

Tek başımıza bulaşıklar', 'Tek kişilik ailenin Çekirdek mensubu cesaretiyle Ahkam kesiyorum kendime Sözüm bir bulaşıklara geçiyor Onlar da bitmek üzere Yorgan altından...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bulasiklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlık', 'ciglik-ahmet-zekai-yildiz-6axih', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir çığlıkla gelmişlerdi.

Gittiler/ bin çığlıkla.

Milyonlarcaydılar.

Yaşadılar çığlık çığlığa.

İnsanlar, insanlar..

Kimi otlar gibi sessiz.

Kimi hayvanlarca vahşi.

Az da olsa insan vardı kuşkusuz.

Duygulu, kaygılı ve sessiz.

Bir dünyaları vardı yaşanacak.

Birbirine dar ettikleri.

Bir de ölümlü bedenleri.

Ne sevmeyi becerebildiler.

Ne de nefret etmeyi.

Bir avuç topraktı işin özeti.

Gün oldu Deli Dumrul oldular.

Bir köprü başında

Fukara nafakası kestiler.

Gün oldu zalim kral olup,

Zengini daha zengin ettiler.

Voyvoda olup kazığa oturttular, insanları..

Hitler olup gaz odalarında yaktılar.

Sarıkamış dağlarında dondurdular binleri.

Dağda yeti,

Ormanda Tarzan,

Çölde Mecnun,

Denizde Macellan,

Ayda Armstrong,

Tabloda Munch,

Klavyede Verdi,

Şiirde Nazım,

Hiroşima’da atom bombası oldular.

Amerika karşısında Che,

Çanakkale’de Atatürk olup,

Yol vermediler işgalciye.

Yollarda Yunus,

Kalplerde Mevlana olup,

Gel! .. Gel ettiler tüm insanlara. 

Mekke’de Muhammed olup,

Kırdılar/ Allah ile kul arasına giren putları.

Nihayet

Buluşmak ve ayrılmaktan ibaret değil mi hayat? 

Bir kuşluk vakti gelmişlerdi, dünyaya..

Gittiler, bir günbatımında 

Çığlık çığlığa, Çığlık çığlığa…', 'Bir çığlıkla gelmişlerdi. Gittiler/ bin çığlıkla. Milyonlarcaydılar. Yaşadılar çığlık çığlığa. İnsanlar, insanlar.. Kimi otlar gibi sessiz. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ciglik-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-ali-veli-rz4qw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabırla yoğurulmuş

Hayallerle avuntulu

Gelecek gün endişesiyle

Umutlanırcasına beklemek

Keskin sirke küpüne zarar misali

Tüketiyor insanı

Kurtulmak gerekli kurulan senaryolardan

Gelmeli beklenen gün

Göstermeli kendini umut

İşte yazgın diyebilmeli

Bak! Göründü gerçek! ..

Düşlemlerde bir serap daha

Yaşama gücünü kemiren beklemek

Umut kıpırtıları gücünü körelten

Ezici,yıpratıcı,güç beklemek

Uzunca yorucu bekleyiş

Hasreti kısa süreli kucaklayış

Beklemek kötü bir kelime

Garipsenecek bir durum

Yaşamım boyunca gitme dürtüsüyle 

Bekledim ben

Niçin olduğunu bilmeden...', 'Sabırla yoğurulmuş Hayallerle avuntulu Gelecek gün endişesiyle Umutlanırcasına beklemek Keskin sirke küpüne zarar misali Tüketiyor insanı Ku...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bekleyis-162-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beğeni', 'begeni-ali-veli-n4yde', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir varoluş kaygısıdır benimkisi

Yolun tam ortasında

Yüzeysel yüzgeçlerin ağırlığında

Uzamsal ve zamansal yoksunluk

Belirsiz estetik', 'Bir varoluş kaygısıdır benimkisi Yolun tam ortasında Yüzeysel yüzgeçlerin ağırlığında Uzamsal ve zamansal yoksunluk Belirsiz estetik...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/begeni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biraz karışık', 'biraz-karisik-adem-atacak-smcx8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Daire içinde 

Köşe kapmaca oynayarak

Kendini aldatan doğruların

Samimiyeti kadar samimiyetsizim

Kum tanelerinin gözümü acıtan

Bütün yorgunluklarının

Raflardaki yerlerini de değiştirdim

Senden kaynaklandığını sandığım

Bu hassasiyetimin

Kaba bir kuruntudan

İbaret olduğunu 

Balıklara yem verirken anladım

Yılların yorgunluğu desem

Daha gencim

Senden desem

Zaten ben seni hiç sevmedim', 'Daire içinde  Köşe kapmaca oynayarak Kendini aldatan doğruların Samimiyeti kadar samimiyetsizim Kum tanelerinin gözümü acıtan Bütün yorgunlu...', ARRAY['Türk Edebiyatı','Şiir','Adem Atacak']::text[], 8.5, '{"poet":"Adem Atacak","poet_slug":"adem-atacak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biraz-karisik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olana Dek', 'sen-olana-dek-mujde-soyturk-15iky', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Selin aktı aktı aktı

Günüme dek, geceme dek

Işığın yaktı yaktı yaktı

Kanıma dek, canıma dek

Seni görüşüm sondu ilkine dek

Ben acemi çaylak

Sen yaman oğlan

Elim karıştı, ağzım cahilliğe dek.

Tenin yandı yandı yandı

Düşüme dek, gözüme dek

İnceliğin çaldı çaldı çaldı

Tadıma dek, malıma dek

Seni isteyişim sondan başa dek

Ben galiba aşık

Sen kendine denk

Her şeyim yitti, 

Sen olana dek.

2001', 'Selin aktı aktı aktı Günüme dek, geceme dek Işığın yaktı yaktı yaktı Kanıma dek, canıma dek Seni görüşüm sondu ilkine dek Ben acemi çaylak S...', ARRAY['Türk Edebiyatı','Şiir','Müjde Soytürk']::text[], 8.5, '{"poet":"Müjde Soytürk","poet_slug":"mujde-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-olana-dek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben olacak yar isterim', 'ben-olacak-yar-isterim-yusuf-ziya-leblebici-yd6yo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haram değil hak görecek

Tenimde bir zar isterim

Beni benden çok sevecek

Ben olacak yar isterim

Gül yanında dikenine

Sevdamızın dertlerine

Düşmanımın cümlesine

Katlanacak yar isterim

Damarımda kan olmalı

Ruhumda bir can olmalı

Yüreğimde çağlamalı

Ben olacak yar isterim

Yatak yorgan düşsem bile

Mapuslara girsem bile

Görüş günü geldiğinde

Bakışacak yar isterim

Yusuf Ziya ne söylese

Aklın yolu birdir dese

Gözümde yaş bitmese de

Ağlayacak yar isterim', 'Haram değil hak görecek Tenimde bir zar isterim Beni benden çok sevecek Ben olacak yar isterim Gül yanında dikenine Sevdamızın dertlerine Dü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-olacak-yar-isterim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adıyamanlı', 'adiyamanli-mahmut-simsek-0h3dz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nemrutun dağları dumanlı

Ben sevdim seni al yazmalı

Deli dolu ve sıcak kanlı

Bir yar sevdim Adıyamanlı.

Gergerin zazaca var dili

Kahtanın,da barajı gölü

Benim yarim besninin gülü

Bir yar sevdim Adıyamanlı

Samsatın var sanatçıları 

Sincik,in tehlike yolları

Çelikhanın güzel kızları

Bir kız sevdim Adıyamanlı.

Gölbaşının güzeldir gölü

Adıyamanın yoktur çölü

Adıyamana has var dili

Güzel kokar etrafı gülü.

Gelom gidom babom der dili

Gardaş goncadır gönülleri

Misafiredir sevgileri

Yar sevdim Adıyamanın gülü.', 'Nemrutun dağları dumanlı Ben sevdim seni al yazmalı Deli dolu ve sıcak kanlı Bir yar sevdim Adıyamanlı. Gergerin zazaca var dili Kahtanın,da...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adiyamanli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkalaşım', 'baskalasim-ali-veli-uat63', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her görünenler yaşanılanlar

His karmaşaları çelişkiler

Arkasından gelen arayışlar istekler

Bitip tükenmek bilmeyen amaçlar arasında

Birden bir ses kendin ol kendini yaşa! ..

Gerisi boş bir kare

Doldurulmayı bekleyen

Yaşanılan eskiden farklı yenilikler getiren

İfade zorluğu alışılmamışlığın getirdiği

Ve yıkılan ilüzyon yıkılan çelişki

Sonsuz bir huzur araştırmayı gerektiren

Yaşadığım kendim duyduğum ses benim

Anlayamıyorum neden geciktiğimi evrim geçirdiğimi

Neden sonra anlıyorum her şeyi kendimin gerçekleştirdiğini

Yürürken uçmak istiyorum unutup herşeyi

Tümünden önemlisi seviyorum kendimi', 'Her görünenler yaşanılanlar His karmaşaları çelişkiler Arkasından gelen arayışlar istekler Bitip tükenmek bilmeyen amaçlar arasında Birden b...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/baskalasim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Musahipzade Celal', 'musahipzade-celal-mehmet-akif-tiryaki-a5wpk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O aslında bir derin yazardı,

Değişmekte olan Türk toplumunun olumsuz yönlerine kızardı

Bunları eleştiren tiyatro eserleri yazardı.

Babıali Tercüme Odası''nda çalışırken,

Bir yandan da Hukuk Mektebi''ne devam etti.

Daha sonra devlet memurluklarında işe girdi.

1923''de emekli oldu, Evkaf Müzesi''ne kuruldu.

Son dönemlerde''de İstanbul Şehir Tiyatrosu kitaplığını korudu

13 Şubat 1952''de kırkıncı sanat yılı jübilesi yapıldı,

Moliere piyesini incelemiş, sahne teknikleriyle ilgilenmiştir.

Bu dönemde Köprülüler, İstanbul Efendisi gibioyunlar yazdı

Cumhuriyetin ilk yıllarında oyunlarıyla ünü yaygınlaştı.

Aynaroz Kadısı daima hatırlandı.

Bir Kavuk Devrildi 1930-31''da Darulbedayi''de  sergilendi.

Onsekiz oyunu 1936''da toplu olarak yayımlandı.

Yapıtlarında güldürü ögesine yer verdi,

Batı tiyatrosu ile orta oyununu birleştirmeye çalıştı.

Eski İstanbul Yaşantısı adlı incelemesi 1946 da yayımlandı.

Türk tiyatrosundan tam not aldı.

Hadi alkış....', 'O aslında bir derin yazardı, Değişmekte olan Türk toplumunun olumsuz yönlerine kızardı Bunları eleştiren tiyatro eserleri yazardı. Babıali T...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/musahipzade-celal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aile olmak', 'aile-olmak-muhsin-yener-dt7ar', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aile olmak;

konuşurken

kelimeleri sıralama telaşına düşmemek…

bir şeyler anlatma gayretinin

yorucu kalabalığına girmemek…

Aile olmak;

gözlerinden anlamaktır insanı,

susuşundan,

bir cümleye sığmayan yorgunluğundan…

Ses tonunun

hangi akşamdan kaldığını bilmek,

“iyiyim” dediğinde

hangi acıyı sakladığını sezmek…

Bir bakışın

bir kitabı kapatması gibi

bütün hikâyeyi kapatmasıdır bazen…

Aile olmak;

kelimelerden önce gelen bir anlayış,

cümlelerden daha eski bir sevgi…

“Ne demek istedi?” diye sormadan

ne hissettiğini bilmek…

ve çoğu zaman

senin kendinden bile önce

seni düşünmektir insanın…

Beni

benden fazla düşünüyorlar

düşünüyorum…

Muhsin yener', 'Aile olmak; konuşurken kelimeleri sıralama telaşına düşmemek… bir şeyler anlatma gayretinin yorucu kalabalığına girmemek… Aile olmak; gözler...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener']::text[], 8.5, '{"poet":"Muhsin Yener","poet_slug":"muhsin-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sev-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpeyim', 'opeyim-belgin-turan-ofgat', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O ellere uzanan, dudakları öpeyim,

Yol kat edip de gelen, ayakları öpeyim,

Seni dilemek için, mabede yüz süreyim,

Utanınca kızaran, yanakları öpeyim.

Belgin Turan               19.12.2005', 'O ellere uzanan, dudakları öpeyim, Yol kat edip de gelen, ayakları öpeyim, Seni dilemek için, mabede yüz süreyim, Utanınca kızaran, yanaklar...', ARRAY['Türk Edebiyatı','Şiir','Belgin Turan']::text[], 8.5, '{"poet":"Belgin Turan","poet_slug":"belgin-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/opeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski resim', 'eski-resim-ali-veli-vhsop', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Lüle saçlarının çevrelediği

O güzel yüz

Resmin cansızlığını inkar edercesine

Merakla bakan gözler

Derinliğe indikçe değişiveriyor

Yazgıma boyun eğmeliyim

Çabalamak boş

Elime tutuşturulan senaryo

Kuralına göre oynamalıyım

Farklı bakan iki gözü

Biri umutlarını gençliğini haykırırken

Diğeri sessizce boyun eğiyor

Anlayamıyorum bir türlü

Hayatı zorunluluklarla dolu

Kendini ifade edemeden

Sürüklenircesine yaşamayı

Eski resimdeki güzel kız

Dolu yaşamayı haketmiştin

Güzel günler görmeyi

İçinde yaşattığın o güzel sevgiyi

İnsanlığa saçmayı haketmiştin sen

Başarılı olmayı yetişmeyi

Başkalarına verebilmeyi öğrenmeyi

Mutlu yaşamayı haketmiştin

Eşini tüm benliğiyle sevebilmeyi

Canından kopan en güzel varlıkları

Geleceğin umutçularını çocuklarını

Sıkıntısız sorunsuz yetiştirmeyi

Güzel bir gelecek hazırlamayı

En doğal biçimde haketmiştin güzel kız

Başına gelecekleri bilmeden

Düşlemlerin,hayallerin,umutlarınla haketmiştin sen

Resimdeki kız bilemezdin gerçeği

Gelecekteki yazgını

Olgunlaşmak için sıkıntı çektin

Bolluktan mahrum kaldın sen

İstemediğin kötü günler yaşadın

Umutlarını neşeni içinde yaşattın

Sevgi özünden kopmadın sen

Bilemezdin bunları resimdeki güzel kız 

Öğrensende inanmazdın

Farklı şeyler dilemiştin hayattan

Geleceğine hazırlık yapmıştı

Her insan gibi bu güzel kız da

Toplumun çarkında istemeden

Hazırlanılan yerini aldı yakınsada

Yaşadıklarınla olgunlaştın sen

Farkına vardın yapmacıklığın

Görebildin insanın niteliğini

Yüce tanrının istediğini

Öğreti yaptın öğrendiklerini

Verebilmek istedin insanlara

Bakın görün dedin insanlığa

Değişebilirlik kanunlarını açıklayarak

Yaradılıştaki özün çelişki olduğunu 

Uzun süren zaman sonunda öğrendin

Gerçeği görebilmenin basitliğini kavradın

Acı ve öfke dolu bir çığlık attın

Sonrada hayret ve pişmanlik duyarak

Gizliliğin olmadığını

Her şeyin farkedilmek için varolduğunu

Yazgıların kendimizce yaratıldığını

Uzunca bir zamanda yakaladın sen

Sonsuz sabırla buldukça aradın

Bildin ve verdin güzel kız

Sevginin özünde olduğunu bilmeden

Şimdide sevgiyi arıyorsun sen

Seviyorum seni insanca yaşadığın için...', 'Lüle saçlarının çevrelediği O güzel yüz Resmin cansızlığını inkar edercesine Merakla bakan gözler Derinliğe indikçe değişiveriyor Yazgıma bo...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/eski-resim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etkileşim', 'etkilesim-ali-veli-xmc8w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duyumlarla kendini gösteren sevgi

Düşüncenin sinir sistemi

Etkinliği davranışlarla belirtmesi

Yaşamın biçimini etkileşimin biçimlendirmesi

Etkilendiğimizi mi sanıyoruz

Yoksa kendimizi mi eleştirdiğimizi

Gerçek olan biziz objeler değil

Kendimiz aramaktır etki

Etkilenmeyi bilmeli

Kendini yetiştirmeli

Düşünmeyi düşünmeli

Etkinin sonucunu tepki değil 

Düşüncenin davranışlarla kendini 

Gösterdiğini bilmeli

Gerçek olan

Kendini yaşamalı kendini bilmeli', 'Duyumlarla kendini gösteren sevgi Düşüncenin sinir sistemi Etkinliği davranışlarla belirtmesi Yaşamın biçimini etkileşimin biçimlendirmesi E...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/etkilesim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen seçtin ben aldım Dursun Elmas''ın Yurttan Haberler şiirine ithafen', 'sen-sectin-ben-aldim-dursun-elmas-in-yurttan-haberler-siirine-ithafen-mikdat-bal-h9op6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '....................................................', '.......................................................', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/sen-sectin-ben-aldim-dursun-elmas-in-yurttan-haberler-siirine-ithafen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Olmadı Olmuyor', 'sensiz-olmadi-olmuyor-mustafa-dogan-elazig-1wfhj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SENSİZ OLMADI OLMUYOR

Sana koşmak istiyorum kader koymuyor,

Seni göremezsem gönlüm teselli olmuyor,

Sarılıp öpemezsem kalbim o an  duruyor,

Bu gönlüm sensiz yaşamıyor inan ölüyor.

Hasretinle mi  geçecek bu kısacık ömrüm,

Sana kavuşmak ümidi benim tek tesellim,

Ne kadar hüzün var hepsi kalbime doldu,

Sensiz, ne huzuru ne de mutluğu buldum.', 'SENSİZ OLMADI OLMUYOR Sana koşmak istiyorum kader koymuyor, Seni göremezsem gönlüm teselli olmuyor, Sarılıp öpemezsem kalbim o an  duruyor, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Elazığ']::text[], 8.5, '{"poet":"Mustafa Doğan Elazığ","poet_slug":"mustafa-dogan-elazig","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sensiz-olmadi-olmuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece uyanık kaldım', 'gece-uyanik-kaldim-ali-veli-74n8e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gece vakti bulutlar

Beyaz bembeyaz ve gece koyu

Tül perdenin pencereye vuran aksi

Küme küme yıldızlar

Saksıdaki toprak gibi

Aslı birkaç...

Seyrediyor çiçekler geceyi

Ve ben yoğunlaşıyorum yalnızlığımda

İnatlaşıyor gündüzle

Hüküm sürüyor sessizlik

Biçimleniyor yalnızlık

Değişiveriyor

Kaygıya bırakıyor yerini

Büyü bozuluveriyor birden

Gündüz korkusu toplumsal çark

Ürkütüveriyor beni

Birkaç saat sonra düzen mekanizması

Kopmak istemiyorum geceden

An da donmak ve orada kalmak

Masallaşıveriyor istek

Bitiveriyor yapay saydığım doğal

Aydınlık

Yaşam savaşı

Yapay,doğal...', 'Bir gece vakti bulutlar Beyaz bembeyaz ve gece koyu Tül perdenin pencereye vuran aksi Küme küme yıldızlar Saksıdaki toprak gibi Aslı birkaç....', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gece-uyanik-kaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yoktun sultanım', 'sen-yoktun-sultanim-bahtiyar-tas-jo9o1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nuhun çaresizliğini anlatıyorum sizlere saygılarımla  yaradanın aşkı', 'Nuhun çaresizliğini anlatıyorum sizlere saygılarımla  yaradanın aşkı...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Taş']::text[], 8.5, '{"poet":"Bahtiyar Taş","poet_slug":"bahtiyar-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/sen-yoktun-sultanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adıyaman', 'adiyaman-mahmut-simsek-u58zt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ulu baba dağından gelir gürlevik suyu

Gönülleri sıcaktır yaşlısı,genci,toyu

Yirmi sekiz uygarlıktan almış bu duyguyu

Güzeldir Adıyamanımın bu kibar huyu

Adıyamanın göbeğinde vardır kalesi

Su doludur memleketimin çepe çevresi

Yeşil bağı bahçesi gelir bülbülün sesi

Sanatçıları var ilimin halkın neşesi.

Ta eski çağdan kalma pirin mağaraları

Tarih kokar çağ kokar adıyaman toprağı

Çeşit çeşit yemek yapar mis kokar mutfağı

Dumanlıdır Adıyamanın toroslar dağı

Mahmut ensari yatar yüksektir ali dağı

Engindir abuzer gaffarinin gönül bağı

Zeynal abidindir en genç ermiş yoktur yarı

Adıyaman korunur ermişlerin diyarı.

Adıyamanın petroldur bahçesi ve bağı

Karşılar yurdumun yakıtının yarısını

Ülkemin oksijenidir görsen havasını

Mis kokar cennet kokar görsen Adıyamanı.', 'Ulu baba dağından gelir gürlevik suyu Gönülleri sıcaktır yaşlısı,genci,toyu Yirmi sekiz uygarlıktan almış bu duyguyu Güzeldir Adıyamanımın b...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adiyaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufukta Gözlerim', 'ufukta-gozlerim-mustafa-dogan-elazig-pu6qg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'UFUKTA  GÖZLERİM

-

Gönlümün kan rengi tepelerinde çılgınca koşan,

Bembeyaz bir kısrak gibi şahlanır bu sevdam, 

Heyecanım coşar,çıldırır aşkına deli gönlümde,

Gözlerine kapıldım, alıp götüren beni kendine,

Tutunamam sensiz hayata,yaşamaz boğulurum.

-

Bahar gibi geldin, buzdan soğuk dünyama sen,

Renk renk çiçek çiçek açtın, gönlümdesin sen,

Varlığın güneşim, uzak da olsan da ısıttın sen,

Doyamam endamına hayalinle avunuyorum ben.

-

Çıkıp gelişine, öyle muhtaç ki bu yaralı kalbim,

Çekip o gidişinle açtığın yaralara bak hala yeni,

Ufukta yorgun gözlerle yılarca gelişin bekledim,

Ne zaman döneceksin diye hep umutla bekledi.

-

Anlatamadı tesellilerim bana senin dönmeyişini,

Alışamadı gözlerim,bir an bile seni göremeyişe

Sevda yollarımda neden bu çalılar bu dikenler,

Aşkı aşk yapan yoksa beni yakan bu hasratmi,

Vuslatımız dünyada değilde yoksa mahşerdemi.', 'UFUKTA  GÖZLERİM - Gönlümün kan rengi tepelerinde çılgınca koşan, Bembeyaz bir kısrak gibi şahlanır bu sevdam,  Heyecanım coşar,çıldırır aşk...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Elazığ']::text[], 8.5, '{"poet":"Mustafa Doğan Elazığ","poet_slug":"mustafa-dogan-elazig","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ufukta-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Bende Bileyim', 'soyle-bende-bileyim-mustafa-dogan-elazig-dlgg1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SÖYLE BENDE BİLEYİM

  

    Uzaklara dalar intizar eder seni gözlerim, 

    Bulamam o kavuşmanın yolunu seni ararım, 

    Mecnuna Kereme ben bu derdimi yanarım,

    Her yerde seni görme,seraplarını yaşarım.

     -

    Ah bilsem bulsam izini, durmam koşarım,  

    Dağlar ayrılık olsa, deniz hasret aşarım,

    Kalbini açmasan bana işte o an nederim,

    Kalbinde ki o zinciri sensiz nasıl kırarım.

    -

    Sensiz ağlar kalbim, bir daha da gülemem,

    Senden aşk dilenmek,oldu mesleğim benim,

    Seviyorsan beni hala niçin geri dönmezsin,

    Aşkın yoksa yalanmıydı bana söylermisin. 

    Ah bilsem bulsam izini, durmam koşarım,  

    Dağlar ayrılık olsa, deniz hasret aşarım,

    Kalbini açmasan bana işte o an nederim,

    Kalbinde ki o zinciri sensiz nasıl kırarım.

    -

    Sensiz ağlar kalbim, bir daha da gülemem,

    Senden aşk dilenmek,oldu mesleğim benim,

    Seviyorsan beni hala niçin geri dönmezsin,

    Aşkın yoksa yalanmıydı bana söylermisin.', 'SÖYLE BENDE BİLEYİM        Uzaklara dalar intizar eder seni gözlerim,      Bulamam o kavuşmanın yolunu seni ararım,      Mecnuna Kereme ben ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Elazığ']::text[], 8.5, '{"poet":"Mustafa Doğan Elazığ","poet_slug":"mustafa-dogan-elazig","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/soyle-bende-bileyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel nefesinle', 'gel-nefesinle-ali-veli-dehtd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buruk bir dalgalanma esnasındaydı hayat

Ardımdan gelen kanat sesleri bir bildiğim

Yeniden duyulan sancıların içimde yarattığı ürpertiler

Doğum vaktidir artık mavi küre turunu tamamlamış

Bir İstanbul tamlaması benim yaşım

Gel nefesinle...

Değişimler tüketmesin özünü gel...

Bilmediğim tüm ihtimalleri toplada gel kalmasın

Beklemekten değil meraktan benimkisi

Dağıt yüreğimdeki ışık pervanelerini sen kal

Ay aydınlığı sessizliğini bozda gel...

Bozkır yalnızlığım sonsuz sandığım yürüyüşlerim

Çelişkilerim hepsi içimden dışa doğru

Tüm bunları bil bilde gel...

Doğumumu paylaş doğmak için

Gel...

Nerdesin', 'Buruk bir dalgalanma esnasındaydı hayat Ardımdan gelen kanat sesleri bir bildiğim Yeniden duyulan sancıların içimde yarattığı ürpertiler Doğ...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gel-nefesinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli sokak', 'gizli-sokak-ali-veli-o0wd5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tüm gel-gitlerin hikayesindeydi sokak

Sokak hikayelerin sancısında

Yaşam sancıların sanrısında

Ve bir hepti bencil senaryosunda

Senaryolar bir yöne doğru

Doğrular dışa doğru isyankarlığında

Ben varoluşuna düşman yadsımış

Bir sokak aynı yöne doğru çıkmazlarında

Bir nev yalnızlığı çoğulun

Ve her bir ben yalnızlığında...

Bir sokak çoğula inkar', 'Tüm gel-gitlerin hikayesindeydi sokak Sokak hikayelerin sancısında Yaşam sancıların sanrısında Ve bir hepti bencil senaryosunda Senaryolar b...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gizli-sokak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnan Sana Gelemem', 'i-nan-sana-gelemem-yusuf-onder-bahceci-nq90j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni sevdim be güzelim,

Başka güzel göremem,

Seni rüyamda gördüm,

Saçlarını öremem.

Bana gelsen diyordun,

Beni sevsen diyordun,

Ama yine gidiyordun,

İnan sana gelemem.

Güzel gözler ağlıyormu,

Onu sevdim biliyormu,

Bana gelsin diyormu,

İnan sana gelemem.

Sevdinmi sen bilemedim,

Derdim derin bilemedin,

Birgün yüzüme gülmedin,

İnan sana gelemem...', 'Seni sevdim be güzelim, Başka güzel göremem, Seni rüyamda gördüm, Saçlarını öremem. Bana gelsen diyordun, Beni sevsen diyordun, Ama yine gid...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/inan-sana-gelemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinin çok güzel olduğu...', 'gozlerinin-cok-guzel-oldugu-ali-veli-x4nfw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suçuyla pekişmiş ölümcül hastalık

Kemiriveriyor gençliğini

Çaresizliğe kalmış yaşam böceği

Kuruyan bir çiçek gibi

Eriyen güzelliği bir tükeniş mi

Varlığı haykırıyor nedir çelişki

Hatırlayabildiğim

Gözlerinin çok güzel olduğu...

Seviniyor suça karşı tükenişi

Bir son bir başlangıç ikilemi

Çektiği suçun cezası

Aldığı tanrısal cezanın katkısı

Kuruyup gidiyor sömürülmüş insanoğlu

Yanında alıp götürüyor sevgiyi

Varoluş nedenini yaşama sevincini

Gözlerinde yaşatırdı

Durgunca sessizce hüznünü

Kuruyordu...

Güneşli sicak bir günün

Öğleden sonrasında

Yaşam sevinci yanılsaması

Geçirerek öldü...

Hatırlayabildiğim

Gözlerinin çok güzel olduğu...

(kendini bilmeden azap çekerek öldü)', 'Suçuyla pekişmiş ölümcül hastalık Kemiriveriyor gençliğini Çaresizliğe kalmış yaşam böceği Kuruyan bir çiçek gibi Eriyen güzelliği bir tüken...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gozlerinin-cok-guzel-oldugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresi Yok Ayrılığın', 'caresi-yok-ayriligin-yusuf-onder-bahceci-k5lvs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak yine akşam oldu,

Bak yine hüzün doldu,

Bütün güllerim soldu,

Çaresi yok ayrılığın.

Bak yine aramadı,

Hâl hatırın sormadı,

Belki kafa yormadı,

Çaresi yok ayrılığın.

Bak yine ağlıyorum,

Sararıpta soluyorum,

Sevdiğimi arıyorum,

Çaresi yok ayrılığın.

Bak yine yollardayım,

Seni nereden bulayım,

Gizli gizli ağlayayım,

Çaresi yok ayrılığın....', 'Bak yine akşam oldu, Bak yine hüzün doldu, Bütün güllerim soldu, Çaresi yok ayrılığın. Bak yine aramadı, Hâl hatırın sormadı, Belki kafa yor...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/caresi-yok-ayriligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnci gerdanlık', 'i-nci-gerdanlik-ali-veli-3tg2t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Işıklar renk renk ışıklar

Yeşil sarı kırmızı...

Büyük ışığın denizdeki aksi

En dipteki yapayalnız düşünce

Ve içimdeki karamsarlık

Yaşadıklarım...

Yaşanılası anılarım

Hafif bir sis dalga sesleri

Ya da ürperten soğuk rüzgar

Arkasından sabırsızca gelen

Kavramlar dünyası

Ve çelişkiler çelişkiler...

Yaşadıklarım...

Yaşanılası anılarım

Yıkılan düşüncelerdeki hüzün

Sevdiklerini yitirme endişesi

Defalarca yenilenen güzel ütopyam

Katı ve gerçekçi mantık yıkımı

Düşlerin hazin sonu

Yaşadıklarım...

Yaşanılası anılarım

Tekrar ve tekrar

Yaşanılacak anılarım

Ümitle! ..

*Değirmendere,sahil,denize vuran Tüpraş''ın ışıkları,deprem öncesi ve sonrası sessizliği,yıkılan umutlar,yinelenen ümitler...', 'Işıklar renk renk ışıklar Yeşil sarı kırmızı... Büyük ışığın denizdeki aksi En dipteki yapayalnız düşünce Ve içimdeki karamsarlık Yaşadıklar...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/inci-gerdanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan oldukça şiddet', 'i-nsan-oldukca-siddet-ali-veli-unc1u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben şiddetim

Sükunet ararım

Boşlukları arayıp doldurmak isterim

Gücüm yıkıcıdır yapıcılıkta kaçarım

Ben şiddetim

Kuvvet kardeşim

Doğayı bozarım insanlara kıyarım

Somut emekleri çözerim düzenliliğe karşıyım

Ben şiddetim

Hem soyut hem somutum

Beyinde oluşan bir bilinmeyenim ben

Olumsuzluklar yaratmak isterim

Ben şiddetim

Birlikteliği bozarım

Temiz düşünce olmadıkça gelişirim

Başka düşman tanımam yokluğuda

Ben varım

Ben şiddetim

İnsan varoldukça...', 'Ben şiddetim Sükunet ararım Boşlukları arayıp doldurmak isterim Gücüm yıkıcıdır yapıcılıkta kaçarım Ben şiddetim Kuvvet kardeşim Doğayı boza...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/insan-oldukca-siddet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman/Şehrin Şiiri', 'zaman-sehrin-siiri-ali-gencay-t064w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kızılca gün batıyor ufuktan

İstanbul kederli

Üsküdar da yangın

Beyoğlu’nda ince saz, keman sesleri

Tadı yok sazın, faslın

Çalınmış şarkıların güftesi

Daracık sokaklar

Işıklı/loş/kasvetli

Karanlıkta herkes sana benziyor

Kadınlar kıvrak/beyaz tenli

Kulaklarımı dövüyor yüksek ökçelerin

Cümbüşü bastıran sesi

Edalı/işveli/cilveli

Kıvrık perdesinden bakor madam

Yitirdiği yıllar, endişeli/kederli 

Karaca Ahmet’te uzun/serin serviler

Zamanı geldi artık

Uzanıp altına, konstantini dinlemeli

Çanlar çalıyor Rumeli’de

Sultan Ahmet’te ezan sesi

Eriyip kayboluyor ruhum

Yedi tepenin orta yerinde

Loti de kaldırıp kollarımı

İstanbul oluyorum 

Her nefes çekişimde', 'Kızılca gün batıyor ufuktan İstanbul kederli Üsküdar da yangın Beyoğlu’nda ince saz, keman sesleri Tadı yok sazın, faslın Çalınmış şarkıları...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zaman-sehrin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onların Haberi Varmıdır Ahiretten?', 'onlarin-haberi-varmidir-ahiretten-hasan-can-segkx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bulutun haberi varmıdır acaba,

Yağmuru onun yağdırdığından.

Denizin balıklardan,

Yada kıyıların dalgalardan.

Dünün haberi varmıdır bugünden,

Zamanın saatlerden...

Ayların haberi varmıdır günlerden,

Yılların ömür götürdüğünden.

Ağacın haberi varmıdır meyvesinden,

Yaprakların rüzgardan...

Toprağın böceklerden,

Yada gecenin karanlıktan.

Sokakların haberi varmıdır insanlardan,

Bıçağın, silahın bir canı almasından,

Gözlerin birgün görmeyeceğinden,

Yalancı sözlerin dudaklardan...

İnsanın insandan haberi varmıdır,

Yoksa nasıl yaşıyor bedenler,

Varsa neden yalnızlar,

Yada neden çaresizler...

Bütün bu soruların cevabı var,

Dünya üzerinde ki varlıkların,

Hepsinin birbirinden haberi var.

Peki onların ahiretten haberi varmıdır?', 'Bulutun haberi varmıdır acaba, Yağmuru onun yağdırdığından. Denizin balıklardan, Yada kıyıların dalgalardan. Dünün haberi varmıdır bugünden,...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/onlarin-haberi-varmidir-ahiretten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Ben', 'simdi-ben-derya-aslan-q3p1j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Teninde eller 

Gözlerinde bakışlar

Dolaşırken 

Zannetmeki ben bihaber

Sen benden bihaber

Güzel kadın

Güzel kadınımdın 

Yüreğimden aktım masum tenine

Yabancı ten

istemedim teninde

Gelir zaman 

Geçer zaman

Gider bu eda

Bu güzellik gider

Beni benden alan

Seni serden çalan

O hilal kaş

O ceylan bakış

O göz,işve o naz

Gider sana hesap vermeden

Senin hesapsız gidişlerin gibi

Yüreğimi ateşlere atışların gibi

Çığ kopan kar,

sel olup taşan su gibi

Zaman gibi gider

Bir ırmaktı aşkım sana akan

Bir ırmaktı yüreğim

Akmak taşmak için yatağını arayan

Dicle’den kopan

İsimsiz ülkelerden sürülen

Yitik kentlerden hüzün alan

Irmaktı yüreğim akmak için

Yatağını arayan

Kaynağım yay gibi kaşların

Kıvrılıp göğsüne doğru yol alan

Sen kurak topraklar

Yıkık umutlarla karşıladın beni

Hesapsızdım 

Nasılki zamana sormadım 

Sanada hesapsız kaldım

Sormadım gitmelerinin hesabını

Yüreğimden akan acı suların selinde

Ben çırpındım yalnızdım

Oysaki yüreğim bir deli taydı

Koşup sarmak isteyen seni

Mor dağ eteklerinin esintisi 

Yelelerimi okşardı

Şimdi ben 

Yalnızlığın yaban gülleri avuçlarımda

Yüreğm ve ben çıktık en yükseğine

En güzel köşesine Nemruda

Tanrılar karşıladı beni el pençe

Çünkü hesapsızdım 

Günahsızdım yoktu yer aldanışa

Ve çünkü

Avuç açmadım hiçbir aşka…', 'Teninde eller  Gözlerinde bakışlar Dolaşırken  Zannetmeki ben bihaber Sen benden bihaber Güzel kadın Güzel kadınımdın  Yüreğimden aktım masu...', ARRAY['Türk Edebiyatı','Şiir','Derya Aslan']::text[], 8.5, '{"poet":"Derya Aslan","poet_slug":"derya-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/simdi-ben-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölene kadar!', 'olene-kadar-veysel-alkan-bddnt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acılara gark eyle,ömrümü bitir.

Anamdan emdiğimi,burnumdan getir.

Bıktır canımdan beni,''İLLALLAH! '' ettir.

Ben senden vazgeçemem,ölene kadar! 

Çekeyim hep elinden,''EL İNSAF! '' demem.

Yaptıklarına kızıp,sana kin gütmem.

Çilenle daralıp da,hiç isyan  etmem.

 Ben senden vazgeçemem,ölene kadar! 

Şu beynimi çenenle,ye çatır çatır.

İstersen falakaya,her gece yatır.

Rezil rüsva olayım,adımı batır.

Ben senden vazgeçemem,ölene kadar! 

İyi bil! şu yüreğim, tek sana talip.

Sen hep önde giden ol,ederim takip.

Ben kaybeden olayım; sen ol, hep galip.

Ben senden vazgeçemem,ölene kadar!', 'Acılara gark eyle,ömrümü bitir. Anamdan emdiğimi,burnumdan getir. Bıktır canımdan beni,''İLLALLAH! '' ettir. Ben senden vazgeçemem,ölene kadar...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olene-kadar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar Yüzünde Yüzümü Gösterir', 'aynalar-yuzunde-yuzumu-gosterir-turan-tuncer-jnvml', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'AYNALAR YÜZÜNDE YÜZÜMÜ GÖSTERİR

Şiirle yaşadı ise ruh

Bunca yeknesak acıyı

Acısız yanışlara

Şairler şiirle veda eder

Bu gün kavga 

Bu gün cenk 

Bu gün omuz verme günüdür

Kalemin,

Kılıcından keskin olmalı

Duruşun bakışın

Yeminin olmalı

Varsan yaşıyorsan! 

İnsanım diyorsan 

Ve; 

Nefes alıyorsan,

Hakkını vermelisin,

Bastığın toprağın.....

Adın bir 

Bedenin bir

Varlığın pir olmalı.

Dar ağaçlarında gözün açık

Ellerin serbest olmalı

Ölürken bile 

Korkmalı hayın senden

Kabe''n, Kıble''n yüz dönmemeli sana

Utanmamalı bastığın topraklar 

İçtiğin sular utanmamalı

Secde ettiğin seccaden 

Kıldan örüldü ama

Kıl olmadı senin kadar

Varlığı apse olmadı 

Neşter vurulası

Kainat sevdi yaradılanı

Yaradan''dan ötürü

Senin bu kinin neden? 

25 Ocak 2006/İst

Alkadraz_Kuşcusu', 'AYNALAR YÜZÜNDE YÜZÜMÜ GÖSTERİR Şiirle yaşadı ise ruh Bunca yeknesak acıyı Acısız yanışlara Şairler şiirle veda eder Bu gün kavga  Bu gün ce...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/aynalar-yuzunde-yuzumu-gosterir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku Senin İçinde', 'korku-senin-i-cinde-turan-tuncer-gc3nd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KORKU SENİN İÇİNDE

Kalemin göz yaşı-

Ağrılığın şiir''dir.

Dile gelirde

Beyaz ova da, (yazı da) 

Evren ahengini yitirir-

Yılkı''ların nal seslerinde,

Engin olur,.

Set kuramazsın acılarına-

Kan olup! 

Akar damla damla, 

Yüreğinin yangını, 

Dile gelir a-b-c''lerinde...

Kalemin kağıda kırıldığı yerde

Kalbin kırıklığı konuşulmaz.

Bütün duygularım kırık,

Yazılarım hayatın bitkisel''inde

Yaşadığıma dair ne varsa.

Ben  aşk yıkımları yaşadım! 

Ama sen! 

Fay hattındasın 

İçinde korkularla.....

26 Ocak 2006/İst

Alkadraz_Kuşcusu', 'KORKU SENİN İÇİNDE Kalemin göz yaşı- Ağrılığın şiir''dir. Dile gelirde Beyaz ova da, (yazı da)  Evren ahengini yitirir- Yılkı''ların nal sesle...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/korku-senin-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giden Gençliğim', 'giden-gencligim-timur-i-likan-snhol', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gençliğimin artık son demindeyim

Usulca gidiyor gençliğim elden

Târifi olmayan kederlerdeyim

Alın yazımmış ne gelir ki elden

Günyüzü görmedi şu bahtsız gönlüm

Sevdâlı bakan bir çift göze hasret

Istırapla geçip gitti bu ömrüm

Dağ yüküyle çektim bin türlü zahmet

Hiç şansım olmadı sevdâdan yana

Kurumuş bir yaprak gibi savruldum

Aşkın ateşiyle ben yana yana 

Çöldeki bir yolcu gibi kavruldum

Zaman ellerimden uçup da gitti

Uzak diyârlara göçen kuşlarla

Sabrım da kalmadı tükenip bitti 

Ömrüm çevrelendi dik yokuşlarla

Giden gençliğim gitti gidiyor

Geri gelmeyecek bir daha aslâ

Üç günlük dünyâ bu bitti bitiyor

Sırtını Cenâb-ı Hâkk''a hep yasla

(26 Ocak 2006/ İstanbul)', 'Gençliğimin artık son demindeyim Usulca gidiyor gençliğim elden Târifi olmayan kederlerdeyim Alın yazımmış ne gelir ki elden Günyüzü görmedi...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/giden-gencligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulur Bütün Güzellikler', 'unutulur-butun-guzellikler-turan-tuncer-dbodc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'UNUTULUR BÜTÜN GÜZELLİKLER

Geriye dönp baktığım da

Düşündüğüm de, 

Unutulmuş gençliğimi

İlk olarak, 

Kötü bir anı gelir aklıma.

Öncelikle! 

Seni ne zaman,

Ya da ne kadar, 

Sevdiğimden önce.

Ayrıldığımız gün gibi..

Hani! 

Bırakıp gittiğin 

Gün yağmurlu.

En son,

Şehrin ışıkları gelir aklıma.

Ya da unutmuşumdur,

Sokakların yakamozlarını

O tepeden son baktığım güne ait.

Öncelik! 

Hep içime çöken karanlığın olurda

Çeker beni içine

Gözlerinin karası.

Önce hatırlayabilseydim,

Yağmur bulutlarından.

Belki! 

Tüm umutsuzluğuma  rağmen 

Gözlerinin 

İçimi ısıttığını 

Unutmadığım gibi...

02-01-2006/İst

Alkadraz_Kuşcusu', 'UNUTULUR BÜTÜN GÜZELLİKLER Geriye dönp baktığım da Düşündüğüm de,  Unutulmuş gençliğimi İlk olarak,  Kötü bir anı gelir aklıma. Öncelikle!  ...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/unutulur-butun-guzellikler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Sesleniyorum', 'sana-sesleniyorum-i-brahim-baykal-6tr7k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgili eşim,

Can yoldaşım, dert ortağım, sırdaşım,

Ne anam tutar yerini,ne babam, ne bacım ne gardaşım,

Çektin gittin ansızın, sen rahat biz perişan,

Senin arkanda biz varız,bize yok ki ağlayan.

''Zaman en iyi ilaçtır '' demiş atalarımız.

Kime? Hangi derde? 

Gün geçtikçe büyüyor acımız,

Hani? Derman nerde? 

Bir hafta ayrı kalsam sizlerden,

Derdin ki! '' Çocukların seni özlüyor,

Nasıl ödeyeceksin onların günahını ''

Ya şimdi? 

Dilleri bile varmıyor adını anmaya,

Sıra sende ver hesabını. 

Hadi yine affettim.

Sende istemezdin böyle olmasını.

Elinde değil, biliyorum.

Alan düşünsün orasını.

                       Aralık 2000 - İbrahim Baykal', 'Sevgili eşim, Can yoldaşım, dert ortağım, sırdaşım, Ne anam tutar yerini,ne babam, ne bacım ne gardaşım, Çektin gittin ansızın, sen rahat bi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Baykal']::text[], 8.5, '{"poet":"İbrahim Baykal","poet_slug":"i-brahim-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-sesleniyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümitçi', 'umitci-bekir-mutlu-gokcesu-ppcd6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üşümüş simitleri tablasında

Düşlerinin alazı vurmuş yanaklarına

Bir, ki, üç... kaç satacak satsa satsa

Yatakta olmak vardı şu sabah ayazında...

Kar var, zor var, işler de kesat anasını satayım ama

Serde gençlik, tablada simit var, ümit çok hala...', 'Üşümüş simitleri tablasında Düşlerinin alazı vurmuş yanaklarına Bir, ki, üç... kaç satacak satsa satsa Yatakta olmak vardı şu sabah ayazında...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/umitci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsandaki tarih ve sevgi çelişkisi', 'i-nsandaki-tarih-ve-sevgi-celiskisi-ali-veli-cskw7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tarih tekerrürden ibaretse eğer

Sevgide bir tarihtir düşünselde

Acılar hatalar yıkımlar tarihte

Göreceli değerler sevgide

İki zıtlık yaratırcasına

Bir tarafta sevgi diğerinde tarih

Saçma sayılmasın ikisi

Aynı şiirde biçimlendirilmesi

İkisininde gerçek sahibi

Bildiğimiz doğa nimeti

Birisinde ezilmiş diğerinde yücelmiş

İki tanımı kendi türetmiş

Acemi bir sanatçı hali tarih

Ustaca yeteneği sevgi

Birer insandık biz

Daha bir çok tanımlar yaratan

Birşeylerle uğraşmak istercesine

Birer haşarı çocuk gibi

Yapılandırıvermişiz çelişkilerimizi

İsimlendirmeyi unutmamışız tarih

Devam ettirmişiz hep aynı olan değişkenliğimizi

İhmal etmişiz gizli isteği sevgiyi

Birbirimizi sevmiyoruz kestirmecesi

Karar vermeliyiz istenileni

İkilemdeki gerçeği görmeli

Hatalardan aldığımız dersi

Yüceltmeli sevgiyi...', 'Tarih tekerrürden ibaretse eğer Sevgide bir tarihtir düşünselde Acılar hatalar yıkımlar tarihte Göreceli değerler sevgide İki zıtlık yaratır...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/insandaki-tarih-ve-sevgi-celiskisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Böyle Doğmuştu', 'o-boyle-dogmustu-turan-tuncer-efxmw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O  BÖYLE   DOĞMUŞTU

Karanlıkta kalmıştı, 

Aldığı nefeslerin- 

Bir yarısı.

Belirsizliğin utancı, 

Yalnızlık vardı-

Titrek ışıkların, 

Gölgelediği yüzünde.

Bir nefes öncesine kadar- 

Baba dediği,

Elini öptüğü bayramlarda,

Yabancılaşmıştı-

Başka biri olmuştu,

Sıradan, her hangi biri.

Öfke! 

Beyninin düşünen yanını- 

Muhasara etmişti,

İçindeki kaleleri düşmüştü,

Tek tek..

Güveni kalmamıştı kimseye

Öyle ya, 

Ana''sı kandırmıştı- 

Yıllarca o küçük yüreğini.

Kimliksiz çıkmıştı

Aynada gördüğü 

O delikanlı yüzü karşısına.

Şimdi intikam zamanıydı

Kinini kusmalıydı

Paylaşmalı 

Ortak etmeliydi 

Birilerini kendi çamuruna.

Debelendi,

Debelendi,

Kasıldı, hırladı hiddetle,

Neden sonra aklına geldi-

Baktı 

Etrafında kimse yoktu,

Savurduğu çamurlar- 

Kendi bedenini örtmüştü.

Pişmanlığı yaşaması gerekenin,

Kendisi olmadığını düşündü

Silkindi,

Ama çok geçti-

Kimseler karanlığa kalmamıştı.

Aydınlıkta, 

Sadece izlerini gördü

Bir zamanlar 

Yanında yol alan kişilerin...

28-12-2005/İst

Alkadraz_Kuşcusu', 'O  BÖYLE   DOĞMUŞTU Karanlıkta kalmıştı,  Aldığı nefeslerin-  Bir yarısı. Belirsizliğin utancı,  Yalnızlık vardı- Titrek ışıkların,  Gölgele...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/o-boyle-dogmustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konarım Gözlerine', 'konarim-gozlerine-turan-tuncer-5k660', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KONARIM GÖZLERİNE

Gülüşlerinde

O

Şubat soğuğu 

                       Hiç olmayacak

Seni 

Yakamozlu ağustos gecelerine saklıyorum

senin sessizliğinde bile

Ben

Binlerce satır okurum

                              Gözlerinin yeşilinde

Hepsi aşk üstüne

Hepsi sevmeler

Beni 

Yaşamın bu kıyısında tutamazlar

Mutlaka geleceğim

Seni

Kollarımda uyutup

Uyandığında

Çiçekler vereceğim 

Bulutsuz gecelerin yıldızlarından

Yaşıyorken gelemezsemde

Olurda bir gün  ölürsem

Senin haberin olmadan

                                       Apansız

Ben

Senin, beni beklediğini bilirim

Takarım meleklerin kanatlarını

Binerim bulutlara

Güneşli bir günde olmasa bile

Yağmurlu bir günde

                              Konarım gözlerine

10-08-2005/ İst

Alkadraz_Kuşcusu', 'KONARIM GÖZLERİNE Gülüşlerinde O Şubat soğuğu                         Hiç olmayacak Seni  Yakamozlu ağustos gecelerine saklıyorum senin sess...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/konarim-gozlerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığa Karşı Aşk Mektubu', 'ayriliga-karsi-ask-mektubu-eyup-selahattin-dalkiran-bftxe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllardır beyaz sayfaların içine dertler dinleten

Kalemim yine kızgın.

Al da oku dedi ellerim şiirimi,

Neden? Eleştirilsel,düşünsel o gece,amaç değerlendirme

Aman ne okuma ne bakış bu sevdiğim.

Diyorsun ki

Ben çantamda birkaç kuruşla dolaşırken

Sen kalkmış hiç evi düşünmeden şiirlerinle yaşıyorsun

Gelip gidiyorsun bir otel gibi

Hiç ilgilenmiyorsun evinle varsa yoksa şiirlerin

Ayrıca 

Neden ben yokum şiirlerin içinde? 

Hani Sevilerim,Dudaklarım,hasretim.

Sanki şiirlerin içinde alaca karanlığın,aydınlığını

Ve kendini öldürür gibiydin sevdiğim.

Hep söylendin sabaha kadar,sanki ilham perilerimi gaza getirircesine.

Al sana öylese

Ah bir bile bilsen yüreğimdeki sana olan sevgiyi,saygıyı

Ve benim içimdeki yorgun çoçuğun işinde orada,burada

Canını dişine takarak koşuşup beklediği maaşını

Amaç ne? 

Senle yaşamak

Ne için? çoçuğumuz ve sen

Kazanç kime

Sana,çoçuğuma ve bana

Ya sonra sen,bana

İbret verici eleştiriler mor bir bakış,neden sevdiğim.? 

Olsun bu yürek dayanır senin söylediklerine

Şu yirmi birinci yüzyılda

sana söylediğim geçersiz acı sözlere

senin yüreğin nasıl dayandıysa bana.

Belki kendince haklısın

On sekiz senelik yaşamın şeklini çiziyorsun

Boşluktaki tualin üstüne

Nede olsa sende güzel yaşamak istiyorsun

Her dakikana şükreden yapınla

Mısralar çok uzun olacak sevdiğim

Belki anlatımlarım bir tırtılın yeşil yaprakları

Kemirip karnını doyurması gibi olacak

Yada

Gündüzün,karanlığa

Hafif rüzgarın,kasırgaya

Yağmurun,doluya

Yaşamın,ölüme

Beyaz sayfaların,kara sayfalar

Bunalımsızlığın,bunalıma

Ölümün,ölümsüzlüğe

Dönüşe bileciğini anlayacaksın,benle birlikte

Ve sonra sen yüreğimde sevilerimde

,kurşun geçirmez bir sevgi

Zırhıyla kaplı olduğunu anlıyacaksın? 

seni dünyada olmayan zümrütlerle süsleyip,sevdiğimi bileceksin 

Bilmezmisin senin ellerini tutmak için neler çektiğimi

Kekeliyiyerek ne kadar zorda olsa anlatmıştım sevgimi

Ne demiştin? evet,biliyorum beni sevdiğini

Kahrolasıca parasızlık büküyordu belimi biliyorsun

Dünya evine girmek kolaymı? 

Gece olmasını istemezdim,parasızlıkla yüzleşirim diye

Mutsuz ve ziyan olmanı istemezdim.

Bu yüzden

Bir çift kuşun babil vaktinde

Yuva kuruşu benim için emek ve sevdanın

Soylu umutlarında yaşardı.

Soylu umutlarda düş ve hüzün olmamalıydı

Geceler hergün geldikçe.

Bir karınca misali yürüdük senelerce

Ne için amaç evlemek birbirimizle

Biz beklerken kaç minik kuş dünyaya geldi kimbilir

Kaç atmaca boğazladı yerdeki tavşanı kendine göre avını.

Kara günlerdi

Emekle,aşkı bir arada götürmek

Kim anlardı ki halimden

Çalıştığım işyerinde hepsi aynı gaylede amaç para

Olmayınca para içemiyorsun ki çayı zemheri soğukta,eller cepte iken

Yirmi birinci yüzyılda

Olsun yüreğim bunda dayanır

Senin yüreğin bunlara dayandığı gibi.

Kuru ve acımazsız sözler senden,benden uzak kalsın

En güzel umutları toplayalım Yaşadıklarımızla

bir demircinin örsüne vurduğu çekiç gibi.

kötü sözleri vurdukça sen,bana,ben,sana. 

Şiirlerim benim sevgilimdir biliyorsun sen gibi

Onu yaralayana karşı

Bir kaplan bir şahin olurum

Söylenmemiş,söylenmeyecek

Boz bulanık türküler,şarkılarla inerim sözlerine.

sevdiğim

Usumda olanca kuşları uçurdum olanca hızıyla

Cumayı cumartesine bağlayan gecede haberin olmadan

Gökyüzü genişlesin diye

Senin mısralarımda,sevilerimde,dudaklarımda

Olduğunu,yeryüzünde olmayan zümrütler ile süsleyip

Kurşun geçirmez zırhla kaplı yüreğimin en güzel yerinde

Olduğunu anlaya bilmen için bir gün.

Duvardaki saat bağırıyor yeter diye

Kaleminde kan damlamak üzere.

Neden mısralarında,sevilerinde yokum sözüne

İlham perimi kızdırdın,işte

Yazılmak istenmeyen bir şiirin hızına girmiş ha bire yazmakta

senin için

Ne yapmalıyım? 

Hanği sevincimi hanği güzel günü,hanği tatlı konuşmaları 

Hanği tatlı dakikaları anlatmam lazım.

İlham perim bile bu söylediğin söze 

Bir ipek böceği gibi sessiz kalmakta,kalıyorda

O deniz kenarındaki koca kayanın duvarına yaslanıpta

Sevda sözlerimdemi seni inandırmadı halen olduğu gibi

Ya denizin dalgaları ya iki üç martının bize baktığı zaman

Sözlerimi duymadılarmı zannediyorsun

Ya o kayanın sırtına yaslanmışken seni öptüğüm an

Onlar şahit değillermi? dudaklarımız

Bak sevdiğim yüreğin bu mısralara dayanırmı,dayanmazmı

Onu bilemem ama bu mısralar

Senin içindir

Bu mısralarımda saçında kızıl çiçekler açmış,bir delikanlının

Yüreğinin temiz sayfalarıdır.

Bu sayfalarda kendinden ve herşeyden kaçış değildir

Bir başkalık vardır şiirimin içinde.

Yaşamın en güzel yanını alır yanına

Ve bizim yaşamımızı

Gel 

Bir ayna içinde 

Bir sen

Bir çoçuğumuz

Deli dolu olan

Elinde eski bir rüzgar çıkını ile dolaşan

Bir ben ile

Demiyelim bu gidiş bu kadın,bu erkek

Bana göre değil ayna içinde

En iyisi yine birbirimizi sevmek

Yüreğimizin en iyi yerinde

Yüreğimiz zırhla kaplanmıştır zırhı kırmayalım,kırılmak

Herşey kırılır kendince

Dal,cam,kristal,şişe,çelik,bakır,yürek

Bir kırılırsak kristal gibi dağılırız

Her bir parçamız bir dağda kalır

Hayır kırmıyacağız biliyorum

Ben sana nasıl sıcacık bir gün ile güneşimle geldimse

Sende bana güneşinle geldin 

Sevgimizde iki yana savrulurdu çiçekler

Kavak ağaçlarının yaprakları titrerdi

Denizin balıkları,dalgaları selama dururlardı.

Gel kırmayalım

Hem yeniyi,hem eskiyi,aşk üstüne,ölüm üstüne,

Ayrılığa karşı olan  yaşayan hayatımızı

Geceleri ölümü düşünmeyelim sıkıntılar içinde

Ölümün gerdanından su içmeyelim

Kalblerimizi hüznün odasına kapatmayalım

Hüznü dışımıza kilitleyelim

Birimizin şu anda olan sevilerimizden

Daha derin sevileri kuçaklıyalım

Ayrılık öyküsünü

Gömelim sulara bizsizlik nehirlerine girmeyelim

Birbirimizin aşkı için aşkımızı ölümsüzlük ipeğine saralım

Uzatalım ellerimizi duygularımızın en güzel eksenine

Hadi gel öpelim birbirimizi gerçek sevgi,aşk ile.', 'Yıllardır beyaz sayfaların içine dertler dinleten Kalemim yine kızgın. Al da oku dedi ellerim şiirimi, Neden? Eleştirilsel,düşünsel o gece,a...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":156,"source_url":"https://www.antoloji.com/ayriliga-karsi-ask-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolum Adına demirliyor da', 'yolum-adina-demirliyor-da-turan-tuncer-67a48', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YOLUM  ADINA  DEMİRLİYOR DA

Koşuyorum da  ardından

Yaşam hep bir adım önümde

Yorgunluğunu yaşarım

Yaşanmamış sevdalarımın

Karanlığa, 

Yüklerim hasretimi 

Şarkılarımı, 

Ayın parlak yüzüne söylerim

Gözlerin gelir aklıma

Ruhu, 

Mavisinde saklıdır

Umutlarımı 

Alabora eden

Sonra! 

Sonrası yok

Bir tufan,

Bir kıyamet.

               Gözlerimde,

                              Gözlerini okuyorum

Yazılmamış kitapların sabrı ile

Neresinden

Bakarsam bakayım

İki kelimesi hep eksik şiirlerimin

Yaşamak ağır gelir

Emanet bedenime

İçinde sevgi olmayınca

Sancılı, uykularım

Her kesildiğinde 

                           Yeni bir senle

Yolum adına demirliyorda

Rüzgarlar kifayetsiz

Doldurmaz yelkenlerimi

Adını,

Adımın öncesinde ezberlemişim

Pas tutmuş aşklarım

Gözlerinin değdiği yerde

Söküp atmak çok korkakça

Bilirimki,

Sevdikleri yakar canını

İnsanların

15-12-2005/İst

Alkadraz_Kuşcusu', 'YOLUM  ADINA  DEMİRLİYOR DA Koşuyorum da  ardından Yaşam hep bir adım önümde Yorgunluğunu yaşarım Yaşanmamış sevdalarımın Karanlığa,  Yükler...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/yolum-adina-demirliyor-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanı Böldüm Dörde', 'zamani-boldum-dorde-i-brahim-baykal-48crd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birincisi,

                Seni tanıyıncaya kadar ki,

                Gençlik zamanıydı demek,

                Hızlı geçti onun gibi,

                Anlayamadım.

                İkincisi,

                Seninle birlikteyken ki geçen,

                İşte.

                Ben o zaman yaşadım,

                Hem iyiyi,hem kötüyü.

                Hem acıyı,hem tatlıyı.

                Öyle ya...Demek buydu hayat.

                Hep güzel geçseydi zaman,

                Nasıl fark ederdik onun güzelliğini,

                Kötü günler olmasa.

                Kavga ettiğimiz de oldu.Konuşmadığımız da.

                Lanet ettiğimiz de oldu.Kahrettiğimiz de.

                Ancak,şimdi anladım.Sen gidince.

                En mutlu günlerimizin onlar olduğunu.

                İyisiyle...Kötüsüyle...

                Gelelim üçüncü zamana,

                Sen yoksun artık yanımda.

                Oysa ben,

                Beraber yaşıyorum seninle,yaşamaksa böylesi.

                Sen gölgemsin yanımda,ya da tersi.

                Dokunamıyorum ama hissediyorum varlığını.

                Attığım adımın biri senin,

                Yediğim lokmanın da.

                Gözümün de kulağımın da biri senin.

                İkiye bölünmüş bedenim.

                Dördüncüsü ve sonuncusu,

                Sana ulaştığım zaman.

                Meçhul...! 

                Vallahi bilemiyorum,nasıl olacağını.

                Nasıl geçeceğini ve ne kadar süreceğini.

                Ne önemi var ki? 

                Geleyim yanına da,

                İster bir daha alsınlar canımızı.

                Atsınlar bizi birlikte bir çukura.

                Cennetmiiiiiş...Cehennemmiş kimin umurun da? 

                                                  

                             Ocak 2001/ İbrahim Baykal', 'Birincisi,                 Seni tanıyıncaya kadar ki,                 Gençlik zamanıydı demek,                 Hızlı geçti onun gibi,       ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Baykal']::text[], 8.5, '{"poet":"İbrahim Baykal","poet_slug":"i-brahim-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/zamani-boldum-dorde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşin İçinde Üşümek', 'atesin-i-cinde-usumek-turan-tuncer-ap8pt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ATEŞIN IÇINDE ÜŞÜMEK

Akşam kızıllıkları, 

Güneş''in- 

Kırallığı 

         Çökerken olur

Ateşin içinde, 

Titremeler  yaşarsın.

Üşümekten beter olursun.

Yakın gurbetler içindir,

Çan çiçekleri.

Kimine göre.

Beş çaylarına- 

Sohbet dostudur,

Akşam sefalari.

Bana göre 

Ayrılıkların habercisi

Baykuş gözleri.

Biz- 

Papatya olalım, 

Sereserpe- 

Kır çiçekleri,

Ayrılmayalım diyorum.

Diyorum ya! 

Benim kırlarıma- 

Betonlar döktüler.

23-11-2005/İst

Alkadraz_Kuşcusu', 'ATEŞIN IÇINDE ÜŞÜMEK Akşam kızıllıkları,  Güneş''in-  Kırallığı           Çökerken olur Ateşin içinde,  Titremeler  yaşarsın. Üşümekten beter...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/atesin-icinde-usumek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Dünya', 'don-dunya-i-brahim-baykal-fk4b6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dön dünya dön, ister daha hızlı dön.

İster, dörde çıkar bir günlük turunu.

Savur beni üzerinden, yük olduysam sana,

Korkmuyorum senden, daha ne yaparsın bana.

Demek,ekmeğini yedim, toprağını çiğnedim,

Suyunu içtim, havanı soludum,

Böyle mi ödeyecektim borcumu? 

Yazık! 

Tükettin umudumu.

Dağların taşların, suların ırmakların senin olsun.

Kuşlarını, böceklerini çiçeklerini de istemiyorum.

Benden aldığın canımı geri ver,yeter.

Yoksa, ben de geliyorum!', 'Dön dünya dön, ister daha hızlı dön. İster, dörde çıkar bir günlük turunu. Savur beni üzerinden, yük olduysam sana, Korkmuyorum senden, daha...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Baykal']::text[], 8.5, '{"poet":"İbrahim Baykal","poet_slug":"i-brahim-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/don-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyuyormusun Beni', 'duyuyormusun-beni-i-brahim-baykal-zlwvs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben yaşadıkça,göreceksin bak! 

Edilen dualar,seni bulacak.	

Unutuldum sanma,gücenirim,

Hasret gönderiyorum al,kucak kucak.

Melekler bile şimdi dosttur sana,

Bana da yanından yer ayırsana.

Yeter artık burada sıkıldım durdum,

Ne duruyorsun hala,hadi çağırsana.

Allahım,beni sen,neden yarattın? 

Kırk yıldır fazladan nasıl yaşattın? 

Suçum ne,günahım neydi? Anlayamadım.

Aldın canımı benden,toprağa kattın.', 'Ben yaşadıkça,göreceksin bak!  Edilen dualar,seni bulacak.	 Unutuldum sanma,gücenirim, Hasret gönderiyorum al,kucak kucak. Melekler bile şim...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Baykal']::text[], 8.5, '{"poet":"İbrahim Baykal","poet_slug":"i-brahim-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duyuyormusun-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte kaderimiz', 'i-ste-kaderimiz-mahmut-simsek-q8suv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biz cefalar için gelmişiz dünyaya

Hiç gülmedik,ki biz hep bahtımız kara

Belki güleriz dedik bir gün bir ara

Olmuyor dostum düşüyoruz hep dara.

Hayattan tad almak geldi içimizden

Yine olmadı sefalar kaçtı bizden

Hayatın acımasız olduğu günden

Kader,kader dedik hep ağladık birden.

Bu acılar işte bizim kaderimiz

Hiç gülmedik gülemeyiz biz deliyiz

Hayat hep düşman oldu bu kaderimiz

Yinede küsmedik bu bizim derdimiz.

İşte dostum bizim kaderimiz böyle

Mekan tutuk ıssız yerleri her gece

Dargınlığımız yok bizim hiç kimseye

Allahtan dileğim sen hiç acı çekme.', 'Biz cefalar için gelmişiz dünyaya Hiç gülmedik,ki biz hep bahtımız kara Belki güleriz dedik bir gün bir ara Olmuyor dostum düşüyoruz hep dar...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iste-kaderimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Mektup', 'sana-mektup-i-brahim-baykal-dqg36', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kızıyorum sana, 

Sana çok kızıyorum.

Beni bıraktın yapayalnız.

Kırıldı kanadım kolum.

Kıskanıyorum seni.

Seni çok kıskanıyorum.

Bak! kimler var yanında,

Akrabalarını sayma.

Herkesin tanıdığı hani,

Herkesin de sevdiği.

Adile Naşit mesela…

Kemal Sunal.

Her gün görüyoruz hayalini,

Sen de gerçeğini.

Burada da severdin sen,

Berabersiniz şimdi.

Barış Manço da vardı,

Hani dolaşırdı dünyayı.

Orda da gezse ya hadi.

Bir de Ahmet Kaya.

Kimileri sevmese de sen severdin biliyorum.

Şarkı söylerdi dağlara,yüreği yanık analara,

Şimdi aranızda.

Esmeray ı da hatırlarsın tezkeresiyle,

Son olarak ta Mahsuni geldi,

Kırık sazı son nefesiyle.

Yaşamları mücadeleyle geçti,boşa mı gitti çabaları,

Eserleri bize kaldı,değişti dünyaları.

Seviyorum seni.

Seni çok seviyorum.

Çok isterdin bu sözü,biliyorum.

Dilim söylemese de anlardın hep.

Hani utanırdım ya.

Şimdi haykırıyorum bak! ulaşır sana.

Seni çok seviyorum.

Bu dünyada duyamadın.

Senden af diliyorum.

Seni merak ediyorum.

Seni çok merak ediyorum.

Oradakilerden haberin var mı,görüyor musun herkesi? 

Yalnız mısın? Yoksa sınır mı var aranızda.

Zamanın nasıl geçiyor? Canın sıkılmasın da.

Uykuyuda severdin, uyuyormusun hala? 

Çalışmadan da duramazsın,  yine de kendini yorma.

Köy mü şehir gibi mi oralar? 

Hala toprakta mısın arasında mı yıldızların? 

Görüyor musun bizi,duyuyor musun sesimizi? 

Seni merak ediyorum.

Seni çok merak ediyorum.

Özlemedin mi beni? 

Ve…

Çok korkuyorum.Vallahi korkuyorum.

Ölmekten değil ha! yanlış anlama.

Seni unutmaktan.

Zamana kızıyorum biraz da.

Yüreğimi katılaştırıyor.

Daha iyi yaşama isteğim yok biliyorsun.

Hiçbir şey de beni mutlu etmeyecek artık.

Hiçbir şeyi de seninle geçen en kötü anıma değişemem inan! 

Ya ben başka ben olursam,

İşte o zaman,

Asıl o zaman ölürüm.

Seni unutmaktan sa ölmeyi yeğlerim diyemiyorum.

Çünkü; en güzeli o.

Sana geliyorum ya.

Senin kollarında gitmek isterdim bu dünyadan.

Ya da başucumda sen olduğunda.

Bu olmadı.

Aç kollarını.

Hiç olmazsa orda sen karşıla.

Özlüyorum seni.

Seni çok özlüyorum.

Merak etme az kaldı.

Kızsan da geliyorum.

                            

                     Mart 2001 - İbrahim Baykal', 'Kızıyorum sana,  Sana çok kızıyorum. Beni bıraktın yapayalnız. Kırıldı kanadım kolum. Kıskanıyorum seni. Seni çok kıskanıyorum. Bak! kimler ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Baykal']::text[], 8.5, '{"poet":"İbrahim Baykal","poet_slug":"i-brahim-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/sana-mektup-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-asude-gediz-wccyy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu seninle son buluşmamız

takıntılı aşklara yer yok dünyamda

sökerek attım sevgini

veda ediyorum sana ve senli günlere

zaten anlamadım nasıl oldu

iki tatlı sözle sevgi olur mu

istemiyorum seni ve senli günleri

bir süre için şiire   veda sayende', 'Bu seninle son buluşmamız takıntılı aşklara yer yok dünyamda sökerek attım sevgini veda ediyorum sana ve senli günlere zaten anlamadım nasıl...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/son-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adın /SUS/ku/ olsun! ..', 'adin-sus-ku-olsun-selahattin-yetgin-5m7ti', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'niye kırmızı atar yüreğim

ellerini uzatınca bana

her gece yıldız düşen

sevda külleriyle oluşmuş

bu aşk bataklığına

niye düşerim sevdam

sen gözlerime değince

sen uluorta yalnızlığımda

sineme mevsim çiçeklerini

yüreğime aşkın repliğini

emsalsiz bir esinle güneşleri

bu büyük atlasta herhangi biriyim işte

niye düşürdün içime üşüten güneşlerini

birlikte destelerken ruhta yakarışı

içimde onlarca geçit leylaklı bir deniz

ey aşk neden zamansız gelirsiniz

müebbedim bitmeden kelepçelersiniz

bu sunaklarda kaybetmedim mi anahtarlarımı

bu ırmaklara savurmadım mı küllerimi

bir çiçeğin erguvan tınısı şimdi sazımda

aşk küllüğümde onlarca izmarit ve sevda

onulmaz bir kabartı düşler ektiğim tarlamda

çılgın bir orkide yol alıyor günlerdir sularımda

dudak arayan elleriyle okşuyor göğsümü rüyalarda

kimi de gözyaşı akıtıyor yeşili kalmayan dağlarıma

gözleri gökçül bir tenin emsalsiz barınaklarında

kalemimi de astım aşkın üşüten söğüt dallarına

gecelere balonlar saldım yıldızlar gülüşsün diye

biliyorsun ben seni yüreğin büyüsün diye sevdim

seni sevmek ölümsüzlükse eğer hiç ölmeyeceğim

adını da /sus/ku koydum sustukça büyüyeceğim', 'niye kırmızı atar yüreğim ellerini uzatınca bana her gece yıldız düşen sevda külleriyle oluşmuş bu aşk bataklığına niye düşerim sevdam sen g...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/adin-sus-ku-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Affet', 'beni-affet-erdinc-batur-f9yet', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelemedim sana, benim de içim kan ağlıyor

Tıkanır cümleler, sevda ise sana olan yangınım

Beni sana hariç her yana sürükler

Geçerken sokağından ve kapından

Her adımın bir ok gibi cana batar

Her bakışın alev-alev içimde yangın

Önce kavurur sonra nefesin savurur küllerimi

Dizlerim tutmuyor can

Sevdan ağır gelir taşıyamam

Beni affet...

Gözlerim kamaşır, ağlamaklı hallerde

Başım yaslı durur bükülen bileklerime

Duvarlara vurmaya ramak kala

Öylede acı, böyle de acı 

Bazen kader deyip geçiyorum

Oysa benim dönmeyen yüzümü, söyleyemeyen sözümü

Mazeretsiz erteleyişlerim sığmaz affa

Kıyametim gelir can 

Ben bu aşka taraf olamam

Beni affet...

İçimde uhde kaldı,

Sana duyduğum özlemler

İçimde bir piyade tüfeği, mermisi saplı kaldı

Hayalin gündüz güneş, gece yıldız

Gözlerimden kalkmayan şu sis perdesi

Semahında cihanın sana haykırsam

Sesim ulaşmaz sana duyuramam

Yüreğim dilimden ırak

Bedenimse senden feragat gibi

Bu aşka yol veremem can

Benim varlığımdır sana ben-d olan 

Beni affet...

                                                      Erdinç Batur...', 'Gelemedim sana, benim de içim kan ağlıyor Tıkanır cümleler, sevda ise sana olan yangınım Beni sana hariç her yana sürükler Geçerken sokağınd...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Batur']::text[], 8.5, '{"poet":"Erdinç Batur","poet_slug":"erdinc-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/beni-affet-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Forsa', 'forsa-umut-engin-deniz-9fszp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“Ayrılığın kırbacını sırtına yedin mi hiç?”

Aydınlık sulardan karanlık sulara yol alan;

aşkın kutsal denizinde batıp çıkan,

fırtınalara ayak direyen 

köhne bir teknede forsa!

Özgür bir şimşek çaktı

karanlığın derinliklerinden,

teknenin güvertesine...

Bir kucak karanfil kokusu vurdu

terden ıslanmış

yorgun bedenime.

Katık oldu,

kimseyle paylaşmadığım

hasret sofrasına.

Parçalıyorum dalgaların karanlık gövdesini —

bir kulaç daha kaldı...

Bekle beni!

UNLBBCN

[email protected]', '“Ayrılığın kırbacını sırtına yedin mi hiç?” Aydınlık sulardan karanlık sulara yol alan; aşkın kutsal denizinde batıp çıkan, fırtınalara ayak...', ARRAY['Türk Edebiyatı','Şiir','Umut Engin Deniz']::text[], 8.5, '{"poet":"Umut Engin Deniz","poet_slug":"umut-engin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/forsa-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son kalan nedir', 'son-kalan-nedir-mikdat-bal-amrh6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün geceden kalma hala şaşkınsın

Dostluk tamam ama bu  ilan nedir? 

Ne bu halin bana ne çok düşkünsün

Şaka maka derken bu pilan nedir? 

Bu şahıs ne deli ne de kaçıktır

Ama gönlüm her gönüle açıktır

Saçlarım ak beti benzim uçuktur

Sevgi, saygı söyle aslolan nedir? 

Sevgi başka mevkı başka dünyada

Yaşıyoruz böyle tatlı hülyada

Dün gece mi gördün beni rüyada

Bütün bunlar gerçek ya yalan nedir? 

Mikdat der ki dünya küçük dar değil

Beni yakan ateş değil nâr değil

Ömür bitti zarar ile kâr değil

Bu dünyadan bize son kalan nedir', 'Dün geceden kalma hala şaşkınsın Dostluk tamam ama bu  ilan nedir?  Ne bu halin bana ne çok düşkünsün Şaka maka derken bu pilan nedir?  Bu ş...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-kalan-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabus', 'kabus-nevzat-ozkan-72wbu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'korkuyla kalktım 

dün gece yatağımdan

baktım pijamam sırılsıklam

komşu bahçede yakalandım

can eriği çalarken

''ana beni eversene'' türküsünü söylüyordu

pencerede elma yiyen

bana abi diyen

komşunun güzel kızı

çitlerden atladım soluk soluğa

aniden karşıma bir bekçi çıktı

başında  subay şapkası

ardında kocaman bir demir kapı

kapının yanında yabancı kadın

what is your name dedi

durdurdu beni

''nedir senin adın''

tekrarladı bekçi

dilim tutuldu bayıldım birden

gözlerimi açtım

asistanlar proflar  başucumdaydı

kağıttaki sorular oldukça zordu

uğraştım yapamadım

yazık bu dönem de mezun olamadım', 'korkuyla kalktım  dün gece yatağımdan baktım pijamam sırılsıklam komşu bahçede yakalandım can eriği çalarken ''ana beni eversene'' türküsünü s...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kabus-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gidişin sonu...', 'bir-gidisin-sonu-mustafa-komuscuoglu-i1khw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ömür sonsuza dek dünde kalmış bir sevdaya hükümlü

Bu gözler gidenin ardından ağlamakla yükümlü

Gönül kapatmış kapılarını,eski bir sevdayla mühürlü

Ne kadar uğraşırsan uğraş,ömrümde hep aynı hüzün gömülü

Görmek yok bundan sonra,bir çift yeşil gözü

Duymak yok,baharda cıvıl cıvıl kuşların ötüşünü

Ve yazmak yok kağıtlara,bir kalbin ölüşünü

Ne kadar uğraşırsan uğraş,diriltmez kuru sözler ölüyü

Tel tel saçlarına bağlamıştım ömrün her gününü

Yokluğunda tattım,yaşarken tadılan ölümü

Yanlız akşamlarda sattım umut denilen kördüğümü

Şimdi ne kadar uğraşırsan uğraş,ölüme saldım gönlümü', 'Ömür sonsuza dek dünde kalmış bir sevdaya hükümlü Bu gözler gidenin ardından ağlamakla yükümlü Gönül kapatmış kapılarını,eski bir sevdayla m...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-gidisin-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beytullah''ı Görmek İstiyor Canım', 'beytullah-i-gormek-i-stiyor-canim-seyfet-bozcali-a5slv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllarca Aşkıyla kavruldum durdum,

Beytullah''ı görmek istiyor canım.

O sevdayı çeke,çeke yoruldum,

Beytullah''ı görmek istiyor canım.

Her yıl milyoncası o sese koşar,

Tek yürek ve tek beden gibi coşar,

Pişman olup gözden dökülür yaşlar,

Göz yaşları dökmek istiyor canım.

Dil,ırk,lisan ayrılığı  gözetmez,

Lebbeyk seslerinden başka söz etmez,

Arş''a çıkar dua ve niyaz yetmez,

Tevhitle haşrolmak istiyor canım.

Melekler karşılar misafirleri,

Doludur Mekke''nin her karış yeri,

Allah nidaları doldurur evreni,

Yalvarmak,af olmak istiyor canım.

Akar durur insan coşan sel gibi,

Hakkın huzurunda herkes bir gibi,

Ağa,paşa boynun bükmüş kul gibi,

Mahşere karışmak istiyor canım.

Kalp gözünü açmış,yüzde yok tasa,

Kimiyi doğrultur,elinde asa,

Kimisi can verir boğulmaz  yasa,

Vuslatla buluşmak istiyor canım.

Çatlak ayaklarla hakka koşarlar,

Açlığını zemzem ile aşarlar,

Cılız,hasta bedeniyle coşarlar,

Allah için coşmak istiyor canım.

Gözü yok dünyanın  fani işinde,

Ahireti arar Kabe başında,

Tavaf eder durur o genç yaşında,

Onlar gibi koşmak istiyor canım.

Rabbine yalvarır,eder niyazı,

Yaratandan mağfirettir tek sözü,

Aşkla kılınıyor veda namazı,

El açıp yalvarmak istiyor canım.

Hacerül Esvede yüzünü süren,

Dünya nefisini,yıkıp ezdiren,

Şeytenları taşlayarak  kızdıran,

Eller olup vurmak istiyor canım.

Sevda seli çoşar,Sefa Merve''de,

Resulüllah bakar durur zirvede,

Cennet anılır,ihrama girmede,

İhramına  girmek istiyor canım.

Makamı İbrahim rahmet sofrası,

Zemzemler sunulur,bir kevser tası,

Mağfiret havası sarmış herkesi,

Rahmetini almak istiyor canım.

Anlatamaz insan böyle olayı,

Melekler kaplamış arzı semayı,

Almıştır hacılar hisseden payı,

O vakayı görmek istiyor canım.

Seyretsem tavafı kalsamda hayran,

Belki o gün kalbim edecek bayram,

Omuz,omuzadır melekle insan,

O araya girmek istiyor canım.

Tövbe,istiğfardır gözlerden akan,

Beytullahtan taşıp göklere çıkan,

Rahmet olup tekrar gönüle akan,

Rahmet yağmurunu istiyor canım.

Allah diye Kabe çoşar,iniler,

Dağlar,taşlar hep o besteyi dinler,

Dirilerek  eşlik eder ölüler,

Onlarla zikretmek istiyor canım.

Dokuz minareden ezan okunur,

Sinelere ilmik,ilmik dokunur,

Resulüme çok selavat okunur,

Toprağa yüz sürmek istiyor canım.

Mahşer yeri,gökler yere kavuşur,

Canlar burda kıyamete alışır,

Rahmet için birbiriyle yarışır,

O rahmeti tatmak istiyor canım.

Orda gördüm dünya bir oyalama,

Zenginlik içinde mutluyum sanma,

Bu canı Kabe''yi görmeden alma,

Mevla''dan dilemek istiyor canım.

Tavaf bitip her can hakkın alınca,

Günahtan arınıp, yurda dönünce,

Bu aciz kulunu layık görünce,

Seyfet der işaret bekliyor canım.....

      12.01.2006', 'Yıllarca Aşkıyla kavruldum durdum, Beytullah''ı görmek istiyor canım. O sevdayı çeke,çeke yoruldum, Beytullah''ı görmek istiyor canım. Her yıl...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/beytullah-i-gormek-istiyor-canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayıptır Söylemesi (Şarkı Sözü)', 'ayiptir-soylemesi-sarki-sozu-cengiz-suslu-kp9cm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her anım alev,alev yanlızlığımda

Her yanım acı dolu yokluğunda

Kırılgan oldum,hayattan yoruldum

Söylemesi ayıptır korkuyorum

Yar banada hak ver,taş değil ki yüreğim

Yar banada hak ver,bilinmedi değerim

Sevdim diye pişman filan değilim

Ayıptır söylemesi,sensin tek istediğim', 'Her anım alev,alev yanlızlığımda Her yanım acı dolu yokluğunda Kırılgan oldum,hayattan yoruldum Söylemesi ayıptır korkuyorum Yar banada hak ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayiptir-soylemesi-sarki-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu ad bize haram olsun bu yalan fani dünyada kalmasın', 'bu-ad-bize-haram-olsun-bu-yalan-fani-dunyada-kalmasin-halil-colak-ftfdv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözü yaşlı analar ağıt yakıp yavrum diye ağlarken

Anadolu dağlarında hain  düşman cirit atıp oynarken

Munzur çayı azgın seller gibi akıp üzüntülü çağlarken 

Türkün tüten ocaklarına hain düşman acıları salmasın

Bir katıksız ekmeğimde olsa da helal olsun millete

Bin bir canımızda olsa da  kurban olsun bu devlete

Eğer boyun eğersek millet olarak bu hain ihanete de

Yere batsın cinsimiz cibilyetimiz yok olsun da kalmasın

Biz bu hainleri  bu kutsal vatan toprağından atmazsak 

Tek başımıza  şerefsiz it sürüsüne değenekle dalmazsak

Eğer cennet olan vatanı bu hainlerden de temizlemesek

Bu ad bize haram olsun bu yalan fani dünyada kalmasın

Halil Çolak 26.1.2006 Ankara', 'Gözü yaşlı analar ağıt yakıp yavrum diye ağlarken Anadolu dağlarında hain  düşman cirit atıp oynarken Munzur çayı azgın seller gibi akıp üzü...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-ad-bize-haram-olsun-bu-yalan-fani-dunyada-kalmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelenim...', 'kardelenim-halide-selcan-karagul-xdida', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kardelenim...

Yaylalar, dağlar benim meskenim

Kar yağar üstüme örter bedenim

Göz alabildiğine bembeyaz yumuşacık döşeğim

Zevk verir bana, yalnız başıma kendimce eğlenirim

Karlar erimeye başlayınca yavaşça gün yüzüne çıkarım

Ürkek, tedirgin bir dost arar gözlerim

Dost sözü yaralar neyleyim sabırla beklerim

Umutsuzluk benden uzak kalsın günü güne eklerim

Daima güneşe dönüktür yüzüm dostça gülümserim

İstemem kimse olmasın yanımda yalnızlık benim sevdiceğim

Yaylalar, dağlar benim meskenim

Ben bir garip beyaz kardelenim...

30.12.2005 15:15', 'Kardelenim... Yaylalar, dağlar benim meskenim Kar yağar üstüme örter bedenim Göz alabildiğine bembeyaz yumuşacık döşeğim Zevk verir bana, ya...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kardelenim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isınıyorum', 'isiniyorum-halime-vatansever-ydl93', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece yamıyor bütün hatalarımı 

Bütün kusurlarımı örtüyor 

Oysa tek istediğim gece boyunca 

Beynimdeki urları kusmak oldu 

Oysa hep ordaydılar 

Aklımın soğuk koridorlarında 

Çıplak ayaklarıyla dolaşıp durdular 

Kaybettiğim bütün imkanlar. 

Bütün imkanların imkansızlık olduğu 

Zamana gelmek için 

Daha çok saat tiktaklarını duyacağımı sanırdım 

Yanılmak böyle birşeymiş demek ki 

Yanmak ve ılımak olmalıymış 

Yanılımak... 

Çünkü ısınıyorum 

Ayak seslerini duymaya alışıyorum giderek 

Hatta seviyorum onları 

Onlar beni seviyor mu bilmiyorum henüz 

Öyleyse bilmek de böyle birşeymiş 

Bilmek ve ilmek... 

Bilmediğim herşey ilmek ilmek oluveriyor aklımda 

Bir sürü ayak sesi daha ekleniyor duyulanlara 

Oysa ben bilmiyorum bile onları 

Önümde bir muhabbet kuşu yine 

Ve yem yiyor diğerlerini hiç düşünmeden 

Üstelik yemlerin kabuğundan biri kağıdıma sıçrıyor 

Öylece pencereyi açmalıyım birgün 

Uçup gitmeli 

Yapamam ki ben bunu 

Şimdi hangimiz özgürüz 

Ben mi 

O mu... 

Halime Vatansever', 'Gece yamıyor bütün hatalarımı  Bütün kusurlarımı örtüyor  Oysa tek istediğim gece boyunca  Beynimdeki urları kusmak oldu  Oysa hep ordaydıla...', ARRAY['Türk Edebiyatı','Şiir','Halime Vatansever']::text[], 8.5, '{"poet":"Halime Vatansever","poet_slug":"halime-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/isiniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat bir hayal etmez', 'hayat-bir-hayal-etmez-halime-vatansever-ca49p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanı hayvandan ayıran birşeyin de 

Hayal edebilmesi olduğunu anladım 

Ne güzel şey hayal edebilmek 

Hele bendeki sen için 

Hele sensizliğindeki ben için ne güzel şey... 

Gemiler gittikçe küçülür gözlerimde 

Martılar büyür de büyür 

Gemiyi yüzdüren büyük mucize oluverir 

Uçaklar hüzünlü görünür gökyüzünde 

Hiç yolcusu yokmuş gibi 

Yapayalnız. 

Ben hiç ayırt edememişimdir 

Martılar gemilerin mi peşindedir 

Uçakların mı yoksa 

Ve benim martılarım hep 

m şeklinde oldu resimlerimde 

Ve ben sonra özgürlüğümü 

m harfiyle başlayan bir kelimeye 

Yüklemeye karar verdim 

Adın geldi sonra aklıma 

Ne kötü içinde m harfinin olmaması 

Ve ben sonra inat ettim hep 

Dizelerle yazmaya 

Ve ben sonra 

Ve ben sonra... 

Ve sonra sonrası olmayan işler gördüm hayatımda 

Martılar bana küstü 

Uçaklar demir yığını oldu 

Onların kara kutuları vardı onları kurtaran 

Gemiler denizi bıraktı 

Tersanelere sığındı 

Bense öylece kalakaldım 

Boş gözlerle 

Bir uçak batıyordu denizde 

Bir gemi uçuyordu gökyüzünde 

Bir martı bir bulutta yüzüyordu 

Ve ben öylece kalakaldım 

Geceyarısı düşlerimle 

Boş koridorda 

Çıplak ayaklarımla... 

---------------------

Hayallerinize inanın 

Onlar size yalan söylemez 

Üstelik hayatınız 

Bir hayal bile etmez.', 'İnsanı hayvandan ayıran birşeyin de  Hayal edebilmesi olduğunu anladım  Ne güzel şey hayal edebilmek  Hele bendeki sen için  Hele sensizliği...', ARRAY['Türk Edebiyatı','Şiir','Halime Vatansever']::text[], 8.5, '{"poet":"Halime Vatansever","poet_slug":"halime-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/hayat-bir-hayal-etmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşillik', 'yesillik-altay-taskin-sm1kq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'taşlarla bezenmiş boylu boyunca yeşillik

ne zaman geçerseniz geçin hakimdir sessizlik

ne ağlayan ne gülen var makamında

ağaçlar kuşlar da bunun farkında

burada uykular derin mi derin

yine de kimseyi rahatsız etmeyin derim

onlar ermiş sonsuzluk deryasına

biz de er geç varırız sessizlik dünyasına', 'taşlarla bezenmiş boylu boyunca yeşillik ne zaman geçerseniz geçin hakimdir sessizlik ne ağlayan ne gülen var makamında ağaçlar kuşlar da bu...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yesillik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Işığı', 'ayrilik-isigi-altay-taskin-r6d0z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ayrılığın sınırlı ışığında

ışıldar gözler

dar gelir dünya

sıkıcı karanlıktan

çıkış başlar

sevgi akla gelince

ışık küçücüktür

sevgi karanlığında

sonsuzluğu hatırlatır insana

ışık kandırıcıdır belki

ayrılığı sevenler için

orada yuvarlak bir masa

üç beş sigara biraz da çay

sevgi karanlığında herşey

coşkuyla

zaten aranan da o değil mi

sınırlı değilmiş hiçbir şey', 'ayrılığın sınırlı ışığında ışıldar gözler dar gelir dünya sıkıcı karanlıktan çıkış başlar sevgi akla gelince ışık küçücüktür sevgi karanlığı...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayrilik-isigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Falcının Dedikleri', 'falcinin-dedikleri-mehmet-sukru-bas-5ntpd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Taşlamalar…

Kırk yılın hatırına, bir tepside geldi kahveler,

Hele bacı dedik, bak bu fala, nicedir haller.

Aldı eline fincanları bacı, evirip de çevirdi,

Ikıla kıkıla hele bakın, ne çamları devirdi.

Bu gün mü? yarın mı?  üç Kasım mı desem,

Sandıklar konacak, önüne senin.

O sandıkta bir umut, bir güven aranacak,

Tesisat döşense de, ampuller yanmayacak.

Arı kovanında bir virüs, arıları sokacak,

Yolunu bulamayıp, peteğe varamayacak.

Dolaşacak başıboş, ideallerden uzak,

Ayağına dolanacak, kendi kurduğu tuzak.

Ak güvercin uçacak ama kolu kanadı kırık,

Sarıvermiş bünyesini, pişmanlıkla, hıçkırık.

Bir tutunacak dal ararken, ak güvercin,

Birden önüne geldi, ödü koptuğu seçim.

Şahlanamaz ki kır at, iki ayağı topal,

Bu yaz mutlaka kurtlara yem olacak.

O kurt ki oda, steplerde ok menzilinde,

Onu da bitirecek, kendi kurduğu tuzak.

İşte böyle oğul dedi, falcı kadın dün bana,

Bir küçücük umut, görünmez fincanında.

Ay mı desem, yıl mı desem, üç Kasım mı desem,

Bazıları boğulacak, kazdıkları kuyuda.', 'Taşlamalar… Kırk yılın hatırına, bir tepside geldi kahveler, Hele bacı dedik, bak bu fala, nicedir haller. Aldı eline fincanları bacı, eviri...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/falcinin-dedikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Yıllar', 'vefasiz-yillar-aynur-avci-pcbet', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok büyüksün yıllar

Kucağında taşıdın

Yüreğinde sakladın 

Bir gün elimden tutmadın

Beni çabuk unuttun

Vefasız yıllar..

Aşkımı sevdanı dağıttın

Gönüllerde avuttun

Çoğu zaman ağlattın

Acılarla bunalttın

Bir gün elimden tutmadın

Beni çabuk unuttun

Vefasız yıllar..', 'Çok büyüksün yıllar Kucağında taşıdın Yüreğinde sakladın  Bir gün elimden tutmadın Beni çabuk unuttun Vefasız yıllar.. Aşkımı sevdanı dağıtt...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vefasiz-yillar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fatih''in Sekreteri', 'fatih-in-sekreteri-mehmet-sukru-bas-czrch', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güncel taşlamalar…

Akıl sır ermese de, memleketin gerçekleri,

Otuz beş milyar pirim alır, Fatih''in sekreteri.

Ya otuz beş yıllık, eli öpülesi öğretmenim,

Ya pazarda limon satar, ya da nane şekeri. *

Yirmi dört Kasım''da başa taçtır öğretmen.

Yirmi yedi Kasım''da coplanandır öğretmen. **

Sakın gam çekme, olma meyus, ey eğitim neferi,

Onlar utansın sana sattırdıkları için nane şekeri.                     

             

  *  30 Kasım 2005 tarihli Hürriyet gazetesi

**  29 Kasım 2005 tarihli Hürriyet gazetesi.', 'Güncel taşlamalar… Akıl sır ermese de, memleketin gerçekleri, Otuz beş milyar pirim alır, Fatih''in sekreteri. Ya otuz beş yıllık, eli öpüles...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/fatih-in-sekreteri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Yarar', 'neye-yarar-nurten-koroglu-x0j3b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlasam neye yarar onca şeyden sonra

Yerine getirebilecek mi yitirdiklerimi

Ya da haykırsam çığlık çığlığa uykularımda

Bulabilecek miyim yanımda sevdiklerimi

Neye yarar once şeyden sonra güzel düşler kurmak

Neye yarar sevginin en güzelini yitirilmeye sunmak

Neye yarar yaralayan yıllardan

Defalarca hesap sormak

Çelişkiler anlamak yada anlaşılmayaçalışmak

Yitirmek her başlanan birlikteliklerde ümitlerini

Bulmaya çalışmak en güzelini en iyisini

Getirebilecek mi kaybolan yıllarım kaybettiklerimi

Boş yere yaşanırmış bu zamanda sevdalar

Yalan dolanmış sevmek dedikleri tılsım

Ya ben zamanın gerisindeyim dediğin gibi

Ya da zamanlar ötesinde sevdalarda sesim', 'Ağlasam neye yarar onca şeyden sonra Yerine getirebilecek mi yitirdiklerimi Ya da haykırsam çığlık çığlığa uykularımda Bulabilecek miyim yan...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neye-yarar-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülfen', 'gulfen-nurten-koroglu-sbw6w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adın gülden

Yazgın kara kışlar gibi

Bu kaçıncı ayaz

Bu kaçıncı yağmur fırtına ki

Sen nasır tutmuş ellerinle

Böyle kaçıncı sabahındasın

Çiğnenen kaldırımların üstünde

Yine mi ekmek kavgasındasın

Gülfen,

Adın gülden

Ruhun en güzelinden

Sormaya ne hacet

Gözlerin anlatıyor her şeyi

Anlatıyor yazgının izlerini

Dökülmese de kederin dilinden

Halden anlamaz bir koca

Uçup giden bir gençlik

Kucağa hasret iki çocuk

Terler alnında  boncuk,boncuk

Gülfen,sen kitapçı kadın

Hiç bir gün yok mu senin rahatın

Sattığın o kitaplardan

Daha ilginç değil mi hayatın

Sen hayat! 

Sen çözemediğim garip bir bilmece

Koynunda ne dünyaları barındırıyorsun

Kimleri ağlatıp

Kimleri güldürüyorsun

Yazık sana

Kimlerin başını

Kimlere eğdiriyorsun', 'Adın gülden Yazgın kara kışlar gibi Bu kaçıncı ayaz Bu kaçıncı yağmur fırtına ki Sen nasır tutmuş ellerinle Böyle kaçıncı sabahındasın Çiğne...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gulfen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmemeliydim', 'sevmemeliydim-aynur-avci-qzjhn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmemeliydim seni delicesine

Sevmemeliydim seni ölürcesine

Sağnak yağmurlar,akar gözümden

Yankılanır yüreğimde sesin

Ellerin başka ele değmesin

Sevmemeliydim seni delicesine

Sevmemeliydim seni ölürcesine

Şarkılarda benimlesin sen

Sözüne güvendim hep ben

Aşkın hasret,sevgin yalan olmasın

Sakla kendini herkesten

Ellerin başka ele değmesin..', 'Sevmemeliydim seni delicesine Sevmemeliydim seni ölürcesine Sağnak yağmurlar,akar gözümden Yankılanır yüreğimde sesin Ellerin başka ele değm...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmemeliydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rehin', 'rehin-belgin-turan-13qqs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O en güzel yıllarım, o körpe umutlarım,

Şafak sökene değin, akan kanlı yaşlarım,

Hayal ötesi sevgin, onlar değil birtanem,

Al bu can olsun senin, bilki o artık rehin.

Belgin Turan                         29.12.2005', 'O en güzel yıllarım, o körpe umutlarım, Şafak sökene değin, akan kanlı yaşlarım, Hayal ötesi sevgin, onlar değil birtanem, Al bu can olsun s...', ARRAY['Türk Edebiyatı','Şiir','Belgin Turan']::text[], 8.5, '{"poet":"Belgin Turan","poet_slug":"belgin-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rehin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugece', 'bugece-guray-gunes-ez1pw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kursam da hayalini,

Yalnız gözlerimdesin bu gece.

Kapatıyorum gözlerimi,

Sarılıyorum sana kirpiklerimle.

Sen,yağmur ol bu gece,

Rüzgarla gel götür beni.

Islanmam,üşümem asla,

Sevdiğim için seni.

Bu gece sessiz her yer,

Karanlık bile konuşmuyor.

Hayaller küsmüş sevgiye,

Seni bana getirmiyor.

Bu gece gel ne olur! 

Gel,hayallerde sevilmeye.

Sen severken yaşıyordum,

Şimdi gel,sonumu görmeye.

Çok güzel olacak bu gece,

Her şey sona erecek.

Sen bile biteceksin bende,

Kalbim son kez sevecek.

Ne olur bu gece sonum ol! 

Ölüm ol,hayatımı çal! 

Sana ölümsüz bir hatıra; 

Ben ölünce,sevgimi al! 

Haydi çabuk ol,

Neredeyse güneş doğacak.

Bu vakit sevgimin son demi,

Birazdan bende bir aşk batacak.

Sanki eriyorum yavaşça,

İşte geldi, bu son sevmek.

Yokluğunla da olsa ne güzelmiş; 

Seni severken ölmek!', 'Kursam da hayalini, Yalnız gözlerimdesin bu gece. Kapatıyorum gözlerimi, Sarılıyorum sana kirpiklerimle. Sen,yağmur ol bu gece, Rüzgarla gel...', ARRAY['Türk Edebiyatı','Şiir','Güray Güneş']::text[], 8.5, '{"poet":"Güray Güneş","poet_slug":"guray-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bugece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanları yapıştırmalıyız', 'i-nsanlari-yapistirmaliyiz-ali-veli-4m6qk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ahenkli duyulan patlama sesi

Buna eşlik eden insan sesleri

Piyano tuşlarından çıkan melodiler gibi

Muazzam bir savaştı yaşanılan

Kolu kopan bir askerin seslenişi:

Bantlar gerekli kopuk kola...

Yardım edin şu küçük kahramana

Cerrahların yıllarca düşlediği

Dokuları anında yapıştıran bir madde

Çaresiz askerin umudu

Çözüm getirendi bilimin bulduğu

Düşünülmeyen savaşın nedenselliği

Algılanmayan fiziksel acı

Dillerden düşmeyen zihinsel boşluk

Organları yapıştırmalı

Eksiklik olmamalı

Yaralının yerini sağlamı almalı

Kolayı parçaların,organların yapıştırılması

Savaşın zihinde oluşturduğu hastalık

Şifası zor bulunanı

Düşünülmesi gereken sorunun şahı

İnsandan kopan barış ve sevginin yarattığı acı

İnsanları yapıştırmalıyız', 'Ahenkli duyulan patlama sesi Buna eşlik eden insan sesleri Piyano tuşlarından çıkan melodiler gibi Muazzam bir savaştı yaşanılan Kolu kopan ...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/insanlari-yapistirmaliyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne diycem.(Bestelenmiş şarkı sözü) ..MP3 Formatında (Özlem''den) dinlemek için tıklayın', 'ne-diycem-bestelenmis-sarki-sozu-mp3-formatinda-ozlem-den-dinlemek-icin-tiklayin-cengiz-suslu-bqvvd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her sabah güneşle uyanmadık mı? 

Kuşlarla kahvaltı yapmadık mı? 

Çiçeklerle,böceklerle,sibel''lerle..

Hayatı paylaşmadık mı? 

Ne oldu,ne oldu toplamış valizini gitcen mi? 

Ne oldu,ne oldu bir kalemde beni silcen mi? 

Söyle bir daha beni sevmiycen mi? 

Ne diycem kuşlara,

ne diycem çocuklara,

ne diycem arkadaşlara

Susma..

Ne diycem çiçeklere,

ne diycem böceklere,

ne diycem sevinç''lere

Hadi cevap ver.

Ne diycem akşamlara,

Ne diycem yıldızlara

Mehtaba hatta aya

Susma..

Ne diycem anneme,

ne diycem babama,

ne diycem ablama

Hadi cevap ver...

Söz-Müzik:Cengiz Süslü', 'Her sabah güneşle uyanmadık mı?  Kuşlarla kahvaltı yapmadık mı?  Çiçeklerle,böceklerle,sibel''lerle.. Hayatı paylaşmadık mı?  Ne oldu,ne oldu...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-diycem-bestelenmis-sarki-sozu-mp3-formatinda-ozlem-den-dinlemek-icin-tiklayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Övgü', 'ovgu-meral-vurgun-ofdbz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'umarım ki sıcaktır etrafı kıçının. 

sarışın melek, senin şarkı söyleyişin martıları bile baştan çıkarır; 

susar ona kuşlar ve dinlencesi parlaklığın. Amin

yaslanıp radyatöre ve

pencereyi açmışsın.

ben güllerini düşlemişim, inceliğini ve yumuşaklığını

kanatlarla örtünüşünü

sarışın melek, senin sade durgunluğunu seviyorum

mahzun duruşunu 

doldur beni, ah tatlı dişi, 

gözlerim bacaklarına doğru sürünür,

sen edebiyat gibi açılırsın. yavaşça.

bir yılan ısırışı gibi bayılır 

senin asil bakışın, bu Tanrı’ya küfretmektir

beni sana diliyorum, ölü ağaçlar yatıyor

yolumun üstünde. düşmüşler, sadece yaşlı gövdeleri

beni sende umuyorum

sen süt bağışlıyorsun, zarifçe yüzüme damlıyor

ki sadece düşlüyoruz, sen ve ben 

ve sen ve ben

kaldır örtünü, şaşkın melek bana mutluluk bahşet 

sıcağa yaslanıyorsun 

ve soğuk umuyorsun

sarhoş, ol, seninle içiyorum, balon düşünceleri öldürüyoruz

kendimizi akışına bırakıyoruz kaosların

hava balkonlarında dansediyoruz içinden geçerek bulutların 

şimşekleri öpüyor, yıldırımları kucaklıyoruz

umarım yaşıyorsun, sarışın melek 

sana güveniyorum 

sen bana hala hep deli diyorsun 

seni rüyalara salıyorum

ben düşüyorum, kollarına düşüyorum ve tüylerine konuyorum

say ki sarılmışsın yumuşacık ve dikkatlice esyior rüzgar 

sen sanat sayfasısın dilek gazetesinin. buruşturulmuş

benim aşkım manasızdan yaklaşıyor 

serçeler çitlerde sağa sola zıplıyor

sağa sola. İncecik ayakları üzerinde

ben Mozart’ı dinliyorum, kimileri Tanrısallıktan söz ediyor

o senin dudaklarından akıyor. güçlü ve görkemli

radyom hışırdıyor, algısı berbat

Mozart çok erken ölmüş

umarım sen yaşıyorsun sarışın melek 

benim dünya aşkım senden yakınlaşıyor 

senin sessiz ve 

senin sesli melodilerinden kendi kendini yaratıyor

sen 40 nolu senfonisin

ben sende uyanıyorum

sende uyuyorum

tüylerine düşüyor ve yazıyorum

onlarla yazıyor ve onlarla düşlüyorum

bir şekilde horluyorum seni, bu kesin bana bağlı 

heyecanla anmak ve alaya almak

bazı durumlarda senin mizahın müşkül

benim yüreğimde keskin bir güneş 

bir şekilde yüceltüyorum seni, bu kesin sana bağlı

...

gel bir kahve içmeye gidelim 

hep böyle hayal kurmamalıyız

bu gün ender bir gün

ben hep böyle hayaller kurmamalıyım sarışın melek 

sen hoplayıp zıplayan serçe

bırak kahvede yabancıları seyredelim 

belki seni tanırım. Hem de beni 

arasıra kinlenirim. Hüzün sızlatır

cümleler nasıl: Umarım sıcaktır etrafı kıçının 

sarışın melek. 

René Herder 

Çevriren (übersetzt)  Meral Vurgun



Hymne 

Ich hoffe es ist warm um deinen Arsch herum.

Blonder Engel, dein Gesang verführt sogar die Möwen; 

schweigt, ihr Vögel, und lauscht der Herrlichkeit. Amen.

Du lehnst an der Heizung und 

hast das Fenster geöffnet.

Ich träume von deinem Rosa, deinem Zart und deinem Weich.

Du bedeckst dich mit den Flügeln.

Blonder Engel, ich liebe deine seichte Depression,

deinen bedrückten Zustand.

Erfülle mich, oh süßes Weib,

meine Augen kriechen hin zu deinen Beinen,

du öffnest dich wie Literatur. Langsam.

Ein Schlangenbiss und ohnmächtig wird

dein arroganter Blick, das ist Blasphemie.

Ich hoffe mich zu dir, es liegen tote Bäume

am Rande meines Weges. Sie sind gefallen, alte Stämme nur.

Ich hoffe mich in dich. 

Du spendest Milch, tropfst sie anmutig in mein Gesicht.

Wir träumen doch nur, ich und du

und du und ich.

Entblöße dich, verwirrter Engel und schenke mir das Glück.

Du lehnst am Warm und

bittest herein das Kalt. 

Betrinke dich, ich trinke mit, wir töten die Ballongedanken

und begeben uns in den Zustand sicheren Wirrsals. 

Tanzen wir auf Luftbalkonen durch die Wolken.

Küsse die Blitze und umarme den Donner. 

Ich hoffe du lebst, blonder Engel.

Ich vertraue dir.

Du nennst noch immer mich den Narr.

Im Traume schieße ich in dich.

Ich falle, falle in deine Arme und lande auf Federn,

werde umhüllt vom Sanft und der Wind bläst vorsichtig,

du bist das Feuilleton der Wunschzeitung. Du bist zerknittert.

Meine Liebe nährt sich vom Widersinn,

die Spatzen hüpfen auf den Zäunen hin und her

und her und hin. Auf ihren schmalen Füßen.

Ich höre Mozart, manche reden von Göttlichkeit,

er fließt durch deine Lippen. Kraft und Eleganz. 

Mein Radio rauscht, der Empfang ist schlecht.

Mozart ist sehr früh gestorben,

ich hoffe du lebst, blonder Engel.

Meine Weltliebe nährt sich doch von dir,

sie schafft sich selbst aus deinen leisen und

deinen lauten Melodien.

Du bist die Symphonie Nr. 40,

ich wache mit dir auf,

ich schlafe mit dir ein,

falle in deine Federn und schreibe

mit ihnen, schreibe und träume. 

Irgendwie verachte ich dich, es liegt wohl an mir.

Schwärmen und höhnen.

Dein Humor ist brenzlig in mancher Situation,

er ist eine gellende Sonne in meinem Herzen.

Irgendwie verehre ich dich, es liegt wohl an dir.

...

Lass uns einen Kaffee trinken gehen,

wir dürfen nicht so lange träumen,

es ist lichter Tag.

Ich darf nicht so lange träumen, blonder Engel,

du hüpfender Spatz.

Lass uns im Café das Fremde beobachten.

Vielleicht erkenne ich dann dich. Und mich.

Ab und zu werde ich gehässig. Traurigkeit wimmert

Sätze wie: Ich hoffe es ist warm um deinen Arsch herum.

Mein blonder Engel.

René Herder', 'umarım ki sıcaktır etrafı kıçının.  sarışın melek, senin şarkı söyleyişin martıları bile baştan çıkarır;  susar ona kuşlar ve dinlencesi par...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":136,"source_url":"https://www.antoloji.com/ovgu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuksu Duygular-(Bestelenmiş şarkı sözü..Cüneyt''ten dinlemek için tıklayın)', 'cocuksu-duygular-bestelenmis-sarki-sozu-cuneyt-ten-dinlemek-icin-tiklayin-cengiz-suslu-ejuou', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocuksu duyguların esiriydim o zaman

Hiç bir art niyetim yoktu içimde

Ateşler sarardı dünyamı dört yanından

Utanırdım gururumdan sana olan sevgimden..

Sana bir kez olsun seviyorum diyemedim

Yaşadığım aşkımı hasretimi gizledim

Elini eller tuttu yanına gelemedim

Sevdim,ağladım,yandım

Şimdi yine senleyim seninleyim bilesin

Ben yine aynı yerde sen bilmem ki nerdesin

Utancımdan demedim derdime sen sebepsin

Ben seni unutmadım sen bunu bilmelisin', 'Çocuksu duyguların esiriydim o zaman Hiç bir art niyetim yoktu içimde Ateşler sarardı dünyamı dört yanından Utanırdım gururumdan sana olan s...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cocuksu-duygular-bestelenmis-sarki-sozu-cuneyt-ten-dinlemek-icin-tiklayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık...', 'i-nsanlik-ali-veli-3w00t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsanı verdim dedi gür bir ses

İnsanlar haykırdı

Bizi verdin sen

Toplanalım dedi insanlar

Düzen kuralım uyum sağlayalım

İnsan olalım dediler insanlığı yaratalım

İnsanlığı yarattılar farkında olmadan

Sevgiyi...

Anlayamadılar yarattıklarını

İnsanlık sevgisini

Bağlıyız dediler seviyoruz

Neyi dedi birisi

Öteki,sevgiyi insanı sevmeyi

Hayır diye haykırdı bir tanesi

Yaşamı seviyoruz kendimiz için yaşamayı

Farkı yaratandı konuşan

Sıradanlığı aşan benliğini bulan

Sevginin tanımını soran

Cevaplar yoğundu kalabalıkta

Çözüme ulaştırmayan kendini avutan

Sevgiyi bilmeli dedi bilge

Varlığını sezmeli varlık nedir bilmeli

O halde diye söylendi insanlar

Nasıl sevmeli

Bilge cevap verdi onlara

Kendini insanlığı yaşamı bilmeli

Sevileni sevmeli sevilmeyi sevmeli...', 'İnsanı verdim dedi gür bir ses İnsanlar haykırdı Bizi verdin sen Toplanalım dedi insanlar Düzen kuralım uyum sağlayalım İnsan olalım dediler...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/insanlik-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşleyen çarkın anlaşılmaz planı', 'i-sleyen-carkin-anlasilmaz-plani-ali-veli-happg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tek bir düşüncede karışmışçasına yoğunlaşmak

Ne istediğini bilmeden sürekli araştırmak

Mutlak olanın kendimiz olduğunu bilmeden

İşleyen yaşam mekanizmasında katılımcı kalmak

Düşlediğimiz senaryoların nasıl gerçekleştiğini bilmeden

Sadece tahminler yürüterek,ispat yüzdeleri arayarak bocalamak

Havada durmadan kanat çırpan kuşun,suda durmadan ilerleyen balığın

Her gün doğan ve batan güneşin,geceleri ışıldayan ayın

Hem yapıcı hem yıkıcı olan doğanın

Bitip tükenmek bilmeyen enerjisinin nereden kaynaklandığını düşünmeden

Kendimizi düşüncesizce bu mekanizmada anlamaya çalışmak

Neden...

Çünkü farkında olan farkında olmadığımız sezilerimiz

Kendimiz değil...

Yıllarca asırlarca durmadan seslenen ses

Bize mutlak olanı söyleyip duruyor

Biz her defasında durmadan duymamazlıktan geldiğimiz halde

Kendimize dönmeliyiz...', 'Tek bir düşüncede karışmışçasına yoğunlaşmak Ne istediğini bilmeden sürekli araştırmak Mutlak olanın kendimiz olduğunu bilmeden İşleyen yaşa...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/isleyen-carkin-anlasilmaz-plani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru(n)', 'soru-n-arjin-murad-cjo6n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dümdüz bir yolda daracık bir köşeye sıkıştınız mı hiç_? 

yada engelsiz engellere takıldınız mı_? 

pervasızca koçmak varken...

süründünüz mü hiç yerlerde? 

güneş aydınlatırken dünyayı karanlıklarda kaldınız mı? 

mırıldanmayın öyle ''''ne oldu yaw'''' diye..

varlığın yokluğunu çekmediyseniz eğer..

tek varın ''''yok''''  olduğu yerden geçtimi yolunuz...? 

leş kargalarıyla bölüştünüz mü hiç canınızı? 

kartallara sundunuz mu yüreğinizi? 

geçeyim bunları isterseniz....

peki...

ömrüne ömrünüzü verdiklerinizin ömrü  tükendi mi karşınızda? 

boş verin beni ve  bu saçma sorularımı...

 bu gün herşey soru(n)  zaten,

yada bir kez olsun düşünün...

ama unutmayın! 

hiç birini

    sormak için

                sormadım...

1ağsts2004

  ikitelli/ist', 'Dümdüz bir yolda daracık bir köşeye sıkıştınız mı hiç_?  yada engelsiz engellere takıldınız mı_?  pervasızca koçmak varken... süründünüz mü ...', ARRAY['Türk Edebiyatı','Şiir','Arjin Murad']::text[], 8.5, '{"poet":"Arjin Murad","poet_slug":"arjin-murad","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/soru-n-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte öyle...', 'i-ste-oyle-ali-veli-dkd3b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sınırsızdı

Sıcak bir kuytunun bunaltısında

Bir bebek çığlığı duymuşçasına 

İrkildim

Sıcağın kaynağına doğru

Tüm boşluklarım ışık doldu

Bilmediğim

Başımı yavaşça çevirip aşağılara baktım

Bilmediğim karanlıklarıda gördüm

İrkildim

Her şeyim çevrilivermiş hiç bir şeyle

Donuk

Titredim delicesine üşüdüm

O sesi bekledim

! ..

Yok 

Nefretlendim

Işık yandı söndü yandı söndü

Koca bir karanlık bende koca bir...

Bir tünel içinde

Zaman zaman gördüğüm ya da

Gördüğümü zannettiğim ışığın peşinde

Tüm etsilliğimle ve tinselliğimle

Delicesine

Koşturuyorum

Başka bir şey bilmiyorum

İlk önce idimi kaybettim

Şimdi de benimi galiba...', 'Sınırsızdı Sıcak bir kuytunun bunaltısında Bir bebek çığlığı duymuşçasına  İrkildim Sıcağın kaynağına doğru Tüm boşluklarım ışık doldu Bilme...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/iste-oyle-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaos', 'kaos-ali-veli-af9uu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gariplikler dünyası...

Tam bir fiyaskodayız

Dönüşü olmayan bir yol bu

Sonuçlarını düşünmek bile korku verici

Zararın neresinden dönersen kardır misali

Tabiata dönmeliyiz', 'Gariplikler dünyası... Tam bir fiyaskodayız Dönüşü olmayan bir yol bu Sonuçlarını düşünmek bile korku verici Zararın neresinden dönersen kar...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kaos-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık', 'karanlik-ali-veli-o22u2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ölüm ilanıdır

Umutlar biçimlenmeden

Kendini gösteremeden

Ardında mutsuz insan

Körelen inançlar

Amaçların hazin sonu

Boş bir sürünceme

Umut ışığı söndü

Mavi ışık yok artık

Mavikuş ile birlikte

Sessiz ve boş bir gülümseyiş

Yüzyılımızın masum kurbanı

Tüketilen insanlık ve sahibi insan

Her şey karanlık artık...

...

Yanıldım,duyduğum mavinin kanat sesleri...', 'Bir ölüm ilanıdır Umutlar biçimlenmeden Kendini gösteremeden Ardında mutsuz insan Körelen inançlar Amaçların hazin sonu Boş bir sürünceme Um...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karanlik-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşılıksız sevgi', 'karsiliksiz-sevgi-ali-veli-9lb9v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seviyordu delicesine

Farkında değildi umursamaz tavrın

Hayaller hayalleri kovalıyordu

Hiç bitmiyordu onunla geçirdiği anlar

Her gördüğünde onu

Sarıyordu benliğini

Hiç bitmesin istiyordu

Duyduğu sevginin birikimi

Farkında değildi sevilen

Bilseydi bu kadar sevildiğini

Severdi belki ötekini

Duyulan sevgiler başkaydı

Bitmeliydi karşılıksız sevgi

Bitiremiyordu seven

Değer veremiyordu sevilen

Seven anlayınca sevilmediğini

Ölümsüzleştirmek istedi sevgisini

Duygularını döktü bir gün kağıda

Ebediyete kadar sürsün diye

Hayatına son vermişti seven 

Sevdiği kişinin kendisini sevdiğini bilmeden

Tek bir hatası vardı eserin

Sevgi nedir bilmeyen

Bir meçhuldün sen...', 'Seviyordu delicesine Farkında değildi umursamaz tavrın Hayaller hayalleri kovalıyordu Hiç bitmiyordu onunla geçirdiği anlar Her gördüğünde o...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/karsiliksiz-sevgi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemek sözü verdiğim...', 'yemek-sozu-verdigim-reyhan-tataroglu-afyfv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çark

