INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karışığım Mayıslarda', 'karisigim-mayislarda-suheyl-turkoglu-p89eo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mayıslarda yaşamıştım

Aşk sarhoşluğunu

Lise tenefüslerinde

Acemi öpüşmeyi.

Ondokuz  Mayıslar,

Bahar şenlikleri,

Mutlu ederdi

Diriltirdi gençliği.

Bağırmak isterdik,

Ses şamarlaşırdı 

Suratlarımızda

Bir Mayıslarda.

Hep ağladım

Yetim çocuklara,

Kutlarken buruktum

Anneler Gününü.

Yine karışığım

Bahar çiçeklerini

Toplarken,

Mayıslarda..', 'Mayıslarda yaşamıştım Aşk sarhoşluğunu Lise tenefüslerinde Acemi öpüşmeyi. Ondokuz  Mayıslar, Bahar şenlikleri, Mutlu ederdi Diriltirdi genç...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/karisigim-mayislarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasap dükkanı', 'kasap-dukkani-reyhan-tataroglu-m0r5f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her

