INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O hayalin gölgesi', 'o-hayalin-golgesi-cetin-hacifettahoglu-jvfoa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamak bazen acı doludur

Ansızın hayal olur gerçekler

Kaçtığın tüm yalanlar

Gerçek olur bir gece vakti

Kan ter içinde 

Uyandığında bir sabah

Gözlerini kapayıp serinlersin

O hayalin gölgesinde

Koca bir çınar gibidir hayaller

Her dalında salıncak

Bir iner bir binersin

Kimi zaman dal kırılır

Düşersin gölgesine

Öfken olur kırılan dal

Yerden alır vurursun yerlere', 'Yaşamak bazen acı doludur Ansızın hayal olur gerçekler Kaçtığın tüm yalanlar Gerçek olur bir gece vakti Kan ter içinde  Uyandığında bir saba...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/o-hayalin-golgesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selamsız sabahsız', 'selamsiz-sabahsiz-reyhan-tataroglu-47fsd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kaç

                                  yolcu

                                  geçti...

                                  bu

                                  handan

                                  bir 

                                  ben

                                  miyim

                                  hancı

                                  herkese

                                  selam

                                  candan

                                  bir

                                  ben

                                  miyim

