INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tutam Aşk', 'bir-tutam-ask-ahmet-agdere-o2tgm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Maviye çalardı gözlerin,

Gözlerin sürpriz çalardı.

Sana bakış,bir tutam aşktı,

Sevdaya dalardı gözlerin.

Çevren zifirden gül bahçesi,

Cehennemden kuşlar konardı.

Zorda bırakan ellerin ki,

Bana dokunmadan yanardı.

Baktığım her deniz gibi..', 'Maviye çalardı gözlerin, Gözlerin sürpriz çalardı. Sana bakış,bir tutam aşktı, Sevdaya dalardı gözlerin. Çevren zifirden gül bahçesi, Cehenn...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-tutam-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel gayrı!', 'gel-gayri-reyhan-tataroglu-32rco', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'geleceğim

