INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diken', 'diken-mehmet-isikoglu-77o4v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çiçekler içinde bir gül kokladım

Koparmak istedim baktım kopmuyor

Kopan çiçekleri bir bir yokladım

Hiç biri gönlümde bir yer yapmıyor

Meftun etti beni içime sindi

Koparabilsem de alsam diyorum

Gizemli yaşamak istiyor kendi

Görmeden sabahı zor ediyorum

Hayat verir onun hayali bana

Ruhumun gıdası gönlümün yari

Ölmeden kavuşmak isterim ona

Arada dikenler olmasa bari', 'Çiçekler içinde bir gül kokladım Koparmak istedim baktım kopmuyor Kopan çiçekleri bir bir yokladım Hiç biri gönlümde bir yer yapmıyor Meftun...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/diken-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Diyorsun', 'gel-diyorsun-engin-hascelik-wql2b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beklemekle günler geçmiyor 

Hiçbir şeye gücüm yetmiyor

Kara günler üzerimden gitmiyor 

Gel diyorsun nasıl geleyim

Her satırın matem dolsa da 

Sevdiklerim bir-bir kayıp olsa da 

Göz yaşların buram buram aksa da 

Gel diyorsun nasıl geleyim

Bakıp da ağlama sisli yollara 

İnanma açılan yalan fallara 

Allah sabır verir seven kullara 

Gel diyorsun nasıl geleyim', 'Beklemekle günler geçmiyor  Hiçbir şeye gücüm yetmiyor Kara günler üzerimden gitmiyor  Gel diyorsun nasıl geleyim Her satırın matem dolsa da...', ARRAY['Türk Edebiyatı','Şiir','Engin Hasçelik']::text[], 8.5, '{"poet":"Engin Hasçelik","poet_slug":"engin-hascelik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-diyorsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-guzin-eye-dundar-lxnm4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç  kimse tutsak edemez onu

ne  başlamak yeniden

ne engellemek sonu

saçımızdaki her ak onun oyunu

yüzlerdeki çizgilerden odur sorumlu

bütün gidişlerin en son nefesi

tohumun umudun tek beklentisi

çürütüp yokeder yaşarken sizi

değişmez hükmüdür 

evrenin  zaman.', 'Hiç  kimse tutsak edemez onu ne  başlamak yeniden ne engellemek sonu saçımızdaki her ak onun oyunu yüzlerdeki çizgilerden odur sorumlu bütün...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zaman-287-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşler nasıl? ? ! ! ...', 'i-sler-nasil-reyhan-tataroglu-83hy5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey! yolcu 

                            yolunda mıdır ki işlerin

                            yoksa meçhule midir gidişlerin

                            bir tutam zevkin şaştın elinden

                            geleceğin telaşına vazgeçtin dünden

                            kendine bir ayna seç, çeki düzen ver

                            edepsizlikle değil, haya ile ever

                            nice fazilet hasıl olsun her damlandan

                            görünce seni işte''''O'''' diye saysınlar adamdan

                            hoşgörünü geniş tut, boğazına  çök horun

                            seni sevgi ile yad etsin eş,dost, torun

                            güzele ulaşmak için kötüye katlanmak gerek

                            kötüden kurtulursun, ancak güzeli severek 

                            başlanmamış bir iş asla bitmez

                            en güzel düşünce bile başlamaya yetmez

                            yanlışta olsa yürümek gerek doğruya

                            biçmeli yanlışları yürürken doğruya doğruya

                            Ey! yolcu

                            yolun sonu yaklaşıyor oyalanmayı bırak

                            yine mevsimi geliyor, hazanda düşecek bir yaprak

                            çam ağacıyım diye güvenme çamına, gövdene

                            biliyor musun çam ağacıda devrilir döne döne', 'Ey! yolcu                              yolunda mıdır ki işlerin                             yoksa meçhule midir gidişlerin                  ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/isler-nasil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Herşeyden Çok Seviyorum', 'seni-herseyden-cok-seviyorum-murat-kilic-2-tkicb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kar kapladı yine yolları.

hiçbir caddeden sokaktan ses gelmiyor artık

ne bir siren sesi ne de köpeklerin uğultusu.

ıslak ıslak bir kar tanesi düşüyor omzuma

dünü düşünüyorum ve bir de seni....

yıldızlar kadar sonsuz 

bir mehtap kadar parlak hayallerini düşünüyorum.

sende açan her çiçeğin 

sende filizlenen her güzelliğin içine

gözlerimi de ekliyorum artık biliyor musun.

her soluk alıp verişimde seni içime çekiyorum.

tüm beklenesi yerlerde seni bekliyorum.

ben senle doğdum

sadece senle varım

sadece senle yaşıyorum.

penceremde güneş gözlerimde ümit var.

çünkü seni herşeyden çok seviyorum.', 'kar kapladı yine yolları. hiçbir caddeden sokaktan ses gelmiyor artık ne bir siren sesi ne de köpeklerin uğultusu. ıslak ıslak bir kar tanes...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-herseyden-cok-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmeden Ölüm varmış', 'olmeden-olum-varmis-umran-aldic-zomdd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölmeden ölüm varmış.

Dünya ne kadar darmış.

Sevenlerin kalbini 

Dikenli güller sarmış.

Bülbül gülü görünce,

Güzelliği ne kanmış.

Dikenleri batınca,

Yürekten yaralanmış.

Sevgi acımı, sizce? 

Üzüntü, gözyaşı mı saklar peşinde? 

Ya unutulmak....

Tarifi imkansız kahroluş bence...', 'Ölmeden ölüm varmış. Dünya ne kadar darmış. Sevenlerin kalbini  Dikenli güller sarmış. Bülbül gülü görünce, Güzelliği ne kanmış. Dikenleri b...', ARRAY['Türk Edebiyatı','Şiir','Ümran Aldıç']::text[], 8.5, '{"poet":"Ümran Aldıç","poet_slug":"umran-aldic","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olmeden-olum-varmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesai', 'mesai-akin-kelesoglu-cjvn0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün batımında

Eve dönmek

Filede, sıcak bir ekmek

Bir otobüs bileti

Bir çiçek elde

Ve 

Cebinde bir şiirle.', 'Gün batımında Eve dönmek Filede, sıcak bir ekmek Bir otobüs bileti Bir çiçek elde Ve  Cebinde bir şiirle....', ARRAY['Türk Edebiyatı','Şiir','Akın Keleşoğlu']::text[], 8.5, '{"poet":"Akın Keleşoğlu","poet_slug":"akin-kelesoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mesai-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Diye?', 'ne-diye-aydin-bastan-3cpss', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aylar gelip yillar gecse aşk bitmez

sen gitsen de gönlüm senden hiç gitmez

beklerim yillarca nazlim gel diye

madem yollar ayri bu sevda niye? 

zorlamam güzelim mutlak sev diye

madem yollar ayri bu sevda niye? 

bilmelisin sevda ciddiyet ister

oki sevmiyorsun mazeret  göster

yillarca söyledim ben dönmem diye

gönlümügönlüne verdim hediye

o zaman sevgimi kabul etmiştin

şimdi yerden yere vurmak ne diye?', 'aylar gelip yillar gecse aşk bitmez sen gitsen de gönlüm senden hiç gitmez beklerim yillarca nazlim gel diye madem yollar ayri bu sevda niye...', ARRAY['Türk Edebiyatı','Şiir','Aydın Baştan']::text[], 8.5, '{"poet":"Aydın Baştan","poet_slug":"aydin-bastan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-diye-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçeğim', 'cicegim-ali-biyikli-romantik-hfgct', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben her bahar değil, bir kere âşık olurum! 

Hayallerim çatlar, umutlarım tükense de

Varlığının kalbimde yer kuracağını,

Rüzgârın seni bana getireceğini biliyordum.

Masum bakışlarının, masun bekçisiyim

Yüreğimden fırlayıp taşan aşkın,

Tek sahibi, tek gülüsün,

Kolay kolay rastlanmayan, yıldız çiçeği gibi,

Sevdalanmış benim gül yüzlüm,

Aşkı bu sefer başka bahara ertelememiş,

Sevgimi beklemiş sevmek için, kalbimi beklemiş

Yemin olsun sadece seninim.

Kalpler bir artık, ırak olsak ta

Umutlar bir, şarkımız bile aynı,

Kaderde bize yol çizmek istemiş,

Uzun uzun… mutluluk kokuyor sanki

Gül yüzlüm! 

Hatırlar mısın kenetlenip, cenneti gördüğümüz o anı,

Gözyaşlarına değer miydi ağlama sen,

Bu kadar hüzün de fazla

Bak ninniler söylüyorum, bahar da geliyor.

Tıpkı benim gibisin….

 Ali Bıyıklı (Romantik)', 'Ben her bahar değil, bir kere âşık olurum!  Hayallerim çatlar, umutlarım tükense de Varlığının kalbimde yer kuracağını, Rüzgârın seni bana g...', ARRAY['Türk Edebiyatı','Şiir','Ali Bıyıklı (Romantik)']::text[], 8.5, '{"poet":"Ali Bıyıklı (Romantik)","poet_slug":"ali-biyikli-romantik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/cicegim-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yargı', 'yargi-ahmet-zekai-yildiz-9hhl7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Metropoliten insan çöplüklerinde

Düzen engizisyonları kurulmuş bizim için

Baykuş gözlü kameraların önünde

Kısacık ömürlere sığmayan

Yüreğimiz yargılanacakmış

Bir lokma ekmek adına

Fukaralık giyotiniyle düşen

Suskun başlarımıza

Son isteklerimiz sorulacak 

Kundaklanan kavruk bedenlerimiz

Alınterimizle yıkanacakmış

Ve başucumuza çakılan eğreti tahtalara

Hiçbir şey yazılmayacakmış.', 'Metropoliten insan çöplüklerinde Düzen engizisyonları kurulmuş bizim için Baykuş gözlü kameraların önünde Kısacık ömürlere sığmayan Yüreğimi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yargi-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Dua', 'son-dua-abdulkadir-ogdum-ycoz9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Deniz bakışlı âmâ bir kıza...

Yaşlarının varını-yoğunu toplayıp gittiği

ve hakkıyla bir çift tortu bıraktığı gözleri hatrına,

semâsı hiç lâcivert olmasın! 

Olmasın ki, ben de göreyim...

Garib Kaptan''lığımdan bilirim deniz yağmurunu...

Ne zordur, sığınacak tek bir yer bulamazsın! 

Allah''ım, onu hiç ağlatma,

varsın, ben ağlamaktan öleyim! 

27.01.2006

23:24', 'Deniz bakışlı âmâ bir kıza... Yaşlarının varını-yoğunu toplayıp gittiği ve hakkıyla bir çift tortu bıraktığı gözleri hatrına, semâsı hiç lâc...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Öğdüm']::text[], 8.5, '{"poet":"Abdulkadir Öğdüm","poet_slug":"abdulkadir-ogdum","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/son-dua-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir Türküsü', 'i-zmir-turkusu-ahmet-zekai-yildiz-h18yr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Be hey Yunan! 

Perki yiyip,uzo içemedin ya.

Sirtyaki de oynayamadın.

Berk-pulat gencimiz,

Senin delişmen oğlanına

Kurban olur mu sandın? 

Ben İzmir''im.

Bağrımda efeler dolaşır,

Görünce yüpürdüğün.

İzmir''in kavakları uzun-ince.

Dökülür yaprakları, hey! 

Dökülür düşman,

Efem, hey! hey! 

Sökülür emperyalizm.', 'Be hey Yunan!  Perki yiyip,uzo içemedin ya. Sirtyaki de oynayamadın. Berk-pulat gencimiz, Senin delişmen oğlanına Kurban olur mu sandın?  Be...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/izmir-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Sevgili Kravatım', 'elveda-sevgili-kravatim-ahmet-zekai-yildiz-dwlw5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elveda sevgili kravatım.

Memurluk yıllarımda,

Yoksulluğumun simgesi.

İki yakamı bir araya getirip,

Adam yerine koyduran

Yüce kumaşcık elveda.

Senin için ne etsem,

Ne yapsam azdır.

Sıcak günlerin bunaltısında,

Ne çileler çekmiştik seninle.

Bir keresinde:

Müdüre kızıp da

Nasıl fırlatıp atmıştım yere seni.

Özür dilerim.

Çok özür dilerim.

Kalan ömrümce,

Seni evimin

En güzide yerine; 

Örneğin, yatak odamda

Başucuma asacağım.

Yanıbaşında da

Son çektirdiğimiz,

Çerçeveli fotoğrafımız olacak.

Seninle ilgili anılarımı,

Hiç kimseyle paylaşmayacağıma söz verebilirim.

Soranlara,

Rengini desenini filan anlatacağım.

Filanca grafik sanatçısının,

Fişmanca eserinden alıntı, diye...

Böbürlenerek...

Elveda sevgili kravatım.

Dört başı mamur olmayan 

Yıllarımın en gözde süsü, elveda...

Elveda yaşayabileceğim

En güzel ayrılık!', 'Elveda sevgili kravatım. Memurluk yıllarımda, Yoksulluğumun simgesi. İki yakamı bir araya getirip, Adam yerine koyduran Yüce kumaşcık elveda...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/elveda-sevgili-kravatim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçmak', 'ucmak-zafer-yazici-su4h0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Issız bir tepede olsam

Sapasağlam bassam ayaklarımı yere

Bir ben olsam, 

Bir de başımda kavak yelleri

Sonra kaldırıp başımı gökyüzüne baksam

Bir sıçrasam kuvvetli deli gibi

Kollarımı çırpsam yere doğru

Havalanmaya başlasam gökyüzünün engin maviliklerine

İğreti dökülse kollarımdan tüyler

Ve ben koşarak uçmaya başlasam özgürlüğüme

Geride kalsa tozlarla karışık yeryüzü

Bir de yapraklar sonbahardan kalan

Kurumuş boynu bükük kırılgan

Yukarıdan bassalar başımın üstüne

Ben inadına baş kaldırsam, çırpınsam uçmak için

Sonra kuşlarla yarışmaya başlarken ben

Hiçe saysam hayatı, en tehlikeli dalışlarla

Dalga geçsem, sonra ağlasam haykırarak

Hiç durmadan bağırsam “ben özgürüm” diye

Kanatlarımı çırptıkça yorulmasam

Bir daha inmesem yer yüzene

Süzülsem kendimce divane gibi

Dolaşsam memleket şehir

Sonra oralarda bir yerlerde ölüversem

Gömseler beni en karanlık bulutların koynuna

Yüzüm apak, gönlüm kuş misali

Bir sıkımlık canımı alsalar sıkmadan

Ve her yağmurla beraber iniversem yerküreye

Girip sızı versem aralarına 

Bir fidan annem olsa benim

Babam ise kara toprak

Ve ben tekrar büyüsem 

Tekrar uçsam

Durmadan

Özgürce…', 'Issız bir tepede olsam Sapasağlam bassam ayaklarımı yere Bir ben olsam,  Bir de başımda kavak yelleri Sonra kaldırıp başımı gökyüzüne baksam...', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ucmak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup.2', 'mektup-2-tevfik-mengulluoglu-3710a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün güneşin bütün ışınları bir araya toplandığında,Bir tek amaçta birleşirler? 

Dünyayla ebedi bir yaşam...! 

İşte benim bütün hücrelerim şimdi bir tek amaç için,bir araya geldi sevgili güneşim...

Uzak diyarlardan çıktım yola...

Çoğu zaman ıssız boranlara kimi zamanda hırçın Yağmurlara kaptırdığım oldu...

Her seferinde gelip yüreğimin kuytusuna otururdu yokluğun usul usul..

Karşıma çıksan birdenbire ve bütün bunları yazmama gerek kalmasa diyorum.

Attığım her adımın sonrasında bir soru yuvarlanıyor kılcal damarlarında beynimin! 

Sevgiyle beslenen kalplerin Damarlarında dolaşan,Yaşama sevincinin bir kanadıymış hayat...

Yeniden başlayabilseydik diyorum,koşarak geldiğimiz yolları yeniden yürüyebilseydik.

Hızlı yemek yemekten,daha hızlı giden araba seçmekten,vazgeçebilseydik keşke...

özlemimizi,tuşların arasından kurtarıp çizgili bir kağıda bütün duygularımızı,

damlatarak yazabilseydik..

Soluduğumuz oksijenin Ciğerimizde örgütlenip Dağılmasıdır belkide Yaşamak...

Görebilseydik hızla yaşadığımız hayatın arasında aynı hızla kaybettiklerimizi.

Kılık değiştiren korku ve nefretimizin ocağına bir kar tanesi gibi,

Yayılıp eriyor zaman.Keş kelerle donatılmış bir yaşamın içinde soluk almaya çalışan pusulasız bir yolcuya benzedik.Çırılçıplak dağların bir ucundan,bir ucuna uzanan yaralı bir gecenin bağrından akan aydınlığı,yudumlayabilseydik her sabah..

Ve ıslak soluklarından buğuya bulanan evlerin camlarına resim çizen çocuklara,o hayalleri verebilmek...Hüznün doğuşu anlatılıyor Sonbaharın yaprak uçlarında.

Şimdi sen muhtemelen oturmuş yalnızlığını parçalara ayırmaya çalışıyorsundur...! 

Parçaladığın kırıntılar arasında oluşan boşluklara,ne kendin inandığın nede bana inandırdığın hayaller kuruyorsun benim gibi..! Biliyor musun...? 

İçim Gidiyor aslında.! Senden binlerce kere daha yalnız oluyorum,sana bunları yazarken? Beynimde dönüp dolaşan bir sözcüğün peşinden dolanıyorum öylece,tam söyleyecekken binlerce kez uzaklaşıyorum kendimden.! 

Yaptığım yolculuklarda yollarında,sağanağa tutulup kaybolduğum bir şehre benziyor yokluğun,soğuktan benzi solmuş cümlelerle bir adres yazıyorum şimdi,sonunu getiremediğim. Yüreğime ıssızlık doluyor konuşamıyorum...

Evlerinin önünde umutları hiç sönmeyen şehirler varmış yollarını bilmediğimiz.

O ateşin dumanı olup bir tütsen diyorum,adresim olsan üstüme sinsen uzak diyarlardan.

Karanlık çökünce sen benim dolunayım,sabahları üşüyünce camıma vuran güneşimdin..

Şimdi ise:Okuduğum kitaplar,her zaman yürüdüğüm yol,aşım,ekmeğim,suyum,teneffüs ettiğim oksijenim? Her şey senin uzaklığında,Beni benden alıp düşüyorlar yollarına...

Hiç olmasaydın diyorum,Hiç tanımasaydım seni? Her şeyi söküp atmak istiyorum şimdi,seni hatırlatan her şeyi,denizi,iyot kokusunu,güneş batımında sevincinden ürperen kelebeklerin hepsini.Ve kendimi,ne varsa sana dair...

Yaz yağmurlarına benzetiyorum seni,biranda bütün dünyamı değiştiriyor,sırılsıklam ediyorsun,sonrasında yakıcı bir güneş ve kupkuru dudaklarla yokluğuna susamış bir yürek

Ayaklanıyor.Tırnaklarımla kanattığım,Sağanak bir gecenin ortasına atıyorum kendimi,ne yana koşsam nafile! Rüzgarın süpürüp yüreğimin avlusuna topladığı kalıntılarının arasında bir çıra gibi tutuşuyorum.Uzak diyarlara savruluyor küllerim yeniden yeşeriyorum defalarca...

Ve yeniden aynı kabusu yaşama ihtimaline rağmen,Defalarca seni yeniden seviyorum...', 'Bir gün güneşin bütün ışınları bir araya toplandığında,Bir tek amaçta birleşirler?  Dünyayla ebedi bir yaşam...!  İşte benim bütün hücreleri...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/mektup-2-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilık Sevgililer', 'ilik-sevgililer-ahmet-zekai-yildiz-j3ffp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün boyu

Okul bahçesine bakışan,

Çorak toprağa dönmüş

Buğday tenli kızlar gülümserdi,

Allı-yeşilli.

Bizi de okula alır mısın

Öğretmenim? der gibi.

Kirpiklerinin arasından bakan

Kara gözleriyle,

Suç işlemişcesine mahçup; 

Başını öne eğerek,

Belli belirsiz titrek bir sesle:

''Günaydın'' diyebilirlerdi.

Suya gitmeyegör.

Getirdiğim testiyi taşırırken,

Kırk yıllık dostlar gibi

Hal-hatır sormaları, yok mu ya? 

Ekmek istediğimde; 

Öyle telaşlı bir yarış içinde,

Elinde ördüğü çorabı

Verecek kadar dalgın,

Eli açık ve sevecen.

Ve geceleri utanmadan

Rüyalarıma gelerek,

Akşama kadar Anadolu soluyan

Tutkulu bedenime,

Aşksız geçen günlerimin

Hesabını sorarlardı.

Ne bulurlardı bende? 

Sorusunun yanıtını,

Tayinim çıkınca anladım.

Ayrılırken,

İlk göz ağrısı yerden:

Bir teki bile gelmedi

Uğurlamaya,

Ilık sevgililerimin.', 'Gün boyu Okul bahçesine bakışan, Çorak toprağa dönmüş Buğday tenli kızlar gülümserdi, Allı-yeşilli. Bizi de okula alır mısın Öğretmenim? der...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ilik-sevgililer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarihin her döneminde Türk Milleti aşıktır hürriyete', 'tarihin-her-doneminde-turk-milleti-asiktir-hurriyete-halil-colak-o4xqs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Allah’ın yarattığı Türk olan millet asla esir alınmaz

Bu Ender millettir tarihte bir daha eşi bulunmaz

Hangi cehennem silahı ile gelsen bu millet yenilmez

Coştu mu bu kahraman milletin önünde  durulmaz

Bak tarihe Mohac’tan başla git kardeşim Niğbolu’ya

 Malazgirt’le başlar kahramanlık uzanır Gelibolu’ya

Sakarya da Türk destan yazar, Türkü olur Anadolu’ya

Kurtuluş Savaşı ders olur şerefsiz zalim olan haçlıya

Ufuklar dar gelecektir bir gün asil olan bu millete

Düşürmesin Allah’ım kutsal olan devletimi zillete

Serden geçen kahramanlar ulaştıracak ebediyete

Tarihin her döneminde Türk Milleti aşıktır hürriyete 

Halil Çolak 28.1.2006 Ankara', 'Allah’ın yarattığı Türk olan millet asla esir alınmaz Bu Ender millettir tarihte bir daha eşi bulunmaz Hangi cehennem silahı ile gelsen bu m...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tarihin-her-doneminde-turk-milleti-asiktir-hurriyete-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güleç Yüzlü Çiçeklerim', 'gulec-yuzlu-ciceklerim-ahmet-zekai-yildiz-9dqhy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saat onu çeyrek geçiyor.

Direksiyon tutar gibi yani.

Yorgun bir gün sonunda,

Uykulu gözlerimden

Okullar geçiyor Anadolu''da.

Çığlık çığlığa..

Ah çocuklar! 

Dört köşe yaşanmayacak yılların

Tutuklusu çocuklar.

Damı akan dersliklerin

Güleç yüzlü çiçekleri.

Sobasında kerme yakarak üşüdüğümüz

Yıllar eskidi.

Beraber yürüdüğümüz 23 nisan''larda,

Coşkulu marşlar söyleyerek; 

Kağıt bayrakları

Heyecanla sallayışınız geçiyor gözlerimden.

Geçiyor, geçiyorsunuz.

Ama mutlaka gülümseyerek geçiyorsunuz.

Saat beşi bir kaç geçiyor.

Hala geçiyorsunuz gözlerimden.

Bitmiyorsunuz.

Bitmeyeceksiniz.', 'Saat onu çeyrek geçiyor. Direksiyon tutar gibi yani. Yorgun bir gün sonunda, Uykulu gözlerimden Okullar geçiyor Anadolu''da. Çığlık çığlığa.....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gulec-yuzlu-ciceklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tombul', 'tombul-ahmet-zekai-yildiz-yewf5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne aşım, ne ocağım kaldı.

Hayatın frizbi oynadığı,

Tencere kapağı gibiyim.

Ey güzel tencerem! 

Tombul sevgilim! 

Haydi yuvarlan geliver.

Bırak, ''kapağını buldu'' desinler.', 'Ne aşım, ne ocağım kaldı. Hayatın frizbi oynadığı, Tencere kapağı gibiyim. Ey güzel tencerem!  Tombul sevgilim!  Haydi yuvarlan geliver. Bır...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tombul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara', 'ankara-ahmet-zekai-yildiz-e64rn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir seymen oyununda,

Hitit aslanıdır; 

Arslanım Ankara.

Başımın tacı,

Başkentim.

Samsunda doğan güneş,

Rasattepe''de batmaz ha! 

Öyle sanıp da

Kanma yobaza.', 'Bir seymen oyununda, Hitit aslanıdır;  Arslanım Ankara. Başımın tacı, Başkentim. Samsunda doğan güneş, Rasattepe''de batmaz ha!  Öyle sanıp d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ankara-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antalya', 'antalya-ahmet-zekai-yildiz-h1day', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Efes''in Meryem''ine söyleyin.

Bergama''nın Zeus''unu çalmışlar.

Kim diye sorulursa,

Dersiniz, hırsız Avrupa.

Kız kalesinde yılan,

Aspendos''ta arya.

Bırak yerinde kalsın,

Hiç olmazsa güzel Antalya.', 'Efes''in Meryem''ine söyleyin. Bergama''nın Zeus''unu çalmışlar. Kim diye sorulursa, Dersiniz, hırsız Avrupa. Kız kalesinde yılan, Aspendos''ta a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/antalya-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* raialar / Çalmana Bırakıyorum Kalbimi', 'raialar-calmana-birakiyorum-kalbimi-mehmet-sidik-dundar-97xya', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'metrekare başına sen düşsen dünyaya

orda burda bırakırdım kendimi fazlasıyla

namus dostu gecelerimde kalman için

bırakacaktım anahtarımı kapıda

ama insan başına hırsız var

insan ağzı payıma düşen hava

sadece senin dudağında kalması için

hünerli notalar iki çekmeli kulağımda

seni dinlediğim şarkılara kalması için

üç gece üç kağıt

bir pencere

hücrelerime kapatmak için 

çalmana iştirak bırakıyorum kalbimi

……..

insan başıma delilik takarak

delik açıyorum 

ahşap kulübemizin duvarına

çomak sokman için

kız parmağı kız dalıyorsun içeri

yakalıyorum seni dışardan yastığıma

ayaklarımdan çekiyorum kendimi sana

naz erkeğinin nazı

……...

bir ay gece

başım kutup buz dağlarında

beynimde donduruyorum seni

hücre başına

sevgi spermleri klonluyorum yüreğimde sana

beşikte erzağımız aç

doymuyorum sana

yanında senim

başında hırsızım

kızmıyorsun hala

ekvatörüne tuttuğum kalbimdeki sıcağın için

bir sabah kalbimi çalıyorsun

açıyorum cenneti

yeminle 

seviyorum seni

belirgin bir satırda deftere geçiyorum

düş''üm kitapta da geçiyor

meryem’in kız dişi etime geçiyor

roman başına tahir’in ısırık haklarına

canımı veriyorum

raialar', 'metrekare başına sen düşsen dünyaya orda burda bırakırdım kendimi fazlasıyla namus dostu gecelerimde kalman için bırakacaktım anahtarımı kap...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sıdık Dündar']::text[], 8.5, '{"poet":"Mehmet Sıdık Dündar","poet_slug":"mehmet-sidik-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/raialar-calmana-birakiyorum-kalbimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamcı', 'aksamci-ahmet-zekai-yildiz-ysbiw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aradığım

Dost söyleşilerdi.

Ak saçımın her telinde,

Her akşam acılar bulduğum; 

Gönlümün mayhoş gülüşüne aldanarak.

Aylak boğuntularda,

İhtiyar olmadan tükenirken,

Rakı bardağında yüzdüğüm meyhanelerin

Soğuk mezeleri tadında,

İki yüzlü tanışlarıydı; 

Selamları sayısınca unutulacak insanla

Sarhoş yaşamak.', 'Aradığım Dost söyleşilerdi. Ak saçımın her telinde, Her akşam acılar bulduğum;  Gönlümün mayhoş gülüşüne aldanarak. Aylak boğuntularda, İhti...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aksamci-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulun Olayım', 'kulun-olayim-turgut-turan-b2dpp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne gecem gecedir ne günüm gündüz                                                         

Göğün güneşisin ay ile yıldız 

Bir bakışta aklım başımdan aldız

Derde derman süren elin olayım

Koluna takmışsın kara kolçağı

Yüzüne çekmişsin ipek pürçeği

Göksünde açılmış cennet çiçeği

Acı merhamet et kulun olayım

Ben seni sevmişim can ile candan

Pare pare etsen ayrılmam sendenm

Kurtar TURGUT’unu bu kara günden

Salın gel sevdiğim yolun olayım', 'Ne gecem gecedir ne günüm gündüz                                                          Göğün güneşisin ay ile yıldız  Bir bakışta aklım b...', ARRAY['Türk Edebiyatı','Şiir','Turgut Turan']::text[], 8.5, '{"poet":"Turgut Turan","poet_slug":"turgut-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kulun-olayim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemal Hoca', 'cemal-hoca-turgut-turan-j7uyy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Açardı kitabı okurdu hece

İlm irfan toplardı yazardı gece

Çok kişi okuttu genç ile koca

Kültürü yayardı hep Cemal Hoca

Zaman okulları köy odaları

Okumak yazmaktı hep çabaları

Başına toplardı son babaları

Kültürü yayardı hep Cemal Hoca

Hocanın cemaati vaizi olsam

Okullar yaptırıp ismini koysam

Ben de torunuyum bunları görsem

TURGUT’un rüyası hep Cemal Hoca', 'Açardı kitabı okurdu hece İlm irfan toplardı yazardı gece Çok kişi okuttu genç ile koca Kültürü yayardı hep Cemal Hoca Zaman okulları köy od...', ARRAY['Türk Edebiyatı','Şiir','Turgut Turan']::text[], 8.5, '{"poet":"Turgut Turan","poet_slug":"turgut-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cemal-hoca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtulamazsın', 'kurtulamazsin-hifzi-ozbekmez-f2fv1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KURTULAMAZSIN

Bedduamı almışsın sen 

Kaçsan da kurtulamazsın

Ah almada şahinim ben

Uçsan da kurtulamazsın

Aşkın ahu zarından da 

Cehennemim narından da

Kısa günün karından da

Geçsen de kurtulamazsın

Dere tepe geçsen nehir

Mutluluğu etsen tehir

Kendi ellerinle zehir

İçsen de kurtulamazsın

Ömrün ahım kıskacında

Siyah kalmasın saçında

İdamı dar ağacında

Seçsen de kurtulamazsın

Latifi eyledin zayi

Unuttum günleri ayı

Arpa ekipte buğdayı

Biçsen de kurtulamazsın

08  EKİM  2005  SAAT: 21:00', 'KURTULAMAZSIN Bedduamı almışsın sen  Kaçsan da kurtulamazsın Ah almada şahinim ben Uçsan da kurtulamazsın Aşkın ahu zarından da  Cehennemim ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kurtulamazsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonrasızlığın öncesi', 'sonrasizligin-oncesi-ali-veli-zij53', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sonrasızlık -daha- sessizliği

Kıyılara vurmuş hüznün ölümsüzlüğü

Çığlık yalnızlığın sireni

Promethe dingin acılarında

Taşlar yanıyor devingenliğin görevinde

Albatroslar yola çıkmış simurgsuz

Bense bir tüy hafifliğinde sessiz

Kıvılcımlar halinde yaşam,kıvılcımlar yıldız

Bir dolunaydır benim aynam

Belirsiz suretler yaratan

Bir yol var biliyorum

Bir turna var biliyorum

Küçük insanları taşıyan ütopyaya

Ve sen varsın belirsiz,bilmediğim

Hiç göremediğim ama varlığını sezdiğim

Nerdesin,hangi mekana ve zamana aitsin

Gel artık,tüketiyorum tüm umutlarımı

Yıldızım söndürüyor ışığını

Biliyorum milyarlarca yıl önce sönmüş olsada

Benim umudum sonrasızlığın öncesinde varolan

İstençlerim...', 'Bir sonrasızlık -daha- sessizliği Kıyılara vurmuş hüznün ölümsüzlüğü Çığlık yalnızlığın sireni Promethe dingin acılarında Taşlar yanıyor dev...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sonrasizligin-oncesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli kanli', 'deli-kanli-zernisan-aydogan-5vrup', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hergün çikma yoluma 

Yapma be deli kanli

Ben geçerken koluma 

Çarpma be deli kanli

Sevmek güçtür güzeli

Besleme her emeli

Ask yolu tehlikeli

Sapma be deli kanli

Sonunda deme eyvah

Gülerim sana kah kah

Ben ne putum nede Allah

Tapma be delikanli', 'Hergün çikma yoluma  Yapma be deli kanli Ben geçerken koluma  Çarpma be deli kanli Sevmek güçtür güzeli Besleme her emeli Ask yolu tehlikeli...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/deli-kanli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımlama gerekliydi', 'tanimlama-gerekliydi-ali-veli-36j6r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk patlamaydı herşeyi başlatan

Sonra sonsuz bir sessizlik

Yayılıyordu küçük olan büyük olmak için

Yeniden başlıyordu herşey

Yepyeni bir erekti düşünülen

Bir defa daha başlıyordu:Başlangıç ve Son

Karanlık ve anlamsızlık,beraberinde korkuyu getiren

Zaman kavramı patlayanla oluşan

Yayılma gibi dönüşsüz olan

Evrenin yaradılışı gibi insandı yaratılan

İçiçeydi ikisi,karışmıştı birbirine

Hücre başkaydı,dokular,organlar,insan,toplum başka

Birliktelikti kompleks olmayı gerektiren

Bütün,birleşmiş,varlığın görüntüleriydik biz

Sadece aksedilen,varlığı ispatlayan

Biz delillerden öteye gidemedik

Varlığımızla başka bir alem yaratamadık

Yalnızca gerçekliğin kendimiz olduğunu düşünebildik

Evet Tanrı içimde,karışmışlık gibi

Birer ifadeleriz bizler

Varlığımız yokluğumuz...', 'İlk patlamaydı herşeyi başlatan Sonra sonsuz bir sessizlik Yayılıyordu küçük olan büyük olmak için Yeniden başlıyordu herşey Yepyeni bir ere...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tanimlama-gerekliydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılların birikimi', 'yillarin-birikimi-ali-veli-6cj7o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birikim

Emin olamadığım,kavrayamadığım

Neleri doldurdum,duyumları

Yaşamda tüketiciyim

Garip sayılacak bir çelişki

Seyret ve izle

Rayların üzerinde,sabit

Işık görmemi engelliyor

Kristalleşmiş bir gökyüzü

Katılaştıkça yumuşuyor

Sevdiklerimden nefret ettikçe

Çıkmaz bir sokak

Tebeşirle çizilmiş çember ok

Herşey kayıp gidiyor,akışkan

İçi boştu

Boşlukta varolan

Yaşam! ..', 'Birikim Emin olamadığım,kavrayamadığım Neleri doldurdum,duyumları Yaşamda tüketiciyim Garip sayılacak bir çelişki Seyret ve izle Rayların üz...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yillarin-birikimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum ölüyor...', 'oglum-oluyor-harun-kesik-p6r4q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyor musun istanbul? 

Benim oğlum ölüyor...

biliyor musun üsküdar? 

görebiliyor musun gözlerimdeki gizli yaşı

bilmiyordum önceleri

ama o hep bir hüzünlüydü 

ölümü anlamış gibi

hep mutluydu dolu dolu 

gururla bakardı dünyaya

ölüme meydan okur gibi 

aman Allahım 

Benim oğlum ölüyor...

kar yağmıştı istanbula

ve henüz kalkmamıştı topraktan

güneş açmıştı ama 

dedim ya daha kar kalkmamıştı topraktan 

oğlumun yaptığı kardan adamda sapa sağlam

kapı gibi duruyordu güneşin 

inadına 

yeşeren ağaçlar ölmüş gibiydi

ama onlar yeniden dirilebilirdi

ya oğlum oğlumda yeniden benim olabilir miydi? 

Allahım erken değil mi? 

o henüz çocuk değil mi? 

ölebilir mi? 

daha bu küçücük yaşında benden ayrılabilir mi? 

Benim canım oğlum ölüyor...

can cansız yaşayabilir mi? 

ağaç topraktan? 

ülke bayraktan 

ana yavrusundan ayrılabilir mi? 

şimdi ölmese bi küçücük daha yaşasa

tamam tamam 

istemiyorum benim canımda onun olsa

ama benim küçük oğlum hep benim olsa', 'Biliyor musun istanbul?  Benim oğlum ölüyor... biliyor musun üsküdar?  görebiliyor musun gözlerimdeki gizli yaşı bilmiyordum önceleri ama o ...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/oglum-oluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derlerse derim', 'derlerse-derim-zernisan-aydogan-50ys2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana bir gün bu asktan vazgeç derlerse

Vazgeçmem o benim askymdir derim

Bikmadin mi hala bu sevgiden derlerse

Bunu bilmem çünkü seven gönlümdür derim

Birgün gelir ayrilirsin ondan derlerse

Ayrilmam o benim ben onunum derim

Acep oda seni seviyor mu derlerse

Yeter artik sormayin ondan size ne derim

O seni sevmiyor baskasini seviyor derlerse

Aglarim saatlerce sadece vefasizmis derim', 'Bana bir gün bu asktan vazgeç derlerse Vazgeçmem o benim askymdir derim Bikmadin mi hala bu sevgiden derlerse Bunu bilmem çünkü seven gönlüm...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/derlerse-derim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın bir karelik görüntüsü', 'yasamin-bir-karelik-goruntusu-ali-veli-ulay9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Boş bir meydan 

Nesnelerin olmadığı

Sadece kendisi

Ve emin olamadığım ben

Dolduruyorum tek tek

İstemim ve belirsizlik

İfade zorluğu biçim yok

Ve emin olamadığım ben

Artık yaşanılmayacak yaşanılan

Sadece yaşanılacak yaşam

Beton ve çiçekler

Boş bir meydan ve ben

Yeşeren umutlar bilinmeyen

Üşüyorum ölüme yaklaştığım için

Elde ettiklerim

Ve yitiriliş kaygısı

Mücadele yaşama amacı', 'Boş bir meydan  Nesnelerin olmadığı Sadece kendisi Ve emin olamadığım ben Dolduruyorum tek tek İstemim ve belirsizlik İfade zorluğu biçim yo...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasamin-bir-karelik-goruntusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve yine bocalamak', 've-yine-bocalamak-ali-veli-iqhkt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne olduğunu bilememek

Neyi amaçladığını

Yaşıyoruz...

Durmadan,bıkmadan,usanmadan

Birimiz çıkıpta ben neyim

Cesaretini gösteremiyor

Fakat ölüme meydan okuyor

Kahraman oluyor

Hala bocalıyoruz

Ne istediğimizi bilmiyoruz

Hep bir yenisini bekliyoruz

Yeniliklerin sonucuna ölümle ulaşıyoruz

Neden? ..

Çünkü insanız

Üstinsan olamıyoruz

Biz insan olmaya layık değiliz

Üstinsana hayranlık duyuyoruz...', 'Ne olduğunu bilememek Neyi amaçladığını Yaşıyoruz... Durmadan,bıkmadan,usanmadan Birimiz çıkıpta ben neyim Cesaretini gösteremiyor Fakat ölü...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ve-yine-bocalamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerine umut', 'ellerine-umut-i-brahim-kamis-x1z7y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerine umut

Ne yapiyorsun simdi,

Camini aralamis.

Nereye bakiyorsun ki,

 gozlerin yanilsamalara gebe..

Sesini duyamadigim,

Yuzunu goremedigim,

Sarilip koklayamadigim...

Umudun yok belki yarina ait,

Sarp gecitlerden geciyor hissettiklerin..

Umudun, Ellerine dusmus hamarilerin

	Hazinelerinin yerini soylemiyor.

Ellerin mi usuyor simdi,

	Yoksa usuyen ellerim mi? 

Seni umuduma ekmek yaptim diye,

	Katiklarima yemek oldun mu simdi..

Uzun mu uzun cumleler geliyor da usuma,

	Kuramiyorum, anlatamiyorum derdimi.

Anlatabilsem sesimi sana

	Sesini gormek istedigimi anlatsam,

Sesin yuregime dusen yagmur idi..

Sen yagmurdun, umutlarimi islatan..

Semsiyeler actırmayan..

Sakla umudunu,

	Sakla..

		Sak-la...

Gelecegim.', 'Ellerine umut Ne yapiyorsun simdi, Camini aralamis. Nereye bakiyorsun ki,  gozlerin yanilsamalara gebe.. Sesini duyamadigim, Yuzunu goremedi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kamış']::text[], 8.5, '{"poet":"İbrahim Kamış","poet_slug":"i-brahim-kamis","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ellerine-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doymayacağım Sana', 'doymayacagim-sana-ali-gencay-x55ul', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yar uyumak istiyorum kollarında

Gün tepeden aşmadan doymalıyım sana

Bir gün/bir saat/bir dakika

Gündüzler kahır, geceler asır bana 

Bir ömür/bir nefes/bir anda olsa

Biliyorum doyamayacağım sana

Söz üstüne söz yok(sa da) 

En güzel yazılmış/söylenmiş olsa da

Kim beni anlatır, ne anlatır

Kurumuş mürekkep saman kağıdında

Hangisi yeter yaşamışlığıma

Kim söyler seni/beni/ aşkı şarkılarda

Doğru ya kim doymuş ki aşka

Biliyorum doyamayacağım sana

Dağlar/yollar uzaklık, ıraklıksa

Özlemin adına ne yanı başında

Yar uyumak istiyorum kollarında

Sensiz geçmez ki zaman

Bir ömür/bir nefes/bir anda olsa

Olmalısın yanımda

Biliyorum doymayacağım sana', 'Yar uyumak istiyorum kollarında Gün tepeden aşmadan doymalıyım sana Bir gün/bir saat/bir dakika Gündüzler kahır, geceler asır bana  Bir ömür...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/doymayacagim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Çiçek Hala Solmadı', 'o-cicek-hala-solmadi-ruhsel-bariscimen-78x5u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana bıraktıgın çiçegi

Gözyaslarimla sulayıp

Hiç kurutmadım...

Korkarim bu gidisle

Solan ben olacagım...

Dönülmez yollardan

Gelemeyisinden...', 'Bana bıraktıgın çiçegi Gözyaslarimla sulayıp Hiç kurutmadım... Korkarim bu gidisle Solan ben olacagım... Dönülmez yollardan Gelemeyisinden.....', ARRAY['Türk Edebiyatı','Şiir','Ruhsel Barışçimen']::text[], 8.5, '{"poet":"Ruhsel Barışçimen","poet_slug":"ruhsel-bariscimen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/o-cicek-hala-solmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Mevsim Olmayacak Kuşlara....', 'bu-mevsim-olmayacak-kuslara-ozgur-celik-4k5gj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu mevsim

kuşlar geçer bizim oralarda

sürü sürü

tam da güneşin battığı yere doğru

kanat seslerini her duyduğumda

içimi inceden bir telaş kaplar

kanatlanıp uçmak isterim ya

bir türlü kalkmaz yerden ayaklarım

önce kendime kızarım

özgürlüğe bukadar düşkünüm diye

sonra kuşlara

beni aralarına almadılar diye

bu mevsim

kazlar düşer bizim oralarda

yorğun akan derelere

avcıların tüfek sesleri duyulur

çok uzaklardan ardı ardına

her tüfek sesinde irkilirim

her kurşun canımı acıtır

kana bulanır her yan

güneş bile kızıla keser

kan kırmızı akar dere

ve ben kan çanağı gözlerimle

önce vurulan kuşlara ağlarım

sonra insanlığıma

bu mevsim

bıldırcınlar çıkar bizim oralarda

küçücük yumurtalardan

sesleri duyulur, başaklar arasında

parlayıverirler  birden

aklım alınır.

alışırım sonra

bıldırcınların acemi uçuşlarına

zamansız gelen yağmurlara

bu mevsim bir başka olur bizim oralar

yine de gözlerim gökyüzünde

bacamıza tüneyen leylekleri arar

''sanırım bu yıl gelmeyecekler....''', 'bu mevsim kuşlar geçer bizim oralarda sürü sürü tam da güneşin battığı yere doğru kanat seslerini her duyduğumda içimi inceden bir telaş kap...', ARRAY['Türk Edebiyatı','Şiir','Özgür Çelik']::text[], 8.5, '{"poet":"Özgür Çelik","poet_slug":"ozgur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bu-mevsim-olmayacak-kuslara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tereddüt', 'tereddut-ali-veli-8djkl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doğum esaretin başlangıcıydı

Varlık hiçlik sayılmıştı

Gerçekler yerini yanılsamalara bırakmıştı

Neydi doğru olan...

Varlığımızı değil yokluğumuzu yaşıyoruz

Yaşıyorsak o da belli değil

Gerçek olan kendimiz

Bizle beraber olan

Yaşam biçimlerimiz yanlış

Neden? ..

Değişkeniz...

Hem kalıcıyız,hem de değişken

Biçimleri görüyoruz,gerekliliği değil

Farkındayken kaçıyoruz

Kendimize dahi ihanet ediyoruz

İşte ihanet:

Doğum ve ölüm arasındaki süreç

Ereğimiz yaşanılanı yaşamak

Bunu gereklilik sayıyoruz

Yaşadıkça dünya var diyoruz

Ölüncede yok olacak yarattığım dünyam diyerekten

Coşku bizi hareketlendiren

Azimler kararlılıklar getiren

Karamsarlık bizi mantığa zorlayan

Düşünceyi yoğunlaştıran,düşlemlemeyi sağlayan

Umut ve sevgi bizi hayata bağlayan

Ve hala soruyorum:

Biz var mıyız,yok muyuz? ..

Yoksa arada mı? ..

Kendimize nicelik ve nitelik veremiyoruz

Çünkü insanız

İnsandan öteye adım atamıyoruz

Aslında,

Hiçliğimizden sıyrılıp özümüzü yaşamak istiyoruz

Gerçek varlığımızı varolmuş olanı

Şimdiki yanılsamayı değil

Acaba istiyormuyuz o da belli değil

Tedirginiz çünkü tereddütteyiz

Tanımlamalıyız diyorum tanımlayabilmeyi

Anlayamıyoruz kendimizi', 'Doğum esaretin başlangıcıydı Varlık hiçlik sayılmıştı Gerçekler yerini yanılsamalara bırakmıştı Neydi doğru olan... Varlığımızı değil yokluğ...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/tereddut-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüşüm Sende Kaldı', 'donusum-sende-kaldi-emin-bayraktar-kah89', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'günahkar düşlerin avcısıyım

kadim dostluğun buhurunu

çekmeyeyim içime

bir şiltede yatayım

yalnızlar tapınağında

bir şiltede...

kır hayatının zaptı yakın

gitmek istiyorlar, yitmek

git ve bit...

en güzel yerinde katılırım şarkıya

gotik tarzı hayatın mistisizminde

seni düşünmek, görmek

yıldız falıma bakmaktır aynada

ey sen, ey öfkem

kalk da vuruşalım

ölümün sindiği sonbahar kokusunda

seni düşünmemek

yolunu yitirmektir

ölümün günahkar labirentlerinde

bir fermanın asık suratında durduruldu

amuda kalkmış hayat teorilerim

ne varsa hayata dair, zihnimde

el sürmek kutsalı çiğnemek kadar yasak

günahkar düşlerin avcısıyım

düşlerimin kutsal metinleri kayıp

yol üstünde kuyu yok, kervan yok

boynumu süsleyen

imgelerle işlenmiş heybem

çoktan süslemekte han duvarlarını.

Emin Bayraktar', 'günahkar düşlerin avcısıyım kadim dostluğun buhurunu çekmeyeyim içime bir şiltede yatayım yalnızlar tapınağında bir şiltede... kır hayatının...', ARRAY['Türk Edebiyatı','Şiir','Emin Bayraktar']::text[], 8.5, '{"poet":"Emin Bayraktar","poet_slug":"emin-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/donusum-sende-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısır Birikintilerim', 'kisir-birikintilerim-emin-bayraktar-v3p9l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu gün iyi bir gün

güneşin tutulduğu gün

sevgiler yarım kaldı pencerelerde

yüklü kadınlar göç etti mağaralara

nereye baksan bir çift kaldırım

kulaklarını tıkamış beni bekliyor gece

yerin altındaki dişiler

dirayetsizliğiyle tanındı

ey çirkin bakışım

hafifletici sebep mi ağlaman

bu gün güzel bir gün

yüreğimin sırtlanlara mesken olduğu gün

rüzgarlarım sarhoş çünkü

çalkalanıyor avuçlarımda gece

görüyor musunuz kirpiklerimde

nasıl da doğurgan oluyor kuşlar

korkunç bir yelkendir onlar

bu gün hoş bir gün

zincire vurulduğum gün

her parmağımda bir tetik

kalaylanmış göğsümde savrulur kargılar

seğişim gürlemelerine yaradı şarkıların

bu gün yüce bir gün

yüceldiğim ama terk edildiğim gün

Emin Bayraktar', 'bu gün iyi bir gün güneşin tutulduğu gün sevgiler yarım kaldı pencerelerde yüklü kadınlar göç etti mağaralara nereye baksan bir çift kaldırı...', ARRAY['Türk Edebiyatı','Şiir','Emin Bayraktar']::text[], 8.5, '{"poet":"Emin Bayraktar","poet_slug":"emin-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kisir-birikintilerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzel Seni Sevmek', 'ne-guzel-seni-sevmek-emin-bayraktar-7mnqz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin sevdiğin şeyleri

Sevmek ne güzel

Senin nefret ettiğin

Şeylerden nefret etmek

Senin gördüğün şeyi görmek

Senin baktığın yere bakmak

Ne güzel, ne güzel

Ettiğin yeminleri etmek

Senin umurunda olmak

Ne güzel? 

Aynaya bakışın güzel

Sana bakmak...

Yüzüne bakıp gülmek

Gülen yüzüne gülmek güzel

Belirli bir saatten

Belirsiz bir saatte kadar

Seni düşünmek ne güzel

Seni sevmek ne güzel yarim.

Emin Bayraktar', 'Senin sevdiğin şeyleri Sevmek ne güzel Senin nefret ettiğin Şeylerden nefret etmek Senin gördüğün şeyi görmek Senin baktığın yere bakmak Ne ...', ARRAY['Türk Edebiyatı','Şiir','Emin Bayraktar']::text[], 8.5, '{"poet":"Emin Bayraktar","poet_slug":"emin-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ne-guzel-seni-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beceremedim Be Gülüm', 'beceremedim-be-gulum-demir-mutlugil-mji7n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yollarımız hep biryerler de kesiştiler,

kavşaklarımda hep sen

çıkmazlar sana çıktı,

git deyişinde geller

gelmeyi beceremedim be gülüm

gurur pranga olmuş,korkular kelepçeler

kaç kez geldim kapına

kaç kez döndüm kapından

gönül kapında ziller

çalmayı beceremedim be gülüm.

bulutlar kurudu  sanki

balıklar denizleri içtiler

gözlerim yaşsız kaldı

boğazıma yumruk oldunda

ağlamayı beceremedim be gülüm.

yüreğime darağaçları kuruldu

kulaklarımda kurşun sesleri

gördüm o ışığı

duydum son nefesleri

ölmeyi beceremedim be gülüm.

yalnızlık karabasanım oldu,

konuşmayı öğrendi resimlerin

özlemlerimde birliktelikler.

sevgiyi çabuk öğrendimde

sevmeyi beceremedim be gülüm.', 'Yollarımız hep biryerler de kesiştiler, kavşaklarımda hep sen çıkmazlar sana çıktı, git deyişinde geller gelmeyi beceremedim be gülüm gurur ...', ARRAY['Türk Edebiyatı','Şiir','Demir Mutlugil']::text[], 8.5, '{"poet":"Demir Mutlugil","poet_slug":"demir-mutlugil","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/beceremedim-be-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesimde Ağustos Böceği I', 'sesimde-agustos-bocegi-i-emin-bayraktar-nk51d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'devrik bir cümleyle anlatıyorum

tutukluğumu

isanın yaşındayım

sararmış bir çarmıhla yaşıyorum

dön ve bul beni

çıplaklığımı paylaş benimle

sesimde ağustos böceği

dilimde sen

bir kolum eksik

bir fırça darbesiyle

yalıyorum geçmişimi

tenime uzanıyorsun, boyunca

emiyorum seni, atmosferi

yoğun bakışlar altındayım

utanırım yorgunluğumdan

kim ne anlar...

yergi gibi yattım

sınırsızlığın

bağdaş kurmuş kucağında

boşluk hissi veren

çömleklerini kırdım

kesik cümlelerle anlatıyorum

yaşanılmışlığımı

isanın yaşındayım

sararmış bir çarmıhla yaşıyorum

gel ve bul beni

paylaş yalnızlığımı

sesimde ağustos böceği

dilimdeki sen

seni dilimde öldürdüm

kim ne bilir...

Emin Bayraktar', 'devrik bir cümleyle anlatıyorum tutukluğumu isanın yaşındayım sararmış bir çarmıhla yaşıyorum dön ve bul beni çıplaklığımı paylaş benimle se...', ARRAY['Türk Edebiyatı','Şiir','Emin Bayraktar']::text[], 8.5, '{"poet":"Emin Bayraktar","poet_slug":"emin-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sesimde-agustos-bocegi-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-ali-veli-82omy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaprak dökümü bitmişti sonrasızlığın sessizliğinde

Tanrısal güdü hakimdi ormandaki suskunluğa

Gitmişlerdi milyonlarcası kanat çırparak telaşlı

Güneş tavrını takınmıştı yine kaynağını kısarak

Doğa ananın uykusu geldi yorgun

İnsanlarda bu olanlara yandaş seyrelmiş

Bir ben kaldım varoluşumla donuk

Varmıyımın sorgusunda,evet...

Evet o kelime,yalnız...

Net kısırdöngülerin yansımasıdır yalnızlık

Ya da kendimle kalma korkusudur! ..

Belirgindir herşey,yaratım,varoluş,yokoluş

Hiçbir şey herbir şey...

Tane tanedir piyanodan dökülen notalar

Herbiri ayrı sorgulamalar yaratan

Sessizlik...

Ardından ürkek kısık sesli düşünceler

Nadasa bırakılmıştır benlik

Durgun ya da dingin ya da...

Hiçbir şey

Belkide bir kedinin kıvrılıp yatmasıdır yalnızlık

Huzur,dinlence,bilinç kayması,ölüm...

Terkedilmiş çoğulun bir kalması,aniden

Korku,teklik,iç hesaplaşma ya da

Tanrı,yalnızlık...

Yağan bir yağmurun ardından gelen

Temiz,arınmış ve yalnız

Sonrası çoğalma isteği paylaşma

Eco''nun hissettiği gidip gelen duygular

Bir varoluş ifadesizliği

Terkedilmişlik...

Yalnız bir ağaç gibi,yapraksız

Ay ışığı parlaklığında ama donuk

Yapayalnız...', 'Yaprak dökümü bitmişti sonrasızlığın sessizliğinde Tanrısal güdü hakimdi ormandaki suskunluğa Gitmişlerdi milyonlarcası kanat çırparak telaş...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yalnizlik-335-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliyet', 'sevgiliyet-emin-bayraktar-ettsa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'beş gündür yağmur yağıyor

beş gündür gece

sen öyle gece içindeyken

gece öyle senin içindeyken

ben nasıl uyurum seni

söyle sen nasıl gecesin

nasıl da gecesin

ne zaman yatsam sen uyursun

seni geceleri sokaklardan geçiririm

rüzgarda asmalara bakarım

koleksiyonumda ölüm manzaraları durur

yanan yaprak kıvılcımı tenimde

ey kutsal teslimiyet

yüreğimde uyuşmuş ka(l) dın

ay ışığı çarpmış kadın

seni romantik kelimelerde değil

yaşayarak sevdim

burçlara ve

satır satır yazan kaleme,

alfabenin son harfine

ant olsun ki seni sevdim

şeyhimin kerameti bu

şükürler olsun

hala seviyorum

Emin Bayraktar', 'beş gündür yağmur yağıyor beş gündür gece sen öyle gece içindeyken gece öyle senin içindeyken ben nasıl uyurum seni söyle sen nasıl gecesin ...', ARRAY['Türk Edebiyatı','Şiir','Emin Bayraktar']::text[], 8.5, '{"poet":"Emin Bayraktar","poet_slug":"emin-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevgiliyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanılmamış Bir Gün İçin Notlar', 'yasanilmamis-bir-gun-i-cin-notlar-emin-bayraktar-no435', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir kuş vardı

tüyleri mavi

deniz anası

gökyüzünde kaybolurdu

saçılmamış ateşler getirirdi bize

sen bekçiydin

zorlama sevgilerin taşıyıcısı

zorlanan hayatın damarı

bir gül vardı yamaçta

taç yapraklarında yedi iklim

derinliğinde delikanlılar dinlenirdi

onu ben de istedim

ama senindi o

güzel duruyordu gerdanında

en içten ofların

en güzel şarkılarımda dolaşırdı dilime

içinde yanan bir şehir saklıydı

ekmeğin asiydi tan yerinde

sana iliştirdim tüm yalnızlığımı

kuşlar göç ederken uğradın hep bana

yağmur, en güzel masalındı senin

onu ben de dinledim

dinlendim...

Emin Bayraktar', 'bir kuş vardı tüyleri mavi deniz anası gökyüzünde kaybolurdu saçılmamış ateşler getirirdi bize sen bekçiydin zorlama sevgilerin taşıyıcısı z...', ARRAY['Türk Edebiyatı','Şiir','Emin Bayraktar']::text[], 8.5, '{"poet":"Emin Bayraktar","poet_slug":"emin-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yasanilmamis-bir-gun-icin-notlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmeyene', 'bilinmeyene-nuri-kucuk-0lljx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir insanı hiçbir zaman tanıyamazsın 

Tıpkı okyanusun nerede sonlandıgını bilemedigin gibi 

Açtıkça açılır insan 

Sayfa sayfa,mısra mısra 

Bir bakmışsın bulut olur 

Yagmur yagdırır susayan gönüllere, 

Bir de bakmışsın güneş olur 

Yakar kavurur sevda çiceklerini, 

Ama en güzeli nedir biliyormusun 

Yüzünü bile görmedigin bir dosta şiirler yazarken 

Masa başında uyuyakalmak...', 'Bir insanı hiçbir zaman tanıyamazsın  Tıpkı okyanusun nerede sonlandıgını bilemedigin gibi  Açtıkça açılır insan  Sayfa sayfa,mısra mısra  B...', ARRAY['Türk Edebiyatı','Şiir','Nuri Küçük']::text[], 8.5, '{"poet":"Nuri Küçük","poet_slug":"nuri-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bilinmeyene-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğime Ağıt', 'yuregime-agit-emin-bayraktar-cxdk8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yüzümün yaylım ateşinde kekreme

bana zor tahammül edilir

parsellenmiş yüreğimden kalkar kuşlar

kayıt dışı yüreğimin

çeperlerine tutulur sevdalar

kavalımın sesinde doğunun yarısı

yağmurlar mayıs yağar

soluk yüzlü kelimelerime

topuklarımın gözeneklerinde birikir

hayat denilen salgı

basitleştirilmiş bir handikap

değil mi ki hayat

nisan yağmurlarında üşüyen yanağımda

evet kimse bilmez bunu

ama her yat saatinden sonra

kanatlı atlı karıncalara binip

istanbul''a güneşi getirenin kim olduğunu

kadınlara ölümlerle gelirdim

salgın bir hastalık anında

duygularıma çarpar kanat sesleri

çelimsiz alkışların gövdesinde

ey vurgun yemiş de düşmüş yüreğim

vurmasaydın vurulmazdın da

ey yüreğim yaktığın ağıtlara bak

kanlı pençeleriyle kuşlar konuyor

ama dur, daha dur

bitmedi bu ağıt... bitmedi bu sevda

Emin Bayraktar', 'yüzümün yaylım ateşinde kekreme bana zor tahammül edilir parsellenmiş yüreğimden kalkar kuşlar kayıt dışı yüreğimin çeperlerine tutulur sevd...', ARRAY['Türk Edebiyatı','Şiir','Emin Bayraktar']::text[], 8.5, '{"poet":"Emin Bayraktar","poet_slug":"emin-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yuregime-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Gribi Dedikleri', 'kus-gribi-dedikleri-seyfet-bozcali-ra8vp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ülkede gündem oluştu,En başta yerin aldı,

En önemli haberlerse,en gerilerde kaldı,

Basın onu sakız yaptı,daim çiğnedi durdu,

Sağ hastadan ayrılmadan, çok hayvan telef oldu.

Halk hastalığın adına tavuk vebası derdi,

Hastalanan hayvanları kesip,afiyetle yerdi.

Çocuklar çok sevinirdi, o gün bayram ederdi,

Canlı cansız bir çok hayvan çukurlara gömüldü.

Her kes bir günah keçisi bulmak için yarıştı,

Ülke için planlara,yeni oyun karıştı,

Yetmiş milyondan dört can öldü,tez Dünya''ya ulaştı,

Basının yaygarasıyla,fakirin ümidi söndü.

Günde yüzlerce kaza var,hiç çözüm üretilmez,

Kapkaç,hırsızlık kol geziyor,basın çare üretmez,

Soyuldu Devlet''in malı,hiç kimse sahip çıkmaz,

Yaygarayla,iftirayla beyaz et elde kaldı.

Çok ülkede bu grip var, ülke önlemin aldı,

Devletin bekası için,basını tedbirli oldu,

Kol kırıldı dedilerse yeni içinde kaldı,

Bizim gibi abartıcı basınada ders oldu.

Biz toplum olaraktan,pireyi deve yapmayı severiz,

Kendimizi hepten yerip,başkasını överiz,

Kendi ellerimizle kendimizi döveriz,

Ülkemiz zarar görürse,üzülecek bizleriz.

Bu şair Seyfet''te derki duyarlı olmalıyız,

Reytink için ülkemize zarar vermemeliyiz,

Bir çok yalan haberlere kulak tıkamalıyız,

Kuş gribi uzaklarda,hasta olan bizleriz...

           12.01.2006', 'Ülkede gündem oluştu,En başta yerin aldı, En önemli haberlerse,en gerilerde kaldı, Basın onu sakız yaptı,daim çiğnedi durdu, Sağ hastadan ay...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kus-gribi-dedikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-ali-veli-bf6tl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olur olmadık zamanlarda

Anlamsızca

Oradan oraya sürüklenmek

Geçici bilinç ile

Sonsuzluğu sonsuza dek tatmak

Kahve fincanının içinde çay kaşığı olmak

Farklı ne yapabiliyoruzki

Sonuçlar,pozitif-negatif deneyimler

Raf dolusu dosyalar bomboş

Nefret ettiğimiz şey fedakarlık yaptığımız gibi

Dünyayı dolaştım bir ceviz kabuğu olarak

Bağdaşamadım bir türlü insanlarla

Kendimi bitki saydım,hayvan saydım

İnsan,tanrı saydım

Sankli saydıklarım benmiş gibi

Sevgiye inanmadım hiçe saydım varlığı

Herşeyi boş saydım,hiçlik saydım

Bilemedim,bulamadım kendimi

Şu an insanım,tanıyamıyorum kendimi

Ben neyim yoksa hiçliğin ta kendisi mi...

Anlayamıyorum hiçliği...

*Şu an aramızda sayıları ciddi rakamları bulan,arayan insanların serzenişleri bunlar,çıkışı bulma umutlarında...', 'Olur olmadık zamanlarda Anlamsızca Oradan oraya sürüklenmek Geçici bilinç ile Sonsuzluğu sonsuza dek tatmak Kahve fincanının içinde çay kaşı...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yasamak-199-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz beyazlıkta yürüyüş', 'sonsuz-beyazlikta-yuruyus-ali-veli-f215a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Derinden gelen soğuk istek

Yürümek sonsuza dek

Büyük beyazlıkta kara delik

Bastığım yerlerde eriyen kar

Sonsuz beyazlıkta yürüyordum

Ölümle karışık sonsuz sevgi

Cazibe değil bu beyaz soğuk

Düşüncelerimi kemiren güzellik

Varlık,ben ve beyaz

Sonsuz beyazlıkta yürüyordum

İki parçaydık,farklı

Uyum bizim için taraflı

Sen başka ben başka

Bende soğuk istek sende ölüm

Sonsuz beyazlıkta yürüyordum

Bedenimi kaplayan garip mavi

Senin gülümseyişinle eşdeğer

Hislerim artık donuklaşıyor

Anlat gizemini beyaz soğuk

Sonsuz beyazlıkta yürüyordum

Beni büyüleyen lapa lapa beyaz melekler

Ölüm şarkısını üstünlüğüyle yorumlarken

Kendimi unutmaya başlamıştım

Artık ben de soğuk beyaza karışan

Sonsuz beyazlıkta yürüyordum

Bütün ben artık yok derken

Umut dolu insanların düşüncelerini süsleyen

Küçük bir çocuğun papatya benzetmesi

Soğuk beyaz kar olmuştum ben

Sonsuz beyazlığıyla renkleri yok eden

Doğanın tuhaf dostu,soğuğun kralı

Lapa lapa yağarken,mırıltı gibi

Sessizce gürlüyordum insanlara ben

İki yüzlülüğümü üstünlük sayarcasına

Sonsuz beyazlıktaki çekicilik ve

ÖLÜM...', 'Derinden gelen soğuk istek Yürümek sonsuza dek Büyük beyazlıkta kara delik Bastığım yerlerde eriyen kar Sonsuz beyazlıkta yürüyordum Ölümle ...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sonsuz-beyazlikta-yuruyus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorun yok! ..', 'sorun-yok-mehmet-coban-9psde', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçinde yaşadığımız ülkenin

İçinde yaşadığımız hayatın

Sorunlarından uzaksak

Hiçbir şeyi takmamışsak

“Ya bu deveyi güder

Ya bu diyardan gidersin”

Esprisinde deveyi gütmüşsek

Her günümüzü gün etmişsek

Boş vermişsek, 

Her türlü adaletsizliğe

Her türlü sefillik ve perişanlığa

Her gün sönen söndürülen umutlara

Her gün çiğnenen haklara

Her gün yok edilen doğaya

Sevgi adına düşmanlıklara

İhanetle satılan dostluklara

Ve bende, 

Ve sende

Ve bizde, 

Devenin güdüldüğü yerde

Gütmek için bulduksa bir deve

Götürüyorsak hamutuyla deveyi

Yapmışsak amaç, hep eğlenmeyi

Kulaklarımızı kapamışsak

Gözlerimizi kapamışsak

Dillerimizi lal yaptıysak

Zulümlere, haksızlıklara, 

Öldürülen insanlıklara

Ve hele, 

Birde bu tarafta değilsek

Öbür tarafta isek, 

O zaman sorun yok! ..

28.01.2006-İzmir', 'İçinde yaşadığımız ülkenin İçinde yaşadığımız hayatın Sorunlarından uzaksak Hiçbir şeyi takmamışsak “Ya bu deveyi güder Ya bu diyardan gider...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sorun-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-nedim-akgun-7dezd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazen duyar ve hissedersin

Seni,senden alan götüren duyguları

Bir tatlı bakış,belkide bir gülüş

Uzun,uzun düşünürsün ama çaresiz,

Ve sorarsın yaşanmalımı diye,

Bilemiyorum? 

Belkide hiç yaşanmamalı,

Belkide hiç düşünülmemeli

Diyebilecek bir insan değilim ben,

Mavi rengarenk dünyamda

Bir çiçek misali gördüğüm,

Koklamaya kıyamadığım,

Ama hep sevdiğim

Arkadaşım,dostum,can yoldaşım,

Bir rüya misali seninle yaşadıklarım.

Bir an gözümün önüne gelir hatırlarım,

Varsın sen ey güzel insan,

Belki bir dost,belkide bir yaren,

Ama insan.

Yanlızlığı yaşamış,acının çilesini çekmiş,

Sadece insan ve sen tatlı bir rüyasın.

Gök gürler,şimşekler çakar ve uyanırsın,

Bakarsın sadece yanlızlığını görürsün,

İşte o an anlarsın,

Göz yaşlarını tutamazsın.', 'Bazen duyar ve hissedersin Seni,senden alan götüren duyguları Bir tatlı bakış,belkide bir gülüş Uzun,uzun düşünürsün ama çaresiz, Ve sorarsı...', ARRAY['Türk Edebiyatı','Şiir','Nedim Akgün']::text[], 8.5, '{"poet":"Nedim Akgün","poet_slug":"nedim-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ruya-232-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece ve Sen', 'gece-ve-sen-dilek-kadioglu-m88fw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi ben de şiirler yazıyorum 

Ama sadece sana 

Yüreğimi koyuyorum satırlara 

Bir iki damla da 

yıldız kayıyor gözlerimden 

Yaşamak varken 

yaşayamadıklarım için ağlıyorum 

Bu gece yine 

ağlamak için sebep arıyorum 

Belki de üşüyen yüreğim için 

Sebep her neyse…. 

Yıldızlar kayıyor gözlerimden 

Ve bir başıma kalıyorum...', 'Şimdi ben de şiirler yazıyorum  Ama sadece sana  Yüreğimi koyuyorum satırlara  Bir iki damla da  yıldız kayıyor gözlerimden  Yaşamak varken ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kadıoğlu']::text[], 8.5, '{"poet":"Dilek Kadıoğlu","poet_slug":"dilek-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gece-ve-sen-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinmiş canım,cismi varına,', 'sinmis-canim-cismi-varina-ali-riza-unal-j2lkg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sinmiş canım,cismi varına,	

Ruh-i revanım,ramın  olsun,

Düşer sensiz olan ismi narına,

Bu aczaden yarın olsun,

Dinmiş avazım,kisve-i zarına,

Lütfa meramım,kârım olsun,

Put kesilir gafilin,ifet-i arına,

Bu miskine ar-ın,vaslın olsun..

Bu eserin mana-ı açıklaması  maksadımız ilâhidir,

1	:  bu canım senin cismine sığınmış  kenetlenmiş

cisimim diye  baktığım bu  her iklimin  vucudu  senin cismindir Allahım,

2  :   o ruh ki senin ezeli ilminde bir gayb-ı  sır  bana lütfettiğin o ruh  bir an bile yerinde sabit değil gezici

seyyal ve seyyah ne gece  ne gündüz  su gibi akıp giderki gider revan halinde  işte benim bu  ruh-i revanım  sana boyun büker  ram olur istesede istemesede  şükürler olsunki bizde isteyerek ve bilerek 

boyun bükmüş ve ram olmustur.

3: seni bilemeyen  zatına sıfatına  değilde bir zan ve vehm ile isminin peşine düşer  dinin peşine düşer yani 

amacı  bırakır bilmez araca tapar   bu da  hiçbir zaman ne aradığını bilmez ve sitres sıkıntı bunalım tasadadır yani narında dır, sen amaçsın  dinin sana ulaşmama araçtır,

4 : bu sırına fakıf bu aciz kulun   yarin olsun  hem her diim  evel ahir.

5 .   seninle  susar  bu avazım feryadım zarım   senin hicap  ebisene kisvene  saklanır ( aman ya Rabbi  beni  sana na mahramden sakla ve beni sana ehile sen ile göster amin.

6 .bu lütfunun  çok ama çok talibiyim  meftunuyum her daim  zuhur ve tecellilerine eylediğin  mashar-ı ilâhi  üzerim den hiç alma ne olur ben sensiz hiçbir  şeyden zevk alamıyorum her hazzımın   ancak ve ancak sen ile kemali mümkün  bu zevki sana talip olan her kuluna lütfet  onlarda  seni bilemeselerde senin kulun  amin.

7 . seni tanımayan cahil gafil put kesilir senin gücünü güzelliğini kendi sanır ve kendine tapmaya başlarki bu başka puta değil  kendi nefsini putlaştırır ( hani demiş ya  birisi Hz. Mevlanaya  ya hazret çok şükür put perestlikten kurtuldum hazrat  derki öylemi cancağazım sen put perestlikten kurtuldum diyorsun ama kendini put edinmişsin)   Rabbım bizi bu gizli put perstlikten korusun  amin.

8 . bu miskin  yani bu halsiz beceriksiz kabiliyetsiz ama her şeyini senden alan  kuluna  ar-ın  yani  o en gizli  hallerin bana vuslat olsun ya Rabbiiiii zaten öylede  daim olsun ya Rabbiii Amiiiin. Ve talip ve layık olan olan her kuluna amiiiiin….', 'Sinmiş canım,cismi varına,	 Ruh-i revanım,ramın  olsun, Düşer sensiz olan ismi narına, Bu aczaden yarın olsun, Dinmiş avazım,kisve-i zarına,...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sinmis-canim-cismi-varina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerime Yükledim Irmakları', 'gozlerime-yukledim-irmaklari-umit-fehmi-sorgunlu-esjrq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece yarısı bir adam

Almış avuçlarına yıldızları

Ay’la konuşuyor, güneşle konuşuyor

Gözlerine yüklemiş ırmakları

Yüreği yıkanıyor

Gece yarısı doğan güneş

Secdede alnından öpüyor

Avcunda ki yıldızları sayıyor bir bir

Dilinde düşmeyen tekbir

Yüreğinde birleşiyor', 'Gece yarısı bir adam Almış avuçlarına yıldızları Ay’la konuşuyor, güneşle konuşuyor Gözlerine yüklemiş ırmakları Yüreği yıkanıyor Gece yarıs...', ARRAY['Türk Edebiyatı','Şiir','Ümit Fehmi Sorgunlu']::text[], 8.5, '{"poet":"Ümit Fehmi Sorgunlu","poet_slug":"umit-fehmi-sorgunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozlerime-yukledim-irmaklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turnanın seçiciliği', 'turnanin-seciciligi-ali-veli-7t3vh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şafağın o güzel mekanında

Bir turna geçiyordu

Kızılımsı güzelliğiyle iri noktanın

Görkemli güneşin hizasında

Biçimli bir karaltı halinde

Gölge oyunlarındaki gibi

Sessizce kanat çırpıyordu

Sırtında küçük bir sepet

İçinde küçük insanlar

Herkes göremezdi onları

Aşamalar kaydetmeliydi görmek isteyen

Farkına varmalıydı gerçeğin

Anlamsız gelebilirdi göremeyenlere

Ama her şafakta

Zamanı doğru işlediğini bilen saat gibi

Turna taşıyordu küçük insanları

Bilmediğim bir yere

Anlatmıştı bana bilge kuzgun

Güzel turnanın hikayesini

Şaşırmıştım insanlığımdan utanarak

Hayran kalmıştım anlattıklarına

Bilemezdim diğerlerini

Verdikleri yaşam mücadelesinin amacını,

Nesillerini devam ettirme çabasını,

Açlığa gösterilen direnişi

Üreme,yeni fertler getirme eylemi

Ama anlatmıştı bilge kuzgun herşeyi

Utamıştım insanlığımdan

Bir turna kadar olamayışımızdan

Yaşamı seven,sevgiye değer veren,

İnsanlık kavramının değerini bilen

Güzel gelecek düşleyen

Doğa ile arasındaki hasreti bitirmek isteyen,

Ender insanları

O gizemiyle sihiriyle küçük insanlara dönüştüren

Fedakar turnanın amacı,

Her canlının görevi olan

Hayatta kalma,neslini devam ettirme güdüsü...

Kendi nesli için değilde insanlık için

Yaptığını bilemeden

Ama anlatmıştı bilge kuzgun herşeyi

Her şafakta taşıyordu küçük insanları

Fedakar turna

Savaşın olmadığı,yıkıcılığın olmadığı

Sahip olma isteğinin olmadığı mekana

Bilmediğim bir yere

Umut ülkesine:Ütopya ya

Her sabah seyrediyorum turnayı

Ona duyduğum güven ve saygıyla

Unutmuyorum utancımı

Yardım etmek istiyorum

Uzatıyorum elimi

Ama geri çekiyorum,elim kirli...

Bozmamalı turnanın güzelliğini,amacını

Her sabah bekliyorum kapımda

Küçük insan olmak istermiş gibi...', 'Şafağın o güzel mekanında Bir turna geçiyordu Kızılımsı güzelliğiyle iri noktanın Görkemli güneşin hizasında Biçimli bir karaltı halinde Göl...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/turnanin-seciciligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erciyes''e Çıkacağım', 'erciyes-e-cikacagim-umit-fehmi-sorgunlu-bhu7q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Erciyes’in tepesine çıkacağım

Selçuklu kalesinin hüznünden sıyrılıp

Bütün hızımla güneşe koşacağım

Yağan kar’larla  yüreğimi yıkayıp 

Ulaşılmaz zirvelere asacağım

Erciyes’in tepesine çıkacağım

Kendimle kavgayı unutup

Karların kayalarla seviştiğine bakacağım 

Aklanan yüreğimle sevgi sunup 

Selçuklu minaresini selamlayacağım

Erciyes’in tepesine çıkacağım 

İçime serin rüzgârları sindirip 

Sımsıcak sevgi haykıracağım

Nefesimle buzları eritip

Selçuklunun gözyaşlarını kurutacağım', 'Erciyes’in tepesine çıkacağım Selçuklu kalesinin hüznünden sıyrılıp Bütün hızımla güneşe koşacağım Yağan kar’larla  yüreğimi yıkayıp  Ulaşıl...', ARRAY['Türk Edebiyatı','Şiir','Ümit Fehmi Sorgunlu']::text[], 8.5, '{"poet":"Ümit Fehmi Sorgunlu","poet_slug":"umit-fehmi-sorgunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/erciyes-e-cikacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bekliyorum', 'seni-bekliyorum-umit-fehmi-sorgunlu-9ie24', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Otobüs gişelerinde

Tren istasyonlarında

Pörsümüş umutlarla 

Seni bekliyorum

Zemherilerde donan

İlk yazlarda ısınan

Çiçek çiçek açan

Sevgimle bekliyorum', 'Otobüs gişelerinde Tren istasyonlarında Pörsümüş umutlarla  Seni bekliyorum Zemherilerde donan İlk yazlarda ısınan Çiçek çiçek açan Sevgimle...', ARRAY['Türk Edebiyatı','Şiir','Ümit Fehmi Sorgunlu']::text[], 8.5, '{"poet":"Ümit Fehmi Sorgunlu","poet_slug":"umit-fehmi-sorgunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-bekliyorum-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatya', 'papatya-umit-fehmi-sorgunlu-0298w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her çıkışımızda bahara

Yapraklarını bir bir kopardımsa

Sevildiğimi anlamak için papatya

Hani bu bahar gelecekti

Yine beni sevecekti

Sende yalancısın papatya

Söz, bir daha yolmam yapraklarını

Yeter ki bitirme umutlarımı

Sakla öbür baharlara', 'Her çıkışımızda bahara Yapraklarını bir bir kopardımsa Sevildiğimi anlamak için papatya Hani bu bahar gelecekti Yine beni sevecekti Sende ya...', ARRAY['Türk Edebiyatı','Şiir','Ümit Fehmi Sorgunlu']::text[], 8.5, '{"poet":"Ümit Fehmi Sorgunlu","poet_slug":"umit-fehmi-sorgunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/papatya-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayırdılar Ayırdılar', 'ayirdilar-ayirdilar-yusuf-onder-bahceci-ih5lf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deli gönül bir güzeli seçti,

Benim ömrüm boşa geçti,

Solan bahtıma bir Güneşti,

Söndürdüler, söndürdüler.

Benim yüzüm hep gülerdi,

Sevdiğim sitemler ederdi,

Bu hayat bana neler verdi,

Öldürdüler, öldürdüler. 

Mutlu bir yuva kuracaktım,

Sevdim benim olacaktın,

Tam da mesut olacaktım,

Ayırdılar, ayırdılar....', 'Deli gönül bir güzeli seçti, Benim ömrüm boşa geçti, Solan bahtıma bir Güneşti, Söndürdüler, söndürdüler. Benim yüzüm hep gülerdi, Sevdiğim ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayirdilar-ayirdilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Postası', 'gonul-postasi-harun-kuscu-qcfle', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ömür mevsiminin gülleri soldu

Keşkahlar çekerek yastadır gönlüm

Yaşanmamış ömrün vadesi doldu

Sonsuz duygulara postadır gönlüm

Yeniden dünyaya  gelseydim eğer

Kalıcı şeylere verseydim değer

Onsuz yaşamaksa boşaymış meğer

Şimdi yadellerde hastadır gönlüm

Perişan haldeyim başımda duman

Geçmişin hayali vermiyor aman

Felek bana borçlu şahittir zaman

Aklımda fikrimde dosttadır gönlüm

Harun kuşcu

Silifke/mersin', 'Ömür mevsiminin gülleri soldu Keşkahlar çekerek yastadır gönlüm Yaşanmamış ömrün vadesi doldu Sonsuz duygulara postadır gönlüm Yeniden dünya...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gonul-postasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nafile yeşermeler...', 'nafile-yesermeler-hasan-esat-heptunali-up3pq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok oldu sen bu şehri terk edeli…

Bozkırın ta orta yerinde

Bilmem hangi ıssız kasabanın

Gözleri raylardaki bi istasyon şefi edalı..

Bir ben…

Düşmüyor damlalar bozkırıma …

Ve düşmeyecekmiş de daha

Öyle diyor acanslar…

Gittin(m)  gideli..

Nafile yeşermeler

…………

Biliyor musun?', 'Çok oldu sen bu şehri terk edeli… Bozkırın ta orta yerinde Bilmem hangi ıssız kasabanın Gözleri raylardaki bi istasyon şefi edalı.. Bir ben…...', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nafile-yesermeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demem Demem Gerekirdi', 'demem-demem-gerekirdi-yusuf-onder-bahceci-c3cve', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni tutsam da ellerinden,

Bilsem ceylan gözlerinden,

Seni sevdim yüreğimden,

Demem, demem gerekirdi.

Baksam ceylan gözlerine,

Sorsam seni şu gönlüme,

Ne olursun sevdiğim de,

Demem, demem gerekirdi.

Sana yandım be güzelim,

Gel seninle köy gezelim,

Seven bu kâlpleri sezelim,

Demem, demem gerekirdi.

Şimdi desem ne olur ki,

Derdim nasıl son bulur ki,

Gece, gündüz ağlar belki,

Demem, demem gerekir.....

Arkadaşlar şiir güzel mi....', 'Seni tutsam da ellerinden, Bilsem ceylan gözlerinden, Seni sevdim yüreğimden, Demem, demem gerekirdi. Baksam ceylan gözlerine, Sorsam seni ş...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/demem-demem-gerekirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüce saydığım parıltı', 'yuce-saydigim-parilti-ali-veli-qkqci', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Varlığımızın seninle oluştuğunu bilmeden

Bizleri seyrediyordun karşılık beklemeden

Bıkmadan usanmadan bizleri

Kendi yüceliğine hayranlık duyuyordun,saygı

Aldırmaz bir tavır

Buram buram olgunluk kokan bakışınla

Bazen seyrederken seni

Titrediğini görüyorum hafiften

Biliyorum,içi içine sığamamak gibi birşey

O üstün enerjini paylaşandın sen

Gündüzleri izlendiğim hissi,geceleride

Paranoyamın sebebi sensin

Işıldak çember çevrende hareketliyken

Küçük kızların oynadığı çember oyunları

Belirleniveriyor zihnimde hayali

Yarı tanrı görünümün etkiliyor beni

Buzlarım çözülüyor,endişelerim

Ama beliren bir endişe,sana muhtaçlığım

Sensiz yapamayışım

Hayat kaynağı oluşun yetmiyor

Kavur beni,erit,buharlaştır

Sana ulaşmamı sağla

Karışmak istiyorum yüceliğine

Ben de seyretmek istiyorum kendimi,bizleri

Dokunaklısın,

Görkeminle hüzünlendiriyorsun beni

Neden acizliğe boyun eğmeli

Karşında küçük düşmeli

İsteyince biliyorum oluşturabilirsin nesneleri

Ya da yok edebilirsin canlı herşeyi

Sana yaklaşmak bile öldürücü

Neden seviyorum seni

Hayat kaynağımsın

Unutmuyorum mantık kokan gerçeği

Bir süre seninle bakışınca

Siliniyor herşey

Grimsi bir mekan alıyor eskinin yerini

O zaman yabancılaşıyorum

Korkuyorum bilinmeyeni yaşayınca

Seni farketmek istemiyorum böyle olunca

Ama biliyorum sen yukarıdasın

İçimde hissediyorum sıcak nefesini

Daha sonra aldırmıyorum sana

Nedeni yanılsamalarda sürüklenmem

Yapımın gerektirdiği bir yasa sanki

Seni seviyor olmam

Yapıcı ve yıkıcı oluşundan

İnsanlara benziyorsun

İlklerden birisin,yüceliğin buradan

Korkum yıkıcılığın

Hayallerim yıkılmamalı,anlamalısın beni

Hep böyle kal.

Olur mu? ! ..', 'Varlığımızın seninle oluştuğunu bilmeden Bizleri seyrediyordun karşılık beklemeden Bıkmadan usanmadan bizleri Kendi yüceliğine hayranlık duy...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/yuce-saydigim-parilti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seven Yürek...', 'seven-yurek-nurdane-diken-jeslb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk okuyan gözü müdür? 

Lâf söyleyen dili midir? 

Harlar yakan özü müdür? 

Seven yürek deli midir? 

Şu sevdaya ben taparım 

Kâh açarım, kâh kaparım

Bulutlardan nem kaparım

Seven yürek suçlu mudur? 

Hırka giydim, gezer oldum

Hazanlardan, hazan buldum

Seni içtim, sarhoş oldum

Seven yürek sarhoş mudur? 

Vah! yüreğim dik sarplar da 

Ömrüm geçer haraplar da

Uykum kaçar serâplar da

Seven yürek esir  midir? 

Demir kafes durağımdır

Artık yanmaz çırağımdır

Hergün artan firağımdır

Seven yürek şebtap mıdır? 

Sarp dağları çok aşarım

Irmaklarla hep taşarım

Seni bulup bir koşarım

Seven yürek yetim midir? ....', 'Aşk okuyan gözü müdür?  Lâf söyleyen dili midir?  Harlar yakan özü müdür?  Seven yürek deli midir?  Şu sevdaya ben taparım  Kâh açarım, kâh ...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seven-yurek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melekler şahit olsun', 'melekler-sahit-olsun-bahtiyar-tas-dic5r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceler uzuyordu ya saçlarında

Unutamadım…

Onu yazdım son mektuba… 

Vedasız sonlar vardı ya…. 

Unutmadım… 

Sebepsin kuruttuğum gözyaşına', 'Geceler uzuyordu ya saçlarında Unutamadım… Onu yazdım son mektuba…  Vedasız sonlar vardı ya….  Unutmadım…  Sebepsin kuruttuğum gözyaşına...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Taş']::text[], 8.5, '{"poet":"Bahtiyar Taş","poet_slug":"bahtiyar-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/melekler-sahit-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyorsam Sebebi Var', 'agliyorsam-sebebi-var-yusuf-onder-bahceci-e08jd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlıyorsam sebebi var,

Kalbim ise durmaz ağlar,

Deli gönül sular çağlar,

Ağlıyorsam sebebi var.

Hep ağlayanlar olur kâni,

Ne var ağlamayımmı yani,

Hoş Dünya''nın sonu fani,

Ağlıyorsam sebebi var.

Gitti gelmez güzel günler,

Benim kalbim acı, keder,

Önder şimdi hayal eder,

Ağlıyorsam sebebi var....', 'Ağlıyorsam sebebi var, Kalbim ise durmaz ağlar, Deli gönül sular çağlar, Ağlıyorsam sebebi var. Hep ağlayanlar olur kâni, Ne var ağlamayımmı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/agliyorsam-sebebi-var-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akliman Kar Altında', 'akliman-kar-altinda-zeki-ergin-nqmgk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklimanda bir zemheri günü

çoştu poyraz

coştu deniz

saldırıyor kumsala köpük köpük

Aklimanda deniz

Aklimanda ağaçlar ak

yok poyraza dur durak

sanki doğanın beyaz isyanıdır

kar tipi savuruyor öfkesini

kediler şaşkın

kuşlar yorgun

bu bir zemheri vurgunudur

duyulmuyor ne motor 

ne de bir kuş sesi

içimin titremesidir

bu şiir

Babakale limanı

teknelere ana kucağıdır

şimdi soba başında

mum ışığında

aşk zamanı

kestane kebap zamanıdır

_babakale 25oca06

_dağlara ver sırtını yt:haz09', 'Aklimanda bir zemheri günü çoştu poyraz coştu deniz saldırıyor kumsala köpük köpük Aklimanda deniz Aklimanda ağaçlar ak yok poyraza dur dura...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/akliman-kar-altinda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce hep birlikte ayaklanıyorlardı', 'once-hep-birlikte-ayaklaniyorlardi-levent-i-skenderoglu-aj57b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önce hep birlikte ayaklanıyorlardı

Ellerinde renksiz bir bayrak

Bilinmeyen ölçülerde 

İki bilinmeyenli denklemler

Çözmeye  başlıyorlardı

bir set çekiliyordu önlerine

Belli belirsiz

Ayakları takılıyordu

Hep birlikte düşüyorlardı

Dipsiz çukurlara

Yüzyıl geçiyordu aradan

Ve bir toplu mezar bulunuyordu

Şehrin göbeğinde', 'Önce hep birlikte ayaklanıyorlardı Ellerinde renksiz bir bayrak Bilinmeyen ölçülerde  İki bilinmeyenli denklemler Çözmeye  başlıyorlardı bir...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/once-hep-birlikte-ayaklaniyorlardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Kalacak Bu Yürek,', 'sensiz-kalacak-bu-yurek-selhan-yurt-ooh3d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir daha mı sensiz kalacak bu yürek,

Ölüm gibi seni sensiz düşünmek...

Keşke isteseydin beni birazcık sevmek,

Bu gönül senden başkasını ne sevdi, ne sevecek....', 'Bir daha mı sensiz kalacak bu yürek, Ölüm gibi seni sensiz düşünmek... Keşke isteseydin beni birazcık sevmek, Bu gönül senden başkasını ne s...', ARRAY['Türk Edebiyatı','Şiir','Selhan Yurt']::text[], 8.5, '{"poet":"Selhan Yurt","poet_slug":"selhan-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sensiz-kalacak-bu-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-bahtiyar-tas-86euq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adını yazdım ya derinlerime…

Unutmak ölüm… 

An gelir ağlarım ikimizin yerine…

Bedenin toprağım olsun…

Bırakıp gidersen azap düşlere..', 'Adını yazdım ya derinlerime… Unutmak ölüm…  An gelir ağlarım ikimizin yerine… Bedenin toprağım olsun… Bırakıp gidersen azap düşlere.....', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Taş']::text[], 8.5, '{"poet":"Bahtiyar Taş","poet_slug":"bahtiyar-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/istanbul-378-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede arkadaşlarım, dostlarım nerede', 'nerede-arkadaslarim-dostlarim-nerede-fikret-dundar-zvhja', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerede kaldı benim eski dostlarım? 

Yine kuruluyor mu,

Merada panayırlarım? 

Bakın kar yağdı yine,

Aklım gitti yine yıllar öncesine! 

Bizim evin yanındaki yokuş var ya,

Yine şenlik var mı orada? 

Kızak kayan çocuklar 

Şakalaşmakta mı aralarında! 

Takır tukur sesler çıkarırkan 

Kızaklar buzlar üzerinde,

Yine tekerlenip, düşen çocuklar var mı

O bembeyaz karların bağırlarına? 

Odada yerlere serili hasırları bile

Neredeyse havalandıracak,

Kadar güçlü esen

O sert rüzgarlar var mı hala oralarda? 

Yine buram buram kokar mı

Ihlamur ağaçlarım çiçek açtıklarında! 

Var mı Kazandere` de, Anadere` de 

Yine yayın balıkları tutanlar,

Yoksa onlarda mı mazi oldu 

Sararmış sayfalarda? 

Yakalamaya çalışırdı 

Rahmetli Şevket abimiz,

O koskocaman yayınları! 

Sabahlara kadar yanardı

Dere kenarında kamp ateşimiz! 

Ah ne güzeldi 

Ne güzeldi o günlerimiz! 

Hiç sormayın şimdi bana,

Efkar bastı yine bağrıma! 

Ne günlerdi diye sormayın bana.

Öyle günlerdi işte! 

Tadı yer etti gönümüzde,

Gömüldü gitti o tatlı anılar 

Belleklerimize! 

O arkadaşlar, o dostlar,

Yok artık çevremizde,

Kimisi geçip de gitmiş 

Gideceği yere önceden,

Kimisi de düşmüş kalmış

Hayat gailesine! 

Bir başına gezer durur gönlüm,

Şimdilerde o yeşil Ergene ovasında, 

Istranca ormanlarında.

Arar durur hala birilerini amma,

Sesime cevap veren yok artık,

Yapayalnız kaldım anılarımla başbaşa,

Yüreğimde ince sızılar var,

Üzgün mü üzgün,

Ve özlem karışmış, ince hüzün 

Ve şıpır şıpır damlayan yaşlar var

Göz pınarlarımdan! 

Haber getiremez oldu artık turnalar

Artık benim gözümde tuten sılamdan,

Haber alamaz oldum eski dostlarımdan! 

Ama taptaze hala o anılar,

Sormayın ne olur bana dostlar

Efkarlandım durdum,

Sarhoş gibiyim sanki 

Gönlümü bastı yine,

Bastı dostlar

Basmaz olası karalar! 

Fikret Dündar

Erenköy-İstanbul

28.01.2006', 'Nerede kaldı benim eski dostlarım?  Yine kuruluyor mu, Merada panayırlarım?  Bakın kar yağdı yine, Aklım gitti yine yıllar öncesine!  Bizim ...', ARRAY['Türk Edebiyatı','Şiir','Fikret Dündar']::text[], 8.5, '{"poet":"Fikret Dündar","poet_slug":"fikret-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/nerede-arkadaslarim-dostlarim-nerede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Yine Bekledim Seni', 'bugun-yine-bekledim-seni-selhan-yurt-0nmrh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün yine bekledim seni,

Her gün gibi...

Belki gelirsin diye,

Gelmiyeceğini bile bile! ! !', 'Bugün yine bekledim seni, Her gün gibi... Belki gelirsin diye, Gelmiyeceğini bile bile! ! !...', ARRAY['Türk Edebiyatı','Şiir','Selhan Yurt']::text[], 8.5, '{"poet":"Selhan Yurt","poet_slug":"selhan-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bugun-yine-bekledim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Spor', 'spor-timur-i-likan-g1l3s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsanların çoğu bilmezmiş

İki nimetin kıymetini

Biri sağlık biri de boş vakitmiş

Öyleyse sen boş vaktini

Değerlendir ki spor yaparak

Hem boş vaktin dolsun

Hem de ruhun ve bedenin sağlık bulsun

Böylece bir taşla iki kuş vurursun

Daha ne olsun

(28 Ocak 2006/ İstanbul)', 'İnsanların çoğu bilmezmiş İki nimetin kıymetini Biri sağlık biri de boş vakitmiş Öyleyse sen boş vaktini Değerlendir ki spor yaparak Hem boş...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/spor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçtim Senden', 'vazgectim-senden-selhan-yurt-4bozn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vazgeçtim senden,

Vazgeçemediğim gözlerinden...

Vazgeçtim kendimden,

Vazgeçemediğim senle hayallerimden...

Vazgeçtim artık seni yazmaktan,

Vazgeçtim ya gerçekleri yazmaktan...', 'Vazgeçtim senden, Vazgeçemediğim gözlerinden... Vazgeçtim kendimden, Vazgeçemediğim senle hayallerimden... Vazgeçtim artık seni yazmaktan, V...', ARRAY['Türk Edebiyatı','Şiir','Selhan Yurt']::text[], 8.5, '{"poet":"Selhan Yurt","poet_slug":"selhan-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/vazgectim-senden-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Yoksun', 'senden-yoksun-selhan-yurt-45qjk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün sende yoksun,

Biz de senden yoksun! ! ! 

Yani hayat durgun...

Galiba güller de solgun! ! ! 

Belli ki sende durgunsun....', 'Bugün sende yoksun, Biz de senden yoksun! ! !  Yani hayat durgun... Galiba güller de solgun! ! !  Belli ki sende durgunsun.......', ARRAY['Türk Edebiyatı','Şiir','Selhan Yurt']::text[], 8.5, '{"poet":"Selhan Yurt","poet_slug":"selhan-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/senden-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Evladımıydın?', 'i-nsan-evladimiydin-serpil-karabacak-1ghrq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatta kendin ol

Başkasına Acı verme 

Sana ait olmayanı takma boynuna. 

Taşıma gerektiğinden fazla ağırlığı üzerinde. 

Vakit geldiğinde atmayı,olurunda bırakmayı öğren, 

İnsan evladı-sın! 

Yaramazsa ciğeri peş para etmez sevgili… 

Aniden düşerse aklına öğren acısada için, besmele çekmeyi... 

Var özgürlüğünün tadına, her şeyi takma öyle kafana 

Ara gerektiğinde,ardındaki gerçeği, izleri, zarar vermeden ruhuna 

İnsan evladı-sın! 

Biliyormusun? bu vakti bekliyorum, 

Çok yoruldum… 

Seni omzumda taşımaktan suçlu gibi. 

Tek suçum adam sanıp gönlümü körü körüne vermekti.. 

İnsan evladı (mıydın) ? 

Kaldıramıyorum inan ağırlığını… 

Gittikçe yürüyüşüm ağırlaşıyor… 

Hissediyorum vakit yavaş yavaş yaklaşıyor... 

İnsan evladı (mıydın) ? 

Acımasızca İndireceğim, atacağım yere, bakmayacağım kesinlikle arkama… 

Diyorum, Nafile 

Olamam, yalan sözlerin arkasına gizlenip asla bir insan evladına kıyamam 

Tek Kıymetini bileceğim bugünün, faydası yok geçen her günün 

Mazinin Değeri… 

Öğrenmek için yaşamanın getirdiği acılar büyütüp olgunlaştırmasıymış… 

İnsan evladı-mıydın? ? ?', 'Hayatta kendin ol Başkasına Acı verme  Sana ait olmayanı takma boynuna.  Taşıma gerektiğinden fazla ağırlığı üzerinde.  Vakit geldiğinde atm...', ARRAY['Türk Edebiyatı','Şiir','Serpil Karabacak']::text[], 8.5, '{"poet":"Serpil Karabacak","poet_slug":"serpil-karabacak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/insan-evladimiydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul aşkı', 'i-stanbul-aski-bahtiyar-tas-iozif', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akşam oldu yalnızlık çöktü üstüme...

Kız kulesi karşımda adalar yanımda...

Ey istanbul ne kaldı alacağın bende..

Bırak herşey kalsın istemem 

Üstü kalsın alacağım yok senden..', 'Akşam oldu yalnızlık çöktü üstüme... Kız kulesi karşımda adalar yanımda... Ey istanbul ne kaldı alacağın bende.. Bırak herşey kalsın istemem...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Taş']::text[], 8.5, '{"poet":"Bahtiyar Taş","poet_slug":"bahtiyar-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/istanbul-aski-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelle Koltukta', 'kelle-koltukta-timur-i-likan-y6dgy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağaçlar hayattır

Ağaçlar umuttur

Ağaçlar gelecektir

Kesmeyelim ağaçları

Yok etmeyelim ormanları

Ne demiş eskiler

Yaş kesen baş kesermiş

Giyotinler çoktan karıştı tarihe

Ama ülkemde mâlesef

Nice başlar koparılmakta gövdesinden

Câhilce ve acımasızca

Anlayacağınız

Kelle koltukta gidiyoruz

Geleceğe doğru koşar adımlarla

(28 Ocak 2006/ İstanbul)', 'Ağaçlar hayattır Ağaçlar umuttur Ağaçlar gelecektir Kesmeyelim ağaçları Yok etmeyelim ormanları Ne demiş eskiler Yaş kesen baş kesermiş Giyo...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kelle-koltukta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keskin Kalem', 'keskin-kalem-mustafa-dilki-dofj0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İyice bilenmiş kılıç kalemi

Şair Ali Dilki bir keskin kalem

korkusuzca taşa tutar alemi

Şair Ali Dilki bir keskin kalem

Hak hukuk yolunda kimseyi takmaz

Taviz vermez kimsenin sözüne bakmaz

Kuru gürültüye papuç bırakmaz

Şair Ali Dilki bir keskin kalem

Böylesi dünyada onun işi zor

Bana değil onu alçaklara sor

Taşı gediğine koymakla meşur

Şair Ali Dilki bir keskin kalem

Ondan başka şair yeğlemiyorum

İnanın iltifat eylemiyorum

Ağabeyim diye söylemiyorum

şair Ali Dilki bir keskin kalam', 'İyice bilenmiş kılıç kalemi Şair Ali Dilki bir keskin kalem korkusuzca taşa tutar alemi Şair Ali Dilki bir keskin kalem Hak hukuk yolunda ki...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/keskin-kalem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Becerebilseydim', 'becerebilseydim-selhan-yurt-ob4m8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğer sensiz kalmanın

Bu kadar acı verdiğini bilseydim; 

Ne gördüğümde o gözlerine bakardım,

Ne de yüreğimi titretmesine izin verirdim! 

Sadece gülüp geçerdim......

                                          Becerebilseydim....!', 'Eğer sensiz kalmanın Bu kadar acı verdiğini bilseydim;  Ne gördüğümde o gözlerine bakardım, Ne de yüreğimi titretmesine izin verirdim!  Sade...', ARRAY['Türk Edebiyatı','Şiir','Selhan Yurt']::text[], 8.5, '{"poet":"Selhan Yurt","poet_slug":"selhan-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/becerebilseydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Ben', 'i-cimdeki-ben-selhan-yurt-svppz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karşımda geçerken hep sen,

Sensizliğe karşı bir sigara yakıyor...

İçimdeki ben...

bir nefes kadar bana yakınken,

Ben her nefesimi bir asırlık çekiyorum

                                                Özleminden....!', 'Karşımda geçerken hep sen, Sensizliğe karşı bir sigara yakıyor... İçimdeki ben... bir nefes kadar bana yakınken, Ben her nefesimi bir asırlı...', ARRAY['Türk Edebiyatı','Şiir','Selhan Yurt']::text[], 8.5, '{"poet":"Selhan Yurt","poet_slug":"selhan-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/icimdeki-ben-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyarbakır sokakları', 'diyarbakir-sokaklari-bahtiyar-tas-hq7cw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu şehir DİYARBEKİR

Karanlıktır sokakları dardır

Ama o karanlık öyle birşeydir ki! ..

İçine gittikçe aydınlanır

Bir tarihi bilinmeyen surların üstüne çıkınca

O zaman anlarsın nasıl bir yerdir diyarbekir...', 'Bu şehir DİYARBEKİR Karanlıktır sokakları dardır Ama o karanlık öyle birşeydir ki! .. İçine gittikçe aydınlanır Bir tarihi bilinmeyen surlar...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Taş']::text[], 8.5, '{"poet":"Bahtiyar Taş","poet_slug":"bahtiyar-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/diyarbakir-sokaklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemezsin', 'sevemezsin-selhan-yurt-uesqz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlayamazsın....! 

Ruhumun, yüreğimin hatta

tüm hücrelerimin

senle oluduğunu...

                    Anlayamazsın...! 

Bilemezsin...! 

Sensiz kalmanın yokluğunu,

Sensiz kalmanın beni nasıl yorduğunu...

                                               Bilemezsin...! 

Göremezsin...! 

Sensizken o hep yalnız olan beni,

İçimde büyüyen küçük masum olan seni...

                                                             Göremezsin...! 

Sevemezsin...! 

Görmeden bendeki seni,

Yani hiç olmayan ya da olmayacak sendeki beni...

                                                                           Sevemezsin...!', 'Anlayamazsın....!  Ruhumun, yüreğimin hatta tüm hücrelerimin senle oluduğunu...                     Anlayamazsın...!  Bilemezsin...!  Sensiz...', ARRAY['Türk Edebiyatı','Şiir','Selhan Yurt']::text[], 8.5, '{"poet":"Selhan Yurt","poet_slug":"selhan-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevemezsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deyiş 12', 'deyis-12-ali-riza-unal-xt4cd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzel ile sohbet güzeldir,

Ehil ile muhabbet kemâldir,

Bu demde ihlas temeldir,

Sır verme cahile eceldir.', 'Güzel ile sohbet güzeldir, Ehil ile muhabbet kemâldir, Bu demde ihlas temeldir, Sır verme cahile eceldir....', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/deyis-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Onları Biliyorum', 'ben-onlari-biliyorum-yusuf-onder-bahceci-npjqy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belki seni bir söz ile tehdit ettiler,

Belki yalan söylediler tehdit ettiler,

Hani şimdi neredeler, nere gittiler,

Ben onları bilirim soysuzdur onlar.

Seni gerçek sevmedi ki bilsinler,

Ateşe atıl dese atılır inan sevenler,

Cânını da verir o, cân ver deseler,

Ben onları bilirim soysuzdur onlar.

Buradan meydan okuyorum onlara,

Dünya kimseye kalmıyor sen anla,

Seni seviyordum ne vardı inansana,

Ben onları biliyorum soysuzdur onlar.

Şimdiki hâlim olsaydı görürdüm hele,

Sonunda ölüm olsaydı bilirdim kele,

Yumruğu vururdum hepsi gelse de,

Ben onları biliyorum soysuzdur onlar.

Kele:Adana tabiriyle kız demek', 'Belki seni bir söz ile tehdit ettiler, Belki yalan söylediler tehdit ettiler, Hani şimdi neredeler, nere gittiler, Ben onları bilirim soysuz...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-onlari-biliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışırım Alışamadığım Yokluğuna', 'alisirim-alisamadigim-yokluguna-selhan-yurt-rv2fj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerine her baktığımda,

Gölgelerin denizine dalıyorum.

İçinde seni arıyorum

Kendim içinde beni arıyorum

Sende... 

Bazen sana o kadar yaklaşıyorum ki,

Belki bir salise kadar yakın,

Belki bir yıl kadar uzak! ! ! 

Evet bu aşk...

Sana değil, bana tuzak

Aşkınsa içimde kanayan bir yara! 

Yüreğimde kopsa da binlerce fırtına,

Bendeki seni sana anlatmaktansa,

Alışırım alışamadığım yokluğuna....', 'Gözlerine her baktığımda, Gölgelerin denizine dalıyorum. İçinde seni arıyorum Kendim içinde beni arıyorum Sende...  Bazen sana o kadar yakla...', ARRAY['Türk Edebiyatı','Şiir','Selhan Yurt']::text[], 8.5, '{"poet":"Selhan Yurt","poet_slug":"selhan-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/alisirim-alisamadigim-yokluguna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk-ı bedel', 'ask-i-bedel-bahtiyar-tas-eabm7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşkın bedel nakd-i ömrüme… 

dayanamam… 

giderim buralardan yoksan bende… 

seni sensiz yaşamak çareyse… 

bırakma… 

tek tesellim ölümdür… 

senden öte…', 'aşkın bedel nakd-i ömrüme…  dayanamam…  giderim buralardan yoksan bende…  seni sensiz yaşamak çareyse…  bırakma…  tek tesellim ölümdür…  sen...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Taş']::text[], 8.5, '{"poet":"Bahtiyar Taş","poet_slug":"bahtiyar-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ask-i-bedel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak / tı', 'yasamak-ti-mehmet-ali-demircan-fxhq9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir batım doğum,

Bir parça yaşam,

Bin kıymık özlem,

Bin bela yitim,

Bir yürek tapım,

Bir veçhe ölüm,

İçinde ne yaşanmışlıklar,

acısı bir başka,

sevdası hasret.

Sevda mı? 

Ya Mecnun ya Leyla,

Hem kahır hem zülüm,

her anı hoyratça.

Hasret mi? 

sorma gitsin.

Saymak işkence.

Çocuksu gönlünce,

Yaşamaktı delice. 

Hele ki, yürek mi? 

bak işte onu sorma! ..

o yürekte neler var neler,

sevmek delice, Kara sevda da.

Kavuşmak vuslatı mahşer de,

Yaşamaktı Dervişçe...

Ayrılıklar ise cehennem azabı.

her anı yasak bir oyun,

Çin işkencesi,

Rus ruleti.

Ve sonunda! ..

bir parça gülüş,

ve alabildiğine 

Kanlı hıçkırıklar, 

hışımla

Çağlayan göz yaşı...



28,01,2006 – 02,12

MADemircan.*Radyoerguvan.com 

*** Aynalar Gerçeklerin Ta Kendisidir. 

Konuş onunla, Doğruyu Söylemekten Çekinmeyecektir. ***', 'Bir batım doğum, Bir parça yaşam, Bin kıymık özlem, Bin bela yitim, Bir yürek tapım, Bir veçhe ölüm, İçinde ne yaşanmışlıklar, acısı bir baş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Demircan']::text[], 8.5, '{"poet":"Mehmet Ali Demircan","poet_slug":"mehmet-ali-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/yasamak-ti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öykü2', 'oyku2-levent-i-skenderoglu-y5i0z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İste sekte artık yaşayamayız 

Bu şehirde

İste sekte koca binalara 

Meydan okuyacak güç kalmadı

İstemesekte yutulduk 

Üzerimize çöktüler

Bağıramadık

Sesimizi bile çıkaramadık

İste sekte mümkün değil artık

Umutlansak ta, özle sekte

Gidiyoruz

Alın şehriniz sizin olsun

Siz oturun güzel dairelerinde 

Siz gidin alışverişe

Dev marketlere

Bizim köyümüzün soğuk sularında

Yıkanmaya hakkımız var

Bizde isterdik ama

Köyümüze mutlu olmaya

Köylü gibi yaşamaya

Ucu yanık mendillere

Türkü yakmaya

Aşık olmaya toprak damlara

Terimizle duş alana kadar

Yorulmaya harmanda

Odun sobası yakmaya

Çıkıp tepeye gönlümüzce

Haykırmaya

Kendimizle iç içe olmaya

İçimize dönüyoruz

Aslında size dargın değiliz

Sizde bizim dönmemizi 

İstemezdiniz aslında

Ama artık kal deseniz de

Kalamayız

Kremlerinizi aldık kullanmaya

Gidiyoruz ellerimiz toprak tutsun

Yaba tutsun çatlasın

Hem gecekondumuzdan iyidir

Toprak evimiz

En azından evimiz dediğimiz

Sahiplenebildiğimiz

Köprüden geçerken rahatça elimizi daldırıp suya

Kana kana içebildiğimiz yerlere gitmek arzumuz

Aslında bir şişe suya yüz bin lira vermekten değil

“keçinin uyuzu suyun gözünden içer” diyorsunuz  ya

Uyuz olmaya gidiyoruz

Siz tüyleri taralı keçi olun

Biz uyuz

Biz böyle mutluyuz

Sizi de bekleriz özletmeyin

Hangimiz olduğu fark etmez

Çalsanız bir  kapıyı

Açılır sonuna kadar

Hem öyle hırlı hırsız korkumuz yok

Siz dumanlı, puslu, kara şehrinizden bıkarsanız

Biz hep orada olacağız

Ucu bizde bucağı sizde şehir

İşimiz düşerse devlet dairelerine anca geliriz

Sağlık ocağı sözüde aldık ama ha deyince olmuyor

Hastanelerinizde uğrarız bir çay içmeye

Kısacası

Şehirli köyüne, köylü şehrine gerek

Hadi Allaha ısmarladık

			

			10.12.1999', 'İste sekte artık yaşayamayız  Bu şehirde İste sekte koca binalara  Meydan okuyacak güç kalmadı İstemesekte yutulduk  Üzerimize çöktüler Bağı...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/oyku2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-bahtiyar-tas-ayppq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'annemsen yokken buralar dar bana 

sensiz ne yaparın bu koca istanbulda

koca istanbul dediğime bakma

sen yokken annem o bile bana dar gelir

şu eşi benzeri olmayan istanbul bana dar 

annem 

bilirim bizimiçin neler yaptığını 

hakkını nasıl öderiz be anne

senin tekisteğin benim okumamdı

okudum anne koca adam oldum 

ama sen yokkrn ben adam olmuş neyime 

senin için anne herkesin dili kısaldı

bana okuyamaz diyolardı şimdi hiçbiri 

karşımda yok be anne

senin hakkını nasıl ödenir bilmem...

ANNEM', 'annemsen yokken buralar dar bana  sensiz ne yaparın bu koca istanbulda koca istanbul dediğime bakma sen yokken annem o bile bana dar gelir ş...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Taş']::text[], 8.5, '{"poet":"Bahtiyar Taş","poet_slug":"bahtiyar-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/annem-134-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairim(Seninim)', 'sairim-seninim-erdener-kirim-g0uzz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şairim,

Tüm servetim,

Kağıdım ve kalemim

Bedenim,

Ruh taşımaktan yorgun bir işçi

Her an paydos edecek

Beyinim,

Düşüncelerin rahmi

Birçok doğumlara gebe

Yüreğim,

Tüm sevgilerin kaynağı

Şu an senin esirin

Şairim,

Yüreğim,beyinim,bedenimle

Seninim

(İstanbul.............28/01/2006)', 'Şairim, Tüm servetim, Kağıdım ve kalemim Bedenim, Ruh taşımaktan yorgun bir işçi Her an paydos edecek Beyinim, Düşüncelerin rahmi Birçok doğ...', ARRAY['Türk Edebiyatı','Şiir','Erdener Kırım']::text[], 8.5, '{"poet":"Erdener Kırım","poet_slug":"erdener-kirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sairim-seninim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pembe Sepetim', 'pembe-sepetim-hulya-endogan-lklxx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Binbir sevgi gülünün

Mis gibi kokan duyguların

Yer aldığı pembe sepetim benim.

Yanındaki çiçek süsün

Hele askındaki nazar boncuğun

Ne güzel durur pembe sepetim benim

Sendeki çiçek sanki refahlığın anlamı

Güzel dünyaların anı

Ne kadar hoş durursun pembe sepetim benim

Elimle süsleyip

Bakışlarımla yenilik kattığım

Pembe sepetim benim.

Düşlerimdeki renkler

Yaşadığım güzellikler

Pembe sepetimdedir benim', 'Binbir sevgi gülünün Mis gibi kokan duyguların Yer aldığı pembe sepetim benim. Yanındaki çiçek süsün Hele askındaki nazar boncuğun Ne güzel ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Endoğan']::text[], 8.5, '{"poet":"Hülya Endoğan","poet_slug":"hulya-endogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/pembe-sepetim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam(ak)', 'yasam-ak-figen-aydogmus-hrzce', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eksilen hayatımız artılara muhtaç

Yalanda olsa yaşam geçiyor yarı tok yarı aç

Lingo lingo şişeler zenginin dilindeki

Emekçide ise cep delik gırtlağa kadar borç

Masallar diyarında yaşarız ağlarken gülmeye aç

F.A. 28.01.2006', 'Eksilen hayatımız artılara muhtaç Yalanda olsa yaşam geçiyor yarı tok yarı aç Lingo lingo şişeler zenginin dilindeki Emekçide ise cep delik ...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yasam-ak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Senden Ayrıyım Cân Senden Ayrı', 'ben-senden-ayriyim-c-n-senden-ayri-yusuf-onder-bahceci-5qthv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben senden ayrıyım cân senden ayrı,

Senden bana şimdi ne dertler kaldı,

Şu ömrümün çiçeğini yaktı zamharı,

Ben senden ayrıyım, cân senden ayrı.

Bahçede solan güllere bakar ağlarım,

Dertli şiirler yazarım da yakar, ağlarım,

Mektuplara, albümlere bakar ağlarım,

Ben senden ayrıyım, cân senden ayrı.

Uzayan  yollara bakar bakar ağlarım,

Bir sigara yakarım savururda ağlarım,

Yarin eller almış sa ben nasıl yaşarım,

Ben senden ayrıyım, cân senden ayrı.', 'Ben senden ayrıyım cân senden ayrı, Senden bana şimdi ne dertler kaldı, Şu ömrümün çiçeğini yaktı zamharı, Ben senden ayrıyım, cân senden ay...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-senden-ayriyim-can-senden-ayri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-nazife-sener-w6drk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gani olsa bu dünyada 

Kala senin malın dostum

Bakmazsan aha feryada

Nola senin halin dostum 

Ganimetin nehir olsa

Çektirdiğin kahır olsa

Neye yarar zehir olsa

Kula senin dilin dostum

Ya bir Paşa ya bir bey''sen

Bir canı kin ile sevsen

Onun yaprağına değsen

Kopa senin dalın dostum

Çok olsa ekmeğin aşın

Bin yıla ulaşsa yaşın

Gelmezse bacın kardaşın

Neye yarar yalın dostum

İster şah ol ister çoban

İster kürk giy ister aban

El ise hısım akraban

Kötü çıkar falın dostum

Bulunmaz seni kayıran

Eti kemikten ayıran

Canı canandan ayıran

Yılan sokar elin dostum

Ganimetin varın olsa

Eğer incittiğin varsa

Petek petek arın olsa

Neye yarar balın dostum

(İstanbul, 28.10.1992)', 'Gani olsa bu dünyada  Kala senin malın dostum Bakmazsan aha feryada Nola senin halin dostum  Ganimetin nehir olsa Çektirdiğin kahır olsa Ney...', ARRAY['Türk Edebiyatı','Şiir','Nazife Şener']::text[], 8.5, '{"poet":"Nazife Şener","poet_slug":"nazife-sener","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dostum-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-halime-ayam-cerrah-b6qgs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kadeh mutluluk sun gözlerinden

Mümkünse alkolsüz olsun be güzelim

Zaten zil zurna sarhoşuz aşkından

Önce kirpiklerinden süzülsün damlalar 

Hiç kırılmadan, usulca...

Sonra yanağındaki çukurlara dolsun.

Sen kımılda onlar düşsün.

Ve ben; 

Kana kana içeyim dudaklarından

O tertemiz,saf aşkı...', 'Bir kadeh mutluluk sun gözlerinden Mümkünse alkolsüz olsun be güzelim Zaten zil zurna sarhoşuz aşkından Önce kirpiklerinden süzülsün damlala...', ARRAY['Türk Edebiyatı','Şiir','Halime Ayam Cerrah']::text[], 8.5, '{"poet":"Halime Ayam Cerrah","poet_slug":"halime-ayam-cerrah","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevdigim-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunun Suçu Bende Bende', 'bunun-sucu-bende-bende-yusuf-onder-bahceci-ogwk8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senden bana gelmez haber,

Ben yanmışım sonum keder,

Deme bana kader, kader,

Bunun suçu bende, bende.

Gönlün yok sanmıştım bende,

İşte böyle ellerim kaldı belde,

Sen de bir şey demedin be,

Bunun suçu bende, bende.

Gerçek sevenler şiir yazar,

Yazar yazar her gün bozar,

Kendi kendine söyler, kızar,

Bunun suçu bende, bende.', 'Senden bana gelmez haber, Ben yanmışım sonum keder, Deme bana kader, kader, Bunun suçu bende, bende. Gönlün yok sanmıştım bende, İşte böyle ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bunun-sucu-bende-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fren Sesi', 'fren-sesi-i-brahim-etem-bakir-z97dg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fren sesi

On kişiden kaç kişiye neyi anımsatır

Telaş mı? 

Korku mu? 

Yoksa zevk mi verir

Hangi fren sesi

Bir kazayı hatırlatmadıki

Yada ardından

Çığlıkları yükseltmedi mi gök yüzüne

Fren sesinin

Bir tek otoban lastiklerinde

Jazz sesi çıkardığını sanmayın

Bir hayattaki

Bir candaki

Fren sesinin farkına varmadınız mı

Hayatına ani bir fren yapıp 

Bir insanın değiştiğini görmediniz mi

Ya mutluluğa yapılan frenler

Ya sevgiye yapılan frenler

Ya huzura yapılan frenler

Bunların adı ne

Mutluluğu; sevgisizlik 

Sevgisizliği; huzursuzluk

Huzursuzluğu da biz yaratıyoruz

Bu sesi de mi duymadınız

Fren sesi denince....

Sahi ya

Hangi şöför istemedikçe

Fren sesiyle korkuttu mu 

Yol yolcularını

Bir de yayaları

Hangi acemiye güvenip

Rahat bir uyku çekebildiniz ki

Yol boyunca

Yüreğiniz elinizde

Eliniz en sevgilinizin elinde olmadı mı ki

Poker masaları 

En son hangi aile yoluna fren yaptı

Kimler; 

Çocukların geleceğini frenledi

Neden bir yuvanın 

Yapı taşlarının fren sesini duymadınız

Hangi karanlık,

Frenleyip bizi bırakıp gitti ki

Peki ya

Neden biz; 

Birbirimize,

Hatta can parçamıza

Kalbimizin yarısına 

Bizi sefaletle büyüten ellere

Hayatını bize emanet eden genç kıza

Kaçımız faklar vurup

Birbirimizin geleceğine…

Fren sesini duyurmadık mı

Kimimiz

Yalnız koyarak

Başının çaresine bırakmadık ki

Hangimiz

Ana kucağına fren yapıp

Üç günlük sevgiliye koşmadık ki

Birleşmiş Milletler gibi 

Hayatını birleştirip

Hayat yolunda

Çık git hayatımdan diye

Defetmedim mi

Freni patlamış çocukların

Minik sokak kavgaları

Bahane olmamış mı büyüklerimize

Ne yaptığının bile farkında olmayan tavuğa

''Kışt'' deme bahanesiyle 

Canlar yanmadı mı

Kalpler kırılmadı mı

Küskünlükler yaratılmadı mı

Çok ileri giderek kan da dökülmedi mi? 

Yine de bunların hepsini

Biz bize yapmıyormuyuz

Can parçamız çocuklar

Yine hiçbir şey olmamışçasına

Birbirleriyle sobe oynayacak

Akşam olunca

Eve gitmek için birbirlerini

Defalarca ebeleyecekler

Hiç umurunda olmayan tavuk ise

Değer verdiğimiz misafir sofrasına aş olacak

Hangi yol bizi birliğe götürecek

Hangi yol bizi hiç ayırmayacak

Hangi yol bizi muhabbetle kucaklayacak

Hangi yol bizi bizden ayıracak

Hangi yol bizi bize hasım edecek

Neleri frenleyip

Neleri frenleyeceğimizin yolunu bulmalıyız

Fren sesinde

Sedece iki yol var

Ya savaş

Ya barış

Biz savaşa fren tutuyoruz

Lanetlenmişler ise

Barışa fren tutuyorlar

Bu fren sesi insanlığa huzur verecek

SAVAŞA FREN SESİ

E.B...', 'Fren sesi On kişiden kaç kişiye neyi anımsatır Telaş mı?  Korku mu?  Yoksa zevk mi verir Hangi fren sesi Bir kazayı hatırlatmadıki Yada ardı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Etem Bakır']::text[], 8.5, '{"poet":"İbrahim Etem Bakır","poet_slug":"i-brahim-etem-bakir","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/fren-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedevinin Aşk-ı', 'bedevinin-ask-i-erdinc-batur-2oi3i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ütüsüz bir gömlek giyindiğim aşk

Kırıkları aynada yüreğimin, çizgisi berrak

Gecenin karanlığı git gide matlaşır

Sana yazdığım sayfalar gözlerimden daha ıslak

Ben tutsam içimde, boğazım yutkunur

Kesmez genzimi başka bir kadın

Kapısı açılmaz sen yokken şu odanın

Vurduysa kurşun, kanayandır sol yanım

Papatya türküsü değil seni seviyorum demek

Yokluğunda ağlar serçeler, kanaryalar

Sensiz aşkın azametinde parça-parça yürek

Çare değil şu cana kasten zulmetmek

Kanayan yanlarımda teninin kokusu

Denizi İstanbul’un, akşamında korkusu

Perde-perde sarar yalnızlığın efsunu

Yıllara yaslı duran bir yanı düşük omuzum

Sona geldiğimi sanmıştım 

Yürürken bu sokakları yavaş-yavaş

Bir banliyöde rastlamak sana ne tuhaf! 

Geride bırakılan yıllar değişmemiş sende yine aynı

Belli oluyor mudur; 

Vurukluğum, düşkünlüğüm, sana yanmışlığım,

Ateşi sönmeyen hislerim, 

Bu yarası kapanmayan bedevini aşk-ı? 

Gelmiyor gönlümden bu aşkın selasını vermek

İçimden kalyonlar çekilir senin sessizliğinde...', 'Ütüsüz bir gömlek giyindiğim aşk Kırıkları aynada yüreğimin, çizgisi berrak Gecenin karanlığı git gide matlaşır Sana yazdığım sayfalar gözle...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Batur']::text[], 8.5, '{"poet":"Erdinç Batur","poet_slug":"erdinc-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bedevinin-ask-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah', 'gunah-halime-ayam-cerrah-96ci0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'boynumda boncuk boncuk maviler

bin nazar değsin bırak! 

bırak yere dökülsün inciler.

göğsümde ince uzun parmakların,

bir nefeslik uzağında günah,

günahın içinde dudakların...

kalbur yürekli kadınım ben; 

ne sevildim ne de sevdim eksizsiz.

çamurlara bulandıı tertemiz tenim,

her ikindinin ılık yağmurunda,

bacaklarımdan dökülen bulanıklık, sen...', 'boynumda boncuk boncuk maviler bin nazar değsin bırak!  bırak yere dökülsün inciler. göğsümde ince uzun parmakların, bir nefeslik uzağında g...', ARRAY['Türk Edebiyatı','Şiir','Halime Ayam Cerrah']::text[], 8.5, '{"poet":"Halime Ayam Cerrah","poet_slug":"halime-ayam-cerrah","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gunah-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
