INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Annem!', 'canim-annem-halide-selcan-karagul-jqn2o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Canım Annem! ! ! 

Bak ben geldim... 

Seni canından çok seven... 

Can kızın... 

Aç gözlerini annem! .. 

Bak ben geldim... 

Biricik can kızın... 

Biliyorum! .. 

Çok sancın var... acı çekiyorsun... 

Betin benzin sararmış, titriyor ellerin.. 

Gözlerinde acı, yüzünde keder var annem! 

Bir bilsen! ... 

Seni böyle görmeye 

Dayanmıyor yüreğim 

İçim yanıyor... çaresizim... acını dindirmekte. 

Gözyaşlarım durmuyor yerinde... 

Çaresizlikten çağlamakta. 

Seni kaybetme korkusu sardı benliğimi 

Ümitsizlik yakıyor yüreğimi... 

Hadi aç gözlerini annem! 

Bak ben geldim... 

Senin gözünden kıskandığın... 

Biricik can kızın... 

Aç gözlerini gör annem! 

Ayrılık hasreti düştü gönlüme 

Acısı yüreğimi yakıyor annem. 

Ellerin avuçlarımın arasında 

Sanki üşümüş annem. 

Beni sensiz bırakıp gitme 

Seni şimdiden özledim annem. 

Canım annem! 

Son bir defa bak gözlerimin içine 

Orada bir tek sen varsın... 

Sen gözbebeğimsin... 

Biliyorsun... 

Seni çok seviyorum... 

Çok seviyorum annem..... 

17 Eylül 2005', 'Canım Annem! ! !  Bak ben geldim...  Seni canından çok seven...  Can kızın...  Aç gözlerini annem! ..  Bak ben geldim...  Biricik can kızın....', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/canim-annem-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllarında Ötesindeydi Gözlerin', 'yillarinda-otesindeydi-gozlerin-sair-odesus-2twbt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllarında ötesindeydi gözlerin

ve yorgun ve çökmüş ve kanlı.

Binlerce ceset içinde hangisinde

Hangisinde olduğunu bilmediğim.

Yıllar kadar canlıydı gözlerin

ve hızlı ve hain ve katil

makyajın altında elinde tırpan,

matarasında yudum yudum kan.

Güneş gibi parlaktı gözlerin

ve keskin ve yakıcı ve hoş

saklıydı herşey dalgalanmasında gözlerinde ışığın

Soğuk çelik kıvılcımları, yansıması ölümün sıcak tenlere.

Buz gibi bir gecenin içinde gözlerin...

Yıldızlar kadar uzak, yıldızlar kadar soğuk

Penceresinde cam olanların sevgilisi

Odasından soba olanların ve gözlerin.

Salkım saçak kirpiklerin

Ve solgun ve yıkılmış ve kurak

Gözlerinin nemi mi bitmiş? 

Yoksa yüreğinin kudretide mi terketti seni? 

Biricik güneş sanmıştım gecenin ayazında

parlayan gözlerini titreşen göz kapaklarının altında

Kimbilir ''yok, ben değilim'' diyordun

Haklıydın da! 

Bir mermiydi gözlerin, hani şu, havada iz bırakanlardan

Kızıl bir başlangıç, pembe bir yol, kırmızı bir leke

Yaşananları tarifledim, hepsi buydu işte.

Yıllarında ötesindeydi gözlerin

Zamanla birlikte akan dingin denizlere ulaşmak için

Çağlayarak gözden uzaklaşan', 'Yıllarında ötesindeydi gözlerin ve yorgun ve çökmüş ve kanlı. Binlerce ceset içinde hangisinde Hangisinde olduğunu bilmediğim. Yıllar kadar ...', ARRAY['Türk Edebiyatı','Şiir','Şair Odesus']::text[], 8.5, '{"poet":"Şair Odesus","poet_slug":"sair-odesus","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yillarinda-otesindeydi-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niyazım Rabbime, Çare Ondadır...', 'niyazim-rabbime-care-ondadir-halide-selcan-karagul-jzi1q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Niyazım Rabbime, Çare Ondadır...

Kan gölüne bulanmış bedenler, 

Yüreğimi dağlar, gözlerim ağlar, 

Biçare kalıp, uzanmaz eller, 

Niyazım Rabbime, çare ondadır... 

Vicdansız yürekler, zalım eller, 

Küçük fidanlara bir bir kıydılar, 

Acımadan dünyalarını başlarına yıktılar, 

Niyazım Rabbime, çare ondadır...... 

Donuklaşmış, o küçük güzel gözler, 

Bembeyaz kesilmiş, o masum yüzler, 

Kan gölüne düşmüş, minik bedenler, 

Niyazım Rabbime, çare ondadır.... 

Masum bedenlere nasıl kıyarlar, 

Bombalarla paramparça yaparlar, 

Demokrasi adıyla tüm canlara kıyarlar, 

Niyazım Rabbime, çare ondadır...... 

14.09.2004', 'Niyazım Rabbime, Çare Ondadır... Kan gölüne bulanmış bedenler,  Yüreğimi dağlar, gözlerim ağlar,  Biçare kalıp, uzanmaz eller,  Niyazım Rabb...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/niyazim-rabbime-care-ondadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Uslanmaz Bir Zırdeliyim', 'ben-uslanmaz-bir-zirdeliyim-atilla-guler-7f5tu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hayat

bir kez daha karşı koyuyorum

sana

bir kez daha

aldırmıyorum yüreğime batan

hayal kırıklıklarıma

biliyorum

ben d e l i y i m

ben uslanmaz bir z ı r d e l i y i m

kim ne derse desin

s e  v g i  ölmez

umutlardır sadece ölen 

düşlerin

kazanmaya çalıştığın 

ölmedikçe 

sen

sürer gider bu böyle

bir kez daha

hiç düşünmeden

sorgusuz sualsiz bu kez

bir çocuğun ellerine tutuşturulan uçurtma gibi

h e r  ş e y  en yükseklerde

sevginin bir parçası/i n a n m a k

duraklar olmasın bu kez

…olmayacak

bu kez yenemeyeceksin

benim olacak zaferler tüm ihtişamıyla 

ilk defa kaybedecek

hayat bu kez

d e l i  bir y a n g ı n  yüreğimde

hem de  z ı r d e l i', 'hayat bir kez daha karşı koyuyorum sana bir kez daha aldırmıyorum yüreğime batan hayal kırıklıklarıma biliyorum ben d e l i y i m ben uslanm...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ben-uslanmaz-bir-zirdeliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım Ermedi', 'aklim-ermedi-tibet-avci-6v630', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Erimekte mi vardı

Bu kısacık varoluşta

Kar adam

Kardan adam

Kardan bile adam oluyor yahu

Bir bizden olmuyor heyhat

İmalat hatası mı var yoksa,

Yada ne bileyim 

Bizimmi bir falsomuz oldu yaradılışta

Kendimde değildim

Hatırlamıyorum

Ne bileyim.

Pek düşündürüyor beni

Kardan adam

Kar? 

Adam? 

Adammısın ulan! ? 

Dikilmiş bahçenin orta yerine

Kara kaşlı,kara gözlü

Kel başında lenger şapka

Bir gıdım güneşe bakar adamlığın

Üç gün koyarsın postanı

Sonrasında cılkın çıkar

Yine de kardan adamsın

Parmağını kıpırdatmadan

Adam sıfatına girersin

Ben kuş tutsam bi tarafımla

Sıfatım olmaz

Varamadım bu işin sırrına

En iyisi bulaşmamak sana', 'Erimekte mi vardı Bu kısacık varoluşta Kar adam Kardan adam Kardan bile adam oluyor yahu Bir bizden olmuyor heyhat İmalat hatası mı var yoks...', ARRAY['Türk Edebiyatı','Şiir','Tibet Avcı']::text[], 8.5, '{"poet":"Tibet Avcı","poet_slug":"tibet-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/aklim-ermedi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki arada...', 'i-ki-arada-reyhan-tataroglu-1tx7d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'arkamdan

                                        bir

                                        ses

                                        ''''geçmiş

                                        olsuna

                                        gel! ''''

                                        dedi

                                        tam

                                        dönerken

                                        ''''hoşgeldin''''

                                        beni

                                        engelledi', 'arkamdan                                         bir                                         ses                                         ''''g...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iki-arada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneee! ...', 'anneee-halide-selcan-karagul-d5jn9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anneee! ...

Dünya karışmış iyice 

Kan, barut kokusu sarmış her yeri 

Güçlü zayıfı eziyor 

Herkes kendi menfaatinde 

Kimse kimseyi takmıyor... 

Ahhh! ! ! 

İnsanlık ölüyorrr! ! ! 

Çocuklar açlıktan ağlıyor..! 

Üzülüyorum anne..! 

İçim çok yanıyorrr! ! ! 

Benim hissettiklerimi sen de hissediyor musun anne..? 

Senin de için yanıyor mu? 

Elinden oyuncağı alınmış çocuk gibiyim 

Kalbim kırık, acıyor... 

Biliyor musun..? 

İçimde yangın var, alev alev yakıyor anne..? 

Bir damlacık su yok ki söndüreyim 

Tüm sular sanki bana inat, akmıyor..! 

Göz yaşlarım da akmıyor 

İçimdeki yangın kurutmuş göz pınarlarımı 

Bir damla olsun akmıyor anne..! 

Ahhh! ! ! 

Anneee! ! ! içim yanıyorrr..! 

İnsanlar çok acımasız, 

Çocuklar ölüyorrr! ! ! 

İnsanlık yok oluyor anne..! 

Neden..! Ben de bilmiyorum..! 

Ahhh! ! ! Bir bilsem..! Bir bilsem anne..! 

Öyle çaresizim ki... 

Sen de benim gibi içimdeki yangını hissediyor musun anne..? 

Duyuyor musun..! ? Duyuyor musun sessiz çığlıklarımı..? ! 

Ahhh! ! ! 

İnsanlık ölüyorrr! ! ! 

Anne İçim yanıyor..! 

Anneee..! ! ! 

27.05.2005', 'Anneee! ... Dünya karışmış iyice  Kan, barut kokusu sarmış her yeri  Güçlü zayıfı eziyor  Herkes kendi menfaatinde  Kimse kimseyi takmıyor.....', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/anneee-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Bebek', 'beklenen-bebek-halide-selcan-karagul-ib5qh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beklenen Bebek 

- Merhaba komşu nasılsın? 

Geldi mi beklenen can 

Aman...! Bizi aldı heyecan 

Senden çok meraktayız inan 

- İyiyim ya...! Bir de bana sorun 

Kız mı erkek mi...? Bir de isim bulun 

Ha erkek ha kız, farketmez cinsiyeti çocuğun 

Yeter ki hayırlı olsun...! 

Aman komşular yanım da durun 

Sevincime ortak olun... 

- Hey komşum...! Gözün aydın...! 

Nur topu maaşallah, doğdu kızın 

Hayal ettin ya nasıl, bebeğin 

İsmi de gelişi gibi ''Hayal'' olsun 

- Komşularım sağolun 

Hepinizden Allah razı olsun...! 

Bebeğin gözleri yemyeşil bakın 

Aman nazar değmesin 

Nazar boncuğu takın...! 

Maaşallah ne de şirin 

Bahtı da güzel olur inşaallah, dua edin... 

İsmi de gelişi gibi ''Hayal'' olsun 

Hayalle beklenen bebeğin... 

30.04.2005', 'Beklenen Bebek  - Merhaba komşu nasılsın?  Geldi mi beklenen can  Aman...! Bizi aldı heyecan  Senden çok meraktayız inan  - İyiyim ya...! Bi...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/beklenen-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Porno Fazilet', 'porno-fazilet-ali-cam-0puvk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her Pazar giyerdi miniyi alta,

Çıkardı sokağa, atardı olta,

Kimse karışmazdı yediği halta,

…..Yediden yetmişe severdi millet,

…..Milletin gülüydü Porno Fazilet.

Genci yaşlısını dökerdi yola,

Konardı her hafta bir başka dala,

Gülerdi evliye, bekara, dula,

…..Boyunu posunu överdi millet,

…..Milletin gülüydü Porno Fazilet.

Çoktu arkasından işmar edeni,

Rüzgarda sallanır narin bedeni,

Hem bey sever hem de koyun güdeni,

…..Kızın arkasında davardı millet,

…..Milletin gülüydü Porno Fazilet.

Gündüz başka idi, gece bir başka,

Onu yolda gören gelirdi aşka,

Uğrardı yalıya, konağa, köşke,

…..Göğsüne yüzlükler sıvardı millet,

…..Milletin gülüydü Porno Fazilet.

Ne zaman uzasa mini bir karış,

Küfrün iftiranın bini bir kuruş,

Etek kısalınca kurulur barış,

…..Her nevi ağıda duvardı millet,

…..Milletin gülüydü Porno Fazilet.

Kim Suçlu?', 'Her Pazar giyerdi miniyi alta, Çıkardı sokağa, atardı olta, Kimse karışmazdı yediği halta, …..Yediden yetmişe severdi millet, …..Milletin gü...', ARRAY['Türk Edebiyatı','Şiir','Ali Çam']::text[], 8.5, '{"poet":"Ali Çam","poet_slug":"ali-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/porno-fazilet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örtüşmeyenler', 'ortusmeyenler-bahaettin-karakoc-jxck6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '- Değerli Üstad''ımızın mürekkebi kurumamış bir şiirini, ilk kez ANTOLOJİ okurları için yayınlıyoruz...

en tenha yanımdan öpüyor yağmuru duyan ışıklar

bir mendirek gibi uzanmış sulara yorgun bedenim

nereden zuhur eder ki bu deli sarmaşıklar? 

tekinsiz çığlıklarla kuşatılan benim

ne yapsam dış ile iç örtüşmüyor.

tenimde nota nota gezinirken böcekler

ruhum kendini yeniler bir şarkının nakaratında

ayak ucumda yorgun düşmüş bir fener bekler

sesimin fotoğrafı dolaşır gök katında

ne var ki merkezle uç örtüşmüyor.

gez dedik, göz dedik, arpacık dedik

bir hedef belirleyip bastık tetiğe

kaç geceyi kaç gündüze teyelledik

konu olduk yazılmamış betiğe

sevgi ile nefret hiç örtüşmüyor.

yalpalayıp duruyorum doğduğum günden beri

gözlerimin ufuklarda kanat çırpması da kaçak

beni benden usandırır sevgilinin sitemleri

can kurbanlık, zaman ise en keskin bıçak

verilen cezayla suç örtüşmüyor

bu gece sevenler için yatacağım istihâreye

ter içinde uyanacağım seherden önce

yüreğimi peynir diye sunacağım her aç fareye

bir daha, bir daha düşüneceğim ince ince

hayat öpücüğüyle öç örtüşmüyor

Bahaeddin KARAKOÇ - 24.01.2006', '- Değerli Üstad''ımızın mürekkebi kurumamış bir şiirini, ilk kez ANTOLOJİ okurları için yayınlıyoruz... en tenha yanımdan öpüyor yağmuru duya...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ortusmeyenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sîneye Çekerim Yeter ki Aklansın Kuşlar', 'ben-s-neye-cekerim-yeter-ki-aklansin-kuslar-bahaettin-karakoc-k7ycv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '- Saygıdeğer Üstad''ımızın henüz mürekkebi kurumamış bir şiirini, ilk kez ANTOLOJİ okurları için yayınlıyoruz...

ben bir ardıç ağacıyım şu tepenin açığında

yanarım, üşürüm, kimseciklerin haberi olmaz

gölgeme sığınanlar yaz sıcaklarında

kışın iyi niyetlerle semtime gelmez

kapımı çalanlar baltayla çalar

yaralarımın nasıl sızladığını tarif edemem

yanar kora dönüşürüm, sönünce kül olurum

yine de kimseciklere kin güdemem

her zaman sevgi egemendir yüreğime.

yıldızlar o kadar yaklaşırlar ki yaz geceleri

kim serper gökyüzüne bunca vişne çiçeklerini? 

uzanıp tek tek  devşiresim gelir

kış geceleri içime çekilip hayâller kurarım

arada bir konuğum olur dostum puhukuşu

bilgece büzülüp düşünür, dinlerken başını sallar

sular buz tutmuş, dağlardan figânlar yükselir

ezgili kar aydınlığında kurtlar sevişir

haritalar sapa düşer düşlerime.

gökyüzünün çizgisiz maviliği damarlarımdan akar

yeryüzünün kar beyazlığı gözlerimi yakar

yaş yüze doğru tırmanışta, ben aynı yerde kelepçeliyim

gördüklerim kambur/kambur üstüne

duyduklarım yüzümü kızartıyor

aklımdaki tek şiir ıhlamurlar üstüne

dişlerim kesmez oldu, tırnaklarım köreldi

rüzgâr deli deli eser, siper kazamam

kader ipotek koymuştur yıllarıma.

ilk kez doğum yılımı kutlayacaktım zehir oldu

bir sürü yorgun kuşu konuk ettim diye dallarıma

onlar uçup gittiler güneye doğru

bense doğduğumda mıhlanmışım bu tepenin toprağına

kötü kötü öksürüyorum, “kuş gribi” olmuşum, tanı bu

bütün kanatlılara soykırımı yapılırken

aşı yok, serum yok, ne yapacağım ben? 

ucunda ölüm olsa da bağrım kuşlara hep açık

iftira ediyorlar kuşlarıma…

Bahaeddin KARAKOÇ - 23.01.2006', '- Saygıdeğer Üstad''ımızın henüz mürekkebi kurumamış bir şiirini, ilk kez ANTOLOJİ okurları için yayınlıyoruz... ben bir ardıç ağacıyım şu te...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ben-sineye-cekerim-yeter-ki-aklansin-kuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Debir - Akrostiş', 'debir-akrostis-halide-selcan-karagul-8cebc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'DEBİR



Düşlerim mi beni aldatır, gerçekte var mısın? 

Elimi uzanıp dokundursam sana can mısın? 

Baktığım her yerde gördüğüm hayalim misin? 

İçtiğim yudum yudum suyumda ki  zerrecik misin? 

Rüyalarımı süsleyen desen misin, renk misin? 



                   xxxxx





Dünya döndükçe parıldayan yıldız mısın, ay mısın? 

Enginleri delip geçen ışık huzmesi misin? 

Beni benliğimden alan güzel dost sen misin? 

İçimde ılgıt ılgıt esen rüzgarım mısın? 

Reyhan kokan çiçekte ki arı mısın, bal mısın? 



                    Xxxxx



Deryalar da dans eden deniz yıldızı mısın? 

Esip coşan yürekleri sakinleştiren meltem misin? 

Buz gibi pınarlardan su içen ahu gözlü ceylan mısın? 

İnleyen nağmelerde bir yanık beste misin? 

Ruhumuzu okşayan solmayan sevgi çiçeği misin? 



                     Xxxxx



  

Dere tepe aşarak yanınıza geldim mi? 

Eş dost meclisi görüp içinize girdim mi? 

Beraberce halleşip sevgileri derdik mi? 

İçimiz de yeşeren umut çiçekleri mi? 

Resimler dost yüzlerin buluştuğu belge mi? 



09.01.2004  /  10:30', 'DEBİR Düşlerim mi beni aldatır, gerçekte var mısın?  Elimi uzanıp dokundursam sana can mısın?  Baktığım her yerde gördüğüm hayalim misin?  İ...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/debir-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey canımın cananı...', 'ey-canimin-canani-halide-selcan-karagul-rk6a6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SEN NERELERDESİN? ! ..



Seni  görmeyince dinmiyor ki şu yüreğimin acısı

Hasretini çekiyorum geçmiyor  ki sancısı

Hayatımın anlamı yok boşa geçti yarısı

Ey canımın cananı sen nerelerdesin? ! ..



                Xxxxxxxx



Sen gelirsen gönül gözüm açılır

Gönül bahçem çiçeklenir şenlenir

Gül bülbüle kavuşursa sevinir

Ey canımın cananı sen nerelerdesin? ! ..



               Xxxxxxxx



Sen yoksun ki, canıma can kataydın

Üşüyen yüreğimi sevginle ısıtaydın

Kapkaranlık dünyamı nur olup dolduraydın

Ey canımın cananı sen nerelerdesin? ! ..



17.02.2004', 'SEN NERELERDESİN? ! .. Seni  görmeyince dinmiyor ki şu yüreğimin acısı Hasretini çekiyorum geçmiyor  ki sancısı Hayatımın anlamı yok boşa ge...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-canimin-canani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin! ...', 'sensin-halide-selcan-karagul-l5ge4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SENSİN! ... 



Seni ilk gördüğüm anda

Beni benden alan sensin,

Ümit vermediğim halde

Beni en çok seven sensin.



Her karşılaşmalarımız da

Yeşil gözlerinde ışıldayan

Sevda dolu bakışlarla

Beni benden çok sevensin.



Görüşmediğimiz zamanlarda

Beni hep özleyen sensin.

Ruhunu yakan hasret de

Beni hep arayan sensin.



Fırtınalar eserken içimde

Yüreğimi bilemezsin.

Beni en derin duygularla

Beni benden alan sensin.



Seni ilk görüşümde

Nasıl sevdim bilemezsin.

Hiç söylemesem de sana

İçimdeki sevda sensin.



10.05.2002', 'SENSİN! ...  Seni ilk gördüğüm anda Beni benden alan sensin, Ümit vermediğim halde Beni en çok seven sensin. Her karşılaşmalarımız da Yeşil ...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sensin-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Demek Aşk?', 'ne-demek-ask-mehmet-lutfu-aydin-waytv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acısız aşk, meyanesiz aş demek

İlahi meşk, kalbe dolan yaş demek

Karasevda yakışır mı hiç cana

Canansız köşk, bir harabe, taş demek', 'Acısız aşk, meyanesiz aş demek İlahi meşk, kalbe dolan yaş demek Karasevda yakışır mı hiç cana Canansız köşk, bir harabe, taş demek...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-demek-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yapmalı', 'ne-yapmali-fatih-mehmet-karaca-7dj5l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu dünyada ne yapmalı? 

   Önce düşün iyi taşın

   Çevreni ibretle incele

   Bu dünyada ben neyim de.

   Düşünmeyi bırakma hiç

   Sırlar saklı çevren bak hep

   Sırları çözer insan

   İbretle çevrene bak.

   Mutlu olmak isteyen insan,

   Yeni,bilmediği şeyler,

   Öğrendiği zaman

   Mutlu olur ozaman

   İnsan bu dünyada

   Neden var olduğunu

   Bilmeli, unutmamalı hiçbiran

   Mutlu olur insan ozaman.', 'Bu dünyada ne yapmalı?     Önce düşün iyi taşın    Çevreni ibretle incele    Bu dünyada ben neyim de.    Düşünmeyi bırakma hiç    Sırlar sak...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Karaca']::text[], 8.5, '{"poet":"Fatih Mehmet Karaca","poet_slug":"fatih-mehmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-yapmali-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğruluk', 'dogruluk-fatih-mehmet-karaca-eqqnc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalancının mumu

Yatsıya kadar yanar

Ataların sözleri

Doğruya götürür bizleri

Nasihat değil bu sözlerim

Ne haddime nasihat

Okuyan düşünsün anlasın

Yapmasın hata en aza indirsin

Yapılan hatalar varsa

Olmaması zaten imkansız

Hoş görmekle silinir

Ameller niyete göredir

Doğruyu arayan insan

Bir arayış içerisindedir

Kendi nefsin için istemediğini

Başkası içinde isteme

Doğru olmayı isteyen

Mutlu bir hayat sürer

Ben yapamıyorum diye

Vazgeçme  hemen

30.08.1999 Kırıkhan/Hatay', 'Yalancının mumu Yatsıya kadar yanar Ataların sözleri Doğruya götürür bizleri Nasihat değil bu sözlerim Ne haddime nasihat Okuyan düşünsün an...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Karaca']::text[], 8.5, '{"poet":"Fatih Mehmet Karaca","poet_slug":"fatih-mehmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dogruluk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğitim-Terbiye', 'egitim-terbiye-fatih-mehmet-karaca-r6gtr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eğitimsiz hiçbir şey

   Olduğu görülmemiş şey

   Büyümekte olan insan

   Eğitimsiz olur mu hiç

   Eğitimle neler olmazki

   Başarı eğitimle terbiye ile

   Bunu unutma sakın ha

   Eğitimsiz olur mu hiç

   Yapamıyorum deme uğraş

   Araştır öğren sor bul

   Eğit eğitil mutlu ol

   Eğitimsiz terbiyesiz olur mu hiç.

       

             25.06.2000 Kırıkhan/Hatay', 'Eğitimsiz hiçbir şey    Olduğu görülmemiş şey    Büyümekte olan insan    Eğitimsiz olur mu hiç    Eğitimle neler olmazki    Başarı eğitimle ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Karaca']::text[], 8.5, '{"poet":"Fatih Mehmet Karaca","poet_slug":"fatih-mehmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/egitim-terbiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağacı Sev Yeşili Koru', 'agaci-sev-yesili-koru-fatih-mehmet-karaca-3mi13', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağacı sev yeşili koru

   Ormansız bir vatan

   Olur mu hiç iyi düşün

   Orman ülkemin süsü

   Ağaç dik yeşili sev

   Örnek ol fidan dik

   Yaptıklarınla çevreni aydınlat

   Orman ülkemin süsü

   Yeşillik insanı dinlendirir

   Sağlıklı büyütür yaşatır

   Geleceği aydınlık istiyorsan

   Ağacı sev yeşili koru

  25.06.2000 Kırıkhan/Hatay', 'Ağacı sev yeşili koru    Ormansız bir vatan    Olur mu hiç iyi düşün    Orman ülkemin süsü    Ağaç dik yeşili sev    Örnek ol fidan dik    Y...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Karaca']::text[], 8.5, '{"poet":"Fatih Mehmet Karaca","poet_slug":"fatih-mehmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/agaci-sev-yesili-koru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir sevinir seninle oluşuma', 'sehir-sevinir-seninle-olusuma-elazigli-mustafa-kaya-obxhr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen sevgilim,

en güzel bir aşkı

başlatır gibisin

içimde çürüyen

duygularımı atıyorsun.

devrik bir ağaçtım.

sen,

nakışlı baharım

bir papatyanın içinde

beni mutlu eden

nefesim..

bol güneşli

bir günde farketti

kuşlar ilk kez bizi.

ahh anlıyorum

içim çağırıyor seni..

ben seninle seveceğim

seninle  öleceğim

sever gibi bakışların

nefesin

güzel çiçeklerle yaklaşır

birbiri içinde ellerimiz

omzuma yaslı başın.

göğün renginde

göz kırpar şehir

dizime uzanışına

her an sevinir.

sen bir tanem

sürme gözlüm

ölümümü süsleyen seccadem..

Mustafa kaya

29.01.2006 / üsküdar', 'sen sevgilim, en güzel bir aşkı başlatır gibisin içimde çürüyen duygularımı atıyorsun. devrik bir ağaçtım. sen, nakışlı baharım bir papatyan...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sehir-sevinir-seninle-olusuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayan Ölü', 'yasayan-olu-mehmet-lutfu-aydin-vudrh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat bütün hızıyla akarken deli dolu

Ben aç, susuz, uykusuz, yaşayan bir ölüyüm

Sevenler, sevilenler, sararken eli kolu

Ben bir aşkın umutsuz, kanayan bir gülüyüm', 'Hayat bütün hızıyla akarken deli dolu Ben aç, susuz, uykusuz, yaşayan bir ölüyüm Sevenler, sevilenler, sararken eli kolu Ben bir aşkın umuts...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yasayan-olu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapanmış Sayfa', 'kapanmis-sayfa-mehmet-lutfu-aydin-79jcs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen sevmenin ustası, ben acemi bir aşık

Sen bir gemi kaptanı, bense deli bir tayfa

Sen dünyamı ışıtan, olsan da tek bir ışık

Topa tutsan açılmaz, kapattığım bir sayfa', 'Sen sevmenin ustası, ben acemi bir aşık Sen bir gemi kaptanı, bense deli bir tayfa Sen dünyamı ışıtan, olsan da tek bir ışık Topa tutsan açı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kapanmis-sayfa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yahu!', 'yahu-reyhan-tataroglu-y30dl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hu! 

