INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-58 (M.S.) 27/01/2006', 'mektuplar-58-m-s-27-01-2006-mahzun-doga-rkipr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yazılmamış bir mektubunu daha aldım.

''Özledim'' diye yazmışsın.

Ve çokça ''seni seviyorum''muşsun.

Parmak izlerinden belli, 

ağlamışsın biraz çok.

Kalemin silik yazmış yine.

Belki de kâğıttandır.

Ya da postacı eksik getirmiş.

Ve yine yazmamışsın adresimi.

Unutkanlık, 

biliyorum.

Yaşlandık mı dersin ha.

Neyse.

Bunun da zarfı maviydi.

Tıpkı önceki beyazlar gibi.

Kenarlarına Mine çiçeği çizmişsin. 

Kokundan sıkmayı unutmamışsın yine.

Teşekkür ederim.

Gözlerimi açmadan okudum.

Sağlığım iyi demişsin.

Ama çokça öksürmüşsün.

O kadar diyorum sana şu sigarayı içme diye.

Ellerin de titremiş yazarken.

Belki de uykusuzluktan.

Ya da yorgunluktan.

Bence yaşlandık.

Ne dersin ha.

Neyse.

Bu mektubunu da aldım ya.

Nasıl sevindim bilemezsin.

Açmadan okumuşum heyecandan.', 'Yazılmamış bir mektubunu daha aldım. ''Özledim'' diye yazmışsın. Ve çokça ''seni seviyorum''muşsun. Parmak izlerinden belli,  ağlamışsın biraz ç...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/mektuplar-58-m-s-27-01-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğe Yemin Ettiğim An...', 'sensizlige-yemin-ettigim-an-hatice-guler-z5ret', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni bana getiren bir gece vaktiydi

Yıldızlardan  başına taç yaptığım an...

Sevdanı hissettiğim muhteşem gece

Kalbimde buzların eridiği

Sevgi tomurcuklarının yeşerdiği

Daha önce yaşanmamış 

Böylesine hissedilmemiş bir aşk''a

Sensizliğe yemin ettiğim an...

.......................................

28.01.2006', 'Seni bana getiren bir gece vaktiydi Yıldızlardan  başına taç yaptığım an... Sevdanı hissettiğim muhteşem gece Kalbimde buzların eridiği Sevg...', ARRAY['Türk Edebiyatı','Şiir','Hatice Güler']::text[], 8.5, '{"poet":"Hatice Güler","poet_slug":"hatice-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensizlige-yemin-ettigim-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-59 (M.S.) 28/01/2006', 'mektuplar-59-m-s-28-01-2006-mahzun-doga-3w8um', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlık.

Göremeyişimizin rengi.

Güçsüzlüğümüzün tesellisi.

Bilinmeyen aydınlık.

Sıfır''ıncı aralığımız.

Ömrümüzün vebası.

Karanlık.

Yaşamın kızdığın anlattığımları.

Kabul etmediğimiz kabullerimiz.

İkimize ait kör yerlerimiz.

karanlık.

Bilemediğimiz bildiklerimiz.

Yaşamın özürlü yanı.

Çaresiz umutluklar. 

Yani kızdığın baktıklarım.

Çarele beni öyleyse.

Bilmediğin şeyler öğret.

Özünle.

Gülüşünle güzümü.

Bir nokta yeşil açtır.

Hadi.

Damarlarını genişlet yolların.

Işıkları aç öyleyse.

Sevinçten sokağa dök beni.

Hadi.

Eklen bana.

Hafifleyeyim.', 'Karanlık. Göremeyişimizin rengi. Güçsüzlüğümüzün tesellisi. Bilinmeyen aydınlık. Sıfır''ıncı aralığımız. Ömrümüzün vebası. Karanlık. Yaşamın ...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/mektuplar-59-m-s-28-01-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlık', 'pismanlik-ahmet-beltekin-dqeek', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unutmuş diyorlardı, her şeyi unutmuş,

Hakikaten unutmuş,

Son fotoğrafta, elinden tutmuş.

Önce kendi de inanamadı, fotoğrafı görünce,

Nasıl unuttuğunu düşünmeye başladı; 

Yine başkalarını suçladı.

Sonra birdenbire,

Alıp eline fotoğrafı yırttı.

Unuttuğunu ispat edecekti; 

Her ne kadar kalbinden söküp atamasa da,

Unuttum deyince, her şey bitecekti...

Ve herkes de inanacaktı unuttuğuna; 

Ama gözlerindeki yaş olmasa...', 'Unutmuş diyorlardı, her şeyi unutmuş, Hakikaten unutmuş, Son fotoğrafta, elinden tutmuş. Önce kendi de inanamadı, fotoğrafı görünce, Nasıl u...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Beltekin']::text[], 8.5, '{"poet":"Ahmet Beltekin","poet_slug":"ahmet-beltekin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/pismanlik-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım', 'canim-ahmet-beltekin-eap6r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüzümdeki çizgiler senelerin sessiz izi,

Uykularımı bölen hüzün durağı canım.

Yağmur dolu gecelerde karşılar bizi,

Kalplerde sokağa çıkma yasağı canım.

Yüzümde geziyor, son yılların telâşı,

Yüreğimde hep sessiz tamtamlar canım.

Ve artık dar vakitlere kaldı gözyaşı,

Zorluyor beni bitmeyen akşamlar canım.

Hatıralarımı senelere verdim ilk,

Ben de güzellikleri bitmez sandım canım.

Ömrümüz zamandan çalınmış yolculuk,

Tükenmez diye sevinçlere kandım canım.

Ötesi yok kapılar kapanacak birden,

Mutluluk hep şarkılarda kalacak canım.

Bir başka şehre göçeceğiz bu şehirden,

Sokaklarda ayak izimiz olacak canım.

Umut artık çok uzaklarda uçan bir kuş,

Rüzgâra teslim olmuş mum gibiyiz canım.

Baharlar biter, geride kalandadır suç,

Ayaklar altındaki kum gibiyiz canım.', 'Yüzümdeki çizgiler senelerin sessiz izi, Uykularımı bölen hüzün durağı canım. Yağmur dolu gecelerde karşılar bizi, Kalplerde sokağa çıkma ya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Beltekin']::text[], 8.5, '{"poet":"Ahmet Beltekin","poet_slug":"ahmet-beltekin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canim-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuruyorum', 'kuruyorum-i-lknur-er-1p96y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Misafir gelme

Sevinçle açtığım kollarımı dolama boynuma

Kendi ellerimle idama mahkum etme beni

Mutluluksa

Bir ömür isterim seni kendime

Her sabah doğmalısın benimle en kuytularıma kadar yeniden

Sevdanın gölgesinde bulmalıyım kendimi

Hasretin ateşinde yakma bu zavallı bedeni

Ben sen olmuşum doğduğum ilk andan beri

Ya adam gibi sev ya adam gibi terket

Her gün yeniden öldürme bu yüreği

Bak kuruyorum parça parça....

29.01.05 01:22', 'Misafir gelme Sevinçle açtığım kollarımı dolama boynuma Kendi ellerimle idama mahkum etme beni Mutluluksa Bir ömür isterim seni kendime Her ...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kuruyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-ali-yurtseven-zhez5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aydınlığı gördüm yüzünde

Karşımda otururken

Gözlerin ışıl ışıl parlıyordu

Benimle beraberken

Ne oldu birden

Tüm zamansızlıklarda

Neydi birden değişen

Sihirmiydi acaba

Bizi birbirimize önce çeken

Sonra birbirimizden iten

Paylaşmak varken herşeyi

Neydi kafamızdaki çelişki

Yine de

Aydınlığı gördüm yüzünde

Gözlerin ışıl ışıl parlıyordu

02/1994', 'Aydınlığı gördüm yüzünde Karşımda otururken Gözlerin ışıl ışıl parlıyordu Benimle beraberken Ne oldu birden Tüm zamansızlıklarda Neydi birde...', ARRAY['Türk Edebiyatı','Şiir','Ali Yurtseven']::text[], 8.5, '{"poet":"Ali Yurtseven","poet_slug":"ali-yurtseven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozler-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkı farket', 'farki-farket-reyhan-tataroglu-nef7g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hayvanlar

                                           aç

