if (V) {document.layers[''sn''+i].left=X[i]; document.layers[''sn''+i].top=Y[i]+T}

else{si[i].style.pixelLeft=X[i]; si[i].style.pixelTop=Y[i]+T}

A[i]+=B[i]; 

