INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Oynama At Yarışı', 'gel-oynama-at-yarisi-yusuf-onder-bahceci-uvyti', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her gün altılı oynarsın,

Son ayakta yatarsın,

Vârın, yoğun satarsın,

Gel oynama at yarışı.

Bu sefer tutar dedin,

Bu at iyi kaçar dedin,

At eşşekti bilmedin,

Gel oynama at yarışı.

Ekseri hep yatacak,

Belki birgün tutacak,

Dostların da artacak,

Gel oynama at yarışı.

Sade at yarışı değil,

Horoz döğüşü de var,

Senin kalbinde ne var,

Gel oynama at yarışı.', 'Her gün altılı oynarsın, Son ayakta yatarsın, Vârın, yoğun satarsın, Gel oynama at yarışı. Bu sefer tutar dedin, Bu at iyi kaçar dedin, At e...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-oynama-at-yarisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-efsun-aydin-y2273', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine de yapıyorum.

Hasta mı olacagim ne? 

Biraz burnum akıyor, atesimde var sayılır…

Aşk! 

Icince sarhos oldugum ickim nerede? 

Ya ilacım olan Sevgili? 

Biliyorum…

Omrumden calıyor bu hastalık…

Az vaktim kaldi.

Nerdesin? 

Gelmene daha kac vakit var?', 'Yine de yapıyorum. Hasta mı olacagim ne?  Biraz burnum akıyor, atesimde var sayılır… Aşk!  Icince sarhos oldugum ickim nerede?  Ya ilacım ol...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ask-528-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Küreğiyle Çok Harçlar Kardım.', 'sevda-kuregiyle-cok-harclar-kardim-i-brahim-halil-demir-ft5em', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdanın kör bir yağlı kurşunu,

Vurdu beni ciğerimin tam ortasından.

Başıma bir türlü konmayan talih kuşunu,

Uçurdular sevda yolunun ta en başından.

Kanatlarını çırpmıyor artık o da küsmüş,

Birini gördüm o da ben gibi sevda oltasına düşmüş.

Protesto etmişti sevdanın her türlüsünü,

Tuttum ellerini dostça,baktım çokça üşümüş.

Derlerdi,sevda her türlü kapıyı açarmış,

Yakaladığını, doğduğuna bin pişman edermiş.

Tam tersine kapattı birer,birer kapılarımı,

Durdurdu hafsalımı,kıblemi şaşırtmış.

Şimdi sağımı solumu bilmeyenlerden oldum.

Taşımaktan yorulduğum, sevda heybelerine sevgi doldurdum.

Dolaşıyorum şimdi çaresizce, rastgele, köşe bucak,

Koklanmaya kıyılmayan bir gül iken, boşu boşuna soldum.

İçi boş sevdalara vardır husumet ve kinim,

Dinler içinde en mükemmelidir bana göre benim dinim.

Yaptıklarımın karşılığını bu dünyada görmesem bile,

Kazanır bu sevdalı yüreğim, ahirette yerim olur belki cennetim.

Aldım sevda küreğini elime,çok harçlar kardım.

Bir gün görmediğimde,ondan bundan sorardım.

Bu yaptıklarından sonra yıklıdı sevgi abidelerim,

Bilseydim sevda hilelerini,saf ve temiz sevgimle bozardım.

29/01/2006', 'Sevdanın kör bir yağlı kurşunu, Vurdu beni ciğerimin tam ortasından. Başıma bir türlü konmayan talih kuşunu, Uçurdular sevda yolunun ta en b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevda-kuregiyle-cok-harclar-kardim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatı zehir etme bana', 'hayati-zehir-etme-bana-i-lhan-koruyucu-8y5sn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatı zehir etme bana

Eğer bir parça tuzu seversen

Onun yanında ekmeği yada acıyı

Garibin yüreğine vurup vurup

Hayata küstürme beni

Sana öyle tatlı şeyler diyemediysem

Uykularım bölünüp, kötü söylemediysem

İçkiyi sevmediğim halde sarhoş olup

Düştüysem ayaklarına hayatı zehir etme bana

Biz seninle eğer bir bütün isek

Heves değil, arzu değil, dilek değilsek

Günleri saydırıp, yarı yolda ekip

Hayatı zehir edip, küstürme beni

Başımın tatlı belki de acı belası

Asla vazgeçmem ayrılmam senden

Eğer benden koparsan kahretmem

Hayatı zehir etme bana

İlhan KORUYUCU', 'Hayatı zehir etme bana Eğer bir parça tuzu seversen Onun yanında ekmeği yada acıyı Garibin yüreğine vurup vurup Hayata küstürme beni Sana öy...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayati-zehir-etme-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Eskiden', 'cok-eskiden-efsun-aydin-jc240', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir de yoksun ya hani…

Ben zaten bu yuzden tukeniyorum.', 'Bir de yoksun ya hani… Ben zaten bu yuzden tukeniyorum....', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/cok-eskiden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Artık Mutluluk Bana', 'yok-artik-mutluluk-bana-kamil-soylemez-jylcu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yok artık, mutluluk yok bana

Sevdam söyledi,haydi git durma

Gece kadar kara..

Gece kadar soğuktu o an

Karlı bir sevdam kararıyla

Ne mevsimde tanıdıysam

İşte o mevsimde kapı gösteriyordu bana

Yol güzergahımızda sarkıt buzlar

Çatılardan içime düşüyordu adeta

O mutlumu ki şimdi

Gerçekte mutluluğun tanımı 

Ayrılıkmı olmalıydı....

Yada başka sevdalardamı aramalıydı

Mutluluk bu kadar saf,ve temiz iken

Benim ne günahım vardı

Zamansız kan damladı

Kor yağdı

Şimdi gidiyorum istanbuldan

Avuçlarımda aradığım eller

İçimdeki melekler yok bana

Güvercinler yokMektup yok bana

Dertler,kederler çok

Hayat yok 

Sevdam.....

Kara gözlü sevdam

Bitsin artık istiyorum

Dursun bundan sonraki zaman

İçimdeki çocuk ölsün

Sevgi öldüyse yaşayamam

Asla yaşayamam.............', 'Yok artık, mutluluk yok bana Sevdam söyledi,haydi git durma Gece kadar kara.. Gece kadar soğuktu o an Karlı bir sevdam kararıyla Ne mevsimde...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yok-artik-mutluluk-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah..Birde konuşabilsek.', 'ah-birde-konusabilsek-tulay-i-cen-1oezq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nedendir çekememezlik,

Nedendir   bananecilik,

Konuşmayı unuttuk dostlar.

Konuşmayı.

Sevgi dedik.

Dürüstlük dedik.

Tek taraflı  yorum,

Tek taraflı düşünce..

Ah...birde konuşa bilsek.

Sanki savaştayız.

Yargısız infaz yapmayı  seviyoruz.

Konuşmayı  sevmiyoruz dostlar.

Konuşmayı...

Hep gündemde olmak marifetmi

Reklam  yıldızı gibi.

Yorumlara kapalı,

Sözlere kapalı.

Tek taraflı yorum olmaz.

Dinlemeyi bilmiyoruz dostlar.

Dinlemeyi..

Kardeşlik,birlik beraberlik dedik.

Arkadan  vurmak bumu dostlar.

İnsanı sevmeyen,

Sevgiden,

Duygudan,

Aşktan,

Sevmekten,

Ne anlar? 

Konuşmayı unuttuk dostlar.

Konuşmayı..

30/01/2006', 'Nedendir çekememezlik, Nedendir   bananecilik, Konuşmayı unuttuk dostlar. Konuşmayı. Sevgi dedik. Dürüstlük dedik. Tek taraflı  yorum, Tek t...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ah-birde-konusabilsek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarlarla Konuşurum', 'ruzgarlarla-konusurum-yusuf-onder-bahceci-l1qim', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben dağlarda gezeceğim,

Seni sevdim seveceğim,

Seven kalbini sezeceğim,

Rüzgârlarla konuşarak.

Seni gördüm diyemedim,

Seni sevdim diyemedim,

Sen benimsin diyemedim,

Rüzgârlarla konuşurum....', 'Ben dağlarda gezeceğim, Seni sevdim seveceğim, Seven kalbini sezeceğim, Rüzgârlarla konuşarak. Seni gördüm diyemedim, Seni sevdim diyemedim,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruzgarlarla-konusurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sibelce', 'sibelce-mehmet-sait-akkus-qrnqu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen kanatlı bir melek

Sen hasretten bir gömlek

Seni doyasıya görmek

Seni yüreklere işlemk

lazım sibelce

Cana can veren

Dostluğa gönül veren

Yeri gelince baş veren

Avuçlarıyla yüreğini veren

Bir meleksin sibelce

Ağır ve vakur yürüyüşün

Yürekleri ısıtan gülüşün

Usulcacık hayatı öpüşün

O bülbül gibi ötüşün

Çınlıyor bak sibelce

Seni görmek tanımak lazım

seni alıp gönüllere sarmak lazım

Seni herkesten çok sevmek lazım

İnan ki sibelce

Senin için dünyayı yakmak lazım', 'Sen kanatlı bir melek Sen hasretten bir gömlek Seni doyasıya görmek Seni yüreklere işlemk lazım sibelce Cana can veren Dostluğa gönül veren ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sibelce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınırlar Üstü', 'sinirlar-ustu-evin-okcuoglu-dp3zn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sınırlar Üstü

Düşman yoğun bir sisti

Çöktü üstüme

Kıtalar aşırıydı

Ülkeler üstü

Uluslar üstüydü

Çöktü geleceğime

Ellerim yorgundu

Onu asırlardır taşımaktan.

Daha henüz doğurgandım 

Bereketime çöktüğü zaman

Ama yoktu kızoğlankız paylaşımın tadı

Birbirimize bulaştırdık

O masum, süt kokan kanlarımızı.

Çılgın zevklere 

Deneysel saldırılara kurban

baş rolde çıktık savaş oyunlarında

Yerin yüzüne çizdiği

Yeşil- kırmızı  çizgiler uğruna

Ölüme boyandık.

İşte böyle sağıldı 

Pörsüdü meme

Yangından kaçırdığı 

Viran atölye.

Üç kuruştu insan emeği

Beden dediğin ne ki

Delik deşik girdik akşamları

Sokaklarımıza ev diye.

Tapındık ulus aşırı

Irk aşırı

Din aşırı 

Şeylere

Marka olduk, 

Mal olduk biz de

Bakındık yaban yaban.

Neredesin, kimsin? 

Tanımadık hemşehrimizi

Yollarda kaldık günlerce

Sağ mıydık ölü mü

Yoksa tutarak mı tuttu bizi de

Nasıl saçıldı da

Koptu irinli lokmalar

Takıldık düştük peşine

Masallarda gezindiğimizde

İflah olmaz haldeydik

Korkunçtu gölgemiz

Aslımız kara delik

Biz hâlâ neslimizin peşinde...

İlk ışığında bile yoktuk sabahın

Ne doğrulttu bizi

Neydi o can havli

Ne mahşerdi

O ‘Hayır’ın savrulduğu an

Derin uğultularla

Çözülmüş halde

Kaldırdık elimizi

Kavga tuttu 

Ekmek tutmayan elimiz

Aşkla tutuştuk

Güller döküldü önümüze 

Kanadık 

kanadık 

kanadık

Temiz kan gelene

Sis gidene

Uğultu dinene dek

Kanadık zamanlarca

Dirildik 

heybetle

Ürettiğimiz, kendimizdik

Üfledik hayatı yeryüzüne...', 'Sınırlar Üstü Düşman yoğun bir sisti Çöktü üstüme Kıtalar aşırıydı Ülkeler üstü Uluslar üstüydü Çöktü geleceğime Ellerim yorgundu Onu asırla...', ARRAY['Türk Edebiyatı','Şiir','Evin Okçuoğlu']::text[], 8.5, '{"poet":"Evin Okçuoğlu","poet_slug":"evin-okcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/sinirlar-ustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir Seninle Güzeldi', 'i-zmir-seninle-guzeldi-durmus-kaya-eiiy4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kordonboyu…

Dillere destan olmuş aşkların sahili,

İşte ben geldim! 

Aydan gülü

Gülden ayı dermeye

Yüreğime sermeye! 

Gönlüm bir yaralı kuş

Martılar arasında! 

İzmir,

Güzel mi güzel

Güneş

Sıcak mı sıcak

Deniz 

Mavi mi mavi

Derin mi derin

Ya o gözlerin? ! 

…..

Lozan kapısı…

“Orda bekle! ..”

Lozan kapısı can kapısı oluveriyor bir an! 

Ayın onbeşi bir ses

Gül kırmızısı sıcak! 

Uçuyorum,

Kanatlarım sen! 

…..

Karşıyaka iskelesinde  ebemkuşağı

Ve sen eleğimsağma! ...

Tutuştum baştan aşağı! ...

Çalkanıp duruyorum

Dumansız ateşler kavuruyor tenimi

Ömrümce duymadığım bir ses

Tatmadığım bir sevgi

Çerağ çerağ sarıyor evrenimi! ..

Karşıyaka iskelesi şimdi

Her yanı gül döşeli 

İri bir sevda başağı

Cam kırığı bakışlı sokaklardan önce! ...

Karanfilleri kucaklamış biri

Tedirgin elleri! ...

Gözleri ürkek  ela/yimsema..

Hilal kaşları hüzün ölçeği bir gizemli kuş; 

Zümrüd-ü Anka! ...

…..

İzmir’in ortasında bir bozkır uşağı

Yüzünde kaynar sular

Omzunda Kafdağı,

Canı dudağında! ...

Gözlerinin yeşili bir sevda uçmağında,

“İzmir daha bir güzel! ” diyor içinden,

İzmir seninle güzel! ..

Sonra o vapur

Mutedil sularda onsekizbin alem! 

Hiç zorlanmayan dilimde, 

Korlar koru bir gem! 

“Gel! ” diyor gizemli kuş 

İnceden ince,

Sıcaktan sıcak! 

Her yanı meneviş

Menekşe,

Salkımsaçak! 

Tutarım diye ellerini korkarak 

Ellerimi cebimde tutuyorum! 

Ben İzmir’i görmüyorum,

İzmir de beni! ...

…..

Kemeraltı’nda ışıltılı vitrinler

Gümüşler, pırlantalar,

Sana bu çarşıyı almak geliyor içimden! 

Ama benim bütün dağlarım dumanlı

Başımda efkar! 

Kızlarağası Han’ı

Bir yanardağın ağzıdır şimdi

Ve.. sevda volkanı! 

Gözlerim fincanda pişmiş kahvede değil

Kafdağı’nın tepesinde parlayan

Çoban yıldızında! 

Yüreğim İzmir’in

Bu güzel kızında! 

Divanlarda yastıklar

Yastıklarda desenler

Dedemin Türkmen çadırına götürüyor beni! ...

Doldukça doluyorum! 

…..

Bana neler oluyor, diye düşündün belki

Belki bende çakan kıvılcımlar sende yoktu! 

Belki gözlerin bunun için ürkek! 

Belki Karşıyaka, 

Kemeraltı, 

Kızlarağası Han’ı

Yanında ben olduğum için 

sana dar geldi! 

Belki yüreğinde hiç olmadı yerim! 

Belki zoraki ağırladın beni! 

Benim içimde bir ukde/zakkum/zehir

Belki sana ar geldi! 

Kaçınılmaz kaderim,

O nazlı İzmir,

İçinde sen olduğun kadar güzeldi!', 'Kordonboyu… Dillere destan olmuş aşkların sahili, İşte ben geldim!  Aydan gülü Gülden ayı dermeye Yüreğime sermeye!  Gönlüm bir yaralı kuş M...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Kaya']::text[], 8.5, '{"poet":"Durmuş Kaya","poet_slug":"durmus-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":98,"source_url":"https://www.antoloji.com/izmir-seninle-guzeldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geride Bıraktıklarım', 'geride-biraktiklarim-aysun-bekci-k5buj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çocuk olmadım hiç bir zaman 

ben bilmem evcilik oynamayı 

annenin elinden tutup dolaşmayı

babnın sıcaklığını ben bilmem

ama hayat benimle çok güzxel oynadı

hele geride bıraktıklarım

şimdi ben oynuyorum ipler benim elimde

ama eskisi gibi sağlam değil

çürümeye yüz tutmuş... 

ah o geride bıraktıklarım şimdi nerdesiniz? ? ? 

yok aslında sizde bir hiçtiniz', 'çocuk olmadım hiç bir zaman  ben bilmem evcilik oynamayı  annenin elinden tutup dolaşmayı babnın sıcaklığını ben bilmem ama hayat benimle ço...', ARRAY['Türk Edebiyatı','Şiir','Aysun Bekçi']::text[], 8.5, '{"poet":"Aysun Bekçi","poet_slug":"aysun-bekci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/geride-biraktiklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu', 'anadolu-i-lhan-koruyucu-yvqj5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anadolu

Benim canım yurdum

Her bir yanı ayrı dantel

Dağların, ovaların

Hepsi Anadolu

Yazın başka

Baharın

Kışında

Dört mevsimi yaşatırsın

Tarih kokar her bir yanın

Atalarımızdan yadigar

Kekik kokan dağların

Engin vadilerin

Üç yanı denizle çevreli

Harika kalyonların

Elleri naşırlı anaların

Nakış nakış işlenmiş

Gelinlik kızlar gibi

Süzülen bakışların

Tarihi kültürün var

Benim eşşiz yurdum

Anadolu.

İlhan KORUYUCU', 'Anadolu Benim canım yurdum Her bir yanı ayrı dantel Dağların, ovaların Hepsi Anadolu Yazın başka Baharın Kışında Dört mevsimi yaşatırsın Tar...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/anadolu-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünle', 'huzunle-dilek-kalindemir-fc4va', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüznü yaşamaksa mutluluk dediğin,

hüzün parçası olur varlığının

Nedeni olur daima

Gülmelerin, ağlamaların...

Denize yakın yaşıyorsan

deniz hüznün olur,

hüzün mavi olur...

Yoksa denizin,

göğe yakınsan en çok,

gökyüzün hüzün olur,

hüznün yine mavi olur...

Sen hep mavisin hüzünlerde

hüzünlerle...

Yaşam maviyi verir sana,

seni maviye bular

gülmelerle, ağlamalarla...

(30 Ocak 2006)', 'Hüznü yaşamaksa mutluluk dediğin, hüzün parçası olur varlığının Nedeni olur daima Gülmelerin, ağlamaların... Denize yakın yaşıyorsan deniz h...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kalındemir']::text[], 8.5, '{"poet":"Dilek Kalındemir","poet_slug":"dilek-kalindemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/huzunle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar Islanmasın', 'yildizlar-islanmasin-durmus-kaya-sn8so', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '•	YILDIZLAR ISLANMASIN

Gönül kanatlarımı

Senin ufuklarına kaldırıyorum

Gökyüzünden kurşun yüklü sevdalar

Gözlerinden hüzün dolduruyorum

Dilinden kar! 

A yar,

Yollarında tipi var

Şahlanmıyor atlarım! 

Gönül kanatlarımı açıyorum sana

Varsın eşkin atlar

Nallarını sürüsün! 

Varsın yüce dağları

Kara duman bürüsün! 

Varsın gök mavi

Deniz yeşil

Güneş süzgün olmasın! 

Gönül kanatlarımı açıyorum sana

Gurbetin sırlı bir gecesinde

Bir yorgun turnanın yanık sesiyle

Bir topal karınca iniltisiyle

Kaçıyorum sana! 

A yar

Islık çalsam üstüme

Yıldızlar yağar,

Türkü söylesem, 

Dağlar! 

Yine efkar, yine efkar, efkar! 

Neyleyim ki deli gönül yanmasın

Yarimin gözlerinde

Yıldızlar ıslanmasın!', '•	YILDIZLAR ISLANMASIN Gönül kanatlarımı Senin ufuklarına kaldırıyorum Gökyüzünden kurşun yüklü sevdalar Gözlerinden hüzün dolduruyorum Dili...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Kaya']::text[], 8.5, '{"poet":"Durmuş Kaya","poet_slug":"durmus-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yildizlar-islanmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzüne Bak (137)', 'gokyuzune-bak-137-i-brahim-arslan-l21ea', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi benim için gökyüzüne bak,

Seni sevdiğimi yazdım oraya,

Artık bu inadı,gururu bırak

Benim için gel uzaklardan yarim...

Yokluğuna alışmak kolay mı ha,

Sen gittin bahar gelmedi buraya,

Gelmek için ne bekliyorsun daha,

Soğukluk mu girdi araya yarim..

Ne zaman istesen ölürüm oysa,

Sen yoksan,beni yaşıyor mu sandın

''Ayrılalım''eğer son sözün buysa,

Ben zaten hep senden ayrıyım yarim...

Sözlerinde Cehennem''e davet var

Kara gözlerin bak üzüyor beni,

Bil ki bende davete icabet var,

Birde yanayım senin için yarim...

Sensizlik sigarasızlık mı sandın,

Sensizlik var ya ölümün kendisi,

Sen sensizlik öyle kolay mı sandın...

Ben onu sana anlatamam yarim...

Yarim,benim gibi sevmez misin sen

Her şeyden vazgeçmez misin ben gibi,

Bileyim şeytan mı melek misin sen

Gerçek olup,gelmez misin sen,yarim...

Sen yoksan kapanmayacak bu yara,

Sen yoksan güneş doğmayacak sabah,

Sen yoksan kıyamete bir saar var,

Sen yoksan yok hiçbirşey bana yarim...

Ben görmüyorum senden başkasını,

Başkaları çekmesin benim gibi,

Çektirdiğin gibi aşk acısını

Sende yanmalısın benim gibi yarim...

Şimdi benim için gökyüzüne bak

Seni sevdiğime inanmalısın..

Sonra senden ayrıldığım yere bak

Seni sevdiğime utanmalısın...

   01.08.2004', 'Şimdi benim için gökyüzüne bak, Seni sevdiğimi yazdım oraya, Artık bu inadı,gururu bırak Benim için gel uzaklardan yarim... Yokluğuna alışma...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gokyuzune-bak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Kokulu Sesin Gelse', 'gul-kokulu-sesin-gelse-durmus-kaya-n6vvd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sende beni ateşleyen bir şey var,

Görmesem yanarım görsem yanarım! 

Yanağında alevlenen gülleri

Dermesem yanarım dersem yanarım! 

Kanar durur bende açtığın yara

Sardığım her ilaç dönüşür har''a

Atıma atlayıp karlı dağlara

Sürmesem yanarım sürsem yanarım! 

      

Şu garip gönlümün gizemli kuşu

İner enginleri çıkar yokuşu! 

Gözlerin gözümde kavuşmak düşü

Kurmasam yanarım kursam yanarım! 

     

Gönül kumaşıma elin değeli

Savrulur içimde sevdanın yeli

Her gece geçerim nice bin çölü

Durmasam yanarım dursam yanarım! 

Gül kokulu sesin gelse sıladan

Selamlar getirse yardan baladan

Şu gurbeti, o gözleri eladan

Sormasam yanarım sorsam yanarım! 

Yarımların mayasında bütün var

Benim, hala nefesimde tütün var! 

Vuslatına kanatlanmış bir gün var

Ermesem yanarım ersem yanarım! 

Gezerken kanımda sen ılık ılık

Ben melal içinde perişan, yıkık

Bu canımı bakışına karşılık

Vermesem yanarım versem yanarım!', 'Sende beni ateşleyen bir şey var, Görmesem yanarım görsem yanarım!  Yanağında alevlenen gülleri Dermesem yanarım dersem yanarım!  Kanar duru...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Kaya']::text[], 8.5, '{"poet":"Durmuş Kaya","poet_slug":"durmus-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gul-kokulu-sesin-gelse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Kokuyorsun', 'hasret-kokuyorsun-gul-yazganarikan-4a3gh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasret kokuyorsun, 

Gözlerin hasret fısıldıyor...

Ellerin sabırsız, ellerin telaş içinde,

Söyle hadi, hasretim seni ne tutuyor...

“Kadınım” diyorsun bir yandan,

Öbür yandan kaçıyor,

Bir elin okşarken saçımı,

Diğer elin çekiyor...

Sevişler bittiği yerde senle tekrar başlıyor....

Kelepçe olmuş tutkular, 

Korkuları bağlıyor...

Bıraktım ben kendimi,

Bana dair ne varsa, seninle azalıyor...

Sen çoğalmaktasın...

Bir hükümsün boynumda,

Umut senin koynunda,

Benden bir iz arıyor...', 'Hasret kokuyorsun,  Gözlerin hasret fısıldıyor... Ellerin sabırsız, ellerin telaş içinde, Söyle hadi, hasretim seni ne tutuyor... “Kadınım” ...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hasret-kokuyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-aysun-bekci-anq93', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bırakıp gitmek yılları bir kalemde silmek bu kadar kolay mıydı

adamım

yürğim üşüyor artık çok yalnızım....

hani türkümüz vardı seninle ''kime kin ettinde giydin alları''

dinliyorum şimdi de acaba o sen misin diye çok soruyorum ama değil işte değil işte

yazmış olmak için yazdım tıpkı kaderim gibi

senden sonra hiç güzel şey yazmadım adamım...

ve şu anda çok yalnızım özlüyorum hala ilk günkü gibi

sevmeden seviyormuş gibi yapmak çok zormuş adamım

belkide o yüzden yalnızım........', 'bırakıp gitmek yılları bir kalemde silmek bu kadar kolay mıydı adamım yürğim üşüyor artık çok yalnızım.... hani türkümüz vardı seninle ''kime...', ARRAY['Türk Edebiyatı','Şiir','Aysun Bekçi']::text[], 8.5, '{"poet":"Aysun Bekçi","poet_slug":"aysun-bekci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalnizim-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tohum...', 'tohum-ercan-akbay-u56gq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ektim yüreğime sevi tohumlarını

    Usum buram buram iyilik kokar

    Sula ey gözyaşlarım sula

    Şiirin topraklarını harmanla

    Elbet senin de bahçende

    Renkli renkli çiçekler açar

    Bakarsın mutluluğu gagasında getirir

    Uzaklardan bilinmeyen kuşlar....

                                19.7.1978  KELEBEK GAZETESİ

                                Ümit Yaşar Oğuzcan ın seçtiği şiirler.', 'Ektim yüreğime sevi tohumlarını     Usum buram buram iyilik kokar     Sula ey gözyaşlarım sula     Şiirin topraklarını harmanla     Elbet se...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tohum-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış Şiiri', 'kis-siiri-asya-yildiz-bjdgb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yansımaz, alabildiğine gider sesimin çağrısı,

Sesimin çarpacağı ne bir beden ne bir duvar..

Çizmiş kaderini, ok gibi fırlayıp dudaklarımdan; 

Kırmızı dudaklarım sonsuz bir boşluğa bakar.

Önce yağdı, üşüyen ve titreyen yokluğunun üzerine,

Tanrının katından savrulup uçuşarak geldiler.

Kutsandım bir beyaz nurla, fırçasının ucunda

Kah çizilip kah bulandım ak ve duru güzelliğe.

Dünya döndükçe savrulsun yüreğim, bana kalmasın,

Ne kimsesiz sözler, ne de gözüm yaşı kalmasın.

Gelen kış, teslim ol ruhum, yazı dilenme gayrı,

Baştan aşağı bembeyaz, kapındaki yas benim, açmayasın.', 'Yansımaz, alabildiğine gider sesimin çağrısı, Sesimin çarpacağı ne bir beden ne bir duvar.. Çizmiş kaderini, ok gibi fırlayıp dudaklarımdan;...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kis-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Kanat', 'kirik-kanat-i-lhan-koruyucu-vrnze', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kırık Kanat

Deniz kenarında

Sahilde koşarken

Kırık kanatlı bir kuş

Atmış kendini

Çırpınarak sekeliyor

Uçmak istiyor belkide

Kendini zorlamak boşsa da

Önce düşündüm

Zavallı dedim kendi kendime

Acımak çözüm olmaz ki

Aldım avuçlarımın içine

Sanki kalbi avuçlarıma atıyordu

Korkak, ürkek ve çaresiz

Evime getirdim 

Kanadını sardım

Yarasını iyileştirmeye çabaladım

Bir kaç gün sonra

Kendine geldi Martı

Hadi uç dedim

Saldım Özgürlüğüne

Öyle koştu ki gökyüzüne

Selamlayarak beni

Bu gökyüzü benim diyordu.

İlhan KORUYUCU', 'Kırık Kanat Deniz kenarında Sahilde koşarken Kırık kanatlı bir kuş Atmış kendini Çırpınarak sekeliyor Uçmak istiyor belkide Kendini zorlamak...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kirik-kanat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Beni Sevseydin', 'sende-beni-sevseydin-yusuf-onder-bahceci-0afyl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni öyle sevmişim ki,

Şu kalbimi kim bilir ki,

Gece gündüz olur belki,

Sende beni sevseydin.

Sen ellerde kim bilecek,

Seven kalbi kim bilecek,

Gözyaşlarım kim silecek,

Sende beni sevmezsen.', 'Seni öyle sevmişim ki, Şu kalbimi kim bilir ki, Gece gündüz olur belki, Sende beni sevseydin. Sen ellerde kim bilecek, Seven kalbi kim bilec...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sende-beni-sevseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonu Yok (138)', 'sonu-yok-138-i-brahim-arslan-4fc7i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sonu yok

öleceğim diye beklerken

anlıyorsun ki

ölmenin sonu yok...

hayatla ciddi olmanın anlamı yok

dalga geçmeninde,insansan

hayvan gibi yaşamayı seçmeninde

manası yok..

anlıyorsun ki bazen

en anlamlı ne varsa

onun da anlamı yok...

sonu yok

bu yolların

bu gurbetin,bu çilenin

bu hasretin sonu yok

bitse herşey

ölsen tabiri caizse

ondan sonra da

sorgu-sual ve cehennemdeysen

yanmanın sonu yok

yine yol ayrımındasın

ve her yolunda sonu yok...

sonu yok

sonsuzlukta boğulmanın,varolmanın-yokolmanın...', 'sonu yok öleceğim diye beklerken anlıyorsun ki ölmenin sonu yok... hayatla ciddi olmanın anlamı yok dalga geçmeninde,insansan hayvan gibi ya...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sonu-yok-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol mu? yolcu mu?', 'yol-mu-yolcu-mu-nazan-i-zmirli-229yz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yol mu olmak

yolcu mu

özlem  dolu bir kalbi

kavuşturmak  mı

yoksa

kavuşan olmak  mı

farkeder mi? 

yol un  sonuda

yolcu nun  sonuda

aynı  nokta

giden  dönmek  zorunda

oysa  yol  kalacak  orada

karar vermek! 

zor............yol........

bir ışık 

süzmesi isen........

zor  yolculukda......

yol  olmak da  zor

yolcu  olmak da.

27.01.2006-antalya', 'yol mu olmak yolcu mu özlem  dolu bir kalbi kavuşturmak  mı yoksa kavuşan olmak  mı farkeder mi?  yol un  sonuda yolcu nun  sonuda aynı  nok...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yol-mu-yolcu-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umut', 'bir-umut-selcen-boyar-5zoop', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneşin doğmadığı

Karanlığın olmadığı 

bir yerde

Bir umut....

Ateşin yanmadığı

Yağmurun ıslanmadığı 

bir demde

Bir umut....

Suların akmadığı

Gözlerin bakmadığı

bir ferde

BİR UMUT

BİN UMUT', 'Güneşin doğmadığı Karanlığın olmadığı  bir yerde Bir umut.... Ateşin yanmadığı Yağmurun ıslanmadığı  bir demde Bir umut.... Suların akmadığı...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-umut-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunun Yangını', 'yoklugunun-yangini-selcen-boyar-vd9w3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yokluğunun yangınını

Ciğerlerimde hissediyorum

Geceler bir kabus

Uyuyamıyorum

Her gece gözlerimde seni büyütüyor

Sonra neden

Yokluğunla sızıyorum

Bugün bu şehirde

yoksun biliyorum

Dudaklarım hep yalandan gülüyor

Oysa her saniyede bin defa ölüyorum,

Hasretin kor bir ateş beni yakıyor', 'Yokluğunun yangınını Ciğerlerimde hissediyorum Geceler bir kabus Uyuyamıyorum Her gece gözlerimde seni büyütüyor Sonra neden Yokluğunla sızı...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yoklugunun-yangini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin Ağlıyorum Ağlayacağım', 'senin-i-cin-agliyorum-aglayacagim-yusuf-onder-bahceci-ozxwi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim sevdiğimdin sen eller içinde,

Ben seni çok severdim güller içinde,

Sevgin kalbimdedir, sevgin içimde,

Senin için ağlıyorum, ağlayacağım.

Seni çok severdim yollara bakan,

Yollara bakar da hep yollara çıkan,

Yıllarca beklemekten bıkıp usanan,

Senin için ağlıyorum, ağlayacağım.

Sevmeyenler bilemez nazı, niyazı,

Sevmeyenler bilmez söz ile sazı,

Sevdan beni yakıyor bitmez alazı,

Senin için ağlıyorum, ağlayacağım.', 'Benim sevdiğimdin sen eller içinde, Ben seni çok severdim güller içinde, Sevgin kalbimdedir, sevgin içimde, Senin için ağlıyorum, ağlayacağı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senin-icin-agliyorum-aglayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine bir yazı', 'oylesine-bir-yazi-bir-mim-kemal-ertugrul-vp9jd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Epeydir yoktum,epey de olmayacağım buralarda...

Dokuz onda dokuz şiddetinde bir deprem geçirmiş olduğunu söylüyor doktorlar yüreğimin...Ve artçılara karşı,kış soğuklarına ve düş üşümelerine karşı yüreğimi kavi tutmamı  öğütlüyor aynı doktorlar...

Bu kısa açıklamanın ardından,en başta Uludağ Üniversitesi Tıp Fakültesi Kardiyoloji Ana Bilim Dalı mensupları olmak üzere,rahatsızlığım sırasında ben ve yakınlarımı arayan,soran,düşünen,düşünmeyen,seven sevmeyen herkese hepinizin huzurunda kalbi teşekkür etmek istedim ve güzel sağlıklı günler dilemek hepinize....

Selam ve sevgilerimimle', 'Epeydir yoktum,epey de olmayacağım buralarda... Dokuz onda dokuz şiddetinde bir deprem geçirmiş olduğunu söylüyor doktorlar yüreğimin...Ve a...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/oylesine-bir-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maya Meselesi', 'maya-meselesi-abdurrahim-karakoc-0vlar', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Medya her gün cilalar yontulmamış odunu 

Soyar, resmini basar ve pazarlar kadını 

Kanundan kaçmak için hırsız, hortumcu, haydut 

Kendine siper yapar Atatürk’ün adını.

28 Ocak 2006/Vakit', 'Medya her gün cilalar yontulmamış odunu  Soyar, resmini basar ve pazarlar kadını  Kanundan kaçmak için hırsız, hortumcu, haydut  Kendine sip...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/maya-meselesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Böyle Birşeydir Ayrılık', 'i-ste-boyle-birseydir-ayrilik-dilek-hokkaomeroglu-kwsb9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'AYRILIK



 

Hani bir yürek sessizce ağlar ya! 

Kayar bir ömür avuçlarından...

Gelmez vuslatlara yanarsın.. 

Bir yanardağ olur yüreğiniz

Yakar etrafını..

Ne var ne yok sevgiye dair...

Alıp götürür...

Kalır yürek ağıtlarda... 

Ömrünüzden ömürler gider..

Ağlamak istersiniz ağlayamazsınız

Boğum boğum olur 

Hasret boğazınızda...

Kapatır kirpikler gözleri anılara..

Gözleriniz çakmak çakmak

Yüreğiniz yangınlarda...

Hayaller hayaller...

İçinizin acıdığını 

Yüreğinizin ağladığını

Duyarsınız derinlerden... 

Tutmak istersiniz bir şarkının dilinden

''''Ömrümüzün Baharı Birlikte geçsin''''

O zaman yalnızlık karışır

Yürek hicran...

İşte böyle bir şeydir ayrılık...

 Temmuz, ağustos, eylül dağıldı kaldı ömür.', 'AYRILIK   Hani bir yürek sessizce ağlar ya!  Kayar bir ömür avuçlarından... Gelmez vuslatlara yanarsın..  Bir yanardağ olur yüreğiniz Yakar ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/iste-boyle-birseydir-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün Olur Ölür Giderim', 'birgun-olur-olur-giderim-yusuf-onder-bahceci-bkue9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben seni severdim sevdiğim diye,

Söylesene bu gidişin sebebi niye,

İnan her gece adını ben diye diye,

Bir gün olur ölür, ölür giderim.

Beni sevdiğin halde ele gidersin,

Seni seven kalbimi neden üzersin,

Hata yapmadımki neden küsersin,

Bir gün olur ölürüm, ölür giderim.', 'Ben seni severdim sevdiğim diye, Söylesene bu gidişin sebebi niye, İnan her gece adını ben diye diye, Bir gün olur ölür, ölür giderim. Beni ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/birgun-olur-olur-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeşlik', 'kardeslik-zuhal-aksulu-mqa5d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben daha üç yaşımda yoktum sen o güzel gözlerini dünyaya açtığında... minik sarı bir şeydin. O minik, yalnız dünyama bir renk katmıştın, öyle sevmiştim, öyle benimsemiştim seni.... hoş gelmiştin. 

Ben ana sınıfına gidiyordum. Mevsim yine şimdiki gibi kıştı. Kar vardı... Ayağına 30 numara büyük gelen terlikleri giyip yola çıktığında o küçük çıplak ayakların soğuğu hissetmiyordu sanki. Ben her şeyden habersiz sınıfta oyuna dalmıştım.. kapı aralandı birden. Tombik sarı suratın üzerine dikilmiş kırmızı bir düğme gibi küçücük burnun ve sen kapıda dikilmiş bana bakıyordun. Daha 3 yaşında yolu nasıl öğrenmiş, nasıl sabahın köründe kalkıp yanıma gelmiştin. Öyle utanmıştım ki seni kapıda çiçekli pijaman ve kocaman terliklerinle gördüğümde... 

O yaşından belliydi ne kadar cesur olduğun. İstediğin uğruna soğuğa, işiteceğin azarlara aldırmadan yola çıkıyordun. Ben hiçbir zaman bu kadar cesur olamadım. Hiçbir zaman istediklerimin peşinden senin gibi hırslı gidemedim. 17 yıl önce o soğuk kış mevsiminde ben utanmıştım, üzülmüştüm... sen yanıma geldin diye. Biliyorum şimdi sen üzüleceksin, utanacaksın. Ben gelemdim diye. Dedim ya.. hiçbir zaman senin kadar cesur olamadım. Ve şimdi bile çok istediğim bir şeyi yapmaktan beni alıkoyan bir şeyler var. Gelmek istiyorum... gelemiyorum.

İnsanın en mutlu günüdür... ve sevdikleri, sevenleri mutlu günlerinde yalnız bırakmazlar. Sen beyazlar içinde ortalıkta salınırken seninle mutlu olur, seninle ağlarlar. İnsan hayatının en özel günüdür bu. Bir yuvadan ayrılıp başka bir yuva kuruyorsundur. Yıllarca seni gözlerinden bile sakınan, senin hastalığında başında sabahlayıp, sen ağlayınca içi sızlayan insanların yanından ayrılıp; artık güçlü olman gereken kendi dünyanın kapılarından giriyorsundur. Sevdiğinin yanına... sevdiklerinle beraber. Sen de artık o adımı atıyorsun. O kapıdan girmene çok az kaldı. Ama ben olamayacağım yanında. Seni beyazların içinde salınırken göremeyeceğim ve biliyorum ki bunun pişmanlığını bir ömür boyu çekeceğim. Hep hayalini kurduğum bir şeydi bu. Sen beyazlar içinde, ben yine her zamanki gibi siyah tuvaletimle etrafında mutlulukla koşturmak. Seninle göbek atıp görenleri çatlatmak. Ama olmayacak işte... olamayacak. 

“çok istiyorum gelmeni” demiştin bana. Ben de çok istiyordum. Ama lanet olası bu dünyada cesurca attığın adımlardan biri bu kez işe yaramadı. Seni benim yanıma getirmek yerine benden aldı. Sen benim canımdan bir parçasın, bensin, benimsin... ama seni bana verenler bu sefer ayırıyorlar... belki bedenlerimiz ayrı.. ama onların tek bilmediği ruhlarımızı ayıramayacakları. Her zaman kalbim ve ruhumla yanında olduğumu bilmeni ve desteğimi hissetmeni isterim. Hayat uzun ve zorlu bir yol ve bu yolda karşına çıkabilecek her türlü problemde uzaklarda da olsa bir ablan olduğunu unutma. Her ihtiyaç duyduğunda, yanına gelemesem de, elimden geleni yapacağımı bil....

iki küçük yaramaz çocuk olup kanepelerin tepesinde zıpladığımız, beraber şarkı söyleyip dans ettiğimiz, hatta saç saça baş başa kavga ettiğimiz günlere geri dönebilmeyi çok isterdim. O günlere dönmeyi ve kendimizi güvende mutlu hissettiğimiz o günlerde kalmayı... fakat insan milyarlar harcasa bir saniyeyi geri getiremiyor. insandan çok şeyi alıp götüren bu zaman paradigmasının iğrenç oyunlarından biri bu. Ama götürdükleri olduğu kadar getirdikleri de olacaktır eminim. İnşallah hayat ve zaman sana her zaman güzel ve mutlu şeyler getirir. 

Çok küçük, önemsiz, çam sakızı çoban armağanı belki... bu mutlu gününde yanında olup da koluna takamadığım bileziğin yerine geçemez biliyorum ama... hesabına bir miktar para yatırıyorum. Düğün armağanı. Maddi değeri önemli değil. Sadece her zaman yanında olduğumu bil diye. 

Sana ve Kürşat’a bir ömür boyu mutluluklar dilerim. İnşallah hep yüzünü güldüren bir hayatın olur. 

Seni seviyorum...

Ablan..

28.01.2006', 'Ben daha üç yaşımda yoktum sen o güzel gözlerini dünyaya açtığında... minik sarı bir şeydin. O minik, yalnız dünyama bir renk katmıştın, öyl...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kardeslik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman/Sensizlik Şiir', 'zaman-sensizlik-siir-ali-gencay-a0dmx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Git/mi diyorsun

Gideceğim yer senden çok mu uzak 

Sus/mu diyorsun

Yüreğimdeki çığlıkları kim duyacak

Mutlu ol diyorsun

Bilmiyor musun

Sensizlik/ölüm/ben 

Mutsuzluğa esir/tutsak

Uzaksın artık bana

Kısık gülüşlerin yok

Havadan sudan konuşuyoruz 

Sevda sözcüklerin yok

Uğruna büyüttüğümüz hayaller

Uykusuz geçen geceler

Uyandığım güne günaydınım yok

Cesurduk hani

Hani korkusuzduk

Sen/ben/gelecek, mutluluktuk

İşte dönüyorum dünyama

Yalnızlık

Beni terk etmeyen tek dostluk

Belki nice tenlere soyunur

Beklide hiç giyinmem

Kim bilir beklide hiç sevmem

Gündüz güneşte tararım saçlarını

Gece heveslere yenilmem

Islanır uzun kirpiklerim

Sen bilmezsin/bilmeyeceksin

Yağmurlar yağana dek silmem

Seni alacak her şeye küfrettim

Uzun sensiz/sessiz zamanlarda

Çıldırmamak adına

Sık, sık adını zikrettim

Yetmedi 

Duvara/masaya/bardağa/ışığa

Resmini çizdim

Sana demiştim

Büyüktür benim yüreğim

Açtın kapısını

Ben üzerine kilitledim

Sana demiştim

Tektir benim güneşim

Işığını sen verdin

Artık senden gayrı

Kör, görmez gözlerim', 'Git/mi diyorsun Gideceğim yer senden çok mu uzak  Sus/mu diyorsun Yüreğimdeki çığlıkları kim duyacak Mutlu ol diyorsun Bilmiyor musun Sensiz...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/zaman-sensizlik-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennem', 'cehennem-zuhal-aksulu-ljal6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatımın belki de en dik yokuşunu iniyordum..

Yanaklarımdan hazan yağmurları gibi süzülen göz yaşlarım cayır cayır yanan kalbimi soğutmaya yetmiyordu. 

Mevsim dışarıda yazdı... içimde sonbahar... 

Ne yağdırdığım yağmurlar yetiyordu ne kopan fırtınalar.. 

içimdeki cehennemi söndürmeye. 

Dikti.. dimdik bir yokuş. 

Yürümüyor adeta yuvarlanıyordum. 

Taa cehennemin dibine. 

Oysa ki cennetteydim. 

Kollarında huri gibi hissediyordum kendimi. 

Dudaklarından tadıyordum balın en tatlısını. 

Şimdi ise cehenneme biletim kesilmiş.. hıçkırıklarla yürüyordum. 

Sensizlik cehennemin ta dibi. 

Umursamadan terk ettin. İttin beni...', 'Hayatımın belki de en dik yokuşunu iniyordum.. Yanaklarımdan hazan yağmurları gibi süzülen göz yaşlarım cayır cayır yanan kalbimi soğutmaya ...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cehennem-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz Sokak', 'cikmaz-sokak-zuhal-aksulu-79yda', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatımda karşıma çıkan belki de en uzun yol duruyordu karşımda.. en uzun, en güvenli, en güzel.... yanda akan mavi nehirler.. papatya kokuları vardı... sımsıkı sarılmıştım sana.. sımsıkı sarılmış ilerliyordum bu yolda... sevginle.. gözlerinle.. çiçeklerinle... öyle kaptırmıştım ki kendimi güzelliklere.. yanımdan ayrıldığını fark etmedim bile..  yalnızdım koca yolda.. yapayalnız.. elin elimden çoktan gitmiş.. bir çiçekler kalmıştı kucağımda.....  çoktan solmuş.. boynu bükük mor çiçekler.... “bir gece ansızın gel yine.. elinde mor çiçeklerle” demiştin.. bekliyorsun diye.. ordasın diye geliyordum.. hiç bırakmadım kucağımdan o çiçekleri.. nefesim tıkanıncaya.. canım çıkıncaya kadar yürüdüm.. hem de yalnız... korktuğum zamanlar oldu.. yoktun...

Uzun bir yol sanıyordum.. sen yoktun.. yolum bir uçurumla son buldu... boşluğa baktım uzunca... göz yaşlarım aktı... aktı.... aktı.....

Bu aşk çıkmaz sokaktı...

Kucağımdaki çiçekler kendini boşluğa bıraktı....', 'Hayatımda karşıma çıkan belki de en uzun yol duruyordu karşımda.. en uzun, en güvenli, en güzel.... yanda akan mavi nehirler.. papatya kokul...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cikmaz-sokak-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin', 'ellerin-zuhal-aksulu-dwcfx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'öyle güzel ellerin vardı ki... kendi ellerimden utandığım... küçük tırnaklar.. uzun ince parmaklar... yumuşak.... 

yıllarca hayatta kendine bir yer edinmek için çalışıp durmaktan kurumuş çatlamış ellerim... tıpkı babamınkine benzeyen kaba, erkeksi ellerim var benim...  el ele geldiğimizde ellerinin sıcaklığını hiçbir zaman hissedemediğim. 

sen o yumuşacık ellerinle papatyaları sererken buluştuğumuz ilk gece... düş gibiydi her şey. hiç uyanmayayım dediğim....

oysa...

oysa sen hiç hoşlanmadın sana dokunmamdan.. yorgun sevişmelerin ardından gelen küçük dokunuşlardan... 

''çek ellerini...'' dedin.. 

düşünemedim...

düşünemedim senin o yumuşacık ellerinin aslında nasır tutmuş bir kalbi sakladığını... benim ellerim kabaydı.. nasırlıydı.. ama kalbim pamuktandı.. buluttandı... senin için... yumuşacıktı.. senin o hiç bir zaman dokunamadığım nasır tutmuş kalbin tıpkı bir hallacın pamukları savurduğu gibi savurdu yüreğimi... paramparça etti.... içimdeki aşk maviliğini süsleyen beyaz buluttan kocaman kalbimi ağlattı... sonbaharın o bitmek tükenmek bilmeyen yağmurları yağdı gözlerimden.. 

günlerce..

gecelerce...

ellerin kalbimi parçaladı... 

ellerin bir düştü benim için...

ellerin düştü....

kalbim düştü...

ellerin...

düştü...', 'öyle güzel ellerin vardı ki... kendi ellerimden utandığım... küçük tırnaklar.. uzun ince parmaklar... yumuşak....  yıllarca hayatta kendine ...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ellerin-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Yüzünden', 'senin-yuzunden-murat-demir-fc0tc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman iki sevgiliyi  görsem el ele

Sırtımdan hançerlenmiş gibi acı duyarım

Birde; sen gözlerimin önüne gelince ki hele

Kayıp gider içimden, edebim, iffetim, arım

Ne zaman bir çift görsem yürürlerken yan yana 

Yalnızlığımı görür yanarım, yanımda yok diye diğer yarım

İşte o an gözyaşlarım sele döner ağlarım yana yana

Ağladıkça arşa çıkar, arşa hıçkırıklarım', 'Ne zaman iki sevgiliyi  görsem el ele Sırtımdan hançerlenmiş gibi acı duyarım Birde; sen gözlerimin önüne gelince ki hele Kayıp gider içimde...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senin-yuzunden-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahşere dek çıkmaz bunun acısı.', 'mahsere-dek-cikmaz-bunun-acisi-yusuf-onder-bahceci-6asqy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herkes sevdiğine güller veriyor,

Sevdiğim diyerek sitemler ediyor,

Benim sevdiğimse ele gidiyor,

Mahşere dek çıkmaz bunun acısı.

Herkes sevdiğine sevdiğim diyor,

Sevdiğim diyor da güller veriyor,

Sen ellerdesin be kâlbim ağrıyor,

Mahşere dek çıkmaz  bunun acısı.

Herkes sevdiğine birtanem diyor,

Acaba gerçekmidir bu bilinmiyor,

Önder senin için cânlar veriyor,

Mahşere dek çıkmaz bunun acısı...', 'Herkes sevdiğine güller veriyor, Sevdiğim diyerek sitemler ediyor, Benim sevdiğimse ele gidiyor, Mahşere dek çıkmaz bunun acısı. Herkes sevd...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mahsere-dek-cikmaz-bunun-acisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntikam ve İntihar', 'i-ntikam-ve-i-ntihar-zuhal-aksulu-7kh2k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İş sebebiyle gidiyorum demiştim evden çıkarken. Evet hayatımın en önemli işiydi... ve artık bitmesi gerekiyordu.

Üç gün önce telefon açıp da “seni çok özledim, sana geliyorum” dediğimde nasıl da heyecanlanmıştı. Birkaç saat sonra başına geleceklerden habersiz “hemen gel, bekliyorum” demişti. Otobüsün kapısından adım attığımda hava soğuktu. Dışarıda lapa lapa kar yağıyor, göz yaşlarım içime akıyordu. Havadan değil ama, buz gibiydi ellerim. Ve hayatımda ilk defa terliyorlardı. Heyecandan gözümü bile kırpmadım. Yol geçmek bilmiyordu, ben saniyeleri sayıyordum. Otobüs otogara yaklaşıp da uzaktan onu gördüğümde bir an yapamayacağımı düşündüm. Dışarıdaki havadan bile soğuktu içim ama yetmeyecek gibi gelmişti. Yüzümde donuk bir gülümsemeyle basamakları inerken ürperdim bir an. Yılışık sarılışına aldırmadan “hadi gidelim” dedim. Güldü... yola çıktık. Yüzüne bakmamaya çalışırken; havadan, sudan geçmişten bahsettiklerine cevap veriyordum. Daha önce bitmek bilmeyen yollar göz açıp kapayana kadar bitmişti işte. Anahtarı deliğine sokarken bir an dönüp gitmek geldi içimden. Sonra olanları düşündüm. Yapamazdım. Bu benim en önemli işimdi ve tamamlamadan dönemezdim. İçeri ilk o girdi. Ve ayakkabılarını bile çıkarmadan sarıldı vahşice. Yüzümde yine aynı o donuk gülümseme, ittirdim hafifçe. Sen “içeriye git, soyun... gözlerini kapat ve beni bekle” dedim... tek kelime bile etmeden dönüp talimatlarımı yerine getirmeye koyuldu. Yavaşça ayakkabılarımı çıkardım. Şuursuzca çantamın bir köşesine attığım bıçağı elime aldım ve hızla yanına gittim. Ne olduğunu anlayamadı. Daha dışarıdaki soğuktan donmuş vücudu ısınamadan bıçağımın soğuk metalini tam göğsünün arasına sapladım. Dehşetle gözlerini açıp acıyla haykırırken yüzünde gördüğüm karmaşık duygulardan biri şaşkınlık, biri özürdü. Son nefesini bile verirken biliyordu özür dilemesi gerektiğini. Ama o üremeye programlanmış hayvansı erkek içgüdülerinin önüne geçemeyen her erkek gibi dileyememişti özrünü işte. Arkamı dönmüş, odadan çıkarken son hırıltılarını işittim. Geberiyordu köpek... hak ediyordu. İlk iş olarak ellerime, yüzüme sıçramış kanı temizlemek üzere banyoya yöneldim. Aynada kendimi gördüğümde ben bile korkmuştum. O iğrenç gülümsemenin üzerine sıçramış birkaç damla kan... ağzıma, burnuma hatta gözlerime kadar bulaşmıştı. Uzun uzun soğuk suyun avuçlarıma doluşunu seyrettim. Ne kadar sürdü bilmiyorum... belki birkaç dakika, belki birkaç asır. Sonra aniden kendime geldim. Yapmam gereken daha çok iş vardı... ve ben daha çok başındaydım. Buzdan bile soğuk suyla yüzümü yıkadım birkaç defa. Ve mutfakta buldum kendimi. Sanki az önce elleri yüzü kan içindeki o soğuk kanlı katil ben değilmişim gibi... açtım buz dolabını, içecek bir şeyler aradım. Dışarısı buz gibiydi. Ama şimdi içim yanıyordu. Şansıma bir şişe soda buldum. Yaptıklarımı değil ama yol boyunca yediklerimi sindirmeme yardımcı olacaktı. Soğuk sodanın kekremsi tadını damağımda hissederken, içerideki geçmişimin ölü bedeni daha soğumamışken açtım telefonumu. Şans eseri cüzdanımda kalmış kartı aldım elime. Usulca numarayı çevirdim....

Karşımda bana iyice yabancılaşmış ses cevap verdi. “alo? ”... “benim” dedim. Hatırlayamadı.. ama uzun sürmedi hatırlaması. “seni özledim, sana geliyorum” dedim... önce mırın kırın etti. “sadece bir defa, n’olur beni kırma..” dedim. O da her erkek gibi içgüdülerine yenik düştü. “gel” dedi. Ben bulunduğum zamandan başka bir zamana gitmek üzere yola çıktığımda hala kar yağıyordu. Ve ben hala gülümsüyordum. Kafamı soğuk otobüs camına dayamış, daha da zevkli olacağını düşündüğüm işimi yapmak için yolun bitmesini bekliyordum. Küçük bir kasabanın dar yolundan geçerken olmayacak bir şey oldu. Öyle dalmış giderken tanıdık iki gözün bana baktığını fark ettim. Şaşkınlık vardı yüzünde. Yine geçmişimden, farklı bir zamandan... ama asla suçlayamayacağım, asla kıyamayacağım... kafamı çevirdim görmemişçesine... şimdi yol daha zor geliyordu. O zamana kadar içime akan göz yaşlarım artık yağmur gibi süzülüyordu gözlerimden. İlk defa ellerim titremeye başlamıştı. Yüzüm de alev alev yanıyordu. Uyumaya çalıştım. Daha yolum vardı ve geçmek bilmeyecekti. 

Gözümü açtığımda otogara gelmiştik. Otobüsün park edişini bile beklemeden kalkıp üstümü giydim. Otobüsten indiğimde soğuk şehrin ayazı yüzümü yaladı. Yüzümde kuruyan göz yaşlarım zaten cildimi germişti, bu soğukla iyice kuruyacak, çatlayacak diye düşündüm... hava iyiden iyiye kararmıştı. Telefonumu açtım. Haber vermediğim için merak eden birkaç kişi aramıştı. Aldırmadan numarayı çevirdim. “geldim” dedim. “nerede buluşalım? ”... “ben seni alırım” dedi. Karanlık ve soğuk havada otogarım dışında belki on tane  sigara içtim. Bir ara sigara paketinin üzerindeki yazıya gözüm takıldı. “sigara öldürür” yazıyordu. Güldüm... ben çoktan ölmüştüm. Geldiğinde hala gülümsüyordum. Arabanın içi sıcaktı. Benim yüzüm yanıyordu... ama içim soğuktu. “nereye gidelim” diye sorduğunda ben geçmişi düşünüyordum. Yine yüzümde o pis gülümsemeyle. “sakin bir yere” dedim. Fazla zaman almadı sakin bir yer bulmamız. Arabayı kenara çekti ve motoru bile kapatmadan üzerime abandı... bense sarılır gibi yapıp çoktandır elimde sakladığım kanlı bıçağı sırtına sapladım. Tıpkı sevişirken çıkardığı iğrenç homurdanmalara benzer bir sesle üzerime yığıldı. İttim üzerimden. Bu sefer yüzüme kan bulaşmamıştı. Ama saçımı düzeltmek için dikiz aynasına baktığımda yine o ürkünç ifadeyle karşılaştım. Gayet sakin saçımı düzelttim. Zaten her yeri kan olmuş sürücü koltuğunun kenarına bıçağımı sildim... ve arkama bakmadan indim... Saat daha erkendi ve diğer işlerimi tamamlamak üzere geri dönebilecek otobüsü bulabilirdim. Otogara gittim.

Otobüsten indiğimde değişen hiçbir şey olmadığını fark ettim. Sadece içimde müthiş bir hafifleme duygusu. Hava aynıydı, ben aynıydım... sabah olmuştu... ve eski bir melodi mırıldanarak yürümeye başladım. Daha vakit erkendi, kahvaltı ettim. Onu bulmam zor olmamıştı. Elimle koymuş gibi. Zili çaldığımda yataktan yeni çıkmıştı. Şaşkın bir ifadeyle “hayırdır” dedi. Hayırdı elbette. Hayatımın en hayırlı işini yapıyordum kendimce, dünyayı adi birkaç pislikten kurtarıyordum. “hayır hayır” diyip içeriye daldım. Önümden adımlarını atarken ne olduğunu anlayamadı. Tam sırtının ortasında bıçağımın soğuk metalini hissedince acıyla haykırdı. İlk defa midem bulanmıştı... o yere yığılmış, kalkmaya çalışırken gittim, kustum. Döndüğümde hala yerde çırpınıyordu. Bu sefer daha kuvvetli bir daha sapladım bıçağımı. Bir daha, bir daha... ve bir daha.... kıpırtı kalmayana kadar. Gidip kan içinde kalmış ellerimi yıkadım. Birazdan birileri gelebilirdi. Hızla çıktım evden. Yine yollar beni bekliyordu. Bir işim daha kalmıştı. Ama onu daha vahşice gerçekleştirmeyi planlıyordum. Kan yok, şaşkınlık yok... sadece acı olacaktı. Yazacağım soğuk satırlar onu zaten öldürecekti. 

Kendimi küçük mutfağa kapattığımda o katil satırları çoktan yazmıştım. Ocağın tüm gözlerini açmış, geride bırakacaklarımı düşünmeden öylece oturuyordum. İşim biterken satırlarımı okumaya devam ediyordum. Eminim beni bulduklarında yüzümde ilk defa huzuru bulacaklar. Hayatta hep karşıma çıkan sahte kişiliklerin iğrenç oyunlarına kurban giden saf duygularımın intikamını almış olmanın huzuruydu bu. Yanlış yerler, yanlış ilişkiler.. daha da önemlisi yanlış dostluklar. Beni kendi tapındıkları ucube tanrılarına kurban etmişlerdi. Artık buna izin vermeyecektim. Oluk oluk kanla boyanmış saflığımı artık benimle götürüyordum. İçerisi iyice havasızlaşmış. Son bir gayretle yazdım... “seni seviyorum”... kime olduğunu bilmeden. Göz kapaklarım iyice ağırlaşı........................................................................................................................................................................................................................................................................................................................................................................................................tı.

27.01.2006

Zuhal AKSULU', 'İş sebebiyle gidiyorum demiştim evden çıkarken. Evet hayatımın en önemli işiydi... ve artık bitmesi gerekiyordu. Üç gün önce telefon açıp da...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/intikam-ve-intihar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katilim', 'katilim-zuhal-aksulu-kbuuo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çokça zaman olmuştu bu kadar açmayalı içimi... Hayatın ve insanların kötülüklerine karşı gidiğim zırhı çıkarıp çırılçıplak kalmamıştım uzun zamandır. Aynı hataları tekrarlamayacağıma dair kendi kendime verdiğim sözlerin aklımdan uçup gittiği anda soyunuverdim birden. Aşk insanı çıplak bırakıyor daha eski yaraların iyileşmeden. Öyle güçsüz, öyle ben, öyle çıplak çıktım ki karşısına şaşırdı... Beklemiyordu bunu. Defalarca söyledi korktuğunu sevgimden. O korktukça ben pervana oldum. Karanlık gecede minik bir mum ışığının etrafında dolanan ateş böcekleri gibi dolandım etrafında.. Onun minicik sevgisi için....Öyle büyüktü ki aşkım, öyle güçsüz bırakıyordu ki beni etrafımda olan biteni farkedemedim. Benim o sevgi sandığım minik mum ışığı aslında bir tuzaktan başka birşey değilmiş. Haince yakaladı beni... Ezdi hiç düşünmeden. Ben ortalıkta öylece paramparça ve kanlar içinde bir bedenden ibaret kaldım... Kan... Kırmızı... Tıpkı ışığı en güçlü hissettiğim günlerde gönderdiği güller gibi.. Aşkın rengi kırmızıdır... Başta çiçekler... Kırmızı güller... Bir zaman sonra yorgun bedenler.. Kırmızı sevişmeler.. Sonda ise lime lime bir yürek... Kandan kırmızı...  Aşkın başı da kırmızı sonu da... Çıkarttığım zırhıma geri koyacak tek sağlam organ bile bulamıyorum bu dağınıklıkta... Yapabileceğim tek şey belki de gül kırmızısı kanımı bir kovaya doldurup katilime yollamak.. Kana kana içsin diye... Kim bilir? Belki tek istediği budur...

9/7/2005', 'Çokça zaman olmuştu bu kadar açmayalı içimi... Hayatın ve insanların kötülüklerine karşı gidiğim zırhı çıkarıp çırılçıplak kalmamıştım uzun ...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/katilim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katolik Kilisesi', 'katolik-kilisesi-zuhal-aksulu-spubo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Koca koca bulutların gökyüzünü kararttığı kasvetli bir sonbahar günüydü.. Üşüyordum.. Yürüyordum...Bilmediğim bu yabancı sokaklarda yalnız.. Kendimi arıyordum..

Rüzgarın uğultusu yıllar önce ölmüş ve sıkıntıdan patlamış ruhların çığlıkları gibi.. beynimde yankılanıyordu. İki yanı ağaçlarla kaplı uzun ve dar bir yolda yapraklar yerde dans ediyorlardı... Bense kafamı eğmiş ''belki'' diye diye ağır adımlar atıyordum... Kimdim ben.. neydim.. ne yapıyordum..? Ne işim vardı buralarda.. neredeydim? Beni yalnızlığımla baş başa bırakan, ruhumu ortadan kaldıran katilim neredeydi? 

Kafamda binlerce soru işareti.. binlerce ok... hepsi de aynı şeyi soruyor... aynı yönü gösteriyor.. İnatla direnmekten başka bir şey gelmiyor elimden.. direniyorum kendime.. direniyorum ruhsuz bedenime...

Kafamın üstünden bir kuş çığlık çığlığa geçerken duydum çan sesini.. sanki halimle dalga geçer gibiydi kuş... sanki... güler gibiydi.. irkildim çan sesiyle...Yapraklarını göz yaşlarım gibi tek tek dökmüş.. sanki ruhum gibi kurumuş ağaçların ortasında olanca heybetiyle duruyordu orada... Yüzlerce yıl öncesinden kalma... Rönesans devri mimarisini gururla taşıyan bir Katolik kilisesiydi sanırım.. O bile bir ruh taşıyor gibiydi.. ben kurumuştum... Çan sesleriyle bir şeyler anlatmaya çalışıyordu.. ben susuyordum....

Hızla kiliseye doğru yöneldim.. İçimde, içinde bir şey bulacağım ümidiyle.. Onun o kocaman ahşap kapısından geçince fark ettim.. Uzun zaman olmuştu ben kapılarımı kapayalı.. çanlarımı susturalı... ne gelen vardı ne giden.. garip bir zangoç gibi kalmıştım içimde.. gidenin ardından çan kulesinden bakakalan.. Bir el dahi sallanmamıştı.. Bir ruh bırakılmamıştı.. ve içimin ayazı şu taş duvarlı koca binadan bile beterdi... Donuyordum... dondukça kaçıyordum işte...

Çok şey hatırlattı bu kilise bana işte... içimi...

İçeride kulağa çok hoş gelen büyülü bir melodi vardı.. benim içimde suskun çığlıklarım.. Nasıl da pes etmiştim.... nasıl da.. kendimden vazgeçmiştim....

Kocaman bir binaydı.. yüksek tavanlar... geniş duvarlar... Tıpkı bir zamanlar kalbimin olduğu gibi.. dünyayı içine sığdırabileceğim bir kalbim vardı.. canlı neşeli... ama yıkılmıştı işte....

O heybetten büyülenmiş... gözlerim dolmuş.. Hızla çan kulesine yöneldim... Sesleri öyle artmıştı ki.. kulaklarım patlayacak sandım... O kadar da yüksekti.. çıktım.. çıktım... Hala çan sesleri kulaklarımda...

Son bir teşekkürle bu Katolik kilisesine...

Kendimi boşluğa bıraktım... 

Benimle dalga geçen kuşa inat....', 'Koca koca bulutların gökyüzünü kararttığı kasvetli bir sonbahar günüydü.. Üşüyordum.. Yürüyordum...Bilmediğim bu yabancı sokaklarda yalnız.....', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/katolik-kilisesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolmak', 'kaybolmak-zuhal-aksulu-4o2jr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan nereye gideceğini bilirken kaybolmuş olur mu? 

Biliyordum nereye gideceğimi.. ne yapacağımı...

Düştüm yollara.. adım adım geçtim ter kokan, çöp kokan, hayat kokan, insan kokan sokaklardan... Her adımda yüzümdeki gergin gülümseme hafifledi.. Daha bir oturdu üstüme sanki.... Kaybolmuştum... yalnızdım. nereye gideceğimi biliyordum....

İlk terk edilişim değildi bu... ama son olacaktı... 

Ben de terk ediyordum artık kendimi..

Hayatımın en anlamlı en güzel yolu beni terk etmişti...  yanından mavi ırmaklar akan.. mis gibi papatya kokan... en uzun yolum.. gitmişti... Yolsuzdum.. Kaybolmuştum... Uzun süre aradım yeni bir yol.. hep karanlık hep karanlık... Kötü ve zor yollar çıktı karşıma... 

Yorulduğum anda.. en kaybolduğum anda buldum yolumu... 

Biliyorum nereye gideceğimi...

Sessiz melodiler yükseliyordu içimden yüzümdeki deli gülümsemeden.. İnsan kaybolunca delirebiliyormuş işte... 

Sessiz.. sakin.. yürüdüm onca yolu.. tek başıma.. yolsuz...

Köprünün başına geldiğimde iyice aydınlanmıştı yolum......

Daha bi sıklaştı adımlarım... daha yumuşadı gülümsemem.. 

Önce içimde kalmış tüm kelimeleri çıkardım cebimden..... savurdum Boğazdan esen serin rüzgara doğru.. belki yerlerine ulaşırlar bir bir.... belki... Aman boş versene...

Köprünün korkuluğuna tırmandığımda saldım içimdeki içinde boğulduğum denizi..... bir hışımla hıçkırdım... boşaldı... ferahladım....

Sonra....

Sonra kendimi buldum.. 

Kaybolmuştum..

Denizim denize buluştuğunda...

Kendim uzun bir yoldum aslında....

Sonuna gelmiştim.... 

Son bir teşekkürle hayatımdaki her şeye...

Kendimi de saldım denize..... uçuyordum.. uçtukça kaçıyordum... 

Sonra kendimi buldum denizde.. denizimde.....

Sonra..

Sonra ne mi oldu...? 

Bendenim denizde kayboldu....

Bulunmamacasına......', 'İnsan nereye gideceğini bilirken kaybolmuş olur mu?  Biliyordum nereye gideceğimi.. ne yapacağımı... Düştüm yollara.. adım adım geçtim ter k...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kaybolmak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Kar', 'mavi-kar-zuhal-aksulu-dur5c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Serin bir Ankara sonbaharıydı biz ilk buluştuğumuzda... Birbirini ilk defa gören ama sanki yıllardır tanıyormuş gibi hasretle kucaklaşan iki insan...

Mavi soğuk renklerdendir.. ve maviydim ben onun için... rengim mavi... mevsim sonbahar... 

İçimizi ısıtacak sıcak bir çay içtik beraber.. Hayatımda içtiğim en lezzetli çaydı belki... çay.. sıcak.. soğuk.. sigara.. ve kokusu başımı döndürmüştü... 

ve buluştuk biz... mevsim kışa döndü... biz buluştuk... Lapa lapa yağan kara ve Ankara''nın ayazına aldırmadan onu bekliyordum.. Nasılsa sıcak bir çayla içimizi ısıtırız diye.. ısındı da.. öyle ısındı ki... Tutkuya dönüştü benim için.. bu son buluşmamız dediğim her seferinde onu görebilmek için yeniden bekliyordum... beklemek.....

Kış bitti... karlar eridi... ve eriyen karlar gibi o da hayatımdan usulca çekip gitti... dedim ya.. maviydim onun için ben... gece yerde mavi mavi parlayan karlar gibi......', 'Serin bir Ankara sonbaharıydı biz ilk buluştuğumuzda... Birbirini ilk defa gören ama sanki yıllardır tanıyormuş gibi hasretle kucaklaşan iki...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mavi-kar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otel Odasındaki Hayalet', 'otel-odasindaki-hayalet-zuhal-aksulu-voz2i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soğuk, karanlık pis bir otel odasında yalnız başına yaşayan bir ruh olmak ne kadar da kötü bir şey.... Bağırmak... Çığlıklar atmak... Ama sesini kimseye duyuramamak....  Her gün gelen değişik yüzler... Değişik hikayeler.. acılar, hüzünler...

Dışarıdan bakıldığında ''bunun da problemi olur mu? '' diyebileceğiniz türden insanlar... Güzel giyimli.. Tıraşlı suratlar.. Gel gör ki koltuğun altına sıkıştırılmış en ucuzundan şaraplar... Yudum yudum içilir.. Yavaş yavaş kendinden geçilir.. Kim ne düşünceler dolaşıyordu milyonlarca beyin hücrelerinin arasında... Hep bir merak.. Hep bir iz bırakma tutkusu.. Küflü duvarlara tırnaklarla yazı yazanlar... Yatağın başucundaki kırık cam parçasını eline alıp... Korkuyla bırakanlar....

Belki...

Belki dolaptaki ipten habersiz.. Bir zamanlar benim soğuk ve donuk bedenimin sallandığı adi, ucuz ip.. 

Şaşarım hep nasıl taşıdığını o ağırlığı o kadarcık ip parçasının... 

Odadaki tek taburenin üzerine çıkıp ipi tavana bağladığımda nasıl da ellerim titremişti... Belki de kalbim titremişti... Terkedilmişliğin verdiği acıyla... kendimi ona bağlamıştım... ona... sevgisine... sıcacık ellerine... ve beni yalnızlığımla baş başa bıraktığında boşlukta kalmıştım.. Kendimi attığım bu soğuk otel odasında kendimi bağlayacağım başka bir şey arayacağımdan habersiz.. Yudum yudum içmiştim köpek öldüreni... yudum yudum içtim geçmişi.....

En koptuğum anda... En korktuğum anda yalnızlıktan.... Gözüme ilişen bir parça ip oldu....

Düşünmeye fırsatım bile olmadı.. düşünmek istemedim belki de.. Sadece kendimi bağlayacak bir şey arıyordum ve buldum...

Tabureye çıktım yavaşça.. ve titrek ellerle.. yaşlı gözlerle güzel bir düğüm attım ipe önce... ve sakin bağladım tavandaki kertiğe... 

İpin sıcaklığını soğuk odada hissettiğim ilk yer boynumdu...  tıpkı sıcacık elleri gibi.... 

Son gözyaşım da süzülürken yanağımdan aşağıya.. ittim tabureyi... saldım kollarına kendimi.... her zaman yaptığı gibi nefessiz bırakmıştı beni...  Kollarında hep olduğu gibi kasıldı bedenim... ve her zamankinden daha hissiz dışarı çıktı dilim....

Artık sıcaktı.. sıcacıktı... oradaydım.. gülüyordum.. ölüyordum...

Kaç kez öldürmüştü beni..  bir kez daha ölüyordum... ama bu sefer gülüyordum... fütursuzca...

Çok kısa sürdü.. Üzerinden iki gün geçmişti soğuk bedenimi bulduklarında... Belli ki kaçamak yapmak için gelmiş bir çiftti... Önce odaya kız girdi... neşeliydi.. gülüyordu... ama birden dondu kaldı... bir çığlık patlattı... karanlıkta yankılanan kulak tırmalayıcı tiz sesi herkesi ayağa kaldırmıştı... herkes.. herkes geldi...

Önce bir bıçakla ipi kestiler.. çıkarttılar.. çok geç kaldıklarını anladılar.. biri çıkarttı ipi morarmış boğazımdan... fırlattı.. dolaba....

Yerlerinden fırlamış gözlerim ve dışarı sarkmış dilimle öylece bakıyordum oysa ki ben onlara.. hafif bir gülümsemeyle...

Çıkarttılar bedenimi...

Unuttular beni...

O gün bugündür izlerim herkesi.. geleni gideni... uyarırım.. bağırırım.. duymaz beni kimse.. duyamaz... 

Ben o soğuk otel odasındaki hayalet... 

Hayat..

Gerçek...

Ölüm de....', 'Soğuk, karanlık pis bir otel odasında yalnız başına yaşayan bir ruh olmak ne kadar da kötü bir şey.... Bağırmak... Çığlıklar atmak... Ama se...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/otel-odasindaki-hayalet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evin Reisi Çok Zalim', 'evin-reisi-cok-zalim-yusuf-onder-bahceci-k70x4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evin Reisi çok zalim,

İçer, içer Hanım döver,

Evin Reisi çok zalim,

Hep çocuklarına söver.

Evin Reisi çok zalim,

Öz çocuklarını döver,

Evin Reisi çok zalim,

Hep elleri metheder.

Evin Reisi çok zalim,

O Kızına bile  söver,

Evin Reisi çok zalim,

Para, para, para der. 

Evin Reisi çok zalim,

Bilmez iyiyi ve kötüyü,

Evin Reisi çok zalim,

Haram bütün yediği.

Evin Reisi çok zalim,

Bitmez yaptığı, ettiği,

Evin Reisi çok zalim,

Birgün bulur hakettiği....', 'Evin Reisi çok zalim, İçer, içer Hanım döver, Evin Reisi çok zalim, Hep çocuklarına söver. Evin Reisi çok zalim, Öz çocuklarını döver, Evin ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/evin-reisi-cok-zalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Gömerim', 'seni-gomerim-lokman-hamitoglu-iur1j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SENİ GÖMERİM

Nazenin ilkbaharlara

Semada uçurtmalara

Bağrı yanık sevdalara 

Ben seni sorarım ey yar! ..

Kayıp giden yıldızlara

Akıp giden ırmaklara

Kuma gelen dalgalara

Ben seni çizerim ey yar! ..

Sağnak yağan yağmurlara

Kurak kalan topraklara

Derdi yazan kemanlara

Ben seni çalarım ey yar! ..

Hesapsız bakan dağlara

Dipli dipsiz ummanlara

Gönlümde ki arzulara 

Ben seni gömerim ey yar! ..

       LOKMAN HAMİTOĞLU', 'SENİ GÖMERİM Nazenin ilkbaharlara Semada uçurtmalara Bağrı yanık sevdalara  Ben seni sorarım ey yar! .. Kayıp giden yıldızlara Akıp giden ır...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seni-gomerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmadı', 'kalmadi-zernisan-aydogan-16zcm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geçti de ömrümün baharı yazı

Istırap dinmedi dert azalmadı

Göz yaşım teselli verirdi bazı

Şimdi gözlerimde yaşta kalmadı

Karardı gittikçe hep gecelerim

Hayatı sık dokur sık incelerim

Uymuyor devrana düşüncelerim

Uyacak akılda bende kalmadı

Her günüm geçiyor bir başka dertle 

Kadere isyan bahta nefretle

Her taşı yokladım hep cesaretle

Şimdi baş vuracak taşta kalmadı', 'Geçti de ömrümün baharı yazı Istırap dinmedi dert azalmadı Göz yaşım teselli verirdi bazı Şimdi gözlerimde yaşta kalmadı Karardı gittikçe he...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalmadi-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülün Dikenindeki Sancı Bülbüle Yabancı Değil', 'gulun-dikenindeki-sanci-bulbule-yabanci-degil-zeliha-bicer-amxqi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gülün sudaki aksinde,gülün sadeliği var

Bülbülün sevdası

Benim sana yazdıklarımda,gönlümün yarası var

Sılası, sevdası var,

Gülün dikenindeki sancı bülbüle yabancı değil

Yüreğimdeki hasretlerin bitimsiz çilesi var.', 'Gülün sudaki aksinde,gülün sadeliği var Bülbülün sevdası Benim sana yazdıklarımda,gönlümün yarası var Sılası, sevdası var, Gülün dikenindeki...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gulun-dikenindeki-sanci-bulbule-yabanci-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Bunlara Bahaneydi.', 'siir-bunlara-bahaneydi-zeliha-bicer-o99bn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özledim zaten seni 

Şiir bunlara bahaneydi.

Utanır oldum artık.

Kulağına usuldan söylerken

Özlem türkülerini şarkılarını

Şarkılar da bahanemdi, 

Anlatmak istediklerimdi. 

Yazmak sana 

Ama yalnız sana

Özlemek böyle birşey

Deli sanma beni, sakın ha! 

Dedim ya

Şiir bahaneydi bunlara..', 'Özledim zaten seni  Şiir bunlara bahaneydi. Utanır oldum artık. Kulağına usuldan söylerken Özlem türkülerini şarkılarını Şarkılar da bahanem...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/siir-bunlara-bahaneydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-cengiz-kapusuz-wh27n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey dünya,

Halin bu ya,

Bir resim çizdim suya,

Sahte renkler sahte boya.', 'Ey dünya, Halin bu ya, Bir resim çizdim suya, Sahte renkler sahte boya....', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dunya-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ağlamak için severim!', 'ben-aglamak-icin-severim-enes-ates-ga26w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben ağlamak için severim,

Ağlarım; 

Ve

Bİter...! 

    Gözyaşı,,

aktığında eğer değer buluyorsa

ve ıslatıyorsa dudakları,

o zaman gözyaşı oluyor ya! 

    AŞK da öyle ağlanıyor işte...

     Geceler,,

bitmek bilmeyen bir çile

dikenler diyarında son gülün solmuş,

gündüze el salla, geri gelmeyecek

     AŞK da işte böyle nafile...

      Gözlerin,,

tan vakti ağarıyor gözlerime,

en şerefli nefesini soluyor feza.

ama gözlerin yalan, benim olmadı! 

      AŞK da gözlerin gibi: Değme! 

       Gözyaşım,

        Gecelerde,

          Gözlerine akıp gitmişti...

Ben ağlamak için sevdim,,,

AĞLADIM VE BİTTİ ! !', 'Ben ağlamak için severim, Ağlarım;  Ve Bİter...!      Gözyaşı,, aktığında eğer değer buluyorsa ve ıslatıyorsa dudakları, o zaman gözyaşı olu...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-aglamak-icin-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Sonra Vurur', 'ask-sonra-vurur-gul-yazganarikan-uk5cs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben ne Venedik’te bir Gondolum, 

Ne de Roma da bir aşk çeşmesi

Senin aradığın sanırım bir yaz hevesi,

Prag’da bir cafe’de bir gönül eğlencesi...

Benden kalelerimi istiyorsun....

Zaptettin sanıyorsun belki de hisar uçlarını

Hint okyanusunda bir sandal gibi, 

Akıntıya bıraktım umutlarımı,

Bekleyişim sen değilsin, değilsin Alp’lerde aradığım...

Tarumar değil ordularım, 

Henüz başladı aslında,

Senin aşkla savaşın...

Yıkılan kulelerim, kalbime saplanan top mermilerin yok...

Ben en çok öldüğümde, en çok dirilenim...

Ben senin o minik heveslerin içinde...

Sağır eden bir sesle aşk marşları söylerim...

Sen uyumaktasın...

Savaşın ortasında, Rüyaya dalmaktasın...

Kalbine saplandığında, barut kokulu kurşun...

Sen korkusuz korkak,

Kaybetmiş olacaksın...', 'Ben ne Venedik’te bir Gondolum,  Ne de Roma da bir aşk çeşmesi Senin aradığın sanırım bir yaz hevesi, Prag’da bir cafe’de bir gönül eğlences...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-sonra-vurur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-cahit-pehlivan-xcmbu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllar aldı gitti beni iki gözüm.

Üzüntü, gam, kederle geçti ömrüm.

Kahrolası dünyada neşe ile geçmedi bir günüm.

Sen bilirsin beni, sen bilirsin gonca gülüm.

Ellerin kapısında köle oldum. Yanarım.

Lafım yoktur senin için, bu çileyede katlanırım.

Ağlamam.Göz yaşlarımı içime akıtırım. 

Canım yanar ama; senin için çıkmaz avazım.

Irak yerdesin bilirim, gelemezsin bana,

Bıraksa felek yakamı, geleceğim senin yurduna,

İçli şarkılarımı okuyacağım. Sana gül dalında,

Bekle geleceğim. Mehtaplı bir gecenin ortasında,

Ellerimde bir demet gonca gül ile, bir mendil olacak.

Razıyım, seni görünce hemen oracıkta ölmeye,

Ölürsem gonca gülleri ser tabutumun üzerine,

Göz yaşlarınla ıslattığın mendilini ört üzerime,

Seni gördüm ve seni yaşadım. Yetiyor işte,

Gidiyorum. Senin ellerinde sensiz olan kabrime.

İZMİR', 'Yıllar aldı gitti beni iki gözüm. Üzüntü, gam, kederle geçti ömrüm. Kahrolası dünyada neşe ile geçmedi bir günüm. Sen bilirsin beni, sen bil...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gidiyorum-207-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olursun Gel', 'ne-olursun-gel-cahit-pehlivan-4dwi1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle özledim ki; canım  bir tanem seni,

Ne olursun döngel, döngel bana hadi,

Her gece, sensizliğe akan göz yaşlarım, hep senli,

Seni var diye; her gece göz yaşlarıma sarılıp yatıyorum.

Seni okşayıp seven ellerim, şimdi boşta,

Seni büyük bir sevgiyle, dönüp gelir diye,

Her gece ellerim, yıldızlardan sana ev yapmakta.

Ne olursun bir kerecik vur, çoban yıldızı kapıma

Uyandır. Engin denizlerin mehtaplı gece büyüsüyle,

Sar kollarını boynuma, bakışalım mahmurlu gözlerimizle,

Doyasıya, okşayıp, sarılıp sevişelim birbirimizle,

Yeter ki gel, senin olsun, can evinden çıkmam diyen bu özüm.

Gel, bekletme, ne olursun gel, benim iki gözüm.

İZMİR', 'Öyle özledim ki; canım  bir tanem seni, Ne olursun döngel, döngel bana hadi, Her gece, sensizliğe akan göz yaşlarım, hep senli, Seni var diy...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-olursun-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günü-(Kanlı Güller) ...', 'dogum-gunu-kanli-guller-bahtiyar-arslan-y3hau', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ya ölümü seveceksin

Yada uçurumda gül büyütmeyeceksin.

Uçurumda büyüyen gül, rengini kandan alır...

İşte sırf bu yüzden

Ben hep uçurumda gül büyüttüm

Kanlı güller…

Bugün de  bu gül senindir

İyi ki varsın

İyi ki doğdun

Doğum günün kutlu olsun…', 'Ya ölümü seveceksin Yada uçurumda gül büyütmeyeceksin. Uçurumda büyüyen gül, rengini kandan alır... İşte sırf bu yüzden Ben hep uçurumda gül...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Arslan']::text[], 8.5, '{"poet":"Bahtiyar Arslan","poet_slug":"bahtiyar-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dogum-gunu-kanli-guller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Tanıdım', 'seni-tanidim-cahit-pehlivan-ibvyg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni tanıdım bu gece,

Loş aydınlık ışıklar içinde,

Seni tanıdım bu gece,

Müzikli, neşeli bir alemde,

Sana bakmaktan alamadım gözlerimi,

Nasıl anlatsam, kaşını kirpiğini, 

Dans ederken tuttum ellerini,

Her nefesinde hissettim kalbinin titreyişini,

Keman, çümbüş, saz hepsi kendi aleminde,

Yalnız sen varsın benim gözlerimde,

Aklımda, fikrimde tüm benliğimde,

Senin hayalin kalacak, bir ömür boyu belkide.

ANKARA', 'Seni tanıdım bu gece, Loş aydınlık ışıklar içinde, Seni tanıdım bu gece, Müzikli, neşeli bir alemde, Sana bakmaktan alamadım gözlerimi, Nası...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-tanidim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'soz', 'soz-nazan-i-zmirli-w9llu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'söz; 

gözlerden

dudaklara dökülen

gülümsemendi.......

artık; 

bakışlarını 

saklasan da

mahçupluğunda

hırçınca..............

söz; 

dudaklarına 

dökülen  mutluluğu

kareledim.

gülümsemende

yok ettiğim

gururumun

sonsuzluğuna.......  :)   :)    :)    :)

30.01.2006-antalya', 'söz;  gözlerden dudaklara dökülen gülümsemendi....... artık;  bakışlarını  saklasan da mahçupluğunda hırçınca.............. söz;  dudakların...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/soz-257-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maçın Sonu', 'macin-sonu-cemil-aygen-9fckg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Penaltı diyor hakem

Koy topu beyaz noktaya

İtirazlarındayım

Faul bile yok

Küfürde yok 

Hiçbirşey yok

Hakem bu...Bağırıyor

İtirazda yok 

Bir şans...

Sana diyor

Kaleciye işaret edip

Çekil sen...Penaltıyı yaptıran o...

Geçsin kaleye

Kurtaran da o olsun

Kazağı uzatıyor kaleci

Sırtıma uymuyor...Topa vuracak olan

Gol kralı olmuş

Ona Golcü Kadir...Pardon KADER diyorlar

Bende kaleci yani ÇİLECİ

Gök gürledi,Yağmur yağdı Sel oldu

Maç yarım kaldı

Ve Ben  Çileci Kurtuldu! 

DEĞİL

Ben kalede 

KADERİN Vurduğu top Goldü

Gene yenildik.....', 'Penaltı diyor hakem Koy topu beyaz noktaya İtirazlarındayım Faul bile yok Küfürde yok  Hiçbirşey yok Hakem bu...Bağırıyor İtirazda yok  Bir ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/macin-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz Şiir', 'i-simsiz-siir-mehmet-ali-yuksel-c3uxw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle bir şiir''ki

Güneş kadar sıcak

Buz dağı gibi soğuk

Dünya kadar büyük

Sevgi gibi tatlı

Böyle bir şiir

Dizelerle,

Hecelerle,

Deyimlerle yazılmış bu şiir

Zalimlerin düşman olduğu bir şiir

Oku, oku bitmez

Doğumla başlar

Dünya oldukça o da yaşar

Öyle derler ya

Yaşarda

Kırık kalbiyle

Kanlı kanadıyla

Sürer gider bu şiir

İsimsiz şiir...

     

       4/7/1995', 'Öyle bir şiir''ki Güneş kadar sıcak Buz dağı gibi soğuk Dünya kadar büyük Sevgi gibi tatlı Böyle bir şiir Dizelerle, Hecelerle, Deyimlerle ya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Yüksel']::text[], 8.5, '{"poet":"Mehmet Ali Yüksel","poet_slug":"mehmet-ali-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/isimsiz-siir-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fakir diye', 'fakir-diye-zernisan-aydogan-1m6qh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine kapladi dert beni dertlerin en beteri

Ömür boyu aglamakmis bu fakirin kaderi

Kader yakmis kandilini tutmuyor bana isik

Bu gördügün deli kanli, esmer bir kiza asik

Ask diyorlar adina seven sevilmiyor niye

Esmer kiz istemiyor deli kanli fakir diye.', 'Yine kapladi dert beni dertlerin en beteri Ömür boyu aglamakmis bu fakirin kaderi Kader yakmis kandilini tutmuyor bana isik Bu gördügün deli...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/fakir-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeryüzüne rahmet', 'yeryuzune-rahmet-bahtiyar-tas-dm8nu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen yoktun sultanım 

Hz adem deydi nur önce cenneti

Sonra yeryüzünü şereflendirdi

Adem nuruna af edildi

Arafat bu afa şahitti

Sen yoktun sultanım

Hz ismail deydi nur

Hz ismail seni ahmet diye çağrıştırdı

O ahmet yeryüzüne rahmet diye

Ve sen yoktun sultanım

Kızları diri dirir toprağa gömek vardı

Annelerin çaresizliği vardı

Toprağa atılan kız çocuğunu ağlamasıydı onu kahreden

Sen vardın sultanım

Ama bir inişin vardı yeryüzüne 

Bir rahmetin vardı

Hira nur dağı senin için süsleniyordu

Ve artık islamiyet yayılmıştı

Senin bir gidişin vardı resulum

Bir gidişin vardı ente resululah

Bilalin çaresizliği vardı 

ALLAH HERKESİ SENİN NURUNA AF ETSİN', 'Sen yoktun sultanım  Hz adem deydi nur önce cenneti Sonra yeryüzünü şereflendirdi Adem nuruna af edildi Arafat bu afa şahitti Sen yoktun sul...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Taş']::text[], 8.5, '{"poet":"Bahtiyar Taş","poet_slug":"bahtiyar-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yeryuzune-rahmet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alimül cühelâ', 'alimul-cuhel-ali-riza-unal-u09pe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hak erenden utanmaz,hali okur kaal eyler,

kulu bilmez peygamberden öte,Allah kesilir,

kıçına bir çivi soksan,feryadı figan zâl eyler,

Bu da kahrı sıfattan,gafleti zat kesilir, :) 

Vehmi zanı put olmuş,bi haber nefsi ilâh,

taklidi hallac müteşair,bir badeye ar kesilir,

bir dilim peynire kâhya,mandırayı alâ,

Aczi bitap ukalâ ifrit,marifeti zat  kesilir :)', 'Hak erenden utanmaz,hali okur kaal eyler, kulu bilmez peygamberden öte,Allah kesilir, kıçına bir çivi soksan,feryadı figan zâl eyler, Bu da ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/alimul-cuhela-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolan umutlar', 'kaybolan-umutlar-zernisan-aydogan-ztiys', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hoyrat gecelere seni anlatıyorum

Seni anlatıyorum kaldırım taşlarına

Ansızın uyanıp gece yarıları

Adını yazıyorum buğu tutmuş camlara

Yaşamım öylesine güzeldi ki seninle

Aydınlanırdı tüm karanlıklar

Umutlarla doluydu yüreğim

Gözümde büyümüyordu yarınlar

Oysa şimdi görsen dalıp dalıp gidiyorum

Düşünüyorum ben neyim kimim diye

Yüreğimde solan umutlarımı bir bir

Çisil çisil ıslattım tekrar yeşersin diye', 'Hoyrat gecelere seni anlatıyorum Seni anlatıyorum kaldırım taşlarına Ansızın uyanıp gece yarıları Adını yazıyorum buğu tutmuş camlara Yaşamı...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kaybolan-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayattan Bir Gün', 'hayattan-bir-gun-cemil-aygen-h6u28', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin bir saati

Kalktım..İçimde bir tedirginlik 

Kapım açık kalmış

Kim gelecekti ki

Hani anahtarını unutup

Gelecek birisi mi var

Seni hatırlayan

Anahtarı olan

Köylükteyiz

Köpek sesleri

Serin hava

Dağ başında Ev

Açık kapı

Anahtarsız

Yapayalnız geçen seneler

Ve zamanlardan

Gecenin bir saati

Kafayı yemişiz

Ya da Kader akıl edip

''Akılsız Benimle'' 

Hep kafa yapıyor

Senelerdir bu böyle

Değişmiyor...', 'Gecenin bir saati Kalktım..İçimde bir tedirginlik  Kapım açık kalmış Kim gelecekti ki Hani anahtarını unutup Gelecek birisi mi var Seni hatı...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hayattan-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşıyorum', 'yasiyorum-ahmet-unal-cam-hr9mt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşıyorum   28-01-2006

Mutluluk uzak

  hep uzaktan bakıyorum

  şiirlere şarkılara

  tutunarak yaşıyorum.', 'Yaşıyorum   28-01-2006 Mutluluk uzak   hep uzaktan bakıyorum   şiirlere şarkılara   tutunarak yaşıyorum....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yasiyorum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak İstiyorum', 'yasamak-i-stiyorum-mehmet-ali-yuksel-1tjgt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamak istiyorum

Gezmeyi,

Görmeyi ve tanımayı

İnsanlarla içiçe yaşamayı

Sevmek istiyorum

Özgürce dokunmayı

El ele

Hayatı tatmayı

Anlamak istiyorum

Dertleri,

Olayları, acıları

Gülmeyi ve ağlamayı

Sarılmak istiyorum

Sevdanın yollarına

Gönlümce,

Doyasıyla eğlenmeyi

            2/5/1991', 'Yaşamak istiyorum Gezmeyi, Görmeyi ve tanımayı İnsanlarla içiçe yaşamayı Sevmek istiyorum Özgürce dokunmayı El ele Hayatı tatmayı Anlamak is...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Yüksel']::text[], 8.5, '{"poet":"Mehmet Ali Yüksel","poet_slug":"mehmet-ali-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasamak-istiyorum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-ahmet-unal-cam-rtziz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'GİDİYORUM  28-01-2006 22:31

Gidiyorum,

          taşan nehirler var içimde

Gidiyorum

         gözlerimde yaş,

     adımlarımda telaş,

                          fırtınalar içinde

Bakıyorum geriye,

  bir ömür, 

  bir ömür geçmiş

Nice, nice mutluluk

  ben beklerken 

                    gitmiş

Mazi torbam boş

   umutlarım tükenmiş

         bırakıp sizi size

                      gidiyorum.

Bir sisin içindeyim,

        yürüdükçe yürüdükçe

               kahırlara gidiyorum

 anlıyorum,

 büyüdükçe

            adım adım bitiyorum.

   fırtına olamadan daha

meltem gibi sessizce

gidiyorum, gidiyorum...', 'GİDİYORUM  28-01-2006 22:31 Gidiyorum,           taşan nehirler var içimde Gidiyorum          gözlerimde yaş,      adımlarımda telaş,       ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gidiyorum-208-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mapus daminda tesbih', 'mapus-daminda-tesbih-bilal-toy-pyi3h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne kanun halden anlar 

Nede binlere mekan olmus su dort duvar

Bir sen anlardin beni 

Birde ozgurlugun simgesi ruzgar

Ruzgara gecit vermiyor dort duvar..

Sen yoksun...

Ve sadece elimde yar namina bir tesbihim var

Hey gidi sari kehribar

Dilimden bi o anlar

Her habbesi bir asir

Her habbesi bin sir tasir

iste ipe dizilmis otuz uc nefer

Elimden kayiyor birer birer

Baslarinda imame 

Hepsi mahkum idama', 'Ne kanun halden anlar  Nede binlere mekan olmus su dort duvar Bir sen anlardin beni  Birde ozgurlugun simgesi ruzgar Ruzgara gecit vermiyor ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Toy']::text[], 8.5, '{"poet":"Bilal Toy","poet_slug":"bilal-toy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mapus-daminda-tesbih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızı...', 'sizi-hasan-esat-heptunali-6ml07', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sızlıyorum

Sızlıyorsun

Anlayacağın sızlıyoruz

Belki de…

İlk kez …

Bu kadar güzel anlaşıyoruz..', 'Sızlıyorum Sızlıyorsun Anlayacağın sızlıyoruz Belki de… İlk kez … Bu kadar güzel anlaşıyoruz.....', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sizi-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşıyormuş 28-01-2006 18:20', 'yasiyormus-28-01-2006-18-20-ahmet-unal-cam-9ojt9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kapalıymış 

hala perdeleri

hüzün içiyor, 

dert yiyormuş 

     geceleri

Bu da geçer,

 sen aldırma be

babam canım babam

  İsmail Çam

Söyler oğlun,

 söyler bir gün 

 mutluluk türküleri.

Yaşadıkça ümitli ol.

Cebinde bir kağıt,

 bir kalem elinde

ve gönlünde gam...

Yaşıyormuş, duydum

Ahmet Ünal Çam.

Not: ''Yagmur Yagıyordu'' hikayesi 28. bölüm için yazılmış şiir

http://www.geocities.com/yagmuroyku/28.htm', 'Kapalıymış  hala perdeleri hüzün içiyor,  dert yiyormuş       geceleri Bu da geçer,  sen aldırma be babam canım babam   İsmail Çam Söyler oğ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yasiyormus-28-01-2006-18-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi kendime', 'kendi-kendime-ahmet-unal-cam-go9vv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bulamadım da

 saatlerce sordum seni

 saatlerce kendime

Türküler söyledim

 söyledim sevdiğimi

Senden uzak, sessizce.

Ne ellerin vardı

  ellerimde

Ne yalan gözlerin

  gözlerimde.

Seni aradım, 

  seni sordum

Saatlerce kendime

Sana söyleyemediklerim

  geçti aklımdan.

    katar katar.

ve gözlerimde 

 hayalin uzaklaşırken

 bir tren penceresinde

Dolaştım,

 dolaştığın yerlerde

Mağlup komutan gibi,

         cephe cephe

Pişmanlıklarla

 sitemler ettim,

 kızdım, kendi kendime

Aradım seni

 tren tren, vagon vagon

Ayak izlerimle doldu

Çankırı’da istasyon.

Yine döndüm evime

Senden iz bulamadan

Ağladım yine her gece

Not: ''Yagmur Yagıyordu'' hikayesi 27. bölüm için yazılmış şiir

http://www.geocities.com/yagmuroyku', 'Bulamadım da  saatlerce sordum seni  saatlerce kendime Türküler söyledim  söyledim sevdiğimi Senden uzak, sessizce. Ne ellerin vardı   eller...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kendi-kendime-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanet Olsun', 'lanet-olsun-mesut-ozturk-lickt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hakkım varsa sana haramdır.

Acıyan şey yüreğimdeki yaramdır.

Senin sevgin baştan sona yalandır.

Adi olan sende tamah bulandır! 

Merhametin olsa yavrun ağlamaz.

Adaletin olsa oğlun sızlanmaz.

Yaptıkların insanları zaten bağlamaz.

Namert olmak hakkın, mertlik yakışmaz! 

Saygıların en büyüğünü sana gösterdim,

Evlatlarının vermediğini, ben sana verdim,

İki yüzlü olduğuna ben, üzülendim,

Karakterin buymuş senin, lanet olsun! 

Bu yaşında kukla gibi maşa olan sen,

Yalanla dolanla avunan yine sen,

Emanete kıyan ihanet eden sen,

Boyuna posuna yazıklar olsun! 

Selamın alınmaz, hatrın sorulmaz,

Senin gibi menfaatci insan olunmaz,

Senden daha iyi kalleş bulunmaz,

Üç kuruşluk şerefine yazıklar olsun!', 'Hakkım varsa sana haramdır. Acıyan şey yüreğimdeki yaramdır. Senin sevgin baştan sona yalandır. Adi olan sende tamah bulandır!  Merhametin o...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/lanet-olsun-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar 28-01-2006', 'ruzgar-28-01-2006-ahmet-unal-cam-ldkym', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir acı aşk hikayesi

 anlatır gibi rüzğar

ağaçlardan gönlüme

süzülür gibi rüzgar.

Alır götürür beni

dağlardan ovalara

Kâh unutturur derdimi

Kâh düşürür ahlara

Savruldukça saçlarım

peşimdedir, anlarım.

Her an adım adım

hüzünleriyle rüzgar

Saklansam da köşe bucak

bilirim, hemen bulacak

beni benden alıp ta

Hazanlara atacak.', 'Bir acı aşk hikayesi  anlatır gibi rüzğar ağaçlardan gönlüme süzülür gibi rüzgar. Alır götürür beni dağlardan ovalara Kâh unutturur derdimi ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruzgar-28-01-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-zernisan-aydogan-5n3sp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen ögrettin bana sevgiyi

Gerçek arkadasligi dostum

Iyi ve güzel olan seylere 

Veda etmisken

Tekrar sen döndürdün yasama beni

Mutsuzluk denizinde boguluyorum diye

Yükselen feryadimi da duyan ilk sen oldun

Dostluga uzanan ellerimi tutan

Simsicak sevgisiyle buz tutan yüregimi isitan

Yine sen oldun dostum

Simdi gecelere siginmiyorum 

Yanlizligimdan da yakinmiyorum

En ümitsiz oldugum anlarda

Senin sözlerini  hatirliyorum

Içime bir sevinç doluyor dostum', 'Sen ögrettin bana sevgiyi Gerçek arkadasligi dostum Iyi ve güzel olan seylere  Veda etmisken Tekrar sen döndürdün yasama beni Mutsuzluk deni...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dostum-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevenin gözlerine yürü', 'sevenin-gozlerine-yuru-mehmet-ali-yuksel-tyujn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kanma sevgilim

Uzakta değilim

Yakınında

Kendinde ara

Bulursun.

Unutma sevgilim

Gözyaşlarını döktüğün yerde

Mehtaba bakarken hatırla

Uzakta değilim

Yüreğinde.

Hatırla sevgilim

Geçmişini anılara bırakma

Sevdanın tutarı ile ol

Sevenin gözlerine yürü

Kucaklasın.

    20/10/1992', 'Kanma sevgilim Uzakta değilim Yakınında Kendinde ara Bulursun. Unutma sevgilim Gözyaşlarını döktüğün yerde Mehtaba bakarken hatırla Uzakta d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Yüksel']::text[], 8.5, '{"poet":"Mehmet Ali Yüksel","poet_slug":"mehmet-ali-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevenin-gozlerine-yuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dosta Ağıt', 'bir-dosta-agit-doner-ozeke-5ngzz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hastaneye yattım kapı kar iken 

Balkona çıktım ki çimler yeşermiş 

Benim emsallerim giyip kuşanmış 

Ben bu dertten kurtulamam ölürüm 

Hastaneye vardım verem dediler 

Annem babam görüşüme geldiler 

Gidip de hekime sordum derdimi 

Yavrum sen bu dertten ölün dediler 

Doktorun kolunda altından saat 

Masamda ekmekler üç günlük bayat

Hastane köşesinde geçmiyor hayat 

Ben bu dertten kurtulamam ölürüm 

Hastaneye yatırdılar garip Türkan 

Üstüne örttüler yeşil ipek yorganı 

Ben bu dertten kurtulurda kalkarsam 

Yavrularım kessinler çifte kurbanı 

Akşam olur hastanenin kapıları kitlenir 

Hastalar da birbirleriyle dertlenir 

Bunu da deyimde duyun ahbaplar 

Gariplerin cenazesi kokar kurtlanır 

            DÖNER ÖZEKE 

                31.01.2006', 'Hastaneye yattım kapı kar iken  Balkona çıktım ki çimler yeşermiş  Benim emsallerim giyip kuşanmış  Ben bu dertten kurtulamam ölürüm  Hastan...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-dosta-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmeyene-2', 'bilinmeyene-2-nuri-kucuk-jjprx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adın ne biliyormuyum,

Sen kimsin? 

Ben kimim? burası neresi? 

Zaman kaç? 

Sorular sarhoşluğunda dönerken dünya,ışık misali sen.

İsmini bilmediğim.

Yalnızca sevebileceğim.

Sevgiler bile bahane olmuşken,

Gelmiş bulunduğum şu kara delik dünyaya,

Yoruldukça yorulduğum yelkovan akrep kovalamacası.

Şehrin ışıkları yanarken,

Mevsimler birbiri ardına geçerken,

Yıldızlar bile tozlanmışken,hatılar gibi...

Gençliğim gibi...

Henüz yeni başlamışken sokak kavgalarımız,

Henüz daha ilk arkadaşım ihanet etmişken,

Henüz daha hayata ve sana küsmemişken...

Şimdi sigaralar var ceplerimde.

Şimdi tütün kokuyor,saçlarını okşadığım parmaklarım.

Şimdi yok ağlamalarım,yersiz nefes alamayışlarım.

Ve geceleri ismini sayıklayışlarım.

Nedenini ve niçinini bilemdiğim bu terkedişin,

Kan davası misali...

Ve fırat kadar,kızılırmak kadar soğuk...

Nerede olduğunu merak etmeyişim.

Şiirlerimizi yakıp keyifle seyredişim.

Kapatıp kapılarımı bir daha açmayışım.

Resimlerini yırtıp,hayatıma dair ne var ne yoksa tavan arasına kaldırışım.

Haa...

Birde habersiz giderken,sapladığın kara saplı bıçak var tabi...

Sana dair tek onu sakladım işte.

Yeni aşklarını sırtından vurayım diye...

Neden yalnızsın? 

Neden kimse yok hayatında? 

Hani sen aydın? 

Hemde hiç tutulmayan? 

Önüne bulutu bile koymayan.

Oysa bak haftalardır ay falan yok gökyüzünde.

Kara bulutlar var hayatında.

Kapkara...

Ve kan kırmızı yağmurların var.

Avuçlarına avuçlarına yağan...

Dün bir resim aldım.

Odamın duvarına asmak için.

Seninkileri söktüğüm yere.

O kadar güzelki...

Rengarenk gözleri var resmin...

Yemyeşil...

Hayata bağlarcasına.

Sanki aşkın tarifi.

Tabiat misali geniş.

Ve bir o kadar derin.

Şimdi aklım fikrim o.

Aklım fikrim.

Ne akrep ne yelkovan.

Zaman yok odamda.

Hayatımda.

Sende yoksun artık.

Terazinin kefesine bile koymuyorum seni.

Çünkü onun sadece gözleri senin hayatından ağır gelir.

Bidaha,bidaha geriye dönermiyim dersin? 

Aslamı? 

Doğru bildin.

Asla.

Sen ve seni alıp gitmişken hayatımdan,

Ve hayatımı bulmuşken ben,

Lanetolası hayatında iyi yaşa! ! ! 

Haa...

Sen,yeşil gözlü...

Sen mi? 

Seni seviyorum ya yetmez mi? 

Tepeden tırnağa sevmek bu.

Bu sefer o dikeni bir ömür tutarım gül uğruna.

Senin uğruna...

Sen,sen o kadar güzelsinki...

Boşuna bekleme...

Şiirlerin ömrü yetmez seni anlatmaya.

Benim ömrüm yetmez seni sevmeye...

Şu kadarını bilki...

                                           HULYAMSIN...', 'Adın ne biliyormuyum, Sen kimsin?  Ben kimim? burası neresi?  Zaman kaç?  Sorular sarhoşluğunda dönerken dünya,ışık misali sen. İsmini bilme...', ARRAY['Türk Edebiyatı','Şiir','Nuri Küçük']::text[], 8.5, '{"poet":"Nuri Küçük","poet_slug":"nuri-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/bilinmeyene-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeryüzünün alemi', 'yeryuzunun-alemi-bahtiyar-tas-0wtea', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen yoktun sultanım

Hz ademdeydi nur 

Önce cenneti sonra yeryüzünü şereflendirdi

Adem nuruna af edildi

Arafat bu afa şahitti

Sen yoktun sultanım

Hz ismail deydi nur

Hz ismail seni ahmet diye çağrıştırdı

O ahmet yeryüzüne rahmet diye

Sen yokken sultanım kız çocuklarını

Diri diri toprağa gömek vardı

Annelerin çaresizliği vardı

Ve sen geldin sultanım

Bir inişin vardı yeryüzüne 

Bir rahmettin...

İslamiyetti yaymıştın 

Amin demişti 18 bin alem 

Amin diyerek inlemişti mekke

Sen yoktun sultanım

Mekke kardı hendek yardı uhud dardı

ALLAH HERKESİ SENİN NURUNA AF ETSİN', 'Sen yoktun sultanım Hz ademdeydi nur  Önce cenneti sonra yeryüzünü şereflendirdi Adem nuruna af edildi Arafat bu afa şahitti Sen yoktun sult...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Taş']::text[], 8.5, '{"poet":"Bahtiyar Taş","poet_slug":"bahtiyar-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yeryuzunun-alemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat pahalılığı', 'hayat-pahaliligi-zernisan-aydogan-eubbs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gurbette kalmışım anamdan ayrı

Mektup alamadım yüreğim gamlı

Hasret ağırlaştı yiğitsen taşı

Hayat pahalılığı yaktı canımı

Genç yaşta benimiz benzimiz soldu

Belimizi büken hep yokluk oldu

Ana baba görmek mucize oldu

Hayat pahalılığı yaktı canımı

Memurun ayakta duramaz oldu

Sınavı kazanınca neler ummuştu

En büyük tokatı büyükler vurdu

Hayat pahalılığı yaktı canımı', 'Gurbette kalmışım anamdan ayrı Mektup alamadım yüreğim gamlı Hasret ağırlaştı yiğitsen taşı Hayat pahalılığı yaktı canımı Genç yaşta benimiz...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-pahaliligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşırı Doz', 'asiri-doz-murat-polat-2-yih1a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine ayarlayamadım dozajımı! 

Yarardan çok verdim zararı.

Hiç bir bünye kaldırmıyor

Her seferinde yan etki tekrarı.

Dostluğunda hep fazlası

Aşkların en hummalısı

Yok ki gönlümün ayarı

Kaçırıyor elbet normal insanı.

Herkes herkesten korkar olmuş

Kimsenin kalmamış kimseye güveni

Ben mi zamanın gerisinde kaldım? 

Yoksa benim için zaman mı durdu? 

                                 

                                  30 Ocak 2006', 'Yine ayarlayamadım dozajımı!  Yarardan çok verdim zararı. Hiç bir bünye kaldırmıyor Her seferinde yan etki tekrarı. Dostluğunda hep fazlası ...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/asiri-doz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz Olsaydın!', 'olmaz-olsaydin-mesut-ozturk-wid4g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aslında ben seni sevemedim,

Yakınlık gösterdin hiç güvenmedim,

yaptıklarını zaten beğenmedim,

Sen benim akrabam olmaz olsaydın! 

Beni babam sana emanet etti, 

İki yüzlülüğün beni kahretti,

Haksızlığın dizboyu canıma yetti,

Sen benim akrabam olmaz olsaydın! 

Başa kalkmak için verirsin,

Orda olmayanı satıp, çiy çiy yersin,

Sonra oturur, ben ne yaptım ki? Dersin.

Keşke aynı kandan olmasaydın! 

Allah`ını bilen saygısız olmaz,

Nedense imanın yok? Gözün hiç doymaz,

Vicdanı olan başkasına kıymaz,

Sen benim akrabam olmaz olsaydın! 

Yalancılık adın olmuş, inkar soyadın,

Bozacaktın bizleri neden aldın? 

Allah`ım adaletli, bak, yanlız kaldın.

Keşke benim yakınım olmasaydın!', 'Aslında ben seni sevemedim, Yakınlık gösterdin hiç güvenmedim, yaptıklarını zaten beğenmedim, Sen benim akrabam olmaz olsaydın!  Beni babam ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olmaz-olsaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çünkü Bunu Bilmedin', 'cunku-bunu-bilmedin-yusuf-onder-bahceci-6ieg2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilsem seni severmiydim,

Sana gönül verirmiydim,

Senin için ölürmüydüm,

Çünkü bunu bilmedin.

Bilsem harap olurmuydum,

Bilsem serap olurmuydun,

Bilsem seni görürmüydüm,

Çünkü bunu bilmedin.

Bilsem seni sorarmıydım,

Rüya görüp yorarmıydım,

Bilsem seni bulurmuydum,

Çünkü bunu bilmedin.

Bilsem seni bırakmazdım,

Bilsem sana kızamazdım,

Bilsem yola bakmazdım,

Çünkü bunu bilmedin....', 'Bilsem seni severmiydim, Sana gönül verirmiydim, Senin için ölürmüydüm, Çünkü bunu bilmedin. Bilsem harap olurmuydum, Bilsem serap olurmuydu...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cunku-bunu-bilmedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatalılar', 'hatalilar-sair-pinki-zsl17', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hissettiremedim

Hissedemedin

Ortada suçlu arama

Suçlu yok

Suçlanan yok

Hata var 

Hatalı var

Hatalıyım, hatalısın

HATALILAR', 'Hissettiremedim Hissedemedin Ortada suçlu arama Suçlu yok Suçlanan yok Hata var  Hatalı var Hatalıyım, hatalısın HATALILAR...', ARRAY['Türk Edebiyatı','Şiir','Şair Pinki']::text[], 8.5, '{"poet":"Şair Pinki","poet_slug":"sair-pinki","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hatalilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok özledi onu gönül', 'cok-ozledi-onu-gonul-omer-ay-rwat1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzgar gibi geçen yıllar

Durun desem dururmola

Yar hasreti çeken kalpler

Yana yana erirmola

Yıldızlara bakan dağlar

Deryalara akan sular

Gurbette kalan garipler

Yardan selam alırmola

Çilelerle geçen ömür

O yarin gözleri kömür

Çok özledi onu gönül

Gurbet elden dönermola', 'Rüzgar gibi geçen yıllar Durun desem dururmola Yar hasreti çeken kalpler Yana yana erirmola Yıldızlara bakan dağlar Deryalara akan sular Gur...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ay']::text[], 8.5, '{"poet":"Ömer Ay","poet_slug":"omer-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cok-ozledi-onu-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-fatma-guven-e0i2i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilinmeyen zamandan gelen,

Bilinç,beyin,ses,

En küçük hücrene kadar,

Saran atmosfer,

Sevgi enerjisini üreten yüreğim.

Uzat ellerini ellerime,

Umutlarımı sana vereyim.

Çarmıha gerilen İsa gibi,

Kin,nefret,öfke,korku,

Zaaf,alışkanlık,çıkar,riya çivisiyle,

Çivilendik insanlığın çarmıhına.

Bu acıdan,

Kurtulamam tek başıma.

Seninle güçlenir,

Sevgiyle varolurum.

Dost ellerini uzat bana.', 'Bilinmeyen zamandan gelen, Bilinç,beyin,ses, En küçük hücrene kadar, Saran atmosfer, Sevgi enerjisini üreten yüreğim. Uzat ellerini ellerime...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dost-132-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerim', 'askerim-doner-ozeke-cunkh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Askerim gittiğin güçük boğazı 

Yarim gideriken yemiş ayazı 

Koyver devlet baba yarimi koyver 

Bize de nasip olsun bayram namazı 

Yarimin gittiği ayğırın dağı 

Kındaptan oluyor potinin bağı 

Hızla geçip giden bu gençlik çağı 

Aslan yarim teskereni alda gel 

Kakülü arnında düzgün yarimin 

Hayatı yaşamı bezgin yarimin 

Başında Subayı azgın yarimin 

Aslan yarim teskereni alda gel 

Pusuda dalıpda sigara yakma 

Sakın yarim sakın arkana bakma 

Düşmanların kalleş gaflete dalma 

Aslan yarim teskereni alda gel 

       

      DÖNER TEMÜR 

         31.01.2006

           ANKARA', 'Askerim gittiğin güçük boğazı  Yarim gideriken yemiş ayazı  Koyver devlet baba yarimi koyver  Bize de nasip olsun bayram namazı  Yarimin git...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/askerim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Geldi, Sen Yoksun', 'eylul-geldi-sen-yoksun-ahmet-unal-cam-92tk7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlamıyorsun

Sen yokken

  bir parçam eksik daima

Sevincim, öfkem bile yarım

Ne hırçınlığımı dindiren, sözlerin

Ne hüzünlerimi bitiren gülüşün

Yoksun

Yoksun işte...

İnanmak istemesem de! ..

   *        *       *       *

Eylül sensiz başlıyor

Bilirsin; kolay hüzünlenir,

  kolay ağlarım

Eylülde sonbahar gasveti

  elimi,kolumu kıran yalnızlık.

Mevsim hüzün, yediğim-içtiğim hüzün

Sonbahar.. sonbahar.. sonbahar

Ayrılık...', 'Anlamıyorsun Sen yokken   bir parçam eksik daima Sevincim, öfkem bile yarım Ne hırçınlığımı dindiren, sözlerin Ne hüzünlerimi bitiren gülüşü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/eylul-geldi-sen-yoksun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Aşk Yolunda Tek Yoldaşımsın', 'sen-ask-yolunda-tek-yoldasimsin-kamil-soylemez-nybet', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen aşk yolumda tek yoldaşımsın

Akşamdan sabaha deil şu yanışım

Ömrüm sonudur,sensiz kalışım

Yok olurum bile,bile yok olurum sana

Özümde sen gerçek göz yaşımsın

Sen ki ruhumun tek sırdaşısın

Ölümüm baş,göz tek atışımsın

Yok olurum bile,bile sana yok olurum

Düşerken tutunduğum tek aşkımsın

Sevdanla gece,gündüz ağlayışımsın

Bu canı sen yakıp,tutuşturanımsın

Yok olurum bile,bile sana yok olurum

Sen gidersen bilirim ki ben ölürüm

Ömrümü virane eder,güllerim soldururum

Hasretin rüzgarıyle savrulurda külüm

Yok olurum bile,bile sana yok olurum', 'Sen aşk yolumda tek yoldaşımsın Akşamdan sabaha deil şu yanışım Ömrüm sonudur,sensiz kalışım Yok olurum bile,bile yok olurum sana Özümde sen...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-ask-yolunda-tek-yoldasimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış Bilmeyin Beni', 'yanlis-bilmeyin-beni-ahmet-unal-cam-t06w5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanlış bilmeyin beni

  mahçup biriyim diye,

  ben de sevdim

    hem de delicesine.

Bir bakışla bile

  yüreğimin hopladığı,çok oldu.

Yanlış bilmeyin beni

  sevdim bazen,yüzü güzel

    yüreği çirkin birini.

Bazen,hem yüzü,hem de

  yüreği güzeli sevdim,

 ...söyleyemedim.

Yanlış bilmeyin beni

  sevildim de,

    imzasız mektup aldım,

    içimde gizli bir sızı kalsa da

    sevindim sevildiğime

  bir mektup arkadaşı da

    sevdi beni.

  ama hiç kimse,

  ilk görüşte sevmedi...sevemezde.

Yanlış bilmeyin beni

  şarkılarla ağladığım oldu

 ...ölümü düşündüm çare diye

  güldüğüm oldu,ağlayışıma.

  sevmeden yaşadığım gün ise

    olmadı.

Yanlış bilmeyin beni

  ''yar''diye sevenim azsa da

  ''dost''diye sevenim çok oldu.

  dert anlatmaktan çok dert dinledim

  çok kez umutsuzken,umut verdim,

  içim ağlarken,gülümsedim.

Yanlış bilmeyin beni

  güldüm,eğlendim de

  eller gibi olmasa da

    kahkaha atmışımdır,belki de...', 'Yanlış bilmeyin beni   mahçup biriyim diye,   ben de sevdim     hem de delicesine. Bir bakışla bile   yüreğimin hopladığı,çok oldu. Yanlış b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yanlis-bilmeyin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbinde beni', 'kalbinde-beni-seckin-eren-1o6tv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kalbinde beni

dudaklarında sesimi

yalnızlıkta seni

ararım gülüm', 'kalbinde beni dudaklarında sesimi yalnızlıkta seni ararım gülüm...', ARRAY['Türk Edebiyatı','Şiir','Seckin Eren']::text[], 8.5, '{"poet":"Seckin Eren","poet_slug":"seckin-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kalbinde-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 46', 'guncel-beyitler-46-huseyin-avdic-gadb2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mirac''a Cikmak Istersen

Iyilige ermek istersen, sevdiginden ver muhtaca.

Adi, bayagi $eyler vererek, cikamazsin Mirac''a.

Berlin, Ocak 2006.', 'Mirac''a Cikmak Istersen Iyilige ermek istersen, sevdiginden ver muhtaca. Adi, bayagi $eyler vererek, cikamazsin Mirac''a. Berlin, Ocak 2006....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'IHLAMUR KOKULU KAR TANESi', 'ihlamur-kokulu-kar-tanesi-olgun-ekinci-1j3zy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '*****Yine ve hep Sana*****

Yanaklarına değmeye gün sayıyorum

Amonyaklarından arınmış 

Toprağa düşmeye direnen,

Kar tanesiyim ıhlamur kokulu..

Temmuz''un sıcağı

Kazma''lar yaktıran Mart

Mevsimler döngü''ler değil

Y a ğ a m a m ı ş l ı ğ ı m..

Kimliksiz, kimsesiz 

Sahipsiz mektuplar…ve

Sokak numarası olmayan

Adressiz yerlere değil

Y a ğ m a y ı ş ı m..

Öyle bir havada

Öyle bir güneşte

Kristalize ve lapa lapa

Düşeceğim ki yanağına,

Ihlamur kokuları yayılacak dokuna

Üşümüş kelebeklerin 

Sıcak yer arayışındaki hüzzam 

Hüzün gözlerinde nem olacağım.

Damla damla akacağım yüreğine

Orada yeniden doğuşum

Sana gelişimin alfabedeki ilk harfi

Kitabımın son sözü olacak.

G e l e c e ğ i m..

Yeminim var sevdama dair

Yeminimiz var s e v d a m ı z a dair…

27.01.2005  Adana', '*****Yine ve hep Sana***** Yanaklarına değmeye gün sayıyorum Amonyaklarından arınmış  Toprağa düşmeye direnen, Kar tanesiyim ıhlamur kokulu....', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ihlamur-kokulu-kar-tanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Ağa''ya Ağıt (Babam''a Ağıt)', 'son-aga-ya-agit-babam-a-agit-necati-dikmen-o353y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir dağ idin, kar tükenmez başında.

Yetim düştün daha iki yaşında.

Baba oldun fukaraya garibe,

Tuzun vardır onların her aşında

Temizliğin elâleme örnekti

Sözün sav''ın çaresize köynekti,

Vermedin taviz dimdik yaşadın.

Arzun hep bizi mutlu görmekti.

İyiyi öğrettin her zaman bize.

Dönüyor insan sonunda öze,

Neyimiz var ise maddi manevi

Mustafa Bey''den kalmıştır bize.

(İstanbul, 30.12.2005)', 'Bir dağ idin, kar tükenmez başında. Yetim düştün daha iki yaşında. Baba oldun fukaraya garibe, Tuzun vardır onların her aşında Temizliğin el...', ARRAY['Türk Edebiyatı','Şiir','Necati Dikmen']::text[], 8.5, '{"poet":"Necati Dikmen","poet_slug":"necati-dikmen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-aga-ya-agit-babam-a-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akraba Dediğin Akrepler', 'akraba-dedigin-akrepler-yusuf-onder-bahceci-zh7le', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acep hovardamı dediler,

Seni benden ettiler,

Bilmem kumarcımı dediler,

Hep günahıma girdiler,

Biliyorum birşeyler dediler,

İşte böyle ettiler,

Şimdi nereye gittiler,

Akraba dediğin akrepler...', 'Acep hovardamı dediler, Seni benden ettiler, Bilmem kumarcımı dediler, Hep günahıma girdiler, Biliyorum birşeyler dediler, İşte böyle ettile...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/akraba-dedigin-akrepler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek Sevincin Olsun', 'olmek-sevincin-olsun-mehmet-ali-yuksel-0yxyx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyan içimdeki sır

Çık dışarı şan şakrak

Dağıl dünyaya

Bir deniz gibi ol

Sevgiye hasrete doy

Gökkuşağı gibi

Işıldar, aydınlık ve renkli

Mavinin simgesi ol

Korkma yürü

Zalimin üstüne

Ölmek sevincin olsun

Ebediyen yaşar ol.

            23/01/1993', 'Uyan içimdeki sır Çık dışarı şan şakrak Dağıl dünyaya Bir deniz gibi ol Sevgiye hasrete doy Gökkuşağı gibi Işıldar, aydınlık ve renkli Mavin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Yüksel']::text[], 8.5, '{"poet":"Mehmet Ali Yüksel","poet_slug":"mehmet-ali-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olmek-sevincin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Seni Severim Bahar Gelmese', 'yine-seni-severim-bahar-gelmese-yusuf-onder-bahceci-wem5p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdamın üstüne karlar da yağsa,

Yine seni severim Bahar gelmese,

Yine de yüzüm güler kalbim ağlasa,

Yine seni severim Bahar gelmese.

Sen beni sevdin mi nerden bileyim,

Ben seni sevmişim hemen söyleyim,

Uğruma ölürmüsün de hemen öleyim,

Yine seni severim Bahar gelmese.

Bir gün bir camiden salam verilir,

Hoca acep ne der, nasıl seslenir,

Ey ahali duyun duyun nasıl sevilir,

Yine seni severim Bahar gelmese.', 'Sevdamın üstüne karlar da yağsa, Yine seni severim Bahar gelmese, Yine de yüzüm güler kalbim ağlasa, Yine seni severim Bahar gelmese. Sen be...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yine-seni-severim-bahar-gelmese-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alın Tanrılar Bu Canımı Sevgisiz Yaşayamam', 'alin-tanrilar-bu-canimi-sevgisiz-yasayamam-kamil-soylemez-30p7o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaç kez baktı sevdam

Kaç kez cep telefonuna

Aradımı diye beni aceba

Ben kaç kez baktım

Kaç kez yandım farkında olmadan

İçin,için hep kanadım

İçin,için ağladım

Kaç kez düşündü

Kaç kez döndü durdu

Kaç kez ev odalarında gel git sürdü

Ben kaç kez gezdim

Anlamsız adımlarda

Neden unuttum evim lavoba düğmesini

Neden di bu kargaşa 

Neden bu kadar dağılma

Sevgi bumuydu aceba

Neden burulup,durdum

Neden üzüldüm

Neydi bu yok olmalar

Sevmek bumuydu

Ölmek bumu

Yaşamak acı çekmekse

Sevmek cehennemi düşsün içime

Dönersem kellem vurulsun

Ben istemem hey tanrılar

Alın bu canı vurun prangalar', 'Kaç kez baktı sevdam Kaç kez cep telefonuna Aradımı diye beni aceba Ben kaç kez baktım Kaç kez yandım farkında olmadan İçin,için hep kanadım...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/alin-tanrilar-bu-canimi-sevgisiz-yasayamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görki Başa Neler Gelir', 'gorki-basa-neler-gelir-yusuf-onder-bahceci-doj09', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzel sevdim derdi ile,

Dağlar, taşlar gelir dile,

Sen Allah''tan sabır dile,

Görki başa neler gelir.', 'Güzel sevdim derdi ile, Dağlar, taşlar gelir dile, Sen Allah''tan sabır dile, Görki başa neler gelir....', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gorki-basa-neler-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muradım Kaldı', 'muradim-kaldi-salim-erben-bqwz7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şeyler eksik bende bunu hissediyorum 

Sol yanımda karıncalama başlıyor

Bir boşluk dayım anlamıyorum

Gözlerimden bir kaç damla yaş

Yanaklarıma süzülüyor buz gibi 

Çoğalıyor nehirden farksız 

Anlamıyorum

 	

Neden baba neden bırakıp gittin

Kim sevdi seni benden fazla

Neden bizi terk ettin baba

Annem beni ne zaman görse 

İki gözü iki çeşme 

Sesimi duysa ağlıyor

Gözükmüyorum ağlamasın diye

Hani küçükken ağlama

Erkekler ağlamaz derdin ya

Ben hiç ağlamıyorum baba

Arada bir gözüm sulanıyor ama 

Varsın sulansın demi baba

Kimse görmüyor ki.

Geceleri sesini duyuyorum 

Cevap veremiyorum 

Sana sarılmak istiyorum 

Sarılamıyorum

Ben seni çok özlüyorum baba

Gelmek istiyorum yanına 

Korkuyor cesaret edemiyorum

Sen görmeyeli 

Torunlarında büyüdü 

Gelinlik çağına geldiler

Hani esra okusun öğretmen olsun 

Köye tayinini yaptırırım derdin ya

Okudu baba 

Esinde bu yıl başlayacak

Annemin saçları beyazladı 

Dişleri döküldü hele ki sağlığı 

İyiden iyiye bozuldu baba

Anlayacağın biz seni çok özlüyoruz 

Baba

  Salım Erben', 'Bir şeyler eksik bende bunu hissediyorum  Sol yanımda karıncalama başlıyor Bir boşluk dayım anlamıyorum Gözlerimden bir kaç damla yaş Yanakl...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/muradim-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavanoz', 'kavanoz-turgay-yildirim-qxxxi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünya’yı hep akvaryuma benzetirdim

Hem de kavanoz dipli akvaryuma

Birilerininde hep bizi seyrettiğini düşlerdim

Ve…………

Her günah işlediğimde

Yukarı bakar

Yüzüm kızarırdı

Ama

Kendimide alıkoyamazdım günah işlemekten..

Zaman geçtikçe

Her yukarı bakışımda gülümsemeye başlamıştım

Neden mi? 

Ar damarım yırtılmış

Seyredilmenin isyanına inat

Tüm çıplaklığımı sunmuştum onlara..

Kendimi…

Prometeusun ateşi 

Herkülün yüküyle

Kavanoz  dipli dünyaya

İnat

01.01.2006

Turgay YILDIRIM', 'Dünya’yı hep akvaryuma benzetirdim Hem de kavanoz dipli akvaryuma Birilerininde hep bizi seyrettiğini düşlerdim Ve………… Her günah işlediğimde...', ARRAY['Türk Edebiyatı','Şiir','Turgay Yıldırım']::text[], 8.5, '{"poet":"Turgay Yıldırım","poet_slug":"turgay-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kavanoz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden?', 'neden-mesut-ozturk-e9tmk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çaresizlik ve boşluk içinde gezerken,

Allah`ım ne olacak bu halim derken? 

Bu Dünya`da birazcıkta umudum varken,

Uygunsuz bir zamanda tanıdım seni! 

Nerden bilecektim hayatİın acı olduğunu,

Dokunduğun çiçeğin bile solduğunu,

Heryerde garibanları bulduğunu,

Hazırlıksız bir anda tanıdım seni! 

Derdime derman olabilirsin dediğinde,

Fakirleri düşünmeden etleri yediğinde,

Yalan yere bana dostluğunu verdiğinde,

Kendimde olmadan tanıdım seni! 

Gerçek yüzün çıkıyor piyasaya,

kendime geldim günleri saya saya,

Bir de baktım ki karşımda sen varsın ya,

Anladım  çok geç, neden tanıdım seni?', 'Çaresizlik ve boşluk içinde gezerken, Allah`ım ne olacak bu halim derken?  Bu Dünya`da birazcıkta umudum varken, Uygunsuz bir zamanda tanıdı...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neden-213-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşırdım Kaldım', 'sasirdim-kaldim-yusuf-onder-bahceci-cgr1u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fazla dürüst olanlara salak diyorlar,

Mayası temiz olanlara yalak diyorlar,

Vatana canım diyene kast ediyorlar,

Şimdi nasıl edeyim, şaşırdım kaldım.

Çok okumuşsan sana solak diyorlar,

Sinema, tiyatro desen entel diyorlar,

Ses sanatcısı olsan dansöz diyorlar,

Şimdi nasıl edeyim, şaşırdım kaldım.

Hep eşşek arısından bal bekliyorlar,

Köpekler kapılarda, hep yal yiyorlar,

Garibanlar cân verse para diyorlar,

Şimdi nasıl edeyim, şaşırdım kaldım.

Şiirler yazanları hep zemmediyorlar,

Hep kendilerini iyi, iyi zannediyorlar,

Hepsi de haram yiyor, haram yiyorlar,

Şimdi nasıl edeyim, şaşırdım kaldım.', 'Fazla dürüst olanlara salak diyorlar, Mayası temiz olanlara yalak diyorlar, Vatana canım diyene kast ediyorlar, Şimdi nasıl edeyim, şaşırdım...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sasirdim-kaldim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanırım Sizi', 'tanirim-sizi-durmus-kaya-d9d8g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'TANIRIM SİZİ

  -Anamın, sarı gül sarışlı ellerini öperken...

Tanırım sizi

Yüreğim kadar  sıcak dillerinizden

Nasırı mor süsen açan

Sarı gül  sarışlı ellerinizden tanırım! 

Kanımda tutuşan bir harlı çerağdır

Bakışlarınızla gönlüme  verdikleriniz

Ve hep karlı dağdır 

Önüme serdikleriniz! 

Adınıza türkü yaksam

Mızrabım kırılır

Kopuzum yanar

Şiir yazsam gökte ay’ım

Yıldızım yanar! 

Beni gül dibinde doğuran

Ve gül yağmuruyla yoğuran

Sizden biri! 

………………………………………………………….

Tanırım sizi

Şahdamarımda gezer

İçimde solursunuz

Şu biçare dünyama

Nur şehri olursunuz! 

Tanırım sizi

Bilirim çileniz yüce dağlardan yüce

Bilirim ya derdinize derman olamam

Benim de gam çiçekleri açar baharım

Benim de önüm ardım çile

Sağım solum hasret

Benim de her şeyim yarım! 

Tanırım sizi

Ebem kuşağının alı

Dilimin en süzgün balı

Sevdamın son durağı sizsiniz

Şol cennetlerin burağı, siz! 

Siz, hasretlere bürünürsünüz de

Acınızla acımaz mı yüreğim

Ben hislenmez miyim? 

Menekşe seli çağlarken gözlerinizde

Islanmaz mıyım? 

Tanırım sizi

Menevişli gözlerinizden

Kavruk yüzlerinizden tanırım! 

Eni gurbet sonu gurbet bir hayatın

Yokluk teknesine düşen acılardan

Hasretlerden

Yılmak ne bilmezsiniz bir dem

Donuk bakışlarınızda hüzün

Kınalı saçlarınızda erdem

Çile hamurunu özlemle yoğurursunuz! 

Hüzün,

Toprağa er bırakmanın adıdır

Sözlüğünüzde bazen! 

Taa uzaklardan gelen bir çocuk sesi

Göğsünden vurulmuş bir can ürpermesi

Ağıt ağıt gökyüzüne ağarken

Bayrakla sarılı tabutlara kapanıp ağlarsınız! 

İşte o zaman düşer can evime

Bir ince sızı

Kor gibi alırım içime

Ay ışığı bakışlarınızı! 

Bu yıllarca ezan sesiyle yunmuş

Esrimiş toprağa

Bu, yıllarca karanfil yağmuru

Yemiş toprağa

Karanfil veren sizsiniz! 

Ve salınan dala

Ve kızaran güle/yaprağa

Şekil veren siz! 

Tanırım sizi

Ve anamı hatırlarım sizi her görüşümde

Cemresi gönül teri bahçelere

Gündeliğe gittiğimiz günleri hatırlarım

Yüreğimde ateş çiçekleri açar

Sizi her görüşümde

Tanırım sizi

Al yazmanızdan

Altın hızmanızdan tanırım! 

Kilimlerde nakışlarınızdan

Aslı duruşlarınızdan

Şirin bakışlarınızdan tanırım! 

Nene Hatun’lar gibi vakti gelende

Cepheye çıkışlarınızdan tanırım! 

Şu yanan yüreğime

Sardığım kar sizsiniz

Yüzünde sevdalı düşlerin

Albenisi esriyen yar

Ve en sıcak diyar siz! 

Tanırım sizi

Nasırı mor süsen açan

Sarı gül sarışlı ellerinizi

Öpmeyen bahar bahar olmaz! 

Sizi görür de insan nasıl

Eriyip buhar olmaz? ! 

Eriyip buhar olmaz? !', 'TANIRIM SİZİ   -Anamın, sarı gül sarışlı ellerini öperken... Tanırım sizi Yüreğim kadar  sıcak dillerinizden Nasırı mor süsen açan Sarı gül ...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Kaya']::text[], 8.5, '{"poet":"Durmuş Kaya","poet_slug":"durmus-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":96,"source_url":"https://www.antoloji.com/tanirim-sizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Oldum!', 'mutlu-oldum-mesut-ozturk-nzaq1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne umutlarla gelmiştim ben sana,

Sadece güvenmiştim Yaradana,

Huzuru ararken bağlandım ona,

Tuvalet temizlerken Mutlu oldum ben! 

Sistemi oturmuş, Teknolojisi bol,

Her köşesi yapılmış, her tarafa gider yol,

Sen anlayamazsın, burda herşey tooll(Havalı) 

Temizlik yaparken Mutlu oldum ben! 

Üniversite okumuşsun, ilgilenmezler,

Şehirlerde büyüsende, beğenmezler,

Öğünerek Türküm desen,zaten dinlemezler,

Sokak süpürürken, Mutlu oldum ben! 

Gülmeyi bilmeyen bu gavur elinde,

Gece gündüz çalışıp harab oldum ben,

Şükrü bilmeyen Avrupa elinde,

Paranın malın kulu oldum ben! 

Verdiğin gibi alırsın,senin gücün yeter,

Yarabbi ne olur, olmayana ver,

Herşeyini kaybeden, bu zat şöyle der; 

Maddiyatın, yalanın kulu oldum ben! 

Biriktir biriktir, faydasını görürsün,

Kaybettiğin gün, yerde sürünürsün,

yardım eli aradığında,

Dünyan yıkılır, açlıktan kudurursun?', 'Ne umutlarla gelmiştim ben sana, Sadece güvenmiştim Yaradana, Huzuru ararken bağlandım ona, Tuvalet temizlerken Mutlu oldum ben!  Sistemi ot...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mutlu-oldum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandırdılar Seni Nasıl İnandın', 'kandirdilar-seni-nasil-i-nandin-yusuf-onder-bahceci-176n4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen ellere inandın da bak nasıl kandın,

Yalnız seni sevdim ben nasıl da kandın,

Sen bu kadar safmısın be nasıl inandın,

Kandırdılar seni güzelim, nasıl inandın.

Beni kimse kandıramaz fazla sevmişim,

Seni çok sevmişim bil, cânım demişim,

Bütün Alem hasım olsa seni sevmişim,

Kandırdılar seni güzelim, nasıl inandın.

Seni böyle kandıranlar şimdi nerdeler,

Söylermisin bana nerede, nere gittiler,

Yorgan gitti Gülüm kavga bitti dediler,

Kandırdılar seni güzelim, nasıl inandın....', 'Sen ellere inandın da bak nasıl kandın, Yalnız seni sevdim ben nasıl da kandın, Sen bu kadar safmısın be nasıl inandın, Kandırdılar seni güz...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kandirdilar-seni-nasil-inandin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Hüznüm', 'sevgili-huznum-hatko-halil-ulutasli-54lbx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yollar sonsuz

Gündüzler umutsuz

Geceler yorgun

Arkamdan ölüm kovalar

Beni bıraktığın

Her coğrafyada...

Tesadüftür doğuşum

Doğru ama

Çerkes oluşum.

Farkında değilim

Bakıyorum nafile

Maalesef

Kör olmuşum.

Beynim iki bin yıllık

Yüreğim her gün yaralı

Ben meğer

Kültürlü yoksulmuşum.

Kraldan çok kralcı

Tüm sorunlara yabancı

Bir kimliksizliğe

Hapsolmuşum.

Neredeyim, kimlerleyim

Konuştuklarım anlaşılmıyor

Konuşulanları

Anlamamaktayım.

Memleketimden

bir karış uzaklıktayım.

Kovalıyor beni

Ölümlü rüzgar

Mezarımı hazırlamışlar.

Neredesin sevgili hüznüm

134 yıl yetmedi mi

Dönmezsen ben de

Ötekiler gibi

Teslim olacağım.

Yalvarıyorum sana

Yüzünü bir göreyim

Tenine bir dokunayım

Yok olmadan

Götür beni

Getirdiğin yere

Sevgilim sevgili hüznüm...', 'Yollar sonsuz Gündüzler umutsuz Geceler yorgun Arkamdan ölüm kovalar Beni bıraktığın Her coğrafyada... Tesadüftür doğuşum Doğru ama Çerkes o...', ARRAY['Türk Edebiyatı','Şiir','Hatko Halil Ulutaşlı']::text[], 8.5, '{"poet":"Hatko Halil Ulutaşlı","poet_slug":"hatko-halil-ulutasli","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sevgili-huznum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Aşk - 2', 'eski-ask-2-metin-yuksek-svid2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saklanacak ne çok anı birikmiş meğerse,

En kuytularda saklanan resimlerin hatrına.

Sıcacık hayaller kurmuşlardı birbirleriyle,

Soğuk sızıları işlemişti yüzlerinin hatlarına.

Evet,bir çocuk parkıydı orası,

Yoksa bir cehennem bahçesi mi? 

Neden yıllar sonra karşılaşmışlardı,

Ve neden hayallerindeki gibi olmamıştı? 

Kadın,kocasını seviyordu evet,

Adam da karısını elbette.

Ama ikiside birbirlerini sevdikleri kadar

Kimseyi sevemeyeceklerini biliyorlardı.

Acı senaryonun suçlusu kimdi peki? 

Terkedip giden kadın mı,

Peşinden gitmeyen adam mı? 

Şimdi bir gurur faturası ödüyorlardı,

Koyunlarında başka insanlar,

Kucaklarında başka çocuklar,

Başka alınyazılarında,

Başka sahnelerde rolleri vardı.

Ama,

Bir bakıştılar ki,

''Seni hala çok seviyorum'' sözü,

İkisinin gözünden aynı anda uçmuştu

Diğerinin gözlerine...

Çoluk çocuğa karışmış iki insan,

Eşlerine ihanet ediyormuş gibi hissettiler; 

Biriken gözyaşlarını sildiler,

Hafif güldüler,

Bir cesaret edip de

''Merhaba.'' diyemediler...

Gururdan ayrılmışlardı,

Gururdan birleşemediler,

Aşklarını eskittiler...', 'Saklanacak ne çok anı birikmiş meğerse, En kuytularda saklanan resimlerin hatrına. Sıcacık hayaller kurmuşlardı birbirleriyle, Soğuk sızılar...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/eski-ask-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse', 'kimse-sair-pinki-yfu7b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensin içtiğim içkilerin kadehlerinde

Sensin attığım adımda,

Aldığım her nefeste

Sensin hayatımın her köşesinde

Bunları kim mi biliyor

Kimse

Şıııt sesiz oku

Duymasın

Kimse', 'Sensin içtiğim içkilerin kadehlerinde Sensin attığım adımda, Aldığım her nefeste Sensin hayatımın her köşesinde Bunları kim mi biliyor Kimse...', ARRAY['Türk Edebiyatı','Şiir','Şair Pinki']::text[], 8.5, '{"poet":"Şair Pinki","poet_slug":"sair-pinki","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kimse-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Modern!', 'modern-mesut-ozturk-qwaka', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saçları dik sürmüş, iki kilo jöle,

Elbise son moda, Kulakta var küpe,

Modern olan sakalı çıkmış öne,

Fakirin karnı aç, ona ne! 

Altnda son model araba,

Yan koltukta birde manita,

sabah olur, diskodan gelir eve,

Ekmek kavgası bilmez, zaten ona ne! 

Baba verir, o yılmadan alır,

Dünya da hava atmak için kalır,

Çalışmayı bilmez, camiyi tanımaz,

O çok yakışıklı, Tanrı işinden ona ne!', 'Saçları dik sürmüş, iki kilo jöle, Elbise son moda, Kulakta var küpe, Modern olan sakalı çıkmış öne, Fakirin karnı aç, ona ne!  Altnda son m...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/modern-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderim Kederim Oldu', 'kaderim-kederim-oldu-metin-yuksek-vpxd4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En acı andı o an,

Titreyen ellerimin ucunda,

Soğuk rüzgarın sardığı bir tepede,

Fotoğrafına düşüyordu gözyaşlarım...

Acın biraz olsun dinmedi içimde,

Yokluğun bir kene gibi yapıştı gecelerime.

Uyku da terketti gözlerimi çoktan,

Tecavüz etti yalnızlığın tüm düşlerime.

Bin ağıt da yaksam,bin türkü de,

derdimi anlatamam kederime.

Kaderim,kederim oldu malesef,

Acın ihanet etti metanetime.', 'En acı andı o an, Titreyen ellerimin ucunda, Soğuk rüzgarın sardığı bir tepede, Fotoğrafına düşüyordu gözyaşlarım... Acın biraz olsun dinmed...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kaderim-kederim-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alim-ûl ûlêma', 'alim-l-l-ma-ali-riza-unal-2r4o5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey Rıza, na ehle pinhan ol, sohbet eyleme

Her mütecaviz istilâ,angudu ukâlâ

Sende ise bu cevher sukûta ver  söyleme

Eliften bihaber ermiş, aşmış alim-ûl cühela

Rabbini bilmeyen gafildir, nefsine müptela

Mürşidi olmayanın hayrı şer, canına bela

Aşık olan ölür mü, nidâ etseler de selâ

Her sırrı ifşa eyleme  incinir alim-ûl ûlâma.', 'Ey Rıza, na ehle pinhan ol, sohbet eyleme Her mütecaviz istilâ,angudu ukâlâ Sende ise bu cevher sukûta ver  söyleme Eliften bihaber ermiş, a...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/alim-ul-ulema-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim Nefis', 'zalim-nefis-i-brahim-halil-demir-4dpp4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zalim nefis için albenisi güzeldir bu fani dünyanın,

Bunu iyi bil ki,aldanırsan,kaybedersin ahiretin.

Nefse hoş gelen hemen-hemen her şey,

Kaybettirir sana ebediyet vadeden cennetin.

Her şeyin en mükemmeli orada,

Cehennem de cennet de kazanılır burada.

Çok çalış fani dünyanın çok zor imtihanlarına! ,

Kazanırsan şayet,mutlulukların en güzeli var orada.

Kandırıyor nefsin hoşuna giden ne varsa,

Durma ek iyilik  fidanlarını,kalmasın boş arsa! 

Meyve ve gölge versinler,ötüşsün üstünde envai türlü kuşlar,

Nasibini alırsın,ne zaman rahmet yağmurları yağarsa.

Güneş,ay ve yıldızların görevi başka-başka,

Bunları seyredip tefekkür ettikçe,gelir insan hemen aşka.

Bu nimetleri yaradanı derinden düşündükçe,

İmanı kavileşir insanın,nefis cayır-cayır yanar ataşta.

İnce ele sık doku ki pişman olmayasın! 

Tüyü henüz bitmemişlerin hakkını sen sakın yemeyesin! 

İsteyeceksen iste yaradandan her şeyin helalini! 

Sen sen ol sakın şeytanın oltasına asla düşmeyesin! 

Nefis uyumaz hiçbir an,ejderha gibi açıktır daim ağzı,

Umulmadık bir anda sinsice yoklanır insanın nabzı.

En büyük galibiyet nefis ile yapılan savaştadır,

Yaradan ne güzel yaratmıştır uçsuz sütunsuz arzı.

Tefekkür etmek lazım ihlas ile gönül derinliğinden,

Nefis hep faydalanmak ister,şeytanın serinliğinden.

Yaşanacak ömür bellidir,zira ne fazlalaşır ne de eksilir,

Gel zikret Allah’ın Cemal esmasını,faydalan her güzelliğinden! 

Bunları söylemek çok kolay ama yaşamak lazım,

Kolay değildir ihlaslı bir mümin için,haram lokmayı hazım.

Nefis güven telkin eder insana,yaptığı birkaç önemsiz amel için,

Düşündükçe bunları,isterim ki kendi mezarım o an kendim kazım.

Gel,uzun gecelerde sahip olduğumuz nimetler için ibadet edelim! 

Sadece onun rızasını kazanmak için birbirimize gelip gidelim! 

En büyük zenginlik budur,şayet kazanılmışsa onun rızası,

Seviyorsak birini,vakit kaybetmeden hemen söyleyelim.

28/01/2006', 'Zalim nefis için albenisi güzeldir bu fani dünyanın, Bunu iyi bil ki,aldanırsan,kaybedersin ahiretin. Nefse hoş gelen hemen-hemen her şey, K...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/zalim-nefis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim sevgiye', 'hasretim-sevgiye-zernisan-aydogan-0y6ak', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nezaman söylesem derdimi kime

Üzgünüm derdimden anlayanım yok

Kapanmaz bu yara kendi kendine

Hasretim sevgiye sevgiden de çok

Dertlerimi alsam bir bir kaleme

Ne defter yeter nede kelime

Gönlüm kırık dostlar ne söylesem nafile

Hasretim sevgiye sevgiden deçok', 'Nezaman söylesem derdimi kime Üzgünüm derdimden anlayanım yok Kapanmaz bu yara kendi kendine Hasretim sevgiye sevgiden de çok Dertlerimi als...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hasretim-sevgiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temenni!', 'temenni-mesut-ozturk-hrc4t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akmasın gözyaşın, al mendili sil hele,

Bak kır olmuş saçın, bu acı elem niye? 

Kahrettin kendini, birgün döneceğim diye,

Bak yıllar oldu, hala burdasın be! 

Ne olurdu bende gülebilseydim,

Yavrularıma sarılıpta sevebilseydim,

Almanya kahrından, kanser olduğumda,

Bir yakınıma sırt dayayabilseydim.

yanlızlık kaderim olmuş benim,

Bir tane bile yok düşünenim.

Eğer bir köşede kalırsa bu cesedim,

Türkiye`ye gömün beni. bu son temennim.', 'Akmasın gözyaşın, al mendili sil hele, Bak kır olmuş saçın, bu acı elem niye?  Kahrettin kendini, birgün döneceğim diye, Bak yıllar oldu, ha...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/temenni-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ses Gelir! ! ! ! Uzaklardan....', 'bir-ses-gelir-uzaklardan-arzu-gulucudur-p4nlb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ses gelir uzaklardan

Gözüm dalar camlar ardına

Aklıma hayalin düşer

Son bakışın ardına

Gözümden süzülür sevgime bir damla

Ardından bir damla daha,çok sevdiğime

Ve bir damla daha vazgeçemediğime

Bir ses gelir.

Adın çınlar kulaklarım da

Özlemim diz boyu

Hasretim kara çalmış beyazlara

Uykusuz geceler yoldaş bana

Çarem yok 

Uzaklar da...

Bir ses gelir.

Kendi kendine konuşur kalem

Yazar hiç bilmeden sevdasını

Okur şarkısını ayrılığın

Destan olur aşk

Dillere dökülür

Dil söyler...

Bir ses gelir uzaklardan

Kısık antar sesi...

_ ''Ben  geldim sevdam''der şair

Ve son perde..

.MUTLUYUZ... :)', 'Bir ses gelir uzaklardan Gözüm dalar camlar ardına Aklıma hayalin düşer Son bakışın ardına Gözümden süzülür sevgime bir damla Ardından bir d...', ARRAY['Türk Edebiyatı','Şiir','Arzu Gülücüdür']::text[], 8.5, '{"poet":"Arzu Gülücüdür","poet_slug":"arzu-gulucudur","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-ses-gelir-uzaklardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışların Yaktı Beni', 'bakislarin-yakti-beni-yusuf-onder-bahceci-4y1u8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saçlarını kıskanmaz mı gecenin karanlığı,

Yüzün sanki bir ay gibi, dolunay aydınlığı,

Hilal kaşlar benziyor, Hilal ile Ahmer''e,

Bakışların yaktı beni, düşürdü bu hallere.

Kirpiklerin ok olmuş, şu kalbimi deliyor,

Sana bakan gözlerim yaşlar ile doluyor,

Ne çok sevmişim seni bana neler oluyor,

Bakışların yaktı beni, düşürdü bu hallere.

Deli gönül sevmiş onu ona gönül verilir,

Gizli gizli ağlanır da binler ahlar çekilir,

Elden bir şey gelmez bu ellerden gidilir,

Bakışların yaktı beni, düşürdü bu hâllere....', 'Saçlarını kıskanmaz mı gecenin karanlığı, Yüzün sanki bir ay gibi, dolunay aydınlığı, Hilal kaşlar benziyor, Hilal ile Ahmer''e, Bakışların y...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bakislarin-yakti-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Be Anam!', 'be-anam-mesut-ozturk-huqqp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bundan yıllar önceydi,

Gözümde gözyaşı, elimde çantam,

Böyle ayrılmıştım baba ocağından,

Yanlızlık kaderim oldu be Anam! 

Altı sene biter mi? Bizi adam eder mi? 

Birgün gibi gelipte geçer mi? 

Bekleyen gurbet kuşuyum, Demiştim.

Yirmi sene oldu. Hala gurbetteyim be Anam! 

Yuvamdan ayrılışım hep aklımdaydı,

Kader birde sevdiğimi elimden aldı,

Herhalde mutluluk bana haramdı? 

Çünkü? Oğlun yavrularına hasret kaldı be Anam

Keşkeleri kaldırdım hayatımdan,

Ballar aksada dudaklarından,

Birşeyi unutma! Eğer saf bir duyguyla seviyorsan! 

Muradıma ereceğim herhalde be Anam!', 'Bundan yıllar önceydi, Gözümde gözyaşı, elimde çantam, Böyle ayrılmıştım baba ocağından, Yanlızlık kaderim oldu be Anam!  Altı sene biter mi...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/be-anam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayda Değer', 'kayda-deger-meral-yagcioglu-lekm4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaşam içinde

yüzlercesini değil

tanıdım birkaçını

içlerinden birisi eğer

olsaydı kayda değer

gönül sayfamın 

tertemiz bir köşesinde

divitten damlayan

damlacıklarla yazılı

kalırdı acı,tatlı bir iz

ya çentiklenen yüreğim

kıvranırdı kan gölünde

ayrılık hüsranıyla

ya da bulutların üzerinde

haylaz çocuklarla

çevirirdi aşka topaç

kapılıp sevgi yeline

kaybolurdu gözden

mavi uçurtma

gelip geçti mevsimler

yok yılların ardında

can da can

canansa hiç olmadı

oysa çiçeklenen yüreğim

sevginin her türlüsüne 

uzanacak elleri

hazır beklemede

sarmak için sinesine

şiir olmuş akmış dizelere

		20/09/2005', 'yaşam içinde yüzlercesini değil tanıdım birkaçını içlerinden birisi eğer olsaydı kayda değer gönül sayfamın  tertemiz bir köşesinde divitten...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kayda-deger-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba!', 'baba-mesut-ozturk-rnkxa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baba olduğunda anlarsın demiştin,

Daha gençsin, sen bilmezsin demiştin,

Ben doğru değil, haksızlık etme dedığimde,

Ben Babayım sus! Sen bilmezsin demiştin.

Şimdi bende babayım baba! 

Haklı olduğunu çoktan anladım ama! 

Maalesef çok uzak kaldım sana,

Ne olur affet bağışla baba! 

Yaşın kaç? Durumun ne olursa olsun? 

Bütün evlatlar babalarına saygılı olsun,

Yaptığın hataların varsa? 

Zaman geçirme! Özür dile. Yoksa! 

Pişman olursun...!', 'Baba olduğunda anlarsın demiştin, Daha gençsin, sen bilmezsin demiştin, Ben doğru değil, haksızlık etme dedığimde, Ben Babayım sus! Sen bilm...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/baba-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Günlerim', 'kara-gunlerim-adnan-gordum-yja8h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karadır günlerim,

Kara gözlerine 

Değmediği zaman gözlerim..', 'Karadır günlerim, Kara gözlerine  Değmediği zaman gözlerim.....', ARRAY['Türk Edebiyatı','Şiir','Adnan Gördüm']::text[], 8.5, '{"poet":"Adnan Gördüm","poet_slug":"adnan-gordum","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kara-gunlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Birgün Okursun', 'belki-birgun-okursun-yusuf-onder-bahceci-tk735', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni çok sevdiğimi nasıl anlatsam,

Bir şiir sitesi bulup şiirler yazsam,

Sana övgü dolu sözlermi yazsam,

Belki birgün bulursun, belki okursun.

İnterneti açarak sen adımı yazsan,

Hemen adım çıkar hemen tıklasan,

O şiirlerde neler var iyi bakarsan,

Belki birgün bulursun, belki okursun.

Aman Allahım aman bu ne iş dersin,

Bu salak beni nasıl sevmiş mi dersin,

Bilmem neler dersin, neler söylersin,

Belki birgün bulursun, belki okursun.

Bu ne laf anlamaz bir adammı dersin,

Yoksa bu şiirleri sendemi beğenirsin,

Sen ne dersen de be seni sevmişim,

Belki birgün bulursun, belki okursun......', 'Seni çok sevdiğimi nasıl anlatsam, Bir şiir sitesi bulup şiirler yazsam, Sana övgü dolu sözlermi yazsam, Belki birgün bulursun, belki okursu...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/belki-birgun-okursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İthal Damat!', 'i-thal-damat-mesut-ozturk-zib7i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İthal damat dediler,

bizlerle dalga geçtiler,

İşbulup çalışsakta,

Seni biz adam ettik dediler.

Karnımız açtı verdiler ekmek,

Lafları dokunurdu sanki köstek,

Ne oldu sanki? Türkiye`den sonradan geldiysek,

satın alınmış insan, değil bir eşek,

Yıllar geçse de;  Bizim sayemizde derler,

Helalı bilmez hep haram yerler,

İnsan yerine havayı sever,

Kalbin sesine kulak vermezler.

Satılık değildir bu deli gönlüm,

Eğer yeterse bu kısa ömrüm? 

İnthalat için verilen parayı,

Elbette öderim birgün!', 'İthal damat dediler, bizlerle dalga geçtiler, İşbulup çalışsakta, Seni biz adam ettik dediler. Karnımız açtı verdiler ekmek, Lafları dokunur...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ithal-damat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İpekli Mendil!', 'i-pekli-mendil-mesut-ozturk-705qt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birgün bende onun gibi ölürsem? 

Kara tabutuma bakarak gözyaşı dökme! 

Lacivert bir arabayla kabre gidersem? 

Silme  gözyaşını  o ipekli mendiline! 

Anladım birkez daha Dünya`nın yalan olduğunu,

Sevgiyle ölebilmek Yarabbi bu mu? 

Lacivert arabayla o kara tabutu,

Görünce silme yaşlarını o ipekli mendiline! 

Ciğerleri su bağlamış, eceli gelmiş,

Nefesi daraldıkça Besmeleyi çekermiş,

Türkiye`deki çiçekler sarı mavi renklenmiş,

Böyle olursan yaşını silme, o ipekli mendiline!', 'Birgün bende onun gibi ölürsem?  Kara tabutuma bakarak gözyaşı dökme!  Lacivert bir arabayla kabre gidersem?  Silme  gözyaşını  o ipekli men...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ipekli-mendil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldırma Dostum', 'aldirma-dostum-murat-kilic-2-8p1gk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aldırma dostum! 

bugün de böyle geçti diye kahretme.

yarını düşün,yarınlar geleceğin.

bir tebessüm satın al baharlardan.

yıldızlar satın al umutlu rüyalardan.

sana hüzünlerini unutturacak,

kendine yol beğen,

mutluluğun kapısından.

özlemlerini bırak gitsin.

onlar senin peşinden koşagelsin.

durmak bilmesin umut kervanın; 

hep en önünde ol ki; 

mutluluğu doyasıya kucaklayabilesin.

allı yeşilli gökyüzü çiz kendine.

gözlerinden gülücükler dağıt,sevin.

sen gülünce unutma ki,

bir yüz daha gülebilir.

kapatma sakın kapılarını,

aç sonuna kadar.

aç ki güzellikler sana da gelsin.

ruhunu saran tarifsiz duygular düşün haylinde.

dağ gibi düşün hayallerini,yenilme yalnızlığa.

gerçek kadar gerçek ol; sen ol

unutma! 

yaşayacağın yalnız bir tek hayat var.

ne zaman biteceği bilinmeyen bir hayat...

güzelliklerle yaşa

güzelliklerle uğurla onu.

ne olursa olsun dik yürü dik yaşa ve dim dik öl.', 'aldırma dostum!  bugün de böyle geçti diye kahretme. yarını düşün,yarınlar geleceğin. bir tebessüm satın al baharlardan. yıldızlar satın al ...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aldirma-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-kaan-salli-fu0hp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yüce tanrım bu ne zengin menü

bu ne zor karar

beni de bu korkutuyor zaten

illa ki birini seçmeli miyim? 

hepsini birden alamaz mıyım? 

bir maceraperest,

bir ihtiyar delikanlı,

bir aristokrat, 

bir çingene ve binbir saz arkadaşı,

bir gizem,

bir mavi bulut,

binbir kendine yalancı.

bir mistik şehir istanbul

bir hayal peşinde kendim

ah bir de yakalayabilsem…

AKS''95', 'yüce tanrım bu ne zengin menü bu ne zor karar beni de bu korkutuyor zaten illa ki birini seçmeli miyim?  hepsini birden alamaz mıyım?  bir m...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istanbul-380-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendime', 'kendime-kaan-salli-h9ktm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'eureka, buldum

dört çeşit insan var; 

gerçekten aptal olanlar,

aptal olup akıllı gibi davrananlar,

akıllı olup aptal gibi davrananlar ve

gerçekten akıllı olanlar.

en tehlikelisi hangisi? 

bilemiyorum

ama benim zararım kendime

bunu bilirim bunu söylerim

kendi kendime

biliyorum, eee

neredeyim? 

AKS''95', 'eureka, buldum dört çeşit insan var;  gerçekten aptal olanlar, aptal olup akıllı gibi davrananlar, akıllı olup aptal gibi davrananlar ve ger...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kendime-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Nikotin Çocuklar', 'kucuk-nikotin-cocuklar-kaan-salli-wi3xy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gecenin karanlığından 

ayarsam keni karanlığıma

küçük nikotin çocuklara sarılırım hemen

yakıp loş ışıklarını

salıverirler buhranın isini ciğerlerme…

ruhumdansa kirlensin ciğerlerim umrumda değil.

AKS''95', 'gecenin karanlığından  ayarsam keni karanlığıma küçük nikotin çocuklara sarılırım hemen yakıp loş ışıklarını salıverirler buhranın isini ciğ...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kucuk-nikotin-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odam', 'odam-kaan-salli-ncxwo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sessiz ve yalnız fırtınalarımı onunla yaşadım

ve tabi çılgın uykularımı paylaştım yıllarca

en umutsuz anımda onun omzunda ağladım

gün geldi, bıraktım onu

tercih ettim dünyayı

ama o hiç küsmedi, küsemedi bana

gürültümü, hıçkırıklarımı o duydu

o ağladı belki de ben yıkıldığımda

sirkeli suların kokusunu o duydu ateşim varken

onunla keşfettim cinsiyetimi

ona yumruk attım kızdığımda

hep beraber içtik hüsran sigaralarını

şu anda bile bana bakıyor gözleri dolu

“sonunda beni de hatırladın, hayırsız” 

diyor bıyıkaltından gülerek

tenimin kokusunu kadınımdan iyi bilir o

herşeye beraber başladık ve

herşeyi beraber bitirdik:

aşklarımı, okulu, sigarayı,

sevişmeleri, mutluluğu, hüznü,

rüyalarımı, kâbuslarımı, parayı

müziği, geceyi, gündüzü, herşeyi,

evet herşeyi…

hayır herşeyim, sekiz köşeli dünyam benim

canım odam.

AKS''95', 'sessiz ve yalnız fırtınalarımı onunla yaşadım ve tabi çılgın uykularımı paylaştım yıllarca en umutsuz anımda onun omzunda ağladım gün geldi,...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/odam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Bakışlar Böyle Gider Sanmıştım', 'bu-bakislar-boyle-gider-sanmistim-yusuf-onder-bahceci-l9ngq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilki herkesten evvel seni sevmiştim,

Ne kadar cahilmişim ben dememişim,

Sen bunu bilseydin ben bilmemişim,

Bu bakışlar böyle gider sanmıştım.

Sevdim kalbimle, konuştum kalbimle,

Gel sende ne olur bir kalbini dinle,

Bana böyle ettin ama kalbim seninle,

Bu bakışlar böyle gider sanmıştım.', 'Bilki herkesten evvel seni sevmiştim, Ne kadar cahilmişim ben dememişim, Sen bunu bilseydin ben bilmemişim, Bu bakışlar böyle gider sanmıştı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-bakislar-boyle-gider-sanmistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paranoya', 'paranoya-kaan-salli-z5774', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'tutunup güvensizliğin dallarına

güveni boğar zehirli sarmaşığıyla

yavaş yavaş koparır beyni kalpten

kalbi kopartıp göğüsten atar yanardağın alevine

yandıkça güler, güldükçe güler iblis

sonra beyni alır zincirler altına

her hatasında daralan bir tasma takar ona

korktukça hata yapar beyin

ve daralır tasma

böylece insanlardan da kopar

ortadan ikiye beyin

artık acımasız efendisi ile başbaşadır

öldükçe semirir efendisi paranoya

emer onu hücrelerine dek, son çılgın nefese dek

sonra da kendi kendine yedirir beyini

paranoya ve işte ölüm! 

AKS''95', 'tutunup güvensizliğin dallarına güveni boğar zehirli sarmaşığıyla yavaş yavaş koparır beyni kalpten kalbi kopartıp göğüsten atar yanardağın ...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/paranoya-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simit', 'simit-kaan-salli-wm03d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'simidin böylesini yemedim uzun zamadır

ah bir de çayım olsa

ha unutmadan; bir de martı ile vapur.

AKS''95', 'simidin böylesini yemedim uzun zamadır ah bir de çayım olsa ha unutmadan; bir de martı ile vapur. AKS''95...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/simit-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-kaan-salli-lapsm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'neden “umut” koyalar sakat doğan çocuğun adını? 

bilir misin? 

umut ettikleri ölüm mü, sağlık mıdır? 

yoksa ettikleri hataların bağışlanması mı? 

ölmezse erkenden, kemale ermeden yaşı

hayat boyu bunu sorar kendine o tohum

ve yaşar umutsuzluğun tezatını adıyla

hayatta hepimiz adem’le havva’nın kardeşleriyken

ve hala üreyip dururken

bilmeden daha da sakat nesillere can verirken

sorma kendine “kıyamet nasıl bir şey? ” diye

işte kıyamet bu umutsuzluk dağının lavları

kustukça kusuyor nefretini insanlara

bu sırat köprüsü dünyada.

AKS''95', 'neden “umut” koyalar sakat doğan çocuğun adını?  bilir misin?  umut ettikleri ölüm mü, sağlık mıdır?  yoksa ettikleri hataların bağışlanması...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/umut-245-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerevet', 'kerevet-kaan-salli-5vsfg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'nerede arap bacı’lı kare mabel çikletleri

	şemsiye çikolatalar

	jelatini defter arası çokomeller

	okul kooperatifinin bayat simitleri

	simit tepsisinin sonu susamlar

	japon-kale mahalle maçlarının

		saklambaçların, uzun eşeklerin,

		yakartopların, istopların,

		bakaralı topaç çevirmelerin,

		36lığın, çukurun, çemberin,

		çelik-çomağın susuzluğu

		şişesi kadar ak sade gazozlar? 

pamuk helvayı gördüm geçenlerde

iyiden iyiye çökmüş tonton

leblebi tozunu sordu

	“nerede horoz ve elma şekeri kardeşler? ” dedi

	“hey gidinin gürbüz çocuk rüyaları, kim 														bilir? ” dedim

	gözünden bir damla hüzün süzüldü

	“iki sene oluyor macun’u kaybettik” dedi

öpüştük, buğulu gözlerle ayrıldık sonsuza dek

ilkokulumun arz-ı endamından geçerken

ihtiyarın heybetli günleri geldi aklıma

neredeydi acaba tahta kalemkutuları

	hani kapağının arkasında kerat cetveli olanlar? 

	hah, hah onlar işte…

	ya dize, dirseğe yama deri kalpler

	mekap marka lastik pabuçlar

	ağızda pabuç kadar olan sigara çikletler

	el örgüsü ponponlu atkı ve şapkalar

	anneannemin göz nuru…

yürüdüm

mahalle çocuklarının “benim babam 													  seninkini….”çığlıkları

olağan pc/amiga  muhabbetlerine bırakmıştı yerini

aaah, ah…

neredeydi ayvaya, duta dalmalar

	cam kırıp kaçmalar

	futbolcu, araba kartları; adi kartondan

	heidi, şeker kız candy, ayı yogi çıkartmaları

		sulukların beslenme kaplarının üstünde

	çocuk kalbi, polyanna, jules verne’in 

		binbir macera tufanı kitabı

	domino, kestane (yedek üye mısır)  patlağı

	hulahup, kol yoran rugby topu

	işıksız yoyolar, tel pervane, çıt çıt, lak lak

	frizbiler, patlayınca küçülmeyen adi plastik toplar

	pompalı fare ve kurbağa

	tel direksiyonlu plastik arabalarım? 

hem elektrik tellerinin defnini protesto eden

kağıt uçurtmalar şimdi nerede dolanıyorlardı tellere? 

neyse

“annneeee! ” diye bağırmadan sızdım

bahçesiz apartmana sıkıntıyla

tabii ki postakutumda doğan kardeş yoktu

eve girip üstümü başımı attım sağa sola

- eskiden olduğu gibi -

televizyona uzandım

haberler vardı ama tuna huş, can akbel yoktu

onların yerine bin kanallı tüpte binbir renk

telefon bile bir kibar çalıyordu

	“dürülü, dürülü, dürülü,…”

hoş “zırrrrrrrrrrn” deseydi de bakmayacaktım.

sehpadan artık çiklet olmayan 

sigarama uzanıp yaktım bir buhran

çektiğim ilk nefesle kararan ciğerlerimi

çığlık çığlığa bağırttı birden yorgun beynim; 

“çocukluğum nerde? ? ? ”

yitti, bitti…

kim erdi muradına ki,

ben çıkayım kerevetine? 

AKS''96', 'nerede arap bacı’lı kare mabel çikletleri 	şemsiye çikolatalar 	jelatini defter arası çokomeller 	okul kooperatifinin bayat simitleri 	simit...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/kerevet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız', 'yalniz-kaan-salli-zdbaw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yalnız kalmak istemediğim yıllar boyu

yalnız bıraktınız

beni

ne olur anlayın artık

yaşayamadığım günlerin yorgunuyum ben

ve tek istediğim

yalnız kalmak ve uyumak çukurumda

üstüm toprak anayla örtülü.

AKS''96', 'yalnız kalmak istemediğim yıllar boyu yalnız bıraktınız beni ne olur anlayın artık yaşayamadığım günlerin yorgunuyum ben ve tek istediğim ya...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalniz-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Yok', 'adi-yok-kaan-salli-sd0b9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir sürü insan, adını bilmediğim

bir sürü insan, adımı bilen

bir sürü insan, derdini bildiğim

bir sürü insan, derdimi bilmeyen

bir sürü insan, pek azı dürüst

bir sürü insan, tek tük insan olan

bir sürü insan, hiç yok benim olan

bir sürü insan, hiç olamadı beni tanıyan

bir sürü insan, çok az yokluğumu yadırgayan

bir sürü insan, neredeyse yok varlığımı özleyen

bir sürü insan, bir sürü sebepten ötürü

bir sürü insan, bir türlü örtemedi üstümü

bir sürü insan, binbir dereden su getirdi amma

bir sürü insan, bir türlü silemedi gözümü

bir sürü insan, bir kez olsun tutamadı sözünü

bir sürü insan, bunca yaptıklarından sonra

bir sürü insan, bir ufacık kalbimi ısıtamadıktan sonra

bir sürü insan, posamı çiğneyip tükürdükten sonra

bir sürü insan, ben öldükten sonra

bir sürü insan, unuttular beni ancak yıllar sonra

AKS''97', 'bir sürü insan, adını bilmediğim bir sürü insan, adımı bilen bir sürü insan, derdini bildiğim bir sürü insan, derdimi bilmeyen bir sürü insa...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/adi-yok-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıram Keskindir Benim', 'hatiram-keskindir-benim-kaan-salli-cx097', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hatıram keskindir benim

sanırsın limon kolonyası 

aylarca dururum bir şişede

ama şöyle derin derin içine çekince…

hatıram keskindir benim

yakıverir genzini aniden

istemesen de gözyaşların

süzülüverir yanak yivlerinden…

hatıram keskindir benim

sanırsın bıçak yarası

aylar geçer üstümden

ama bir de dikkatlice bakınca…

hatıram keskindir benim

izi kapanmaz aniden

istemesen de ince bir çizgisi

beliriverir teninin pürüzsüzlüğünde…

AKS''97', 'hatıram keskindir benim sanırsın limon kolonyası  aylarca dururum bir şişede ama şöyle derin derin içine çekince… hatıram keskindir benim ya...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hatiram-keskindir-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Sevdalara', 'selam-sevdalara-oguzkan-bolukbasi-nnkz8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sıcaklığını bir şiire sarıp

Hayatıma katık etmekte geç kaldığımı anladım

En meymenetsiz havayı bile güneşli yaptığını görünce

Buzu çözülen bir sarkıt gibi sokağına damladım

Dudakların yoktu ne yapayım

/Ben senin toprağında yeşeren ne varsa dalı olmaya razıyım

Yeter ki kökümde senin gücün olsun/

Başka bir akşamı anlatıyorlar masaya oturduğumda sarhoşlar

Benim akşamlarımda ne varsa çalmışlar

Uykularımı boğmuşlar bir köşesinde yıldızların

Kervanlarda yürüyorum sabaha kadar

Kum tanesi oldum dağıldım çöl fırtınalarında 

Gözlerin yoktu ne yapayım

/Ben sana ulaşan her gemide yelken olmaya razıyım

Yeter ki rüzgarımı dudakların üflesin /

Korkma yanına gelirsem diye

Yaşamıma tanıklık edecek aşkı yüreğine gömdüm ben

Kelimeler bitti, öldüm ben

Toprağa can olup düştüm ben

Kucağın yoktu ne yapayım

/ Ben öptüğün yerde biten gülün dikeni olmaya razıyım

Yeter ki kokusunu senden alsın/

Bütün sevdalara selamım var benim', 'Sıcaklığını bir şiire sarıp Hayatıma katık etmekte geç kaldığımı anladım En meymenetsiz havayı bile güneşli yaptığını görünce Buzu çözülen b...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/selam-sevdalara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Oldum, Kolay Öleceğim', 'zor-oldum-kolay-olecegim-kaan-salli-bsnc1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'içimde bir sıkıntı vardı ki sormayın

böyle bir kabına sığmama

bir limitlerinden taşma, daralma

itivermiştim kendimi dünyaya

daha ilk nefesimde pişman olmuştum

ağlayıvermiştim kabama inen şaplakla

şimdi yine öyle bir sıkıntı var ki sormayın

böyle bir içimden içime kusma

bir sürüncemede kalma, zorlanma

itivereceğim kendimi öbür dünyaya

ilk nefesimde pişman olmuştum

son nefesimde pişman olmayacağım

pişman olsam bile ağlamayacağım

AKS''97', 'içimde bir sıkıntı vardı ki sormayın böyle bir kabına sığmama bir limitlerinden taşma, daralma itivermiştim kendimi dünyaya daha ilk nefesim...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zor-oldum-kolay-olecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayan Yürekler...', 'aglayan-yurekler-i-brahim-ethem-bingul-7u160', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her geçen gün artarken içimde sevgin

Vurdu ayrılığın kancası insafsızca, zalimce

Kanar dururum sessiz sessiz, yaram çok derin

Dalda çiçek mi kalır, kavuran soğuk gelince...

Dondu, isyan etti sensizliğine

Varlığınla kimlik bulan duygularım 

Bak, hasretinle bile ağlayamıyorum

Karaya oturdu umut yüklü sallarım...

Keşke...Keşke...Diyerek tükendi düşler

Birer hatıra şimdi senli gülüşler

Senin özleminle gönlümde mutluluk tüter

Gel artık, dememden kan ağlıyor yürekler...

www.iebingul.com', 'Her geçen gün artarken içimde sevgin Vurdu ayrılığın kancası insafsızca, zalimce Kanar dururum sessiz sessiz, yaram çok derin Dalda çiçek mi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aglayan-yurekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara Donduruyor', 'ankara-donduruyor-figen-aydogmus-u6mtw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ürkek adımlarla yollarda insancıklarız 

Bir ufacık çakıl arar gibi bakınıyor gözlerimiz yere 

Eller bileklere kadar eldivenli olsa da 

Bedenimiz bir türlü alışamadı bu ayazlara

Bahar bekleniyor 

Sırtımızdaki yükü atmak için 

Ayağımızdaki postallar koku yapıyor ıslandıkça 

Belli belirsiz serüvenlere çıkıyor yokuşlar

Adım adım arşınlanıyor Ulus’un caddeleri 

Buz kör biri gibi dağıtıyor kaldırıma bedenimizi

Soğuk bir başka oluyor Ankara’da 

Ayaz bütün küfürleri sayıyor yüzümüze 

Yanıt verecek hiç bir yerimiz kalmıyor 

İşledikçe iliklere titreme 

Gözlerimiz otobüste bile kapanıyor

Başımız yorgun, yastığa değdiği anda uykular kızıl alevi

Sabaha dek sessiz

Sabaha dek nefessiz dalıp kalıyoruz yorganın sıcaklığına

Ve yine bir gün daha adımlarımıza hükmediyor

Ankara donduruyor donmaya inat eden yüreklerimizi

Dost sohbetlerini esirgiyor eksiler

Bir bakışı dahi saklamak zorunda bıraktırıyor atkı arkasına

Ankara buz, 

Buzlar her şeyi kesiyor

F.A. 30.01.2006', 'Ürkek adımlarla yollarda insancıklarız  Bir ufacık çakıl arar gibi bakınıyor gözlerimiz yere  Eller bileklere kadar eldivenli olsa da  Beden...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ankara-donduruyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Sensizlikten Öleceğim Sanki', 'bugun-sensizlikten-olecegim-sanki-murat-kilic-2-c0imk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gün doğdu gün battı; herşey aynı.

sabah kalktığımda kara bulutların

dağılıp gitmesi için çok yalvardım Allah''a.

dağıldılar da ne oldu sanki! 

yine yalnız karşıladım güneşi.

gözüm kapıda kulağım telefonda

iki büklüm kaldım pencere önünde.

çiçekler soldu.

gürül gürül akan sular kurudu bugün.

bu ceza mı yoksa hediye mi senden bana.

özlemlere bile özlem duyuyorum şimdi.

hasret girdabına düştüm sensizlikten.

saatlece kendime ağladım bir de sana...

radyo frekanslarında şarkımızı aradım şarkımızı saatlerce

ne onu bulabildim ne de seni....

kendi hesaplaşmalarımda kaldım.

uçurumların önünde kaldım.

ve hala aynıyım.

kendi gün batımımda sırılsıklamım.

bugün sensizlikten ölsem burada,

ne ses ne bir kıpırtı ne de soluk alırım

bugün burada,yarın kim bilir,

hangi berduş gönülde toprağa karışırım.', 'gün doğdu gün battı; herşey aynı. sabah kalktığımda kara bulutların dağılıp gitmesi için çok yalvardım Allah''a. dağıldılar da ne oldu sanki!...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bugun-sensizlikten-olecegim-sanki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göksüz Geceler', 'goksuz-geceler-erkan-arslan-e8mga', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her vakit hoş şekli ile doğarken sabah,

Vaktin  de ötesinde vakte erer ömrüm.

Bu hoş şeklini seyreder ederim tamah,

Toyluğuna toyluk  katar serseri gönlüm.

Gündüzüm kaybolmaya yüz bulduğu andır,

Her vaktin erdiği,her vaktin dayandığı,

Neden batar ızdırabıma ermiş günler,

Ve akşam olur ömrümün öbür yarısı.

Doğar ve batar güneşler her akşam bu an.

Gün daraldı mı,gece sahibini bekler,

Geceden farksızdır odam,kaybolur tavan.

Göksüz geceler beni,sahibime ekler.

Artık ölüm zamanı hale geldim.

          Nisan 2000', 'Her vakit hoş şekli ile doğarken sabah, Vaktin  de ötesinde vakte erer ömrüm. Bu hoş şeklini seyreder ederim tamah, Toyluğuna toyluk  katar ...', ARRAY['Türk Edebiyatı','Şiir','Erkan Arslan']::text[], 8.5, '{"poet":"Erkan Arslan","poet_slug":"erkan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/goksuz-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur Yarala Beni!', 'vur-yarala-beni-i-brahim-halil-demir-fttyz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gamzeli yanaklarından dökülen gülücüklerle, 

İnsanı çöllere salan sevdalı kara gözlerinle,

Kirazımsı mosmor dudaklarınla,

Sevda kırlarında ceylanımsı yürüyüşünle,

Vur yarala beni! 

Sevda pınarından avuç-avuç su içişinle,

Sinirlendiğinde her şeyi bir kalemde silişinle,

Aslanvari  vakarlı haşin bakışınla

Sevda kalemiyle çok uzun mektuplar yazışınla,

Vur yarala beni! 

Konuşurken herkese kendini can kulağıyla dinletmenle,

Sevda aynasının karşısında saçlarını taramanla,

Damarlarında dolaşan asil ve tatlı kanınla,

İnsanın taşlaşan yüreğini yufkalaştıran göz yaşınla,

Vur yarala beni! 

İnsanı yarı yolda koymayan vefalı dostluğunla,

Bir lokma ekmeğini sevdiğiyle paylaşmanla,

Allah’a ve Resulullah’a olan bağlılığınla,

Enaniyetten ve riyakarlıktan kaçmanla,

Vur yarala beni! 

Dostlar için şirin uykudan seve-seve uyanmanla,

Seyyah misali kapı-kapı sevgi ve muhabbet dağıtmanla,

Güzelliklerin tamamını sevdiklerinle paylaşmanla,

Çirkinliklerden ise son süraat kaçmanla,

Vur yarala beni! 

30/01/2006', 'Gamzeli yanaklarından dökülen gülücüklerle,  İnsanı çöllere salan sevdalı kara gözlerinle, Kirazımsı mosmor dudaklarınla, Sevda kırlarında c...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/vur-yarala-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarsam Ağlarsın', 'aglarsam-aglarsin-kaan-salli-tlfc4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bunca yıl yürüttün beni 

hep kaldırımın kenarından

hiç mi aklına gelmedi 

ya düşseydim ha? 

ya düşseydim de,

görmeseydim seni

görseydim de,

öpmeseydim seni

öpseydim de,

sevmeseydim seni

sevseydim de, 

çabucak unutsaydım seni

unutmasaydım da,

ağlasaydım sana

o zaman üzülmez miydin? 

hadi tut elimden artık

tutmazsan düşerim,

düşersem göremem,

göremezsem öpemem,

öpemezsem sevemem,

sevemezsem unuturum,

unutursam ağlarsın 

işte buna dayanamam ben.

AKS''98', 'bunca yıl yürüttün beni  hep kaldırımın kenarından hiç mi aklına gelmedi  ya düşseydim ha?  ya düşseydim de, görmeseydim seni görseydim de, ...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aglarsam-aglarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizken', 'sensizken-kaan-salli-u88iz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bakamam gözlerine sensizken

gaztede binbir haber 

ben hepsinden bihaber

gittim geldim işime 

yatamam yatağa sensizken

duyamam kokunu sensizken

yanda komşular uyur

dışarda şehir uyur

gittim geldim evime

saramam aklımı sensizken

soramam kendimi sensizken

telefon çalar durur

bakan belki olur

gittim geldim sana

çekemem içimi sensizken

zora gelemem sensizken

herkes bişey sorar

herbiri beni kapsar

gittim geldim içime

hiç pes edemem sensizken

sıkıldım kendimden sensizken

hep ben, hep seni özler

hep sen, yoksun sen

gitti geldi aklım başıma

sen tek ilacım sensizken

AKS''98', 'bakamam gözlerine sensizken gaztede binbir haber  ben hepsinden bihaber gittim geldim işime  yatamam yatağa sensizken duyamam kokunu sensizk...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sensizken-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt!', 'ogut-mesut-ozturk-5xjk6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle birgün oldu ki sanki gökler ağladı? 

Yıkılmış bir viraneden yaşlı Nine çağırdı,

Hemen vardım yanına, gözlerinin yaşları,

Yanağına süzüldü bana dedi: Dinle oğul! 

Senelerce evveldi, zehir doluydu her lokmam,

Tat alamazdım gördüğün suyumdan ve aşımdan,

Günüm sitemle geçerdi, bıkmıştım vatanımdan,

Kader tuzağına düşmüştüm o anlarda oğul! 

Minik yavrular beşikte babalarını tanımadan,

Nice gelinler dul kaldı kınaları solmadan,

Mehmetciğim kışlada Cumhuriyeti tatmadan,

Alkanlara büründü haberin var mı? oğul! 

Senin kanın asildir ceddinden süregelen,

Anılar rüzgar gibi eser vatan zerresinden,

Yiğitliği anladın mı? Söyle yatan dedelerinden,

seni mertce yetiştirdik, bunu bilesin Oğul! 

Özgürlüğüne sahip ol dinle yaşlı nineni,

Bunu hep söyleyeceğim birgün giysemde kefeni,

Ben namuslu yetiştirdim sizi ciğer paremizi,

Sizin gibisine nineler kurban olsun Oğul! 

Az bir vakit geçti ki nine gitti yanımdan,

Bir ürperti gelmişti içmden, ta ruhumdan,

Hayret ettim olaya oracıktan ayrılmadan,

Naraları geliyordu, diyordu aslan oğul! 

Ne Mutlu Türklüğüme, böylesi bir ceddime,

Umutla bakıyorum, şimdi inanıyorum istikbalime,

Anıyorum onları bugün 29 ekimde...

Ninenin de dediği: Yaşasın Türküm Oğul!', 'Öyle birgün oldu ki sanki gökler ağladı?  Yıkılmış bir viraneden yaşlı Nine çağırdı, Hemen vardım yanına, gözlerinin yaşları, Yanağına süzül...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ogut-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Bahçesine Giren Güller Kokarmış', 'gul-bahcesine-giren-guller-kokarmis-yusuf-onder-bahceci-53yd2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söyleyim aşk şiirlerinin hecesi olmaz,

Güzel sevenlerin hiç gecesi olmaz,

Sevdiğin severse bil güllerin solmaz,

Gül bahçesine giren, güller kokarmış.

Sen bana bakarken, kalbim yakarken,

Şimdi neden böyle oldu çalı ve diken,

Sen beni severken ve gönül verirken,

Gül bahçesine giren, güller kokarmış.

Sevdim seni güzelim bekleyeceğim,

Sevdim seni güzelim bil seveceğim,

Seni cânım bildimde hep diyeceğim,

Gül bahçesine giren, güller kokarmış....', 'Söyleyim aşk şiirlerinin hecesi olmaz, Güzel sevenlerin hiç gecesi olmaz, Sevdiğin severse bil güllerin solmaz, Gül bahçesine giren, güller ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gul-bahcesine-giren-guller-kokarmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Defnem', 'defnem-kaan-salli-98ly8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'o kadar küçük ama

o kadar güzelsin ki

canımı vereceğim sana

o kadar yeni ama 

o kadar özlemsin ki

aşkımı vereceğim sana

o kadar saf ama

o kadar özelsin ki

ömrümü vereceğim sana

o kadar benim ama

o kadar özelsin ki

hayallerini vereceğim sana

AKS''01', 'o kadar küçük ama o kadar güzelsin ki canımı vereceğim sana o kadar yeni ama  o kadar özlemsin ki aşkımı vereceğim sana o kadar saf ama o ka...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/defnem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş Dakika', 'bes-dakika-kaan-salli-kn6mb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hani bu gece bana sarılıp sıkıca

küçük başını koydun ya omzuma

keşke dursaydı yorgun dünya 

ve bin yıl sürseydi o beş dakika

hani aniden kalbim sıkışıverdi ya

koltuğa uzanıp yattığımızda

keşke dursaydı yorgun dünyam

ve son hatıram olsaydı o beş dakika

hani en sonunda uykuya daldın ya

yatağımıza birlikte uzandığımızda

iyi geldin bu acımasız dünyaya

ve seninle bin yıl oldu her beş dakika

AKS''02', 'hani bu gece bana sarılıp sıkıca küçük başını koydun ya omzuma keşke dursaydı yorgun dünya  ve bin yıl sürseydi o beş dakika hani aniden kal...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bes-dakika-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buhran', 'buhran-kaan-salli-5hlbf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir kabuk bağlamış ki hüznümü 

sorma kalkmaz bir türlü

en son ne zaman ağladım acaba? 

şöyle kana kana, şöyle salya sümük

şöyle dişlerimi sıkmadan rahat rahat

“teyzen kanser” dediler, durdum dinledim,

“ameliyat olacakmış” dediklerinde

diyet kolamdan bir yudum aldım, usulca

nedir bu soğukluk, olgunluk numarası mı? 

yoksa fırtınamı sessizlik mi saklıyor? 

içim sıkılıyor içim, içim ağlıyor,

dışım buz gibi duruyor ateşin üstünde

AKS''02', 'bir kabuk bağlamış ki hüznümü  sorma kalkmaz bir türlü en son ne zaman ağladım acaba?  şöyle kana kana, şöyle salya sümük şöyle dişlerimi sı...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/buhran-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinir', 'sinir-kaan-salli-19r20', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu med cezir gibi gelmeler gitmeler

bu sıkıntı içinde geviş getirmeler

şu boğazına birşey takılmış hissi

ve bu yüzden aksırıp öksürmeler...

o adamın mosmor vurdumduymazlığı

o kadının kara duman kiri ahlaksızlığı

şu haylaz çocuğun ağlayıp durması

ve o yüzden kan ter içinde kalmalar...

şu kırık başımın içindeki kırk tilkiler

şu afyonumun bir türlü patlmayışı

sinir ediyor BENİ, SİNİR ediyor beni

ve o yüzden bu sinir dolu şiir yazmalar.

AKS''02', 'bu med cezir gibi gelmeler gitmeler bu sıkıntı içinde geviş getirmeler şu boğazına birşey takılmış hissi ve bu yüzden aksırıp öksürmeler... ...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sinir-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-kaan-salli-ukpbi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir kuyruklu yalanı yaşıyorum

yıllardır kendimden kaçıyorum

kendimi terketmek de zor ama

sonunda yılana kucak açıyorum

gidip gelmeler, durup kalkmalar

yanıp sönmeler, donup kalmalar

hiçbiri hay’ra alamet değil ama

ben etrafa gülücükler saçıyorum 

bakalım nereye kadar bu oyun

ben bu halde bir çobansız koyun

bahar geçti çiçek açamadım ama

farketmez! ben tohuma kaçıyorum

nasıl olur, nasıl dolar bu bardak

nihayetinde hepimizin sonu toprak

yarı yolda inmek de hoş değil ama

ben hemen yolun sonunu istiyorum

“dört kolluda biter” diyorlar “çilen”

oynayan yokken neye yarar hilen

kağıtları da ben dağıtmıştım ama

sürekli oyunu ben kaybediyorum

bitmişim, bitirmişler herhalde beni

inatla kaşıklıyorum kavanozun dibini

az birşey daha çıkıyor benden ama

ben olandan da çok almak istiyorum

AKS''03', 'bir kuyruklu yalanı yaşıyorum yıllardır kendimden kaçıyorum kendimi terketmek de zor ama sonunda yılana kucak açıyorum gidip gelmeler, durup...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-240-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenlere Ağıt', 'gidenlere-agit-kaan-salli-1hsdz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir ömür boyu

bir avuç toprak için ise kavgan

merak etme bir çukur dolusu örtülü olacak üstünde

her gününü, her anını

her aşkını başkası için yaşadıysan 

merak etme başkası olmayacak yatarken çukurunda

yollar üç gün yakın

yollar üç ay sonra yokuş olacak

merak etme yine sen sene kalacaksın mezarında

eller gözler siliyor

eller eller teselli ediyor

merak etme ellerden ırak olacaksın toprak altında

bizim hesap belli

bizim olanla, olmak isteyen bizim

merak etme gözümüz hiç olmadı sizin olanda

sizin hesap önemli

sizin hesapta bizim olan da varsa

merak etme onlar da olmayacak cepsiz kefende

kim ister yenmişi

kim ister taze varken olmuşu

merak etme artık kimse istemez seni karşın alanda 

ölü ağırdır derler

ölü kuşlar kadar hafiftir halbuki

merak etme tüm ağırlığın ahır dünyada kalanda

insan doymaz ister 

insan istedikçe acıkır yine ister

merak etme artık kimsecikler olmayacak yakanda

dünya fani değil

dünya gözü ile gördün ise herşeyi

merak etme hakkın da kalmayacaktır olanda

giden dönmez geri

giden artık ne sever ne sevmez kalanı 

merak etme kalanlar sevecek seni adın her ananda

gül artık üzülme

gül ekeceğiz mezarın üstüne

merak etme bir kul sevap işler suyun dökende

AKS''03', 'bir ömür boyu bir avuç toprak için ise kavgan merak etme bir çukur dolusu örtülü olacak üstünde her gününü, her anını her aşkını başkası içi...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gidenlere-agit-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Musun', 'mutlu-musun-kaan-salli-81112', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'mutlu musun? 

nasıl olur? hani sen sürekli bulutluydun? 

kalbin gürler, gözlerin sağnaktı her zaman

boğazında düğüm düğüm seller

aklında binbir şimşekler

mafsallarında sürekli bir kış sızısı olurdu? 

mutluyum,

hem de çok! sesimden belli değil mi? 

kuşlar cıvıldıyor kalbimdeki kafeste

bahar geldi göğsümdeki soba isine

bir ılık meltem tüm buzlarımı eritti

kadınımın tenini kokladım sabah işe gelirken



mutlu musun? 

nasıl olur? hani sürekli kırılırdın sen? 

daha dün taşmıştı bardağının son damlası

kanamaktaydı hala sırtındaki bıçak yarası

sızlıyordu düşmekten diz kapağın

aklında sürekli binbir tilki koşuyor olurdu? 

mutluyum,

hem de çok! yüzümden belli değil mi? 

çiçeklerim açtı dikenlerimin üstüne

dişlerim gıcırdamıyor ağzımın içinde

bir aşk yağmuru tüm çatlaklarımı kapattı

çocuğumun tenini kokladım sabah işe gelirken

AKS''03', 'mutlu musun?  nasıl olur? hani sen sürekli bulutluydun?  kalbin gürler, gözlerin sağnaktı her zaman boğazında düğüm düğüm seller aklında bin...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mutlu-musun-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Para!', 'para-kaan-salli-3nyxj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'insan satmak ne kolay değil mi

sırlarını şöyle bir üfürüverdin mi 

bütün kapalı kapılar açılır sana

yazıklar olsun paranın altına yatana! 

dünya malı dediğin nedir? dünya ahir

kaldıysa vicdanında toz kadar cevahir

gel uyma sen insanı satan şeytana

yazıklar olsun paranın altına yatana! 

para pul elinin, yalan dilinin kiri

hiç mi insafın yok vicdan fakiri

kanını içtin adamın kana kana

yazıklar olsun paranın altına yatana! 



hepsini koydun kenara sanki yiyecen

biri de seni satmaya kalksa ne diycen

o zaman vuracak taş bulamazsın kafana

yazıklar olsun paranın altına yatana! 

er ya da geç senin de sıran gelecek

derviş dervişe yine sırayla binecek

belki sen de dersin düşünce kapana

yazıklar olsun paranın altına yatana! 

AKS''03', 'insan satmak ne kolay değil mi sırlarını şöyle bir üfürüverdin mi  bütün kapalı kapılar açılır sana yazıklar olsun paranın altına yatana!  d...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/para-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonra', 'sonra-kaan-salli-dullh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hepsi olacak

herşey

ve sonra hepsi ölecek 

hepsi

ama sonra 

birden

aniden

beklediğin ya da beklemediğin bir anda

tekrar 

hepsi olacak

AKS''04', 'hepsi olacak herşey ve sonra hepsi ölecek  hepsi ama sonra  birden aniden beklediğin ya da beklemediğin bir anda tekrar  hepsi olacak AKS''04...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sonra-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Uyuyorum', 'asik-uyuyorum-kaan-salli-jz7ur', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ben sadece seni düşünerek uykuma dalıyorum,

hayattan ancak böyle zevk alıyorum,

yıllar sonra hala böyle düşündürdüğün için bana,

bu gece yine sana aşık uyuyorum…

AKS''05', 'ben sadece seni düşünerek uykuma dalıyorum, hayattan ancak böyle zevk alıyorum, yıllar sonra hala böyle düşündürdüğün için bana, bu gece yin...', ARRAY['Türk Edebiyatı','Şiir','Kaan Salli']::text[], 8.5, '{"poet":"Kaan Salli","poet_slug":"kaan-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/asik-uyuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zakkum ve Gül', 'zakkum-ve-gul-gul-yazganarikan-g0eau', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kokladım seni 

Çektim içime,

Gül tadıydı dolan gönlüme

Birazdan anladım ki 

Tadından

Gül değil zakkum açmış bağrından

 sen uslanmazsın

Önce okşar ellerin

Ardı sıra kaçarsın

Bir bakarım alev olmuş

İçin için yakarsın...

Yanıyorum gel desem

Üste odun atarsın...

Zevk alır dudakların

Sır dolu sözcüklerden,

Göz göze gelmekten çocuk gibi korkarsın

Bedenimiz gelince boşluksuz bir araya

Hırçın çağlayan gibi

Maviliğe akarsın...', 'Kokladım seni  Çektim içime, Gül tadıydı dolan gönlüme Birazdan anladım ki  Tadından Gül değil zakkum açmış bağrından  sen uslanmazsın Önce ...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/zakkum-ve-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Allah Diyerek Namaza Sarıl', 'allah-allah-diyerek-namaza-saril-yusuf-onder-bahceci-dbqkz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğer birini çok sevip alamamışsan,

Alıp ta sen bağrına saramamışsan,

Allah''a yalvarıp sen yakarmışsan,

Allah, Allah diyerek namaza sarıl. 

Dünya''da bir çıkışın kalmamış ise,

Dostların el olmuş sormamış ise,

Paran ve de pulun kalmamış ise,

Allah, Allah diyerek namaza sarıl.

Nefesin daralıp, başın hep ağrırsa,

Ayaklarında ağrı var da uyuşuyorsa,

Her gün köpek gibi saldırıyorlarsa,

Allah, Allah diyerek namaza sarıl.

Görmedim Dünya''da baki kalanı,

Bu Dünya yalan, ömrün geri kalanı,

Kalbinde sevda ateşiyle elin olanı,

Allah, Allah diyerek namaza sarıl.', 'Eğer birini çok sevip alamamışsan, Alıp ta sen bağrına saramamışsan, Allah''a yalvarıp sen yakarmışsan, Allah, Allah diyerek namaza sarıl.  D...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/allah-allah-diyerek-namaza-saril-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su', 'su-arjin-murad-cpxoo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'suyu yazabilmek kağıtlara.... 

suyu yazabilmek kağıtlardan... 

sızabilmek suyun kuytuluklarına (su misali)

ne mümkün yazabilmek seni... 

sensiz ıslanmak ne mümkün... 

ıslatmak gözleri yada kurak bir ömrü... 

ne mümkün... 

su.. 

başlığı yok olamaz bir ömürdür su.. 

su durlumaz... 

dursa isyandır... 

AKsa hayat...

ne mümkün...

ANLA(t) mak seni..', 'suyu yazabilmek kağıtlara....  suyu yazabilmek kağıtlardan...  sızabilmek suyun kuytuluklarına (su misali) ne mümkün yazabilmek seni...  sen...', ARRAY['Türk Edebiyatı','Şiir','Arjin Murad']::text[], 8.5, '{"poet":"Arjin Murad","poet_slug":"arjin-murad","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/su-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağlaması Yok Aşkın', 'saglamasi-yok-askin-tulay-sustam-t0e6k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne zaman

ben ve sen bir araya gelsek

'''' biz '''' olurduk

ne zaman 

sırtımı dönüp gitsem

sen; sen olurdun

ben; hiç olmadığım kadar ben

yani diyorum ki; 

sağlaması yok aşkın

sen olmasan da hayatımda

ben benim, biz yine benim

biliyorum ben olmasam

senden BİZ çıkmayacak', 'ne zaman ben ve sen bir araya gelsek '''' biz '''' olurduk ne zaman  sırtımı dönüp gitsem sen; sen olurdun ben; hiç olmadığım kadar ben yani diy...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/saglamasi-yok-askin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amedea', 'amedea-mehmet-akif-tiryaki-f2zwb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kiraz sevdi dalından Amedea

Maşukiye''de Sapanca Gölü''nün karşısında,

Uzun iki tarafı ağaçlı güneşsiz gölge yollardan geçip

Kiraz bahçesindeki ince ve dar merdivene çıktı,

Koluna taktığı hasır sepete kiraz toplayacaktı

En büyükleri ile ağzını tadlandırdı, onlar baldı,

Ağaçlarda kırmızının tonlarında kızıl noktalar, 

Yeşilin tonlarında yapraklar vardı,

Kirazlar hamrâ ve hümeyrâ''ydı

Maşukiye''de Amedea Napolyon Kirazı topladı....', 'Kiraz sevdi dalından Amedea Maşukiye''de Sapanca Gölü''nün karşısında, Uzun iki tarafı ağaçlı güneşsiz gölge yollardan geçip Kiraz bahçesindek...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/amedea-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birşeyler Var İçimde', 'birseyler-var-i-cimde-yusuf-onder-bahceci-zthkc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni sana bağlayan,

Şu kalbimi dağlayan,

Gece, gündüz ağlayan,

Bir şeyler var içimde.

İnan bende bilmiyorum,

Sabır, sabır diyorum,

Allah''a dualar ediyorum,

Bir şeyler var içimde.

Neden böyle oluyor,

Dünya bize gülmüyor,

Çok sevdiğim sormuyor,

Bir şeyler var içimde.

Aman Allah''ım aman,

Güzel sevdim elaman,

O gözlere dayanamam,

Bir şeyler var içimde....', 'Beni sana bağlayan, Şu kalbimi dağlayan, Gece, gündüz ağlayan, Bir şeyler var içimde. İnan bende bilmiyorum, Sabır, sabır diyorum, Allah''a d...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birseyler-var-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zirvedeki Kartepe', 'zirvedeki-kartepe-mehmet-akif-tiryaki-iw89b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zirvede Kartepe,

Eteklerinde Maşukiye, artistik villalar,

Sessizlik sizi göl manzarasıyla karşılar

Hava cam gibi soğuk ve diri,

Klimanız çalışır tekerleklerde kar zinciri,

Kış mevsiminde karda dağa böyle çıkılır 

Bir saatte Green Otel hedefine varılır.

Aşağılarda da manzaradan faydalanılır.

Zirvede Kartepe, zemin Sapanca Gölü ile kaplı,

Ormanın içinde restorantlarda alabalık saklı

Sapanca''nın içi çarşı,

Antikacılar dizilmiş karşı karşı,

Göl kenarı çaybahçesi

İki çay size Sapanca hediyesi

Düzenleyen aktif başkan İbrahim Uslu

Artık dünya küçük ve çok uluslu

Yakında yabancılar keşf eder Ege''den sonra

Sapanca dağlarında artistik villalar bir başka

Davos neyse Sapanca beş misli,

Göl manzarası yanında dost bahşişi,hediyesi

Sapanca''da yaşanır ikinci bahar evresi,

Hatırımdan çıkmaz Sapanca''nın manzarası her devresi,

Kartepeye açılır küçük evimin iki kanatlı büyük penceresi.', 'Zirvede Kartepe, Eteklerinde Maşukiye, artistik villalar, Sessizlik sizi göl manzarasıyla karşılar Hava cam gibi soğuk ve diri, Klimanız çal...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/zirvedeki-kartepe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicrî Yılbaşınız Mübârek Olsun', 'hicr-yilbasiniz-mub-rek-olsun-mevlut-bicik-27u7z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgili  Dostlar! 

    Bu gün Hicrî 1426 senesinin son günü, yarında Hicrî  1427 senesinin Muharrem-i şerîfinin birinci günü‘dür. Yani bu gece hicrî yılbaşı gece‘sidir. Daha güzel bir ifâdeyle“ Íslâm Âleminin,Müslüman olanların ihyâ ve idrâk ettiği mübârek bir gece‘dir.„

    Íşte bu gün senenin son günü‘dür. Ínsanların amel defterlerinin bir senelik hesâbının kapandığı gün‘dür. Muhâsebe işleriyle meşğûl olan vazîfeli melekler,geçmiş bir senenin hesâbını,kitâbını yapıp,güzellikler ve çirkinliklerle, sevablarla ve günahlarla, hayırlar ve şerlerle yazılı ve resimli olarak doldurduğumuz geçmiş senenin defterini rafa kaldırdığı arşiv‘e bıraktığı bir gündür.

    Yarın ise tertemiz daha hiç el değmemiş içine bir çizgi bile çekilmemiş bir defterin bizim adımıza açıldığı bir gündür. Kâdir-i mutlak olan yüce Rabbîmiz gecmiş senenin defterini hayırlı amellerle kapatmayı,gelecek senenin defterini de hayırlı amellerle açmayı cümlemize nasîb eylesin. 

    Ayrıca! Bu gece bir mazlûmun yüce bir insanın doğup, büyüdüğü, çocukluğunu,gençliğini geçirdiği, nîce hâtırâlara imzasını attığı,nîce taşına toprağına selâm verdiği, canından da daha çok sevdiği vatanından çıkarıldığı, kovulduğu,uzaklaştırıldığı bir gece‘dir.

    O yüce insan; insanların en mükemmeli,beşeriyyetin efendisi,Allah‘ın habîbi,Abdullah‘ın yetîmi Muhammed Mustafa sallallâhü aleyhi vesellem‘den baskaşı değil‘dir.

    Bu gece! O yüce insanın Cennet şehri güzel Mekkeden gözyaşlarıyla ayrıldığı gece‘dir. şöyle Mekkenin dağına çıkıp son kez Allah‘ın evi Kâbe-i Muazzama‘ya yaşlı gözlerle bakıp bakıp“ Vallâhi düşmanlarım çıkarmasalardı ben seni terketmezdim ey Mekke şehri, Vatan,Vatan,Vatan,Vatan sevgisi îmân‘dandır.„vecîzesini söyleyerek yalın ayak, başı açık, boynu bükük bir vaziyyette ayrıldığı, ayrılmaya mecbur bırakıldığı gece‘dir.

    Ayrıca bu gece! Íslâmın dönüm noktasıdır.Zâhirî ve Bâtinî Íslâm devletine doğru giden yolun ilk adımlarının atıldığı gece‘dir.Tam  on senedir çekilen çîlelerin netîcesinde hira mağarasında (islâmın nüvesi,özü olan) tasavvufun,mâneviyyâtın H.z. Ebubekir‘e ögretildigi gece‘dir.Daha nîce nîce hâdiselere sahne olan müstesnâ bir gece‘dir.

    Bu duygularla gece‘miz ve hicrî yılımız mübârek olsun diyorum sevgili dostlar….

Mevlüt Bicik

30.01.2006    saat  15.55    Esslingen', 'Sevgili  Dostlar!      Bu gün Hicrî 1426 senesinin son günü, yarında Hicrî  1427 senesinin Muharrem-i şerîfinin birinci günü‘dür. Yani bu ge...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Bicik']::text[], 8.5, '{"poet":"Mevlüt Bicik","poet_slug":"mevlut-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hicri-yilbasiniz-mubarek-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sapan''da', 'sapan-da-mehmet-akif-tiryaki-l4yqj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimsesiz bir ev buldum Sapan''da

Camları kırık dökük, içerisi soğuk, yıkık

Duvarlar çatlak, banyo ve mutfak derbederdi,

İçimden derlemek toplamak geldi

Bu iş bana göre değil, mecalim tükendi,

Manzara güzel göle bakıyor,

Sırtını Kartepe''ye yaslamış sallanıyor,

Bin metrekare bahçe bahçivan arıyor

Göl manzarası harika gönül baktıkça dinlensin,

Yoruldum dostlar başkaları ilgilensin

Hayat devam ediyor Davos''ta Caracas''da

Acaba hava nasıl Sivas''ta

Maşukiye''de bir bakımsız ev Fethi Bey hasta

Ne günler yaşanmıştı öndeki terasta.', 'Kimsesiz bir ev buldum Sapan''da Camları kırık dökük, içerisi soğuk, yıkık Duvarlar çatlak, banyo ve mutfak derbederdi, İçimden derlemek topl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sapan-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çölleri de Aşarım Dağları da Ben', 'colleri-de-asarim-daglari-da-ben-yusuf-onder-bahceci-6ryl4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir punduna getirirsem yıkarım bu dağları,

Dağlar bana sökmez, aşarım bu dağları,

Mecnun olur da geçerim ben bu çölleri,

Çölleri de aşarım hem dağları da ben.

Önüme serseler çalı, diken ve mayınları,

Ben onları aşarım, hem de karlı dağları,

Bütün Dünya bir olup bana saldırsalar,

Çölleri de aşarım hem dağları da ben.

Okyanuslar kabarsa, gel-gitler oluşsa,

Med-Cezir sökmez bana ister olursa,

Yüce Allah''ım bana vekil, vekil olursa,

Çölleri de aşarım hem dağları da ben.....', 'Bir punduna getirirsem yıkarım bu dağları, Dağlar bana sökmez, aşarım bu dağları, Mecnun olur da geçerim ben bu çölleri, Çölleri de aşarım h...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/colleri-de-asarim-daglari-da-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı..', 'kirmizi-pinar-koc-dpzyn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kırmızı,

Aşk kırmızı

Gül kırmızı,

Ve kan kırmızı…

Gökyüzü ağlarken

Yaş kırmızı…

Gelecek beyaz değil artık,

Ne hayaller yeşil

Ne umutlar mavi…

Aşk kırmızı sadece

Gül kırmızı

Kan kırmızı…..

                                                 16.01.2002     00:12', 'Kırmızı, Aşk kırmızı Gül kırmızı, Ve kan kırmızı… Gökyüzü ağlarken Yaş kırmızı… Gelecek beyaz değil artık, Ne hayaller yeşil Ne umutlar mavi...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kirmizi-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biberonsuz BEBEK', 'biberonsuz-bebek-tulay-sustam-26mde', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gidersem! ...

sütten kesilmiş

bir bebek olacaksın

gönlüm el vermiyor

incirin sütüyle büyümene

kalırsam ne değişecek? 

sadece babasız büyüyecek aşk''ım', 'gidersem! ... sütten kesilmiş bir bebek olacaksın gönlüm el vermiyor incirin sütüyle büyümene kalırsam ne değişecek?  sadece babasız büyüyec...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/biberonsuz-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dostun Şiiri*', 'bir-dostun-siiri-ugur-kilic-ghi3c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk Oyunu

Kalbinde bir köşe bom boş duruyor

Kim bilir kiminle dolacak canan

Uzaktamı yakındamı acaba

Sana bir gün talip olacak canan

Ayakların yere basmaz önceler

Boyanır bir başka renge geceler

Dudakların hep ismini heceler

Aklın daim onda kalacak canan

Bir rüya görürsün gönül yaşında

Uçu verir akıl kalmaz başında

Beyaz atlı prens seni atında

Gezdirip gönlünü çalacak canan

Sahilde gezmeler parkta sohbetler

Gece sinemaya dansa gitmeler

Mum ışıklarında yemek yemeler

Bütün bir gününü alacak canan

Kapıya koşarsın her zil çalınca

Herkesten kaçarsın onsuz kalınca

Bir heyecan başlar akşam olunca

Sevdiğin güllerden alacak canan

Birinci baharda can cana olur

İkinci baharda yan yana olur

Üçüncü baharda o düş kaybolur

Cicim ayları son bulacak canan

Dargınlıklar başlar geçimsizlikler

Bir gün sen küsersin bir gün o küser

O yeşil umutlar o taze hisler

Öyle yavaş yavaş solacak canan

Karışırsın artık çoluk çocuğa

Annelik yaparsın bir yumurcağa

Düşersin sanki bir derin boşluğa

Ellerin saçını yolacak canan

Bazen kıskandırır kadının biri

Boynuna dolanır gönül zinciri

Görünür o eski günlerin yeri

Gözlerin maziye dalacak canan

Uğur ne bilecek doğru olanı

Umarım sonunda çıkar yalanı

Bütün hayatınız olsun balayı

Dualarım senle olacak canan

UĞUR ER

Sevgili abimin yazdığı şiiri sayfamda sizlerle paylaşmaktan onur duydum.....', 'Aşk Oyunu Kalbinde bir köşe bom boş duruyor Kim bilir kiminle dolacak canan Uzaktamı yakındamı acaba Sana bir gün talip olacak canan Ayaklar...', ARRAY['Türk Edebiyatı','Şiir','Uğur Kılıç']::text[], 8.5, '{"poet":"Uğur Kılıç","poet_slug":"ugur-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bir-dostun-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Göz Ağrım', 'i-lk-goz-agrim-serkan-karabulut-hs318', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzak Mısın Şu Sıra Dağlar Kadar, 

Mavi Bir Düşte Gibisin, İyimi Kötümü Bilemedim, 

Vardığımda Bir Noktaya Göreceklerimden Emin Değilim, 

Olsun Sırları Severim Kolaycı Değilim, 

Baharı Bildiğim Gibi Ayazları Da Bilirim.

Bir El Uzatsam Tutacak Mısın? 

Nasıl İhtiyacım Var Sevmeye Sevilmeye 

Beni Sever Misin? 

İster Misin İlk Göz Ağrım.', 'Uzak Mısın Şu Sıra Dağlar Kadar,  Mavi Bir Düşte Gibisin, İyimi Kötümü Bilemedim,  Vardığımda Bir Noktaya Göreceklerimden Emin Değilim,  Ols...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ilk-goz-agrim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salı...', 'sali-pinar-koc-m6uv1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günlerden acı

Günlerden mutsuzluk

Günlerden umutsuzluk

Bu gün günlerden Salı…

Bu gün günlerden perişanlık…

İçime bir pişmanlık saplandığı bu gün

Kurumuş yapraklar gibi döküldüm bu Salı…

Gönlümde mor menekşelerin ağlamaklı ölümü

Sevdalarımda,kayan yıldızların hüzünlü vedası

Ölümümle,mutsuzluğumun garip sonu…

Günlerden acı

Günlerden mutsuzluk

Günlerden umutsuzluk

Bugün günlerden Salı…

Kurumuş yapraklar gibi döküldüm bu Salı….

                                                                 20.08.2001 

                                                                   salı', 'Günlerden acı Günlerden mutsuzluk Günlerden umutsuzluk Bu gün günlerden Salı… Bu gün günlerden perişanlık… İçime bir pişmanlık saplandığı bu...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sali-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennet Gibi', 'cennet-gibi-faruk-tiryaki-vxud5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben seni cennet gibi sevdim boncuk gözlüm.

Artık cenneti merak etmiyorum.

Çünkü cenneti gözlerinde gördüm.

Ben seni cennet gibi sevdim boncuk gözlüm.

Sen benim kaderim, sen benim dilberim,

Sen benim ellerim, sen benim gözlerim,

Sen benim hayatım, herşeyim eşim,nişanlım,sözlüm...

Ben seni cennet gibi sevdim boncuk gözlüm.', 'Ben seni cennet gibi sevdim boncuk gözlüm. Artık cenneti merak etmiyorum. Çünkü cenneti gözlerinde gördüm. Ben seni cennet gibi sevdim boncu...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tiryaki']::text[], 8.5, '{"poet":"Faruk Tiryaki","poet_slug":"faruk-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cennet-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar, Kış. İlkbahar, Yaz', 'sonbahar-kis-i-lkbahar-yaz-hasan-can-yb7g1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yaprağın düşmesiyle başladı sonbahar,

Çırılçıplak soyundu bütün ağaçlar,

Rüzgara karışıp bilinmeyen kuytulara sürüklendi yapraklar,

Sonra yağmur yağdı ıslandı cadde ve sokaklar.

Isının sıfırın altına düşmesiyle başladı karakış,

Fakir bir bedenin üşümesiyle devam etti.

Yavaş yavaş büyüdü çığlıklar içinde haykırış,

Sesler bir yoksulun son nefesiyle kesildi.

Ağaçların yeşermesiyle başladı ilkbahar,

Kış uykusundan uyandı bütün kuşlar,

Çiçeklerin açmasıyla geri döndü umutlar,

Sonra ekmeğin peşine düştü bütün yoksullar.

Güneşin göklere hakim olmasıyla başladı yaz,

Eğlenceler hemen yerini aldı gitar, keman, saz....

Daha dün bir yoksul ibret olmuştu bütün aleme,

Ama unutulmasın ki yazın sonu yine ayaz...', 'Bir yaprağın düşmesiyle başladı sonbahar, Çırılçıplak soyundu bütün ağaçlar, Rüzgara karışıp bilinmeyen kuytulara sürüklendi yapraklar, Sonr...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonbahar-kis-ilkbahar-yaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve seni...', 've-seni-pinar-koc-9l944', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni,

Son kibrit çöpümün ışığıyla,

Yağmur damlalarından topladım 

seni! 

Sonbaharda güneş rengine dönen,

Ve sonra annesinden ayrılan çocuklar gibi

Dallardan dökülen yapraklardan topladım...

Acıların gün batımı esmerliğinde buldum.

Ve seni,

Kırılan aynamın binlerce parçasında kaybettim...

                                                                                    2.10.2002', 'Seni, Son kibrit çöpümün ışığıyla, Yağmur damlalarından topladım  seni!  Sonbaharda güneş rengine dönen, Ve sonra annesinden ayrılan çocukla...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ve-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Habersiz...', 'habersiz-mustafa-okutan-vbtb8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben ise daha neler neler düsüyordum, bizim icin gurbetten silaya

Kurumaya baslayan ellerinden, yari islak topragindan habersiz...

Hayallerim seninle süslenen tablolar, himayenle oturan düzen icindeydi.

Bir gün elbet dönecek senden baslayacaktim hasret gidermeye.

Bedenini kapimizdan iceri girerken evimizde bulacak,

Sesini beni görünce`''Oglum! '' derken agzindan duyacak,

Hasret musluklarini canim ellerinden öperken acacak,

O mis kokunu ise elimdeki haber-i yadigar tesbihinden degil de; 

Sana o heyecan, simsiki sarilinca senden alacaktim, kendimce...

Oysa ki simdi son nefesinden haberdar bicare sana agliyorum.

Senin bedenine, sesine, kokuna özlemle kavusmayi hayal ediyorum...

Bir gün gelecek, bedenini gücler mezarliginda ziyaret edecegimi,

Sesini odana girince gayblerden tilsim tilsim duyacagimi,

Hasret musluklarini annemin ellerinden öperken acacagimi,

O mis kokunu ise, O`na sarilinca, en iyi O`ndan alacagimi biliyorum.

Tecelli olan Allahìn, aci benim. Sabir ver  Yarâb! Sabir Yarâb! ..

Sabrim bana yetmiyor Yaràb.........

02,07,2002 Dorfen/München', 'Ben ise daha neler neler düsüyordum, bizim icin gurbetten silaya Kurumaya baslayan ellerinden, yari islak topragindan habersiz... Hayallerim...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Okutan']::text[], 8.5, '{"poet":"Mustafa Okutan","poet_slug":"mustafa-okutan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/habersiz-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımı Masaya Yatırdım', 'askimi-masaya-yatirdim-sevinc-kavuk-9ooqu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öylesine güzel açımlanmış ki, ben aşk nedir diye 

sormadım hiç böyle, 

aşık olmak diye dile almak istedim, 

benim varlığımın kendisi aşk, aşk ile yaratıldım, 

yaşam yolumda yenilendirili aşkla gideceğim... 

lakin burada noktalandı bu mübarek konu

şöyle okurken; 

aşk nedir sorarsan (virgül)    gönlümce (virgül)     

odaklandım bu gönlümce´de...

anlat bana anlayayım diye geçirdim içimden, 

aklımca, mantığımca; 

o an ve o durumu / kişiyi / olayı / tutumu gibi anlarım sadece, 

gönül gözüm de bakar tabii, 

anlamak istemez onu, 

yani ona geçerli olamayacağı imiş, 

ama aklımca, mantığımca hala

o an´ı, o durumu / olayı anlamamış da olmuyorum... 

gönül gözüm 

ahh ne seçici, ne özel, ne duyumlu ve duyarlı, 

hem de ne özen beklentili.... 

Beynim, mantığım, aklım ama 

alıngan değil, seçici değil, 

ona istediğim kadar ödev vereyim hepsiyle ilgilenir mübarek, 

doymak bile bilmiyor üstelik, 

sırça parmağını ver elini ister, kolunu ver bedenini, 

dahasını da dahasını…

taa ki organiksel yavaşlamaya, 

yorgunluğa yüz tutuncaya kadar... 

ama gönül gözüm hala dinç, hala seçici, hala özel, hala....

o, 

doymak, meşgul olmak için değil, 

o, 

sadece ona hitabede başarılı ender yüceliği alıyor, 

yorulmadığı bundan mıdır diye az mı sordum kendime....

Gönlümcesi bu dersem, 

şu aşk, ahh şu aşk, 

beni öyle yoruyor ki, 

içimi onunla yaşıyor ama anlatamıyorum onu...

dilime almama niye böyle imtina eder bilmem... 

aşk, yaşam yolumda soluduğum her nefeste, 

uykumda bile benim varlığım, 

kükrüyorum bu aşk, küsüyorum bu aşk, 

seviyorum bu aşk, 

açlıktan midem kazılıyor bu aşk, 

gülücüklerden sevinç duyuyorum bu aşk, 

ölümüne razıyım (yaşamadım ama, yine de öyledir)    bu aşk... 

''Sen Mükemmelsin''  BiR  aşk o, 

o „sen mükemmelsin” 

her canlı varlık için geçerli olmak şartıyla, 

o sen

ben de oluyorum aynı zamanda, 

işte aşkların en güzel duyumu 

bu ''Sen Mükemmelsin''´de uyaklı huzuru....

Evet aşk bu! Ben niye yazamaz mışım? 

Bal gibide yazarım bu aşkı, hem de doya doya, 

katık da ederim gönlümceyi canım istedikçe, hınzırlığım tuttukça... 

Arap saçı, haham curcunası, hınzır pazarı, şeytan gıdıklaması

bunlar da hepsi birer aşk

Ben anladım galiba aşk´ı...

Ne diyorsunuz buna şimdi....? 

Haa, ileriye gitmek yok, burda dur! 

Bunu kendine sor, sen kendine, kendi sen´ine sor! 

Başkasını masaya yatırdığın zaman sorabilirsin böyle! 

Mimar operatör doktor! hanımefendinin

hadi geçmiş olsun, masaya yatırdığı aşk ameliyatı 

en samimi güzelliğe buluşan başarıyla geçti! 

2006......Aşk yılıma merhaba!', 'Öylesine güzel açımlanmış ki, ben aşk nedir diye  sormadım hiç böyle,  aşık olmak diye dile almak istedim,  benim varlığımın kendisi aşk, aş...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/askimi-masaya-yatirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana bir masal anlat', 'bana-bir-masal-anlat-mikdat-bal-194jh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana bir masal anlat 

Maziyle uyut beni

Kulaklarımı çınlat

Uyutma avut beni

Gönlüm bir başka atar

Ruhum güzellik tadar

Renklerime renk katar

Bir başka boyut beni 

Perileri prensesle

Hafif hafif bir sesle

Hızlı hızlı nefesle

Söylerken unut beni

Yalanlardan kaçılsın

Gözüm gönlüm açılsın

Neşe, Sevinç saçılsın

Kaplasın umut beni

Kalpten kalbe akarak

Bir uyur bir bakarak

Bülbül gülde şakarak

Anlatsın “Hudhud” beni

Söz olsam ahit olsam

Buna bir şahit olsam

Yolunda şehit olsam

Taşır mı ” Uhud” beni', 'Bana bir masal anlat  Maziyle uyut beni Kulaklarımı çınlat Uyutma avut beni Gönlüm bir başka atar Ruhum güzellik tadar Renklerime renk katar...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bana-bir-masal-anlat-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Umduk Ne Bulduk', 'ne-umduk-ne-bulduk-yilmaz-turkyilmaz-zb9oe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne umduk ne bulduk görmüyor musun? 

Varıp kapınızı çalabilseydim! 

Şu garibi yoksa sevmiyor musun? 

Aşktan mutluluğu tadabilseydim! 

Sen olmadan neye yarar bu dünya? 

İçimi dağlayan gözlerin var ya! 

Zamanla unutup yaşardım güya

Candan hasretini atabilseydim! 

Kuş olsaydım pencerene konardım,

Ateş olup yüreğinde yanardım,

Çektiklerim için hesap sorardım,

Feleği yakasından tutabilseydim! ? 

Kalbinde bir köşe arar bulurdum.

Gözlerimi kapar hayâl kururdum,

Sonsuza dek bir tek senin olurdum,

Göz göze muhabbet kapabilseydim! ? 

Sen tatlı uykuda bense nöbette

Hayır, şer, gizlidir her bir sebepte

Çok şey değişirdi çok şey elbette,

O gece koynunda kalabilseydim! ? 

Nazlıdır sevdalar sevgidir bazen

Aşıktır kalemi şairdir yazan

Bir elime geçse bu aşkı bozan

TÜRKYILMAZ zannedip kızabilseydim! ? 

                                                        25-01-2006 ANTALYA', 'Ne umduk ne bulduk görmüyor musun?  Varıp kapınızı çalabilseydim!  Şu garibi yoksa sevmiyor musun?  Aşktan mutluluğu tadabilseydim!  Sen olm...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ne-umduk-ne-bulduk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utandım', 'utandim-yilmaz-turkyilmaz-vhzn7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyor musunuz ben! ? 

Atom ilmini; 

Savaş alanlarında kullanan,

Amerikalı olmaktan utandım…

İhtilâl yapıyorum diye,

Öz kardeşlerinin boynuna,

Giyotin indiren Fransız olmaktan utandım…

Hitler gibi bir liderle,

Irkçı bir Alman olmaktan utandım…

Bir İtalyan olaraktan; 

Mafyalarla yönetilen,

Bir ülke olmaktan utandım…

Demokrasinin beşiği İngiltere’de; 

Krallıkla yönetilen İngiliz olmaktan utandım…

Boğaları öldüren İspanyolluğumdan,

Dünyaya kapalı Rusluğumdan,

Tembel uyuşuk Araplığımdan,

Kapalı tekdüze Çinliliğimden utandım…

Türk doğmamla gurur duydum.

Yerli malı kullanmamaktan,

Dayı selamıyla iş görmekten,

Kirli gezmekten,

Sevmeyi bile becerememekten! ? 

Çalışmaktan çok kibirlenmekten utandım…

Başka ülkeleri kucaklayıp,

Kendi vatandaşlarımı pataklamaktan utandım…

Sahipsiz öldü Karafatmalar, 

Daha nice destan yazanlar! ! ! 

Köylümü kışt''lamaktan,

Memurumu fişlemekten,

İşçimi dışlamaktan,

Öğrencimi haşlamaktan utandım...

Her güzelin mutlaka bir kusuru var görürsen! 

Vesselâm; 

Dünyanın her neresinde olursak olalım,

Fark etmeyen insanlığımdan utandım…

          Yılmaz TÜRKYILMAZ

         03.08.1988 / ANKARA

         (GÜZEL DOST adlı şiir kitabından.)', 'Biliyor musunuz ben! ?  Atom ilmini;  Savaş alanlarında kullanan, Amerikalı olmaktan utandım… İhtilâl yapıyorum diye, Öz kardeşlerinin boynu...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/utandim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efendim', 'efendim-yilmaz-turkyilmaz-m4y8v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seyret güzelliği neler görürsün! ? 

Güzellikten, güzel yansır efendim.

Kâmilin gönlünde sevgi bulursun,

Cahil gönlündeki pastır efendim.

İyilik yapmayı silme gönlünden,

Hakkın kelâmını kesme dilinden,

Kendini hep kolla zalim elinden,

Kötüler dünyada çoktur efendim.

Dünyanın nimeti bitmez ha bitmez,

Yaşamayı becer bak ele geçmez,

Akıllı iki kez hataya düşmez! 

Kimisi örnektir, tektir efendim.

Doğru olan canım harama bakmaz,

Hak''kı seven hey dost bir cana kıymaz,

Haram yiyen mikrop asla hiç doymaz,

Helâl yiyen kişi toktur efendim.

Yüce dağ başından kar eksik olmaz,

Kâinat bir giz’dir sır eksik olmaz! 

TÜRKYILMAZ gönlünden yâr eksik olmaz,

Pîr’in içi dışı Hâk’tır efendim.

                                                          

              15.03.1997 / Ghedi - İTALYA', 'Seyret güzelliği neler görürsün! ?  Güzellikten, güzel yansır efendim. Kâmilin gönlünde sevgi bulursun, Cahil gönlündeki pastır efendim. İyi...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/efendim-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör/ebe...', 'kor-ebe-ugur-deniz-ulkegul-b5qo1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düştün 

Gözümden

En sıcak iklimlerin çöl rüzgarı

Savurdu düşlerimden

Omzuna dağılmış ipek saçları…

Düştün

Sözümden

Devrik cümlelerin sorguları

Sildi gülüşlerimden

Sen kokan yarınsız baharları…

Delirme noktası bir menzil

Aklımı çelen üryan geceler

Dudağımda yarım kalırken heceler…

Çırılçıplak bir kadın

Üzerini örttüğüm sevişmeler,

Ve senin şen şakrak duran korkuların…

Gidişim kadar yoksul bakan

Bilişim gibi ürkek ve sokulgan

Sana kal diyen çelimsiz duyguların

Kıskacında büyür  gölgeler……….

Sen bakar bir kadın

Sen kokar bir çocuk

Sen kadar azalır içimde

Gittikçe büyüyen çokluk…

Hesapsız sevmelerin suçudur

Kitapsız cümlelerin yosma kalışı

Kırılan bir kalem hükmünde yenik

Bir sevişmelik anıdan ibaret aldanışı..

Köhne bir ağaç gölgesinde

Hüzünbaz öfkelerde yaz-geç/er

İntihara meyilli bir zaman ertesinde

Bir adam, bütün korkulardan vazgeçer…

Kimsesiz bir yaşamak sancısıdır

Kimliksiz kalmak telaşıdır sözün

Girilen kavgaların bilmem kaçıncısıdır…

Ağır yaralıdır yollar

Ölümcül yalnızlıklar sabaha gebe

Çocuksu bir düşten kalmadır aşk

Büyüdükçe anlar bunu kör/ebe......', 'Düştün  Gözümden En sıcak iklimlerin çöl rüzgarı Savurdu düşlerimden Omzuna dağılmış ipek saçları… Düştün Sözümden Devrik cümlelerin sorgula...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/kor-ebe-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antalya''m', 'antalya-m-yilmaz-turkyilmaz-tgrj5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu şehir duru mavi deniziyle doğal,

Bu şehir karlı dağlara mecbur,

Bu şehir yeşilliğe doymaz,

Bu şehirde kötü bir şey olmaz,

Bu şehrin güzellerine doyum olmaz,

Bu şehirde hiçbir şeyin kaybolmaz,

Bu şehre kar yağmaz, soğuk olmaz,

Bu şehirde çiçekler solmaz,

Nice umutlara gebe bu şehir! ? 

Bu şehir güzel yaşamlara layık.

Turunç limon bu şehir,

Altın portakal bu şehir,

Bu şehir günlük güneşlik.

Tam bize göre bu şehir! 

Tadında kadeh gibi bir dikimlik,

Sevdaları ciğerine işler adamın! 

Bu şehir tam sevişmelik...', 'Bu şehir duru mavi deniziyle doğal, Bu şehir karlı dağlara mecbur, Bu şehir yeşilliğe doymaz, Bu şehirde kötü bir şey olmaz, Bu şehrin güzel...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/antalya-m-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can İncinmesin', 'can-i-ncinmesin-yilmaz-turkyilmaz-fl1oh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerini kapamış da uyumuş,

Gönül nefesin tut, can incinmesin.

Hele bakın; masum güzel can imiş! 

Bir nazar kıl narin can incinmesin.

Yanağından al gülleri dereyim,

Ellerinden derde şifa bulayım,

Gözlerine baka baka öleyim,

Yavaş uyan kirpik kaş incinmesin.

Deler geçer gözler bana bakınca,

Duman tüter gönül aşka yanınca,

Sen de beni seviyorsun kanımca! ? 

Uzat kollarını el incinmesin.

Salın da gel boylarına bakayım,

Gerdanına inci mercan takayım,

Ellerine al kınalar yakayım,

Tara zülüfleri tel incinmesin.

Yâr ben senin için tutuldum derde,

Güzelliğin açtı gözümde perde,

TÜRKYILMAZ adını anar her yerde,

Senden benden bir tek kul incinmesin.', 'Gözlerini kapamış da uyumuş, Gönül nefesin tut, can incinmesin. Hele bakın; masum güzel can imiş!  Bir nazar kıl narin can incinmesin. Yanağ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/can-incinmesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuğum', 'cocugum-yilmaz-turkyilmaz-y7qli', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çocuğum! 

Sen daha gençsin.

Yarın; mutlaka, kesin kez gelecek.

Ama yarınlara beslediğin umutların,

Tamı tamına gelmeyecek…

Çok bekletileceksin,

Çok atlatılacaksın,

Çok aldanacaksın,

Analog bir saatin kadranı gibi; 

Hayatın bazen Oniki’lerdeki gibi zirvede olacak.

Bazen de Altı’larda sayacaksın çıldırırcasına.

Dibe vurmak zor be çocuğum,

Varlıktan, sağlıktan olmak çok zor…

Dostluğu kaybetmek zor,

Güven yitirmek, dikiş tutturmamak zor.

En iyisi zirveye yakın yerler! 

En iyisi kimselere muhtaç olmadan,

En iyisi yolun yolsuza düşmeden,

En iyisi gücün dirayetin varken,

En iyisi eşin dostun sağken,

En iyisi itibarın var iken,

En iyisi sevgi saygı görürken be çocuğum.

Barışık, sağlıklı ve huzurlu ol.

Gelecek; kaygan zemin gibidir be çocuğum.

Hiçbir şeyin garantisi yoktur.

Varlığın ve duyguların kadar güzel ol! 

Oldu mu be çocuğum! ! ! ...', 'Çocuğum!  Sen daha gençsin. Yarın; mutlaka, kesin kez gelecek. Ama yarınlara beslediğin umutların, Tamı tamına gelmeyecek… Çok bekletileceks...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/cocugum-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Erenler', 'hey-erenler-yilmaz-turkyilmaz-37g42', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hey Erenler bir sözüm var! 

Yol oğluyum yola geldim.

Hakkın sevdası özümde,

Çiçek açtım dala geldim.

Ariflere malım vardır,

Alan aldığı kadardır.

Dostluğum dosta şifadır,

Öldüm öldüm cana geldim.

Sözüm bazen öze işler,

Sözüm var ki gözden düşer,

Sevdiklerim üçer beşer,

Kaçtı benden sona geldim.

Kimine dedim sultanım,

Kimine dedim mihmanım,

Kimini gördüm düşmanım! ? 

Saçlarımı yolageldim.

Alıp satmak işim değil,

Kâr eylemek düşüm değil,

Haram lokma aşım değil,

Ne paraya pula geldim.

TÜRKYILMAZ ‘ım doğru özüm,

Budaktan sakınmam gözüm,

Bazı yanık çalar sazım! ? 

Türkülerle dile geldim.', 'Hey Erenler bir sözüm var!  Yol oğluyum yola geldim. Hakkın sevdası özümde, Çiçek açtım dala geldim. Ariflere malım vardır, Alan aldığı kada...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hey-erenler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Sökülmüş Gülmelerim Kanasın / Dudaklarında...', 'sokulmus-gulmelerim-kanasin-dudaklarinda-i-mdat-ozcan-4yrln', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidiyorum 

Bu kutlu sevdayı yüreğime sarıp 

Zemheriler kuşanarak 

Gidiyorum 

Sökülmüş gülmelerim kanasın dudaklarında 

Yüreğim yüreğinde sürgün kalsın 

Attığım her adımda daha bir üşüyorum 

Her adımda daha bir kanıyor yerin kalbi 

Her adımda daha çok ölüyorum 

Gidiyorum 

Puslu sabahlar tenhasına 

Suratımda ki izine inat dudaklarının 

Eylüller öfkesini ellerime alarak 

Gözyaşı hatırına 

Şakağımdan sızan kana ant olsun 

Ölüm bir uğrak köşe başı 

Canımı kattığım cana ant olsun 

Solmuş bir tebessüm ufukta 

Siyah beyaz resimler yollara serpilmiş 

Gidiyorum 

Çığlıklar barındırarak suskunluğumda 

Attığım her adımda daha bir inliyor zaman 

Her adımda daha bir yanıyorum 

Her adımda zehir dolu bir tas 

Her adımda daha çok kanıyorum 

Çiy düşmüş sokaklar üşüşür üzerime 

Kaldırımlar paramparça 

Gidiyorum 

Yokluğunu ömrüme dolayıp 

Genç bir intihar vuslatına 

Bahar değmeden gözlerime 

Gidiyorum 

Bahar değmeden yüreğime 

Gidiyorum… 

21/11/2005 - Kartal', 'Gidiyorum  Bu kutlu sevdayı yüreğime sarıp  Zemheriler kuşanarak  Gidiyorum  Sökülmüş gülmelerim kanasın dudaklarında  Yüreğim yüreğinde sür...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sokulmus-gulmelerim-kanasin-dudaklarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni uzaktan sevmek (1)', 'seni-uzaktan-sevmek-1-esin-cinar-ubwjn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni uzaktan sevmek (1) 

''Seni uzaktan sevmek aşkların en güzeli'' diyordu şair.

Yanına yaklaşmaya imkan olmayan bir güzelliğe hasret böyle güzel anlatılır. 

Bende seni hep uzaktan sevdim,asla cesaret edip sevdiğimi söyleyemedim. 

Mümkün olup ta sevgine ulaşamadım,kalbine girip de içinde dolaşamadım. 

Kendi halimde ellerim ceplerimde yanlızlığın azabıyla dolaşırken. 

Yaşam boşluklarımı senin hayallerinle doldurup avunurum. 

Ama ne yaparsam yapayım o şarkıdaki en güzel şeye ulaşamıyorum. 

Ne güzün ne baharda ne yazın nede kışta, ellerini elimle,bellerini kolumla 

Sarıp dolaşamıyorum. 

Seni uzaktan sevmeyi ben yalnız yaşıyorum.

Belki de ömür boyu karşılıksız olarak sevmeyi sürdürecek bir kalbi taşıyorum. 

Seni uzaktan sevmek aşkların en güzeli demek bana yetmiyor. 

Elimdeki sadece,seni uzaktan sevmek,fakat hasret bitmiyor.

Yarattığım hayalin gözlerimden gitmiyor.

Cesaretim sevgimin yarısı kadar olsaydı böyle uzaktan sevmez. 

Gördüğüm her yerde gırtlağımı patlatır aşkımı haykırırdım. 

Olsun,bütün gerçeklere rağmen ben seni ümitsizce seviyorum. 

Ve ne yapacağım,inanki bilmiyorum. 

Şair haklı çıksın diye. 

Elimden gelen tek şey,uzağa gidiyorum.

Kalbim kabul etmiyor ama beynim biliyor.

Her kalb birgün gelince başka kalbi seviyor.

Biliyorum ki sen de benim gibi bir gün birisini görecek ve beğeneceksin. 

Belki de görmüş ve beğenmişsindir. 

Eğer öyleyse veya öyle olacaksa umarım hiç bir zaman uzaktan sevmezsin. 

Sevdiğinin sevgisiyle birlikte el ele diz dize şairi yalancı çıkartırsın. 

Ümit fakirin ekmeği,sevenin sevgisinden sonra her şeyi. 

Olurya belki sende öğrenir beni uzaklardan çağırırsın. 

Şaire inat olsun hep yanımda kalırsın. 

Seni yakından sevmek aşkların en güzeli diyerek haykırırsın. 

Esin Çınar

(28.03.2005 / 30.01.2006)', 'Seni uzaktan sevmek (1)  ''Seni uzaktan sevmek aşkların en güzeli'' diyordu şair. Yanına yaklaşmaya imkan olmayan bir güzelliğe hasret böyle g...', ARRAY['Türk Edebiyatı','Şiir','Esin Çınar']::text[], 8.5, '{"poet":"Esin Çınar","poet_slug":"esin-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/seni-uzaktan-sevmek-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlarım', 'dostlarim-yilmaz-turkyilmaz-fgt20', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Doğrudur, dürüsttür, sahte değiller.

Sevgi deryasına bütün meyiller! 

Evliyâlar, Enbiyâlar, Velîler

Dostlarım da benim güzel dostlarım.

Eliyle koymazsa onu almazlar

Cahilce söylenip gönül yıkmazlar

Helâlden gayrıya uçkur çözmezler

Dostlarım da benim güzel dostlarım.

Nazımı çekerler, surat etmezler

Binbir söz söylesem güce gitmezler

Önümden ardımdan atıp tutmazlar

Dostlarım da benim güzel dostlarım.

İkiliği yoktur birde dururlar

İnsan gibi doğup insan kalırlar

Mustafa Kemal''i önder bilirler

(Muhammet Ali''yi ulu bilirler) 

Dostlarım da benim güzel dostlarım.

Enginden söylenen sözleri yüce

Yaşlılara saygı, sevgiler gence

Şu iki cihanda herşeyden önce

Dostlarım da benim güzel dostlarım.

Kin ile silahla işleri yoktur

Birçoğu gariptir dertleri çoktur

TÜRKYILMAZ dostlara övgü lâyıktır

Dostlarım da benim güzel dostlarım.

            24.08.1994 / İZMİR

            (GÜZEL DOST adlı şiir kitabından.)', 'Doğrudur, dürüsttür, sahte değiller. Sevgi deryasına bütün meyiller!  Evliyâlar, Enbiyâlar, Velîler Dostlarım da benim güzel dostlarım. Eliy...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dostlarim-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu memleket', 'bu-memleket-lokman-ali-yavuz-inf6o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasıl derim ki bizimdir bu memleket.

''Soğuğu'' da Sibirya’dan bu memleket.

Satıldı ne varsa, yalana yılana,

Bize böyle mi kaldı ki bu memleket?', 'Nasıl derim ki bizimdir bu memleket. ''Soğuğu'' da Sibirya’dan bu memleket. Satıldı ne varsa, yalana yılana, Bize böyle mi kaldı ki bu memleke...', ARRAY['Türk Edebiyatı','Şiir','Lokman Ali Yavuz']::text[], 8.5, '{"poet":"Lokman Ali Yavuz","poet_slug":"lokman-ali-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bu-memleket-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delice şeyler', 'delice-seyler-zati-erbas-3vihb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'buz

tutmuş

bir 

şehri

ne kadar ısıtabilir ki kalbim.

bana

sorsanız

her şeyi yapabilir.

düşünsenize

sarıp 

sarmalanmayı

sımsıcak

bir 

yürekle.

bu gece

şehirden hiç farkım 

yok

yok ama

hep delice şeyler var içimde.', 'buz tutmuş bir  şehri ne kadar ısıtabilir ki kalbim. bana sorsanız her şeyi yapabilir. düşünsenize sarıp  sarmalanmayı sımsıcak bir  yürekle...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/delice-seyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan mıydı?', 'yalan-miydi-yilmaz-turkyilmaz-78hea', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalan mıydı el ele tutuştuğumuz? 

Yalan mıydı çok evvelden tanıştığımız? 

Yalan mıydı köpük, köpük sel gibi coştuğumuz? 

Yalan mıydı? ...

                     

                        Yalan mıydı söyle zalimin kızı! ? 

                        Yalan mıydı içindeki sızı? 

                        Yalan mıydı sen koyuuun, ben kuzu? 

                        Ardından meleştiğim yalan mıydı? ...

Yalan mıydı tutuşup ta yandığın? 

Yalan mıydı seni canım sandığım? 

Yalan mıydı seninle uyandığım, yalan mıydı? ...

        Yalan mıydı gül yüzünde Güneşim? 

         Yalan mıydı ''hani yoktu bir eşim? ''

         Yalan mıydı yüreğinde ateşim? 

         Söyle ha! Yalan mıydı? ...

Yalan mıydı kahvemde çıkan fallar? 

Yalan mıydı bir çocuğa masallar? 

Yalan mıydı mutlu, seven insanlar? 

Haydi söyle! 

Yalan mıydı? ...

          Yılmaz TÜRKYILMAZ

          05.12.1996 /  ESKİŞEHİR

          (GÜZEL DOST adlı şiir kitabından.)', 'Yalan mıydı el ele tutuştuğumuz?  Yalan mıydı çok evvelden tanıştığımız?  Yalan mıydı köpük, köpük sel gibi coştuğumuz?  Yalan mıydı? ...   ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yalan-miydi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana can veriyorum', 'sana-can-veriyorum-durdu-mehmet-dalkanat-38e36', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(sevgili E.S e) 

Göklerden gelen bir armağansa kurban,

En sevgiliye en sevdiğini feda etmekse eğer,

Sana can veriyorum.

Bitmeyen bir sevdanın adağıysa,

Eğer kurban,

Sana kendimi adıyorum.

Biliyorum ki senin kucağın diriliş kucağıdır.

Sana kurban olmak,

Yeniden hayat bulmak demektir.

Senin adağın olmak,

Kaybolmaya yüztutmuş bir yaşam sevincine,

Ve yaşam heyecanına,

yeniden kavuşmak demektir.

Bayram...

Adağın sahibine ulaştığı günse eğer,

Kutlu olsun.

Avuçlarına...

Çırpınan bir yüreğin teslim olduğu bir zaman dilimiyse eğer,

mübarek olsun.

Herkes yeniden hayat bulsun,

yeniden yaşama tutunsun,

Bir sevda kucağı bulsun herkes kendine,

Feda edebileceği birşeyleri olsun,

feda edilebilen birşeyler bulunsun,

ki yaşam yeniden yeşersin,

Gözyaşları sevinç olsun.

Bayramsa eğer bu bayram

Böyle bir bayram olsun', '(sevgili E.S e)  Göklerden gelen bir armağansa kurban, En sevgiliye en sevdiğini feda etmekse eğer, Sana can veriyorum. Bitmeyen bir sevdanı...', ARRAY['Türk Edebiyatı','Şiir','Durdu Mehmet Dalkanat']::text[], 8.5, '{"poet":"Durdu Mehmet Dalkanat","poet_slug":"durdu-mehmet-dalkanat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sana-can-veriyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak', 'toprak-huseyin-sonmez-86pt0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karşılıksız sevmeyi 

Sen öğretttin,

Cömertçe önümüze serdin

Tüm güzellikleri,

Bağrına bastın uyuttun,

Bir ana şevkati gösterdin

Bize.

Hep o uluların

Üzerine bıraktığı ize 

Bakarak yürüdük

Yıllarca.

Bıkmadan usanmadan

Aylarca.

Üzerine bir damla bıraktık

Bir umman verdin.

Ocağımıza dirliği,

Bereketi serdin.

Hanlar yaptık üzerine

Yolcu konakladı

Dert konakladı

Derman verdin.

Barajlar yaptık

Su konakladı

Gözyaşı konakladı

Hayat verdin.

Ağaçlar diktik 

Orman konakladı,

Can verdin

Kan verdin.

Senden gelip sana giderken

Sessiz şehirde

Yurt verdin..

Damla damla her zerren

Ağladı.

Halin nice diyemedik

Yok muydu acaba

Senin derdin? 

Yıllarca

Kıymetini bilemedik.', 'Karşılıksız sevmeyi  Sen öğretttin, Cömertçe önümüze serdin Tüm güzellikleri, Bağrına bastın uyuttun, Bir ana şevkati gösterdin Bize. Hep o ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/toprak-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biran Yalnızlık', 'biran-yalnizlik-erkan-akarcay-z0l3s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bıraktım kağıdı kalemi, yaslandım arkama.

Ama nerdeee..

Biraz soluklanayim, bir bardak taze çay ve yanında sigara,

''Ne iyi Olurdu.'' dediğim anda..

Kalemim küsmüş, kağıtlar suratını buruşturmuştu adeta,

Bir bebek alırsın kucağına, sararsın sımsıkı,

Mırıldanırsın kulağına ezik ses tonuyla ninniler..

Sonra biran için uyuduğunu düşünerekden,

bırakırsın usulca yatağına,

Işıği kapatıp, tam odadan çıkacakken,

Önce bir inilti sesi duyar,

''Eyvah..'' demeye kalmadan yırtar kendini o karanlik Odada..

O minicik yüreği nasıl alışsın senden biran uzak kalmaya..

Bir ihtiyar kadın düşün; 

Parkda oturmuş, sakin vede sessiz,..sessiz,

etrafında olup bitenleri, genclik dönemindeki,

o fıkır..fıkır genc kızlık dönemindeki yaşantısını,

Şimdiki zamanla kıyaslarcasına, 

etrafına attığı yorgun bakışlı o ihtiyar kadını düşün..

Yanina gelicek, karşısında oturan, birbirlerine kur yapan çifti görüp,

''Teyzecim senin zamanında nasıldı.? '' 

diye... soracak birine ihtiyaç duymaz mı sence.? duymaz mı.? 

Sonucta yediden yetmişe herkes muhtaç,

Herkes aç bu ömrünün sonuna dek,

beklediği ilgiye, sevgiye..

Sonuçta biranlık yalnız kalmak istemez mi hiçkimse..? 

Birilerinin geriye dönüp, birdaha bırakmamacasına,

Sımsıkı sarılmasını beklemez mi..? 

Bekler delicesine.. bekler elbetde..

Hernekadar söyleyemeyip için içini yesede,

Birilerinin yanına çağırmasını bekler her seferinde,

bekler..

Ben şuanda biryandan çayımı yudumlayıp,

sigaramı ağır ağır çekerken,

Bana biranlık küsen kalemim ve suratını buruşturmuş kağıtlarımın yanına,

Biran yalnız bıraktığım çayım ve sigaramı davet ettim sadece...

Siz bunu söyleyemesenizde, ben söylüyorum işte size,

Kağıdım, kalemim, çayım ve sigaram ve birde düşüncelerim,

Sizlerden hiç ayrı kalabilir miyim hı.? kalabilir miyim..? 

Peki ya bu yazdıklarımı paylaştığım,

Sesimi duyurduğum sizler; 

Peki ya siz..

siz bu sözlerim sona erdikden sonra,

Biran yalnız bıraktıklarınız, ne yapiyordur..diye düşündünüzmü hiç..? 

Vakit geçmeden yapman gerekeni yap,

Çünkü geriye döndüğünde, herşey bıraktığın gibi kalmayabilir...

Web Site        :  http://www.erkanakarcay.com

İletişim: [email protected]', 'Bıraktım kağıdı kalemi, yaslandım arkama. Ama nerdeee.. Biraz soluklanayim, bir bardak taze çay ve yanında sigara, ''Ne iyi Olurdu.'' dediğim ...', ARRAY['Türk Edebiyatı','Şiir','Erkan Akarçay']::text[], 8.5, '{"poet":"Erkan Akarçay","poet_slug":"erkan-akarcay","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/biran-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kır Gezintisi', 'bir-kir-gezintisi-huseyin-sonmez-zsfad', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün kırlarda dolaştım

Tek başıma.

Çimenler arasında koşarak

Bir ağacın gölgesinde yatarak

Dallardaki kuşlarla konuşarak,

Dalıp gittim.

Sonra; 

Küçük taşları göle atarak

Hareler oluşturdum.

Balıklara bakarak

Konuştum.

Çiğdem topladım.

Oradan oraya koşarak

Hopladım.

Rengârenk çiçekleri kokladım.

Tatlı tatlı esen meltemi

Ciğerlerime sakladım.

Bugün kırlarda

Tek başıma dolaştım

Kuzularını otlatan çobanın

Karşı köydeki camiden hocanın

Sesi yankılandı

Kırlarda.

İçim içime sığmıyordu bugün.

Mutluydum

Umutluydum

Güzelliği,

Sevgiyi 

İçtim 

Hep 

Yudum yudum...', 'Bugün kırlarda dolaştım Tek başıma. Çimenler arasında koşarak Bir ağacın gölgesinde yatarak Dallardaki kuşlarla konuşarak, Dalıp gittim. Son...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-kir-gezintisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni mi Resmini mi seçmeli?', 'seni-mi-resmini-mi-secmeli-faruk-tiryaki-wan71', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günümde sen, gündüzümde sen,

Uykumda sen, uykusuz her gecemde sen, 

Dilimde sen, hecemde sen,

Aklımda sen, fikrimde sen,

Gözümde sen, heryerde sen,

Yatağımda sen, Hayatımda sen,

Ve sen ey resim...

Hayatımın her anında olsanda seni yırtamıyorum.

Çerçevemden çıkardım ama içimden çıkartamıyorum.

Bazen düşünüyorum; 

Acaba seni mi?  Yoksa Sahibini mi seviyorum....? 

Ve Biliyorum; 

Sahibin gitti ama

Sen hep yanımda olacaksın.

Mezarımda bile beni yalnız bırakmayacaksın....', 'Günümde sen, gündüzümde sen, Uykumda sen, uykusuz her gecemde sen,  Dilimde sen, hecemde sen, Aklımda sen, fikrimde sen, Gözümde sen, heryer...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tiryaki']::text[], 8.5, '{"poet":"Faruk Tiryaki","poet_slug":"faruk-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-mi-resmini-mi-secmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerim Icin', 'askerim-icin-sezen-akoluk-8p9lj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Asker olmak zor olsa gerek,

gün saymalar bitmez bu bir gercek,

yok başka bir secenek,

merak etme, beklemeler bitecek.

Senin için zor olduğu gibi 

benim içinde çok zor,

aglamaktan gözlerim oldu mosmor,

sevdan oldu içimde bir kor.

En önemli görevi yapmaktasın,

biliyorum yemeklerden kusmaktasın,

telefonda, hasretten susmaktasın,

geceler havaya bakip 

uyumaya calışmaktasın.

Yolunu gözler gözlerim bilesin

Burnumda tüter mektupların

Koynumda saklı satırların

Dillerimden düşmüyor hatıraların', 'Asker olmak zor olsa gerek, gün saymalar bitmez bu bir gercek, yok başka bir secenek, merak etme, beklemeler bitecek. Senin için zor olduğu ...', ARRAY['Türk Edebiyatı','Şiir','Sezen Akoluk']::text[], 8.5, '{"poet":"Sezen Akoluk","poet_slug":"sezen-akoluk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/askerim-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötü Dünya', 'kotu-dunya-sezen-akoluk-bj79t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağa cıkıp bagırmak

Hayata haykırmak

Yeni bir dünya kurmak

Geliyor içimden.

Memnun degilim bu hayattan

Bıktım sagın solun laflarından

Tek umudum sevdamdan

O da memnun degil bu durumdan

Kim memnun ki şimdi ki zamandan? 

Gecilmiyor yoldan, acılan yaralardan

Günlük yaşanan sevdalardan

Bıktım artık bu yaşam tarzından! 

Gelmeyin üstüme yalanlarla

Boynumu büker giderim hayattan

Bıktırdınız hayat dolu dünyamdan

Dünyam güzel kötü dünyanınzdan…', 'Dağa cıkıp bagırmak Hayata haykırmak Yeni bir dünya kurmak Geliyor içimden. Memnun degilim bu hayattan Bıktım sagın solun laflarından Tek um...', ARRAY['Türk Edebiyatı','Şiir','Sezen Akoluk']::text[], 8.5, '{"poet":"Sezen Akoluk","poet_slug":"sezen-akoluk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kotu-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dermansız Bir Yara', 'dermansiz-bir-yara-mehmet-koc-2-jgmah', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dermansız Bir Yara

Gidişin normalin çok çok üstünde.

Dermansız bir yara açtın da gittin.	

Karışıklık varmış senin sütünde.

Dermansız bir yara açtın da gitin.

Divane ettin sen uykularımı.

Harabe ettin sen duygularımı.

Tarumar ettin sen kaygılarımı,

Dermansız bir yara açtın da gittin.

Şimdi mekanlarım köşe başları.

Yatağımı sorma parke taşları.

Aramam aylardır sıcak aşları.

Dermansız bir yara açtın da gittin.

Gülmek yasaklandı mahşere kadar.

Dert adına bende ne istersen var.

Bir gün vereceğim kendime zarar.

Dermansız bir yara açtın da gitin. 

		KOÇBEY KOÇ.', 'Dermansız Bir Yara Gidişin normalin çok çok üstünde. Dermansız bir yara açtın da gittin.	 Karışıklık varmış senin sütünde. Dermansız bir yar...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Koç 2']::text[], 8.5, '{"poet":"Mehmet Koç 2","poet_slug":"mehmet-koc-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dermansiz-bir-yara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O''nun Gözleri Denizdi', 'o-nun-gozleri-denizdi-seyfet-bozcali-yplbe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O''nu öğle gördüm öğle tanıdım,

Deniz gibi parlaktı ve durgundu,

Masmavi Ummanlar gibiydi.

Her baktığımda içinde kayboluyordum,

O''nun gözleri denizdi...

Kalbim huzuru onda buluyordu,

Gözlerim ona bakmaktan,

Doymuyordu.

Aşkım içinde yüzüp duruyordu,

Herşeyi içinde hapsediyordu,

O''nun gözleri denizdi...

Martılar onun üzerinde uçuyordu özgürce,

Yakamozlar sevgimizi kıpraştırıyordu sessizce.

Seven aşıklar üzerinde sandallarla seyre çıkardı.

Mehtabı içine çekerdi,

Güneş gibi kalbime ısıtırdı.

Çocukluğum tertemiz aşkı onda saklıydı,

Delikanlılığımın baş kaldırışını,

o teskin ediyordo.

Her yerde onu görüyor,

her yerde onu duyuyordum,

O''nun gözleri denizdi...

Hiç dalgalandığını,

köpürüp, coştuğunu görmedim.

Sevgi saklı bir hazine gibiydi,

Yok ediyordu kini,nefreti,

Gönlümün tek kadını,

İlk aşkım,Sultanım

Beni hep Mahkum etti,

otuz yıldır  o gözlere

Aşkımı,benliğimi sırlarımı

sakladı masmavi derinliğinde,

O''nun gözleri denizdi...

            19.05.2006', 'O''nu öğle gördüm öğle tanıdım, Deniz gibi parlaktı ve durgundu, Masmavi Ummanlar gibiydi. Her baktığımda içinde kayboluyordum, O''nun gözleri...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/o-nun-gozleri-denizdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Felek.', 'vefasiz-felek-mehmet-koc-2-2s2pr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vefasız Felek.

Mutluluk adına herşeyim vardı.

Gecem ayrı güzel,kışım bahardı.

Birden etrafımı bir ateş sardı.

Aldı neşeleri vefasız felek.

Bu genç ne haldeydi,nasıldı kimdi.

Meçhule giden yol önümde şimdi.

Neşemi bir sülük misali emdi.

Aldı huzurumu vefasız felek.

Bakmaz oldum aynalara korkumdan.

Hergün bin işkence sağdan solumdan.

Çarem hiç kalmadı artık ölümden.

Aldı genç ömrümü vefasız felek,

Şimdi isyanlarla doldu dillerim.

Titrek tüm vicudum titrek ellerim.

Habersiz ölürsem özür dilerim.

Aldı benden beni vefasız felek.

              KOÇBEY KOÇ', 'Vefasız Felek. Mutluluk adına herşeyim vardı. Gecem ayrı güzel,kışım bahardı. Birden etrafımı bir ateş sardı. Aldı neşeleri vefasız felek. B...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Koç 2']::text[], 8.5, '{"poet":"Mehmet Koç 2","poet_slug":"mehmet-koc-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/vefasiz-felek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göçmen kızı', 'gocmen-kizi-durdu-mehmet-dalkanat-e8xi9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sıra bana ilişme can.

 Dokunma sakın titreyen etime.

 Söyleme..

 Söyleme bir çift söz.

 göç almış yüreğime.

 Her yanıma yürüyen, dört cihetten akın var.

 Yığın yığın üstüme devrilen,

 acı haykırışlar var.

 Dokunma! ..

 Söyleme! ..

 her karem bir bamteli.

 Sakın ha! ...

 Yaklaşma! ..

 hücrelerim gözyaşıma ayarlı,

 Parça tesirli bombalar.

 İnfilaklar pusu kurmuş.

 Bendedir.

 Dertler genlerimi mesken tutmuş.

 İçtedir.

 Göçler öbek öbek çadır dikmiş.

 Direkleri bendedir.

 Çile kervanları yollarıma çıkmış,

 Hanları içtedir.

 Bana hucum üstüne hucum var.

 Kır saçlı,eli bastonlu pir dünya,

 Hüzün tarihini tablo yapmış,

 Çakmış üstüme.

 Dokunma! ..

 Boşalacağım.

 Değme sakın! ..

 Kurumuş hazan yaprağıyım.

 Döküleceğim.

 Hucum üstüne hucum devam ediyor.

 Bitmek yok diyen göçler bana geliyor.

 Göçmenler....

 Çölün kumundan çok göçmenler.

 Hala bana yürüyor.

 Promoteus, ardında Zeus un hışmıyla,

 Bana koşuyor.

 Brahmanların ayağından düşen shadonlar,

 kollarıma kaçıyor. 

 Gök ve tüm yıldızlar,

 Erimiş maden,

 yağıyorlar saçlarımın tellerine.

 Sakın ha! ..

 Değme! ..

 Değme yanarsın! ..

 Parmakların ip ince kemiklerine vurur da,

 göçmen kızı

 Tırnaklarından start alan bir acı yürür,

 İşler canına canına.

 Erirsin..

 Dirhem, dirhem erirsin..

 Yudum yudum içer seni ateş.

 sende bitersin.', 'Bu sıra bana ilişme can.  Dokunma sakın titreyen etime.  Söyleme..  Söyleme bir çift söz.  göç almış yüreğime.  Her yanıma yürüyen, dört cih...', ARRAY['Türk Edebiyatı','Şiir','Durdu Mehmet Dalkanat']::text[], 8.5, '{"poet":"Durdu Mehmet Dalkanat","poet_slug":"durdu-mehmet-dalkanat","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/gocmen-kizi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar mı Olur?', 'bahar-mi-olur-mehmet-koc-2-r8ir7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bahar mı Olur? 

Güneş doğsa parlak,açsa çiçekler 

Uçuşsa neşeyle kuşlar böcekler

Sensiz bu dünyama ne edecekler

Söyle sene sensiz bahar mı olur.

Ruhsuz bir bedenin bende ruhusun.

Geçilmesi en zor güzel duygusun

Bende can ne ise işte sen busun

Söyle sene sensiz bahar mı olur

Tadı mı kalırmış gülmelerimin

Adı mı kalırmış neşelerimin

Canımı kalırmış hücrelerimin

Söyle sene sensiz bahar mı olur.

Hem kafam beynimsin bu bedenimde

Damar damar sensinherbir tenimde

Sadece sen varsın tüm evrenimde

Söyle sene sensiz bahar mı olure.

Düşünmek saçmadır sensiz dünyayı

Varlığın zor olsa seçmem kolayı

İyi anla bendeki bu olayı

Söyle sene sensiz bahar mı olur.

              KOÇBEY KOÇ.', 'Bahar mı Olur?  Güneş doğsa parlak,açsa çiçekler  Uçuşsa neşeyle kuşlar böcekler Sensiz bu dünyama ne edecekler Söyle sene sensiz bahar mı o...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Koç 2']::text[], 8.5, '{"poet":"Mehmet Koç 2","poet_slug":"mehmet-koc-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bahar-mi-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Sorma', 'sakin-sorma-seyfet-bozcali-tey06', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çile ile geçti gençlik yıllarım,

Ötesini sakın sorma! 

Ana özlemiyle o çocuk günlerim,

O çocukluk günlerimi hiç sorma...

Çatlak ayaklı,

Yanık suratlı,

Yırtık gömlekli,

Sığır,koyun,kaz güden,

Çocuğu hiç mi hiç sorma....

Gençliğimde etmediğim ibadeti,

Mevla''mın verdiği,

Şükretmeden  tükettiğim nimeti,

Dünya için çektiğim zahmeti,

Nankörlük eden adamı hiç sorma! 

Çek git.......

            25.10.1985', 'Çile ile geçti gençlik yıllarım, Ötesini sakın sorma!  Ana özlemiyle o çocuk günlerim, O çocukluk günlerimi hiç sorma... Çatlak ayaklı, Yanı...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sakin-sorma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Kız', 'kara-kiz-gulden-isik-rxyie', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'evin ilk çocuğu kız dı

ilk göz ağrısı derler ya

--olamadı.

helvacıda paket sarsın diye

orta okuldan alındı.

evlendirildiğinde de

henüz,

-on altı yaşındaydı.

ikincisi oğlan oldu

aman Allah’ım! 

evlere neşe doldu.

büyütüldü er kişi denilerek

gittiği yerler,

-mekanı oldu.

üçüncüsü kara kızdı

oğlandan sonra

hiçte olmadı.

yakıştığından

adı da,

-kara kız kaldı

o da,

her alınganlığında

bunu yanlış anladı

dördüncüsü yine kız dı

sarışın mavi gözlü

-farklıydı.

bebek güzelliğinde

her şey onda ballanırdı.

son gözdesiydi evin

bunu anladığınca 

anlatmakta,

--kullandı

2006', 'evin ilk çocuğu kız dı ilk göz ağrısı derler ya --olamadı. helvacıda paket sarsın diye orta okuldan alındı. evlendirildiğinde de henüz, -on ...', ARRAY['Türk Edebiyatı','Şiir','Gülden Işık']::text[], 8.5, '{"poet":"Gülden Işık","poet_slug":"gulden-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kara-kiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıyı Şımartmayın', 'aciyi-simartmayin-gulden-isik-6ftni', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Açın dem kapısını

Hoşgörüye yol verin 

Unutmayın sevmeleri

Nefreti de erteleyin

Bugün yarında biter

Şimdileri yaşayın

Ömür nefestir yiter 

Acıyı şımartmayın.

1998-güfte', 'Açın dem kapısını Hoşgörüye yol verin  Unutmayın sevmeleri Nefreti de erteleyin Bugün yarında biter Şimdileri yaşayın Ömür nefestir yiter  A...', ARRAY['Türk Edebiyatı','Şiir','Gülden Işık']::text[], 8.5, '{"poet":"Gülden Işık","poet_slug":"gulden-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aciyi-simartmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekirdek Yiyenlere', 'cekirdek-yiyenlere-gulden-isik-hnb86', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'iyi güzel..

oturmuşsun denize karşı 

püfür püfür rüzgar tadında.. 

gamsızca çekirdek çitletiyorsun. 

iyi de be güzelim 

neden yere atıyorsun !

sadece çekirdek olsa iyi; 

içtiğin sigara izmaritini 

bitirdiğin su şişesini 

hatta ekmek arası çöpünü de

daha önceden atmışsın. 

bir şey desem olmuyor

demesem hiç olmuyor

sen sefanı sürerken

oh ne ala ne ala! 

ben sana kızgın bakmaktan 

manzara bana zehir 

zıkkım oluyor. 

vallahi de... billahi de 

senin gibiler beni

deli ediyor. 

2006', 'iyi güzel.. oturmuşsun denize karşı  püfür püfür rüzgar tadında..  gamsızca çekirdek çitletiyorsun.  iyi de be güzelim  neden yere atıyorsun...', ARRAY['Türk Edebiyatı','Şiir','Gülden Işık']::text[], 8.5, '{"poet":"Gülden Işık","poet_slug":"gulden-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cekirdek-yiyenlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükretmek Çok Güzel', 'sukretmek-cok-guzel-seyfet-bozcali-m3drl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akıl verdin,göz verdin,izan verdin,

Yanında güler yüz,tatlı söz verdin,

Dileklerim zamanından tez verdin,

Şükretmek çok güzel Allah''ım seni....

Aşık olduğum Saliha eş verdin,

Yuva verdin,nimet verdin aş verdin,

Nimetlere can katan yağış verdin,

Şükretmek çok güzel Allah''ım seni....

Öğretmen mesleğini sen layık gördün,

Çocuk sevgisini kalbime koydun,

Dua ettim şükretmekten doymadım,

Şükretmek çok güzel Allah''ım seni...

01.03.1979', 'Akıl verdin,göz verdin,izan verdin, Yanında güler yüz,tatlı söz verdin, Dileklerim zamanından tez verdin, Şükretmek çok güzel Allah''ım seni....', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sukretmek-cok-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmasan', 'olmasan-gulden-isik-e4vjc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uykularımdasın…

yalnızlığımdasın…

düşerse kaybolacak

göz yaşlarımdasın

kimse göremez seni bende

kimse anlayamaz

suskunluğumdasın.

karanlıkta ışığım olmasan

isyanlarda bayrağım olmasan

olmasan var ya olmasan

sen benim utancımsın…

sen benim yüzkaramsın

2001', 'uykularımdasın… yalnızlığımdasın… düşerse kaybolacak göz yaşlarımdasın kimse göremez seni bende kimse anlayamaz suskunluğumdasın. karanlıkta...', ARRAY['Türk Edebiyatı','Şiir','Gülden Işık']::text[], 8.5, '{"poet":"Gülden Işık","poet_slug":"gulden-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olmasan-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtirazım Var', 'i-tirazim-var-gulden-isik-1pzfs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kadının karnından sıpayı 

sırtından da sopayı 

eksik etmeyin'''' i öğreten

o çok bilmiş dillere

itirazım var! 

 ‘’kadın evin hamalı

dış kapının mandalı 

birde kaşık düşmanı’’

diyen ata sözlere... 

itirazım var! 

törelere sığınıp

namus için hak sanıp

kanı kanla yıkayıp

temizlenen ellere

itirazım var! 

bir tek erkeği sayan

kızı el yerine koyan

hep kadını sınayan

çileli ömürlere

itirazım var! 

 ana yoldaş bacıyken 

gül gibi sevmeyene

‘’önce erkek’’ diyerek

hakkını vermeyene

2004', 'kadının karnından sıpayı  sırtından da sopayı  eksik etmeyin'''' i öğreten o çok bilmiş dillere itirazım var!   ‘’kadın evin hamalı dış kapını...', ARRAY['Türk Edebiyatı','Şiir','Gülden Işık']::text[], 8.5, '{"poet":"Gülden Işık","poet_slug":"gulden-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/itirazim-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Ver Gitsin', 'bos-ver-gitsin-seyfet-bozcali-2nqc8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kulun ayıbını yüzüne vurma,

O nu gören görür üstünde durma,

Boş şeyler düşünüp kafanı yorma,

Boş ver gitsin ötesini arama.

Hak hukukun çiğneyenler olacak,

Alay edip üzerine gülecek,

Hasetlikler,iftiralar olacak,

Bilen,bilir ötesini arama.

Yeter ki sen sarıl Hak''kın özüne,

Kulak asma,cahillerin sözüne,

Resulüm''ün sünnetine izine,

Sür yüzünü ötesini arama...

              12.10.1995', 'Kulun ayıbını yüzüne vurma, O nu gören görür üstünde durma, Boş şeyler düşünüp kafanı yorma, Boş ver gitsin ötesini arama. Hak hukukun çiğne...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bos-ver-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-muzaffer-alcinkaya-z0h82', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmur yağar ince ince

Sen kokar toprak

Islanırım yürürken

Kokun sarar bedenimi

Dayanamam toprak olurum.', 'Yağmur yağar ince ince Sen kokar toprak Islanırım yürürken Kokun sarar bedenimi Dayanamam toprak olurum....', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Alçınkaya']::text[], 8.5, '{"poet":"Muzaffer Alçınkaya","poet_slug":"muzaffer-alcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yagmur-259-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz sönerim', 'sensiz-sonerim-hasan-emre-kocak-04kgn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben  sabah  gibiyim

Ben  akşam  gibiyim

Sensiz  ben  deliyim...', 'Ben  sabah  gibiyim Ben  akşam  gibiyim Sensiz  ben  deliyim......', ARRAY['Türk Edebiyatı','Şiir','Hasan Emre Koçak']::text[], 8.5, '{"poet":"Hasan Emre Koçak","poet_slug":"hasan-emre-kocak","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sensiz-sonerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Rüya Görsem', 'bir-ruya-gorsem-seyfet-bozcali-03iiq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasretiğle yanıpta tutuştuğum,

Hayelimde Gül yüzünü sevdiğim,

Gül üstünde kokusunu bildiğim,

Resulüm''le dolu bir rüya görsem...

O''nun  aşkı ile aşık olduğum,

Hayatın okuyup hayran kaldığım,

Ümmetine merhametin bildiğim,

Habibim''le dolu bir rüya görsem...

Ya Rabbim son arzum kutsal Medine,

Sevgisiz yüreği getirir dile,

Görüp te ölmeye razıyım bile,

Resulüm''le dolu bir rüya  görsem...

30.01.2006', 'Hasretiğle yanıpta tutuştuğum, Hayelimde Gül yüzünü sevdiğim, Gül üstünde kokusunu bildiğim, Resulüm''le dolu bir rüya görsem... O''nun  aşkı ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-ruya-gorsem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Treni Kaçırma', 'son-treni-kacirma-seyfet-bozcali-m93bi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelen geçti,yerinde duran var mı? 

Ne beklersin,beklemen sana kar mı? 

Gitmiş olsan, kimse arar sorar mı? 

Yol yakınken, son treni kaçırma...

Belki hayatının son dakikası,

Veren vermiş o sayılı nefesi,

Dönmez tren alır gider herkesi,

Ömrün varken son treni kaçırma...', 'Gelen geçti,yerinde duran var mı?  Ne beklersin,beklemen sana kar mı?  Gitmiş olsan, kimse arar sorar mı?  Yol yakınken, son treni kaçırma.....', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/son-treni-kacirma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesap Ortada', 'hesap-ortada-muzaffer-alcinkaya-goq32', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllardır benden gizlediğin aşkı sonunda başkasınamı verdin

Geçilmez dediğin o dağlardan şimdi kimler geçiyor

Beni bugüne kadar avuturken, yalanlarınla kandırırken

Yarınlardaki umutların hesabını şimdi  kimler verecek

Bir yalan üzerine kurulmuş umutlar,hayaller,dünyamız

Sen ve Ben yani biz yokmuşuz aslında

Sen ve O varmış yani siz.......

Ben yıllarca kendimi kandırmış, sana inanmışım

Şimdi söyle ben nerde yanlış yaptım

Kimlere vereyim geçen zamanın hesabını

Yoksa senin de dediğin gibi hesap ortadamı....', 'Yıllardır benden gizlediğin aşkı sonunda başkasınamı verdin Geçilmez dediğin o dağlardan şimdi kimler geçiyor Beni bugüne kadar avuturken, y...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Alçınkaya']::text[], 8.5, '{"poet":"Muzaffer Alçınkaya","poet_slug":"muzaffer-alcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hesap-ortada-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynadaki Adama', 'aynadaki-adama-kadir-alanli-dm8i3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hey oradaki 

Sana söylüyorum 

Boyun bir yetmiş beş gibi

Bönbön bakıyorsun doğan güne

Öyle bir bakıyorsunki sanki salağın dik allası

Estafirullah özür dilerim siz salak değilsiniz

Kocaman bir ahmaksınız

Hani bir insan bu kadarmı korkar sevmekten

Kollarını açmış beklerken sevgiliden kaçmak neden

Aşk yok, gerçek aşk yok diyorsun 

Bilmezmisin gecenim en kötü vakti getirir sabahı

en çok yanıldın; demek yakın gerçek aşkın zamanı

Ne kadar yaşadın, ne gördün ve ne biliyorsun

Kaç sevda geçti gönlünden 

Daha yirmisinde koşuyorsun hayatın

Tamam ölüm yakın

Günşe merhaba de hadi

Şimdi sevmenin vakti

Sev sev hadi 

Güneşi ayı

Geceyi ve günü

Yarını ve dünü 

Sev  sev hadi', 'Hey oradaki  Sana söylüyorum  Boyun bir yetmiş beş gibi Bönbön bakıyorsun doğan güne Öyle bir bakıyorsunki sanki salağın dik allası Estafiru...', ARRAY['Türk Edebiyatı','Şiir','Kadir Alanlı']::text[], 8.5, '{"poet":"Kadir Alanlı","poet_slug":"kadir-alanli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aynadaki-adama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk gençliği İbrahim Çoşar''ın Bitmiş gençliğim bitmiş şiirine ithafen', 'turk-gencligi-i-brahim-cosar-in-bitmis-gencligim-bitmis-siirine-ithafen-mikdat-bal-l1cyc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu millet necip millet bağrında güller açan 

Ne mutlu Türk’üm diyor, yaşasın Türk gençliği 

Her şeyinde karar var, ifrat tefritten kaçan 

Bu fetreti kazasız, aşasın Türk gençliği 

Tarihin sahnesinde yerimiz var bilesin 

Vatanına kem gözle bakanlara silesin 

Bendine sığmazsın sen, bir kendine gelesin 

Elinde bayrak ile koşasın Türk gençliği 

Ataların yolundan yürüyecek an senin 

Muhtaç olduğun kudret damarında kan senin 

Tek umudumuz sensin, övgü senin şan senin 

Her Türk bir asker doğar, paşasın Türk gençliği 

Ona başka bir gençlik, ne denktir ne de eştir 

Tek başına kalsa da dünyayla dişe diştir

Kendine döner dönmez yapacağı ilk iştir 

Emperyalist bağları boşasın Türk gençliği 

Tüm dünya birlik oldu seni yıkamadılar 

Özündedir cevherin ona bakamadılar 

Gereği gibi sana sahip çıkamadılar 

Sana çılgın diyene şaşasın Türk gençliği 

Oku ve kültürünü günden güne ilerlet 

Öyle bir uyanış ki düşmanları deli  et 

Haykır dünyaya karşı hedefini belirlet “

İman ile sevgiyle taşasın Türk gençliği 

Özünü bilmeyenler, sayar bir kaç hatanı 

”Bir Türk dünya ya bedel”, kendini iyi tanı 

Vatan sana emanet, şad edesin atanı 

Ne ele köle, ne de maşasın Türk gençliği 

Mikdat der, dünya senden öğrendi adaleti 

İlim en büyük silah, yıkalım cehaleti 

Sende hâlâ mevcuttur ecdadın asaleti 

Bu duygu her yanını kuşatsın Türk gençliği', 'Bu millet necip millet bağrında güller açan  Ne mutlu Türk’üm diyor, yaşasın Türk gençliği  Her şeyinde karar var, ifrat tefritten kaçan  Bu...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/turk-gencligi-ibrahim-cosar-in-bitmis-gencligim-bitmis-siirine-ithafen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyorum', 'agliyorum-atilla-kizilkaya-3ln7y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece yine sessizdi 

Düşlerimdeydin yine 

Eski bir şiir gibi 

Yokluğundu beni kahreden 

Bu zifiri karanlıkta 

Bıkmıyordum seni satırlara yazmaya 

Gece senin gibi sessizdi 

Irmaklar kurumuştu 

Kuşlar dahi suskundu yokluğunda 

Ne ay nede yıldızlar aydınlatıyordu 

Yolumu 

Bir sigara yakıyorum 

Nefes nefes seni içtiğim 

Ve haykırıyorum gökyüzüne 

SENİ SEVİYORUM diye 

Ama sen duymuyorsun 

Issız bir tepeden seyrediyorum 

Sensiz olan olan bu şehri

Ağlıyorum...', 'Gece yine sessizdi  Düşlerimdeydin yine  Eski bir şiir gibi  Yokluğundu beni kahreden  Bu zifiri karanlıkta  Bıkmıyordum seni satırlara yazm...', ARRAY['Türk Edebiyatı','Şiir','Atilla Kızılkaya']::text[], 8.5, '{"poet":"Atilla Kızılkaya","poet_slug":"atilla-kizilkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/agliyorum-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Handan', 'bu-handan-seyfet-bozcali-ibl0t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu handan ah bu handan,

Gelen geçer bu handan,

Ayrılmak zor gelirse,

Geçemezsin bu candan.

Yolcular dolar taşar,

Pek çok olaylar yaşar,

Çoğu toruna düşer,

Çıkamazsın bu handan...

         30.03.1998', 'Bu handan ah bu handan, Gelen geçer bu handan, Ayrılmak zor gelirse, Geçemezsin bu candan. Yolcular dolar taşar, Pek çok olaylar yaşar, Çoğu...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bu-handan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GiderkenArdından/Bakarken/Leylâ''ya', 'giderkenardindan-bakarken-leyl-ya-yilmaz-helimergin-u54it', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'I- Son Anlar...

Atar bir damar gibi her vakti sayar gibi,

Bu elveda ve gidiş sanki hezeyan gibi...

-II-Giderken...

Sanma isyan ve feryat sanma intizarımdır,

Acı günde od bulan beden yanışlarımdır.

Dünyalık ayrılığa sözlü itirazımdır,

Gönül ahında yanan hasret buğularımdır.

Bir ahlı figan kopar adı hasret takılır,

Sonra ayaz süsünde düşe hayal katılır.

Ömrü yoran can solur ölüm bahar sanılır,

Eyvah ölür ah kalır kara haber dağılır.

Buz renkli sokaklara yaz havası saklanır,

Kar düşer, beyaz yağar buygun meltem ayılır

Kuru, yorgun kabuslar matem rengi kaplanır.

Söz ve dile takılan bir vah, eyvah anılır

Közlü buz yamacında ahu, efgan satılır

Belki harp alanında her an üryan kalınır,

Sensiz doğan sanılar özlü hicran sayılır.

O gününün isyanında bin dert göğe salınır,

Duman yanar can tüter zaman akar gün biter,

Senden arta kalanlar borçlu bir veda alır.

An ve zan bana yürür yaşadığım gün gider,

Son güldüğün yüz bir de hatırımda gül kalır.

II- Ardından...

Kaynar denizden geçip sıratı biçer gibi,

Keşti gamdan vazgeçip ebedi seçer gibi,

Zahirin kucağında panzehir içer gibi; 

Bir esriyiştir gitti can elimden yiterken.

Gönlüme ahu güldü, hasret yağdı tenime

Dört duvar oldu umman özlem sardı evime,

Hayal sığ bulut doldu hicran vurdu bendime,

Görünüp te gül ziyan güneş gibi batarken.

Bembeyaz anıtlara kazınan yazıt gibi,

Açık kapı önünde gerilmiş engel gibi,

Yaşanmamış anılar çoktan yaşanmış gibi; 

Yüreğe mil çekilip gönül feryat ederken.

Milyon kere söylenen tövbeler unutuldu,

Baharım güz olmadan umutlar kurutuldu,

Son nefesin an suyu sanki erken yutuldu,

Yeşeren yazgılarım kansız kalıp solarken.

Mercan kayalığında görmeden yaşar gibi,

Dertlerin yamacından kementsiz geçer gibi,

Sancılar sancısını umarsız seçer gibi,

Karanlığa kapıldım gün az önce doğarken.

Yeryüzü yağmur yağdı gökyüzüme sel vardı

Dağlar suya karıştı, denizler alev aldı

Hırçın yaralar gibi bedeni ölüm sardı,

Duraklandı hayatım sen bu elden giderken...

(Şimdi yanma vakti...)    

 	30.01.2006 21:24:00', 'I- Son Anlar... Atar bir damar gibi her vakti sayar gibi, Bu elveda ve gidiş sanki hezeyan gibi... -II-Giderken... Sanma isyan ve feryat san...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Helimergin']::text[], 8.5, '{"poet":"Yılmaz Helimergin","poet_slug":"yilmaz-helimergin","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/giderkenardindan-bakarken-leyla-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen özlem', 'bitmeyen-ozlem-durdu-mehmet-dalkanat-jaw24', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni arıyordu hala.... 

Gözlerin.

tayflar püskürten, gözlerin.

Değil mi anne...

Bir esintinin bağrından düşüp,

Kapını çalacak diye...

Bekliyordun...

Ben öperken çileli saçlarından...

sen.

Şefkatinle eritecektin...

Zindanda don tutmuş yüreğimi,

Öyle mi anne.....

Artık...

il il....

ilçe ilçe.....

Sürüklenmeyecektin...

peşimden....

Asık suratlı beton duvarlarda,

Ve zebani kılıklı,

Yaratıklar elinde açılan.. 

İğreti kapılarda... 

Hüznü giyinmeyecektin.

Öyle mi...

Bitecekmiydi gerçekten...

gün gün...

Ay ay...

Yıl yıl...

Büyüyen...

Dağ dağ olan...

Ve mektup zarflarına sığmaz olan..

Özlem leğenin de yuğrulmuş,

Hasret....

Bitecekmiydi anne...', 'Beni arıyordu hala....  Gözlerin. tayflar püskürten, gözlerin. Değil mi anne... Bir esintinin bağrından düşüp, Kapını çalacak diye... Bekliy...', ARRAY['Türk Edebiyatı','Şiir','Durdu Mehmet Dalkanat']::text[], 8.5, '{"poet":"Durdu Mehmet Dalkanat","poet_slug":"durdu-mehmet-dalkanat","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bitmeyen-ozlem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül, Dualar ve Sabır', 'gonul-dualar-ve-sabir-muhsin-yener-qt3u3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönül…

bir arayışın adıdır geceden sabaha.

Yanılır, düşer, kalkar

ama yine de doğruyu arar durur.

Biz biliriz ki

doğru, her zaman bağırmaz insana.

Bazen bir suskunlukta gizlenir,

bazen bir gözyaşının içinde.

Dualar…

göğe bırakılmış en ağır emanetlerdir.

Düşmez, kaybolmaz,

sadece vakti gelince iner kalbe.

Umudumuz baki…

çünkü biz biliriz:

Karanlık, sabrın gölgesinden ibarettir.

Ve sabır…

bir bekleyiş değil yalnızca,

Allah’a teslim edilmiş bir yürüyüştür.

Rabbimiz…

en güzel hediyesini

en geciken vakitte verir.

Çünkü bilir:

insan, aceleyle değil

imtihanla olgunlaşır.

Biz de yürürüz…

dizlerimizde yorgunluk,

kalbimizde dua…

ama gözümüzde inatla parlayan bir ışıkla.

Muhsin yener', 'Gönül… bir arayışın adıdır geceden sabaha. Yanılır, düşer, kalkar ama yine de doğruyu arar durur. Biz biliriz ki doğru, her zaman bağırmaz i...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener']::text[], 8.5, '{"poet":"Muhsin Yener","poet_slug":"muhsin-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ben-olmayacagim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-suheyla-kurnaz-yi784', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gidiyorum Akdeniz’in incisi 

Hoşçakal.

Bir daha dönmem geri

Ne verdin ki bana, geldiğim günden beri? 

Gidiyorum…

Tüm   güllerimi  koparıp gidiyorum.

Gençliğimi,

Sevgilerimi,

Arzularımı 

Bütün anılarımı,

Her gamda döktüğüm siyah saçlarımı

Sabahı olmayan yanlız gecelerimi…

Her şeyimi feda edipte gidiyorum.

Ey çılgın Toroslar! 

Alın, yüreğimi kopardım yerinden 

Öksüz sevdamı göğsünüze dayayıp,

Sarabilirseniz size vereyim? 

Ya siz bulutlar? 

Alın, 

Alın heybemdeki tüm ağıtlarımı,

Taşıyabilirseniz size vereyim? 

Gidiyorum 

Hoşçakalın dağ, taş ve bulutlar…

Gidiyorum ey sevgili! 

Ümitlerimi sana bırakıp gidiyorum.

Sevda bağına düşünce

Bülbülün figanı nafile…

Anlatamadım sana sevdamı

Tut ki,

Bir baharda  sana olan aşkımı yaşadın, hissettin 

Artık  nafile… 

Şimdi garip bir serçeyim

Bir sapan taşının sancısıyla

Gidiyorum…

Bütün acılarımı bırakarak, 

Toprak kokusu saran bedenimi, 

Yaralı kanatlarımla sürükleyerek gidiyorum

Hoşçakal yüreğimin nar çiçeği

Ben…

Cennet güllerini koklamaya gidiyorum…

01.01.2006

SuheylaKurnaz.com - Kişisel Web Sitem

SuheylaKurnaz.com - Kişisel blog Sayfam

Yorum: Ömer Aykan (Bursa Yerel Radyo...Radyo Davet_Mavi Gece Şiir programı...)', 'Gidiyorum Akdeniz’in incisi  Hoşçakal. Bir daha dönmem geri Ne verdin ki bana, geldiğim günden beri?  Gidiyorum… Tüm   güllerimi  koparıp gi...', ARRAY['Türk Edebiyatı','Şiir','Süheyla Kurnaz']::text[], 8.5, '{"poet":"Süheyla Kurnaz","poet_slug":"suheyla-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/gidiyorum-209-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Yok Yaşanmışlıkların', 'adi-yok-yasanmisliklarin-i-lker-caliskan-6i8kv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adı yok yaşanmışlıkların

Biraz eğik bir aşk

Ucuz bir yalnızlık

Sessiz birkaç çığlık

Hiç konuşulmayan birdolu düşünce

Düşmanımdı sensiz her gece

Adı yok yaşanmışlıkların.', 'Adı yok yaşanmışlıkların Biraz eğik bir aşk Ucuz bir yalnızlık Sessiz birkaç çığlık Hiç konuşulmayan birdolu düşünce Düşmanımdı sensiz her g...', ARRAY['Türk Edebiyatı','Şiir','İlker Çalışkan']::text[], 8.5, '{"poet":"İlker Çalışkan","poet_slug":"i-lker-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/adi-yok-yasanmisliklarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adımı Aşka Yazdırdım', 'adimi-aska-yazdirdim-abdullah-artac-arslan-17st6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben adımı aşka yazdırdım..

Yalnızlıkları bırakıp,

Yüreğimi sana fırlattım.

Ocağın ayazında,

Kendimi haziranda sandım.

Bir göze,bir gülüşe

Sıcak bir merhabaya

Yüreğime yeni bir yürek kattım.

Hayatımı hep hüzünlerde,

Gözlerimi ufuklarda,

Ellerimi dikenlerde,

Umutlarımı mezarlarda bıraktım.

Ama şimdi...! 

Yağmurun ardından bir gökkuşağı yarattım.

Ayazı güneşe,

Geceyi güne,

Hasreti vuslata,

Beni sana bıraktım.

Ben adımı aşka yazdırdım.

       Abdullah Artaç ARSLAN', 'Ben adımı aşka yazdırdım.. Yalnızlıkları bırakıp, Yüreğimi sana fırlattım. Ocağın ayazında, Kendimi haziranda sandım. Bir göze,bir gülüşe Sı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Artaç Arslan']::text[], 8.5, '{"poet":"Abdullah Artaç Arslan","poet_slug":"abdullah-artac-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adimi-aska-yazdirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlamak Bitişe Komşu', 'baslamak-bitise-komsu-i-rfan-kayagil-wljwd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Korkuyorum karanlıktan

Korkum karanlığın aydınlığı yutmasından

Sabah elbet olur, ya uzun sürerse gece

Hesaplamak kolay, zaman sadece iki hece

O kadar kısa ki başlamak bitişe komşu

Yok oluşa neden, Dünyanın var oluşu

Her sabah aynı korkuyu yaşar beşer

Gecenin ürpertisi içlerine, ta sabah düşer

Kaç olursa olsun yaşları

Bu yüzdendir bütün telaşları

Korkarlar, karanlığın aydınlığı yutmasından

Mutluysanız, zaman yine  kısa 

Tek dileğiniz o an dursa.

O kadar kısa ki başlamak bitişe komşu

Özlem’e neden sevginin var oluşu

Sevmeseydiniz oysa, hiç sevmeseydiniz.

Ne özlemi, ne ayrılık sancısını bilmezdiniz.

Belki bu yüzden korkuyorum karanlıktan

Korkum bu yüzden alıştığım aydınlıktan

Görmeseydim oysa hiç görmeseydim

Güneşin bu denli parlak olduğunu

Sevdanın ateşinin sıcak olduğunu

En sıcak yerin sevgiyle acılan kucak olduğunu

Korkmazdım, sevdiklerimi yitirmekten

Günün aydınlığını sevgisiz bitirmekten.

Yok oluşa neden Dünyanın var oluşu

Zaman o kadar kısa ki, başlamak bitişe komşu.

Ankara. Ocak 2006', 'Korkuyorum karanlıktan Korkum karanlığın aydınlığı yutmasından Sabah elbet olur, ya uzun sürerse gece Hesaplamak kolay, zaman sadece iki hec...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/baslamak-bitise-komsu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denge', 'denge-kamer-taskin-5nj09', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tırmanırken, bir yukarı, bir aşağı,

Koşarken, bir hızlı, bir yavaş,

Yaşarken, bir umutlu, bir umutsuz,

Özlerken, bir sevdalı, bir sevdasız,

Birikir, 

Bir yanda birinciler, bir yanda ikinciler,

Birikir,

Denge bozulana ve sen buna katlanana dek.', 'Tırmanırken, bir yukarı, bir aşağı, Koşarken, bir hızlı, bir yavaş, Yaşarken, bir umutlu, bir umutsuz, Özlerken, bir sevdalı, bir sevdasız, ...', ARRAY['Türk Edebiyatı','Şiir','Kamer Taşkın']::text[], 8.5, '{"poet":"Kamer Taşkın","poet_slug":"kamer-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/denge-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Giderim Yollar Gider', 'ben-giderim-yollar-gider-kamber-bal-p4lws', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Avare güller vermeden filiz

Ben giderim yollar gider

Derelerim olmadan deniz

Ben giderim yollar gider

Zİfriler geceyi boyamadan

Has günlerimi sayamadan

Gençliğime hiç doyamadan

Ben giderim yollar gider

Ömrümün atmadan şafağı

Ayağım düştü çukur aşağı

Şimdi görünmeden ay ışığı

Ben giderim yollar gider

Can erginliği bulmadan

Gittiğim yollar yorulmdan

Bir ah kaldı ise Bal''dan

Ben giderim yollar gider', 'Avare güller vermeden filiz Ben giderim yollar gider Derelerim olmadan deniz Ben giderim yollar gider Zİfriler geceyi boyamadan Has günlerim...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-giderim-yollar-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanınmış Sen', 'taninmis-sen-abdullah-artac-arslan-msae3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daha dün tanıyabildim seni

Buruk,sevgiye muhtaç

Ölesiye sevebilecek

Ölümüde bilecek kadar

Etkilenmedim desem.....

Kendim bile inanmam buna.

Korkuyorum biraz da,

Kaybetme korkusu bu

Çünkü...,

Sevdiklerimi hep kaybettim.

En mutlu olduğumda bile

Yalnız hissettim kendimi..

Artık usandım yalnızlıktan,

Sevmek istiyorum ölesiye,

Ölümden korkmadan doyasıya,

Senin gibi..... Sana muhtaç.

       Abdullah Artaç ARSLAN', 'Daha dün tanıyabildim seni Buruk,sevgiye muhtaç Ölesiye sevebilecek Ölümüde bilecek kadar Etkilenmedim desem..... Kendim bile inanmam buna. ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Artaç Arslan']::text[], 8.5, '{"poet":"Abdullah Artaç Arslan","poet_slug":"abdullah-artac-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/taninmis-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair', 'sair-kamer-taskin-cshqd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Harf, sözcük ve mısraların,

İlham meydanındaki,

Zorlu, savaşından çıkıp gelen,

Sihirli ve yorgun sakatlar ordusu,

Sende şifa bulup,

Seni bir mucizenin, tek şahidi yapınca, 

Yazmazsın da ne yaparsın.', 'Harf, sözcük ve mısraların, İlham meydanındaki, Zorlu, savaşından çıkıp gelen, Sihirli ve yorgun sakatlar ordusu, Sende şifa bulup, Seni bir...', ARRAY['Türk Edebiyatı','Şiir','Kamer Taşkın']::text[], 8.5, '{"poet":"Kamer Taşkın","poet_slug":"kamer-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sair-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunun yorgun yolları..', 'yoklugunun-yorgun-yollari-pinar-koc-fyej4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgini yaşadım bugün,çok yoğun….

Yorgun hislerimin içinde sen yoktun.

Yoruldum artık,bitmeyen bir yoldun.

Yoğundun biliyorum ve hep yorgun

Yoldum yüreğimden sevdanı,artık hiç yoktun……

Yok oldum hayatından ama sen yordun…….

Yoğunluğun bahaneydi, 

Belki biraz yorgundun……

Yokluğun ve yoksunluğunla

Beni hep yordun…….

Ve gün geldi

Yorulmuş yollarında

Yok oldum……

                                                                 30.01.2006    22:00

.', 'Sevgini yaşadım bugün,çok yoğun…. Yorgun hislerimin içinde sen yoktun. Yoruldum artık,bitmeyen bir yoldun. Yoğundun biliyorum ve hep yorgun ...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yoklugunun-yorgun-yollari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heycan Eder Heycan Eder', 'heycan-eder-heycan-eder-yasar-gurlek-p1esq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'HEYCAN HEDER HEYCAN EDER

gul dalina konmus bulbul

feryat eder feryat eder

gonca gonca acmisda gul

heycan heder heycan eder

yar ne guzel gul bagin var

koca dunya gonlume dar

karsimda bin cilveli yar

heycan heder heycan eder

neselimi nesesizmi

gonul sensiz caresizmi

bakar bana onun resmi

heycan heder heycan eder

deli gonlum yanar askla

feryat eder feryat eder

yar bakisin bana baska

heycan heder heycan eder

YASAR GURLEK

1992 leiden hollanda', 'HEYCAN HEDER HEYCAN EDER gul dalina konmus bulbul feryat eder feryat eder gonca gonca acmisda gul heycan heder heycan eder yar ne guzel gul ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/heycan-eder-heycan-eder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur Beni Öldür Beni', 'vur-beni-oldur-beni-abdullah-atay-0qsoq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni her gördüğümde

Sar beni güldür beni

Sözümden döndüğümde

Vur beni öldür beni...

Yaban gülü koklarsam

Onun yolun beklersem

Senden bir şey saklarsam 

Vur beni öldür beni...

Elde gönül eylersem

Sensiz gülüp oynarsam

Fıkır fıkır kaynarsam

Vur beni öldür beni...

El sözüne kanarsam

Başka adı anarsam

İçin için yanarsam

Vur beni öldür beni...

El bağına girince

Gonca gülün derince

İnce beller sarınca

Vur beni öldür beni...

Yad ellere koşarsam

Hasretiyle yaşarsam

Vuslatıyla coşarsam

Vur beni öldür beni...

Başka yari düşlersem

Aşkımızı dışlarsam

Tek bir günah işlersem

Vur beni öldür beni...

Hemen canım bu hafta

Söz verdiğim nikahta

Hem gece hem sabahta 

Sar beni gülldur beni...', 'Seni her gördüğümde Sar beni güldür beni Sözümden döndüğümde Vur beni öldür beni... Yaban gülü koklarsam Onun yolun beklersem Senden bir şey...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/vur-beni-oldur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamalısın', 'yasamalisin-abdullah-artac-arslan-zkp1v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Meğer  ''to be or not to be'' değilmiş mesele

Yaşayabilmekmiş önemlisi

Kısa veya uzun...farketmez.! 

Dolu dolu alabildiğince

Korkmadan kaygısızca yaşamalı.

Yarını düşünmeden bugünü,

Ölümü düşünmeden hayatı.

Herşeyi sırasıyla yaşayacaksın.! 

''Aşkıda''

Kaçmadan,isteyerek...

         Abdullah Artaç ARSLAN', 'Meğer  ''to be or not to be'' değilmiş mesele Yaşayabilmekmiş önemlisi Kısa veya uzun...farketmez.!  Dolu dolu alabildiğince Korkmadan kaygısı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Artaç Arslan']::text[], 8.5, '{"poet":"Abdullah Artaç Arslan","poet_slug":"abdullah-artac-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yasamalisin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Girdap', 'girdap-i-lker-caliskan-wj828', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sessizliğin tam orta yerinde 

