INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Bilmediler', 'hic-bilmediler-yusuf-onder-bahceci-af58n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel sen bu sevdadan vazgeç dediler,

Allah aşkına bu kadar sevme dediler,

Gel bu kadar acı, keder etme dediler,

Bu adam deli olmuş be, deli dediler,

Sevgim elimde değil hiç bilmediler.

Gel başka bir gönüle gir sen dediler,

Gel gönlünü bir güzelle eyle dediler,

Gel sen aşk ateşinde yanma dediler,

Bu ne laf anlamıyor kardeşim dediler,

Sevgim elimde değil hiç bilmediler....', 'Gel sen bu sevdadan vazgeç dediler, Allah aşkına bu kadar sevme dediler, Gel bu kadar acı, keder etme dediler, Bu adam deli olmuş be, deli d...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hic-bilmediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni İstiyorum', 'seni-i-stiyorum-feride-omur-ywh6j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimde yokluğunun fırtınası

Ruhum hüzünlere teslim

Sensiz, sevda sürgününde

Damla damla eriyorum

Hasretin zehir misali

_____Adın bir melodi dilimde

_____Seni istiyorum...

Yıldızlar sevişiyor her gece

Gökyüzünün siyahi dinginliğinde

Tıpkı seninle benim gibi

Dalgalar okşuyor sahili

Bir zamanlar beni okşadığın gibi

_____Tenim tenine muhtaç

_____Seni istiyorum...

Bir meltemin dokunuşu misali

Ellerini hissediyorum saçlarımda

Kaybolmak istiyorum gözlerinde

Sevgi dolu bakışlarının derinliğinde

_____Tüm sessiz gecelerimde

_____Seni istiyorum...

Ayrılık asla bitiremedi sevgimi

Hiç ayrılmamışız gibi

Her anımda düşlüyorum gelmeni

Yüreğim çağırıyor sevgilim seni

_____Duy çağrımı birtanem

_____Seni, yalnızca seni istiyorum...', 'Yüreğimde yokluğunun fırtınası Ruhum hüzünlere teslim Sensiz, sevda sürgününde Damla damla eriyorum Hasretin zehir misali _____Adın bir melo...', ARRAY['Türk Edebiyatı','Şiir','Feride Ömür']::text[], 8.5, '{"poet":"Feride Ömür","poet_slug":"feride-omur","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-istiyorum-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bir Masalda Saklıyız Biz', 'eski-bir-masalda-sakliyiz-biz-derin-oger-h5puh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aşk diyip 

dalmıştım gözlerinin derinlerine

ve boğulmayı arzulayan bir delinin öyküsü olarak

kalışım dudaklarında

ey yel esip fırtınalar koparan okyanus

hani boy veren dalgaların hani med cezirlerin

sanki bir rüzgâr kırıntısına bulanmış şaşkın bakışların

oysa gözlerindi seni gönlüme taşıyan

yüreğimin  yüreğine duyduğu aşkı soluk soluk paylaşan

anlatabildiklerim ve anlatamadıklarımla

içim böylesine sen doluyken

kal demek isterdim kal demek sana bakışı özlenen 

prangalara vurmadan aşkı kal demek

şimdi eski bir masalda saklıyız 

tarih tarih biz....', 'aşk diyip  dalmıştım gözlerinin derinlerine ve boğulmayı arzulayan bir delinin öyküsü olarak kalışım dudaklarında ey yel esip fırtınalar kop...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eski-bir-masalda-sakliyiz-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cân Veremezsem Yazıklar Bana', 'c-n-veremezsem-yaziklar-bana-yusuf-onder-bahceci-e6z93', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevda ateşiyle yanan gönlüme,

Taşlar basarım ben kimlere ne,

Çok sevdiğim güzelin gözlerine,

Cân veremezsem yazıklar bana.

O beni terketse de, ellere gitse de,

Seviyorum kardeşim o bilmese de,

Sevmek budur işte o sevmese de,

Cân veremezsem yazıklar bana.', 'Sevda ateşiyle yanan gönlüme, Taşlar basarım ben kimlere ne, Çok sevdiğim güzelin gözlerine, Cân veremezsem yazıklar bana. O beni terketse d...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/can-veremezsem-yaziklar-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama!', 'aglama-nazan-i-zmirli-gt5jn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ne  varsa  benden  arda  kalan

gel  gör, gel  gör  ve  ağlama! 

sensizlikten.............

koca  bedenimden,

ne  bir  zerre  buhar

ne  bir  damla  yaş

ne  de  bir  parça  kül 

toprağa  kalan

ölmeden  ecele  son  nefesi  vermeden

bir  beyaz  güvercin  geldi,  tam  şurama

böğrüme  konan

öyle  söküp  aldı ki  onu  benden

o  an  bedenim  ona  eş,bir  kuş  oldu

ardından  yol  alan

ağlama! 

beni  sensiz  bıraktın

yüreğim  acılarda

feryatlarım  ayyuk da

sensizlikten yanaydı

inanmadın

kabullenmedin

ne kadar sevgisizmişsinki

sevgimi göremedin

an be an seni yaşamak istedim

uzaklardaydın

özlemin  derya   oldu  büyüdü

kavuşamadım

kokun,  tenin,  bakışın  hayal  oldu

hatırlayamadım

tebessümlerini hissettim hissettim

gülümsedim  gülümsedim

seni  çok  ama  çok  özledim.

sesini  duymak  istedim

rüzgarlara  karşı  yürüdüm.

dev  dalgalara  saldım  bedenimi

kavak  yellerini  dinledim

bulamadım  sesindeki  ahengi

söndüremedim  yüreğimdeki  alevi

sabah  güneşim  benim

şafak  vakti  beklerken  tanyelini

doğan  günle  görmek  geldiğini

işte  o  an  olan  oldu

tanyelinin  içinde  gördüm  seni

kuşların  şakıyor  sabahlarıma

hangi yana baksam  sen....

sendin

sendin  alıp  götüren  beni

ardından  yol  aldığım

ağlama! 

ne  sana  kavuşabildim

ne  sesini  duyabildim

bildiğim  o  senin  özgür  bıraktığın 

kuşundu

kaçıp  gelen  beni  alıp  götüren

ağlama! 

her  an  seninleyim  artık

özlemsiz.....

bekleyişsiz.....

doyumsuz.........

dokunduğun  her  kuş  da

parmaklarının  ucun da

baktığın  her  toprak da

öptüğün  her  dudak da

ağlama! .......

31.01.2006-antalya', 'ne  varsa  benden  arda  kalan gel  gör, gel  gör  ve  ağlama!  sensizlikten............. koca  bedenimden, ne  bir  zerre  buhar ne  bir  d...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/aglama-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıgara - Katre Kitabından', 'sigara-katre-kitabindan-omer-ekinci-micingirt-d7aw8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden miras kaldı kör öksürükler

Dalga geçer doktor gelin çürükler 

Doktor mu hatalı ben mi hatalı

On yıl oldu şükür seni atalı

Mazgallar zift dolmuş afişler boy boy 

Hınzır hınzır güler şımarık kovboy

Ambalaj tılsımlı jelâtin renk renk

Sam amcanın zehri uranyuma denk

Boş ver abi diyor çek bir sigara

Kaç bin zehir taşır tek bir sigara

Yiğidin ölüm arpadan olsun 

Manşet at kurbanlar körpeden olsun

Dizde derman yoktur ciğer sararmış 

Kurumdan yüzgeçler vücudu sarmış 

Hücrede tek sağlam yer bırakmadan 

Ölüm estiriyor dönüp bakmadan 

Bu ne bir rüyadır ne sırlı haber 

Ocaklar  söndürür siyon beraber 

Kömüre benzetir yakar upuzun 

İter kucağına sonu sonsuzun 

Dolar hırs baronlar sabah akşamlar

Nefessiz göğüsler kesilmiş kollar 

Baronlar karanlık her yer sis duman 

Frengi üretir satar durmadan 

Ağu karışımı amansız güfte

İnsanlık celladı ülkem hedefte

Emperyal kurbanı kokuşu tuzun 

Devri firavunun ve namussuzun

Sigaraya baktım birde mâziye 

Ölüm kokusu var çürük taziye 

Düzmece mazeret emekleyerek 

Nefes parçalanmış kalp tekleyerek 

Tuzak var hem madem niye ne gerek 

Yüzüm yangın yeri ellerim titrek 

Acıklı tükeniş var kertesinde

Dehşet son gayrısı mevt ertesinde', 'Senden miras kaldı kör öksürükler Dalga geçer doktor gelin çürükler  Doktor mu hatalı ben mi hatalı On yıl oldu şükür seni atalı Mazgallar z...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sigara-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sazları Anlatayım', 'sazlari-anlatayim-yusuf-onder-bahceci-4k595', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep dertli şarkılara eşlik ederim,

İşte böyle benim bitmez kederim,

Bilirim ben hep kendime ederim,

Deli gönül söz anlamaz kaderim.

Davul bile çalsa ben hüzünlenirim,

Zurnanın sesi etkiler yanar yüreğim,

Keman çalınırsa bilki o an biterim,

Neylerle kendime gelirim biraz.

Sazlar çaldığında dalar giderim,

Kaval üfleyince koyun güderim,

Mızıka bile çalsa yanar ciğerim,

Darbuka ile kendime gelirim biraz.

Saksafon deyipte geçmeyin hele,

Nasıl da çıkıyor sesi dinleyin hele,

Alto viyolensel dinle kopar zelzele,

Cura ile kendime gelirim biraz.

Sipsi deyipte siz gelip geçmeyin,

Çok iyi kulak verin siz iyi dinleyin,

Mandolinse sazın kardeşi deyim,

Kemençe ile kendime gelirim biraz.', 'Hep dertli şarkılara eşlik ederim, İşte böyle benim bitmez kederim, Bilirim ben hep kendime ederim, Deli gönül söz anlamaz kaderim. Davul bi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sazlari-anlatayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Mısralık Hayat', 'tek-misralik-hayat-timur-i-likan-fgv5z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşandıkça yaşanası şu hayat o kadar da kısa ki

Tek bir mısraya sığıverdi o dev gibi görünen hayat

           (31 Ocak 2006/ İstanbul)', 'Yaşandıkça yaşanası şu hayat o kadar da kısa ki Tek bir mısraya sığıverdi o dev gibi görünen hayat            (31 Ocak 2006/ İstanbul)...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/tek-misralik-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlıyorum', 'anliyorum-ahmet-beltekin-y9ln4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşlerime giriyorsun, her gece,

Ellerini tutuyorum, gözlerim gözlerinde.

Kaçmak istiyorsun kendince,

Saçlarını okşuyorum,

Gülüyorsun.

Biliyorum.

Seviyorsun.

Verdiği ıstırapla gecelerin,

Ağlıyorsun.

Duyuyorum…

Bana bakıyorsun sessizce,

Anlıyorum…', 'Düşlerime giriyorsun, her gece, Ellerini tutuyorum, gözlerim gözlerinde. Kaçmak istiyorsun kendince, Saçlarını okşuyorum, Gülüyorsun. Biliyo...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Beltekin']::text[], 8.5, '{"poet":"Ahmet Beltekin","poet_slug":"ahmet-beltekin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anliyorum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Büyük Korku', 'en-buyuk-korku-ahmet-beltekin-j66ww', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin en derin yerinde,uyanmak istemem,

Telaşlı bir telefon sesinde.

Bilirim ki o saatte acı haber verir,

Karşımdaki tanıdık kimse,

Sık sık alıp verdiği,titreyen nefesinde,

En yakınını kaybetmenin acısı vardır…', 'Gecenin en derin yerinde,uyanmak istemem, Telaşlı bir telefon sesinde. Bilirim ki o saatte acı haber verir, Karşımdaki tanıdık kimse, Sık sı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Beltekin']::text[], 8.5, '{"poet":"Ahmet Beltekin","poet_slug":"ahmet-beltekin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/en-buyuk-korku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Önce', 'senden-once-ahmet-beltekin-49d5n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep geleceği düşledim,yıllar yılı,

Düşlerim hep aynı noktada yorulurdu.

Beklemekten bıkkın duygularım vardı,zavallı,

Tüm dertler sebepsiz beni bulurdu.

Hep geleceği düşledim yıllar yılı,

Hüzün dolu her şarkıda,içim burkulurdu.

Yüreğimde zincirler vardı paslı mı paslı,

Nereye baksam akşam olurdu…', 'Hep geleceği düşledim,yıllar yılı, Düşlerim hep aynı noktada yorulurdu. Beklemekten bıkkın duygularım vardı,zavallı, Tüm dertler sebepsiz be...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Beltekin']::text[], 8.5, '{"poet":"Ahmet Beltekin","poet_slug":"ahmet-beltekin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senden-once-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimde Bir Kadın Var', 'gozlerimde-bir-kadin-var-ahmet-beltekin-ez4p2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kadın var gözlerimde,yaşamak kadar çılgın,

Umut kadar kuşkulu,yalnızlık kadar ürkek…

Bir kadın  var yüreğimde,senelerce günlerimi süsleyecek..

Gözlerimde bir kadın var,şimdi yalnızlık kadar yorgun,

Geceler kadar duygulu…

Gözlerimde bir kadın var,

Başından tırnağına dek,benimle dolu…', 'Bir kadın var gözlerimde,yaşamak kadar çılgın, Umut kadar kuşkulu,yalnızlık kadar ürkek… Bir kadın  var yüreğimde,senelerce günlerimi süsley...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Beltekin']::text[], 8.5, '{"poet":"Ahmet Beltekin","poet_slug":"ahmet-beltekin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gozlerimde-bir-kadin-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstasyonlar', 'i-stasyonlar-ahmet-beltekin-mndpf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daha dinmedi,çocukların trenlere öfkesi,

Canavar düdüğü gibi geliyor onlara tren sesi.

Yapmayın çocuklar,taş atmayın trenlere,

Hep yalnızlık getirmez trenler.

Arada bir hasretler çektirse bile,

İstasyonlar kavuşmaların en güzel adresi…', 'Daha dinmedi,çocukların trenlere öfkesi, Canavar düdüğü gibi geliyor onlara tren sesi. Yapmayın çocuklar,taş atmayın trenlere, Hep yalnızlık...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Beltekin']::text[], 8.5, '{"poet":"Ahmet Beltekin","poet_slug":"ahmet-beltekin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/istasyonlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanet', 'emanet-ahmet-beltekin-naqfa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eller sallanmaktan yorulur,

 Ve kaybolur gözden,gidenler…

Otobüs camlarında kalır gözyaşları,

 Sonra birbirlerine bırakırlar kalplerini,

Ayrılık olmasın diye,sevenler', 'Eller sallanmaktan yorulur,  Ve kaybolur gözden,gidenler… Otobüs camlarında kalır gözyaşları,  Sonra birbirlerine bırakırlar kalplerini, Ayr...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Beltekin']::text[], 8.5, '{"poet":"Ahmet Beltekin","poet_slug":"ahmet-beltekin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/emanet-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Yaşamını Terkettin', 'guz-yasamini-terkettin-cumhur-boratav-164is', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'güz yaşamını terketti bedenim

sen yaprakların sararması gibi

ağladın

ağladım

soğuk, keskin bir diken gibi

kesiyor anımsadıkça seni

o kadar alçak ki bulutlar 

üstümde gezinen karanlık

bir kuyu kadar derin 

senin kadar yapışkan

unutmamı engelleyen bir ses artık

içimde seslendiğim bir kış

hiç bir şeyi sevmeyen bir sevgin

yalnızsın

güz yaşamını terkettin

kış, seninle', 'güz yaşamını terketti bedenim sen yaprakların sararması gibi ağladın ağladım soğuk, keskin bir diken gibi kesiyor anımsadıkça seni o kadar a...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Boratav']::text[], 8.5, '{"poet":"Cumhur Boratav","poet_slug":"cumhur-boratav","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guz-yasamini-terkettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmesem Deli Olacaktım', 'sevmesem-deli-olacaktim-ahmet-beltekin-sndwv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir türlü sonu gelmeyen hayâllerdeydim,

Yüreğime düşen gölgeydi ayrılık.

Seni gökyüzünün görünmediği gecelerde sevdim,

Güzün yaprak döktüğü bahçelerde,sessizce,

Kol gezerken gözlerimde yalnızlık…

Hiç umudu kalmayan insanlar gibi,

Kendimden geçerek,her şeyi göze alarak sevdim.

İşte o zaman anladım,tutuşmuş yüreklerin acısını,

O zaman hissettim,

Gönüllerde hiç sönmeyen yangının,dinmeyen yasını…

Oysa bir gökkuşağı güzelliğindeydi yaşamak,

Baştan çıkarıyordu birdenbire,

Geri gelmeyeceğini bile bile gidenlerin…

Biliyordum,beklemek bir ölümdü,

Ve tutsak olmak gecelere…

Bir türlü sonu gelmeyen hayâllerdeydim,

Bir gün nasıl olsa yalnız kalacaktım,

Nasıl olsa geceler boyu ağlayacaktım.

Biliyordum bir çığ gibi düşecekti yüreğime,

Ama olsun,sevmesem deli olacaktım', 'Bir türlü sonu gelmeyen hayâllerdeydim, Yüreğime düşen gölgeydi ayrılık. Seni gökyüzünün görünmediği gecelerde sevdim, Güzün yaprak döktüğü ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Beltekin']::text[], 8.5, '{"poet":"Ahmet Beltekin","poet_slug":"ahmet-beltekin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevmesem-deli-olacaktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter ki Sana Kavuşmak Olsun Sonunda', 'yeter-ki-sana-kavusmak-olsun-sonunda-huseyin-erdogan-2le5o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'biliyor musun sevdiğim? 

ben kendimi yitirdim

bir bakabilir misin? 

senin oralarda var mıyım? 

bulursan sakın bırakma

sıkıca tut ellerimi

sen benim gönlümü fethettin

beni adeta yüreğine hapsettin

söyler misin lütfen? 

kaybolmakta haksız mıyım? 

bil ki senin yanında

müebbete bile razıyım

sevmek aşık olmak bu olsa gerek

insan mapusluğu bile 

göze alıyor isteyerek

senden hiç ayrı kalmak istemem

keşke her yerde

senin gölgen oluversem

denizde dalga olsam

sen kulaç attıkça bedenini okşasam

ışık olup gözlerine dolsam

dünyaya hep benimle baksan

ah! uzaktan da olsa bir ışık yaksan

sana doğru koşsam koşsam

yeter ki sana kavuşmak olsun sonunda

vallahi yıllarca koşsam da hiç yorulmam

sana ulaşamadan ölürsem eğer

sevgili şiirim hiç olmazsa

beni sana en yakın mezara koyuver

arada bir olsa da

en şık kıyafetlerinle ziyarete geliver

üzerime de rengarenk çiçekler dikiver

her gelişinde de sakın ihmal etme

benim yerime birer birer  koklayıver

içine çek doya doya amma dışarı verme

                                    31.01.2006

                                Hüseyin Erdoğan', 'biliyor musun sevdiğim?  ben kendimi yitirdim bir bakabilir misin?  senin oralarda var mıyım?  bulursan sakın bırakma sıkıca tut ellerimi se...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yeter-ki-sana-kavusmak-olsun-sonunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son durak', 'son-durak-tulay-i-cen-zzues', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ses.

evet,

Burası  son durak,

diyen ses..

Sağıma,soluma  baktım,

kimse yok.

Sesi duyuyorum ama,

göremiyorum.

Nereye gelmiştim.

Burası neresi...

Duyduğumu ses,

Son durak diyordu.

Her yolun  bir sonu vardır.

Yaşantımızın sonu olduğu gibi.

Hayatın sonumuydu...

Bu son durak..

Boş bir sokaktayım,

elimde  küçük bir valiz,

Nerdeyim.! 

Nerden geldim..

Son durak denilen yer,

Neresi,burası? 

Elimde bir canta,

Okul yolundayım.

Bir elimde çanta diğer elim,

Sıcacık sıcacık bir elin içinde.

Annem..

evet annem.

Sıcacık tutuyot elimi.

Sokak boş kimseler yok.

Bir küçük valiz  birde ben.

Son durak burasımı.

Yine elimde  bir çanta,

Yüreğimde bir  sıcaklık,

yakan hoş bir sıcaklık.

yüreğimdeki sevgiliyle 

yürüyoruz..

Bizi yakan ateşle..

Hızla akıp  giden yıllar,

Yüreğimdeki ateşi yakan kim.

Aşk..

Zamanı  durdurmak mümkün olsada,

durdura bilsem.

İşte yine O ses.

Burası son durak..

Son durak diye bağırıyor..

Buz kestim donuyorum.

Yüreğimde ateş yok.

Acı var.

Soğuk çok soğuk.

Elimde ağır bir çanta,

Yüreğimde acı..

Sol yanım çok acıyor..

Okul yolundayım annemin tutuğu elim.

Sevgilinin kolundayken yüreğimin,

sıcaklığı..

İki ayrı sıcaklık.

Son durak geldik,

diyen ses yine sesleniyor.

Evet burası Son durak.

30/01/2006', 'Bir ses. evet, Burası  son durak, diyen ses.. Sağıma,soluma  baktım, kimse yok. Sesi duyuyorum ama, göremiyorum. Nereye gelmiştim. Burası ne...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/son-durak-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka', 'aska-ahmetnecat-ucur-05ghd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duramam,durduramaz beni kimse,Allah''tan başka,

Yıllar,yıllar önce düşmüştüm ben bu ölümsüz aşka...

İstesekte,istemesek de aşk bu,aşk,bir bambaşka,

Yaşayıp,yaşandıkça,ölüm bile vızgelir aşka! 

Bizim aşkımızdır bu,sevsede herkes başka başka,

Olursa kupkuru sevgi,döner mi sevgiler aşka...

Değilmi ki,yaşadığımız duygular,bir bambaşka,

O halde doya doya doyalım,bu doyumsuz aşka! 

Sevgiymiş,aşkmış,neymiş bunlar dersen eğer,o başka,

Bilmezsin,anlamazsın,düşmemişsen eğer,o aşka...

Olsa da giymezmisin elbisen,hergün başka başka,

Koş,yetiş,yakala aşkı,yan,tutuş,kavrul o aşka! 

Bekledin,istedin,var mı istediğin başka,

Düşmüşsen,düşemezsin istesende bir daha aşka...

Sensin ve benim aşk,sade sevgilerde var o başka,

Susamıştık aşkımıza,yanalım gel şimdi aşka...

Seninle olmak,sana doyamamak,hasretten başka,

Duygulardır,heyecanlardır aşkla kavuşmak aşka...

Ruhun,kalbin,beynin bende,ne kaldıki sen de başka,

Benimkiler de sen de,olmazmı insan aşık,aşka...

Yaşadığın gerçek başka,rüyalarındaki başka,

Kavuşmak istemezmisin,rüyalarındaki aşka...

Gördüğümüz aynı rüya,görüyoruz başka başka,

Gördükçe sevgiyi,aşkı,sen sen ol da düşme aşka!', 'Duramam,durduramaz beni kimse,Allah''tan başka, Yıllar,yıllar önce düşmüştüm ben bu ölümsüz aşka... İstesekte,istemesek de aşk bu,aşk,bir bam...', ARRAY['Türk Edebiyatı','Şiir','Ahmetnecat Ucur']::text[], 8.5, '{"poet":"Ahmetnecat Ucur","poet_slug":"ahmetnecat-ucur","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aska-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar', 'kuslar-ali-kaybal-sqbz5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Martılar,

Kanat çırpar.

Denizlerin mavi enginliğinde,

Dalgalar kabarır, göğün serinliğinde.

Gözlerime bak, kanat çırparsan derinliğinde,

Aranmaz deniz, aranmaz göğün maviliği de.

Mutluluk deryası olur, beni sevdiğini söylediğinde,

Duygularım kabarır,dalgalanır, sen gözüme geldiğinde

Şimşekler çakar, kızgınlık yansır, gözlerimin içinde,

Çıldırırım, kem gözle sana bakanı gördüğümde.

Sen, yine de serçem ol,

Yuva yap, bahçemde dalıma,

Pencereme yanaş, tıkırdat camıma,

Seninle uçarım inan, bulunmaz ufuklara.

Yeşil gözler,

Ruhuma ferahlık verir,

Yanıma gel, ormanım ol, sık ağaçlarla,

Ben sana kanat çırparım, güzellikler arasında,

Şahin olup süzülürüm yanına,

Sahip olurum sana, felaketler çıksa da karşıma,

Bırakmam kimseye, sahip olurum duygularıma,

Kartal olur, konarım yollarına,

Kol kanat gererim, sen yanımda olduğunda,

Benimdir der, sıkı sıkıya tutarım parmaklarımla.

Leylek olsam, aldırmam yazına kışına,

Bir haberi müjdelemek için uçarım sana,

Hem baharım, hem yazım, yar yeşiller arasında,

Beyaz güvercin kanat çırpar yukarılara,

Köşeyi örümcek kaplasa da, yuva yaparım yanına,

Saf temiz duygularla, atılırım kollarına,

Ben, yine de olurum bülbül,

Bahçede yuva yaparım dalına,

Pencere kenarına konar, tıkırdarım camına,

Seninle uçarım, kafes olsa yarınlara.', 'Martılar, Kanat çırpar. Denizlerin mavi enginliğinde, Dalgalar kabarır, göğün serinliğinde. Gözlerime bak, kanat çırparsan derinliğinde, Ara...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kuslar-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüdüm Ağlayarak', 'yurudum-aglayarak-zeynep-nilgun-gokceoz-66bmy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana rastladım tutsak gecemde, 

Dönüp gitmek istedim ardıma bakmadan 

Muradı alınmış aşklar dikildi karşıma 

Uzandım boylu boyunca paslı geceye 

Sussam da sevdaya tutuştu tenim 

Ay ışığında pencerem kara bir düğüm 

Söz sustu, yanımda ürkek bir hüzün 

Yürüdüm ağlayarak 

İçim yağmur bulutu, 

Nöbet tutuyor düşümde hasret damlaları 

Azat edilmiş yaşlar dökülürken yanaklarımdan 

Sevda sularında oynaşır sahipsiz bakışlar 

Şahit olur gecenin kadehinde gökyüzüyle yıldızlar 

Ağlaştıkça hantallaşır dudaklarımdaki umutlar 

Saklanırken bedenimde mahcup tutkular sevdam uyandı 

Yürüdüm ağlayarak 

İhanet ediyorum söz verdiğim yeminlere, 

Dilimde yarım kalmış türküler var 

Dokurken özlemleri yitirdiğim gökyüzüne 

Soluyor tebessümüm sevgimin diyetinde 

Çaresizliğim kanıyor ıslak gecelerime 

Düşlerime sığdıramadığım sevdam yok artık 

Sürgün yazılırken kapımdan geçen rüzgara 

Yürüdüm ağlayarak', 'Sana rastladım tutsak gecemde,  Dönüp gitmek istedim ardıma bakmadan  Muradı alınmış aşklar dikildi karşıma  Uzandım boylu boyunca paslı gec...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yurudum-aglayarak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saygıyla Sevgiler', 'saygiyla-sevgiler-semsettin-veli-erbilli-oe6qq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unuttun mu beni sen neden dostum

Sensiz onurum yok hem beden dostum

Aldı da aklımı o giden dostum

Hep Erbil''lilere saygıyla sevgi

Unutun mu beni ne zaman dostum 

Gözlerim yoldadır ver aman dostum 

Ara sıra bir sor gün yaman dostum 

Hep Erbil''lire saygıyla sevgi

Unuttun mu beni sen nerde dostum

Sen gideli kaldım dar yerde dostum

Derin bir yaram var gel sar da dostum

Hep Erbil''lire saygıyla sevgi

Unuttun mu beni sen hasret dostum

Her yerde överim ol nasret dostum

Yarın sözlerine gel ıssrat dostum

Hep Erbil''lire saygıyla sevgi', 'Unuttun mu beni sen neden dostum Sensiz onurum yok hem beden dostum Aldı da aklımı o giden dostum Hep Erbil''lilere saygıyla sevgi Unutun mu ...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Veli Erbilli']::text[], 8.5, '{"poet":"Şemsettin Veli Erbilli","poet_slug":"semsettin-veli-erbilli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unutun-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek Oldu..', 'melek-oldu-cagla-toygan-n549f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün var yarın yok...

Kaybettiğin an var...

İnanmak istemediğin,

Yaşlarla boğulurken

Gücünü hissettiğin...

Arada isyan ettiğin...

Oysa daha yaşanacaklar vardı...

Ama daha görmeliydi birçok şeyi...

Olmalıydı yanında hayallerin gerçekleşirken...

Bakmalıydı sana sevmeliydi sıcacık...

Dolmalıydı gözleri yine sevgiyle...

Solumalıydı senle yeni anıları...

Şimdi fotoğraflarda...

Şimdi seslerde....

Şimdi her yerde O..

Geceleri konuşur seninle...

Karanlık sessizlikte acınla sen

Pamuk gibi sesi yarar acıları ulaşır sana...

Hissedersin O’nu yanında saçlarını okşarken...

Üzülme torunların bir tanesi ağlama

Deden hep yanında seni izliyor der sana...

Üzülme sen üzülme..

O şimdi en huzurda..

O şimdi hak ettiği gibi güzelliklerle...

Yorgunluğunu atıyor içi huzurlu...

Sevdikleri ardında O’nu andıkça   

Gözyaşlarıyla doluyor hayat pınarı yeniden...

Yine aynı yerde oturuyor sana bakıyor..

Bir şey değişmedi üzülme...

Toprağa kavuştu yeniden acısız olan..

Bebek gibi saf ve mutlu artık...

Melek O artık her zaman iyiliklerle...

Şer’den uzaklarda bir tebessümle...

Bembeyaz pamuk gibi...

Seninle O tüm gücüyle sonuna kadar…

MERHUM DEDEMİN RUHUNA…..

               (1927-2006)', 'Bugün var yarın yok... Kaybettiğin an var... İnanmak istemediğin, Yaşlarla boğulurken Gücünü hissettiğin... Arada isyan ettiğin... Oysa daha...', ARRAY['Türk Edebiyatı','Şiir','Çağla Toygan']::text[], 8.5, '{"poet":"Çağla Toygan","poet_slug":"cagla-toygan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/melek-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylendi Bir Kere', 'soylendi-bir-kere-sair-gulcenaz-0p6ae', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üzüldüm, hem de çok üzüldüm,

Kelimeler bedenimi sardı, kalbime saplandı,

Gözlerim karardı.

Ama söylendi bir kere.

Kelimeleri gömdüm, çok derine gömdüm,

Bende bıraktığı izden daha derine...', 'Üzüldüm, hem de çok üzüldüm, Kelimeler bedenimi sardı, kalbime saplandı, Gözlerim karardı. Ama söylendi bir kere. Kelimeleri gömdüm, çok der...', ARRAY['Türk Edebiyatı','Şiir','Şair Gülcenaz']::text[], 8.5, '{"poet":"Şair Gülcenaz","poet_slug":"sair-gulcenaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/soylendi-bir-kere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-latif-oz-9w4cx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'eşyanın dilini bilmesidir

şairin farkı

yıldızlara selam çakıp

şahit tutması

koskoca masaldır hayat

devlerle aşık

yenmiştir elması', 'eşyanın dilini bilmesidir şairin farkı yıldızlara selam çakıp şahit tutması koskoca masaldır hayat devlerle aşık yenmiştir elması...', ARRAY['Türk Edebiyatı','Şiir','Latif Öz']::text[], 8.5, '{"poet":"Latif Öz","poet_slug":"latif-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/masal-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sapanca ve Maşukiye', 'sapanca-ve-masukiye-mehmet-akif-tiryaki-i7wsb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birkaç ağaç, birkaç kulübe

İstanbul''un Davos''u Memnuniye

Richmont Otel gölün kenarına bağdaş kurmuş,

Dedeman Otel tepeye oturmuş,

Green Otel Kartepe''ye otağ kurmuş

Başı dumanlı tepeler soğumuş

Kar yağmış Kartepeye

Ölürüm İlmiye, Memnuniye''ye

Derin bir soluk

En güzel hediye

Derbent kırmızı halı sermiş Maşukiye''ye

Haydarpaşa, Sapanca ikibuçuk saat trenle

Gidiş dönüş 1 kişi 8 yl ye

Sapanca''da  gez dolaş köfte ye dön geriye

Sapanca havası kalsın hediye,

Tren Söğütlüçeşme,Erenköy,Bostancı,Maltepe ve Pendik''te durur,

O duraklardan da insanlar geziye koyulur.

Kısa bir tren seyahati manzara,

Son bulur seyahat Sapanca çarşısında

Sapanca tepeleri ve temiz hava

Cep telefonunuzla alırsınız birkaç manzara

Bu da değer iki kişi onaltı liraya

Yolunuz açık olsun haftasonunu geçirin Sapan''da

Son tren dokuzbuçukta hazır olun hâ durakta', 'Birkaç ağaç, birkaç kulübe İstanbul''un Davos''u Memnuniye Richmont Otel gölün kenarına bağdaş kurmuş, Dedeman Otel tepeye oturmuş, Green Otel...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sapanca-ve-masukiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kucak Sevgi', 'bir-kucak-sevgi-sair-gulcenaz-xevqx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeşilin tam göbeğinde,

Mavinin cam göbeğinde, 

Güneşin gözbebeğinde,

Kucaklasam seni....', 'Yeşilin tam göbeğinde, Mavinin cam göbeğinde,  Güneşin gözbebeğinde, Kucaklasam seni.......', ARRAY['Türk Edebiyatı','Şiir','Şair Gülcenaz']::text[], 8.5, '{"poet":"Şair Gülcenaz","poet_slug":"sair-gulcenaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-kucak-sevgi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Canımın Bir Yarısı**', 'canimin-bir-yarisi-sakine-aydin-4af37', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cennette öksüz kaldı,

Canımın bir yarısı,

Kavuşmadan bitmez,

Bu hasretin acısı….

Var mıdır  bir yerlerde,

Havaya sinmiş midir kokun? 

Her nefes alışımda kokunu duyuyorum..

Gözlerimin daldığı her yerde,

Hayalinle yaşıyorum ….

Sensizliğim de bende bir ben kayboluyorum..

Ama ….

Yattığın toprak kadar vefalıyım sana..

Kalbim kalbinde..

Gözlerim gözlerinde..

Ruhum ruhunda mahsur kaldı..

Hadi bırak artık beni..

İzin ver ne olur gidişime..

Yoksa katlanmak zorundasın..

Göz göre göre bitişime..

Ben....

Seni....

Kaybetmeden yanmıştım sensizliğe....

05.05.04 

31.01.06', 'Cennette öksüz kaldı, Canımın bir yarısı, Kavuşmadan bitmez, Bu hasretin acısı…. Var mıdır  bir yerlerde, Havaya sinmiş midir kokun?  Her ne...', ARRAY['Türk Edebiyatı','Şiir','Sakine Aydın']::text[], 8.5, '{"poet":"Sakine Aydın","poet_slug":"sakine-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/canimin-bir-yarisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Sus 2 (sayfa çalışması)', 'sus-2-sayfa-calismasi-nurten-altinok-33254', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sus..! 

                      

Bu gece yanımda olabilmeliydin 

Gölgeni seyredebilmeliydim holde gezinen 

Mutfaktan bir şeyler aramalıydın ve 

Kırılmadıydı bir bardak mermerde, en kıymetlisinden 

-Canın sağ olsun, seslenebilmeliydim, - boş ver aldırma 

Yüreğinin atışını duyabilmeliydim bu gece, dalga dalga 

Şekerini karıştıran bir kaşığın bardak sesine karışmalıydı sesin 

–Sen de ister misin? 

Bu gece yanımda olabilmeliydin 

Demleyebilmeliydik zamanı seninle 

Demlenebilmeliydik 

Korumasızdır yavruları kumruların / biraz saf, uçmaya hevesli 

Taşıyamaz kanatları oysa acemi uçuşları 

En uslu dokunuşlarım gezinebilmeliydi saçlarında / düşmeden önce 

Çenenden tutup yüzünü bana doğru kaldırabilmeliydim 

Körkuyu gözlerinde dibe vurabilmeliydim özlediğim 

Kozasında büyümeliydi mavi şafak renginde ipekten bir sevgi 

Ayrılık nedir bilmemeliydi ve öğrenmemeliydi 

Ölüme bir türlü sonsuzluk dendiğini 

İbadetine diz çökmüş bir bekleyişin dualarında 

Kokun dokunuyor önce bam teline sızımın / pan flüt eşliğinde 

Arka fonda gözü kan çanağı yarasa geceler bekçim 

Resimlerinde flu bir bulut / kir beyazı, pamuk duman 

Çalmayın mavimi diyorum gözlerimin mayasından 

Acıtıyor dudaklarımı filtresinden yanan ateş 

Bu kaçıncı bilmem 

Bu kaçıncı sigaram 

Bu gece yanımda olabilmeliydin, çırılçıplak soyunup geçmişinden 

Harman yeri savrulmuş duygularıma yenik düşmüşlüğümde 

Küfürlerin binini bir paraya savurduğum bu yazgıya 

Öpebilmeliydin dudaklarımdan 

- Sus..! 

Bu gece yanımda olabilmeliydin 

İmansız bir acının terkisinde kırbaç ıslığı sesim 

Sus / tura 

bilmeliydin 

Sus / a 

bilmeliydim 

Bu gece yanımda olabilmeliydin

Nurten Altınok



Seslendiren:   NEG', 'Sus..!                         Bu gece yanımda olabilmeliydin  Gölgeni seyredebilmeliydim holde gezinen  Mutfaktan bir şeyler aramalıydın ve...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sus-2-sayfa-calismasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Besmele', 'besmele-mehmet-akif-tiryaki-qyrwj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sığındım zat-ı Hakka gel gidelim,

Euzubillahimineşşeydanirraciym.

Bismillahirrahmanirrahim.

Cemal-i ba kemali seyr idelim.

Azabından affına sığınırım,

Gazabından rızana sığınırım,

Senden sana sığınırım,

Zatın yüce oldu.', 'Sığındım zat-ı Hakka gel gidelim, Euzubillahimineşşeydanirraciym. Bismillahirrahmanirrahim. Cemal-i ba kemali seyr idelim. Azabından affına ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/besmele-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarap', 'sarap-gonul-bikim-d5sj5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Daima kuytularda unutulmuş

Yıllanmış mahzenlerde şarap gibi

Ama gel gör ki artık 

Açılmak istiyor! ...', 'Daima kuytularda unutulmuş Yıllanmış mahzenlerde şarap gibi Ama gel gör ki artık  Açılmak istiyor! ......', ARRAY['Türk Edebiyatı','Şiir','Gönül Bıkım']::text[], 8.5, '{"poet":"Gönül Bıkım","poet_slug":"gonul-bikim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sarap-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenilme!', 'yenilme-kubra-gulbahar-ilicb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Devir beynimde ihtilaller koparma devri

Sağım sen… Solum sen…

Duygular savunmasız

Çek şu düşman bakışlarını üstümden

Gözlerim esir alınmış adeta

Gördüğüm her yer mahzen

Kurtuluşumu yazacak bir kalem yok

Hiçbir sayfanda nokta kadar yer ayrılmamış bana

Yüreğimde fethedilecek bir toprak mı kaldı

Al bütün teslim bayraklarım senin olsun

Yeter daha fazla yaklaşma

Korkuyorum..!', 'Devir beynimde ihtilaller koparma devri Sağım sen… Solum sen… Duygular savunmasız Çek şu düşman bakışlarını üstümden Gözlerim esir alınmış a...', ARRAY['Türk Edebiyatı','Şiir','Kübra Gülbahar']::text[], 8.5, '{"poet":"Kübra Gülbahar","poet_slug":"kubra-gulbahar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yenilme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birtanem', 'birtanem-selcen-boyar-hzbkq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir umutla gittiğin o yerden,

Binbir umutla dön birtanem

Her emelin gerçek olsun yürekten

Muradına ermiş ol da dön birtanem

O tertemiz kalbinde kötülükler yer etmesin

Umutların gerçek olsun sönmesin

Kötülükler yüreğine girmesin

O tertemiz yüreğinle dön birtanem

Mevsimler kış olsada sen hep bahar ol

Varsın bahçen olmasın bir çiçekle mutlu ol

Umutlar gelecek içindir umutlu ol

Umudunu kaybetmeden dön birtanem

Kar yağar poyraz olur aldırma

Hasret yüreğini yakarda ağlama

Gurbet bitmez, dağlar aşılmaz sanma

O dağlarda aşılır, gurbet biter birtanem

Bu şiirimi bugün Litvanya''ya öğrenci olarak giden kardeşim Hakan''a hediye ediyorum. 31.01.2006/salı', 'Bir umutla gittiğin o yerden, Binbir umutla dön birtanem Her emelin gerçek olsun yürekten Muradına ermiş ol da dön birtanem O tertemiz kalbi...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/birtanem-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklama Yüreğim', 'saklama-yuregim-yavuz-bayram-caliskan-xrb69', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine beklemek mi düştü yollara? 

Karşımdasın ama gözlerimde değil,

Karanlık mı güneş mi anlayamadım,

Ömrümü alacak galiba,

İsterdim ki deniz kenarında çay yudumlasak,

Ben anlatsam sen dinlesen,

Sen anlatsan ben öğrensem,

Çok şey öğretecek hayat bana,

Senin gittiğin yollardan mı gidiyorum ne? 

Yüreğim kaynar kazan her gelen bir ateş atıyor.

Yoruldum artık, yoruldum.

Son yaprakta döküldü ama ağaç kaldım ben.

Yanı başımda iki âşık sesiz ve göz göze,

Kızın etekleri tutuşmuş oğlanın yüreği,

Martıları gören yok o balık peşinde.

Susma hatıralar, aldığın günlerle gel,

Dökülen saçlarını bekleyen eylüllerle gel,

Ağları çeken kim içinde ne var? 

Saklama yüreğim, saklama tomurcukları,

İçinde açacak bir çiçeğim var.', 'Yine beklemek mi düştü yollara?  Karşımdasın ama gözlerimde değil, Karanlık mı güneş mi anlayamadım, Ömrümü alacak galiba, İsterdim ki deniz...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/saklama-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklar', 'uzaklar-gonul-bikim-coe3h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzakları düşünüyorum 

Uzak insanları

	Uzak anları

		Uzak yaşamları

			Uzak yerleri

				Uzak olan

her şey geçiyor

	aklımdan

Yaşadığım,yaşamış olduğum

	Ve şu an uzak olduğum

Her an,dakika geliyor aklıma

	Ve uzaklarda olmak

Uzakları yaşamak 

	Uzak olduğum insanlara kavuşmak

Uzak olduğum yerlerde olmak istiyorum

	Ben özlediğim hayata,uzak olan

Hayatıma kavuşmak,

	Uzakları yakın yapmak istiyorum.....', 'Uzakları düşünüyorum  Uzak insanları 	Uzak anları 		Uzak yaşamları 			Uzak yerleri 				Uzak olan her şey geçiyor 	aklımdan Yaşadığım,yaşamış...', ARRAY['Türk Edebiyatı','Şiir','Gönül Bıkım']::text[], 8.5, '{"poet":"Gönül Bıkım","poet_slug":"gonul-bikim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/uzaklar-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Besbelli', 'besbelli-gul-yazganarikan-n66qr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Besbelli 

Ne güzel gözlerin var,

Bakmayı bilmiyorsun,

Gördüğün benim ama,

İnkarla geziyorsun...

Ellerin yumuşak, ellerin sıcak,

Tutmayı bilmiyorsun...

Uzatınca elimi,

Sanki buz kesiyorsun...

Sesin en güzel çalgıların, resitali gönlümde,

Dinledikçe ümitle, 

Akordu bozuyorsun...

Ben sana koştukça içimdeki özlemle

Rüzgar gibi tenimden kayıp da geçiyorsun...

Besbelli görmüyor gözlerin, 

Baktığı yeri,

Besbelli yüreğin nasır, 

Elini neylemeli

Besbelli kaçak yarim, 

sesin de güzel ama,

ısıtmıyor, sözlerin, 

üşütüyor kalbimi...', 'Besbelli  Ne güzel gözlerin var, Bakmayı bilmiyorsun, Gördüğün benim ama, İnkarla geziyorsun... Ellerin yumuşak, ellerin sıcak, Tutmayı bilm...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/besbelli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Ağrım', 'yurek-agrim-gul-yazganarikan-2euqy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şarabın tadı senin yanında,

ekmek de öyle...

uyku desen sensiz derin firarda

yürek ağrım, böyle ömür geçer mi

her şarkı sensin,

her çalgı ben...

şiirler sensin,

okuyan ben...

gelme ihtimalin varsa 

daha bir gün önceden

yüreğim ellerimde çırpınır dururum ben...

seni soyunurum,

seni giyinirim,

el açıp dualarda seni dilenirim...

yürek ağrım seni ben 

başımda gezdiririm,

yeter ki bir ah çekip,

gözlerinde dinlensem...', 'şarabın tadı senin yanında, ekmek de öyle... uyku desen sensiz derin firarda yürek ağrım, böyle ömür geçer mi her şarkı sensin, her çalgı be...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yurek-agrim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başbuğ', 'basbug-riyaz-demirci-ofsef', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '20 - 27 Ocak  2006  tarihinde Ankara’da 

düzenlenecek olan “ Şairler Vicdanında DOĞRAMACI ” 

konulu şiir şöleni münasebeti ile 

Irak Türkmenlerinin önderi sayılan 

Sayın Prof.Dr. İhsan DOĞRAMACI 

olan bu büyük adam için yazılmıştır.

Kalenin dar buruğu hep seni bekler başbuğ

Tarihin her sayfası ismini ekler başbuğ

Çelebiler ağalar seninle begler başbuğ

Doğum yerin Erbil''dir Erbil sana muhtactır

Tophane saray tekke izin gösterdi beden

Arvatlar yokuşunda bu yollara kim giden

Ahmediye kapusu başbuğa selam eden

Sen Erbil''lisin paşam Erbil bize bir tactır

Hamam ile camisi bir de şehaba sesi

Bunlardır tarih kuran Erbil''in bir esasi

Katıl paşam bunlara Erbil''in Türk havası

Seninle eser paşam sana Türkçülük bacdır', '20 - 27 Ocak  2006  tarihinde Ankara’da  düzenlenecek olan “ Şairler Vicdanında DOĞRAMACI ”  konulu şiir şöleni münasebeti ile  Irak Türkmen...', ARRAY['Türk Edebiyatı','Şiir','Riyaz Demirci']::text[], 8.5, '{"poet":"Riyaz Demirci","poet_slug":"riyaz-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/basbug-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olursun Esme Seher Yeli', 'ne-olursun-esme-seher-yeli-munevver-senol-qhhs5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seher yeli, seher yeli.

Ne olursun esme bugün deli deli.

Canlarım geliyor yolda.

Üşürler bak seher yeli...

Bu zehmeride hiç yola konulur mu? 

Benden hesap sorulur mu? 

Ama bugün senin mutlu günün.

Gözün aydın Müniş Teyze.

Hiç sana karşı durulur mu.? 

 Not: 09.01.2006 tarihinde  çocuklarım yoldaydı. Bu bayram hep beraber olduk. Burak''ın da hayırlı işi vardı, işte içimden geldi, böyle karaladım.', 'Seher yeli, seher yeli. Ne olursun esme bugün deli deli. Canlarım geliyor yolda. Üşürler bak seher yeli... Bu zehmeride hiç yola konulur mu?...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-olursun-esme-seher-yeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatanım çiçek açsın rengi kanımdan olsun', 'vatanim-cicek-acsin-rengi-kanimdan-olsun-selcen-boyar-ys66i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak gidiyorum anam dağlara, uzaklara,

Alnım açık, başım dik, teslim oldum vatana

En yakın vakitte döneceğim inşallah

Sakın beni merak etme, ağlama ana.

Bedenimdeki kanım tümüyle feda olsun,

Vatanım çiçek açsın Rengi kanımdan olsun.

Yüzündeki mutlluk sakın solmasın

Döneceğim günü bekle, umudun kaybolmasın.

Her açan çiçekten haberimi al,

Esen yellerden duy sesimi.

Bir sabah bir türküyle selamını sal,

Doya doya gidereyim hasretimi.

Bu hasretlik öyle güzel hasretki,

Kavuşmak aşkıyla yanıyor kalbim.

Toprağımın sıcaklığına susamışım gel görki,

Dayanmıyor, dayanmyor yüreğim

Ah anam ahh.. Bir görsen dağ çiçeklerini

Senin bile gelesin gelir duramazsın

Vatanımın buram, buram her köşesi

Bir görsen beni ardımdan ağlamazsın.

17.07.1995

Selcen Boyar', 'Bak gidiyorum anam dağlara, uzaklara, Alnım açık, başım dik, teslim oldum vatana En yakın vakitte döneceğim inşallah Sakın beni merak etme, ...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/vatanim-cicek-acsin-rengi-kanimdan-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Kabrime Yazılsa', 'ask-kabrime-yazilsa-mustafa-benkli-w51c0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana deli desinler,

İçimi dinlesinler; 

Ne bildiğim; bilsinler,

Cehlimi bildirsinler...

Sonra, beni bilenin

Gönlüne indirsinler; 

Garîbânı sevenin,

Kalbinde dindirsinler...

Havayla, suyla değil

Sevgiyle beslesinler; 

Kabrimi büstle değil,

Duâyla süslesinler...

Yüzüm Kıbleye dönük

Lâhite yaslasınlar; 

Bütün sedâlar sönük,

Tek sesle seslesinler! ...

Beni benden alıp da,

O sese göndersinler; 

Gönlüm orda kalıp da

Bedenim görmesinler...

Nebi`în sevinç sesi; 

Sana muştu desinler! ...

Beni; çeksin Nefesi,

Kendime vermesinler! ...', 'Bana deli desinler, İçimi dinlesinler;  Ne bildiğim; bilsinler, Cehlimi bildirsinler... Sonra, beni bilenin Gönlüne indirsinler;  Garîbânı s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Benkli']::text[], 8.5, '{"poet":"Mustafa Benkli","poet_slug":"mustafa-benkli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ask-kabrime-yazilsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni...', 'bekle-beni-omer-golge-lylgy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bekle beni..

Bütün umutların bittiği yerde

Çaresizlikten değil ufkun bu karanlığı

Yediveren gülleri açsın ellerinde

Kavgalar doğurur çocuklarını

Geleceğim........

Mahşeri taşıyarak gözlerimde.

Üzülme.....

İnen bu karabulutlar vatanımın üstüne..

Gelecek hürriyet rüzgarının müjdecisidir.

Şimdiden saçlarını okşayan imbat

Bir mavi fırtınanın habercisidir.

Ey...gamzelerinde çukurovayı

Gözlerinde torosları gördüğüm..

Anadolum gibi dişi,doğurgan

Sevdasını şu kavgama kattığım,

Bekle beni.....

Bütün umutların bittiği yerde.

Herbir yöresinden Anadolunun

Binlerce oğlanla,binlerce kızla

Yüzyıllardır derdimi anlattığım,

Mavzer gibi gürleyen üç telli sazla

Geleceğim kollarına koşarak

Bereket taşıyan baharla, yazla

Sil artık  gönlünden gam izlerini

Yeşersin umutlar gül dudağında

Satılmış hainler buğulandırmasın

Kavgam gibi sevdiğim o gözlerini

Vatan deyip uğruna yandığımız,

Altı,üstü biraz toprak parçası

Namustur üstünde sakladığımız

Sende anlam bulmuş,o can yongası

Bekle beni toprağımın kadını..

Fidanın güneşe durması gibi

Özgürlük kokuyor terleyen toprak

Ekinin bire bin vermesi gibi.

Bu gece sana dair yazmayım dedim

İstedim ki haine,fırsatcıya,kahpeye

Bir kurşun yollayım her bir sözümde

Ana oldun,bacı oldun,yar oldun

Birden bire vatan oldun gözümde

Ne düşünsem senden ayrı olmuyor

Ateşin saklanmış benim közümde

Bekle beni...

Bütün umutların bittiği yerde.

Yüreğinde sırılsıklam bir sevda

Gözlerinde çok sevdiğim hüzünle....', 'Bekle beni.. Bütün umutların bittiği yerde Çaresizlikten değil ufkun bu karanlığı Yediveren gülleri açsın ellerinde Kavgalar doğurur çocukla...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bekle-beni-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Yeli...', 'askin-yeli-i-brahim-ethem-bingul-l96vo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gamzeli tebessümün olmadan mutlu olamadığımı

Dayanamadığımı ayrılığına tek saniye

İtiraf bile edemezken kendime 

Bakışlarınla nefes ve can geldi bedenime...

Bakışlarında geceyi kıskandıran o gözlerine

Bir beni görsün bu gözler deyip dururum

Dağılırım zerre zerre iklimlere sevginle

Özlemimin acısı sığınmaya toprağı özler...

Biliyorum kaybolacağım bu sevginin denizinde

Yazmaktayım sevdamı tüm hücrelerimle

Ya hüsran getirirse diyorum aşkın yeli

Çekemez bu yürek ey yâr kefen hazırla bedenime...

www.iebingul.com', 'Gamzeli tebessümün olmadan mutlu olamadığımı Dayanamadığımı ayrılığına tek saniye İtiraf bile edemezken kendime  Bakışlarınla nefes ve can g...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askin-yeli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çift Sözün Olmalı - Şiir Perisine', 'bir-cift-sozun-olmali-siir-perisine-i-brahim-usta-pmkgh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yetmedi mi sustuğun bağrı yanık milletim 

Senin de söylenecek bir çift sözün olmalı 

Asırlar var yaraya, zehirli mikrop hekim 

Merhamet kadar gerçek bir çift sözün olmalı..

Esaretin son bulsun, artık zincirleri kır 

Dünyaya gür sesinle hakkaniyeti haykır 

Mazlumun feryadına medeniyetler sağır 

Bütün dünyaya örnek bir çift sözün olmalı.', 'Yetmedi mi sustuğun bağrı yanık milletim  Senin de söylenecek bir çift sözün olmalı  Asırlar var yaraya, zehirli mikrop hekim  Merhamet kada...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Usta']::text[], 8.5, '{"poet":"İbrahim Usta","poet_slug":"i-brahim-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-cift-sozun-olmali-siir-perisine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Kendimi Bırakıyorum', 'sana-kendimi-birakiyorum-mehmet-karadut-2zkp3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana sevdamın şarkılarını bırakıyorum

Yokluğumda dinleyesin diye

Sana hayallerimi bırakıyorum

Geleceğe daha bir umutla bak diye

Sana hasretimin gözyaşlarını bırakıyorum

Kuraklaşan yüreğinde sevdalar büyütesin diye

Sana kaderimin kötü yanlarını bırakıyorum

Kaderin kötülüklere doysun, güzel bahtın olsun diye

Sana ömrümün kalanını bırakıyorum

Ömrüne ömür katsın diye

Sana yüreğimi, sevdamı bırakıyorum

Sevdiğini adam gibi sev diye

Ve sana kendimi bırakıyorum

Kendine her daim dikkat et diye', 'Sana sevdamın şarkılarını bırakıyorum Yokluğumda dinleyesin diye Sana hayallerimi bırakıyorum Geleceğe daha bir umutla bak diye Sana hasreti...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karadut']::text[], 8.5, '{"poet":"Mehmet Karadut","poet_slug":"mehmet-karadut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sana-kendimi-birakiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm Eksiliyorsun', 'omrum-eksiliyorsun-gul-yazganarikan-e7yxb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ömrüm uçuyorsun elimden

Tutmak ne mümkün

Gün geçmiyor ki üstünden

Eksiliyorsun...

Eksiliyorum...

Geldimdi daha dün, 

Yaşadım mı  bugün.

Yarına Allah Kerim

Bakarsın severim...

Ömrüm oyun ediyorsun...

Dağılmışım ben yerlere

Toplamadan gidiyorsun...

Aşk var sende, sevgi var, duygu var 

İnanmıyorsun bana

Bende deli yürek var...

Eksiliyorsun ömrüm,

Eksiltiyorsun...

Çizgilerin nakış nakış tenime işliyorsun...

Kar olup yağıyorsun tepelerime,

Aşk olup fısıldıyorsun çeperlerime

Acı olup çöküyorsun, gecelerime

Benden beni götürüyorsun...

Eksildikçe günlerim

Sen acıyla gülüyorsun...', 'Ömrüm uçuyorsun elimden Tutmak ne mümkün Gün geçmiyor ki üstünden Eksiliyorsun... Eksiliyorum... Geldimdi daha dün,  Yaşadım mı  bugün. Yarı...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/omrum-eksiliyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-munire-aksaray-enrnh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen, bende ben gibiydin.

Yazık! 

Ben, sende ben gibi olamadım

Bitti!', 'Sen, bende ben gibiydin. Yazık!  Ben, sende ben gibi olamadım Bitti!...', ARRAY['Türk Edebiyatı','Şiir','Münire Aksaray']::text[], 8.5, '{"poet":"Münire Aksaray","poet_slug":"munire-aksaray","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-750-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vaylar Olsun Halimize!', 'vaylar-olsun-halimize-i-brahim-halil-demir-4s6fp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üşüyor duygularım, doğunun bir yaz sıcağında,

Kaskatı kesilmiş bedenim, sevginin kucağında,

Zemheri soğukları, çoktan terk etmiş sılamı,

Isınmıyor yüreğim, cayır cayır yanan aşk ocağında.

Mutluluğu kuş misali uçurdular, evlerin saçağından,

Bereketli hasatlar, yapılmıyor artık sevda bağından,

Küskün değilim sadece o yare,küskünüm herkese,

Zira kayıyor bir bir, sevgi yıldızları insanlığın gençlik çağından.

Her şey yapay olmuş vaylar olsun halimize,

Güvenilir ve itibar ediliyor artık en cahilimize.

Kalmadı ben gibi sevgi hamallarına yaşama hakkı,

Çok yazıklar oldu, zümrüt kıymetindeki neslimize.

Bitirmişler değerlerimizi, fare misali kemire kemire,

Kör ve sağır olunmuş sanki,uyulmuyor hiçbir emire.

Tadı tuzu kalmamış riyakarlardan dolayı fani dünyanın,

Sevgi dolu yufka yürekler bile, dönmüş paslı demire.

Gel de içerlenme  yazdıktan sonra bunları,

Affedemiyorum, bir figuran gibi riyakarlık yapanları,

Bırakıyorum hakkımı mahşere ve bir adı da Adil olan Allah’a,

Yaman olur halleri.Allah’ta unutur Allah’ı unutanları.

31/01/2006', 'Üşüyor duygularım, doğunun bir yaz sıcağında, Kaskatı kesilmiş bedenim, sevginin kucağında, Zemheri soğukları, çoktan terk etmiş sılamı, Isı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vaylar-olsun-halimize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyanım Kendime', 'i-syanim-kendime-mehmet-karadut-v7l4a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerin yaşla dolmuş gülsün artık

Sen sus hiç konuşma yoksun artık

İsyanım sana değil benim kendime

Tanrı al bu canı, acılar bitsin artık

Kalmadı takatim yol bitmemekte

Geçiyor mevsimler, ben hep nöbette

Sevdiğim gelmiyor başka ellerde

Tarı al bu canı, bana zulüm etme', 'Gözlerin yaşla dolmuş gülsün artık Sen sus hiç konuşma yoksun artık İsyanım sana değil benim kendime Tanrı al bu canı, acılar bitsin artık K...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karadut']::text[], 8.5, '{"poet":"Mehmet Karadut","poet_slug":"mehmet-karadut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/isyanim-kendime-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Özür Dilesen Bir Küfür Edermi', 'bin-ozur-dilesen-bir-kufur-edermi-mehmet-karadut-e1vxs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hatırıma gönlüme dokunup durdun

Sen başka dünyalara uzanır oldun

Şimdi özür dilemek seni bitirir

Vakitsiz sözlerin ne faydası var

Nefrete sevgiye zaman ne fayda

Bir anda olan olur yaşanır her şey

Sevdiklerin gitmiş kalmışsın yalnız

Bin özür dilesen, bir küfür eder mi? 

Tükürdüğün yüze bakma, baktığına tükürme

Sende Memed’ler bitmez, gideni arama

Bak senden hiç kalmadı, olanda yalandı

Bin özür dilesen, bir küfür siler mi?', 'Hatırıma gönlüme dokunup durdun Sen başka dünyalara uzanır oldun Şimdi özür dilemek seni bitirir Vakitsiz sözlerin ne faydası var Nefrete se...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karadut']::text[], 8.5, '{"poet":"Mehmet Karadut","poet_slug":"mehmet-karadut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bin-ozur-dilesen-bir-kufur-edermi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oda', 'oda-nevzat-ozkan-j351g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'merhaba,

küçük odadaki eşyalar.

kim bilir neler gördü,

neler geçirdi,

sırları dökük

sır küpü

kırık ayna. 

dişleri sökülmüş

kına kokulu kemik

tarak yanı başında.

tahta dolapta 

sararmış naftalinli gelinlik.

ve dantelli beyaz eldiven.

dayının gelişini haber veriyor

damarlarına kadar aşınmış,

taşımaktan yorulmuş

gıcırtılı tahta merdiven.

mirasyedi dayı

bir elinde rakı

diğerinde sigara.

önce bebek kokardı 

bu küçük oda,

diyor yengem,

şimdi ise anason.', 'merhaba, küçük odadaki eşyalar. kim bilir neler gördü, neler geçirdi, sırları dökük sır küpü kırık ayna.  dişleri sökülmüş kına kokulu kemik...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/oda-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızılırmak', 'kizilirmak-yusuf-ter-n2rum', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Memleketimin ırmağı 

Nazlı akar Kızılırmak 

Yıllarca durmadan aharı

Nazlı akar Kızılırmak

Gece gündüz ağlayanım

Yüreğimi dağlayanım

Benim güzel çağlayanım

Nazlı akar Kızılırmak 

Yusuf’um köyüne ağlar

Irmağımız coşar çağlar

Akışına bakar dağlar

Nazlı akar Kızılırmak

Yusuf Ter  30.01.06

Saat 23:21 İsviçre', 'Memleketimin ırmağı  Nazlı akar Kızılırmak  Yıllarca durmadan aharı Nazlı akar Kızılırmak Gece gündüz ağlayanım Yüreğimi dağlayanım Benim gü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kizilirmak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baktığın Herşey Sana Birşey Demeli', 'baktigin-hersey-sana-birsey-demeli-yusuf-onder-bahceci-3fr8y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsanda asalet yoksa neye bakarsın,

Fani Dünya''da kafanı neye takarsın,

Dut yemiş bülbül gibi öyle bakarsın,

Baktığın herşey sana birşey demeli.

Memleket sevdasıyla yanalım desem,

Bak ilim bir deryadır kanalım desem,

Sana anlayacağın sözler söylesem,

Baktığın herşey sana birşey demeli.

Arife tarif gerekmez derler be cânım,

Ben bu cânımı memleketime adadım,

Gece, gündüz bilmem adak adadım,

Baktığın herşey sana birşey demeli.

Gel seninle gönüllere girelim desem,

Bahçede açan gülleri derelim desem,

Seni öyle sevmişim ki nasıl söylesem,

Baktığın herşey sana birşey demeli....', 'İnsanda asalet yoksa neye bakarsın, Fani Dünya''da kafanı neye takarsın, Dut yemiş bülbül gibi öyle bakarsın, Baktığın herşey sana birşey dem...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/baktigin-hersey-sana-birsey-demeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kişiye özel', 'kisiye-ozel-ali-i-hsan-ozturk-51xug', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nuru cihan vardır sanki yüzünde,

İnsanlık bakidir onun özünde,

Dinleyen bir başka tada bulanır,

Özel bir halika vardır sözünde.

Sesi okşamakta tüm kulakları,

Yaşı gençtir ama çıkmış akları,

Yaratılanların en özelidir,

Gül kurusu renkli bal dudakları.

Sevgi cennetidir sanki yüreği,

Boşa gitmemiştir hiçbir emeği,

Bir kalbe binlerce aşkı sığdırır,

Benzini bitsede vardır yedeği.

Aşklarıyla adı ayyuka çıkmış,

Sarışın, esmerden, kumraldan bıkmış,

İradeler yetmez onun fendine,

Hep katı kurallar tabular yıkmış.

Boş lafları sevmez hep karnı toktur,

Varlığı azsada sevgisi çoktur,

Hiç boyun eğmedi makam mevkiye,

Arkadan konuşmaz riyası yoktur.

Para, pul, çuhaya hiç aldanmadı,

İnsanlık dışında hiç kazanmadı,

Kötülük görsede karşılığında,

Yılmadan direndi hiç usanmadı.

Hiçbir beklentisi yoktur hayattan,

Birkaç kere ölüp geçmiş sırattan,

Her anı keyifli güzellik dolu,

Zaten nasibini almış sanattan.

Şiir yorumunda gerçek ustadır,

Onu dinlemeyen zaten hastadır,

Kimseye kırılmaz gücenmez ama,

Onu kızdıranlar şimdi mevtadır.

Eşine rastlanmaz dünyada tektir,

İyilik timsali safi melektir,

Paraya, maddeye hiç değer vermez,

Adı Ali İhsan sanı ÖZTÜRK’tür.', 'Nuru cihan vardır sanki yüzünde, İnsanlık bakidir onun özünde, Dinleyen bir başka tada bulanır, Özel bir halika vardır sözünde. Sesi okşamak...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Öztürk']::text[], 8.5, '{"poet":"Ali İhsan Öztürk","poet_slug":"ali-i-hsan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kisiye-ozel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gözü Kör O Sağır', 'ben-gozu-kor-o-sagir-murat-demir-94yyr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimde bir dert var ki

Sırtımdakinden ağır

Bu nasıl sevdadır ki

Ben gözü kör o sağır

Nasıl desem elveda

O kadar zor ki veda

Belli ki bu zamanda

Tadı yok sevdanında

Çare derdime diye

Bağır yüreğim bağır

Bağırsan ne yazar ki

Sen gözü kör o sağır

Nasıl desem elveda

Bu kadar zorken veda

Kahrolası zamanda

Tuzu yok sevdanında', 'İçimde bir dert var ki Sırtımdakinden ağır Bu nasıl sevdadır ki Ben gözü kör o sağır Nasıl desem elveda O kadar zor ki veda Belli ki bu zama...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-gozu-kor-o-sagir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehidim! Mehmet’im!', 'sehidim-mehmet-im-sukran-gunay-63umt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah! anam babam canlarım

Kanar oluk oluk, buz tutar yanlarım

Bir ben, bir de yaban siyahı

Bilir hallerimi

Karalar giymiş sabahlarım

Giyinir hüznümü 

Asar beni an an darağacına

Ölüm alır koynuna insafsızca da

Doğarım inadına gün batımlarında

Hem de ne inat! 

Atalarıma sözüm

Yavrularıma görevim var daha

Umutlarım, umutlarım...

Ah  başı dumanlı Vatanım! 

Bir garibim, 

Seninle yatar, sevdanla uyanırım

Gönderimin Ay Yıldızlı, Al Fistanlısı

Bilmez misin seni ben

Çekmecemde  saklarım

Gülmen için al al

Esmen için dalga dalga

Analar babalar uğurlar kuzularını 

Murad almamış, yar koynunda yatmamış

Gül benizli  yağızlarım, yavrularım

Can verir Vatan dağlarında, bağlarında

Bak! 

Ahlanır,  yakarır analar babalar 

Kıvranır dul ve yetim kalanlar

Gel gör ki,

Batıdan şaşmalı, azgın canavar! 

Beslenir, beslendikçe diş bilenir

Sorarım, gözüm yaşlı, başımda duman; 

Bekçileri Cumhuriyet’in

Bilmem ki neden susarlar? 

Kahrolsun!

Elim kolum  tutmaz, olmuşum darmadağın

Yanar şuracığım, ağlarım ağlarım...

31.01.2006', 'Ah! anam babam canlarım Kanar oluk oluk, buz tutar yanlarım Bir ben, bir de yaban siyahı Bilir hallerimi Karalar giymiş sabahlarım Giyinir h...', ARRAY['Türk Edebiyatı','Şiir','Şükran Günay']::text[], 8.5, '{"poet":"Şükran Günay","poet_slug":"sukran-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sehidim-mehmet-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haziran', 'haziran-caner-avci-g7gko', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haziran geldi mi

Rüzgar bir başka  eser

Dağın yamacındaki yarpuzların 

Uzaklardan gelir kokusu

Dayanamam

Alır götürür beni 

Dağlara dağlara … 

Haziran geldi mi

Yusufcuk bir başka öter

Bülbül bir başka...

Uzaklardan gelir sesleri

Alır götürür beni 

Dağlara dağlara …

Haziran geldi mi

Günler bir başka olur

Dağın her tarafında 

Çiçekler halay tutar

Dağla kasaba sarmaş dolaş olur

Uzaklardan gelir sevinç

Güneş gibi

Alır götürür beni

Dağlara dağlara….', 'Haziran geldi mi Rüzgar bir başka  eser Dağın yamacındaki yarpuzların  Uzaklardan gelir kokusu Dayanamam Alır götürür beni  Dağlara dağlara ...', ARRAY['Türk Edebiyatı','Şiir','Caner Avcı']::text[], 8.5, '{"poet":"Caner Avcı","poet_slug":"caner-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/haziran-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teşekkürler', 'tesekkurler-asude-gediz-553uv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana özel mesaj göndererek 

şiire aravermememi  isteyen değerli şiir doslarıma teşekkür ederim

şiir benim özüm, sözüm, herşeyim. Hiç biri zaman aravermeyi düşünmedim.

Son şiirimdeki dizenin konu bütünlüğü adına  yazılmış olduğunu belirtmek isterim

Sevgi ve  Saygılarımla

Asude GEDİZ', 'Bana özel mesaj göndererek  şiire aravermememi  isteyen değerli şiir doslarıma teşekkür ederim şiir benim özüm, sözüm, herşeyim. Hiç biri za...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tesekkurler-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatasız Kul Olmaz Olmaz Dostlarım', 'hatasiz-kul-olmaz-olmaz-dostlarim-yusuf-onder-bahceci-or3ex', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben neye yanarım dostlarım bilirmisiniz,

Hep böyle şiirler yazarım severmisiniz,

Hatalarım varsa benim siz silermisiniz,

Hatasız kul olmaz, olmaz dostlarım.

Bahçede güller kimin için açarmış sorun,

Gül dalına konan bülbüller sonu hasretin,

Ben kaybetmişim mutluluğu onu siz bulun,

Hatasız kul olmaz, olmaz dostlarım.

Ölene dek böyle dertli şiirler yazan ben,

Her yazdığı şiirde ağlayan ve kızan ben,

Nerede oynanan oyun görse bozan ben,

Hatasız kul olmaz, olmaz dostlarım....', 'Ben neye yanarım dostlarım bilirmisiniz, Hep böyle şiirler yazarım severmisiniz, Hatalarım varsa benim siz silermisiniz, Hatasız kul olmaz, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hatasiz-kul-olmaz-olmaz-dostlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarıldım adıma..', 'sarildim-adima-dilek-kadioglu-t80hf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelen çok oldu, giden daha çok hayatından

Her gelen bir ümit getirdi, gidenler ömrünün yarısı götürdü

Kırılmışlığın

Ezikliğin

İhanete uğraman

Kopardı hayattan seni

Sus oldun

Bir kahpeliklere susmadın

Haksıza merhamet

Haksızlığa siper oldun

Kaç kere sırtından vuruldun

Alnın açık başın dik 

Aman diyene el kaldırmadın

Yaşadın hayatın yaşanmaması gerekenlerini

Yordu

Üzdü

Ve kırdı yaşadıkların seni

Kabuk tuttu kanayan yaraların

Bir çizgi çektin düne

Bugüne merhaba dedin

Hayatın ne olduğunu ne için yaşayacağını öğrendin

Biri çıktı karşına

Umut ekledin yarınlarına

Uzattın ellerini ona

Tutmasını bekledin 

Belki 

Dostça 

Kardeşçe

Ama en çokta

Yar olarak tutsun istedin

Kaybetmemek için

Kardeş olmasına bile ses çıkarmadın

Yanında olması yeterdi senin için

Üzüntüsüne, sevincine ortak olmak isterdin

Sevdan ağır bastı saklayamadın yüreğini

Dile vurdun duygunu

Gördüm sende ki ışığı 

Tuttum uzattığın ellerini

Karşılıksız sevişin sevdirdi seni bana

Sarıldım adıma

İnandım sevdana

Geldim yanına gidenlerden olmamak için

Geri kalan ömrümü uğruna harcamak

Canına can olmak için geldim

Dün ben yoktum

Bugün seninle doğdum

Ve yanında öleceğim

Sarıldım adıma ve sana..', 'Gelen çok oldu, giden daha çok hayatından Her gelen bir ümit getirdi, gidenler ömrünün yarısı götürdü Kırılmışlığın Ezikliğin İhanete uğrama...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kadıoğlu']::text[], 8.5, '{"poet":"Dilek Kadıoğlu","poet_slug":"dilek-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/sarildim-adima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbette Akşam', 'gurbette-aksam-umit-fehmi-sorgunlu-ka7vr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Olmazsa gidecek bir yuvan

O zaman anlarsın inan 

Nasıl zormuş gurbette akşam

Bir sigara dumanıyla içersin yalnızlığını

Ta içinde duyarsın 

Sevgi dolu bakışlardan 

Ayrı kalmanın acısını

Düşerse aklına özlemle

Sevgilinin hasret dolu bakışları

Hançer gibi saplanır yüreğine

Bitmeyen gurbet akşamları', 'Olmazsa gidecek bir yuvan O zaman anlarsın inan  Nasıl zormuş gurbette akşam Bir sigara dumanıyla içersin yalnızlığını Ta içinde duyarsın  S...', ARRAY['Türk Edebiyatı','Şiir','Ümit Fehmi Sorgunlu']::text[], 8.5, '{"poet":"Ümit Fehmi Sorgunlu","poet_slug":"umit-fehmi-sorgunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gurbette-aksam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanç', 'utanc-umit-fehmi-sorgunlu-yudmo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dökülür kutlu çınardan

Uçuşan bir yaprak sancı

Çiğnenir tozlu tabanlarda

İnsanın yücelen utancı

Ayıp denen uçurumlar

Koparır tüm bağlarını

Zamana akan koşmalar

Sardıkça sarar insanlığı', 'Dökülür kutlu çınardan Uçuşan bir yaprak sancı Çiğnenir tozlu tabanlarda İnsanın yücelen utancı Ayıp denen uçurumlar Koparır tüm bağlarını Z...', ARRAY['Türk Edebiyatı','Şiir','Ümit Fehmi Sorgunlu']::text[], 8.5, '{"poet":"Ümit Fehmi Sorgunlu","poet_slug":"umit-fehmi-sorgunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/utanc-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nurlu Sabahlar', 'nurlu-sabahlar-umit-fehmi-sorgunlu-ws3ch', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ses dökülür minarelerden

Uykusuz sabahlarda

Su olup akar gözlerden

Tekbirle eğilir başlar

Her secdeye varışta 

Nur olur alnına dolar

Açılırken avuçlar semaya 

Arınır günahtan bedenin

Ruhun ulaşır Allaha', 'Bir ses dökülür minarelerden Uykusuz sabahlarda Su olup akar gözlerden Tekbirle eğilir başlar Her secdeye varışta  Nur olur alnına dolar Açı...', ARRAY['Türk Edebiyatı','Şiir','Ümit Fehmi Sorgunlu']::text[], 8.5, '{"poet":"Ümit Fehmi Sorgunlu","poet_slug":"umit-fehmi-sorgunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nurlu-sabahlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu hicrana şifa,cismi canındır', 'bu-hicrana-sifa-cismi-canindir-ali-riza-unal-gkxtn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sendedir  sıdk-ı vefa, ismi şanındır,    

Bu hicrana  şifa, cismi canındır,

Medet ya,sahip,suzan eyleme,

Bendedir zevk-ü fena,aslı şanındır.

Katredir küre-i cihan,dehr-i anındır

Bu giryâna  ecza,hüsnü zanımdır

Feth et vaslı payanın,firak eyleme

Sendedir zev-ü beka,cismi canındır,

-----bu eserin anlam ve açıklaması----

1--sendedir sadıklık vefakâlık çünkü ismi şanıdan,

2--bu hastalığa derde şifa hem vucut hem canındır,

3--yardım et kurtar beni ey sahibim ağlatıp sızlatma,

4--bendedir geçici bitici ölümlü zevk devamı senin ismi şanındandır.

5--şu alemler gezegenler yerelr gökler zerredir,zaman içinde bir anındır senin,

6--bu inlememe ızdırabıma ilaç sana olan iyi güzel zanım ümitlerimdir,

7--sar heryanımı beni bende koyma vuslat et kavuştur beni sana haydi o verdiğin söz ile bitsin bu ayrılık acısı,

8-- sendedir bitmeyen, tükenmeyen  beka,sevgi zevk

cismin ve canındadır,', 'Sendedir  sıdk-ı vefa, ismi şanındır,     Bu hicrana  şifa, cismi canındır, Medet ya,sahip,suzan eyleme, Bendedir zevk-ü fena,aslı şanındır....', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bu-hicrana-sifa-cismi-canindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Yol', 'bitmeyen-yol-umit-fehmi-sorgunlu-46bkm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sırtına abasını vurmuş

Güneş kızgın yol ırak

Terlemiş yüzü yorulmuş

Gideceği yer ne ilk ne son durak 

Bıkmış artık belli ki, 

Umutlarını gün be gün yemekten

Bir kurtuluş var sanki

Bıkmıyor yürümekten', 'Sırtına abasını vurmuş Güneş kızgın yol ırak Terlemiş yüzü yorulmuş Gideceği yer ne ilk ne son durak  Bıkmış artık belli ki,  Umutlarını gün...', ARRAY['Türk Edebiyatı','Şiir','Ümit Fehmi Sorgunlu']::text[], 8.5, '{"poet":"Ümit Fehmi Sorgunlu","poet_slug":"umit-fehmi-sorgunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bitmeyen-yol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Kıvılcımı', 'umut-kivilcimi-umit-fehmi-sorgunlu-wpdgp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zincire vurulmuş tüm sevgiler

Umut kıvılcımı söndü sönecek

Bir kurt gibi kemirmiş tomurcukları

Küflü karanlıklar

Bir nefes bekliyor kıvılcım 

Soluklansa yeniden

Nurlu sabahlar yakın 

Ver müjdeyi şimdiden', 'Zincire vurulmuş tüm sevgiler Umut kıvılcımı söndü sönecek Bir kurt gibi kemirmiş tomurcukları Küflü karanlıklar Bir nefes bekliyor kıvılcım...', ARRAY['Türk Edebiyatı','Şiir','Ümit Fehmi Sorgunlu']::text[], 8.5, '{"poet":"Ümit Fehmi Sorgunlu","poet_slug":"umit-fehmi-sorgunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umut-kivilcimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili..', 'sevgili-nurdane-diken-yaog6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbimin mavi mermer sarayına gelerek

Yıkılan âbideye bakar mısın sevgili! 

Herşeyi unutarak benliğine alarak

Yüzünü döndürerek, bakar mısın sevgili! 

Can suyumdan doldurdum sana getirsin diye

Verdim sâf meleklere gâmı atasın diye

Yol aldım geliyorum aşkı tutasın diye

Yürekteki sevgiyi, yıkar mısın sevgili.

Gâmı çekme! sevgili o güzel yüreğine

Kim düşer sevdiğine iş gider gereğine 

Ben yüklerim gamları sırtıma yüreğime

Köşeden bucaklardan, kaçar mısın sevgili.

Bakarmısın! ırmağın delice akmasına

Şeker olur dudağın tadına bakmasına

Yıkıp hilâl kaşının korlarla yakmasına

Beni yerlere vurup, yıkar mısın sevgili.

Yokluğun bir çığ gibi içime hep çöküyor

Aşkın narlı ateşi yüreğimi söküyor

Bulutlardan bir demet yüreğime akıyor 

Sönmüş olan ateşi, yakar mısın sevgili.

O yârin bahçesinde güller yeniden açmış

Elvan olmuş yüreği kolları bana açmış

Güllerimi dererken dallarımı hep saçmış

Küle dönmüş yüreği, tutar mısın sevgili.

Vurun beni! yerlerde aşkından sürüneyim

Sevgin yoksa zindanda kapkara çürüyeyim

Gel! sevgili gel bana sen yoksan sürüleyim 

Bu saf sevgiden, aşktan bıkar mısın sevgili...', 'Kalbimin mavi mermer sarayına gelerek Yıkılan âbideye bakar mısın sevgili!  Herşeyi unutarak benliğine alarak Yüzünü döndürerek, bakar mısın...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevgili-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vahşi...', 'vahsi-reyhan-tataroglu-enpjn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hem aşkını

                                   hem de seni sırtlandım

                                   dağ dağ,şehir şehir

                                   kaç nehir geçirdim

                                   kaç nehir...

                                   bir an yorgunluktan

                                   diz çöktüm önünde

                                   sandın ki bu bir tehir

                                   ve acımadın...

                                   geçirdin dişlerini bir anda 

                                   yüreğime... hafifçe sırıttın

                                   eyvah! çok geç...

                                   anladım ki ben yaralı bülbül

                                   sen ise sırtlandın', 'hem aşkını                                    hem de seni sırtlandım                                    dağ dağ,şehir şehir                 ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/vahsi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzel Kâfiye', 'ne-guzel-k-fiye-yusuf-onder-bahceci-3neir', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Patates ve de domates,

Barbunya ve sardalya,

Hatta oturak, sandalye,

Her yer işgal, işgaliye,

WC görsen meşguliye,

Tatlıcı da keşkül ye,

Aman ne güzel kâfiye,

Domates çorba severmisin,

Patates haşlamaya ne dersin,

Acılı Adana yermisin,

Aman ne güzel kâfiye,

Çorbaya çevirdiniz şiirleri,

Ustalar nerede hicivleri,

Şu yeni çıkan civcivleri,

Ne tez usta olmuşlar,

Edep nedir sorarsan,

Merak edip yorarsan,

Hatır gönül yıkarsan,

Bir yerlere varamazsın,

Adam ise olamazsın....', 'Patates ve de domates, Barbunya ve sardalya, Hatta oturak, sandalye, Her yer işgal, işgaliye, WC görsen meşguliye, Tatlıcı da keşkül ye, Ama...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-guzel-kafiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskici Akıl', 'eskici-akil-reyhan-tataroglu-ftcsu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çok acımasızdı çoook...

                                    gece gündüz düşündürdü

                                    olur olmaz her şeye koşturdu

                                    aç susuz demedi, mesaiye bıraktı

                                    boş durdurmadı boşa çalıştırdı

                                    yan gelip yatmaya kendini alıştırdı

                                    ve...dayanamadı iflas etti,eskidi artık 

                                    O da

                                    dil ucuyla anıyorlar şimdi

                                    ''''demode''''', 'çok acımasızdı çoook...                                     gece gündüz düşündürdü                                     olur olmaz her şeye k...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/eskici-akil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlham', 'i-lham-muhsin-altintas-ouugl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlham: bir doğuştur, bir çocuğun cığlığı,

Bir hissediş, dokunuş, sonsuz uzay boşluğu,

Karanlığın kucağında tutsak olan kuşluğu,

Aydınlığa erdiren bir güneştir ''o''

Sevmesini bilenler, onu bulanlar için,

Bir ümittir, tekrar doğanlar için

Ya kalbi kırıklar, boynu bükükler için

Kurtuluştur ölmekten, bir başlangıçtır ''o''

Ruhları temizleyen bir hizmetçi gibidir,

Kederlere rest çeken bir cengaver eridir,

Sonsuzluğu kucaklayan sanki hasret selidir,

Hem ağlayış, hemde kahkahadır ''o''

Tarifi imkansızdır kelimeler, sözcüklerle,

Bir duygu yoğunluğu, sel gibi akan gönüle,

Ne sanırsın mümkünmüdür anlatmak onu dille,

Sanatçının herşeyi, sanki hayatıdır ''o''', 'İlham: bir doğuştur, bir çocuğun cığlığı, Bir hissediş, dokunuş, sonsuz uzay boşluğu, Karanlığın kucağında tutsak olan kuşluğu, Aydınlığa er...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Altıntaş']::text[], 8.5, '{"poet":"Muhsin Altıntaş","poet_slug":"muhsin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ilham-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezan', 'ezan-halil-colak-n4iz7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlık  gecelerinde felah müjdesi

Minarelerden  haber verir ezan sesi

Gül bahçesinde öten bülbüller nidası

Mümine mutlululuk verir huzur verir

Halil Çolak 31.1.2006 Ankara', 'Karanlık  gecelerinde felah müjdesi Minarelerden  haber verir ezan sesi Gül bahçesinde öten bülbüller nidası Mümine mutlululuk verir huzur v...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ezan-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı', 'cagri-rahim-recep-akdora-3k64r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hep ünlüler yazılır çoğu kitaplara

hep ünlüler gösterilir çok iyi örneklermiş gibi

Anadolu’ya gidelim 

hala hastalarını kızaklarla doktora götüren bir köye

az bilinen bir köyde bir kadın seçelim komşu köyünü bile bilmeyen

aşkı soralım ona

doğurduğu çocukları

onurun ne olduğunu

ezilmişliği

haksızlığı

vereceği yanıtlar ilgi çeker ki 

sesler yükselir yurdun dört köşesinden

sekiz on yaşında bir çocuğun cinayetini alalım 

büyüklerinin kanunları aldatma yeltenişleri çıksın ortaya

tecavüze uğramış bir kadının suçluluk oranını belirleyelim

bana sorulursa sıfır

haykır sende düşünceni arkadaşım

sen de haykır bir öteden

az öteden bir başkası haykırsın

bayrak yapalım kadınımızın suçsuzluğunu

koruyalım bizi doğuran analarımızın onurunu

hiç işi olmamış bir işçi bulalım.

Sakalından suratının derisi görünmeyen bir işçi

Çocuklarını soralım

Ne yediklerini

Ne giyindiklerini

Okullarını

Allah’ı soralım

Cumhurbaşkanını

Başbakanı

Memleketimizin aynasını kuralım vereceği yanıtlarla

Çözüm bulalım karmaşık sakalların arasında 

sonra dağlara çıkalım

ölenler,öldürenler kim

Soralım kendi kendimize 

“neden kardeş kardeşi vuruyor? ! ”

bizim Allah’ımız var

cumhuriyetimiz var

cumhurbaşkanımız

başbakanımız var

demokrasimiz var her düşünceye uygun bir nimet

ekmeğimiz ayni ovanın mahsulünden

odunumuz ayni dağın odunu

neden AB cilerin

neden ABD cilerin fitneliklerine inanıyoruz

bu vatan bizim

bu vatan zengin

bu vatan hepimize yetecek kadar geniş

neden anlamak istemiyoruz bunu

bunların yanıtlarını bulalım

nimetler kaplasın ovalarımızı her dudağa ayrı bir tat

dağlarımızın saçlarını iyimser rüzgarlar tarasın 

haykıralım dört bir yana avaz dolusu

sağır etsin tüm fitnelikleri Türkiye korosu', 'Hep ünlüler yazılır çoğu kitaplara hep ünlüler gösterilir çok iyi örneklermiş gibi Anadolu’ya gidelim  hala hastalarını kızaklarla doktora g...', ARRAY['Türk Edebiyatı','Şiir','Rahim Recep Akdora']::text[], 8.5, '{"poet":"Rahim Recep Akdora","poet_slug":"rahim-recep-akdora","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/cagri-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin içindir', 'senin-icindir-muhsin-altintas-tham7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Byrak teselliyi teselli verme

Kalyyorsam gurbette senin içindir.

Gülümse uzaktan, istersen gelme

Ya?yyorsam hasretle, senin içindir.

Banane el alem ne?eyle ço?sun,

Yalnyz sen benim, Dünya onlaryn olsus,

Gurbet elde sensiz, sevgiden yoksun,

Ya?yyorsam gayretle senin içindir.

Ellerim semada bombo? ve mahsun,

Gözlerim ufukta bir garip kalsyn,

Kollarym yalnyzca hayalin sarsyn,

Eriyorsam özlemle senin içindir.

Kalbinde benim için yalnyz bir kö?e,

Versende seyretsem seni günlerce,

Bilemezsin sensizlik ne zor her gece,

Bekliyorsam sabyrla senin içindir.', 'Byrak teselliyi teselli verme Kalyyorsam gurbette senin içindir. Gülümse uzaktan, istersen gelme Ya?yyorsam hasretle, senin içindir. Banane ...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Altıntaş']::text[], 8.5, '{"poet":"Muhsin Altıntaş","poet_slug":"muhsin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-icindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Kaderse Sevdamız Nerede', 'ayrilik-kaderse-sevdamiz-nerede-yusuf-onder-bahceci-yex3l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılığın adına hep kader demişler,

Ne de kolay bulup kolay demişler,

Seni nasıl severim hiç bilmemişler,

Ayrılık kaderse, sevdamız nerede.

Dinmez oldu gözümde gözyaşları,

Adını derde başlar hep gözyaşları,

Doktora gerek yok hep gözyaşları,

Ayrılık kaderse, sevdamız nerede.

Bilki ayrılık ölümden beterdir beter,

Benim bu çektiklerim acı ve keder,

Yollarımız durmadan uzar da gider,

Ayrılık kaderse, sevdamız nerede.

Çekmeye mecburum sevdanı senin,

Geceler boyu uyku bilmem güzelim,

Tuzakla aldılar elimden nasıl edelim,

Ayrılık kaderse, sevdamız nerede.....', 'Ayrılığın adına hep kader demişler, Ne de kolay bulup kolay demişler, Seni nasıl severim hiç bilmemişler, Ayrılık kaderse, sevdamız nerede. ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrilik-kaderse-sevdamiz-nerede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba', 'acaba-muharrem-karaman-ruryk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneş ışıklarını elden ayaktan çekip gidiyorken,

Gün ağırlaşıp yatmaya koyulurken,

Eşyalar rengini yitirmek üzereyken,

Her şey öyle soluk rengiyle sessiz sedasız karşımda durmaktayken,

Sadece yalnızlık yanımda kanıma işlemiş sarmış her yanımı 

Artık ortalığa gece hakim 

Ağırlığını koydu gözü gönlü kararmış gece…

Her şey,binalar,eşyalar,çiçekler,kaldırımlar,ağaçlar,bütün nesneler siyah görünmekte 

Yada gözüm kararmakta…

Bunlar içinde aklımda bir tek sen,

Unutulmayan,eskimeyen hep yaralayan kanatan sen….

Geceleri acıyorum yaralarımı ve gönlümün sargı bezini değiştiriyorum sessizce,

Kanayıp seni boğmasın diye,

Daha sabaha çok var güzelim.

Daha çok kanayacak bu gönül,kanadıkça sargı bezi değişecek

Sargı bezi değiştikçe sabah olacak….

Saatler su gibi akıp giderken,

Güneşin ilk ışıkları kan çanağına dönüşmüş gözlerime vurunca.

Ve ben yine defterimi kapatıp,kalemimi bir yana bırakıp,

Ve delicesine içime çektiğim sigaranın son dumanını alıp söndürmek üzereyken,

Ve yine sen ………….

Acaba kimler unutur seni 

Yada nasıl unutur bu gönül o gözleri,saçları,elleri,dilleri …

Hiç sanmam ancak mezar taşı unutur seni………..', 'Güneş ışıklarını elden ayaktan çekip gidiyorken, Gün ağırlaşıp yatmaya koyulurken, Eşyalar rengini yitirmek üzereyken, Her şey öyle soluk re...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Karaman']::text[], 8.5, '{"poet":"Muharrem Karaman","poet_slug":"muharrem-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/acaba-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Farkındamısın Bizim', 'sen-farkindamisin-bizim-muharrem-karaman-1ztd0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz Türk genciyiz,  Türk evladıyız.

Damarlarımızda asil kan dolaşır bizim.

Delicesine atar bu yürek,

Hiç dur durak bilmez koşar vatanına,

Sarılır toprağına taşına…….

Bayraktır bizim yürek atışımız,

Bayraktır kanımız canımız,

Delicesine ölümüne sevdiğimiz……..

Türk gencidir bu……..

Anlı acık yüzü aktır.

Başı dik yüreği delidir.

Bakışları hançer, zehirdir sözü, gamdır bileği,

Ve gülüm Türk’tür aslı Türk’tür geleceği…..

Atalarımızdan öğrendiğimiz,

Analarımızdan babalarımızdan gördüğümüz,

Bu Türküdür.

Dilden dile dolaşan,

Asırdan asır’a söylenen,

Bu Türküdür.

Dilimizden düşmeyen…..

Kanımız Bayrak canımız Vatandır…

Biz buyuz….

Biz Türk oğlu Türk’üz…..

“Uyan Türk evladı uyan otuz kupona alınmadı bu vatan”', 'Biz Türk genciyiz,  Türk evladıyız. Damarlarımızda asil kan dolaşır bizim. Delicesine atar bu yürek, Hiç dur durak bilmez koşar vatanına, Sa...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Karaman']::text[], 8.5, '{"poet":"Muharrem Karaman","poet_slug":"muharrem-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-farkindamisin-bizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıplak Günahlar', 'ciplak-gunahlar-kubra-gulbahar-jvxzy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen bir imkânsız örter tüm yaşamı

Çıplak kalır düşler soyunur yalnızlığa

Yürekler kentleşir en kirlileri çalarak

Bir zenne gibi görülür her şey

Güzel…  Alımlı… Biraz korunmaya muhtaç…

Oysaki gecede kalmıştır en süslü yalanlar

Gün doğarken bütün duygular kabalaşır

Günah bedende sükûnetle duş alır

Ve bir çocuk doğar

Yarın ki yalnızlığa inatla…', 'Bazen bir imkânsız örter tüm yaşamı Çıplak kalır düşler soyunur yalnızlığa Yürekler kentleşir en kirlileri çalarak Bir zenne gibi görülür he...', ARRAY['Türk Edebiyatı','Şiir','Kübra Gülbahar']::text[], 8.5, '{"poet":"Kübra Gülbahar","poet_slug":"kubra-gulbahar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ciplak-gunahlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
